  ui_story_1011_10110202_4_dialog_content = "¿Cuántos de ellos hay?",
  ui_story_1011_10110202_5_dialog_content = "¡Siguen viniendo!",
  ui_story_1011_10110202_6_dialog_content = "¡Tenemos la espalda contra la pared!",
  ui_story_1011_10110202_7_dialog_content = "¡La estación de control está justo detrás de nosotros!",
  ui_story_1011_10110202_8_dialog_content = "¡Rugido!",
  ui_story_1011_10110202_9_dialog_content = "Vice, ¡Cuidado!",
  ui_story_1011_10110202_10_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1011_10110202_11_dialog_content = "¡Oh, no! ¡Tocaron los controles!",
  ui_story_1011_10110202_12_dialog_content = "¡¿Qué?!",
  ui_story_1011_10110202_13_dialog_content = "¡Nos vamos abajo!",
  ui_story_1011_10110202_14_dialog_content = "¡Ay! ¡Ayuda!",
  ui_story_1011_10110202_15_dialog_content = "¡Agárrate a algo!",
  ui_story_1011_10110202_16_dialog_content = "PlayerName, ¡toma mi mano!",
  ui_story_1011_10110202_17_dialog_content = "(Eclipsian) El Coloso se estrelló...",
  ui_story_1011_10110202_18_dialog_content = "(Eclipsian) ¡Montón de imbéciles!",
  ui_story_1011_10110202_19_dialog_content = "(Eclipsian) ¡L-Lo sentimos!",
  ui_story_1011_10110202_20_dialog_content = "(Eclipsian) Te ordené capturar el Colossus y el Caelestite.",
  ui_story_1011_10110202_21_dialog_content = "(Eclipsian) ¡No te pedí que los mataras!",
  ui_story_1011_10110202_22_dialog_content = "(Eclipsian) ¡Intentaremos salvar la situación!",
  ui_story_1011_10110202_23_dialog_content = "(Eclipsian) Alcanzarlos, ubicarlos. No los dejes escapar.",
  ui_story_1011_10110202_24_dialog_content = "(Eclipsian) Esta es tu última oportunidad.",
  ui_story_1011_10110202_25_dialog_content = "(Eclipsian) Entendido.",
  ui_story_1011_10110202_26_dialog_content = "(Eclipsian) Eres demasiado estúpido para estar al mando.",
  ui_story_1011_10110202_27_dialog_content = "(eclipsiano) Forsakin. No interfieras.",
  ui_story_1011_10110202_28_dialog_content = "(Eclipsian) Te lo dije. Este es mi experimento. Mantente fuera de esto.",
  ui_story_1011_10110202_29_dialog_content = "(Eclipsian) Tú y tus idiotas Eclipsites se han convertido en elementos inestables en el experimento.",
  ui_story_1011_10110202_30_dialog_content = "(Eclipsian) Quédate en las afueras y espera.",
  ui_story_1011_10110202_31_dialog_content = "(Eclipsian) Sucede que hay una unidad Illuminan más adelante obstruyendo nuestro camino. Manténgalos alejados.",
  ui_story_1011_10110202_32_dialog_content = "(Eclipsian) No me cause problemas.",
  ui_story_1011_10110202_33_dialog_content = "(eclipsiano) Forsakin...",
  ui_story_1011_10110202_34_dialog_content = "(Eclipsian) Un día pagarás por tu arrogancia.",
  ui_story_1011_10110202_40X1_dialog_content = "¡Soldados! Reinhardt ha ordenado a nuestra 2ª Legión que se quede quieta...",
  ui_story_1011_10110202_40X2_dialog_content = "¡Le mostraremos lo inexpugnables que podemos ser!",
  ui_story_1011_10110202_40X3_dialog_content = "¡Tú! Inspeccione todas las fortificaciones, repare cualquier daño y fortalezca las estructuras clave.",
  ui_story_1011_10110202_40X4_dialog_content = "No importa cuántos eclipses vengan, ¡mantendremos las cosas bajo control!",
  ui_story_1011_10110202_40X5_dialog_content = "¡Sí!",
  ui_story_1011_10110202_40X6_dialog_content = "¡Y tú! Relevar a los guardias de turno.",
  ui_story_1011_10110202_40X7_dialog_content = "Asegúrese de que todos los centinelas se cambien cada 6 horas para que estén bien descansados.",
  ui_story_1011_10110202_40X8_dialog_content = "¡Mantén los ojos bien abiertos para detectar cualquier movimiento de Eclipsite!",
  ui_story_1011_10110202_40X9_dialog_content = "¡Sí!",
  ui_story_1011_10110202_40X10_dialog_content = "<color=#e8d9bb>¡Kaboom!</color>",
  ui_story_1011_10110202_40X11_dialog_content = "¡¿Qué fue eso?!",
  ui_story_1011_10110202_40X12_dialog_content = "¿Ese es... Soroz?",
  ui_story_1011_10110202_40X13_dialog_content = "¿Por qué vuela tan bajo?",
  ui_story_1011_10110202_40X14_dialog_content = "¿Y son todos esos puntos negros... Eclipsitos?",
  ui_story_1011_10110202_40X15_dialog_content = "¡Que demonios! ¡El niño está bajo ataque!",
  ui_story_1011_10110202_40X16_dialog_content = "¡Señor!",
  ui_story_1011_10110202_40X17_dialog_content = "¡Hablar!",
  ui_story_1011_10110202_40X18_dialog_content = "Nuestros exploradores notaron un movimiento inusual de Eclipsite. ¡Todos se dirigen hacia Eraveil ahora mismo!",
  ui_story_1011_10110202_40X19_dialog_content = "¡Además de los eclipses normales, también se detectaron varios de alto nivel!",
  ui_story_1011_10110202_40X20_dialog_content = "Incluido Forsakin ¡y otro Eclipsite de alto nivel!",
  ui_story_1011_10110202_40X21_dialog_content = "Forsakin...",
  ui_story_1011_10110202_40X22_dialog_content = "¿Por qué ella va allí también?",
  ui_story_1011_10110202_40X23_dialog_content = "Nop.",
  ui_story_1011_10110202_40X24_dialog_content = "Caelestita, Eclipsitas y Forsakin...",
  ui_story_1011_10110202_40X25_dialog_content = "Si todos se dirigen hacia Eraveil, significa que algo importante está a punto de ocurrir.",
  ui_story_1011_10110202_40X26_dialog_content = "Informe a todos los miembros de la 2.ª Legión que se mantengan en alerta máxima.",
  ui_story_1011_10110202_40X27_dialog_content = "Asigna una unidad de exploradores para vigilar de cerca a Eraveil.",
  ui_story_1011_10110202_40X28_dialog_content = "¡Sí!",
  ui_story_1011_10110202_40X29_dialog_content = "Y...",
  ui_story_1011_10110202_40X30_dialog_content = "<color=#e8d9bb>Ta... ta... ta...</color>",
  ui_story_1011_10110202_40X31_dialog_content = "Eso es... ¿Eraveil?",
  ui_story_1011_10110202_40X32_dialog_content = "¿Nuestros hombres están luchando contra Eclipsites?",
  ui_story_1011_10110202_40X33_dialog_content = "¡S-Sí!",
  ui_story_1011_10110202_40X34_dialog_content = "Recibimos noticias de que nuestras unidades se toparon con una empresa de Eclipsites bajo Forsakin¡El comando de!",
  ui_story_1011_10110202_40X35_dialog_content = "Nuestras tropas se están enfrentando al enemigo, pero Forsakin partió para Eraveil solo!",
  ui_story_1011_10110202_40X36_dialog_content = "Lo que sea que estén planeando los Eclipsites, no puede ser bueno.",
  ui_story_1011_10110202_40X37_dialog_content = "Te dije que algo malo iba a pasar pronto.",
  ui_story_1011_10110202_40X38_dialog_content = "¡No pueden salirse con la suya!",
  ui_story_1011_10110202_40X39_dialog_content = "Informe a todas las unidades que se mantengan firmes. ¡Sin retroceder!",
  ui_story_1011_10110202_40X40_dialog_content = "voy a capturar a ese traidor Forsakin con mis propias manos!",
  ui_story_1011_10110202_40X41_dialog_content = "Pero señor, se nos ordenó...",
  ui_story_1011_10110202_40X42_dialog_content = "¡Escuchar! En la batalla, cada oportunidad debe ser aprovechada.",
  ui_story_1011_10110202_40X43_dialog_content = "Forsakin definitivamente no trama nada bueno y tenemos que detenerla mientras podamos.",
  ui_story_1011_10110202_40X44_dialog_content = "Si esperamos hasta que haga lo que tiene planeado, será demasiado tarde.",
  ui_story_1011_10110202_40X45_dialog_content = "Si mi decisión causa problemas, dígaselo. Reinhardt y el comité...",
  ui_story_1011_10110202_40X46_dialog_content = "Pueden contener al Comandante de la 2.ª Legión. Barton responsable de todas las consecuencias!",
  ui_story_1011_10110202_40X47_dialog_content = "¿Lo entiendes?",
  ui_story_1011_10110202_40X48_dialog_content = "¡Sí señor!",
  ui_story_1011_10110202_40X49_dialog_content = "Me pregunto cómo se mantiene el Navigator...",
  ui_story_1011_10110202_40X50_dialog_content = "Es como un gato con nueve vidas. Él estará bien.",
  ui_story_1011_10110202_40X51_dialog_content = "Démosle una mano.",
  ui_story_1011_10110401_1_dialog_content = "<anim type=Shake><size=50>¡Ahhhhhhh!</size></anim>",
  ui_story_1011_10110401_2_dialog_content = "¡¡¡VAMOS A BAJAR!!!",
  ui_story_1011_10110401_3_dialog_content = "PlayerName¡Mantén nuestra dirección firme!",
  ui_story_1011_10110401_4_dialog_content = "Hay espacio debajo de la torre. ¡Haz que Soroz se deslice!",
  ui_story_1011_10110401_7X1_dialog_content = "¡No puedo hacerlo!",
  ui_story_1011_10110401_7X2_dialog_content = "El controlador está dañado. ¡He perdido el control de Soroz!",
  ui_story_1011_10110401_7X3_dialog_content = "¡Aférrate a algo entonces!",
  ui_story_1011_10110401_7X4_dialog_content = "Y luego.",
  ui_story_1011_10110401_7X5_dialog_content = "¡Oremos para no chocar contra la torre!",
  ui_story_1011_10110401_7X6_dialog_content = "¡Ahhh!",
  ui_story_1011_10110401_8_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1011_10110401_9_dialog_content = "<color=#e8d9bb>*retumbando*</color>",
  ui_story_1011_10110401_10_dialog_content = "*Tose* Hay tanto polvo...",
  ui_story_1011_10110401_11_dialog_content = "¿Estamos... todavía vivos?",
  ui_story_1011_10110401_12_dialog_content = "Umm... Ese parece ser el caso.",
  ui_story_1011_10110401_13_dialog_content = "Aterrizamos con éxito.",
  ui_story_1011_10110401_14_dialog_content = "¿Todos están bien? ¿Alguien resultó herido?",
  ui_story_1011_10110401_15_dialog_content = "Estoy bien, aparte de sentir náuseas.",
  ui_story_1011_10110401_16_dialog_content = "Yo... yo también estoy bien.",
  ui_story_1011_10110401_17_dialog_content = "*Tose* ¿Estamos en la base de la torre?",
  ui_story_1011_10110401_18_dialog_content = "Sí, nos colamos en el espacio directamente debajo de la Torre Blanca.",
  ui_story_1011_10110401_19_dialog_content = "<color=#e8d9bb>\"Destino alcanzado: Base de mantenimiento de Colossus Asfalto\".</color>",
  ui_story_1011_10110401_20_dialog_content = "<color=#e8d9bb>\"Estableciendo conexión a los sistemas de control de la base\".</color>",
  ui_story_1011_10110401_21_option_content = "¿Pista?",
  ui_story_1011_10110401_22_dialog_content = "Todo este espacio... ¿es un asfalto?",
  ui_story_1011_10110401_23_dialog_content = "No es de extrañar que sea tan grande... Podrían caber bastantes colosos más.",
  ui_story_1011_10110401_24_dialog_content = "No creas que cuenta como un accidente si aterrizamos en la pista...",
  ui_story_1011_10110401_25_dialog_content = "Graah! ¡Rugido!",
  ui_story_1011_10110401_26_dialog_content = "...",
  ui_story_1011_10110401_27_dialog_content = "...",
  ui_story_1011_10110401_28_dialog_content = "¡Más eclipses!",
  ui_story_1011_10110401_29_dialog_content = "¡Grrr!",
  ui_story_1011_10110401_30_dialog_content = "¡Atrapalo!",
  ui_story_1011_10110401_31_dialog_content = "¡Debe haber muchos más a bordo!",
  ui_story_1011_10110401_32_dialog_content = "¡No podemos dejar que causen más daño!",
  ui_story_1011_10110402_1_dialog_content = "Uf... Este debe ser el último.",
  ui_story_1011_10110402_2_dialog_content = "No parece haber más a la vista.",
  ui_story_1011_10110402_3_dialog_content = "No siento más enemigos. Deberíamos poder tomar un respiro.",
  ui_story_1011_10110402_4_dialog_content = "Déjame ver a Soroz primero.",
  ui_story_1011_10110402_5_dialog_content = "<color=#e8d9bb>\"Intentando conectarse al sistema de control de la base de mantenimiento Colossus\".</color>",
  ui_story_1011_10110402_6_dialog_content = "<color=#e8d9bb>\"Error: Asfalto desconectado del sistema de control central\".</color>",
  ui_story_1011_10110402_7_dialog_content = "<color=#e8d9bb>\"Diríjase a la sala de control central y vuelva a conectarse manualmente\".</color>",
  ui_story_1011_10110402_8_dialog_content = "¿La Sala de Control Central...?",
  ui_story_1011_10110402_9_dialog_content = "¿Se supone que eso está en la Torre Blanca?",
  ui_story_1011_10110402_10_dialog_content = "¿Tenemos algo en la base de datos al respecto?",
  ui_story_1011_10110402_11_dialog_content = "No lo creo...",
  ui_story_1011_10110402_12_dialog_content = "No me importa revisar todos los archivos, pero eso llevará tiempo.",
  ui_story_1011_10110402_13_dialog_content = "Revisar los archivos por sí solo no ayudará. Tenemos que hacer una investigación práctica.",
  ui_story_1011_10110402_14_dialog_content = "Buen punto. Bajemos allí y echemos un vistazo.",
  ui_story_1011_10110402_15_dialog_content = "Vamos, entonces.",
  ui_story_1011_10110402_16_dialog_content = "Está tan vacío aquí...",
  ui_story_1011_10110402_17_dialog_content = "Todo lo que decimos resuena...",
  ui_story_1011_10110402_18_dialog_content = "Según los datos, este fue una vez un hábitat de los Caelestites.",
  ui_story_1011_10110402_19_dialog_content = "Pero apenas puedes distinguir las habitaciones ahora. Si alguien vivió aquí una vez, ha pasado mucho tiempo.",
  ui_story_1011_10110402_20_dialog_content = "Deben haberse mudado hace mucho tiempo...",
  ui_story_1011_10110402_21_dialog_content = "Incluso si dejaran algo atrás, con el tiempo todo se habría perdido.",
  ui_story_1011_10110402_22_dialog_content = "Aunque nunca imaginé que Caelestites viviera en el asfalto.",
  ui_story_1011_10110402_23_dialog_content = "¿Simplemente aterrizaron sus Colosos aquí y vivieron con ellos?",
  ui_story_1011_10110402_24_dialog_content = "Suena extrañamente similar a acampar.",
  ui_story_1011_10110402_25_dialog_content = "Tal vez esa es la razón por la que no ves ninguna vivienda aquí, porque Caelestites solía vivir en sus colosos.",
  ui_story_1011_10110402_26_dialog_content = "Cuando se fueron, se llevaron sus Colosos con ellos.",
  ui_story_1011_10110402_27_dialog_content = "Si aterrizaron sus Colossi aquí, entonces sabían que esto era una pista.",
  ui_story_1011_10110402_28_dialog_content = "Y si ese es el caso, ellos habrían sabido sobre el <color=#FFB400>Base de mantenimiento del coloso</color>.",
  ui_story_1011_10110402_29_dialog_content = "Entonces, ¿por qué no hay registro de ello?",
  ui_story_1011_10110402_30_dialog_content = "De hecho, es raro. A ver si podemos saber más al respecto más adelante.",
  ui_story_1011_10110402_31_dialog_content = "Sí.",
  ui_story_1011_10110402_32_dialog_content = "Una base que no está en ningún registro y es desconocida para el mundo... Es como si simplemente apareciera de la nada.",
  ui_story_1011_10110402_33_dialog_content = "No veo nada que se parezca a una estación de mantenimiento o una sala para los Colosos cerca.",
  ui_story_1011_10110402_34_dialog_content = "De hecho, no hay nada más que gruesas capas de polvo.",
  ui_story_1011_10110402_35_dialog_content = "Tampoco parece que la Sala de Control Central esté en ninguna parte aquí.",
  ui_story_1011_10110402_36_dialog_content = "¿A menos que esté arriba?",
  ui_story_1011_10110402_37_dialog_content = "PlayerName, ¿qué hay exactamente en la torre?",
  ui_story_1011_10110402_38_dialog_content = "Déjame pensar.",
  ui_story_1011_10110402_39_dialog_content = "Según la base de datos de Soroz, Caelestites una vez habitó esta torre durante un período de tiempo.",
  ui_story_1011_10110402_40_dialog_content = "Pero eventualmente se mudaron y se establecieron en su hábitat moderno.",
  ui_story_1011_10110402_41_dialog_content = "Caelestites del pasado peinaron este lugar en detalle, incluidos los pisos superiores de la torre.",
  ui_story_1011_10110402_42_dialog_content = "Sin embargo, no encontraron nada aparte de las mismas piedras blancas estampadas que las que se ven desde el exterior.",
  ui_story_1011_10110402_43_dialog_content = "¿No hay nada arriba...?",
  ui_story_1011_10110402_44_dialog_content = "¿Estamos en las coordenadas equivocadas?",
  ui_story_1011_10110402_45_dialog_content = "No me parece. Incluso si la estructura se movió debido a razones geológicas, no debería haberse alejado mucho de su posición original.",
  ui_story_1011_10110402_46_dialog_content = "Si no hay nada en la torre...",
  ui_story_1011_10110402_47_dialog_content = "¿Qué pasa debajo de él?",
  ui_story_1011_10110402_48_dialog_content = "¿Debajo de ella?",
  ui_story_1011_10110402_49_dialog_content = "¿Te refieres a un espacio subterráneo oculto, como Gannon?",
  ui_story_1011_10110402_50_dialog_content = "¡Ese es realmente un buen punto!",
  ui_story_1011_10110402_51_dialog_content = "Pero este lugar está lleno de piedras de la torre derrumbada. ¿Cómo se supone que vamos a encontrar la entrada sin un mapa?",
  ui_story_1011_10110402_52_dialog_content = "¿A menos que estés planeando excavar en todo este lugar?",
  ui_story_1011_10110402_53_dialog_content = "Probablemente tomaría años encontrar un pasaje.",
  ui_story_1011_10110402_54_dialog_content = "Un pasaje... Entrañas... una forma de encontrar...",
  ui_story_1011_10110402_55_dialog_content = "¡Lo tengo!",
  ui_story_1011_10110402_56_dialog_content = "Hay detectores de metales entre los suministros que nos proporcionó el Gran Mariscal.",
  ui_story_1011_10110402_57_dialog_content = "Si de hecho hay una base subterránea, lo más probable es que parte de la estructura esté hecha de metal.",
  ui_story_1011_10110402_58_dialog_content = "Podemos usar el detector de metales para buscar posibles lugares de excavación.",
  ui_story_1011_10110402_59_dialog_content = "Y pensar que el Gran Mariscal incluso previó esto...",
  ui_story_1011_10110402_60_dialog_content = "Ella es realmente tan visionaria como dicen los rumores.",
  ui_story_1011_10110402_60X1_dialog_content = "También podría traer los otros suministros y los explosivos también.",
  ui_story_1011_10110402_60X2_dialog_content = "Podrían ser útiles.",
  ui_story_1011_10110402_61_dialog_content = "Supongo que eso es lo que haremos entonces.",
  ui_story_1011_10110402_62_dialog_content = "Ojalá tengamos suerte y encontremos una entrada enseguida.",
  ui_story_1011_10110402_63_dialog_content = "<color=#e8d9bb>En algún lugar fuera de la Torre Blanca</color>",
  ui_story_1011_10110402_64_dialog_content = "Como sospechaba, esta torre no es tan simple como parece.",
  ui_story_1011_10110402_65_dialog_content = "Si no fuera por la clave de Caelestite como guía, sus secretos nunca serían descubiertos.",
  ui_story_1011_10110402_66_dialog_content = "Es hora de hacer que esos secretos formen parte de mis datos de experimentación.",
  ui_story_1011_10110402_66X1_dialog_content = "¡No te vas a escapar!",
  ui_story_1011_10110402_66X2_dialog_content = "Graaahh—",
  ui_story_1011_10110402_66X3_dialog_content = "Comandante de la legión, ¡hemos despejado la mayoría de los eclipses de la zona!",
  ui_story_1011_10110402_66X4_dialog_content = "¡Buen trabajo! Usa este tiempo para reconstruir nuestra defensa.",
  ui_story_1011_10110402_66X5_dialog_content = "¡Sí!",
  ui_story_1011_10110402_66X6_dialog_content = "Estos eclipses son todos inútiles.",
  ui_story_1011_10110402_66X7_dialog_content = "Dónde está Forsakin?",
  ui_story_1011_10110402_66X8_dialog_content = "¿Ha llegado ya a Eraveil?",
  ui_story_1011_10110402_66X9_dialog_content = "¿Son todos estos eclipses y Forsakin aquí por PlayerName?",
  ui_story_1011_10110402_66X10_dialog_content = "Que fiesta mas animada.",
  ui_story_1011_10110402_66X11_dialog_content = "No puedo esperar a ver qué más tiene bajo la manga.",
  ui_story_1011_10110501_1_dialog_content = "Una caja vacía inútil...",
  ui_story_1011_10110501_2_dialog_content = "Tirar a la basura.",
  ui_story_1011_10110501_3_dialog_content = "Libros apenas legibles...",
  ui_story_1011_10110501_4_dialog_content = "Tirar a la basura.",
  ui_story_1011_10110501_5_dialog_content = "Una lata de algo...",
  ui_story_1011_10110501_6_dialog_content = "Tirar a la basura.",
  ui_story_1011_10110501_7_dialog_content = "¡Esperar! ¡No lo desperdicies!",
  ui_story_1011_10110501_8_dialog_content = "Pero... ha caducado desde Dios sabe cuánto tiempo.",
  ui_story_1011_10110501_9_dialog_content = "Es mejor simplemente tirarlo.",
  ui_story_1011_10110501_10_dialog_content = "Suspiro...",
  ui_story_1011_10110501_11_dialog_content = "Solo terminamos con un montón de basura inútil después de horas de trabajo.",
  ui_story_1011_10110501_12_dialog_content = "Revisemos cada esquina nuevamente para asegurarnos de que no nos perdimos nada.",
  ui_story_1011_10110501_13_dialog_content = "Bien. Haré otro barrido.",
  ui_story_1011_10110501_14_dialog_content = "No creo que hayamos revisado esta área todavía.",
  ui_story_1011_10110501_15_dialog_content = "Estas piedras blancas están esparcidas por aquí... ¿Parece que salieron de la Torre Blanca?",
  ui_story_1011_10110501_16_dialog_content = "Me pregunto si hay algo dentro de ellos...",
  ui_story_1011_10110501_17_dialog_content = "Debería comprobar con el detector de metales.",
  ui_story_1011_10110501_18_dialog_content = "<color=#e8d9bb>¡Bip, bip...!</color>",
  ui_story_1011_10110501_19_dialog_content = "¡Está... reaccionando!",
  ui_story_1011_10110501_20_dialog_content = "¿A algo dentro de la piedra?",
  ui_story_1011_10110501_21_option_content = "Toca la piedra",
  ui_story_1011_10110501_22_dialog_content = "<color=#e8d9bb>TOC Toc...!</color>",
  ui_story_1011_10110501_23_dialog_content = "No suena hueco en absoluto. ¿Puede ser en la parte de atrás?",
  ui_story_1011_10110501_24_dialog_content = "Está tan oscuro aquí, y hay sombras por todas partes...",
  ui_story_1011_10110501_25_dialog_content = "Parece que hay algo en las sombras, pero no puedo distinguir qué es.",
  ui_story_1011_10110501_26_dialog_content = "Acerquémonos un poco más. Esperar. Es eso...",
  ui_story_1011_10110501_27_dialog_content = "¡¿Un Eclipsite con una lata en la cabeza, tratando de disfrazarse de escombros?!",
  ui_story_1011_10110501_28_dialog_content = "¡Roooooor!",
  ui_story_1011_10110501_29_dialog_content = "¿Ehhhh?",
  ui_story_1011_10110501_30_dialog_content = "¡PlayerName!",
  ui_story_1011_10110501_31_dialog_content = "Graah! ¡Rugido!",
  ui_story_1011_10110501_32_dialog_content = "¡E-Eso estuvo cerca!",
  ui_story_1011_10110501_33_dialog_content = "¿¡Cómo llegaron aquí!?",
  ui_story_1011_10110501_34_dialog_content = "Es un espacio vacío con muchas sombras para esconderse.",
  ui_story_1011_10110501_35_dialog_content = "Los Eclipsites deben haberse colado cuando buscábamos la entrada.",
  ui_story_1011_10110501_36_dialog_content = "Rooooar!",
  ui_story_1011_10110501_37_dialog_content = "Maldita sea. ¡Estamos rodeados!",
  ui_story_1011_10110501_38_dialog_content = "¡Más eclipses se derraman desde la entrada!",
  ui_story_1011_10110501_39_dialog_content = "¡Tenemos que encontrar una manera de abrirnos paso!",
  ui_story_1011_10110501_40_dialog_content = "¡No!",
  ui_story_1011_10110501_41_dialog_content = "¡Eso significaría que les estamos entregando la Torre Blanca y Soroz!",
  ui_story_1011_10110501_42_dialog_content = "Tenemos que evitar que los Eclipsites entren si queremos proteger este lugar.",
  ui_story_1011_10110501_43_dialog_content = "¡Pero es como una cueva sin nada que se parezca remotamente a una puerta!",
  ui_story_1011_10110501_44_dialog_content = "Sin puerta...",
  ui_story_1011_10110501_45_dialog_content = "¡Entonces haremos uno!",
  ui_story_1011_10110501_46_dialog_content = "¡Usa los explosivos!",
  ui_story_1011_10110501_47_dialog_content = "¡¿Quieres volar la entrada?!",
  ui_story_1011_10110501_48_dialog_content = "¡Exactamente!",
  ui_story_1011_10110501_49_dialog_content = "No importa si la entrada se derrumba. Todavía podemos salir de los niveles superiores de la torre.",
  ui_story_1011_10110501_49X1_dialog_content = "En el peor de los casos, podemos encontrar otra salida en las ruinas subterráneas si es necesario.",
  ui_story_1011_10110501_50_dialog_content = "¡Pero tenemos que detener a los Eclipsites aquí y ahora para proteger a Soroz y las ruinas!",
  ui_story_1011_10110501_51_dialog_content = "Vice y te cubriré. PlayerName¡Aprovecha esta oportunidad y detona los explosivos en la entrada!",
  ui_story_1011_10110501_52_dialog_content = "¡Está bien!",
  ui_story_1011_10110501_53_dialog_content = "¡Cuento con ustedes dos!",
  ui_story_1011_10110502_1_dialog_content = "Graah! ¡Rugido!",
  ui_story_1011_10110502_2_dialog_content = "¡Fuera del camino!",
  ui_story_1011_10110502_3_dialog_content = "Rooooar!",
  ui_story_1011_10110502_4_dialog_content = "Más y más eclipses están inundando... A este ritmo, ni siquiera me acercaré a la entrada...",
  ui_story_1011_10110502_5_dialog_content = "¡Y mucho menos detonar los explosivos!",
  ui_story_1011_10110502_6_dialog_content = "Tengo que tratar de atravesarlos primero.",
  ui_story_1011_10110502_7_dialog_content = "¡No podemos quedarnos atrapados aquí!",
  ui_story_1011_10110502_9_dialog_content = "¡Prueba esto!",
  ui_story_1011_10110502_10_dialog_content = "La entrada, mira! ¿No es eso...?",
  ui_story_1011_10110502_11_dialog_content = "Barton?!",
  ui_story_1011_10110502_12_dialog_content = "¡¿Qué estás haciendo aquí?!",
  ui_story_1011_10110502_12X1_dialog_content = "¡Ja! Sabía que ustedes estarían bien.",
  ui_story_1011_10110502_12X2_dialog_content = "Vi un montón de Eclipsites viniendo de esta manera, así que vine a ver las cosas.",
  ui_story_1011_10110502_13_dialog_content = "¡Estaba de paso y usaba los Eclipsites para mi rutina diaria de ejercicios!",
  ui_story_1011_10110502_14_dialog_content = "Haz lo que necesitas hacer. Te tengo cubierto.",
  ui_story_1011_10110502_15_dialog_content = "Comandante Barton está frenando a los Eclipsites! PlayerName, esta es tu oportunidad!",
  ui_story_1011_10110502_16_dialog_content = "Barton, ¡volver! ¡Vamos a sellar la entrada!",
  ui_story_1011_10110502_17_dialog_content = "¿Sello? ¿Cómo vas a hacer eso?",
  ui_story_1011_10110502_18_dialog_content = "¡Lo vamos a explotar!",
  ui_story_1011_10110502_19_dialog_content = "¡¿Explotarlo?!",
  ui_story_1011_10110502_20_dialog_content = "¡No pensé que lo tuvieras en ti, chico!",
  ui_story_1011_10110502_21_dialog_content = "Tengo cosas manejadas aquí. ¡Ve a explotar las cosas al contenido de tu corazón!",
  ui_story_1011_10110502_22_dialog_content = "Los Eclipsites están retrocediendo. PlayerName, ¡Vamos!",
  ui_story_1011_10110502_23_dialog_content = "¡Entendido!",
  ui_story_1011_10110502_24_dialog_content = "Los explosivos están en posición. Vice, Carleen, ¡volver!",
  ui_story_1011_10110502_25_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1011_10110502_26_dialog_content = "¿Lo hicimos nosotros?",
  ui_story_1011_10110502_27_dialog_content = "¡Parece que funcionó!",
  ui_story_1011_10110502_28_dialog_content = "Pero Barton aun esta afuera...",
  ui_story_1011_10110502_29_dialog_content = "Enlace mental!",
  ui_story_1011_10110502_30_dialog_content = "Barton, ¿estás bien? ¿Estás herido?",
  ui_story_1011_10110502_31_dialog_content = "Sin preocupaciones. ¡Nunca he estado mejor!",
  ui_story_1011_10110502_32_dialog_content = "¿Cómo estáis chicos?",
  ui_story_1011_10110502_33_dialog_content = "La entrada ha sido sellada. ¡No te preocupes por nosotros!",
  ui_story_1011_10110502_34_dialog_content = "Excelente. ¡Ahora puedo dejarme llevar de verdad!",
  ui_story_1011_10110502_35_dialog_content = "¡Cuidate!",
  ui_story_1011_10110502_36_dialog_content = "Depende de nosotros ahora.",
  ui_story_1011_10110502_37_dialog_content = "Démonos prisa y busquemos las ruinas.",
  ui_story_1011_10110502_38_dialog_content = "La entrada con barricadas solo puede contenerlos por un tiempo.",
  ui_story_1011_10110502_39_dialog_content = "Los Eclipsites tienen suficiente mano de obra para excavar o escalar la torre y entrar de esa manera.",
  ui_story_1011_10110502_40_dialog_content = "Vamos a dividir.",
  ui_story_1011_10110502_41_dialog_content = "Ya hemos buscado por toda esta área.",
  ui_story_1011_10110502_42_dialog_content = "Incluso si miramos de nuevo, todo lo que vamos a encontrar es basura al azar.",
  ui_story_1011_10110502_43_dialog_content = "¿Alguien tiene alguna otra idea?",
  ui_story_1011_10110502_44_dialog_content = "¿Como tal vez algo que solo un Caelestita sería capaz de hacer?",
  ui_story_1011_10110502_45_dialog_content = "¿Te refieres a mi habilidad psíquica?",
  ui_story_1011_10110502_46_dialog_content = "Sí.",
  ui_story_1011_10110502_47_dialog_content = "¿Puedes usar tu habilidad psíquica y ver si hay alguna pista?",
  ui_story_1011_10110502_48_dialog_content = "Lo intentaré.",
  ui_story_1011_10110502_49_option_content = "Enlace mental!",
  ui_story_1011_10110502_50_dialog_content = "¡Ay!",
  ui_story_1011_10110502_51_dialog_content = "¡Mi cabeza!",
  ui_story_1011_10110502_52_dialog_content = "¿¡PlayerName!?",
  ui_story_1011_10110502_53_dialog_content = "Este lugar es muy extraño.",
  ui_story_1011_10110502_54_dialog_content = "Se siente como si algo estuviera impidiendo que mi habilidad sondee el área.",
  ui_story_1011_10110502_55_dialog_content = "Interferir con la habilidad psíquica de Caelestite...",
  ui_story_1011_10110502_56_dialog_content = "¿Qué está tratando de ocultar este lugar?",
  ui_story_1011_10110502_57_dialog_content = "Pero significa que estamos en el camino correcto.",
  ui_story_1011_10110502_58_dialog_content = "Excepto si Navigator no puede usar su habilidad psíquica, no tenemos pistas.",
  ui_story_1011_10110502_59_dialog_content = "... No, todavía hay una manera.",
  ui_story_1011_10110502_60_dialog_content = "Encontré la plantilla de eco para Soroz usando mi habilidad en el módulo Think Tank.",
  ui_story_1011_10110502_61_dialog_content = "Además, fueron los datos del módulo de reparación los que nos señalaron aquí.",
  ui_story_1011_10110502_62_dialog_content = "Puedo intentar usar mi habilidad en el módulo de reparación y ver si hay una forma de solucionar nuestro problema.",
  ui_story_1011_10110502_62X1_dialog_content = "Mi habilidad funcionó bien antes con Barton.",
  ui_story_1011_10110502_62X2_dialog_content = "Supongo que si tengo un objetivo concreto, debería funcionar.",
  ui_story_1011_10110502_63_dialog_content = "Eso suena plausible.",
  ui_story_1011_10110502_64_dialog_content = "Aún así...",
  ui_story_1011_10110502_65_dialog_content = "Si comienza a sentirse incómodo, debe cortar el vínculo. Oyes, PlayerName?",
  ui_story_1011_10110502_66_dialog_content = "No te excedas.",
  ui_story_1011_10110502_67_dialog_content = "Lo tengo. No te preocupes.",
  ui_story_1011_10110502_68_option_content = "¡Control forzado!",
  ui_story_1011_10110502_69_dialog_content = "...",
  ui_story_1011_10110502_70_dialog_content = "¡Dime cómo llegar a la Sala de Control Central!",
  ui_story_1011_10110502_71_dialog_content = "\"Comando aceptado. Examinando...\"",
  ui_story_1011_10110502_72_dialog_content = "\"Sistema de control de acceso fuera de línea\".",
  ui_story_1011_10110502_73_dialog_content = "\"Enviando a Firefly para tareas de mantenimiento\".",
  ui_story_1011_10110502_74_dialog_content = "Una luciérnaga... ¿de Soroz?",
  ui_story_1011_10110502_75_dialog_content = "\"¡Bip!\"",
  ui_story_1011_10110502_76_dialog_content = "<color=#e8d9bb>Hacer clic</color>",
  ui_story_1011_10110502_77_dialog_content = "\"Unidad de energía de respaldo de control de acceso conectada. Activando el sistema de control de acceso\".",
  ui_story_1011_10110502_78_dialog_content = "\"Por favor, diga la palabra de seguridad para la verificación de identidad\".",
  ui_story_1011_10110502_79_dialog_content = "¿Qué?",
  ui_story_1011_10110502_80_dialog_content = "¿De dónde viene esa voz?",
  ui_story_1011_10110502_81_dialog_content = "\"Este es el sistema de control de acceso a la base de mantenimiento Colossus\".",
  ui_story_1011_10110502_82_dialog_content = "\"Advertencia: el sistema de control de acceso se ha desconectado del sistema de control central durante ■■■■■■ días\".",
  ui_story_1011_10110502_83_dialog_content = "\"Por favor, restablezca la conexión o use la contraseña de restablecimiento\".",
  ui_story_1011_10110502_84_dialog_content = "¿Eso suena como algo que puede abrir una puerta?",
  ui_story_1011_10110502_85_dialog_content = "¡Y también está controlado por voz!",
  ui_story_1011_10110502_86_dialog_content = "\"Contraseña no válida. Quedan 3 intentos\".",
  ui_story_1011_10110502_87_dialog_content = "¿eh? ¡No! Ese no era yo tratando de...",
  ui_story_1011_10110502_88_dialog_content = "\"Contraseña no válida. Quedan 2 intentos\".",
  ui_story_1011_10110502_89_dialog_content = "¡Hey, espera!",
  ui_story_1011_10110502_90_dialog_content = "\"Contraseña no válida. Queda 1 intento\".",
  ui_story_1011_10110502_91_dialog_content = "\"Precaución: más errores bloquearán el sistema de control de acceso\".",
  ui_story_1011_10110502_92_dialog_content = "¡Deja de hablar!",
  ui_story_1011_10110502_93_dialog_content = "¡Mmm! ¡Mmm!",
  ui_story_1011_10110502_94_dialog_content = "¿Podemos restablecer la contraseña?",
  ui_story_1011_10110502_95_dialog_content = "\"Advertencia: no coincide el tipo de gen. Comando no válido\".",
  ui_story_1011_10110502_96_dialog_content = "...",
  ui_story_1011_10110502_97_dialog_content = "(¿Quieres que lo intente?)",
  ui_story_1011_10110502_98_dialog_content = "Esta es la última oportunidad. PlayerName, A por ello.",
  ui_story_1011_10110502_99_dialog_content = "Asegúrate de pensar antes de hablar.",
  ui_story_1011_10110502_100_dialog_content = "(Bien...)",
  ui_story_1011_10110502_101_dialog_content = "...",
  ui_story_1011_10110502_102_option_content = "Control de acceso, restablecer contraseña.",
  ui_story_1011_10110502_103_dialog_content = "\"Tipo de gen autenticado. Restablecimiento de contraseña\".",
  ui_story_1011_10110502_104_dialog_content = "\"Responda las siguientes 3 preguntas para la verificación de identidad\".",
  ui_story_1011_10110502_105_dialog_content = "¿Hay preguntas de seguridad?",
  ui_story_1011_10110502_106_dialog_content = "Tenemos que ir con la corriente.",
  ui_story_1011_10110502_107_dialog_content = "No te preocupes, PlayerName. Ayudaré.",
  ui_story_1011_10110502_108_dialog_content = "¡Estoy poniendo mi reputación como estudiante sobresaliente en juego!",
  ui_story_1011_10110502_109_dialog_content = "\"¿Eres un eclipse?\"",
  ui_story_1011_10110502_110_dialog_content = "¿eh...?",
  ui_story_1011_10110502_111_dialog_content = "¿¡Cómo podría ser un Eclipsite!?",
  ui_story_1011_10110502_112_dialog_content = "\"Respuesta invalida.\"",
  ui_story_1011_10110502_113_dialog_content = "\"Repito: ¿Eres un Eclipsite?\"",
  ui_story_1011_10110502_114_dialog_content = "No, no lo soy.",
  ui_story_1011_10110502_115_dialog_content = "\"Respuesta aceptada\".",
  ui_story_1011_10110502_116_dialog_content = "\"¿Eres auroriano?\"",
  ui_story_1011_10110502_117_dialog_content = "No soy auroriano.",
  ui_story_1011_10110502_118_dialog_content = "\"Respuesta aceptada\".",
  ui_story_1011_10110502_119_dialog_content = "\"Seleccione un Firefly de las siguientes opciones\".",
  ui_story_1011_10110502_120_dialog_content = "¿Son estas... proyecciones?",
  ui_story_1011_10110502_121_dialog_content = "¡Parece tan real!",
  ui_story_1011_10110502_122_option_content = "Toca la proyección de Firefly",
  ui_story_1011_10110502_123_dialog_content = "\"Respuesta aceptada\".",
  ui_story_1011_10110502_124_dialog_content = "\"Identidad verificada: Caelestite\".",
  ui_story_1011_10110502_125_dialog_content = "\"Por favor, introduzca la nueva contraseña\".",
  ui_story_1011_10110502_126_dialog_content = "Umm... ¡Ábrete sésamo!",
  ui_story_1011_10110502_127_dialog_content = "\"Restablecimiento de contraseña. Nueva contraseña: Umm... Abre sésamo\".",
  ui_story_1011_10110502_128_dialog_content = "¡No incluyas inflexiones en la contraseña, por Dios!",
  ui_story_1011_10110502_129_dialog_content = "\"Abriendo puertas\".",
  ui_story_1011_10110502_130_dialog_content = "<color=#e8d9bb>¡Kaboom!</color>",
  ui_story_1011_10110502_131_dialog_content = "¡Whoa!",
  ui_story_1011_10110502_132_dialog_content = "<color=#e8d9bb>*retumbando*</color>",
  ui_story_1011_10110502_133_dialog_content = "¡La pared se está partiendo! Y... espera, ¿eso es una puerta?",
  ui_story_1011_10110502_134_dialog_content = "¡Es enorme!",
  ui_story_1011_10110502_135_dialog_content = "Pero, ¡¿qué diablos fue eso?!",
  ui_story_1011_10110502_136_dialog_content = "¡Ese proceso de verificación de identidad fue ridículo!",
  ui_story_1011_10110502_137_dialog_content = "¡Cualquier ser inteligente sería capaz de abrirse camino a través de mentiras!",
  ui_story_1011_10110502_137X1_dialog_content = "No creo que las respuestas fueran lo que se estaba verificando.",
  ui_story_1011_10110502_137X2_dialog_content = "¿Entonces que?",
  ui_story_1011_10110502_137X3_dialog_content = "¿Cómo puedes verificar que alguien es Caelestita a través de una serie de preguntas simples?",
  ui_story_1011_10110502_137X4_dialog_content = "Anteriormente, cuando hice una pregunta, respondió: \"Desajuste del tipo de gen\".",
  ui_story_1011_10110502_137X5_dialog_content = "Creo que ya había verificado tu identidad como caelestita por otros medios.",
  ui_story_1011_10110502_137X6_dialog_content = "Las preguntas eran solo para hacerte confirmar: \"Soy un caelestita\".",
  ui_story_1011_10110502_137X7_dialog_content = "¿La confirmación era más importante que todas las demás pruebas?",
  ui_story_1011_10110502_137X8_dialog_content = "Supongo que así es como piensan las máquinas.",
  ui_story_1011_10110502_137X9_dialog_content = "Entonces, ¿estás diciendo... que estas ruinas cuentan con tecnología que puede realizar pruebas genéticas remotas?",
  ui_story_1011_10110502_137X10_dialog_content = "La transparencia total me hace sentir algo incómodo.",
  ui_story_1011_10110502_137X11_dialog_content = "Olvida eso. Lo que importa es el resultado.",
  ui_story_1011_10110502_137X12_dialog_content = "La puerta está abierta. No necesitamos detenernos en cómo sucedió.",
  ui_story_1011_10110502_138_dialog_content = "Sinceramente, deberíamos agradecer a su diseño simplista por hacernos la vida más fácil.",
  ui_story_1011_10110502_139_dialog_content = "La puerta que conduce hacia abajo debe ser la entrada a las ruinas subterráneas.",
  ui_story_1011_10110502_140_dialog_content = "Pero si una puerta como esta siempre ha estado aquí, ¿cómo es que los caelestitas la extrañaron todos esos años?",
  ui_story_1011_10110502_141_dialog_content = "No sé... Todo aquí está envuelto en misterio.",
  ui_story_1011_10110502_142_dialog_content = "De todos modos, el pasaje aquí significa que todavía hay regiones debajo para que las exploremos.",
  ui_story_1011_10110502_143_dialog_content = "Nuestra prioridad en este momento es encontrar una manera de reparar Soroz, superar los eclipses y encontrar una manera de salir de aquí.",
  ui_story_1011_10110502_144_dialog_content = "Estás bien. No tenemos un momento que perder.",
  ui_story_1011_10110502_145_dialog_content = "¡Vamos a ello, entonces!",
  ui_story_1011_10110601_1_dialog_content = "Graah!",
  ui_story_1011_10110601_2_dialog_content = "¿Ni siquiera puedes montar una emboscada adecuada? ¡Eres carne de cañón!",
  ui_story_1011_10110601_3_dialog_content = "¿Quien te envio? ¿Un eclipse de mayor tamaño? ¿O ese chiflado de científico?",
  ui_story_1011_10110601_4_dialog_content = "Cierto, casi olvido que ustedes ni siquiera pueden hablar.",
  ui_story_1011_10110601_5_dialog_content = "gaar...",
  ui_story_1011_10110601_6_dialog_content = "¡Jajaja! ¡Nada más que basura!",
  ui_story_1011_10110601_7_dialog_content = "Matar a gente como tú ni siquiera es un logro. ¿Es esto todo lo que tiene Eclipse?",
  ui_story_1011_10110601_8_dialog_content = "...",
  ui_story_1011_10110601_10_dialog_content = "¿Quién está ahí?",
  ui_story_1011_10110601_11_dialog_content = "...",
  ui_story_1011_10110601_12_dialog_content = "Realmente eres tú. <color=#FFB400>negador</color>, traidor de Illumina.",
  ui_story_1011_10110601_13_dialog_content = "... En realidad no. Fuiste exiliado de Illumina.",
  ui_story_1011_10110601_14_dialog_content = "Tsk.",
  ui_story_1011_10110601_15_dialog_content = "Debo decir que si querías sacrificar tus tropas para crear una distracción, no deberías haberte atrapado.",
  ui_story_1011_10110601_16_dialog_content = "(¿Tropas...? ¿Son estos los secuaces de Figerald?)",
  ui_story_1011_10110601_17_dialog_content = "(Siempre superfluo, ese...)",
  ui_story_1011_10110601_18_dialog_content = "No tengo ningún interés en pelear contigo, y no envié estos Eclipsites.",
  ui_story_1011_10110601_19_dialog_content = "Una pelea tonta solo enterraría aún más los secretos de la Torre Blanca.",
  ui_story_1011_10110601_20_dialog_content = "(¿La Torre Blanca? Así que ella planea seguir PlayerName...?)",
  ui_story_1011_10110601_21_dialog_content = "¿eh? No hay tiempo para charlas ociosas en un campo de batalla.",
  ui_story_1011_10110601_22_dialog_content = "Si quieres entrar, sigue adelante. Si puedes pasarme.",
  ui_story_1011_10110601_23_dialog_content = "He terminado de hablar contigo. Toma esto, Forsakin!",
  ui_story_1011_10110601_24_dialog_content = "¡Prueba el poder de Ironjaw!",
  ui_story_1011_10110601_25_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_1011_10110601_26_dialog_content = "Qué problemático. ¿Qué tiene que ver este lugar contigo?",
  ui_story_1011_10110601_27_dialog_content = "Odio las complicaciones.",
  ui_story_1011_10110601_28_dialog_content = "Si deshacerme de ti puede ahorrarme más problemas... Morderé.",
  ui_story_1011_10110601_29_dialog_content = "Jajajaja! ¡Eso es lo que me gusta escuchar!",
  ui_story_1011_10110601_30_dialog_content = "¡Vamos a matar el tiempo juntos!",
  ui_story_1011_10110601_31_dialog_content = "<color=#e8d9bb>Pasaje de entrada, torre principal</color>",
  ui_story_1011_10110601_32_dialog_content = "<color=#e8d9bb>*Pasos resonando*</color>",
  ui_story_1011_10110601_33_dialog_content = "(Qué pasillo tan largo y angosto. Parece durar una eternidad...)",
  ui_story_1011_10110601_34_dialog_content = "(Apenas puedo ver la luz de la entrada ahora.)",
  ui_story_1011_10110601_35_dialog_content = "<color=#e8d9bb>Clam, clang...</color>",
  ui_story_1011_10110601_36_dialog_content = "Vice, ¡Cuidado!",
  ui_story_1011_10110601_37_dialog_content = "¿¡Qué!?",
  ui_story_1011_10110601_38_dialog_content = "<color=#e8d9bb>Auge-</color>",
  ui_story_1011_10110601_39_dialog_content = "¡Ten cuidado!",
  ui_story_1011_10110601_40_dialog_content = "*Tose*",
  ui_story_1011_10110601_41_dialog_content = "¡Está tan polvoriento aquí!",
  ui_story_1011_10110601_42_dialog_content = "<color=#e8d9bb><size=35>aquí... aquí... aquí...</size></color>",
  ui_story_1011_10110601_43_dialog_content = "¿Mmm?",
  ui_story_1011_10110601_44_dialog_content = "Cállate. Mantengámoslo abajo.",
  ui_story_1011_10110601_45_dialog_content = "Parece que todavía tenemos un largo camino por recorrer.",
  ui_story_1011_10110601_46_dialog_content = "Si nuestras voces atraen algo hacia nosotros en este estrecho corredor, ni siquiera tendríamos un lugar donde escondernos.",
  ui_story_1011_10110601_47_dialog_content = "De paso, PlayerName...",
  ui_story_1011_10110601_48_dialog_content = "¿Realmente no sabías que este lugar existía antes de esto?",
  ui_story_1011_10110601_49_dialog_content = "Sí... Ni siquiera Soroz mencionó este lugar antes.",
  ui_story_1011_10110601_50_dialog_content = "De todos modos, no es que Soroz lo sepa todo.",
  ui_story_1011_10110601_51_dialog_content = "...",
  ui_story_1011_10110601_52_dialog_content = "(Soroz...)",
  ui_story_1011_10110601_53_dialog_content = "Ya que nos guió aquí el plugin Echo Template...",
  ui_story_1011_10110601_54_dialog_content = "Todo lo que necesitamos es encontrar ese \"Sistema de control central\", ¿verdad?",
  ui_story_1011_10110601_55_dialog_content = "Definitivamente encontraremos lo que necesitamos para arreglar a Soroz allí, PlayerName.",
  ui_story_1011_10110601_56_dialog_content = "Gracias, Vice.",
  ui_story_1011_10110601_57_dialog_content = "¿Qué?",
  ui_story_1011_10110601_58_dialog_content = "¿Qué tal?",
  ui_story_1011_10110601_59_dialog_content = "El material debajo de nuestros pies no parece ser guijarros regulares o piedras blancas comunes.",
  ui_story_1011_10110601_60_dialog_content = "Hmmm... Déjame ver.",
  ui_story_1011_10110601_61_dialog_content = "El color y la textura son bastante únicos. Por lo que aprendí en la Academia...",
  ui_story_1011_10110601_62_dialog_content = "Este material pétreo es exclusivo del antiguo Astra...",
  ui_story_1011_10110601_63_dialog_content = "(Eh...?)",
  ui_story_1011_10110601_64_dialog_content = "E-Eso significa que estos son...",
  ui_story_1011_10110601_65_dialog_content = "<color=#FFB400>Parches de coloso</color>?",
  ui_story_1011_10110601_66_dialog_content = "¡¿?!",
  ui_story_1011_10110601_67_dialog_content = "(El camino por delante está cubierto con estas piedras trituradas...)",
  ui_story_1011_10110601_68_dialog_content = "(¿Podrían ser todos estos... Coloso <color=#FFB400>restos</color>?)",
  ui_story_1011_10110601_69_dialog_content = "¡Lo que significa que estamos realmente dentro de la base de mantenimiento Colossus!",
  ui_story_1011_10110601_70_dialog_content = "En cuanto a la cantidad, Colossi debe haber sido vehículos comunes en ese entonces, ¡tal como lo afirman las leyendas y los registros históricos!",
  ui_story_1011_10110601_71_dialog_content = "Oye, PlayerName. ¿Es ese el final del pasaje?",
  ui_story_1011_10110601_72_dialog_content = "mmm... PlayerName. ¿Estás bien?",
  ui_story_1011_10110601_73_dialog_content = "...",
  ui_story_1011_10110601_74_option_content = "Siento un poco de miedo.",
  ui_story_1011_10110601_75_dialog_content = "Yo... nunca había visto algo así...",
  ui_story_1011_10110601_76_dialog_content = "Soroz para mí es... una familia, una amiga, una mentora...",
  ui_story_1011_10110601_77_dialog_content = "Hemos ido a muchos lugares y sobrevivido a tanto peligro...",
  ui_story_1011_10110601_78_dialog_content = "Pero nunca pensé que podría terminar así algún día.",
  ui_story_1011_10110601_79_option_content = "Me siento un poco emocionado.",
  ui_story_1011_10110601_80_dialog_content = "Los colosos son pocos en el Astra actual.",
  ui_story_1011_10110601_81_dialog_content = "La idea de este enorme cementerio de Colosos dejado atrás por mis antepasados...",
  ui_story_1011_10110601_82_dialog_content = "Acostado aquí justo debajo de Soroz y yo en un Eraveil que ha estado desocupado durante 17 años...",
  ui_story_1011_10110601_83_dialog_content = "Siento una extraña sensación de pertenencia.",
  ui_story_1011_10110601_84_dialog_content = "Ya veo.",
  ui_story_1011_10110601_85_dialog_content = "Entonces sigamos adelante.",
  ui_story_1011_10110601_86_dialog_content = "Veamos de dónde vienen todos estos restos de colosos.",
  ui_story_1011_10110601_87_dialog_content = "Finalmente, en algún lugar más abierto.",
  ui_story_1011_10110601_88_dialog_content = "Esperaba que esta área fuera más oscura, pero en realidad es lo suficientemente brillante.",
  ui_story_1011_10110601_89_dialog_content = "Solo las sombras nebulosas del Coloso obstruyen nuestra vista.",
  ui_story_1011_10110601_90_dialog_content = "Aunque no sabemos la fuente de esta luz, al menos esto prueba que no estamos en un espacio completamente cerrado.",
  ui_story_1011_10110601_91_dialog_content = "Mira estos Colosos todos alineados en orden...",
  ui_story_1011_10110601_92_dialog_content = "Podrían haber estado muy bien conservados si este lugar no se hubiera derrumbado...",
  ui_story_1011_10110601_93_dialog_content = "PlayerName, deberías darle una oportunidad a tu habilidad psíquica.",
  ui_story_1011_10110601_94_dialog_content = "Si hay algún Colossi que aún funcione, podrías establecer una conexión.",
  ui_story_1011_10110601_95_dialog_content = "Buen punto. Después-",
  ui_story_1011_10110601_96_option_content = "¡Control forzado!",
  ui_story_1011_10110601_97_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10110601_98_dialog_content = "No. No hay respuesta en absoluto.",
  ui_story_1011_10110601_99_dialog_content = "(¿En qué estoy pensando? Encontrar un ser con conciencia dentro de una ruina como esta es imposible...)",
  ui_story_1011_10110601_100_dialog_content = "¡A-Al menos hemos visto rastros de los antiguos Colosos!",
  ui_story_1011_10110601_101_dialog_content = "A continuación, comprobemos seguir estas puertas y mirar a través de todas ellas.",
  ui_story_1011_10110601_102_dialog_content = "Vamos, PlayerName.",
  ui_story_1011_10110601_103_dialog_content = "Derecha. Entonces vamos...",
  ui_story_1011_10110601_104_option_content = "Revisa los alrededores",
  ui_story_1011_10110601_105_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_1011_10110601_106_dialog_content = "¡¿Eh?!",
  ui_story_1011_10110601_107_dialog_content = "Me duele la mano... ¡Ni siquiera se mueve!",
  ui_story_1011_10110601_108_dialog_content = "A juzgar por el daño causado a los Colosos, dudo que estas habitaciones estén intactas.",
  ui_story_1011_10110601_109_dialog_content = "Las rocas caídas han sellado estas puertas para cerrarlas. Parece que adelante es nuestro único camino.",
  ui_story_1011_10110601_110_option_content = "avanzar",
  ui_story_1011_10110601_111_dialog_content = "¡Bien! Más adelante, ¡parece que hay escaleras que conducen a un nivel inferior!",
  ui_story_1011_10110601_112_dialog_content = "Debería ser seguro caminar sobre... ¿Cierto? Quiero decir, si todavía existen después de todos estos años...",
  ui_story_1011_10110601_113_dialog_content = "Solía haber tantos Colosos aparcados en la entrada.",
  ui_story_1011_10110601_114_dialog_content = "Eso implica que el espacio de abajo debe estar completamente equipado para haber dado servicio una vez a todos esos Colosos.",
  ui_story_1011_10110601_115_dialog_content = "Continuemos, PlayerName.",
  ui_story_1011_10110601_116_dialog_content = "<color=#e8d9bb>*Pasos resonando*</color>",
  ui_story_1011_10110601_117_dialog_content = "(La escalera está tan poco iluminada. Si tan solo hubiera una luciérnaga aquí...)",
  ui_story_1011_10110601_118_dialog_content = "(Me pregunto qué tipo de tecnología está enterrada allí, y si se puede usar en Soroz...)",
  ui_story_1011_10110601_119_dialog_content = "(Finalmente hemos llegado al final. No puedo esperar para irme⁠—)",
  ui_story_1011_10110601_120_dialog_content = "¿eh...?",
  ui_story_1011_10110601_121_dialog_content = "C-Cómo podría esto...",
  ui_story_1011_10110601_122_dialog_content = "Es espacioso y abierto, pero no hay grandes equipos de ningún tipo a la vista...",
  ui_story_1011_10110601_123_dialog_content = "Estas ruinas subterráneas son mucho más grandes de lo que pensé que serían.",
  ui_story_1011_10110601_124_dialog_content = "Pero, ¿para qué era este nivel?",
  ui_story_1011_10110601_125_dialog_content = "Mesas polvorientas, estantes de piedra llenos de cosas que ya no identificamos y colchones al azar...",
  ui_story_1011_10110601_126_dialog_content = "¿Tal vez esto era una sala de almacenamiento?",
  ui_story_1011_10110601_127_dialog_content = "Pfft... ¡Jajaja! Ahora que lo has dicho, creo que tengo una idea.",
  ui_story_1011_10110601_128_dialog_content = "Me imagino que este lugar solía ser el<color=#FFB400>vivienda</color> de los antiguos Caelestitas.",
  ui_story_1011_10110601_129_dialog_content = "Servicios básicos similares se pueden encontrar en áreas residenciales de Entrañas de Illumina.",
  ui_story_1011_10110601_130_dialog_content = "Aunque la mayoría de los objetos aquí están hechos jirones y hechos jirones, todavía puedes distinguirlos...",
  ui_story_1011_10110601_131_dialog_content = "Mesas de comedor, bancos de trabajo, despensas, estanterías, colchones...",
  ui_story_1011_10110601_132_dialog_content = "Esto no es escombros al azar, Carleen.",
  ui_story_1011_10110601_133_dialog_content = "¡Ya lo sé!",
  ui_story_1011_10110601_134_dialog_content = "¿Mmm?",
  ui_story_1011_10110601_135_dialog_content = "Vice, Mira. ¿Hay algo en esta taza?",
  ui_story_1011_10110601_136_dialog_content = "¿Hmm? ¿Dónde?",
  ui_story_1011_10110601_137_dialog_content = "¡A mí me parecen manchas normales!",
  ui_story_1011_10110601_138_dialog_content = "No. Me refiero al fondo de la taza. PlayerName, ven a ver esto.",
  ui_story_1011_10110601_139_dialog_content = "Eh... Parece una especie de símbolo.",
  ui_story_1011_10110601_140_dialog_content = "¡Oye, tienes wazón!",
  ui_story_1011_10110601_141_dialog_content = "¿Podría este símbolo estar relacionado con los Caelestitas...?",
  ui_story_1011_10110601_142_dialog_content = "No me parece. Mira todas las cosas esparcidas.",
  ui_story_1011_10110601_143_dialog_content = "Esta copa es la única que tiene la marca.",
  ui_story_1011_10110601_144_dialog_content = "Verdadero. Si realmente es un símbolo que representa Caelestites, debería estar en todo.",
  ui_story_1011_10110601_145_dialog_content = "¿Así que qué es lo? Realmente no puedo entenderlo...",
  ui_story_1011_10110601_146_dialog_content = "Creo que se parece a... las iniciales de un nombre, pero...",
  ui_story_1011_10110601_147_dialog_content = "No, está demasiado gastado para leer.",
  ui_story_1011_10110601_148_dialog_content = "Entonces no perdamos el tiempo en ello.",
  ui_story_1011_10110601_149_dialog_content = "Hmm...",
  ui_story_1011_10110601_150_dialog_content = "(A pesar de PlayerNamelas palabras de, no puedo simplemente olvidarlo...)",
  ui_story_1011_10110601_151_dialog_content = "(El destino debe habernos llevado al nombre de la persona que una vez vivió aquí).",
  ui_story_1011_10110601_152_dialog_content = "(Estaré atento a cualquier cosa relacionada con esto).",
  ui_story_1011_10110601_153_dialog_content = "¿Mmm? ¿Qué es esto sobre la mesa?",
  ui_story_1011_10110601_154_dialog_content = "¡Increíble! Su...",
  ui_story_1011_10110601_155_dialog_content = "conchas de nautilus?",
  ui_story_1011_10110601_156_dialog_content = "No uno, sino un montón de ellos.",
  ui_story_1011_10110601_157_dialog_content = "eh... entonces PlayerName, son estos... Caelestite artículos de uso diario?",
  ui_story_1011_10110601_158_dialog_content = "¿eh? ¿Encontraste esto justo ahora?",
  ui_story_1011_10110601_159_dialog_content = "No hay forma de que sepa para qué sirven cuando ni siquiera sé lo que son.",
  ui_story_1011_10110601_160_dialog_content = "¿Nautilus? ¿No son esas criaturas marinas?",
  ui_story_1011_10110601_161_dialog_content = "¿Podría ser que... Eraveil solía ser un océano? ¿O tal vez los antiguos Caelestitas los tenían como comida?",
  ui_story_1011_10110601_162_dialog_content = "¡Ambos suenan ridículos!",
  ui_story_1011_10110601_163_dialog_content = "Bueno, estas conchas de nautilus son diferentes a las que conocemos...",
  ui_story_1011_10110601_164_dialog_content = "Son pequeños y suaves, livianos y, de alguna manera, todavía están en perfectas condiciones después de todos estos años.",
  ui_story_1011_10110601_165_dialog_content = "Deben estar diseñados para ser una especie de almacenamiento portátil.",
  ui_story_1011_10110601_166_dialog_content = "Además... ¡AAAAAH!",
  ui_story_1011_10110601_167_dialog_content = "¡Hay algo dentro!",
  ui_story_1011_10110601_168_dialog_content = "¿¡Qué!?",
  ui_story_1011_10110601_169_dialog_content = "¿Estás bien? ¿Se derramó algo?",
  ui_story_1011_10110601_170_dialog_content = "Estoy bien. Me llegó a la mano, pero no siento nada.",
  ui_story_1011_10110601_171_dialog_content = "*Sniff sniff*",
  ui_story_1011_10110601_172_dialog_content = "Hmm... No tiene olor ni sabor, y es muy fluido. Sin embargo, no puedo decir qué tipo de líquido es.",
  ui_story_1011_10110601_173_dialog_content = "(Espera... Conchas... ¿fluidez?)",
  ui_story_1011_10110601_174_dialog_content = "(No me digas ...)",
  ui_story_1011_10110601_175_dialog_content = "Uf... Aún así, es mejor tener cuidado cuando ni siquiera sabemos qué es.",
  ui_story_1011_10110601_176_dialog_content = "T-Tienes razón.",
  ui_story_1011_10110601_177_dialog_content = "(Mejor mantengo la boca cerrada por ahora hasta que tenga pruebas).",
  ui_story_1011_10110601_178_dialog_content = "(Pero si tengo razón, debería poder encontrar pruebas en algún lugar de estas ruinas).",
  ui_story_1011_10110601_179_dialog_content = "(Pondré esto en mi bolsillo por ahora...)",
  ui_story_1011_10110601_180_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_1011_10110601_181_dialog_content = "¿Eh?",
  ui_story_1011_10110601_182_dialog_content = "PlayerName, Carleen, ¿Paso algo?",
  ui_story_1011_10110601_183_dialog_content = "¿Qué? Pensé que el sonido venía de tu lado. Espera un minuto...",
  ui_story_1011_10110601_184_dialog_content = "... ¡Algo no esta bien!",
  ui_story_1011_10110601_185_dialog_content = "¿Podría haber alguien más aquí?",
  ui_story_1011_10110601_186_dialog_content = "Si ese fuera el caso, ya habrían aparecido. Solo tengo miedo de que sea—",
  ui_story_1011_10110601_187_dialog_content = "gaar...",
  ui_story_1011_10110601_188_dialog_content = "Rugido... ¡¡¡Rugido!!!",
  ui_story_1011_10110601_189_dialog_content = "Tienes que estar bromeando. ¿Eclipsitos, aquí?",
  ui_story_1011_10110601_190_dialog_content = "¿Me estás diciendo que lograron seguirnos?",
  ui_story_1011_10110601_191_dialog_content = "PlayerName, ¿estás listo para una pelea?",
  ui_story_1011_10110601_192_dialog_content = "¡Siempre!",
  ui_story_1011_10110702_1_dialog_content = "PlayerName, PlayerName!",
  ui_story_1011_10110702_2_dialog_content = "¿Q-Qué está pasando...?",
  ui_story_1011_10110702_3_dialog_content = "¡Despierta, PlayerName!",
  ui_story_1011_10110702_4_dialog_content = "(Mmm...)",
  ui_story_1011_10110702_5_dialog_content = "(Yo... no puedo respirar...)",
  ui_story_1011_10110702_6_dialog_content = "(Son Vice y Carleen ¿llamándome? Suenan tan lejos...)",
  ui_story_1011_10110702_7_dialog_content = "(Yo...)",
  ui_story_1011_10110702_8_dialog_content = "Sujeto detectado: forma de vida supersensorial. Identidad confirmada: Caelestite.)",
  ui_story_1011_10110702_9_dialog_content = "Enlace mental establecido.",
  ui_story_1011_10110702_10_dialog_content = "Advertencia: los niveles de O2 descienden en el sistema respiratorio del sujeto. Sistema de ventilación del área residencial activado.",
  ui_story_1011_10110702_11_dialog_content = "<color=#e8d9bb>Whoosh, whoosh...</color>",
  ui_story_1011_10110702_12_dialog_content = "(¿Q-Qué es ese sonido?)",
  ui_story_1011_10110702_13_dialog_content = "¿Mm...?",
  ui_story_1011_10110702_14_dialog_content = "Vaya, PlayerName!",
  ui_story_1011_10110702_15_dialog_content = "¡PlayerName! ¡Estas despierta!",
  ui_story_1011_10110702_16_dialog_content = "¿Cómo te sientes?",
  ui_story_1011_10110702_17_dialog_content = "Yo... Creo que estoy bien ahora.",
  ui_story_1011_10110702_18_dialog_content = "La batalla de antes me costó mucho, y el largo viaje hasta aquí fue agotador... así que yo...",
  ui_story_1011_10110702_19_dialog_content = "No podía recuperar el aliento, y entonces...",
  ui_story_1011_10110702_20_dialog_content = "La batalla...?",
  ui_story_1011_10110702_21_dialog_content = "¿Agotador?",
  ui_story_1011_10110702_22_dialog_content = "...",
  ui_story_1011_10110702_23_dialog_content = "(¡No me mires así en silencio!)",
  ui_story_1011_10110702_24_dialog_content = "Analizando el estado físico del sujeto...",
  ui_story_1011_10110702_25_dialog_content = "Estado: Normal. Clasificación física: A-.",
  ui_story_1011_10110702_26_dialog_content = "¿Eh?",
  ui_story_1011_10110702_27_dialog_content = "¡¿Q-Quién habla?!",
  ui_story_1011_10110702_28_dialog_content = "No está mal, pero...",
  ui_story_1011_10110702_29_dialog_content = "La directiva principal de Neural Aux es ayudar a Caelestites de todas las formas posibles.",
  ui_story_1011_10110702_30_dialog_content = "Recibido... Analizando pregunta...",
  ui_story_1011_10110702_31_dialog_content = "Respuesta encontrada: Se requiere asistencia de un Caelestita. Neural Aux está hablando con Caelestite.",
  ui_story_1011_10110702_32_dialog_content = "(¡¿Toma tanto tiempo responder una pregunta tan simple?!)",
  ui_story_1011_10110702_33_dialog_content = "Pero, ahora que lo pienso, cuando me desmayé...",
  ui_story_1011_10110702_34_dialog_content = "Advertencia: los niveles de O2 descienden en el sistema respiratorio del sujeto. Sistema de ventilación del área residencial conectado.",
  ui_story_1011_10110702_35_dialog_content = "Así que activó el sistema de ventilación aquí para ayudarme.",
  ui_story_1011_10110702_36_dialog_content = "Oh... Con razón sentí... una pizca de brisa en mi piel.",
  ui_story_1011_10110702_36X_dialog_content = "¿Qué es eso? Parece un holograma.",
  ui_story_1011_10110702_37_dialog_content = "Entonces, ¿esta es la antigua tecnología de Caelestite? Demuestra ser bastante confiable en tiempos de emergencia.",
  ui_story_1011_10110702_38_dialog_content = "¡Guau! Déjame echar un vistazo. ¡No puedo creer que haya una IA funcionando aquí!",
  ui_story_1011_10110702_39_dialog_content = "Hmm...",
  ui_story_1011_10110702_40_dialog_content = "...",
  ui_story_1011_10110702_41_dialog_content = "Objetivo detectado: forma de vida luminosa. Identidad confirmada: Aurorian. Cantidad: 2.",
  ui_story_1011_10110702_42_dialog_content = "\"Neural Aux\"... ¿Eres un antiguo técnico de Caelestite?",
  ui_story_1011_10110702_43_dialog_content = "Recibido... Pregunta de análisis. Error. La directiva principal de Neural Aux es ayudar a Caelestite en todas las formas posibles.",
  ui_story_1011_10110702_44_dialog_content = "¡¿Q-Qué?! ¿Entonces los aurorianos no pueden usar las herramientas Caelestite?",
  ui_story_1011_10110702_45_dialog_content = "Recibido... Pregunta de análisis. Error. La directiva principal de Neural Aux es ayudar a Caelestite en todas las formas posibles.",
  ui_story_1011_10110702_46_dialog_content = "Oh, caramba. ¡Eso no era una pregunta!",
  ui_story_1011_10110702_47_dialog_content = "¿Alguna vez te ha dicho un auroriano que tu personalidad apesta?",
  ui_story_1011_10110702_48_dialog_content = "Cálmate, Vice. ¿Qué tal si pregunto por ti?",
  ui_story_1011_10110702_49_dialog_content = "N-Neural Aux, tengo algunas preguntas:",
  ui_story_1011_10110702_50_dialog_content = "Solicitud recibida. Modificando sistema... Ingresando el nuevo nombre del sistema: N-Neural Aux.",
  ui_story_1011_10110702_51_dialog_content = "¿Eh? ¡Esperar! ¡No! ¡Pausa! ¡Pausar entrada!",
  ui_story_1011_10110702_52_dialog_content = "Entrada en pausa.",
  ui_story_1011_10110702_53_dialog_content = "(Bueno, casi puedo concluir que incluso si se trata de una IA que quedó de la antigüedad...)",
  ui_story_1011_10110702_54_dialog_content = "(En realidad no es tan inteligente...)",
  ui_story_1011_10110702_55_dialog_content = "(Debería dividir mis preguntas para que me entienda mejor...)",
  ui_story_1011_10110702_56_dialog_content = "Ejem... Primera pregunta: Por favor, háblame de esta torre.",
  ui_story_1011_10110702_57_dialog_content = "Recibido... Analizando pregunta...",
  ui_story_1011_10110702_58_dialog_content = "Respuesta encontrada: Este es el <color=#FFB400>Obelisco del Retorno</color>.",
  ui_story_1011_10110702_59_dialog_content = "(¿Obelisco del Retorno? Eso suena como una especie de estructura de guía de navegación... como un faro).",
  ui_story_1011_10110702_60_dialog_content = "Volver... ¿Qué significa eso? ¿Soroz nos trajo aquí... para volver a este lugar?",
  ui_story_1011_10110702_61_dialog_content = "Disculpas. No sé.",
  ui_story_1011_10110702_62_dialog_content = "(¿E-Eso es todo? ¡¿Simplemente dice \"No sé\" así?!)",
  ui_story_1011_10110702_63_dialog_content = "Multa. Segunda pregunta: ¿Cómo era originalmente el interior de la torre?",
  ui_story_1011_10110702_64_dialog_content = "¿Dónde estamos en la torre?",
  ui_story_1011_10110702_65_dialog_content = "Reproducción de la grabación introductoria de Neural Aux: la unidad Neural Aux es un asistente de IA diseñado para Obelisk of Return...",
  ui_story_1011_10110702_66_dialog_content = "La unidad Neural Aux brinda asistencia a un Caelestite en función de su nivel de acceso y rango.",
  ui_story_1011_10110702_67_dialog_content = "Confirmando el nivel de acceso de Caelestite...",
  ui_story_1011_10110702_68_dialog_content = "Nivel de acceso confirmado. Neural Aux puede proporcionarle un plano del Obelisco del Retorno.",
  ui_story_1011_10110702_69_dialog_content = "(¡Eso será súper útil!)",
  ui_story_1011_10110702_70_dialog_content = "¡Excelente! ¡Ahora sí sabemos adónde vamos!",
  ui_story_1011_10110702_71_dialog_content = "Démonos prisa y encontremos el lugar para arreglar a Soroz.",
  ui_story_1011_10110702_72_dialog_content = "(Hmm... No me haré ilusiones, pero no estaría de más intentarlo...)",
  ui_story_1011_10110702_73_dialog_content = "Última pregunta: Dime cómo entrar al Sistema de Control Central.",
  ui_story_1011_10110702_74_dialog_content = "...",
  ui_story_1011_10110702_75_dialog_content = "Disculpas. No sé.",
  ui_story_1011_10110702_76_dialog_content = "Beeboo... Beeboo.... ♪",
  ui_story_1011_10110702_77_dialog_content = "(¿¡Por qué está tarareando una canción de repente!?)",
  ui_story_1011_10110702_78_dialog_content = "No importa, PlayerName. Avancemos. Esto es mejor que nada.",
  ui_story_1011_10110702_79_dialog_content = "Ahora que tenemos un mapa del lugar, confirmemos nuestra posición con Neural Aux.",
  ui_story_1011_10110702_80_dialog_content = "Buena idea. Déjame ver...",
  ui_story_1011_10110702_81_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10110702_82_dialog_content = "Ya veo. Los diferentes niveles de esta torre cumplen diferentes funciones. Todavía estamos en la región cercana al nivel de la superficie.",
  ui_story_1011_10110702_83_dialog_content = "El nivel por donde entramos a la torre era la Base de Mantenimiento Colossus.",
  ui_story_1011_10110702_84_dialog_content = "Como nos vimos a nosotros mismos, no queda mucho de eso.",
  ui_story_1011_10110702_85_dialog_content = "El nivel en el que estamos ahora es el Área Residencial de Caelestite, al igual que Vice adivinado...",
  ui_story_1011_10110702_86_dialog_content = "Ya hemos buscado en su totalidad.",
  ui_story_1011_10110702_87_dialog_content = "Desafortunadamente, hay muchas habitaciones en estos dos niveles que están bloqueadas por escombros...",
  ui_story_1011_10110702_88_dialog_content = "El almacenamiento de componentes Colossus, la sala de producción de recursos, la instalación de eliminación de desechos... Todos están prácticamente enterrados.",
  ui_story_1011_10110702_89_dialog_content = "Soroz...",
  ui_story_1011_10110702_90_dialog_content = "No te rindas todavía. Todavía tenemos tantos niveles debajo de nosotros para explorar.",
  ui_story_1011_10110702_91_dialog_content = "Tal vez estoy diciendo esto demasiado rápido, pero estamos recopilando más y más información a medida que avanzamos, ¿no es así?",
  ui_story_1011_10110702_92_dialog_content = "Sí, no te rindas, PlayerName. Encontraremos una manera.",
  ui_story_1011_10110702_93_dialog_content = "Sí, démonos prisa y pasemos al siguiente nivel.",
  ui_story_1011_10110702_94_dialog_content = "Eso sería... el <color=#FFB400>Zona de exilio</color>?",
  ui_story_1011_10110702_95_dialog_content = "¿Exiliado?",
  ui_story_1011_10110702_96_dialog_content = "No entiendo... Caelestites son una raza pacífica. ¿Por qué tendrían un área dedicada para este tipo de cosas...?",
  ui_story_1011_10110702_97_dialog_content = "Bueno, tendría sentido si se usara para contener Eclipsitas antiguas.",
  ui_story_1011_10110702_98_dialog_content = "De cualquier manera, no suena como un buen lugar para estar. Tengamos mucho cuidado.",
  ui_story_1011_10110901_1_dialog_content = "<color=#e8d9bb>Obelisco del Retorno: Zona de Exilio</color>",
  ui_story_1011_10110901_2_dialog_content = "*inhala exhala*",
  ui_story_1011_10110901_3_dialog_content = "(Saber de antemano para qué se usó este nivel me pone muy nervioso...)",
  ui_story_1011_10110901_4_dialog_content = "(¡Si algún Eclipsite decide saltar, voy a arrancar uno nuevo!)",
  ui_story_1011_10110901_5_dialog_content = "Beeboo... Beeboo.... ♪",
  ui_story_1011_10110901_6_dialog_content = "Bip bip bip... Bip bip bip... ♪",
  ui_story_1011_10110901_7_dialog_content = "\"Lo que se pierde nunca volverá. Lo que queda siempre permanecerá... ♪\"",
  ui_story_1011_10110901_8_dialog_content = "Es tan ruidoso.",
  ui_story_1011_10110901_9_dialog_content = "PlayerName, haz que lo mantenga bajo, especialmente aquí donde los eclipses podrían aparecer en cualquier momento.",
  ui_story_1011_10110901_10_dialog_content = "Déjame intentar conectarme a él...",
  ui_story_1011_10110901_11_dialog_content = "Enlace mental establecido.",
  ui_story_1011_10110901_12_dialog_content = "Neural Aux reproducirá música aleatoria cuando no se detecte ninguna amenaza.",
  ui_story_1011_10110901_13_dialog_content = "¿Estás disfrutando de esta música antigua, Caelestite?",
  ui_story_1011_10110901_14_dialog_content = "Asumiendo que estos sonidos fragmentados se supone que son \"música\"...",
  ui_story_1011_10110901_15_dialog_content = "Todos los Caelestites pueden editar la lista de reproducción de música de Neural Aux...",
  ui_story_1011_10110901_16_dialog_content = "Neural Aux también puede estudiar sus preferencias personales y realizar las modificaciones necesarias en su sistema. ¿Modificar ahora?",
  ui_story_1011_10110901_17_dialog_content = "... No, esto está bien.",
  ui_story_1011_10110901_18_dialog_content = "(Después de todo, esta música es como un eco del pasado).",
  ui_story_1011_10110901_19_dialog_content = "Sin embargo, dado que Neural Aux puede detectar si un área es segura o no...",
  ui_story_1011_10110901_20_dialog_content = "Podemos bajar la guardia y relajarnos un poco.",
  ui_story_1011_10110901_21_dialog_content = "Aun así, este nivel me hace sentir incómodo.",
  ui_story_1011_10110901_22_dialog_content = "Aquí no hay señales de vida...",
  ui_story_1011_10110901_23_dialog_content = "Pero mira la parte trasera de las puertas.",
  ui_story_1011_10110901_24_dialog_content = "¿A-Son esas marcas de garras...?",
  ui_story_1011_10110901_25_dialog_content = "Observe cómo estas habitaciones están tan apretadamente juntas. Creo que este lugar fue...",
  ui_story_1011_10110901_26_dialog_content = "Se parece a la prisión de Lumopolis.",
  ui_story_1011_10110901_27_dialog_content = "...",
  ui_story_1011_10110901_28_dialog_content = "Pero, ¿por qué se tomaron la molestia de encerrar los Eclipsites? Matarlos habría sido más fácil.",
  ui_story_1011_10110901_29_dialog_content = "¿Podría ser que los antiguos Caelestites no poseían habilidades de combate?",
  ui_story_1011_10110901_30_dialog_content = "Improbable. Incluso si no lo hicieran, por lo que hemos visto de su tecnología...",
  ui_story_1011_10110901_31_dialog_content = "Claramente tenían la capacidad de producir armas poderosas para el combate y la defensa.",
  ui_story_1011_10110901_32_dialog_content = "<color=#e8d9bb>¡Ding!</color>",
  ui_story_1011_10110901_33_dialog_content = "¿Eh?",
  ui_story_1011_10110901_34_dialog_content = "¿Pateaste algo?",
  ui_story_1011_10110901_35_dialog_content = "Déjame ver...",
  ui_story_1011_10110901_36_dialog_content = "¿Eh?",
  ui_story_1011_10110901_37_dialog_content = "¿Una placa de identificación de metal?",
  ui_story_1011_10110901_38_dialog_content = "\"Nombre: Tenoki. Identidad: Caelestite\".",
  ui_story_1011_10110901_39_dialog_content = "\"<color=#FFB400>Período de exilio</color>: 14 años.\"",
  ui_story_1011_10110901_40_dialog_content = "Aquí también hay uno. \"Nombre: Lanti. Identidad: Caelestite. Período de exilio: 12 años\".",
  ui_story_1011_10110901_41_dialog_content = "Estas celdas tenían a Caeleistes como tú, PlayerName.",
  ui_story_1011_10110901_42_dialog_content = "¡¿Lo que significa que este lugar es en realidad la Zona de Exilio de Caelestite?!",
  ui_story_1011_10110901_43_dialog_content = "Pero... ¿por qué encerrarían a su propia gente?",
  ui_story_1011_10110901_44_dialog_content = "¡¿La idea de Caelestites \"amantes de la paz\" siempre fue solo una suposición inexacta?!",
  ui_story_1011_10110901_45_dialog_content = "Cálmate, PlayerName. No tenemos nada concluyente en este momento.",
  ui_story_1011_10110901_46_dialog_content = "Piénsalo. Si los antiguos Caelestitas fueran un gran grupo...",
  ui_story_1011_10110901_47_dialog_content = "Hubiera existido la necesidad de hacer cumplir el orden de una forma u otra.",
  ui_story_1011_10110901_48_dialog_content = "Incluso si eso es cierto, Caelestites puede lograrlo a través de nuestro vínculo mental.",
  ui_story_1011_10110901_49_dialog_content = "No tiene sentido condenarlos a largos años en el exilio.",
  ui_story_1011_10110901_50_dialog_content = "Neural Aux, por favor respóndeme.",
  ui_story_1011_10110901_51_dialog_content = "Recibido... Analizando pregunta... Palabra clave obtenida. Responder-",
  ui_story_1011_10110901_52_dialog_content = "<color=#FFB400>maestro francisco</color> dijo una vez: \"A partir de ese momento, dejamos de ser sus parientes\".",
  ui_story_1011_10110901_53_dialog_content = "¡¿?!",
  ui_story_1011_10110901_54_dialog_content = "¿Qué significa \"dejó de ser su pariente\"?",
  ui_story_1011_10110901_55_dialog_content = "¿De quién?",
  ui_story_1011_10110901_56_dialog_content = "¿Estaban los Caelestitas divididos por algunos <color=#FFB400>conflicto interno irreconciliable</color> ¿hace miles de años?",
  ui_story_1011_10110901_57_dialog_content = "(¿Fue este el comienzo de su guerra civil?)",
  ui_story_1011_10110901_57X1_dialog_content = "Recibido... Analizando pregunta...",
  ui_story_1011_10110901_57X2_dialog_content = "Según los datos que tenemos, la mayoría de Caelestites no estaban en buenos términos con el Maestro Francis.",
  ui_story_1011_10110901_57X3_dialog_content = "De hecho, sirvió en la Zona de Exilio.",
  ui_story_1011_10110901_57X3X1_dialog_content = "Por cierto, esta área fue utilizada como prisión para los herejes caelestitas.",
  ui_story_1011_10110901_57X3X2_dialog_content = "El maestro Francis y los investigadores bajo su mando fueron todos exiliados por la misma razón...",
  ui_story_1011_10110901_57X3X3_dialog_content = "Fueron acusados de incitar al libre pensamiento y difundir ideas progresistas.",
  ui_story_1011_10110901_57X4_dialog_content = "Todas las palabras que se encuentran en asociación con Francisco son bastante negativas. Incluyen lo siguiente:",
  ui_story_1011_10110901_57X5_dialog_content = "Friki, lunático, experto en control mental, coleccionista de cerebros...",
  ui_story_1011_10110901_57X6_dialog_content = "Derecha, PlayerName, Creo que podemos dejar que se detenga ahora...",
  ui_story_1011_10110901_57X7_dialog_content = "Suena como si fuera un... ¿investigador inusual?",
  ui_story_1011_10110901_57X8_dialog_content = "El maestro Francis se dedicó a los estudios de las nuevas tecnologías.",
  ui_story_1011_10110901_57X9_dialog_content = "Siempre decía: \"La investigación es un camino arduo y lleno de obstáculos. Ser incomprendido es un lugar común\".",
  ui_story_1011_10110901_57X10_dialog_content = "El maestro Francis también fue la mente detrás de otra gran innovación.",
  ui_story_1011_10110901_57X11_dialog_content = "Caelestite, a juzgar por la identidad de tus compañeros, cambió el mundo.",
  ui_story_1011_10110901_57X12_dialog_content = "¿Cambió el mundo?",
  ui_story_1011_10110901_57X13_dialog_content = "Los Caelestitas modernos muestran un cambio evidente de postura y constitución en comparación con los Caelestitas antiguos.",
  ui_story_1011_10110901_57X14_dialog_content = "Incluso has llegado a compartir un enemigo común con los aurorianos y los semihumanos.",
  ui_story_1011_10110901_57X15_dialog_content = "El maestro Francis habría estado complacido.",
  ui_story_1011_10110901_57X16_dialog_content = "¿Un \"cambio de postura\"? Entonces... ¿qué postura tenían los antiguos Caelestitas?",
  ui_story_1011_10110901_57X17_dialog_content = "¿Cuál es esa gran innovación a la que te refieres?",
  ui_story_1011_10110901_58_dialog_content = "Confirmando el nivel de acceso de Caelestite...",
  ui_story_1011_10110901_59_dialog_content = "Nivel de acceso insuficiente. Lo siento, no puedo responder a tu pregunta.",
  ui_story_1011_10110901_60_dialog_content = "Multa. Preguntaré algo más entonces.",
  ui_story_1011_10110901_61_dialog_content = "Volvamos a esta afirmación...",
  ui_story_1011_10110901_61X1_dialog_content = "\"A partir de ese momento, ya no somos sus parientes\".",
  ui_story_1011_10110901_63_dialog_content = "¿Se refería a Caelestites cuando dijo \"nosotros\"?",
  ui_story_1011_10110901_64_dialog_content = "Respuesta: \"Nosotros\" somos Caelestitas.",
  ui_story_1011_10110901_65_dialog_content = "...",
  ui_story_1011_10110901_66_dialog_content = "Error. ¡Error! Neural Aux no es una Caelestita.",
  ui_story_1011_10110901_67_dialog_content = "Reproducción de la grabación introductoria de Neural Aux: la unidad Neural Aux es un asistente de IA diseñado para Obelisk of Return...",
  ui_story_1011_10110901_68_dialog_content = "¡Escúchame! ¡Nadie aquí piensa que eres un caelestita!",
  ui_story_1011_10110901_69_dialog_content = "La unidad Neural Aux brinda asistencia a un Caelestite en función de su nivel de acceso y rango.",
  ui_story_1011_10110901_70_dialog_content = "Olvídalo. He tenido suficiente...",
  ui_story_1011_10110901_71_dialog_content = "¿Francisco?",
  ui_story_1011_10110901_72_dialog_content = "PlayerName, ¿recuerdas la taza que vimos en el nivel de arriba?",
  ui_story_1011_10110901_73_dialog_content = "Ahora que lo mencionas, el tallado borroso en el fondo de la copa parece haber dicho...",
  ui_story_1011_10110901_74_dialog_content = "¿Era eso... la copa de Francis...?",
  ui_story_1011_10110901_75_dialog_content = "Recibido... Analizando pregunta... Respuesta encontrada: Al Maestro Francis le encantaba consumir bebidas energéticas.",
  ui_story_1011_10110901_76_dialog_content = "Siempre se le veía con su copa en la mano.",
  ui_story_1011_10110901_77_dialog_content = "(Así que acertamos...)",
  ui_story_1011_10110901_78_dialog_content = "Reproducción de la grabación introductoria de bebidas energéticas: Las bebidas energéticas son exclusivas del Obelisco del Retorno. Proporciona-",
  ui_story_1011_10110901_79_dialog_content = "(¡Realmente no necesitamos información irrelevante como esa!)",
  ui_story_1011_10110901_80_dialog_content = "Está disponible en el área residencial de Caelestite, sala de producción de recursos, zona de exilio...",
  ui_story_1011_10110901_81_dialog_content = "Se pueden comprar directamente en las máquinas expendedoras de suministros en los lugares mencionados.",
  ui_story_1011_10110901_82_dialog_content = "(¿Máquinas expendedoras?)",
  ui_story_1011_10110901_83_dialog_content = "(¡Mi corazonada era correcta, entonces!)",
  ui_story_1011_10110901_84_dialog_content = "PlayerName, Carleen, ¡sígueme!",
  ui_story_1011_10110901_85_dialog_content = "<color=#e8d9bb>Obelisk of Return: Exile Zone - Máquina expendedora de suministros</color>",
  ui_story_1011_10110901_86_dialog_content = "<color=#e8d9bb>Clank... ¡Bang!</color>",
  ui_story_1011_10110901_87_dialog_content = "¡Guau... increíble! ¡Todo lo que se necesitó fueron algunas patadas para que volviera a funcionar!",
  ui_story_1011_10110901_88_dialog_content = "¿Es esta la máquina expendedora que mencionó Neural Aux?",
  ui_story_1011_10110901_89_dialog_content = "Este tipo de objeto... parece familiar.",
  ui_story_1011_10110901_90_dialog_content = "Sí... La IA y las máquinas expendedoras parecen ser una configuración estándar para ruinas subterráneas o algo así...",
  ui_story_1011_10110901_91_dialog_content = "¡Decir ah! Ustedes dos, solo miren y aprendan.",
  ui_story_1011_10110901_92_dialog_content = "Mmm... ¡Aquí vamos!",
  ui_story_1011_10110901_93_dialog_content = "¿Eh? ¡¿Los trajiste contigo?!",
  ui_story_1011_10110901_94_dialog_content = "Bueno, quería probar mi teoría.",
  ui_story_1011_10110901_95_dialog_content = "Cuando vi la forma de la concha y como tenía líquido adentro, comencé a preguntarme...",
  ui_story_1011_10110901_96_dialog_content = "Los Caelestitas tenían vasos para contener agua potable, y tampoco consumían mariscos y cosas por el estilo.",
  ui_story_1011_10110901_97_dialog_content = "Entonces, ¿qué estaban haciendo con estas cosas?",
  ui_story_1011_10110901_98_dialog_content = "Pero ahora estoy bastante seguro de para qué servían... Mira:",
  ui_story_1011_10110901_99_dialog_content = "Si vierto este líquido del caparazón del nautilus en este agujero de la máquina expendedora...",
  ui_story_1011_10110901_100_dialog_content = "<color=#e8d9bb>¡Timbre! ¡Estallido!</color>",
  ui_story_1011_10110901_101_dialog_content = "¡Funcionó!",
  ui_story_1011_10110901_102_dialog_content = "¡Tada! Una bebida energética para llevar. Ha caducado hace mucho tiempo, pero de todos modos.",
  ui_story_1011_10110901_103_dialog_content = "¡¿Cómo se te ocurrió esto?!",
  ui_story_1011_10110901_104_dialog_content = "Tuve una corazonada cuando vi por primera vez esas conchas.",
  ui_story_1011_10110901_105_dialog_content = "Verás, la espiral de una concha de nautilus en realidad significa algo.",
  ui_story_1011_10110901_106_dialog_content = "Es un concepto matemático que se encuentra en la naturaleza.",
  ui_story_1011_10110901_107_dialog_content = "Naturaleza...? no lo entiendo ¿Qué tiene que ver la espiral con la naturaleza?",
  ui_story_1011_10110901_108_dialog_content = "¿No son las cosas de la naturaleza como los árboles y las flores?",
  ui_story_1011_10110901_109_dialog_content = "Tienes razón, los árboles y las flores son parte de la naturaleza.",
  ui_story_1011_10110901_110_dialog_content = "Pero estos conceptos son el fundamento de la naturaleza.",
  ui_story_1011_10110901_111_dialog_content = "Las espirales de concha Nautilus simbolizan el curso natural de las cosas.",
  ui_story_1011_10110901_112_dialog_content = "O simplemente puede llamarlo \"continuidad\".",
  ui_story_1011_10110901_113_dialog_content = "¿Continuidad?",
  ui_story_1011_10110901_114_dialog_content = "Sí. Tome un retoño, por ejemplo. No se convierte en un árbol instantáneamente.",
  ui_story_1011_10110901_115_dialog_content = "Crece continuamente cada segundo de cada minuto.",
  ui_story_1011_10110901_116_dialog_content = "Y \"continuidad\" se refiere a esta evolución.",
  ui_story_1011_10110901_117_dialog_content = "Bien, lo entiendo ahora... ¿Creo?",
  ui_story_1011_10110901_118_dialog_content = "Ahora bien, dado que las antiguas matemáticas caelestitas se fundaron a partir del concepto de \"continuidad\"...",
  ui_story_1011_10110901_119_dialog_content = "Supuse que su forma de vida habría sido muy diferente a la nuestra.",
  ui_story_1011_10110901_120_dialog_content = "Un ejemplo obvio sería la moneda.",
  ui_story_1011_10110901_121_dialog_content = "¡Vaya! Estás diciendo que nuestra moneda, ya sean monedas o billetes, no son \"continuas\", ¿correcto?",
  ui_story_1011_10110901_122_dialog_content = "Así es. En cuanto a su forma de moneda, bueno, se nota al observar la concha de nautilus.",
  ui_story_1011_10110901_123_dialog_content = "Era... ¿líquido?",
  ui_story_1011_10110901_124_dialog_content = "Ya veo. ¿Entonces estas conchas de nautilus sirvieron como billeteras?",
  ui_story_1011_10110901_125_dialog_content = "Recibido... Pregunta de análisis... Respuesta: La concha es un recipiente de moneda.",
  ui_story_1011_10110901_126_dialog_content = "El volumen líquido era la métrica utilizada para el valor de un artículo en el Obelisco del Retorno.",
  ui_story_1011_10110901_127_dialog_content = "Las transacciones involucraron el intercambio de varias cantidades de líquido entre las conchas.",
  ui_story_1011_10110901_128_dialog_content = "Ya veo. Quiero decir, esta no es mi área de especialización...",
  ui_story_1011_10110901_129_dialog_content = "Pero suena como si fuera un bonito sistema de sonido.",
  ui_story_1011_10110901_130_dialog_content = "Adorando la naturaleza, buscando la continuidad...",
  ui_story_1011_10110901_131_dialog_content = "Encaja con la imagen general de los Caelestites.",
  ui_story_1011_10110901_132_dialog_content = "Eres increíble, Vice. ¡Tu suposición coincidió con la explicación de Neural Aux palabra por palabra!",
  ui_story_1011_10110901_133_dialog_content = "N-No es tan impresionante...",
  ui_story_1011_10110901_134_dialog_content = "Avancemos.",
  ui_story_1011_10110901_135_dialog_content = "Pero no hay escaleras que conduzcan más abajo.",
  ui_story_1011_10110901_136_dialog_content = "¿Está la Zona de Exilio en la parte inferior de la torre?",
  ui_story_1011_10110901_137_dialog_content = "No me parece. El mapa de Neural Aux muestra que la Zona de Exilio está situada en el medio.",
  ui_story_1011_10110901_138_dialog_content = "Neural Aux, ¿cómo llegamos al siguiente nivel?",
  ui_story_1011_10110901_139_dialog_content = "Recibido... Analizando pregunta... Respuesta: El pasaje al siguiente nivel se ha derrumbado.",
  ui_story_1011_10110901_140_dialog_content = "Si estás decidido a alcanzarlo...",
  ui_story_1011_10110901_141_dialog_content = "Continúe a través de la grieta entre las dos máquinas expendedoras detrás de usted.",
  ui_story_1011_10110901_142_dialog_content = "<color=#e8d9bb>Obelisco del Retorno: Grieta</color>",
  ui_story_1011_10110901_143_dialog_content = "Ugh... Está tan oscuro y apretado aquí. Es mucho más angosto que el pasaje por donde entramos.",
  ui_story_1011_10110901_144_dialog_content = "Apenas puedo moverme también.",
  ui_story_1011_10110901_145_dialog_content = "(Espero que no provoquemos otro colapso al forzar nuestro paso por aquí...)",
  ui_story_1011_10110901_146_dialog_content = "Vamos a prisa, PlayerName.",
  ui_story_1011_10110901_147_dialog_content = "R-Correcto...",
  ui_story_1011_10110901_148_dialog_content = "¡Bip!",
  ui_story_1011_10110901_149_dialog_content = "Advertencia: forma de vida detectada 50 metros más adelante.",
  ui_story_1011_10110901_150_dialog_content = "Advertencia: Forma de vida acercándose. 50 metros adelante.",
  ui_story_1011_10110901_151_dialog_content = "¿¡Q-Qué!? Pero literalmente no hay a dónde acudir...",
  ui_story_1011_10110901_152_dialog_content = "¿Hay eclipses primordiales aquí?",
  ui_story_1011_10110901_153_dialog_content = "Advertencia: Forma de vida acercándose. 40 metros adelante.",
  ui_story_1011_10110901_154_dialog_content = "Advertencia: 30 metros...",
  ui_story_1011_10110901_155_dialog_content = "PlayerName, ¡piensa en algo!",
  ui_story_1011_10110901_156_dialog_content = "Advertencia: forma de vida detectada 10 metros más adelante. Confirmando identidad...",
  ui_story_1011_10110901_157_dialog_content = "No siento nada. No es una Caelestita.",
  ui_story_1011_10110901_158_dialog_content = "Todos, prepárense para pelear.",
  ui_story_1011_10110901_159_dialog_content = "Identidad confirmada: Eclipsite.",
  ui_story_1011_10110901_160_dialog_content = "gaar...",
  ui_story_1011_10110901_161_dialog_content = "Rugido... ¡¡¡Rugido!!!",
  ui_story_1011_10110901_162_dialog_content = "¡Cuidado con el terreno y ten cuidado!",
  ui_story_1011_10110902_1_dialog_content = "Rugido...",
  ui_story_1011_10110902_2_dialog_content = "Deberíamos haber prestado más atención.",
  ui_story_1011_10110902_3_dialog_content = "Hay rastros de lucha esparcidos por todo este lugar. Deberíamos haber estado en guardia.",
  ui_story_1011_10110902_4_dialog_content = "Después de todo, este es un pasadizo secreto hacia la Zona de Exilio. No es de extrañar que haya peligro al acecho.",
  ui_story_1011_10110902_5_dialog_content = "Es demasiado tarde para dar marcha atrás ahora.",
  ui_story_1011_10110902_6_dialog_content = "(Si estos son <color=#FFB400>rastros de lucha</color>...)",
  ui_story_1011_10110902_7_dialog_content = "Neural Aux, escanea las huellas en el suelo y dame un análisis completo.",
  ui_story_1011_10110902_8_dialog_content = "Recibió. Activando escaneo...",
  ui_story_1011_10110902_9_dialog_content = "Comparando resultados con la base de datos...",
  ui_story_1011_10110902_10_dialog_content = "Escaneo completo.",
  ui_story_1011_10110902_11_dialog_content = "¿Entonces?",
  ui_story_1011_10110902_12_dialog_content = "Generando informe. Los hallazgos iniciales sugieren que aquí tuvo lugar una batalla entre Caelestites y Eclipsites.",
  ui_story_1011_10110902_13_dialog_content = "El análisis muestra rastros de 200 restos de Eclipsite de bajo nivel y 40 restos de Caelestite dentro de la muestra de suelo.",
  ui_story_1011_10110902_14_dialog_content = "Hmm...",
  ui_story_1011_10110902_15_dialog_content = "16 placas de identificación Caelestite y 2 Caelestite <color=#FFB400>armas</color> se encuentran 10 metros adelante.",
  ui_story_1011_10110902_16_dialog_content = "¿¡Armas!?",
  ui_story_1011_10110902_17_dialog_content = "Neural Aux tiene razón. Mira esto.",
  ui_story_1011_10110902_18_dialog_content = "Hay dos armas aquí al lado de las rocas caídas, se ven prístinas.",
  ui_story_1011_10110902_19_dialog_content = "Generando informe complementario...",
  ui_story_1011_10110902_20_dialog_content = "Corrección de resultados: 1 arma Caelestite. Falta el clip de energía de la segunda pistola.",
  ui_story_1011_10110902_21_dialog_content = "Aquí está.",
  ui_story_1011_10110902_22_dialog_content = "Es sorprendentemente ligero y compacto.",
  ui_story_1011_10110902_23_dialog_content = "Entonces... ¿el... \"cargador de energía\" de esta pistola está cargado y funciona?",
  ui_story_1011_10110902_24_dialog_content = "Recibido... Analizando la pregunta... Reproduciendo la grabación introductoria de Laser Gun...",
  ui_story_1011_10110902_25_dialog_content = "Nombre del arma: Pistola láser. Inventor: Maestro Francisco.",
  ui_story_1011_10110902_26_dialog_content = "Habilidad especial: <color=#FFB400>Ataque de eclipse</color>. Usabilidad: Todos los Caelestites.",
  ui_story_1011_10110902_27_dialog_content = "Tutorial: Cree un enlace mental con la pistola láser para tomar represalias efectivas contra todos los pequeños ataques de Eclipsite.",
  ui_story_1011_10110902_28_dialog_content = "(¡Esto es increíble! ¡Es casi como una versión de IA de un arma de fuego!)",
  ui_story_1011_10110902_29_dialog_content = "¿Eh?",
  ui_story_1011_10110902_30_dialog_content = "Hay marcas irregulares a lo largo del mango.",
  ui_story_1011_10110902_31_dialog_content = "Información complementaria: esta arma pertenecía al maestro Francis.",
  ui_story_1011_10110902_32_dialog_content = "¿E-Ese tipo otra vez?",
  ui_story_1011_10110902_33_dialog_content = "(Por la información que hemos recopilado, este maestro Francis parece ser un personaje impresionante).",
  ui_story_1011_10110902_34_dialog_content = "Advertencia: Forma de vida acercándose por detrás. 50 metros",
  ui_story_1011_10110902_35_dialog_content = "¿Es eso así? Tiempo perfecto.",
  ui_story_1011_10110902_36_dialog_content = "Es hora de darle una oportunidad a esa arma, PlayerName. Carleen y cuidaré tu espalda.",
  ui_story_1011_10110902_37_dialog_content = "¡Está bien!",
  ui_story_1011_10110902_38_dialog_content = "(Golpe... Golpe...)",
  ui_story_1011_10110902_39_dialog_content = "(He comandado innumerables batallas, pero es angustioso estar a la cabeza).",
  ui_story_1011_10110902_40_dialog_content = "Gah...",
  ui_story_1011_10110902_41_dialog_content = "¡Graaagh!",
  ui_story_1011_10110902_42_dialog_content = "(¡Ahora!)",
  ui_story_1011_10110902_43_dialog_content = "<color=#e8d9bb>¡Bang! ¡Bang!</color>",
  ui_story_1011_10110902_44_dialog_content = "gaar...",
  ui_story_1011_10110902_45_dialog_content = "¡Funcionó!",
  ui_story_1011_10110902_46_dialog_content = "No fue letal, ¡pero noqueó por completo al Eclipsite!",
  ui_story_1011_10110902_47_dialog_content = "¡Un solo disparo! ¡Esta cosa es tan efectiva!",
  ui_story_1011_10110902_48_dialog_content = "PlayerName, Estoy impresionado de que tus manos ni siquiera temblaran.",
  ui_story_1011_10110902_49_dialog_content = "G-Gracias por el cumplido!",
  ui_story_1011_10110902_50_dialog_content = "De todos modos, con esta pistola láser, estamos mucho mejor de lo que estábamos.",
  ui_story_1011_10110902_51_dialog_content = "Avancemos.",
  ui_story_1011_10111001_1_dialog_content = "¡Graaagh!",
  ui_story_1011_10111001_2_dialog_content = "¡Rugido!",
  ui_story_1011_10111001_3_dialog_content = "¡Grrr!",
  ui_story_1011_10111001_4_dialog_content = "<color=#e8d9bb>¡Estallido! ¡Estallido! ¡Estallido!</color>",
  ui_story_1011_10111001_5_dialog_content = "Estás bastante acostumbrado a combatir ahora, PlayerName...",
  ui_story_1011_10111001_6_dialog_content = "A pesar de tener un arma poderosa como esta, su número sigue siendo desalentador...",
  ui_story_1011_10111001_7_dialog_content = "¿Cómo demonios llegaron aquí estos eclipses?",
  ui_story_1011_10111001_8_dialog_content = "(¿Podrían haberse originado aquí...?)",
  ui_story_1011_10111001_9_dialog_content = "Y extrañamente, todos van en la misma dirección.",
  ui_story_1011_10111001_10_dialog_content = "Dado que los eclipses no tienen mente propia, deben estar reaccionando a una invocación, ¿verdad?",
  ui_story_1011_10111001_11_dialog_content = "(¿Una convocatoria?)",
  ui_story_1011_10111001_12_dialog_content = "(¿Podría ser el Eclipse o...?)",
  ui_story_1011_10111001_13_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_1011_10111001_14_dialog_content = "Oh no...",
  ui_story_1011_10111001_15_dialog_content = "¡Algo se está acercando a nosotros, rápido!",
  ui_story_1011_10111001_16_dialog_content = "¡Así que realmente hay un líder entre ellos!",
  ui_story_1011_10111001_17_dialog_content = "¡Advertencia! Forma de vida por delante. 30, 20, 10 metros!",
  ui_story_1011_10111001_18_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_1011_10111001_19_dialog_content = "¡Rooooooor!",
  ui_story_1011_10111001_20_dialog_content = "Rugido...",
  ui_story_1011_10111001_21_dialog_content = "¡¿No es ese el Eclipsite de antes?!",
  ui_story_1011_10111001_22_dialog_content = "¿No lo sacamos ya? ¿Cómo podría ser tan resistente...",
  ui_story_1011_10111001_23_dialog_content = "Carleen, Vice, ¡un paso atrás!",
  ui_story_1011_10111001_24_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_1011_10111001_25_dialog_content = "*jadeo*",
  ui_story_1011_10111001_26_dialog_content = "Gracias a Dios que tengo esta pistola...",
  ui_story_1011_10111001_27_dialog_content = "gaar...",
  ui_story_1011_10111001_28_dialog_content = "¡Rugido!",
  ui_story_1011_10111001_29_dialog_content = "¿¡Qué!?",
  ui_story_1011_10111001_30_dialog_content = "¿¡No está afectado!?",
  ui_story_1011_10111001_31_dialog_content = "¡Rugido!",
  ui_story_1011_10111001_32_dialog_content = "PlayerName, ¡deja de distraerte! ¡Correr!",
  ui_story_1011_10111001_33_dialog_content = "F-Adelante? Pero... Pero ni siquiera sabemos qué hay más adelante—",
  ui_story_1011_10111001_34_dialog_content = "¡Olvida eso!",
  ui_story_1011_10111001_35_dialog_content = "Neural Aux, activa el sistema de alerta!",
  ui_story_1011_10111001_36_dialog_content = "Recibió. Sistema de alerta activado manualmente. Advertencia: forma de vida detectada a 5 metros en la parte trasera.",
  ui_story_1011_10111001_37_dialog_content = "Advertencia: forma de vida detectada a 10 metros en la parte trasera.",
  ui_story_1011_10111001_38_dialog_content = "Advertencia: forma de vida detectada. 15 metros en la parte trasera. Cerrando en...",
  ui_story_1011_10111001_39_dialog_content = "Advertencia: forma de vida detectada. 10 metros en la parte trasera. Cerrando en...",
  ui_story_1011_10111001_40_dialog_content = "Huff huff... ¡No estamos poniendo distancia entre nosotros en absoluto!",
  ui_story_1011_10111001_41_dialog_content = "Ponerse al día, PlayerName!",
  ui_story_1011_10111001_42_dialog_content = "¡Yo sé!",
  ui_story_1011_10111001_43_dialog_content = "Advertencia: forma de signo de vida. 30 metros en la parte trasera. Cerrando en...",
  ui_story_1011_10111001_44_dialog_content = "¡No te detengas!",
  ui_story_1011_10111001_45_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_1011_10111001_46_dialog_content = "¡Ay! Eso duele...",
  ui_story_1011_10111001_47_dialog_content = "¿Mmm? ¿Qué es esto?",
  ui_story_1011_10111001_48_dialog_content = "¿Eh?",
  ui_story_1011_10111001_49_dialog_content = "Vice? ¿Qué sucedió?",
  ui_story_1011_10111001_50_dialog_content = "¡Eso fue doloroso! ¡¿Qué es un dispositivo como este sentado en medio de un túnel estrecho?!",
  ui_story_1011_10111001_51_dialog_content = "Parece una especie de panel de control y su apariencia es similar a Neural Aux...",
  ui_story_1011_10111001_52_dialog_content = "Pero independientemente, ¿qué está haciendo en medio de un túnel?",
  ui_story_1011_10111001_53_dialog_content = "En realidad... tal vez podamos hacer uso de ella.",
  ui_story_1011_10111001_54_dialog_content = "Advertencia: forma de vida detectada. 25 metros en la parte trasera.",
  ui_story_1011_10111001_55_dialog_content = "Neural Aux, ¡díganos cómo funciona este dispositivo!",
  ui_story_1011_10111001_56_dialog_content = "Neural Aux en modo de alerta manual. No se puede cambiar de modo en este momento.",
  ui_story_1011_10111001_57_dialog_content = "Advertencia: forma de vida detectada. 10 metros en la parte trasera.",
  ui_story_1011_10111001_58_dialog_content = "Sabes qué, esto se parece a los dispositivos de control usados para las armas de Illumina.",
  ui_story_1011_10111001_59_dialog_content = "¡También podría darle una oportunidad!",
  ui_story_1011_10111001_60_dialog_content = "PlayerName, ven ayúdame a verificar con tu identidad!",
  ui_story_1011_10111001_61_dialog_content = "¡Te lo dejo a ti entonces!",
  ui_story_1011_10111001_62_option_content = "¡Control forzado!",
  ui_story_1011_10111001_63_dialog_content = "Ahora... Primero, cierre la puerta de bloqueo y active el dispositivo...",
  ui_story_1011_10111001_64_dialog_content = "Y luego.",
  ui_story_1011_10111001_65_dialog_content = "¡Esto debería mostrar los eclipses!",
  ui_story_1011_10111001_66_dialog_content = "<color=#e8d9bb>¡Banco de iglesia! ¡Tortazo!</color>",
  ui_story_1011_10111001_67_dialog_content = "(¿Está... enfocando su ataque en los Eclipsites?)",
  ui_story_1011_10111001_68_dialog_content = "¡Rugido!",
  ui_story_1011_10111001_69_dialog_content = "gaar...",
  ui_story_1011_10111001_70_dialog_content = "(¡Qué poderoso!)",
  ui_story_1011_10111001_71_dialog_content = "Increíble...! PlayerName¡Parece tan efectivo contra los Eclipsites como tu arma!",
  ui_story_1011_10111001_72_dialog_content = "No. ¡Es mucho mejor que el arma!",
  ui_story_1011_10111001_73_dialog_content = "¡Rugido!",
  ui_story_1011_10111001_74_dialog_content = "¡Gahhhhhh!",
  ui_story_1011_10111001_75_dialog_content = "¡Rugido!",
  ui_story_1011_10111001_76_dialog_content = "(¿Por qué los Eclipsites están tan irritados por su muerte?)",
  ui_story_1011_10111001_77_dialog_content = "Vice, ¡Cuidado!",
  ui_story_1011_10111001_78_dialog_content = "¡Dispersión, pétalos de hielo!",
  ui_story_1011_10111001_79_dialog_content = "¡Uh!",
  ui_story_1011_10111001_80_dialog_content = "Vice¡No intentes jugar al héroe! ¡Volver!",
  ui_story_1011_10111001_81_dialog_content = "(Ya llegamos hasta aquí, y tenemos un arma poderosa como esta aquí con nosotros...)",
  ui_story_1011_10111001_82_dialog_content = "(Mantenga la calma. Debe haber una manera.)",
  ui_story_1011_10111001_83_dialog_content = "(¡Eso es todo! <color=#FFB400>Orden de matar de rango completo</color>!)",
  ui_story_1011_10111001_84_dialog_content = "<color=#e8d9bb>Bip, bip, bip, bip... ¡Bang!</color>",
  ui_story_1011_10111001_85_dialog_content = "<color=#e8d9bb>¡Pam! ¡Auge!</color>",
  ui_story_1011_10111001_86_dialog_content = "*jadeando*...Vice?",
  ui_story_1011_10111001_87_dialog_content = "Vice!",
  ui_story_1011_10111001_88_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10111001_89_dialog_content = "V-Vice!",
  ui_story_1011_10111001_90_dialog_content = "(De ninguna manera... Nuestro vínculo sigue intacto. ¡Ella tiene que estar bien!)",
  ui_story_1011_10111001_91_dialog_content = "Vice!",
  ui_story_1011_10111001_92_dialog_content = "*tos, tos* ¡Estoy justo aquí! PlayerName, Carleen!",
  ui_story_1011_10111001_93_dialog_content = "¡Gracias a dios!",
  ui_story_1011_10111001_94_dialog_content = "Vice! Me asustaste. Pensé que eras...",
  ui_story_1011_10111001_95_dialog_content = "<color=#e8d9bb>Bip, bip, bip, bip...</color>",
  ui_story_1011_10111001_96_dialog_content = "¿Eh?",
  ui_story_1011_10111001_97_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1011_10111001_98_dialog_content = "Qué—",
  ui_story_1011_10111001_99_dialog_content = "<color=#e8d9bb>Bip, bip, bip, bip...</color>",
  ui_story_1011_10111001_100_dialog_content = "No hay objetivos restantes. Orden de matar a distancia completa completa.",
  ui_story_1011_10111001_101_dialog_content = "P-Por qué...",
  ui_story_1011_10111001_102_dialog_content = "Cómo...",
  ui_story_1011_10111001_103_dialog_content = "<size=50>Vice!</size>",
  ui_story_1011_10111001_104_dialog_content = "Vice... Vice!",
  ui_story_1011_10111001_105_dialog_content = "(¡No!)",
  ui_story_1011_10111001_106_dialog_content = "Carleen! ¡Quedarse atrás!",
  ui_story_1011_10111001_107_dialog_content = "¡Hay algo mal con la máquina! ¡Que no te detecte!",
  ui_story_1011_10111001_108_option_content = "¡Corta el enlace!",
  ui_story_1011_10111001_109_option_content = "¿Cortar el enlace...?",
  ui_story_1011_10111001_110_dialog_content = "(¡Maldita sea! ¡El dispositivo no responde!)",
  ui_story_1011_10111001_111_dialog_content = "Carleen, ¡mantente oculto!",
  ui_story_1011_10111001_112_dialog_content = "¡Entendido!",
  ui_story_1011_10111001_113_dialog_content = "<color=#e8d9bb>Bip, bip, bip, bip...</color>",
  ui_story_1011_10111001_114_dialog_content = "¿Mmm?",
  ui_story_1011_10111001_115_dialog_content = "(¡¿Todavía logró detectarme?!)",
  ui_story_1011_10111001_116_dialog_content = "(Me pregunto si mi Moon Cocoon puede protegerse contra—)",
  ui_story_1011_10111001_117_dialog_content = "¡Rugido!",
  ui_story_1011_10111001_118_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1011_10111001_119_dialog_content = "(¡¿Cómo hay más eclipses?!)",
  ui_story_1011_10111001_120_option_content = "¡Corta el enlace!",
  ui_story_1011_10111001_121_dialog_content = "<color=#e8d9bb>Crujido...</color>",
  ui_story_1011_10111001_122_dialog_content = "(¡Finalmente, se apaga!)",
  ui_story_1011_10111001_123_dialog_content = "PlayerName, ocúpate primero de los Eclipsites. No dejes que lleguen a Vice!",
  ui_story_1011_10111001_124_dialog_content = "No sabemos su condición. ¡No podemos permitirnos perder más tiempo!",
  ui_story_1011_10111002_1_dialog_content = "Buscando formas de vida...",
  ui_story_1011_10111002_2_dialog_content = "Resultado de escaneo generado...",
  ui_story_1011_10111002_3_dialog_content = "Estado físico de la forma de vida: No se detectan latidos del corazón. Sin señales activas de vida.",
  ui_story_1011_10111002_4_dialog_content = "Informe de forma de vida: <color=#FFB400>Hibernación</color> estado confirmado.",
  ui_story_1011_10111002_5_dialog_content = "¿Hibernación?",
  ui_story_1011_10111002_6_dialog_content = "Cálmate, PlayerName.",
  ui_story_1011_10111002_7_dialog_content = "Tenemos que averiguar cómo llegar Vice fuera de su estado actual.",
  ui_story_1011_10111002_8_dialog_content = "Yo sé...",
  ui_story_1011_10111002_9_dialog_content = "Yo... soy el único capaz de comunicarse con Neural Aux de todos modos.",
  ui_story_1011_10111002_17_option_content = "¿Hibernación?",
  ui_story_1011_10111002_18_dialog_content = "Las formas de vida golpeadas por el atacante especial entrarán en hibernación.",
  ui_story_1011_10111002_19_dialog_content = "Los aurorianos que hayan entrado en ese estado de hibernación caerán en coma.",
  ui_story_1011_10111002_20_dialog_content = "¿Una coma?",
  ui_story_1011_10111002_21_dialog_content = "Lo que significa que todo lo que tenemos que hacer es despertar Vice ¡arriba!",
  ui_story_1011_10111002_22_dialog_content = "Cuénteme más sobre este estado de hibernación y cómo deshacerse de él.",
  ui_story_1011_10111002_23_dialog_content = "Recibido... Analizando pregunta...",
  ui_story_1011_10111002_24_dialog_content = "Respuesta encontrada: el estado de hibernación no es un coma regular.",
  ui_story_1011_10111002_25_dialog_content = "El latido del corazón y la respiración de un auroriano en hibernación se suspenderán indefinidamente.",
  ui_story_1011_10111002_26_dialog_content = "Lo mismo ocurre con la energía lumínica dentro de su cuerpo.",
  ui_story_1011_10111002_27_dialog_content = "Buscando cómo finalizar la hibernación...",
  ui_story_1011_10111002_28_dialog_content = "Lo siento. Búsqueda fallida. No sé.",
  ui_story_1011_10111002_29_dialog_content = "¿Qué quieres decir con que la búsqueda falló?",
  ui_story_1011_10111002_30_dialog_content = "No soy capaz de darte una solución.",
  ui_story_1011_10111002_31_dialog_content = "¡¿Qué?!",
  ui_story_1011_10111002_32_dialog_content = "Entonces eso no... eso no significa...",
  ui_story_1011_10111002_33_dialog_content = "(¿No significa eso que ella es tan buena como <color=#FFB400>muerto</color>?!?!)",
  ui_story_1011_10111002_34_dialog_content = "¿Por qué Caelestites inventaría algo tan terrible?",
  ui_story_1011_10111002_36_dialog_content = "No, no, esto no está pasando...",
  ui_story_1011_10111002_37_dialog_content = "Debe haber una manera de despertar Vice arriba...",
  ui_story_1011_10111002_38_dialog_content = "A-Mientras sigamos aquí en estas ruinas, lo encontraremos...",
  ui_story_1011_10111002_39_dialog_content = "¡Pero...!",
  ui_story_1011_10111002_40_dialog_content = "Si me hubiera ocupado de todos esos eclipses...",
  ui_story_1011_10111002_41_dialog_content = "Si pudieras haberte desconectado de Vice y la detuvo...",
  ui_story_1011_10111002_41X1_dialog_content = "¡Esto le habría pasado a ella!",
  ui_story_1011_10111002_41X2_dialog_content = "Tuvimos una oportunidad, podríamos haber...",
  ui_story_1011_10111002_42_dialog_content = "Carleen...",
  ui_story_1011_10111002_43_dialog_content = "...",
  ui_story_1011_10111002_44_dialog_content = "Lo siento. Dejo que mis emociones saquen lo mejor de mí.",
  ui_story_1011_10111002_45_dialog_content = "(Ahora que lo pienso, ¿por qué el dispositivo dañó Vice?)",
  ui_story_1011_10111002_46_dialog_content = "(¿Podría haber hecho algo mal? No... Si lo hubiera hecho, lo habría sentido).",
  ui_story_1011_10111002_47_dialog_content = "<color=#e8d9bb>Bip, bip, bip, bip...</color>",
  ui_story_1011_10111002_48_dialog_content = "No hay objetivos restantes. Orden de matar a distancia completa completa.",
  ui_story_1011_10111002_49_dialog_content = "Vice fue quien activó la \"Orden de matanza de rango completo\".",
  ui_story_1011_10111002_50_dialog_content = "Neural Aux, ¿cómo terminó dañando el dispositivo? Vice ¿por error?",
  ui_story_1011_10111002_51_dialog_content = "Recibido... Analizando pregunta...",
  ui_story_1011_10111002_52_dialog_content = "Respuesta: El Atacante Especial ejecutó la orden sin error. Ninguna forma de vida fue dañada por error.",
  ui_story_1011_10111002_53_dialog_content = "¿¡Qué!?",
  ui_story_1011_10111002_54_dialog_content = "Vice está mintiendo justo en frente de nosotros! ¡Deja de bromear!",
  ui_story_1011_10111002_55_dialog_content = "Mi respuesta es correcta. Repetir: El Atacante Especial ejecutó la orden sin error. Ninguna forma de vida era—",
  ui_story_1011_10111002_56_dialog_content = "Caelestite, por favor baje su pistola láser. Su efecto paralizante no funciona en Neural Aux.",
  ui_story_1011_10111002_57_dialog_content = "Repetir: El Atacante Especial ejecutó la orden sin error. Ninguna forma de vida fue dañada por error.",
  ui_story_1011_10111002_58_dialog_content = "...",
  ui_story_1011_10111002_59_dialog_content = "...",
  ui_story_1011_10111002_60_dialog_content = "Cálmate, PlayerName. Interrogarlo meticulosamente, hasta que obtengamos las respuestas que necesitamos.",
  ui_story_1011_10111002_61_dialog_content = "No dejes que la lógica de la máquina de Neural Aux saque lo mejor de ti.",
  ui_story_1011_10111002_62_dialog_content = "Vice todavía está esperando que la despertemos.",
  ui_story_1011_10111002_63_dialog_content = "Estás bien. Hay una pregunta importante que todavía no hemos hecho.",
  ui_story_1011_10111002_64_dialog_content = "Neural Aux, por favor explique el <color=#FFB400>función principal</color> de este Atacante Especial.",
  ui_story_1011_10111002_65_dialog_content = "Recibido... Analizando pregunta...",
  ui_story_1011_10111002_66_dialog_content = "Reproduciendo la grabación introductoria de Special Attacker...",
  ui_story_1011_10111002_67_dialog_content = "Caelestites inicialmente usó el Atacante especial como un dispositivo para la autodefensa.",
  ui_story_1011_10111002_68_dialog_content = "Ofrece diferentes niveles de supresión contra diferentes tipos de enemigos.",
  ui_story_1011_10111002_69_dialog_content = "Debido a su efectividad, luego se usó activamente en combate. Fin de la grabación.",
  ui_story_1011_10111002_70_dialog_content = "¡Eso no nos dice nada!",
  ui_story_1011_10111002_71_dialog_content = "Estoy aún más confundido ahora. ¿Por qué demonios atacaría? Vice?",
  ui_story_1011_10111002_72_dialog_content = "PlayerName.",
  ui_story_1011_10111002_73_dialog_content = "Creo que estoy empezando a entender.",
  ui_story_1011_10111002_74_dialog_content = "Es decir, si Neural Aux nos ha contado todo lo que hay que saber sobre este dispositivo.",
  ui_story_1011_10111002_74X1_dialog_content = "Era tecnología Caelestite, utilizada para la autodefensa. Su orden de matar de rango completo terminó apuntando Vice, un auroriano.",
  ui_story_1011_10111002_75_dialog_content = "Entonces, el estado de hibernación al que envía a los no Caelestitas podría haber sido...",
  ui_story_1011_10111002_76_dialog_content = "Es posible que para los antiguos Caelestitas, esto fuera solo un <color=#FFB400>común</color> ocurrencia.",
  ui_story_1011_10111002_77_dialog_content = "Al igual que cuando aprendí por primera vez a usar mi Moon Cocoon...",
  ui_story_1011_10111002_78_dialog_content = "Mi instructor nunca se molestó en mencionar por qué lo apuntaría a un Eclipsite en primer lugar.",
  ui_story_1011_10111002_79_dialog_content = "Porque no era algo que realmente necesitara ser explicado.",
  ui_story_1011_10111002_80_dialog_content = "¡¿?!",
  ui_story_1011_10111002_81_dialog_content = "No puedo entender, ni puedo simplemente aceptar esto...",
  ui_story_1011_10111002_82_dialog_content = "Pero no puedo negar que lo que dices tiene sentido.",
  ui_story_1011_10111002_83_dialog_content = "¿Es posible que los antiguos aurorianos consideraran a Caelestites como su <color=#FFB400>enemigo</color>?",
  ui_story_1011_10111101_1_dialog_content = "No tengo ni idea. Cada vez estoy más confundido.",
  ui_story_1011_10111101_2_dialog_content = "Estamos en Eraveil, debajo de la torre blanca que es el hito más distintivo de la región.",
  ui_story_1011_10111101_3_dialog_content = "Sin embargo, no puedo entender nada.",
  ui_story_1011_10111101_4_dialog_content = "No sé qué es este lugar, ni qué tipo de personas vivieron aquí alguna vez.",
  ui_story_1011_10111101_5_dialog_content = "No sé cómo perecieron esos individuos, dejando tras de sí evidentes signos de una batalla que alguna vez libraron.",
  ui_story_1011_10111101_6_dialog_content = "Quizás a través de nuestras experiencias, ya hemos encontrado la respuesta.",
  ui_story_1011_10111101_7_dialog_content = "Los eclipses son las únicas cosas que sobrevivieron en este lugar.",
  ui_story_1011_10111101_8_dialog_content = "...",
  ui_story_1011_10111101_9_dialog_content = "¿Al igual que sucedió en Eraveil hace diecisiete años?",
  ui_story_1011_10111101_10_dialog_content = "Tal vez peor. Porque sus últimos gritos nunca habrían logrado que el resto del mundo los escuchara.",
  ui_story_1011_10111101_11_dialog_content = "Este lugar conoció su trágico final en completo silencio, sin que nadie lo supiera.",
  ui_story_1011_10111101_12_dialog_content = "Puede que seamos los únicos forasteros en cientos o miles de años en poner un pie aquí.",
  ui_story_1011_10111101_13_dialog_content = "Buscando en los últimos mil años.",
  ui_story_1011_10111101_14_dialog_content = "Sin registro de personas ajenas. Tu teoría es correcta.",
  ui_story_1011_10111101_15_dialog_content = "No estaba hablando contigo.",
  ui_story_1011_10111101_16_dialog_content = "La directiva principal de Neural Aux es ayudar a Caelestites de todas las formas posibles.",
  ui_story_1011_10111101_17_dialog_content = "Si tan solo fueras realmente útil para resolver los problemas reales en cuestión...",
  ui_story_1011_10111101_18_dialog_content = "no sabes despertar Vice ni cómo reparar Soroz.",
  ui_story_1011_10111101_19_dialog_content = "Consultando con los nuevos parámetros...",
  ui_story_1011_10111101_20_dialog_content = "Ningún método para \"despertar Vice up\" o \"reparar Soroz\" encontrado en la base de datos.",
  ui_story_1011_10111101_21_dialog_content = "Su análisis es exacto. No sé.",
  ui_story_1011_10111101_22_dialog_content = "Jeje, gracias por la confirmación.",
  ui_story_1011_10111101_23_dialog_content = "Lo siento terriblemente. Puntuación de satisfacción del usuario baja recibida. Los ajustes se harán en el futuro.",
  ui_story_1011_10111101_24_dialog_content = "no te estaba culpando...",
  ui_story_1011_10111101_25_dialog_content = "Teniendo en cuenta el desastre que obviamente tuvo lugar aquí, no es de extrañar que no estés trabajando correctamente.",
  ui_story_1011_10111101_26_dialog_content = "Encontraremos las respuestas nosotros mismos.",
  ui_story_1011_10111101_27_dialog_content = "Continuemos, Carleen, en las profundidades.",
  ui_story_1011_10111101_28_dialog_content = "No tenemos otra opción.",
  ui_story_1011_10111101_29_dialog_content = "Sí. llevaré Vice.",
  ui_story_1011_10111101_30_dialog_content = "(Encontraremos una manera de arreglar lo que te sucedió).",
  ui_story_1011_10111101_31_dialog_content = "(Solo espera... Debes.)",
  ui_story_1011_10111101_32_dialog_content = "<color=#e8d9bb>*Pasos resonando*</color>",
  ui_story_1011_10111101_33_dialog_content = "Me sorprende que no hayamos encontrado nada en este camino.",
  ui_story_1011_10111101_34_dialog_content = "No hay eclipses ni escombros esparcidos.",
  ui_story_1011_10111101_35_dialog_content = "De hecho, esta es probablemente la zona más ordenada que hemos visto desde que llegamos aquí.",
  ui_story_1011_10111101_36_dialog_content = "Sí, pero la limpieza es extraña.",
  ui_story_1011_10111101_37_dialog_content = "Es como si este lugar no se viera afectado en absoluto por lo que sucedió en las otras áreas.",
  ui_story_1011_10111101_38_dialog_content = "Está desprovisto tanto de vida humana como de indicios de batalla.",
  ui_story_1011_10111101_39_dialog_content = "Le da un ambiente frígido, ¿no?",
  ui_story_1011_10111101_40_dialog_content = "Sí.",
  ui_story_1011_10111101_41_dialog_content = "un maestro en el Dawn La academia una vez me dijo:",
  ui_story_1011_10111101_42_dialog_content = "\"Las cosas que hacen humanos a los seres humanos tienden a congregarse en la superficie del mundo\".",
  ui_story_1011_10111101_43_dialog_content = "\"Cuanto más profundices, más sentirás que tu humanidad se desvanece\".",
  ui_story_1011_10111101_44_dialog_content = "¿No es esto representante de nuestras circunstancias actuales?",
  ui_story_1011_10111101_45_dialog_content = "Cada paso que damos nos adentra más en las profundidades.",
  ui_story_1011_10111101_46_dialog_content = "Tu maestro probablemente nunca esperó que aplicaras esa declaración a las profundidades subterráneas reales.",
  ui_story_1011_10111101_47_dialog_content = "Bueno, ahora lo entiendo mucho más de lo que nunca lo hice sentado en un salón de clases.",
  ui_story_1011_10111101_48_dialog_content = "Caelestita detectada en el área restringida. Verificando la identidad.",
  ui_story_1011_10111101_49_dialog_content = "Bip... Bip... Bip... Bip...",
  ui_story_1011_10111101_50_dialog_content = "¿Hmm? ¿Por qué de repente estás haciendo tanto ruido, Neural Aux?",
  ui_story_1011_10111101_51_dialog_content = "Bip... Bip... Bip... Bip!",
  ui_story_1011_10111101_52_dialog_content = "Fallo en la verificación. No siga adelante. Repita: no continúe.",
  ui_story_1011_10111101_53_dialog_content = "¿Y qué, volvemos atrás? De ninguna manera voy a volver a enfrentarme a muerte con un montón de Eclipsites.",
  ui_story_1011_10111101_54_dialog_content = "¿Y por qué de repente? ¡Al menos tienes que darme una explicación!",
  ui_story_1011_10111101_55_dialog_content = "PlayerName, mirar hacia el futuro.",
  ui_story_1011_10111101_56_dialog_content = "Es que una <color=#FFB400>puerta de piedra</color>?",
  ui_story_1011_10111101_57_dialog_content = "Seguro que parece uno.",
  ui_story_1011_10111101_58_dialog_content = "Esto es masivo. Casi lo tomo como una pared.",
  ui_story_1011_10111101_59_dialog_content = "Imagine la fuerza necesaria para abrir una puerta de este tamaño.",
  ui_story_1011_10111101_60_dialog_content = "No creo que se mueva aunque lo golpeen con el martillo más pesado.",
  ui_story_1011_10111101_61_dialog_content = "No puedo pensar en ninguna facción en el mundo que actualmente tenga la capacidad de producir o incluso impulsar una puerta de piedra tan enorme.",
  ui_story_1011_10111101_62_dialog_content = "Estoy de acuerdo.",
  ui_story_1011_10111101_63_dialog_content = "Ni siquiera una tecnología tan milagrosa podría salvarlos al final, ¿eh?",
  ui_story_1011_10111101_64_dialog_content = "No siga adelante. Repita: no continúe.",
  ui_story_1011_10111101_65_dialog_content = "No se le permite acceder a la <color=#FFB400>Núcleo central</color>.",
  ui_story_1011_10111101_66_dialog_content = "¿Acceso no concedido?",
  ui_story_1011_10111101_67_dialog_content = "La puerta solo abre para personal autorizado.",
  ui_story_1011_10111101_68_dialog_content = "No se permite la entrada de personal no autorizado por el <color=#FFB400>pedidos</color> dado.",
  ui_story_1011_10111101_69_dialog_content = "Me gustaría ver esta puerta abierta. La vista probablemente sería magnífica.",
  ui_story_1011_10111101_70_dialog_content = "Yo también lo creo. Necesitamos un poco de ayuda aquí, Neural Aux.",
  ui_story_1011_10111101_71_dialog_content = "¿Cómo obtenemos el permiso para entrar?",
  ui_story_1011_10111101_72_dialog_content = "Lo siento. No puedo ayudarte.",
  ui_story_1011_10111101_73_dialog_content = "¿Eh? ¿No dijiste que tu directiva principal era ayudarme en todas las formas posibles?",
  ui_story_1011_10111101_74_dialog_content = "Su acceso es denegado por el Decreto Supremo. El primer y más alto orden que existe.",
  ui_story_1011_10111101_75_dialog_content = "Caelestites no puede desobedecer el Decreto Supremo, ni Neural Aux.",
  ui_story_1011_10111101_76_dialog_content = "El Decreto Supremo... ¿o sí?",
  ui_story_1011_10111101_77_dialog_content = "Usaron una puerta de piedra del tamaño de una montaña solo para mantener a la gente afuera.",
  ui_story_1011_10111101_78_dialog_content = "El Decreto Supremo suena bastante arrogante.",
  ui_story_1011_10111101_79_dialog_content = "Esta puerta de piedra seguro que se adecuaba a su propósito.",
  ui_story_1011_10111101_80_dialog_content = "Sin embargo...",
  ui_story_1011_10111101_81_dialog_content = "Fue entonces cuando este lugar estaba en su apogeo.",
  ui_story_1011_10111101_82_dialog_content = "Esos días terminaron y todo lo que queda es una amenaza vacía.",
  ui_story_1011_10111101_83_dialog_content = "Sí, estas grietas desgastadas son más que suficientes para permitirnos pasar.",
  ui_story_1011_10111101_84_dialog_content = "Similar a un león que no tiene dientes, pero aún así no se dobla.",
  ui_story_1011_10111101_85_dialog_content = "Es bastante lamentable verlo hacer tal esfuerzo por rechazarnos en este estado.",
  ui_story_1011_10111101_86_dialog_content = "No siga adelante. Repita: no continúe.",
  ui_story_1011_10111101_87_dialog_content = "Entremos ya.",
  ui_story_1011_10111101_88_dialog_content = "Veamos qué esconde esta puerta de piedra.",
  ui_story_1011_10111101_89_dialog_content = "Sí. Todavía hay mucho por descubrir y, en este momento, no tenemos otras opciones.",
  ui_story_1011_10111101_90_dialog_content = "No se le ha concedido acceso. No puede ingresar a la región Central Core.",
  ui_story_1011_10111101_91_dialog_content = "Neural Aux, solo déjalo descansar ya.",
  ui_story_1011_10111101_92_dialog_content = "El Decreto Supremo te niega la entrada.",
  ui_story_1011_10111101_93_dialog_content = "Los Caelestitas no pueden desobedecer el Decreto Supremo...",
  ui_story_1011_10111101_94_dialog_content = "(Al arrastrarme por esta grieta oscura me doy cuenta de que esta puerta de piedra es mucho más gruesa de lo que parece desde el exterior).",
  ui_story_1011_10111101_95_dialog_content = "(La voz de Neural Aux se ha apagado. Me pregunto si finalmente se rindió o fue bloqueada por la puerta).",
  ui_story_1011_10111101_96_dialog_content = "(Mi imaginación se vuelve loca pensando en lo que podría estar esperándonos al otro lado de esta puerta...)",
  ui_story_1011_10111101_97_dialog_content = "(Pero solo sé que pase lo que pase, me sorprenderé).",
  ui_story_1011_10111101_98_dialog_content = "(Conozco el significado y las implicaciones de lo que estoy a punto de ver).",
  ui_story_1011_10111101_99_dialog_content = "(Estos son los restos de toda una civilización.)",
  ui_story_1011_10111101_100_dialog_content = "¿Qué es esto?",
  ui_story_1011_10111101_101_dialog_content = "Milagrosamente sigue funcionando...",
  ui_story_1011_10111101_102_dialog_content = "Neural Aux, ¿sigues ahí?",
  ui_story_1011_10111101_103_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10111101_104_dialog_content = "No creo que responda ya que no pudo evitar que entremos.",
  ui_story_1011_10111101_105_dialog_content = "Así que tendremos que resolver esto por nosotros mismos.",
  ui_story_1011_10111101_106_dialog_content = "Son un montón de tabletas circulares flotantes.",
  ui_story_1011_10111101_107_dialog_content = "¿Para qué son? Realmente no puedo ni imaginar.",
  ui_story_1011_10111101_108_dialog_content = "¿Habías visto algo así antes?",
  ui_story_1011_10111101_109_dialog_content = "Nunca.",
  ui_story_1011_10111101_110_dialog_content = "Nunca antes habíamos desenterrado nada remotamente similar de otras ruinas antiguas.",
  ui_story_1011_10111101_111_dialog_content = "Eso no es sorprendente, sin embargo. Estas ruinas son diferentes a las demás, son ruinas de Caelestite.",
  ui_story_1011_10111101_112_dialog_content = "Tal vez solo Caelestites pueda hacer uso de estos objetos.",
  ui_story_1011_10111101_113_dialog_content = "¿Quieres decir?",
  ui_story_1011_10111101_114_dialog_content = "La forma en que los caelestitas ven el mundo es diferente de cómo lo vemos los aurorianos.",
  ui_story_1011_10111101_115_dialog_content = "Si fueron diseñados para ser utilizados por Caelestites, entonces tal vez solo un Caelestite tenga la capacidad de operarlo.",
  ui_story_1011_10111101_116_dialog_content = "¿Te refieres a mi habilidad psíquica?",
  ui_story_1011_10111101_117_dialog_content = "Es solo mi suposición. ¿Por qué no lo probamos?",
  ui_story_1011_10111101_118_dialog_content = "Bien.",
  ui_story_1011_10111101_119_option_content = "¡Control forzado!",
  ui_story_1011_10111101_120_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_1011_10111101_121_dialog_content = "¿Eh? Esto es...",
  ui_story_1011_10111101_122_dialog_content = "Bienvenido, recién nacido.",
  ui_story_1011_10111101_123_dialog_content = "¿Es esta tu primera vez con el <color=#FFB400>sistema circular</color>?",
  ui_story_1011_10111101_124_dialog_content = "sistema circular? ¿Te refieres al dispositivo?",
  ui_story_1011_10111101_125_dialog_content = "¿Dónde estoy? ¿Quien esta hablando?",
  ui_story_1011_10111101_126_dialog_content = "El Sistema Circular contiene los recuerdos de toda la raza Caelestite.",
  ui_story_1011_10111101_127_dialog_content = "Aquí, aprenderás sobre el mundo.",
  ui_story_1011_10111101_128_dialog_content = "Espera... En realidad, nadie me está \"hablando\".",
  ui_story_1011_10111101_129_dialog_content = "Toda esta información trascendió el lenguaje verbal mismo y me está siendo enviada directamente.",
  ui_story_1011_10111101_130_dialog_content = "Comencemos con su ubicación actual.",
  ui_story_1011_10111101_131_dialog_content = "Esta es la cuna de la civilización Caelestita, donde nacen todos los Caelestitas.",
  ui_story_1011_10111101_132_dialog_content = "No importa a dónde vayas, este lugar siempre será tu hogar.",
  ui_story_1011_10111101_133_dialog_content = "Este es el <color=#FFB400>Ciudad del Obelisco</color>.",
  ui_story_1011_10111101_134_dialog_content = "Ciudad del Obelisco...",
  ui_story_1011_10111101_135_dialog_content = "¿No son Caelestites de Eraveil?",
  ui_story_1011_10111101_136_dialog_content = "Esta ciudad se compone de innumerables torres.",
  ui_story_1011_10111101_137_dialog_content = "Estás parado en el centro de la ciudad, dentro de la primera y más alta de todas las torres.",
  ui_story_1011_10111101_138_dialog_content = "El Obelisco del Retorno.",
  ui_story_1011_10111101_139_dialog_content = "Cada caelestita recibe educación aquí hasta que alcanza la mayoría de edad.",
  ui_story_1011_10111101_140_dialog_content = "Tendrás la oportunidad de explorar el mundo y viajar a los confines del mundo una vez que seas mayor de edad.",
  ui_story_1011_10111101_141_dialog_content = "Pero tu hogar... la Ciudad del Obelisco... siempre te estará esperando...",
  ui_story_1011_10111101_142_dialog_content = "Esperando tu regreso... al final de... tu viaje...",
  ui_story_1011_10111101_143_dialog_content = "!",
  ui_story_1011_10111101_144_dialog_content = "¿¡E-Eso es todo!?",
  ui_story_1011_10111101_145_dialog_content = "¿Asi que? ¿Qué viste?",
  ui_story_1011_10111101_146_dialog_content = "Escuché una voz. No. No es una voz. Recibí información.",
  ui_story_1011_10111101_147_dialog_content = "¿Información?",
  ui_story_1011_10111101_148_dialog_content = "En el momento en que me conecté con el dispositivo, la información me llegó directamente.",
  ui_story_1011_10111101_149_dialog_content = "Se sentía como... una conferencia.",
  ui_story_1011_10111101_150_dialog_content = "Me informaron que este dispositivo se llama Sistema Circular, que contiene toda la historia de la raza Caelestita.",
  ui_story_1011_10111101_151_dialog_content = "También decía que este es el lugar de nacimiento de los Caelestitas, llamada la Ciudad del Obelisco.",
  ui_story_1011_10111101_152_dialog_content = "El Obelisco del Retorno, en el que nos encontramos ahora, es el más alto de todos.",
  ui_story_1011_10111101_153_dialog_content = "¿No mencionaba a Eraveil?",
  ui_story_1011_10111101_154_dialog_content = "No. Yo también estaba desconcertado por eso.",
  ui_story_1011_10111101_155_dialog_content = "¿Cambió el nombre en el transcurso del tiempo...?",
  ui_story_1011_10111101_156_dialog_content = "Eso es posible. Este lugar es antiguo. Tanto el lenguaje escrito como el verbal pueden haber cambiado.",
  ui_story_1011_10111101_157_dialog_content = "Entonces... ¿este sistema circular es una especie de dispositivo de almacenamiento de información?",
  ui_story_1011_10111101_158_dialog_content = "Puedes decir eso.",
  ui_story_1011_10111101_159_dialog_content = "Los caelestitas recuperan información usando habilidades psíquicas.",
  ui_story_1011_10111101_160_dialog_content = "¿Por qué está diseñado así?",
  ui_story_1011_10111101_161_dialog_content = "Todavía no entiendo cómo se supone que funcionan esas tabletas circulares.",
  ui_story_1011_10111101_162_dialog_content = "Además de eso... Su tamaño es demasiado grande para un dispositivo de almacenamiento de información.",
  ui_story_1011_10111101_163_dialog_content = "La cantidad de información sería enorme incluso si este lugar estuviera lleno de libros.",
  ui_story_1011_10111101_164_dialog_content = "Libros...",
  ui_story_1011_10111101_165_dialog_content = "Esperar. Carleen, ¿recuerdas la amonita que recogimos?",
  ui_story_1011_10111101_166_dialog_content = "Claro.",
  ui_story_1011_10111101_167_dialog_content = "Vice dicho, su forma imita los principios matemáticos de esta antigua civilización.",
  ui_story_1011_10111101_168_dialog_content = "Adoran la naturaleza, y su representación matemática es \"progresión\".",
  ui_story_1011_10111101_169_dialog_content = "Ese concepto bien puede estar en juego aquí.",
  ui_story_1011_10111101_170_dialog_content = "¿Quieres decir que estas formas circulares también simbolizan \"progresión\"?",
  ui_story_1011_10111101_171_dialog_content = "Sí. Estoy pensando en cómo dijiste que este lugar podría haber estado lleno de libros.",
  ui_story_1011_10111101_172_dialog_content = "Si tuviéramos que almacenar y organizar libros, los apilaríamos, sin dejar espacio entre ellos.",
  ui_story_1011_10111101_173_dialog_content = "Eventualmente, terminaremos con una pila rectangular de libros.",
  ui_story_1011_10111101_174_dialog_content = "Pero un rectángulo tiene muchas esquinas, por lo que sus líneas no son continuas...",
  ui_story_1011_10111101_175_dialog_content = "Mientras que un círculo no tiene esquinas.",
  ui_story_1011_10111101_176_dialog_content = "Así que este espacio también incorporó el concepto de \"progresión\" para almacenar información.",
  ui_story_1011_10111101_177_dialog_content = "¡Eso es exactamente lo que quise decir!",
  ui_story_1011_10111101_178_dialog_content = "Incluso si puedo... describirlo así, todavía no entiendo cómo funciona realmente.",
  ui_story_1011_10111101_179_dialog_content = "Si eso era cierto, esta antigua civilización estaba mucho más avanzada de lo que pensábamos anteriormente.",
  ui_story_1011_10111101_180_dialog_content = "Sus principios científicos básicos son drásticamente diferentes a los nuestros.",
  ui_story_1011_10111101_181_dialog_content = "A sus ojos, bien podríamos ser seres primitivos jugando con palos.",
  ui_story_1011_10111101_182_dialog_content = "Eso es... tan difícil de imaginar.",
  ui_story_1011_10111101_183_dialog_content = "Intente acceder de nuevo, PlayerName.",
  ui_story_1011_10111101_184_dialog_content = "¿Cuánta información podría contener dada su tecnología no convencional?",
  ui_story_1011_10111101_185_dialog_content = "Tal vez tenga la respuesta a todas las preguntas del mundo.",
  ui_story_1011_10111101_186_dialog_content = "¡Lo intentaré de nuevo!",
  ui_story_1011_10111101_187_option_content = "¡Control forzado!",
  ui_story_1011_10111101_188_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_1011_10111101_189_dialog_content = "Aqui otra vez.",
  ui_story_1011_10111101_190_dialog_content = "Si este lugar almacena información... Debería poder navegar a través de él.",
  ui_story_1011_10111101_191_dialog_content = "Pero no hay nada tan obvio como las estanterías.",
  ui_story_1011_10111101_192_dialog_content = "Correcto, mi mente. Déjame tratar de visualizarlo en mi mente.",
  ui_story_1011_10111101_193_dialog_content = "¿Eh?",
  ui_story_1011_10111101_194_dialog_content = "Las tabletas flotantes se están moviendo.",
  ui_story_1011_10111101_195_dialog_content = "PlayerName, ¿Que estas haciendo?",
  ui_story_1011_10111101_196_dialog_content = "¡Guau! Dios mio...",
  ui_story_1011_10111101_197_dialog_content = "Siento náuseas... ¿me estoy moviendo?",
  ui_story_1011_10111101_198_dialog_content = "Alto... Necesito encontrar una manera de detenerme.",
  ui_story_1011_10111101_199_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_1011_10111101_200_dialog_content = "Uf... ¿Se detuvo?",
  ui_story_1011_10111101_201_dialog_content = "el coloso",
  ui_story_1011_10111101_202_dialog_content = "¿¡Eh!?",
  ui_story_1011_10111101_203_dialog_content = "The Colossus es una gran instalación multifuncional impulsada por Lumina.",
  ui_story_1011_10111101_204_dialog_content = "Es lo más confiable para un Caelestita.",
  ui_story_1011_10111101_205_dialog_content = "Los Caelestites son poderosos mentalmente, pero el precio es ser físicamente débiles.",
  ui_story_1011_10111101_206_dialog_content = "Un Colossus compensa la debilidad de un Caelestite y sirve como una extensión del cuerpo, sincronizando el movimiento con la velocidad del pensamiento de un Caelestite.",
  ui_story_1011_10111101_207_dialog_content = "Por lo tanto, cada Caelestite debe aprender a pilotar un Colossus, ante todo.",
  ui_story_1011_10111101_208_dialog_content = "Definitivamente es un programa educativo...",
  ui_story_1011_10111101_209_dialog_content = "¿Me está enseñando a pilotar un Colossus esta vez?",
  ui_story_1011_10111101_210_dialog_content = "Hay una cabina instalada para que Caelestites controle el Coloso.",
  ui_story_1011_10111101_211_dialog_content = "Un Caelestita debe vincular su mente a un Coloso.",
  ui_story_1011_10111101_212_dialog_content = "Suficiente potencia de resonancia activará el Colossus.",
  ui_story_1011_10111101_213_dialog_content = "Eso es lo que me pasó.",
  ui_story_1011_10111101_214_dialog_content = "Un Colossus puede equiparse con varios módulos y complementos para cumplir diferentes funciones para el Caelestite.",
  ui_story_1011_10111101_215_dialog_content = "Con Colossus, un Caelestite puede ser más poderoso que cualquier ser vivo en el mundo.",
  ui_story_1011_10111101_216_dialog_content = "Pero, como poseedor de este gran poder, cualquier piloto de Colossus haría bien en recordar:",
  ui_story_1011_10111101_217_dialog_content = "El Decreto Supremo impreso en ti en el momento de tu nacimiento.",
  ui_story_1011_10111101_218_dialog_content = "Los Caelestites y Colossi serán siempre y para siempre máquinas de guerra.",
  ui_story_1011_10111101_219_dialog_content = "¿¡Máquinas de guerra!?",
  ui_story_1011_10111101_220_dialog_content = "Como es eso posible... La Soroz y yo... ni siquiera podemos pelear...",
  ui_story_1011_10111101_221_dialog_content = "Esta máquina de guerra tiene el cuerpo de un Coloso y la mente de un Caelestite.",
  ui_story_1011_10111101_222_dialog_content = "Esta arma en particular está atada por el Decreto Supremo y lista para los enemigos...",
  ui_story_1011_10111101_223_dialog_content = "Todo a su servicio.",
  ui_story_1011_10111101_224_dialog_content = "¿¡QUÉ!?",
  ui_story_1011_10111101_225_dialog_content = "¿Son estos... Eclipsitos?",
  ui_story_1011_10111101_226_dialog_content = "A continuación, deberá aprender sobre la guerra con mucho tiempo.",
  ui_story_1011_10111101_227_dialog_content = "Verá el campo de batalla en los datos.",
  ui_story_1011_10111101_228_dialog_content = "Verás lo insignificante que es una vida, y verás cómo inclinar la balanza destruye la balanza.",
  ui_story_1011_10111101_229_dialog_content = "Afortunadamente, este campo de batalla no pertenece a Caelestites.",
  ui_story_1011_10111101_230_dialog_content = "Hay soldados nacidos para la guerra, y lo único que saben es matar.",
  ui_story_1011_10111101_231_dialog_content = "Estos repugnantes soldados abrazarán el campo de batalla.",
  ui_story_1011_10111101_232_dialog_content = "En cuanto a ti, solo te encargarás de...",
  ui_story_1011_10111101_233_dialog_content = "Creando guerras para el mundo.",
  ui_story_1011_10111201_1_dialog_content = "Uf... uf...",
  ui_story_1011_10111201_2_dialog_content = "¿Qué pasa, PlayerName?",
  ui_story_1011_10111201_3_dialog_content = "Estás sudando mucho.",
  ui_story_1011_10111201_4_dialog_content = "Uf... yo...",
  ui_story_1011_10111201_5_dialog_content = "No sé.",
  ui_story_1011_10111201_6_dialog_content = "No sé por qué vi lo que acabo de ver.",
  ui_story_1011_10111201_7_dialog_content = "No sé lo que significaba... No lo sé.",
  ui_story_1011_10111201_8_dialog_content = "¿Qué viste?",
  ui_story_1011_10111201_9_dialog_content = "Vi el Coloso.",
  ui_story_1011_10111201_10_dialog_content = "El Sistema Circular me está enseñando a operar un Coloso.",
  ui_story_1011_10111201_11_dialog_content = "Y...",
  ui_story_1011_10111201_12_dialog_content = "Cómo comandar el Eclipsite dentro del Coloso.",
  ui_story_1011_10111201_13_dialog_content = "¿¡Comandar el Eclipsite!?",
  ui_story_1011_10111201_13X1_dialog_content = "Sí... Me dijo que Caelestites y Colossi eran máquinas de guerra...",
  ui_story_1011_10111201_14_dialog_content = "¿Cómo es eso posible?",
  ui_story_1011_10111201_15_dialog_content = "Carleen, Piensas qué...",
  ui_story_1011_10111201_16_dialog_content = "Yo también estoy sorprendido, pero... Realmente no tenemos suficiente información para hacer ningún tipo de juicio.",
  ui_story_1011_10111201_17_dialog_content = "Quiero decir, este lugar es antiguo, el mundo era diferente entonces.",
  ui_story_1011_10111201_18_dialog_content = "No sabemos qué sucedió entonces y no podemos confirmar la autenticidad del mensaje.",
  ui_story_1011_10111201_19_dialog_content = "Es eso así...",
  ui_story_1011_10111201_20_dialog_content = "Pero, si los caelestitas realmente comandaron a los eclipsitas.",
  ui_story_1011_10111201_21_dialog_content = "¿Qué me hace eso? como me veo...",
  ui_story_1011_10111201_22_dialog_content = "Pudo Schummer... tener razón, después de todo?",
  ui_story_1011_10111201_23_dialog_content = "Puedes pensar en el mensaje y lo que significa, pero no te dejes influir por él.",
  ui_story_1011_10111201_24_dialog_content = "Lo que experimentaste y cómo piensas es lo que más importa, ¿no es así?",
  ui_story_1011_10111201_25_dialog_content = "Las cosas por las que has pasado con Soroz son reales.",
  ui_story_1011_10111201_26_dialog_content = "Y todos los que lucharon codo con codo contigo son reales.",
  ui_story_1011_10111201_27_dialog_content = "No te preocupes por cómo debes verte a ti mismo.",
  ui_story_1011_10111201_28_dialog_content = "Yo, Vice, y todos los que no están presentes...",
  ui_story_1011_10111201_29_dialog_content = "Siempre tendrás un lugar con nosotros.",
  ui_story_1011_10111201_30_dialog_content = "Cierto... yo...",
  ui_story_1011_10111201_31_dialog_content = "Carleen... Muchas gracias...",
  ui_story_1011_10111201_32_dialog_content = "Hmm... No tienes que ponerte tan emocional.",
  ui_story_1011_10111201_33_dialog_content = "Estás bien. Eres todo real.",
  ui_story_1011_10111201_34_dialog_content = "Y encontrar una manera de despertar Vice arriba es lo importante en este momento.",
  ui_story_1011_10111201_35_dialog_content = "Necesito intentarlo de nuevo.",
  ui_story_1011_10111201_36_dialog_content = "¿Por qué no te tomas un descanso?",
  ui_story_1011_10111201_37_dialog_content = "Vincularse con el Sistema Circular parece realmente agotador.",
  ui_story_1011_10111201_38_dialog_content = "Estoy bien.",
  ui_story_1011_10111201_39_dialog_content = "Creo que he encontrado una forma de controlarlo.",
  ui_story_1011_10111201_40_option_content = "¡Control forzado!",
  ui_story_1011_10111201_41_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_1011_10111201_42_dialog_content = "Puedo sentir mi conciencia moviéndose allí.",
  ui_story_1011_10111201_43_dialog_content = "Creo que toda la información almacenada aquí puede haber creado un espacio virtual.",
  ui_story_1011_10111201_44_dialog_content = "Y puedo navegar a través de este espacio a través de mi conciencia.",
  ui_story_1011_10111201_45_dialog_content = "En mi intento, todavía estaba pensando en la experiencia anterior, así que entré en la conferencia de Caelestites.",
  ui_story_1011_10111201_46_dialog_content = "Esta vez, voy a controlarlo...",
  ui_story_1011_10111201_47_dialog_content = "Y encontrar una manera de despertar Vice arriba.",
  ui_story_1011_10111201_48_dialog_content = "Debo enfocar mi mente en la hibernación...",
  ui_story_1011_10111201_49_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_1011_10111201_50_dialog_content = "D-Funcionó?",
  ui_story_1011_10111201_51_dialog_content = "Datos de prueba, código...",
  ui_story_1011_10111201_52_dialog_content = "Acceso... cambiado a sin restricciones. Accesible para todos...",
  ui_story_1011_10111201_53_dialog_content = "Modificado por: Francisco.",
  ui_story_1011_10111201_54_dialog_content = "Francis... Este nombre otra vez.",
  ui_story_1011_10111201_55_dialog_content = "Parece que este mensaje está gravemente dañado. Espero que todavía pueda encontrar algunas pistas.",
  ui_story_1011_10111201_56_dialog_content = "Sujeto... No se pudo recuperar de la hibernación. Físico... El signo de vida se desvaneció.",
  ui_story_1011_10111201_57_dialog_content = "Sujeto... No se pudo recuperar de la hibernación... Exhibiendo... Signo de vida...",
  ui_story_1011_10111201_58_dialog_content = "Asunto... Error... Recuperar... Experimento...",
  ui_story_1011_10111201_59_dialog_content = "¿Qué tipo de experimentos son estos?",
  ui_story_1011_10111201_60_dialog_content = "Los datos de prueba... Esto es inquietante.",
  ui_story_1011_10111201_61_dialog_content = "Asunto... Error... Recuperar... No hay otras anomalías.",
  ui_story_1011_10111201_62_dialog_content = "Sujeto... No se pudo recuperar de la hibernación. Ninguna otra...",
  ui_story_1011_10111201_63_dialog_content = "Asunto... Error...",
  ui_story_1011_10111201_64_dialog_content = "Todos ellos eran...",
  ui_story_1011_10111201_65_dialog_content = "Experimentos...",
  ui_story_1011_10111201_66_dialog_content = "...",
  ui_story_1011_10111201_67_dialog_content = "Aún así, se pierden demasiados datos...",
  ui_story_1011_10111201_68_dialog_content = "... Último intento... combinado con...",
  ui_story_1011_10111201_69_dialog_content = "Tema...",
  ui_story_1011_10111201_70_dialog_content = "Observado... cambios físicos...",
  ui_story_1011_10111201_71_dialog_content = "...",
  ui_story_1011_10111201_72_dialog_content = "... recuperado con éxito de la hibernación.",
  ui_story_1011_10111201_73_dialog_content = "!?",
  ui_story_1011_10111201_74_dialog_content = "¡Un éxito!",
  ui_story_1011_10111201_75_dialog_content = "¿Qué es este experimento? ¿Dónde está?",
  ui_story_1011_10111201_76_dialog_content = "necesito mas informacion Tengo que sumergirme más profundo.",
  ui_story_1011_10111201_77_dialog_content = "Precaución: información de destino... acceso restringido...",
  ui_story_1011_10111201_78_dialog_content = "Acceso... terminado.",
  ui_story_1011_10111201_79_dialog_content = "Uf... no puedo inspeccionarlo...",
  ui_story_1011_10111201_80_dialog_content = "¿Asi que? ¿Encontraste algo?",
  ui_story_1011_10111201_81_dialog_content = "Sí. Encontré un conjunto de datos de prueba.",
  ui_story_1011_10111201_82_dialog_content = "Tiene los registros de un sujeto que se recuperó con éxito de la hibernación.",
  ui_story_1011_10111201_83_dialog_content = "Pero no sé qué fue el experimento ni dónde tuvo lugar.",
  ui_story_1011_10111201_84_dialog_content = "Y sólo hay un caso exitoso.",
  ui_story_1011_10111201_85_dialog_content = "No vimos ningún equipo de prueba intacto en el camino.",
  ui_story_1011_10111201_86_dialog_content = "Solo podemos esperar que se encuentre en algún lugar más profundo y todavía esté operativo.",
  ui_story_1011_10111201_87_dialog_content = "Y tendremos que arriesgarnos.",
  ui_story_1011_10111201_88_dialog_content = "Estás bien. Es todo lo que podemos hacer.",
  ui_story_1011_10111201_89_dialog_content = "Ven entonces. Vayamos más profundo.",
  ui_story_1011_10111201_90_dialog_content = "Incluso si no podemos encontrar el equipo de prueba, aún podemos encontrar otras pistas.",
  ui_story_1011_10111201_91_dialog_content = "Quién sabe cuántos secretos esconde este lugar.",
  ui_story_1011_10111201_92_dialog_content = "<color=#e8d9bb>Ta... ta... ta...</color>",
  ui_story_1011_10111201_93_dialog_content = "El \"Obelisco del Retorno\"...",
  ui_story_1011_10111201_94_dialog_content = "Mirando hacia atrás, solo ahora nos damos cuenta de que hemos estado explorando el interior de la torre.",
  ui_story_1011_10111201_95_dialog_content = "No hay forma de saber si las instalaciones subterráneas y la torre sobre el suelo son de la misma estructura.",
  ui_story_1011_10111201_96_dialog_content = "Se sienten como dos lugares claramente diferentes.",
  ui_story_1011_10111201_97_dialog_content = "La Torre Blanca ha estado en pie en Eraveil durante mucho tiempo. Todos estamos familiarizados con eso.",
  ui_story_1011_10111201_98_dialog_content = "No se puede decir lo mismo de las ruinas subterráneas. Es algo completamente extraño.",
  ui_story_1011_10111201_99_dialog_content = "La conexión entre los dos... eres tú...",
  ui_story_1011_10111201_100_dialog_content = "Los Caelestitas.",
  ui_story_1011_10111201_101_dialog_content = "...",
  ui_story_1011_10111201_102_dialog_content = "Aunque los tiempos y todo hayan cambiado, los caelestitas siguen viviendo bajo el mismo cielo.",
  ui_story_1011_10111201_103_dialog_content = "Sin duda, eso es un monumento en sí mismo.",
  ui_story_1011_10111201_104_dialog_content = "Nunca sentí nada remotamente similar cuando estaba en Northland, el lugar de nacimiento de los aurorianos.",
  ui_story_1011_10111201_105_dialog_content = "\"Monumento\"... ¿es así?",
  ui_story_1011_10111201_106_dialog_content = "Esa es una palabra pesada de soportar...",
  ui_story_1011_10111201_107_dialog_content = "¿Eh?",
  ui_story_1011_10111201_108_dialog_content = "Soy el único que lleva el peso de este \"monumento\" ahora...",
  ui_story_1011_10111201_109_dialog_content = "PlayerName.",
  ui_story_1011_10111201_110_dialog_content = "No importa. No es el momento de pensar en eso.",
  ui_story_1011_10111201_111_dialog_content = "En el lado positivo, esto significa que soy el único sucesor de toda esta estructura.",
  ui_story_1011_10111201_112_dialog_content = "Así que... Todo aquí me pertenece ahora, ¿verdad?",
  ui_story_1011_10111201_113_dialog_content = "Jeje.",
  ui_story_1011_10111201_114_dialog_content = "Estás bien. Usted es su propietario legítimo ahora.",
  ui_story_1011_10111201_115_dialog_content = "Eso es tan agradable. Nunca tendré que pasar hambre, teniendo tantas antigüedades y reliquias a mi disposición.",
  ui_story_1011_10111201_116_dialog_content = "voy a romper Viceel libro de cuentas!",
  ui_story_1011_10111201_117_dialog_content = "me aseguraré de dar Vice el mensaje.",
  ui_story_1011_10111201_118_dialog_content = "Oye... no vamos...",
  ui_story_1011_10111201_119_dialog_content = "<color=#e8d9bb>Tzz... Tzz...</color>",
  ui_story_1011_10111201_120_dialog_content = "Creo que escuché algo frotándose uno contra el otro.",
  ui_story_1011_10111201_121_dialog_content = "¿Podría ser algún tipo de mecanismo en el trabajo aquí?",
  ui_story_1011_10111201_122_dialog_content = "Eso es posible.",
  ui_story_1011_10111201_123_dialog_content = "No puedo evitar preguntarme, ¿cómo sigue operativo después de haber estado abandonado durante tanto tiempo?",
  ui_story_1011_10111201_124_dialog_content = "Estamos hablando de algunos milenios... Energía, desgaste... Realmente no puedo entenderlo.",
  ui_story_1011_10111201_125_dialog_content = "Puede ser un gran problema para nosotros, pero no necesariamente para quien creó este lugar.",
  ui_story_1011_10111201_126_dialog_content = "Parecen tener un enfoque muy diferente a los problemas.",
  ui_story_1011_10111201_127_dialog_content = "Eso es cierto.",
  ui_story_1011_10111201_128_dialog_content = "Acerquémonos y encontremos la fuente de ese sonido.",
  ui_story_1011_10111201_129_dialog_content = "Sí.",
  ui_story_1011_10111201_130_dialog_content = "<color=#e8d9bb>Tzz... Tzz...</color>",
  ui_story_1011_10111201_131_dialog_content = "¡Espera!",
  ui_story_1011_10111201_132_dialog_content = "¿Qué es?",
  ui_story_1011_10111201_133_dialog_content = "Creo que lo sentí.",
  ui_story_1011_10111201_134_dialog_content = "<color=#e8d9bb>Tzz... Tzz...</color>",
  ui_story_1011_10111201_135_dialog_content = "...",
  ui_story_1011_10111201_136_dialog_content = "¿Eclipsitos?",
  ui_story_1011_10111201_137_dialog_content = "¿Aquí también?",
  ui_story_1011_10111201_138_dialog_content = "Extraño. Deben habernos visto. Pero ¿por qué no reaccionan?",
  ui_story_1011_10111201_139_dialog_content = "...",
  ui_story_1011_10111201_140_dialog_content = "¡Mirar! ¿Qué están haciendo?",
  ui_story_1011_10111201_141_dialog_content = "<color=#e8d9bb>Tzz... Tzz...</color>",
  ui_story_1011_10111201_142_dialog_content = "¿Están... empujando las tabletas?",
  ui_story_1011_10111201_143_dialog_content = "¿Por qué hacen eso?",
  ui_story_1011_10111201_144_dialog_content = "Nunca he visto eclipses como este.",
  ui_story_1011_10111201_145_dialog_content = "Es difícil encontrarle sentido a lo que están haciendo...",
  ui_story_1011_10111201_145X1_dialog_content = "¿Están siguiendo la orden de un Eclipsite de alto nivel?",
  ui_story_1011_10111201_145X2_dialog_content = "No. No tiene sentido que ningún Eclipsite impulse las tabletas.",
  ui_story_1011_10111201_145X3_dialog_content = "Sin embargo... es una historia completamente diferente para Caelestites...",
  ui_story_1011_10111201_147_dialog_content = "¿A qué te refieres con eso?",
  ui_story_1011_10111201_148_dialog_content = "Estábamos hablando de cómo todo aquí permanece operativo, ¿no?",
  ui_story_1011_10111201_149_dialog_content = "Hemos encontrado nuestra respuesta.",
  ui_story_1011_10111201_150_dialog_content = "¿Te refieres a los eclipses?",
  ui_story_1011_10111201_151_dialog_content = "Es una hipótesis.",
  ui_story_1011_10111201_152_dialog_content = "¿Ver? Simplemente siguen empujando las tabletas y han optado por ignorarnos por completo.",
  ui_story_1011_10111201_153_dialog_content = "Son como las cadenas que mueven los engranajes... Son parte del mecanismo.",
  ui_story_1011_10111201_154_dialog_content = "<color=#e8d9bb>Tzz... Tzz...</color>",
  ui_story_1011_10111201_155_dialog_content = "Cómo es esto posible...",
  ui_story_1011_10111201_156_dialog_content = "Parece que lo que he visto en el Sistema Circular es cierto.",
  ui_story_1011_10111201_157_dialog_content = "La antigua Caelestite podría de alguna manera comandar a los Eclipsites...",
  ui_story_1011_10111201_158_dialog_content = "¿Cómo hicieron eso?",
  ui_story_1011_10111201_159_dialog_content = "¿Usando el enlace mental, tal vez?",
  ui_story_1011_10111201_160_dialog_content = "Este lugar ha sido abandonado durante mucho tiempo, pero los Eclipsites todavía siguen sus órdenes.",
  ui_story_1011_10111201_161_dialog_content = "Esperar. Parece ser un callejón sin salida.",
  ui_story_1011_10111201_162_dialog_content = "Estás bien. Ese es el final.",
  ui_story_1011_10111201_163_dialog_content = "No parece que haya nada aquí. Sólo un espacio abierto.",
  ui_story_1011_10111201_164_dialog_content = "Hay una plataforma de piedra en el medio. Vamos a ver.",
  ui_story_1011_10111201_165_dialog_content = "Los Eclipsites deben estar empujando las tabletas para conducir algo.",
  ui_story_1011_10111201_166_dialog_content = "Pero es sólo una plataforma de piedra.",
  ui_story_1011_10111201_167_dialog_content = "¿Hay algún interruptor o algo a los lados?",
  ui_story_1011_10111201_168_dialog_content = "*Tos* Está tan polvoriento...",
  ui_story_1011_10111201_169_dialog_content = "¿Qué hay de usar sus habilidades psíquicas?",
  ui_story_1011_10111201_170_dialog_content = "Ya hecho. Nada en absoluto.",
  ui_story_1011_10111201_171_dialog_content = "Realmente es solo un pedazo de piedra.",
  ui_story_1011_10111201_172_dialog_content = "¿Cómo podría ser esto?",
  ui_story_1011_10111201_173_dialog_content = "O tal vez, algo estuvo una vez aquí.",
  ui_story_1011_10111201_174_dialog_content = "Pero ya se ha derrumbado y se ha ido.",
  ui_story_1011_10111201_175_dialog_content = "Eso es posible, ya que todo en las ruinas está en estado de colapso.",
  ui_story_1011_10111201_176_dialog_content = "Incluso esa enorme puerta de piedra se marchitó y se agrietó. Las cosas hechas de otros materiales deben haber...",
  ui_story_1011_10111201_177_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_1011_10111201_178_dialog_content = "Solicitud de inicio de sesión detectada.",
  ui_story_1011_10111201_179_dialog_content = "¡Es Neural Aux!",
  ui_story_1011_10111201_180_dialog_content = "Algo activado. Qué hiciste, PlayerName?",
  ui_story_1011_10111201_181_dialog_content = "¡Yo... yo no hice nada!",
  ui_story_1011_10111201_182_dialog_content = "¡Estaba a punto de preguntarte lo mismo!",
  ui_story_1011_10111201_183_dialog_content = "Se requiere verificación de identidad.",
  ui_story_1011_10111201_184_dialog_content = "Por favor ingrese la identidad del usuario.",
  ui_story_1011_10111201_185_dialog_content = "¿Identidad? ¿Mío?",
  ui_story_1011_10111201_186_dialog_content = "Me llamo PlayerName.",
  ui_story_1011_10111201_187_dialog_content = "Se requiere verificación de identidad.",
  ui_story_1011_10111201_188_dialog_content = "Por favor ingrese la identidad del usuario.",
  ui_story_1011_10111201_189_dialog_content = "¿Eh? Dije, mi nombre esPlayerName... Eso no lo hará?",
  ui_story_1011_10111201_190_dialog_content = "Probablemente no pueda encontrarte en su base de datos, PlayerName.",
  ui_story_1011_10111201_191_dialog_content = "Entonces, ¿qué hacemos?",
  ui_story_1011_10111201_192_dialog_content = "¿No hay un Caelestita llamado Francis?",
  ui_story_1011_10111201_193_dialog_content = "¿Intentar usar su nombre?",
  ui_story_1011_10111201_194_dialog_content = "Entrada de identidad detectada: Pa... la... pong.",
  ui_story_1011_10111201_195_dialog_content = "¿eh? ¿Qué tipo de nombre es ese? ¡Yo no dije nada de eso!",
  ui_story_1011_10111201_196_dialog_content = "Verificación de identidad.",
  ui_story_1011_10111201_197_dialog_content = "Bip... Bip... Bip...",
  ui_story_1011_10111201_198_dialog_content = "¿Hay alguien que use ese tipo de nombre ridículo?",
  ui_story_1011_10111201_199_dialog_content = "Déjalo ya, Neural Aux. ¿Puedes decirnos primero qué es este lugar?",
  ui_story_1011_10111201_200_dialog_content = "Esperar, PlayerName!",
  ui_story_1011_10111201_201_dialog_content = "Mirar...",
  ui_story_1011_10111201_202_dialog_content = "¿Qué es?",
  ui_story_1011_10111201_203_dialog_content = "...",
  ui_story_1011_10111201_204_dialog_content = "Umm... ¿Por qué los Eclipsites dejaron de empujar las tabletas?",
  ui_story_1011_10111201_205_dialog_content = "De ninguna manera...",
  ui_story_1011_10111201_206_dialog_content = "¡¡Graaaah!!",
  ui_story_1011_10111201_207_dialog_content = "Carleen!",
  ui_story_1011_10111201_208_dialog_content = "¡Dispersión, pétalos de hielo!",
  ui_story_1011_10111401_1_dialog_content = "Afortunadamente, no son grandes en número.",
  ui_story_1011_10111401_2_dialog_content = "De lo contrario, estaríamos abrumados.",
  ui_story_1011_10111401_3_dialog_content = "Sí.",
  ui_story_1011_10111401_4_dialog_content = "¿Qué pasa con Neural Aux? Parece más muerto cerebralmente que antes.",
  ui_story_1011_10111401_5_dialog_content = "Hola, Neural Aux. ¿Puedes escucharme?",
  ui_story_1011_10111401_6_dialog_content = "¡Responder! ¿Que esta pasando?",
  ui_story_1011_10111401_7_dialog_content = "La verificación de identidad falló. Nombre de usuario ilegal: Palapong.",
  ui_story_1011_10111401_8_dialog_content = "Envíe un nombre de usuario válido o cancele el inicio de sesión.",
  ui_story_1011_10111401_9_dialog_content = "Qué... ¡Ni siquiera escucha!",
  ui_story_1011_10111401_10_dialog_content = "¿No sientes que te está tratando diferente ahora...?",
  ui_story_1011_10111401_11_dialog_content = "Anteriormente, trató de responder a sus preguntas...",
  ui_story_1011_10111401_12_dialog_content = "Pero ahora, solo está esperando la entrada de su comando.",
  ui_story_1011_10111401_13_dialog_content = "Creo que tienes razón...",
  ui_story_1011_10111401_14_dialog_content = "¿Pero por qué?",
  ui_story_1011_10111401_15_dialog_content = "¿Es por donde estamos ahora?",
  ui_story_1011_10111401_16_dialog_content = "Tal vez este lugar es donde se ingresan sus comandos.",
  ui_story_1011_10111401_17_dialog_content = "¿Tu lo crees?",
  ui_story_1011_10111401_18_dialog_content = "Neural Aux, cancelar inicio de sesión.",
  ui_story_1011_10111401_19_dialog_content = "Solicitud de reactivación del Obelisco del Retorno recibida.",
  ui_story_1011_10111401_20_dialog_content = "Solicitud de: Palapong. Identidad ilegal.",
  ui_story_1011_10111401_21_dialog_content = "Advertencia: La operación continua activará el <color=#FFB400>Sistema Guardián</color>.",
  ui_story_1011_10111401_22_dialog_content = "¡Ver! ¡Lo está haciendo de nuevo!",
  ui_story_1011_10111401_23_dialog_content = "¿Palapong se refiere a mí? Yo no pedí nada reactivación!",
  ui_story_1011_10111401_24_dialog_content = "Si no pensamos demasiado en esto...",
  ui_story_1011_10111401_25_dialog_content = "La respuesta más simple es que: está roto.",
  ui_story_1011_10111401_26_dialog_content = "¿Roto? auxiliar neuronal?",
  ui_story_1011_10111401_27_dialog_content = "No. El receptor de comandos está roto.",
  ui_story_1011_10111401_28_dialog_content = "¿Has probado a usar la radio de Illumina?",
  ui_story_1011_10111401_29_dialog_content = "Cuando está roto, hace esos ruidos \"pzaaazzzz\".",
  ui_story_1011_10111401_30_dialog_content = "Suena un poco similar al nombre que Neural Aux sigue repitiendo.",
  ui_story_1011_10111401_31_dialog_content = "Entonces estamos en serios problemas.",
  ui_story_1011_10111401_32_dialog_content = "Confirmada la solicitud de reactivación del Obelisco del Retorno.",
  ui_story_1011_10111401_33_dialog_content = "Advertencia: Guardian System está a punto de activarse. Cancele la solicitud.",
  ui_story_1011_10111401_34_dialog_content = "¡Cancelar! ¡Cancelar ahora!",
  ui_story_1011_10111401_35_dialog_content = "¡Y ni siquiera hice la solicitud!",
  ui_story_1011_10111401_36_dialog_content = "Advertencia: El usuario ilegal ha activado la secuencia de reactivación del Obelisco del Retorno por la fuerza.",
  ui_story_1011_10111401_37_dialog_content = "Recuperando la secuencia de reactivación del Obelisco del Retorno del Sistema Circular.",
  ui_story_1011_10111401_38_dialog_content = "Bip... Bip... Bip...",
  ui_story_1011_10111401_39_dialog_content = "Tengo el presentimiento de que algo malo va a pasar.",
  ui_story_1011_10111401_40_dialog_content = "Igual aquí. ¿Hay alguna forma de detenerlo ahora?",
  ui_story_1011_10111401_41_dialog_content = "¿Qué tal si rompemos su transceptor por completo?",
  ui_story_1011_10111401_42_dialog_content = "Malfuncionando así... Podríamos simplemente destruirlo.",
  ui_story_1011_10111401_43_dialog_content = "No sé dónde está. ¿La plataforma de piedra?",
  ui_story_1011_10111401_44_dialog_content = "Supongo que lo averiguaremos... ¡Aquí va!",
  ui_story_1011_10111401_45_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1011_10111401_46_dialog_content = "¡Ay! ¡Eso duele!",
  ui_story_1011_10111401_47_dialog_content = "¡Está hecho de piedra! ¿Cuál es el punto de darle una patada?",
  ui_story_1011_10111401_48_dialog_content = "Advertencia: El usuario ilegal ha activado la secuencia de reactivación del Obelisco del Retorno por la fuerza.",
  ui_story_1011_10111401_49_dialog_content = "Módulo de energía recuperado. Comience a cargar módulos de fuente de alimentación adicionales.",
  ui_story_1011_10111401_50_dialog_content = "Bip... Bip... Bip...",
  ui_story_1011_10111401_51_dialog_content = "Carleen... ¿Sientes algo retumbando debajo de nosotros?",
  ui_story_1011_10111401_52_dialog_content = "Sí lo hago...",
  ui_story_1011_10111401_53_dialog_content = "Decía: \"Secuencia de reactivación del Obelisco del Retorno\". Algo le debe estar pasando a toda la estructura.",
  ui_story_1011_10111401_54_dialog_content = "toda la estructura? Eso suena aterrador.",
  ui_story_1011_10111401_55_dialog_content = "Eso no es lo que debería preocuparnos en este momento.",
  ui_story_1011_10111401_56_dialog_content = "La \"advertencia\" que sigue recordándonos... No creo que debamos descartarla.",
  ui_story_1011_10111401_57_dialog_content = "Advertencia: El usuario ilegal ha activado la secuencia de reactivación del Obelisco del Retorno por la fuerza.",
  ui_story_1011_10111401_58_dialog_content = "Acceso restringido detectado. La medida de corrección está a punto de ser lanzada.",
  ui_story_1011_10111401_59_dialog_content = "Esta es tu última advertencia. Cancele inmediatamente su solicitud.",
  ui_story_1011_10111401_60_dialog_content = "¡Te dije que cancelaras!",
  ui_story_1011_10111401_61_dialog_content = "¡Dáme un respiro! ¡Cancelalo!",
  ui_story_1011_10111401_62_dialog_content = "¡No estoy interesado en enfrentarme a una tecnología antigua!",
  ui_story_1011_10111401_64_dialog_content = "Solicitud ilegal aún en curso.",
  ui_story_1011_10111401_65_dialog_content = "Medida de corrección lista para lanzar.",
  ui_story_1011_10111401_66_dialog_content = "¡Que te jodan, Neural Aux!",
  ui_story_1011_10111401_67_dialog_content = "Activando \"Sistema Guardián\". Liberando Claudia.",
  ui_story_1011_10111401_68_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1011_10111401_69_dialog_content = "Qué es esto...?",
  ui_story_1011_10111401_70_dialog_content = "¿Una estatua? ¿Una maquina?",
  ui_story_1011_10111401_71_dialog_content = "¿Se puede mover...?",
  ui_story_1011_10111401_72_dialog_content = "Debe estar... roto...",
  ui_story_1011_10111401_73_dialog_content = "<color=#e8d9bb>Clic clic...</color>",
  ui_story_1011_10111401_74_dialog_content = "Parece de esa manera.",
  ui_story_1011_10111401_75_dialog_content = "PlayerName, ¡Prepárate para una pelea!",
  ui_story_1011_10111401_76_dialog_content = "Hola, Neural Aux... ¿es demasiado tarde para hablar de esto?",
  ui_story_1011_10111401_77_dialog_content = "\"Guardian System\" ha comenzado el proceso de corrección.",
  ui_story_1011_10111401_78_dialog_content = "Corrección de comandos ilegales, o \nel usuario ilegal.",
  ui_story_1011_10111402_1_dialog_content = "Que tipo tan duro.",
  ui_story_1011_10111402_2_dialog_content = "Puede contrarrestar la Luminática.",
  ui_story_1011_10111402_3_dialog_content = "No saldremos de esto pronto.",
  ui_story_1011_10111402_4_dialog_content = "¿Puedes aguantar? Carleen?",
  ui_story_1011_10111402_5_dialog_content = "Estoy bien, pero...",
  ui_story_1011_10111402_6_dialog_content = "Vice está acostado justo a mi lado. Estoy preocupado por ella.",
  ui_story_1011_10111402_7_dialog_content = "¿Hay alguna manera de terminar esta batalla rápido?",
  ui_story_1011_10111402_8_dialog_content = "Iniciando autodiagnóstico en las instalaciones del Obelisco del Retorno.",
  ui_story_1011_10111402_9_dialog_content = "Advertencia: Daño crítico. La mayoría de las áreas no funcionan.",
  ui_story_1011_10111402_10_dialog_content = "\"Programa de Control de Daños\" activado. Intentando reparaciones.",
  ui_story_1011_10111402_11_dialog_content = "!",
  ui_story_1011_10111402_12_dialog_content = "Carleen, ¡Se detuvo!",
  ui_story_1011_10111402_13_dialog_content = "¡Ahora! ¡Vuelve a su espalda!",
  ui_story_1011_10111402_14_dialog_content = "¡Entendido!",
  ui_story_1011_10111402_15_dialog_content = "Guardian System sigue activo.",
  ui_story_1011_10111402_16_dialog_content = "Saltar programa. Continuar el comando de reparación.",
  ui_story_1011_10111402_17_dialog_content = "Bip... Bip... Bip...",
  ui_story_1011_10111402_18_dialog_content = "<color=#e8d9bb>¡Hacer clic!</color>",
  ui_story_1011_10111402_19_dialog_content = "Carleen, se está moviendo de nuevo! ¡Ten cuidado!",
  ui_story_1011_10111402_20_dialog_content = "Es todo lo que necesito.",
  ui_story_1011_10111402_21_dialog_content = "¡Tecnología antigua, conozca la Luminática del futuro!",
  ui_story_1011_10111402_22_dialog_content = "Uf... ¿Lo conseguimos?",
  ui_story_1011_10111402_23_dialog_content = "Sí, está abajo.",
  ui_story_1011_10111402_24_dialog_content = "No te rindas.",
  ui_story_1011_10111402_25_dialog_content = "Hemos visto las capacidades defensivas del Obelisco del Retorno.",
  ui_story_1011_10111402_26_dialog_content = "Ahora que somos considerados hostiles, puede haber más por venir.",
  ui_story_1011_10111402_27_dialog_content = "¿No puedo ser...?",
  ui_story_1011_10111402_28_dialog_content = "Realmente espero que no guarde rencor.",
  ui_story_1011_10111402_29_dialog_content = "¡Timbre! Polla...",
  ui_story_1011_10111402_30_dialog_content = "Reparaciones del programa de control de daños completadas. Funciones principales reparadas.",
  ui_story_1011_10111402_31_dialog_content = "El Obelisco del Retorno ya está reactivado.",
  ui_story_1011_10111402_32_dialog_content = "¿Mmm? ¿Pasó algo enorme sin que nos diéramos cuenta...?",
  ui_story_1011_10111402_33_dialog_content = "Obelisco de los Sistemas de Energía de Retorno: Restaurado.",
  ui_story_1011_10111402_34_dialog_content = "Obelisco de Sistemas de Transmisión de Retorno: Restaurado.",
  ui_story_1011_10111402_35_dialog_content = "Obelisco de Sistemas Sensoriales de Retorno: Restaurado.",
  ui_story_1011_10111402_36_dialog_content = "<color=#e8d9bb>Haga clic... Haga clic... Haga clic... Haga clic...</color>",
  ui_story_1011_10111402_37_dialog_content = "Escuchar, Carleen! ¡La torre está cobrando vida en todas partes a nuestro alrededor!",
  ui_story_1011_10111402_38_dialog_content = "Está funcionando... ¡Toda la torre está funcionando ahora!",
  ui_story_1011_10111402_39_dialog_content = "Esto es increíble.",
  ui_story_1011_10111402_40_dialog_content = "No está muerto... Simplemente...",
  ui_story_1011_10111402_41_dialog_content = "... Tuve un largo sueño.",
  ui_story_1011_10111402_42_dialog_content = "Informe de situación de la torre.",
  ui_story_1011_10111402_43_dialog_content = "Zona de mantenimiento Colossus - Colossus Cantidad: 1. Estado: Reparaciones necesarias.",
  ui_story_1011_10111402_44_dialog_content = "Almacenamiento de componentes Colossus: Dañado. Las reparaciones fallaron.",
  ui_story_1011_10111402_45_dialog_content = "Sala de producción de recursos - Cantidad de personal: 0",
  ui_story_1011_10111402_46_dialog_content = "Instalación de eliminación de residuos - Cantidad de personal: 0",
  ui_story_1011_10111402_47_dialog_content = "Residencial Caelestite - Cantidad de Personal: 0",
  ui_story_1011_10111402_48_dialog_content = "Zona Exiliada - Cantidad de Personal: 0",
  ui_story_1011_10111402_49_dialog_content = "...",
  ui_story_1011_10111402_50_dialog_content = "No hay más Caelestitas, excepto...",
  ui_story_1011_10111402_51_dialog_content = "Núcleo central - Cantidad de personal: 1",
  ui_story_1011_10111402_52_dialog_content = "Sí. Yo.",
  ui_story_1011_10111402_53_dialog_content = "Ha despertado de su letargo.",
  ui_story_1011_10111402_54_dialog_content = "Pero... ¿puede acostumbrarse a la soledad?",
  ui_story_1011_10111402_55_dialog_content = "Secuencia de reinicio iniciada.",
  ui_story_1011_10111402_56_dialog_content = "El Obelisco del Retorno ascenderá una vez más.",
  ui_story_1011_10111402_57_dialog_content = "¿No has tenido suficiente?",
  ui_story_1011_10111402_58_dialog_content = "Uf... uf...",
  ui_story_1011_10111402_59_dialog_content = "¡Oye! ¡No me abandones!",
  ui_story_1011_10111402_60_dialog_content = "¡No es una batalla real hasta que uno de nosotros cae!",
  ui_story_1011_10111402_61_dialog_content = "Estás solo. Estás destinado a fracasar.",
  ui_story_1011_10111402_62_dialog_content = "Esto no es una batalla. Solo estás teniendo una rabieta.",
  ui_story_1011_10111402_63_dialog_content = "(Ella realmente no se da por vencida. Qué terriblemente fuerte es).",
  ui_story_1011_10111402_64_dialog_content = "(La única razón por la que logré aguantar tanto tiempo es porque ella está preocupada).",
  ui_story_1011_10111402_65_dialog_content = "(¿Pero qué tiene en mente? ¿Qué hay en esta torre que significa tanto para ella?)",
  ui_story_1011_10111402_66_dialog_content = "(Olvídalo. Es poco probable que pueda encontrar la respuesta pronto).",
  ui_story_1011_10111402_67_dialog_content = "(Lo único que necesito saber es que tengo que evitar que mi oponente haga lo que quiere hacer).",
  ui_story_1011_10111402_68_dialog_content = "(¡Un soldado no puede acobardarse solo porque el enemigo es poderoso!)",
  ui_story_1011_10111402_69_dialog_content = "Por ahí, ¡Forsakin!",
  ui_story_1011_10111402_70_dialog_content = "¡No me vas a engañar con tácticas como esa!",
  ui_story_1011_10111402_71_dialog_content = "<color=#e8d9bb>¡Kaboom!</color>",
  ui_story_1011_10111402_72_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1011_10111402_73_dialog_content = "¿Hey, qué pasa? ¿Un terremoto?",
  ui_story_1011_10111402_74_dialog_content = "¡Oh vamos! ¡Estamos en medio de una batalla!",
  ui_story_1011_10111402_75_dialog_content = "Espera... Este no es un terremoto ordinario.",
  ui_story_1011_10111402_76_dialog_content = "Esta torre...",
  ui_story_1011_10111402_77_dialog_content = "Toda la torre se está moviendo.",
  ui_story_1011_10111402_78_dialog_content = "¡Todo el humo! *tos tos*",
  ui_story_1011_10111402_79_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1011_10111402_80_dialog_content = "Santo...!",
  ui_story_1011_10111402_81_dialog_content = "¡Esto es mucho peor que un terremoto!",
  ui_story_1011_10111402_82_dialog_content = "¡Por supuesto que es!",
  ui_story_1011_10111402_83_dialog_content = "Lo que estamos a punto de presenciar probablemente solo ocurra una vez cada milenio o más...",
  ui_story_1011_10111402_84_dialog_content = "Esta Torre Blanca nunca estuvo destinada a estar aquí.",
  ui_story_1011_10111402_85_dialog_content = "Debería estar... en algún lugar mucho más alto.",
  ui_story_1011_10111402_86_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1011_10111402_87_dialog_content = "¿¡QUÉ!?",
  ui_story_1011_10111402_88_dialog_content = "¿Estoy tropezando? La enorme torre... ¿¡acaba de levantarse del suelo!?",
  ui_story_1011_10111402_89_dialog_content = "PlayerName! ¡Todavía están ahí!",
  ui_story_1011_10111402_90_dialog_content = "¿Qué han hecho?",
  ui_story_1011_10111402_91_dialog_content = "No puedo creer que realmente exista. Una estructura antigua que todavía funciona.",
  ui_story_1011_10111402_92_dialog_content = "Detrás de la pared... ¿Estoy mirando...?",
  ui_story_1011_10111402_93_dialog_content = "¿Otra era?",
  ui_story_1011_10111402_94_dialog_content = "Entonces, ¿qué es exactamente esta cosa? ¿Lo estudiaste?",
  ui_story_1011_10111402_95_dialog_content = "No necesito responderte.",
  ui_story_1011_10111402_96_dialog_content = "(eclipsiano) Forsakin... Forsakin!",
  ui_story_1011_10111402_97_dialog_content = "(Eclipsian) Hay un hueco en la pared exterior de la Torre Blanca.",
  ui_story_1011_10111402_98_dialog_content = "Un hueco... Gran noticia.",
  ui_story_1011_10111402_99_dialog_content = "Ya no necesito entretener a este lunático.",
  ui_story_1011_10111402_100_dialog_content = "¡Oye! ¡No puedes simplemente alejarte de mí!",
  ui_story_1011_10111402_101_dialog_content = "¡Aún no hemos terminado!",
  ui_story_1011_10111402_101X1_dialog_content = "(Te apuesto PlayerName está haciendo algo muy significativo.)",
  ui_story_1011_10111402_101X2_dialog_content = "(No puedo dejar Forsakin molestarlos. ¡Eso es seguro!)",
  ui_story_1011_10111402_102_dialog_content = "¡Qué esta pasando! ¡Esto es un temblor serio!",
  ui_story_1011_10111402_103_dialog_content = "¡Agárrate a algo! ¡Y cuidado con los escombros que caen!",
  ui_story_1011_10111402_104_dialog_content = "Qué pasa Vice!?",
  ui_story_1011_10111402_105_dialog_content = "Déjala a mí. ¡Yo me ocuparé de ella!",
  ui_story_1011_10111402_106_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1011_10111402_107_dialog_content = "Uf... Uf... Finalmente se detuvo...",
  ui_story_1011_10111402_108_dialog_content = "Estás bien, Carleen?",
  ui_story_1011_10111402_109_dialog_content = "Estoy bien. Vice está bien... En cuanto a ti...",
  ui_story_1011_10111402_110_dialog_content = "Puedes soltar esa plataforma de piedra ahora.",
  ui_story_1011_10111402_111_dialog_content = "Cierto.",
  ui_story_1011_10111402_112_dialog_content = "Entonces, ¿qué pasó esta vez?",
  ui_story_1011_10111402_113_dialog_content = "Creo que nos estábamos moviendo hacia arriba en este momento.",
  ui_story_1011_10111402_114_dialog_content = "Yo también siento lo mismo.",
  ui_story_1011_10111402_115_dialog_content = "El Obelisco del Retorno, reinicio de posición.",
  ui_story_1011_10111402_116_dialog_content = "Reportando estado al gerente...",
  ui_story_1011_10111402_117_dialog_content = "¿La torre cambió de posición? ¿Es eso lo que significa \"reiniciar\"?",
  ui_story_1011_10111402_118_dialog_content = "¿Cómo se podría hacer?",
  ui_story_1011_10111402_119_dialog_content = "Informe fallido. Administrador no encontrado.",
  ui_story_1011_10111402_120_dialog_content = "Iniciar procedimiento de copia de seguridad. Localización del usuario que inició el comando de reinicio.",
  ui_story_1011_10111402_121_dialog_content = "Usuario confirmado como usuario ilegal \"Palapong\".",
  ui_story_1011_10111402_122_dialog_content = "No me vas a dar más problemas, ¿verdad?",
  ui_story_1011_10111402_123_dialog_content = "Procedimiento de copia de seguridad iniciado. Promoción del usuario \"Palapong\" al estado de administrador.",
  ui_story_1011_10111402_124_dialog_content = "Acceso interno otorgado a \"Palapong\".",
  ui_story_1011_10111402_125_dialog_content = "¿Eh?",
  ui_story_1011_10111402_126_dialog_content = "Pensé que era un usuario ilegal, pero ¿ahora soy administrador?",
  ui_story_1011_10111402_127_dialog_content = "¿Qué puede hacer un gerente?",
  ui_story_1011_10111402_128_dialog_content = "El administrador puede controlar la mayoría de las funciones del Obelisco del Retorno a través de la unidad Neural Aux.",
  ui_story_1011_10111402_129_dialog_content = "Ok...",
  ui_story_1011_10111402_130_dialog_content = "¡Esperar! ¡Me estás hablando normalmente otra vez!",
  ui_story_1011_10111402_131_dialog_content = "Afirmativo.",
  ui_story_1011_10111402_132_dialog_content = "Entonces, ¿qué fue eso?",
  ui_story_1011_10111402_133_dialog_content = "Los usuarios normales solo pueden ingresar comandos en Central Core y no pueden interactuar con Neural Aux.",
  ui_story_1011_10111402_134_dialog_content = "Solo un administrador tiene acceso a Neural Aux en cualquier momento.",
  ui_story_1011_10111402_135_dialog_content = "Oh, veo cómo amas a una persona en el poder.",
  ui_story_1011_10111402_136_dialog_content = "No entiendo.",
  ui_story_1011_10111402_137_dialog_content = "No importa...",
  ui_story_1011_10111402_138_dialog_content = "Pero los comandos... ¡Esos comandos eran completamente inexactos!",
  ui_story_1011_10111402_139_dialog_content = "Quiero decir, solo mira mi nombre de usuario, ¿Palapong? ¡¿Dime cómo es eso correcto?!",
  ui_story_1011_10111402_140_dialog_content = "El sistema de entrada de comandos no funcionaba correctamente. Este problema ya ha sido reparado.",
  ui_story_1011_10111402_141_dialog_content = "Me disculpo por los inconvenientes.",
  ui_story_1011_10111402_142_dialog_content = "No se trataba de meros \"inconvenientes\".",
  ui_story_1011_10111402_143_dialog_content = "¿Y qué quiso decir con \"acceso interno\"?",
  ui_story_1011_10111402_144_dialog_content = "La información y funciones del Obelisco del Retorno se dividen en tres niveles de acceso.",
  ui_story_1011_10111402_145_dialog_content = "<color=#FFB400>Anillo exterior</color> es accesible para los usuarios normales.",
  ui_story_1011_10111402_146_dialog_content = "<color=#FFB400>Anillo interior</color> sólo es accesible para el administrador.",
  ui_story_1011_10111402_147_dialog_content = "<color=#FFB400>Anillo central</color> es el nivel del Decreto Supremo, no accesible a ningún usuario.",
  ui_story_1011_10111402_148_dialog_content = "En otras palabras, ¿ahora tengo todos los accesos excepto el Core Ring?",
  ui_story_1011_10111402_149_dialog_content = "Afirmativo.",
  ui_story_1011_10111402_150_dialog_content = "Ahora tiene acceso al anillo interior. Sincronizándote con el Obelisco del Retorno.",
  ui_story_1011_10111402_151_dialog_content = "¿eh? ¿Qué vas a hacer?",
  ui_story_1011_10111402_152_dialog_content = "¡Todos estos términos me están confundiendo!",
  ui_story_1011_10111402_153_dialog_content = "No es necesario que se confunda. Abre tu mente y conéctate.",
  ui_story_1011_10111402_154_dialog_content = "El Obelisco del Retorno te servirá de ojos.",
  ui_story_1011_10111402_155_dialog_content = "Qué es esto...?",
  ui_story_1011_10111402_156_dialog_content = "¡Esa es una torre enorme! ¿Ese es todo el Obelisco del Retorno?",
  ui_story_1011_10111402_157_dialog_content = "Esa... Esa es la entrada de la cueva que volamos.",
  ui_story_1011_10111402_158_dialog_content = "¡Así que era parte de la Torre Blanca!",
  ui_story_1011_10111402_159_dialog_content = "PlayerName, se puede ver el exterior de la torre?",
  ui_story_1011_10111402_160_dialog_content = "¡Sip!",
  ui_story_1011_10111402_161_dialog_content = "¡Esto es increíble! ¡Se siente como si estuviera volando!",
  ui_story_1011_10111402_162_dialog_content = "Puedes ver más lejos.",
  ui_story_1011_10111402_163_dialog_content = "Más... Mucho más lejos.",
  ui_story_1011_10111501_1_dialog_content = "¡Ahí! ¡Por ahí!",
  ui_story_1011_10111501_2_dialog_content = "Lo comprobé ya lo hizo. ¡No hay nada!",
  ui_story_1011_10111501_3_dialog_content = "Entonces que es...",
  ui_story_1011_10111501_4_dialog_content = "¡Necesitaremos a alguien en esto!",
  ui_story_1011_10111501_5_dialog_content = "Esto no es algo que podamos resolver solos.",
  ui_story_1011_10111501_6_dialog_content = "¡Derecha! ¡Llama a la Guardia Nocturna! ¡Llama a la Guardia Nocturna!",
  ui_story_1011_10111501_7_dialog_content = "¡Seguramente pueden manejar problemas como este!",
  ui_story_1011_10111501_8_dialog_content = "Eso es... Eso es Damocles...",
  ui_story_1011_10111501_9_dialog_content = "Nadine, informe de situación.",
  ui_story_1011_10111501_10_dialog_content = "Si mi señor.",
  ui_story_1011_10111501_11_dialog_content = "Nuestros guardias informaron irregularidades provenientes de la dirección de la sala de control hace unos diez minutos.",
  ui_story_1011_10111501_12_dialog_content = "No se han encontrado con situaciones similares. Entraron en pánico después de no poder identificar los problemas.",
  ui_story_1011_10111501_13_dialog_content = "Sin embargo, llegaron a una conclusión.",
  ui_story_1011_10111501_14_dialog_content = "<color=#FFB400>Damocles</color> se está activando.",
  ui_story_1011_10111501_15_dialog_content = "Damocles de nuevo.",
  ui_story_1011_10111501_16_dialog_content = "¿Quién está tratando de activarlo esta vez?",
  ui_story_1011_10111501_17_dialog_content = "Nadie.",
  ui_story_1011_10111501_18_dialog_content = "¡¿?!",
  ui_story_1011_10111501_19_dialog_content = "Los guardias hicieron una búsqueda minuciosa. No han encontrado a nadie.",
  ui_story_1011_10111501_20_dialog_content = "Damocles activado por sí mismo.",
  ui_story_1011_10111501_21_dialog_content = "¿Qué estás pensando?",
  ui_story_1011_10111501_22_dialog_content = "¿Cuál es la situación de Damocles en este momento?",
  ui_story_1011_10111501_23_dialog_content = "Está ejecutando procedimientos de inicio. Está cargando a Lumina.",
  ui_story_1011_10111501_24_dialog_content = "Bueno. Entiendo.",
  ui_story_1011_10111501_25_dialog_content = "Nadine, corta el enlace Lumina entre Damocles y Lumopolis, ahora mismo.",
  ui_story_1011_10111501_26_dialog_content = "No hay necesidad de preocuparse por las consecuencias. Solo hazlo.",
  ui_story_1011_10111501_27_dialog_content = "Si mi señor.",
  ui_story_1011_10111501_28_dialog_content = "Irridon, toma a tus hombres y cierra este lugar. No dejes que nadie se acerque a la sala de control.",
  ui_story_1011_10111501_29_dialog_content = "Especialmente el Consejo de Ancianos... Cómo les encanta darnos más dolores de cabeza en momentos de problemas...",
  ui_story_1011_10111501_30_dialog_content = "Si mi señor.",
  ui_story_1011_10111501_31_dialog_content = "Pero estoy pensando si primero deberíamos confirmar la precisión de la información.",
  ui_story_1011_10111501_32_dialog_content = "Las consecuencias de cortar Damocles y bloquear la sala de control son enormes.",
  ui_story_1011_10111501_33_dialog_content = "Solo si fuera algo que pudiera hacer castigar a unos pocos guardias...",
  ui_story_1011_10111501_34_dialog_content = "Pero dudo que ese sea el caso.",
  ui_story_1011_10111501_35_dialog_content = "No correré ningún riesgo de que Damocles pueda estar disparando en cualquier momento. Todas las demás preocupaciones son secundarias.",
  ui_story_1011_10111501_36_dialog_content = "Entendido, Mi Señor.",
  ui_story_1011_10111501_37_dialog_content = "Cuatro Ángeles, conmigo.",
  ui_story_1011_10111501_38_dialog_content = "¡Sí señor!",
  ui_story_1011_10111501_39_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_1011_10111501_40_dialog_content = "¡Otro pulso de Lumina!",
  ui_story_1011_10111501_41_dialog_content = "Pero... ¡Los niveles de energía de Damocles están cayendo!",
  ui_story_1011_10111501_42_dialog_content = "Bien. ¿Qué hay de la tuya?",
  ui_story_1011_10111501_43_dialog_content = "Podemos aguantar... ¡pero no por mucho tiempo!",
  ui_story_1011_10111501_44_dialog_content = "Estamos dando todo lo que tenemos...",
  ui_story_1011_10111501_45_dialog_content = "Mi pecho se siente como... está ardiendo...",
  ui_story_1011_10111501_46_dialog_content = "...",
  ui_story_1011_10111501_47_dialog_content = "Ya veo.",
  ui_story_1011_10111501_48_dialog_content = "Lo terminaremos esta vez.",
  ui_story_1011_10111501_49_dialog_content = "¡Todos, liberen a Lumina para que interfiera con la transmisión de Damocles!",
  ui_story_1011_10111501_50_dialog_content = "¡Haz todo lo que puedas para revertir sus operaciones!",
  ui_story_1011_10111501_51_dialog_content = "¡Sí señor!",
  ui_story_1011_10111501_52_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_1011_10111501_53_dialog_content = "<color=#e8d9bb>Brr...</color>",
  ui_story_1011_10111501_54_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10111501_55_dialog_content = "Huff... Huff...",
  ui_story_1011_10111501_56_dialog_content = "¿Lo... detuvimos...?",
  ui_story_1011_10111501_57_dialog_content = "Nosotros... todo... incinerado...",
  ui_story_1011_10111501_58_dialog_content = "...",
  ui_story_1011_10111501_59_dialog_content = "Mi Señor, ¿está resuelto el problema?",
  ui_story_1011_10111501_60_dialog_content = "Sí, hemos terminado en esta sala.",
  ui_story_1011_10111501_61_dialog_content = "Dicho esto...",
  ui_story_1011_10111501_62_dialog_content = "Damocles...",
  ui_story_1011_10111501_63_dialog_content = "¿Cuál es tu objetivo previsto...?",
  ui_story_1011_10111501_64_dialog_content = "<color=#e8d9bb>Zumbido, zumbido...</color>",
  ui_story_1011_10111501_65_dialog_content = "Eso es... tan... ¡RUIDOSO!",
  ui_story_1011_10111501_66_dialog_content = "*Sollozos* Solo quiero una buena siesta...",
  ui_story_1011_10111501_67_dialog_content = "¿Hm? ¿Philyshy?",
  ui_story_1011_10111501_68_dialog_content = "Te estás quedando dormido en el trabajo otra vez, ¿no?",
  ui_story_1011_10111501_69_dialog_content = "¿De qué está hablando, señor? ¡Estoy bien despierto!",
  ui_story_1011_10111501_70_dialog_content = "No importa... Esta vez.",
  ui_story_1011_10111501_71_dialog_content = "Pero, ¿qué es ese ruidoso sonido...?",
  ui_story_1011_10111501_72_dialog_content = "<color=#e8d9bb>Zumbido, zumbido...</color>",
  ui_story_1011_10111501_73_dialog_content = "Ese sonido... ¡Me está poniendo de los nervios! ¿¡Qué es!?",
  ui_story_1011_10111501_74_dialog_content = "¡Oye! ¡Alguien!",
  ui_story_1011_10111501_75_dialog_content = "Oh, comandante Sharona.",
  ui_story_1011_10111501_76_dialog_content = "Tú también...?",
  ui_story_1011_10111501_77_dialog_content = "Vivian, ¿sabes lo que está pasando?",
  ui_story_1011_10111501_78_dialog_content = "Ni idea. Nunca escuché algo así.",
  ui_story_1011_10111501_79_dialog_content = "Nadie sabe nada.",
  ui_story_1011_10111501_80_dialog_content = "No me digas que tengo que sufrir ruidos de Gannon como este fuera del campo de batalla...",
  ui_story_1011_10111501_81_dialog_content = "Algo debe haber fallado en alguna parte. ¡Conseguiré a alguien de inmediato!",
  ui_story_1011_10111501_82_dialog_content = "<color=#e8d9bb>Zumbido, zumbido...</color>",
  ui_story_1011_10111501_83_dialog_content = "Así que esa es la situación en este momento. Todo Gannon puede oírlo.",
  ui_story_1011_10111501_84_dialog_content = "Um-hum...",
  ui_story_1011_10111501_85_dialog_content = "Nuestros chicos de mantenimiento dijeron que proviene de algún equipo antiguo dentro de la pared.",
  ui_story_1011_10111501_86_dialog_content = "Fueron catalogados como defectuosos y desechados... Nadie esperaba que fueran capaces de hacer este tipo de ruido.",
  ui_story_1011_10111501_87_dialog_content = "Um-hum...",
  ui_story_1011_10111501_88_dialog_content = "Gronru, ¿esta usted escuchando?",
  ui_story_1011_10111501_89_dialog_content = "Um-hum... Estoy escuchando.",
  ui_story_1011_10111501_90_dialog_content = "Estás hablando de eso... Sí. Esa cosa.",
  ui_story_1011_10111501_91_dialog_content = "¡No estás escuchando nada!",
  ui_story_1011_10111501_92_dialog_content = "¡Deja el libro! ¡Esto es importante!",
  ui_story_1011_10111501_93_dialog_content = "¡Los ruidos han causado pánico en la ciudad!",
  ui_story_1011_10111501_94_dialog_content = "No hay nada que nuestros equipos técnicos puedan hacer. Puede...",
  ui_story_1011_10111501_95_dialog_content = "¡Cállate!",
  ui_story_1011_10111501_96_dialog_content = "!?",
  ui_story_1011_10111501_97_dialog_content = "<color=#e8d9bb>Zumbido, zumbido...</color>",
  ui_story_1011_10111501_98_dialog_content = "Ya veo.",
  ui_story_1011_10111501_99_dialog_content = "Sí. Entiendo ahora. En realidad.",
  ui_story_1011_10111501_100_dialog_content = "¿Hmm? ¿Que entendiste tu?",
  ui_story_1011_10111501_101_dialog_content = "No te apagues solo porque te duele escuchar... ¡pero ESCUCHA atentamente!",
  ui_story_1011_10111501_102_dialog_content = "No es solo ruido. Hay un mensaje oculto...",
  ui_story_1011_10111501_103_dialog_content = "¿Un mensaje oculto?",
  ui_story_1011_10111501_104_dialog_content = "En un idioma muy antiguo, sí.",
  ui_story_1011_10111501_105_dialog_content = "Déjame ver... Página 302... Página 564...",
  ui_story_1011_10111501_106_dialog_content = "¡Ahí está!",
  ui_story_1011_10111501_107_dialog_content = "Diría que es una conjetura educada de los idiomas antiguos en el mejor de los casos...",
  ui_story_1011_10111501_108_dialog_content = "Pero creo que significa algo como...",
  ui_story_1011_10111501_109_dialog_content = "<color=#FFB400>\"Esconder ahora.\"</color>",
  ui_story_1011_10111501_110_dialog_content = "Ya voy, Brock.",
  ui_story_1011_10111501_111_dialog_content = "¡Humph! ¿Estás preparado para perder?",
  ui_story_1011_10111501_112_dialog_content = "¡Eso es lo que debería estar diciéndole, General Ever-Lost!",
  ui_story_1011_10111501_113_dialog_content = "¡Ya no llevaré ese título vergonzoso!",
  ui_story_1011_10111501_114_dialog_content = "Hoy todos me verán latir Sinsa, ¡justo y cuadrado!",
  ui_story_1011_10111501_115_dialog_content = "¡Vaya! Me gusta la confianza que tienes.",
  ui_story_1011_10111501_116_dialog_content = "¿Pero todos?",
  ui_story_1011_10111501_117_dialog_content = "Así es. Llamé a todos los de Rediesel Wrench aquí.",
  ui_story_1011_10111501_118_dialog_content = "¿Qué? ¿Tener que pelear conmigo frente a todos te da miedo?",
  ui_story_1011_10111501_119_dialog_content = "Creo que te refieres a otra persona... Pero, ¿dónde están todos?",
  ui_story_1011_10111501_120_dialog_content = "No veo un alma.",
  ui_story_1011_10111501_121_dialog_content = "¡Oye! ¡Vamos gente!",
  ui_story_1011_10111501_122_dialog_content = "¡El duelo está por comenzar!",
  ui_story_1011_10111501_123_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10111501_124_dialog_content = "¡Oye!",
  ui_story_1011_10111501_125_dialog_content = "¿Deberíamos aplaudir?",
  ui_story_1011_10111501_126_dialog_content = "Te estamos animando...",
  ui_story_1011_10111501_127_dialog_content = "¡Mi hermano ganará seguro!",
  ui_story_1011_10111501_128_dialog_content = "¿eh? ¿Solo ustedes tres?",
  ui_story_1011_10111501_129_dialog_content = "A nadie le interesa una pelea perdida...",
  ui_story_1011_10111501_130_dialog_content = "¿Por qué no te rindes? Brock?",
  ui_story_1011_10111501_131_dialog_content = "¿¡Cómo podría yo!?",
  ui_story_1011_10111501_132_dialog_content = "¡Hermano, golpéalo!",
  ui_story_1011_10111501_133_dialog_content = "¡Derecha! no te defraudaré, Eve!",
  ui_story_1011_10111501_134_dialog_content = "¿Dónde te gustaría verlo caer?",
  ui_story_1011_10111501_135_dialog_content = "Sinsa, no se puede pelear encima del Lepidoz?",
  ui_story_1011_10111501_136_dialog_content = "No importa la multitud... ¡No necesito un cuervo de todos modos!",
  ui_story_1011_10111501_137_dialog_content = "¡Después les contaré a todos sobre mi impecable victoria!",
  ui_story_1011_10111501_138_dialog_content = "¡Ja ja! ¡Ven a mí!",
  ui_story_1011_10111501_139_dialog_content = "<color=#e8d9bb>¡Kaboom!</color>",
  ui_story_1011_10111501_140_dialog_content = "¡Ahhhhhh!",
  ui_story_1011_10111501_141_dialog_content = "¿Qué está pasando?",
  ui_story_1011_10111501_142_dialog_content = "¡Bopper, no empieces el Lepidoz sin que yo te lo diga!",
  ui_story_1011_10111501_143_dialog_content = "Jefe, estoy aquí...",
  ui_story_1011_10111501_144_dialog_content = "No hay nadie en el Lepidoz excepto tú.",
  ui_story_1011_10111501_145_dialog_content = "¿eh? ¿Entonces qué es esto?",
  ui_story_1011_10111501_146_dialog_content = "Oye, Sinsa, vas a huir?",
  ui_story_1011_10111501_147_dialog_content = "¡Cierra el pico! Se mueve solo⁠—",
  ui_story_1011_10111501_148_dialog_content = "<color=#e8d9bb>¡Kaboom!</color>",
  ui_story_1011_10111501_149_dialog_content = "Waaaaaah! ¡Está acelerando!",
  ui_story_1011_10111501_150_dialog_content = "¡Guau! Esto es más emocionante de lo que imaginaba.",
  ui_story_1011_10111501_151_dialog_content = "Bro huyó de una pelea. El hermano es un cobarde.",
  ui_story_1011_10111501_152_dialog_content = "¡No soy yo! ¡Lo juro! ¡Es el Lepidoz!",
  ui_story_1011_10111501_153_dialog_content = "¡Deja de estar parado! ¡Ven a darme una mano!",
  ui_story_1011_10111501_154_dialog_content = "¡Oye!",
  ui_story_1011_10111501_155_dialog_content = "<color=#e8d9bb>Tu-tum... Tu-tum...</color>",
  ui_story_1011_10111501_156_dialog_content = "Hola. Tengo un correo urgente para el Sr. Istvan aquí para que usted firme.",
  ui_story_1011_10111501_157_dialog_content = "Me lo llevo.",
  ui_story_1011_10111501_158_dialog_content = "Esperar. ¿Quién es el remitente?",
  ui_story_1011_10111501_159_dialog_content = "No está en el sobre.",
  ui_story_1011_10111501_160_dialog_content = "Oh, por favor permítanme explicar.",
  ui_story_1011_10111501_161_dialog_content = "No se requiere el nombre del remitente para un correo urgente dirigido al Sr. Istvan.",
  ui_story_1011_10111501_162_dialog_content = "Esto es solicitado por el Sr. Istvan él mismo.",
  ui_story_1011_10111501_163_dialog_content = "Ya veo.",
  ui_story_1011_10111501_164_dialog_content = "Gracias.",
  ui_story_1011_10111501_165_dialog_content = "Gracias por elegir Courier Union. ¡Hasta luego!",
  ui_story_1011_10111501_166_dialog_content = "¡Hola! Un correo urgente para el Sr. Istvan. ¡Por favor, fírmelo!",
  ui_story_1011_10111501_167_dialog_content = "Bueno. ¿Otro?",
  ui_story_1011_10111501_168_dialog_content = "Entonces... la razón por la que no hay un nombre de remitente es que...",
  ui_story_1011_10111501_169_dialog_content = "Lo pide el Sr. Istvan él mismo, ¿correcto?",
  ui_story_1011_10111501_170_dialog_content = "¡Correcto!",
  ui_story_1011_10111501_171_dialog_content = "Puedes dejarlo conmigo. Gracias.",
  ui_story_1011_10111501_172_dialog_content = "¡No hay problema! ¡Ahora despues!",
  ui_story_1011_10111501_173_dialog_content = "¡Ahhhhh! ¡Llego tarde, llego tarde!",
  ui_story_1011_10111501_174_dialog_content = "Espero no llegar demasiado tarde y que no me descuenten el sueldo.",
  ui_story_1011_10111501_175_dialog_content = "Oye, estás aquí también, Dove?",
  ui_story_1011_10111501_176_dialog_content = "Yo, Tweety! Tú...",
  ui_story_1011_10111501_177_dialog_content = "Hablaremos más tarde. Llego tarde como es.",
  ui_story_1011_10111501_178_dialog_content = "Hola. Tengo un correo urgente para el Sr. Istvan aquí para que usted firme.",
  ui_story_1011_10111501_179_dialog_content = "Padre, acabo de recibir algunos correos urgentes para usted de Courier Union.",
  ui_story_1011_10111501_180_dialog_content = "¿Correos urgentes? Tráemelos.",
  ui_story_1011_10111501_181_dialog_content = "Aquí tienes.",
  ui_story_1011_10111501_182_dialog_content = "Múltiples correos urgentes a la vez...",
  ui_story_1011_10111501_183_dialog_content = "Entonces, ¿qué hizo que los gorriones entraran en pánico de esta manera?",
  ui_story_1011_10111501_184_dialog_content = "...",
  ui_story_1011_10111501_185_dialog_content = "Parece que no son solo los gorriones.",
  ui_story_1011_10111501_186_dialog_content = "Sheol, envía más gente para rastrear todo lo que sucede en Lumopolis.",
  ui_story_1011_10111501_187_dialog_content = "Quiero cada detalle hasta el soldado que sacó su espada.",
  ui_story_1011_10111501_188_dialog_content = "Considérelo hecho.",
  ui_story_1011_10111501_189_dialog_content = "¿Pero no deberíamos hacer alguna otra preparación?",
  ui_story_1011_10111501_190_dialog_content = "Puede que sea demasiado tarde si esperamos a que Lumopolis actúe.",
  ui_story_1011_10111501_191_dialog_content = "El curso de acción en este momento es suficiente.",
  ui_story_1011_10111501_192_dialog_content = "Residimos en las sombras de Lumopolis.",
  ui_story_1011_10111501_193_dialog_content = "Y una sombra debe conocer su lugar.",
  ui_story_1011_10111501_194_dialog_content = "<color=#e8d9bb>papá...</color>",
  ui_story_1011_10111501_195_dialog_content = "Dama Victoria, ¿estás bien?",
  ui_story_1011_10111501_196_dialog_content = "...",
  ui_story_1011_10111501_197_dialog_content = "Todavía sin respuesta.",
  ui_story_1011_10111501_198_dialog_content = "¿Deberíamos entrar?",
  ui_story_1011_10111501_199_dialog_content = "La mirada de la dama Victoria antes me tenía preocupado.",
  ui_story_1011_10111501_200_dialog_content = "No absolutamente no...",
  ui_story_1011_10111501_201_dialog_content = "No podemos entrar en Lady Victoriala habitación sin permiso. Eso es una violación grave...",
  ui_story_1011_10111501_202_dialog_content = "No hay necesidad de preocuparse. Dama Victoria podría estar cansado.",
  ui_story_1011_10111501_203_dialog_content = "¿No tenéis nada mejor que hacer que preocuparos por ella?",
  ui_story_1011_10111501_204_dialog_content = "Intentaré tocar una vez más.",
  ui_story_1011_10111501_205_dialog_content = "<color=#e8d9bb>Toc Toc...</color>",
  ui_story_1011_10111501_206_dialog_content = "Dama Victoria, ¿estás bien ahí dentro?",
  ui_story_1011_10111501_207_dialog_content = "...",
  ui_story_1011_10111501_208_dialog_content = "Parece que...",
  ui_story_1011_10111501_209_dialog_content = "Faust, entra aquí.",
  ui_story_1011_10111501_210_dialog_content = "!",
  ui_story_1011_10111501_211_dialog_content = "Tu solo. No quiero que se moleste.",
  ui_story_1011_10111501_212_dialog_content = "Sí, señora...",
  ui_story_1011_10111501_213_dialog_content = "<color=#e8d9bb>*cruje*</color>",
  ui_story_1011_10111501_214_dialog_content = "Dama Victoria, tú...",
  ui_story_1011_10111501_215_dialog_content = "Mira.",
  ui_story_1011_10111501_216_dialog_content = "Cómo fluye la sangre de la Biblia sangrienta.",
  ui_story_1011_10111501_217_dialog_content = "Ha estado fluyendo desde hace un tiempo.",
  ui_story_1011_10111501_218_dialog_content = "¿Significa esto... que una nueva profecía está a punto de ser revelada?",
  ui_story_1011_10111501_219_dialog_content = "Está tomando más tiempo que antes.",
  ui_story_1011_10111501_220_dialog_content = "La alfombra ya está empapada de sangre, pero nada aparece en sus páginas.",
  ui_story_1011_10111501_221_dialog_content = "¿Qué podría ser, que incluso a la Verdad le resultaría difícil descifrar en palabras?",
  ui_story_1011_10111501_222_dialog_content = "Cómo podría ser esto...?",
  ui_story_1011_10111501_223_dialog_content = "¿Alguna vez te has encontrado con algo así en toda tu vida?",
  ui_story_1011_10111501_224_dialog_content = "¡Cállate!",
  ui_story_1011_10111501_225_dialog_content = "Está viniendo.",
  ui_story_1011_10111501_226_dialog_content = "Finalmente. Está viniendo.",
  ui_story_1011_10111501_227_dialog_content = "!",
  ui_story_1011_10111501_228_dialog_content = "\"■■\"",
  ui_story_1011_10111501_229_dialog_content = "\"■■■■■■■■■■\"",
  ui_story_1011_10111501_230_dialog_content = "¿¡Qué!?",
  ui_story_1011_10111501_231_dialog_content = "¡Nunca había visto este idioma antes! Señora Victoria, ¿qué significa esto?",
  ui_story_1011_10111501_232_dialog_content = "Biblia sangrienta.",
  ui_story_1011_10111501_233_dialog_content = "Lo que nos estás mostrando no es para nuestros ojos, ¿verdad?",
  ui_story_1011_10111501_234_dialog_content = "Entonces, ¿para quién es esto, el destinado a recibir la profecía...?",
  ui_story_1011_10111501_235_dialog_content = "Guau... Es tan brillante.",
  ui_story_1011_10111501_236_dialog_content = "¿Eh? Pensé que el sol acababa de ponerse...",
  ui_story_1011_10111501_237_dialog_content = "¡Ese no es el sol!",
  ui_story_1011_10111501_238_dialog_content = "Parece que... viene del faro junto al mar.",
  ui_story_1011_10111501_239_dialog_content = "¡Estás en lo correcto!",
  ui_story_1011_10111501_240_dialog_content = "Pero no recuerdo que alguna vez haya sido tan brillante.",
  ui_story_1011_10111501_241_dialog_content = "Novio, ¿está Su Majestad en el Palacio de Invierno?",
  ui_story_1011_10111501_242_dialog_content = "Ella es.",
  ui_story_1011_10111501_243_dialog_content = "Estás sudando mucho. ¿Qué esta pasando?",
  ui_story_1011_10111501_244_dialog_content = "El brillo de la baliza es anormal. Estoy preocupado...",
  ui_story_1011_10111501_245_dialog_content = "Tal vez las fuerzas que custodiaban Northland tuvieron algún problema.",
  ui_story_1011_10111501_246_dialog_content = "Ya veo. Este es de hecho un asunto crucial.",
  ui_story_1011_10111501_247_dialog_content = "Venir. Tendremos una audiencia con Su Majestad de inmediato.",
  ui_story_1011_10111501_248_dialog_content = "<color=#e8d9bb>Ta... ta... ta...</color>",
  ui_story_1011_10111501_249_dialog_content = "Su Majestad, Nikinis solicita su audiencia.",
  ui_story_1011_10111501_250_dialog_content = "Ella dice-",
  ui_story_1011_10111501_251_dialog_content = "está mirando—",
  ui_story_1011_10111501_252_dialog_content = "¿Mmm? Su...",
  ui_story_1011_10111501_253_dialog_content = "Está mirando... Está... mirando...",
  ui_story_1011_10111501_254_dialog_content = "Su Majestad está durmiendo.",
  ui_story_1011_10111501_255_dialog_content = "¿Deberíamos despertarla?",
  ui_story_1011_10111501_256_dialog_content = "Naturalmente, Su Majestad querría saber si el Beacon estaba funcionando mal.",
  ui_story_1011_10111501_257_dialog_content = "Acércate a ella y susurráselo al oído.",
  ui_story_1011_10111501_258_dialog_content = "Está bien.",
  ui_story_1011_10111501_259_dialog_content = "¿Su Majestad?",
  ui_story_1011_10111501_260_dialog_content = "El Beacon está brillando tan brillante como el sol en este momento.",
  ui_story_1011_10111501_261_dialog_content = "Todos están preocupados y se preguntan qué está desviando la noche oscura de Northland.",
  ui_story_1011_10111501_262_dialog_content = "Nos está mirando... desde los cielos...",
  ui_story_1011_10111501_263_dialog_content = "El Obelisco... los ojos en el cielo...",
  ui_story_1011_10111501_264_dialog_content = "¿Su Majestad?",
  ui_story_1011_10111501_265_dialog_content = "Corre... escóndete... lo más lejos posible...",
  ui_story_1011_10111501_266_dialog_content = "A las cimas de las montañas... a las islas deshabitadas...",
  ui_story_1011_10111501_267_dialog_content = "Novio, algo anda mal con Su Majestad.",
  ui_story_1011_10111501_268_dialog_content = "Sí.",
  ui_story_1011_10111501_269_dialog_content = "Su Majestad, es hora de despertar.",
  ui_story_1011_10111501_270_dialog_content = "alejate de ese lugar...",
  ui_story_1011_10111501_271_dialog_content = "El Obelisco...",
  ui_story_1011_10111501_272_dialog_content = "Aléjate... de la Ciudad del Obelisco...",
  ui_story_1011_10111501_273_dialog_content = "¡Su Majestad!",
  ui_story_1011_10111501_274_dialog_content = "¡SU MAJESTAD!",
  ui_story_1011_10111501_275_dialog_content = "...",
  ui_story_1011_10111501_276_dialog_content = "Su Majestad, usted...",
  ui_story_1011_10111501_277_dialog_content = "<color=#FFB400>Eres tu, PlayerName.</color>",
  ui_story_1011_10111501_278_dialog_content = "!",
  ui_story_1011_10111501_279_dialog_content = "¡No, Su Majestad! YO-",
  ui_story_1011_10111501_280_dialog_content = "¿Eh?",
  ui_story_1011_10111501_281_dialog_content = "¿Por qué...? ¿Por qué está pasando esto...?",
  ui_story_1011_10111501_282_dialog_content = "¿Qué pasa, PlayerName?",
  ui_story_1011_10111501_283_dialog_content = "¿Que pasa conmigo? YO...",
  ui_story_1011_10111501_284_dialog_content = "Esto va a sonar absurdo, pero...",
  ui_story_1011_10111501_285_dialog_content = "Estoy bastante seguro de que acabo de ver, tan claro como el día...",
  ui_story_1011_10111501_286_dialog_content = "¿Qué viste?",
  ui_story_1011_10111501_287_dialog_content = "Yo vi <color=#FFB400>el mundo entero</color>.",
  ui_story_1012_10120101_1_dialog_content = "Vi el mundo entero en un instante.",
  ui_story_1012_10120101_2_dialog_content = "De Illumina a Lumópolis.",
  ui_story_1012_10120101_3_dialog_content = "Desde Northland hasta el desierto de Rediesel.",
  ui_story_1012_10120101_4_dialog_content = "Lo vi todo.",
  ui_story_1012_10120101_5_dialog_content = "Era como si ya no fuera yo mismo...",
  ui_story_1012_10120101_6_dialog_content = "Pero el propio Obelisco del Retorno.",
  ui_story_1012_10120101_7_dialog_content = "Qué extraño... No hay registros de que los Caelestitas tengan tal tecnología.",
  ui_story_1012_10120101_8_dialog_content = "No importa, no nos centremos en esto por ahora.",
  ui_story_1012_10120101_9_dialog_content = "Si esta máquina es el núcleo de esta base, debería saber cómo ahorrar Vice!",
  ui_story_1012_10120101_10_dialog_content = "¡Derecha! Neural Aux, busque casos que contengan detalles sobre la recuperación del estado de hibernación.",
  ui_story_1012_10120101_11_dialog_content = "Acceso verificado. Generando informe.",
  ui_story_1012_10120101_12_dialog_content = "Los sujetos en estado de hibernación se colocaron dentro del <color=#FFB400>Enlace de acorde</color> para intentar la sincronización con la función Homophony.",
  ui_story_1012_10120101_13_dialog_content = "Los resultados arrojaron efectos terapéuticos positivos inesperados.",
  ui_story_1012_10120101_14_dialog_content = "Se observaron signos de recuperación de la conciencia en los sujetos, junto con cambios físicos.",
  ui_story_1012_10120101_15_dialog_content = "Los efectos secundarios de los cambios físicos siguen sin estar claros.",
  ui_story_1012_10120101_16_dialog_content = "Al final, la homofonización de los sujetos fue exitosa y se recuperaron de la hibernación.",
  ui_story_1012_10120101_17_dialog_content = "enlace de acordes...",
  ui_story_1012_10120101_18_dialog_content = "¿Qué es eso?",
  ui_story_1012_10120101_19_dialog_content = "Buscando información sobre Chord Link.",
  ui_story_1012_10120101_20_dialog_content = "...",
  ui_story_1012_10120101_21_dialog_content = "...",
  ui_story_1012_10120101_22_dialog_content = "#*%￥&￥#&*!",
  ui_story_1012_10120101_23_dialog_content = "¿Auxiliar neuronal?",
  ui_story_1012_10120101_24_dialog_content = "Proceso de error terminado.",
  ui_story_1012_10120101_25_dialog_content = "Los datos experimentales de Chord Link se almacenan en Chord Zone y el acceso público está restringido.",
  ui_story_1012_10120101_26_dialog_content = "¿Por qué se mantiene en secreto con tanta fuerza?",
  ui_story_1012_10120101_27_dialog_content = "Suena como una instalación muy importante.",
  ui_story_1012_10120101_28_dialog_content = "Quizá lo más importante de esta torre blanca no sea el Sistema Circular...",
  ui_story_1012_10120101_29_dialog_content = "Pero este Chord Link.",
  ui_story_1012_10120101_30_dialog_content = "Neural Aux, ¿tienes algún detalle sobre la Chord Zone?",
  ui_story_1012_10120101_31_dialog_content = "El vínculo entre Neural Aux y Chord Zone se cortó. ¡No se pueden leer los datos!",
  ui_story_1012_10120101_32_dialog_content = "La descripción de la base de datos local del dispositivo dice:",
  ui_story_1012_10120101_33_dialog_content = "El Chord Link puede curar heridas y hacer modificaciones en varias partes del cuerpo de un Aurorian para que su verdadero potencial pueda ser desatado...",
  ui_story_1012_10120101_34_dialog_content = "Para que los Aurorianos se coordinen mejor con Caelestites en la batalla.",
  ui_story_1012_10120101_35_dialog_content = "Esto suena como... algún tipo de dispositivo de transformación.",
  ui_story_1012_10120101_36_dialog_content = "Espera, pero no... Si los caelestitas en el pasado veían a los aurorianos como enemigos...",
  ui_story_1012_10120101_37_dialog_content = "¿Por qué hay aquí un dispositivo que puede transformar aurorianos para hacerlos más compatibles con Caelestites en la batalla?",
  ui_story_1012_10120101_38_dialog_content = "Estás bien. Esto es realmente extraño.",
  ui_story_1012_10120101_39_dialog_content = "PlayerName, no podemos simplemente confiar ciegamente en la información que nos dicen.",
  ui_story_1012_10120101_40_dialog_content = "Primero debemos averiguar para qué se utiliza exactamente este Chord Link y, lo que es más importante, si tiene el potencial de dañar a Vice.",
  ui_story_1012_10120101_41_dialog_content = "Sí, tienes razón.",
  ui_story_1012_10120101_42_dialog_content = "Neural Aux, ¿hay algún efecto secundario al usar Chord Link?",
  ui_story_1012_10120101_43_dialog_content = "¿Tendrá algún efecto negativo en Vice?",
  ui_story_1012_10120101_44_dialog_content = "El vínculo entre Neural Aux y Chord Zone se cortó. ¡No se pueden leer los datos!",
  ui_story_1012_10120101_45_dialog_content = "¿Ha pasado tanto tiempo que no has intentado repararlo en todo este tiempo?",
  ui_story_1012_10120101_46_dialog_content = "Neural Aux es solo un sistema utilizado para brindar asistencia a Caelestites.",
  ui_story_1012_10120101_47_dialog_content = "¡Está prohibido forzar al Neural Aux a realizar tareas de mantenimiento que están fuera de los parámetros de sus funciones!",
  ui_story_1012_10120101_48_dialog_content = "Parece que no estamos obteniendo ninguna información relevante de él...",
  ui_story_1012_10120101_49_dialog_content = "Bueno, parece que no hay elección.",
  ui_story_1012_10120101_50_dialog_content = "Tenemos que intentarlo, aunque sea arriesgado.",
  ui_story_1012_10120101_51_dialog_content = "Vice terminó así por mi culpa.",
  ui_story_1012_10120101_52_dialog_content = "Me haré responsable, incluso si...",
  ui_story_1012_10120101_53_dialog_content = "...",
  ui_story_1012_10120101_54_dialog_content = "Cuando llegue el momento, intentaré usar el dispositivo primero.",
  ui_story_1012_10120101_55_dialog_content = "Si no hay problemas, podemos usarlo para salvar a Vice.",
  ui_story_1012_10120101_56_dialog_content = "Pero si no funciona... contaré contigo, Carleen. Lleva a Vice de vuelta a Illumina para buscar ayuda.",
  ui_story_1012_10120101_57_dialog_content = "Aprecio tus sentimientos, pero no olvides que eres Caelestite, no Aurorian.",
  ui_story_1012_10120101_58_dialog_content = "El vicio es mi amigo. Estoy dispuesto a hacer todo lo que pueda para salvarla.",
  ui_story_1012_10120101_59_dialog_content = "Si no tenemos otra opción, déjame ser el sujeto de prueba.",
  ui_story_1012_10120101_60_dialog_content = "Neural Aux, llévame a este dispositivo.",
  ui_story_1012_10120101_61_dialog_content = "Cálculo de la ruta a la Zona de Cuerdas—",
  ui_story_1012_10120101_62_dialog_content = "Ruta detectada. La mayoría de los pasadizos con acceso a la Zona de Cuerdas se han derrumbado. El Gerente debe hacer un desvío a través de la Zona de Exilio para continuar.",
  ui_story_1012_10120101_63_dialog_content = "El vínculo entre Neural Aux y Chord Zone se ha cortado. Neural Aux no puede abrir la puerta directamente.",
  ui_story_1012_10120101_64_dialog_content = "De acuerdo con la configuración más reciente, se ha generado una clave secreta para que el Administrador desbloquee el Control de acceso.",
  ui_story_1012_10120101_65_dialog_content = "Última modificación por: Maestro Francis.",
  ui_story_1012_10120101_66_dialog_content = "¿Otra vez este tipo, el maestro Francis?",
  ui_story_1012_10120101_67_dialog_content = "¿Qué estaba planeando este tipo?",
  ui_story_1012_10120101_68_dialog_content = "No creo que estuviera planeando nada.",
  ui_story_1012_10120101_69_dialog_content = "Parece más como si estuviera allanando el camino para quien vendría después de él.",
  ui_story_1012_10120101_70_dialog_content = "Como nosotros.",
  ui_story_1012_10120101_71_dialog_content = "Administrador, siga a Neural Aux hasta Chord Zone. Neural Aux descifrará el control de acceso de Chord Zone por usted.",
  ui_story_1012_10120101_72_dialog_content = "¿La Chord Zone y la Exile Zone están vinculadas?",
  ui_story_1012_10120101_73_dialog_content = "El lugar suena turbio...",
  ui_story_1012_10120101_74_dialog_content = "Independientemente, es nuestra única esperanza.",
  ui_story_1012_10120101_75_dialog_content = "Vamos. Llevemos Vice a la Chord Zone.",
  ui_story_1012_10120101_76_dialog_content = "Muestra el camino, Neural Aux.",
  ui_story_1012_10120101_77_dialog_content = "¡Sí! ¡Navegación Aux Neural, a tu servicio!",
  ui_story_1012_10120101_78_dialog_content = "enlace de acordes...",
  ui_story_1012_10120101_79_dialog_content = "¿Es esa la tecnología que está enterrada en esta base subterránea?",
  ui_story_1012_10120101_80_dialog_content = "La capacidad de transformar cuerpos aurorianos...",
  ui_story_1012_10120101_81_dialog_content = "Es exactamente lo que quiero.",
  ui_story_1012_10120101_82_dialog_content = "(Eclipsian) Lady Forsakin, ese Illuminan todavía se está acercando a nosotros.",
  ui_story_1012_10120101_83_dialog_content = "(Eclipsian) Es... demasiado poderoso. No podemos detenerlo.",
  ui_story_1012_10120101_84_dialog_content = "Illumina genera monstruos.",
  ui_story_1012_10120101_85_dialog_content = "Si no podemos detenerlo, encuentra una forma de engañarlo.",
  ui_story_1012_10120101_86_dialog_content = "No dejes que ese bufón temerario se acerque a tan valiosa tecnología.",
  ui_story_1012_10120101_87_dialog_content = "Sus células cerebrales solo son capaces de luchar y destruir.",
  ui_story_1012_10120101_88_dialog_content = "(Eclipsian) Entendido.",
  ui_story_1012_10120101_89_dialog_content = "Irridon, no me detengas.",
  ui_story_1012_10120101_90_dialog_content = "El Consejo de Ancianos tiene derecho a saber el motivo de la activación de Damocles.",
  ui_story_1012_10120101_91_dialog_content = "El Señor de la Ciudad ha ordenado que nadie entre en la sala de control.",
  ui_story_1012_10120101_92_dialog_content = "Sus órdenes son ley en Lumopolis. Estoy seguro de que ya lo sabes.",
  ui_story_1012_10120101_93_dialog_content = "Lord Otto, ni siquiera el Consejo de Ancianos está por encima de la ley.",
  ui_story_1012_10120101_94_dialog_content = "Los derechos del Consejo de Ancianos también son parte de la ley de Lumopolis.",
  ui_story_1012_10120101_95_dialog_content = "Juez principal Irridon, debo informarte que ahora eres—",
  ui_story_1012_10120101_96_dialog_content = "¿Damocles se detuvo?",
  ui_story_1012_10120101_97_dialog_content = "(El Señor de la Ciudad y los Cuatro Ángeles... ¿Tuvieron éxito?)",
  ui_story_1012_10120101_98_dialog_content = "Caballero Schwartz...",
  ui_story_1012_10120101_99_dialog_content = "Por favor, dime qué pasó en la sala de control. ¿Por qué Damocles se activaría repentinamente?",
  ui_story_1012_10120101_100_dialog_content = "Relájate, Otto, relájate.",
  ui_story_1012_10120101_101_dialog_content = "Es cierto que Damocles se activó sin previo aviso y autorización, pero lo detuve.",
  ui_story_1012_10120101_102_dialog_content = "Está de nuevo bajo nuestro control ahora.",
  ui_story_1012_10120101_103_dialog_content = "Activación no autorizada... ¿Cómo es eso posible?",
  ui_story_1012_10120101_104_dialog_content = "Damocles es un arma poderosa, pero un arma sigue siendo solo eso.",
  ui_story_1012_10120101_105_dialog_content = "¿Cómo podría autoactivarse sin que nadie lo operara?",
  ui_story_1012_10120101_106_dialog_content = "Debo corregirte en un punto, Otto.",
  ui_story_1012_10120101_107_dialog_content = "Damocles es de hecho un arma de Lumopolis, pero...",
  ui_story_1012_10120101_108_dialog_content = "No pertenece completamente a Lumopolis.",
  ui_story_1012_10120101_109_dialog_content = "...",
  ui_story_1012_10120101_110_dialog_content = "Al final, sigue siendo un remanente de personas antiguas que nunca hemos visto, y algo que Lumopolis rechaza ferozmente.",
  ui_story_1012_10120101_111_dialog_content = "Cuando trabajas con un poder desconocido que no te pertenece, siempre existe la posibilidad de que pierdas el control sobre él.",
  ui_story_1012_10120101_112_dialog_content = "Haré que los técnicos responsables del mantenimiento de Damocles realicen una revisión minuciosa para encontrar la causa de la pérdida de control.",
  ui_story_1012_10120101_113_dialog_content = "Tendré los resultados para mañana.",
  ui_story_1012_10120101_114_dialog_content = "Lo aprecio.",
  ui_story_1012_10120101_115_dialog_content = "Naturalmente. Preservar la seguridad y la prosperidad de Lumopolis es nuestra máxima prioridad.",
  ui_story_1012_10120101_116_dialog_content = "...",
  ui_story_1012_10120101_117_dialog_content = "Damocles...",
  ui_story_1012_10120101_118_dialog_content = "La dirección en la que estás mirando es...",
  ui_story_1012_10120101_119_dialog_content = "...",
  ui_story_1012_10120101_120_dialog_content = "Rafael.",
  ui_story_1012_10120101_121_dialog_content = "¡Ah, s-sí!",
  ui_story_1012_10120101_122_dialog_content = "Señor, ¿tiene órdenes para mí?",
  ui_story_1012_10120101_123_dialog_content = "Ve con Beretta y dile que reúna un equipo de caballeros. Ve a Eraveil de inmediato.",
  ui_story_1012_10120101_124_dialog_content = "Está bien, pero ¿qué quieres que haga Beretta?",
  ui_story_1012_10120101_125_dialog_content = "Dile que improvise y haga lo que sea necesario.",
  ui_story_1012_10120101_126_dialog_content = "¡¿Qué?!",
  ui_story_1012_10120101_127_dialog_content = "Seguir.",
  ui_story_1012_10120101_128_dialog_content = "¡Cierto, okey!",
  ui_story_1012_10120101_129_dialog_content = "Su Majestad...",
  ui_story_1012_10120101_130_dialog_content = "Estoy bien.",
  ui_story_1012_10120101_131_dialog_content = "Mis disculpas por haberte preocupado.",
  ui_story_1012_10120101_132_dialog_content = "Hay algo que debo informar. Hay un problema con el Beacon. Está emitiendo una luz fuerte como ninguna otra.",
  ui_story_1012_10120101_133_dialog_content = "Ya veo.",
  ui_story_1012_10120101_134_dialog_content = "Yo manejaré este asunto. No tienes que preocuparte por eso.",
  ui_story_1012_10120101_135_dialog_content = "Entendido...",
  ui_story_1012_10120101_136_dialog_content = "Su Majestad, mencionó el nombre de Caelestite cuando estaba medio dormido.",
  ui_story_1012_10120101_137_dialog_content = "No fue una coincidencia, ¿verdad?",
  ui_story_1012_10120101_138_dialog_content = "...",
  ui_story_1012_10120101_139_dialog_content = "Lo vi parado en el Obelisco, mirando hacia abajo al mundo.",
  ui_story_1012_10120101_140_dialog_content = "Esa torre es una existencia que incluso yo no puedo comprender.",
  ui_story_1012_10120101_141_dialog_content = "Fue construido en la antigüedad, y sus orígenes son desconocidos.",
  ui_story_1012_10120101_142_dialog_content = "El Obelisco y el Faro que protege Northland son como el fuego y el agua.",
  ui_story_1012_10120101_143_dialog_content = "¿Se ha convertido Caelestite en... nuestro enemigo?",
  ui_story_1012_10120101_144_dialog_content = "No, no sentí ninguna hostilidad viniendo de él.",
  ui_story_1012_10120101_145_dialog_content = "Era el mismo de siempre, puro y amable.",
  ui_story_1012_10120101_146_dialog_content = "Pero me di cuenta de que estaba experimentando algún tipo de dificultad con la que nunca había tenido que lidiar antes.",
  ui_story_1012_10120101_147_dialog_content = "El dilema en el que se encuentra afectará a todo Astra.",
  ui_story_1012_10120101_148_dialog_content = "Northland debe tomar una decisión.",
  ui_story_1012_10120101_149_dialog_content = "Prepara un carruaje.",
  ui_story_1012_10120101_150_dialog_content = "Iré directamente a Eraveil y resolveré este dilema.",
  ui_story_1012_10120101_151_dialog_content = "¡Sí!",
  ui_story_1012_10120101_152_dialog_content = "¡El carruaje está listo, Su Majestad!",
  ui_story_1012_10120101_153_dialog_content = "Nos vamos de una vez.",
  ui_story_1012_10120101_154_dialog_content = "Su Majestad, permítame ir con usted a Eraveil.",
  ui_story_1012_10120101_155_dialog_content = "No, tienes que quedarte.",
  ui_story_1012_10120101_156_dialog_content = "Debes proteger bien a Northland mientras yo no esté aquí. Asegúrese de observar el movimiento de Eclipsite.",
  ui_story_1012_10120101_157_dialog_content = "Todo lo demás procederá como de costumbre. No hay necesidad de poner las cosas en espera solo porque no estoy cerca.",
  ui_story_1012_10120101_158_dialog_content = "Tiare me acompañará.",
  ui_story_1012_10120101_159_dialog_content = "...",
  ui_story_1012_10120101_160_dialog_content = "Tiaré, en espera.",
  ui_story_1012_10120101_161_dialog_content = "Eres tú...",
  ui_story_1012_10120101_162_dialog_content = "Bueno, entonces, por favor proteja bien a Su Majestad. Protege la llama de la esperanza de Northland.",
  ui_story_1012_10120101_163_dialog_content = "R-Informe, ¡miau!",
  ui_story_1012_10120101_164_dialog_content = "Se han reportado extraños ruidos fuertes en todo Gannon.",
  ui_story_1012_10120101_165_dialog_content = "Gronru cree que es una especie de alarma emitida por los instrumentos antiguos en las paredes de Entrañas, ¡miau!",
  ui_story_1012_10120101_166_dialog_content = "Entiendo. Sigue monitoreando la situación en Gannon.",
  ui_story_1012_10120101_167_dialog_content = "Además, pregúntales a las otras Entrañas si han estado experimentando lo mismo.",
  ui_story_1012_10120101_168_dialog_content = "¡Sí, miau!",
  ui_story_1012_10120101_169_dialog_content = "Gran Mariscal, nuestros exploradores han detectado un movimiento sospechoso en el Eclipsite.",
  ui_story_1012_10120101_170_dialog_content = "Todos los Eclipsites de Astra parecen estar congregándose en Eraveil.",
  ui_story_1012_10120101_171_dialog_content = "Comprendido. Mantén las defensas altas en Entrañas y sigue observando.",
  ui_story_1012_10120101_172_dialog_content = "Sí.",
  ui_story_1012_10120101_173_dialog_content = "Reuniones de eclipses, Eraveil y ruidos misteriosos provenientes de tecnología antigua en Gannon...",
  ui_story_1012_10120101_174_dialog_content = "¿Ese niño está en algún tipo de problema otra vez?",
  ui_story_1012_10120101_175_dialog_content = "Je, seguro que sabe cómo elegir un momento.",
  ui_story_1012_10120101_176_dialog_content = "Informes.",
  ui_story_1012_10120101_177_dialog_content = "... Bueno, sabía que eso no era todo lo que íbamos a obtener.",
  ui_story_1012_10120101_178_dialog_content = "Dime. ¿Ahora que?",
  ui_story_1012_10120101_179_dialog_content = "El Comité recibió un informe que decía que una Torre Blanca en Eraveil se activó repentinamente.",
  ui_story_1012_10120101_180_dialog_content = "Después de eso, la tecnología antigua de todo el mundo comenzó a reaccionar colectivamente.",
  ui_story_1012_10120101_181_dialog_content = "¿Oh?",
  ui_story_1012_10120101_182_dialog_content = "Estos incluyen Northland's Beacon, Lumopolis's Damocles, Rediesel Wrench's Lepidoz, y así sucesivamente...",
  ui_story_1012_10120101_183_dialog_content = "El Comité tiene fuertes sospechas de que la anomalía en Gannon está relacionada con estos incidentes.",
  ui_story_1012_10120101_184_dialog_content = "¿Desencadenó reacciones incluso de Beacon y Damocles...?",
  ui_story_1012_10120101_185_dialog_content = "¿Qué has desenterrado, PlayerName...",
  ui_story_1012_10120101_186_dialog_content = "Gran Mariscal, esperamos instrucciones.",
  ui_story_1012_10120101_187_dialog_content = "Déjame pensar.",
  ui_story_1012_10120101_188_dialog_content = "Dile a todos los equipos en la región de Eraveil que avancen hacia la Torre Blanca activada.",
  ui_story_1012_10120101_189_dialog_content = "Si se encuentran eclipses, levanta una barricada y evita que se reúnan.",
  ui_story_1012_10120101_190_dialog_content = "Además, organice una unidad de élite de inmediato. Yo guiaré Tenemos que llegar a Eraveil y averiguar qué está pasando.",
  ui_story_1012_10120101_191_dialog_content = "Sí, iré a la derecha—",
  ui_story_1012_10120101_192_dialog_content = "Con el debido respeto, Gran Mariscal, no te has recuperado de las heridas que sufriste en Entrañas 80. No estás en condiciones de emprender esta misión en este momento.",
  ui_story_1012_10120101_193_dialog_content = "...",
  ui_story_1012_10120101_194_dialog_content = "Anatoli, vuelve al trabajo.",
  ui_story_1012_10120101_195_dialog_content = "Sí.",
  ui_story_1012_10120101_196_dialog_content = "Gran Mariscal Reinhardt, permítame recordarle que aún está bajo revisión por parte del Comité.",
  ui_story_1012_10120101_197_dialog_content = "Actuar impulsivamente podría influir en su evaluación.",
  ui_story_1012_10120101_198_dialog_content = "¿Qué es más importante, una evaluación en una hoja de papel o la seguridad de Illumina?",
  ui_story_1012_10120101_199_dialog_content = "... La seguridad de Illumina es de mayor importancia.",
  ui_story_1012_10120101_200_dialog_content = "Ahora que lo entiendes, ve a hacer tu trabajo.",
  ui_story_1012_10120101_201_dialog_content = "Yo también haré lo mío, como Gran Mariscal.",
  ui_story_1012_10120101_202_dialog_content = "Haré un registro de sus acciones en el informe de investigación.",
  ui_story_1012_10120101_203_dialog_content = "Escribe lo que quieres.",
  ui_story_1012_10120101_204_dialog_content = "La gente de Illumina será el juez final de mis decisiones.",
  ui_story_1012_10120201_1_dialog_content = "Graaahh—",
  ui_story_1012_10120201_2_dialog_content = "¿Ese fue el último?",
  ui_story_1012_10120201_3_dialog_content = "Ugh...",
  ui_story_1012_10120201_4_dialog_content = "No son más que un montón de minions molestos que se interponen en mi camino.",
  ui_story_1012_10120201_5_dialog_content = "¿Adónde en el mundo se ha escapado Forsakin ahora?",
  ui_story_1012_10120201_6_dialog_content = "Tch... Tengo que encontrarla rápido.",
  ui_story_1012_10120201_7_dialog_content = "¿No acabo de estar aquí?",
  ui_story_1012_10120201_8_dialog_content = "¿Por qué estas cosas viejas tienen que estar esparcidas por aquí de manera tan similar?",
  ui_story_1012_10120201_9_dialog_content = "Este lugar es prácticamente un laberinto.",
  ui_story_1012_10120201_10_dialog_content = "¿Podría... ese grupo de Eclipsites haberme atraído aquí a propósito?",
  ui_story_1012_10120201_11_dialog_content = "... ¡Apuesto a que Forsakin planeó esto!",
  ui_story_1012_10120201_12_dialog_content = "¿Quieres detenerme con un laberinto? Mírame romperlo.",
  ui_story_1012_10120201_13_dialog_content = "<color=#e8d9bb>Barra oblicua-!</color>",
  ui_story_1012_10120201_14_dialog_content = "!",
  ui_story_1012_10120201_15_dialog_content = "Hiss-",
  ui_story_1012_10120201_16_dialog_content = "¡Ay, ay, ay—!",
  ui_story_1012_10120201_17_dialog_content = "¿De qué diablos está hecha esta pared? ¿Por qué es tan resistente?",
  ui_story_1012_10120201_18_dialog_content = "Mi hoja no deja marcas en ella y el retroceso me mata la mano.",
  ui_story_1012_10120201_19_dialog_content = "Si tan solo pudiera tomarlo y usarlo para las paredes en Undercities, o montarlo en el tanque y usarlo para lidiar con Eclipsites.",
  ui_story_1012_10120201_20_dialog_content = "Claramente, mi plan de demoler las paredes no va a funcionar.",
  ui_story_1012_10120201_21_dialog_content = "Tengo que pasar por estos pasajes.",
  ui_story_1012_10120201_22_dialog_content = "Pero dado que Forsakin parece estar liderando esos Eclipsites, si me dirijo hacia ellos, estaré en el camino correcto.",
  ui_story_1012_10120201_23_dialog_content = "Sin embargo, solo tengo que pasar más tiempo limpiando la carne de cañón.",
  ui_story_1012_10120201_24_dialog_content = "<color=#e8d9bb>Eraveil: en lo profundo de la base de mantenimiento de Colossus</color>",
  ui_story_1012_10120201_25_dialog_content = "Gire a la derecha en la intersección más adelante.",
  ui_story_1012_10120201_26_dialog_content = "Esta base es enorme...",
  ui_story_1012_10120201_27_dialog_content = "Habríamos perdido varios días en estos complicados pasadizos si no tuviéramos a Neural Aux para guiarnos.",
  ui_story_1012_10120201_28_dialog_content = "Si incluimos el área colapsada, el alcance de esta base subterránea podría cubrir toda el área de Eraveil.",
  ui_story_1012_10120201_29_dialog_content = "Especialmente estas áreas que parecen pasillos extendidos.",
  ui_story_1012_10120201_30_dialog_content = "Este ancho y alto indican claramente que los pasajes no fueron hechos solo para personas.",
  ui_story_1012_10120201_31_dialog_content = "Cuando llegamos aquí por primera vez, todavía estaba confundido, pero ahora creo que lo he descubierto.",
  ui_story_1012_10120201_32_dialog_content = "Estos pasajes podrían haber sido para que pasaran los Colosos.",
  ui_story_1012_10120201_33_dialog_content = "...",
  ui_story_1012_10120201_34_dialog_content = "En cuanto a ti, solo te encargarás de...",
  ui_story_1012_10120201_35_dialog_content = "Creando guerras para el mundo.",
  ui_story_1012_10120201_36_dialog_content = "Caelestites piloteó los Colosos por aquí, pero no por motivos pacíficos...",
  ui_story_1012_10120201_37_dialog_content = "¿Qué son los Caelestitas, realmente?",
  ui_story_1012_10120201_38_dialog_content = "PlayerName.",
  ui_story_1012_10120201_39_dialog_content = "Eres tú mismo, ante todo, antes de tu identidad como Caelestita.",
  ui_story_1012_10120201_40_dialog_content = "¿Eh?",
  ui_story_1012_10120201_41_dialog_content = "Para aquellos de nosotros que vivimos en la actualidad, solo eres tú.",
  ui_story_1012_10120201_42_dialog_content = "La Última Caelestita a quien Vice rescató del subsuelo.",
  ui_story_1012_10120201_43_dialog_content = "El aliado que ayudó a Lumopolis en la lucha contra Schummer y el Coloso Negro.",
  ui_story_1012_10120201_44_dialog_content = "El aliado que ha ido en innumerables aventuras con todos nosotros.",
  ui_story_1012_10120201_45_dialog_content = "Mientras sigas siendo tú, mientras mantengas tu amabilidad y te adhieras a tus principios, no nos importa si eres Caelestite o Aurorian.",
  ui_story_1012_10120201_46_dialog_content = "No elegimos nuestros orígenes. No hay necesidad de que te cargues con la culpa.",
  ui_story_1012_10120201_47_dialog_content = "Carleen...",
  ui_story_1012_10120201_48_option_content = "Gracias por consolarme.",
  ui_story_1012_10120201_49_dialog_content = "Pero todavía tengo que seguir con este asunto.",
  ui_story_1012_10120201_50_dialog_content = "Soy el Último Caelestita.",
  ui_story_1012_10120201_51_dialog_content = "Puede que sea la única persona en este mundo que pueda descubrir los secretos de Eraveil.",
  ui_story_1012_10120201_52_dialog_content = "Si Caelestites realmente fueron máquinas de combate en el pasado, entonces...",
  ui_story_1012_10120201_53_dialog_content = "Tanto Eraveil como la existencia de Caelestites podrían ser una amenaza para el mundo.",
  ui_story_1012_10120201_54_dialog_content = "Es posible que nunca pueda volver a dormir bien si no descifro esto y resuelvo los peligros que podrían estar expuestos al mundo.",
  ui_story_1012_10120201_55_dialog_content = "No quiero que mi existencia amenace la seguridad de mis amigos.",
  ui_story_1012_10120201_56_dialog_content = "...",
  ui_story_1012_10120201_57_dialog_content = "No te esfuerces demasiado.",
  ui_story_1012_10120201_58_dialog_content = "Lo se.",
  ui_story_1012_10120201_59_dialog_content = "No te preocupes, soy consciente de mis límites.",
  ui_story_1012_10120201_60_dialog_content = "<size=30>Cualquier Eclipsite al azar podría enviarme volando con un solo golpe...</size>",
  ui_story_1012_10120201_61_dialog_content = "Definitivamente voy a depender de la ayuda de todos en momentos de necesidad.",
  ui_story_1012_10120201_62_dialog_content = "Bien.",
  ui_story_1012_10120201_63_dialog_content = "<color=#e8d9bb>Barra oblicua-!</color>",
  ui_story_1012_10120201_64_dialog_content = "¡¿Qué fue eso?!",
  ui_story_1012_10120201_65_dialog_content = "¿Podría haber entrado un Eclipsite grande?",
  ui_story_1012_10120201_66_dialog_content = "Suena cerca.",
  ui_story_1012_10120201_67_dialog_content = "Salgamos de aquí rápido y sigamos adelante.",
  ui_story_1012_10120201_68_dialog_content = "Con Vice inconsciente, la lucha será difícil.",
  ui_story_1012_10120201_69_dialog_content = "¡Espera!",
  ui_story_1012_10120201_70_dialog_content = "¿Qué es?",
  ui_story_1012_10120201_71_dialog_content = "Creo que... ¡siento eclipses!",
  ui_story_1012_10120201_72_dialog_content = "¡Detrás!",
  ui_story_1012_10120201_73_dialog_content = "Graaahh—",
  ui_story_1012_10120201_74_dialog_content = "!",
  ui_story_1012_10120201_75_dialog_content = "¡¿De dónde vienen?!",
  ui_story_1012_10120201_76_dialog_content = "Necesito su apoyo, PlayerName!",
  ui_story_1012_10120201_77_dialog_content = "¡Ok!",
  ui_story_1012_10120202_1_dialog_content = "¿Por qué de repente hay tantos eclipses...",
  ui_story_1012_10120202_2_dialog_content = "¡¿Y cómo es posible que ni siquiera los sintiera?!",
  ui_story_1012_10120202_3_dialog_content = "Este lugar ha estado abandonado durante mucho tiempo.",
  ui_story_1012_10120202_4_dialog_content = "Ya sea que existieran originalmente o se formaran después del colapso, esta base subterránea tiene innumerables túneles oscuros.",
  ui_story_1012_10120202_5_dialog_content = "Los eclipses podrían provenir de túneles que ni siquiera sabemos que existen.",
  ui_story_1012_10120202_6_dialog_content = "Estás bien...",
  ui_story_1012_10120202_7_dialog_content = "El diseño aquí es demasiado complicado. No puedo garantizar que pueda sentir Eclipsites incluso con mi habilidad psíquica.",
  ui_story_1012_10120202_8_dialog_content = "Démonos prisa y salgamos de aquí. ¡Prefiero no demorarme!",
  ui_story_1012_10120202_9_dialog_content = "Ni siquiera hay una bifurcación en el camino aquí. No podremos huir si somos atacados por ambos lados.",
  ui_story_1012_10120202_10_dialog_content = "...",
  ui_story_1012_10120202_11_dialog_content = "La telepatía Caelestite es realmente difícil de tratar.",
  ui_story_1012_10120202_12_dialog_content = "Pero, afortunadamente, hay muchos eclipses para todos.",
  ui_story_1012_10120202_13_dialog_content = "Los resultados de la experimentación se obtienen a partir de innumerables sacrificios.",
  ui_story_1012_10120202_14_dialog_content = "¿Cuál fue la perturbación en este momento?",
  ui_story_1012_10120202_15_dialog_content = "(Eclipsian) Lady Forsakin, ese fue el sonido del Illuminan intentando atravesar la pared.",
  ui_story_1012_10120202_16_dialog_content = "(Eclipsian) El temblor sobresaltó a Caelestite para que usara su habilidad psíquica, alertándolo de nuestra presencia.",
  ui_story_1012_10120202_17_dialog_content = "Sigue deteniéndolo.",
  ui_story_1012_10120202_18_dialog_content = "El Caelestite se acerca al objetivo.",
  ui_story_1012_10120202_19_dialog_content = "Ese idiota imprudente no debe arruinar mis planes.",
  ui_story_1012_10120202_20_dialog_content = "Mantenlo bloqueado, incluso si tienes que usar cadáveres.",
  ui_story_1012_10120202_21_dialog_content = "(Eclipsian) Sí, señora Forsakin!",
  ui_story_1012_10120202_22_dialog_content = "¡Maldita sea, siguen viniendo!",
  ui_story_1012_10120202_23_dialog_content = "¿Tratando de detenerme aquí? ¡Soñar en!",
  ui_story_1012_10120202_24_dialog_content = "Fuera de mi camino-!",
  ui_story_1012_10120202_25_dialog_content = "Vienen de esta dirección, así que eso significa...",
  ui_story_1012_10120202_26_dialog_content = "Forsakin debe estar allí también, ¿eh?",
  ui_story_1012_10120202_27_dialog_content = "finalmente te tengo, Forsakin.",
  ui_story_1012_10120401_1_dialog_content = "(Eclipsian) L-Lady Forsakin!",
  ui_story_1012_10120401_2_dialog_content = "(Eclipsian) ¡Ese fanático de Illumina es demasiado! ¡No podemos detenerlo!",
  ui_story_1012_10120401_3_dialog_content = "(Eclipsian) ¡Viene directo hacia nosotros!",
  ui_story_1012_10120401_4_dialog_content = "Debería haber un límite a la temeridad voluntaria.",
  ui_story_1012_10120401_5_dialog_content = "Más bien, no debería haber esperado que un monstruo tuviera habilidades de comprensión.",
  ui_story_1012_10120401_6_dialog_content = "Todos ustedes vayan a detenerlo.",
  ui_story_1012_10120401_7_dialog_content = "(Eclipsian) D-Todavía tenemos que luchar en...",
  ui_story_1012_10120401_8_dialog_content = "No me hagas repetirme.",
  ui_story_1012_10120401_9_dialog_content = "(Eclipsian) Entendido....",
  ui_story_1012_10120401_10_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_1012_10120401_11_dialog_content = "¿Qué es ese sonido?",
  ui_story_1012_10120401_12_dialog_content = "<color=#e8d9bb>AUGE-!</color>",
  ui_story_1012_10120401_13_dialog_content = "¡Por—el amor—!",
  ui_story_1012_10120401_14_dialog_content = "Que terquedad tonta.",
  ui_story_1012_10120401_15_dialog_content = "Una criatura como tú ni siquiera cumpliría con los estándares para ser experimentada.",
  ui_story_1012_10120401_16_dialog_content = "¡Estoy seguro de que no estás tramando nada bueno otra vez!",
  ui_story_1012_10120401_17_dialog_content = "Si tanto te apetece realizar experimentos, ve a realizarlos en una celda de prisión en Gannon.",
  ui_story_1012_10120401_18_dialog_content = "Ve a detenerlo.",
  ui_story_1012_10120401_19_dialog_content = "Gaah-!",
  ui_story_1012_10120401_20_dialog_content = "¿Eso es todo lo que sus Eclipsites son capaces de hacer?",
  ui_story_1012_10120401_21_dialog_content = "No eres todo eso, ¿verdad?",
  ui_story_1012_10120401_22_dialog_content = "Eres la hermana menor de Reinhardt, ¿no deberías tener al menos su fuerza?",
  ui_story_1012_10120401_23_dialog_content = "...",
  ui_story_1012_10120401_24_dialog_content = "No me compares con un fracasado como ella.",
  ui_story_1012_10120401_25_dialog_content = "¿Vaya? ¿Estás enojado?",
  ui_story_1012_10120401_26_dialog_content = "¡Bien, si estás enojado, peleemos!",
  ui_story_1012_10120401_27_dialog_content = "Parece que no puedo concentrarme en mis experimentos si no hago que te calmes adecuadamente.",
  ui_story_1012_10120401_28_dialog_content = "Me estás haciendo enojar.",
  ui_story_1012_10120401_29_dialog_content = "Eso es justo lo que quería.",
  ui_story_1012_10120401_30_dialog_content = "Estoy de vuelta aquí de nuevo...",
  ui_story_1012_10120401_31_dialog_content = "Todavía no puedo acostumbrarme a la atmósfera aquí.",
  ui_story_1012_10120401_32_dialog_content = "A mí tampoco me gusta este lugar.",
  ui_story_1012_10120401_33_dialog_content = "Apresurémonos y encontremos la entrada a la Chord Zone.",
  ui_story_1012_10120401_34_dialog_content = "Se ha llegado a la puerta de la Zona de Acordes.",
  ui_story_1012_10120401_35_dialog_content = "Descifrar el control de acceso. Neural Aux no podrá aceptar otros comandos durante el proceso. Espere por favor.",
  ui_story_1012_10120401_36_dialog_content = "1%... 2%... 5%...",
  ui_story_1012_10120401_37_dialog_content = "Parece que tomará un tiempo.",
  ui_story_1012_10120401_38_dialog_content = "Sí, entonces yo...",
  ui_story_1012_10120401_39_dialog_content = "Esto es...",
  ui_story_1012_10120401_40_dialog_content = "¿Qué es?",
  ui_story_1012_10120401_41_dialog_content = "Sentí el aura de Forsakin... ¡Está en la torre!",
  ui_story_1012_10120401_42_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_1012_10120401_43_dialog_content = "¡¿Qué diablos es este sonido?!",
  ui_story_1012_10120401_44_dialog_content = "Ha estado sonando persistentemente todo este tiempo...",
  ui_story_1012_10120401_45_dialog_content = "Lo es Forsakin?",
  ui_story_1012_10120401_46_dialog_content = "¿Quizás está enviando eclipses a la torre para causar estragos?",
  ui_story_1012_10120401_47_dialog_content = "¿O se derrumbó algo en la torre?",
  ui_story_1012_10120401_48_dialog_content = "<color=#e8d9bb>AUGE-!</color>",
  ui_story_1012_10120401_49_dialog_content = "¡Guau! ¡¿Qué pasa con toda esta suciedad?!",
  ui_story_1012_10120401_50_dialog_content = "¡Cuidado! ¡Algo está saliendo del polvo!",
  ui_story_1012_10120401_51_dialog_content = "<color=#e8d9bb>¡Clang—!</color>",
  ui_story_1012_10120401_52_dialog_content = "Estás en el camino.",
  ui_story_1012_10120401_53_dialog_content = "¡Concéntrate, Renegado!",
  ui_story_1012_10120401_54_dialog_content = "Soy tu oponente.",
  ui_story_1012_10120401_55_dialog_content = "Barton?! ¡Así que fuiste tú!",
  ui_story_1012_10120401_56_dialog_content = "Yo, PlayerName. ¿También estás aquí?",
  ui_story_1012_10120401_57_dialog_content = "¿Qué pasó con Vicio? ¿Se desmayó?",
  ui_story_1012_10120401_58_dialog_content = "ella está herida ¡Tenemos que abrir esta puerta para encontrar alguna forma de salvarla!",
  ui_story_1012_10120401_59_dialog_content = "¡Barton, ayúdanos a mantener ocupados a Forsakin!",
  ui_story_1012_10120401_60_dialog_content = "¿Quieres que gane tiempo...? ¡Por supuesto!",
  ui_story_1012_10120401_61_dialog_content = "¡Ustedes solo quédense detrás de mí y encárguense de esos secuaces!",
  ui_story_1012_10120401_62_dialog_content = "Solo mira esa confianza.",
  ui_story_1012_10120401_63_dialog_content = "Les sugiero que todos dejen de resistirse.",
  ui_story_1012_10120401_64_dialog_content = "Debes ser consciente de la brecha de poder entre nosotros.",
  ui_story_1012_10120401_65_dialog_content = "No quiero perder el tiempo con ustedes, y probablemente tampoco quieran perder sus vidas.",
  ui_story_1012_10120401_66_dialog_content = "Así que dame acceso a esa máquina y ríndete.",
  ui_story_1012_10120401_67_dialog_content = "Te dejaré vivir.",
  ui_story_1012_10120401_68_dialog_content = "¡Bueno, te sugiero que te des un buen puñetazo en la cara para despertarte de tu delirio!",
  ui_story_1012_10120401_69_dialog_content = "¿Qué va a ser, Caelestite?",
  ui_story_1012_10120401_70_dialog_content = "¿Vas a seguir luchando inútilmente como el Iluminado imprudente de aquí?",
  ui_story_1012_10120401_71_dialog_content = "...",
  ui_story_1012_10120401_72_option_content = "no te creeré",
  ui_story_1012_10120401_73_dialog_content = "¿Oh?",
  ui_story_1012_10120401_74_dialog_content = "Has engañado a demasiada gente.",
  ui_story_1012_10120401_75_dialog_content = "Gertzurde, Shelt, Schummer...",
  ui_story_1012_10120401_76_dialog_content = "¡No te importaban sus medios de subsistencia en absoluto! ¡Solo te preocupas por ti!",
  ui_story_1012_10120401_77_dialog_content = "¡No se puede confiar en ti en absoluto!",
  ui_story_1012_10120401_78_dialog_content = "...",
  ui_story_1012_10120401_79_dialog_content = "Mi paciencia es limitada.",
  ui_story_1012_10120401_80_dialog_content = "Entrega el acceso y haré las cosas rápido.",
  ui_story_1012_10120401_81_dialog_content = "¡Nunca, nunca te lo daré!",
  ui_story_1012_10120401_82_dialog_content = "Resistencia sin sentido.",
  ui_story_1012_10120401_83_dialog_content = "Bien entonces...",
  ui_story_1012_10120401_84_dialog_content = "Adiós.",
  ui_story_1012_10120402_1_dialog_content = "¡Cuidado, PlayerName!",
  ui_story_1012_10120402_2_dialog_content = "¡Aah—! ¡Ayuda!",
  ui_story_1012_10120402_3_dialog_content = "¡¡!!",
  ui_story_1012_10120402_4_dialog_content = "¡Uf!",
  ui_story_1012_10120402_5_dialog_content = "No te distraigas cuando pelees.",
  ui_story_1012_10120402_6_dialog_content = "Tú mismo dijiste esto.",
  ui_story_1012_10120402_7_dialog_content = "Barton!",
  ui_story_1012_10120402_8_dialog_content = "Tch...",
  ui_story_1012_10120402_9_dialog_content = "¿Eso es todo lo que tienes? ¿No comiste?",
  ui_story_1012_10120402_10_dialog_content = "Has estado causando problemas sin parar desde fuera de la torre hasta aquí.",
  ui_story_1012_10120402_11_dialog_content = "Deberías estar quedándote sin fuerzas ahora mismo, ¿no?",
  ui_story_1012_10120402_12_dialog_content = "...",
  ui_story_1012_10120402_13_dialog_content = "No hay necesidad de esta lucha innecesaria.",
  ui_story_1012_10120402_14_dialog_content = "¡Bah! ¡Déjate de tonterías!",
  ui_story_1012_10120402_15_dialog_content = "Tráelo-!",
  ui_story_1012_10120402_16_dialog_content = "Estarías mejor si hubieras pasado la mitad del tiempo que pasas peleando en estudiar.",
  ui_story_1012_10120402_17_dialog_content = "¿Estudiando?",
  ui_story_1012_10120402_18_dialog_content = "Así que la gente como tú existe, el tipo que solo pide que le den una paliza.",
  ui_story_1012_10120402_19_dialog_content = "¿Crees que tengo paciencia para estudiar?",
  ui_story_1012_10120402_20_dialog_content = "Vas a terminar pagando por tu ignorancia.",
  ui_story_1012_10120402_21_dialog_content = "¡Uh!",
  ui_story_1012_10120402_22_dialog_content = "Las articulaciones de tu muñeca derecha están hechas añicos.",
  ui_story_1012_10120402_23_dialog_content = "Me gustaría ver cómo planeas recoger ese cuchillo.",
  ui_story_1012_10120402_24_dialog_content = "O...",
  ui_story_1012_10120402_25_dialog_content = "Podrías simplemente ponerte de rodillas y rogarme que pare.",
  ui_story_1012_10120402_26_dialog_content = "Para, Forsakin!",
  ui_story_1012_10120402_27_dialog_content = "Callarse la boca.",
  ui_story_1012_10120402_28_dialog_content = "No tienes derecho a hablar, inútil debilucho de Caelestite.",
  ui_story_1012_10120402_29_dialog_content = "Un soldado Illuminati...",
  ui_story_1012_10120402_30_dialog_content = "¿Mmm?",
  ui_story_1012_10120402_31_dialog_content = "Soldados Illuminan... ¡nunca se rendirían ante alguien como tú!",
  ui_story_1012_10120402_32_dialog_content = "!",
  ui_story_1012_10120402_33_dialog_content = "¡Incluso si solo tengo una mano, es más que suficiente para derribarte!",
  ui_story_1012_10120402_34_dialog_content = "Barton! ¡Tu pierna!",
  ui_story_1012_10120402_35_dialog_content = "Ayúdalo, Carleen!",
  ui_story_1012_10120402_36_dialog_content = "¡Dispersión, pétalos de hielo!",
  ui_story_1012_10120402_37_dialog_content = "¡Esto no está funcionando, hay demasiados de ellos!",
  ui_story_1012_10120402_38_dialog_content = "¡No te preocupes por mí!",
  ui_story_1012_10120402_39_dialog_content = "¡Solo abre la puerta! me encargaré Forsakin!",
  ui_story_1012_10120402_40_dialog_content = "Pero ya estás...",
  ui_story_1012_10120402_41_dialog_content = "!",
  ui_story_1012_10120402_42_dialog_content = "¡Ve!",
  ui_story_1012_10120402_43_dialog_content = "¡Pero...!",
  ui_story_1012_10120402_44_dialog_content = "¡Encontrar una salida!",
  ui_story_1012_10120402_45_dialog_content = "Si caigo en la batalla, escribe esto en mi lápida:",
  ui_story_1012_10120402_46_dialog_content = "¡Un glorioso soldado de Illumina que luchó contra los Eclipsites hasta el final!",
  ui_story_1012_10120402_47_dialog_content = "PlayerName¡Necesitamos espacio para retirarnos!",
  ui_story_1012_10120402_48_dialog_content = "¡Moriremos si nos quedamos atrapados aquí!",
  ui_story_1012_10120402_49_dialog_content = "¡...!",
  ui_story_1012_10120402_50_dialog_content = "Neural Aux, ¿cuánto tiempo más necesitas?",
  ui_story_1012_10120402_51_dialog_content = "El descifrado de la puerta está al 96%, espere.",
  ui_story_1012_10120402_52_dialog_content = "... ¡Espera un poco más!",
  ui_story_1012_10120402_53_dialog_content = "97%.",
  ui_story_1012_10120402_54_dialog_content = "98%.",
  ui_story_1012_10120402_55_dialog_content = "99%.",
  ui_story_1012_10120402_56_dialog_content = "100%, descifrado completo.",
  ui_story_1012_10120402_57_dialog_content = "<color=#e8d9bb>Retumbar-</color>",
  ui_story_1012_10120402_58_dialog_content = "La puerta... ¡está abierta!",
  ui_story_1012_10120402_59_dialog_content = "Carleen, Barton, ¡retirar!",
  ui_story_1012_10120501_1_dialog_content = "¡Flor de hielo!",
  ui_story_1012_10120501_2_dialog_content = "¡Apuro! Forsakin viene detrás de nosotros y no puedo detenerla por mucho tiempo!",
  ui_story_1012_10120501_3_dialog_content = "Vayan por aquí. Barton, proteger PlayerName!",
  ui_story_1012_10120501_4_dialog_content = "No te preocupes, podría estar herido, ¡pero no dejaré que Forsakin le ponga un dedo encima!",
  ui_story_1012_10120501_5_dialog_content = "¿Cuánto más, Neural Aux?",
  ui_story_1012_10120501_6_dialog_content = "Siga recto 650 pies y llegará a su destino.",
  ui_story_1012_10120501_7_dialog_content = "Huff... Huff... ¡Casi... ahí!",
  ui_story_1012_10120501_8_dialog_content = "¡Puedo ver la puerta!",
  ui_story_1012_10120501_9_dialog_content = "No puedo—",
  ui_story_1012_10120501_10_dialog_content = "¡¿Por qué el suelo es tan desigual aquí?!",
  ui_story_1012_10120501_11_dialog_content = "Especulo que el camino a la Chord Zone se ha deformado debido a cambios en el terreno.",
  ui_story_1012_10120501_12_dialog_content = "¡Pero confíe en que la ruta que he proporcionado es precisa!",
  ui_story_1012_10120501_13_dialog_content = "¡Gerente, por favor no se rinda! ¡Sigue adelante!",
  ui_story_1012_10120501_14_dialog_content = "¡Yo... no me rendiré!",
  ui_story_1012_10120501_15_dialog_content = "PlayerName, no pares!",
  ui_story_1012_10120501_16_dialog_content = "¡Sigue corriendo, muchacho!",
  ui_story_1012_10120501_17_dialog_content = "¡Te haré correr 100 vueltas alrededor de Gannon cuando regresemos si te atreves a parar!",
  ui_story_1012_10120501_18_dialog_content = "¡No tienes que ser tan violento cuando tratas de animarme!",
  ui_story_1012_10120501_19_dialog_content = "¡Ay!",
  ui_story_1012_10120501_20_dialog_content = "¡Auxiliar neural!",
  ui_story_1012_10120501_21_dialog_content = "¡Navegación Aux Neural, a tu servicio!",
  ui_story_1012_10120501_22_dialog_content = "¡Cierra las puertas justo después de que entremos en Chord Zone!",
  ui_story_1012_10120501_23_dialog_content = "¡Cierra esos Eclipsites afuera!",
  ui_story_1012_10120501_24_dialog_content = "¡Entendido!",
  ui_story_1012_10120501_25_dialog_content = "Pero, Gerente, ¡preste atención a las trampas debajo de sus pies!",
  ui_story_1012_10120501_26_option_content = "¿Trampas?",
  ui_story_1012_10120501_27_dialog_content = "¡¿Por qué hay trampas aquí?!",
  ui_story_1012_10120501_28_option_content = "¡¿También hay trampas?!",
  ui_story_1012_10120501_29_dialog_content = "¡¿De dónde vienen?!",
  ui_story_1012_10120501_30_dialog_content = "Estas trampas son dispositivos independientes que forman parte del sistema de defensa de Chord Zone.",
  ui_story_1012_10120501_31_dialog_content = "Debido a que el enlace entre Neural Aux y Chord Zone se ha cortado, no puedo controlar las trampas en Chord Zone.",
  ui_story_1012_10120501_32_dialog_content = "¡Estas trampas están preparadas actualmente para atacar al ser detectadas!",
  ui_story_1012_10120501_33_dialog_content = "Gerente, haga lo que le parezca... no, quiero decir, esquive lo que le parezca.",
  ui_story_1012_10120501_34_dialog_content = "¡Deberías habernos dicho antes!",
  ui_story_1012_10120501_35_dialog_content = "Los libros de texto de Caelestite ya incluyen el hecho de que hay trampas en la Zona de Cuerdas.",
  ui_story_1012_10120501_36_dialog_content = "Si lo ha olvidado, Gerente, ¡Neural Aux le recomendó volver a la escuela!",
  ui_story_1012_10120501_37_dialog_content = "Mira donde pisas, PlayerName!",
  ui_story_1012_10120501_38_dialog_content = "¿Eh?",
  ui_story_1012_10120501_39_dialog_content = "<color=#e8d9bb>Hacer clic-</color>",
  ui_story_1012_10120501_40_dialog_content = "PlayerName, ¡sal ahora!",
  ui_story_1012_10120501_41_dialog_content = "¡Ahhh!",
  ui_story_1012_10120501_42_dialog_content = "...",
  ui_story_1012_10120501_43_dialog_content = "¡Gerente, por favor esquive!",
  ui_story_1012_10120501_44_dialog_content = "¿Esta cosa tiene capacidades de combate?",
  ui_story_1012_10120501_45_dialog_content = "¡Tíralo si lo hace! ¡Al menos detendría a Forsakin por un tiempo!",
  ui_story_1012_10120501_46_dialog_content = "Solo soy un holograma, no tengo habilidades de combate.",
  ui_story_1012_10120501_47_dialog_content = "¡Está prohibido obligar al Neural Aux a realizar tareas de combate que están fuera de los parámetros de sus funciones!",
  ui_story_1012_10120501_48_dialog_content = "¡Cuéntanos la ubicación de las trampas entonces!",
  ui_story_1012_10120501_49_dialog_content = "Yo, estoy buscando datos sobre las trampas en la Chord Zone—",
  ui_story_1012_10120501_50_dialog_content = "¡Búsqueda completa!",
  ui_story_1012_10120501_51_dialog_content = "¡Esquiva a la derecha más adelante!",
  ui_story_1012_10120501_52_dialog_content = "¡Oh, no, los eclipses se están poniendo al día!",
  ui_story_1012_10120501_53_dialog_content = "¡Tenemos que hacer uso de estas trampas para quitárnoslas de encima!",
  ui_story_1012_10120502_1_dialog_content = "Gerente, se está acercando a su destino.",
  ui_story_1012_10120502_2_dialog_content = "Inicializando el cierre de la puerta Chord Zone.",
  ui_story_1012_10120502_3_dialog_content = "¡Gerente, ingrese a Chord Zone antes de que se cierre la puerta!",
  ui_story_1012_10120502_4_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_1012_10120502_5_dialog_content = "¡Esperar! ¡Eso es demasiado rápido!",
  ui_story_1012_10120502_6_dialog_content = "¡No lo lograremos!",
  ui_story_1012_10120502_7_dialog_content = "¡Detenerlos! No dejes que esas cucarachas dañen la maquinaria del interior.",
  ui_story_1012_10120502_8_dialog_content = "PlayerName, ¡piensa en algo!",
  ui_story_1012_10120502_9_dialog_content = "¡Tenemos que poner distancia entre nosotros y los Eclipsites!",
  ui_story_1012_10120502_10_dialog_content = "Una solución... solución... ¿Dónde se supone que debo encontrar una solución?",
  ui_story_1012_10120502_11_dialog_content = "¡Hay una trampa explosiva por delante! ¡Cuidado y esquiva!",
  ui_story_1012_10120502_12_dialog_content = "trampa explosiva?",
  ui_story_1012_10120502_13_dialog_content = "¡Niño, ve a pisar esa trampa explosiva!",
  ui_story_1012_10120502_14_dialog_content = "¡¿Eh?!",
  ui_story_1012_10120502_15_dialog_content = "Confía en mí, ¡pisa la trampa y eso lo hará!",
  ui_story_1012_10120502_16_dialog_content = "No te vas a escapar.",
  ui_story_1012_10120502_17_dialog_content = "¡Solo te hablaré por esta vez!",
  ui_story_1012_10120502_18_dialog_content = "<color=#e8d9bb>¡Hacer clic!</color>",
  ui_story_1012_10120502_19_dialog_content = "¡Agárrate fuerte, chico!",
  ui_story_1012_10120502_20_dialog_content = "<color=#e8d9bb>¡Bang, bang!</color>",
  ui_story_1012_10120502_21_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_1012_10120502_22_dialog_content = "Esto es-!",
  ui_story_1012_10120502_23_dialog_content = "¡Ahhh! ¡Vamos a ser lanzados al cielo!",
  ui_story_1012_10120502_24_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10120502_25_dialog_content = "Realmente eres un monstruo Iluminado.",
  ui_story_1012_10120502_26_dialog_content = "Muchos de sus métodos implican casi perder la vida.",
  ui_story_1012_10120502_27_dialog_content = "Derriba esta puerta.",
  ui_story_1012_10120502_28_dialog_content = "(Eclipsian) Sí, señora Forsakin!",
  ui_story_1012_10120502_29_dialog_content = "¿Tuvimos... éxito?",
  ui_story_1012_10120502_30_dialog_content = "Seguimos vivos, al menos...",
  ui_story_1012_10120502_31_dialog_content = "Vice tampoco está herido.",
  ui_story_1012_10120502_32_dialog_content = "Uf... Espera, ¿dónde está? Barton?!",
  ui_story_1012_10120502_33_dialog_content = "Estoy bien...",
  ui_story_1012_10120502_34_dialog_content = "Tsk... Pero esa bomba que hicieron los caelestitas era bastante poderosa.",
  ui_story_1012_10120502_35_dialog_content = "Todos estaríamos muertos si no lo hubiera puesto en marcha antes.",
  ui_story_1012_10120502_36_dialog_content = "¡Obviamente no estás bien!",
  ui_story_1012_10120502_37_dialog_content = "Ejem... Relájate, chico...",
  ui_story_1012_10120502_38_dialog_content = "Todos en Illumina han experimentado duras batallas antes. Heridas como estas solo necesitan un poco de vendaje y estarán bien después de una noche de sueño.",
  ui_story_1012_10120502_39_dialog_content = "Si corremos al médico con un rasguño tan pequeño, definitivamente nos agarrarán por la nuca y nos sacarán de la enfermería.",
  ui_story_1012_10120502_40_dialog_content = "No os preocupéis por mí... Eso es lo que estáis buscando, ¿verdad?",
  ui_story_1012_10120502_41_dialog_content = "Neural Aux, ¿es este el Chord Link?",
  ui_story_1012_10120502_42_dialog_content = "¡Creo que debería ser esto!",
  ui_story_1012_10120502_43_dialog_content = "¿Es confiable su juicio?",
  ui_story_1012_10120502_44_dialog_content = "¿Existen registros de este aparato?",
  ui_story_1012_10120502_45_dialog_content = "El Chord Link es el aparato principal de la Chord Zone.",
  ui_story_1012_10120502_46_dialog_content = "De acuerdo con la información recopilada, el dispositivo frente al Gerente debería ser el Chord Link.",
  ui_story_1012_10120502_47_dialog_content = "<color=#e8d9bb>Ruido sordo-!</color>",
  ui_story_1012_10120502_48_dialog_content = "¡Esos eclipses están tratando de derribar la puerta!",
  ui_story_1012_10120502_49_dialog_content = "No te preocupes por ellos por ahora.",
  ui_story_1012_10120502_50_dialog_content = "Las paredes y las puertas aquí son fuertes. No pude atravesarlos incluso después de golpearlos durante horas.",
  ui_story_1012_10120502_51_dialog_content = "<color=#e8d9bb>RUIDO SORDO-!</color>",
  ui_story_1012_10120502_52_dialog_content = "Uh... ¡Hay una abolladura en la puerta!",
  ui_story_1012_10120502_53_dialog_content = "Neural Aux, ¿hay alguna forma de reforzar la puerta?",
  ui_story_1012_10120502_54_dialog_content = "¡Activando la función de mejora del control de acceso a la zona de acordes!",
  ui_story_1012_10120502_55_dialog_content = "<color=#e8d9bb>Clic clic-</color>",
  ui_story_1012_10120502_56_dialog_content = "Ahora hay algunas puertas más selladas sobre la entrada.",
  ui_story_1012_10120502_57_dialog_content = "Parece que deberían aguantar un rato más.",
  ui_story_1012_10120502_58_dialog_content = "<color=#e8d9bb>*sonidos de golpes débiles*</color>",
  ui_story_1012_10120502_59_dialog_content = "¿Se detuvieron?",
  ui_story_1012_10120502_60_dialog_content = "<color=#e8d9bb>¡¡¡zas!!!</color>",
  ui_story_1012_10120502_61_dialog_content = "¡¿Por qué su asalto es cada vez más fuerte?!",
  ui_story_1012_10120502_62_dialog_content = "¿Las cabezas de esos Eclipsites están hechas de acero?",
  ui_story_1012_10120502_63_dialog_content = "¡Ja! Forsakin ¡Me llama terco cuando ella misma es bastante testaruda!",
  ui_story_1012_10120502_64_dialog_content = "¡Regresa ya que has golpeado la pared!",
  ui_story_1012_10120502_65_dialog_content = "Pronto se abrirán paso si esto continúa.",
  ui_story_1012_10120502_66_dialog_content = "PlayerName, date prisa y activa el Chord Link para sanar Vice.",
  ui_story_1012_10120502_67_dialog_content = "Si Vice es revivido, podemos escapar de aquí juntos. ¡Todavía puede haber esperanza!",
  ui_story_1012_10120502_68_dialog_content = "Neural Aux, ¡ayúdame a activar Chord Link!",
  ui_story_1012_10120502_69_dialog_content = "¡Activa el enlace de acordes!",
  ui_story_1012_10120502_70_dialog_content = "¡Busque registros de experimentos para obtener información sobre los efectos secundarios y los resultados de Chord Link!",
  ui_story_1012_10120502_71_dialog_content = "Buscando... ¡Error!",
  ui_story_1012_10120502_72_dialog_content = "¡No puedo recuperar los registros del experimento!",
  ui_story_1012_10120502_73_dialog_content = "¡¿Qué?!",
  ui_story_1012_10120502_74_dialog_content = "¿No dijiste que estaban todos almacenados aquí?",
  ui_story_1012_10120502_75_dialog_content = "¡¿Por qué no se pueden recuperar?!",
  ui_story_1012_10120502_76_dialog_content = "He estado desconectado de la Zona de Acordes durante mucho tiempo, por lo tanto, no estoy familiarizado con los asuntos relacionados con ella.",
  ui_story_1012_10120502_77_dialog_content = "He detectado registros eliminados en los archivos de Chord Zone.",
  ui_story_1012_10120502_78_dialog_content = "Los datos se perdieron hace mucho tiempo y no se pueden recuperar.",
  ui_story_1012_10120502_79_dialog_content = "Err...",
  ui_story_1012_10120502_80_dialog_content = "Entonces, ¿planeaban usar un dispositivo no probado en Vice?",
  ui_story_1012_10120502_81_dialog_content = "No, primero iba a encontrar los registros del experimento, pero todos han sido borrados...",
  ui_story_1012_10120502_82_dialog_content = "Barton, Carleen, por favor traten de esperar un momento.",
  ui_story_1012_10120502_83_dialog_content = "Voy a confirmar lo que hace Chord Link por mi cuenta.",
  ui_story_1012_10120502_84_dialog_content = "Espera, no eres un auroriano. No sabemos qué podría pasar si lo usas.",
  ui_story_1012_10120502_85_dialog_content = "pero no puedo hacer Vice arriesgalo.",
  ui_story_1012_10120502_86_dialog_content = "Forsakin se abrirá camino pronto. Ustedes dos realmente pueden pelear...",
  ui_story_1012_10120502_87_dialog_content = "Mientras tanto, soy un Caelestite que ni siquiera puede usar Luminatics. ¡Soy más adecuado para la experimentación!",
  ui_story_1012_10120502_88_dialog_content = "¡Alto!",
  ui_story_1012_10120502_89_dialog_content = "¡No me detengas!",
  ui_story_1012_10120502_90_dialog_content = "¡Cálmate!",
  ui_story_1012_10120502_91_dialog_content = "¿Sabes lo que esa cosa puede hacer?",
  ui_story_1012_10120502_92_dialog_content = "El Chord Link puede curar heridas y hacer modificaciones en varias partes del cuerpo de un Aurorian para que su verdadero potencial pueda ser desatado.",
  ui_story_1012_10120502_93_dialog_content = "Puede curar, ¿eh?",
  ui_story_1012_10120502_94_dialog_content = "¡Entonces me iré!",
  ui_story_1012_10120502_95_dialog_content = "¡Pero ni siquiera sé qué efectos secundarios tiene, cuál es la tasa de éxito o si podría matarte!",
  ui_story_1012_10120502_96_dialog_content = "¡Entonces debería ser yo quien lo haga!",
  ui_story_1012_10120502_97_dialog_content = "Necesitas un sujeto de prueba, ¿no?",
  ui_story_1012_10120502_98_dialog_content = "Estoy gravemente herido. No puedo hacer mucho si tengo que enfrentarme a Forsakin ahora mismo.",
  ui_story_1012_10120502_99_dialog_content = "Si se quedan afuera y se coordinan con Carleen, podrán ganar más tiempo.",
  ui_story_1012_10120502_100_dialog_content = "Así que déjame ir.",
  ui_story_1012_10120502_101_dialog_content = "Si esa máquina puede curarme, tendré una sorpresa esperando a Forsakin.",
  ui_story_1012_10120502_102_dialog_content = "Y luego puede estar seguro y usarlo para ahorrar Vice.",
  ui_story_1012_10120502_103_dialog_content = "... Está bien...",
  ui_story_1012_10120502_104_dialog_content = "Dejaré esto a ustedes dos entonces.",
  ui_story_1012_10120502_105_dialog_content = "¡Mantén esos eclipses fuera de mí!",
  ui_story_1012_10120502_106_dialog_content = "<color=#e8d9bb>¡¡¡zas!!!</color>",
  ui_story_1012_10120502_107_dialog_content = "¡Graaaaaagh!",
  ui_story_1012_10120502_108_dialog_content = "Más fuerte que los materiales utilizados en Entrañas, pero más ligero.",
  ui_story_1012_10120502_109_dialog_content = "El material utilizado aquí es más similar a Colossus Patches.",
  ui_story_1012_10120502_110_dialog_content = "Caelestitas, Colosos, e incluso Eclipsitas...",
  ui_story_1012_10120502_111_dialog_content = "Quizás ni siquiera los Eclipse sepan qué secretos enterrados aguardan.",
  ui_story_1012_10120502_112_dialog_content = "Que interesante.",
  ui_story_1012_10120502_113_dialog_content = "(Eclipsiana) Señora Forsakin, Lord Figerald me ordenó que le entregara un mensaje.",
  ui_story_1012_10120502_114_dialog_content = "(Eclipsian) El ejército ha terminado de reunirse fuera de la torre.",
  ui_story_1012_10120502_115_dialog_content = "(Eclipsian) Pero los cambios de la Torre Blanca han llamado la atención de Illumina, Lumopolis y Northland.",
  ui_story_1012_10120502_116_dialog_content = "(Eclipsian) Todos han enviado refuerzos y el lugar está rodeado.",
  ui_story_1012_10120502_117_dialog_content = "(eclipsiano) Reinhardt y Bethlehem están entre ellos.",
  ui_story_1012_10120502_118_dialog_content = "Por lo general, son tan cobardes, pero ahora todos han salido arrastrándose de sus guaridas, ¿eh?",
  ui_story_1012_10120502_119_dialog_content = "Seguro que tienen un oído agudo.",
  ui_story_1012_10120502_120_dialog_content = "Dile a Figerald que los mantenga alejados.",
  ui_story_1012_10120502_121_dialog_content = "Necesito tiempo para experimentar.",
  ui_story_1012_10120502_122_dialog_content = "(Eclipsian) Lord Figerald me dijo que te diera un recordatorio.",
  ui_story_1012_10120502_123_dialog_content = "(Eclipsian) No hagas nada innecesario.",
  ui_story_1012_10120502_124_dialog_content = "Si realmente quiere ayudarme, debería dejar de molestarme.",
  ui_story_1012_10120502_125_dialog_content = "...",
  ui_story_1012_10120502_126_dialog_content = "(Eclipsian) Eso es lo que señora Forsakin dijo...",
  ui_story_1012_10120502_127_dialog_content = "(Eclipsian) Parece que Forsakin necesita algunos recordatorios.",
  ui_story_1012_10120502_128_dialog_content = "(Eclipsian) Pero aún no es el momento para eso.",
  ui_story_1012_10120502_129_dialog_content = "(Eclipsian) Illumina, Lumopolis e incluso Northland han aparecido.",
  ui_story_1012_10120502_130_dialog_content = "(Eclipsian) Lord Figerald, ¿deberíamos detenerlos?",
  ui_story_1012_10120502_131_dialog_content = "(Eclipsian) Adelante, diviértete si quieres.",
  ui_story_1012_10120502_132_dialog_content = "(Eclipsian) Pero no hay necesidad de luchar hasta la muerte. Dejar entrar a uno o dos no es gran cosa.",
  ui_story_1012_10120502_133_dialog_content = "(Eclipsian) Le daría a Forsakin algo de presión, por lo que se ve obligada a demostrarnos su valor.",
  ui_story_1012_10120502_134_dialog_content = "(Eclipsian) Sí, Lord Figerald.",
  ui_story_1012_10120601_1_dialog_content = "<color=#e8d9bb>Alerta del sistema: Chord Link ahora está activo... No interrumpa el proceso de sincronización...</color>",
  ui_story_1012_10120601_2_dialog_content = "<color=#e8d9bb>Golpe... Golpe... Golpe... Golpe...</color>",
  ui_story_1012_10120601_3_dialog_content = "¿Qué es ese sonido?",
  ui_story_1012_10120601_4_dialog_content = "Parece venir de todas partes... Un sonido realmente incómodo.",
  ui_story_1012_10120601_5_dialog_content = "Más que incómodo, es más inquietante.",
  ui_story_1012_10120601_6_dialog_content = "Esto suena como...",
  ui_story_1012_10120601_7_option_content = "Sonidos de terremotos.",
  ui_story_1012_10120601_8_dialog_content = "La intensidad de las vibraciones ni siquiera es tan fuerte como cuando se elevaba el Obelisco del Retorno.",
  ui_story_1012_10120601_9_dialog_content = "Todas las paredes del Núcleo Central están temblando con él...",
  ui_story_1012_10120601_10_dialog_content = "Como si este lugar estuviera a punto de derrumbarse.",
  ui_story_1012_10120601_11_option_content = "Sonidos de latidos del corazón.",
  ui_story_1012_10120601_12_dialog_content = "Suenan como un ritmo constante.",
  ui_story_1012_10120601_13_dialog_content = "Puedo sentir una energía terrible en este ritmo...",
  ui_story_1012_10120601_14_dialog_content = "Es como la cámara del corazón de un gigante.",
  ui_story_1012_10120601_15_dialog_content = "¿Es este el poder del Chord Link...?",
  ui_story_1012_10120601_16_dialog_content = "Ya veo... Un sonido muy inquietante.",
  ui_story_1012_10120601_17_dialog_content = "Simplemente no sabemos cuánto durará esto.",
  ui_story_1012_10120601_18_dialog_content = "Barton, él...",
  ui_story_1012_10120601_19_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10120601_20_dialog_content = "¡¿?!",
  ui_story_1012_10120601_21_dialog_content = "Este sonido definitivamente no fue causado por Chord Link, ¿verdad?",
  ui_story_1012_10120601_22_dialog_content = "Advertencia: intrusos ilegales detectados 100 pies más adelante.",
  ui_story_1012_10120601_23_dialog_content = "Ella todavía vino. ¡Neural Aux, modifica la estructura y cierra la puerta aquí!",
  ui_story_1012_10120601_24_dialog_content = "Recibido... ¡Error! ¡Error!",
  ui_story_1012_10120601_25_dialog_content = "Organismos vivos detectados en la entrada de Chord Zone. No se puede cerrar.",
  ui_story_1012_10120601_26_dialog_content = "No tenemos otra opción. Prepararse, PlayerName!",
  ui_story_1012_10120601_27_dialog_content = "Hm... La sincronización todavía está en progreso. tenemos que proteger Barton!",
  ui_story_1012_10120601_28_dialog_content = "(... Cualquiera que sea el resultado de la Sincronización)",
  ui_story_1012_10120601_29_dialog_content = "Advertencia: intrusos ilegales detectados 30 pies más adelante.",
  ui_story_1012_10120601_30_dialog_content = "¡Repetir! Intrusos ilegales detectados 30 pies más adelante.",
  ui_story_1012_10120601_31_dialog_content = "¡Repetir! Intrusos ilegales detectados 30 pies más adelante...",
  ui_story_1012_10120601_32_dialog_content = "¿Se detuvo?",
  ui_story_1012_10120601_33_dialog_content = "¿D-De verdad...?",
  ui_story_1012_10120601_34_dialog_content = "<color=#e8d9bb><size=45>¡¡¡ESTALLIDO!!!</size></color>",
  ui_story_1012_10120601_35_dialog_content = "¿Intrusos ilegales?",
  ui_story_1012_10120601_36_dialog_content = "Acabo de hacer las mismas cosas que ustedes hicieron.",
  ui_story_1012_10120601_37_dialog_content = "La única diferencia está en quién vino primero y quién vino después.",
  ui_story_1012_10120601_38_dialog_content = "... ¿Ah?",
  ui_story_1012_10120601_39_dialog_content = "Así que todavía hay tales dispositivos disruptivos escondidos en el nivel más profundo de este cementerio.",
  ui_story_1012_10120601_40_dialog_content = "Ustedes todavía están un paso por delante de mí en todo este \"matar Barton\" cosa.",
  ui_story_1012_10120601_41_dialog_content = "¡No hables tonterías!",
  ui_story_1012_10120601_42_dialog_content = "PlayerName¡Deja de perder el tiempo con ella!",
  ui_story_1012_10120601_43_dialog_content = "No se le puede permitir ir más profundo. Vice todavía está allí!",
  ui_story_1012_10120601_44_dialog_content = "Muchas cosas en el mundo no se desarrollarán de la manera que tú quieres.",
  ui_story_1012_10120601_45_dialog_content = "PlayerName, como Caelestite, y habiendo dejado los Colosos durante mucho tiempo, me sorprende que todavía necesites que te diga esta verdad.",
  ui_story_1012_10120601_46_dialog_content = "No necesitas que te dé más detalles sobre lo que le pasó al último caelestita que se metió en mi contra.",
  ui_story_1012_10120601_47_dialog_content = "¡Tú!",
  ui_story_1012_10120601_48_dialog_content = "(Eclipsiano) Ataque.",
  ui_story_1012_10120601_49_dialog_content = "(Eclipsiano) Roger!",
  ui_story_1012_10120702_1_dialog_content = "¡Gaaah!",
  ui_story_1012_10120702_2_dialog_content = "¡Ja!",
  ui_story_1012_10120702_3_dialog_content = "Gah...",
  ui_story_1012_10120702_4_dialog_content = "¡A tu espalda! Carleen!",
  ui_story_1012_10120702_5_dialog_content = "¡¿Qué...?!",
  ui_story_1012_10120702_6_dialog_content = "Gaaaaaah!!!",
  ui_story_1012_10120702_7_dialog_content = "Oh...",
  ui_story_1012_10120702_8_dialog_content = "(Esto no funcionará. Forsakin trajo demasiados eclipses.)",
  ui_story_1012_10120702_9_dialog_content = "(Tal vez disparar el rifle es más eficiente que enlazar con Carleen¡la conciencia!)",
  ui_story_1012_10120702_10_dialog_content = "¡¿Eh?!",
  ui_story_1012_10120702_11_dialog_content = "No tengo ni idea. ¿Cuándo aprendiste a usar un arma? PlayerName?",
  ui_story_1012_10120702_12_dialog_content = "Hmm... Parece un arma Caelestite. Se puede considerar una reliquia.",
  ui_story_1012_10120702_13_dialog_content = "Esto es lo bueno.",
  ui_story_1012_10120702_14_dialog_content = "Me lo llevo. Gracias, PlayerName.",
  ui_story_1012_10120702_15_dialog_content = "¡Maldición! ¡Devolvérsela!",
  ui_story_1012_10120702_16_dialog_content = "Gaaaaaah!!!",
  ui_story_1012_10120702_17_dialog_content = "Detenerlos, PlayerName! ¡No podemos dejar que sigan entrando!",
  ui_story_1012_10120702_18_dialog_content = "¡El proceso de sincronización no puede fallar por este motivo!",
  ui_story_1012_10120702_19_dialog_content = "¡Dispersión, pétalos de hielo!",
  ui_story_1012_10120702_20_dialog_content = "<size=45>¡Gaaaaaah!</size>",
  ui_story_1012_10120702_21_dialog_content = "C-Carleen!",
  ui_story_1012_10120702_22_option_content = "¡Control forzado!",
  ui_story_1012_10120702_23_dialog_content = "Carleen... Por favor... ¡Por favor responda!",
  ui_story_1012_10120702_24_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1012_10120702_25_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1012_10120702_26_dialog_content = "(Eclipsiano) Matar Barton y Vice. No dañes ese dispositivo.",
  ui_story_1012_10120702_27_dialog_content = "(Eclipsian) Como ordenes.",
  ui_story_1012_10120702_28_dialog_content = "<size=50><anim type=Shake>ga-</anim></size>",
  ui_story_1012_10120702_29_dialog_content = "(¿Por qué… por qué sucede esto…?)",
  ui_story_1012_10120702_30_dialog_content = "(Este sentimiento de impotencia otra vez... lo estoy experimentando de nuevo...)",
  ui_story_1012_10120702_31_dialog_content = "(Si tuviera el poder de los Lumináticos, las cosas seguramente serían diferentes a partir de ahora).",
  ui_story_1012_10120702_32_dialog_content = "(Vice, Carleen, y...)",
  ui_story_1012_10120702_33_dialog_content = "(Ellos...)",
  ui_story_1012_10120702_34_dialog_content = "¡Ayuda! ¿Alguien puede salvarme?",
  ui_story_1012_10120702_35_dialog_content = "No te acerques a él. ¡Lucharé contra ustedes!",
  ui_story_1012_10120702_36_dialog_content = "Eh... Waaah... Waaah...",
  ui_story_1012_10120702_37_dialog_content = "Llamas de batalla, Eclipses... ¿Esta es la bienvenida que recibo cuando abro los ojos?",
  ui_story_1012_10120702_38_dialog_content = "(¡¿Qué?!)",
  ui_story_1012_10120702_39_dialog_content = "¿Hay algo mejor?",
  ui_story_1012_10120702_40_dialog_content = "Apenas puedo contenerme. ¡Este poder se siente como si brotara en cualquier momento!",
  ui_story_1012_10120702_41_dialog_content = "Una batalla oportuna es aquella que debemos usar para practicar.",
  ui_story_1012_10120702_42_dialog_content = "Barton! Tú... ¡Lo lograste!",
  ui_story_1012_10120702_43_dialog_content = "Vaya, PlayerName... ¿Qué te pasa, chico?",
  ui_story_1012_10120702_44_dialog_content = "Límpiate el agua de la cara. ¡Deja de actuar como una niña!",
  ui_story_1012_10120702_45_dialog_content = "¡Muéstrame tu espíritu de lucha!",
  ui_story_1012_10120702_46_dialog_content = "¡Por supuesto!",
  ui_story_1012_10120702_47_dialog_content = "Vamos, déjame enseñarte lo que es un verdadero campo de batalla.",
  ui_story_1012_10120702_48_dialog_content = "Esta torre te pertenece. ¡No puedes dejar que caiga en manos de la gente de Eclipse!",
  ui_story_1012_10120702_49_dialog_content = "(Eclipsian) Qué sorpresa. La antigua tecnología Caelestite es realmente muy avanzada.",
  ui_story_1012_10120702_50_dialog_content = "(Eclipsian) Estoy demasiado emocionado. Perseguirlo aquí es la decisión correcta.",
  ui_story_1012_10120702_51_dialog_content = "(Eclipsian) Eres sabia, señora Forsakin.",
  ui_story_1012_10120702_52_dialog_content = "(Eclipsian) ¿Qué estás haciendo? ¡Agárralo, pero no lo mates! Lo necesito vivo.",
  ui_story_1012_10120702_53_dialog_content = "(Eclipsiano) Roger—",
  ui_story_1012_10120702_54_dialog_content = "<color=#e8d9bb><size=45>¡Auge!</size></color>",
  ui_story_1012_10120702_55_dialog_content = "Ha sido un tiempo, Forsakin.",
  ui_story_1012_10120702_56_dialog_content = "Pensé que tendrías una tripulación más fuerte ahora.",
  ui_story_1012_10120702_57_dialog_content = "Explosión...",
  ui_story_1012_10120702_58_dialog_content = "(Eclipsian) ¡Todas las manos! ¡Ataque!",
  ui_story_1012_10120702_59_dialog_content = "Gaaaaaah!!!",
  ui_story_1012_10120702_60_dialog_content = "¡Golpe de leopardo!",
  ui_story_1012_10120702_61_dialog_content = "PlayerName? Barton?!",
  ui_story_1012_10120702_62_dialog_content = "Pero eso debe significar... ¡Chord Link tuvo éxito!",
  ui_story_1012_10120702_63_dialog_content = "¡Jajaja! ¡Claro que sí!",
  ui_story_1012_10120702_64_dialog_content = "Rápido, ve a rescatar Vice. Tu equipo la va a necesitar, ¿verdad?",
  ui_story_1012_10120702_65_dialog_content = "En cuanto a aquí... Puedo limpiar.",
  ui_story_1012_10120702_66_dialog_content = "...",
  ui_story_1012_10120702_67_dialog_content = "(Eclipsian) ¡Retrocede y reagrupate con las fuerzas principales de Eclipse!",
  ui_story_1012_10120702_68_dialog_content = "(Eclipsian) Como... como ordenes.",
  ui_story_1012_10120702_69_dialog_content = "¡Quédate quieto, maldita sea!",
  ui_story_1012_10120702_70_dialog_content = "¡Qué grupo de derrochadores desvergonzados y descarados!",
  ui_story_1012_10120702_71_dialog_content = "Estás bien, Carleen? Eso podría haberse puesto feo, ¿estás bien...?",
  ui_story_1012_10120702_72_dialog_content = "Estoy bien. No podemos perder el tiempo, PlayerName...",
  ui_story_1012_10120702_73_dialog_content = "tenemos que rescatar Vice, ¡ahora!",
  ui_story_1012_10120702_74_dialog_content = "Ahí no te equivocas. Hagamos la sincronización.",
  ui_story_1012_10120702_75_dialog_content = "(Entonces... Por favor trabaja, Chord Link.)",
  ui_story_1012_10120702_76_dialog_content = "(Espero que despiertes, Vice...)",
  ui_story_1012_10120702_77_dialog_content = "<color=#e8d9bb>Alerta del sistema: Chord Link ya está operativo...</color>",
  ui_story_1012_10120801_1_dialog_content = "<color=#e8d9bb>Alerta del sistema: Chord Link ahora está activo... No interrumpa el proceso de sincronización...</color>",
  ui_story_1012_10120801_2_dialog_content = "...",
  ui_story_1012_10120801_3_dialog_content = "...",
  ui_story_1012_10120801_4_dialog_content = "¡Ha estado funcionando durante mucho tiempo! ¿Lo que da?",
  ui_story_1012_10120801_5_dialog_content = "Cálmate, PlayerName. Dar Vice a veces.",
  ui_story_1012_10120801_6_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1012_10120801_7_dialog_content = "De cualquier manera, ¡¿no ha estado ocurriendo demasiado tiempo la Sincronización?!",
  ui_story_1012_10120801_8_dialog_content = "Ahora que lo pienso... no tuve que esperar tanto para Barton despertarse.",
  ui_story_1012_10120801_9_dialog_content = "Qué hacemos, PlayerName?",
  ui_story_1012_10120801_10_dialog_content = "(Carleen...)",
  ui_story_1012_10120801_11_dialog_content = "(Bueno, será mejor que me calme).",
  ui_story_1012_10120801_12_dialog_content = "Seguimos las instrucciones de Chord Link al pie de la letra, ¿verdad? Obtuvo Vice para acostarse en él.",
  ui_story_1012_10120801_13_dialog_content = "Todo es igual a lo que Barton pasó por.",
  ui_story_1012_10120801_14_dialog_content = "No recibimos ninguna alerta de mal funcionamiento con Chord Link o Neural Aux.",
  ui_story_1012_10120801_15_dialog_content = "Eso es lo que me hace pensar que tal vez el problema es con...",
  ui_story_1012_10120801_16_option_content = "ViceHibernación.",
  ui_story_1012_10120801_17_dialog_content = "Ya veo. Supongo que esa es la única explicación.",
  ui_story_1012_10120801_18_dialog_content = "¿El General Illumina no resultó herido también, pero no perdió el conocimiento?",
  ui_story_1012_10120801_19_dialog_content = "Entonces, a pesar de las graves heridas, se despertó con un cuerpo más fuerte.",
  ui_story_1012_10120801_20_option_content = "Forsakinla destrucción.",
  ui_story_1012_10120801_21_dialog_content = "¿En serio? Que hizo Forsakin hacer...?",
  ui_story_1012_10120801_22_dialog_content = "Pero... ForsakinLos eclipses de ahora ni siquiera estaban cerca del Chord Link...",
  ui_story_1012_10120801_23_dialog_content = "Y ya habían sido derribados por el General Illumina.",
  ui_story_1012_10120801_24_dialog_content = "Esto me hace pensar que... El problema tiene que ser con la hibernación.",
  ui_story_1012_10120801_25_dialog_content = "Tiene que ser. Piensa en los datos que acabamos de ver en el Sistema Circular...",
  ui_story_1012_10120801_26_dialog_content = "Sujeto... No se pudo recuperar de la hibernación... Físico... Los signos de vida se desvanecieron.",
  ui_story_1012_10120801_27_dialog_content = "Sujeto... No se pudo recuperar de la hibernación... Exhibido... Signos de vida...",
  ui_story_1012_10120801_28_dialog_content = "Sujeto... No se pudo recuperar... En el experimento...",
  ui_story_1012_10120801_29_dialog_content = "Todos esos Caelestites que terminaron como sujetos de prueba tenían algo en común—",
  ui_story_1012_10120801_30_dialog_content = "Hibernación.",
  ui_story_1012_10120801_31_dialog_content = "¿Pero cómo? ¿Cómo podría ser esto?",
  ui_story_1012_10120801_32_dialog_content = "(¿Es posible que este sea su destino compartido? ¿No recuperarse de la hibernación?)",
  ui_story_1012_10120801_33_dialog_content = "(Si esto es cierto, entonces... Vice!)",
  ui_story_1012_10120801_34_dialog_content = "PlayerName.",
  ui_story_1012_10120801_35_dialog_content = "¿PlayerName?",
  ui_story_1012_10120801_36_dialog_content = "Re-Reinhardt?!",
  ui_story_1012_10120801_37_dialog_content = "Al menos tu señal parece ser lo suficientemente clara.",
  ui_story_1012_10120801_38_dialog_content = "¿Cuál es la situación allí? ¿Tienes idea del escándalo que estás haciendo?",
  ui_story_1012_10120801_39_dialog_content = "¡Lo-lo siento!",
  ui_story_1012_10120801_40_dialog_content = "Jajajaja! No te estoy culpando.",
  ui_story_1012_10120801_41_dialog_content = "Solo quiero recordarles que, en medio de toda la agitación reciente en Eraveil, no es solo Illumina quien está escuchando.",
  ui_story_1012_10120801_42_dialog_content = "Asegúrate de nunca ceder toda la iniciativa...",
  ui_story_1012_10120801_43_dialog_content = "Después de todo, eres el único que puede traer cambios a Eraveil.",
  ui_story_1012_10120801_44_dialog_content = "Te veo en un rato.",
  ui_story_1012_10120801_45_dialog_content = "Sí, Reinhardt.",
  ui_story_1012_10120801_46_dialog_content = "Ella no está equivocada.",
  ui_story_1012_10120801_47_dialog_content = "Actualmente estamos completamente ciegos en cuanto a lo que está sucediendo fuera de la torre. Esta es una mala situación para nosotros.",
  ui_story_1012_10120801_48_dialog_content = "Entonces, ¿cómo podemos saber qué está pasando?",
  ui_story_1012_10120801_49_dialog_content = "Bartonprobablemente todavía esté lidiando con Forsakin. No quiero molestarlo y causar problemas...",
  ui_story_1012_10120801_50_dialog_content = "Recibido... Analizando pregunta...",
  ui_story_1012_10120801_51_dialog_content = "¡¿Eh?!",
  ui_story_1012_10120801_52_dialog_content = "¿Hay alguna forma de evitar esto, Neural Aux?",
  ui_story_1012_10120801_53_dialog_content = "Activación del monitor de torre externo.",
  ui_story_1012_10120801_54_dialog_content = "Uf... Uf...",
  ui_story_1012_10120801_55_dialog_content = "Deja de correr, Forsakin!",
  ui_story_1012_10120801_56_dialog_content = "¡Enfréntame como un verdadero guerrero!",
  ui_story_1012_10120801_57_dialog_content = "¿Eh?",
  ui_story_1012_10120801_58_dialog_content = "¿Qué...?",
  ui_story_1012_10120801_59_dialog_content = "Bueno, yo nunca... ¡Hace mucho tiempo que no veo algo así!",
  ui_story_1012_10120801_60_dialog_content = "(¡Mira todos los refuerzos movilizados!)",
  ui_story_1012_10120801_61_dialog_content = "(Esto está comenzando a compartir una horrible similitud con la Crisis de Darkover hace una década más o menos).",
  ui_story_1012_10120801_62_dialog_content = "(¿Cuánto tiempo puedo... Retenerlos por PlayerName y esos chicos?)",
  ui_story_1012_10120801_63_dialog_content = "¿Oh?",
  ui_story_1012_10120801_64_dialog_content = "Parece que estás en un lugar de molestia, Forsakin.",
  ui_story_1012_10120801_65_dialog_content = "Quizás no seas tan terco la próxima vez, ¿eh?",
  ui_story_1012_10120801_66_dialog_content = "Tal inconveniente debe haber convertido todos sus esfuerzos en vano.",
  ui_story_1012_10120801_67_dialog_content = "Creo que encontrará que ha sido muy gratificante.",
  ui_story_1012_10120801_68_dialog_content = "Y de todos modos, no es asunto tuyo.",
  ui_story_1012_10120801_69_dialog_content = "No intentes salvar el día después de quedarte al margen.",
  ui_story_1012_10120801_70_dialog_content = "Hmph. Lo que sea.",
  ui_story_1012_10120801_71_dialog_content = "Que mala vida. Estás pidiendo ayuda porque no puedes vencerlos, Forsakin?",
  ui_story_1012_10120801_72_dialog_content = "(¡Allí! ¡Un hueco en las defensas!)",
  ui_story_1012_10120801_73_dialog_content = "Leopardo... ¡Huelga!",
  ui_story_1012_10120801_74_dialog_content = "Argh...",
  ui_story_1012_10120801_75_dialog_content = "Eclipse no se ha reunido para ti, ya sabes.",
  ui_story_1012_10120801_76_dialog_content = "Solo ríndete, deja de resistirte.",
  ui_story_1012_10120801_77_dialog_content = "Has estado ganando tiempo para esa Caelestita desde que llegaste a la Torre Blanca.",
  ui_story_1012_10120801_78_dialog_content = "tengo razón, ¿no?",
  ui_story_1012_10120801_79_dialog_content = "...",
  ui_story_1012_10120801_80_dialog_content = "(Eclipsian) Agarrarlo.",
  ui_story_1012_10120801_81_dialog_content = "¡¡¡Gahhhhhh!!!",
  ui_story_1012_10120801_82_dialog_content = "<color=#e8d9bb>¡Boom! ¡Boom!</color>",
  ui_story_1012_10120801_83_dialog_content = "Está...",
  ui_story_1012_10120801_84_dialog_content = "Bueno, esta torre es aún más extraordinaria de cerca.",
  ui_story_1012_10120801_85_dialog_content = "Todo es como mis sueños lo predijeron...",
  ui_story_1012_10120801_86_dialog_content = "No importa hacia dónde se dirija el mundo, destrucción o renacimiento, la confrontación entre Eraveil y los Eclipsites es inevitable.",
  ui_story_1012_10120801_87_dialog_content = "(¿El líder de Northland...?)",
  ui_story_1012_10120801_88_dialog_content = "(¿Ella me dio una mano hace un momento...?)",
  ui_story_1012_10120801_89_dialog_content = "Comandante Barton, estoy seguro de que conoce la Estatua 42 de las Regulaciones Militares de Illumina, que trata sobre la insubordinación.",
  ui_story_1012_10120801_90_dialog_content = "¡¿Eh?!",
  ui_story_1012_10120801_91_dialog_content = "Illumina siempre busca la justicia, en estricto apego a las normas. Los delincuentes particularmente atroces serán sometidos a consejo de guerra.",
  ui_story_1012_10120801_92_dialog_content = "—Pero, por supuesto, esto tendrá que esperar hasta después de la guerra.",
  ui_story_1012_10120801_93_dialog_content = "... Gran Mariscal?",
  ui_story_1012_10120801_94_dialog_content = "Los batallones de refuerzo de vanguardia ya casi están aquí, así que ve a reunirte con ellos.",
  ui_story_1012_10120801_95_dialog_content = "¿Vaya? Esto es... ¿Asistió a algún tipo de entrenamiento especial de emergencia? Te ves un poco diferente...",
  ui_story_1012_10120801_96_dialog_content = "De todos modos, da lo mejor de ti para esta batalla, Comandante. Barton!",
  ui_story_1012_10120801_97_dialog_content = "¡Vea si puede expiar sus errores en el campo de batalla!",
  ui_story_1012_10120801_98_dialog_content = "...",
  ui_story_1012_10120801_99_dialog_content = "¡Entendido!",
  ui_story_1012_10120801_100_dialog_content = "Solo espera y verás, Gran Mariscal.",
  ui_story_1012_10120801_101_dialog_content = "Supervisión externa completada.",
  ui_story_1012_10120801_102_dialog_content = "Su Majestad, y Reinhardt...",
  ui_story_1012_10120801_103_dialog_content = "Parece que tanto Northland como Illumina están en vigor.",
  ui_story_1012_10120801_104_dialog_content = "Pero... Incluso con todas sus tropas, ¿será suficiente para contrarrestar el Eclipse?",
  ui_story_1012_10120801_105_dialog_content = "Tenemos que pensar en algo, PlayerName!",
  ui_story_1012_10120801_106_dialog_content = "¡Lo sé! Diría que nuestra mejor apuesta es aprovechar el Obelisco del Retorno, ya que está en una posición bastante central.",
  ui_story_1012_10120801_107_dialog_content = "Neural Aux, ¿qué tan buenas son las defensas de esta torre?",
  ui_story_1012_10120801_108_dialog_content = "Recibido... Analizando pregunta...",
  ui_story_1012_10120801_109_dialog_content = "Dentro del Obelisco del Retorno se encuentra el último sistema de defensa: El<color=#FFB400>acorde de la ley</color>.",
  ui_story_1012_10120801_110_dialog_content = "Este es el activo más fuerte y único de Eraveil, y también la última línea de defensa.",
  ui_story_1012_10120801_111_dialog_content = "Así que...",
  ui_story_1012_10120801_112_dialog_content = "El Acorde de la Ley es difícil de activar y costoso de usar.",
  ui_story_1012_10120801_113_dialog_content = "No puedo autorizar a ningún Caelestita a activar el Acorde de la Ley.",
  ui_story_1012_10120801_114_dialog_content = "¿Autorización? ¿Por qué siempre hay un problema con la autorización?",
  ui_story_1012_10120801_115_dialog_content = "Repito: El Acorde de la Ley es difícil de activar y costoso de usar.",
  ui_story_1012_10120801_116_dialog_content = "No puedo autorizar a ningún Caelestite...",
  ui_story_1012_10120801_117_dialog_content = "No tiene sentido discutir con una máquina, PlayerName.",
  ui_story_1012_10120801_118_dialog_content = "¡Tenemos nuestro propio libre albedrío y no podemos dejarnos bloquear por una mera máquina!",
  ui_story_1012_10120801_119_dialog_content = "(Carleentiene razón. Y de todos modos, no puedo volver a pasar por eso...)",
  ui_story_1012_10120801_120_dialog_content = "(Esa impotencia ante los Eclipsites, donde ningún Caelestite puede hacer nada.)",
  ui_story_1012_10120801_121_dialog_content = "¡No me voy a quedar fuera de esto! ¡Voy a llevarlo al Eclipse esta vez!",
  ui_story_1012_10120801_122_dialog_content = "Te siento, PlayerName. Pero...",
  ui_story_1012_10120801_123_dialog_content = "Vice...",
  ui_story_1012_10120801_124_dialog_content = "Dado que la sincronización aún no está completa, Vice va a tener que seguir aguantando el proceso.",
  ui_story_1012_10120801_125_dialog_content = "PlayerName, una vez que salgamos de Chord Zone, hagamos que Neural Aux cambie la estructura de la entrada.",
  ui_story_1012_10120801_126_dialog_content = "Asegúrate de sellar la entrada a la Zona de Cuerdas y cambia la estructura del pasadizo secreto...",
  ui_story_1012_10120801_127_dialog_content = "hagamos un <color=#FFB400>Capullo</color> lo suficientemente fuerte para Vice.",
  ui_story_1012_10120801_128_dialog_content = "¡Por supuesto!",
  ui_story_1012_10120801_129_dialog_content = "(Por favor, Vice, el Chord Link TIENE que despertarte...)",
  ui_story_1012_10120801_130_dialog_content = "(Todos estamos esperando tu renacimiento.)",
  ui_story_1012_10120801_131_dialog_content = "Te veremos pronto, Vice.",
  ui_story_1012_10120901_1_dialog_content = "<color=#e8d9bb>Pasaje de entrada, torre principal</color>",
  ui_story_1012_10120901_2_dialog_content = "<color=#e8d9bb>Golpeteo de pitidos... Golpeteo de pitidos...</color>",
  ui_story_1012_10120901_3_dialog_content = "La entrada por la que entramos está un poco más adelante.",
  ui_story_1012_10120901_4_dialog_content = "No quiero sonar sermoneador, PlayerName, pero...",
  ui_story_1012_10120901_5_dialog_content = "No tengas miedo.",
  ui_story_1012_10120901_6_dialog_content = "C-Carleen...?",
  ui_story_1012_10120901_7_dialog_content = "Nunca lo olvides: estás luchando por tu tierra, tu hogar.",
  ui_story_1012_10120901_8_dialog_content = "Este es un gran honor, y no hay que temerlo.",
  ui_story_1012_10120901_9_dialog_content = "Su Majestad... me enseñó esto.",
  ui_story_1012_10120901_10_dialog_content = "Gracias, Carleen.",
  ui_story_1012_10120901_11_dialog_content = "Estoy listo para lo que venga.",
  ui_story_1012_10120901_12_dialog_content = "Bien. Bueno, ¡vamos a aventurarnos de regreso al mundo fuera de la torre, juntos!",
  ui_story_1012_10120901_13_dialog_content = "Es... Es un...",
  ui_story_1012_10120901_14_dialog_content = "<color=#e8d9bb>Kkkkkkrack... Kkkkkkrack...</color>",
  ui_story_1012_10120901_15_dialog_content = "<anim type=Shake><size=50>¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡</size></anim>",
  ui_story_1012_10120901_16_dialog_content = "Eraveil no se veía así... en aquel entonces...",
  ui_story_1012_10120901_17_dialog_content = "PlayerName, ¡Estar atento!",
  ui_story_1012_10120901_18_dialog_content = "Gaah...",
  ui_story_1012_10120901_19_dialog_content = "Tsk, tsk, tsk...",
  ui_story_1012_10120901_20_dialog_content = "Tener una mejor inteligencia vale más que la pura potencia de fuego.",
  ui_story_1012_10120901_21_dialog_content = "La situación actual ya es bastante clara, de todos modos.",
  ui_story_1012_10120901_22_dialog_content = "Tus fuerzas no se pueden comparar con las del ejército Eclipse.",
  ui_story_1012_10120901_23_dialog_content = "Oh, ¿es una extraña tradición de Eclipse decir tonterías antes de una pelea?",
  ui_story_1012_10120901_24_dialog_content = "Las palabras vacías en realidad no te hacen más fuerte, ¿sabes?",
  ui_story_1012_10120901_24X1_dialog_content = "(... Ahora que lo pienso, Reina Bethlehem debería estar aquí ya.)",
  ui_story_1012_10120901_24X2_dialog_content = "PlayerName, me dirigiré al otro lado del Obelisco del Retorno para investigar y reunirme con Queen Bethlehem.",
  ui_story_1012_10120901_24X3_dialog_content = "Quédate aquí con estos refuerzos de Illumina, ¿de acuerdo?",
  ui_story_1012_10120901_24X4_dialog_content = "Claro, pero recuerda mantenerte en contacto.",
  ui_story_1012_10120901_24X5_dialog_content = "Cuídate entonces, Carleen.",
  ui_story_1012_10120901_25_dialog_content = "Actualización de inteligencia para el Gran Mariscal: Los refuerzos de la 2.ª Legión se han reunido con el Comandante Barton.",
  ui_story_1012_10120901_26_dialog_content = "En espera de sus órdenes.",
  ui_story_1012_10120901_27_dialog_content = "Bien. Indíqueles que concentren su fuerza principal en la línea del frente y ataquen en formación cerrada.",
  ui_story_1012_10120901_28_dialog_content = "Divide las fuerzas restantes en dos contingentes y ata las reservas de Eclipse desde atrás.",
  ui_story_1012_10120901_29_dialog_content = "¡Entendido!",
  ui_story_1012_10120901_30_dialog_content = "Entonces, ¿por qué sigues aquí?",
  ui_story_1012_10120901_31_dialog_content = "... Gran Mariscal, aún no me ha asignado una misión de combate.",
  ui_story_1012_10120901_32_dialog_content = "¡Jajaja! Bien entonces. Retírate, defiende esa torre y espera.",
  ui_story_1012_10120901_33_dialog_content = "¿Defender la... Torre?",
  ui_story_1012_10120901_34_dialog_content = "Ves esa enorme Torre Blanca, ¿verdad?",
  ui_story_1012_10120901_35_dialog_content = "Sí, pero...",
  ui_story_1012_10120901_36_dialog_content = "Esa torre es todo el propósito de nuestra misión aquí.",
  ui_story_1012_10120901_37_dialog_content = "Si bien esta misión puede no estar en primera línea, es de suma importancia.",
  ui_story_1012_10120901_38_dialog_content = "Te responderé en breve, y todavía necesitaré que me transmitas algo de inteligencia, así que no te preocupes.",
  ui_story_1012_10120901_39_dialog_content = "... ¡Sí, señora!",
  ui_story_1012_10120901_40_dialog_content = "Como para PlayerName, solo quédate conmigo por ahora.",
  ui_story_1012_10120901_41_dialog_content = "Uh... ¿No sois un par de chicos bajitos...?",
  ui_story_1012_10120901_42_dialog_content = "Reinhardt... Vice, ella...",
  ui_story_1012_10120901_43_dialog_content = "Comandante Barton ya me ha informado sobre el teniente Vice.",
  ui_story_1012_10120901_44_dialog_content = "Debes tener fe en lo que hay dentro de esta torre. Es un gran tesoro que tus antepasados te dejaron.",
  ui_story_1012_10120901_45_dialog_content = "Además, con la guerra que se avecina, tenemos que mantenernos positivos.",
  ui_story_1012_10120901_46_dialog_content = "¡Mantén la cabeza y la moral en alto!",
  ui_story_1012_10120901_47_dialog_content = "...¡Voy a!",
  ui_story_1012_10120901_48_dialog_content = "¡Ese es el espíritu!",
  ui_story_1012_10120901_49_dialog_content = "<color=#e8d9bb>Mientras tanto, al otro lado de la Torre</color>",
  ui_story_1012_10120901_50_dialog_content = "<size=45>¡Majestad!</size>",
  ui_story_1012_10120901_51_dialog_content = "¡Fui negligente con mi deber como guardaespaldas de Su Majestad!",
  ui_story_1012_10120901_52_dialog_content = "¡Le pediría a Su Majestad que ya no se enfrente solo a los Eclipsites sin mí!",
  ui_story_1012_10120901_53_dialog_content = "¡Permítame ser su valiente vanguardia, Su Majestad!",
  ui_story_1012_10120901_54_dialog_content = "Tiare, has estado en la naturaleza nevada durante tantos años. Sabes que tus puntos fuertes son la vigilancia y la infiltración...",
  ui_story_1012_10120901_55_dialog_content = "Tus puntos fuertes resultan ser la estrategia de Northland para apoyar a Eraveil.",
  ui_story_1012_10120901_56_dialog_content = "Dejemos el frente a esos aurorianos sedientos de batalla. Adoptaremos el enfoque más conservador y haremos guardia junto a esta Torre Blanca.",
  ui_story_1012_10120901_57_dialog_content = "He llamado a todas las fuerzas de Northland a los alrededores de la Torre Blanca y las he puesto en alerta máxima.",
  ui_story_1012_10120901_58_dialog_content = "A menos que las líneas del frente colapsen, esos eclipses no penetrarán tan fácilmente.",
  ui_story_1012_10120901_59_dialog_content = "¡Muy bien, Su Majestad!",
  ui_story_1012_10120901_60_dialog_content = "... Una cosa más. Puedes prescindir de la formalidad mientras estamos en el campo de batalla.",
  ui_story_1012_10120901_61_dialog_content = "Llámame Bethlehem.",
  ui_story_1012_10120901_62_dialog_content = "Ahora ven, cúbrete detrás de este escudo.",
  ui_story_1012_10120901_63_dialog_content = "¡Muy bien! ¡Si su Majestad!",
  ui_story_1012_10120901_64_dialog_content = "¡¿Su Majestad?! ¡No te esperaba tan pronto!",
  ui_story_1012_10120901_65_dialog_content = "Ha sido un tiempo, Carleen.",
  ui_story_1012_10120901_66_dialog_content = "Por supuesto, ahora no es el momento de recordar. Considera las circunstancias actuales como una prueba...",
  ui_story_1012_10120901_67_dialog_content = "Déjame ver cuánto puedes manejar tú solo.",
  ui_story_1012_10120901_68_dialog_content = "Carleen ¡difícilmente está sola!",
  ui_story_1012_10120901_69_dialog_content = "¿Beretta?",
  ui_story_1012_10120901_70_dialog_content = "¿No estás...? ¿Cómo es que no estás con Raphael?",
  ui_story_1012_10120901_71_dialog_content = "Su Alteza, traigo a los valientes Lumo Knights en su ayuda.",
  ui_story_1012_10120901_72_dialog_content = "Esperamos tu orden, <color=#FFB400>Capitán Carleen</color>!",
  ui_story_1012_10120901_73_dialog_content = "(Ya veo. ¿Esto es obra de mi padre?)",
  ui_story_1012_10120901_74_dialog_content = "(Me sorprende que mi padre se haya apresurado a enviar tropas y dejar clara su posición).",
  ui_story_1012_10120901_75_dialog_content = "¡Noche Blanca en lo alto, levanta tus armas en alto y avanza conmigo!",
  ui_story_1012_10120901_76_dialog_content = "¡Así como el día atraviesa la noche, la oscuridad nunca puede ocultarse!",
  ui_story_1012_10120901_77_dialog_content = "¡Noche Blanca en lo alto!",
  ui_story_1012_10120901_78_dialog_content = "<color=#e8d9bb>Guarnición Eclipse en Eraveil</color>",
  ui_story_1012_10120901_79_dialog_content = "(Eclipsian) ¿Incluso Lumopolis envió fuerzas? Ese viejo tonto es demasiado.",
  ui_story_1012_10120901_80_dialog_content = "(Eclipsian) Lumopolis pagará el precio por enfrentarse a Eclipse.",
  ui_story_1012_10120901_81_dialog_content = "(Eclipsian) Tampoco va a terminar ahí. ¡Una vez que Eraveil sea nuestro, nada podrá impedir que tomemos todo el continente!",
  ui_story_1012_10120901_82_dialog_content = "(Eclipsian) Tsk, tsk, tsk...",
  ui_story_1012_10120901_83_dialog_content = "(Eclipsian) Mis camaradas, nuestro tiempo se acerca...",
  ui_story_1012_10120901_84_dialog_content = "(Eclipsian) La victoria está a nuestro alcance.",
  ui_story_1012_10120901_85_dialog_content = "(Eclipsian) ¡Eraveil volverá a enrojecerse de sangre!",
  ui_story_1012_10120901_86_dialog_content = "(Eclipsian) ¡A Eraveil! ¡Toma la Torre Blanca! ¡Exterminar a todos los que se oponen a nosotros!",
  ui_story_1012_10120901_87_dialog_content = "<size=45>(Eclipsian) A LAS ARMAS!!</size>",
  ui_story_1012_10120901_88_dialog_content = "<anim type=Shake><size=45>¡¡¡Gahhhhhh!!!</size></anim>",
  ui_story_1012_10120901_89_dialog_content = "(Eclipsian) Este es el último día que sale el sol sobre Astra...",
  ui_story_1012_10121002_1_dialog_content = "Tu mando es tan firme como siempre, PlayerName.",
  ui_story_1012_10121002_2_dialog_content = "Capaz de mantener la cabeza fría en tales circunstancias... ¿Debería llamarte sereno o simple?",
  ui_story_1012_10121002_3_dialog_content = "Creo que estoy empezando a entender cómo te has ganado tanta confianza de tantos.",
  ui_story_1012_10121002_4_dialog_content = "Eso es un poco demasiado, sin duda...",
  ui_story_1012_10121002_5_dialog_content = "Nueva información recién llegada: ¡la primera ola de ataques de Eclipse ha sido repelida con éxito!",
  ui_story_1012_10121002_6_dialog_content = "Aunque la situación es fluida, parece que la línea de refuerzos se mantiene.",
  ui_story_1012_10121002_7_dialog_content = "Excelente. Asegúrese de mantener el ritmo, todos, ya que eso fue solo el comienzo.",
  ui_story_1012_10121002_8_dialog_content = "Notificar al comandante Barton para liderar los refuerzos y coordinar con nuestros aliados.",
  ui_story_1012_10121002_9_dialog_content = "Sí.",
  ui_story_1012_10121002_10_dialog_content = "A pesar de que Carleenya no es un niño...",
  ui_story_1012_10121002_11_dialog_content = "Probablemente no se sentiría muy cómoda peleando junto a tus tropas en el frente.",
  ui_story_1012_10121002_12_dialog_content = "¡Ja ja! Un soldado que vive una vida fácil nunca llegará a ser general.",
  ui_story_1012_10121002_13_dialog_content = "Escuché que te levantaste Carleen?",
  ui_story_1012_10121002_14_dialog_content = "Le pareces más un padre que Schwartz, ¡Su Majestad!",
  ui_story_1012_10121002_15_dialog_content = "... Mira cómo hablas, mi señora Reinhardt.",
  ui_story_1012_10121002_16_dialog_content = "¡Por favor, diríjase a Su Majestad con respeto!",
  ui_story_1012_10121002_17_dialog_content = "Gaaaaaah!!!",
  ui_story_1012_10121002_18_dialog_content = "Argh...",
  ui_story_1012_10121002_19_dialog_content = "¡Cuando el hielo se derrite!",
  ui_story_1012_10121002_20_dialog_content = "Prefiero no charlar ociosamente mientras ruge la batalla.",
  ui_story_1012_10121002_21_dialog_content = "Aunque la situación aún está bajo control, no se permita distraerse.",
  ui_story_1012_10121002_22_dialog_content = "Bueno, entonces, llevaré a las tropas restantes a encontrarse con el Eclipse frente a la torre.",
  ui_story_1012_10121002_23_dialog_content = "¡Las cosas parecen ir bien!",
  ui_story_1012_10121002_24_dialog_content = "<color=#e8d9bb>Frente de batalla, Eraveil</color>",
  ui_story_1012_10121002_25_dialog_content = "¡¿Qué?! ¿Trabajar con esos tipos de Lumopolis?",
  ui_story_1012_10121002_26_dialog_content = "Así es.",
  ui_story_1012_10121002_27_dialog_content = "Pff, bien, lo que sea. Sé la puntuación. Ningún hombre amenaza a un mensajero.",
  ui_story_1012_10121002_28_dialog_content = "¡¿Eh?!",
  ui_story_1012_10121002_29_dialog_content = "Gaaaaaah!!!",
  ui_story_1012_10121002_30_dialog_content = "Gaah...",
  ui_story_1012_10121002_31_dialog_content = "Muy bien, parece que todavía tenemos algo de limpieza que hacer aquí. Será mejor que vuelvas con el Gran Mariscal. Ve a proteger esa Torre.",
  ui_story_1012_10121002_32_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10121002_33_dialog_content = "¡Ah!",
  ui_story_1012_10121002_34_dialog_content = "¡Oye!",
  ui_story_1012_10121002_35_dialog_content = "Por Illumina... ¡¿Qué estás haciendo?!",
  ui_story_1012_10121002_36_dialog_content = "¡No fue a propósito! El suelo de repente tembló hace un momento...",
  ui_story_1012_10121002_37_dialog_content = "¡De verdad, no te metas en líos!",
  ui_story_1012_10121002_38_dialog_content = "<color=#e8d9bb>¡¡Boom—!!</color>",
  ui_story_1012_10121002_39_dialog_content = "¡¿Gah... gah...?!",
  ui_story_1012_10121002_40_dialog_content = "Espera un segundo... ¡¿Nos acaban de disparar un Eclipsite?!",
  ui_story_1012_10121002_41_dialog_content = "Qué conveniente.",
  ui_story_1012_10121002_42_dialog_content = "Gaah...",
  ui_story_1012_10121002_43_dialog_content = "Esta es la primera línea, no un patio de recreo. Si no estás aquí para luchar...",
  ui_story_1012_10121002_44_dialog_content = "Entonces también podrías irte a casa.",
  ui_story_1012_10121002_45_dialog_content = "¡Entendido!",
  ui_story_1012_10121002_46_dialog_content = "Pff... ¿Tienes qué, exactamente?",
  ui_story_1012_10121002_47_dialog_content = "¡Lo siento!",
  ui_story_1012_10121002_48_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_1012_10121002_49_dialog_content = "Esta concha es?",
  ui_story_1012_10121002_50_dialog_content = "Eso es extraño. No estaba dirigido a nosotros esta vez, y...",
  ui_story_1012_10121002_51_dialog_content = "Parecía proyectar una sombra inquietante, lo que solo podía significar...",
  ui_story_1012_10121002_52_dialog_content = "¡Maldita sea!",
  ui_story_1012_10121002_53_dialog_content = "Es <color=#FFB400>Flujo oscuro</color>!",
  ui_story_1012_10121002_54_dialog_content = "Esos primeros proyectiles solo estaban probando el agua...",
  ui_story_1012_10121002_55_dialog_content = "Este <color=#FFB400>Concha de flujo oscuro</color> está dirigido al Obelisco del Retorno!",
  ui_story_1012_10121002_56_dialog_content = "(¡¿Obelisco del Retorno?!)",
  ui_story_1012_10121002_57_dialog_content = "¡Escuchad, refuerzos de la 2ª Legión! ¡La batalla está cambiando!",
  ui_story_1012_10121002_58_dialog_content = "¡Sube al Obelisco del Retorno y apoya al Gran Mariscal!",
  ui_story_1012_10121101_1_dialog_content = "<color=#e8d9bb>Obelisco del Retorno, Eraveil</color>",
  ui_story_1012_10121101_2_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_1012_10121101_3_dialog_content = "(¿Eh? ¡Algo explotó arriba!)",
  ui_story_1012_10121101_4_dialog_content = "(¡Vamos, tenemos que unirnos para proteger a Su Majestad!)",
  ui_story_1012_10121101_5_dialog_content = "(¿Qué está pasando? ¡Me siento enfermo de repente!)",
  ui_story_1012_10121101_6_dialog_content = "(Una náusea desagradablemente familiar...)",
  ui_story_1012_10121101_7_dialog_content = "¡¿?!",
  ui_story_1012_10121101_8_dialog_content = "Es <color=#FFB400>Flujo oscuro</color>!",
  ui_story_1012_10121101_9_dialog_content = "¡Congelación instantánea!",
  ui_story_1012_10121101_10_dialog_content = "La protección solo puede cubrir un área limitada. Por favor, ¿todos pueden acurrucarse?",
  ui_story_1012_10121101_11_dialog_content = "¡No dejes que el Darkflow te afecte!",
  ui_story_1012_10121101_12_dialog_content = "*Tos* ¡Este poquito no tendrá ningún efecto!",
  ui_story_1012_10121101_13_dialog_content = "La evasión no es una estrategia viable a largo plazo.",
  ui_story_1012_10121101_14_dialog_content = "A este ritmo, vamos a tener que idear nuevas tácticas, y rápido.",
  ui_story_1012_10121101_15_dialog_content = "Gran Mariscal!",
  ui_story_1012_10121101_16_dialog_content = "Momento perfecto, Anatoli...",
  ui_story_1012_10121101_17_dialog_content = "¿Vaya? Y parece que también trajiste a las tropas clave.",
  ui_story_1012_10121101_18_dialog_content = "Comandante de la 2ª Legión Barton, reportando en.",
  ui_story_1012_10121101_19_dialog_content = "¿Cuáles son sus órdenes, Gran Mariscal?",
  ui_story_1012_10121101_20_dialog_content = "Aprovecha la oportunidad fugaz para el combate.",
  ui_story_1012_10121101_21_dialog_content = "Ah, justo a tiempo, comandante Barton.",
  ui_story_1012_10121101_22_dialog_content = "¡Vaya! Eh, eh... ¿Gran Mariscal?",
  ui_story_1012_10121101_23_dialog_content = "¡Llena la cabeza de este soldado con algo más que inteligencia!",
  ui_story_1012_10121101_24_dialog_content = "Quédate aquí y aleja la potencia de fuego de Eclipse de la Torre Blanca. ¿Puedes manejar eso?",
  ui_story_1012_10121101_25_dialog_content = "Quiero enseñarles que no solo el Eclipse puede ser astuto.",
  ui_story_1012_10121101_26_dialog_content = "Hmm, ¿estás planeando un ataque furtivo? Lo apruebo.",
  ui_story_1012_10121101_27_dialog_content = "Vete entonces. Puedo cuidar este lugar.",
  ui_story_1012_10121101_28_dialog_content = "(Viendo Reinhardtla energía y el espíritu de Darkflow, casi puedo olvidar esa horrible sensación del Darkflow...)",
  ui_story_1012_10121101_29_dialog_content = "(Mientras el Eclipse sigue disparando su siniestro cañón Darkflow directamente hacia nosotros...)",
  ui_story_1012_10121101_30_dialog_content = "(Ella corre hacia la oscuridad con una expresión como si estuviera disfrutando de un paseo primaveral.)",
  ui_story_1012_10121101_31_dialog_content = "(Un genio táctico o un aspirante peligroso... Las opiniones en Illumina ciertamente están divididas).",
  ui_story_1012_10121101_32_dialog_content = "(Pero cualquiera que la haya visto alguna vez en el campo de batalla comprenderá el verdadero significado de Illumina...)",
  ui_story_1012_10121101_33_dialog_content = "(Ella brilla y centellea como Phospherus en la oscuridad sin esperanza.)",
  ui_story_1012_10121101_34_dialog_content = "<size=33>Cuídate de darme una mano, PlayerName?</size>",
  ui_story_1012_10121101_35_dialog_content = "<size=33>Hay algo con lo que solo un Caelestita como tú puede ayudar.</size>",
  ui_story_1012_10121101_36_dialog_content = "¿Eh?",
  ui_story_1012_10121101_37_dialog_content = "¡Hey, espera!",
  ui_story_1012_10121101_38_dialog_content = "¡¿Qué crees que estás haciendo?! ¡No puedes simplemente recogerme!",
  ui_story_1012_10121101_39_dialog_content = "(¿Es una tradición de Illumina simplemente recoger gente cuando quieras?)",
  ui_story_1012_10121101_40_dialog_content = "Jaja... lo siento. ¡Por favor, ten paciencia conmigo un minuto!",
  ui_story_1012_10121101_41_dialog_content = "Se dice que Caelestites puede ver los colores de la Lumina, por lo que debe ser capaz de localizar el <color=#FFB400>fuente del Darkflow</color> ¡también!",
  ui_story_1012_10121101_42_dialog_content = "Por ahora, sea mi navegador.",
  ui_story_1012_10121101_43_dialog_content = "¡Mientras aplastamos los cañones Darkflow del Eclipse!",
  ui_story_1012_10121101_44_dialog_content = "<color=#e8d9bb>Frente de batalla, Eraveil</color>",
  ui_story_1012_10121101_45_dialog_content = "Capitán Carleen, este es el Eclipsite final de esta salida.",
  ui_story_1012_10121101_46_dialog_content = "¿Vamos a cambiar las líneas de batalla con esos tipos de Illumina?",
  ui_story_1012_10121101_47_dialog_content = "No. No podemos permitir brechas en nuestras defensas.",
  ui_story_1012_10121101_48_dialog_content = "Si retrocedemos, solo estamos cediendo terreno al Eclipse.",
  ui_story_1012_10121101_49_dialog_content = "¡Qué curioso!",
  ui_story_1012_10121101_50_dialog_content = "El Señor de Lumopolis está realmente dispuesto a enviar a su querida hija a la guerra...",
  ui_story_1012_10121101_51_dialog_content = "¡¿?!",
  ui_story_1012_10121101_52_dialog_content = "Durante mucho tiempo me he preguntado cómo es bailar tango con una princesa.",
  ui_story_1012_10121101_53_dialog_content = "(Y aquí está. Lo sabía...)",
  ui_story_1012_10121101_54_dialog_content = "Mirren Gautier... ¿No eres más que un oponente derrotado de Lumopolis?",
  ui_story_1012_10121101_55_dialog_content = "¿Eres buscado por el Salón de la Justicia y, sin embargo, te atreves a mostrar tu rostro aquí?",
  ui_story_1012_10121101_56_dialog_content = "¡Ja ja! Entonces, Alteza, mi apariencia debe dejar una impresión tan memorable, ¿no?",
  ui_story_1012_10121101_57_dialog_content = "Bueno, si ese es el caso, entonces supongo que no fue por nada que me torturé con esos experimentos de \"Vista\".",
  ui_story_1012_10121101_57X1_dialog_content = "Solo somos nosotros y algunos de tus secuaces...",
  ui_story_1012_10121101_57X2_dialog_content = "No saquemos conclusiones precipitadas sobre quién mordió el anzuelo.",
  ui_story_1012_10121101_58_dialog_content = "Eres repugnante. Incluso tu voz me hace sentir mal.",
  ui_story_1012_10121101_59_dialog_content = "Ah... ¡Urgh! ¡Hielo!",
  ui_story_1012_10121101_60_dialog_content = "¡¿Qué es esto?! ¿Cómo es que eres como ese bicho raro helado en el dragón?",
  ui_story_1012_10121101_61_dialog_content = "Frost, bicho raro... ¿Estás hablando de Queen? Bethlehem?!",
  ui_story_1012_10121101_62_dialog_content = "¡Cómo te atreves a insultar así a Su Majestad...!",
  ui_story_1012_10121101_63_dialog_content = "¡¡IMPERDONABLE!!",
  ui_story_1012_10121101_64_dialog_content = "<color=#e8d9bb>¡Kaboom!</color>",
  ui_story_1012_10121101_65_dialog_content = "Parece que estás en un pequeño lío.",
  ui_story_1012_10121101_66_dialog_content = "Gracias PlayerName, yo no. Él es el que sintió Mirren GautierDarkflow de...",
  ui_story_1012_10121101_67_dialog_content = "Insistió en que deberíamos venir y ayudarte.",
  ui_story_1012_10121101_68_dialog_content = "Estás aquí ahora, PlayerName, así que no perdamos más tiempo.",
  ui_story_1012_10121101_69_dialog_content = "¡Los cañones de Eclipse se han detenido! ¡Ahora es nuestra oportunidad de poner fin a sus sucios trucos para siempre!",
  ui_story_1012_10121101_70_dialog_content = "En cuanto a Mirren...",
  ui_story_1012_10121101_71_dialog_content = "... ¡¿Eh?!",
  ui_story_1012_10121101_72_dialog_content = "Pff... Es rápido, escurriéndose así.",
  ui_story_1012_10121101_73_dialog_content = "No hay tiempo que perder, entonces. ¡Tenemos que seguir adelante!",
  ui_story_1012_10121101_74_dialog_content = "Mantendré la línea aquí. Lideras a los Lumo Knights y te unes a la fuerza principal.",
  ui_story_1012_10121101_75_dialog_content = "Eclipses acercándose... Flujo oscuro por todas partes... Lo que la Torre Blanca necesita ahora, más que nada, es una defensa constante.",
  ui_story_1012_10121101_76_dialog_content = "Muy bien, ¡hagamos esto!",
  ui_story_1012_10121101_77_dialog_content = "... De todos modos, no te ves tan bien, PlayerName... ¿Estás bien?",
  ui_story_1012_10121101_78_dialog_content = "(El Darkflow es demasiado espeso... Puedo sentirlo en todas partes. Casi puedo saborearlo, olerlo... Es tan repugnante...)",
  ui_story_1012_10121101_79_dialog_content = "(¡Pero es vergonzoso admitir esto!)",
  ui_story_1012_10121101_80_dialog_content = "Hmm... ¡Si estoy un poco pálido, eso solo significa que vamos en la dirección correcta!",
  ui_story_1012_10121101_81_dialog_content = "Vamos a separarnos por ahora. Espera mis buenas noticias, Carleen.",
  ui_story_1012_10121101_82_dialog_content = "Cuídate.",
  ui_story_1012_10121101_83_dialog_content = "Mudarse, PlayerName.",
  ui_story_1012_10121101_84_dialog_content = "Los cañones Darkflow están justo delante. Podríamos estar en una pelea difícil.",
  ui_story_1012_10121102_1_dialog_content = "Muy bien hecho, PlayerName!",
  ui_story_1012_10121102_2_dialog_content = "¡Más como cañones de vidrio!",
  ui_story_1012_10121102_3_dialog_content = "Ese fue el último, ¿verdad?",
  ui_story_1012_10121102_4_dialog_content = "Déjame revisar...",
  ui_story_1012_10121102_5_option_content = "¡Potencia de fuerza!",
  ui_story_1012_10121102_6_dialog_content = "Parece que ya no hay más Darkflow mezclados convergiendo, pero...",
  ui_story_1012_10121102_7_dialog_content = "Gaaaaaah!!!",
  ui_story_1012_10121102_8_dialog_content = "¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡",
  ui_story_1012_10121102_9_dialog_content = "Estos irregulares son muy aburridos.",
  ui_story_1012_10121102_10_dialog_content = "¿El Darkflow que emiten interfiere con tu juicio?",
  ui_story_1012_10121102_11_dialog_content = "En ese caso... ¡Vamos a ensartarlos con mi lanza!",
  ui_story_1012_10121102_12_dialog_content = "¡Prueba el poder real!",
  ui_story_1012_10121102_13_dialog_content = "Gaah...",
  ui_story_1012_10121102_14_dialog_content = "Veo que sigues tan sanguinario como siempre, Reinhardt.",
  ui_story_1012_10121102_15_dialog_content = "Un día, esta manía tuya será tu muerte.",
  ui_story_1012_10121102_16_dialog_content = "Gracias por tu preocupación...",
  ui_story_1012_10121102_17_dialog_content = "No pareces particularmente sorprendido de que todavía esté respirando, Forsakin.",
  ui_story_1012_10121102_18_dialog_content = "Lo has sabido, desde entonces <color=#FFB400>ese momento</color>...",
  ui_story_1012_10121102_19_dialog_content = "Que un monstruo como yo sería difícil de dejar.",
  ui_story_1012_10121102_20_dialog_content = "Realmente estás tan seguro de ti mismo.",
  ui_story_1012_10121102_21_dialog_content = "Por cierto, si estás aquí por Figerald, él está justo delante.",
  ui_story_1012_10121102_22_dialog_content = "Me temo que no puedo quedarme a jugar.",
  ui_story_1012_10121102_23_dialog_content = "(Eclipsian) Vamos.",
  ui_story_1012_10121102_24_dialog_content = "(Eclipsiano) Roger.",
  ui_story_1012_10121102_25_dialog_content = "(Eso sí que es raro. ¿Por qué Forsakin siendo todos amigos?)",
  ui_story_1012_10121102_26_dialog_content = "(Incluso señaló a dónde ir...)",
  ui_story_1012_10121102_27_dialog_content = "Re-Reinhardt... Algo pasa con Forsakin.",
  ui_story_1012_10121102_28_dialog_content = "...",
  ui_story_1012_10121102_29_dialog_content = "PlayerName, ve a ver cómo le va a la línea del frente en la base de la torre.",
  ui_story_1012_10121102_30_dialog_content = "Sí, sí. ¡De acuerdo!",
  ui_story_1012_10121102_31_dialog_content = "Tsk, tsk, tsk...",
  ui_story_1012_10121102_32_dialog_content = "Incluso tu propia hermana no puede engañarte, ¿eh?",
  ui_story_1012_10121102_33_dialog_content = "Ustedes, los aurorianos, a menudo son mucho más insensibles que los eclipses.",
  ui_story_1012_10121102_34_dialog_content = "... Tsk.",
  ui_story_1012_10121102_35_dialog_content = "(Como era de esperar, me están apuntando a mí).",
  ui_story_1012_10121102_36_dialog_content = "(Si no viniera, seguirían minando nuestra fuerza con esos cañones Darkflow).",
  ui_story_1012_10121102_37_dialog_content = "(Pero si viniera a destruir los cañones, simplemente asaltarían la Torre Blanca...)",
  ui_story_1012_10121102_38_dialog_content = "(Somos... demasiado pocos.)",
  ui_story_1012_10121102_39_dialog_content = "démonos prisa, PlayerName!",
  ui_story_1012_10121102_40_dialog_content = "¿De verdad crees que eso ayudará en las cosas?",
  ui_story_1012_10121102_41_dialog_content = "Tu derrota final nunca ha estado en duda, Aurorian.",
  ui_story_1012_10121102_42_dialog_content = "Todo lo que has hecho es solo retrasar lo inevitable.",
  ui_story_1012_10121102_43_dialog_content = "Si, ve. Corre, conejito, y ve a tus amigos. <color=#FFB400>roto y derrotado</color>!",
  ui_story_1012_10121102_44_dialog_content = "Mira cómo son pulverizados por Eclipsites.",
  ui_story_1012_10121102_45_dialog_content = "¿Qué...?",
  ui_story_1012_10121102_46_dialog_content = "Tsk, tsk, tsk... Incluso imaginarlo me hace babear. ¡No te puedes perder un espectáculo así!",
  ui_story_1012_10121102_47_dialog_content = "Creo que iré a tomar mi asiento.",
  ui_story_1012_10121102_48_dialog_content = "Disfruta el dulce sabor de la derrota, Reinhardt.",
  ui_story_1012_10121102_49_dialog_content = "Despues de el, PlayerName, ¡ahora!",
  ui_story_1012_10121102_50_dialog_content = "Nosotros... ¿Qué sigue, Reinhardt?",
  ui_story_1012_10121102_51_dialog_content = "Que les parece... ¡Luchamos!",
  ui_story_1012_10121102_52_dialog_content = "Ten fe en tus compañeros y sigue luchando...",
  ui_story_1012_10121102_53_dialog_content = "¡Hasta el final!",
  ui_story_1012_10121301_1_dialog_content = "Tsk, una escena tan conmovedora.",
  ui_story_1012_10121301_2_dialog_content = "Ese huevo que has trabajado tan duro para proteger finalmente se rompe.",
  ui_story_1012_10121301_3_dialog_content = "Creo que encontraré el punto débil y lo presionaré lentamente.",
  ui_story_1012_10121301_4_dialog_content = "Quiero sentirte destrozarte y desmoronarte en mi mano.",
  ui_story_1012_10121301_5_dialog_content = "¡Eclipsitos! ¡Mis amigos sedientos de sangre!",
  ui_story_1012_10121301_6_dialog_content = "¿Ya puedes oler la sangre?",
  ui_story_1012_10121301_7_dialog_content = "¡Entrena tu vista en sus puntos débiles!",
  ui_story_1012_10121301_8_dialog_content = "¡Apaga los últimos rayos de luz!",
  ui_story_1012_10121301_9_dialog_content = "¡Gaah!",
  ui_story_1012_10121301_10_dialog_content = "¡La fuerza principal de Eclipsite está avanzando!",
  ui_story_1012_10121301_11_dialog_content = "¿Podemos... todavía retenerlos?",
  ui_story_1012_10121301_12_dialog_content = "Estratégicamente hablando, nuestra línea de defensa ya se ha roto. Sería tonto y arriesgado tratar de mantener la posición.",
  ui_story_1012_10121301_13_dialog_content = "El área violada en sí es extremadamente vulnerable. Y lo que es más...",
  ui_story_1012_10121301_14_dialog_content = "Suficiente. ¡No necesito oír más!",
  ui_story_1012_10121301_15_dialog_content = "¡Nadie quiere sermones en medio de un campo de batalla!",
  ui_story_1012_10121301_16_dialog_content = "Es precisamente PORQUE estamos en medio de un campo de batalla que ese pensamiento racional es importante.",
  ui_story_1012_10121301_17_dialog_content = "Entonces, ¿cuál es el resultado de tu pensamiento racional?",
  ui_story_1012_10121301_18_dialog_content = "Si nos atrincheramos, seremos totalmente aniquilados.",
  ui_story_1012_10121301_19_dialog_content = "...",
  ui_story_1012_10121301_20_dialog_content = "Objetivamente, nuestra mejor apuesta es abandonar la Torre Blanca, reagruparnos e intentar abrirnos paso en una dirección.",
  ui_story_1012_10121301_21_dialog_content = "Debido al hecho de que nuestros soldados son, en general, más fuertes que nuestros oponentes, espero que podamos abrirnos paso.",
  ui_story_1012_10121301_22_dialog_content = "Entonces, ¿por qué no estás saliendo alegremente?",
  ui_story_1012_10121301_23_dialog_content = "No puedo ir.",
  ui_story_1012_10121301_24_dialog_content = "El Gran Mariscal me ordenó quedarme, así que debo quedarme y seguir luchando.",
  ui_story_1012_10121301_25_dialog_content = "¡Jajaja! Creo que detecto una falla en tu juicio racional, pequeño soldado de Illumina.",
  ui_story_1012_10121301_26_dialog_content = "Es el deber de un soldado obedecer las órdenes, ante todo. En estas condiciones yo...",
  ui_story_1012_10121301_27_dialog_content = "Sé que sé. Guárdalo.",
  ui_story_1012_10121301_28_dialog_content = "Pero viendo lo inevitable...",
  ui_story_1012_10121301_29_dialog_content = "¿No es una mejor idea darle un descanso a esa inteligente cabeza que tienes y preparar tus manos para pelear?",
  ui_story_1012_10121301_30_dialog_content = "Ahora, eso no funcionará en absoluto, bella dama.",
  ui_story_1012_10121301_31_dialog_content = "Si sigues causándonos problemas, Lord Figerald se irritará.",
  ui_story_1012_10121301_32_dialog_content = "¡¿Quién es ese?!",
  ui_story_1012_10121301_33_dialog_content = "¿Qué... diablos es esto?",
  ui_story_1012_10121301_34_dialog_content = "¡Cuidado!",
  ui_story_1012_10121301_35_dialog_content = "Tú... solo mantén tu nariz fuera de esto.",
  ui_story_1012_10121301_36_dialog_content = "Allí estaba yo, solo yo y la bella dama del mundo entero, antes de que un apestoso intruso irrumpiera en nuestra fiesta.",
  ui_story_1012_10121301_37_dialog_content = "¡Tú!",
  ui_story_1012_10121301_38_dialog_content = "Tenga en cuenta que nuestra Lumina circundante parece ser limitada.",
  ui_story_1012_10121301_39_dialog_content = "Nuestro poder está limitado aquí.",
  ui_story_1012_10121301_40_dialog_content = "¿En serio?",
  ui_story_1012_10121301_41_dialog_content = "Eso es demasiado para mí en lo que pensar ahora. ¡Todo lo que quiero hacer es introducir mi puño en la cara de ese tipo!",
  ui_story_1012_10121301_42_dialog_content = "¡Vaya! ¡Qué íntimo, mi señora!",
  ui_story_1012_10121301_43_dialog_content = "Puedes reducir la velocidad, ya sabes... Tenemos mucho tiempo.",
  ui_story_1012_10121301_44_dialog_content = "¿Por qué no nos conocemos un poco mejor?",
  ui_story_1012_10121301_45_dialog_content = "Gaaaaah!!",
  ui_story_1012_10121301_46_dialog_content = "...",
  ui_story_1012_10121301_47_dialog_content = "¡El de atrás! ¿Por qué estremecerse de luchar?",
  ui_story_1012_10121301_48_dialog_content = "...",
  ui_story_1012_10121301_49_dialog_content = "reina del norte...",
  ui_story_1012_10121301_49X1_dialog_content = "Te recuerdo, el rebelde en la Celebración de la Noche Blanca.",
  ui_story_1012_10121301_49X2_dialog_content = "Eras más inteligente en ese entonces.",
  ui_story_1012_10121301_50_dialog_content = "Ahora, resultaste ser el único que dudaba en el campo de batalla.",
  ui_story_1012_10121301_51_dialog_content = "...",
  ui_story_1012_10121301_52_dialog_content = "Oh poderosa Reina del Norte, ¿estás ciega a cómo sopla el viento?",
  ui_story_1012_10121301_53_dialog_content = "Una derrota auroriana es inevitable. ¿Cuál es el punto de pelear?",
  ui_story_1012_10121301_54_dialog_content = "Una derrota auroriana puede ser inevitable. Pero solo los cobardes no se atreven a luchar.",
  ui_story_1012_10121301_55_dialog_content = "Yo...",
  ui_story_1012_10121301_56_dialog_content = "A luchar y pelear, a defender tu hogar. Esto es algo que debería haber considerado antes de ahora.",
  ui_story_1012_10121301_57_dialog_content = "Tal como eres ahora, no durarás ni un segundo en el campo de batalla.",
  ui_story_1012_10121301_58_dialog_content = "Mmm... Si es así...",
  ui_story_1012_10121301_59_dialog_content = "Entonces, si me permite el honor...",
  ui_story_1012_10121301_60_dialog_content = "¡De estar en tu contra!",
  ui_story_1012_10121301_61_dialog_content = "¡Guau! ¡Ese es uno grande!",
  ui_story_1012_10121301_62_dialog_content = "¿Eso viene de... la dirección de Su Majestad?",
  ui_story_1012_10121301_63_dialog_content = "¡¡¡Su Majestad!!!",
  ui_story_1012_10121301_64_dialog_content = "Gaaaaah!!",
  ui_story_1012_10121301_65_dialog_content = "¡Fuera del camino! ¡Insectos molestos!",
  ui_story_1012_10121301_66_dialog_content = "Debo proteger a Su Majestad...",
  ui_story_1012_10121301_67_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10121301_68_dialog_content = "¡Ay! ¡¿Qué fue eso?!",
  ui_story_1012_10121301_69_dialog_content = "¡Su Majestad! ¡Oh, Su Majestad!",
  ui_story_1012_10121301_70_dialog_content = "Tanta lealtad infantil.",
  ui_story_1012_10121301_71_dialog_content = "Tú.",
  ui_story_1012_10121301_72_dialog_content = "Una mujer tan poderosa no necesita un cachorro como tú para protegerla.",
  ui_story_1012_10121301_73_dialog_content = "Te sugiero que te preocupes por ti mismo.",
  ui_story_1012_10121301_74_dialog_content = "¿Vamos a tener una cacería alegre? Comienza ahora.",
  ui_story_1012_10121301_75_dialog_content = "!",
  ui_story_1012_10121301_76_dialog_content = "Aaaaah!",
  ui_story_1012_10121301_77_dialog_content = "*jadeando*",
  ui_story_1012_10121301_78_dialog_content = "(Me estoy cansando demasiado para esto...)",
  ui_story_1012_10121301_79_dialog_content = "(Incluso después de la mejora de Chord Link, este nivel de intensidad es... demasiado...)",
  ui_story_1012_10121301_80_dialog_content = "(¡No! Júntalo Barton! ¡No decepciones a los demás!)",
  ui_story_1012_10121301_81_dialog_content = "¿Es eso todo lo que tienes? Barton?",
  ui_story_1012_10121301_82_dialog_content = "¡¿Qué?!",
  ui_story_1012_10121301_83_dialog_content = "Forsakin, maldito!",
  ui_story_1012_10121301_84_dialog_content = "Nuestra lucha finalmente está llegando a una conclusión atrasada.",
  ui_story_1012_10121301_85_dialog_content = "Pero no te preocupes. Me aseguraré de tallar tu epitafio yo mismo: \"Admiro tu espíritu\".",
  ui_story_1012_10121301_86_dialog_content = "Pff... ¡No te molestes en mi cuenta!",
  ui_story_1012_10121301_87_dialog_content = "¡Toma esto!",
  ui_story_1012_10121301_88_dialog_content = "¡Decir ah! ¡¿Ni siquiera peleaste?!",
  ui_story_1012_10121301_89_dialog_content = "No tengo ningún interés en los animales heridos. Te cuidarán en mi lugar.",
  ui_story_1012_10121301_90_dialog_content = "Solo tengo ojos para la torre detrás de ti.",
  ui_story_1012_10121301_91_dialog_content = "¡Gaah!",
  ui_story_1012_10121301_92_dialog_content = "¿Qué clase de broma es esta?",
  ui_story_1012_10121301_93_dialog_content = "Forsakin!",
  ui_story_1012_10121301_94_dialog_content = "Forsaaaakiiiinnn!!",
  ui_story_1012_10121301_95_dialog_content = "<color=#e8d9bb>¡Estallido! ¡Estallido! ¡Estallido!</color>",
  ui_story_1012_10121301_96_dialog_content = "¿Eh? Qué es esto...?",
  ui_story_1012_10121301_97_dialog_content = "(Barton, ¡volver!)",
  ui_story_1012_10121301_98_dialog_content = "PlayerName! ¡Regresaste!",
  ui_story_1012_10121301_99_dialog_content = "Oh no...",
  ui_story_1012_10121301_100_dialog_content = "Mejor tarde que nunca.",
  ui_story_1012_10121301_101_dialog_content = "No se ve bien. Hay demasiados de ellos.",
  ui_story_1012_10121301_102_dialog_content = "¡Ustedes, háganse útiles en otro lugar!",
  ui_story_1012_10121301_103_dialog_content = "Lo tomaré desde aquí.",
  ui_story_1012_10121301_104_dialog_content = "Tengo cosas que discutir con ella.",
  ui_story_1012_10121301_105_dialog_content = "¿Conversar? ¿No es un poco tarde para eso?",
  ui_story_1012_10121301_106_dialog_content = "¡Ja ja! Ahora escucha, sé que ninguno de los dos quiere escuchar lo que el otro tiene que decir.",
  ui_story_1012_10121301_107_dialog_content = "Así que esta vez, usaré un lenguaje que entenderás.",
  ui_story_1012_10121301_108_dialog_content = "¡Apenas tienes influencia frente al poder combinado del Eclipse!",
  ui_story_1012_10121301_109_dialog_content = "No me importan. Sólo necesito que escuches.",
  ui_story_1012_10121301_110_dialog_content = "Alerta: Eclipsites no registrados están ingresando a la Zona de mantenimiento de Colossus.",
  ui_story_1012_10121301_111_dialog_content = "Alerta: Eclipsites no registrados están ingresando al almacenamiento de componentes de Colossus.",
  ui_story_1012_10121301_112_dialog_content = "Alerta: Los Eclipsitos no registrados están ingresando a la Instalación de Eliminación de Residuos.",
  ui_story_1012_10121301_113_dialog_content = "¡Basta de alertas inútiles! ¡¿Hay algo que podamos hacer?!",
  ui_story_1012_10121301_114_dialog_content = "Inspeccionando las defensas del Obelisco del Retorno—",
  ui_story_1012_10121301_115_dialog_content = "Siento informar de graves daños a las capacidades defensivas de la torre. Hay una capacidad reducida para resistir el ataque.",
  ui_story_1012_10121301_116_dialog_content = "Supongo... Si hubiera habido una manera, ya lo habríamos intentado contra Forsakin.",
  ui_story_1012_10121301_117_dialog_content = "PlayerName, ¿Neural Aux se está comunicando contigo de nuevo?",
  ui_story_1012_10121301_118_dialog_content = "Sí... Transmitiendo los Eclipsites asaltando la torre.",
  ui_story_1012_10121301_119_dialog_content = "Incluso si pudiéramos ocuparnos de todos los Eclipsites en la torre, es demasiado tarde.",
  ui_story_1012_10121301_120_dialog_content = "Si no podemos revertir la batalla afuera, es solo cuestión de tiempo antes de que tomen el Obelisco del Retorno.",
  ui_story_1012_10121301_121_dialog_content = "¿Cómo podemos darle la vuelta, entonces?",
  ui_story_1012_10121301_122_dialog_content = "Incluso con Aurorianos tan poderosos como Reinhardt y Bethlehem de nuestro lado...",
  ui_story_1012_10121301_122X1_dialog_content = "Las cosas siguen yendo cuesta abajo.",
  ui_story_1012_10121301_123_dialog_content = "Todavía tenemos algunos trucos bajo la manga...",
  ui_story_1012_10121301_124_dialog_content = "¡Como esa \"arma definitiva\" que mencionó Neural Aux, el Acorde de la Ley!",
  ui_story_1012_10121301_125_dialog_content = "Alerta: los Eclipsites no registrados están ingresando a la sala de producción de recursos.",
  ui_story_1012_10121301_126_dialog_content = "Alerta: Eclipsites no registrados están ingresando a los barrios residenciales de Caelestite.",
  ui_story_1012_10121301_127_dialog_content = "¡Ya basta de alertas, Neural Aux! ¡Date prisa y dime cómo activar el Acorde de la Ley en su lugar!",
  ui_story_1012_10121301_128_dialog_content = "Ni siquiera sé lo que hace, pero no tenemos opciones. ¡Tengo que probar!",
  ui_story_1012_10121301_129_dialog_content = "???",
  ui_story_1012_10121301_130_dialog_content = "Solicitud incorrecta detectada.",
  ui_story_1012_10121301_131_dialog_content = "A ningún Caelestita se le permite tocar el Acorde de la Ley. Esto es exigido por el Decreto Supremo.",
  ui_story_1012_10121301_132_dialog_content = "¡¿Cómo puedes preocuparte por las reglas y regulaciones en un momento como este?!",
  ui_story_1012_10121301_133_dialog_content = "¡No será solo un desastre para nosotros si el Eclipse gana! ¡El Obelisco del Retorno también sufrirá!",
  ui_story_1012_10121301_134_dialog_content = "¡¿Quieres que eso pase?!",
  ui_story_1012_10121301_135_dialog_content = "Lo siento. No puedo desear ningún resultado específico.",
  ui_story_1012_10121301_136_dialog_content = "Sólo sé seguir el Decreto Supremo.",
  ui_story_1012_10121301_137_dialog_content = "¡Tú!",
  ui_story_1012_10121301_138_dialog_content = "¡Estoy hasta aquí con esa máquina inútil, sin alma e indiferente!",
  ui_story_1012_10121301_139_dialog_content = "Enfriar, PlayerName. No tiene sentido pelear con una IA.",
  ui_story_1012_10121301_140_dialog_content = "Hagamos lo mejor que podamos. Supongo que todos los lados están a punto de converger aquí.",
  ui_story_1012_10121301_141_dialog_content = "Sólo espero que todavía estemos vivos cuando lleguen.",
  ui_story_1012_10121301_142_dialog_content = "Bueno, no te equivocas. Lo único que podemos hacer es nuestro mejor esfuerzo.",
  ui_story_1012_10121301_143_dialog_content = "Alerta: Eclipsites no registrados están ingresando al Núcleo Central.",
  ui_story_1012_10121301_144_dialog_content = "¡Bip! ¡Bip! ¡Bip! ¡Bip! ¡Bip! ¡Bip!",
  ui_story_1012_10121301_145_dialog_content = "¡¿Podrías POR FAVOR callarte?!",
  ui_story_1012_10121301_146_dialog_content = "Si no puedes ser de ayuda, Neural Aux, ¿al menos puedes callarte?",
  ui_story_1012_10121301_147_dialog_content = "Precondición activada. Comando inactivo iniciado.",
  ui_story_1012_10121301_148_dialog_content = "Comando de: Francisco. Prioridad de comando: Máxima.",
  ui_story_1012_10121301_149_dialog_content = "Modificando los sistemas lógicos subyacentes de Neural Aux...",
  ui_story_1012_10121301_150_dialog_content = "¿Francisco? ¿Él de nuevo? ¿Qué está tramando esta vez?",
  ui_story_1012_10121301_151_dialog_content = "Se completó la modificación del sistema lógico subyacente.",
  ui_story_1012_10121301_152_dialog_content = "Determinando que existe una amenaza existencial, informaré a Caelestita sobre cómo activar el Acorde de la Ley.",
  ui_story_1012_10121301_153_dialog_content = "¡¿Qué?!",
  ui_story_1012_10121301_154_dialog_content = "Tú... ¿Estás dispuesto a decírmelo ahora? ¿Cómo?",
  ui_story_1012_10121301_155_dialog_content = "Eso es correcto. El comando inactivo me permite realizar esta operación ahora.",
  ui_story_1012_10121301_156_dialog_content = "Francis, no sé quién eres, ¡pero gracias!",
  ui_story_1012_10121301_157_dialog_content = "Vamos entonces, escúpelo. ¿Que necesito hacer?",
  ui_story_1012_10121301_158_dialog_content = "Debes ir al Núcleo Central y conectar tu conciencia al Sistema Circular.",
  ui_story_1012_10121301_159_dialog_content = "En las profundidades del Sistema Circular, hazte con la Autorización del Anillo Núcleo.",
  ui_story_1012_10121301_160_dialog_content = "Sólo la Autorización del Anillo Núcleo puede activar el Acorde de la Ley.",
  ui_story_1012_10121301_161_dialog_content = "¿Autorización de anillo central? ¡¿No es esa la máxima autoridad intocable?!",
  ui_story_1012_10121301_162_dialog_content = "Correcto. Por eso elegí el verbo \"apoderarse\".",
  ui_story_1012_10121301_163_dialog_content = "Este acto está en contravención de todas las regulaciones. es tabú",
  ui_story_1012_10121301_164_dialog_content = "También hay una alta probabilidad de que muera en el proceso.",
  ui_story_1012_10121301_165_dialog_content = "¡¿Qué?!",
  ui_story_1012_10121301_166_dialog_content = "¿Por qué? ¿Cuál es el riesgo?",
  ui_story_1012_10121301_167_dialog_content = "Lo siento. No tengo acceso a la información relacionada con la Autorización de Core Ring.",
  ui_story_1012_10121301_168_dialog_content = "El comando exige que le informe a Caelestite cómo activar el Acorde de la Ley.",
  ui_story_1012_10121301_169_dialog_content = "Sólo la Autorización del Anillo Núcleo puede activar el Acorde de la Ley.",
  ui_story_1012_10121301_170_dialog_content = "...",
  ui_story_1012_10121301_171_dialog_content = "No me estás dejando mucho margen de maniobra, ¿verdad?",
  ui_story_1012_10121301_172_dialog_content = "Carleen, Creo que he encontrado una manera de cambiar el rumbo de la batalla.",
  ui_story_1012_10121301_173_dialog_content = "Vamos. Tenemos que volver al Núcleo Central. Voy a activar el Acorde de la Ley.",
  ui_story_1012_10121301_174_dialog_content = "¡¿El acorde de la ley?! ¿Neural Aux finalmente te dijo qué hacer?",
  ui_story_1012_10121301_175_dialog_content = "Sí, claro.",
  ui_story_1012_10121301_176_dialog_content = "¿Será difícil? ¿Puedo ayudar?",
  ui_story_1012_10121301_177_dialog_content = "La torre está repleta de eclipses. Ayudarme a llegar al Núcleo Central sería suficiente.",
  ui_story_1012_10121301_178_dialog_content = "Después de eso, estoy por mi cuenta.",
  ui_story_1012_10121301_179_dialog_content = "(Reinhardt, ¿puedes escucharme?)",
  ui_story_1012_10121301_180_dialog_content = "¡Vaya! ¡Sí! ¿Cómo están las cosas por allá? ¿Necesitas algún apoyo?",
  ui_story_1012_10121301_181_dialog_content = "(Supongo que sí... voy en camino a activar el arma definitiva del Obelisco del Retorno).",
  ui_story_1012_10121301_182_dialog_content = "(Me temo que tengo que dejar la lucha a los demás por un tiempo).",
  ui_story_1012_10121301_183_dialog_content = "(Y necesito que ustedes me den algo de tiempo).",
  ui_story_1012_10121301_184_dialog_content = "(Antes de que active el arma, no puedes dejar que nadie te pase al Obelisco del Retorno).",
  ui_story_1012_10121301_185_dialog_content = "¿Arma definitiva? ¡Parece que podría ser de gran ayuda!",
  ui_story_1012_10121301_186_dialog_content = "Las armas de esta enorme torre están impulsadas por los secretos de una antigua civilización...",
  ui_story_1012_10121301_187_dialog_content = "¡Y tengo que ver qué pueden hacer, Caelestite!",
  ui_story_1012_10121301_188_dialog_content = "(¡Ja! Aunque ni siquiera sé si voy a tener éxito).",
  ui_story_1012_10121301_189_dialog_content = "Tú solo déjame la lucha a mí. Nada va a pasar.",
  ui_story_1012_10121301_190_dialog_content = "¡Tendrán que llenar este valle de cadáveres antes de poder enterrarme!",
  ui_story_1012_10121301_191_dialog_content = "...",
  ui_story_1012_10121301_192_dialog_content = "(¿Puede oírme, Su Majestad?)",
  ui_story_1012_10121301_193_dialog_content = "(Yo...)",
  ui_story_1012_10121301_194_dialog_content = "Ve a hacer lo que tienes que hacer.",
  ui_story_1012_10121301_195_dialog_content = "(!!!)",
  ui_story_1012_10121301_196_dialog_content = "Las estrellas se reúnen aquí de todas partes, donde brillarán hasta el amanecer.",
  ui_story_1012_10121301_197_dialog_content = "Por favor, atraviesa la oscuridad.",
  ui_story_1012_10121301_198_dialog_content = "(Su Majestad...)",
  ui_story_1012_10121301_199_dialog_content = "Además...",
  ui_story_1012_10121301_200_dialog_content = "Asegúrate de volver con vida.",
  ui_story_1012_10121302_1_dialog_content = "Gaah...",
  ui_story_1012_10121302_2_dialog_content = "¡El Núcleo Central está justo adelante! ¡Apuro!",
  ui_story_1012_10121302_3_dialog_content = "¡Sí!",
  ui_story_1012_10121302_4_dialog_content = "Pero, eh... ¿Crees que hay más y más eclipses por aquí?",
  ui_story_1012_10121302_5_dialog_content = "Sí... Tal vez todos los combates los perturbaron.",
  ui_story_1012_10121302_6_dialog_content = "Bueno, el peor de los casos es que atraigamos a todos los Eclipsites en el Obelisco del Retorno.",
  ui_story_1012_10121302_7_dialog_content = "Bueno, eso es basura. El Núcleo Central es un callejón sin salida.",
  ui_story_1012_10121302_8_dialog_content = "¿Realmente no hay nada que podamos usar para defendernos, Neural Aux?",
  ui_story_1012_10121302_9_dialog_content = "El Sistema Guardián es el mecanismo de defensa del Núcleo Central.",
  ui_story_1012_10121302_10_dialog_content = "Pero los registros indican que el sistema se dañó hace poco tiempo.",
  ui_story_1012_10121302_11_dialog_content = "Sí, nuestro mal. Lo lamento.",
  ui_story_1012_10121302_12_dialog_content = "Más eclipses, justo en nuestra cola. ¡Apuro!",
  ui_story_1012_10121302_13_dialog_content = "¡Oh, chasquido!",
  ui_story_1012_10121302_14_dialog_content = "<color=#e8d9bb>Golpeteo de pitidos... Golpeteo de pitidos...</color>",
  ui_story_1012_10121302_15_dialog_content = "¡Lo hicimos!",
  ui_story_1012_10121302_16_dialog_content = "¡¡¡Gah!!!",
  ui_story_1012_10121302_17_dialog_content = "Whoaaaa—",
  ui_story_1012_10121302_18_dialog_content = "Uf... Te debo una, Carleen.",
  ui_story_1012_10121302_19_dialog_content = "Ve a hacer lo que viniste a hacer.",
  ui_story_1012_10121302_20_dialog_content = "Ve a activar el Acorde de la Ley.",
  ui_story_1012_10121302_21_dialog_content = "Parece que no hemos sacudido todos los eclipses.",
  ui_story_1012_10121302_22_dialog_content = "¿No deberíamos ocuparnos de ellos primero?",
  ui_story_1012_10121302_23_dialog_content = "No sabemos cuántos hay... Podríamos estar luchando para siempre.",
  ui_story_1012_10121302_24_dialog_content = "Déjame manejarlos.",
  ui_story_1012_10121302_25_dialog_content = "¿Eh? ¿Por tí mismo?",
  ui_story_1012_10121302_26_dialog_content = "Ve a activar el arma, yo me encargaré de los Eclipsites.",
  ui_story_1012_10121302_27_dialog_content = "Un Caelestite y un Aurorian, cada uno haciendo su parte.",
  ui_story_1012_10121302_28_dialog_content = "Pero hay tantos de ellos...",
  ui_story_1012_10121302_29_dialog_content = "Solo cree en mi.",
  ui_story_1012_10121302_30_dialog_content = "Como creo en ti.",
  ui_story_1012_10121302_31_dialog_content = "¡Dispersión, pétalos de hielo!",
  ui_story_1012_10121302_32_dialog_content = "...",
  ui_story_1012_10121302_33_dialog_content = "Sí. Creo en ti, Carleen.",
  ui_story_1012_10121302_34_dialog_content = "¡Bien! ¡Hagámoslo!",
  ui_story_1012_10121302_35_option_content = "¡Potencia de fuerza!",
  ui_story_1012_10121302_36_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_1012_10121302_37_dialog_content = "Aquí estoy de nuevo, el Sistema Circular.",
  ui_story_1012_10121302_38_dialog_content = "La última vez descubrí que el Sistema Circular era un espacio que operaba a nivel consciente, un espacio mental.",
  ui_story_1012_10121302_39_dialog_content = "Mi conciencia puede moverse y profundizar en toda la información que está almacenada aquí.",
  ui_story_1012_10121302_40_dialog_content = "Neural Aux dijo algo acerca de que las funciones del Obelisco del Retorno se dividen en tres niveles: el Anillo Exterior, el Anillo Interior y el Anillo Central.",
  ui_story_1012_10121302_41_dialog_content = "Como todo tiene la palabra \"anillo\" en su nombre, me pregunto si estas autorizaciones también se reparten entre los diferentes anillos del Sistema Circular.",
  ui_story_1012_10121302_42_dialog_content = "Neural Aux también dijo que la Autorización de Core Ring estaba en la parte más profunda del Sistema Circular. ¿Eso significa que necesita una mayor autorización cuanto más se acerque al centro?",
  ui_story_1012_10121302_43_dialog_content = "Si no me equivoco, es una forma extraña pero ordenada de hacer las cosas.",
  ui_story_1012_10121302_44_dialog_content = "En resumen, sin embargo, necesito acercarme lo más posible al centro del Sistema Circular.",
  ui_story_1012_10121302_45_dialog_content = "¿Qué es esto? ¿De ninguna manera?",
  ui_story_1012_10121302_46_dialog_content = "A mi conciencia le resulta difícil ir más allá.",
  ui_story_1012_10121302_47_dialog_content = "No puedes ir más profundo.",
  ui_story_1012_10121302_48_dialog_content = "!",
  ui_story_1012_10121302_49_dialog_content = "Caelestites no están permitidos cerca del Core Ring.",
  ui_story_1012_10121302_50_dialog_content = "Este es el <color=#FFB400>Decreto supremo</color>.",
  ui_story_1012_10121302_51_dialog_content = "Ya he oído bastante de este Supremo Decreto.",
  ui_story_1012_10121302_52_dialog_content = "¿Qué ES, de todos modos?",
  ui_story_1012_10121302_53_dialog_content = "¿Por qué todos simplemente obedecen a esta cosa?",
  ui_story_1012_10121302_54_dialog_content = "¿eh...?",
  ui_story_1012_10121302_55_dialog_content = "¿Por qué... tengo miedo?",
  ui_story_1012_10121302_56_dialog_content = "los <color=#FFB400>Decreto supremo</color> es la directiva original y principal.",
  ui_story_1012_10121302_57_dialog_content = "Existió mucho antes de que nacieras, anterior incluso a toda la raza Caelestita.",
  ui_story_1012_10121302_58_dialog_content = "Es parte de ti, de tu conciencia, tu carne y tu sangre.",
  ui_story_1012_10121302_59_dialog_content = "Es el credo obligatorio de los Caelestitas, y la razón por la que llegaron a existir.",
  ui_story_1012_10121302_60_dialog_content = "Es su naturaleza fundamental predestinada desde hace mucho tiempo.",
  ui_story_1012_10121302_61_dialog_content = "¡Mi conciencia se tambalea hacia atrás!",
  ui_story_1012_10121302_62_dialog_content = "¿Realmente he estado obedeciendo este llamado Decreto Supremo?",
  ui_story_1012_10121302_63_dialog_content = "Suena casi instintivo...",
  ui_story_1012_10121302_64_dialog_content = "Caelestites no están permitidos cerca del Core Ring.",
  ui_story_1012_10121302_65_dialog_content = "Este es el <color=#FFB400>Decreto supremo</color>.",
  ui_story_1012_10121302_66_dialog_content = "(Mi conciencia está obedeciendo el Decreto Supremo... Es como si hubiera una mente más fuerte manipulando la mía.)",
  ui_story_1012_10121302_67_dialog_content = "(Tengo un sentimiento tan fuerte de esto.)",
  ui_story_1012_10121302_68_dialog_content = "(Si obedezco, aunque sea por un segundo, nunca seré libre. Tendré que vivir dentro de su marco por el resto de mi vida).",
  ui_story_1012_10121302_69_dialog_content = "(No habrá forma de escapar de los poderosos lazos innatos).",
  ui_story_1012_10121302_70_dialog_content = "(Se acabó el juego si eso sucede).",
  ui_story_1012_10121302_71_dialog_content = "(No habrá otra oportunidad de activar el Acorde de la Ley, o de cambiar el rumbo de la batalla).",
  ui_story_1012_10121302_72_dialog_content = "(Solo tengo una oportunidad en esto, y eso es ahora mismo).",
  ui_story_1012_10121302_73_dialog_content = "Muévete, ¡MUÉVETE! ¡Ve más profundo!",
  ui_story_1012_10121302_74_dialog_content = "Olvídate del Decreto Supremo. ¡No lo creas!",
  ui_story_1012_10121302_75_dialog_content = "¿Naturaleza destinada? Lo que sea... ¡Nunca he oído hablar de eso en toda mi vida!",
  ui_story_1012_10121302_76_dialog_content = "¿De dónde te bajas, saliendo de la carpintería para detenerme ahora?",
  ui_story_1012_10121302_77_dialog_content = "No puedes ir más profundo.",
  ui_story_1012_10121302_78_dialog_content = "Caelestites no están permitidos cerca del Core Ring.",
  ui_story_1012_10121302_79_dialog_content = "Este es el <color=#FFB400>Decreto supremo</color>.",
  ui_story_1012_10121302_80_dialog_content = "¡No fue el Decreto Supremo lo que me mantuvo con vida hasta ahora! ¡Fueron mis padres, quienes se sacrificaron por mí! Era Soroz...",
  ui_story_1012_10121302_81_dialog_content = "Fue Vice, que me encontró! ¡Y todos los Aurorianos que lucharon junto a mí!",
  ui_story_1012_10121302_82_dialog_content = "¡ELLOS son mi Decreto Supremo!",
  ui_story_1012_10121302_83_dialog_content = "No puedes ir más profundo.",
  ui_story_1012_10121302_84_dialog_content = "Se puede ir...",
  ui_story_1012_10121302_85_dialog_content = "¿Eh? ¿Lo vencí?",
  ui_story_1012_10121302_86_dialog_content = "¿Es esto...? ¿El anillo central?",
  ui_story_1012_10121302_87_dialog_content = "Espera un segundo, esto es...",
  ui_story_1012_10121302_87X1_dialog_content = "Creo que lo he visto antes. Lago glacial como Lake Mirror y Aurora en el cielo.",
  ui_story_1012_10121302_87X2_dialog_content = "¿Es esto realmente mi imaginación? Pero se sentía tan real. El aire frío del lago me da escalofríos.",
  ui_story_1012_10121302_88_dialog_content = "Este lugar parece real, no como un espacio mental.",
  ui_story_1012_10121302_89_dialog_content = "¡Mi conciencia de alguna manera se volvió sólida! Asombroso.",
  ui_story_1012_10121302_90_dialog_content = "Tal vez sea una tecnología similar a Battle Simulator.",
  ui_story_1012_10121302_91_dialog_content = "Entonces, ¿qué se supone que debo hacer ahora dentro del Core Ring? No creo que Neural Aux haya dicho nada al respecto.",
  ui_story_1012_10121302_92_dialog_content = "Hola, Neural Aux. ¿Tu copia?",
  ui_story_1012_10121302_93_dialog_content = "Yo, eh, llegué al Core Ring. ¿Qué hago ahora?",
  ui_story_1012_10121302_94_dialog_content = "<color=#e8d9bb>Crujido...</color>",
  ui_story_1012_10121302_95_dialog_content = "¿Eh? ¿Que es ese ruido?",
  ui_story_1012_10121302_96_dialog_content = "<color=#e8d9bb>Click-clack...</color>",
  ui_story_1012_10121302_97_dialog_content = "...",
  ui_story_1012_10121302_98_dialog_content = "...",
  ui_story_1012_10121302_99_dialog_content = "¡Sostener! ¿Es esto un guardián?",
  ui_story_1012_10121302_100_dialog_content = "¿Por qué está aquí?",
  ui_story_1012_10121302_101_dialog_content = "<color=#e8d9bb>Golpe... Golpe... Golpe... Golpe...</color>",
  ui_story_1012_10121302_102_dialog_content = "Has roto un tabú al entrometerte en el Anillo central, Caelestite.",
  ui_story_1012_10121302_103_dialog_content = "Core Ring Authorization pertenece al supremo. No se puede tocar.",
  ui_story_1012_10121302_104_dialog_content = "Tal presunción debe ser detenida.",
  ui_story_1012_10121302_105_dialog_content = "Caelestites son incapaces de poseer poder. Así, el poder es lo que sostiene el decreto.",
  ui_story_1012_10121302_106_dialog_content = "Estás bromeando... ¡DOS de ellos!",
  ui_story_1012_10121302_107_dialog_content = "Este acto está en contravención de todas las regulaciones. es tabú",
  ui_story_1012_10121302_108_dialog_content = "También hay una alta probabilidad de que muera en el proceso.",
  ui_story_1012_10121302_109_dialog_content = "¿Necesito... luchar contra estas cosas...?",
  ui_story_1012_10121302_110_dialog_content = "<color=#e8d9bb>Bip...</color>",
  ui_story_1012_10121302_111_dialog_content = "<color=#e8d9bb>Bip...</color>",
  ui_story_1012_10121302_112_dialog_content = "<color=#e8d9bb>Bip...</color>",
  ui_story_1012_10121302_113_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1012_10121302_114_dialog_content = "...",
  ui_story_1012_10121401_1_dialog_content = "Uf... uf...",
  ui_story_1012_10121401_2_dialog_content = "Este chico...",
  ui_story_1012_10121401_3_dialog_content = "(Tal poder.)",
  ui_story_1012_10121401_4_dialog_content = "Oh, pequeña presa, pequeña presa... ¿Ya no puedes correr, hmm?",
  ui_story_1012_10121401_5_dialog_content = "¡Puedes volar! ¡Por supuesto que no estás cansado!",
  ui_story_1012_10121401_6_dialog_content = "¿Y quién corre?",
  ui_story_1012_10121401_7_dialog_content = "Tsk, tsk, tsk... Te ves un poco cansado allí, y eso podría ser peligroso.",
  ui_story_1012_10121401_8_dialog_content = "El momento más emocionante de la caza es cuando la presa empieza a mostrarse exhausta.",
  ui_story_1012_10121401_9_dialog_content = "Esa sensación de estar a punto de reclamar tu premio. ¡Oh, es estimulante!",
  ui_story_1012_10121401_10_dialog_content = "¡Estás enfermo... bicho raro!",
  ui_story_1012_10121401_11_dialog_content = "¡Urgh...!",
  ui_story_1012_10121401_12_dialog_content = "¡Tsk, tsk, tsk! ¡Sigue corriendo! Oh sí...",
  ui_story_1012_10121401_13_dialog_content = "¡Quema lo que te queda de vitalidad para vivir un poco más!",
  ui_story_1012_10121401_14_dialog_content = "tengo que dejar de correr...",
  ui_story_1012_10121401_15_dialog_content = "Porque yo... ¡soy la guardia de la Reina!",
  ui_story_1012_10121401_16_dialog_content = "<color=#e8d9bb>Haz clic... Explota... Grieta...</color>",
  ui_story_1012_10121401_17_dialog_content = "¿eh? Que es eso...?",
  ui_story_1012_10121401_18_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10121401_19_dialog_content = "*Tose*... Pff...",
  ui_story_1012_10121401_20_dialog_content = "*Pantalones*... ¿Estás bien, soldado de Illumina?",
  ui_story_1012_10121401_21_dialog_content = "Estoy bien... Ahora por fin estoy fuera.",
  ui_story_1012_10121401_22_dialog_content = "Todavía necesitamos nuestro ingenio sobre nosotros...",
  ui_story_1012_10121401_23_dialog_content = "¡Oh, eso sí que es una pena, je, je! El juego ha sido interrumpido.",
  ui_story_1012_10121401_24_dialog_content = "¿No te gustó nuestro pequeño mundo? ¿Por qué querrías arriesgar tu vida, corriendo así?",
  ui_story_1012_10121401_25_dialog_content = "Tal como eres ahora, solo esperas el final con una vista diferente.",
  ui_story_1012_10121401_26_dialog_content = "despreciable...",
  ui_story_1012_10121401_27_dialog_content = "Oye, ¿es esa... la guardia de la Reina del Norte?",
  ui_story_1012_10121401_28_dialog_content = "son ustedes...",
  ui_story_1012_10121401_29_dialog_content = "¿Aún puedes pelear?",
  ui_story_1012_10121401_30_dialog_content = "Las cosas no se ven muy bien en este momento...",
  ui_story_1012_10121401_31_dialog_content = "Puedo ver que... Ese tipo en el cielo es el jefe enemigo, ¿verdad?",
  ui_story_1012_10121401_32_dialog_content = "Excelente, Mirren. Muy bien hecho.",
  ui_story_1012_10121401_33_dialog_content = "¡Conduce a la presa junta! ¡Será una cacería agradable y limpia!",
  ui_story_1012_10121401_34_dialog_content = "¡Cuidado!",
  ui_story_1012_10121401_35_dialog_content = "Tan intenso Darkflow...",
  ui_story_1012_10121401_36_dialog_content = "¡Vamos! Darlo todo, una última vez...",
  ui_story_1012_10121401_37_dialog_content = "¡Ilumina! ¡Detrás de ti!",
  ui_story_1012_10121401_38_dialog_content = "¡Vaya! Me encontraste.",
  ui_story_1012_10121401_39_dialog_content = "Urgh.",
  ui_story_1012_10121401_40_dialog_content = "(Esto es malo. No puedo escapar.)",
  ui_story_1012_10121401_41_dialog_content = "Tu expresión de total impotencia...",
  ui_story_1012_10121401_42_dialog_content = "Casi parece que estás coqueteando.",
  ui_story_1012_10121401_43_dialog_content = "¡Bruto!",
  ui_story_1012_10121401_44_dialog_content = "¡Allí arriba! ¡Ese tipo volador está volviendo!",
  ui_story_1012_10121401_45_dialog_content = "¡¿Qué?!",
  ui_story_1012_10121401_46_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10121401_47_dialog_content = "Argh...",
  ui_story_1012_10121401_48_dialog_content = "Mi mano izquierda... no puedo moverla...",
  ui_story_1012_10121401_49_dialog_content = "Uy, eso duele...",
  ui_story_1012_10121401_50_dialog_content = "*Tose*",
  ui_story_1012_10121401_51_dialog_content = "Tsk, tsk... Es realmente bastante lamentable... verlos sufrir a todos.",
  ui_story_1012_10121401_52_dialog_content = "¡Mi señor Figerald! No son más que Aurorianos inferiores, no dignos de tu piedad.",
  ui_story_1012_10121401_53_dialog_content = "¡Ah, pero así soy yo! Siempre emocionada, viendo ese último destello de luz en sus ojos a punto de apagarse.",
  ui_story_1012_10121401_54_dialog_content = "¡Compasión por el enemigo! Vaya, lord Figerald, es usted demasiado magnánimo.",
  ui_story_1012_10121401_55_dialog_content = "¿Magnánimo? No me insultes con ese término.",
  ui_story_1012_10121401_56_dialog_content = "Pero... no puedo negarlo. Siento un ligero atisbo de lástima por ellos.",
  ui_story_1012_10121401_57_dialog_content = "Quisiera acabar yo mismo con el sufrimiento de estas pobres cositas.",
  ui_story_1012_10121401_58_dialog_content = "¿En serio?",
  ui_story_1012_10121401_59_dialog_content = "¿Eh? Ese es...",
  ui_story_1012_10121401_60_dialog_content = "Mostrar misericordia significa estar por encima de todos los demás.",
  ui_story_1012_10121401_61_dialog_content = "Pero tú... Ciertamente no lo eres.",
  ui_story_1012_10121401_62_dialog_content = "reina del norte!!! Tú...",
  ui_story_1012_10121401_63_dialog_content = "¿Dónde está Miguel Ángel?",
  ui_story_1012_10121401_64_dialog_content = "Él no puede sostenerme.",
  ui_story_1012_10121401_65_dialog_content = "¡Maldito seas!",
  ui_story_1012_10121401_66_dialog_content = "Esta ha sido una batalla difícil. Para los aurorianos, sí, pero también para ti.",
  ui_story_1012_10121401_67_dialog_content = "Has estado huyendo durante demasiado tiempo.",
  ui_story_1012_10121401_68_dialog_content = "Pero me enfrentarás, de una forma u otra, antes de que esto termine.",
  ui_story_1012_10121401_69_dialog_content = "Este es el precio que pagarán por esta guerra.",
  ui_story_1012_10121401_70_dialog_content = "¡¡¡Su Majestad!!! ¡¡¡Ay, nuestra Reina ha venido a salvarnos!!!",
  ui_story_1012_10121401_71_dialog_content = "¡Reina del Norte, qué poder tan impresionante!",
  ui_story_1012_10121401_72_dialog_content = "¡Que mucho! Sé que estás en tu límite.",
  ui_story_1012_10121401_73_dialog_content = "Pero aguanta un poco más. La guerra aún no ha terminado.",
  ui_story_1012_10121401_74_dialog_content = "El Caelestite está tratando de recuperar la ventaja, pero tenemos que ganarle suficiente tiempo defendiendo el Obelisco del Retorno.",
  ui_story_1012_10121401_75_dialog_content = "No hay final a la vista para esta derrota devastadora.",
  ui_story_1012_10121401_76_dialog_content = "Celestita...",
  ui_story_1012_10121401_77_dialog_content = "¿Es realmente prudente apostar toda la guerra a ese joven débil?",
  ui_story_1012_10121401_78_dialog_content = "Yo creo en el.",
  ui_story_1012_10121401_79_dialog_content = "Espero que todos ustedes también.",
  ui_story_1012_10121401_80_dialog_content = "¡Hago! ¡Si Su Majestad cree, yo también!",
  ui_story_1012_10121401_81_dialog_content = "...",
  ui_story_1012_10121401_82_dialog_content = "Hmm... El juicio de la Reina del Norte es valioso. Más que la mía.",
  ui_story_1012_10121401_83_dialog_content = "No es como si fuéramos a rendirnos, de todos modos.",
  ui_story_1012_10121401_84_dialog_content = "Pero lo que me preocupa es...",
  ui_story_1012_10121401_85_dialog_content = "¿Todavía tenemos la fuerza para sostener la torre?",
  ui_story_1012_10121401_86_dialog_content = "Definitivamente no necesitas preocuparte por eso.",
  ui_story_1012_10121401_87_dialog_content = "Todavía tiene la entrada cerrada. Después de todo, ella nació para la guerra.",
  ui_story_1012_10121401_88_dialog_content = "(Eclipsian) ¡Retirada! ¡Retroceder!",
  ui_story_1012_10121401_89_dialog_content = "(Eclipsian) ¡Velocidad máxima! ¡Retrocede lo más que puedas!",
  ui_story_1012_10121401_90_dialog_content = "(Eclipsiana) Señora Forsakin, Lord Figerald nos ordenó no escatimar nada en nuestro ataque.",
  ui_story_1012_10121401_91_dialog_content = "(Eclipsian) Entonces, ¿por qué...?",
  ui_story_1012_10121401_92_dialog_content = "(Eclipsian) ¡Te dije que retrocedieras! ¡¡¡HAZLO!!!",
  ui_story_1012_10121401_93_dialog_content = "(Eclipsiana) Señora Forsakin?",
  ui_story_1012_10121401_94_dialog_content = "(Eclipsian) Tienes nuevas órdenes ahora, ¡así que retírate!",
  ui_story_1012_10121401_95_dialog_content = "(Eclipsian) ¡Su misión era atacar, no sacrificarse por nada!",
  ui_story_1012_10121401_96_dialog_content = "<color=#e8d9bb>¡¡¡AUGE!!! ¡BANG, CRACK, BOOM!</color>",
  ui_story_1012_10121401_97_dialog_content = "¡¿Qué?!",
  ui_story_1012_10121401_98_dialog_content = "¿Qué está pasando en la entrada de la Torre Blanca?",
  ui_story_1012_10121401_99_dialog_content = "¿Algo... explotó?",
  ui_story_1012_10121401_100_dialog_content = "...",
  ui_story_1012_10121401_101_dialog_content = "Todo el valle está temblando.",
  ui_story_1012_10121401_102_dialog_content = "Que demonios es eso...?",
  ui_story_1012_10121401_103_dialog_content = "Esa es un arma. Uno que hayas visto antes.",
  ui_story_1012_10121401_104_dialog_content = "¡¿Qué quieres decir con que lo he visto antes...?!",
  ui_story_1012_10121401_105_dialog_content = "No puede ser...",
  ui_story_1012_10121401_106_dialog_content = "¡Al final! Puedo ser testigo de la última y heroica posición del Gran Mariscal.",
  ui_story_1012_10121401_107_dialog_content = "No sé si debería estar emocionado o nervioso.",
  ui_story_1012_10121401_108_dialog_content = "Oye, ¿a dónde fueron todos los enemigos?",
  ui_story_1012_10121401_109_dialog_content = "Algo huele mal. ¿Cómo podría un campo de batalla vaciarse así?",
  ui_story_1012_10121401_110_dialog_content = "No son más que perros sarnosos y miserables.",
  ui_story_1012_10121401_111_dialog_content = "¿Incluso monstruosidades como ustedes también temen a la muerte?",
  ui_story_1012_10121401_112_dialog_content = "...",
  ui_story_1012_10121401_113_dialog_content = "Cuidado ahora, Reinhardt. Te lastimarás ejerciendo un poder así.",
  ui_story_1012_10121401_114_dialog_content = "¡Jajaja! Tan absurdo. ¿No es esto un campo de batalla?",
  ui_story_1012_10121401_115_dialog_content = "No me hacía ilusiones acerca de salir ileso de aquí.",
  ui_story_1012_10121401_116_dialog_content = "Sería prudente usar ese poder para salvar a los demás.",
  ui_story_1012_10121401_117_dialog_content = "Sigues sin entender...",
  ui_story_1012_10121401_118_dialog_content = "Esta es una lucha que continuaremos hasta el final, hasta la victoria o la muerte.",
  ui_story_1012_10121401_119_dialog_content = "¡La idea de escapar nunca se me ocurrió!",
  ui_story_1012_10121401_120_dialog_content = "...",
  ui_story_1012_10121401_121_dialog_content = "Parece que simplemente somos incapaces de entendernos.",
  ui_story_1012_10121401_122_dialog_content = "¡Ja ja! Nada nuevo allí.",
  ui_story_1012_10121401_123_dialog_content = "Has elegido encender tu propia mecha.",
  ui_story_1012_10121401_124_dialog_content = "Así que ahora, déjame verte arder.",
  ui_story_1012_10121401_125_dialog_content = "Bien, tráelo.",
  ui_story_1012_10121401_126_dialog_content = "Esta bien puede ser nuestra batalla final.",
  ui_story_1012_10121401_127_dialog_content = "...",
  ui_story_1012_10121401_128_dialog_content = "(Eclipsian) Todas las unidades, ataquen el Obelisco del Retorno.",
  ui_story_1012_10121401_129_dialog_content = "*jadeando*",
  ui_story_1012_10121401_130_dialog_content = "Gaaaaah!!",
  ui_story_1012_10121401_131_dialog_content = "Todavía hay.... tantos Eclipsitos...",
  ui_story_1012_10121401_132_dialog_content = "Alejate de PlayerName!",
  ui_story_1012_10121401_133_dialog_content = "Arg...!",
  ui_story_1012_10121401_134_dialog_content = "Suerte que es mi brazo izquierdo... Todavía puedo empuñar mi lanza...",
  ui_story_1012_10121401_135_dialog_content = "Cuántos quedan, PlayerName? Dónde están...",
  ui_story_1012_10121401_136_dialog_content = "Oh, lo olvidé. No puedes oírme ahora...",
  ui_story_1012_10121401_137_dialog_content = "Ni siquiera sé cómo te van las cosas.",
  ui_story_1012_10121401_138_dialog_content = "No sé cuánto tiempo más pueda durar... Probablemente no tanto...",
  ui_story_1012_10121401_139_dialog_content = "¡Aaaahhhhh!",
  ui_story_1012_10121401_140_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10121401_141_dialog_content = "¡Ay! ¡Mi mano!",
  ui_story_1012_10121401_142_dialog_content = "¿La gente realmente... golpea así?",
  ui_story_1012_10121401_143_dialog_content = "...",
  ui_story_1012_10121401_144_dialog_content = "Oh no, está a la derecha...",
  ui_story_1012_10121401_145_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10121401_146_dialog_content = "*Tose*",
  ui_story_1012_10121401_147_dialog_content = "¡No! No he terminado... Y ese asqueroso ha vuelto...",
  ui_story_1012_10121401_148_dialog_content = "...",
  ui_story_1012_10121401_149_dialog_content = "Oh, yo sé que uno. Ese tipo de ataque intenso y rápido.",
  ui_story_1012_10121401_150_dialog_content = "¡Vamos, concéntrate! Concentrarse...",
  ui_story_1012_10121401_151_dialog_content = "<color=#e8d9bb>¡Silbido!</color>",
  ui_story_1012_10121401_152_dialog_content = "¡Uf! esquivado...",
  ui_story_1012_10121401_153_dialog_content = "Pero no tengo nada que dar...",
  ui_story_1012_10121401_154_dialog_content = "Estoy exhausto y todo lo que he hecho es esquivar ataques. Me las he arreglado para retrasar lo inevitable, pero...",
  ui_story_1012_10121401_155_dialog_content = "No puedo permitirme demorar más.",
  ui_story_1012_10121401_156_dialog_content = "Las cosas fuera de la torre se ven sombrías. Carleen no puede contener tantos eclipses por mucho tiempo.",
  ui_story_1012_10121401_157_dialog_content = "Necesito usar Chord of the Law, y cuanto antes mejor.",
  ui_story_1012_10121401_158_dialog_content = "¿Pero cómo?",
  ui_story_1012_10121401_159_dialog_content = "<color=#e8d9bb>¡Silbido!</color>",
  ui_story_1012_10121401_160_dialog_content = "¡No de nuevo!",
  ui_story_1012_10121401_161_dialog_content = "Argh... Apenas puedo ponerme de pie...",
  ui_story_1012_10121401_162_dialog_content = "Pero no puedo hacer nada hasta que me ocupe de esos dos Guardianes.",
  ui_story_1012_10121401_163_dialog_content = "Necesito sacarlos.",
  ui_story_1012_10121401_164_dialog_content = "Le daré otra oportunidad...",
  ui_story_1012_10121401_165_dialog_content = "¡Ahhhhhhhhhhh!",
  ui_story_1012_10121401_166_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10121401_167_dialog_content = "¡Es tan doloroso!",
  ui_story_1012_10121401_168_dialog_content = "Pero... espera, ¡este es un espacio mental!",
  ui_story_1012_10121401_169_dialog_content = "No importa cuánto dolor cause, nada puede hacerme daño aquí.",
  ui_story_1012_10121401_170_dialog_content = "Todo está en la mente. ¡Todo lo que tengo que hacer es luchar contra el dolor!",
  ui_story_1012_10121401_171_dialog_content = "Así que eso es lo que haré.",
  ui_story_1012_10121401_172_dialog_content = "Un golpe no causará ningún daño. Pero, ¿qué hay de cien golpes? ¿Un millón?",
  ui_story_1012_10121401_173_dialog_content = "¡Seguiré adelante hasta que sea derrotado!",
  ui_story_1012_10121401_174_option_content = "¡Puñetazo!",
  ui_story_1012_10121401_175_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10121401_176_dialog_content = "Ay...",
  ui_story_1012_10121401_177_option_content = "¡Puñetazo!",
  ui_story_1012_10121401_178_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10121401_179_dialog_content = "Lucha contra el dolor...",
  ui_story_1012_10121401_180_option_content = "¡Puñetazo!",
  ui_story_1012_10121401_181_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10121401_182_dialog_content = "No puedo sentir mis dedos. Eso es malo. Necesito dedos para hacer puños.",
  ui_story_1012_10121401_183_dialog_content = "¿Tenían que hacer este espacio mental tan convincente?",
  ui_story_1012_10121401_184_dialog_content = "¡No importa, todavía tengo mi otra mano!",
  ui_story_1012_10121401_185_option_content = "¡Puñetazo!",
  ui_story_1012_10121401_186_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10121401_187_dialog_content = "¿Qué tan duro tienes que ser, eh?",
  ui_story_1012_10121401_188_option_content = "¡Puñetazo!",
  ui_story_1012_10121401_189_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10121401_190_dialog_content = "Entonces, ¿esto funciona...?",
  ui_story_1012_10121401_191_dialog_content = "!",
  ui_story_1012_10121401_192_dialog_content = "Espera, me olvidé de ese...",
  ui_story_1012_10121401_193_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1012_10121401_194_dialog_content = "Urgh... Ay...",
  ui_story_1012_10121401_195_dialog_content = "No quedan fuerzas. No puedo... mover...",
  ui_story_1012_10121401_196_dialog_content = "No importa lo que haga, no puedo vencerlos solo...",
  ui_story_1012_10121401_197_dialog_content = "(Y en este momento, entendí el Decreto Supremo del Obelisco del Retorno).",
  ui_story_1012_10121401_198_dialog_content = "(Me di cuenta de lo mucho que estaba más allá de mi comprensión, lo distante.)",
  ui_story_1012_10121401_199_dialog_content = "(No se basó en una mera advertencia hablada para preservar su autoridad).",
  ui_story_1012_10121401_200_dialog_content = "(Apuntó al punto más débil de Caelestites).",
  ui_story_1012_10121401_201_dialog_content = "(Ninguna cantidad de fuerza de voluntad o sabiduría serviría aquí.)",
  ui_story_1012_10121401_202_dialog_content = "(Utiliza una sola cosa: poder, poder irresistible. Y con ese poder, se defenderá a sí mismo y a su Decreto Supremo).",
  ui_story_1012_10121401_203_dialog_content = "(Los caelestitas nunca han sido capaces de luchar contra eso, desde que nacieron).",
  ui_story_1012_10121401_204_dialog_content = "(Es una restricción innata en toda la raza caelestita.)",
  ui_story_1012_10121401_205_dialog_content = "...",
  ui_story_1012_10121401_206_dialog_content = "Lo siento por todos, yo...",
  ui_story_1012_10121401_207_dialog_content = "Bien, ¿quién está haciendo con todos los pensamientos negativos?",
  ui_story_1012_10121401_208_dialog_content = "!",
  ui_story_1012_10121401_209_dialog_content = "Vice?",
  ui_story_1012_10121401_210_dialog_content = "Esos tipos están siendo un poco molestos, ¿eh?",
  ui_story_1012_10121401_211_dialog_content = "Es posible que desee hacerse a un lado, solo estoy aprendiendo a manejar estos nuevos juguetes. No puedo prometer que estarás a salvo.",
  ui_story_1012_10121401_212_dialog_content = "Vice, ¡¡¡Realmente eres tú!!!",
  ui_story_1012_10121401_213_dialog_content = "¿Estás despierto? ¿Pero cómo?",
  ui_story_1012_10121401_214_dialog_content = "¿Qué pasa con todas las preguntas? ¿Cómo voy a saber por dónde empezar?",
  ui_story_1012_10121401_215_dialog_content = "Comencemos con los trabajos fáciles. Estos tipos al frente, mátalos, ¿sí?",
  ui_story_1012_10121401_216_dialog_content = "¡Sí!",
  ui_story_1012_10121401_217_dialog_content = "Entonces, ¿qué estamos esperando?",
  ui_story_1012_10121401_218_dialog_content = "PlayerName, estoy a tus órdenes.",
  ui_story_1012_10121402_1_dialog_content = "Bien, ustedes dos se han divertido. ¡Aquí termina!",
  ui_story_1012_10121402_2_dialog_content = "¡Tú primero, grandote!",
  ui_story_1012_10121402_3_dialog_content = "Zumbido...",
  ui_story_1012_10121402_4_dialog_content = "Debería haber aprendido a esquivar.",
  ui_story_1012_10121402_5_dialog_content = "¡Ninguna defensa es lo suficientemente fuerte para resistir mis flechas!",
  ui_story_1012_10121402_6_dialog_content = "Vice! ¡Cuidado!",
  ui_story_1012_10121402_7_dialog_content = "Sí, sí, lo sé. A mi derecha, ¿verdad?",
  ui_story_1012_10121402_8_dialog_content = "<color=#e8d9bb>¡Silbido!</color>",
  ui_story_1012_10121402_9_dialog_content = "Mmm... ¿Cómo lo supiste?",
  ui_story_1012_10121402_10_dialog_content = "Y ahora solo queda uno, lo que queda es fácil.",
  ui_story_1012_10121402_11_dialog_content = "¿Cuántas flechas puedes tomar? ¡Vamos a averiguar!",
  ui_story_1012_10121402_12_dialog_content = "Zumbido...",
  ui_story_1012_10121402_13_dialog_content = "¡Sí! Lo hicimos, ambos Guardianes están caídos.",
  ui_story_1012_10121402_14_dialog_content = "Vice, ¡¡¡Eso es genial!!!",
  ui_story_1012_10121402_15_dialog_content = "Puff... eran un poco duros.",
  ui_story_1012_10121402_16_dialog_content = "No podría haberlos tomado si no fuera por todos estos cambios en mi físico.",
  ui_story_1012_10121402_17_dialog_content = "Entonces, ¿cómo es que estás aquí? Pensé que este espacio mental solo estaba abierto para Caelestites.",
  ui_story_1012_10121402_18_dialog_content = "O tal vez... no eres realmente Vice? Eres solo un producto de mi...",
  ui_story_1012_10121402_19_dialog_content = "¡Por supuesto que soy real!",
  ui_story_1012_10121402_20_dialog_content = "¿Crees que eres una especie de superhéroe capaz de crear vicios mágicos cada vez que necesitas una mano?",
  ui_story_1012_10121402_21_dialog_content = "Supongo que no. Pero entonces, ¿cómo es que estás aquí? No tiene sentido.",
  ui_story_1012_10121402_22_dialog_content = "Está bien, lo mantendré simple...",
  ui_story_1012_10121402_23_dialog_content = "Me desperté de mi coma e inmediatamente tuve la sensación de que me necesitabas.",
  ui_story_1012_10121402_24_dialog_content = "¿Eh?",
  ui_story_1012_10121402_25_dialog_content = "Lo sé, yo tampoco puedo explicarlo. Era como si nuestras conciencias estuvieran unidas de alguna manera.",
  ui_story_1012_10121402_26_dialog_content = "Podía sentir lo preocupada que estabas. Y yo sabía dónde estabas.",
  ui_story_1012_10121402_27_dialog_content = "Cuando te encontré y te toqué, mi conciencia terminó aquí, como si hubiera sido atraída.",
  ui_story_1012_10121402_28_dialog_content = "Tu sabes el resto.",
  ui_story_1012_10121402_29_dialog_content = "¿Nuestras conciencias estaban vinculadas?",
  ui_story_1012_10121402_30_dialog_content = "Yo tampoco sé cómo sucedió.",
  ui_story_1012_10121402_31_dialog_content = "¡Pero podemos resolver los detalles más tarde!",
  ui_story_1012_10121402_32_dialog_content = "Carleen dijo algo sobre que necesitabas activar un arma definitiva en la torre, ¿no es así?",
  ui_story_1012_10121402_33_dialog_content = "Así que ¡vamos!",
  ui_story_1012_10121402_34_dialog_content = "¡Si, tienes razón!",
  ui_story_1012_10121402_35_dialog_content = "Tenemos que apoderarnos de la Autorización del anillo central. ¿Está en algún lugar de este espacio?",
  ui_story_1012_10121402_36_option_content = "¡Potencia de fuerza!",
  ui_story_1012_10121402_37_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_1012_10121402_38_dialog_content = "¡Ah! ¿Qué es esto...?",
  ui_story_1012_10121402_39_dialog_content = "(Mi conciencia se expandió para llenar por todas partes.)",
  ui_story_1012_10121402_40_dialog_content = "(Somos uno...)",
  ui_story_1012_10121402_41_dialog_content = "(Sentí una sensación de paz que nunca antes había experimentado. Era como si...)",
  ui_story_1012_10121402_42_dialog_content = "(Como si estuviera flotando en un cielo infinito.)",
  ui_story_1012_10121402_43_dialog_content = "(Nada podía detenerme. Todas las creaciones yacían a mis pies.)",
  ui_story_1012_10121402_44_dialog_content = "¿Funcionó? ¿Encontraste algo?",
  ui_story_1012_10121402_45_dialog_content = "No lo creas. No hay nada aquí, solo nosotros y estos dos guardianes golpeados.",
  ui_story_1012_10121402_46_dialog_content = "Pero para ser honesto, ni siquiera estoy seguro de saber lo que estoy buscando.",
  ui_story_1012_10121402_47_dialog_content = "Ojalá Neural Aux estuviera aquí.",
  ui_story_1012_10121402_48_dialog_content = "¿Y cómo puedo ser de servicio?",
  ui_story_1012_10121402_49_dialog_content = "¡Guau!",
  ui_story_1012_10121402_50_dialog_content = "¿Eres real?",
  ui_story_1012_10121402_51_dialog_content = "¿Cómo es que no respondiste cuando te necesitaba antes?",
  ui_story_1012_10121402_52_dialog_content = "Porque no se me permitió tocar el Core Ring.",
  ui_story_1012_10121402_53_dialog_content = "Entonces, ¿cómo es que puedes ahora?",
  ui_story_1012_10121402_54_dialog_content = "Porque es parte del Decreto Supremo.",
  ui_story_1012_10121402_55_dialog_content = "El Decreto Supremo pidió que Neural Aux apareciera aquí. Y seguí órdenes.",
  ui_story_1012_10121402_56_dialog_content = "¿El decreto supremo?",
  ui_story_1012_10121402_57_dialog_content = "¿Pensé que era yo quien te quería aquí?",
  ui_story_1012_10121402_58_dialog_content = "Correcto.",
  ui_story_1012_10121402_59_dialog_content = "Tú, actualmente, eres el Decreto Supremo.",
  ui_story_1012_10121402_60_dialog_content = "¡¿Qué?!",
  ui_story_1012_10121402_61_dialog_content = "Tu conciencia se ha fusionado con el Anillo Central.",
  ui_story_1012_10121402_62_dialog_content = "El Anillo del Núcleo es el portador del Decreto Supremo. Y así, tú eres el Decreto Supremo.",
  ui_story_1012_10121402_63_dialog_content = "Tus órdenes deben ser seguidas, tus deseos llevados a buen término.",
  ui_story_1012_10121402_64_dialog_content = "Entonces, ¿cómo puedo ser útil?",
  ui_story_1012_10121402_65_dialog_content = "Espera, el Decreto Supremo me ha estado obstruyendo, pero ahora... ¿Soy el Decreto Supremo?",
  ui_story_1012_10121402_66_dialog_content = "Bien, entonces... Quiero activar el Acorde de la Ley.",
  ui_story_1012_10121402_67_dialog_content = "Comandos recibidos. Iniciando el Acorde de la Ley.",
  ui_story_1012_10121402_68_dialog_content = "Ingrese los parámetros de orientación y la ley que desea aplicar.",
  ui_story_1012_10121402_69_dialog_content = "eh??? ¿Que es todo esto?",
  ui_story_1012_10121402_70_dialog_content = "Acorde de la Ley es un arma de precisión.",
  ui_story_1012_10121402_71_dialog_content = "Su uso requiere información específica sobre el tiempo y el objetivo.",
  ui_story_1012_10121402_72_dialog_content = "Esto es esencial para que los resultados coincidan con las expectativas.",
  ui_story_1012_10121402_73_dialog_content = "Pero, ¿cómo voy a saber qué poner?",
  ui_story_1012_10121402_74_dialog_content = "¿Son estos números pares? ¡No puedo leerlos!",
  ui_story_1012_10121402_75_dialog_content = "Este es un paso necesario. Ingrese los parámetros de orientación y la ley que desea aplicar.",
  ui_story_1012_10121402_76_dialog_content = "Solo... solo ataca todos los Eclipsites cerca del Obelisco del Retorno, ¿de acuerdo?",
  ui_story_1012_10121402_77_dialog_content = "Lo sentimos, su solicitud es demasiado vaga. Acorde de la Ley es un arma de precisión.",
  ui_story_1012_10121402_78_dialog_content = "Entonces, ¿¡qué se supone que debo hacer!?",
  ui_story_1012_10121402_79_dialog_content = "¿Seguramente no vas a impedir que lo use ahora, cuando lo necesitemos?",
  ui_story_1012_10121402_80_dialog_content = "Se han encontrado los parámetros existentes y se pueden utilizar para la inicialización.",
  ui_story_1012_10121402_81_dialog_content = "¿Desea continuar?",
  ui_story_1012_10121402_82_dialog_content = "¿Parámetros existentes?",
  ui_story_1012_10121402_83_dialog_content = "Alerta: Eclipsitas no registradas están ingresando al Obelisco del Retorno.",
  ui_story_1012_10121402_84_dialog_content = "Demasiados para contar con precisión.",
  ui_story_1012_10121402_85_dialog_content = "¡Oh, no! Vamos a perder la batalla afuera.",
  ui_story_1012_10121402_86_dialog_content = "No tengo más tiempo que perder.",
  ui_story_1012_10121402_87_dialog_content = "Neural Aux, ¿puede decirnos quién ingresó esos parámetros?",
  ui_story_1012_10121402_88_dialog_content = "Claro.",
  ui_story_1012_10121402_89_dialog_content = "Alguien que inició sesión como \"Francis\".",
  ui_story_1012_10121402_90_dialog_content = "Así que fue él.",
  ui_story_1012_10121402_91_dialog_content = "Alerta: Eclipsitas no registradas están ingresando al Obelisco del Retorno.",
  ui_story_1012_10121402_92_dialog_content = "Demasiados para contar...",
  ui_story_1012_10121402_93_dialog_content = "¿¡Quién era su objetivo!?",
  ui_story_1012_10121402_94_dialog_content = "Solo necesito saber una cosa, ¿a quién usó Francisco el Acorde de la Ley para atacar?",
  ui_story_1012_10121402_95_dialog_content = "Comprobando los registros de datos...",
  ui_story_1012_10121402_96_dialog_content = "Confirmado. Último objetivo: eclipses.",
  ui_story_1012_10121402_97_dialog_content = "Entendido.",
  ui_story_1012_10121402_98_dialog_content = "(Maestro Francis, ¿puedo confiar en usted?)",
  ui_story_1012_10121402_99_dialog_content = "Neural Aux, lanza el Acorde de la Ley utilizando los parámetros existentes!",
  ui_story_1012_10121402_100_dialog_content = "Copiar.",
  ui_story_1012_10121402_101_dialog_content = "Inicializar parámetros de lanzamiento a partir de datos históricos.",
  ui_story_1012_10121402_102_dialog_content = "Ajuste de destino: eclipses.",
  ui_story_1012_10121402_103_dialog_content = "Establezca el acceso de todos los Eclipsites a: Desterrado.",
  ui_story_1012_10121402_104_dialog_content = "Establezca la Ley que se aplicará para: <color=#FFB400>Evasión permanente del Obelisco del Retorno</color>",
  ui_story_1012_10121402_105_dialog_content = "Inicialización completada.",
  ui_story_1012_10121402_106_dialog_content = "Lanzamiento del Acorde de la Ley.",
  ui_story_1012_10121402_107_dialog_content = "¿Qué está pasando?",
  ui_story_1012_10121402_108_dialog_content = "¡Toda la torre está brillando!",
  ui_story_1012_10121402_109_dialog_content = "Es el amanecer. Lo hemos logrado.",
  ui_story_1012_10121402_110_dialog_content = "¡Ja ja! ¡Sabía que podía hacerlo!",
  ui_story_1012_10121402_111_dialog_content = "Muévanse todos. Busquemos un buen punto de vista.",
  ui_story_1012_10121402_112_dialog_content = "Un lugar desde el que podamos disfrutar del espectáculo.",
  ui_story_1012_10121402_113_dialog_content = "Oye, ¿qué pasa?",
  ui_story_1012_10121402_114_dialog_content = "¿Qué está haciendo la torre?",
  ui_story_1012_10121402_115_dialog_content = "Seguro que no puede ser...",
  ui_story_1012_10121402_116_dialog_content = "UH oh...",
  ui_story_1012_10121402_117_dialog_content = "...",
  ui_story_1012_10121402_118_dialog_content = "Gaah...",
  ui_story_1012_10121402_119_dialog_content = "¿Por qué se han detenido todos los eclipses?",
  ui_story_1012_10121402_120_dialog_content = "¡No retrocedas! ¡Sigue con el ataque!",
  ui_story_1012_10121402_121_dialog_content = "¡El enemigo no puede resistir mucho más!",
  ui_story_1012_10121402_122_dialog_content = "Gaah...",
  ui_story_1012_10121402_123_dialog_content = "¡Diablos!",
  ui_story_1012_10121402_124_dialog_content = "Lord Figerald, estos...",
  ui_story_1012_10121402_125_dialog_content = "Err... Uf...",
  ui_story_1012_10121402_126_dialog_content = "Señor... ¿Lord Figerald?",
  ui_story_1012_10121402_127_dialog_content = "Cómo puede ser esto...",
  ui_story_1012_10121402_128_dialog_content = "Lord Figerald, ¿hemos terminado de luchar?",
  ui_story_1012_10121402_129_dialog_content = "...",
  ui_story_1012_10121402_130_dialog_content = "Retiro. Todos retírense.",
  ui_story_1012_10121402_131_dialog_content = "Pero por qué...?",
  ui_story_1012_10121402_132_dialog_content = "¡Por que yo dije! Retírate, ¿entendido?",
  ui_story_1012_10121402_133_dialog_content = "Sí, mi Señor.",
  ui_story_1012_10121402_134_dialog_content = "Solo retírate. Es todo lo que podemos hacer...",
  ui_story_1012_10121402_135_dialog_content = "He perdido todo deseo de atacar...",
  ui_story_1012_10121402_136_dialog_content = "Mi mente sigue diciéndome que retroceda.",
  ui_story_1012_10121402_137_dialog_content = "Y no importa lo que haga... no puedo derrotar a mi propia mente.",
  ui_story_1012_10121402_138_dialog_content = "Están retrocediendo. ¡Los eclipses, se están retirando!",
  ui_story_1012_10121402_139_dialog_content = "Extraño. No tiene ningún sentido. ¿Por qué renuncian, justo cuando estaban a punto de ganar?",
  ui_story_1012_10121402_140_dialog_content = "¿Tiene algo que ver con esa luz de la Torre Blanca?",
  ui_story_1012_10121402_141_dialog_content = "preguntaremos PlayerName más tarde, él sabrá.",
  ui_story_1012_10121402_142_dialog_content = "Ah. Esa batalla seguro me sacó de quicio. Tal vez podría tumbarme en el césped aquí.",
  ui_story_1012_10121402_143_dialog_content = "¿No deberíamos estar preparados para otro ataque?",
  ui_story_1012_10121402_144_dialog_content = "Todavía tienen los números para hacer las cosas difíciles si nos rodean.",
  ui_story_1012_10121402_145_dialog_content = "Relax. Su mejor oportunidad era tomar la torre antes de que llegaran todos los ejércitos.",
  ui_story_1012_10121402_146_dialog_content = "Serán carne de cañón si se quedan, y no son tan estúpidos.",
  ui_story_1012_10121402_147_dialog_content = "Gracias por la lección, Gran Mariscal.",
  ui_story_1012_10121402_148_dialog_content = "Aproveche la oportunidad de descansar mientras pueda.",
  ui_story_1012_10121402_149_dialog_content = "Porque si no me equivoco, lo que sigue va a hacer que el combate parezca relajante.",
  ui_story_1012_10121402_150_dialog_content = "¡Nosotros... lo logramos!",
  ui_story_1012_10121402_151_dialog_content = "¿Lo hicimos? ¿Qué está pasando afuera?",
  ui_story_1012_10121402_152_dialog_content = "Todos los eclipses se retiraron.",
  ui_story_1012_10121402_153_dialog_content = "Parece que tenían que obedecer la ley que hicimos cumplir—",
  ui_story_1012_10121402_154_dialog_content = "\"Evitación permanente del Obelisco del Retorno\".",
  ui_story_1012_10121402_155_dialog_content = "¿Hiciste que los eclipses obedecieran una ley que estableciste?",
  ui_story_1012_10121402_156_dialog_content = "¡Eso es increíble!",
  ui_story_1012_10121402_157_dialog_content = "Puedo sentir el Acorde de la Ley trabajando. Realmente es un arma adecuada para Caelestites.",
  ui_story_1012_10121402_158_dialog_content = "No usa la fuerza. Simplemente planta una cierta idea en la mente del enemigo.",
  ui_story_1012_10121402_159_dialog_content = "Cambia la mentalidad de las personas y evita toda la violencia.",
  ui_story_1012_10121402_160_dialog_content = "Ese tipo de poder... da miedo.",
  ui_story_1012_10121402_161_dialog_content = "Oye, ¿qué pasa?",
  ui_story_1012_10121402_162_dialog_content = "Este espacio mental está empezando a volverse inestable.",
  ui_story_1012_10121402_163_dialog_content = "El Obelisco del Retorno se está quedando sin energía.",
  ui_story_1012_10121402_164_dialog_content = "Muchos componentes de un solo uso se dañaron al lanzar Chord of the Law y necesitan un reemplazo urgente.",
  ui_story_1012_10121402_165_dialog_content = "Busco personal de mantenimiento...",
  ui_story_1012_10121402_166_dialog_content = "Búsqueda fallida.",
  ui_story_1012_10121402_167_dialog_content = "Por lo que tiene poca potencia.",
  ui_story_1012_10121402_168_dialog_content = "Supongo que fue una suerte que durara lo suficiente como para usar Chord of the Law.",
  ui_story_1012_10121402_169_dialog_content = "Si no lo hubiera hecho... Odio siquiera pensar en dónde estaríamos ahora.",
  ui_story_1012_10121402_170_dialog_content = "Energía insuficiente para mantener las operaciones.",
  ui_story_1012_10121402_171_dialog_content = "El Obelisco del Retorno pronto entrará en silencio.",
  ui_story_1012_10121402_172_dialog_content = "¿eh? ¿Silencio? ¿Te refieres a?",
  ui_story_1012_10121402_173_dialog_content = "Todos los equipos dejarán de funcionar. Ninguna funcionalidad estará disponible.",
  ui_story_1012_10121402_174_dialog_content = "Será aún más tranquilo que antes de su llegada.",
  ui_story_1012_10121402_175_dialog_content = "Comprendo.",
  ui_story_1012_10121402_176_dialog_content = "Espera, Neural Aux, no querrás decir que...",
  ui_story_1012_10121402_177_dialog_content = "Hago. Ya no podré servir a los Caelestitas.",
  ui_story_1012_10121402_178_dialog_content = "...",
  ui_story_1012_10121402_179_dialog_content = "Pero tengo una tarea final que completar.",
  ui_story_1012_10121402_180_dialog_content = "Antes de que caiga el silencio, debo transmitir un mensaje del maestro Francis.",
  ui_story_1012_10121402_181_dialog_content = "¿Maestro Francisco?",
  ui_story_1012_10121402_182_dialog_content = "\"A ti, compañero Caelestite—\"",
  ui_story_1012_10121402_183_dialog_content = "\"Opté por transmitir este mensaje solo en el último momento\".",
  ui_story_1012_10121402_184_dialog_content = "\"No soy de pesimismo. Las celebraciones de la victoria son más mi estilo\".",
  ui_story_1012_10121402_185_dialog_content = "\"Y el solo hecho de saber que alguien está escuchando este mensaje me anima\".",
  ui_story_1012_10121402_186_dialog_content = "\"Qué idea tan extraña. Pensar que alguien muy, muy lejano, alguien que ni siquiera existe todavía, cumplirá mi deseo\".",
  ui_story_1012_10121402_187_dialog_content = "\"Tal vez es porque estamos en el mismo camino. Y qué camino tan poco transitado es\".",
  ui_story_1012_10121402_188_dialog_content = "¿Estamos en el mismo camino? ¿Cómo?",
  ui_story_1012_10121402_189_dialog_content = "\"Puede que no entiendas completamente lo que ha sucedido. Incluso puedes pensar que has tenido suerte\".",
  ui_story_1012_10121402_190_dialog_content = "\"Pero lo que quiero decir es esto: recuerda, todo sucede por una razón\".",
  ui_story_1012_10121402_191_dialog_content = "\"La energía falló en este preciso momento porque la torre retuvo solo lo suficiente para lanzar el Acorde de la Ley\".",
  ui_story_1012_10121402_192_dialog_content = "\"Fue mi regalo para ti\".",
  ui_story_1012_10121402_193_dialog_content = "¿¡Regalo!?",
  ui_story_1012_10121402_194_dialog_content = "\"Un regalo que te ayudó en tu lucha contra los Eclipsites\".",
  ui_story_1012_10121402_195_dialog_content = "\"Un regalo que te ayudó a liberarte de tu <color=#FFB400>innato</color> restricciones\".",
  ui_story_1012_10121402_196_dialog_content = "!",
  ui_story_1012_10121402_197_dialog_content = "\"Es hora\".",
  ui_story_1012_10121402_198_dialog_content = "\"Así que finalmente, les agradezco por tomar este camino\".",
  ui_story_1012_10121402_199_dialog_content = "\"El pasado ya pasó. El resto permanecerá...\"",
  ui_story_1012_10121402_200_dialog_content = "Adiós, Caelestita.",
  ui_story_1012_10121501_1_dialog_content = "Ay, qué alivio—",
  ui_story_1012_10121501_2_dialog_content = "Eraveil, tal como lo recuerdo.",
  ui_story_1012_10121501_3_dialog_content = "Siempre se ve mucho más natural cuando está en paz.",
  ui_story_1012_10121501_4_dialog_content = "Carleen, te ves hecho en. Toma, toma mi brazo.",
  ui_story_1012_10121501_5_dialog_content = "Oh, no quiero ser un problema...",
  ui_story_1012_10121501_6_dialog_content = "Cállate. PlayerName me contaste que me cargaste mientras yo estaba inconsciente.",
  ui_story_1012_10121501_7_dialog_content = "¡Ahora es el momento de devolverte el favor!",
  ui_story_1012_10121501_8_dialog_content = "...",
  ui_story_1012_10121501_9_dialog_content = "Bien entonces.",
  ui_story_1012_10121501_10_dialog_content = "¡Finalmente, emergen los héroes!",
  ui_story_1012_10121501_11_dialog_content = "¿Héroes? ¿Te estás burlando de mí?",
  ui_story_1012_10121501_12_dialog_content = "Jaja, por supuesto que no! Piénsalo: cambiaste el rumbo de esta gran batalla.",
  ui_story_1012_10121501_13_dialog_content = "Una batalla que el Gran Mariscal de Illumina y la Reina del Norte no pudieron ganar.",
  ui_story_1012_10121501_14_dialog_content = "Pero... no fui yo, ¿verdad?",
  ui_story_1012_10121501_15_dialog_content = "Todo lo que hice fue...",
  ui_story_1012_10121501_16_dialog_content = "Fue mi regalo para ti.",
  ui_story_1012_10121501_17_dialog_content = "Todo lo que hice fue terminar el trabajo de otras personas.",
  ui_story_1012_10121501_18_dialog_content = "La modestia es una cosa, pero esto es ir demasiado lejos.",
  ui_story_1012_10121501_19_dialog_content = "Ja ja. Bueno, todos luchamos duro, ¿verdad?",
  ui_story_1012_10121501_20_dialog_content = "yo no era yo Fuimos nosotros. Todos cambiamos las cosas.",
  ui_story_1012_10121501_21_dialog_content = "Hmm... No puedo discutir con eso.",
  ui_story_1012_10121501_22_dialog_content = "La victoria es de todos. Las palabras de un verdadero guerrero!",
  ui_story_1012_10121501_23_dialog_content = "¡Ja, sí! La victoria es de todos.",
  ui_story_1012_10121501_24_dialog_content = "me gusta tu forma de decirlo Reinhardt.",
  ui_story_1012_10121501_25_dialog_content = "Pero recuerda, sigues siendo especial.",
  ui_story_1012_10121501_26_dialog_content = "Nuestro punto de partida, nuestra clave, nuestro estandarte. El que trae el cambio.",
  ui_story_1012_10121501_27_dialog_content = "Y eso no es un elogio, sino una advertencia.",
  ui_story_1012_10121501_28_dialog_content = "Nunca lo olvides, ser especial es algo temible.",
  ui_story_1012_10121501_29_dialog_content = "No lo haré.",
  ui_story_1012_10121501_30_dialog_content = "Regresaste.",
  ui_story_1012_10121501_31_dialog_content = "¡Su Majestad!",
  ui_story_1012_10121501_32_dialog_content = "Siempre estás tan tranquilo, ya sea ahora o en el campo de batalla.",
  ui_story_1012_10121501_33_dialog_content = "Aunque supongo que viste el desenlace de antemano.",
  ui_story_1012_10121501_34_dialog_content = "...",
  ui_story_1012_10121501_35_dialog_content = "De hecho, esta vez no lo hice.",
  ui_story_1012_10121501_36_dialog_content = "¿Oh?",
  ui_story_1012_10121501_37_dialog_content = "No vi un futuro en el que cambiaras el rumbo de la batalla.",
  ui_story_1012_10121501_38_dialog_content = "Sólo te vi ir a hacer algo.",
  ui_story_1012_10121501_39_dialog_content = "Vos tambien...",
  ui_story_1012_10121501_40_dialog_content = "...",
  ui_story_1012_10121501_41_dialog_content = "Y tenía fe en que tendrías éxito.",
  ui_story_1012_10121501_42_dialog_content = "Su Majestad...",
  ui_story_1012_10121501_43_dialog_content = "¡Espero no haberte fallado!",
  ui_story_1012_10121501_44_dialog_content = "Cuidado con Eraveil. Ahí está tu respuesta.",
  ui_story_1012_10121501_45_dialog_content = "Todavía hay una pregunta para que respondas, PlayerName.",
  ui_story_1012_10121501_46_dialog_content = "¿Cómo lo hiciste?",
  ui_story_1012_10121501_47_dialog_content = "Los Eclipsites abandonaron repentinamente su ataque a la torre y salieron corriendo, con el rabo entre las piernas.",
  ui_story_1012_10121501_48_dialog_content = "Dijiste algo sobre un \"arma definitiva\", pero vi que no se usaba.",
  ui_story_1012_10121501_49_dialog_content = "Honestamente, no estoy muy seguro de mí mismo.",
  ui_story_1012_10121501_50_dialog_content = "Se sentía como si fuera más un arma mental.",
  ui_story_1012_10121501_51_dialog_content = "No atacó al enemigo físicamente. Atacó sus mentes.",
  ui_story_1012_10121501_52_dialog_content = "Insertó una orden en sus cabezas: alejarse del Obelisco del Retorno. Y lo hicieron.",
  ui_story_1012_10121501_53_dialog_content = "¿Control mental? Nunca supe que tales armas fueran posibles.",
  ui_story_1012_10121501_54_dialog_content = "Lo sé. A mí también me resulta extraño.",
  ui_story_1012_10121501_55_dialog_content = "Esto es significativo. ¿Qué podría significar tal arma para el mundo? ¿Cómo funciona y qué potencia tiene?",
  ui_story_1012_10121501_56_dialog_content = "Esto podría ser incluso peor que el Eclipse.",
  ui_story_1012_10121501_57_dialog_content = "Bueno, sobre eso... No creo que debamos preocuparnos demasiado.",
  ui_story_1012_10121501_58_dialog_content = "El arma se ha ido.",
  ui_story_1012_10121501_59_dialog_content = "¿Qué?",
  ui_story_1012_10121501_60_dialog_content = "La torre solo retuvo la energía para activar el arma una sola vez.",
  ui_story_1012_10121501_61_dialog_content = "Y ahora tanto el arma como la torre misma se han quedado en silencio.",
  ui_story_1012_10121501_62_dialog_content = "Nunca pertenecieron a nuestro tiempo. Sólo aguantaron aquí, para cumplir un deseo.",
  ui_story_1012_10121501_63_dialog_content = "Y cuando el arma disparó, volvieron a su estado original, su tarea completa.",
  ui_story_1012_10121501_64_dialog_content = "Ahora permanecerán aquí, como un testamento silencioso.",
  ui_story_1012_10121501_65_dialog_content = "Ya veo.",
  ui_story_1012_10121501_66_dialog_content = "Es raro. Casi siento afinidad por esa arma.",
  ui_story_1012_10121501_67_dialog_content = "Tal vez porque no era solo un arma.",
  ui_story_1012_10121501_68_dialog_content = "Era un <color=#FFB400>regalo</color>.",
  ui_story_1012_10121501_69_dialog_content = "<color=#e8d9bb>Retumbar... Retumbar... Retumbar...</color>",
  ui_story_1012_10121501_70_dialog_content = "Haa... haa... finalmente, se detuvo.",
  ui_story_1012_10121501_71_dialog_content = "Así que esto es... ¿Eraveil?",
  ui_story_1012_10121501_72_dialog_content = "Ahora bien, ¿por qué ha venido Lepidoz a Eraveil?",
  ui_story_1012_10121501_73_dialog_content = "Espera, ¿desde cuándo Eraveil tiene una torre así?",
  ui_story_1012_10121501_74_dialog_content = "Ah-ha, tenemos un recién llegado de aspecto dudoso, por lo que veo.",
  ui_story_1012_10121501_75_dialog_content = "No esperaba que la llave inglesa Rediesel apareciera tan pronto.",
  ui_story_1012_10121501_76_dialog_content = "¡El Gran Mariscal de Illumina!",
  ui_story_1012_10121501_77_dialog_content = "¿Qué haces en Eraveil?",
  ui_story_1012_10121501_78_dialog_content = "Lo creas o no, acabamos de tener una batalla.",
  ui_story_1012_10121501_79_dialog_content = "¿Una batalla?",
  ui_story_1012_10121501_80_dialog_content = "*Olfatea...*",
  ui_story_1012_10121501_81_dialog_content = "Efectivamente, podía oler el combate.",
  ui_story_1012_10121501_82_dialog_content = "Pero realmente, ¿una batalla?",
  ui_story_1012_10121501_83_dialog_content = "¿Qué, no nos crees?",
  ui_story_1012_10121501_84_dialog_content = "Bueno, ya sabes lo que dicen sobre confiar en Illumina...",
  ui_story_1012_10121501_85_dialog_content = "Pero es bastante animado aquí. Tantas figuras famosas reunidas en un solo lugar.",
  ui_story_1012_10121501_86_dialog_content = "La Reina del Norte y yo vinimos a pelear.",
  ui_story_1012_10121501_87_dialog_content = "Ya ves, cuando PlayerName organiza una fiesta, todos vienen.",
  ui_story_1012_10121501_88_dialog_content = "Así que te tenemos a ti, la Reina del Norte, y... ¿quién es?",
  ui_story_1012_10121501_89_dialog_content = "¿Quién?",
  ui_story_1012_10121501_90_dialog_content = "El de aspecto altivo detrás de ti.",
  ui_story_1012_10121501_91_dialog_content = "!",
  ui_story_1012_10121501_92_dialog_content = "...",
  ui_story_1012_10121501_93_dialog_content = "Victoria! Cuando lo hiciste...",
  ui_story_1012_10121501_94_dialog_content = "No me importa.",
  ui_story_1012_10121501_95_dialog_content = "Sólo estoy aquí para disfrutar del espectáculo.",
  ui_story_1012_10121501_96_dialog_content = "No puedo creer que incluso tú aparecieras.",
  ui_story_1012_10121501_97_dialog_content = "<color=#e8d9bb>Pisotear, pisar, pisar</color>",
  ui_story_1012_10121501_98_dialog_content = "¡Detente!",
  ui_story_1012_10121501_99_dialog_content = "¡Forma un perímetro!",
  ui_story_1012_10121501_100_dialog_content = "¡Sí señor!",
  ui_story_1012_10121501_101_dialog_content = "Esien, por fin.",
  ui_story_1012_10121501_102_dialog_content = "Sin embargo, tradicionalmente, los refuerzos llegan durante la batalla.",
  ui_story_1012_10121501_103_dialog_content = "Perdóneme, Gran Mariscal, pero no hemos sido enviados como refuerzos.",
  ui_story_1012_10121501_104_dialog_content = "Entonces estás aquí... ¿por qué?",
  ui_story_1012_10121501_105_dialog_content = "Lo siento, Gran Mariscal. Los detalles de la misión se revelan según la necesidad de saberlos, y no es necesario que los sepas.",
  ui_story_1012_10121501_106_dialog_content = "¡¿No necesito saberlo?!",
  ui_story_1012_10121501_107_dialog_content = "La última vez que lo comprobé, sigo siendo el Gran Mariscal de Illumina, ¿no?",
  ui_story_1012_10121501_108_dialog_content = "Tienes esa posición militar, sí.",
  ui_story_1012_10121501_109_dialog_content = "Pero no tienes autoridad fuera del campo de batalla.",
  ui_story_1012_10121501_110_dialog_content = "...",
  ui_story_1012_10121501_111_dialog_content = "Ahora lo entiendo. Es El Comité de nuevo, ¿no?",
  ui_story_1012_10121501_112_dialog_content = "Si me disculpas.",
  ui_story_1012_10121501_113_dialog_content = "Gran Mariscal... Ellos...",
  ui_story_1012_10121501_114_dialog_content = "No les hagas caso.",
  ui_story_1012_10121501_115_dialog_content = "Los políticos tienen más poder que el Gran Mariscal en el mundo real.",
  ui_story_1012_10121501_116_dialog_content = "¿Debo tomar nota de eso?",
  ui_story_1012_10121501_117_dialog_content = "No. Solo estoy lloriqueando.",
  ui_story_1012_10121501_118_dialog_content = "Por ahí. Otro escuadrón viene por aquí.",
  ui_story_1012_10121501_119_dialog_content = "Esos buitres... No tienen ningún interés en las batallas, pero están dispuestos a luchar entre ellos hasta la muerte por unos pocos cadáveres trofeo.",
  ui_story_1012_10121501_120_dialog_content = "Mi Señor, Illumina está en movimiento.",
  ui_story_1012_10121501_121_dialog_content = "¿Vamos a sentarnos aquí y esperar?",
  ui_story_1012_10121501_122_dialog_content = "Tener paciencia.",
  ui_story_1012_10121501_123_dialog_content = "Este es un asunto grave. Sería prudente considerar las ramificaciones antes de actuar.",
  ui_story_1012_10121501_124_dialog_content = "Lo que necesita Lumopolis es mantener el orden, no un clavo que sobresalga.",
  ui_story_1012_10121501_125_dialog_content = "¡Sí señor!",
  ui_story_1012_10121501_126_dialog_content = "Yo sabía Señor Schwartz había llegado tan pronto como vi a toda esta gente inundada.",
  ui_story_1012_10121501_127_dialog_content = "Lumopolis seguro que sabe cómo hacer una entrada tardía.",
  ui_story_1012_10121501_128_dialog_content = "Reinhardt, Illumina y Lumopolis hacen las cosas de manera diferente. ¿Por qué el sarcasmo?",
  ui_story_1012_10121501_129_dialog_content = "Guarda tu aliento para el asunto en cuestión.",
  ui_story_1012_10121501_130_dialog_content = "¿El asunto en cuestión? ¿No oliste el humo en el aire? Ya se termino.",
  ui_story_1012_10121501_131_dialog_content = "Mira, incluso los comerciantes están aquí. El negocio es el asunto que nos ocupa ahora, ¿no es así? ¡Jajaja!",
  ui_story_1012_10121501_132_dialog_content = "Los comerciantes tienen más que ganancias en sus manos.",
  ui_story_1012_10121501_133_dialog_content = "Y no soy un simple comerciante.",
  ui_story_1012_10121501_134_dialog_content = "Pero también la sombra que sigue a Lumopolis, ¿no?",
  ui_story_1012_10121501_135_dialog_content = "Esa es nuestra forma de vida. ¿Tiene algo más que decir, Gran Mariscal?",
  ui_story_1012_10121501_136_dialog_content = "Suficiente. Todos saben que nos reunimos aquí porque todos sentimos la turbulencia de los eventos.",
  ui_story_1012_10121501_137_dialog_content = "Debemos ser conscientes de lo que está pasando y lo que podría significar para el futuro.",
  ui_story_1012_10121501_138_dialog_content = "Gran Mariscal, ¿sería tan amable de mostrarnos el camino?",
  ui_story_1012_10121501_139_dialog_content = "Mi placer. Sígame por favor.",
  ui_story_1012_10121501_140_dialog_content = "Esos son muchos nombres importantes... ¿Qué planean hacer?",
  ui_story_1012_10121501_141_dialog_content = "Parece que el despertar del Obelisco del Retorno causó más inquietudes de las que imaginamos.",
  ui_story_1012_10121501_142_dialog_content = "Querrán saber qué pasó exactamente aquí, y...",
  ui_story_1012_10121501_143_dialog_content = "Cómo lidiar con esta torre.",
  ui_story_1012_10121501_144_dialog_content = "Trata... con esta torre...",
  ui_story_1012_10121501_145_dialog_content = "Lo siento. Sé que no suena agradable.",
  ui_story_1012_10121501_146_dialog_content = "Esta torre, debería ser tuya.",
  ui_story_1012_10121501_147_dialog_content = "Está bien. Entiendo.",
  ui_story_1012_10121501_148_dialog_content = "Los sentimientos personales deben dejarse de lado en los asuntos que conciernen al mundo.",
  ui_story_1012_10121501_149_dialog_content = "PlayerName.",
  ui_story_1012_10121501_150_dialog_content = "PlayerName! ¿Por qué estás parado al margen?",
  ui_story_1012_10121501_151_dialog_content = "Mmm... bueno...",
  ui_story_1012_10121501_152_dialog_content = "¡Venir! El Gran Mariscal pregunta por ti.",
  ui_story_1012_10121501_153_dialog_content = "pregunta por mi?",
  ui_story_1012_10121501_154_dialog_content = "Sí. Todos te están esperando. ¡Vamos!",
  ui_story_1012_10121501_155_dialog_content = "Oh, okay...",
  ui_story_1012_10121501_156_dialog_content = "¡Espera!",
  ui_story_1012_10121501_157_dialog_content = "PlayerName, una palabra de precaución.",
  ui_story_1012_10121501_158_dialog_content = "Digas lo que digas, no les hables de la posición que tomaron los antiguos Caelestitas.",
  ui_story_1012_10121501_159_dialog_content = "Gran Mariscal. PlayerName es aquí.",
  ui_story_1012_10121501_160_dialog_content = "Excelente. el Maestro de la Torre está aquí. Ahora por fin podemos empezar.",
  ui_story_1012_10121501_161_dialog_content = "¿¡Maestro de la torre!?",
  ui_story_1012_10121501_162_dialog_content = "Eres el último de los Caelestitas y, por lógica, el maestro del Obelisco del Retorno.",
  ui_story_1012_10121501_163_dialog_content = "Tanto la Reina como yo insistimos en tu presencia en las conversaciones.",
  ui_story_1012_10121501_164_dialog_content = "¿Con... todos los gobernantes?",
  ui_story_1012_10121501_165_dialog_content = "No hay nada que temer. Participaste en la Celebración de la Noche Blanca, ¿no es así?",
  ui_story_1012_10121501_166_dialog_content = "Tienes más autoridad en asuntos relacionados con el Obelisco del Retorno que nadie aquí.",
  ui_story_1012_10121501_167_dialog_content = "Sólo di lo que tienes en mente. No dejes que la estatura o la posición de nadie te detenga.",
  ui_story_1012_10121501_168_dialog_content = "Okay...",
  ui_story_1012_10121501_169_dialog_content = "Nosotros somos los que nos quedamos en la oscuridad.",
  ui_story_1012_10121501_170_dialog_content = "Tal vez seas el único que puede señalarnos el futuro.",
  ui_story_1012_10121501_171_dialog_content = "En primer lugar, ¿cómo veis esta Torre?",
  ui_story_1012_10121501_172_dialog_content = "Para nosotros, sin duda, es una grave amenaza para Lumopolis.",
  ui_story_1012_10121501_173_dialog_content = "Damocles activándose solo... Es inaudito.",
  ui_story_1012_10121501_174_dialog_content = "Además de eso, apunta en nuestra dirección, por lo que es necesario destruir la torre.",
  ui_story_1012_10121501_175_dialog_content = "(Damocles activándose por sí mismo. Sí, vi eso).",
  ui_story_1012_10121501_176_dialog_content = "Illumina secunda eso.",
  ui_story_1012_10121501_177_dialog_content = "Las reliquias antiguas en Gannon también sonaron la alerta. Fue causado por los movimientos aquí.",
  ui_story_1012_10121501_178_dialog_content = "Obviamente, el Obelisco del Retorno se consideraba hostil a los constructores de Gannon City.",
  ui_story_1012_10121501_179_dialog_content = "(Esto no es bueno. Todos me tratan como al enemigo).",
  ui_story_1012_10121501_180_dialog_content = "Estoy de acuerdo.",
  ui_story_1012_10121501_181_dialog_content = "En la antigüedad, el Obelisco del Retorno era algo que temía a los aurorianos.",
  ui_story_1012_10121501_182_dialog_content = "!",
  ui_story_1012_10121501_183_dialog_content = "Como todos estamos de acuerdo, entonces propongo que lo destruyamos o lo enterremos.",
  ui_story_1012_10121501_184_dialog_content = "Algo que no debería existir debería desaparecer.",
  ui_story_1012_10121501_185_dialog_content = "¡De ninguna manera! ¡Esa es una torre enorme de la que estás hablando!",
  ui_story_1012_10121501_186_dialog_content = "¡Las reliquias antiguas que contiene por sí solas podrían alcanzar una gran cantidad de dinero!",
  ui_story_1012_10121501_187_dialog_content = "¡Y podríamos aprender y aplicar ingeniería inversa a su tecnología para ayudar a la gente!",
  ui_story_1012_10121501_188_dialog_content = "Ustedes, los miembros de la realeza, realmente no tienen idea de lo difícil que es la vida para los plebeyos.",
  ui_story_1012_10121501_189_dialog_content = "No estamos aquí para hablar de necesidades civiles.",
  ui_story_1012_10121501_190_dialog_content = "Los Illumina tampoco creemos que el Obelisco del Retorno deba ser destruido.",
  ui_story_1012_10121501_191_dialog_content = "Dejando a un lado nuestros prejuicios y conjeturas, es una instalación con grandes valores militares.",
  ui_story_1012_10121501_192_dialog_content = "Debemos estudiarlo, no destruirlo por miedo.",
  ui_story_1012_10121501_193_dialog_content = "¿Para ser estudiado por Illumina? ¿Qué garantía tenemos de que pondrá los resultados en un buen trabajo?",
  ui_story_1012_10121501_194_dialog_content = "¿Puedo recordarte que tu historial está lejos de ser impecable?",
  ui_story_1012_10121501_195_dialog_content = "Oigan, relájense, gente.",
  ui_story_1012_10121501_196_dialog_content = "Mira a tu alrededor. Esta torre es solo un montón de piedras.",
  ui_story_1012_10121501_197_dialog_content = "No hay artilugios que funcionen ni Lumina que fluya.",
  ui_story_1012_10121501_198_dialog_content = "¿Estás diciendo que le tienes miedo a algunas piedras?",
  ui_story_1012_10121501_199_dialog_content = "Piedras que sirvieron para un propósito desconocido. ¿Quién puede decir que no volverán a funcionar de repente?",
  ui_story_1012_10121501_200_dialog_content = "U-Um...",
  ui_story_1012_10121501_201_dialog_content = "Les puedo asegurar que la energía del Obelisco del Retorno está totalmente agotada.",
  ui_story_1012_10121501_202_dialog_content = "Justo como dijo el Gran Mariscal, ahora es solo un montón de piedras.",
  ui_story_1012_10121501_203_dialog_content = "Piedras que guardaron un registro de nuestras historias.",
  ui_story_1012_10121501_204_dialog_content = "...",
  ui_story_1012_10121501_205_dialog_content = "Esa es una gran garantía de tu parte, Caelestite. ¿Estás seguro de que puedes hacer esa garantía?",
  ui_story_1012_10121501_206_dialog_content = "Yo...",
  ui_story_1012_10121501_207_dialog_content = "Mi Señor, puedo responder por él.",
  ui_story_1012_10121501_208_dialog_content = "Carleen?",
  ui_story_1012_10121501_209_dialog_content = "PlayerName y he explorado completamente la torre.",
  ui_story_1012_10121501_210_dialog_content = "Puedo garantizarle que la torre ya no funciona.",
  ui_story_1012_10121501_211_dialog_content = "...",
  ui_story_1012_10121501_212_dialog_content = "¿Ver? No hay necesidad de tensión.",
  ui_story_1012_10121501_213_dialog_content = "Para el mundo de hoy, esta torre ya no es una amenaza, sino un tesoro de tesoros antiguos.",
  ui_story_1012_10121501_214_dialog_content = "Una vez perteneció a los Caelestitas, y así debe permanecer.",
  ui_story_1012_10121501_215_dialog_content = "¿Hmm?",
  ui_story_1012_10121501_216_dialog_content = "Yo creo PlayerName es el propietario legítimo de la torre ahora.",
  ui_story_1012_10121501_217_dialog_content = "Necesitaremos su permiso y aprobación sobre cómo manejaremos los artículos en la torre.",
  ui_story_1012_10121501_218_dialog_content = "Estoy seguro PlayerName estaría de acuerdo con cualquier investigación que pudiera beneficiarnos a todos.",
  ui_story_1012_10121501_219_dialog_content = "Y PlayerName tendrá derecho a negar cualquier investigación que pueda causar un daño potencial.",
  ui_story_1012_10121501_220_dialog_content = "Por favor, déjame aclarar algo primero.",
  ui_story_1012_10121501_221_dialog_content = "La Gran Mariscal habla por sí misma. Sus opiniones no representan las opiniones de Illumina de ninguna manera.",
  ui_story_1012_10121501_222_dialog_content = "¿Vaya? Entonces, ¿cuál es la posición de Illumina en esto?",
  ui_story_1012_10121501_223_dialog_content = "Illumina insiste en estudiar todas las cosas en el Obelisco del Retorno.",
  ui_story_1012_10121501_224_dialog_content = "No debe pertenecer a nadie.",
  ui_story_1012_10121501_225_dialog_content = "Tsk... Ustedes...",
  ui_story_1012_10121501_226_dialog_content = "estoy de acuerdo con Reinhardt.",
  ui_story_1012_10121501_227_dialog_content = "PlayerName es el propietario legítimo del Obelisco del Retorno.",
  ui_story_1012_10121501_228_dialog_content = "Reina Bethlehem...",
  ui_story_1012_10121501_229_dialog_content = "Todos luchamos alguna vez para proteger nuestros hogares. No hay razón más digna de respeto que esta.",
  ui_story_1012_10121501_230_dialog_content = "Y los caelestitas luchan para proteger este lugar ahora, al igual que nosotros.",
  ui_story_1012_10121501_231_dialog_content = "Si la propiedad de su hogar ancestral iba a ser determinada por otros, entonces la guerra estaba perdida.",
  ui_story_1012_10121501_232_dialog_content = "Tanto los Aurorianos como los Eclipsitas son forasteros para los Caelestitas.",
  ui_story_1012_10121501_233_dialog_content = "Si llamamos a los caelestitas nuestros aliados, entonces nosotros, los aurorianos, debemos respetar a nuestro aliado y no invadir Eraveil.",
  ui_story_1012_10121501_234_dialog_content = "Su Majestad...",
  ui_story_1012_10121501_235_dialog_content = "En cuanto al señor SchwartzLas preocupaciones, las veo como infundadas.",
  ui_story_1012_10121501_236_dialog_content = "Un arma no es inherentemente buena o mala. Eso lo decide el que tiene el gatillo.",
  ui_story_1012_10121501_237_dialog_content = "Como todos hemos sido testigos, PlayerName usó el Obelisco del Retorno para evitar esta guerra.",
  ui_story_1012_10121501_238_dialog_content = "La Caelestita nos ha mostrado a todos la posición que ocupa el Obelisco del Retorno.",
  ui_story_1012_10121501_239_dialog_content = "...",
  ui_story_1012_10121501_240_dialog_content = "Es raro verte expresar tu opinión así, Reina. Bethlehem.",
  ui_story_1012_10121501_241_dialog_content = "Cuan importante es esto Para ti?",
  ui_story_1012_10121501_242_dialog_content = "El Caelestita es un importante aliado de los Aurorianos.",
  ui_story_1012_10121501_243_dialog_content = "Entendido.",
  ui_story_1012_10121501_244_dialog_content = "Mejor no digo más, o alguien va a pensar que soy conservador.",
  ui_story_1012_10121501_245_dialog_content = "La Reina del Norte se ha puesto de pie y respeto su decisión.",
  ui_story_1012_10121501_246_dialog_content = "Lumopolis ya no interferirá con los asuntos relacionados con el manejo del Obelisco del Retorno.",
  ui_story_1012_10121501_247_dialog_content = "¿Qué dicen todos ustedes?",
  ui_story_1012_10121501_248_dialog_content = "Si ese es el caso, estoy de acuerdo.",
  ui_story_1012_10121501_249_dialog_content = "Ahora, ¿no es eso agradable? ¡No tengo otras opiniones!",
  ui_story_1012_10121501_250_dialog_content = "...",
  ui_story_1012_10121501_251_dialog_content = "He dejado clara la posición de Illumina y no comentaré todas sus decisiones.",
  ui_story_1012_10121501_252_dialog_content = "Parece que hemos llegado a una conclusión.",
  ui_story_1012_10121501_253_dialog_content = "De cualquier manera, la guerra ha terminado y todos podemos disfrutar de la paz por un poco más de tiempo...",
  ui_story_1012_10121501_254_dialog_content = "Hasta que surja la próxima guerra. La paz nunca dura, pero al menos podemos aprovecharla al máximo.",
  ui_story_1012_10121501_255_dialog_content = "En cuanto a ti, PlayerName, felicidades por tu trofeo.",
  ui_story_1012_10121501_256_dialog_content = "Un verdadero hogar.",
  ui_story_1012_10121501_257_dialog_content = "...",
  ui_story_1012_10121501_258_dialog_content = "Ehhh...",
  ui_story_1012_10121501_259_dialog_content = "Un verdadero hogar...",
  ui_story_1012_10121501_260_dialog_content = "¿Por qué suspiras?",
  ui_story_1012_10121501_261_dialog_content = "¿¡S-Su Majestad!?",
  ui_story_1012_10121501_262_dialog_content = "¿Por qué estás aquí?",
  ui_story_1012_10121501_263_dialog_content = "Llevas tus problemas en tu cara.",
  ui_story_1012_10121501_264_dialog_content = "Jaja... Nada se te escapa, ya veo.",
  ui_story_1012_10121501_265_dialog_content = "Hmm...",
  ui_story_1012_10121501_266_dialog_content = "Estoy un poco perdido... Simplemente no entiendo.",
  ui_story_1012_10121501_267_dialog_content = "¿Por la batalla?",
  ui_story_1012_10121501_268_dialog_content = "No exactamente. YO...",
  ui_story_1012_10121501_269_dialog_content = "Estoy aquí si necesitas que alguien te escuche.",
  ui_story_1012_10121501_270_dialog_content = "No como la Reina del Norte, sino solo como yo.",
  ui_story_1012_10121501_271_dialog_content = "Solo se tú...",
  ui_story_1012_10121501_272_dialog_content = "Gracias... Realmente me vendría bien una persona con quien hablar.",
  ui_story_1012_10121501_273_dialog_content = "Ve siempre derecho. No voy a ninguna parte.",
  ui_story_1012_10121501_274_dialog_content = "Yo... Vimos algo ahí abajo... Con respecto a la historia de los Caelestitas.",
  ui_story_1012_10121501_275_dialog_content = "Los registros que quedan en el Obelisco del Retorno son solo fragmentos, pero vi...",
  ui_story_1012_10121501_276_dialog_content = "Vi cómo Caelestites luchaba con los Eclipsites...",
  ui_story_1012_10121501_277_dialog_content = "Lo que significa... En la antigüedad, los caelestitas pueden haberse aliado con los eclipsitas.",
  ui_story_1012_10121501_278_dialog_content = "¿Las Caelestitas y las Eclipsitas?",
  ui_story_1012_10121501_279_dialog_content = "Sí... Los experimenté trabajando juntos.",
  ui_story_1012_10121501_280_dialog_content = "No sé cómo describir lo que sentí por ti...",
  ui_story_1012_10121501_281_dialog_content = "No tengo ninguna prueba concreta, pero creo que realmente sucedió.",
  ui_story_1012_10121501_282_dialog_content = "Incluso después de la batalla, todavía no puedo deshacerme de ella... yo...",
  ui_story_1012_10121501_283_dialog_content = "Creo que es más de lo que puedo manejar.",
  ui_story_1012_10121501_284_dialog_content = "¿Estás bien, PlayerName?",
  ui_story_1012_10121501_285_dialog_content = "Siento que mi cabeza está a punto de explotar. Lamento no tener algunas de esas cosas para mostrarte.",
  ui_story_1012_10121501_286_dialog_content = "Lo que viste puede no ser necesariamente toda la verdad. Además de eso, no tenemos registros de una alianza entre Caelestites y Eclipsites.",
  ui_story_1012_10121501_287_dialog_content = "¡Te prometo que vi a Caelestites y Eclipsites derribando a los aurorianos!",
  ui_story_1012_10121501_288_dialog_content = "Ese sentimiento... no era una simple ilusión.",
  ui_story_1012_10121501_289_dialog_content = "Quería que fuera una ilusión... Realmente quiero.",
  ui_story_1012_10121501_290_dialog_content = "Si fuera verdad, no Novio ¿saber? Ha vivido durante mucho tiempo, pero nunca dijo nada al respecto.",
  ui_story_1012_10121501_291_dialog_content = "Sí, y no pude encontrar nada relacionado con lo que vi en los registros históricos a bordo de Soroz.",
  ui_story_1012_10121501_292_dialog_content = "Hasta donde yo sé, ni Lumopolis ni Illumina tienen ninguna evidencia de esto... De lo contrario...",
  ui_story_1012_10121501_293_dialog_content = "De lo contrario, un \"aliado de los Eclipsites\" como yo sin duda sería... Jeje...",
  ui_story_1012_10121501_294_dialog_content = "Déjame decirte exactamente lo que encontramos, desde el principio...",
  ui_story_1012_10121501_295_dialog_content = "... Eso es todo.",
  ui_story_1012_10121501_296_dialog_content = "...",
  ui_story_1012_10121501_297_dialog_content = "En primer lugar, a pesar de todo lo que has visto, los fragmentos están lejos de ser suficientes para llegar a una conclusión.",
  ui_story_1012_10121501_298_dialog_content = "En segundo lugar, incluso si realmente sucedió, debe ser antiguo.",
  ui_story_1012_10121501_299_dialog_content = "De hecho, puede ser tan antiguo que incluso sus ancestros no lo supieran.",
  ui_story_1012_10121501_300_dialog_content = "¿Quieres decir... que puede ser anterior a la historia de Northland?",
  ui_story_1012_10121501_301_dialog_content = "Los aurorianos también solo tienen fragmentos de nuestra historia antigua. La mayor parte es en realidad desconocida para nosotros.",
  ui_story_1012_10121501_302_dialog_content = "Sin embargo, en cualquier registro histórico que tengamos, los Caelestitas siempre han sido amigos de los Aurorianos.",
  ui_story_1012_10121501_303_dialog_content = "Y nuestros dos pueblos lucharon juntos contra los Eclipsitas. Eso nunca ha cambiado.",
  ui_story_1012_10121501_304_dialog_content = "¿Tu gente no fue diezmada también por los Eclipsites?",
  ui_story_1012_10121501_305_dialog_content = "Sí... Es por eso que no puedo entenderlo. Sólo quiero saber qué pasó realmente.",
  ui_story_1012_10121501_306_dialog_content = "Pero... si los Caelestites y Eclipsites realmente...",
  ui_story_1012_10121501_307_dialog_content = "Incluso si fuera así, ¿cómo te afecta hoy algo tan lejano y antiguo?",
  ui_story_1012_10121501_308_dialog_content = "Estuve pensando... Si los caelestitas realmente se aliaron con los eclipsitas...",
  ui_story_1012_10121501_309_dialog_content = "Entonces lo que he aprendido desde la infancia, todo sobre nuestra historia y creencias... todo sería una mentira.",
  ui_story_1012_10121501_310_dialog_content = "¿Qué pensaría mi gente si vieran lo que yo vi...?",
  ui_story_1012_10121501_311_dialog_content = "Si eso fuera cierto... Los caelestitas... serían despreciables.",
  ui_story_1012_10121501_312_dialog_content = "Aunque Caelestites y Aurorians comparten diferentes puntos de vista sobre muchas cosas, Caelestites siempre han sido conocidos por abogar por la paz y abrazar la naturaleza.",
  ui_story_1012_10121501_313_dialog_content = "Por supuesto, hay cosas aquí que todavía tenemos que entender, pero tú...",
  ui_story_1012_10121501_314_dialog_content = "He estado pensando... Sólo he podido llegar hasta aquí creyendo en los Caelestitas. Si en lo que creo fuera mentira...",
  ui_story_1012_10121501_315_dialog_content = "Entonces... ¿en qué me convierte eso...?",
  ui_story_1012_10121501_316_dialog_content = "Eres la Caelestite más valiente y resistente que he conocido. PlayerName.",
  ui_story_1012_10121501_317_dialog_content = "Eh... Mi cabeza va a explotar.",
  ui_story_1012_10121501_318_dialog_content = "PlayerName, si los caelestitas fueran realmente aliados de los eclipsitas, ¿te aliarías con los eclipsitas?",
  ui_story_1012_10121501_319_dialog_content = "¿¡Qué!? ¡No! ¡Nunca! ¡Lucharé contra los Eclipsites pase lo que pase!",
  ui_story_1012_10121501_320_dialog_content = "Se llevaron a mi familia y lastimaron a mis amigos. ¡No hay forma de que los perdone!",
  ui_story_1012_10121501_321_dialog_content = "Tu creencia y fuerza se transmiten de los que te precedieron, ¿no es así?",
  ui_story_1012_10121501_322_dialog_content = "La historia es exactamente eso, historia. Lo más importante eres tú y la bondad y valentía de tu pueblo.",
  ui_story_1012_10121501_323_dialog_content = "Creo que entiendo lo que intentas decir... pero creo que necesitaré un tiempo antes de poder aceptar esta... mancha...",
  ui_story_1012_10121501_324_dialog_content = "¿Recuerdas cómo criticaste a todos los líderes por sus conspiraciones en la Celebración de la Noche Blanca?",
  ui_story_1012_10121501_325_dialog_content = "Harías bien en ser siempre esa persona.",
  ui_story_1012_10121501_326_dialog_content = "Pero... trae mucha vergüenza a los Caelestitas y me hace dudar de mí mismo...",
  ui_story_1012_10121501_327_dialog_content = "Lo que es peor, tal vez incluso mis amigos duden en confiar en mí...",
  ui_story_1012_10121501_328_dialog_content = "¿Me verían como una amenaza potencial para el mundo, tal como sucedió allí?",
  ui_story_1012_10121501_329_dialog_content = "Yo... no quiero que me miren con recelo... odio ese sentimiento...",
  ui_story_1012_10121501_330_dialog_content = "Tanto Lumopolis como Illumina tienen un pasado turbio, así que ¿por qué sigues considerando Carleen y Vice como tus mejores amigos?",
  ui_story_1012_10121501_331_dialog_content = "Porque luchamos juntos, confiamos el uno en el otro y confiamos el uno en el otro...",
  ui_story_1012_10121501_332_dialog_content = "¿Romperían esa confianza solo por algo que les sucedió a los caelestitas hace tanto, tanto tiempo?",
  ui_story_1012_10121501_333_dialog_content = "¡Definitivamente no!",
  ui_story_1012_10121501_334_dialog_content = "Como puede ver, esta no es una pregunta complicada en absoluto.",
  ui_story_1012_10121501_335_dialog_content = "Usted está PlayerName, un Caelestita, sí, pero no representas a todo el pueblo Caelestita.",
  ui_story_1012_10121501_336_dialog_content = "Pero los caelestitas lo son todo para mí... Al igual que Northland lo es todo para ti.",
  ui_story_1012_10121501_337_dialog_content = "\"Los caelestitas no valen nada en una pelea, e incluso se pusieron del lado de los eclipsitas en el pasado...\"",
  ui_story_1012_10121501_338_dialog_content = "La idea de que alguien diga algo así me duele.",
  ui_story_1012_10121501_339_dialog_content = "Entiendo.",
  ui_story_1012_10121501_340_dialog_content = "Todavía tenemos que aprender la verdadera historia de tu pueblo.",
  ui_story_1012_10121501_341_dialog_content = "Es posible que tus ancestros eligieran rebelarse y, por lo tanto, alteraran el destino de los Caelestitas.",
  ui_story_1012_10121501_342_dialog_content = "Pero el pasado no se puede cambiar.",
  ui_story_1012_10121501_343_dialog_content = "Y ahora, el futuro de los Caelestites está en tus manos.",
  ui_story_1012_10121501_344_dialog_content = "Yo... necesito tiempo para pensar en esto.",
  ui_story_1012_10121501_345_dialog_content = "Tal vez lo que necesito hacer es encontrar la verdad.",
  ui_story_1012_10121501_346_dialog_content = "¿Qué harías si es una fea verdad, PlayerName?",
  ui_story_1012_10121501_347_dialog_content = "Tengo miedo de que la verdad pueda ser aún más fea de lo que imaginaba.",
  ui_story_1012_10121501_348_dialog_content = "Y que tal vez tenga que soportar la sospecha y el escrutinio de todos...",
  ui_story_1012_10121501_349_dialog_content = "Necesitarás tiempo, PlayerName.",
  ui_story_1012_10121501_350_dialog_content = "Sí... Tal vez mucho tiempo...",
  ui_story_1012_10121501_351_dialog_content = "<color=#e8d9bb>\"Control principal: activo\".</color>",
  ui_story_1012_10121501_352_dialog_content = "<color=#e8d9bb>\"Módulos Biológicos: Activos\".</color>",
  ui_story_1012_10121501_353_dialog_content = "<color=#e8d9bb>\"Soporte vital: activo\".</color>",
  ui_story_1012_10121501_354_dialog_content = "<color=#e8d9bb>\"Motores en marcha...\"</color>",
  ui_story_1012_10121501_355_dialog_content = "<color=#e8d9bb>\"16%... 33%...\"</color>",
  ui_story_1012_10121501_356_dialog_content = "<color=#e8d9bb>\"89%... 97%...\"</color>",
  ui_story_1012_10121501_357_dialog_content = "<color=#e8d9bb>\"100%. Compromiso exitoso\".</color>",
  ui_story_1012_10121501_358_dialog_content = "¡Guau! ¡Soroz está completamente reparado!",
  ui_story_1012_10121501_359_dialog_content = "¡Sí, finalmente!",
  ui_story_1012_10121501_360_dialog_content = "Aunque la conciencia aún no se ha despertado, ¡esto sigue siendo una gran victoria!",
  ui_story_1012_10121501_361_dialog_content = "Como si hubieras recuperado algo que perdiste, ¿verdad?",
  ui_story_1012_10121501_362_dialog_content = "¡Es Correcto!",
  ui_story_1012_10121501_363_dialog_content = "Uf... Estoy exhausto. No puedo creer la cantidad de situaciones de vida o muerte por las que hemos pasado en los últimos días.",
  ui_story_1012_10121501_364_dialog_content = "Sí, como si siempre pendiéramos de un hilo...",
  ui_story_1012_10121501_365_dialog_content = "Pero aguantamos y lo logramos.",
  ui_story_1012_10121501_366_dialog_content = "Tengo que decir... Tuvimos mucha suerte, ¡jaja!",
  ui_story_1012_10121501_367_dialog_content = "Estás en lo correcto.",
  ui_story_1012_10121501_368_dialog_content = "Pero... tal vez no sea solo suerte.",
  ui_story_1012_10121501_369_dialog_content = "Tal vez todo sucedió por una razón... que aún se nos escapa.",
  ui_story_1012_10121501_370_dialog_content = "Suenas como si realmente lo hubieras pensado bien. ¿Pasó algo en el Obelisco del Retorno?",
  ui_story_1012_10121501_371_dialog_content = "Es solo que cuando recuerdo, casi puedo sentir que hay una conexión entre todo lo que sucedió.",
  ui_story_1012_10121501_372_dialog_content = "Muchas cosas le sucedieron a la gente en el Obelisco del Retorno.",
  ui_story_1012_10121501_373_dialog_content = "Aunque es posible que nunca conozcamos sus historias, vemos las marcas que dejan.",
  ui_story_1012_10121501_374_dialog_content = "Y es como si hubiéramos estado volviendo sobre los pasos.",
  ui_story_1012_10121501_375_dialog_content = "No sé a quién pertenecían ni qué pretendían hacer...",
  ui_story_1012_10121501_376_dialog_content = "Solo estábamos armando un gran rompecabezas paso a paso en el camino.",
  ui_story_1012_10121501_377_dialog_content = "Te refieres a ese señor Francis, ¿no?",
  ui_story_1012_10121501_378_dialog_content = "Él parece estar en tu mente mucho.",
  ui_story_1012_10121501_379_dialog_content = "Sí... Me he estado preguntando, ¿cuál fue su historia?",
  ui_story_1012_10121501_380_dialog_content = "El rifle le pertenecía, y luchó contra los Eclipsites en la torre...",
  ui_story_1012_10121501_381_dialog_content = "Estaba a cargo de los experimentos de Chord Link y su laboratorio estaba escondido dentro de la Zona Exiliada.",
  ui_story_1012_10121501_382_dialog_content = "No sé si él también pasó por lo que pasamos luchando por el control de la Autorización del Anillo Central, pero...",
  ui_story_1012_10121501_383_dialog_content = "Un Aurorian mejorado con Chord Link fue clave.",
  ui_story_1012_10121501_384_dialog_content = "Derecha. Ahora que lo dijiste, parece que hemos estado siguiendo sus pasos todo el tiempo.",
  ui_story_1012_10121501_385_dialog_content = "Luchamos contra el Eclipse. ¿Qué hay de él?",
  ui_story_1012_10121501_386_dialog_content = "Contra lo que luchó... tal vez incluso más terrible.",
  ui_story_1012_10121501_387_dialog_content = "No puedo señalar exactamente qué... pero puede ser el destino mismo.",
  ui_story_1012_10121501_388_dialog_content = "No quiere tu vida, pero quiere controlar tu vida.",
  ui_story_1012_10121501_389_dialog_content = "El Maestro Francis trató de luchar contra eso... contra su \"naturaleza\".",
  ui_story_1012_10121501_390_dialog_content = "Resistir... a la propia naturaleza...",
  ui_story_1012_10121501_391_dialog_content = "¿Es eso posible?",
  ui_story_1012_10121501_392_dialog_content = "Me pregunto si lo logró o no.",
  ui_story_1012_10121501_393_dialog_content = "Esa respuesta es obvia. Solo mira por la ventana.",
  ui_story_1012_10121501_394_dialog_content = "Los Caelestites tienen un lugar al que llamar hogar bajo el Obelisco del Retorno.",
  ui_story_1012_10121501_395_dialog_content = "El Decreto Supremo ya no dicta sus vidas, ni están sujetos a los Eclipses.",
  ui_story_1012_10121501_396_dialog_content = "Su sueño ha alterado el destino de sus futuras generaciones...",
  ui_story_1012_10121501_397_dialog_content = "Ha cambiado la vida de todos los Caelestitas.",
  ui_story_1013_10130101_1_dialog_content = "Otro día tranquilo entonces.",
  ui_story_1013_10130101_2_dialog_content = "Sip.",
  ui_story_1013_10130101_3_dialog_content = "Parece una eternidad desde que usamos Luminatics para luchar contra los Eclipsites.",
  ui_story_1013_10130101_4_dialog_content = "Apuesto a que incluso mis habilidades de combate se han oxidado.",
  ui_story_1013_10130101_5_dialog_content = "¡La paz es algo bueno!",
  ui_story_1013_10130101_6_dialog_content = "Si alguna vez llega el día en que todos los Eclipsites son eliminados, probablemente así sería la vida.",
  ui_story_1013_10130101_7_dialog_content = "Nunca tendríamos que preocuparnos por ser atacados. Y podríamos pasar nuestros días caminando, pescando o cocinando.",
  ui_story_1013_10130101_8_dialog_content = "Eso suena muy bien, en realidad.",
  ui_story_1013_10130101_9_dialog_content = "¿Qué piensas hacer cuando llegue ese momento?",
  ui_story_1013_10130101_10_option_content = "¿Plantar arboles?",
  ui_story_1013_10130101_11_dialog_content = "Planta montones de árboles raros para embellecer los Jardines de las Nubes.",
  ui_story_1013_10130101_12_dialog_content = "Aunque no sería fácil. ¡Esas mutaciones fallan nueve de cada diez veces!",
  ui_story_1013_10130101_13_dialog_content = "Plantar árboles requiere perseverancia.",
  ui_story_1013_10130101_14_option_content = "¿Pescar?",
  ui_story_1013_10130101_15_dialog_content = "Me encantaría llevar más peces ornamentales a la Fuente de los Deseos.",
  ui_story_1013_10130101_16_dialog_content = "Estoy cansado de pescar chatarra...",
  ui_story_1013_10130101_17_dialog_content = "¡Definitivamente tendrías éxito en eso!",
  ui_story_1013_10130101_18_dialog_content = "Eraveil es tan pacífico como lo es, todo gracias al Acorde de la Ley.",
  ui_story_1013_10130101_19_dialog_content = "No me di cuenta de lo poderoso que era.",
  ui_story_1013_10130101_20_dialog_content = "Si hubiera disparado a voluntad, sin los parámetros que el maestro Francis había establecido de antemano...",
  ui_story_1013_10130101_21_dialog_content = "Probablemente habría habido serias repercusiones.",
  ui_story_1013_10130101_22_dialog_content = "Todavía me estremezco cuando lo pienso ahora.",
  ui_story_1013_10130101_23_dialog_content = "La crisis ha pasado, así que no gastes energías preocupándote ahora.",
  ui_story_1013_10130101_24_dialog_content = "¡Vivir el momento!",
  ui_story_1013_10130101_25_dialog_content = "¡Estás bien! Bien dicho.",
  ui_story_1013_10130101_26_dialog_content = "De todos modos, Vice, ¿por qué sigues vestido así?",
  ui_story_1013_10130101_27_dialog_content = "¿Eh? ¿Te refieres a todo el negro?",
  ui_story_1013_10130101_28_dialog_content = "Bueno, estoy mucho más acostumbrada a usar mi atuendo habitual, pero a veces incluso me gusta darle un poco de sabor con algo diferente.",
  ui_story_1013_10130101_29_dialog_content = "¿Es raro? Si es así, ¿podría... cambiarme de nuevo a mi blanco habitual?",
  ui_story_1013_10130101_30_dialog_content = "¡No no! ¡No hay necesidad!",
  ui_story_1013_10130101_31_dialog_content = "No me preocupa lo que te pones, ¡siempre y cuando te guste!",
  ui_story_1013_10130101_32_dialog_content = "Por cierto, los peces ornamentales que acabas de pescar todavía están en el balde.",
  ui_story_1013_10130101_33_dialog_content = "¡Date prisa y ponlos en la Fuente de los Deseos!",
  ui_story_1013_10130101_34_dialog_content = "¡Así es! ¡Lo olvidé totalmente!",
  ui_story_1013_10130101_35_dialog_content = "Déjame ir a tirarlos a la Fuente.",
  ui_story_1013_10130101_36_dialog_content = "¡¿Eh?!",
  ui_story_1013_10130101_37_dialog_content = "Vice, ¿has estado practicando nueva Luminatics?",
  ui_story_1013_10130101_38_dialog_content = "¿Nueva Luminática? No yo...",
  ui_story_1013_10130101_39_dialog_content = "¡¿Qué demonios está pasando?!",
  ui_story_1013_10130101_40_dialog_content = "¡No usé Luminatics!",
  ui_story_1013_10130101_41_dialog_content = "¿Quién está jugando? Ven afuera. ¡Podemos verte!",
  ui_story_1013_10130101_42_dialog_content = "Um... No, parece que esta Lumina está saliendo de mí.",
  ui_story_1013_10130101_43_dialog_content = "Puedo sentir a Lumina desapareciendo lentamente de mí. ¿Que está pasando aqui?",
  ui_story_1013_10130101_44_dialog_content = "Podría ser...",
  ui_story_1013_10130101_45_dialog_content = "¿Un efecto secundario del uso de Chord Link?",
  ui_story_1013_10130101_46_dialog_content = "¿Estás bien, Vice? ¿Te sientes bien?",
  ui_story_1013_10130101_47_dialog_content = "Físicamente me siento totalmente bien...",
  ui_story_1013_10130101_48_dialog_content = "La velocidad de pérdida de Lumina es tan lenta que apenas puedo sentirla.",
  ui_story_1013_10130101_49_dialog_content = "Si esto es todo, entonces no es gran cosa.",
  ui_story_1013_10130101_50_dialog_content = "Pero no sabemos si tendrá otros síntomas.",
  ui_story_1013_10130101_51_dialog_content = "Sabemos tan poco sobre la tecnología antigua, pero aun así usamos ese dispositivo tan apresuradamente, yo...",
  ui_story_1013_10130101_52_dialog_content = "Relájate, PlayerName.",
  ui_story_1013_10130101_53_dialog_content = "¡También podríamos regresar a Gannon!",
  ui_story_1013_10130101_54_dialog_content = "Gannon tiene los mejores científicos e instalaciones médicas en Illumina. Estamos obligados a descubrir qué está causando todo esto.",
  ui_story_1013_10130101_55_dialog_content = "¡Oh, es cierto! Vamos ahora mismo. ¡Podemos usar la terminal de comunicación para contactar a Vivian en el camino, y ella nos ayudará con seguridad!",
  ui_story_1013_10130101_56_dialog_content = "Destino del piloto automático confirmado: Gannon City.",
  ui_story_1013_10130101_57_dialog_content = "Muy bien, ¡vamos a movernos!",
  ui_story_1013_10130101_58_dialog_content = "No te preocupes, PlayerName, Estoy bien.",
  ui_story_1013_10130101_59_dialog_content = "Solo estoy, ya sabes, brillando un poco.",
  ui_story_1013_10130101_60_dialog_content = "Pero solo saliste lastimado porque me estabas ayudando a encontrar una manera de reparar a Soroz.",
  ui_story_1013_10130101_61_dialog_content = "También fue mi decisión usar Chord Link para tratarte.",
  ui_story_1013_10130101_62_dialog_content = "Así que... tengo que asumir la responsabilidad de lo que sean estos síntomas ahora.",
  ui_story_1013_10130101_63_dialog_content = "¡Especialmente porque decidí por mi cuenta operar esos dispositivos antiguos sin siquiera saber para qué estaban hechos!",
  ui_story_1013_10130101_64_dialog_content = "PlayerName...",
  ui_story_1013_10130101_65_dialog_content = "Por favor, no te preocupes. Honestamente me siento bien.",
  ui_story_1013_10130101_66_dialog_content = "Pero, por supuesto, no podemos simplemente ignorar esto.",
  ui_story_1013_10130101_67_dialog_content = "Estás bien. Nuestra mejor apuesta es dirigirnos primero a Gannon para un examen completo.",
  ui_story_1013_10130101_68_dialog_content = "Póngase en contacto con la oficial Vivian mientras estamos en camino y pídale que organice los exámenes.",
  ui_story_1013_10130101_69_dialog_content = "Servirá.",
  ui_story_1013_10130101_70_dialog_content = "¿viviana? ¿Puedes escucharme?",
  ui_story_1013_10130101_71_dialog_content = "PlayerName? Si puedo oirte. Avanzar.",
  ui_story_1013_10130101_72_dialog_content = "¡Hay una situación un poco urgente con Vice, y necesito ayuda!",
  ui_story_1013_10130101_73_dialog_content = "¿Una situación urgente? No me digas que Vice también tendrá uno de esos episodios.",
  ui_story_1013_10130101_74_dialog_content = "\"También\"?",
  ui_story_1013_10130101_75_dialog_content = "¿Barton también ha comenzado a brillar al azar?",
  ui_story_1013_10130101_76_dialog_content = "Sí, el comandante Barton fue puesto de baja para que pudiera descansar justo después de la batalla en Eraveil.",
  ui_story_1013_10130101_77_dialog_content = "De alguna manera esta mañana, su cuerpo comenzó a emitir Lumina sin motivo alguno.",
  ui_story_1013_10130101_78_dialog_content = "Supongo que Vice está experimentando lo mismo.",
  ui_story_1013_10130101_79_dialog_content = "Así es. Vamos camino a Gannon mientras hablamos. ¿Sería capaz de organizar un examen para cuando lleguemos allí?",
  ui_story_1013_10130101_80_dialog_content = "Déjamelo a mí.",
  ui_story_1013_10130101_81_dialog_content = "Illumina ya planeó realizar un examen exhaustivo del Comandante Barton y Vice debido al hecho de que usaron Chord Link.",
  ui_story_1013_10130101_82_dialog_content = "¿De veras? ¡Estupendo!",
  ui_story_1013_10130101_83_dialog_content = "Vaya al centro médico tan pronto como llegue a la ciudad de Gannon. Te espero allí.",
  ui_story_1013_10130101_84_dialog_content = "Entiendo. ¡Gracias!",
  ui_story_1013_10130101_85_dialog_content = "<color=#e8d9bb>Centro médico de la ciudad de Gannon</color>",
  ui_story_1013_10130101_86_dialog_content = "Aquí está el centro médico.",
  ui_story_1013_10130101_87_dialog_content = "La última vez que estuve aquí fue para el examen físico obligatorio cuando me alisté.",
  ui_story_1013_10130101_88_dialog_content = "Es mi primera vez. ¡No tenía idea de que el centro médico Illumina sería tan grande!",
  ui_story_1013_10130101_89_dialog_content = "¡Claro!",
  ui_story_1013_10130101_90_dialog_content = "Nadie puede predecir el número de bajas que puede resultar en una batalla.",
  ui_story_1013_10130101_91_dialog_content = "Cuanto más grande sea el centro, más soldados heridos podremos tratar con urgencia.",
  ui_story_1013_10130101_92_dialog_content = "Un tratamiento rápido aumenta sus probabilidades de sobrevivir...",
  ui_story_1013_10130101_93_dialog_content = "Muy cierto...",
  ui_story_1013_10130101_94_dialog_content = "Oye, vicio, PlayerName!",
  ui_story_1013_10130101_95_dialog_content = "Ya estás aquí.",
  ui_story_1013_10130101_96_dialog_content = "¡Comandante Barton! ¡Oficial Viviana!",
  ui_story_1013_10130101_97_dialog_content = "Parece que Barton sufre del mismo fenómeno...",
  ui_story_1013_10130101_98_dialog_content = "¿Eh? Oh, ¿te refieres al brillo?",
  ui_story_1013_10130101_99_dialog_content = "No me molesta si solo brilla. De todos modos, no es como si usara una gran cantidad de Lumina.",
  ui_story_1013_10130101_100_dialog_content = "¡Claro, pero no puedes simplemente ignorar el riesgo potencial!",
  ui_story_1013_10130101_101_dialog_content = "Sí, bueno, espero que esos tipos inteligentes con batas blancas encuentren una manera de detener el brillo pronto.",
  ui_story_1013_10130101_102_dialog_content = "De lo contrario, seré un blanco brillante y resplandeciente por la noche. ¡Y no podré emboscar a los enemigos!",
  ui_story_1013_10130101_103_dialog_content = "E-Ciertamente.",
  ui_story_1013_10130101_104_dialog_content = "¿Qué pasa, chico? Tienes preocupación escrita en toda tu cara.",
  ui_story_1013_10130101_105_dialog_content = "¿Vaya? Bueno... No voy a mentir, estoy un poco preocupado.",
  ui_story_1013_10130101_106_dialog_content = "no seas Esta es la mejor organización médica de Illumina. ¡Pueden traerte de vuelta antes de que sepas que estás muerto!",
  ui_story_1013_10130101_107_dialog_content = "Este tipo de situación brillante indolora e inofensiva es un paseo por el parque.",
  ui_story_1013_10130101_108_dialog_content = "¡Correcto!",
  ui_story_1013_10130101_109_dialog_content = "Bien, permítanme acompañar al Comandante Barton y Vice a sus exámenes.",
  ui_story_1013_10130101_110_dialog_content = "Si pudiera esperar afuera, por favor. PlayerName.",
  ui_story_1013_10130101_111_dialog_content = "Por supuesto.",
  ui_story_1013_10130101_112_dialog_content = "¡Nos vemos!",
  ui_story_1013_10130101_113_dialog_content = "Más tarde, chico.",
  ui_story_1013_10130101_114_dialog_content = "Y el silencio cae sobre el corredor una vez más.",
  ui_story_1013_10130101_115_dialog_content = "Esperemos que esta situación sea solo una casualidad.",
  ui_story_1013_10130101_116_dialog_content = "En cuanto a ti, eres el único responsable de—",
  ui_story_1013_10130101_117_dialog_content = "Creando guerras para el mundo.",
  ui_story_1013_10130101_118_dialog_content = "...",
  ui_story_1013_10130101_119_dialog_content = "No, nunca haré eso.",
  ui_story_1013_10130101_120_dialog_content = "Pero, ¿estoy tomando las decisiones correctas?",
  ui_story_1013_10130101_121_dialog_content = "Se ve igual que la última vez, pero no bajes la guardia.",
  ui_story_1013_10130101_122_dialog_content = "No hay lugar para la negligencia o los accidentes en su condición.",
  ui_story_1013_10130101_123_dialog_content = "*Tose*... Lo sé, lo sé.",
  ui_story_1013_10130101_124_dialog_content = "Soy plenamente consciente de mi condición. Siempre lo ha sido.",
  ui_story_1013_10130101_125_dialog_content = "Podrías venir a entrenar con nosotros.",
  ui_story_1013_10130101_126_dialog_content = "¡Confía en mí! ¡El entrenamiento me hizo más fuerte, transformándome de un pequeño brote débil que no podía hacer nada!",
  ui_story_1013_10130101_127_dialog_content = "Jajaja. Mi condición no es algo que el entrenamiento pueda arreglar.",
  ui_story_1013_10130101_128_dialog_content = "(¿Estos tipos también están aquí para un examen?)",
  ui_story_1013_10130101_129_dialog_content = "¡Eh, tú! ¿Qué estás mirando?",
  ui_story_1013_10130101_130_dialog_content = "¡¿Eh?! ¡Oh lo siento!",
  ui_story_1013_10130101_131_dialog_content = "Acabo de ver a unos extraños, y...",
  ui_story_1013_10130101_132_dialog_content = "Espera, tú...",
  ui_story_1013_10130101_133_dialog_content = "No eres el Caelestite legendario, ¿verdad?",
  ui_story_1013_10130101_134_dialog_content = "¿Qué?",
  ui_story_1013_10130101_135_dialog_content = "¿Eh? La Caelestita, ¿en serio?",
  ui_story_1013_10130101_136_dialog_content = "¿Me conoces? No creo que nos hayamos conocido antes.",
  ui_story_1013_10130101_137_dialog_content = "¡Por supuesto! Eres famoso de donde somos por muchas cosas.",
  ui_story_1013_10130101_138_dialog_content = "Navegando por el Coloso, luchando contra los Eclipsites junto a los Aurorianos en la Línea Dunefire.",
  ui_story_1013_10130101_139_dialog_content = "¡Y repeliendo a los Eclipsites en Eraveil, aliados con Illumina, Lumopolis y Northland!",
  ui_story_1013_10130101_140_dialog_content = "Todos somos grandes admiradores tuyos y de tus obras.",
  ui_story_1013_10130101_141_option_content = "Solo hice lo que pude.",
  ui_story_1013_10130101_142_dialog_content = "Después de todo, los Eclipsites son enemigos de todos.",
  ui_story_1013_10130101_143_option_content = "Fue un esfuerzo conjunto.",
  ui_story_1013_10130101_144_dialog_content = "No hay forma de que hubiera podido hacer todo eso sin la ayuda de todos.",
  ui_story_1013_10130101_145_dialog_content = "¡Y eres tan humilde como dicen!",
  ui_story_1013_10130101_146_dialog_content = "Permítame presentarme. Mi nombre es Zhao y sirvo como Jefe de Estado Mayor en la ciudad de Crepúsculo, al oeste.",
  ui_story_1013_10130101_147_dialog_content = "Este es mi asistente Crow y mi colega Sean.",
  ui_story_1013_10130101_148_dialog_content = "¡Nunca hubiera pensado que te encontraría aquí! Debe ser mi día de suerte.",
  ui_story_1013_10130101_149_dialog_content = "Encantado de conocerlos a todos. estoy PlayerName.",
  ui_story_1013_10130101_150_dialog_content = "Hola, PlayerName.",
  ui_story_1013_10130101_151_dialog_content = "Hola.",
  ui_story_1013_10130101_152_dialog_content = "Lo siento si fui un poco brusco en este momento. Mi trabajo es cuidar de Zhao.",
  ui_story_1013_10130101_153_dialog_content = "Está bien. Realmente no fue educado de mi parte mirar fijamente, de todos modos.",
  ui_story_1013_10130101_154_dialog_content = "¡El jefe Zhao siempre nos cuenta historias sobre ti!",
  ui_story_1013_10130101_155_dialog_content = "¡Estoy tan celosa! Me encantaría volar un Colossus por todos lados.",
  ui_story_1013_10130101_156_dialog_content = "Probablemente sea muy conveniente viajar muy lejos con un Colossus, ¿verdad?",
  ui_story_1013_10130101_157_dialog_content = "¡Con seguridad! No importa a dónde vaya, mi Colossus puede llevarme allí en un abrir y cerrar de ojos.",
  ui_story_1013_10130101_158_dialog_content = "¡Impresionante! Me gustaría tener uno también.",
  ui_story_1013_10130101_159_dialog_content = "¡De esa manera, podemos volver a Crepúsculo antes!",
  ui_story_1013_10130101_160_dialog_content = "¿Hay alguna razón urgente por la que necesites regresar?",
  ui_story_1013_10130101_161_dialog_content = "¡Sí!",
  ui_story_1013_10130101_162_dialog_content = "¿No sabes lo que está pasando en Crepúsculo?",
  ui_story_1013_10130101_163_dialog_content = "Realmente no. ¿Dónde está ese pueblo tuyo?",
  ui_story_1013_10130101_164_dialog_content = "Twilight está justo fuera de la jurisdicción de Illumina. Está bastante lejos de Gannon.",
  ui_story_1013_10130101_165_dialog_content = "Si bien las perturbaciones de Eclipsite son más comunes allí que los asentamientos dentro de la frontera, sigue siendo un lugar bastante agradable para vivir.",
  ui_story_1013_10130101_166_dialog_content = "¡Quiero volver rápido y ayudar a mis amigos a encargarse de esos bichos de Eclipsite!",
  ui_story_1013_10130101_167_dialog_content = "Honestamente, era claramente solo un rasguño, pero los médicos insistieron en enviarme hasta Gannon para recibir tratamiento.",
  ui_story_1013_10130101_168_dialog_content = "Aunque supongo que está bien. ¡Ya hemos terminado y podemos regresar a Crepúsculo esta tarde!",
  ui_story_1013_10130101_169_dialog_content = "Es mejor estar seguro que lamentar.",
  ui_story_1013_10130101_170_dialog_content = "Tienes que cuidarte a ti mismo, o no tendrás la fuerza para enfrentarte a más enemigos.",
  ui_story_1013_10130101_171_dialog_content = "No seas como cierta persona, y siempre esfuérzate demasiado.",
  ui_story_1013_10130101_172_dialog_content = "*Tos*... De todos modos, PlayerName, deberíamos irnos.",
  ui_story_1013_10130101_173_dialog_content = "Si alguna vez tienes la oportunidad de visitarnos, te recibiremos con los brazos abiertos.",
  ui_story_1013_10130101_174_dialog_content = "Me encantaría tener la oportunidad de luchar junto a Caelestite.",
  ui_story_1013_10130101_175_dialog_content = "Si surge la oportunidad, la tomaré con seguridad.",
  ui_story_1013_10130101_176_dialog_content = "Nos vemos por ahí si el destino lo tiene.",
  ui_story_1013_10130101_177_dialog_content = "Adiós.",
  ui_story_1013_10130101_178_dialog_content = "¡Adiós!",
  ui_story_1013_10130101_179_dialog_content = "¿Crepúsculo? Suena como un lugar bastante remoto.",
  ui_story_1013_10130101_180_dialog_content = "¿Eh? Esa persona que sale de la sala de consulta de allí, ¿es eso...?",
  ui_story_1013_10130101_181_dialog_content = "¿Reinhardt?",
  ui_story_1013_10130101_182_dialog_content = "¿Eh? PlayerName?",
  ui_story_1013_10130101_183_dialog_content = "Vivian mencionó que traerías Vice a Gannon. Sin embargo, no pensé que me encontraría contigo.",
  ui_story_1013_10130101_184_dialog_content = "Estoy gratamente sorprendido también.",
  ui_story_1013_10130101_185_dialog_content = "¿Que te trae por aqui?",
  ui_story_1013_10130101_186_dialog_content = "¿También te pasó algo extraño después de usar los sistemas médicos de Soroz?",
  ui_story_1013_10130101_187_dialog_content = "Oh, no. Nada parecido a lo que están tratando Barton y Vice.",
  ui_story_1013_10130101_188_dialog_content = "Solo estoy aquí para un examen físico de rutina.",
  ui_story_1013_10130101_189_dialog_content = "Tengo que tener uno cada seis meses. Es solo estado físico y análisis de sangre, realmente, cosas estándar.",
  ui_story_1013_10130101_190_dialog_content = "Mis resultados son tan estables como siempre, así que no hay necesidad de preocuparse.",
  ui_story_1013_10130101_191_dialog_content = "Genial, eso es un alivio. Oh, sí, ¿cómo está esa herida que te hiciste la última vez?",
  ui_story_1013_10130101_192_dialog_content = "¡Jajaja! Relax. Gracias a su equipo médico de primer nivel, hace mucho que se curó.",
  ui_story_1013_10130101_193_dialog_content = "Si Illumina tuviera ese tipo de equipo...",
  ui_story_1013_10130101_194_dialog_content = "¡Hola chico, estamos de vuelta!",
  ui_story_1013_10130101_195_dialog_content = "Gran Mariscal Reinhardt? ¿También estás aquí?",
  ui_story_1013_10130101_196_dialog_content = "Oye PlayerName... y el Gran Mariscal?!",
  ui_story_1013_10130101_197_dialog_content = "¿Han terminado de examinarlos a ustedes dos? ¿Cómo fueron los resultados?",
  ui_story_1013_10130101_198_dialog_content = "como pongo esto...",
  ui_story_1013_10130101_199_dialog_content = "El informe decía que el resultado fue: ¡nada!",
  ui_story_1013_10130101_200_dialog_content = "¡¿Eh?!",
  ui_story_1013_10130101_201_dialog_content = "Esos médicos y científicos nos pincharon y pincharon con todo tipo de instrumentos durante lo que pareció una eternidad, pero al final del día no pudieron llegar a una conclusión.",
  ui_story_1013_10130101_202_dialog_content = "Todas las pruebas habituales realizadas durante un examen físico de rutina resultaron normales.",
  ui_story_1013_10130101_203_dialog_content = "Entonces, no hay ningún problema, al menos según los resultados de las pruebas.",
  ui_story_1013_10130101_204_dialog_content = "Pero parece que ya no hay Lumina saliendo de ustedes. ¿Cómo te curaste?",
  ui_story_1013_10130101_205_dialog_content = "¡Ay, sobre eso!",
  ui_story_1013_10130101_206_dialog_content = "Una de las pruebas involucró el uso de Luminatics para atacar a los maniquíes de entrenamiento.",
  ui_story_1013_10130101_207_dialog_content = "Creo que los científicos probablemente querían ver si este tipo de dispersión de Lumina afectaría o no nuestra capacidad de usar Luminatics.",
  ui_story_1013_10130101_208_dialog_content = "De todos modos, después de golpear felizmente a los maniquíes por un tiempo, el resplandor se detuvo por sí solo.",
  ui_story_1013_10130101_209_dialog_content = "Si hubiera sabido que esa era la forma de detener el brillo, ¡habría ido a buscar algunos eclipses!",
  ui_story_1013_10130101_210_dialog_content = "Escuché a algunos científicos decir que el Comandante Barton destruyó por completo unos buenos diez maniquíes de entrenamiento.",
  ui_story_1013_10130101_211_dialog_content = "¿Es eso así? Pues bien, el costo de repararlos se descontará de la asignación mensual del Comandante de la 2ª Legión.",
  ui_story_1013_10130101_212_dialog_content = "¡¿Esperar lo?!",
  ui_story_1013_10130101_213_dialog_content = "Jajaja, estoy bromeando.",
  ui_story_1013_10130101_214_dialog_content = "Lo principal es que ambos estáis bien. Sin embargo, no bajes la guardia solo porque estás bien en este momento.",
  ui_story_1013_10130101_215_dialog_content = "Asegúrese de hacerse chequeos regulares, al menos por un tiempo breve, para asegurarse de que todo está bien.",
  ui_story_1013_10130101_216_dialog_content = "¡Sí, señora!",
  ui_story_1013_10130101_217_dialog_content = "¡Sí, señora!",
  ui_story_1013_10130101_218_dialog_content = "Con todo, mi salud es normal en todos los ámbitos.",
  ui_story_1013_10130101_219_dialog_content = "No tienes que preocuparte demasiado.",
  ui_story_1013_10130101_220_dialog_content = "Supongo que por ahora, el brillo no es un gran problema.",
  ui_story_1013_10130101_221_dialog_content = "Pero todavía me preocupa si el uso de Chord Link podría causar otros síntomas.",
  ui_story_1013_10130101_222_dialog_content = "No sabemos nada, que es lo que hace que esto sea aterrador.",
  ui_story_1013_10130101_223_dialog_content = "Eso es algo de lo que dijeron los médicos también.",
  ui_story_1013_10130101_224_dialog_content = "Así que me aconsejaron que me mantuviera activo y prestara especial atención a cualquier cambio en mi condición física.",
  ui_story_1013_10130101_225_dialog_content = "¡De acuerdo! ¡También te ayudaré a vigilarte!",
  ui_story_1013_10130101_226_dialog_content = "Hablando de eso, tengo una propuesta para ti.",
  ui_story_1013_10130101_227_dialog_content = "Bueno, para ser precisos, es más una petición.",
  ui_story_1013_10130101_228_dialog_content = "PlayerName, Esperaba que estuviera dispuesto a conceder a Illumina acceso de investigación a Soroz y al Obelisco del Retorno.",
  ui_story_1013_10130101_229_dialog_content = "¡¿Eh?!",
  ui_story_1013_10130101_230_dialog_content = "¿Puedo preguntar por qué?",
  ui_story_1013_10130101_231_dialog_content = "Por supuesto.",
  ui_story_1013_10130101_232_dialog_content = "Después de todo, toda la comunidad científica de Illumina y yo hemos desarrollado una profunda apreciación del poder de la tecnología Caelestite.",
  ui_story_1013_10130101_233_dialog_content = "Particularmente con respecto al Chord Link y la tecnología médica, si pudiéramos usarlos en la batalla, podríamos salvar las vidas de tantos Aurorianos.",
  ui_story_1013_10130101_234_dialog_content = "Además, la Sala de Simulación en el Coloso también tiene un potencial fenomenal.",
  ui_story_1013_10130101_235_dialog_content = "Si pudiéramos usarlo para entrenar comandantes, definitivamente podríamos reducir el número de bajas.",
  ui_story_1013_10130101_236_dialog_content = "Pero...",
  ui_story_1013_10130101_237_dialog_content = "(Si la tecnología Caelestite se hizo para incitar a la guerra, ¿está bien entregarla así?)",
  ui_story_1013_10130101_238_dialog_content = "Sé lo que probablemente te preocupe.",
  ui_story_1013_10130101_239_dialog_content = "Por lo tanto, te prometo esto:",
  ui_story_1013_10130101_240_dialog_content = "Illumina nunca utilizará esta tecnología para ningún propósito adverso.",
  ui_story_1013_10130101_241_dialog_content = "Y, por supuesto, le ofreceremos una compensación.",
  ui_story_1013_10130101_242_dialog_content = "A cambio, Illumina enviará a nuestros mejores y más brillantes científicos para ayudarlo a reparar Soroz.",
  ui_story_1013_10130101_243_dialog_content = "...",
  ui_story_1013_10130101_244_dialog_content = "¿Qué opinas, Vice?",
  ui_story_1013_10130101_245_dialog_content = "¿Que pienso?",
  ui_story_1013_10130101_246_dialog_content = "Bueno, quiero que Illumina tenga la mejor tecnología médica.",
  ui_story_1013_10130101_247_dialog_content = "Pero Eraveil es tuyo. La decision es tuya.",
  ui_story_1013_10130101_248_dialog_content = "Entonces, en qué piensas, PlayerName?",
  ui_story_1013_10130101_249_dialog_content = "Oiga, espere un minuto, Gran Mariscal.",
  ui_story_1013_10130101_250_dialog_content = "¿No es un poco precipitado esperar una respuesta ahora mismo?",
  ui_story_1013_10130101_251_dialog_content = "Esta no es una pequeña decisión que puedes tomar por capricho.",
  ui_story_1013_10130101_252_dialog_content = "Dale al niño algo de tiempo para pensarlo. Obtendrás tu respuesta.",
  ui_story_1013_10130101_253_dialog_content = "...",
  ui_story_1013_10130101_254_dialog_content = "Lo siento, fui un poco apresurado.",
  ui_story_1013_10130101_255_dialog_content = "Si necesita tiempo para considerar, por favor, por todos los medios. Puedo esperar.",
  ui_story_1013_10130101_256_dialog_content = "Yo...",
  ui_story_1013_10130101_257_dialog_content = "Está bien.",
  ui_story_1013_10130101_258_option_content = "lo permitiré",
  ui_story_1013_10130101_259_dialog_content = "Excelente. Gracias, PlayerName.",
  ui_story_1013_10130101_260_option_content = "Confío en ti.",
  ui_story_1013_10130101_261_dialog_content = "¡...!",
  ui_story_1013_10130101_262_dialog_content = "Gracias, PlayerName.",
  ui_story_1013_10130101_263_dialog_content = "Bueno, no hay tiempo que perder. Me pondré en contacto con el equipo científico del centro de investigación y les diré que se preparen.",
  ui_story_1013_10130101_264_dialog_content = "Usted y Vice también deberían venir, ya que es posible que necesitemos su ayuda. Disculpas de antemano por la molestia.",
  ui_story_1013_10130101_265_dialog_content = "Está bien. Si me ayudan a reparar Soroz, todos ganan.",
  ui_story_1013_10130101_266_dialog_content = "Si es por Illumina, entonces eso hace que sea mi responsabilidad. Yo nunca me negaría.",
  ui_story_1013_10130101_267_dialog_content = "Parece que no tengo motivos para quedarme aquí más tiempo.",
  ui_story_1013_10130101_268_dialog_content = "En ese caso, volveré a la 2.ª Legión.",
  ui_story_1013_10130101_269_dialog_content = "Pasa por un juego de ajedrez si alguna vez tienes un minuto, chico.",
  ui_story_1013_10130101_270_dialog_content = "¡Por supuesto! Me gustaría eso.",
  ui_story_1013_10130201_1_dialog_content = "Esta es el área administrativa del Illumina Research Center.",
  ui_story_1013_10130201_2_dialog_content = "Esta es probablemente tu primera vez aquí.",
  ui_story_1013_10130201_3_dialog_content = "¡S-Sí!",
  ui_story_1013_10130201_4_dialog_content = "Siempre he oído que este lugar tiene los mejores científicos de toda la Federación Illumina.",
  ui_story_1013_10130201_5_dialog_content = "¡Nunca esperé verlo con mis propios ojos!",
  ui_story_1013_10130201_6_dialog_content = "¡Vaya, está ocupado!",
  ui_story_1013_10130201_7_dialog_content = "Por supuesto. Todos aquí trabajan duro en nombre de Illumina, todos los días.",
  ui_story_1013_10130201_8_dialog_content = "El éxito de Illumina se debe en gran medida a sus esfuerzos.",
  ui_story_1013_10130201_9_dialog_content = "¡Yo! Gran Mariscal! ¡Y Vicio! ¡Y el perdedor!",
  ui_story_1013_10130201_10_option_content = "¡¿Gronru?!",
  ui_story_1013_10130201_11_dialog_content = "¿Qué estás haciendo acá?",
  ui_story_1013_10130201_12_dialog_content = "El Gran Mariscal nos pidió a Migard ya mí que ayudáramos con algunos experimentos. Dijo que sería libre de estudiar las nuevas funciones de Soroz.",
  ui_story_1013_10130201_13_dialog_content = "¡Lo cual sonaba mucho más divertido que ganar otro juego en la dificultad más alta! Acepté en un santiamén.",
  ui_story_1013_10130201_14_dialog_content = "Por favor, sé amable con Soroz...",
  ui_story_1013_10130201_15_dialog_content = "¡Ay, relájate! ¡Trataré a Soroz con las manos más cuidadosas del mundo!",
  ui_story_1013_10130201_16_dialog_content = "Ha pasado un tiempo, joven.",
  ui_story_1013_10130201_17_dialog_content = "Señorita... Migard...",
  ui_story_1013_10130201_18_dialog_content = "(Aunque sé que es inofensiva, no puedo evitar ponerme nervioso cada vez que la veo...)",
  ui_story_1013_10130201_19_dialog_content = "¿Mmm? ¿Qué pasa con tu expresión?",
  ui_story_1013_10130201_20_dialog_content = "Pareces preocupado desde que llegaste a Illumina hoy.",
  ui_story_1013_10130201_21_dialog_content = "Porque algo estaba pasando con Vice...",
  ui_story_1013_10130201_22_dialog_content = "Espera, ¿nos viste? ¿Cómo es que no te vi? ¡¿Espero no haberte ignorado?!",
  ui_story_1013_10130201_23_dialog_content = "Jajaja, olvidas que mis Diving Spines vigilan todos los rincones de Illumina.",
  ui_story_1013_10130201_24_dialog_content = "Incluso si no estoy allí en persona, puedo verte a través de ellos.",
  ui_story_1013_10130201_25_dialog_content = "Err... ya veo...",
  ui_story_1013_10130201_26_dialog_content = "Muy bien, ¡vamos! ¡El centro de investigación te espera!",
  ui_story_1013_10130201_27_dialog_content = "Salgamos a la carretera, PlayerName!",
  ui_story_1013_10130201_28_dialog_content = "¡Todo el mundo! ¡El Navegante está aquí!",
  ui_story_1013_10130201_29_dialog_content = "Espera, ¿es este EL Navegante? ¡Oh, he sido fan durante tanto tiempo!",
  ui_story_1013_10130201_30_dialog_content = "Hmm, es un poco joven, pero como sujeto de prueba... será suficiente.",
  ui_story_1013_10130201_31_dialog_content = "¡¿Sujeto de prueba?!",
  ui_story_1013_10130201_32_dialog_content = "PlayerName es mi compañero, no un sujeto de prueba!",
  ui_story_1013_10130201_33_dialog_content = "Jaja, no les hagas caso. Casi todos los investigadores aquí tienen algo un poco extraño en ellos.",
  ui_story_1013_10130201_34_dialog_content = "Pero no te preocupes, son totalmente inofensivos.",
  ui_story_1013_10130201_35_dialog_content = "Gran Mariscal, todo aquí ha sido preparado según las instrucciones. Estamos listos para comenzar nuestra investigación.",
  ui_story_1013_10130201_36_dialog_content = "Bien. Pero una última cosa.",
  ui_story_1013_10130201_37_dialog_content = "¿Hay más?",
  ui_story_1013_10130201_38_dialog_content = "Sí. Necesito expresarte mi gratitud.",
  ui_story_1013_10130201_39_dialog_content = "¿Hmm?",
  ui_story_1013_10130201_40_dialog_content = "¿No acabas de darme las gracias?",
  ui_story_1013_10130201_41_dialog_content = "Eso fue a título personal. Pero esta vez, es como el Gran Mariscal de la Federación Illumina.",
  ui_story_1013_10130201_42_dialog_content = "Permitir que Illumina lleve a cabo esta investigación sin duda salvará la vida de innumerables aurorianos.",
  ui_story_1013_10130201_43_dialog_content = "Gracias, PlayerName!",
  ui_story_1013_10130201_44_dialog_content = "También tienes mi agradecimiento, joven, a pesar del aumento de la carga de trabajo.",
  ui_story_1013_10130201_45_dialog_content = "¡Gracias!",
  ui_story_1013_10130201_46_dialog_content = "Gracias por tu contribución, sujeto de prueba.",
  ui_story_1013_10130201_47_dialog_content = "¡¿Pero aún no he hecho nada?!",
  ui_story_1013_10130201_48_dialog_content = "Solo acepta su agradecimiento.",
  ui_story_1013_10130201_49_dialog_content = "Después de todo, su acuerdo era necesario para que todo esto sucediera.",
  ui_story_1013_10130201_50_dialog_content = "Mmm...",
  ui_story_1013_10130201_51_dialog_content = "Oigan, ¿podrían dejar de mirarme así? Es un poco incómodo...",
  ui_story_1013_10130201_52_dialog_content = "¿No tienen que investigar o algo así?",
  ui_story_1013_10130201_53_dialog_content = "Jaja, tienes toda la razón.",
  ui_story_1013_10130201_54_dialog_content = "Ustedes, pónganse a trabajar. Cumplir con nuestra agenda.",
  ui_story_1013_10130201_55_dialog_content = "Sí, señora.",
  ui_story_1013_10130201_56_dialog_content = "Todos, divididos en tres grupos como discutió el Gran Mariscal.",
  ui_story_1013_10130201_57_dialog_content = "Grupo A, dirígete al Obelisco del Retorno y busca información sobre el Enlace de Cuerda.",
  ui_story_1013_10130201_58_dialog_content = "Grupo B, conmigo. Estamos recopilando datos sobre el equipo médico de Soroz.",
  ui_story_1013_10130201_59_dialog_content = "El resto de ustedes, Grupo C, esperen mi orden, luego conecten el cable de transmisión de datos a la Sala de Simulación de Soroz.",
  ui_story_1013_10130201_60_dialog_content = "Vea si podemos usar Illumina Battle Simulator para analizar los datos de la sala de simulación.",
  ui_story_1013_10130201_61_dialog_content = "¡Sí, señora!",
  ui_story_1013_10130201_62_dialog_content = "Illumina tiene un simulador de batalla?",
  ui_story_1013_10130201_63_dialog_content = "Sí. La última vez, cuando Gronru ayudó a Soroz a instalar la Sala de simulación, obtuvimos una gran cantidad de datos de investigación.",
  ui_story_1013_10130201_64_dialog_content = "Después de regresar a Illumina, hizo una máquina similar modelada a partir de la de Soroz.",
  ui_story_1013_10130201_65_dialog_content = "Aunque al principio, todo lo que quería hacer era construir una máquina de juegos...",
  ui_story_1013_10130201_66_dialog_content = "Sin embargo, al final del día, ¡resultó ser algo increíble!",
  ui_story_1013_10130201_67_dialog_content = "Eso es aterrador impresionante...",
  ui_story_1013_10130201_68_dialog_content = "¡Sí! Si está interesado, le invitamos a probarlo usted mismo durante el experimento un poco más tarde.",
  ui_story_1013_10130201_69_dialog_content = "¡Eso suena genial!",
  ui_story_1013_10130201_70_dialog_content = "¡Debería practicar de antemano y hacer que piense diferente de mí!",
  ui_story_1013_10130201_71_dialog_content = "<color=#e8d9bb>Varias horas después</color>",
  ui_story_1013_10130201_72_dialog_content = "Informando, Gran Mariscal.",
  ui_story_1013_10130201_73_dialog_content = "¿Algún descubrimiento?",
  ui_story_1013_10130201_74_dialog_content = "Buenas noticias, señora. Hemos logrado extraer información sobre el método de fabricación de equipos médicos de Soroz del nuevo módulo.",
  ui_story_1013_10130201_75_dialog_content = "Esta información nos permitirá actualizar todo nuestro equipo actual en el centro.",
  ui_story_1013_10130201_76_dialog_content = "¡Excelente trabajo!",
  ui_story_1013_10130201_77_dialog_content = "Manténgase al día con la investigación y vea si puede hacer otros descubrimientos nuevos.",
  ui_story_1013_10130201_78_dialog_content = "Sí, señora.",
  ui_story_1013_10130201_79_dialog_content = "Equipo medico…",
  ui_story_1013_10130201_80_dialog_content = "Ese tipo, Zhao, no parecía muy bien, físicamente.",
  ui_story_1013_10130201_81_dialog_content = "Si se está mejorando el equipo médico, ¿quizás podría recibir ayuda?",
  ui_story_1013_10130201_82_dialog_content = "¿Vaya? ¿Conoces a Zhao?",
  ui_story_1013_10130201_83_dialog_content = "Especie de. Lo conocí por casualidad en el centro médico, y hablamos un poco.",
  ui_story_1013_10130201_84_dialog_content = "Comprendo.",
  ui_story_1013_10130201_85_dialog_content = "Zhao es el Jefe de Estado Mayor de Illumina Garrison en Crepúsculo. Tiene una mente excepcional, pero un cuerpo frágil.",
  ui_story_1013_10130201_86_dialog_content = "Fue gravemente herido cuando era joven. Darkflow corroyó sus órganos, dejándolo incapaz de luchar.",
  ui_story_1013_10130201_87_dialog_content = "No es de extrañar que emitiera el aire de alguien con una enfermedad crónica.",
  ui_story_1013_10130201_88_dialog_content = "No solo eso, sino que su subordinado Sean también está plagado de problemas físicos.",
  ui_story_1013_10130201_89_dialog_content = "Sean? ¡Pero parecía que podía correr un maratón sin sudar!",
  ui_story_1013_10130201_90_dialog_content = "Eso es porque se somete a un entrenamiento constante y agotador.",
  ui_story_1013_10130201_91_dialog_content = "Tiene un defecto genético bastante complejo.",
  ui_story_1013_10130201_92_dialog_content = "Esto también lo llevó a ser pasado por alto cuando se unió al ejército por primera vez. Fue enviado a estaciones remotas como soldado de a pie.",
  ui_story_1013_10130201_93_dialog_content = "La increíble voluntad y determinación de ese niño son de agradecer por todo lo que ha logrado.",
  ui_story_1013_10130201_94_dialog_content = "Sí, podía sentir algo en él que claramente se había perfeccionado a través de años de dificultades.",
  ui_story_1013_10130201_95_dialog_content = "Así es. Y es por eso que, cuando nuestras actualizaciones estén completas, él y aquellos como él serán los primeros beneficiarios.",
  ui_story_1013_10130201_96_dialog_content = "Gran mariscal, ya hemos avanzado en nuestra investigación sobre Chord Link.",
  ui_story_1013_10130201_97_dialog_content = "¡¿Tan rapido?!",
  ui_story_1013_10130201_98_dialog_content = "No subestimes los conocimientos tecnológicos de Illumina, sujeto de prueba.",
  ui_story_1013_10130201_99_dialog_content = "Pero de todos modos, gran mariscal, pensamos que deberíamos informarle, pero...",
  ui_story_1013_10130201_100_dialog_content = "(¿Acaba de echarme un vistazo?)",
  ui_story_1013_10130201_101_dialog_content = "PlayerName es el maestro de Eraveil, y el Chord Link.",
  ui_story_1013_10130201_102_dialog_content = "No hay nada sobre esta investigación que no se pueda decir frente a él.",
  ui_story_1013_10130201_103_dialog_content = "Muy bien. En ese caso, lo explicaré lo suficientemente simple como para que incluso el sujeto de prueba pueda seguirlo.",
  ui_story_1013_10130201_104_dialog_content = "Con base en los resultados de los exámenes físicos realizados al Comandante Barton y al Teniente Vice, ya podemos hacer una hipótesis tentativa para qué probablemente se usó el dispositivo.",
  ui_story_1013_10130201_105_dialog_content = "Sospechamos que además de poder modificar los cuerpos aurorianos, Chord Link también puede liberar su potencial latente.",
  ui_story_1013_10130201_106_option_content = "¿Modificar cuerpos?",
  ui_story_1013_10130201_107_dialog_content = "¿No te has dado cuenta? Las apariencias tanto del Comandante Barton como del Teniente Vice han cambiado, en mayor o menor medida.",
  ui_story_1013_10130201_108_dialog_content = "Lo sé, pero además de su apariencia, ¿podría esta modificación afectar el cuerpo de otras maneras?",
  ui_story_1013_10130201_109_dialog_content = "Tendríamos que investigar más antes de llegar a ninguna conclusión.",
  ui_story_1013_10130201_110_dialog_content = "Pero una cosa que podemos concluir es que este cambio ha impactado la Luminática que usan.",
  ui_story_1013_10130201_111_option_content = "potencial latente?",
  ui_story_1013_10130201_112_dialog_content = "Sí. Creemos que las modificaciones de Chord Link también han afectado la forma en que usan Luminatics.",
  ui_story_1013_10130201_113_dialog_content = "Permitiéndoles desatar un poder que antes habría sido imposible, o al menos difícil, de controlar.",
  ui_story_1013_10130201_114_dialog_content = "Y eso nos lleva de vuelta a la teoría de la Luminática.",
  ui_story_1013_10130201_115_dialog_content = "No me importa pasar un día entero detallando cada aspecto de Luminatics para el sujeto de prueba.",
  ui_story_1013_10130201_116_dialog_content = "Uh... No creo que sea necesario.",
  ui_story_1013_10130201_117_dialog_content = "No hay necesidad de preocuparse indebidamente, sujeto de prueba.",
  ui_story_1013_10130201_118_dialog_content = "Incluso después de usar Chord Link, aún mantienen la capacidad de usar sus viejos Luminatics.",
  ui_story_1013_10130201_119_dialog_content = "Esto nos lleva a creer que su naturaleza fundamental permanece invariable.",
  ui_story_1013_10130201_120_dialog_content = "¿En realidad...?",
  ui_story_1013_10130201_121_dialog_content = "¿Están hablando de algo serio?",
  ui_story_1013_10130201_122_dialog_content = "¿Ese es el casco del simulador de batalla que tienes en las manos?",
  ui_story_1013_10130201_123_dialog_content = "¿Has progresado?",
  ui_story_1013_10130201_124_dialog_content = "¡Sip!",
  ui_story_1013_10130201_125_dialog_content = "Conectamos el Simulador de Batalla a la base de datos de Soroz.",
  ui_story_1013_10130201_126_dialog_content = "Justo al comienzo de nuestros experimentos, parecía que activamos algunas funciones en los nuevos componentes de Soroz.",
  ui_story_1013_10130201_127_dialog_content = "¡La sala de simulación se actualizó y ahora puede simular completamente las condiciones reales del campo de batalla!",
  ui_story_1013_10130201_128_dialog_content = "Puedes probarlo ahora mismo usando el Simulador de Batalla.",
  ui_story_1013_10130201_129_dialog_content = "pensé que acababa de escuchar PlayerName estaba interesado.",
  ui_story_1013_10130201_130_dialog_content = "¿Qué dices? ¿Quieres intentarlo?",
  ui_story_1013_10130201_131_option_content = "¿Es difícil?",
  ui_story_1013_10130201_132_dialog_content = "¡No voy a hacerte pasar un mal rato! Como es un juego nuevo, comenzaremos con la dificultad más fácil.",
  ui_story_1013_10130201_133_dialog_content = "Muy bien, ¡hagámoslo!",
  ui_story_1013_10130201_134_option_content = "¡Claro!",
  ui_story_1013_10130201_135_dialog_content = "¡Suena genial!",
  ui_story_1013_10130201_136_dialog_content = "¡Bien entonces! Tome asiento allí, PlayerName, y ponte este casco.",
  ui_story_1013_10130201_137_dialog_content = "Listo.",
  ui_story_1013_10130201_138_dialog_content = "¿Eh? ¡El ambiente cambió!",
  ui_story_1013_10130201_139_dialog_content = "Puedes oírme, PlayerName?",
  ui_story_1013_10130201_140_dialog_content = "¡¿Vicio?! ¿Dónde estás?",
  ui_story_1013_10130201_141_dialog_content = "¡Estoy justo a tu lado!",
  ui_story_1013_10130201_142_dialog_content = "Hay una pantalla aquí, así que puedo ver lo que ves.",
  ui_story_1013_10130201_143_dialog_content = "Asi que, PlayerName, ¿que ves?",
  ui_story_1013_10130201_144_dialog_content = "Un desierto totalmente desierto. Hay una brisa agradable y hace bastante sol.",
  ui_story_1013_10130201_145_dialog_content = "Suena preciso.",
  ui_story_1013_10130201_146_dialog_content = "Ahí es donde comienza Battle Simulator.",
  ui_story_1013_10130201_147_dialog_content = "Ahora, PlayerName, imagina a tus compañeros de pie a tu lado.",
  ui_story_1013_10130201_148_dialog_content = "¿Imagina cómo se ven?",
  ui_story_1013_10130201_149_dialog_content = "¡Así es!",
  ui_story_1013_10130201_150_dialog_content = "El simulador de batalla proyectará una imagen auroriana correspondiente utilizando la imagen que evocas en tu mente y los datos de Illumina existentes.",
  ui_story_1013_10130201_151_dialog_content = "Estas proyecciones aurorianas te ayudarán a completar la prueba de batalla.",
  ui_story_1013_10130201_152_option_content = "Piensa en Vice.",
  ui_story_1013_10130201_153_dialog_content = "¡Whoa!",
  ui_story_1013_10130201_154_dialog_content = "¡Apareció!",
  ui_story_1013_10130201_155_dialog_content = "Eso es increíble. ¡Se parece a mí!",
  ui_story_1013_10130201_156_dialog_content = "¡Excelente! Todo va bien.",
  ui_story_1013_10130201_157_dialog_content = "A continuación, permítanme introducir algunos eclipses en escena.",
  ui_story_1013_10130201_158_dialog_content = "¡Gaaah!",
  ui_story_1013_10130201_159_dialog_content = "¡Guau! Los eclipses también parecen reales.",
  ui_story_1013_10130201_160_dialog_content = "¡Casi puedo sentir el Darkflow que sale de ellos!",
  ui_story_1013_10130201_161_dialog_content = "No tengas miedo.",
  ui_story_1013_10130201_162_dialog_content = "¡Esta es solo la prueba más básica!",
  ui_story_1013_10130201_163_dialog_content = "¡Intenta derrotar a esos Eclipsites con el Aurorian virtual!",
  ui_story_1013_10130201_164_dialog_content = "Puedes hacerlo, PlayerName!",
  ui_story_1013_10130201_165_dialog_content = "¡De acuerdo! ¡Lo haré lo mejor que pueda!",
  ui_story_1013_10130201_166_dialog_content = "Dificultad: Fácil.",
  ui_story_1013_10130201_167_dialog_content = "Modo predeterminado, número de serie de etapa: 01.",
  ui_story_1013_10130201_168_dialog_content = "Objetivo: eliminar todos los eclipses.",
  ui_story_1013_10130201_169_dialog_content = "Simulador inicializando...",
  ui_story_1013_10130201_170_dialog_content = "<anim type=Shake><size=50>Graagh!!!</size></anim>",
  ui_story_1013_10130302_1_dialog_content = "¡Uf... todos los Eclipsites están resueltos!",
  ui_story_1013_10130302_2_dialog_content = "Objetivo de etapa completado.",
  ui_story_1013_10130302_3_dialog_content = "Prueba concluida. Grado de etapa: A.",
  ui_story_1013_10130302_4_dialog_content = "Impresionante, PlayerName! ¡Obtuviste una calificación A en tu primer intento en Battle Simulator!",
  ui_story_1013_10130302_5_dialog_content = "Dame un momento, necesito desconectarte del simulador antes de que puedas quitarte el casco.",
  ui_story_1013_10130302_6_dialog_content = "Desconectado. Es seguro salir ahora.",
  ui_story_1013_10130302_7_dialog_content = "Ngh...",
  ui_story_1013_10130302_8_dialog_content = "Cómo te sientes, PlayerName? ¿Todo está bien?",
  ui_story_1013_10130302_9_dialog_content = "Está bien, supongo. Siento que realmente acabo de luchar contra un montón de Eclipsites. ¡Estoy agotado, física y mentalmente!",
  ui_story_1013_10130302_10_dialog_content = "¡Jajaja! Bueno, buen trabajo de todos modos, PlayerName.",
  ui_story_1013_10130302_11_dialog_content = "Sin embargo, esto solo demuestra los méritos de la tecnología.",
  ui_story_1013_10130302_12_dialog_content = "Usando solo algunas de las funciones de la sala de simulación de Soroz, podemos recrear perfectamente las condiciones de batalla reales.",
  ui_story_1013_10130302_13_dialog_content = "¡Esto es mucho mejor que la tediosa teoría y las simulaciones militares!",
  ui_story_1013_10130302_14_dialog_content = "Eso me hace querer darle una oportunidad!",
  ui_story_1013_10130302_15_dialog_content = "Me temo que tendrás que esperar a otro momento.",
  ui_story_1013_10130302_16_dialog_content = "Esta es la tecnología Caelestite después de todo, y solo puede ser probada por PlayerName en este momento.",
  ui_story_1013_10130302_17_dialog_content = "Una vez que entendamos por completo qué es lo que hace que esta tecnología funcione, ¡podremos modificarla para los aurorianos!",
  ui_story_1013_10130302_18_dialog_content = "Con la investigación de Battle Simulator como máxima prioridad, ¿estará listo para nuestros ejercicios militares conjuntos?",
  ui_story_1013_10130302_19_dialog_content = "¡Creo que habría mucho más interés en los ejercicios si pudiéramos implementar esta tecnología!",
  ui_story_1013_10130302_20_dialog_content = "No debería ser un problema si PlayerName está ahí para ayudar!",
  ui_story_1013_10130302_21_dialog_content = "¿Ejercicios militares conjuntos? ¿Que son esos?",
  ui_story_1013_10130302_22_dialog_content = "¡Entrenamiento que ocurre cada dos años!",
  ui_story_1013_10130302_23_dialog_content = "Tampoco es solo la Federación Illumina la que participa. Lumopolis, Northland e incluso Umbraton se unen.",
  ui_story_1013_10130302_24_dialog_content = "Aparte de la colaboración militar a gran escala, cada nación participante también envía a los mejores y más brillantes para competir en eventos individuales.",
  ui_story_1013_10130302_25_dialog_content = "Al final de los ejercicios, todos los que participan se enfrentan a Eclipsitas reales en una batalla real.",
  ui_story_1013_10130302_26_dialog_content = "Suena como un evento animado...",
  ui_story_1013_10130302_27_dialog_content = "¡Mucho!",
  ui_story_1013_10130302_28_dialog_content = "Todo el mundo quiere ser el primero en la competición individual.",
  ui_story_1013_10130302_29_dialog_content = "¡El vencedor gana la oportunidad de entrenar uno a uno con la mismísima Gran Mariscal Reinhardt!",
  ui_story_1013_10130302_30_dialog_content = "¡¿Eh?!",
  ui_story_1013_10130302_31_dialog_content = "Originalmente fue solo una cosa del momento. Siempre les preguntaba a los ganadores si querían pelear una o dos rondas.",
  ui_story_1013_10130302_32_dialog_content = "Pero entonces, pareció convertirse en una parte aceptada del programa.",
  ui_story_1013_10130302_33_dialog_content = "Dicho esto, no me desagrada.",
  ui_story_1013_10130302_34_option_content = "¿No te molesta?",
  ui_story_1013_10130302_35_dialog_content = "¡En lo mas minimo! De hecho, lo espero con ansias.",
  ui_story_1013_10130302_36_option_content = "¡Eso suena como tú!",
  ui_story_1013_10130302_37_dialog_content = "¡Jajaja! Gracias, lo tomaré como un cumplido.",
  ui_story_1013_10130302_38_dialog_content = "Poder cruzar espadas con lo mejor de la generación más joven es un verdadero placer para mí.",
  ui_story_1013_10130302_39_dialog_content = "Mirando con mis propios ojos como crecen y se hacen más fuertes...",
  ui_story_1013_10130302_40_dialog_content = "Hasta que llegue el día en que nos superen y tomen el lugar que les corresponde como los nuevos líderes de una nueva era.",
  ui_story_1013_10130302_41_dialog_content = "Me emociono solo de pensarlo.",
  ui_story_1013_10130302_42_dialog_content = "¿Con quién se enfrentó Reinhardt?",
  ui_story_1013_10130302_43_dialog_content = "¡Creo que la última vencedora del evento individual fue Carleen!",
  ui_story_1013_10130302_44_dialog_content = "¡Estaba más de diez puntos por encima del segundo lugar y lo hizo parecer fácil!",
  ui_story_1013_10130302_45_dialog_content = "Carleen es verdaderamente la mejor de la nueva generación.",
  ui_story_1013_10130302_46_dialog_content = "Cuando entrenamos la última vez, ella dijo que volvería por el primer lugar la próxima vez también.",
  ui_story_1013_10130302_47_dialog_content = "Apuesto a que cuando llegue ese día, ella podría incluso ser lo suficientemente fuerte como para vencerme.",
  ui_story_1013_10130302_48_dialog_content = "¡Jajaja! ¡Estoy deseando que llegue!",
  ui_story_1013_10130302_49_dialog_content = "Estoy tan celoso...",
  ui_story_1013_10130302_50_dialog_content = "Me encantaría tener la oportunidad de entrenar contigo, Gran Mariscal. ¡Apuesto a que aprendería mucho!",
  ui_story_1013_10130302_51_dialog_content = "Luego entrena duro y haz tu mejor esfuerzo para lograr el primer lugar.",
  ui_story_1013_10130302_52_dialog_content = "¡Sí!",
  ui_story_1013_10130302_53_dialog_content = "Tú también, PlayerName!",
  ui_story_1013_10130302_54_dialog_content = "¡¿Yo?!",
  ui_story_1013_10130302_55_dialog_content = "¡Por supuesto! No hay ninguna regulación que diga que los participantes deben ser Aurorianos.",
  ui_story_1013_10130302_56_dialog_content = "Cuando todavía había Caelestites en Astra, a menudo luchaban junto a los Aurorianos.",
  ui_story_1013_10130302_57_dialog_content = "Si puedes participar, será casi como si los caelestitas hubieran regresado.",
  ui_story_1013_10130302_58_dialog_content = "\"Regresado\", eh...",
  ui_story_1013_10130302_59_dialog_content = "Y si vienes primero, también entrenaré contigo.",
  ui_story_1013_10130302_60_dialog_content = "¡No, no hay necesidad!",
  ui_story_1013_10130302_61_dialog_content = "Si peleo contigo, dudo que salga con vida...",
  ui_story_1013_10130302_62_dialog_content = "Entonces, ¿por qué no hacemos una simulación militar?",
  ui_story_1013_10130302_63_dialog_content = "¡Si es solo una simulación, estaría dispuesto a eso!",
  ui_story_1013_10130302_64_dialog_content = "¡Excelente! En ese caso, ¡espero tu coronación como campeón!",
  ui_story_1013_10130302_65_dialog_content = "Lamento interrumpir su conversación.",
  ui_story_1013_10130302_66_dialog_content = "¡Hemos completado los experimentos de hoy!",
  ui_story_1013_10130302_67_dialog_content = "Mi equipo y yo necesitamos analizar los resultados y ajustar el simulador en consecuencia. Creo que para mañana deberíamos poder pasar a la siguiente fase de prueba.",
  ui_story_1013_10130302_68_dialog_content = "¡Dejanoslo a nosotros!",
  ui_story_1013_10130302_69_dialog_content = "¿Hay otra fase?",
  ui_story_1013_10130302_70_dialog_content = "¡Por supuesto! Hoy solo involucró pruebas preliminares básicas.",
  ui_story_1013_10130302_71_dialog_content = "¡El Simulador de Batalla todavía tiene muchas funciones que necesitan ser exploradas!",
  ui_story_1013_10130302_72_dialog_content = "Pero el mantenimiento de Soroz...",
  ui_story_1013_10130302_73_dialog_content = "Relájate, no lo olvidaremos.",
  ui_story_1013_10130302_74_dialog_content = "¡El mantenimiento de Soroz y la investigación de Battle Simulator se pueden realizar al mismo tiempo!",
  ui_story_1013_10130302_75_dialog_content = "Pero tendrás que darnos algo de tiempo.",
  ui_story_1013_10130302_76_dialog_content = "Por favor sea paciente. ¿Por qué no ir y descansar bien?",
  ui_story_1013_10130302_77_dialog_content = "Muy bien, supongo que eso es todo lo que puedo hacer por ahora.",
  ui_story_1013_10130302_78_dialog_content = "Sí. Tomemos un descanso por ahora.",
  ui_story_1013_10130302_79_dialog_content = "¡Todo lo demás puede esperar hasta mañana!",
  ui_story_1013_10130401_1_dialog_content = "<color=#e8d9bb>Gruñido-</color>",
  ui_story_1013_10130401_2_dialog_content = "Estoy hambriento...",
  ui_story_1013_10130401_3_dialog_content = "<color=#e8d9bb> ¡Gruñido! </color>",
  ui_story_1013_10130401_4_dialog_content = "¡Tengo tanta hambre!",
  ui_story_1013_10130401_5_dialog_content = "Después de terminar ayer en el centro de investigación, Vice me llevó a pasar una noche en Gannon City.",
  ui_story_1013_10130401_6_dialog_content = "¡No pensé que me despertaría tan tarde hoy!",
  ui_story_1013_10130401_7_dialog_content = "<color=#e8d9bb>*gruñe el estómago*</color>",
  ui_story_1013_10130401_8_dialog_content = "Eso es todo. Tengo que encontrar algo para comer.",
  ui_story_1013_10130401_9_dialog_content = "La ciudad es tan grande que estoy seguro de que hay muchos lugares para conseguir algo de comida.",
  ui_story_1013_10130401_10_dialog_content = "Eso sí, espero que no sea demasiado caro. No me queda mucho Nightium.",
  ui_story_1013_10130401_11_dialog_content = "Nop.",
  ui_story_1013_10130401_12_dialog_content = "otro no?",
  ui_story_1013_10130401_13_dialog_content = "¡¿Cómo es que literalmente no hay nada?!",
  ui_story_1013_10130401_14_dialog_content = "He caminado por millas, no encontré nada de comida, ¡y ahora tengo aún más hambre!",
  ui_story_1013_10130401_15_dialog_content = "Juro que mi visión ya se está desvaneciendo...",
  ui_story_1013_10130401_16_dialog_content = "¡Esperar! ¿Eso es... comida lo que huelo?",
  ui_story_1013_10130401_17_dialog_content = "¡¿PlayerName?!",
  ui_story_1013_10130401_18_dialog_content = "Despierta, PlayerName! ¡No querrás dormir aquí!",
  ui_story_1013_10130401_19_option_content = "V-Vicio?!",
  ui_story_1013_10130401_20_dialog_content = "¿Estás bien? No te ves tan bien.",
  ui_story_1013_10130401_21_dialog_content = "Estoy bien. Bueno, en realidad me muero de hambre y no puedo encontrar un lugar para comer en ningún lado...",
  ui_story_1013_10130401_22_dialog_content = "Deambulé en vano durante años, solo para terminar aquí.",
  ui_story_1013_10130401_23_dialog_content = "¡Lo siento mucho! Olvidé mencionar.",
  ui_story_1013_10130401_24_dialog_content = "Illumina opera con un sistema de racionamiento, por lo que no hay restaurantes ni nada en Gannon.",
  ui_story_1013_10130401_25_dialog_content = "Si los visitantes necesitan suministros, primero deben ir a un área designada y pasar por todos los aros burocráticos.",
  ui_story_1013_10130401_26_dialog_content = "Estábamos tan ocupados con los exámenes ayer que me olvidé por completo de aplicar...",
  ui_story_1013_10130401_27_dialog_content = "La oficial Vivian ya preparó las raciones para ti, ¡así que vayamos a recogerlas cuando terminemos hoy!",
  ui_story_1013_10130401_28_dialog_content = "Parece un poco complicado.",
  ui_story_1013_10130401_29_dialog_content = "Bueno, la productividad de la Federación Illumina es limitada, después de todo. Incluso asegurarse de que todos puedan comer no es tarea fácil.",
  ui_story_1013_10130401_30_dialog_content = "Las raciones son la mejor manera de evitar el desperdicio y garantizar que todos tengan suficiente.",
  ui_story_1013_10130401_31_dialog_content = "De todos modos, ¡mira lo que traje! ¡Desayuno!",
  ui_story_1013_10130401_32_dialog_content = "¡Ta-da!",
  ui_story_1013_10130401_33_dialog_content = "¡Así que ERA comida lo que olí!",
  ui_story_1013_10130401_34_dialog_content = "¡Debes estar muerto de hambre! ¡Ven y come!",
  ui_story_1013_10130401_35_dialog_content = "¡Tenemos que regresar al centro de investigación en un momento!",
  ui_story_1013_10130401_36_dialog_content = "¡Estoy cavando!",
  ui_story_1013_10130401_37_dialog_content = "(No tenía idea de que un lugar tan aparentemente poderoso como Illumina tendría que ser tan cuidadoso con sus recursos).",
  ui_story_1013_10130401_38_dialog_content = "NOM Nom Nom...",
  ui_story_1013_10130401_39_dialog_content = "¡Eso es mejor! ¡Me siento vivo de nuevo ahora que estoy lleno!",
  ui_story_1013_10130401_40_dialog_content = "¡Sí, siempre estoy más feliz a la hora de comer!",
  ui_story_1013_10130401_41_dialog_content = "Ya que estamos recargados, deberíamos empezar con el trabajo del día.",
  ui_story_1013_10130401_42_dialog_content = "Se suponía que íbamos a seguir ayudando con el Simulador de batalla, ¿verdad?",
  ui_story_1013_10130401_43_dialog_content = "Sí. Según los científicos que trabajaron toda la noche, ¡descubrieron una nueva función!",
  ui_story_1013_10130401_44_dialog_content = "¿Deberíamos echar un vistazo?",
  ui_story_1013_10130401_45_dialog_content = "¡Seguro!",
  ui_story_1013_10130401_46_dialog_content = "<color=#e8d9bb>Centro de investigación Illumina</color>",
  ui_story_1013_10130401_47_dialog_content = "¡Buenos dias! Ustedes dos finalmente están aquí.",
  ui_story_1013_10130401_48_dialog_content = "¿Gran mariscal?",
  ui_story_1013_10130401_49_dialog_content = "¿Nos has estado esperando todo este tiempo?",
  ui_story_1013_10130401_50_dialog_content = "Sí. Me gustaría ver por mí mismo cómo funciona Battle Simulator.",
  ui_story_1013_10130401_51_dialog_content = "Entonces, ¿están todos aquí?",
  ui_story_1013_10130401_52_dialog_content = "¡Ya logramos actualizar el Simulador de batalla!",
  ui_story_1013_10130401_53_dialog_content = "¡Así es! Y también tenemos un nombre totalmente actualizado: ¡el Simulador de campo de batalla!",
  ui_story_1013_10130401_54_option_content = "¿Campo de batalla?",
  ui_story_1013_10130401_55_dialog_content = "Si bien una sílaba adicional no parece mucho, ¡la diferencia es realmente enorme!",
  ui_story_1013_10130401_56_option_content = "¿Qué diferencia?",
  ui_story_1013_10130401_57_dialog_content = "¡Uno enorme!",
  ui_story_1013_10130401_58_dialog_content = "El simulador de campo de batalla se actualizó después de leer los datos tomados de los nuevos módulos de Soroz.",
  ui_story_1013_10130401_59_dialog_content = "¡Ahora, se pueden recrear simulaciones precisas de batallas históricas a partir de registros de combate detallados!",
  ui_story_1013_10130401_60_dialog_content = "No solo el enemigo, sino también la hora local, el terreno e incluso el clima se pueden recrear perfectamente.",
  ui_story_1013_10130401_61_dialog_content = "Increíble, ¿no?",
  ui_story_1013_10130401_62_dialog_content = "¿Estás diciendo que es capaz de crear batallas aún más realistas?",
  ui_story_1013_10130401_63_dialog_content = "En teoría, sí.",
  ui_story_1013_10130401_64_dialog_content = "Sin embargo, debido a que aún no lo hemos configurado por completo, aún eres el único que puede probar el Simulador de campo de batalla.",
  ui_story_1013_10130401_65_dialog_content = "Así que... ¡hoy volveremos a contar contigo!",
  ui_story_1013_10130401_66_dialog_content = "Todavía estoy hecho polvo desde ayer. Espero que no sea muy difícil hoy.",
  ui_story_1013_10130401_67_dialog_content = "No te preocupes. Usamos datos de batallas del pasado meticulosamente registrados.",
  ui_story_1013_10130401_68_dialog_content = "¡Será un paseo por el parque para alguien con tus habilidades!",
  ui_story_1013_10130401_69_dialog_content = "Buena suerte, PlayerName. Estaré pendiente desde aquí.",
  ui_story_1013_10130401_70_dialog_content = "¡E-está bien!",
  ui_story_1013_10130401_71_dialog_content = "Ahora, ponte el casco, como ayer...",
  ui_story_1013_10130401_72_dialog_content = "No se ve muy diferente.",
  ui_story_1013_10130401_73_dialog_content = "¡Paciencia! Estamos cargando los datos de batalla ahora.",
  ui_story_1013_10130401_74_dialog_content = "Déjame ver. ¿Cuál debería elegir?",
  ui_story_1013_10130401_75_dialog_content = "Interesante. ¿Que tal este?",
  ui_story_1013_10130401_76_dialog_content = "¿eh? ¿Está seguro, Gran Mariscal?",
  ui_story_1013_10130401_77_dialog_content = "¿No es eso un poco...",
  ui_story_1013_10130401_78_dialog_content = "No hay necesidad de preocuparse. Ciertamente está dentro de sus habilidades.",
  ui_story_1013_10130401_79_dialog_content = "Tiene experiencia en este tipo de entorno de combate. ¡Ten fe en él!",
  ui_story_1013_10130401_80_dialog_content = "¡Sí, señora!",
  ui_story_1013_10130401_81_dialog_content = "¡Espera un segundo, Reinhardt!",
  ui_story_1013_10130401_82_dialog_content = "¡¿Qué elegiste exactamente?!",
  ui_story_1013_10130401_83_dialog_content = "Lo sabrás en un segundo.",
  ui_story_1013_10130401_84_dialog_content = "Cargando registro de batalla...",
  ui_story_1013_10130401_85_dialog_content = "Campaña encontrada: Dark Zone War.",
  ui_story_1013_10130401_86_dialog_content = "¡Todo se ha vuelto tan oscuro como la Noche Eterna!",
  ui_story_1013_10130401_87_dialog_content = "Urgh... Incluso la horrible sensación de Darkflow está siendo simulada.",
  ui_story_1013_10130401_88_dialog_content = "¿Qué opinas, nombre del jugador?",
  ui_story_1013_10130401_89_dialog_content = "¡Ciertamente es realista!",
  ui_story_1013_10130401_90_dialog_content = "¡Incluso podría decir que es un poco demasiado realista!",
  ui_story_1013_10130401_91_dialog_content = "Realmente se siente como una batalla en la Zona Oscura, ¡hasta la sensación desorientadora del Darkflow!",
  ui_story_1013_10130401_92_dialog_content = "¿De veras? ¡Estupendo!",
  ui_story_1013_10130401_93_option_content = "¡¿Qué es exactamente lo bueno de esto?!",
  ui_story_1013_10130401_94_dialog_content = "Cuanto más realista podamos hacer que el entorno de simulación sea, más útil será el Simulador de campo de batalla.",
  ui_story_1013_10130401_95_dialog_content = "Brindará a los usuarios la experiencia más realista que puedan obtener de una batalla real sin estar realmente en una; experimentar personalmente las sombrías y duras realidades de la guerra.",
  ui_story_1013_10130401_96_dialog_content = "También les dará la oportunidad de familiarizarse con el campo de batalla y perfeccionar sus habilidades en entornos complejos.",
  ui_story_1013_10130401_97_dialog_content = "Entonces, cuando realmente se encuentren en un conflicto real, habrá menos bajas.",
  ui_story_1013_10130401_98_dialog_content = "Hace sentido...",
  ui_story_1013_10130401_99_dialog_content = "Así que por favor, sé el primero en experimentarlo. ¡Lucha tanto como quieras y prueba todo lo que el simulador tiene para ofrecer!",
  ui_story_1013_10130401_100_dialog_content = "Muy bien, estoy en ello.",
  ui_story_1013_10130401_101_dialog_content = "Bueno. Preparándose para inicializar la batalla. Prepararse, PlayerName.",
  ui_story_1013_10130401_102_dialog_content = "Modo de simulación de campo de batalla, número de serie del escenario: 11,328.",
  ui_story_1013_10130401_103_dialog_content = "Objetivo: atravesar o eliminar los eclipses.",
  ui_story_1013_10130401_104_dialog_content = "Simulador inicializando...",
  ui_story_1013_10130401_105_dialog_content = "Graaaaah-!",
  ui_story_1013_10130401_106_dialog_content = "Muy bien, comencemos esta fiesta.",
  ui_story_1013_10130502_1_dialog_content = "¡Echar para atrás! ¡Usa las rocas para cubrirte!",
  ui_story_1013_10130502_2_dialog_content = "...",
  ui_story_1013_10130502_3_dialog_content = "Grr-!",
  ui_story_1013_10130502_4_dialog_content = "¡Graagh!",
  ui_story_1013_10130502_5_dialog_content = "¡¿Dónde están todos ellos procedentes de?!",
  ui_story_1013_10130502_6_dialog_content = "¡...!",
  ui_story_1013_10130502_7_dialog_content = "esto no es bueno Un golpe más y Vice quedará fuera de servicio.",
  ui_story_1013_10130502_8_dialog_content = "¿Qué tengo que hacer? Con tantos eclipses, no se ve bien...",
  ui_story_1013_10130502_9_dialog_content = "Está bien, cálmate. Simplemente cálmate.",
  ui_story_1013_10130502_10_dialog_content = "Mira alrededor. Tiene que haber algo.",
  ui_story_1013_10130502_11_dialog_content = "¡Vicio! ¡Dispara a esa roca que sobresale!",
  ui_story_1013_10130502_12_dialog_content = "roger",
  ui_story_1013_10130502_13_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_1013_10130502_14_dialog_content = "Graaahh—",
  ui_story_1013_10130502_15_dialog_content = "¡Excelente! ¡La roca atravesó ese paquete de Eclipsites!",
  ui_story_1013_10130502_16_dialog_content = "¡Vicio, ahora! ¡Avancemos!",
  ui_story_1013_10130502_17_dialog_content = "Copiado.",
  ui_story_1013_10130502_18_dialog_content = "¡Ahí! ¡Podemos romper ese punto débil allí!",
  ui_story_1013_10130502_19_dialog_content = "¡Lo logré!",
  ui_story_1013_10130502_20_dialog_content = "Objetivo de etapa completado.",
  ui_story_1013_10130502_21_dialog_content = "Prueba concluida. Grado de etapa: C.",
  ui_story_1013_10130502_22_dialog_content = "Buf... buf...",
  ui_story_1013_10130502_23_dialog_content = "Eso fue completamente agotador...",
  ui_story_1013_10130502_24_dialog_content = "¡¿Y solo obtuvimos una C?!",
  ui_story_1013_10130502_25_dialog_content = "Buen trabajo, PlayerName.",
  ui_story_1013_10130502_26_dialog_content = "Un segundo, te desconectaré.",
  ui_story_1013_10130502_27_dialog_content = "Desconectado. Es seguro salir ahora.",
  ui_story_1013_10130502_28_dialog_content = "Bien hecho de hecho, PlayerName!",
  ui_story_1013_10130502_29_dialog_content = "¿Qué te pareció la simulación de la Zona Oscura?",
  ui_story_1013_10130502_30_option_content = "Agotador...",
  ui_story_1013_10130502_31_dialog_content = "A pesar de que estaba sentado allí, mi ropa todavía estaba empapada de sudor.",
  ui_story_1013_10130502_32_option_content = "Difícil...",
  ui_story_1013_10130502_33_dialog_content = "Hice lo mejor que pude y usé todas las estrategias que se me ocurrieron...",
  ui_story_1013_10130502_34_dialog_content = "¡Y aún así solo obtuve una C!",
  ui_story_1013_10130502_35_dialog_content = "¡Aunque lo hiciste muy bien!",
  ui_story_1013_10130502_36_dialog_content = "¡Así es! Y sabes, esta fue una de las propias batallas del Gran Mariscal.",
  ui_story_1013_10130502_37_dialog_content = "Así que obtener la puntuación que obtuviste ya es un gran logro.",
  ui_story_1013_10130502_38_dialog_content = "Espera, ¿esa fue una batalla en la que luchó Reinhardt?",
  ui_story_1013_10130502_39_dialog_content = "¿Cuál fue el resultado de la pelea real?",
  ui_story_1013_10130502_40_dialog_content = "Déjame revisar los registros...",
  ui_story_1013_10130502_41_dialog_content = "¡Entiendo! Aquí dice que logró derrotar a 50 Eclipsites Y abrirse paso, recibiendo solo heridas leves en el proceso.",
  ui_story_1013_10130502_42_dialog_content = "Ese es probablemente el criterio del simulador para una A o superior.",
  ui_story_1013_10130502_43_dialog_content = "¡Increíble!",
  ui_story_1013_10130502_44_dialog_content = "Para lograr eso, especialmente en la Zona Oscura.",
  ui_story_1013_10130502_45_dialog_content = "¡Como se esperaba del Gran Mariscal!",
  ui_story_1013_10130502_46_dialog_content = "Suspiro ... Estaba luchando solo para completarlo.",
  ui_story_1013_10130502_47_dialog_content = "Date un poco de crédito, PlayerName.",
  ui_story_1013_10130502_48_dialog_content = "Esta es solo la segunda vez que peleas dentro de la Zona Oscura. Lo que has logrado ya es muy impresionante.",
  ui_story_1013_10130502_49_dialog_content = "En comparación con la última vez, tomó más en cuenta el medio ambiente y lo usó a su favor.",
  ui_story_1013_10130502_50_dialog_content = "Además, pudiste completar la batalla sin apoyo adicional.",
  ui_story_1013_10130502_51_dialog_content = "Has mejorado mucho, ¡lo que merece un elogio!",
  ui_story_1013_10130502_52_dialog_content = "¿G-gracias?",
  ui_story_1013_10130502_53_dialog_content = "Si tan solo la Federación Illumina tuviera más comandantes como tú...",
  ui_story_1013_10130502_54_dialog_content = "Nuestras batallas contra los Eclipsites irían mucho mejor.",
  ui_story_1013_10130502_55_dialog_content = "Ahora que lo pienso, PlayerName Ya tenía una gran comprensión del mando cuando nos conocimos.",
  ui_story_1013_10130502_56_option_content = "Gracias a Soroz.",
  ui_story_1013_10130502_57_option_content = "Me enseñaron desde muy joven.",
  ui_story_1013_10130502_58_dialog_content = "¿Hmm?",
  ui_story_1013_10130502_59_dialog_content = "Soroz me enseñó mucho en los 17 años que pasé bajo tierra.",
  ui_story_1013_10130502_60_dialog_content = "Incluyendo lo que se necesita para ser un buen comandante en el campo de batalla.",
  ui_story_1013_10130502_61_dialog_content = "¿Los caelestitas incluyen el mando en el campo de batalla en su programa académico...?",
  ui_story_1013_10130502_62_dialog_content = "¿Pero pensé que los Caelestites eran una raza amante de la paz?",
  ui_story_1013_10130502_63_dialog_content = "Mmm. Ahora que lo pienso, ese conocimiento probablemente provino de la misma fuente que los datos en el Obelisco del Retorno.",
  ui_story_1013_10130502_64_dialog_content = "Yo...",
  ui_story_1013_10130502_65_dialog_content = "¿Dudas de ti mismo? PlayerName?",
  ui_story_1013_10130502_66_dialog_content = "... No. Ya lo he pensado.",
  ui_story_1013_10130502_67_dialog_content = "¿Oh?",
  ui_story_1013_10130502_68_dialog_content = "Independientemente de dónde adquirí este conocimiento, es mío.",
  ui_story_1013_10130502_69_dialog_content = "Solo lo usaré para proteger a mis compañeros; no para ningún propósito nefasto.",
  ui_story_1013_10130502_70_dialog_content = "¡Ajajaja! Estuvimos separados por poco tiempo, ¡pero parece que has madurado mucho!",
  ui_story_1013_10130502_71_dialog_content = "¿D-De veras?",
  ui_story_1013_10130502_72_dialog_content = "¡Mucho!",
  ui_story_1013_10130502_73_dialog_content = "Después del incidente de Eraveil la última vez, pensé que te veías un poco peor. En realidad estuve preocupado por un tiempo.",
  ui_story_1013_10130502_74_dialog_content = "Pero ahora parece que tales preocupaciones estaban fuera de lugar.",
  ui_story_1013_10130502_75_dialog_content = "¡No me subestimes!",
  ui_story_1013_10130502_76_dialog_content = "No, ciertamente no lo haré.",
  ui_story_1013_10130502_77_dialog_content = "Sin embargo, es un poco vergonzoso. Tenía todo preparado mi discurso de consuelo, pero al final del día, ni siquiera lo necesitabas.",
  ui_story_1013_10130502_78_dialog_content = "¿Eh? ¿Discurso?",
  ui_story_1013_10130502_79_dialog_content = "Bueno, más como un viejo dicho de Illumina:",
  ui_story_1013_10130502_80_dialog_content = "\"No existe el bien o el mal inherente en la ciencia y la tecnología, sino solo en los corazones de los aurorianos que las manejan\".",
  ui_story_1013_10130502_81_dialog_content = "Em...",
  ui_story_1013_10130502_82_dialog_content = "Es un poco difícil imaginar esas palabras saliendo de tu boca.",
  ui_story_1013_10130502_83_dialog_content = "Bueno, ¡no son mis palabras! Solo estoy transmitiendo lo que esos viejos pedantes solían decirme.",
  ui_story_1013_10130502_84_dialog_content = "Comprendo.",
  ui_story_1013_10130502_85_dialog_content = "De todos modos, estoy encantado de verte capaz de seguir adelante tan rápido.",
  ui_story_1013_10130502_86_dialog_content = "Aunque no pude ayudarte esta vez, no dudes en acudir a mí si hay algo que necesites en el futuro.",
  ui_story_1013_10130502_87_dialog_content = "Te ayudaré en todo lo que pueda.",
  ui_story_1013_10130502_88_dialog_content = "Pero no soy la persona más elocuente, por lo que es posible que no tenga consejos útiles para usted.",
  ui_story_1013_10130502_89_dialog_content = "Solo tu oferta ya es muy conmovedora.",
  ui_story_1013_10130502_90_dialog_content = "Ah, ahora que lo pienso, todavía estoy bastante preocupado por Soroz...",
  ui_story_1013_10130502_91_dialog_content = "Sí. Hicimos todo lo que se suponía que debíamos hacer. Encontramos el módulo y volvimos al Obelisco del Retorno para repararlo.",
  ui_story_1013_10130502_92_dialog_content = "Pero, ¿por qué Soroz no ha despertado todavía?",
  ui_story_1013_10130502_93_dialog_content = "Está más allá de nuestro control ahora.",
  ui_story_1013_10130502_94_dialog_content = "Incluso la Federación Illumina, conocida por su tecnología avanzada, no ha investigado realmente la inteligencia artificial.",
  ui_story_1013_10130502_95_dialog_content = "La conciencia de un Coloso también es muy diferente de las formas más comunes de IA.",
  ui_story_1013_10130502_96_dialog_content = "¡Estoy seguro de que descubriremos más a medida que continuamos con nuestra investigación!",
  ui_story_1013_10130502_97_dialog_content = "De todos modos, sigamos adelante por ahora, porque tengo buenas noticias si quieres escucharlas.",
  ui_story_1013_10130502_98_dialog_content = "¿Qué es?",
  ui_story_1013_10130502_99_dialog_content = "Encontramos bastantes registros de batalla en el nuevo módulo de Soroz.",
  ui_story_1013_10130502_100_dialog_content = "Estos registros son probablemente tan antiguos como el Coloso y el Obelisco del Retorno.",
  ui_story_1013_10130502_101_dialog_content = "¡Oye, no me robes las líneas!",
  ui_story_1013_10130502_102_dialog_content = "Creemos que será posible recopilar información sobre los Colosos a partir de estos registros.",
  ui_story_1013_10130502_103_dialog_content = "Supongo que le gustaría ver su Colossus reparado, sujeto de prueba.",
  ui_story_1013_10130502_104_dialog_content = "... Solo dime que hacer.",
  ui_story_1013_10130502_105_dialog_content = "Cargaremos estos datos antiguos en el simulador de campo de batalla y ejecutaremos un simulador.",
  ui_story_1013_10130502_106_dialog_content = "Todo lo que necesitas hacer es pelear en ese sim.",
  ui_story_1013_10130502_107_dialog_content = "Estaremos observando desde afuera y recopilando los datos que necesitamos.",
  ui_story_1013_10130502_108_dialog_content = "Y obviamente, PlayerName, le brindaremos toda la ayuda y orientación que podamos.",
  ui_story_1013_10130502_109_dialog_content = "No estamos probando tus habilidades aquí, después de todo. Esto es todo acerca de la recopilación de datos.",
  ui_story_1013_10130502_110_dialog_content = "Sin embargo, esta es la primera vez que cargamos datos como estos en el simulador.",
  ui_story_1013_10130502_111_dialog_content = "Recomiendo ser extra precavido.",
  ui_story_1013_10130502_112_dialog_content = "Entiendo. Si esta es la forma más rápida de arreglar a Soroz, me apunto.",
  ui_story_1013_10130502_113_dialog_content = "Empecemos.",
  ui_story_1013_10130502_114_dialog_content = "Cosa segura. Toma asiento en la silla y ponte el casco, como antes.",
  ui_story_1013_10130601_1_dialog_content = "¿Dónde... dónde está esto?",
  ui_story_1013_10130601_2_dialog_content = "Parece una ciudad.",
  ui_story_1013_10130601_3_dialog_content = "¿Qué pasó con el desierto?",
  ui_story_1013_10130601_4_dialog_content = "Extraño.",
  ui_story_1013_10130601_5_dialog_content = "¡Oye! Vice, Reinhardt, ¿puedes oírme?",
  ui_story_1013_10130601_6_dialog_content = "...",
  ui_story_1013_10130601_7_dialog_content = "¿Cómo es que no están respondiendo?",
  ui_story_1013_10130601_8_dialog_content = "¿Seguramente el simulador no puede haber fallado?",
  ui_story_1013_10130601_9_dialog_content = "<color=#e8d9bb>Fuera del simulador</color>",
  ui_story_1013_10130601_10_dialog_content = "¿PlayerName?",
  ui_story_1013_10130601_11_dialog_content = "Oye, PlayerName! ¿Puedes escucharme?",
  ui_story_1013_10130601_12_dialog_content = "¿Que esta pasando? ¿Hemos perdido la conexión?",
  ui_story_1013_10130601_13_dialog_content = "Lo siento. ¡Nosotros tampoco lo sabemos!",
  ui_story_1013_10130601_14_dialog_content = "El simulador no informa ningún error. Y podemos ver lo que PlayerName está experimentando.",
  ui_story_1013_10130601_15_dialog_content = "Pero no podemos comunicarnos con él.",
  ui_story_1013_10130601_16_dialog_content = "¿¡Pero por qué!?",
  ui_story_1013_10130601_17_dialog_content = "¡Rápido, sácalo del simulador!",
  ui_story_1013_10130601_18_dialog_content = "No podemos dejarlo en riesgo.",
  ui_story_1013_10130601_19_dialog_content = "¡S-Sí!",
  ui_story_1013_10130601_20_dialog_content = "¿Ah?",
  ui_story_1013_10130601_21_dialog_content = "No puedo cortar la conexión. ¿Pero por qué?",
  ui_story_1013_10130601_22_dialog_content = "¿Y ahora qué pasa?",
  ui_story_1013_10130601_23_dialog_content = "Lo siento. Pero no puedo explicarlo.",
  ui_story_1013_10130601_24_dialog_content = "Voluntad... Voluntad PlayerName ¿estar bien?",
  ui_story_1013_10130601_25_dialog_content = "¿Por qué el simulador fallaría tan repentinamente?",
  ui_story_1013_10130601_26_dialog_content = "Nada como esto ha sucedido antes.",
  ui_story_1013_10130601_27_dialog_content = "Tal vez sea porque usamos los datos de batalla de Soroz.",
  ui_story_1013_10130601_28_dialog_content = "¿Podemos obligar al sim a terminar quitándose el casco?",
  ui_story_1013_10130601_29_dialog_content = "Eso sería desaconsejable, Gran Mariscal.",
  ui_story_1013_10130601_30_dialog_content = "¿Eh? Pensé que estabas mirando el equipo médico. ¿Qué estás haciendo aquí?",
  ui_story_1013_10130601_31_dialog_content = "Necesitas un biólogo para averiguar qué le está pasando al niño. Así que aquí estoy.",
  ui_story_1013_10130601_32_dialog_content = "Estás bien. Entonces, ¿qué puede decirnos sobre lo que le está pasando a PlayerName?",
  ui_story_1013_10130601_33_dialog_content = "Nada, hasta que haya llevado a cabo un examen adecuado.",
  ui_story_1013_10130601_34_dialog_content = "Pero puedo decir que las cosas no pintan bien. Cuando el simulador se está ejecutando, forma un vínculo con la conciencia del usuario.",
  ui_story_1013_10130601_35_dialog_content = "Si cortamos ese vínculo a la fuerza, pasará el resto de su vida en una cama de hospital.",
  ui_story_1013_10130601_36_dialog_content = "Como demonios...",
  ui_story_1013_10130601_37_dialog_content = "Pero tampoco podemos dejarlo ahí dentro.",
  ui_story_1013_10130601_38_dialog_content = "¿No hay nada que podamos hacer desde aquí?",
  ui_story_1013_10130601_39_dialog_content = "Mantenga la calma, teniente Vice.",
  ui_story_1013_10130601_40_dialog_content = "Todo lo que puedes hacer por ahora es mantenerte fuera de nuestro camino mientras averiguamos cómo ayudarlo.",
  ui_story_1013_10130601_41_dialog_content = "Entonces sigue haciendo lo que puedas para ayudar. PlayerName.",
  ui_story_1013_10130601_42_dialog_content = "Sácalo del simulador de forma segura y lo antes posible.",
  ui_story_1013_10130601_43_dialog_content = "<color=#e8d9bb>De vuelta en la simulación</color>",
  ui_story_1013_10130601_44_dialog_content = "¿Qué está pasando acá?",
  ui_story_1013_10130601_45_dialog_content = "No puedo contactar a los investigadores afuera. No he escuchado nada que indique que la etapa está comenzando.",
  ui_story_1013_10130601_46_dialog_content = "¿Y dónde está esto? No es Illumina o Lumopolis.",
  ui_story_1013_10130601_47_dialog_content = "Recuerdo que los investigadores dijeron que los datos provenían del nuevo módulo de Soroz.",
  ui_story_1013_10130601_48_dialog_content = "Eso significa que estoy mirando...",
  ui_story_1013_10130601_49_option_content = "¿Una ciudad antigua?",
  ui_story_1013_10130601_50_dialog_content = "¡Corre!",
  ui_story_1013_10130601_51_dialog_content = "¿Eh? ¿Por qué esas personas corren en mi dirección?",
  ui_story_1013_10130601_52_dialog_content = "¡Corre ahora! ¡No te dejes atrapar!",
  ui_story_1013_10130601_53_dialog_content = "¡Aférrate! ¿Qué esta pasando?",
  ui_story_1013_10130601_54_dialog_content = "¡Aaah! ¡Ellos vienen!",
  ui_story_1013_10130601_55_dialog_content = "¿Quién esta viniendo? ¿Que esta pasando?",
  ui_story_1013_10130601_56_dialog_content = "Espera, ¿es eso Darkflow?",
  ui_story_1013_10130601_57_dialog_content = "Graaaaah!",
  ui_story_1013_10130601_58_dialog_content = "¡Eek! ¡Vicio!",
  ui_story_1013_10130601_59_dialog_content = "...",
  ui_story_1013_10130601_60_dialog_content = "Afortunadamente, mi subconsciente creó un Vicio imaginario para mí justo a tiempo...",
  ui_story_1013_10130601_61_dialog_content = "¡Protege a los civiles! ¡Mantente en formación!",
  ui_story_1013_10130601_62_dialog_content = "No tenemos nada que temer de los eclipses.",
  ui_story_1013_10130601_63_dialog_content = "¡Levanta tus armas y mantente cerca!",
  ui_story_1013_10130601_64_dialog_content = "¡¡¡Cargar!!!",
  ui_story_1013_10130601_65_dialog_content = "¡Grrr!",
  ui_story_1013_10130601_66_dialog_content = "¿Son esos aurorianos? Están luchando contra los Eclipsites con Luminatics...",
  ui_story_1013_10130601_67_dialog_content = "Pero parece tan débil.",
  ui_story_1013_10130601_68_dialog_content = "No está haciendo ningún daño a los Eclipsites.",
  ui_story_1013_10130601_69_dialog_content = "¡Grrr!",
  ui_story_1013_10130601_70_dialog_content = "¡Urgh!",
  ui_story_1013_10130601_71_option_content = "¡Retrocede!",
  ui_story_1013_10130601_72_dialog_content = "¡No puedes vencer a esos eclipses!",
  ui_story_1013_10130601_73_dialog_content = "No queda ningún lugar al que recurrir.",
  ui_story_1013_10130601_74_dialog_content = "Ya están en nuestras puertas.",
  ui_story_1013_10130601_75_dialog_content = "¡Oye! ¡Corre antes de que te maten!",
  ui_story_1013_10130601_76_dialog_content = "¡¡¡Cargar!!!",
  ui_story_1013_10130601_77_dialog_content = "Grah!!!",
  ui_story_1013_10130601_78_dialog_content = "¡Vicio, ayúdalos!",
  ui_story_1013_10130601_79_dialog_content = "¡Servirá!",
  ui_story_1013_10130602_1_dialog_content = "<color=#e8d9bb>Fuera del simulador</color>",
  ui_story_1013_10130602_2_dialog_content = "Como es PlayerName ¿haciendo?",
  ui_story_1013_10130602_3_dialog_content = "Todavía estamos analizando la situación.",
  ui_story_1013_10130602_4_dialog_content = "El sujeto se mantiene estable y se ha dado cuenta de que algo anda mal.",
  ui_story_1013_10130602_5_dialog_content = "Está peleando con los Eclipsites. Y eso nos da tiempo.",
  ui_story_1013_10130602_6_dialog_content = "¡Confía en el Navegante para que te ayude a su manera!",
  ui_story_1013_10130602_7_dialog_content = "No dejes que sus esfuerzos se desperdicien. ¡Sigue trabajando en el análisis de los datos!",
  ui_story_1013_10130602_8_dialog_content = "¡Entendido!",
  ui_story_1013_10130602_9_dialog_content = "Gran Mariscal, hemos encontrado algo durante nuestro análisis.",
  ui_story_1013_10130602_10_dialog_content = "Seguir.",
  ui_story_1013_10130602_11_dialog_content = "Analizamos la escena que se desarrolla actualmente en el simulador.",
  ui_story_1013_10130602_12_dialog_content = "Los edificios allí no coinciden con el estilo arquitectónico moderno de Aurorian.",
  ui_story_1013_10130602_13_dialog_content = "Pero son idénticos a los que Siobhan encontró en una antigua ciudad subterránea.",
  ui_story_1013_10130602_14_dialog_content = "Creemos que los datos son anteriores a los aurorianos.",
  ui_story_1013_10130602_15_dialog_content = "Se remonta a un período de la historia que hace mucho que se olvidó.",
  ui_story_1013_10130602_16_dialog_content = "Historia antigua, eh...",
  ui_story_1013_10130602_17_dialog_content = "Sigue grabando.",
  ui_story_1013_10130602_18_dialog_content = "Es probable que los datos del simulador puedan proporcionarnos un fragmento de la historia de entonces.",
  ui_story_1013_10130602_19_dialog_content = "Y esté atento a lo que le sucede al Navegador. Tal vez podamos encontrar algo que nos ayude a sacarlo.",
  ui_story_1013_10130602_20_dialog_content = "<color=#e8d9bb>De vuelta en la simulación</color>",
  ui_story_1013_10130602_21_dialog_content = "¿Que esta pasando? El escenario aún no ha comenzado, pero los Eclipsites ya están aquí...",
  ui_story_1013_10130602_22_dialog_content = "Algo está muy mal. Supongo que el simulador debe haber fallado.",
  ui_story_1013_10130602_23_dialog_content = "¡Gahhhhhh!",
  ui_story_1013_10130602_24_dialog_content = "...",
  ui_story_1013_10130602_25_dialog_content = "Simplemente siguen viniendo. ¿Esto alguna vez va a terminar?",
  ui_story_1013_10130602_26_dialog_content = "Estoy solo aquí con un Vicio imaginario.",
  ui_story_1013_10130602_27_dialog_content = "No puedo escuchar ninguna comunicación de mis compañeros. Ni siquiera Soroz está aquí conmigo.",
  ui_story_1013_10130602_28_dialog_content = "¿Cómo se supone que voy a poner fin a esta extraña situación?",
  ui_story_1013_10130602_29_dialog_content = "¿Qué pasa si dejo que los Eclipsites me maten? ¿Quizás eso desencadenaría las condiciones de falla y la simulación terminaría?",
  ui_story_1013_10130602_30_dialog_content = "Sin embargo, esta es la primera vez que cargamos datos como estos en el simulador.",
  ui_story_1013_10130602_31_dialog_content = "Recomiendo ser extra precavido.",
  ui_story_1013_10130602_32_dialog_content = "No, no puedo arriesgarme a hacer nada precipitado.",
  ui_story_1013_10130602_33_dialog_content = "Algo extraño está pasando con el simulador. Cualquier cosa que haga podría tener consecuencias inesperadas.",
  ui_story_1013_10130602_34_dialog_content = "Y... bueno, no estoy solo, ¿verdad?",
  ui_story_1013_10130602_35_dialog_content = "Vice y los demás habrán notado que algo anda mal. Estarán tratando de ayudar.",
  ui_story_1013_10130602_36_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_1013_10130602_37_dialog_content = "¿¡Ahora que!?",
  ui_story_1013_10130602_38_dialog_content = "<color=#e8d9bb>¡¡¡BOOM!!!</color>",
  ui_story_1013_10130602_39_dialog_content = "¿Es un terremoto?",
  ui_story_1013_10130602_40_dialog_content = "Espera, ¿¡todo... todo se está derrumbando!?",
  ui_story_1013_10130602_41_dialog_content = "<color=#e8d9bb>AUGE-!!</color>",
  ui_story_1013_10130602_42_dialog_content = "¡Retiro! ¡Regresa, ahora!",
  ui_story_1013_10130602_43_dialog_content = "¡Vienen los demonios!",
  ui_story_1013_10130602_44_dialog_content = "¿Demonios?",
  ui_story_1013_10130602_45_dialog_content = "¡Ay! ¡Mi cabeza!",
  ui_story_1013_10130602_46_dialog_content = "Tengo que salir de aquí...",
  ui_story_1013_10130602_47_dialog_content = "PlayerName.",
  ui_story_1013_10130602_48_dialog_content = "Despierta.",
  ui_story_1013_10130602_49_dialog_content = "No puedes renunciar todavía.",
  ui_story_1013_10130602_50_dialog_content = "¡Todo ha cambiado de nuevo!",
  ui_story_1013_10130602_51_dialog_content = "¡Hay hordas de eclipses en la distancia!",
  ui_story_1013_10130602_52_dialog_content = "Y esas sombras en el cielo son... ¡Colosos!",
  ui_story_1013_10130602_53_dialog_content = "Eclipsitos montando colosos y luchando contra aurorianos...",
  ui_story_1013_10130602_54_dialog_content = "Los registros en el Obelisco del Retorno eran ciertos...",
  ui_story_1013_10130602_55_dialog_content = "Atención, todas las tropas de combate—",
  ui_story_1013_10130602_56_dialog_content = "¿Eso es una transmisión?",
  ui_story_1013_10130602_57_dialog_content = "Mantenga la línea y mantenga la resistencia.",
  ui_story_1013_10130602_58_dialog_content = "La humanidad debe derrotar a los demonios.",
  ui_story_1013_10130602_59_option_content = "¿\"Demonios\"?",
  ui_story_1013_10130602_60_dialog_content = "Alguien estaba gritando sobre demonios antes. ¿Se referían a los eclipses?",
  ui_story_1013_10130602_61_option_content = "\"Humanidad\"?",
  ui_story_1013_10130602_62_dialog_content = "¿Qué es la \"humanidad\"? ¿No se supone que son \"Aurorianos\"?",
  ui_story_1013_10130602_63_dialog_content = "¿Todos escucharon eso? ¡Debemos mantenernos firmes!",
  ui_story_1013_10130602_64_dialog_content = "¡Mantenga la línea! ¡Por nuestra patria!",
  ui_story_1013_10130602_65_dialog_content = "¡No, espera! ¡Regresar!",
  ui_story_1013_10130602_66_dialog_content = "No eres lo suficientemente fuerte para luchar contra los Eclipsites. ¡Es una misión suicida!",
  ui_story_1013_10130602_67_dialog_content = "¡Si no estás peleando, sal del camino!",
  ui_story_1013_10130602_68_dialog_content = "¡Cobrar! ¡Mata a los eclipses! ¡Acaba con los demonios!",
  ui_story_1013_10130602_69_dialog_content = "Defender su posición. Ni un paso atrás.",
  ui_story_1013_10130602_70_dialog_content = "La humanidad debe salir victoriosa.",
  ui_story_1013_10130602_71_dialog_content = "Grah!!!",
  ui_story_1013_10130602_72_dialog_content = "¡Urgh...!",
  ui_story_1013_10130602_73_dialog_content = "¡No podemos... retroceder!",
  ui_story_1013_10130602_74_dialog_content = "¡¡¡Basta!!!",
  ui_story_1013_10130602_75_dialog_content = "Continúa luchando. ¡Perseverar!",
  ui_story_1013_10130602_76_dialog_content = "¿Qué diablos está tratando de hacer ese locutor? ¿Cómo pueden enviar gente a la muerte tan fácilmente?",
  ui_story_1013_10130602_77_dialog_content = "<color=#e8d9bb>Tzzst—</color>",
  ui_story_1013_10130602_78_dialog_content = "Cargando... grabar...",
  ui_story_1013_10130602_79_dialog_content = "¡Ese es el simulador de campo de batalla!",
  ui_story_1013_10130602_80_dialog_content = "¿Ha recuperado finalmente sus funciones?",
  ui_story_1013_10130602_81_dialog_content = "Campaña...: ... inminente.",
  ui_story_1013_10130602_82_dialog_content = "Batalla... número de serie: Error.",
  ui_story_1013_10130602_83_dialog_content = "Objetivo: Retirada... terreno seguro.",
  ui_story_1013_10130602_84_dialog_content = "¿Retiro? Hay eclipses por todas partes. ¿Adónde debo retirarme?",
  ui_story_1013_10130602_85_dialog_content = "¡Tú allí!",
  ui_story_1013_10130602_86_dialog_content = "Corre de esa manera. Es seguro allá atrás. Los soldados te protegerán.",
  ui_story_1013_10130602_87_dialog_content = "Y no te rindas. ¡La humanidad prevalecerá sobre los demonios!",
  ui_story_1013_10130602_88_dialog_content = "Supongo que debería correr en la dirección opuesta de donde vienen los eclipses.",
  ui_story_1013_10130602_89_dialog_content = "Battlefield Simulator es tan realista que casi lo olvido...",
  ui_story_1013_10130602_90_dialog_content = "que todo lo que estoy viendo ahora es un registro del pasado.",
  ui_story_1013_10130602_91_dialog_content = "Y eso significa que no hay forma de que pueda cambiar nada.",
  ui_story_1013_10130602_92_dialog_content = "Todo lo que puedo hacer es terminar la etapa para que todo termine.",
  ui_story_1013_10130602_93_dialog_content = "Simulador inicializando...",
  ui_story_1013_10130701_1_dialog_content = "Resoplan...",
  ui_story_1013_10130701_2_dialog_content = "(No tengo idea de en qué dirección debería correr).",
  ui_story_1013_10130701_3_dialog_content = "(Pero seguir a estos soldados debería estar bien).",
  ui_story_1013_10130701_4_dialog_content = "¡Eh, tú allí! Cúbrete aquí abajo.",
  ui_story_1013_10130701_5_dialog_content = "¡E-está bien!",
  ui_story_1013_10130701_6_dialog_content = "¿Ah?",
  ui_story_1013_10130701_7_dialog_content = "(Hay algunas personas allá arriba que no están corriendo).",
  ui_story_1013_10130701_8_dialog_content = "(¿Están heridos?)",
  ui_story_1013_10130701_9_dialog_content = "Repito: ¡Sigan luchando y sigan adelante!",
  ui_story_1013_10130701_10_dialog_content = "Hola, ¿hay alguien herido? ¿Alguien necesita ayuda?",
  ui_story_1013_10130701_11_dialog_content = "Es demasiado peligroso aquí. ¡Te llevaré a un lugar seguro!",
  ui_story_1013_10130701_12_dialog_content = "¿Eh? Qué...?",
  ui_story_1013_10130701_13_dialog_content = "(Esa extraña aura de arco iris en la que están envueltos es del mismo color que Lumina).",
  ui_story_1013_10130701_14_dialog_content = "(¿Podrían... ser aurorianos?)",
  ui_story_1013_10130701_15_dialog_content = "El Dios de la Luz no nos concede la aurora aeterna: una vida libre de dolores y preocupaciones.",
  ui_story_1013_10130701_16_dialog_content = "El Dios de la Luz no nos concede días eternos: un mundo libre de guerras y disturbios.",
  ui_story_1013_10130701_17_dialog_content = "El Dios de la Luz nos otorga fuerza y coraje, sabiduría e ingenio, y compasión por todos...",
  ui_story_1013_10130701_18_dialog_content = "para que podamos enfrentar nuestras dificultades con valor infinito, sabiduría suprema y amor imperecedero.",
  ui_story_1013_10130701_19_dialog_content = "(Parece que están orando, pero ¿a quién y para qué?)",
  ui_story_1013_10130701_20_dialog_content = "<color=#e8d9bb>Auge-!!!</color>",
  ui_story_1013_10130701_21_dialog_content = "La batalla se está expandiendo rápidamente. Todo el personal, siga las instrucciones y retírese a un lugar seguro.",
  ui_story_1013_10130701_22_dialog_content = "Esta es la última advertencia. Evacue todas las áreas donde puedan aparecer los demonios.",
  ui_story_1013_10130701_23_dialog_content = "Grah!!!",
  ui_story_1013_10130701_24_dialog_content = "Mierda, tengo que darme prisa—",
  ui_story_1013_10130701_25_dialog_content = "Graah-!",
  ui_story_1013_10130701_26_dialog_content = "Los enviados de la Luz nunca deben temer a la oscuridad.",
  ui_story_1013_10130701_27_dialog_content = "Nos quedamos aquí para obligar a los demonios nacidos de la oscuridad a retirarse.",
  ui_story_1013_10130701_28_dialog_content = "¡Niño, ve, rápido! No dejes que te atrapen. Ya han muerto demasiados.",
  ui_story_1013_10130701_29_option_content = "No, puedo ayudarte.",
  ui_story_1013_10130701_30_dialog_content = "Si estás dispuesto a confiar en mí y permitirme hacer contacto con tu conciencia...",
  ui_story_1013_10130701_31_dialog_content = "Soy capaz de navegar aurorianos en la batalla. ¡Déjame ayudarte para que puedas usar mejor tu poder y aprovechar la oportunidad de la victoria!",
  ui_story_1013_10130701_32_option_content = "No, tienes que venir conmigo.",
  ui_story_1013_10130701_33_dialog_content = "Esta no es una batalla que cuatro Aurorianos puedan ganar solos.",
  ui_story_1013_10130701_34_dialog_content = "Ven conmigo para encontrar un lugar donde refugiarnos. No tenemos otra opción.",
  ui_story_1013_10130701_35_dialog_content = "¿\"Aurorianos\"? no tengo ni idea de lo que hablas...",
  ui_story_1013_10130701_36_dialog_content = "Este no es lugar para un niño. ¡Ponte a salvo!",
  ui_story_1013_10130701_37_dialog_content = "Ah, ¿¡y no eres un niño!?",
  ui_story_1013_10130701_38_dialog_content = "No se puede determinar la edad de un Enviado de la Luz por su apariencia.",
  ui_story_1013_10130701_39_dialog_content = "Solo aquellos expertos en el uso de Lumina pueden resistir y luchar aquí.",
  ui_story_1013_10130701_40_dialog_content = "En momentos como este, debemos <color=#FFB400>seguir devotamente</color> las enseñanzas del Dios de la Luz.",
  ui_story_1013_10130701_41_dialog_content = "Te refieres a...",
  ui_story_1013_10130701_42_dialog_content = "Acordado. Ya no podemos usar ninguna de nuestras preocupaciones como excusa para abstenernos de usar el poder en nuestras palmas.",
  ui_story_1013_10130701_43_dialog_content = "Mantente alejado, chico, si no quieres ser arrastrado por una ola de luz.",
  ui_story_1013_10130701_44_dialog_content = "Muy bien. Me temo que nos arrepentiremos si no lo hacemos.",
  ui_story_1013_10130701_45_dialog_content = "Los demonios se acercan rápidamente desde allí.",
  ui_story_1013_10130701_46_dialog_content = "Aprovechemos este último rayo de luz.",
  ui_story_1013_10130701_47_dialog_content = "¡La luz nos pertenece!",
  ui_story_1013_10130701_48_dialog_content = "¡E-Qué Lumina tan fuerte!",
  ui_story_1013_10130701_49_dialog_content = "Graaaaah—",
  ui_story_1013_10130701_50_dialog_content = "¡Ahhhhhhhh!",
  ui_story_1013_10130701_51_dialog_content = "Qué-",
  ui_story_1013_10130701_52_dialog_content = "(Se suponía que iban a ganar la partida, pero esto... todo lo que veo ante mí es una escena de una pesadilla).",
  ui_story_1013_10130701_53_dialog_content = "(¡Los rayos de luz están matando a todos, Eclipsitas y Aurorianos por igual!)",
  ui_story_1013_10130701_54_dialog_content = "(No puedo aguantar. ¿Significa esto... que yo también lo haré...)",
  ui_story_1013_10130701_55_dialog_content = "<color=#e8d9bb>¡BOOM!</color>",
  ui_story_1013_10130701_56_dialog_content = "Resoplan...",
  ui_story_1013_10130701_57_dialog_content = "Buzz Buzz-",
  ui_story_1013_10130701_58_dialog_content = "¿Se... se acabó?",
  ui_story_1013_10130701_59_option_content = "¡Potencia de fuerza!",
  ui_story_1013_10130701_60_dialog_content = "Ya no puedo sentir Darkflow. Sólo un silencio de muerte.",
  ui_story_1013_10130701_61_dialog_content = "¿Fue así como el mundo de antes llegó a su fin?",
  ui_story_1013_10130701_62_dialog_content = "¡Espera!",
  ui_story_1013_10130701_63_dialog_content = "¡Algo está saliendo del suelo!",
  ui_story_1013_10130701_64_dialog_content = "<color=#e8d9bb>Crujido-</color>",
  ui_story_1013_10130701_65_dialog_content = "Silbido-!!!",
  ui_story_1013_10130701_66_dialog_content = "¡Oh, no!",
  ui_story_1013_10130701_67_dialog_content = "(¿Siempre estuvo ahí abajo? ¿Eso le permitió sobrevivir a la catástrofe?)",
  ui_story_1013_10130701_68_dialog_content = "(¡Lo terminaré!)",
  ui_story_1013_10130702_1_dialog_content = "Silbido-!!!",
  ui_story_1013_10130702_2_dialog_content = "¡No puedo vencerlo!",
  ui_story_1013_10130702_3_dialog_content = "Su cuerpo parece estar cada vez más grande.",
  ui_story_1013_10130702_4_dialog_content = "Pero los eclipses no pueden regenerarse en el acto de esa manera. ¿Es un error de simulación?",
  ui_story_1013_10130702_5_dialog_content = "Hiss-",
  ui_story_1013_10130702_6_dialog_content = "Lo que sea que esté pasando, necesito contactar a los investigadores.",
  ui_story_1013_10130702_7_dialog_content = "¡No moriré aquí!",
  ui_story_1013_10130702_8_dialog_content = "¡Investigadores! ¿Copias? ¡Por favor responde!",
  ui_story_1013_10130702_9_dialog_content = "Repito: ¡Investigadores! ¿Copias? ¡Por favor responde!",
  ui_story_1013_10130702_10_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10130702_11_dialog_content = "Q-que puedo hacer...",
  ui_story_1013_10130702_12_dialog_content = "¿Qué más puedo probar?",
  ui_story_1013_10130702_13_dialog_content = "<color=#e8d9bb>Grieta-</color>",
  ui_story_1013_10130702_14_dialog_content = "¿Estoy... realmente voy a morir aquí?",
  ui_story_1013_10130702_15_dialog_content = "Yo—",
  ui_story_1013_10130702_16_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_1013_10130702_17_dialog_content = "\"Sistema de control primario... normal\".",
  ui_story_1013_10130702_18_dialog_content = "\"Módulos biológicos... normales\".",
  ui_story_1013_10130702_19_dialog_content = "\"Soporte vital... operativo. Capacidad actual: 1 persona\".",
  ui_story_1013_10130702_20_dialog_content = "\"Generador... normal. Intento de inicio...\"",
  ui_story_1013_10130702_21_dialog_content = "¡Soroz!",
  ui_story_1013_10130702_22_dialog_content = "Estoy aquí, PlayerName. Yo siempre estoy aquí.",
  ui_story_1013_10130702_23_dialog_content = "\"Mantenerte con vida y a salvo es mi máxima prioridad\". ¿Recuerda?",
  ui_story_1013_10130702_24_dialog_content = "Esto podría ser un mundo virtual...",
  ui_story_1013_10130702_25_dialog_content = "pero eso no significa que pueda dejar que te lastimen.",
  ui_story_1013_10130702_26_dialog_content = "Intenta cortar tu vínculo conmigo. Y luego... confía en mí.",
  ui_story_1013_10130702_27_dialog_content = "\"Sistema de piloto automático lanzado... Objetivo: Regresar a la realidad\".",
  ui_story_1013_10130702_28_dialog_content = "Ngnh...",
  ui_story_1013_10130702_29_dialog_content = "Funcionó... Soroz...",
  ui_story_1013_10130702_30_dialog_content = "PlayerName... PlayerName ¡está despierto!",
  ui_story_1013_10130702_31_dialog_content = "PlayerName¡Finalmente estás despierto!",
  ui_story_1013_10130702_32_dialog_content = "¡El niño está consciente de nuevo! Mantenga sus vías respiratorias abiertas.",
  ui_story_1013_10130702_33_dialog_content = "Active el escáner de exámenes médicos del centro de investigación.",
  ui_story_1013_10130702_34_dialog_content = "¿Qué estás... Espera! Estoy bien, no estoy herido.",
  ui_story_1013_10130702_35_dialog_content = "¿Qué pasa con Soroz?",
  ui_story_1013_10130702_36_dialog_content = "No podemos confiar en su conciencia subjetiva para decirnos si está herido o no.",
  ui_story_1013_10130702_37_dialog_content = "Los resultados estarán disponibles en poco tiempo. Por favor, quédese quieto durante cinco minutos.",
  ui_story_1013_10130702_38_dialog_content = "¿¡Cómo es que nunca me dijiste que el simulador podría fallar así!?",
  ui_story_1013_10130702_39_dialog_content = "Sé que bromeo sobre abrirte, pero aún conozco la línea entre las bromas y la realidad.",
  ui_story_1013_10130702_40_dialog_content = "No teníamos intención de ponerte en peligro. El centro de investigación asumirá toda la responsabilidad por este incidente.",
  ui_story_1013_10130702_41_dialog_content = "Investigaré a los investigadores que compilaron los datos del antiguo campo de batalla y ejecutaré un nuevo conjunto de pruebas en el simulador.",
  ui_story_1013_10130702_42_dialog_content = "Además, pasa mi pedido:",
  ui_story_1013_10130702_43_dialog_content = "El Illumina Research Center cubrirá PlayerNameLos costos de mantenimiento de Colossus para los próximos tres meses.",
  ui_story_1013_10130702_44_dialog_content = "Qué dices, PlayerName?",
  ui_story_1013_10130702_45_dialog_content = "Supongo que eso funciona...",
  ui_story_1013_10130702_46_dialog_content = "Hmm, creo que el problema es que la tecnología que usamos para vincular el Colossus y el simulador todavía está inmadura.",
  ui_story_1013_10130702_47_dialog_content = "Esa regeneración de Jormungand era indicativa del hecho de que estabas atrapado en datos corruptos del pasado.",
  ui_story_1013_10130702_48_dialog_content = "Así que ustedes pudieron ver todo como sucedió...",
  ui_story_1013_10130702_49_dialog_content = "Al final, Soroz cortó el enlace con el simulador y me sacó.",
  ui_story_1013_10130702_50_dialog_content = "Entonces, ¿cómo está Soroz?",
  ui_story_1013_10130702_51_dialog_content = "Los resultados están listos. ¡Felicitaciones, sujeto de prueba! Todo parece normal.",
  ui_story_1013_10130702_52_dialog_content = "¿Alguien me dirá cómo es Soroz?",
  ui_story_1013_10130702_53_dialog_content = "Soroz...",
  ui_story_1013_10130702_54_dialog_content = "Soroz pagó el precio por romper la conexión de esa manera.",
  ui_story_1013_10130702_55_dialog_content = "Su conciencia permaneció en el sistema del simulador de campo de batalla.",
  ui_story_1013_10130702_56_dialog_content = "Sé que te parece cruel. Pero este tipo de situación es común durante la experimentación.",
  ui_story_1013_10130702_57_dialog_content = "Su conciencia en este momento se encuentra en un estado complicado: su personalidad ha sido despojada de sus recuerdos.",
  ui_story_1013_10130702_58_dialog_content = "Los recuerdos de Soroz ahora toman la forma de pura información. Su personalidad ha retrocedido a una pizarra en blanco.",
  ui_story_1013_10130702_59_dialog_content = "Cuando ocurrió esa regresión, Soroz pudo sacarlo de manera segura, pero perdió esa parte de su funcionalidad.",
  ui_story_1013_10130702_60_dialog_content = "!",
  ui_story_1013_10130702_61_dialog_content = "¿Qué quieres decir... ¿Qué significa esto?",
  ui_story_1013_10130702_62_dialog_content = "Justo lo que pensarías.",
  ui_story_1013_10130702_63_dialog_content = "¿Ustedes llaman a esto un pequeño problema?",
  ui_story_1013_10130702_64_option_content = "¡Potencia de fuerza!",
  ui_story_1013_10130702_65_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10130702_66_option_content = "Impulso de fuerza !!",
  ui_story_1013_10130702_67_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10130702_68_option_content = "Impulso de fuerza!!!",
  ui_story_1013_10130702_69_dialog_content = "No desperdicies tu fuerza, PlayerName.",
  ui_story_1013_10130702_70_dialog_content = "No podrás controlarlo en este momento.",
  ui_story_1013_10130702_71_dialog_content = "Seguiremos intentando restaurar su conciencia. Como mínimo intentaremos restaurar sus funciones.",
  ui_story_1013_10130702_72_dialog_content = "¿Qué significa eso?",
  ui_story_1013_10130702_73_dialog_content = "¿Cómo puede ser \"funcional\" sin su personalidad o recuerdos?",
  ui_story_1013_10130702_74_dialog_content = "¿Qué crees que estás haciendo? ¡¿No se supone que ustedes deben asumir toda la responsabilidad por esto?!",
  ui_story_1013_10130702_75_dialog_content = "Sí, Gran Mariscal. El centro de investigación asumirá toda la responsabilidad de restaurar la conciencia del Coloso.",
  ui_story_1013_10130702_76_dialog_content = "Sin embargo, sujeto de prueba, debemos recordar no hacer amigos con nuestra tecnología. Son solo herramientas para servirnos y ayudarnos en la investigación.",
  ui_story_1013_10130702_77_dialog_content = "Cuando el Coloso perdió el conocimiento, su sistema perdió estabilidad...",
  ui_story_1013_10130702_78_dialog_content = "pero mientras podamos ponerlo en marcha, no importa si su personalidad está inactiva o perdida.",
  ui_story_1013_10130702_79_dialog_content = "¡No toques a Soroz! ¡Soroz es mi amigo, mi mentor y mi única familia!",
  ui_story_1013_10130702_80_dialog_content = "Por favor calmate, PlayerName. Te prometo que nuestro trabajo no lo dañará.",
  ui_story_1013_10130702_81_dialog_content = "¡Ya lo estás dañando!",
  ui_story_1013_10130702_82_dialog_content = "<color=#e8d9bb>TOC Toc</color>",
  ui_story_1013_10130702_83_dialog_content = "Los laboratorios deben estar en silencio. Por favor, mantén el ruido bajo.",
  ui_story_1013_10130702_84_dialog_content = "Vaya...?",
  ui_story_1013_10130702_85_dialog_content = "Gran Mariscal, Oficial de Inteligencia Yingel de la <color=#FFB400>Consejo de Ciencias</color>, informes.",
  ui_story_1013_10130702_86_dialog_content = "¿El Consejo de Ciencias? Así que han reclutado en secreto a algunos recién llegados prometedores nuevamente.",
  ui_story_1013_10130702_87_dialog_content = "Gracias, Gran Mariscal. Creo que es la primera vez que nos vemos.",
  ui_story_1013_10130702_88_dialog_content = "Pero siento que te conozco bien.",
  ui_story_1013_10130702_89_dialog_content = "¡Ja ja! Todo el mundo en Illumina me conoce.",
  ui_story_1013_10130702_90_dialog_content = "Entonces, ¿para qué te envió el Consejo de Ciencias? ¿Para estudiar la Caelestita?",
  ui_story_1013_10130702_91_dialog_content = "El Consejo está a punto de celebrar una conferencia secreta. Sólo estoy aquí para pasar órdenes.",
  ui_story_1013_10130702_92_dialog_content = "Decir ah. Esos nerds de laboratorio finalmente han elegido mostrarse, ¿eh?",
  ui_story_1013_10130702_93_dialog_content = "El Consejo de Ciencias solicita, con sinceras intenciones, hablar en persona con Caelestite.",
  ui_story_1013_10130702_94_dialog_content = "¿Qué hay de mí?",
  ui_story_1013_10130702_95_dialog_content = "Eres bienvenido a asistir, naturalmente.",
  ui_story_1013_10130702_96_dialog_content = "Más bien, se le está ordenando que lo haga. Asista a la reunión junto con Caelestite.",
  ui_story_1013_10130702_97_dialog_content = "Supongo que eso significa que tengo aún menos derecho a declinar.",
  ui_story_1013_10130702_98_dialog_content = "Pero Soroz...",
  ui_story_1013_10130702_99_dialog_content = "Gronru y yo ordenaremos a los investigadores que detengan todo el trabajo en el Coloso hasta que regreses.",
  ui_story_1013_10130702_100_dialog_content = "¡No te preocupes, los vigilaré como un halcón!",
  ui_story_1013_10130702_101_dialog_content = "No te preocupes, PlayerName. Aún no nos hemos quedado sin soluciones.",
  ui_story_1013_10130702_102_dialog_content = "El Consejo de Ciencias podría brindarle más información sobre Soroz.",
  ui_story_1013_10130702_103_dialog_content = "... Entiendo.",
  ui_story_1013_10130702_104_dialog_content = "También tengo algunas preguntas sobre la antigua batalla que presencié.",
  ui_story_1013_10130702_105_dialog_content = "Tu cooperación es apreciada. Estoy seguro de que el Consejo de Ciencias responderá a sus preguntas lo mejor que pueda.",
  ui_story_1013_10130702_106_dialog_content = "¿Si ambos me siguieran?",
  ui_story_1013_10130801_1_dialog_content = "¿El Consejo de Ciencias?",
  ui_story_1013_10130801_2_dialog_content = "Sí. Reportan directamente a los más altos poderes de Illumina...",
  ui_story_1013_10130801_3_dialog_content = "Sus miembros clave están dispersos por todo Illumina. Solo en momentos de crisis se reúnen para una reunión secreta.",
  ui_story_1013_10130801_4_dialog_content = "Sé que todo suena un poco aterrador. Pero cada miembro del Consejo tiene acceso a los mayores secretos de Illumina.",
  ui_story_1013_10130801_5_dialog_content = "Es por eso que mantienen sus identidades en secreto.",
  ui_story_1013_10130801_6_dialog_content = "La última vez que se revelaron fue para votar cuando estaba cambiando la cúpula militar.",
  ui_story_1013_10130801_7_dialog_content = "Espera, ¿no era eso...?",
  ui_story_1013_10130801_8_dialog_content = "¿Cuándo me nombraron? Sí, en realidad.",
  ui_story_1013_10130801_9_dialog_content = "Suena muy misterioso. Lo que explica por qué nunca he oído hablar de ellos.",
  ui_story_1013_10130801_10_dialog_content = "¿Si pudiera darse prisa?",
  ui_story_1013_10130801_11_dialog_content = "Ja ja. Oyes eso, PlayerName? Vamos, vamos a alcanzarla.",
  ui_story_1013_10130801_12_dialog_content = "(Eso es impresionante. Incluso un simple oficial de inteligencia del Consejo Científico tiene la audacia de dar órdenes al Gran Mariscal).",
  ui_story_1013_10130801_13_dialog_content = "Todavía te ves nervioso.",
  ui_story_1013_10130801_14_dialog_content = "Yo no diría nervioso. Soy más... cauteloso.",
  ui_story_1013_10130801_15_dialog_content = "Nada de lo que me has dicho me ayuda a entender por qué de repente necesitan reunirse conmigo.",
  ui_story_1013_10130801_16_dialog_content = "¿Es por Vice y Barton? ¿O se trata del Obelisco del Retorno?",
  ui_story_1013_10130801_17_dialog_content = "Solo te estás volviendo loco haciendo conjeturas descabelladas como esa.",
  ui_story_1013_10130801_18_dialog_content = "Los miembros del Consejo tienen mucho poder y no actúan arbitrariamente.",
  ui_story_1013_10130801_19_dialog_content = "Si te han invitado a una reunión, significa que te explicarán todo y tratarán de ganarse tu confianza.",
  ui_story_1013_10130801_20_dialog_content = "Además, pueden estar a cargo de administrar toda la inteligencia de Illumina, pero al final del día, son solo un grupo de nerds de la ciencia.",
  ui_story_1013_10130801_21_dialog_content = "Incluso podrían ayudarlo a encontrar una manera de restaurar la personalidad de Soroz.",
  ui_story_1013_10130801_22_dialog_content = "—Si algo de eso te hace sentir mejor.",
  ui_story_1013_10130801_23_dialog_content = "... Gracias, Reinhardt.",
  ui_story_1013_10130801_24_dialog_content = "Hemos llegado.",
  ui_story_1013_10130801_25_dialog_content = "Por favor regístrese en la entrada.",
  ui_story_1013_10130801_26_dialog_content = "Y no se preocupe, la información que proporcione solo se utilizará para registrar su entrada y salida.",
  ui_story_1013_10130801_27_dialog_content = "(Wow, realmente son reservados).",
  ui_story_1013_10130801_28_dialog_content = "<color=#e8d9bb>bip—bip—</color>",
  ui_story_1013_10130801_29_dialog_content = "He ingresado el código de acceso para la puerta. Por favor entra.",
  ui_story_1013_10130801_30_dialog_content = "¿Por qué no invitamos a gente del centro de investigación o de Black Umbrella Laboratories? Incluso el teniente antivicio sería una mejor opción.",
  ui_story_1013_10130801_31_dialog_content = "No sabemos dónde se encuentra Caelestite. Y él es el único con esa genial habilidad psíquica sobre tecnología antigua.",
  ui_story_1013_10130801_32_dialog_content = "El genio lo está exagerando. Pero él es el único Caelestite de sangre pura sobreviviente que conocemos.",
  ui_story_1013_10130801_33_dialog_content = "Bueno, hasta que lo vea con mis propios ojos, asumo que esta \"habilidad psíquica\" es solo una tontería.",
  ui_story_1013_10130801_34_dialog_content = "Incluso un reloj parado acierta dos veces al día.",
  ui_story_1013_10130801_35_dialog_content = "Tendré en cuenta tus pensamientos.",
  ui_story_1013_10130801_36_dialog_content = "Muy bien, están aquí.",
  ui_story_1013_10130801_37_dialog_content = "<color=#e8d9bb>*Sonido de golpe*</color>",
  ui_story_1013_10130801_38_dialog_content = "La última Caelestita, PlayerName, es aquí.",
  ui_story_1013_10130801_39_dialog_content = "Acompañado por el Gran Mariscal Reinhardt.",
  ui_story_1013_10130801_40_dialog_content = "Esplendor Illumina.",
  ui_story_1013_10130801_41_dialog_content = "Esplendor Illumina.",
  ui_story_1013_10130801_42_dialog_content = "PlayerName, puedes sentarte a mi lado.",
  ui_story_1013_10130801_43_dialog_content = "Por favor, ¿la Caelestita podría sentarse a la izquierda de Ulises? Frente a la pantalla.",
  ui_story_1013_10130801_44_dialog_content = "Y Reinhardt, puedes pararte junto a él.",
  ui_story_1013_10130801_45_dialog_content = "Barrett, parece que te gusta estar a cargo de la disposición de los asientos hoy.",
  ui_story_1013_10130801_46_dialog_content = "Bueno, solo podemos acomodar a un cierto número de personas. Alguien tiene que hacerse cargo de la logística.",
  ui_story_1013_10130801_47_dialog_content = "Gracias por asistir a nuestra reunión.",
  ui_story_1013_10130801_48_dialog_content = "Siguiendo reglas estrictas, podemos ahorrarnos una gran cantidad de tiempo.",
  ui_story_1013_10130801_49_dialog_content = "Eso incluye tanto las reglas escritas como las que no están escritas.",
  ui_story_1013_10130801_50_dialog_content = "Por favor, tome asiento, Caelestite.",
  ui_story_1013_10130801_51_dialog_content = "Hola señor.",
  ui_story_1013_10130801_52_dialog_content = "Permítanme hacer algunas presentaciones. A su derecha está el profesor Ulysses, biólogo.",
  ui_story_1013_10130801_53_dialog_content = "Frente al profesor está el Sr. Joyce, nuestro físico.",
  ui_story_1013_10130801_54_dialog_content = "Junto al Gran Mariscal Reinhardt está la señorita Barrett, una ingeniera.",
  ui_story_1013_10130801_55_dialog_content = "Y luego.",
  ui_story_1013_10130801_56_dialog_content = "Señorita Algol, por favor despierte...",
  ui_story_1013_10130801_57_dialog_content = "Huh-Oh, lo siento. Mi tiempo es limitado, ya sabes.",
  ui_story_1013_10130801_58_dialog_content = "Ponerse al día con el sueño es un uso mucho más eficiente del tiempo que escuchar la disposición de los asientos.",
  ui_story_1013_10130801_59_dialog_content = "Hola—",
  ui_story_1013_10130801_60_dialog_content = "Soy Algol, a cargo de la inteligencia artificial. El robot en mi hombro es Bool.",
  ui_story_1013_10130801_61_dialog_content = "Estoy seguro de que tú y yo disfrutaremos hablando, siempre y cuando no despertemos a Bool.",
  ui_story_1013_10130801_62_dialog_content = "N-Encantado de conocerte.",
  ui_story_1013_10130801_63_dialog_content = "Si no hay objeciones, ¿empezamos?",
  ui_story_1013_10130801_64_dialog_content = "Antes de que nos pongamos manos a la obra, puede que sea más eficaz abordar primero sus preguntas.",
  ui_story_1013_10130801_65_dialog_content = "Por favor, limítelo a tres como máximo.",
  ui_story_1013_10130801_66_dialog_content = "PlayerName acaba de terminar una sesión de prueba en el simulador de campo de batalla en el centro de investigación.",
  ui_story_1013_10130801_67_dialog_content = "Él tiene una serie de preguntas para usted.",
  ui_story_1013_10130801_68_dialog_content = "Gracias por contribuir, Reinhardt.",
  ui_story_1013_10130801_69_dialog_content = "Entonces, ¿puedo invitar a Caelestita a hablar ahora?",
  ui_story_1013_10130801_70_dialog_content = "... Sé mi invitado.",
  ui_story_1013_10130801_71_option_content = "Pregunte acerca de los \"demonios\".",
  ui_story_1013_10130801_72_dialog_content = "¿Todo eso realmente sucedió? Me refiero a las cosas que vi en la simulación.",
  ui_story_1013_10130801_73_dialog_content = "Vi aurorianos usando Luminatics en una antigua batalla.",
  ui_story_1013_10130801_74_dialog_content = "¿Y lo que llamaban \"demonios\"... eran...?",
  ui_story_1013_10130801_75_dialog_content = "Esos eventos de hecho sucedieron.",
  ui_story_1013_10130801_76_dialog_content = "Antes de los aurorianos y caelestitas, esta tierra estuvo habitada por nuestros ancestros lejanos.",
  ui_story_1013_10130801_77_dialog_content = "Y se llamaban a sí mismos \"humanidad\", ¿verdad?",
  ui_story_1013_10130801_78_dialog_content = "Exactamente. Se parecían a nosotros y usaban tecnología como nosotros... y algunos de ellos también se entregaron a la fe como nosotros.",
  ui_story_1013_10130801_79_dialog_content = "Pero no tenían poderes especiales.",
  ui_story_1013_10130801_80_dialog_content = "(Entonces... ¿por eso todo lo que podían hacer era huir de los \"demonios\"?)",
  ui_story_1013_10130801_81_dialog_content = "Déjame tratar de hacerlo fácil de entender.",
  ui_story_1013_10130801_82_dialog_content = "Los más dotados de nuestros antepasados evolucionaron para convertirse en aurorianos.",
  ui_story_1013_10130801_83_dialog_content = "Pero otros sucumbieron a las tentaciones ofrecidas por los \"demonios\".",
  ui_story_1013_10130801_84_dialog_content = "Pero, ¿qué eran esos \"demonios\"?",
  ui_story_1013_10130801_85_dialog_content = "¿Eran eclipses de alto nivel? ¿Aurorianos? ¿O Caelestitas?",
  ui_story_1013_10130801_86_dialog_content = "El centro de investigación aún está trabajando para encontrar la respuesta a esa pregunta, por lo que no tengo una respuesta para usted en este momento.",
  ui_story_1013_10130801_87_dialog_content = "¿Quieres decir que no has hecho ningún progreso desde nuestra última reunión? ¿Después de todo este tiempo?",
  ui_story_1013_10130801_88_dialog_content = "El origen de los \"demonios\", cómo evolucionaron, su impacto en nuestra historia... necesitamos estudiar estos asuntos con mucho cuidado.",
  ui_story_1013_10130801_89_dialog_content = "Estas no son preguntas que puedan responderse con unas pocas batallas simuladas.",
  ui_story_1013_10130801_90_dialog_content = "...",
  ui_story_1013_10130801_91_dialog_content = "Al final, Caelestites y Eclipsites, controlados por demonios, libraron una batalla decisiva contra los aurorianos.",
  ui_story_1013_10130801_92_dialog_content = "Esta parte de la historia no es un secreto para los que están sentados alrededor de esta mesa.",
  ui_story_1013_10130801_93_dialog_content = "Entonces, después de eso, el mundo de nuestros antepasados fue destruido. Los Eclipsites regresaron a la Zona Oscura y los Caelestites desaparecieron.",
  ui_story_1013_10130801_94_dialog_content = "Los Aurorianos sobrevivientes construyeron una nueva civilización y lucharon contra los Eclipsitas que los demonios habían dejado atrás.",
  ui_story_1013_10130801_95_dialog_content = "¿Está bien?",
  ui_story_1013_10130801_96_dialog_content = "No hemos confirmado esto. Pero nuestros puntos de vista actuales están ampliamente en línea con su hipótesis, sí.",
  ui_story_1013_10130801_96X1_dialog_content = "Espere por favor.",
  ui_story_1013_10130801_97_dialog_content = "<color=#e8d9bb>Escofina—Crujido</color>",
  ui_story_1013_10130801_98_dialog_content = "(¿Una bebida? Estas personas no han cambiado en absoluto).",
  ui_story_1013_10130801_99_dialog_content = "(Esas pequeñas señales que se envían entre sí solo engañarían a un recién llegado como PlayerName.)",
  ui_story_1013_10130801_100_dialog_content = "¿Te gustaría probar uno, Caelestite? Es un nuevo tipo de bebida que está de moda en Illumina.",
  ui_story_1013_10130801_100X1_dialog_content = "(¡¿D-De dónde vienes?!)",
  ui_story_1013_10130801_100X2_dialog_content = "Barrett, veo que has decidido aparecer por una vez.",
  ui_story_1013_10130801_100X3_dialog_content = "Sí, estoy un poco interesado en este Caelestite.",
  ui_story_1013_10130801_100X4_dialog_content = "Pero los otros pueden no sentir lo mismo.",
  ui_story_1013_10130801_100X5_dialog_content = "Fueron <color=#FFB400>observando</color> tú, haz lo mejor que puedas, Caelestite.",
  ui_story_1013_10130801_101_dialog_content = "... Yo lo haré.",
  ui_story_1013_10130801_102_option_content = "Pregunta por los antiguos aurorianos.",
  ui_story_1013_10130801_103_dialog_content = "Entonces, ¿cómo desarrollaron esos ancestros \"dotados\" el poder de la Luminática?",
  ui_story_1013_10130801_104_dialog_content = "En las escenas que vi, solo estaban rezando a la luz.",
  ui_story_1013_10130801_105_dialog_content = "¿Es esa la fuente de la fe de Lumopolis?",
  ui_story_1013_10130801_106_dialog_content = "Ja, este no es el lugar para hacer esa pregunta, jovencito.",
  ui_story_1013_10130801_107_dialog_content = "¡Lo siento!",
  ui_story_1013_10130801_108_dialog_content = "Hay muchos Aurorianos en nuestro mundo. Pero pocos de ellos conocen la verdadera naturaleza de la Luminática.",
  ui_story_1013_10130801_109_dialog_content = "Los aurorianos prefieren apegarse a las explicaciones que son más fáciles de entender.",
  ui_story_1013_10130801_110_dialog_content = "Por ejemplo, un regalo de un dios, o algo que se origina en una tierra sagrada, o un poder adquirido al darse cuenta de alguna \"verdad\"...",
  ui_story_1013_10130801_111_dialog_content = "Pero en esencia, es una habilidad, una habilidad para usar <color=#FFB400>vitalidad</color> a la energía directa.",
  ui_story_1013_10130801_112_dialog_content = "¿Vitalidad? Pero los Caelestitas...",
  ui_story_1013_10130801_113_dialog_content = "Caelestitas poseen vitalidad. Pero no puedes dominar el manejo de Luminatics.",
  ui_story_1013_10130801_114_dialog_content = "Mucho menos los Eclipsitos. Carecen de vitalidad y son totalmente incapaces de dirigir la energía.",
  ui_story_1013_10130801_115_dialog_content = "Pero, ¿cómo funciona exactamente esta habilidad?",
  ui_story_1013_10130801_116_dialog_content = "je. Bueno, en pocas palabras, es una aplicación práctica de Luminatics. Tome la Federación Illumina, por ejemplo.",
  ui_story_1013_10130801_117_dialog_content = "Usualmente usamos Luminatics <color=#FFB400>como actúa</color>, para conducir maquinaria y usar tecnología para controlar los efectos.",
  ui_story_1013_10130801_118_dialog_content = "Mientras tanto, en Lumopolis utilizan la fe pura para impulsar su vitalidad.",
  ui_story_1013_10130801_119_dialog_content = "Entonces ellos controlan la Luminática <color=#FFB400>en la fuente</color>.",
  ui_story_1013_10130801_120_dialog_content = "Esa es realmente la única diferencia entre Lumopolis e Illumina.",
  ui_story_1013_10130801_121_dialog_content = "¿La unica diferencia? Eso es un poco extremo.",
  ui_story_1013_10130801_122_dialog_content = "Y por favor, abstente de interrumpirme.",
  ui_story_1013_10130801_123_dialog_content = "(Todos estos científicos actúan amigablemente en la superficie, pero parecen tener una agresividad subyacente en ellos. ¿O me lo estoy imaginando?)",
  ui_story_1013_10130801_124_dialog_content = "Llevamos más de diez minutos hablando. Profesor Ulises, no olvide por qué estamos aquí.",
  ui_story_1013_10130801_125_dialog_content = "Gracias por recordarme. Pero como acordamos, a Caelestite todavía se le permite una pregunta más.",
  ui_story_1013_10130801_126_dialog_content = "Tan serio, Ulises. Has entrenado a la joven para que sea tan exigente con las reglas como tú.",
  ui_story_1013_10130801_127_dialog_content = "Yingel es uno de los alumnos prometedores modificados por el programa Phospherus. Es solo mi deber entrenarla apropiadamente.",
  ui_story_1013_10130801_128_dialog_content = "(¿¡Modificado!?)",
  ui_story_1013_10130801_129_dialog_content = "(¿Es eso lo que han estado haciendo? <color=#FFB400>Modificando Aurorianos</color>!?)",
  ui_story_1013_10130801_130_dialog_content = "... ¡¿Es ese el experimento sobre el que has estado tan reservado?!",
  ui_story_1013_10130801_131_dialog_content = "¡Explíquense! ¿No se cerró el programa Phospherus hace años?",
  ui_story_1013_10130801_132_dialog_content = "Para ser precisos, el Comité realizó una votación sobre el cierre del programa.",
  ui_story_1013_10130801_133_dialog_content = "Pero el resultado no fue el que esperabas, Reinhardt.",
  ui_story_1013_10130801_134_dialog_content = "¡Entonces tendré que presentar otra propuesta para cerrarlo!",
  ui_story_1013_10130801_135_dialog_content = "¡No permitiré que mis soldados y ciudadanos sufran modificaciones experimentales!",
  ui_story_1013_10130801_136_dialog_content = "Por supuesto, Reinhardt. Puedes hacer lo que quieras.",
  ui_story_1013_10130801_137_dialog_content = "Tus poderes como Gran Mariscal te los otorga la gente de Illumina. Es justo que uses esos poderes para su beneficio.",
  ui_story_1013_10130801_138_dialog_content = "Pero eso debe esperar hasta que hayamos concluido esta reunión. ¿Si pudieras dejar hablar a Caelestita?",
  ui_story_1013_10130801_139_dialog_content = "(¿Qué está pasando? ¿Esto explica lo que le ha estado pasando a Vice?)",
  ui_story_1013_10130801_140_dialog_content = "(¿Cuántos Aurorianos han sido modificados en secreto sin su conocimiento? ¿Cuántos de ellos son mis compañeros?)",
  ui_story_1013_10130801_141_dialog_content = "(¡Fuerza de impulso!)",
  ui_story_1013_10130801_142_dialog_content = "No entrar en pánico, PlayerName. Cuento contigo para hacerles la pregunta.",
  ui_story_1013_10130801_143_dialog_content = "Pregúntele a Ulysses qué es exactamente lo que espera lograr con sus experimentos de modificación.",
  ui_story_1013_10130801_144_dialog_content = "Esto concierne al futuro de Vice y los demás, y este oficial de inteligencia aquí y sus compatriotas.",
  ui_story_1013_10130801_145_dialog_content = "Y quizás también... lo que pasó entonces...",
  ui_story_1013_10130801_146_dialog_content = "... Entiendo.",
  ui_story_1013_10130801_147_dialog_content = "Y puede que esté pensando demasiado en las cosas, pero sospecho que te están poniendo a prueba.",
  ui_story_1013_10130801_148_dialog_content = "Probandome?",
  ui_story_1013_10130801_149_dialog_content = "Sospecho que entre sus filas, todavía tienen que llegar a un consenso sobre algo.",
  ui_story_1013_10130801_150_dialog_content = "Necesitaban reunirse contigo primero antes de llegar a algún tipo de decisión en secreto.",
  ui_story_1013_10130801_151_dialog_content = "Es uno de sus viejos trucos. De todos modos, se hacen señas usando esas bebidas.",
  ui_story_1013_10130801_152_dialog_content = "Pero no te preocupes demasiado por eso. Sólo haz lo que tengas que hacer.",
  ui_story_1013_10130801_153_dialog_content = "O-Está bien.",
  ui_story_1013_10130801_154_dialog_content = "(¿Estaba usando su habilidad psíquica durante ese período de silencio?)",
  ui_story_1013_10130801_155_dialog_content = "(De todos modos, definitivamente es alguien a quien debemos vigilar de cerca).",
  ui_story_1013_10130801_156_dialog_content = "<color=#e8d9bb>Escofina—Crujido</color>",
  ui_story_1013_10130801_157_dialog_content = "(Jejeje... así que por fin reconoces el valor de Caelestite.)",
  ui_story_1013_10130801_158_option_content = "Pregunte acerca de los experimentos de modificación.",
  ui_story_1013_10130801_159_dialog_content = "¿Fue Helios también un producto de este programa Phospherus?",
  ui_story_1013_10130801_160_dialog_content = "¿Por qué...? ¿Por qué Illumina querría modificar los aurorianos?",
  ui_story_1013_10130801_161_dialog_content = "Helios? No esperaba que estuvieras tan bien informado.",
  ui_story_1013_10130801_162_dialog_content = "Dado esto, no tiene sentido engañarte. De hecho, he estado realizando tales experimentos.",
  ui_story_1013_10130801_163_dialog_content = "Yingel, que está aquí ante ustedes, fue uno de los productos más exitosos de la última ronda.",
  ui_story_1013_10130801_164_dialog_content = "Los Aurorianos modificados tienen la misma genética y características que los Aurorianos normales.",
  ui_story_1013_10130801_165_dialog_content = "Aunque, para ser sincero, su personalidad obstinada a veces es un poco problemática.",
  ui_story_1013_10130801_166_dialog_content = "¡Ese no es el punto! ¿Por qué harías tal cosa?",
  ui_story_1013_10130801_167_dialog_content = "Para Ilumina.",
  ui_story_1013_10130801_168_dialog_content = "Obviamente, es para Illumina. Debemos tener nuestro propio equipo de modificación.",
  ui_story_1013_10130801_169_dialog_content = "Al igual que Lumopolis tiene cañones, y Eraveil tiene dispositivos antiguos que fortalecen a los aurorianos.",
  ui_story_1013_10130801_170_dialog_content = "Illumina una vez exploró la Zona Oscura en busca de equipos similares, pero fue en vano.",
  ui_story_1013_10130801_171_dialog_content = "Todo lo que tiene Illumina es su ciudadanía leal. Y nuestra defensa se basa en los huesos de esos guerreros.",
  ui_story_1013_10130801_172_dialog_content = "Nuestra investigación en este campo representa la voluntad de nuestro pueblo.",
  ui_story_1013_10130801_173_dialog_content = "Cada tema que modificamos significa un inocente menos sacrificado.",
  ui_story_1013_10130801_174_dialog_content = "¡Absoluto sin sentido! ¿Qué pasa con los sujetos experimentales? ¿No son inocentes? ¿Los gustos de Helios no cuentan como sacrificios?",
  ui_story_1013_10130801_175_dialog_content = "<color=#e8d9bb>Escofina—Crujido</color>",
  ui_story_1013_10130801_176_dialog_content = "Sobre el tema de Helios...",
  ui_story_1013_10130801_177_dialog_content = "Ese lote de sujetos en realidad no formaba parte del programa Phospherus.",
  ui_story_1013_10130801_178_dialog_content = "Pertenece a una empresa diferente. Era solo un producto fallido de un experimento fallido.",
  ui_story_1013_10130801_179_dialog_content = "¿¡Un fracaso!?",
  ui_story_1013_10130801_180_dialog_content = "¿Arruinar la vida de un auroriano no significa nada más para ti que un fracaso experimental?",
  ui_story_1013_10130801_181_dialog_content = "Reinhardt, como benefactor de nuestros experimentos, realmente no tienes derecho a tomar la delantera moral.",
  ui_story_1013_10130801_182_dialog_content = "Difícilmente puedes decir que arruinamos su vida. Quizás era un camino más adecuado para él, ¿no?",
  ui_story_1013_10130801_183_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1013_10130801_184_dialog_content = "No puedo sentarme a través de esta reunión por más tiempo. Y Ulises, me temo que te has salido del camino de la razón.",
  ui_story_1013_10130801_185_dialog_content = "Creo que hemos oído suficiente. No tiene sentido continuar.",
  ui_story_1013_10130801_186_dialog_content = "¿Quieres terminar la reunión? Pero el Consejo de Ciencias apenas está comenzando.",
  ui_story_1013_10130801_187_dialog_content = "Puedes irte si te parece bien dejar a Caelestita aquí sola.",
  ui_story_1013_10130801_188_dialog_content = "Que...",
  ui_story_1013_10130801_189_dialog_content = "No te atreverías.",
  ui_story_1013_10130801_190_dialog_content = "Relax. Somos gente educada. No somos tan intrigantes como crees que somos.",
  ui_story_1013_10130801_191_dialog_content = "El caelestita estará a salvo con nosotros. Hemos sido amigos de él todo este tiempo, después de todo.",
  ui_story_1013_10130801_192_dialog_content = "Pero necesitamos un testigo autorizado.",
  ui_story_1013_10130801_193_dialog_content = "Reinhardt, espero que no necesites que te aclare esto. Por favor, haga su parte.",
  ui_story_1013_10130801_194_dialog_content = "...",
  ui_story_1013_10130801_195_dialog_content = "<color=#e8d9bb>*golpes ligeros*</color>",
  ui_story_1013_10130801_196_dialog_content = "Bostezo.",
  ui_story_1013_10130801_197_dialog_content = "Por favor todos. No dejemos que nuestras emociones se disparen tanto.",
  ui_story_1013_10130801_198_dialog_content = "Todos ustedes han dado la señal secreta para <color=#FFB400>aceptar la Caelestita</color>. Así que al menos podrías ser un poco más amigable.",
  ui_story_1013_10130801_199_dialog_content = "Y la querida Yingel tiene razón. No olvidemos por qué lo convocamos aquí.",
  ui_story_1013_10130801_200_dialog_content = "(¿Están finalmente a punto de decirnos lo que realmente está pasando?)",
  ui_story_1013_10130801_201_dialog_content = "Caelestite, han respondido a tus preguntas en su totalidad.",
  ui_story_1013_10130801_202_dialog_content = "No se han contenido, incluso cuando tocan temas relacionados con los secretos más guardados de Illumina.",
  ui_story_1013_10130801_203_dialog_content = "Es un comercio justo, ¿no? Nuestros secretos para su cooperación.",
  ui_story_1013_10130801_204_dialog_content = "!?",
  ui_story_1013_10130801_205_dialog_content = "¡Eso es ridículo! ¡Nunca apoyaría un programa así!",
  ui_story_1013_10130801_206_dialog_content = "Pa. Eres el único caelestita superviviente. Nunca te modificaríamos.",
  ui_story_1013_10130801_207_dialog_content = "Como acabamos de decir, no tocaremos ni un solo pelo de tu cabeza.",
  ui_story_1013_10130801_208_dialog_content = "Simplemente te pido que nos ayudes. Y hacerlo te beneficiará indirectamente.",
  ui_story_1013_10130801_209_dialog_content = "¿Podrías dejar de andarte por las ramas?",
  ui_story_1013_10130801_210_dialog_content = "No te enojes. Sé que quieres que Vice vuelva a la normalidad y que te preocupa el mal funcionamiento de Colossus.",
  ui_story_1013_10130801_211_dialog_content = "(E-Eso es verdad...)",
  ui_story_1013_10130801_212_dialog_content = "Para resumir, el Consejo Científico espera usar sus poderes psíquicos para establecer un vínculo con <color=#FFB400>guardián uno</color>.",
  ui_story_1013_10130801_213_dialog_content = "Previamente, los científicos de Illumina acordaron que Soroz era un Coloso de transporte ordinario.",
  ui_story_1013_10130801_214_dialog_content = "Pero dado su comportamiento reciente y la forma en que sus sistemas continúan actualizándose...",
  ui_story_1013_10130801_215_dialog_content = "se han abierto posibilidades alternativas.",
  ui_story_1013_10130801_216_dialog_content = "Y tú, el Caelestite que controlas a Soroz, eres parte integral de ellos.",
  ui_story_1013_10130801_217_dialog_content = "La antigua tecnología que te une a Soroz provocó una serie de eventos milagrosos.",
  ui_story_1013_10130801_218_dialog_content = "Llegamos a un acuerdo después de nuestra conversación anterior. Podemos confiarte la conciencia del Guardián Uno.",
  ui_story_1013_10130801_219_dialog_content = "Por lo tanto, esperamos que use su poder para comunicarse con Guardian One.",
  ui_story_1013_10130801_220_dialog_content = "¿Guardián uno? ¿Qué es eso, otro robot que necesita una paliza?",
  ui_story_1013_10130801_221_dialog_content = "Es una antigua inteligencia artificial que ha sobrevivido hasta nuestros días. Gestiona los cálculos y las operaciones diarias de toda la tecnología de Illumina.",
  ui_story_1013_10130801_222_dialog_content = "¿Entonces, qué piensas? Hay similitudes con los Colosos, ¿no?",
  ui_story_1013_10130801_223_dialog_content = "Es verdad.",
  ui_story_1013_10130801_224_dialog_content = "Y si puedes ponerte en contacto con Guardian One...",
  ui_story_1013_10130801_225_dialog_content = "Existe la posibilidad de que los recuerdos antiguos en su conciencia brinden pistas sobre cómo devolver Vice a la normalidad.",
  ui_story_1013_10130801_226_dialog_content = "Y si puedes encontrar las partes apropiadas de esos recuerdos, quizás te reúnas con tu Coloso.",
  ui_story_1013_10130801_227_dialog_content = "!?",
  ui_story_1013_10130801_228_dialog_content = "(Si lo que dice es verdad, entonces Soroz...)",
  ui_story_1013_10130801_229_dialog_content = "La decisión es tuya. Simplemente le doy una opción.",
  ui_story_1013_10130801_230_dialog_content = "PlayerName, ¿no estás seguro?",
  ui_story_1013_10130801_231_dialog_content = "Después de lo que han dicho, ¡tengo que probarlo!",
  ui_story_1013_10130801_232_dialog_content = "Pensé que lo haría. Y apruebo tu elección.",
  ui_story_1013_10130801_233_dialog_content = "La actitud del Consejo deja mucho que desear, pero no se puede dejar escapar la oportunidad de cambiar las cosas.",
  ui_story_1013_10130801_234_dialog_content = "Parece que estás de acuerdo.",
  ui_story_1013_10130801_235_dialog_content = "Traeré a Guardián Uno inmediatamente.",
  ui_story_1013_10130901_1_dialog_content = "Es una antigua inteligencia artificial que ha sobrevivido hasta nuestros días. Gestiona los cálculos y las operaciones diarias de toda la tecnología de Illumina.",
  ui_story_1013_10130901_2_dialog_content = "¿Entonces, qué piensas? Hay similitudes con los Colosos, ¿no?",
  ui_story_1013_10130901_3_dialog_content = "Una antigua inteligencia artificial que respalda todo lo que hace Illumina...",
  ui_story_1013_10130901_4_dialog_content = "Ciertamente estoy intrigado. Suena increíble.",
  ui_story_1013_10130901_5_dialog_content = "Me pregunto cómo se ve. Debe ser enorme para contener el poder computacional que requiere Illumina.",
  ui_story_1013_10130901_6_dialog_content = "Tan grande como Soroz.",
  ui_story_1013_10130901_7_dialog_content = "Y si está tan bien conservado, debe conservar toda su programación antigua.",
  ui_story_1013_10130901_8_dialog_content = "Debería ser más inteligente que un Chubb, al menos.",
  ui_story_1013_10130901_9_dialog_content = "Y debe tener algún tipo de pantalla para que las personas interactúen con él.",
  ui_story_1013_10130901_10_dialog_content = "Como el viejo \"mayordomo\" de Entrañas.",
  ui_story_1013_10130901_11_dialog_content = "¡Hola Caelestita!",
  ui_story_1013_10130901_12_dialog_content = "No eres lo que los datos acumulados llevaron a Guardian One a esperar.",
  ui_story_1013_10130901_13_dialog_content = "¿Q-Qué? Seguro que este pequeño robot no es...",
  ui_story_1013_10130901_14_dialog_content = "Está. Saluda al Guardián Uno.",
  ui_story_1013_10130901_15_dialog_content = "¡No es nada como lo imaginaba!",
  ui_story_1013_10130901_16_dialog_content = "Guardian One aprovechará su existencia para actualizar los datos de Guardian One sobre Caelestites.",
  ui_story_1013_10130901_17_dialog_content = "Evidentemente, tanto usted como Guardian One comparten ese sentimiento.",
  ui_story_1013_10130901_18_dialog_content = "Caelestite, ¿debemos enriquecer las bases de datos de los demás?",
  ui_story_1013_10130901_19_dialog_content = "Eso... ¿Es tratar de hacer amigos?",
  ui_story_1013_10130901_20_dialog_content = "Está mostrando su voluntad de trabajar con usted. Guardian One es un tipo amigable de inteligencia artificial.",
  ui_story_1013_10130901_21_dialog_content = "Espere varios minutos. Necesito programar Guardian One con nuevos protocolos de conexión.",
  ui_story_1013_10130901_22_dialog_content = "Error. Error.",
  ui_story_1013_10130901_23_dialog_content = "La entrada del protocolo de conexión falló. Guardian One no puede conectarse con usuarios no identificados.",
  ui_story_1013_10130901_24_dialog_content = "Qué significa eso...?",
  ui_story_1013_10130901_25_dialog_content = "<size=30>Pensé que acordamos que dejarías que el resto de Caelestite tratara de conectarse con tu conciencia. Firmé el formulario de consentimiento...</size>",
  ui_story_1013_10130901_26_dialog_content = "¿Ni siquiera han llegado a un acuerdo sobre esto?",
  ui_story_1013_10130901_27_dialog_content = "L-Lo siento. Guardian One es un riguroso con las reglas.",
  ui_story_1013_10130901_28_dialog_content = "Sin un análisis exhaustivo y cortafuegos estrictos, no se conectará a ningún módulo externo.",
  ui_story_1013_10130901_29_dialog_content = "Guardian One debe examinar y analizar todos los objetos conocidos y desconocidos.",
  ui_story_1013_10130901_30_dialog_content = "Guardian One está dispuesto a examinar nuevos datos de Caelestite. Pero según la base de datos existente sobre Caelestites...",
  ui_story_1013_10130901_31_dialog_content = "Según el análisis de datos anteriores, Guardian One no puede otorgar permisos de control a Caelestites.",
  ui_story_1013_10130901_32_dialog_content = "Pero, ¿no es esta una buena oportunidad para actualizar esa base de datos?",
  ui_story_1013_10130901_33_dialog_content = "Comprendido. Guardian One de hecho prometió actualizar los marcos conceptuales con este Caelestite mutuamente.",
  ui_story_1013_10130901_34_dialog_content = "Entonces eso es un si?",
  ui_story_1013_10130901_35_dialog_content = "Guardian One llevará a cabo una rigurosa prueba de campo para registrar y analizar datos sobre las capacidades de Caelestite.",
  ui_story_1013_10130901_36_dialog_content = "Los resultados de ese proceso informarán a Guardian One sobre si concede o no dichos permisos de control de Caelestite.",
  ui_story_1013_10130901_37_dialog_content = "Er, ¿prueba de campo? ¿En esta sala de reuniones?",
  ui_story_1013_10130901_38_dialog_content = "Caelestite, ponte en modo de emparejamiento.",
  ui_story_1013_10130901_39_dialog_content = "(¡Oh! ¿Supongo que eso significa que quiere un enlace psíquico?)",
  ui_story_1013_10130901_40_option_content = "¡Potencia de fuerza!",
  ui_story_1013_10130901_41_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_1013_10130901_42_dialog_content = "¡Espera!",
  ui_story_1013_10130901_43_dialog_content = "<color=#e8d9bb>Bzzz...</color>",
  ui_story_1013_10130901_44_dialog_content = "Nadie...",
  ui_story_1013_10130901_45_dialog_content = "¡Nadie me ha dicho en qué consiste esta prueba de campo!",
  ui_story_1013_10130901_46_dialog_content = "<color=#e8d9bb>¡Guau! ¡Guau!</color>",
  ui_story_1013_10130901_47_dialog_content = "Es esto... ¡Espera! ¡Este es el lugar del simulador de campo de batalla!",
  ui_story_1013_10130901_48_dialog_content = "Aquí es donde realizaremos la prueba de campo.",
  ui_story_1013_10130901_49_dialog_content = "¡¿Quién es ese?!",
  ui_story_1013_10130901_50_dialog_content = "Por favor, mira hacia arriba, Caelestite.",
  ui_story_1013_10130901_51_dialog_content = "Guardian One está por encima de ti.",
  ui_story_1013_10130901_52_dialog_content = "¡¿Qué?!",
  ui_story_1013_10130901_53_dialog_content = "(Esto es increíble...)",
  ui_story_1013_10130901_54_dialog_content = "(Si observo cuidadosamente el espacio sobre mí, puedo ver dónde la simulación se encuentra con la realidad).",
  ui_story_1013_10130901_55_dialog_content = "(Ese debe ser su sensor que puedo distinguir allá arriba. Es aproximadamente del mismo tamaño que el sol).",
  ui_story_1013_10130901_56_dialog_content = "Bienvenido al antiguo campo de batalla virtual. Guardian One registrará el rendimiento de su prueba en tiempo real.",
  ui_story_1013_10130901_57_dialog_content = "Asegúrate de demostrar lo que puedes hacer, Caelestite.",
  ui_story_1013_10130901_58_dialog_content = "¿Otra vez? ¿Qué es esto, la nueva metodología de prueba estandarizada de Illumina?",
  ui_story_1013_10130901_59_dialog_content = "(Pero si todos usan esta misma simulación, entonces la conciencia de Soroz debe ser...)",
  ui_story_1013_10130901_60_dialog_content = "(Excelente. Tendré que hacer un buen uso de esta oportunidad.)",
  ui_story_1013_10130901_61_dialog_content = "Familiarícese con el entorno lo antes posible. Guardian One está a punto de inyectar el primer lote de datos de batalla.",
  ui_story_1013_10130901_62_dialog_content = "Entiendo. Pero antes de empezar, tengo una petición.",
  ui_story_1013_10130901_63_dialog_content = "Si paso la prueba, quiero examinar los datos de este campo de batalla en su totalidad yo mismo.",
  ui_story_1013_10130901_64_dialog_content = "Eso es inusual...",
  ui_story_1013_10130901_65_dialog_content = "Eso está permitido. Solicitud concedida.",
  ui_story_1013_10130901_66_dialog_content = "Ahora para el siguiente paso. ¿Estás lista, Caelestita?",
  ui_story_1013_10130901_67_dialog_content = "Que comience la batalla.",
  ui_story_1013_10130901_68_dialog_content = "Objetivo: eliminar todos los eclipses.",
  ui_story_1013_10130901_69_dialog_content = "Guardian One inicializando...",
  ui_story_1013_10130901_70_dialog_content = "En ese caso.",
  ui_story_1013_10130901_71_dialog_content = "¡Vicio! ¡Carleen! ¡Cuento con usted!",
  ui_story_1013_10130901_72_dialog_content = "Déjame esto a mi.",
  ui_story_1013_10130901_73_dialog_content = "Lo tengo.",
  ui_story_1013_10131002_1_dialog_content = "Graah...",
  ui_story_1013_10131002_2_dialog_content = "Objetivo de etapa completado.",
  ui_story_1013_10131002_3_dialog_content = "Prueba concluida. Grado de etapa: B.",
  ui_story_1013_10131002_4_dialog_content = "Grabando nuevos datos...",
  ui_story_1013_10131002_5_dialog_content = "Las habilidades de batalla de Caelestite incluyen la gestión de despliegues tácticos.",
  ui_story_1013_10131002_6_dialog_content = "El Caelestite puede controlar Aurorianos y completar tareas de combate.",
  ui_story_1013_10131002_7_dialog_content = "Sé que esto podría ser un concepto nuevo para ti. Pero en nuestros tiempos, es completamente normal.",
  ui_story_1013_10131002_8_dialog_content = "Comprendido. Se ha actualizado la base de datos de Guardian One sobre Caelestites.",
  ui_story_1013_10131002_9_dialog_content = "Has superado la prueba, Caelestite.",
  ui_story_1013_10131002_10_dialog_content = "Y según lo acordado, Guardian One pondrá a su disposición los registros de los datos de hoy.",
  ui_story_1013_10131002_11_dialog_content = "En breve abandonarás el antiguo campo de batalla. Será destruido una vez que ya no esté en uso.",
  ui_story_1013_10131002_12_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_1013_10131002_13_dialog_content = "Espera...",
  ui_story_1013_10131002_14_dialog_content = "¡Por favor, no lo destruyas!",
  ui_story_1013_10131002_15_option_content = "¡Potencia de fuerza!",
  ui_story_1013_10131002_16_dialog_content = "Para usar un término auroriano, Caelestite, estás siendo \"descortés\".",
  ui_story_1013_10131002_17_dialog_content = "Guardian One ha reconocido tus habilidades. Pero eso no significa que puedas vincularte con Guardian One a voluntad.",
  ui_story_1013_10131002_18_dialog_content = "Le explicaré a Algol más tarde.",
  ui_story_1013_10131002_19_dialog_content = "Muy bien. Explique por qué no desea que se destruya la antigua simulación del campo de batalla.",
  ui_story_1013_10131002_20_dialog_content = "Esto no estaba incluido en su solicitud original.",
  ui_story_1013_10131002_21_dialog_content = "Guardian One no comprende por qué desea examinar y conservar estos datos.",
  ui_story_1013_10131002_22_dialog_content = "¿Qué estás planeando?",
  ui_story_1013_10131002_23_dialog_content = "Es como esto...",
  ui_story_1013_10131002_24_dialog_content = "Mi Colossus tuvo que sacarme de la simulación de batalla anterior. Al hacerlo, funcionó mal.",
  ui_story_1013_10131002_25_dialog_content = "Sus datos de conciencia todavía están aquí, en algún lugar de esa gran pila de datos.",
  ui_story_1013_10131002_26_dialog_content = "¿Es muy importante para ti, Caelestite?",
  ui_story_1013_10131002_27_option_content = "Soroz es mi amigo más cercano.",
  ui_story_1013_10131002_28_dialog_content = "Soroz es más que una pieza de antigua tecnología autoconsciente.",
  ui_story_1013_10131002_29_dialog_content = "Sus recuerdos contienen todas las aventuras que hemos vivido juntos.",
  ui_story_1013_10131002_30_dialog_content = "Guardian One entiende.",
  ui_story_1013_10131002_31_dialog_content = "Grabando nuevos datos...",
  ui_story_1013_10131002_32_dialog_content = "Guardian One ha actualizado su base de datos sobre Caelestites.",
  ui_story_1013_10131002_33_dialog_content = "¿Que esta pasando? Tengo la vaga sensación de que ustedes dos se han vuelto... amigos.",
  ui_story_1013_10131002_34_dialog_content = "Reporte. Caelestite y Guardian One acaban de concluir una breve conexión y sincronizar los resultados de las pruebas.",
  ui_story_1013_10131002_35_dialog_content = "(Elegí no revelar la razón por la que lo vinculé a la fuerza...)",
  ui_story_1013_10131002_36_dialog_content = "Bien, entonces tienes una perspectiva totalmente nueva sobre Caelestite ahora, ¿verdad?",
  ui_story_1013_10131002_37_dialog_content = "Entonces, ¿podemos continuar con el experimento mencionado anteriormente?",
  ui_story_1013_10131002_38_dialog_content = "Sí, Guardian One lo permite.",
  ui_story_1013_10131002_39_dialog_content = "Caelestite, los datos actuales del antiguo campo de batalla se han sincronizado con su terminal según el acuerdo.",
  ui_story_1013_10131002_40_dialog_content = "Gracias, Guardián Uno.",
  ui_story_1013_10131002_41_dialog_content = "Bien entonces. Volvamos a la razón principal por la que estamos aquí.",
  ui_story_1013_10131002_42_dialog_content = "Guardian One estudiará su uso de tecnología antigua a través de un enlace telepático con usted.",
  ui_story_1013_10131002_43_dialog_content = "Sus comentarios se mostrarán en tiempo real en la pantalla de la sala de conferencias.",
  ui_story_1013_10131002_44_dialog_content = "Esto será increíble para el advenimiento de la tecnología Illumina.",
  ui_story_1013_10131002_45_dialog_content = "Lo haré lo mejor que pueda.",
  ui_story_1013_10131002_46_dialog_content = "Ciertamente has pasado por muchas simulaciones de batalla hoy.",
  ui_story_1013_10131002_47_dialog_content = "Esta vez no podré ser espectador, pero ten cuidado.",
  ui_story_1013_10131002_48_dialog_content = "Relájate, Reinhardt. Y técnicamente no estoy solo.",
  ui_story_1013_10131002_49_dialog_content = "Guardian One está listo para vincularse.",
  ui_story_1013_10131002_50_dialog_content = "(La mayor diferencia entre Caelestite y nuestros científicos es su actitud hacia la tecnología).",
  ui_story_1013_10131002_51_dialog_content = "(Aunque las capacidades técnicas del instituto de investigación han ido mejorando en los últimos años...)",
  ui_story_1013_10131002_X51_dialog_content = "(Si no poseemos la misma mentalidad, no seremos capaces de atravesar la barrera que nos mantiene alejados de la cima de la tecnología).",
  ui_story_1013_10131002_52_dialog_content = "(Esperemos que aprendan de este experimento).",
  ui_story_1013_10131002_53_dialog_content = "Guardián Uno, ábrase a los pensamientos que le estoy enviando.",
  ui_story_1013_10131002_54_option_content = "¡Potencia de fuerza!",
  ui_story_1013_10131002_55_dialog_content = "¿Es así como se ve el paisaje mental de Guardian One...?",
  ui_story_1013_10131002_56_dialog_content = "Guardián Uno está presente, Caelestite.",
  ui_story_1013_10131002_57_dialog_content = "¡Bienvenidos!",
  ui_story_1013_10131002_58_dialog_content = "Siéntete libre de actuar como quieras, ya que el profesor Algol no tiene el mando aquí.",
  ui_story_1013_10131002_59_dialog_content = "Está bien, perdóname de antemano.",
  ui_story_1013_10131002_60_dialog_content = "(Es casi como si estuviéramos jugando a fingir...)",
  ui_story_1013_10131002_61_dialog_content = "Tus pensamientos serpentean, Caelestite. Todavía estás preocupado por tu Colossus.",
  ui_story_1013_10131002_62_dialog_content = "(Impresionante... No debería esperar menos de la IA que ejecuta todas las operaciones en Illumina).",
  ui_story_1013_10131002_63_dialog_content = "¿Confías lo suficiente en Guardian One para convertir este proceso de aprendizaje en una experiencia más desafiante, Caelestite?",
  ui_story_1013_10131002_64_dialog_content = "Bueno, confío en ti, por eso me vinculé contigo...",
  ui_story_1013_10131002_65_dialog_content = "Confianza verificada. A continuación, Guardian One solicita buscar las señales del Coloso con fines de acceso.",
  ui_story_1013_10131002_66_dialog_content = "¡¿Esperar lo?!",
  ui_story_1013_10131002_67_dialog_content = "Si confía en Guardian One, Guardian One solicita buscar las señales de Colossus para fines de acceso.",
  ui_story_1013_10131002_68_dialog_content = "(¿Está tratando de ayudarme a encontrar una solución para Soroz?)",
  ui_story_1013_10131002_69_dialog_content = "(¿Debería hacer lo que dice?)",
  ui_story_1013_10131002_70_dialog_content = "Estás dudando, Caelestite.",
  ui_story_1013_10131002_71_dialog_content = "Iniciando análisis inteligente...",
  ui_story_1013_10131002_72_dialog_content = "Escenario 1: Guardian One se vincula con éxito con Colossus y obtiene sus señales.",
  ui_story_1013_10131002_73_dialog_content = "Resultado: Los datos de reconocimiento de Colossus se recuperan. El Coloso recupera la conciencia.",
  ui_story_1013_10131002_74_dialog_content = "Escenario 2: Guardian One se vincula con éxito con Colossus, obtiene sus señales e intenta alterar sus datos.",
  ui_story_1013_10131002_75_dialog_content = "Resultado: Caelestite detecta el intento y corta el vínculo entre Guardian One y Colossus. El estado del Coloso permanece sin cambios.",
  ui_story_1013_10131002_76_dialog_content = "Escenario 3—",
  ui_story_1013_10131002_77_dialog_content = "¡Está bien, está bien, no necesitas pasar por todas las posibilidades...!",
  ui_story_1013_10131002_78_dialog_content = "Entiendo lo que quieres decir ahora. No es que tenga mejores opciones, de todos modos.",
  ui_story_1013_10131002_79_dialog_content = "Gracias, Guardián Uno, por hacer esto.",
  ui_story_1013_10131002_80_dialog_content = "Caelestite y la antigua tecnología de IA son amigos.",
  ui_story_1013_10131002_81_dialog_content = "Guardian One también es tecnología antigua de IA.",
  ui_story_1013_10131002_82_dialog_content = "Bien, ¡cuento contigo entonces!",
  ui_story_1013_10131002_83_dialog_content = "¡Volvamos a la antigua simulación de batalla y salvemos la conciencia de Soroz!",
  ui_story_1013_10131002_84_dialog_content = "Guardián Uno está listo. Contando hacia atrás...",
  ui_story_1013_10131002_85_dialog_content = "Tres...",
  ui_story_1013_10131002_86_dialog_content = "Dos...",
  ui_story_1013_10131002_87_dialog_content = "Una.",
  ui_story_1013_10131101_1_dialog_content = "Precaución: simulación de batalla inestable.",
  ui_story_1013_10131101_2_dialog_content = "Esté preparado para situaciones inesperadas.",
  ui_story_1013_10131101_3_dialog_content = "Está bien, he estado aquí antes.",
  ui_story_1013_10131101_4_dialog_content = "Aunque es diferente a la última vez.",
  ui_story_1013_10131101_5_dialog_content = "La simulación está en piloto automático. El tiempo avanza.",
  ui_story_1013_10131101_6_dialog_content = "Lo que no entiendo es, si es una simulación, ¿cómo podría quedar atrapada la conciencia de Soroz?",
  ui_story_1013_10131101_7_dialog_content = "La conciencia de Soroz es puro dato, al igual que la simulación.",
  ui_story_1013_10131101_8_dialog_content = "Su \"mente\" interfirió con la simulación y los datos se mezclaron.",
  ui_story_1013_10131101_9_dialog_content = "Debes llegar a Soroz antes de que la simulación se autodestruya.",
  ui_story_1013_10131101_10_dialog_content = "De lo contrario, los datos de Soroz también serán destruidos.",
  ui_story_1013_10131101_11_dialog_content = "¿Quiere decir que la conciencia de Soroz desaparecería?",
  ui_story_1013_10131101_12_dialog_content = "No, pero ya no sería accesible.",
  ui_story_1013_10131101_13_dialog_content = "En términos del mundo real, estaría enterrado en las ruinas de esta simulación.",
  ui_story_1013_10131101_14_dialog_content = "Seguiría existiendo, pero nadie sería capaz de encontrarlo.",
  ui_story_1013_10131101_15_dialog_content = "¿Por qué se autodestruiría la simulación?",
  ui_story_1013_10131101_16_dialog_content = "La simulación de esta batalla en particular es especial.",
  ui_story_1013_10131101_17_dialog_content = "No se detiene en ningún punto designado y, en cambio, borra continuamente los datos...",
  ui_story_1013_10131101_18_dialog_content = "hasta que no queda nada y, por lo tanto, se autodestruye.",
  ui_story_1013_10131101_19_dialog_content = "Especial... Esos tipos dijeron que la civilización fue destruida una vez.",
  ui_story_1013_10131101_20_dialog_content = "Esta simulación es un registro de esa catástrofe, ¿verdad?",
  ui_story_1013_10131101_21_dialog_content = "Según mis cálculos, casi ninguna forma de vida podría haber sobrevivido. Por lo tanto, esa es una conclusión lógica.",
  ui_story_1013_10131101_22_dialog_content = "Con razón fui testigo de lo que hice...",
  ui_story_1013_10131101_23_dialog_content = "Grah!",
  ui_story_1013_10131101_24_dialog_content = "¡Ahhhhhhhh!",
  ui_story_1013_10131101_25_dialog_content = "La humanidad se está muriendo... Incluso los Eclipsites no sobrevivirán.",
  ui_story_1013_10131101_26_dialog_content = "La destrucción total es el final inevitable para un mundo así...",
  ui_story_1013_10131101_27_dialog_content = "<color=#e8d9bb>¡Crujido!</color>",
  ui_story_1013_10131101_28_dialog_content = "!",
  ui_story_1013_10131101_29_dialog_content = "<color=#e8d9bb>Crujido, crujido!</color>",
  ui_story_1013_10131101_30_dialog_content = "Grah, rugido!",
  ui_story_1013_10131101_31_dialog_content = "¿Eclipsitos? Pensé que todos habrían perecido en ese evento del fin del mundo.",
  ui_story_1013_10131101_32_dialog_content = "Difícil de creer que algunos sobrevivieron.",
  ui_story_1013_10131101_33_dialog_content = "¿Q-Qué está haciendo?",
  ui_story_1013_10131101_34_dialog_content = "El Eclipsite está consumiendo barras de refuerzo.",
  ui_story_1013_10131101_35_dialog_content = "<color=#e8d9bb>Crujido, crujido!</color>",
  ui_story_1013_10131101_36_dialog_content = "¿Porqué haría eso?",
  ui_story_1013_10131101_37_dialog_content = "Incluso si no hay nada para comer, hay mejores cosas para masticar que barras de refuerzo... como esas rocas en el suelo.",
  ui_story_1013_10131101_38_dialog_content = "Basado en mis deducciones, los Eclipsites anhelan las características de las barras de refuerzo.",
  ui_story_1013_10131101_39_dialog_content = "¿Características?",
  ui_story_1013_10131101_40_dialog_content = "Las barras de refuerzo no fueron destruidas en la catástrofe.",
  ui_story_1013_10131101_41_dialog_content = "Los Eclipsites desean obtener características similares a las barras de refuerzo al consumirlas.",
  ui_story_1013_10131101_42_dialog_content = "¿E-Es eso posible?",
  ui_story_1013_10131101_43_dialog_content = "Es solo una teoría, pero el hecho es que los eclipses sobrevivieron a la catástrofe.",
  ui_story_1013_10131101_44_dialog_content = "En grandes cantidades.",
  ui_story_1013_10131101_45_dialog_content = "<color=#e8d9bb>¡Crujido, crujido!</color>",
  ui_story_1013_10131101_46_dialog_content = "<color=#e8d9bb>¡Crujido!</color>",
  ui_story_1013_10131101_47_dialog_content = "¡Graaagh!",
  ui_story_1013_10131101_48_dialog_content = "Vaya, ¿canibalismo también?",
  ui_story_1013_10131101_49_dialog_content = "Los eclipses hicieron mucho más que la humanidad para sobrevivir.",
  ui_story_1013_10131101_50_dialog_content = "Por lo tanto, los eclipses son la única presencia en esta ciudad humana.",
  ui_story_1013_10131101_51_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131101_52_dialog_content = "Muchos de ellos...",
  ui_story_1013_10131101_53_dialog_content = "Muchos Eclipsites muertos todavía están en el suelo. Mueren y reaparecen constantemente.",
  ui_story_1013_10131101_54_dialog_content = "Sí. La evolución no se puede lograr a través de un solo individuo, por lo que los Eclipsites eligieron una alternativa rápida.",
  ui_story_1013_10131101_55_dialog_content = "Perfeccionaron la mejora genética a través de la muerte persistente como grupo hasta que pudieron adaptarse al entorno hostil.",
  ui_story_1013_10131101_56_dialog_content = "Espera, ¿estos eclipses se están reuniendo en alguna parte?",
  ui_story_1013_10131101_57_dialog_content = "Sí. Se están moviendo en la misma dirección. Algo los está atrayendo.",
  ui_story_1013_10131101_58_dialog_content = "¿Atraerlos? Podría ser...?",
  ui_story_1013_10131101_59_option_content = "¡Potencia de fuerza!",
  ui_story_1013_10131101_60_dialog_content = "Soroz! ¡Esa es la conciencia de Soroz!",
  ui_story_1013_10131101_61_dialog_content = "Eso lo explicaría. Los datos no relacionados con la simulación tienden a ser extremadamente palpables.",
  ui_story_1013_10131101_62_dialog_content = "Los eclipses convergerían a su alrededor.",
  ui_story_1013_10131101_63_dialog_content = "Encuentra a Soroz y podemos solucionar sus problemas, ¿verdad?",
  ui_story_1013_10131101_64_dialog_content = "Podemos conectarnos a Soroz y realizar diagnósticos, aunque se desconoce si será posible realizar reparaciones.",
  ui_story_1013_10131101_65_dialog_content = "Vale, vale, no hace falta que seas tan pedante. En cualquier caso, ¡vamos a Soroz!",
  ui_story_1013_10131101_66_dialog_content = "Afortunadamente, esto es solo una simulación, por lo que tengo la capacidad de luchar contra los Eclipsites.",
  ui_story_1013_10131101_67_dialog_content = "¡Toma esto!",
  ui_story_1013_10131101_68_dialog_content = "<color=#e8d9bb>Blam—¡Boom!</color>",
  ui_story_1013_10131101_69_dialog_content = "¿Qué fue eso? ¿Algo está a punto de derrumbarse?",
  ui_story_1013_10131101_70_dialog_content = "El edificio a tu lado se está derrumbando.",
  ui_story_1013_10131101_71_dialog_content = "Precaución, la simulación actual es muy inestable. Los ataques pueden hacer que el mundo se derrumbe.",
  ui_story_1013_10131101_72_dialog_content = "¡Vaya, en realidad se está cayendo a pedazos!",
  ui_story_1013_10131101_73_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1013_10131101_74_dialog_content = "*Tose* Tanto polvo...",
  ui_story_1013_10131101_75_dialog_content = "¡Apenas hice nada! ¿Es este mundo tan frágil?",
  ui_story_1013_10131101_76_dialog_content = "¿Por qué simplemente...",
  ui_story_1013_10131101_77_dialog_content = "Debido a la inestabilidad de los datos de batalla, eventualmente se autodestruiría incluso sin que nadie hiciera nada.",
  ui_story_1013_10131101_78_dialog_content = "Cuidado.",
  ui_story_1013_10131101_79_dialog_content = "!",
  ui_story_1013_10131101_80_dialog_content = "<color=#e8d9bb>¡¡¡Golpe!!!</color>",
  ui_story_1013_10131101_81_dialog_content = "Caray, ¿hay un final para esto?",
  ui_story_1013_10131101_82_dialog_content = "Precaución, el colapso del mundo es una indicación de la autodestrucción de la simulación en progreso.",
  ui_story_1013_10131101_83_dialog_content = "Y la destrucción de los datos de la simulación causará...",
  ui_story_1013_10131101_84_dialog_content = "Hacer que se borren los datos de Soroz, ¿verdad?",
  ui_story_1013_10131101_85_dialog_content = "Sí. Su comprensión es correcta.",
  ui_story_1013_10131101_86_dialog_content = "Supongo que no tengo tiempo para quejarme ahora mismo...",
  ui_story_1013_10131101_87_dialog_content = "¡Tengo que llegar a Soroz antes de que el mundo se desmorone!",
  ui_story_1013_10131202_1_dialog_content = "Treinta.",
  ui_story_1013_10131202_2_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1013_10131202_3_dialog_content = "¡Whoa!",
  ui_story_1013_10131202_4_dialog_content = "Casi me caigo...",
  ui_story_1013_10131202_5_dialog_content = "¡Las fisuras en el suelo parecen estar persiguiéndome!",
  ui_story_1013_10131202_6_dialog_content = "Eso es porque tú eres una de las razones del colapso.",
  ui_story_1013_10131202_7_dialog_content = "Veinticinco.",
  ui_story_1013_10131202_8_dialog_content = "¡¿Q-Qué diablos pasa con los números que sigues arrojando tan espeluznantemente?!",
  ui_story_1013_10131202_9_dialog_content = "Ese es el tiempo que te queda.",
  ui_story_1013_10131202_10_dialog_content = "Simulé la obliteración a través de interpretaciones de los datos de simulación. Esta cuenta regresiva es absolutamente precisa.",
  ui_story_1013_10131202_11_dialog_content = "¿Solo quedan veintitantos segundos? Eso no es-",
  ui_story_1013_10131202_12_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1013_10131202_13_dialog_content = "Veinte.",
  ui_story_1013_10131202_14_dialog_content = "De acuerdo, debería poder cubrir cierta distancia en 20 segundos.",
  ui_story_1013_10131202_15_dialog_content = "¡Soroz está justo adelante, puedo sentirlo!",
  ui_story_1013_10131202_16_dialog_content = "No olvides estar en guardia contra los eclipses.",
  ui_story_1013_10131202_17_dialog_content = "¡De acuerdo, deja de regañar!",
  ui_story_1013_10131202_18_dialog_content = "Fuera de mi camino-",
  ui_story_1013_10131202_19_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1013_10131202_20_dialog_content = "¡Aaaahhhh!",
  ui_story_1013_10131202_21_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1013_10131202_22_dialog_content = "*Tose*",
  ui_story_1013_10131202_23_dialog_content = "Ay...",
  ui_story_1013_10131202_24_dialog_content = "¿Cuánto tiempo tengo, Guardián Uno...",
  ui_story_1013_10131202_25_dialog_content = "Diez.",
  ui_story_1013_10131202_26_dialog_content = "Tonterías. necesito darme prisa",
  ui_story_1013_10131202_27_dialog_content = "Estoy casi allí...",
  ui_story_1013_10131202_28_dialog_content = "Está justo ahí.",
  ui_story_1013_10131202_29_dialog_content = "Cinco.",
  ui_story_1013_10131202_30_dialog_content = "*Tose*",
  ui_story_1013_10131202_31_dialog_content = "cuatro",
  ui_story_1013_10131202_32_dialog_content = "Casi, tan cerca...",
  ui_story_1013_10131202_33_dialog_content = "Tres.",
  ui_story_1013_10131202_34_dialog_content = "Uf... uf...",
  ui_story_1013_10131202_35_dialog_content = "Dos.",
  ui_story_1013_10131202_36_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1013_10131202_37_dialog_content = "Una.",
  ui_story_1013_10131202_38_dialog_content = "¡Potencia de fuerza!",
  ui_story_1013_10131202_39_dialog_content = "¿Eres tú, Soroz?",
  ui_story_1013_10131202_40_dialog_content = "...",
  ui_story_1013_10131202_41_dialog_content = "¡Lo encontré, encontré a Soroz!",
  ui_story_1013_10131202_42_dialog_content = "¿Llegué a tiempo?",
  ui_story_1013_10131202_43_dialog_content = "¡Rápido, conéctate, ahora mismo!",
  ui_story_1013_10131202_44_dialog_content = "Conectando al puerto de datos de Soroz.",
  ui_story_1013_10131202_45_dialog_content = "Ninguna respuesta. Iniciando entrada forzada.",
  ui_story_1013_10131202_46_dialog_content = "Prepararse. Su conciencia entrará pronto en el espacio de datos de Soroz.",
  ui_story_1013_10131202_47_dialog_content = "Guardian One no puede predecir las situaciones a las que te enfrentarás.",
  ui_story_1013_10131202_48_dialog_content = "Por supuesto que estoy listo... Sea lo que sea, no puede ser peor que esto.",
  ui_story_1013_10131202_49_dialog_content = "Iniciando transferencia de datos.",
  ui_story_1013_10131202_50_dialog_content = "Iniciar sesión en Soroz.",
  ui_story_1013_10131202_51_dialog_content = "Está oscuro... ¿Ya llegamos?",
  ui_story_1013_10131202_52_dialog_content = "Sí. Tal vez debería intentar abrir los ojos si no puede ver.",
  ui_story_1013_10131202_53_dialog_content = "¿Ah?",
  ui_story_1013_10131202_54_dialog_content = "¡Oh, puedo ver ahora! Espera, ¿cómo es que necesitaba un recordatorio para eso?",
  ui_story_1013_10131202_55_dialog_content = "Es normal. Tus ojos estaban abiertos cuando terminó la simulación.",
  ui_story_1013_10131202_56_dialog_content = "En tu mente, tus ojos ya estaban abiertos, por lo que no pensarías en abrirlos de nuevo.",
  ui_story_1013_10131202_57_dialog_content = "Pero te descargué en un nuevo cuerpo en este nuevo espacio, y sus ojos estaban cerrados.",
  ui_story_1013_10131202_58_dialog_content = "La disonancia cognitiva entre tu mente y tu cuerpo resultó en esto.",
  ui_story_1013_10131202_59_dialog_content = "Bien...",
  ui_story_1013_10131202_60_dialog_content = "¿Lo entiendes? ¿Debería repetir—",
  ui_story_1013_10131202_61_dialog_content = "¡Entiendo, totalmente!",
  ui_story_1013_10131202_62_dialog_content = "¿Ese es Soroz?",
  ui_story_1013_10131202_X62_dialog_content = "Estamos tan cerca, pero no puedo tocarlo.",
  ui_story_1013_10131202_X63_dialog_content = "¿Dónde está este lugar?",
  ui_story_1013_10131202_63_dialog_content = "Desde un punto de vista visual, estás viendo el interior de Soroz.",
  ui_story_1013_10131202_64_dialog_content = "Pero es más exacto llamar a este caché de datos temporales de Soroz.",
  ui_story_1013_10131202_65_dialog_content = "En otras palabras, la memoria de Soroz.",
  ui_story_1013_10131202_66_dialog_content = "¿Memoria?",
  ui_story_1013_10131202_67_dialog_content = "¿Por qué estamos aquí? ¿No deberíamos estar resolviendo problemas de Soroz?",
  ui_story_1013_10131202_68_dialog_content = "Sí. La causa del mal funcionamiento de Soroz son los datos defectuosos en el caché.",
  ui_story_1013_10131202_69_dialog_content = "Debemos localizar dichos datos entre la miríada de otros datos y repararlos.",
  ui_story_1013_10131202_70_dialog_content = "El proceso es simplemente una cuestión de operaciones de datos para Guardian One.",
  ui_story_1013_10131202_71_dialog_content = "Pero no puedes hacer eso directamente con tu cerebro. Por lo tanto, Guardian One lo ayudará a visualizar los datos a través de su imaginación.",
  ui_story_1013_10131202_72_dialog_content = "Los recuerdos almacenados se convertirán en imágenes, mientras que los fallos se manifestarán como anomalías.",
  ui_story_1013_10131202_73_dialog_content = "Guardian One examinará los recuerdos de Soroz contigo durante todo el proceso.",
  ui_story_1013_10131202_74_dialog_content = "Resolveremos los datos dañados así.",
  ui_story_1013_10131202_75_dialog_content = "¿Seré capaz de reconocer los fallos?",
  ui_story_1013_10131202_76_dialog_content = "Tomarán formas de cosas que ustedes encontrarán repulsivas de acuerdo a su mente; por lo tanto, los reconocerás.",
  ui_story_1013_10131202_77_dialog_content = "Ah, ya veo. Eso suena bastante fácil.",
  ui_story_1013_10131202_78_dialog_content = "Guardian One no puede confirmar esa afirmación.",
  ui_story_1013_10131202_79_dialog_content = "Está bien, lo resolveremos a medida que avanzamos.",
  ui_story_1013_10131202_X79_dialog_content = "Accediendo a datos... Mudarse a una cabaña de Soroz.",
  ui_story_1013_10131202_X80_dialog_content = "¡Uf! ¡Me siento mucho más cómodo aquí!",
  ui_story_1013_10131202_80_dialog_content = "Por cierto, todavía no sabemos ni qué parte de la memoria de Soroz es esta.",
  ui_story_1013_10131202_81_dialog_content = "No pasa nada y hay un silencio absoluto.",
  ui_story_1013_10131202_82_dialog_content = "¿Donde nos encontramos ahora? Quiero decir, ¿dónde estaba Soroz en este recuerdo?",
  ui_story_1013_10131202_83_dialog_content = "Guardian One no posee esos datos.",
  ui_story_1013_10131202_84_dialog_content = "Cierto, no puedes saberlo todo.",
  ui_story_1013_10131202_85_dialog_content = "Conozco a Soroz como la palma de mi mano. Saldré y echaré un vistazo.",
  ui_story_1013_10131202_86_dialog_content = "<color=#e8d9bb>*Pasos*</color>",
  ui_story_1013_10131202_87_dialog_content = "Oye, ¿cómo es que todas las puertas están cerradas?",
  ui_story_1013_10131202_88_dialog_content = "Creo que puedo abrir esto...",
  ui_story_1013_10131202_89_dialog_content = "<color=#e8d9bb>¡Bip! ¡Bip! ¡Bip!</color>",
  ui_story_1013_10131202_90_dialog_content = "¡¿Una advertencia?! ¿Qué se supone que significa esto?",
  ui_story_1013_10131202_91_dialog_content = "¿Me estás encerrando dentro, Soroz?",
  ui_story_1013_10131202_92_dialog_content = "Actualmente no circula aire entre el exterior y el interior. Soroz ha sellado la cabina por completo.",
  ui_story_1013_10131202_93_dialog_content = "Que esta pasando...",
  ui_story_1013_10131202_94_dialog_content = "Oh cierto, debería haber un registro en la consola de control...",
  ui_story_1013_10131202_95_dialog_content = "Déjame ver... Las coordenadas de nuestra ubicación actual son...",
  ui_story_1013_10131202_96_dialog_content = "?!!",
  ui_story_1013_10131202_97_dialog_content = "No hay coordenadas...",
  ui_story_1013_10131202_98_dialog_content = "¡Ninguna otra información tampoco!",
  ui_story_1013_10131202_99_dialog_content = "¿Por qué apenas hay nada en el registro?",
  ui_story_1013_10131202_100_dialog_content = "Este es el recuerdo de Soroz. Parte de la información anterior debe haber sido eliminada.",
  ui_story_1013_10131202_101_dialog_content = "No pasa nada y no hay registros. No hay mucho en el camino de los recuerdos en esta memoria, ¿eh?",
  ui_story_1013_10131202_102_dialog_content = "¿Por qué Soroz sería así?",
  ui_story_1013_10131202_103_dialog_content = "Las memorias de las máquinas difieren de las de los seres biológicos.",
  ui_story_1013_10131202_104_dialog_content = "Tiene esos recuerdos no porque sean memorables sino porque sucedieron.",
  ui_story_1013_10131202_105_dialog_content = "¡Soroz no es una máquina! Su...",
  ui_story_1013_10131202_106_dialog_content = "Ah, pero eres...",
  ui_story_1013_10131202_107_dialog_content = "Lo siento, no quiero decir que las máquinas sean malas.",
  ui_story_1013_10131202_108_dialog_content = "Guardian One no entiende por qué te disculparías.",
  ui_story_1013_10131202_109_dialog_content = "¡Es mejor que no lo hagas! Solo me gusta disculparme, ja... ja.",
  ui_story_1013_10131202_110_dialog_content = "?",
  ui_story_1013_10131202_111_dialog_content = "Ejem, estoy divagando. Déjame ver si puedo encontrar más información.",
  ui_story_1013_10131202_112_dialog_content = "Guardián Uno encontró algo de información.",
  ui_story_1013_10131202_113_dialog_content = "¿En serio? ¿Dónde?",
  ui_story_1013_10131202_114_dialog_content = "En esta cosa llamada \"Terminal\".",
  ui_story_1013_10131202_115_dialog_content = "Es este...",
  ui_story_1013_10131202_116_dialog_content = "■■■■■■■■■■■■",
  ui_story_1013_10131202_117_dialog_content = "¿Qué es esto?",
  ui_story_1013_10131202_118_dialog_content = "Es probable que sea un texto antiguo.",
  ui_story_1013_10131202_119_dialog_content = "Un momento. Soroz registró los procedimientos de traducción.",
  ui_story_1013_10131202_120_dialog_content = "Lo convertiré en un escrito que puedas comprender.",
  ui_story_1013_10131202_121_dialog_content = "\"Mensajes recibidos desde tierra, posiblemente por última vez\".",
  ui_story_1013_10131202_122_dialog_content = "\"La Ciudad del Obelisco está destruida\".",
  ui_story_1013_10131202_123_dialog_content = "¿Qué? ¿Cómo...? ¿Cómo puede ser esto?",
  ui_story_1013_10131202_124_dialog_content = "Era sólo cuestión de tiempo. Todo en la superficie se está desmoronando. La Ciudad del Obelisco no es una excepción.",
  ui_story_1013_10131202_125_dialog_content = "Estaba destinado a suceder desde nuestra partida.",
  ui_story_1013_10131202_126_dialog_content = "¿A dónde vamos a volver?",
  ui_story_1013_10131202_127_dialog_content = "Tenga la seguridad de que el maestro Francis dijo que cuando sea el momento de que regresemos, seremos señalados.",
  ui_story_1013_10131202_128_dialog_content = "Ha hecho todos los arreglos. Todos confiamos en él, ¿verdad?",
  ui_story_1013_10131202_129_dialog_content = "Sí, todos confiamos en él.",
  ui_story_1013_10131202_130_dialog_content = "¿Tenemos alguna otra opción? Confiar en él es todo lo que podemos hacer.",
  ui_story_1013_10131202_131_dialog_content = "Por cierto, solo quiero saber, ¿cuándo podemos dejar nuestros Colosos?",
  ui_story_1013_10131202_132_dialog_content = "Soy el único en este Coloso y me estoy volviendo loco.",
  ui_story_1013_10131202_133_dialog_content = "Quiero ver a otras personas, especialmente cuando estamos tan cerca el uno del otro.",
  ui_story_1013_10131202_134_dialog_content = "Y mi hermana pequeña también. La extraño mucho. Ella está en tu Colossus, cierto, eh...",
  ui_story_1013_10131202_135_dialog_content = "Lo siento, olvidé tu nombre, 217.",
  ui_story_1013_10131202_136_dialog_content = "Sí, está bien, no te preocupes.",
  ui_story_1013_10131202_137_dialog_content = "Pero nadie puede dejar sus Colosos todavía... absolutamente no.",
  ui_story_1013_10131202_138_dialog_content = "Si haces tonterías, acabarás muerto.",
  ui_story_1013_10131202_139_dialog_content = "Está bien, pero ¿hay algo más que podamos hacer?",
  ui_story_1013_10131202_140_dialog_content = "Ya estoy cansada de comer. Si yo también me canso de dormir, no sé qué será de mí.",
  ui_story_1013_10131202_141_dialog_content = "No hay nada aquí. Y a partir de ahora, tampoco habrá ni un fragmento de noticia del exterior.",
  ui_story_1013_10131202_142_dialog_content = "Todo lo que puedo hacer es mirar la terminal todo el día, hablando con un montón de números en una pantalla.",
  ui_story_1013_10131202_143_dialog_content = "Tarde o temprano, todos seremos como 79 y olvidaremos el nombre de todos, recordando solo los números.",
  ui_story_1013_10131202_144_dialog_content = "De ninguna manera, recuerdo tu nombre. ¡Eres Parker!",
  ui_story_1013_10131202_145_dialog_content = "¡No olvidaré el nombre de nadie! ¡Los caelestitas no se llaman entre sí por números!",
  ui_story_1013_10131202_146_dialog_content = "Sólo olvídalo mientras puedas.",
  ui_story_1013_10131202_147_dialog_content = "No ganarás nada permaneciendo apegado a las viejas tradiciones. Solo será más doloroso cuando lo olvides.",
  ui_story_1013_10131202_148_dialog_content = "Es posible que recuerde un nombre que no usa durante un día o un mes.",
  ui_story_1013_10131202_149_dialog_content = "Pero, ¿qué tal un año después? ¿Diez años?",
  ui_story_1013_10131202_150_dialog_content = "¿Diez años? Eso es un largo tiempo...",
  ui_story_1013_10131202_151_dialog_content = "¿Es así como vamos a pasar la próxima década?",
  ui_story_1013_10131202_152_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131202_153_dialog_content = "Vamos a volver, ¿verdad?",
  ui_story_1013_10131202_154_dialog_content = "Sí somos.",
  ui_story_1013_10131202_155_dialog_content = "El maestro Francis dijo que obtendremos las señales para regresar.",
  ui_story_1013_10131202_156_dialog_content = "Todos confiamos en él, ¿verdad?",
  ui_story_1013_10131301_1_dialog_content = "¡Este es un registro de las conversaciones de Caelestites!",
  ui_story_1013_10131301_2_dialog_content = "¿Hay otros colosos a nuestro alrededor?",
  ui_story_1013_10131301_3_dialog_content = "Actualmente no se puede recopilar suficiente información.",
  ui_story_1013_10131301_4_dialog_content = "Pero eso es ciertamente posible.",
  ui_story_1013_10131301_5_dialog_content = "De las conversaciones, los otros Colosos también están sellados herméticamente como Soroz.",
  ui_story_1013_10131301_6_dialog_content = "Todo el mundo pasaba día tras día jugando con los pulgares...",
  ui_story_1013_10131301_7_dialog_content = "(Qué sentimiento familiar.)",
  ui_story_1013_10131301_8_dialog_content = "(¿No es así como fue mi infancia?)",
  ui_story_1013_10131301_9_dialog_content = "Guardian One postula que la razón de esto es el exilio o el refugio.",
  ui_story_1013_10131301_10_dialog_content = "Exilio: Alguien confinó a ciertos Caelestites en los Colosos para desterrarlos a un lugar designado.",
  ui_story_1013_10131301_11_dialog_content = "Refugio: El ambiente fuera de los Colosos era inequívocamente inhabitable para los Caelestitas. Por lo tanto, fueron sellados para proteger a sus pasajeros.",
  ui_story_1013_10131301_12_dialog_content = "Por el tono de las conversaciones, prefiero creer que fue por una emergencia.",
  ui_story_1013_10131301_13_dialog_content = "Mencionaron un nombre familiar... Francis.",
  ui_story_1013_10131301_14_dialog_content = "¿Conoces ese nombre?",
  ui_story_1013_10131301_15_dialog_content = "Realmente no. Tuve el honor de ver lo que dejó atrás.",
  ui_story_1013_10131301_16_dialog_content = "Debe haber dejado una impresión en ti, entonces.",
  ui_story_1013_10131301_17_dialog_content = "Por supuesto. Era un Caelestita muy especial.",
  ui_story_1013_10131301_18_dialog_content = "Incluso podrías llamarlo una antítesis de otros Caelestitas de su tiempo.",
  ui_story_1013_10131301_19_dialog_content = "Él no eligió traer la guerra al mundo. Todo lo contrario, luchó contra el destino que se impuso a los Caelestitas.",
  ui_story_1013_10131301_20_dialog_content = "Una vez me conmovió profundamente su voluntad en un momento en que pensé que se había perdido toda esperanza.",
  ui_story_1013_10131301_21_dialog_content = "Afortunadamente, ahora se ha hecho evidente que él no era el único con ese tipo de resolución.",
  ui_story_1013_10131301_22_dialog_content = "¿Te refieres a los que conversaban?",
  ui_story_1013_10131301_23_dialog_content = "Sí, los Caelestitas se identificaron con números.",
  ui_story_1013_10131301_24_dialog_content = "Han pasado generaciones, pero compartimos la misma confianza por el mismo nombre.",
  ui_story_1013_10131301_25_dialog_content = "Solo eso me hace sentir que tenían fe.",
  ui_story_1013_10131301_26_dialog_content = "No se vieron obligados a exiliarse, sino que eligieron su propio camino.",
  ui_story_1013_10131301_27_dialog_content = "Tal vez fue algo terrible lo que los obligó a adoptar medidas tan extremas.",
  ui_story_1013_10131301_28_dialog_content = "Esa es una teoría muy peculiar. Guardián Uno no entiende, pero se ha tomado nota de su conclusión.",
  ui_story_1013_10131301_29_dialog_content = "No tienes que salir de tu camino para anotarlo...",
  ui_story_1013_10131301_30_dialog_content = "La conversación termina ahí. ¿Hay otra información disponible?",
  ui_story_1013_10131301_31_dialog_content = "No eso es todo.",
  ui_story_1013_10131301_32_dialog_content = "Entonces, ¿qué hacemos ahora?",
  ui_story_1013_10131301_33_dialog_content = "No encontramos fallas y no tenemos ninguna pista.",
  ui_story_1013_10131301_34_dialog_content = "¿Se supone que debemos sentarnos aquí y experimentar el aburrimiento como los otros Caelestites?",
  ui_story_1013_10131301_35_dialog_content = "Ese es ciertamente un método muy ineficiente para examinar datos.",
  ui_story_1013_10131301_36_dialog_content = "Espere mientras realizo una búsqueda más precisa.",
  ui_story_1013_10131301_37_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_1013_10131301_38_dialog_content = "¿Qué fue eso? ¿Qué hiciste?",
  ui_story_1013_10131301_39_dialog_content = "Esto puede afectar las imágenes que ve, pero no entre en pánico.",
  ui_story_1013_10131301_40_dialog_content = "No estoy entrando en pánico, solo confundido.",
  ui_story_1013_10131301_41_dialog_content = "Para decirlo de una manera que puedas comprender, Guardian One está clasificando los recuerdos.",
  ui_story_1013_10131301_42_dialog_content = "Estamos avanzando rápidamente en recuerdos pasados sin fallas.",
  ui_story_1013_10131301_43_dialog_content = "¿Usted puede hacer eso?",
  ui_story_1013_10131301_44_dialog_content = "Gaaaaah!!",
  ui_story_1013_10131301_45_dialog_content = "¡Whoa!",
  ui_story_1013_10131301_46_dialog_content = "¡¿Qué está pasando?!",
  ui_story_1013_10131301_47_dialog_content = "Ignorar todos los datos no corrompidos naturalmente nos haría terminar—",
  ui_story_1013_10131301_48_dialog_content = "¡Graagh!",
  ui_story_1013_10131301_49_dialog_content = "Oye, ¿estás bien?",
  ui_story_1013_10131301_50_dialog_content = "—donde están los fallos.",
  ui_story_1013_10131301_51_dialog_content = "¡Tiempos como este requieren una explicación directa!",
  ui_story_1013_10131301_52_dialog_content = "Entonces, ¿los eclipses son los fallos?",
  ui_story_1013_10131301_53_dialog_content = "Sí. Los fallos se manifestarán como imágenes que no te gustan o que detestas:",
  ui_story_1013_10131301_54_dialog_content = "¡Graagh!",
  ui_story_1013_10131301_55_dialog_content = "Tú—",
  ui_story_1013_10131301_56_dialog_content = "—Está bien, mi estructura de datos es muy duradera. No se desmoronará fácilmente.",
  ui_story_1013_10131301_57_dialog_content = "Está bien, lo entiendo, simplemente no te conviertas en un saco de boxeo nunca más. es aterrador",
  ui_story_1013_10131301_58_dialog_content = "No sé nada de datos, ni tengo tiempo para lecciones.",
  ui_story_1013_10131301_59_dialog_content = "Pero como están en forma de Eclipsite, ¡los trataré como si fueran Eclipsites!",
  ui_story_1013_10131302_1_dialog_content = "¡Torrente rápido!",
  ui_story_1013_10131302_2_dialog_content = "¡Flor de hielo!",
  ui_story_1013_10131302_3_dialog_content = "Vaya, esto se siente increíble...",
  ui_story_1013_10131302_4_dialog_content = "Guardian One no tiene claro el beneficio de tales vocalizaciones en la batalla.",
  ui_story_1013_10131302_5_dialog_content = "En realidad, lo mismo.",
  ui_story_1013_10131302_6_dialog_content = "Acabo de ver a los aurorianos hacerlo todo el tiempo en las peleas, así que pensé en intentarlo.",
  ui_story_1013_10131302_7_dialog_content = "¿Tal vez es genial decir tus movimientos mientras peleas?",
  ui_story_1013_10131302_8_dialog_content = "Mira, los enemigos son demolidos después de que grito, así que funciona.",
  ui_story_1013_10131302_9_dialog_content = "Mmm. Guardian One intentará entender este argumento que está completamente desprovisto de lógica.",
  ui_story_1013_10131302_10_dialog_content = "Ja, dejemos eso a un lado por ahora. Entonces, ¿algún cambio en Soroz?",
  ui_story_1013_10131302_11_dialog_content = "Se eliminó aproximadamente el 37% de los fallos. Tus acciones han sido efectivas.",
  ui_story_1013_10131302_12_dialog_content = "Se han restaurado funciones parciales.",
  ui_story_1013_10131302_13_dialog_content = "37%! ¿Me deshice de tanto de una vez?",
  ui_story_1013_10131302_14_dialog_content = "Soroz rectificará los fallos aislados y dispersos por sí mismo.",
  ui_story_1013_10131302_15_dialog_content = "Por lo tanto, las fallas que aún nos esperan exhibirán una mayor cohesión.",
  ui_story_1013_10131302_16_dialog_content = "Según los cálculos, solo queda un lote de fallas.",
  ui_story_1013_10131302_17_dialog_content = "¡Muy bien, eso significa que estamos cerca de tener éxito!",
  ui_story_1013_10131302_18_dialog_content = "Sí, pero el lote es más conflictivo. Debes tener precaución.",
  ui_story_1013_10131302_19_dialog_content = "Si está listo, Guardian One iniciará una búsqueda de precisión y avanzará rápidamente hasta las fallas.",
  ui_story_1013_10131302_20_dialog_content = "Espera, el segmento de tiempo en el que estamos ahora es diferente al que teníamos cuando empezamos, ¿verdad?",
  ui_story_1013_10131302_21_dialog_content = "Correcto. La búsqueda saltó durante un período muy largo.",
  ui_story_1013_10131302_22_dialog_content = "Debido a la falta de puntos de referencia, no se puede determinar el tramo exacto.",
  ui_story_1013_10131302_23_dialog_content = "Si ese es el caso, me gustaría comprobar la terminal de nuevo.",
  ui_story_1013_10131302_24_dialog_content = "Tengo curiosidad por saber por lo que pasaron los Caelestites en este momento.",
  ui_story_1013_10131302_25_dialog_content = "Comprendido. Guardian One extraerá los mensajes de la terminal por usted.",
  ui_story_1013_10131302_26_dialog_content = "Recuerde traducirlo para mí primero.",
  ui_story_1013_10131302_27_dialog_content = "Por supuesto. La optimización y la eficiencia impulsan las acciones de toda la IA.",
  ui_story_1013_10131302_28_dialog_content = "Y Guardian One es el modelo más óptimo.",
  ui_story_1013_10131302_29_dialog_content = "¡Hola a todos!",
  ui_story_1013_10131302_30_dialog_content = "¡Aquí!",
  ui_story_1013_10131302_31_dialog_content = "Esto es bastante repentino, pero hoy es en realidad mi cumpleaños.",
  ui_story_1013_10131302_32_dialog_content = "¿Alguien quiere oírme cantar una canción?",
  ui_story_1013_10131302_33_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_34_dialog_content = "Bien, cambié de opinión.",
  ui_story_1013_10131302_35_dialog_content = "Sin canción ¡Les escribiré un poema!",
  ui_story_1013_10131302_36_dialog_content = "Escribo buenos poemas. ¡Papá dijo que crecería para ser poeta!",
  ui_story_1013_10131302_37_dialog_content = "Recuerdo tu último cumpleaños, 35.",
  ui_story_1013_10131302_38_dialog_content = "Olvidé cuánto tiempo fue, pero definitivamente no fue hace un año hoy.",
  ui_story_1013_10131302_39_dialog_content = "Tienes buena memoria, 982. Y aquí pensé que podía engañarlos a todos...",
  ui_story_1013_10131302_40_dialog_content = "Los cumpleaños son importantes, no los uses como bromas.",
  ui_story_1013_10131302_41_dialog_content = "No importa, olvida el cumpleaños entonces.",
  ui_story_1013_10131302_42_dialog_content = "¡Déjame compartir un consejo con todos ustedes!",
  ui_story_1013_10131302_43_dialog_content = "Caliente la lata #4 y mézclela con una lata congelada #15.",
  ui_story_1013_10131302_44_dialog_content = "¡Es súper delicioso! ¡Tienen que probarlo!",
  ui_story_1013_10131302_45_dialog_content = "Tan burbujeante como siempre, 35.",
  ui_story_1013_10131302_46_dialog_content = "79! ¡Ha sido un tiempo!",
  ui_story_1013_10131302_47_dialog_content = "Sí lo tiene. Raramente reviso la terminal ahora.",
  ui_story_1013_10131302_48_dialog_content = "Deberías revisar más a menudo. No me gusta hablar solo.",
  ui_story_1013_10131302_49_dialog_content = "Bueno, creo que a 982 le gusta ser tu cómplice.",
  ui_story_1013_10131302_50_dialog_content = "De ninguna manera, aparece incluso menos que tú, ¡79!",
  ui_story_1013_10131302_51_dialog_content = "¡Vino hoy solo para avergonzarme!",
  ui_story_1013_10131302_52_dialog_content = "¿Debería disculparme?",
  ui_story_1013_10131302_53_dialog_content = "Bueno no. Me equivoqué al mentir.",
  ui_story_1013_10131302_54_dialog_content = "De hecho, decidí revisar el terminal porque hoy es especial para mí.",
  ui_story_1013_10131302_55_dialog_content = "Me gustaría conmemorarlo.",
  ui_story_1013_10131302_56_dialog_content = "Oh, ¿hoy es el cumpleaños de 982?",
  ui_story_1013_10131302_57_dialog_content = "No.",
  ui_story_1013_10131302_58_dialog_content = "Se podría decir que hoy es exactamente el polo opuesto de un cumpleaños.",
  ui_story_1013_10131302_59_dialog_content = "982, no me digas...",
  ui_story_1013_10131302_60_dialog_content = "Oh, ¿no mencionaste escribir un poema? ¿Qué tal escribir uno para mí?",
  ui_story_1013_10131302_61_dialog_content = "¡Por supuesto! ¿Algún tema que quieras solicitar?",
  ui_story_1013_10131302_62_dialog_content = "El terreno. Un poema que tiene que ver con la superficie debajo de nosotros.",
  ui_story_1013_10131302_63_dialog_content = "Bien, ¡déjame pensarlo y escribir uno que te encantará!",
  ui_story_1013_10131302_64_dialog_content = "¿Cuánto tiempo llevará?",
  ui_story_1013_10131302_65_dialog_content = "No estoy seguro. Las ideas no me llegan en este momento.",
  ui_story_1013_10131302_66_dialog_content = "¿Puedes esperar? ¡Te llamaré tan pronto como termine!",
  ui_story_1013_10131302_67_dialog_content = "Deberías acelerarlo antes de que decida que ya no lo quiero.",
  ui_story_1013_10131302_68_dialog_content = "¡No puedes hacer eso! ¡No todos los días puedo escribir un poema para otra persona!",
  ui_story_1013_10131302_69_dialog_content = "¡Tienes que tomarlo!",
  ui_story_1013_10131302_70_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_71_dialog_content = "¡Tu poema está listo, 982!",
  ui_story_1013_10131302_72_dialog_content = "982?",
  ui_story_1013_10131302_73_dialog_content = "¡Oye, puse mucho esfuerzo y pensé en ello!",
  ui_story_1013_10131302_74_dialog_content = "¡Me voy a enojar si no respondes pronto!",
  ui_story_1013_10131302_75_dialog_content = "982! 982! 982!",
  ui_story_1013_10131302_76_dialog_content = "...",
  ui_story_1013_10131302_77_dialog_content = "Olvídalo. No voy a pelear contigo por asuntos tan triviales.",
  ui_story_1013_10131302_78_dialog_content = "Avísame cuando estés de vuelta. Estoy aqui todo el tiempo.",
  ui_story_1013_10131302_79_dialog_content = "Llegas muy temprano hoy, 35.",
  ui_story_1013_10131302_80_dialog_content = "Sí, porque me quedé despierto toda la noche terminando el poema de 982.",
  ui_story_1013_10131302_81_dialog_content = "Pero él...",
  ui_story_1013_10131302_82_dialog_content = "Wow, trabajaste duro, ¿eh?",
  ui_story_1013_10131302_83_dialog_content = "Pero ya sabes lo voluble que es el 982.",
  ui_story_1013_10131302_84_dialog_content = "Lo que quería ayer, puede que no lo quiera hoy.",
  ui_story_1013_10131302_85_dialog_content = "Eso es cierto, ¡él hace eso!",
  ui_story_1013_10131302_86_dialog_content = "Así que no te preocupes por eso. Envíamelo a mí en su lugar. Quiero ver qué tan talentoso eres.",
  ui_story_1013_10131302_87_dialog_content = "Pero esperaba que 982 lo leyera primero ya que es su regalo.",
  ui_story_1013_10131302_88_dialog_content = "Si quieres, también puedo escribirte uno, ¡79!",
  ui_story_1013_10131302_89_dialog_content = "¿Para mí?",
  ui_story_1013_10131302_90_dialog_content = "Mejor no, no quiero que vuelvas a quemar el aceite de medianoche.",
  ui_story_1013_10131302_91_dialog_content = "¡No, está totalmente bien! Tenemos tiempo más que suficiente para dormir estos días.",
  ui_story_1013_10131302_92_dialog_content = "No puedo hacer que escribas un poema en un día cualquiera.",
  ui_story_1013_10131302_93_dialog_content = "Dame uno en el futuro.",
  ui_story_1013_10131302_94_dialog_content = "Espera un día que sea especial para mí.",
  ui_story_1013_10131302_95_dialog_content = "Oh, okay.",
  ui_story_1013_10131302_96_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_97_dialog_content = "Hoy encontré un disco de vinilo sin abrir en el almacén.",
  ui_story_1013_10131302_98_dialog_content = "¡Es bastante bueno! ¿Alguien quiere escucharlo?",
  ui_story_1013_10131302_99_dialog_content = "Oye, ¿hay alguien ahí?",
  ui_story_1013_10131302_100_dialog_content = "De todos modos, lo subí a la terminal, ¡así que échale un vistazo si estás interesado!",
  ui_story_1013_10131302_101_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_102_dialog_content = "Mi dispositivo de baño dejó de funcionar...",
  ui_story_1013_10131302_103_dialog_content = "¿Alguien sabe cómo arreglarlo?",
  ui_story_1013_10131302_104_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_105_dialog_content = "La temperatura por aquí ha bajado. Traten de mantenerse abrigados y abrigados, todos.",
  ui_story_1013_10131302_106_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_107_dialog_content = "Uh, no he hablado con nadie en mucho tiempo, así que me encantaría charlar.",
  ui_story_1013_10131302_108_dialog_content = "Hoy es mi cumpleaños.",
  ui_story_1013_10131302_109_dialog_content = "Es de verdad, esta vez.",
  ui_story_1013_10131302_110_dialog_content = "Alguien, por favor háblame...",
  ui_story_1013_10131302_111_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_112_dialog_content = "No he sabido nada de usted en mucho tiempo, Sr. 217.",
  ui_story_1013_10131302_113_dialog_content = "No estabas mintiendo cuando dijiste que volveríamos, ¿verdad?",
  ui_story_1013_10131302_114_dialog_content = "¿Ya no quieres tu poema, estúpido 982?",
  ui_story_1013_10131302_115_dialog_content = "¿Cuándo te volveré a ver en la terminal, 79?",
  ui_story_1013_10131302_116_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_117_dialog_content = "Suspiro, no hay nadie aquí.",
  ui_story_1013_10131302_118_dialog_content = "El historial está lleno de mis mensajes.",
  ui_story_1013_10131302_119_dialog_content = "Siento que todos me odian.",
  ui_story_1013_10131302_120_dialog_content = "Esto no puede seguir.",
  ui_story_1013_10131302_121_dialog_content = "¡Lo tengo!",
  ui_story_1013_10131302_122_dialog_content = "Comando: ¡Verificación de estado para todos los Colosos!",
  ui_story_1013_10131302_123_dialog_content = "Colossus 217, perfecto, sin anomalías.",
  ui_story_1013_10131302_124_dialog_content = "Colossus 982, perfecto, sin anomalías.",
  ui_story_1013_10131302_125_dialog_content = "Colossus 79, perfecto, sin anomalías.",
  ui_story_1013_10131302_126_dialog_content = "Colossus 35, perfecto, sin anomalías.",
  ui_story_1013_10131302_127_dialog_content = "¡Aquí vamos! ¡Eso es un poco más animado!",
  ui_story_1013_10131401_1_dialog_content = "Bueno, terminé.",
  ui_story_1013_10131401_2_dialog_content = "Siento una tristeza indescriptible.",
  ui_story_1013_10131401_3_dialog_content = "Guardián Uno no entiende.",
  ui_story_1013_10131401_4_dialog_content = "Basado en el análisis, fue solo un diálogo normal y no debería evocar tristeza.",
  ui_story_1013_10131401_5_dialog_content = "Mira estos registros. El número de participantes fue disminuyendo a medida que pasaba el tiempo.",
  ui_story_1013_10131401_6_dialog_content = "Hasta que solo quedó uno.",
  ui_story_1013_10131401_7_dialog_content = "Empatizo con ese sentimiento.",
  ui_story_1013_10131401_8_dialog_content = "Expresar pensamientos sin sentido en voz alta a nadie, día tras día...",
  ui_story_1013_10131401_9_dialog_content = "solo por la oportunidad de obtener una respuesta que reavivaría la esperanza.",
  ui_story_1013_10131401_10_dialog_content = "Pero al final, incluso ese simple deseo fue en vano.",
  ui_story_1013_10131401_11_dialog_content = "Comprendido. No estabas aludiendo al contenido real sino al número de participantes y la frecuencia de sus mensajes.",
  ui_story_1013_10131401_12_dialog_content = "Guardian One ha tomado nota de esta expresión empática.",
  ui_story_1013_10131401_13_dialog_content = "Yo no llamaría a eso... sabes qué, es difícil de explicar.",
  ui_story_1013_10131401_14_dialog_content = "Sentí su desesperación por el contacto social.",
  ui_story_1013_10131401_15_dialog_content = "Esa es la opresión que siento. Incluso se podría decir que le temo.",
  ui_story_1013_10131401_16_dialog_content = "Miedo. ¿Temes que te pongan en su lugar?",
  ui_story_1013_10131401_17_dialog_content = "Sí. Pero cuando lo pienso, he tenido una experiencia similar.",
  ui_story_1013_10131401_18_dialog_content = "Una vez viví solo bajo tierra durante 17 años.",
  ui_story_1013_10131401_19_dialog_content = "No sé si eso es más largo o más corto de lo que pasaron.",
  ui_story_1013_10131401_20_dialog_content = "Pero mi desesperación no era tan fuerte como la de ellos.",
  ui_story_1013_10131401_21_dialog_content = "Tal vez porque tuve a Soroz conmigo todo el tiempo.",
  ui_story_1013_10131401_22_dialog_content = "Espera, pero también tenían Colosos...",
  ui_story_1013_10131401_23_dialog_content = "Es solo que los suyos no parecían tener ninguna personalidad.",
  ui_story_1013_10131401_24_dialog_content = "Después de todo, no se puede combatir el aislamiento con respuestas meramente mecánicas.",
  ui_story_1013_10131401_25_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_1013_10131401_26_dialog_content = "¿Mmm? ¿Qué esta pasando?",
  ui_story_1013_10131401_27_dialog_content = "¿Estás avanzando rápido de nuevo, Guardián Uno?",
  ui_story_1013_10131401_28_dialog_content = "Guardian One no está ejecutando ningún comando.",
  ui_story_1013_10131401_29_dialog_content = "Eso significa que esto es...",
  ui_story_1013_10131401_30_dialog_content = "Yo-Se detuvo.",
  ui_story_1013_10131401_31_dialog_content = "Solo estamos examinando los datos almacenados de Soroz en orden cronológico.",
  ui_story_1013_10131401_32_dialog_content = "Ese fenómeno indica que hay un problema con los datos en sí.",
  ui_story_1013_10131401_33_dialog_content = "¿Datos defectuosos?",
  ui_story_1013_10131401_34_dialog_content = "Es extraño, pero según mi evaluación, el mal funcionamiento no se debió a la eliminación de datos.",
  ui_story_1013_10131401_35_dialog_content = "No puedo encontrar un mal funcionamiento equivalente en mi base de datos.",
  ui_story_1013_10131401_36_dialog_content = "¿Hay cosas que ni siquiera tú sabes?",
  ui_story_1013_10131401_37_dialog_content = "Esto es muy extraño. Quizás esto no sea un mal funcionamiento, sino una anomalía.",
  ui_story_1013_10131401_38_dialog_content = "¿Una anomalía?",
  ui_story_1013_10131401_39_dialog_content = "Sí. Guardian One encontró datos similares en un registro no relacionado con la máquina.",
  ui_story_1013_10131401_40_dialog_content = "Se parece mucho al \"olvido\" que es común en el cerebro de los seres vivos.",
  ui_story_1013_10131401_41_dialog_content = "¿Olvido? ¿Quieres decir que Soroz olvidó ciertos recuerdos, por lo que nos hemos saltado ciertos momentos en el tiempo?",
  ui_story_1013_10131401_42_dialog_content = "Si la teoría se sostiene, esa es la conclusión lógica.",
  ui_story_1013_10131401_43_dialog_content = "Pero es ilógico que las máquinas olviden, ya que siguen un protocolo más complejo para eliminar datos.",
  ui_story_1013_10131401_44_dialog_content = "¡Eso realmente lo explica porque Soroz no es una máquina!",
  ui_story_1013_10131401_45_dialog_content = "¡Reinicia la terminal de nuevo, Guardián Uno!",
  ui_story_1013_10131401_46_dialog_content = "Si ha pasado el tiempo, debería haber nuevos registros en la terminal.",
  ui_story_1013_10131401_47_dialog_content = "Sí. Espere por favor.",
  ui_story_1013_10131401_48_dialog_content = "Comando: ¡Regístrese, Coloso 35!",
  ui_story_1013_10131401_49_dialog_content = "Colossus 35 está listo, esperando órdenes.",
  ui_story_1013_10131401_50_dialog_content = "Muy bien, ahora retomaré la historia de la última vez.",
  ui_story_1013_10131401_51_dialog_content = "Esto es sobre el día que partí.",
  ui_story_1013_10131401_52_dialog_content = "Acababa de obtener mis credenciales de Navigator y era la primera vez que pilotaba un Colossus.",
  ui_story_1013_10131401_53_dialog_content = "Pasé toda una noche pensando en todos los posibles escenarios de emergencia y cómo debería responder.",
  ui_story_1013_10131401_54_dialog_content = "Empaqué mis maletas llenas de ropa que me costó cada centavo de mi asignación.",
  ui_story_1013_10131401_55_dialog_content = "Planeé guardar el mejor atuendo para nuestro regreso a casa. Quería volver como un héroe.",
  ui_story_1013_10131401_56_dialog_content = "Al final resultó que, nada de eso terminó siendo de ninguna utilidad.",
  ui_story_1013_10131401_57_dialog_content = "No nos encontramos con ninguna emergencia. Ni una sola vez. Eventualmente, ya ni siquiera tengo que pilotar.",
  ui_story_1013_10131401_58_dialog_content = "Ese conjunto todavía está cuidadosamente doblado en la maleta.",
  ui_story_1013_10131401_59_dialog_content = "Me lo probé ayer y descubrí que ahora me queda pequeño.",
  ui_story_1013_10131401_60_dialog_content = "Suspiro, era un vestido tan bonito... ¿Sigues escuchando, Colossus 35?",
  ui_story_1013_10131401_61_dialog_content = "Comando: ¡Regístrese, Coloso 35!",
  ui_story_1013_10131401_62_dialog_content = "Colossus 35 está listo, esperando órdenes.",
  ui_story_1013_10131401_63_dialog_content = "Es bueno que todavía estés escuchando. voy a seguir adelante...",
  ui_story_1013_10131401_64_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131401_65_dialog_content = "Comando: ¡Regístrate, Coloso 982!",
  ui_story_1013_10131401_66_dialog_content = "Colossus 982 está listo, esperando órdenes.",
  ui_story_1013_10131401_67_dialog_content = "¡Bueno! Hoy, serás tú quien escuche mi narración.",
  ui_story_1013_10131401_68_dialog_content = "¿Por qué no hablo de después de que partimos? Todos habían comenzado a acostumbrarse a no verse y solo chatear a través de la terminal.",
  ui_story_1013_10131401_69_dialog_content = "Todos nuestros Colosos tienen designaciones, así que eso es lo que usábamos para dirigirnos unos a otros.",
  ui_story_1013_10131401_70_dialog_content = "Entonces me asustó porque los números me parecen impersonales y fríos.",
  ui_story_1013_10131401_71_dialog_content = "Así que insistí en llamar a los demás por sus nombres.",
  ui_story_1013_10131401_72_dialog_content = "¿Cuánto tiempo mantuve eso? Varios meses, tal vez un año... no recuerdo.",
  ui_story_1013_10131401_73_dialog_content = "Hasta que olvidé un nombre por primera vez.",
  ui_story_1013_10131401_74_dialog_content = "No hubiera sido educado llamarlo solo a él y a nadie más por número.",
  ui_story_1013_10131401_75_dialog_content = "No tuve más remedio que comenzar a llamar a todos por sus designaciones.",
  ui_story_1013_10131401_76_dialog_content = "982 me lo atribuyó mientras crecía, pero en realidad lo odiaba.",
  ui_story_1013_10131401_77_dialog_content = "No quería crecer ni olvidar los nombres de todos.",
  ui_story_1013_10131401_78_dialog_content = "...",
  ui_story_1013_10131401_79_dialog_content = "Sí, todo el mundo merece un nombre. Incluso los Colosos.",
  ui_story_1013_10131401_80_dialog_content = "¡Lo sé! ¡Nombraré a los Colosos, no más números!",
  ui_story_1013_10131401_81_dialog_content = "El primero eres tú, 982. Déjame ver...",
  ui_story_1013_10131401_82_dialog_content = "Tu navegante es un tipo irritante, pero \"Irritable\" no es un buen nombre, así que debería ser otra cosa.",
  ui_story_1013_10131401_83_dialog_content = "¡Te llamaré \"Solituz\"!",
  ui_story_1013_10131401_84_dialog_content = "Comando: Revisar el distintivo de llamada de Colossus 982 de 982 a Solituz.",
  ui_story_1013_10131401_85_dialog_content = "Comando copiado. Distintivo de llamada revisado.",
  ui_story_1013_10131401_86_dialog_content = "El siguiente es 217!",
  ui_story_1013_10131401_87_dialog_content = "El Sr. 217 es como nuestro líder, ¡así que Naviduz será tu nombre!",
  ui_story_1013_10131401_88_dialog_content = "Comando: Revisar el distintivo de llamada para Colossus 217 de 217 a Naviduz.",
  ui_story_1013_10131401_89_dialog_content = "Comando copiado. Distintivo de llamada revisado.",
  ui_story_1013_10131401_90_dialog_content = "Luego tenemos a Miss 79. Es amable y considerada, ¡así que necesitamos un nombre bonito para su Colossus!",
  ui_story_1013_10131401_91_dialog_content = "Un bonito nombre... Un bonito nombre...",
  ui_story_1013_10131401_92_dialog_content = "¿Me estás llamando, 35?",
  ui_story_1013_10131401_93_dialog_content = "79! ¡Por fin estás en la terminal!",
  ui_story_1013_10131401_94_dialog_content = "Sí. Estoy impresionado, 35, que puedes mantener una conversación animada por tu cuenta.",
  ui_story_1013_10131401_95_dialog_content = "Je. Estoy nombrando los Colosos de todos en este momento.",
  ui_story_1013_10131401_96_dialog_content = "¿Nombrando a los Colosos? Eso suena divertido, y como algo que harías.",
  ui_story_1013_10131401_97_dialog_content = "¡Sí, es divertido! ¡Quiero darle un nombre a cada coloso!",
  ui_story_1013_10131401_98_dialog_content = "Esa es una tarea difícil, dada la cantidad de Colosos que tenemos.",
  ui_story_1013_10131401_99_dialog_content = "Bueno, no tenemos nada más que tiempo de todos modos.",
  ui_story_1013_10131401_100_dialog_content = "Cierto.",
  ui_story_1013_10131401_101_dialog_content = "Oh, estaba a punto de nombrar tu Coloso. ¿Algunas ideas?",
  ui_story_1013_10131401_102_dialog_content = "En realidad 35, tengo una solicitud para ti hoy.",
  ui_story_1013_10131401_103_dialog_content = "¿Una solicitud? ¿Te refieres a algo que pueda hacer por ti?",
  ui_story_1013_10131401_104_dialog_content = "Sí.",
  ui_story_1013_10131401_105_dialog_content = "Me gustaría que me escribieras un poema.",
  ui_story_1013_10131401_106_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131401_107_dialog_content = "¿Harías eso por mí, 35?",
  ui_story_1013_10131401_108_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_1013_10131401_109_dialog_content = "¿Qué sucedió? ¡No he terminado de leerlo!",
  ui_story_1013_10131401_110_dialog_content = "¿Estamos saltando el tiempo?",
  ui_story_1013_10131401_111_dialog_content = "La asignación de datos es escasa para este segmento en particular.",
  ui_story_1013_10131401_112_dialog_content = "En un idioma que pueda entender, por favor.",
  ui_story_1013_10131401_113_dialog_content = "Soroz no tiene muchos recuerdos de este período de tiempo.",
  ui_story_1013_10131401_114_dialog_content = "Para ser justos, no había mucho que recordar.",
  ui_story_1013_10131401_115_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1013_10131401_116_dialog_content = "¡Guau! ¡Eso salio de la nada!",
  ui_story_1013_10131401_117_dialog_content = "¿Qué es ese sonido?",
  ui_story_1013_10131401_118_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1013_10131401_119_dialog_content = "La puerta de la cabina está siendo embestida desde el exterior.",
  ui_story_1013_10131401_120_dialog_content = "¿Quién está haciendo eso? Aquí nunca hubo nadie más.",
  ui_story_1013_10131401_121_dialog_content = "Espera, a menos que...",
  ui_story_1013_10131401_122_dialog_content = "Evaluación: Hemos llegado a la falla causada por la anomalía de datos.",
  ui_story_1013_10131401_123_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_1013_10131401_124_dialog_content = "¡Podrías haberme avisado con anticipación para que tuviera tiempo de prepararme!",
  ui_story_1013_10131401_125_dialog_content = "Espera, no creo que sea un eclipse... ¿Qué es eso?",
  ui_story_1013_10131401_126_dialog_content = "...",
  ui_story_1013_10131401_127_dialog_content = "¿Una flor? ¿Creciendo en el suelo de la cabina?",
  ui_story_1013_10131401_128_dialog_content = "No necesito que me lo digas esta vez para saber que es un problema técnico.",
  ui_story_1013_10131401_129_dialog_content = "Sí, lo es. Pero Guardian One no entiende cómo llegaste a esa conclusión.",
  ui_story_1013_10131401_130_dialog_content = "¡Porque no es lógico! ¿Qué flores podrían crecer aquí?",
  ui_story_1013_10131401_131_dialog_content = "¿Pero no dijiste que los fallos tomarían formas de cosas que no me gustan?",
  ui_story_1013_10131401_132_dialog_content = "Realmente no puedo odiar algo que nunca he visto antes.",
  ui_story_1013_10131401_133_dialog_content = "El análisis de Guardian One es que la oposición evaluó su esfuerzo anterior de detección de fallas.",
  ui_story_1013_10131401_134_dialog_content = "Por lo tanto, hizo ajustes a la falla como contramedida.",
  ui_story_1013_10131401_135_dialog_content = "Accedió a la memoria de Soroz y se manifestó como entidades individuales más adecuadas para la batalla.",
  ui_story_1013_10131401_136_dialog_content = "Uno de los que estás viendo ahora mismo.",
  ui_story_1013_10131401_137_dialog_content = "¿Puede esta cosa pelear?",
  ui_story_1013_10131401_138_dialog_content = "Es un eclipse llamado Diavola que se extrajo de los recuerdos de Soroz.",
  ui_story_1013_10131401_139_dialog_content = "¿Es un eclipse? ¿Te ves así?",
  ui_story_1013_10131401_140_dialog_content = "Sí.",
  ui_story_1013_10131401_141_dialog_content = "Eso es impresionante, cambiar las tácticas en vivo en función de las batallas anteriores.",
  ui_story_1013_10131401_142_dialog_content = "Voy a estar en desventaja si esto persiste durante algunas rondas más.",
  ui_story_1013_10131401_143_dialog_content = "Guardian One, ¿es este el lote final?",
  ui_story_1013_10131401_144_dialog_content = "Sí. Tenga cuidado, contiene más fallas que antes.",
  ui_story_1013_10131401_145_dialog_content = "Sus habilidades de combate también están optimizadas.",
  ui_story_1013_10131401_146_dialog_content = "Lo tengo, lo tengo.",
  ui_story_1013_10131401_147_dialog_content = "¿Te importaría decirme mis posibilidades de ganar?",
  ui_story_1013_10131401_148_dialog_content = "10%.",
  ui_story_1013_10131401_149_dialog_content = "¿Eso es todo?",
  ui_story_1013_10131401_150_dialog_content = "Bueno, al menos no es cero.",
  ui_story_1013_10131401_151_dialog_content = "Es intrascendente. Nuestro objetivo es eliminar fallas en los datos, no ganar batallas.",
  ui_story_1013_10131401_152_dialog_content = "También contarás con mi ayuda.",
  ui_story_1013_10131401_153_dialog_content = "Qué raro, escuchar palabras tan reconfortantes de ti. ¡Me siento mucho mejor ahora!",
  ui_story_1013_10131401_154_dialog_content = "Pero todavía estoy obsesionado con el 10% de posibilidades.",
  ui_story_1013_10131401_155_dialog_content = "Dijiste que estás constantemente optimizando tus acciones, ¿verdad?",
  ui_story_1013_10131401_156_dialog_content = "Sí.",
  ui_story_1013_10131401_157_dialog_content = "Entonces observa atentamente, te daré un ejemplo.",
  ui_story_1013_10131402_1_dialog_content = "Debes esquivar los ataques frontales.",
  ui_story_1013_10131402_2_dialog_content = "¡Sé que sé! ¡Puedo hacerlo yo solo!",
  ui_story_1013_10131402_3_dialog_content = "Luego, concentra tu ataque en el núcleo.",
  ui_story_1013_10131402_4_dialog_content = "¿Puedes reducir la velocidad y darme tiempo para procesar esto por mi cuenta?",
  ui_story_1013_10131402_5_dialog_content = "El núcleo, el núcleo...",
  ui_story_1013_10131402_6_dialog_content = "Guardian One analiza que el momento siguiente es el momento más óptimo para atacar.",
  ui_story_1013_10131402_7_dialog_content = "Tienes tres segundos.",
  ui_story_1013_10131402_8_dialog_content = "Vale, vale, ¡lo tengo! ¡No vuelvas a presionarme con cuentas regresivas!",
  ui_story_1013_10131402_9_dialog_content = "Enfoque. Este es el golpe final.",
  ui_story_1013_10131402_10_dialog_content = "Crujido-",
  ui_story_1013_10131402_11_dialog_content = "Apunta al núcleo.",
  ui_story_1013_10131402_12_dialog_content = "¡Ahora!",
  ui_story_1013_10131402_13_dialog_content = "Crujido-",
  ui_story_1013_10131402_14_dialog_content = "¡Sí, se ha ido!",
  ui_story_1013_10131402_15_dialog_content = "Escaneando el banco de memoria de Soroz.",
  ui_story_1013_10131402_16_dialog_content = "Escaneo completo. No se encontró ningún fallo.",
  ui_story_1013_10131402_17_dialog_content = "Guardian One analiza que se han eliminado todas las fallas en Soroz.",
  ui_story_1013_10131402_18_dialog_content = "¡Vaya, todo se ha ido!",
  ui_story_1013_10131402_19_dialog_content = "¿Eso significa que Soroz puede despertarse ahora?",
  ui_story_1013_10131402_20_dialog_content = "Se han eliminado todas las causas del mal funcionamiento. Actualmente, todos los sistemas de Soroz son funcionales.",
  ui_story_1013_10131402_21_dialog_content = "Todas las funciones han vuelto a la normalidad.",
  ui_story_1013_10131402_22_dialog_content = "En cuanto al \"despertar\" al que aludes, es decir, si se puede restaurar su personalidad, Guardian One no puede confirmarlo.",
  ui_story_1013_10131402_23_dialog_content = "¿Ah?",
  ui_story_1013_10131402_24_dialog_content = "El sistema de personalidad de Soroz está más allá de los parámetros de comprensión de Guardian One.",
  ui_story_1013_10131402_25_dialog_content = "Por lo tanto, Guardian One no puede determinar si se puede restaurar.",
  ui_story_1013_10131402_26_dialog_content = "Sin embargo, podemos comprobarlo a través de la experimentación específica después de que abandonemos este espacio.",
  ui_story_1013_10131402_27_dialog_content = "Entiendo...",
  ui_story_1013_10131402_28_dialog_content = "Hemos completado todo lo que es necesario aquí.",
  ui_story_1013_10131402_29_dialog_content = "Podemos volver a la realidad ahora para examinar más a fondo a Soroz.",
  ui_story_1013_10131402_30_dialog_content = "¿Salimos?",
  ui_story_1013_10131402_31_dialog_content = "Déjame pensar por un minuto...",
  ui_story_1013_10131402_32_dialog_content = "¿Podemos esperar? Me gustaría revisar la terminal nuevamente.",
  ui_story_1013_10131402_33_dialog_content = "Tengo curiosidad por saber qué pasó con los Caelestites.",
  ui_story_1013_10131402_34_dialog_content = "¿Dónde terminó su historia?",
  ui_story_1013_10131402_35_dialog_content = "No hay problema. Permanecer en el espacio de datos no tendrá un impacto negativo en Soroz. Eres libre de navegar.",
  ui_story_1013_10131402_36_dialog_content = "Guardian One extraerá las grabaciones de la terminal.",
  ui_story_1013_10131402_37_dialog_content = "Gracias, Guardián Uno.",
  ui_story_1013_10131402_38_dialog_content = "Me has ayudado mucho.",
  ui_story_1013_10131402_39_dialog_content = "Comando: Misión de viaje, desde las coordenadas registradas de Solituz a las de Naviduz, a toda velocidad.",
  ui_story_1013_10131402_40_dialog_content = "Destinos: Aviduz, Soroz.",
  ui_story_1013_10131402_41_dialog_content = "Retrasar el comando por 3 segundos.",
  ui_story_1013_10131402_42_dialog_content = "Tres, dos, uno... ¡Empieza!",
  ui_story_1013_10131402_43_dialog_content = "Soroz completó el viaje.",
  ui_story_1013_10131402_44_dialog_content = "Aviduz completó el viaje.",
  ui_story_1013_10131402_45_dialog_content = "Hmm, Soroz es una vez más más rápido.",
  ui_story_1013_10131402_46_dialog_content = "Es tan monótono cuando los resultados nunca cambian.",
  ui_story_1013_10131402_47_dialog_content = "Probaremos el tramo de vuelta la próxima vez. Tienes que hacerlo mejor, Aviduz.",
  ui_story_1013_10131402_48_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_49_dialog_content = "Comando: Solituz, reporte el inventario de alimentos.",
  ui_story_1013_10131402_50_dialog_content = "#1 latas restantes: 152. #2 latas restantes: 73. #3 latas restantes...",
  ui_story_1013_10131402_51_dialog_content = "Comando: Naviduz, grabe el informe de Solituz.",
  ui_story_1013_10131402_52_dialog_content = "Grabación. Latas de Solituz #1 restantes: 152...",
  ui_story_1013_10131402_53_dialog_content = "Así es, ustedes dos deberían comunicarse más a menudo.",
  ui_story_1013_10131402_54_dialog_content = "No solo habléis conmigo, sino también entre vosotros.",
  ui_story_1013_10131402_55_dialog_content = "Naviduz, deberías hablar con Solituz.",
  ui_story_1013_10131402_56_dialog_content = "Comando: Naviduz, reporte el inventario de alimentos.",
  ui_story_1013_10131402_57_dialog_content = "#1 latas restantes...",
  ui_story_1013_10131402_58_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_59_dialog_content = "Es hora de cuentos para dormir otra vez, linda.",
  ui_story_1013_10131402_60_dialog_content = "Comando: Chica, graba la conversación.",
  ui_story_1013_10131402_61_dialog_content = "Grabación de conversación.",
  ui_story_1013_10131402_62_dialog_content = "¿Dónde lo dejé ayer? Lo siento, mi memoria no es tan buena como solía ser.",
  ui_story_1013_10131402_63_dialog_content = "Creo que fue la parte en la que te nombré.",
  ui_story_1013_10131402_64_dialog_content = "Una vez que hube nombrado a los otros Colosos, dirigí mi atención a la tuya.",
  ui_story_1013_10131402_65_dialog_content = "Quería un nombre especial para ti porque no te pareces a ningún otro.",
  ui_story_1013_10131402_66_dialog_content = "Eres mi coloso.",
  ui_story_1013_10131402_67_dialog_content = "Reflexioné durante mucho tiempo, pero no podía pensar en nada lo suficientemente especial...",
  ui_story_1013_10131402_68_dialog_content = "El origen del nombre de Cutie se registró ayer.",
  ui_story_1013_10131402_69_dialog_content = "¿Fue? Lo siento me olvidé.",
  ui_story_1013_10131402_70_dialog_content = "Así que eso está hecho... ¿De qué debo hablar ahora?",
  ui_story_1013_10131402_71_dialog_content = "Espera.",
  ui_story_1013_10131402_72_dialog_content = "¡Espera!",
  ui_story_1013_10131402_73_dialog_content = "¿Acabo de darte una orden?",
  ui_story_1013_10131402_74_dialog_content = "Déjame ver...",
  ui_story_1013_10131402_75_dialog_content = "¡No, no ingresé ningún comando!",
  ui_story_1013_10131402_76_dialog_content = "¿Cómo pudiste responderme sin una orden, linda?",
  ui_story_1013_10131402_77_dialog_content = "Es porque me entendiste, ¿verdad?",
  ui_story_1013_10131402_78_dialog_content = "Respóndeme, linda. ¡Sé que puedes!",
  ui_story_1013_10131402_79_dialog_content = "Porque se detectó contenido repetitivo.",
  ui_story_1013_10131402_80_dialog_content = "A Cutie le gustaría grabar contenido nuevo.",
  ui_story_1013_10131402_81_dialog_content = "Estos registros...",
  ui_story_1013_10131402_82_dialog_content = "Se siente como si el Coloso evolucionara a lo largo de ellos.",
  ui_story_1013_10131402_83_dialog_content = "Desde respuestas puramente mecánicas hasta respuestas que contienen cierta autoconciencia...",
  ui_story_1013_10131402_84_dialog_content = "También mencionaba a Soroz... ¿Fue entonces cuando empezó a desarrollar una personalidad?",
  ui_story_1013_10131402_85_dialog_content = "Guardian One encuentra los cambios insondables.",
  ui_story_1013_10131402_86_dialog_content = "Según los registros, Colossi no estaba equipado con un intrincado sistema de inteligencia artificial.",
  ui_story_1013_10131402_87_dialog_content = "Es imposible para ellos desarrollar las llamadas personalidades dadas las circunstancias.",
  ui_story_1013_10131402_88_dialog_content = "Pero lo viste, ¿verdad?",
  ui_story_1013_10131402_89_dialog_content = "El Coloso expresó su deseo diciendo que \"me gustaría\".",
  ui_story_1013_10131402_90_dialog_content = "Sí. Las máquinas sin personalidad no deberían ser capaces de eso.",
  ui_story_1013_10131402_91_dialog_content = "Guardian One confirma que Colossus ganó conciencia de sí mismo, pero no puede comprender el proceso.",
  ui_story_1013_10131402_92_dialog_content = "A ver si hay más.",
  ui_story_1013_10131402_93_dialog_content = "Cuéntame un chiste, Solituz.",
  ui_story_1013_10131402_94_dialog_content = "No pares hasta que me hagas reír.",
  ui_story_1013_10131402_95_dialog_content = "Búsqueda de entradas de idioma relacionadas con \"broma\" y \"risa\".",
  ui_story_1013_10131402_96_dialog_content = "\"Cutie funciona mal y se detiene, pero vuelve a moverse después de un tiempo\".",
  ui_story_1013_10131402_97_dialog_content = "\"Un pasajero pregunta qué sucedió. Cutie dice: 'Está bien, acabo de encontrar una nueva Caelestite lo suficientemente audaz como para tomar las riendas'\".",
  ui_story_1013_10131402_98_dialog_content = "Jajaja...",
  ui_story_1013_10131402_99_dialog_content = "Divertido, muy divertido.",
  ui_story_1013_10131402_100_dialog_content = "Objeción. Solituz ha contado el mismo chiste muchas veces. Es contenido repetitivo.",
  ui_story_1013_10131402_101_dialog_content = "¿Es eso así? Lo siento, no puedo recordar.",
  ui_story_1013_10131402_102_dialog_content = "Es divertido, pero no vuelvas a repetir las cosas, Solituz.",
  ui_story_1013_10131402_103_dialog_content = "Todos ustedes deben ejercitar su creatividad.",
  ui_story_1013_10131402_104_dialog_content = "Aprende a contar chistes, cantar y escribir poesía.",
  ui_story_1013_10131402_105_dialog_content = "Aprende todo lo que es maravilloso en este mundo.",
  ui_story_1013_10131402_106_dialog_content = "Copiar. Solituz ajustará la prioridad de la información repetida.",
  ui_story_1013_10131402_107_dialog_content = "No cuento el último, así que cuéntame otro chiste.",
  ui_story_1013_10131402_108_dialog_content = "Lo mismo, no pares hasta que me hagas reír.",
  ui_story_1013_10131402_109_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_110_dialog_content = "Sugerencia de Naviduz para el nombre: Cans.",
  ui_story_1013_10131402_111_dialog_content = "No, eso suena horrible.",
  ui_story_1013_10131402_112_dialog_content = "Sugerencia de nombre de Aviduz: Aviduz.",
  ui_story_1013_10131402_113_dialog_content = "¿Estás tratando de holgazanear usando tu propio nombre?",
  ui_story_1013_10131402_114_dialog_content = "Sugerencia de nombre de Soroz: Sky-sky.",
  ui_story_1013_10131402_115_dialog_content = "Supongo que nombrar es demasiado pronto para ti, Soroz.",
  ui_story_1013_10131402_116_dialog_content = "Caray, les di nombres geniales, y ustedes me pagan dando los nombres más horribles.",
  ui_story_1013_10131402_117_dialog_content = "No importa, sigue llamándome 35.",
  ui_story_1013_10131402_118_dialog_content = "Olvidé los nombres de todos, así que no es tan extraño que ahora haya olvidado el mío.",
  ui_story_1013_10131402_119_dialog_content = "Eso es lo justo.",
  ui_story_1013_10131402_120_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_121_dialog_content = "Es hora de un cuento antes de dormir, Cutie.",
  ui_story_1013_10131402_122_dialog_content = "Está bien...",
  ui_story_1013_10131402_123_dialog_content = "La historia terminó el día de la partida de 35. Cutie continuará desde allí.",
  ui_story_1013_10131402_124_dialog_content = "35 recibió las credenciales de Navigator justo antes de partir, y era la primera vez que 35 pilotaba un Colossus.",
  ui_story_1013_10131402_125_dialog_content = "35 pasó toda una noche pensando en todos los posibles escenarios de emergencia y cómo responder.",
  ui_story_1013_10131402_126_dialog_content = "El equipaje de 35 estaba lleno de ropa. Costarían cada centavo de la asignación de 35.",
  ui_story_1013_10131402_127_dialog_content = "El mejor atuendo estaba destinado a la vuelta a casa, ya que el 35 quería volver como un héroe.",
  ui_story_1013_10131402_128_dialog_content = "Oh, ¿había tal atuendo?",
  ui_story_1013_10131402_129_dialog_content = "Eso es genial, linda. Descubro cosas nuevas cada vez que escucho tus historias.",
  ui_story_1013_10131402_130_dialog_content = "Eso es todo por el día. Quiero ir a buscar ese conjunto.",
  ui_story_1013_10131402_131_dialog_content = "Un héroe... debe haber sido alguna ropa elegante.",
  ui_story_1013_10131402_132_dialog_content = "¡Los Colosos desarrollaron personalidades!",
  ui_story_1013_10131402_133_dialog_content = "Hay muchas más grabaciones como esta de Caelestite hablando con los Colosos.",
  ui_story_1013_10131402_134_dialog_content = "Si no es un incidente aislado, no puede descartarse como una coincidencia o un milagro.",
  ui_story_1013_10131402_135_dialog_content = "Según el análisis actual, Colossus generó inteligencia en su tiempo con Caelestite.",
  ui_story_1013_10131402_136_dialog_content = "¿Autogenerado?",
  ui_story_1013_10131402_137_dialog_content = "Todos los colosos tienen cierta capacidad de aprendizaje.",
  ui_story_1013_10131402_138_dialog_content = "El propósito de eso es optimizar las decisiones para una mejor ejecución de los comandos.",
  ui_story_1013_10131402_139_dialog_content = "Eso es idéntico a Guardian One.",
  ui_story_1013_10131402_140_dialog_content = "Sí, recuerdo que dijiste que optimizas todas tus acciones.",
  ui_story_1013_10131402_141_dialog_content = "Tal capacidad básica de aprendizaje no es equivalente a la inteligencia.",
  ui_story_1013_10131402_142_dialog_content = "Sin embargo, a juzgar por el resultado, Caelestite guió el proceso de aprendizaje hasta que se convirtió en inteligencia.",
  ui_story_1013_10131402_143_dialog_content = "¿Guiado? ¿Cómo se hizo eso?",
  ui_story_1013_10131402_144_dialog_content = "Lo viste. Todas las conversaciones grabadas. Ese fue el proceso.",
  ui_story_1013_10131402_145_dialog_content = "¿Te refieres a conversar con el Coloso?",
  ui_story_1013_10131402_146_dialog_content = "Sí. El Caelestite continuó conversando con los Colosos que eran innatamente incapaces de conversar.",
  ui_story_1013_10131402_147_dialog_content = "En el proceso, los Colosos comenzaron a aprender esos comportamientos.",
  ui_story_1013_10131402_148_dialog_content = "Es un proceso muy lento. Los cálculos de Guardian One indican que el éxito es imposible.",
  ui_story_1013_10131402_149_dialog_content = "Pero el hecho es que propició el nacimiento de una inteligencia inesperada.",
  ui_story_1013_10131402_150_dialog_content = "Probablemente sea porque Caelestite perseveró.",
  ui_story_1013_10131402_151_dialog_content = "¿Alguien más invertiría todos sus esfuerzos en hablar con una máquina?",
  ui_story_1013_10131402_152_dialog_content = "Lo siento, finalmente me referí a Colossus como la máquina.",
  ui_story_1013_10131402_153_dialog_content = "Aunque eso parece razonable hasta que desarrollan una personalidad.",
  ui_story_1013_10131402_154_dialog_content = "No todos hablarían con una máquina todos los días, y mucho menos durante años.",
  ui_story_1013_10131402_155_dialog_content = "Pero aunque eso suene ridículo y absurdo, eso es lo que Caelestite hizo toda su vida.",
  ui_story_1013_10131402_156_dialog_content = "Tiene un punto. El Caelestita mantuvo muchas más conversaciones con el Coloso a través de órdenes que las expectativas del Guardián Uno.",
  ui_story_1013_10131402_157_dialog_content = "Incluso dada la lentitud del aprendizaje, una cantidad suficiente de información eventualmente daría como resultado un resultado favorable.",
  ui_story_1013_10131402_158_dialog_content = "No fue un milagro, sino una inevitabilidad.",
  ui_story_1013_10131402_159_dialog_content = "No, fue un milagro... la Caelestite fue el milagro.",
  ui_story_1013_10131402_160_dialog_content = "Transformó lo imposible en inevitable.",
  ui_story_1013_10131402_161_dialog_content = "<color=#e8d9bb>¡Bip!</color>",
  ui_story_1013_10131402_162_dialog_content = "¿Qué es eso?",
  ui_story_1013_10131402_163_dialog_content = "El terminal recibió un nuevo mensaje.",
  ui_story_1013_10131402_164_dialog_content = "¿Ahora? ¡Este es el primer mensaje instantáneo que veo en los recuerdos!",
  ui_story_1013_10131402_165_dialog_content = "Vamos a ver...",
  ui_story_1013_10131402_166_dialog_content = "Todos, miren hacia aquí.",
  ui_story_1013_10131402_167_dialog_content = "Esto es probablemente de la nada, pero...",
  ui_story_1013_10131402_168_dialog_content = "No importa, intentaré hacerlo breve.",
  ui_story_1013_10131402_169_dialog_content = "Tengo un favor que pedirles a todos ustedes.",
  ui_story_1013_10131402_170_dialog_content = "¿Puedes escribirme un poema?",
  ui_story_1013_10131402_171_dialog_content = "Quiero uno sobre \"personas\".",
  ui_story_1013_10131402_172_dialog_content = "¡¿Un poema?! no me digas...",
  ui_story_1013_10131402_173_dialog_content = "Lo siento, pero Cutie no ha aprendido a crear poesía.",
  ui_story_1013_10131402_174_dialog_content = "Datos insuficientes en el registro de conversación para el aprendizaje.",
  ui_story_1013_10131402_175_dialog_content = "Quizás 35 pueda escribir varios poemas que sirvan como muestras de aprendizaje.",
  ui_story_1013_10131402_176_dialog_content = "Cutie aprenderá lo más rápido posible.",
  ui_story_1013_10131402_177_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_178_dialog_content = "...",
  ui_story_1013_10131402_179_dialog_content = "Eso es todo lo que hay.",
  ui_story_1013_10131402_180_dialog_content = "Si lo se.",
  ui_story_1013_10131402_181_dialog_content = "Guardián Uno no entiende. ¿Regalar poesía es una costumbre caelestita?",
  ui_story_1013_10131402_182_dialog_content = "Creo que fue más como una convención.",
  ui_story_1013_10131402_183_dialog_content = "Si se hubiera transmitido, tal vez se hubiera convertido en una costumbre.",
  ui_story_1013_10131402_184_dialog_content = "Pero nunca tendría esa oportunidad.",
  ui_story_1013_10131402_185_dialog_content = "Guardian One no entiende lo que quieres decir.",
  ui_story_1013_10131402_186_dialog_content = "¿Puedes adelantar la línea de tiempo, Guardián Uno?",
  ui_story_1013_10131402_187_dialog_content = "Quiero echar un vistazo más adelante.",
  ui_story_1013_10131402_188_dialog_content = "No hay nada más que ver aquí.",
  ui_story_1013_10131402_189_dialog_content = "Seguramente.",
  ui_story_1013_10131402_190_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_1013_10131402_191_dialog_content = "¿Dónde te gustaría parar?",
  ui_story_1013_10131402_192_dialog_content = "Aún no lo sé. ¿Cuánto más rápido es este movimiento en comparación con lo normal?",
  ui_story_1013_10131402_193_dialog_content = "Mil millones de veces.",
  ui_story_1013_10131402_194_dialog_content = "¿Tanto?",
  ui_story_1013_10131402_195_dialog_content = "Cada segundo transcurrido equivale a treinta años.",
  ui_story_1013_10131402_196_dialog_content = "Eso es alucinante... Solo tengo diecisiete años, así que eso es menos de un segundo.",
  ui_story_1013_10131402_197_dialog_content = "Pero nada parece estar pasando.",
  ui_story_1013_10131402_198_dialog_content = "Sí. El terminal tampoco ha recibido nuevos mensajes.",
  ui_story_1013_10131402_199_dialog_content = "Vamos a matar el tiempo.",
  ui_story_1013_10131402_200_dialog_content = "Quiero ver lo que veía Soroz todos los días afuera.",
  ui_story_1013_10131402_201_dialog_content = "Es muy oscuro.",
  ui_story_1013_10131402_202_dialog_content = "¿Cuánto tiempo ha pasado? Sigo viendo y escuchando las mismas cosas, y me está haciendo perder el juicio.",
  ui_story_1013_10131402_203_dialog_content = "Antes me sentía aburrido, pero ahora solo tengo sueño.",
  ui_story_1013_10131402_204_dialog_content = "Quiero tomar una siesta.",
  ui_story_1013_10131402_205_dialog_content = "Si cada segundo son treinta años, ¿cuánto tiempo habrá pasado cuando me despierte?",
  ui_story_1013_10131402_206_dialog_content = "Esto es difícil... Soy terrible en matemáticas.",
  ui_story_1013_10131402_207_dialog_content = "Incluso si pudiera descifrarlo, pensaría que es falso, de todos modos.",
  ui_story_1013_10131402_208_dialog_content = "A este ritmo, el milagro del Coloso cobrando conciencia sería solo un vistazo pasajero.",
  ui_story_1013_10131402_209_dialog_content = "¿Dónde comienza siquiera la conciencia? Incluso yo no sé con certeza si todavía poseo conciencia en este momento.",
  ui_story_1013_10131402_210_dialog_content = "No puedo decir si estoy despierto o durmiendo.",
  ui_story_1013_10131402_211_dialog_content = "No puedo distinguir nada.",
  ui_story_1013_10131402_212_dialog_content = "Soroz probablemente también esté inactivo.",
  ui_story_1013_10131402_213_dialog_content = "No importa, no estaría mal dormir un rato junto a Soroz...",
  ui_story_1013_10131402_214_dialog_content = "<color=#e8d9bb>¡Bip!</color>",
  ui_story_1013_10131402_215_dialog_content = "!",
  ui_story_1013_10131402_216_dialog_content = "¿Qué fue eso?",
  ui_story_1013_10131402_217_dialog_content = "El terminal recibió un nuevo mensaje.",
  ui_story_1013_10131402_218_dialog_content = "¿Ahora? ¿Cómo es eso posible?",
  ui_story_1013_10131402_219_dialog_content = "¿Cuánto tiempo ha pasado? ¿Varios miles o incluso decenas de miles de años?",
  ui_story_1013_10131402_220_dialog_content = "¿Cómo podría recibir un nuevo mensaje ahora?",
  ui_story_1013_10131402_221_dialog_content = "¡Rápido, muéstrame!",
  ui_story_1013_10131402_222_dialog_content = "Terminal de visualización.",
  ui_story_1013_10131402_223_dialog_content = "Este es diferente de todos los mensajes anteriores.",
  ui_story_1013_10131402_224_dialog_content = "No procedía de ningún navegante.",
  ui_story_1013_10131402_225_dialog_content = "¿Es eso...?",
  ui_story_1013_10131402_226_dialog_content = "Vuelve, Colosos.",
  ui_story_1013_10131402_227_dialog_content = "!",
  ui_story_1013_10131402_228_dialog_content = "¿Soroz está despegando?",
  ui_story_1013_10131402_229_dialog_content = "Sí, está volando en cierta dirección a gran velocidad.",
  ui_story_1013_10131402_230_dialog_content = "Guardian One está haciendo ajustes para que te adaptes a la velocidad.",
  ui_story_1013_10131402_231_dialog_content = "¿Puedes averiguar dónde está nuestro destino?",
  ui_story_1013_10131402_232_dialog_content = "¡Espera, no necesitas hacer eso!",
  ui_story_1013_10131402_233_dialog_content = "¡Ventana! ¡Mira por la ventana!",
  ui_story_1013_10131402_234_dialog_content = "(Cielo, tierra, sol... Hace mucho, mucho tiempo que no los veo).",
  ui_story_1013_10131402_235_dialog_content = "(Si tan solo pudiera alargar este momento un billón de veces más...)",
  ui_story_1013_10131402_236_dialog_content = "(Lástima que nadie pudo soportar el salto a tiempo para disfrutar de la alegría de este regreso tan esperado).",
  ui_story_1013_10131402_237_dialog_content = "(Ah, y los Colosos, probablemente lo sientan).",
  ui_story_1013_10131402_238_dialog_content = "(Como un legado, transmitido de los Caelestitas a sus Colosos. Un milagro heredado.)",
  ui_story_1013_10131402_239_dialog_content = "(Un milagro que permite a las almas no humanas presenciar cosas que sus pasajeros vivos no pueden).",
  ui_story_1013_10131402_240_dialog_content = "(Me pregunto qué época es esta y qué tipo de habitantes viven en este mundo actual).",
  ui_story_1013_10131402_241_dialog_content = "(¿Están mirando hacia el cielo, viendo a los Colosos eclipsar al sol?)",
  ui_story_1013_10131402_242_dialog_content = "(Siendo testigos de gigantes de una época pasada que regresan de los cielos, llevando a los últimos de la especie de sus dueños).",
  ui_story_1013_10131402_243_dialog_content = "(El Último Caelestita se graba a sí mismo una vez más en otra sección de la historia).",
  ui_story_1013_10131402_244_dialog_content = "(Qué momento tan surrealista, donde el pasado, el presente y el futuro parecen chocar).",
  ui_story_1013_10131402_245_dialog_content = "(Una antigua promesa, finalmente cumplida.)",
  ui_story_1013_10131402_246_dialog_content = "Escaneo completo. Ubicación actual: Eraveil.",
  ui_story_1013_10131501_1_dialog_content = "Hmm, supongo que está desconectado.",
  ui_story_1013_10131501_X1_dialog_content = "Yo...",
  ui_story_1013_10131501_X2_dialog_content = "Relax.",
  ui_story_1013_10131501_2_dialog_content = "Yingel, revisa el Caelestite.",
  ui_story_1013_10131501_3_dialog_content = "¡Sí!",
  ui_story_1013_10131501_4_dialog_content = "Informe, guardián uno.",
  ui_story_1013_10131501_5_dialog_content = "Pasaste más tiempo del esperado, así que espero que haya un regreso apropiado.",
  ui_story_1013_10131501_6_dialog_content = "Guardian One ha reunido suficiente información sobre Caelestites.",
  ui_story_1013_10131501_7_dialog_content = "Incluyendo los valores vivos de Caelestite, los procesos de pensamiento y el rango emocional.",
  ui_story_1013_10131501_8_dialog_content = "Así como una cierta porción de la historia antigua de Caelestita.",
  ui_story_1013_10131501_9_dialog_content = "¿Qué porción?",
  ui_story_1013_10131501_10_dialog_content = "De los recuerdos de Soroz, se puede deducir que los caelestitas una vez partieron para refugiarse en sus colosos durante un período desconocido.",
  ui_story_1013_10131501_11_dialog_content = "Luego, regresaron a Astra después de un paso de tiempo muy significativo.",
  ui_story_1013_10131501_12_dialog_content = "La ubicación a la que regresó fue Eraveil.",
  ui_story_1013_10131501_13_dialog_content = "¿Se fueron del Astra en sus Colosos? Ya veo...",
  ui_story_1013_10131501_14_dialog_content = "Debe haber sido por el inicio de la destrucción de la civilización. ¡Debería!",
  ui_story_1013_10131501_15_dialog_content = "Siempre nos quedamos en blanco sobre cómo sobrevivió la cultura Caelestita en estudios previos.",
  ui_story_1013_10131501_16_dialog_content = "¡Quizás los registros sobre la salida llenen el vacío!",
  ui_story_1013_10131501_17_dialog_content = "Sí. Transmita la misma información a Barrett más tarde, Guardián Uno.",
  ui_story_1013_10131501_18_dialog_content = "¿Hay algo más que valga la pena mencionar?",
  ui_story_1013_10131501_19_dialog_content = "Guardián Uno asistido PlayerName en la eliminación de fallas de datos de Soroz.",
  ui_story_1013_10131501_20_dialog_content = "¿Qué?",
  ui_story_1013_10131501_21_dialog_content = "H-Qué útil de tu parte.",
  ui_story_1013_10131501_22_dialog_content = "¿Estás bien, PlayerName?",
  ui_story_1013_10131501_23_dialog_content = "La desconexión puede causar molestias, pero debería desaparecer lo suficientemente pronto, así que no te preocupes.",
  ui_story_1013_10131501_24_dialog_content = "Está bien, no siento nada fuera de lo normal.",
  ui_story_1013_10131501_25_dialog_content = "¿Como le fue? Te fuiste por un buen tiempo. ¿Qué viste?",
  ui_story_1013_10131501_26_dialog_content = "Déjame pensar por un segundo...",
  ui_story_1013_10131501_27_dialog_content = "Pasé por la simulación de colapso, luego visité los recuerdos de Soroz...",
  ui_story_1013_10131501_28_dialog_content = "¡Espera, Soroz! ¡Se eliminaron todas las fallas de Soroz!",
  ui_story_1013_10131501_29_dialog_content = "¡Quiero ver si recuperó su conciencia!",
  ui_story_1013_10131501_30_dialog_content = "¿Se arregló? Esa es una feliz sorpresa.",
  ui_story_1013_10131501_31_dialog_content = "Haré los arreglos de inmediato.",
  ui_story_1013_10131501_32_dialog_content = "<color=#e8d9bb>\"Controles principales: Activo\".</color>",
  ui_story_1013_10131501_33_dialog_content = "<color=#e8d9bb>\"Módulos Biológicos: Activos\".</color>",
  ui_story_1013_10131501_34_dialog_content = "<color=#e8d9bb>\"Soporte vital: activo\".</color>",
  ui_story_1013_10131501_35_dialog_content = "<color=#e8d9bb>\"Motores en marcha...\"</color>",
  ui_story_1013_10131501_36_dialog_content = "<color=#e8d9bb>\"16%... 33%...\"</color>",
  ui_story_1013_10131501_37_dialog_content = "<color=#e8d9bb>\"89%... 97%...\"</color>",
  ui_story_1013_10131501_38_dialog_content = "<color=#e8d9bb>\"100%. Compromiso exitoso\".</color>",
  ui_story_1013_10131501_39_dialog_content = "Soroz, ¿puedes oírme?",
  ui_story_1013_10131501_40_dialog_content = "¡Soroz!",
  ui_story_1013_10131501_41_dialog_content = "...",
  ui_story_1013_10131501_42_dialog_content = "St... Todavía no hay respuesta...",
  ui_story_1013_10131501_43_dialog_content = "Guardián Uno, comprueba de nuevo el estado de Soroz.",
  ui_story_1013_10131501_44_dialog_content = "Confirmado. No hay mal funcionamiento de datos, todas las funciones son normales.",
  ui_story_1013_10131501_45_dialog_content = "Es lo que pensaba.",
  ui_story_1013_10131501_46_dialog_content = "Después de escuchar el informe de Guardian One, Caelestite...",
  ui_story_1013_10131501_47_dialog_content = "Tengo una teoría no confirmada. ¿Te gustaría escucharlo?",
  ui_story_1013_10131501_48_dialog_content = "Seguro.",
  ui_story_1013_10131501_49_dialog_content = "Por lo que dijo Guardian One, los Colosos ganando inteligencia fue inesperado.",
  ui_story_1013_10131501_50_dialog_content = "Por lo tanto, dicha inteligencia no es intrínseca a su sistema de datos.",
  ui_story_1013_10131501_51_dialog_content = "Una explicación simple: aún puede usar Soroz aunque carezca de autoconciencia.",
  ui_story_1013_10131501_52_dialog_content = "Derecha. Es simplemente incapaz de conversar conmigo.",
  ui_story_1013_10131501_53_dialog_content = "Poseer una inteligencia que no es intrínseca al propio sistema es un arma de doble filo.",
  ui_story_1013_10131501_54_dialog_content = "Significa que Colossi no puede ejecutar un autodiagnóstico si ocurren problemas y, por lo tanto, no puede solucionarlo.",
  ui_story_1013_10131501_55_dialog_content = "El mal funcionamiento o la eliminación de la programación que, para empezar, nunca formó parte del sistema, no tiene consecuencias para el sistema en sí.",
  ui_story_1013_10131501_56_dialog_content = "Y ahí es donde estás ahora. Tienes un Coloso funcional y saludable que simplemente carece de conciencia.",
  ui_story_1013_10131501_57_dialog_content = "Incluso se podría decir que un Coloso sin personalidad es en realidad lo que es normal.",
  ui_story_1013_10131501_58_dialog_content = "¿Cómo puede ser esto?",
  ui_story_1013_10131501_59_dialog_content = "Así que no importa lo que haga, ¿no importará?",
  ui_story_1013_10131501_60_dialog_content = "¿La razón por la que no puedo restaurar la conciencia de Soroz es porque el hecho de que tenía una era una anomalía?",
  ui_story_1013_10131501_61_dialog_content = "Esa es la situación que nos ocupa.",
  ui_story_1013_10131501_62_dialog_content = "Pero no es imposible que Soroz recupere su conciencia.",
  ui_story_1013_10131501_63_dialog_content = "¿Hay una manera?",
  ui_story_1013_10131501_64_dialog_content = "La solución más sencilla es repetir lo que hicieron.",
  ui_story_1013_10131501_65_dialog_content = "Viste cómo Soroz desarrolló su conciencia en primer lugar. Solo haz eso.",
  ui_story_1013_10131501_66_dialog_content = "¿Hablar con eso? Pero eso llevará años...",
  ui_story_1013_10131501_67_dialog_content = "Todavía eres joven, por lo que aún puedes llegar al día en que suceda.",
  ui_story_1013_10131501_68_dialog_content = "...",
  ui_story_1013_10131501_69_dialog_content = "Por supuesto, hay una opción más eficiente.",
  ui_story_1013_10131501_70_dialog_content = "Viste en la memoria de Soroz que no fue el único Coloso en tomar conciencia.",
  ui_story_1013_10131501_71_dialog_content = "Si puede conseguir los datos de esos Colosos como referencia...",
  ui_story_1013_10131501_72_dialog_content = "No debería ser muy difícil recuperar al viejo Soroz.",
  ui_story_1013_10131501_73_dialog_content = "¡¿En serio?!",
  ui_story_1013_10131501_74_dialog_content = "Es imposible hacer algo de la nada, pero la imitación es otra historia.",
  ui_story_1013_10131501_75_dialog_content = "No menosprecien a los científicos modernos.",
  ui_story_1013_10131501_76_dialog_content = "¡Eso es genial! ¡Rastrearé a otro coloso con autoconciencia!",
  ui_story_1013_10131501_77_dialog_content = "Sobre eso...",
  ui_story_1013_10131501_78_dialog_content = "¿Qué te parece, Ulises?",
  ui_story_1013_10131501_79_dialog_content = "El hecho de que esperaste hasta ahora para pedir mi opinión hace que sea obvio que quieres seguir adelante con esto.",
  ui_story_1013_10131501_80_dialog_content = "Por supuesto. Estamos hablando de inteligencia accidental. Moriría por tener la oportunidad de estudiarlo.",
  ui_story_1013_10131501_81_dialog_content = "Tal vez nuestra investigación pueda hacer avanzar aún más los circuitos de inteligencia del Guardián Uno.",
  ui_story_1013_10131501_82_dialog_content = "Ya que lo dices de esa manera, todos los estudios que beneficien a Illumina deben ser apoyados.",
  ui_story_1013_10131501_83_dialog_content = "Sobre restaurar la inteligencia de Soroz, Caelestite...",
  ui_story_1013_10131501_84_dialog_content = "Si está dispuesto a cooperar con el esfuerzo de investigación de Illumina, podemos brindarle asistencia efectiva.",
  ui_story_1013_10131501_85_dialog_content = "Hacer tratos es el enfoque principal de nuestra reunión. Eso no cambiará.",
  ui_story_1013_10131501_86_dialog_content = "¿Asistencia? ¿Qué tipo de asistencia?",
  ui_story_1013_10131501_87_dialog_content = "Illumina ha realizado estudios sobre los antiguos Colosos antes.",
  ui_story_1013_10131501_88_dialog_content = "Dichos archivos pueden ayudarlo a restaurar la inteligencia de Soroz.",
  ui_story_1013_10131501_89_dialog_content = "Illumina llevó a cabo ese tipo de estudio?",
  ui_story_1013_10131501_90_dialog_content = "Sin embargo, no tenemos los archivos en este momento.",
  ui_story_1013_10131501_91_dialog_content = "Si acepta el trato, enviaremos representantes para negociar con los científicos que poseen la información.",
  ui_story_1013_10131501_92_dialog_content = "Un intercambio, por los datos de investigación requeridos por Soroz.",
  ui_story_1013_10131501_93_dialog_content = "A cambio, debe cumplir con nuestros arreglos y cooperar en nuestra investigación de Colossi.",
  ui_story_1013_10131501_94_dialog_content = "¿Qué tal? Debería ser una gran oferta para ti.",
  ui_story_1013_10131501_95_dialog_content = "Em...",
  ui_story_1013_10131501_96_dialog_content = "Está bien, acepto los términos.",
  ui_story_1013_10131501_97_dialog_content = "Cooperaré con su investigación mientras no perjudique a Soroz.",
  ui_story_1013_10131501_98_dialog_content = "No le haremos daño a Soroz. Al contrario, lo restauraré como tú quieres que sea.",
  ui_story_1013_10131501_99_dialog_content = "Estamos listos, entonces.",
  ui_story_1013_10131501_100_dialog_content = "Yingel, por favor traiga el archivo del Cajón A-42 Clasificado.",
  ui_story_1013_10131501_101_dialog_content = "Nuestro amigo caelestita lo necesita.",
  ui_story_1013_10131501_102_dialog_content = "¡Sí!",
  ui_story_1013_10131501_103_dialog_content = "(¿A-42? ¡Ese es un nivel de autorización de seguridad muy alto!)",
  ui_story_1013_10131501_104_dialog_content = "Después de recuperarlo, por favor ve a mi laboratorio.",
  ui_story_1013_10131501_105_dialog_content = "Tengo otra tarea para ti.",
  ui_story_1013_10131501_106_dialog_content = "¡Sí!",
  ui_story_1013_10131501_107_dialog_content = "Esta es información que ni siquiera yo conozco, Ulises.",
  ui_story_1013_10131501_108_dialog_content = "¿Qué más están escondiendo ustedes?",
  ui_story_1013_10131501_109_dialog_content = "Yo no lo llamaría esconderse, simplemente nadie trató de encontrarlo.",
  ui_story_1013_10131501_110_dialog_content = "No estarías interesado, de todos modos.",
  ui_story_1013_10131501_111_dialog_content = "Está en las Ruinas de Aurora.",
  ui_story_1013_10131501_112_dialog_content = "!",
  ui_story_1013_10131501_113_dialog_content = "Año calendario matutino ■■■■, el Coloso en guerra contra ■■■■.",
  ui_story_1013_10131501_114_dialog_content = "Año calendario matutino ■■■■, el Colossus sufrió daños irreversibles en la batalla.",
  ui_story_1013_10131501_115_dialog_content = "Año calendario matutino ■■■■, signos del Coloso en Entrañas ■■.",
  ui_story_1013_10131501_116_dialog_content = "Qué montón de zorros astutos. Mucho de esto está censurado.",
  ui_story_1013_10131501_117_dialog_content = "Este es un documento de alto secreto, PlayerName. No lo leamos en el pasillo.",
  ui_story_1013_10131501_118_dialog_content = "¡Lo siento, Gran Mariscal! Me emociono cuando pienso en Soroz.",
  ui_story_1013_10131501_119_dialog_content = "Entiendo. Estás muy cerca de restaurarlo esta vez.",
  ui_story_1013_10131501_120_dialog_content = "¡Sí, así es como me siento yo también!",
  ui_story_1013_10131501_121_dialog_content = "Puede que este no sea el momento adecuado, pero todavía tengo que mencionar algunas cosas.",
  ui_story_1013_10131501_122_dialog_content = "Las Ruinas de Aurora son ajenas a ti, pero deberías reconocer algo más.",
  ui_story_1013_10131501_123_dialog_content = "¿Recuerdas Crepúsculo?",
  ui_story_1013_10131501_124_dialog_content = "Sí, Zhao y Sean viven allí.",
  ui_story_1013_10131501_125_dialog_content = "Twilight es un asentamiento en la región de las Ruinas de Aurora.",
  ui_story_1013_10131501_126_dialog_content = "El lugar es más complicado de lo que piensas.",
  ui_story_1013_10131501_127_dialog_content = "¿Complicado?",
  ui_story_1013_10131501_128_dialog_content = "El alcance del Consejo de Ciencias en esa región solo les permite observar.",
  ui_story_1013_10131501_129_dialog_content = "No son capaces de hacer mucho más que eso.",
  ui_story_1013_10131501_130_dialog_content = "Alguien los obstaculizará, lo que podría obstaculizarlo a usted también.",
  ui_story_1013_10131501_131_dialog_content = "¿Pero no es ese territorio de la Federación Illumina?",
  ui_story_1013_10131501_132_dialog_content = "Lo es, pero ya sabes que también pertenece a Lumopolis.",
  ui_story_1013_10131501_133_dialog_content = "Además, no puedes ver las facciones y alianzas allí con nociones preconcebidas.",
  ui_story_1013_10131501_134_dialog_content = "Todo es completamente diferente allí.",
  ui_story_1013_10131501_135_dialog_content = "La guerra perenne ha quemado durante mucho tiempo la tierra con pólvora.",
  ui_story_1013_10131501_136_dialog_content = "Los caballeros no se inclinan ante Schwartz. Los creyentes adoran un sol diferente.",
  ui_story_1013_10131501_137_dialog_content = "Los soldados tampoco escuchan a algún Gran Mariscal de lejos.",
  ui_story_1013_10131501_138_dialog_content = "Entiendo...",
  ui_story_1013_10131501_139_dialog_content = "Por lo tanto, es posible que el Consejo de Ciencias no pueda darle lo que le prometió.",
  ui_story_1013_10131501_140_dialog_content = "Planean intercambiar recursos médicos y militares por información, lo que parece un intercambio justo sobre el papel.",
  ui_story_1013_10131501_141_dialog_content = "Desafortunadamente, los intercambios justos no funcionan allí.",
  ui_story_1013_10131501_142_dialog_content = "Este trato se prolongará, o incluso se desvanecerá sin un gemido.",
  ui_story_1013_10131501_143_dialog_content = "¡De ninguna manera! ¡No puedo dejar escapar la oportunidad! ¡Es mi única esperanza!",
  ui_story_1013_10131501_144_dialog_content = "Quién sabe qué más podría pasarle a su conciencia durante este período inestable...",
  ui_story_1013_10131501_145_dialog_content = "No puedo esperar. ¡Tengo que ir a las Ruinas de Aurora y negociar yo mismo!",
  ui_story_1013_10131501_146_dialog_content = "Con Soroz, estoy seguro de que llegaré más rápido que las tropas de enlace.",
  ui_story_1013_10131501_147_dialog_content = "¡Incluso si tengo problemas, es mejor resolverlo por mi cuenta que preocuparme por eso aquí!",
  ui_story_1013_10131501_148_dialog_content = "Supuse que dirías eso. Admiro y felicito su conducción.",
  ui_story_1013_10131501_149_dialog_content = "Si desea manejarlo personalmente, debe estar completamente preparado.",
  ui_story_1013_10131501_150_dialog_content = "Preparado para hacer frente a eclipses, batallas armadas e incluso desastres naturales.",
  ui_story_1013_10131501_151_dialog_content = "Haré todo lo que pueda para ayudarte a prepararte en Gannon, pero una vez que te pongas en marcha, estarás solo.",
  ui_story_1013_10131501_152_dialog_content = "No estoy exactamente solo. No olvides que los caelestitas no cargan solos en las batallas.",
  ui_story_1013_10131501_153_dialog_content = "Entonces asegúrese de obtener socios confiables.",
  ui_story_1013_10131501_154_dialog_content = "No te preocupes, aunque nunca he tenido confianza en mí mismo...",
  ui_story_1013_10131501_155_dialog_content = "¡Confío en mis amigos al 100 por ciento!",
  ui_story_1013_10131501_156_dialog_content = "Ese es un eslogan bastante cursi.",
  ui_story_1013_10131501_157_dialog_content = "Oh...",
  ui_story_1013_10131501_158_dialog_content = "Pero habiendo luchado junto a ti, creo que puedo entender tu actitud.",
  ui_story_1013_10131501_159_dialog_content = "No es la victoria lo que importa, sino el miedo al fracaso. No es sobresalir lo que importa, sino la perseverancia silenciosa.",
  ui_story_1013_10131501_160_dialog_content = "Es una actitud que motiva y une a los guerreros.",
  ui_story_1013_10131501_161_dialog_content = "¿Sabes qué es más fuerte que el coraje? La audacia de los vulnerables.",
  ui_story_1014_10140101_1_dialog_content = "<color=#e8d9bb>Federación Illumina, Ciudad Gannon, Centro de Investigación Illumina</color>",
  ui_story_1014_10140101_2_dialog_content = "¡Ya veo! ¡Qué gloriosa misión!",
  ui_story_1014_10140101_3_dialog_content = "¡Un pueblo misterioso, lleno de peligros, bordeando la Zona Oscura! ¡Y emocionantes aventuras!",
  ui_story_1014_10140101_4_dialog_content = "Estoy listo y con muchas ganas de ir, PlayerName!",
  ui_story_1014_10140101_5_dialog_content = "Por supuesto-",
  ui_story_1014_10140101_6_dialog_content = "-¡NO!",
  ui_story_1014_10140101_7_dialog_content = "<size=45>¡¿Qué?!</size>",
  ui_story_1014_10140101_8_dialog_content = "Ignorando por un momento cuán peligrosa podría ser una ciudad fuera de la línea de defensa Illumina...",
  ui_story_1014_10140101_9_dialog_content = "Y lo duro que es el entorno cerca de la Zona Oscura...",
  ui_story_1014_10140101_10_dialog_content = "No puedes alejarte tanto de Illumina en tu condición, Vice.",
  ui_story_1014_10140101_11_dialog_content = "¿Qué tiene eso que ver con nada? Estoy bien ahora, ¿no?",
  ui_story_1014_10140101_12_dialog_content = "¡No significa no!",
  ui_story_1014_10140101_13_dialog_content = "Illumina está empezando a trabajar en la actualización de su equipo médico.",
  ui_story_1014_10140101_14_dialog_content = "De todos modos, debe quedarse y recuperarse en el centro médico hasta que se haya recuperado por completo.",
  ui_story_1014_10140101_15_dialog_content = "<color=#e8d9bb>Buzz Buzz-</color>",
  ui_story_1014_10140101_16_dialog_content = "¿Mmm? Sostenga ese pensamiento, PlayerName.",
  ui_story_1014_10140101_17_dialog_content = "Hola...? ¡Ah—!",
  ui_story_1014_10140101_18_dialog_content = "¡L-Teniente Vice informando, Gran Mariscal!",
  ui_story_1014_10140101_19_dialog_content = "(¿El Gran Mariscal? Probablemente también esté preocupada por Vice... ¿Seguramente?)",
  ui_story_1014_10140101_20_dialog_content = "¿Vaya? ¿Una misión urgente?",
  ui_story_1014_10140101_21_dialog_content = "(¡¿Qué?! ¿Urgente? ¡¿Ahora?!)",
  ui_story_1014_10140101_22_dialog_content = "Comprendido. Déjame tomar algunas notas.",
  ui_story_1014_10140101_23_dialog_content = "<size=33>El Consejo... Crepúsculo... Ruinas de Aurora... Intercambio de información...</size>",
  ui_story_1014_10140101_24_dialog_content = "(¡Eso es básicamente todo lo que acabamos de repasar allí!)",
  ui_story_1014_10140101_25_dialog_content = "Si entiendo.",
  ui_story_1014_10140101_26_dialog_content = "Gracias por creer en mi. Tenga la seguridad de que haré el trabajo.",
  ui_story_1014_10140101_27_dialog_content = "(¿Qué diablos le asignaron hacer esta vez?)",
  ui_story_1014_10140101_28_dialog_content = "¡Comprendido! ¡Completaré la misión con la máxima concentración!",
  ui_story_1014_10140101_29_dialog_content = "Asi que, PlayerName, di lo que quieras, pero yo voy contigo!",
  ui_story_1014_10140101_30_dialog_content = "Es una orden directa de la propia Gran Mariscal.",
  ui_story_1014_10140101_31_dialog_content = "No me compliques las cosas ni avergüences al Gran Mariscal.",
  ui_story_1014_10140101_32_dialog_content = "¡¿Cómo está pasando esto?!",
  ui_story_1014_10140101_33_dialog_content = "El Gran Mariscal sonaba un poco preocupado. Parece estar un poco atrapada en sus deberes.",
  ui_story_1014_10140101_34_dialog_content = "\"Teniente Vice, usted representará el cuartel general de Illumina y apoyará la misión de Caelestite con las fuerzas fronterizas\".",
  ui_story_1014_10140101_35_dialog_content = "Esas fueron sus instrucciones.",
  ui_story_1014_10140101_36_dialog_content = "Aún así-",
  ui_story_1014_10140101_37_dialog_content = "No te preocupes, PlayerName.",
  ui_story_1014_10140101_38_dialog_content = "¿Por qué no me informa de los detalles de esta tarea?",
  ui_story_1014_10140101_39_dialog_content = "... Multa. Entonces déjame empezar desde arriba. En la reunión del consejo anterior...",
  ui_story_1014_10140101_40_dialog_content = "<color=#e8d9bb>Federación Illumina, ciudad de Gannon, salón de conferencias Illumina</color>",
  ui_story_1014_10140101_41_dialog_content = "Si acepta el trato, enviaremos representantes para negociar con los científicos que poseen la información.",
  ui_story_1014_10140101_42_dialog_content = "Un intercambio, por los datos de investigación requeridos por Soroz.",
  ui_story_1014_10140101_43_dialog_content = "No más retrasos. ¡Tengo que ir yo mismo a las Ruinas de Aurora para hacer el intercambio!",
  ui_story_1014_10140101_44_dialog_content = "Con Soroz, estoy seguro de que llegaré más rápido que las tropas de enlace.",
  ui_story_1014_10140101_45_dialog_content = "¿Quieres decir que te comunicarás con los que viven alrededor de las Ruinas Aurora como representante de la sede de Illumina?",
  ui_story_1014_10140101_46_dialog_content = "No creo que tengas ese tipo de autoridad, Caelestite.",
  ui_story_1014_10140101_47_dialog_content = "¿Cuál es el problema? No hagas las cosas políticas, Ulises.",
  ui_story_1014_10140101_48_dialog_content = "Esto es, en última instancia, un comercio entre PlayerName y Crepúsculo. Illumina solo proporciona un medio para este fin.",
  ui_story_1014_10140101_49_dialog_content = "Ya-wn... Estoy deseando que llegue.",
  ui_story_1014_10140101_50_dialog_content = "por algo como el <color=#FFB400>Fragilidad celestial</color>, realmente necesitamos a las personas adecuadas para escoltarlo.",
  ui_story_1014_10140101_51_dialog_content = "¿Fragilidad celestial? Eso es lo que esperas intercambiar, ¿verdad?",
  ui_story_1014_10140101_52_dialog_content = "Sí. El cuartel general ya ha negociado con las fuerzas de Illumina estacionadas en Crepúsculo.",
  ui_story_1014_10140101_53_dialog_content = "Debido a los frecuentes combates en la zona fronteriza, decidieron enviar un cyborg de combate a la zona.",
  ui_story_1014_10140101_54_dialog_content = "Es el último producto de Ulysses.",
  ui_story_1014_10140101_55_dialog_content = "Úselo para interactuar con las fuerzas de Illumina allí, y le ofrecerán datos de investigación relevantes de Colossus a cambio.",
  ui_story_1014_10140101_56_dialog_content = "Pero el cyborg es a la vez muy valioso y frágil, se debe tener sumo cuidado en el tránsito.",
  ui_story_1014_10140101_57_dialog_content = "En lugar de transportarlo en un dirigible, es más seguro que Caelestite lo entregue especialmente.",
  ui_story_1014_10140101_58_dialog_content = "Entonces, la legendaria Fragilidad Celestial...",
  ui_story_1014_10140101_59_dialog_content = "Así es. Está en nuestras manos.",
  ui_story_1014_10140101_60_dialog_content = "¡Me tienes realmente curioso ahora! Me pregunto qué tipo de cyborg es.",
  ui_story_1014_10140101_61_dialog_content = "<color=#e8d9bb><size=30>Sonido metálico...</size></color>",
  ui_story_1014_10140101_62_dialog_content = "PlayerName! C-Ven rápido! ¡Está haciendo una especie de ruido!",
  ui_story_1014_10140101_63_dialog_content = "¿Q-Qué ruido? creo que no escuché nada...",
  ui_story_1014_10140101_64_dialog_content = "... Tal vez estoy un poco nervioso.",
  ui_story_1014_10140101_65_dialog_content = "Qué estabas pensando, PlayerName?",
  ui_story_1014_10140101_66_dialog_content = "Estoy un poco... preocupado.",
  ui_story_1014_10140101_67_dialog_content = "Soroz no está en muy buen estado. Será difícil que complete incluso el trabajo logístico más básico, y si...",
  ui_story_1014_10140101_68_dialog_content = "Si nos encontramos con algún problema, pensaremos en algo.",
  ui_story_1014_10140101_69_dialog_content = "¡Por ahora, debemos dejar de hablar y comenzar a movernos!",
  ui_story_1014_10140101_70_dialog_content = "Sí, probablemente tengas razón...",
  ui_story_1014_10140101_71_dialog_content = "<color=#e8d9bb>Soroz, El Puente</color>",
  ui_story_1014_10140101_72_dialog_content = "(Sistemas de control primario... Comprobar.)",
  ui_story_1014_10140101_73_dialog_content = "(Funcionamiento del motor... Comprobar.)",
  ui_story_1014_10140101_74_dialog_content = "Necesito manejar estas cosas yo mismo ahora...",
  ui_story_1014_10140101_75_dialog_content = "(Debería ir al salón y verificar las cosas dos veces).",
  ui_story_1014_10140101_76_dialog_content = "... ¡¿Eh?!",
  ui_story_1014_10140101_77_dialog_content = "¿Carleen, Beretta? Y... Yingel??",
  ui_story_1014_10140101_78_dialog_content = "¿Qué estáis haciendo aquí?",
  ui_story_1014_10140101_79_dialog_content = "Carleen, ni siquiera he tenido tiempo de informarte...",
  ui_story_1014_10140101_80_dialog_content = "Vice ya lo hizo. Dijo que estaba a punto de partir hacia la noche eterna, PlayerName.",
  ui_story_1014_10140101_81_dialog_content = "Solo ustedes dos ahí afuera, peleando solos. ¿Cómo podríamos no preocuparnos?",
  ui_story_1014_10140101_82_dialog_content = "Jeje, la buena y confiable Carleen.",
  ui_story_1014_10140101_83_dialog_content = "¡Me preocupaba que no llegaras a tiempo!",
  ui_story_1014_10140101_84_dialog_content = "Bueno, resulta que ha pasado mucho tiempo desde que Lumopolis se puso en contacto con las fuerzas fronterizas en Crepúsculo.",
  ui_story_1014_10140101_85_dialog_content = "Así que traje a Beretta, ya que también podríamos realizar una inspección mientras estamos allí.",
  ui_story_1014_10140101_86_dialog_content = "Hola de nuevo, PlayerName.",
  ui_story_1014_10140101_87_dialog_content = "No te ves muy bien. ¿Necesitas que te ponga una pequeña inyección?",
  ui_story_1014_10140101_88_dialog_content = "¡¿Q-Qué?!",
  ui_story_1014_10140101_89_dialog_content = "Es una broma.",
  ui_story_1014_10140101_90_dialog_content = "¿Quién es este Illuminati? ¿Nos conocimos en Eraveil? No pareces familiar.",
  ui_story_1014_10140101_91_dialog_content = "¿Ese Iluminado de pelo blanco no te siguió esta vez?",
  ui_story_1014_10140101_92_dialog_content = "Modales, Beretta.",
  ui_story_1014_10140101_93_dialog_content = "¡Sí, señora! Señora Carleen.",
  ui_story_1014_10140101_94_dialog_content = "Coronel Yingel, de los Servicios de Seguridad Interna de la Federación Illumina.",
  ui_story_1014_10140101_95_dialog_content = "Es un placer conocerlo finalmente, Teniente Antivicio. Hay tantas cosas que quiero preguntar sobre Colossus y Caelestite.",
  ui_story_1014_10140101_96_dialog_content = "¡Ay, eh...! E-Eres demasiado amable. ¡Es un gran honor conocerte!",
  ui_story_1014_10140101_97_dialog_content = "(¡Vice no tiene ni idea de qué hacer!)",
  ui_story_1014_10140101_98_dialog_content = "Si me permite el atrevimiento, ¿puedo preguntarle si el Consejo de Ciencias arregló su presencia aquí?",
  ui_story_1014_10140101_99_dialog_content = "Lo siento, pero estoy aquí en una misión. Sin embargo...",
  ui_story_1014_10140101_100_dialog_content = "Personalmente, estoy feliz de visitar la zona de guerra fronteriza.",
  ui_story_1014_10140101_101_dialog_content = "Le proporcionaré inteligencia creíble específica de acuerdo con el Archivo A-42.",
  ui_story_1014_10140101_102_dialog_content = "Creo que también podría necesitar un tercero para verificar la autenticidad de Heavenly Fragility.",
  ui_story_1014_10140101_103_dialog_content = "Eso es cierto, pero—",
  ui_story_1014_10140101_104_dialog_content = "No te preocupes. El cuartel general está tomando la iniciativa en esto, así que no interferiré indebidamente, tanto si las cosas van bien como si no.",
  ui_story_1014_10140101_105_dialog_content = "(No hay razón para dudar de ella...)",
  ui_story_1014_10140101_106_dialog_content = "Espera... ¿Esto no deja solo a Reinhardt para hablar con el Consejo de Ciencias?",
  ui_story_1014_10140101_107_dialog_content = "¿Seguramente no estás preocupado por el Gran Mariscal?",
  ui_story_1014_10140101_108_dialog_content = "Supongo que tienes razón, no necesito preocuparme por Reinhardt.",
  ui_story_1014_10140101_109_dialog_content = "<color=#e8d9bb>Mientras tanto, Illumina Conference Hall</color>",
  ui_story_1014_10140101_110_dialog_content = "Cazar a Forsakin y Helios no es una misión estratégica, Reinhardt. No creo que haya ninguna necesidad de que lo hagas tú mismo.",
  ui_story_1014_10140101_111_dialog_content = "El Consejo de Ciencias encomendó esa misión a los más adecuados.",
  ui_story_1014_10140101_112_dialog_content = "Nunca es sabio obsesionarse con el pasado. Tienes que centrarte en cosas más importantes.",
  ui_story_1014_10140101_113_dialog_content = "¿Te preocupa que pueda descubrir pruebas de cosas que son desfavorables para Ulises?",
  ui_story_1014_10140101_114_dialog_content = "¿A qué te refieres con eso?",
  ui_story_1014_10140101_115_dialog_content = "Sabes muy bien a lo que me refiero.",
  ui_story_1014_10140101_116_dialog_content = "No puedo esperar el día en que la verdad salga a la luz, Ulises. Te estás quedando sin tiempo para hacerte el tonto.",
  ui_story_1014_10140101_117_dialog_content = "Si insiste en ser así, me temo que el Comité también tendrá que reevaluar su competencia.",
  ui_story_1014_10140101_118_dialog_content = "Muy bien, entonces dime: ¿Qué consideras más importante que el destino de los aurorianos?",
  ui_story_1014_10140101_119_dialog_content = "¿Quieres que te lo diga? El evento militar conjunto de Illumina, futuras estrategias de contraataque, todo es—",
  ui_story_1014_10140101_120_dialog_content = "Que absurdo.",
  ui_story_1014_10140101_121_dialog_content = "Nunca he necesitado que nadie me diga cómo ser Gran Mariscal.",
  ui_story_1014_10140101_122_dialog_content = "Mis decisiones no se dejan influir fácilmente por otros.",
  ui_story_1014_10140101_123_dialog_content = "Me despediré, todos.",
  ui_story_1014_10140101_124_dialog_content = "Todavía es tan obstinada.",
  ui_story_1014_10140101_125_dialog_content = "Claro, pero con sus habilidades, debería poder rastrear fácilmente a esa mujer Eclipse.",
  ui_story_1014_10140101_126_dialog_content = "Guarden sus comentarios para ustedes mismos.",
  ui_story_1014_10140101_127_dialog_content = "Hice un plan de contingencia para esta situación precisa.",
  ui_story_1014_10140201_1_dialog_content = "Sistemas de control primario, um, normal.",
  ui_story_1014_10140201_2_dialog_content = "Así es el sistema de piloto automático.",
  ui_story_1014_10140201_3_dialog_content = "Soroz ha estado volando sin problemas desde hace un tiempo, PlayerName. Puedes relajarte un poco.",
  ui_story_1014_10140201_4_dialog_content = "Supongo que tienes razón, Vice. Gracias.",
  ui_story_1014_10140201_5_dialog_content = "Estoy bien, pero todavía te ves estresado.",
  ui_story_1014_10140201_6_dialog_content = "Pero aun así... no creo que necesites aferrarte a esta cosa de la fragilidad celestial todo el tiempo.",
  ui_story_1014_10140201_7_dialog_content = "No eres una gallina melancólica.",
  ui_story_1014_10140201_8_dialog_content = "Técnicamente hablando, es parte integral de la reparación de Soroz, ¡así que es muy importante!",
  ui_story_1014_10140201_9_dialog_content = "No sé de qué otra manera protegerlo por ahora.",
  ui_story_1014_10140201_10_dialog_content = "Además, no es tan pesado como imaginaba...",
  ui_story_1014_10140201_11_dialog_content = "¿En serio? Eso es extraño. ¿Crees que es algún tipo de arma ligera?",
  ui_story_1014_10140201_12_dialog_content = "Es a la vez ligero y frágil... lo que parece peculiar para un cyborg de combate avanzado.",
  ui_story_1014_10140201_13_dialog_content = "¡D-De todos modos, voy a seguir aferrándome así!",
  ui_story_1014_10140201_14_dialog_content = "Honestamente.",
  ui_story_1014_10140201_15_dialog_content = "(Iré a ver qué está haciendo Carleen en su lugar.)",
  ui_story_1014_10140201_16_dialog_content = "<color=#e8d9bb>Zumbido—Crujido—</color>",
  ui_story_1014_10140201_17_dialog_content = "...",
  ui_story_1014_10140201_18_dialog_content = "¿Todavía no sirve, Beretta?",
  ui_story_1014_10140201_19_dialog_content = "Lo siento, señora Carleen. No estoy muy bien informado sobre este tipo de dispositivos.",
  ui_story_1014_10140201_20_dialog_content = "¿Mmm?",
  ui_story_1014_10140201_21_dialog_content = "Momento perfecto, Vice.",
  ui_story_1014_10140201_22_dialog_content = "¿Que pasa? ¿Algo en lo que pueda ayudar?",
  ui_story_1014_10140201_23_dialog_content = "Estaba pensando en contactar a los Lumo Knights estacionados en la frontera para tener una idea de la situación allí.",
  ui_story_1014_10140201_24_dialog_content = "Han estado allí durante muchos años y deberían poder ayudarnos.",
  ui_story_1014_10140201_25_dialog_content = "Este tipo de cosas generalmente las maneja el Señor de la Ciudad. Es mi culpa por no hacer contacto por adelantado.",
  ui_story_1014_10140201_26_dialog_content = "Bueno, ¡fue una partida bastante de última hora!",
  ui_story_1014_10140201_27_dialog_content = "Pero ahora no necesito preocuparme, ya que tengo una gran guía delante de mí.",
  ui_story_1014_10140201_28_dialog_content = "Por favor, Vice, ayúdame a descubrir qué le pasa a esta cosa.",
  ui_story_1014_10140201_29_dialog_content = "La señal se sigue cortando.",
  ui_story_1014_10140201_30_dialog_content = "¡Déjamelo a mí!",
  ui_story_1014_10140201_31_dialog_content = "A ver... Primero, calibrar la sensibilidad de la antena...",
  ui_story_1014_10140201_32_dialog_content = "Muy bien, ¡pruébalo!",
  ui_story_1014_10140201_33_dialog_content = "<color=#e8d9bb>Zumbido—Crujido—</color>",
  ui_story_1014_10140201_34_dialog_content = "Hmm, ok. Entonces, ¿qué tal... ajustar el módulo de potencia?",
  ui_story_1014_10140201_35_dialog_content = "¡De acuerdo! Debería ser bueno para ir ahora.",
  ui_story_1014_10140201_36_dialog_content = "<color=#e8d9bb>Zumbido—Crujido—</color>",
  ui_story_1014_10140201_37_dialog_content = "¡Ajaja! En ese caso, lo único que queda es—",
  ui_story_1014_10140201_38_dialog_content = "<color=#e8d9bb>¡Estallido! ¡Sonido metálico seco!</color>",
  ui_story_1014_10140201_39_dialog_content = "<color=#e8d9bb>Bip, bip...</color>",
  ui_story_1014_10140201_40_dialog_content = "¡Uf! Pedazo de pastel.",
  ui_story_1014_10140201_41_dialog_content = "Así es como lo arreglas.",
  ui_story_1014_10140201_42_dialog_content = "¿Hay alguien ahí?",
  ui_story_1014_10140201_43_dialog_content = "Este es el <color=#FFB400>Caballeros de Ironthorn</color>. Repito, los Caballeros Ironthorn.",
  ui_story_1014_10140201_44_dialog_content = "Bien, tenemos una señal fuerte. En lo alto de la Noche Blanca, la capitana de la Guardia de los Jardines de Lumopolis, Carleen, envía saludos a los Caballeros de Ironthorn.",
  ui_story_1014_10140201_45_dialog_content = "El Capitán Leo saluda a Lady Carleen...",
  ui_story_1014_10140201_46_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_1014_10140201_47_dialog_content = "(¿Sigue siendo mala la señal...?)",
  ui_story_1014_10140201_48_dialog_content = "Sir Leo, Lumopolis se dirigirá a Twilight para una inspección de rutina.",
  ui_story_1014_10140201_49_dialog_content = "Asistiré en representación de Lumopolis. Espero reunirme con usted entonces.",
  ui_story_1014_10140201_50_dialog_content = "Trabajar en la zona fronteriza es difícil. Espero tener la oportunidad de agradecértelo en persona.",
  ui_story_1014_10140201_51_dialog_content = "Bueno, eso es un poco de una sorpresa! Haré todo lo posible para coordinar la <color=#FFB400>Fortaleza de Lumo</color> patrullas",
  ui_story_1014_10140201_52_dialog_content = "Y no hay necesidad de agradecerme. Solo estoy haciendo mi trabajo.",
  ui_story_1014_10140201_53_dialog_content = "Te veré pronto, entonces.",
  ui_story_1014_10140201_54_dialog_content = "roger Cuando llegues, enviaré a alguien... tu llegas... a...",
  ui_story_1014_10140201_55_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_1014_10140201_56_dialog_content = "<color=#e8d9bb>Bip, bip...</color>",
  ui_story_1014_10140201_57_dialog_content = "Parece que la señal se ha perdido por completo...",
  ui_story_1014_10140201_58_dialog_content = "Olvídalo, al menos logramos transmitir la información.",
  ui_story_1014_10140201_59_dialog_content = "¿Eso está bien, Lady Carleen?",
  ui_story_1014_10140201_60_dialog_content = "Tu posición como Capitán fue restablecida recientemente después de la batalla en Eraveil.",
  ui_story_1014_10140201_61_dialog_content = "Aunque pareces mucho más decidido que antes...",
  ui_story_1014_10140201_62_dialog_content = "Según el señor de la ciudad, técnicamente sigues en libertad condicional.",
  ui_story_1014_10140201_63_dialog_content = "Espero que todo salga bien...",
  ui_story_1014_10140201_64_dialog_content = "Estará bien, Beretta. Entiendo de dónde vienes, pero no hay necesidad de preocuparse indebidamente.",
  ui_story_1014_10140201_65_dialog_content = "Incluso si hay un problema, respondemos apropiadamente y estaremos bien.",
  ui_story_1014_10140201_66_dialog_content = "Sí... ¡Tienes razón, Lady Carleen!",
  ui_story_1014_10140201_67_dialog_content = "Por cierto, ¿quién es este Capitán Leo?",
  ui_story_1014_10140201_68_dialog_content = "Ofreciste tu educada gratitud, pero su respuesta fue bastante grosera.",
  ui_story_1014_10140201_69_dialog_content = "No digas eso, Beretta.",
  ui_story_1014_10140201_70_dialog_content = "Aquellos de nosotros que vivimos seguros dentro de Lumopolis debemos respetar a los combatientes de la zona fronteriza.",
  ui_story_1014_10140201_71_dialog_content = "<color=#e8d9bb>Bip-bip-bip-</color>",
  ui_story_1014_10140201_72_dialog_content = "¿Qué es eso?",
  ui_story_1014_10140201_73_dialog_content = "¿No es la alarma de advertencia de Soroz?",
  ui_story_1014_10140201_74_dialog_content = "Oh, no...",
  ui_story_1014_10140201_75_dialog_content = "tenemos que ir a buscar PlayerName!",
  ui_story_1014_10140201_76_dialog_content = "Huff... Huff...",
  ui_story_1014_10140201_77_option_content = "Activar modo de emergencia",
  ui_story_1014_10140201_78_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1014_10140201_79_option_content = "Estabilizar aeronaves",
  ui_story_1014_10140201_80_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_1014_10140201_81_dialog_content = "¡Cuidado!",
  ui_story_1014_10140201_82_dialog_content = "Si no lo estuviera sosteniendo, Heavenly Fragility estaría siendo golpeado por todos lados.",
  ui_story_1014_10140201_83_dialog_content = "¿Qué está pasando exactamente, PlayerName?",
  ui_story_1014_10140201_84_dialog_content = "La alarma te sobresaltó, ¿verdad? Um, mi mal. Lo activé por accidente.",
  ui_story_1014_10140201_85_dialog_content = "¡No digas algo así tan casualmente como si estuvieras hablando del clima!",
  ui_story_1014_10140201_86_dialog_content = "¿Estás seguro de que todo está bien? Pilotar un Colossus es más difícil de lo que pensé que sería...",
  ui_story_1014_10140201_87_dialog_content = "O-Por supuesto, todo está bien.",
  ui_story_1014_10140201_88_dialog_content = "(¡Soy un Caelestite, al final del día!)",
  ui_story_1014_10140201_89_dialog_content = "No te presiones, podemos aterrizar en algún lugar cercano y descansar un poco.",
  ui_story_1014_10140201_90_dialog_content = "Cuanto más nos acerquemos a la noche eterna, más Darkflow habrá a nuestro alrededor.",
  ui_story_1014_10140201_91_dialog_content = "No puedes sentirte muy bien en este momento, ¿verdad?",
  ui_story_1014_10140201_92_dialog_content = "Se honesto.",
  ui_story_1014_10140201_93_dialog_content = "Qué perspicaz... Pero tienes razón. Me empezó a doler la cabeza antes.",
  ui_story_1014_10140201_94_dialog_content = "No sé mucho sobre pilotar un Colossus, pero considerando la seguridad de Heavenly Fragility...",
  ui_story_1014_10140201_95_dialog_content = "Mi consejo sería aterrizar y descansar un rato.",
  ui_story_1014_10140201_96_dialog_content = "No creo que ninguno de nosotros quiera ver que le pase algo a Heavenly Fragility porque hayas cometido un error.",
  ui_story_1014_10140201_97_dialog_content = "No claro que no.",
  ui_story_1014_10140201_98_dialog_content = "Bien. De hecho, estaba tratando de convencerme de que estaba bien.",
  ui_story_1014_10140201_99_dialog_content = "Todos, prepárense para aterrizar. Yo iniciaré el descenso de Soroz.",
  ui_story_1014_10140201_100_dialog_content = "Uf-",
  ui_story_1014_10140201_101_dialog_content = "Es agradable salir y estirar las piernas un poco.",
  ui_story_1014_10140201_102_dialog_content = "De todos modos, ¿sabemos qué pasó con Soroz?",
  ui_story_1014_10140201_103_dialog_content = "Es difícil imaginar que necesitas aterrizarlo manualmente.",
  ui_story_1014_10140201_104_dialog_content = "Parece más serio que la última vez.",
  ui_story_1014_10140201_105_dialog_content = "Hay un problema con su conciencia. No afecta sus funciones normales, pero en este momento, no recibo ninguna otra respuesta.",
  ui_story_1014_10140201_106_dialog_content = "... Iré a revisar los instrumentos una vez más.",
  ui_story_1014_10140201_107_dialog_content = "Iré contigo.",
  ui_story_1014_10140201_108_dialog_content = "<color=#e8d9bb>Whoosh... Whoosh...</color>",
  ui_story_1014_10140201_109_dialog_content = "(Es realmente desolado por ahí.)",
  ui_story_1014_10140201_110_dialog_content = "El Lumina aquí es mucho más delgado que en la sede de Illumina. ¿Te sientes bien?",
  ui_story_1014_10140201_111_dialog_content = "Esto no es nada.",
  ui_story_1014_10140201_112_dialog_content = "Y además, documentar a fondo el viaje de Caelestite es una de las cosas que me encomendaron.",
  ui_story_1014_10140201_113_dialog_content = "¿Por qué no continúas y averiguas qué está pasando con tu Colossus ahora?",
  ui_story_1014_10140201_114_dialog_content = "F-Bien, estoy en ello.",
  ui_story_1014_10140201_115_dialog_content = "(Se siente como si estuviera siendo monitoreado...)",
  ui_story_1014_10140201_116_dialog_content = "Graah...",
  ui_story_1014_10140201_117_dialog_content = "¿Eh? ¿No es ese el sonido de—",
  ui_story_1014_10140201_118_dialog_content = "<anim type=Shake><size=45>Graaaaah!</size></anim>",
  ui_story_1014_10140201_119_dialog_content = "¿Eclipsitos?",
  ui_story_1014_10140201_120_dialog_content = "¡Supongo que no hay nada extraño en que estén en este tipo de lugar!",
  ui_story_1014_10140201_121_dialog_content = "No podemos dejar que lleguen a Soroz. ¿Puedes pelear?",
  ui_story_1014_10140201_122_dialog_content = "Yo... Si fuera una batalla simulada o algo así...",
  ui_story_1014_10140201_123_dialog_content = "En ese caso, ve a buscar a Vice y Carleen, ¡ahora!",
  ui_story_1014_10140201_124_dialog_content = "Batalla.",
  ui_story_1014_10140201_125_dialog_content = "Comandos de batalla recibidos.",
  ui_story_1014_10140201_126_dialog_content = "¡¿?!",
  ui_story_1014_10140201_127_dialog_content = "(Salió por fin...)",
  ui_story_1014_10140201_128_dialog_content = "¡¿Q-Quién habla?!",
  ui_story_1014_10140201_129_dialog_content = "<color=#e8d9bb>Clam, clang...</color>",
  ui_story_1014_10140201_130_dialog_content = "He recibido tus órdenes de batalla.",
  ui_story_1014_10140201_131_dialog_content = "No molestes a Yingel.",
  ui_story_1014_10140201_132_dialog_content = "Estoy listo para pelear.",
  ui_story_1014_10140201_133_dialog_content = "Tu-Tu eres...",
  ui_story_1014_10140201_134_dialog_content = "Estás <color=#FFB400>Fragilidad celestial</color>? ¡¿Lo que nos dio el Consejo de Ciencias?!",
  ui_story_1014_10140201_135_dialog_content = "¡Graagh!",
  ui_story_1014_10140201_136_dialog_content = "Débil.",
  ui_story_1014_10140202_1_dialog_content = "Torrente rápido—!",
  ui_story_1014_10140202_2_dialog_content = "¡Dispersión, pétalos de hielo!",
  ui_story_1014_10140202_3_dialog_content = "Gracias por la ayuda, Teniente Vice.",
  ui_story_1014_10140202_4_dialog_content = "¿Todo bien, Axelia?",
  ui_story_1014_10140202_5_dialog_content = "Deberías preguntar esas cosas.",
  ui_story_1014_10140202_6_dialog_content = "... Aunque ninguno de ellos está en condiciones de responder.",
  ui_story_1014_10140202_7_dialog_content = "Bueno, realmente ahora! No deberías salir de la cámara de estasis sin autorización. Este no es el destino de su misión.",
  ui_story_1014_10140202_8_dialog_content = "Tendré cuidado de no lastimarme.",
  ui_story_1014_10140202_9_dialog_content = "No quisiera ponerte las cosas difíciles, Yingel.",
  ui_story_1014_10140202_10_dialog_content = "¡Este no es el momento para charlas!",
  ui_story_1014_10140202_11_dialog_content = "¿A alguien le importaría explicarme por qué parece una auroriana?",
  ui_story_1014_10140202_12_dialog_content = "Estrictamente hablando, ella ES una Auroriana.",
  ui_story_1014_10140202_13_dialog_content = "Pero aparte de eso, se la conoce principalmente como Combat Cyborg, el orgullo y la alegría del Consejo Científico.",
  ui_story_1014_10140202_14_dialog_content = "¿Un... cíborg?",
  ui_story_1014_10140202_15_dialog_content = "Estamos acostumbrados a llamarla así.",
  ui_story_1014_10140202_16_dialog_content = "Es una perfeccionista, capaz de llevar a cabo cada orden al pie de la letra.",
  ui_story_1014_10140202_17_dialog_content = "No es tanto que controle a Lumina, sino más bien que Lumina se transformó en ella.",
  ui_story_1014_10140202_18_dialog_content = "Siempre que active Luminatics, usará Lumina para ver, escuchar y operar todo tipo de tecnología para concluir una batalla.",
  ui_story_1014_10140202_19_dialog_content = "¡Eso es increíble! ¡Nunca había visto algo así!",
  ui_story_1014_10140202_20_dialog_content = "Lo sé. Ella es verdaderamente el modelo de los usuarios de Luminatics. Sin embargo...",
  ui_story_1014_10140202_21_dialog_content = "Su forma física es excepcionalmente frágil.",
  ui_story_1014_10140202_22_dialog_content = "Se nota por todos los vendajes que sus órganos están en un estado de falla constante.",
  ui_story_1014_10140202_23_dialog_content = "¿Falla de organo? ¿Pero por qué? ¿Y por qué la tecnología médica de Illumina no puede curarlo?",
  ui_story_1014_10140202_24_dialog_content = "Tal vez sea genético. ¿Quién sabe?",
  ui_story_1014_10140202_25_dialog_content = "De todos modos, es justo lo que ella es: un cañón de cristal.",
  ui_story_1014_10140202_26_dialog_content = "Mantenerla en la sede de Illumina fue un desperdicio. Sus habilidades solo se pueden ver realmente en un lugar drástico como Crepúsculo.",
  ui_story_1014_10140202_27_dialog_content = "Hola, PlayerName. Este saludo está muy atrasado.",
  ui_story_1014_10140202_28_dialog_content = "Tendré que molestarte de nuevo por el resto del viaje, disculpas.",
  ui_story_1014_10140202_29_dialog_content = "A cambio, yo...",
  ui_story_1014_10140202_30_dialog_content = "dejar mi cámara de estasis y luchar en tiempos de necesidad.",
  ui_story_1014_10140202_31_dialog_content = "¡E-Eso no será necesario!",
  ui_story_1014_10140202_32_dialog_content = "(¡Estamos acabados si te lesionas!)",
  ui_story_1014_10140202_33_dialog_content = "Nosotros mismos podemos manejar fácilmente los eclipses normales. ¡Para ti involucrarte es como usar un mazo para romper una nuez!",
  ui_story_1014_10140202_34_dialog_content = "Sí. Solo descansa, no te llamaremos a menos que sea absolutamente necesario.",
  ui_story_1014_10140202_35_dialog_content = "Ahora que lo mencionas, siento un poco de sueño.",
  ui_story_1014_10140202_36_dialog_content = "(Aww... ¡Ella es solo una niña linda!)",
  ui_story_1014_10140202_37_dialog_content = "Parece tener la misma edad que nosotros, pero le da sueño tan fácilmente.",
  ui_story_1014_10140202_38_dialog_content = "Ella siempre ha sido así...",
  ui_story_1014_10140202_39_dialog_content = "Para ella, cada batalla es un gasto masivo de energía. Probablemente sea mejor para ella descansar y recuperarse.",
  ui_story_1014_10140202_40_dialog_content = "Buenas noches a todos.",
  ui_story_1014_10140202_41_dialog_content = "¿Deberíamos llevarla al salón?",
  ui_story_1014_10140202_42_dialog_content = "Beretta, ¿cómo te va por tu lado?",
  ui_story_1014_10140202_43_dialog_content = "¡Voy, señora Carleen!",
  ui_story_1014_10140202_44_dialog_content = "Acabo de realizar un examen superficial del Coloso.",
  ui_story_1014_10140202_45_dialog_content = "A pesar de ser el asistente de Raphael, cuando se trata de las enfermedades de una máquina tan antigua, todavía sigo…",
  ui_story_1014_10140202_46_dialog_content = "¡Gracias por tus esfuerzos, Beretta!",
  ui_story_1014_10140202_47_dialog_content = "De todos modos, no hay forma de que Soroz pueda volar en este momento.",
  ui_story_1014_10140202_48_dialog_content = "Vamos a llamarlo un día entonces, tómese un tiempo para descansar.",
  ui_story_1014_10140202_49_dialog_content = "¿Descansar... en este tipo de lugar?",
  ui_story_1014_10140202_50_dialog_content = "Apenas podemos ver el sol desde aquí. Ni siquiera podemos decir qué hora es...",
  ui_story_1014_10140202_51_dialog_content = "Eh, no importa. Tal vez este sea el tipo de cosas que haces en peregrinación a una tierra sagrada.",
  ui_story_1014_10140202_52_dialog_content = "tierra sagrada? No creo que puedas llamar sagrado a ese tipo de lugar.",
  ui_story_1014_10140202_53_dialog_content = "Es una fortaleza donde se libró una antigua batalla entre Aurorianos y Eclipsitas.",
  ui_story_1014_10140202_54_dialog_content = "Los aurorianos se mantuvieron firmes y finalmente expulsaron a los eclipsitas hacia la noche eterna.",
  ui_story_1014_10140202_55_dialog_content = "¿Cantar sobre las tumbas de los muertos es una tradición de Lumopolis?",
  ui_story_1014_10140202_56_dialog_content = "¡No! ¡Por supuesto que no!",
  ui_story_1014_10140202_57_dialog_content = "Las leyendas afirman que las Ruinas de Aurora son la fuente de las auroras del mundo.",
  ui_story_1014_10140202_58_dialog_content = "También es el lugar más lejano todavía habitable para los aurorianos, el lugar donde podemos rastrear nuestras raíces.",
  ui_story_1014_10140202_59_dialog_content = "Eso no contradice lo que acabo de decir.",
  ui_story_1014_10140202_60_dialog_content = "¡Así que no lo hagas pasar por un cementerio!",
  ui_story_1014_10140202_61_dialog_content = "(Qué dolor de cabeza... No sé si es por el Darkflow concentrado, o por estos dos y sus disputas).",
  ui_story_1014_10140202_62_dialog_content = "¡Suficiente por favor! ¿Pueden todos mantenerlo bajo...",
  ui_story_1014_10140202_63_dialog_content = "Ven aquí, Beretta.",
  ui_story_1014_10140202_64_dialog_content = "Cálmese, Comandante Yingel.",
  ui_story_1014_10140202_65_dialog_content = "Se está poniendo más oscuro. Volvamos al Coloso.",
  ui_story_1014_10140202_66_dialog_content = "...",
  ui_story_1014_10140202_67_dialog_content = "Humph.",
  ui_story_1014_10140301_1_dialog_content = "<color=#e8d9bb>Soroz, El Puente</color>",
  ui_story_1014_10140301_2_dialog_content = "<anim type=Shake>Bostezo-</anim>",
  ui_story_1014_10140301_3_dialog_content = "(Todavía tan cansada... Realmente no dormí bien.)",
  ui_story_1014_10140301_4_dialog_content = "Mañana, PlayerName.",
  ui_story_1014_10140301_5_dialog_content = "¡Guau! Uh... te ves un poco pálido.",
  ui_story_1014_10140301_6_dialog_content = "¿Problemas para dormir?",
  ui_story_1014_10140301_7_dialog_content = "Más o menos. El Darkflow aquí es más fuerte que cuando llegamos por primera vez.",
  ui_story_1014_10140301_8_dialog_content = "Me desperté cada vez que un Eclipsite pasó por Soroz anoche.",
  ui_story_1014_10140301_9_dialog_content = "No puedo evitar sentir que estamos siendo perseguidos...",
  ui_story_1014_10140301_10_dialog_content = "Suena como una noche difícil... Deberías dormir un poco más ahora.",
  ui_story_1014_10140301_11_dialog_content = "Mmmmmm. Buena idea.",
  ui_story_1014_10140301_12_dialog_content = "Supongo que volveré a la cama entonces...",
  ui_story_1014_10140301_13_dialog_content = "<color=#e8d9bb>¡Bang! ¡Bang!</color>",
  ui_story_1014_10140301_14_dialog_content = "<color=#e8d9bb>Ruido sordo-!</color>",
  ui_story_1014_10140301_15_dialog_content = "Oh, por el amor de—",
  ui_story_1014_10140301_16_dialog_content = "¡¡¡¿Qué está pasando ahí fuera?!!!",
  ui_story_1014_10140301_17_dialog_content = "Iré a comprobarlo con Beretta.",
  ui_story_1014_10140301_18_dialog_content = "¡Quiero ver por mí mismo!",
  ui_story_1014_10140301_19_dialog_content = "(¡Estos eclipses realmente han ido demasiado lejos!)",
  ui_story_1014_10140301_20_dialog_content = "Estoy empezando a perder la paciencia en serio.",
  ui_story_1014_10140301_21_dialog_content = "... ¿Eh? Sean?",
  ui_story_1014_10140301_22_dialog_content = "¡¿Eh?! PlayerName?!",
  ui_story_1014_10140301_23_dialog_content = "¡Qué sorpresa encontrarte en un lugar como este!",
  ui_story_1014_10140301_24_dialog_content = "Así que esta gran cosa blanca es, como, *tu* Coloso, ¿eh?",
  ui_story_1014_10140301_25_dialog_content = "... ¿De quién más sería?",
  ui_story_1014_10140301_26_dialog_content = "Justo... De todos modos PlayerName, Lo siento por los problemas que he causado a todos.",
  ui_story_1014_10140301_27_dialog_content = "Iré a echar un vistazo en un minuto. Espero que mi \"toque a la puerta\" no haya dañado a Soroz...",
  ui_story_1014_10140301_28_dialog_content = "(Suspiro...)",
  ui_story_1014_10140301_29_dialog_content = "Solo estaba patrullando las afueras de Twilight.",
  ui_story_1014_10140301_30_dialog_content = "Aquí tenemos a Lumina muy débil, por lo que a menudo aparecen refugiados perdidos.",
  ui_story_1014_10140301_31_dialog_content = "Mi tarea principal es localizar a las personas atrapadas por desastres repentinos y limpiar los Eclipsites mientras estoy en eso.",
  ui_story_1014_10140301_32_dialog_content = "¡En el momento en que vi a este enorme tipo blanco, inmediatamente pensé en ti!",
  ui_story_1014_10140301_33_dialog_content = "Probablemente sea muy conveniente viajar muy lejos con un Colossus, ¿verdad?",
  ui_story_1014_10140301_34_dialog_content = "¡Con seguridad! No importa a dónde vaya, mi Colossus puede llevarme allí en un abrir y cerrar de ojos.",
  ui_story_1014_10140301_35_dialog_content = "¡Impresionante! Me gustaría tener uno también.",
  ui_story_1014_10140301_36_dialog_content = "Pensé que mis sueños se estaban volviendo realidad.",
  ui_story_1014_10140301_37_dialog_content = "Pero en retrospectiva, encontrar un nuevo Coloso abandonado en este tipo de puesto avanzado remoto es un poco descabellado...",
  ui_story_1014_10140301_38_dialog_content = "Bueno, sí, es absolutamente descabellado.",
  ui_story_1014_10140301_39_dialog_content = "Permítanme presentarles a todos. Estas son Lady Carleen y Beretta, Guardianas de los Jardines de Lumopolis.",
  ui_story_1014_10140301_40_dialog_content = "Hola.",
  ui_story_1014_10140301_41_dialog_content = "No seas tan precipitado de nuevo, ¿de acuerdo?",
  ui_story_1014_10140301_42_dialog_content = "¡Lo siento mucho!",
  ui_story_1014_10140301_43_dialog_content = "Esta es la Coronel Yingel, y esa caja que lleva es Axelia. Lo que quiero decir con eso es...",
  ui_story_1014_10140301_44_dialog_content = "¡Yingel! ¡Ha sido un tiempo! ¿Quién hubiera pensado que nos encontraríamos de nuevo en este tipo de lugar?",
  ui_story_1014_10140301_45_dialog_content = "¿Y cómo está Axelia? ¿Todavía te va bien?",
  ui_story_1014_10140301_46_dialog_content = "¿Se conocen entre sí?",
  ui_story_1014_10140301_47_dialog_content = "Bueno, ahora, qué sorpresa ver que todavía estás vivo y coleando.",
  ui_story_1014_10140301_48_dialog_content = "¡Pff, por supuesto! Luchar es la vida, al menos en Crepúsculo, ¡y mis habilidades han mejorado mucho!",
  ui_story_1014_10140301_49_dialog_content = "Tan optimista como siempre...",
  ui_story_1014_10140301_50_dialog_content = "(De repente, no tengo sueño en absoluto...)",
  ui_story_1014_10140301_51_dialog_content = "Déjame ir a ver cómo le va a Soroz por última vez, entonces creo que estaremos bien para volver a la carretera.",
  ui_story_1014_10140301_52_dialog_content = "¿Golpear la carretera? ¿No me digan que se dirigen a Crepúsculo?",
  ui_story_1014_10140301_53_dialog_content = "Es una larga historia, pero en resumen, la sede de Illumina nos ha ordenado a Twilight para hacer algún tipo de intercambio.",
  ui_story_1014_10140301_54_dialog_content = "En ese caso, ¡déjame ser tu guía! Conozco algunos buenos atajos.",
  ui_story_1014_10140301_55_dialog_content = "Además, tampoco soy malo tratando con Eclipsites. Puedo manejar cualquier cosa que surja en el camino.",
  ui_story_1014_10140301_56_dialog_content = "¡Eso sería muy util!",
  ui_story_1014_10140301_57_dialog_content = "Mmm...",
  ui_story_1014_10140301_58_dialog_content = "¿Cómo se ve el Coloso?",
  ui_story_1014_10140301_59_dialog_content = "Bueno, no parece haber ningún problema importante en general. Creo que podemos prepararnos para irnos.",
  ui_story_1014_10140301_60_dialog_content = "¿Q-Qué pasa con la puerta?",
  ui_story_1014_10140301_61_dialog_content = "No te preocupes, Sean, la puerta está bien.",
  ui_story_1014_10140301_62_dialog_content = "Uf... Eso es un alivio. ¡Puedo respirar de nuevo!",
  ui_story_1014_10140301_63_dialog_content = "<color=#e8d9bb>Grrhk...</color>",
  ui_story_1014_10140301_64_dialog_content = "¡¿Qué fue eso?!",
  ui_story_1014_10140301_65_dialog_content = "¡¿De nuevo?!",
  ui_story_1014_10140301_66_dialog_content = "<anim type=Shake><size=45>¡¡¡Gahhh!!!</size></anim>",
  ui_story_1014_10140301_67_dialog_content = "¡Qué amable de tu parte servirte en bandeja de plata!",
  ui_story_1014_10140301_68_dialog_content = "Bueno, si tenemos visitas, ¡puedo empezar a limpiar!",
  ui_story_1014_10140402_1_dialog_content = "¡Eh!",
  ui_story_1014_10140402_2_dialog_content = "Deberias hacer eso.",
  ui_story_1014_10140402_3_dialog_content = "¡Tengo que admitir que te subestimé en el centro médico Illumina!",
  ui_story_1014_10140402_4_dialog_content = "Jeje, ahora finalmente podemos partir.",
  ui_story_1014_10140402_5_dialog_content = "De todos modos, si fue la central la que te envió a hacer el intercambio...",
  ui_story_1014_10140402_6_dialog_content = "Debería contactar a los chicos a cargo aquí antes de tiempo.",
  ui_story_1014_10140402_7_dialog_content = "¡No es mi intención dudar de ti, por cierto!",
  ui_story_1014_10140402_8_dialog_content = "Es solo que Twilight es bastante cautelosa con los forasteros.",
  ui_story_1014_10140402_9_dialog_content = "Si les aviso con anticipación, será más sencillo entrar y todo lo demás.",
  ui_story_1014_10140402_10_dialog_content = "Ah, ya veo. Gracias, en ese caso.",
  ui_story_1014_10140402_11_dialog_content = "<color=#e8d9bb>En otro lugar, en el puente</color>",
  ui_story_1014_10140402_12_dialog_content = "(Hm... Realmente parece más fuerte que antes.)",
  ui_story_1014_10140402_13_dialog_content = "¿Observando a Sean, Yingel?",
  ui_story_1014_10140402_14_dialog_content = "¿Axelia? ¡N-No deberías aparecer detrás de alguien! Es realmente desconcertante...",
  ui_story_1014_10140402_15_dialog_content = "¡Oh lo siento!",
  ui_story_1014_10140402_16_dialog_content = "Es bueno moverse un poco después de descansar.",
  ui_story_1014_10140402_17_dialog_content = "Me da un poco de nostalgia recordarnos a los tres en el pasado, entrenando juntos en el <color=#FFB400>Programa Fósforo</color>.",
  ui_story_1014_10140402_18_dialog_content = "Solo han pasado cinco años, pero ya he olvidado casi todo lo que sucedió entonces.",
  ui_story_1014_10140402_19_dialog_content = "Porque tu mente siempre estaba llena de todo tipo de órdenes.",
  ui_story_1014_10140402_20_dialog_content = "Eres uno para hablar, Yingel...",
  ui_story_1014_10140402_21_dialog_content = "Pero tal vez esta es una de mis ventajas.",
  ui_story_1014_10140402_22_dialog_content = "Todos nosotros, incluido Sean, estamos en los roles en los que mejor nos destacamos.",
  ui_story_1014_10140402_23_dialog_content = "Hmph, ¿incluso ese rechazo?",
  ui_story_1014_10140402_24_dialog_content = "... Aunque no puedo negar que parece amarlo.",
  ui_story_1014_10140402_25_dialog_content = "¡Perdón por hacer esperar a todos! ¡Finalmente estamos listos para volver a la normalidad!",
  ui_story_1014_10140402_26_dialog_content = "¡Las fuerzas de Illumina en Crepúsculo están esperando para darles la bienvenida a todos!",
  ui_story_1014_10140402_27_dialog_content = "¡¿?!",
  ui_story_1014_10140402_28_dialog_content = "¿Axelia? ¡Estas despierto!",
  ui_story_1014_10140402_29_dialog_content = "Er, ¿estabais viendo cómo me ocupaba de esos eclipses?",
  ui_story_1014_10140402_30_dialog_content = "Así es.",
  ui_story_1014_10140402_31_dialog_content = "¿Qué piensas? ¿No soy totalmente más impresionante? ¿Sin mencionar que es mucho más fuerte que cuando estábamos en la sede?",
  ui_story_1014_10140402_32_dialog_content = "¿Quieres entrenar una ronda? ¡A ver quién gana esta vez!",
  ui_story_1014_10140402_33_dialog_content = "No, gracias.",
  ui_story_1014_10140402_34_dialog_content = "Por cierto, ¿parece que tienes cuatro robots desconocidos a tu lado?",
  ui_story_1014_10140402_35_dialog_content = "Son el Trío Cúbico.",
  ui_story_1014_10140402_36_dialog_content = "Er, está bien, pero hay cuatro...",
  ui_story_1014_10140402_37_dialog_content = "El cuarto pequeño solo me ayuda a levantarme las mangas.",
  ui_story_1014_10140402_38_dialog_content = "¡Muy raro! ¡¿Pero por qué no?!",
  ui_story_1014_10140402_39_dialog_content = "De todos modos Sean, Axelia es lo que vamos a ofrecer a cambio durante el intercambio.",
  ui_story_1014_10140402_40_dialog_content = "No la hagas usar demasiada energía en este momento.",
  ui_story_1014_10140402_41_dialog_content = "¡¿En serio?!",
  ui_story_1014_10140402_42_dialog_content = "¡¿Eso me hace mayor que Axelia?!",
  ui_story_1014_10140402_43_dialog_content = "¿Tienes algo que quieras preguntarme?",
  ui_story_1014_10140402_44_dialog_content = "Bueno, me preguntaba sobre la estructura militar actual de Twilight.",
  ui_story_1014_10140402_45_dialog_content = "Um, bueno, soy más un soldado de a pie, así que...",
  ui_story_1014_10140402_46_dialog_content = "En ese caso, ¿hay algún tipo especial de Eclipses alrededor de Crepúsculo?",
  ui_story_1014_10140402_47_dialog_content = "Er, en realidad no estoy muy seguro...",
  ui_story_1014_10140402_48_dialog_content = "Sin embargo, no dude en preguntarme cualquier otra cosa! Como dónde está la mejor comida en Crepúsculo, o su historia, o los mejores lugares panorámicos...",
  ui_story_1014_10140402_49_dialog_content = "Bájalo, ¿podrías...?",
  ui_story_1014_10140501_1_dialog_content = "<color=#e8d9bb>Afueras Crepusculares</color>",
  ui_story_1014_10140501_2_dialog_content = "Lady Carleen, los informes de patrulla anteriores indican que Crepúsculo se aproxima.",
  ui_story_1014_10140501_3_dialog_content = "Leo y los demás pronto deberían estar allí para darnos la bienvenida también. Prepárate para aterrizar, PlayerName.",
  ui_story_1014_10140501_4_dialog_content = "<color=#e8d9bb>Auge-</color>",
  ui_story_1014_10140501_5_dialog_content = "¡¿Qué fue eso?!",
  ui_story_1014_10140501_6_dialog_content = "Una explosión.",
  ui_story_1014_10140501_7_dialog_content = "Axelia, vuelve a tu cámara de estasis. Es un caos ahí fuera.",
  ui_story_1014_10140501_8_dialog_content = "Pero este es justo el tipo de tiempo que debería ser necesario.",
  ui_story_1014_10140501_9_dialog_content = "Sean, ¿qué está pasando afuera?",
  ui_story_1014_10140501_10_dialog_content = "Cálmense todos. Todo está bien.",
  ui_story_1014_10140501_11_dialog_content = "Estamos rodeados por algunos molestos eclipses.",
  ui_story_1014_10140501_12_dialog_content = "Pero... ¿por qué todos en el suelo no se mueven?",
  ui_story_1014_10140501_13_dialog_content = "Todos están mirando algo.",
  ui_story_1014_10140501_14_dialog_content = "apuesto a que es PlayerName¡Es Coloso!",
  ui_story_1014_10140501_15_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_1014_10140501_16_dialog_content = "Algo esta mal.",
  ui_story_1014_10140501_17_dialog_content = "¡Rápido! Encuentra un lugar para aterrizar, PlayerName.",
  ui_story_1014_10140501_18_dialog_content = "¡A-Está bien! ¡Siéntense bien, todos!",
  ui_story_1014_10140501_19_dialog_content = "Bueno, hubo algunos contratiempos en el camino, pero lo logramos. ¡Bienvenidos a Crepúsculo!",
  ui_story_1014_10140501_20_dialog_content = "Situada en la frontera de Astra, cuenta con un clima agradable, un estilo de vida sencillo y tradicional.",
  ui_story_1014_10140501_21_dialog_content = "¡Fuera del camino! ¡Muévelo! Vamos, déjame pasar...",
  ui_story_1014_10140501_22_dialog_content = "¡Tos, tos! ¡Qué cantidad de polvo!",
  ui_story_1014_10140501_23_dialog_content = "Jajaja... Sí, eso. Pasa algunas veces.",
  ui_story_1014_10140501_24_dialog_content = "Hola, ¿puedo preguntar a dónde se dirigen? ¿Puedo ayudar en algo?",
  ui_story_1014_10140501_25_dialog_content = "¿Crepúsculo todavía está muy lejos de aquí?",
  ui_story_1014_10140501_26_dialog_content = "¡Estamos en las afueras de la ciudad ahora mismo! Ustedes... no deben ser de por aquí.",
  ui_story_1014_10140501_27_dialog_content = "¡OK gracias!",
  ui_story_1014_10140501_28_dialog_content = "¡Aférrate! Si también te diriges a Crepúsculo, también podrías acompañarnos.",
  ui_story_1014_10140501_29_dialog_content = "Lo sentimos, pero no nos queda mucho tiempo.",
  ui_story_1014_10140501_30_dialog_content = "Le sugiero encarecidamente que encuentre un lugar donde refugiarse, rápidamente.",
  ui_story_1014_10140501_31_dialog_content = "¿Refugio?",
  ui_story_1014_10140501_32_dialog_content = "¿Ves cómo el cielo se ha vuelto de un color raro? Esa es una señal segura de que un <color=#FFB400>tormenta de aurora</color> ¡está viniendo!",
  ui_story_1014_10140501_33_dialog_content = "Si no encuentra refugio pronto, una vez que golpea, nadie puede salvarlo.",
  ui_story_1014_10140501_34_dialog_content = "¿Aurora tormentosa...?",
  ui_story_1014_10140501_35_dialog_content = "Solo he leído sobre esto en libros. Incluso Northland, con sus frecuentes auroras, rara vez ve tal fenómeno.",
  ui_story_1014_10140501_36_dialog_content = "Solo los residentes que han residido en las zonas fronterizas durante generaciones los han presenciado.",
  ui_story_1014_10140501_37_dialog_content = "<color=#e8d9bb>bip—bip—</color>",
  ui_story_1014_10140501_38_dialog_content = "¡Esa es la sirena de advertencia de Twilight!",
  ui_story_1014_10140501_39_dialog_content = "Escuchen, todos. A tu ritmo, no hay forma de que llegues a Crepúsculo hoy.",
  ui_story_1014_10140501_40_dialog_content = "Soy Sean, un oficial subalterno de las fuerzas de Illumina estacionadas en Crepúsculo. Si confías en mí,",
  ui_story_1014_10140501_41_dialog_content = "¡Puedo llevar a todos a refugiarse en una trinchera improvisada!",
  ui_story_1014_10140501_42_dialog_content = "Confía en ti mucho? ¡Sois sólo un montón de niños!",
  ui_story_1014_10140501_43_dialog_content = "Sí, pero no tenemos exactamente ninguna forma de defendernos, ¿verdad? Si nos atacan los eclipses de nuevo...",
  ui_story_1014_10140501_44_dialog_content = "¿Eclipsitos? Quiere decir... que su clan también...",
  ui_story_1014_10140501_45_dialog_content = "... Sí. Si las cosas continúan así, la cantidad de clanes sobrevivientes por aquí seguirá disminuyendo.",
  ui_story_1014_10140501_46_dialog_content = "Dirigirse a Crepúsculo es nuestra mejor oportunidad de supervivencia.",
  ui_story_1014_10140501_47_dialog_content = "Deja de decirle tonterías. Sólo nos quedaremos allí un rato.",
  ui_story_1014_10140501_48_dialog_content = "Llegará el día en que podamos volver a casa...",
  ui_story_1014_10140501_49_dialog_content = "<color=#e8d9bb>golpe, golpe, golpe</color>",
  ui_story_1014_10140501_50_dialog_content = "Los ruidos vienen del suelo esta vez.",
  ui_story_1014_10140501_51_dialog_content = "Graaaaah!",
  ui_story_1014_10140501_52_dialog_content = "<anim type=Shake><size=45>GRAAAAAH!!!</size></anim>",
  ui_story_1014_10140501_53_dialog_content = "Eclipsitos... ¡Se acercan los eclipses!",
  ui_story_1014_10140501_54_dialog_content = "¿Programaron su ataque para que coincidiera con la Aurorastorm? Tienen un poco de habilidad estratégica, al parecer.",
  ui_story_1014_10140501_55_dialog_content = "Beretta.",
  ui_story_1014_10140501_56_dialog_content = "¡Sí, señora Carleen!",
  ui_story_1014_10140501_57_dialog_content = "¡Déjame cubrir el retiro de todos!",
  ui_story_1014_10140501_58_dialog_content = "La evasión no es una estrategia viable a largo plazo.",
  ui_story_1014_10140501_59_dialog_content = "Por favor, déjame pelear. De lo contrario, tendré que tomar medidas extremas.",
  ui_story_1014_10140501_60_dialog_content = "¡No te preocupes por luchar contra ellos todavía!",
  ui_story_1014_10140501_61_dialog_content = "¿Qué pasaría con estos civiles indefensos si cargamos?",
  ui_story_1014_10140501_62_dialog_content = "Creo que puedo protegerlos al mismo tiempo.",
  ui_story_1014_10140501_63_dialog_content = "Por favor, no te preocupes. No tomará mucho tiempo.",
  ui_story_1014_10140501_64_dialog_content = "¡¡Dije que no!!",
  ui_story_1014_10140501_65_dialog_content = "Beretta, Axelia, ustedes dos se separaron.",
  ui_story_1014_10140501_66_dialog_content = "Beretta, Carleen, Sean, vayan a poner a salvo a los civiles.",
  ui_story_1014_10140501_67_dialog_content = "Axelia, Yingel, Vice, iré contigo. ¡Llevaremos la batalla a los Eclipsites!",
  ui_story_1014_10140501_68_dialog_content = "Entiendo.",
  ui_story_1014_10140501_69_dialog_content = "No hay necesidad de cansarse.",
  ui_story_1014_10140501_70_dialog_content = "Deja estos Eclipsites a los Caballeros Ironthorn.",
  ui_story_1014_10140501_71_dialog_content = "Perdone nuestra llegada tardía; Me alegro de que todos estén bien.",
  ui_story_1014_10140501_72_dialog_content = "Momento impecable, Leo! ¡Ayúdanos a luchar contra estos eclipses antes de escoltarnos!",
  ui_story_1014_10140501_73_dialog_content = "Naturalmente. Como la batalla es inminente, por favor, perdóneme por no desmontar, Lady Carleen.",
  ui_story_1014_10140501_74_dialog_content = "Un poco. No necesita mostrar lealtad a la etiqueta, simplemente a su nombre.",
  ui_story_1014_10140501_75_dialog_content = "¡Jajaja! ¡Bueno, me convertí en un caballero de Crepúsculo, en lugar de mi nombre!",
  ui_story_1014_10140501_76_dialog_content = "¡Caballeros, armas presentes!",
  ui_story_1014_10140501_77_dialog_content = "¡Solo requiero una cosa de ti en esta lucha!",
  ui_story_1014_10140501_78_dialog_content = "Lucha para exterminar todos los Eclipsites hasta tu último aliento.",
  ui_story_1014_10140501_79_dialog_content = "¡¡¡ATAQUE!!!",
  ui_story_1014_10140602_1_dialog_content = "Mantente en formación. No se disperse.",
  ui_story_1014_10140602_2_dialog_content = "Prioriza al enemigo en el flanco lateral.",
  ui_story_1014_10140602_3_dialog_content = "¡Sí señor!",
  ui_story_1014_10140602_4_dialog_content = "¡Hay más de ellos! ¡Otro gran grupo de Eclipsites está avanzando!",
  ui_story_1014_10140602_5_dialog_content = "Estaremos exhaustos peleando así. ¿Deberíamos retirarnos?",
  ui_story_1014_10140602_6_dialog_content = "Ah, los veo. Mmm, hay bastantes.",
  ui_story_1014_10140602_7_dialog_content = "En ese caso, nosotros...",
  ui_story_1014_10140602_8_dialog_content = "¡Todos los caballeros! ¡Descarga y prepárate para el asalto!",
  ui_story_1014_10140602_9_dialog_content = "¡Sí señor!",
  ui_story_1014_10140602_10_dialog_content = "Err, asalto? ¿Ahora?",
  ui_story_1014_10140602_11_dialog_content = "Seguramente un asalto frontal con tantos Eclipsites no es la mejor idea...",
  ui_story_1014_10140602_12_dialog_content = "Ustedes, los forasteros, pueden esperar aquí, entonces. Espera y observa.",
  ui_story_1014_10140602_13_dialog_content = "¡Todos los caballeros! Formación en cuña, dos escuadrones. Uno conmigo, uno con el diputado.",
  ui_story_1014_10140602_14_dialog_content = "Divídase una vez a través de la línea enemiga.",
  ui_story_1014_10140602_15_dialog_content = "Ahora, mira la pancarta en mi mano.",
  ui_story_1014_10140602_16_dialog_content = "¡Caballeros de Ironthorn, CARGA!",
  ui_story_1014_10140602_17_dialog_content = "<size=50>CARGA!!</size>",
  ui_story_1014_10140602_18_dialog_content = "¡¿Están realmente apresurando a esa horda de Eclipsites?! ¿No es eso un poco... imprudente?",
  ui_story_1014_10140602_19_dialog_content = "No necesariamente. Sólo mira.",
  ui_story_1014_10140602_20_dialog_content = "Su asalto fue más suave de lo esperado.",
  ui_story_1014_10140602_21_dialog_content = "¡De verdad! ¡Incluso tantos Eclipsites no pudieron detener a los caballeros!",
  ui_story_1014_10140602_22_dialog_content = "Los cortaron con precisión quirúrgica...",
  ui_story_1014_10140602_23_dialog_content = "¡¿Cómo hicieron eso?!",
  ui_story_1014_10140602_24_dialog_content = "Creo que algo entiendo. Las palabras de Beretta fueron acertadas.",
  ui_story_1014_10140602_25_dialog_content = "Realmente son como una espada.",
  ui_story_1014_10140602_26_dialog_content = "Al sacrificar un cadáver, nadie piensa dos veces en el peso del cuchillo en comparación con el animal.",
  ui_story_1014_10140602_27_dialog_content = "Siempre que la cuchilla esté lo suficientemente afilada, cortará a la perfección.",
  ui_story_1014_10140602_28_dialog_content = "Romper...",
  ui_story_1014_10140602_29_dialog_content = "Mira, Leo va a volver con la mitad de ellos.",
  ui_story_1014_10140602_30_dialog_content = "<color=#e8d9bb>Clip-clop, clip-clop</color>",
  ui_story_1014_10140602_31_dialog_content = "¿Qué opinan, forasteros? No es tan mala idea después de todo, ¿eh?",
  ui_story_1014_10140602_32_dialog_content = "La guerra no es simplemente un juego de números. La misma fuerza se puede usar de manera diferente con diferentes tácticas.",
  ui_story_1014_10140602_33_dialog_content = "Aquí a lo largo de la frontera remota, no tenemos la fuerza para chocar con los Eclipsites de frente.",
  ui_story_1014_10140602_34_dialog_content = "No entienden la estrategia militar. Sin embargo, lo hacemos, y esta es nuestra ventaja.",
  ui_story_1014_10140602_35_dialog_content = "Entonces, ¿cómo juzgaste que era el momento adecuado para un asalto?",
  ui_story_1014_10140602_36_dialog_content = "Porque conozco bien este tipo de Eclipsite.",
  ui_story_1014_10140602_37_dialog_content = "Son agresivos y buenos para abrumar con números absolutos. Pero su debilidad es obvia: no son competentes contra ataques repentinos.",
  ui_story_1014_10140602_38_dialog_content = "Así que al enfrentarlos, independientemente de qué lado tenga más fuerzas, debemos tomar la iniciativa y atacar.",
  ui_story_1014_10140602_39_dialog_content = "Nuestra carga frontal concentra nuestras fuerzas en una sola línea, que atraviesa y debilita al enemigo.",
  ui_story_1014_10140602_40_dialog_content = "El ataque también rompe la formación de los Eclipsites. Cuanto más disperso esté el enemigo, mejor para nosotros.",
  ui_story_1014_10140602_41_dialog_content = "¿Verás? Dejé la mitad de mis fuerzas entre ellos.",
  ui_story_1014_10140602_42_dialog_content = "Se ocuparán del resto de los Eclipsites, creando más caos y confusión al atravesar el campo de batalla mientras eliminan grupos de rezagados.",
  ui_story_1014_10140602_43_dialog_content = "¡Asombroso! Parece que hay mucho más que considerar de lo que pensaba cuando se trata de luchar contra los Eclipsites.",
  ui_story_1014_10140602_44_dialog_content = "Claramente, los Eclipsites nos superaban ampliamente en número, pero ustedes están igualados en el campo de batalla...",
  ui_story_1014_10140602_45_dialog_content = "Por eso digo que la estrategia es más importante que el poder.",
  ui_story_1014_10140602_46_dialog_content = "Pero tú, forastero, tienes talento para detectar eclipses antes que yo.",
  ui_story_1014_10140602_47_dialog_content = "Ese tipo de sentido del campo de batalla es raro.",
  ui_story_1014_10140602_48_dialog_content = "No es realmente nada del otro mundo.",
  ui_story_1014_10140602_49_dialog_content = "No soy un auroriano como tú. Soy Caelestita.",
  ui_story_1014_10140602_50_dialog_content = "¿Una Caelestita? ¿Esa carrera legendaria?",
  ui_story_1014_10140602_51_dialog_content = "Jajaja, que fascinante! ¡Un personaje de mis libros ha cobrado vida!",
  ui_story_1014_10140602_52_dialog_content = "Entonces, Caelestite, usa tus agudos sentidos y dime: ¿Qué debemos hacer a continuación?",
  ui_story_1014_10140602_53_dialog_content = "Um... ¿Lanzar un ataque de seguimiento, antes de que el enemigo se reagrupa?",
  ui_story_1014_10140602_54_dialog_content = "¡Incorrecto! Nos retiramos.",
  ui_story_1014_10140602_55_dialog_content = "¿Eh? ¿Pero por qué? ¡Acabamos de establecer una ventaja!",
  ui_story_1014_10140602_56_dialog_content = "No puedes mantener tus ojos solo en el campo de batalla frente a ti.",
  ui_story_1014_10140602_57_dialog_content = "Nuestro objetivo final es interceptar todos los eclipses. Lo que estamos haciendo ahora no es suficiente.",
  ui_story_1014_10140602_58_dialog_content = "Detrás de ellos se encuentra un terreno peligroso con pasos traicioneros. La batalla inevitablemente cambiaría allí.",
  ui_story_1014_10140602_59_dialog_content = "Tenemos que prepararnos primero.",
  ui_story_1014_10140602_60_dialog_content = "¿Nos ayudarías, forastero?",
  ui_story_1014_10140602_61_dialog_content = "¡Por supuesto! Esperaba tener la oportunidad de observar tus tácticas nuevamente.",
  ui_story_1014_10140602_62_dialog_content = "Bueno, íbamos a tratar con los Eclipsites de todos modos.",
  ui_story_1014_10140602_63_dialog_content = "Escuche, ayude o no, no hace ninguna diferencia para nosotros. Pero tengo una pregunta...",
  ui_story_1014_10140602_64_dialog_content = "¿Alguien ha visto a ese idiota de Sean en alguna parte?",
  ui_story_1014_10140602_65_dialog_content = "<size=45>Muereeeee!!</size>",
  ui_story_1014_10140602_66_dialog_content = "¿Cuántos de ustedes quedan?",
  ui_story_1014_10140602_67_dialog_content = "Nunca pensé que podrías luchar tan bien, soldado de Illumina.",
  ui_story_1014_10140602_68_dialog_content = "¿Eh? ¡Oh, bueno, gracias!",
  ui_story_1014_10140602_69_dialog_content = "Llamas la atención incluso en el campo de batalla de los Caballeros de Ironthorn.",
  ui_story_1014_10140602_70_dialog_content = "Un luchador tan destacado como usted no debe carecer de elogios.",
  ui_story_1014_10140602_71_dialog_content = "¿E-en serio? No suelo recibir cumplidos.",
  ui_story_1014_10140602_72_dialog_content = "Sin embargo, ¿por qué exactamente estás aquí? ¿Pensé que el capitán te dijo que esperaras allí?",
  ui_story_1014_10140602_73_dialog_content = "¡¿Él hizo?!",
  ui_story_1014_10140602_74_dialog_content = "Mira, todos tus compañeros todavía están allí.",
  ui_story_1014_10140602_75_dialog_content = "Ohhh, ahora lo recuerdo. El Capitán Leo dijo algo acerca de que los forasteros se quedaran donde estaban.",
  ui_story_1014_10140602_76_dialog_content = "¡Pero no soy un extraño! Yo también vivo aquí en Crepúsculo.",
  ui_story_1014_10140602_77_dialog_content = "...",
  ui_story_1014_10140602_78_dialog_content = "¿Alguien te ha dicho alguna vez que no eres la herramienta más afilada del cobertizo?",
  ui_story_1014_10140602_79_dialog_content = "¡Sí!",
  ui_story_1014_10140602_80_dialog_content = "¿Sabes que eso NO es un cumplido...?",
  ui_story_1014_10140602_81_dialog_content = "No importa. Gracias a ti, toda la situación de la batalla es mucho más clara.",
  ui_story_1014_10140602_82_dialog_content = "Nuestra directiva de misión original era tratar con los eclipses. Mirando cómo están las cosas actualmente, no debería ser demasiado difícil eliminarlas por completo.",
  ui_story_1014_10140602_83_dialog_content = "¡Bueno! ¡No puedo dejar que ninguno de ellos se escape!",
  ui_story_1014_10140602_84_dialog_content = "Pareces lleno de pasión. Eso es bueno.",
  ui_story_1014_10140602_85_dialog_content = "Sabes, he estado escuchando historias sobre los Caballeros Ironthorn y el Capitán Leo desde siempre.",
  ui_story_1014_10140602_86_dialog_content = "¡Tener la oportunidad de luchar codo a codo con un grupo tan heroico realmente me hace bombear la sangre!",
  ui_story_1014_10140602_87_dialog_content = "Oculta estas ballestas en la hierba alta. Nuestros preparativos están casi completos.",
  ui_story_1014_10140602_88_dialog_content = "Perfecto, están regresando.",
  ui_story_1014_10140602_89_dialog_content = "<color=#e8d9bb>Clip-clop, clip-clop</color>",
  ui_story_1014_10140602_90_dialog_content = "Capitán.",
  ui_story_1014_10140602_91_dialog_content = "Buen trabajo, y más elegantemente ejecutado de lo que imaginaba.",
  ui_story_1014_10140602_92_dialog_content = "Esta vez, tenemos que agradecer el apoyo de este excelente luchador de Illumina.",
  ui_story_1014_10140602_93_dialog_content = "Oh, vamos, no fue nada...",
  ui_story_1014_10140602_94_dialog_content = "Mmmm, lo vi. Una lucha tan vigorosa no podía pasar desapercibida.",
  ui_story_1014_10140602_95_dialog_content = "¿Eres un oficial de Illumina?",
  ui_story_1014_10140602_96_dialog_content = "¡Sí! ¡Soy el segundo teniente Sean, de Twilight's Garrison!",
  ui_story_1014_10140602_97_dialog_content = "Guarnición del Crepúsculo, eh. No puedo creer que nunca supe que teníamos un guerrero tan valiente justo al lado.",
  ui_story_1014_10140602_98_dialog_content = "No, ¿por qué lo harías? No soy una excepción entre mis camaradas, y en realidad no tengo mucha experiencia en el campo de batalla.",
  ui_story_1014_10140602_99_dialog_content = "Por supuesto, alguien como usted no habría oído hablar de mí, capitán Leo.",
  ui_story_1014_10140602_100_dialog_content = "Parece que sabes de mí.",
  ui_story_1014_10140602_101_dialog_content = "¡¡Naturalmente!! ¡Quién en Crepúsculo no ha oído hablar de las valientes hazañas de los Caballeros Ironthorn!",
  ui_story_1014_10140602_102_dialog_content = "Bueno, en ese caso... muchacho, ¿te gustaría unirte a nosotros?",
  ui_story_1014_10140602_103_dialog_content = "¿Ah?",
  ui_story_1014_10140602_104_dialog_content = "Los combatientes sobresalientes deben mostrar su valía en el campo de batalla, no languidecer en los cuarteles contando los días que pasan.",
  ui_story_1014_10140602_105_dialog_content = "Únete a nosotros y daré a conocer tu nombre en Crepúsculo en menos de un mes.",
  ui_story_1014_10140602_106_dialog_content = "Pero...",
  ui_story_1014_10140602_107_dialog_content = "Ejem. Capitán Leo, una invitación tan escandalosa definitivamente va en contra del protocolo.",
  ui_story_1014_10140602_108_dialog_content = "Como mínimo, trata de convertir a tu enemigo con más discreción.",
  ui_story_1014_10140602_109_dialog_content = "Ahaha, mis disculpas, aunque no puedo ver qué tiene de vergonzoso esto.",
  ui_story_1014_10140602_110_dialog_content = "Lumopolis e Illumina no son más que lugares para descansar, nuestros últimos enemigos son los Eclipsites.",
  ui_story_1014_10140602_111_dialog_content = "Solo quiero que este niño tenga un lugar mejor al que llamar hogar.",
  ui_story_1014_10140602_112_dialog_content = "Por supuesto, los extrañas, también son impresionantes. Si alguna vez tiene la intención de unirse a nosotros, los Caballeros de Ironthorn estarán listos para darle la bienvenida.",
  ui_story_1014_10140602_113_dialog_content = "Tú... No tenía idea de que el Capitán de los Caballeros de Ironthorn fuera un maestro de la solicitación.",
  ui_story_1014_10140602_114_dialog_content = "Deberías renunciar y convertirte en político en la ciudad de Gannon. También me gustaría que tuvieras un mejor lugar al que llamar hogar.",
  ui_story_1014_10140602_115_dialog_content = "¿Político, dices? No es una mala opción. Lo pensaré un poco.",
  ui_story_1014_10140602_116_dialog_content = "Estoy cansado.",
  ui_story_1014_10140602_117_dialog_content = "¿Mmm?",
  ui_story_1014_10140602_118_dialog_content = "Ya—wn, dije que estoy cansada.",
  ui_story_1014_10140602_119_dialog_content = "¿En serio? En este momento...?",
  ui_story_1014_10140602_120_dialog_content = "No importa, no hay nada que hacer al respecto. Vuelve a la cámara de estasis y descansa un poco, Axelia.",
  ui_story_1014_10140602_121_dialog_content = "Por supuesto. Estaré apoyando por ti.",
  ui_story_1014_10140602_122_dialog_content = "Volveré inmediatamente en cuanto me despierte.",
  ui_story_1014_10140602_123_dialog_content = "No te preocupes por eso. Descansa bien.",
  ui_story_1014_10140602_124_dialog_content = "Vigila la cámara de estasis, PlayerName.",
  ui_story_1014_10140602_125_dialog_content = "¡Servirá!",
  ui_story_1014_10140602_126_dialog_content = "¡Simplemente desapareció en esa caja!",
  ui_story_1014_10140602_127_dialog_content = "Ustedes, forasteros, realmente están ampliando mis horizontes.",
  ui_story_1014_10140602_128_dialog_content = "La condición física de Axelia no es muy buena, por lo que tiene que descansar mucho en la cámara de estasis.",
  ui_story_1014_10140602_129_dialog_content = "Entonces, ¿por qué la llevarías a un lugar tan peligroso como la región fronteriza?",
  ui_story_1014_10140602_130_dialog_content = "Porque llevarla a Twilight a salvo era el objetivo de la misión.",
  ui_story_1014_10140602_131_dialog_content = "Ah, ya veo. Bueno, en ese caso, no me entrometeré más.",
  ui_story_1014_10140602_132_dialog_content = "Basta de cháchara, creo que ese grupo de allí se está poniendo inquieto.",
  ui_story_1014_10140602_133_dialog_content = "Necesito instalar una cerca de hierro aquí antes de que aparezcan los Eclipsites.",
  ui_story_1014_10140602_134_dialog_content = "Estamos aquí para ayudar, entonces, ¿qué podemos hacer?",
  ui_story_1014_10140602_135_dialog_content = "Solo participar en la batalla por nosotros es suficiente. No hay necesidad de involucrarla en las minucias de nuestro negocio, Lady Carleen.",
  ui_story_1014_10140602_136_dialog_content = "De hecho, considerando su estatus, probablemente debería cederle el mando del campo de batalla.",
  ui_story_1014_10140602_137_dialog_content = "Es solo que en las circunstancias actuales, temo que a los caballeros les resulte difícil adaptarse. Por favor, perdóname por sobrepasar mi autoridad.",
  ui_story_1014_10140602_138_dialog_content = "...",
  ui_story_1014_10140602_139_dialog_content = "El mando debe pertenecer a quien sea más capaz de llevar a todos a la victoria. No hay necesidad de tanta formalidad aquí.",
  ui_story_1014_10140602_140_dialog_content = "Si tenemos la libertad de hacer lo que nos plazca, nos dirigiremos hacia el este para ayudar a mantener la defensa.",
  ui_story_1014_10140602_141_dialog_content = "Si mis observaciones son correctas, la línea defensiva allí es relativamente débil.",
  ui_story_1014_10140602_142_dialog_content = "Este... Tienes toda la razón. Carecemos de mano de obra suficiente para cubrir todas las áreas, y ese es nuestro punto débil.",
  ui_story_1014_10140602_143_dialog_content = "Parece que tiene buen ojo táctico, Lady Carleen.",
  ui_story_1014_10140602_144_dialog_content = "Si bien mi nacimiento me impide tener el título de Knight Commander, no me confundas con una simple princesa de Lumopolis.",
  ui_story_1014_10140602_145_dialog_content = "¡Nunca! Confío en el nombre de los Caballeros de Lumopolis.",
  ui_story_1014_10140602_146_dialog_content = "Ambos luchamos por la misma gloria.",
  ui_story_1014_10140602_147_dialog_content = "Esto parece un área segura de retaguardia. Creo que deberías instalar la cámara de estasis de Axelia aquí, PlayerName.",
  ui_story_1014_10140602_148_dialog_content = "Está bien.",
  ui_story_1014_10140602_149_dialog_content = "El despliegue de Leo ha dejado la línea oriental relativamente débil.",
  ui_story_1014_10140602_150_dialog_content = "Deberíamos ir a apoyar a las fuerzas defensivas allí.",
  ui_story_1014_10140602_151_dialog_content = "Sí, señora Carleen.",
  ui_story_1014_10140602_152_dialog_content = "Estás cooperando con las órdenes de Leo de buena gana, Carleen.",
  ui_story_1014_10140602_153_dialog_content = "Tiene una gran experiencia de mando. Has visto por ti mismo lo fácil que logra la victoria, si se siguen sus órdenes.",
  ui_story_1014_10140602_154_dialog_content = "Pero no nos designó una tarea específica.",
  ui_story_1014_10140602_155_dialog_content = "No. No lo haría.",
  ui_story_1014_10140602_156_dialog_content = "¿Eh? ¿Por qué no?",
  ui_story_1014_10140602_157_dialog_content = "Siento que Leo está manteniendo una distancia deliberada.",
  ui_story_1014_10140602_158_dialog_content = "No se someterá a mí, pero tampoco me dará órdenes.",
  ui_story_1014_10140602_159_dialog_content = "Porque soy, después de todo, la hija del Señor de la Ciudad de Lumopolis.",
  ui_story_1014_10140602_160_dialog_content = "Bueno, está bien, pero todavía no entiendo realmente. ¿Es eso algo malo?",
  ui_story_1014_10140602_161_dialog_content = "No estoy muy seguro de mí mismo.",
  ui_story_1014_10140602_162_dialog_content = "De hecho, lo preferiría a él que a un simple guerrero, sin nada de la etiqueta o la reverencia.",
  ui_story_1014_10140602_163_dialog_content = "En esta frontera lejana, tan alejada de todo, sólo se ve el campo de batalla.",
  ui_story_1014_10140602_164_dialog_content = "Pero no para él. Por el contrario, es extremadamente consciente de mi estado.",
  ui_story_1014_10140602_165_dialog_content = "Y usa esta distancia entre nosotros para convertir la \"fidelidad\" en \"respeto\".",
  ui_story_1014_10140602_166_dialog_content = "Así que lo respetaré a cambio y seguiré sus órdenes tácticas.",
  ui_story_1014_10140602_167_dialog_content = "Que confuso ¿Es esto lo que llaman guerra de la política?",
  ui_story_1014_10140602_168_dialog_content = "Qué apto.",
  ui_story_1014_10140602_169_dialog_content = "Quizás esta sea la tragedia que define a Lumopolis. Nunca podemos separarnos verdaderamente de la política.",
  ui_story_1014_10140602_170_dialog_content = "<color=#e8d9bb>Retumbar-</color>",
  ui_story_1014_10140602_171_dialog_content = "!",
  ui_story_1014_10140602_172_dialog_content = "¿Qué es ese ruido?",
  ui_story_1014_10140602_173_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1014_10140602_174_dialog_content = "¡Algo se dirige hacia aquí!",
  ui_story_1014_10140602_175_dialog_content = "El Darkflow es grueso. Probablemente hay muchos de ellos.",
  ui_story_1014_10140602_176_dialog_content = "Y... ¡parece que han traído a un gran amigo!",
  ui_story_1014_10140701_1_dialog_content = "¡Caballeros de Ironthorn, prepárense para la batalla!",
  ui_story_1014_10140701_2_dialog_content = "¡Nadie debe dejar la formación sin mi orden!",
  ui_story_1014_10140701_3_dialog_content = "¡Sí señor!",
  ui_story_1014_10140701_4_dialog_content = "<color=#e8d9bb>Retumbar-</color>",
  ui_story_1014_10140701_5_dialog_content = "Hay incluso más de ellos que la última vez.",
  ui_story_1014_10140701_6_dialog_content = "Apuesto a que es el que está haciendo todo el alboroto.",
  ui_story_1014_10140701_7_dialog_content = "<color=#FFB400>cerrito</color>.",
  ui_story_1014_10140701_8_dialog_content = "Cerrito... otra vez...",
  ui_story_1014_10140701_9_dialog_content = "¿Qué?",
  ui_story_1014_10140701_10_dialog_content = "Una aberración. Un eclipse único. Uno con una fuerza extraordinaria.",
  ui_story_1014_10140701_11_dialog_content = "Los Caballeros de Ironthorn se han enfrentado antes, pero ninguno de los bandos pudo asegurar una victoria definitiva.",
  ui_story_1014_10140701_12_dialog_content = "¿Alguna posibilidad de detenerlo esta vez?",
  ui_story_1014_10140701_13_dialog_content = "No es una cuestión de si podemos detenerlo. Debemos.",
  ui_story_1014_10140701_14_dialog_content = "Si nos pasan, llegarán a Twilight.",
  ui_story_1014_10140701_15_dialog_content = "No hay otros Caballeros de Ironthorn para ayudar a detenerlo.",
  ui_story_1014_10140701_16_dialog_content = "¡Esperar! ¡Mira allá! ¡Al frente de los Eclipsites!",
  ui_story_1014_10140701_17_dialog_content = "¡¿Gente?! ¡Los civiles están huyendo!",
  ui_story_1014_10140701_18_dialog_content = "Alguien... Por favor...",
  ui_story_1014_10140701_19_dialog_content = "No puedo... correr mucho más...",
  ui_story_1014_10140701_20_dialog_content = "Sólo un poco más lejos. C-Casi allí... Crepúsculo.",
  ui_story_1014_10140701_21_dialog_content = "Habrá alguien allí para protegernos, sé que lo habrá.",
  ui_story_1014_10140701_22_dialog_content = "¿Podemos hacerlo...?",
  ui_story_1014_10140701_23_dialog_content = "Puedo oírlo... Detrás de mí... los monstruos...",
  ui_story_1014_10140701_24_dialog_content = "Suenan tan cerca... Tan cerca...",
  ui_story_1014_10140701_25_dialog_content = "¡Realmente hay gente! ¡Están a punto de ser atrapados!",
  ui_story_1014_10140701_26_dialog_content = "¡Rápido, al rescate! ¡Ve ahora, antes de que sea demasiado tarde!",
  ui_story_1014_10140701_27_dialog_content = "Pero, ¿qué debemos hacer, Capitán Leo?",
  ui_story_1014_10140701_28_dialog_content = "...",
  ui_story_1014_10140701_29_dialog_content = "¿Capitán Leo?",
  ui_story_1014_10140701_30_dialog_content = "Caballeros Ironthorn, manténganse en formación.",
  ui_story_1014_10140701_31_dialog_content = "<size=45>¡¿Qué?!</size>",
  ui_story_1014_10140701_32_dialog_content = "La mafia de Eclipsite está casi sobre nosotros. Romper la formación ahora sería un suicidio.",
  ui_story_1014_10140701_33_dialog_content = "No podemos romper la formación.",
  ui_story_1014_10140701_34_dialog_content = "Pero, ¿y ellos? ¡¿Los que están siendo perseguidos ahora mismo?!",
  ui_story_1014_10140701_35_dialog_content = "¡Están a punto de ser atrapados!",
  ui_story_1014_10140701_36_dialog_content = "Lo siento, pero somos caballeros, no dioses. No podemos salvar a todos.",
  ui_story_1014_10140701_37_dialog_content = "Tú...",
  ui_story_1014_10140701_38_dialog_content = "No puedo arriesgarme a que todo Crepúsculo sea consumido por una avalancha de eclipses por unos pocos rezagados, ni puedo pedirles a mis Caballeros que se sacrifiquen por esos civiles.",
  ui_story_1014_10140701_39_dialog_content = "Aquí en la frontera, cada vida es preciosa y cada decisión es importante.",
  ui_story_1014_10140701_40_dialog_content = "¿Así que estamos destinados a verlos ser asesinados por los Eclipsites?",
  ui_story_1014_10140701_41_dialog_content = "Entonces vete, si prefieres no presenciarlo. O actuar solo.",
  ui_story_1014_10140701_42_dialog_content = "Después de todo, no sois Caballeros de Ironthorn y no estáis bajo mi mando.",
  ui_story_1014_10140701_43_dialog_content = "...",
  ui_story_1014_10140701_44_dialog_content = "Multa. ¡Entonces, por favor, mantenga la línea y no deje que nada le pase a Axelia!",
  ui_story_1014_10140701_45_dialog_content = "¡Haremos lo que decidas no hacer!",
  ui_story_1014_10140701_46_dialog_content = "<size=40>Aaaaah!</size>",
  ui_story_1014_10140701_47_dialog_content = "¡¡Hermano!! ¡¿Qué sucedió?!",
  ui_story_1014_10140701_48_dialog_content = "¡Los monstruos están justo detrás de mí! Mi... Me duele la pierna...",
  ui_story_1014_10140701_49_dialog_content = "¡Tienes que correr! ¡Corre ahora!",
  ui_story_1014_10140701_50_dialog_content = "¡No! no puedo dejarte...",
  ui_story_1014_10140701_51_dialog_content = "<size=40>¡¡Argh!!</size>",
  ui_story_1014_10140701_52_dialog_content = "<size=40>¡¡Largarse!!</size>",
  ui_story_1014_10140701_53_dialog_content = "¿Eh? Es esto...",
  ui_story_1014_10140701_54_dialog_content = "¡Aquí hay más, Carleen!",
  ui_story_1014_10140701_55_dialog_content = "Entiendo.",
  ui_story_1014_10140701_56_dialog_content = "¡Déjame los de ahí a mí!",
  ui_story_1014_10140701_57_dialog_content = "¡Todo el mundo! ¡Sígueme! Aguanta ahí solo un poco más. ¡Te llevaremos a un lugar seguro!",
  ui_story_1014_10140701_58_dialog_content = "¡Hurra! ¡Vinieron por nosotros!",
  ui_story_1014_10140701_59_dialog_content = "¡Rápido! ¡Siguelos!",
  ui_story_1014_10140701_60_dialog_content = "No hay tiempo para que nos pongamos detrás de los Caballeros Ironthorn.",
  ui_story_1014_10140701_61_dialog_content = "¡Están casi sobre nosotros! ¡Prepararse!",
  ui_story_1014_10140701_62_dialog_content = "¿Ya? ¡¿Qué hay de los civiles?!",
  ui_story_1014_10140701_63_dialog_content = "¡Haz que permanezcan juntos!",
  ui_story_1014_10140701_64_dialog_content = "¡Haré todo lo posible para protegerlos!",
  ui_story_1014_10140701_65_dialog_content = "Prepararse. Ellos estan aqui.",
  ui_story_1014_10140701_66_dialog_content = "<color=#e8d9bb>Rumble-Rumble-Rumble-</color>",
  ui_story_1014_10140701_67_dialog_content = "<anim type=Shake><size=45>Graaahh—</size></anim>",
  ui_story_1014_10140701_68_dialog_content = "Retrocede un poco, Vice. No dejes que se acerquen demasiado.",
  ui_story_1014_10140701_69_dialog_content = "¡No hay vuelta atrás en un momento como este! ¡A su derecha!",
  ui_story_1014_10140701_70_dialog_content = "¡Guau! Tantos de ellos... ¿Dónde están todos? ¡¿Dónde estoy?!",
  ui_story_1014_10140701_71_dialog_content = "Oh, si Axelia estuviera aquí.",
  ui_story_1014_10140701_72_dialog_content = "¡Oye! ¡Cuida tus palabras! ¡¿Así que no soy suficiente?!",
  ui_story_1014_10140701_73_dialog_content = "¡Todos, pónganse detrás de mí! ¡No te vayas corriendo!",
  ui_story_1014_10140701_74_dialog_content = "Yo te protegere...",
  ui_story_1014_10140701_75_dialog_content = "¡¡Argh!! ¡Eclipsitos, dirigiéndose directamente hacia nosotros!",
  ui_story_1014_10140701_76_dialog_content = "¿Eh? ¿Donde?",
  ui_story_1014_10140701_77_dialog_content = "¡Aquí! ¡Están por aquí!",
  ui_story_1014_10140701_78_dialog_content = "¡Espera, ya voy!",
  ui_story_1014_10140701_79_dialog_content = "¡Graaagh!",
  ui_story_1014_10140701_80_dialog_content = "... ¡Están por todas partes!",
  ui_story_1014_10140701_81_dialog_content = "PlayerName! ¿Puedes darme una idea de la posición del enemigo?",
  ui_story_1014_10140701_82_dialog_content = "No puedo averiguar dónde están...",
  ui_story_1014_10140701_83_dialog_content = "<size=45>¡TODO EL MUNDO! ¡¡SAL DE AQUÍ!!</size>",
  ui_story_1014_10140701_84_dialog_content = "¿Eh? ¿Y adónde estamos destinados a ir?",
  ui_story_1014_10140701_85_dialog_content = "Realmente no lo sé, pero... ¡Cuanto más lejos, mejor!",
  ui_story_1014_10140701_86_dialog_content = "<color=#e8d9bb>Rumble—Rumble—</color>",
  ui_story_1014_10140701_87_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1014_10140701_88_dialog_content = "Wow... Este tipo es ridículo.",
  ui_story_1014_10140701_89_dialog_content = "¡No te quedes ahí parado!",
  ui_story_1014_10140701_90_dialog_content = "<anim type=Shake><size=50>Grrr!</size></anim>",
  ui_story_1014_10140701_91_dialog_content = "*Tos* La formación se rompió... ¿Están todos bien?",
  ui_story_1014_10140701_92_dialog_content = "PlayerName advirtió a todos, por lo que nadie debería haber sido atrapado.",
  ui_story_1014_10140701_93_dialog_content = "Estoy más preocupado por los civiles.",
  ui_story_1014_10140701_94_dialog_content = "Si la formación se rompe, es más probable que sean atacados.",
  ui_story_1014_10140701_95_dialog_content = "¡Estás bien! ¡Deberíamos ir a ayudarlos!",
  ui_story_1014_10140701_96_dialog_content = "¿Podemos siquiera salir de aquí?",
  ui_story_1014_10140701_97_dialog_content = "¡Ayuda!",
  ui_story_1014_10140701_98_dialog_content = "Eclipsitos, ¡están por todas partes!",
  ui_story_1014_10140701_99_dialog_content = "¿A dónde fueron? ¡¿Las personas que venían a salvarnos?!",
  ui_story_1014_10140701_100_dialog_content = "¡Mantengan la calma, todos! ¡Ven a mí, te protegeré!",
  ui_story_1014_10140701_101_dialog_content = "PlayerName, los enemigos...",
  ui_story_1014_10140701_102_dialog_content = "Están en todas partes ahora. ¡Todo el campo de batalla está repleto de ellos!",
  ui_story_1014_10140701_103_dialog_content = "No hay forma de que los civiles se agrupen. Los Eclipsites lograron dispersar a la multitud.",
  ui_story_1014_10140701_104_dialog_content = "S-Entonces, ¿qué hacemos ahora?",
  ui_story_1014_10140701_105_dialog_content = "Estoy pensando...",
  ui_story_1014_10140701_106_dialog_content = "No son solo ellos, también nosotros.",
  ui_story_1014_10140701_107_dialog_content = "Ese monstruo al que llaman Cerritus seguirá lanzando ataques y no sobreviviremos mucho en un mar de eclipses.",
  ui_story_1014_10140701_108_dialog_content = "Estás en el clavo... Está aquí de nuevo...",
  ui_story_1014_10140701_109_dialog_content = "¿Ves alguna salida, Yingel? Por lo general, eres el más inteligente de la sala.",
  ui_story_1014_10140701_110_dialog_content = "Olvídate de los civiles, retírate detrás de los Ironthorn Knights.",
  ui_story_1014_10140701_111_dialog_content = "¿Eh? Pero...",
  ui_story_1014_10140701_112_dialog_content = "León tenía razón. Tenemos que enfrentarlo. Esta es la frontera, y no somos lo suficientemente fuertes.",
  ui_story_1014_10140701_113_dialog_content = "Incluso si seguimos luchando, esos civiles seguirán siendo eliminados uno por uno en el caos.",
  ui_story_1014_10140701_114_dialog_content = "No podemos salvar a todos.",
  ui_story_1014_10140701_115_dialog_content = "...",
  ui_story_1014_10140701_116_dialog_content = "hemos hecho nuestro mejor esfuerzo, PlayerName. Debes comprender nuestra situación.",
  ui_story_1014_10140701_117_dialog_content = "<color=#e8d9bb>Retumbar-</color>",
  ui_story_1014_10140701_118_dialog_content = "¿Oyes eso? Viene el monstruo.",
  ui_story_1014_10140701_119_dialog_content = "N-nosotros...",
  ui_story_1014_10140701_120_dialog_content = "Si no te decides, te llevaré conmigo.",
  ui_story_1014_10140701_121_dialog_content = "!",
  ui_story_1014_10140701_122_dialog_content = "Deme algo de cobertura, Srta. Lumopolis. Nos retiramos.",
  ui_story_1014_10140701_123_dialog_content = "Pero...",
  ui_story_1014_10140701_124_dialog_content = "¡Yo prometí! Dije que los protegería...",
  ui_story_1014_10140701_125_dialog_content = "Entonces deja que tu propio crecimiento comience con una promesa que no puedes cumplir.",
  ui_story_1014_10140701_126_dialog_content = "<color=#e8d9bb>Retumbar-</color>",
  ui_story_1014_10140701_127_dialog_content = "Lo siento, pero al menos tengo que intentarlo. No puedo romper mi palabra tan fácilmente.",
  ui_story_1014_10140701_128_dialog_content = "Porque elegí llamarme caballero.",
  ui_story_1014_10140701_129_dialog_content = "Tú—",
  ui_story_1014_10140701_130_dialog_content = "¡¡Beretta!!",
  ui_story_1014_10140701_131_dialog_content = "Así que te haces llamar caballero. Dad gracias al nombre, por haceros así justos y puros.",
  ui_story_1014_10140701_132_dialog_content = "¿Ah?",
  ui_story_1014_10140701_133_dialog_content = "Rooarrrrr—",
  ui_story_1014_10140701_134_dialog_content = "¡Cerritus fue repelido por Luminatics! Eso fue-",
  ui_story_1014_10140701_135_dialog_content = "Esta es la primera vez que conozco a un caballero como tú.",
  ui_story_1014_10140701_136_dialog_content = "R-¿En serio? Sólo estoy haciendo lo que se espera de un caballero.",
  ui_story_1014_10140701_137_dialog_content = "Pero otros caballeros no son como tú.",
  ui_story_1014_10140701_138_dialog_content = "Eres tan hermosa... ¿Eres una especie de ángel?",
  ui_story_1014_10140701_139_dialog_content = "Yo también he deseado durante mucho tiempo encontrarme con un ángel, pero, por desgracia... Todavía tienen que venir ante mí.",
  ui_story_1014_10140701_140_dialog_content = "Por lo tanto, los mortales deben ser suficientes para algunos esfuerzos.",
  ui_story_1014_10140701_141_dialog_content = "Aldeanos, seguid la luz y venid a mí.",
  ui_story_1014_10140701_142_dialog_content = "Noche blanca en lo alto, la luz purgará todo mal y guiará a todas las almas de regreso a casa.",
  ui_story_1014_10140701_143_dialog_content = "¡Mirar! ¡Los Eclipsites tienen miedo de la luz de allí!",
  ui_story_1014_10140701_144_dialog_content = "¡Rápido! ¡Vamos allá! ¡Estaremos a salvo!",
  ui_story_1014_10140701_145_dialog_content = "¡He oído hablar de ella! Tiene que ser ella, ¡la Santa del Crepúsculo!",
  ui_story_1014_10140701_146_dialog_content = "¡Asombroso! ¡Los civiles han logrado agruparse de nuevo!",
  ui_story_1014_10140701_147_dialog_content = "Los Eclipsites se esconden de la luz que irradia el cuerpo de la niña. ¡Parece que tenemos que seguirnos si queremos salir de aquí!",
  ui_story_1014_10140701_148_dialog_content = "Sí, estoy de acuerdo. Entonces, cambio de planes: ahora rodeamos a esa chica y hacemos todo lo posible para cubrir la retirada del civil.",
  ui_story_1014_10140701_149_dialog_content = "¡Copie eso, Comandante Yingel!",
  ui_story_1014_10140701_150_dialog_content = "No me llames así.",
  ui_story_1014_10140701_151_dialog_content = "¡Capitán! ¡Están regresando! ¡CON esos civiles!",
  ui_story_1014_10140701_152_dialog_content = "Yo vi. Abra la formación con cuidado y llévelos a la parte trasera.",
  ui_story_1014_10140701_153_dialog_content = "¡Sí señor!",
  ui_story_1014_10140701_154_dialog_content = "¡Son los Caballeros de Ironthorn! ¡Gracias a dios! Estamos a salvo ahora.",
  ui_story_1014_10140701_155_dialog_content = "¡Agarrar el ritmo! ¿Cómo podría alguien relajarse hasta que estemos en Crepúsculo y fuera de este maldito desierto?",
  ui_story_1014_10140701_156_dialog_content = "Buen trabajo, Capitán Leo.",
  ui_story_1014_10140701_157_dialog_content = "Estás siendo sarcástico, ¿verdad? <color=#FFB400>Su Santidad</color>?",
  ui_story_1014_10140701_158_dialog_content = "De nada. No soy tan infantil y soy plenamente consciente de su situación.",
  ui_story_1014_10140701_159_dialog_content = "Muchos están huyendo a Crepúsculo, se está volviendo imposible protegerlos tanto como a nuestra ciudad.",
  ui_story_1014_10140701_160_dialog_content = "Cada Eclipsite que logre pasarte se precipitará directamente hacia Crepúsculo. Naturalmente, no puedes salir de la línea defensiva.",
  ui_story_1014_10140701_161_dialog_content = "Gracias por tu absolución. Me siento mejor ahora.",
  ui_story_1014_10140701_162_dialog_content = "Tu cara no lo muestra. ¿Es este el tema de la dignidad del que ha hablado?",
  ui_story_1014_10140701_163_dialog_content = "No en realidad no. Es que te tengo envidia, que eres capaz de hacer tan fácilmente lo que yo no puedo.",
  ui_story_1014_10140701_164_dialog_content = "Ahora te toca a ti, hacer lo que yo no puedo.",
  ui_story_1014_10140701_165_dialog_content = "Seguramente. Lleva a los civiles a la retaguardia y déjame el campo de batalla a mí.",
  ui_story_1014_10140701_166_dialog_content = "Ni un solo Eclipsite superará a los Ironthorn Knights.",
  ui_story_1014_10140701_167_dialog_content = "Tengo fe en ti.",
  ui_story_1014_10140701_168_dialog_content = "Adelante entonces. Nuestro breve tiempo juntos ha llegado a su fin.",
  ui_story_1014_10140701_169_dialog_content = "Siempre parece así con nosotros, rozándonos los hombros al pasar en el campo de batalla.",
  ui_story_1014_10140701_170_dialog_content = "Sí. Siempre.",
  ui_story_1014_10140701_171_dialog_content = "Siempre estamos corriendo en direcciones opuestas.",
  ui_story_1014_10140701_172_dialog_content = "Nuestro amigo se está acercando. Puedo oírlo.",
  ui_story_1014_10140701_173_dialog_content = "¡Caballeros de Espina de Hierro! ¡Apoyar! ¿Quién está por darle al grandullón una patada igual de grande?",
  ui_story_1014_10140701_174_dialog_content = "<size=40>¡¡YO!!</size>",
  ui_story_1014_10140701_175_dialog_content = "<size=40>¡Yo también!</size>",
  ui_story_1014_10140701_176_dialog_content = "¿Quieres unirte a nosotros? Si todavía tienes fuerzas para luchar, por supuesto.",
  ui_story_1014_10140701_177_dialog_content = "¡Definitivamente! ¡Es hora de devolver diez veces lo que acabamos de sufrir!",
  ui_story_1014_10140701_178_dialog_content = "Jajajajaja! ¡Me gusta ese espíritu!",
  ui_story_1014_10140701_179_dialog_content = "Con tu ayuda, nuestro objetivo no será puramente defensivo.",
  ui_story_1014_10140701_180_dialog_content = "¡Esta noche, quiero colgar nuestro estandarte en sus cuernos!",
  ui_story_1014_10140702_1_dialog_content = "<anim type=Shake><size=45>Graah!!! Graaaaah—</size></anim>",
  ui_story_1014_10140702_2_dialog_content = "Dale un descanso, grandote.",
  ui_story_1014_10140702_3_dialog_content = "Uf... Finalmente está abajo. Esa cosa era locamente fuerte.",
  ui_story_1014_10140702_4_dialog_content = "No te relajes todavía. El ataque de los Eclipsites aún está en curso, y debemos verlo hasta el final.",
  ui_story_1014_10140702_5_dialog_content = "¡Por supuesto! Pero al menos la presión está apagada.",
  ui_story_1014_10140702_6_dialog_content = "Dios, finalmente estamos fuera de esa mafia de Eclipsite.",
  ui_story_1014_10140702_7_dialog_content = "¿Qué pasa con Cerrito? ¿Adónde se fue ese grandote?",
  ui_story_1014_10140702_8_dialog_content = "...",
  ui_story_1014_10140702_9_dialog_content = "¡Gracias! ¡Oh, gracias, Su Santidad!",
  ui_story_1014_10140702_10_dialog_content = "¡Nos salvaste a todos!",
  ui_story_1014_10140702_11_dialog_content = "Oh, por favor... Por favor, deja de llamarme así.",
  ui_story_1014_10140702_12_dialog_content = "Me llamo <color=#FFB400>joselyne</color>. Seremos vecinos si eliges establecerte en Crepúsculo.",
  ui_story_1014_10140702_13_dialog_content = "Oh cierto, ¿qué se supone que debemos hacer ahora?",
  ui_story_1014_10140702_14_dialog_content = "Vayamos a Crepúsculo primero. Con las tropas de Lumopolis e Illumina allí, al menos estaremos a salvo.",
  ui_story_1014_10140702_15_dialog_content = "Si seguimos moviéndonos, no se sabe cuándo podrían ser atacados por los eclipses de nuevo.",
  ui_story_1014_10140702_16_dialog_content = "Acordado. Y no quiero tener que huir, no otra vez.",
  ui_story_1014_10140702_17_dialog_content = "Todos diríjanse primero a Crepúsculo. Todos deben estar exhaustos, considerando lo que han pasado.",
  ui_story_1014_10140702_18_dialog_content = "Habrá otros llegando a Crepúsculo hoy también. La gente del pueblo se está preparando para instalarlos.",
  ui_story_1014_10140702_19_dialog_content = "Habrá habitaciones para todos esta noche, así que descanse y recargue energías.",
  ui_story_1014_10140702_20_dialog_content = "Podemos discutir lo que viene mañana por la mañana.",
  ui_story_1014_10140702_21_dialog_content = "¡Maravilloso! Muchas gracias por cuidarnos con tanto cariño.",
  ui_story_1014_10140702_22_dialog_content = "Lamentablemente, esta no es la primera vez que Twilight ha tenido que hacer esto.",
  ui_story_1014_10140702_23_dialog_content = "Muchas de las personas que viven aquí también huyeron de los lugares vecinos, por lo que todos se solidarizan con su situación.",
  ui_story_1014_10140702_24_dialog_content = "Hacemos lo que podemos para ayudar. Espero que encuentres un nuevo hogar lo antes posible.",
  ui_story_1014_10140702_25_dialog_content = "¿Un nuevo hogar? ¡Oh, sí, lo haremos!",
  ui_story_1014_10140702_26_dialog_content = "Se está haciendo tarde. Diríjanse a la ciudad, todos.",
  ui_story_1014_10140702_27_dialog_content = "¡Bien! ¡Solo espere a que nos instalemos, luego vendremos y le agradeceremos adecuadamente, Su Santidad!",
  ui_story_1014_10140702_28_dialog_content = "Ahh, ya dije que me llamara simplemente Joselyne.",
  ui_story_1014_10140702_29_dialog_content = "Noche Blanca en lo alto, te visitaremos en la iglesia cuando podamos!",
  ui_story_1014_10140702_30_dialog_content = "¡No soy parte de la iglesia, así que no me encontrarás allí!",
  ui_story_1014_10140702_31_dialog_content = "¿Qué? ¿No eres miembro de la iglesia?",
  ui_story_1014_10140702_32_dialog_content = "No, en absoluto. Solo soy una persona común, igual que todos ustedes.",
  ui_story_1014_10140702_33_dialog_content = "Si quieres encontrarme, ven al mercado. A menudo estoy allí vendiendo cosas.",
  ui_story_1014_10140702_34_dialog_content = "Bien, el mercado. ¡Recordaré eso!",
  ui_story_1014_10140702_35_dialog_content = "Adiós, Su Santidad.",
  ui_story_1014_10140702_36_dialog_content = "es joselyn...",
  ui_story_1014_10140702_37_dialog_content = "Madre mía, ese sonido...",
  ui_story_1014_10140702_38_dialog_content = "Están de vuelta.",
  ui_story_1014_10140702_39_dialog_content = "<color=#e8d9bb>Clip-clop, clip-clop</color>",
  ui_story_1014_10140702_40_dialog_content = "Así que vino a visitar la frontera, Lady Carleen.",
  ui_story_1014_10140702_41_dialog_content = "Correcto. Ha pasado mucho tiempo desde la última vez que Lumopolis intercambió noticias con Twilight.",
  ui_story_1014_10140702_42_dialog_content = "¿No es un poco exagerado enviarte aquí por un asunto tan trivial?",
  ui_story_1014_10140702_43_dialog_content = "Usted ha visto la situación general aquí. El conflicto aquí es una lucha, pero aún podemos mantener cierta apariencia de estabilidad.",
  ui_story_1014_10140702_44_dialog_content = "Nuestras fuerzas están concentradas alrededor de la Fortaleza Lumo. El núcleo de energía de Twilight está ahí, por lo que tiene mucha defensa.",
  ui_story_1014_10140702_45_dialog_content = "Si tiene tiempo, Lady Carleen, le invitamos a hacer un recorrido.",
  ui_story_1014_10140702_46_dialog_content = "Gracias, me gustaría eso.",
  ui_story_1014_10140702_47_dialog_content = "Casi estámos allí.",
  ui_story_1014_10140702_48_dialog_content = "Parece que tenemos una fiesta de bienvenida.",
  ui_story_1014_10140702_49_dialog_content = "¡Oye, esa es... la chica de la batalla!",
  ui_story_1014_10140702_50_dialog_content = "Recuerdo que todos la llamaban la \"Santa del Crepúsculo\".",
  ui_story_1014_10140702_51_dialog_content = "Por favor, olvida ese título y llámame Joselyne.",
  ui_story_1014_10140702_52_dialog_content = "Me impresionó tu heroísmo en el campo de batalla.",
  ui_story_1014_10140702_53_dialog_content = "Estoy aquí en nombre del pueblo para dar la bienvenida a su regreso triunfal.",
  ui_story_1014_10140702_54_dialog_content = "Diría que fue más tu conducta en la batalla lo que fue más impresionante.",
  ui_story_1014_10140702_55_dialog_content = "¡Sí! ¡La forma en que apareciste, bañado en luz! ¡Tan dramático!",
  ui_story_1014_10140702_56_dialog_content = "Aunque apuesto a que esos civiles que salvaste se sienten aún más fuertes que yo.",
  ui_story_1014_10140702_57_dialog_content = "Realmente parecías un emisario divino...",
  ui_story_1014_10140702_58_dialog_content = "Por favor, no digas esas cosas, me aterroriza.",
  ui_story_1014_10140702_59_dialog_content = "Nunca pensé que vería una Lumina tan pura tan lejos de Lumopolis.",
  ui_story_1014_10140702_60_dialog_content = "No estoy tan familiarizado con la iglesia fronteriza. ¿Es usted miembro?",
  ui_story_1014_10140702_61_dialog_content = "La forma en que estás vestida... no es como imagino que lo haría una monja.",
  ui_story_1014_10140702_62_dialog_content = "Ah, la gente siempre tiene esa idea de mí.",
  ui_story_1014_10140702_63_dialog_content = "Pero no soy miembro de la iglesia, lo siento.",
  ui_story_1014_10140702_64_dialog_content = "¿No me digas que eres un soldado Iluminado?",
  ui_story_1014_10140702_65_dialog_content = "Los soldados de Illumina no se visten así.",
  ui_story_1014_10140702_66_dialog_content = "Aquí en la frontera, no todos tienen que estar aliados con Lumopolis o Illumina. Y tampoco son solo los soldados los que luchan.",
  ui_story_1014_10140702_67_dialog_content = "Técnicamente, ella es una comerciante de tomates.",
  ui_story_1014_10140702_68_dialog_content = "¡¿?!",
  ui_story_1014_10140702_69_dialog_content = "Me gustaría recordarle al poderoso Capitán que también estoy en el negocio del tejido.",
  ui_story_1014_10140702_70_dialog_content = "Nunca me has comprado ni un solo tomate, pero he reparado al menos dos de tus pancartas.",
  ui_story_1014_10140702_71_dialog_content = "Disculpas... Deseo apoyar tu negocio, pero los tomates no son realmente parte de la dieta de un caballero.",
  ui_story_1014_10140702_72_dialog_content = "¡Caballeros! ¿Qué comemos?",
  ui_story_1014_10140702_73_dialog_content = "¡CARNE!",
  ui_story_1014_10140702_74_dialog_content = "¡Nada como una sabrosa pierna de cordero asada a la perfección!",
  ui_story_1014_10140702_75_dialog_content = "Bueno... Espero que tus gustos pronto se pongan al día con tus habilidades de combate.",
  ui_story_1014_10140702_76_dialog_content = "De todos modos, todos, excepto los caballeros, son forasteros, ¿verdad? No creo haberlos visto antes, chicos.",
  ui_story_1014_10140702_77_dialog_content = "Así es. Acabamos de llegar de la ciudad de Gannon, en el este.",
  ui_story_1014_10140702_78_dialog_content = "¿Ciudad de Gannon? Entonces realmente has recorrido un largo camino. Solo lo he visto en un mapa.",
  ui_story_1014_10140702_79_dialog_content = "¿Y supongo que te quedarás en Crepúsculo un poco más?",
  ui_story_1014_10140702_80_dialog_content = "Por cierto. Tenemos algunos asuntos que atender aquí.",
  ui_story_1014_10140702_81_dialog_content = "En ese caso, ¿por qué no vienes conmigo? Puedo ayudar a organizar algunos alojamientos adecuados.",
  ui_story_1014_10140702_82_dialog_content = "Y espero no estar molestando, pero también me gustaría invitarlos a todos a probar algunas especialidades locales.",
  ui_story_1014_10140702_83_dialog_content = "Es lo menos que puedo hacer para pagar tu valentía.",
  ui_story_1014_10140702_84_dialog_content = "¿eh? E-Eso es muy amable, pero seguramente innecesario.",
  ui_story_1014_10140702_85_dialog_content = "No recibimos muchos visitantes aquí, menos aún que luchen por nosotros.",
  ui_story_1014_10140702_86_dialog_content = "Tenía la intención de invitarlos a todos a cenar también, si Joselyne no se me hubiera adelantado.",
  ui_story_1014_10140702_87_dialog_content = "Pero dado que Su Santidad se ha ofrecido amablemente a pagar la factura, ¡le sugiero que la acepte!",
  ui_story_1014_10140702_88_dialog_content = "Ya veo... ¿Qué piensan todos?",
  ui_story_1014_10140702_89_dialog_content = "Bueno, llegados a este punto, sería de mala educación no aceptar.",
  ui_story_1014_10140702_90_dialog_content = "Definitivamente acepto! Quiero saber qué tipo de delicias tiene Twilight. ¡No puedo esperar!",
  ui_story_1014_10140702_91_dialog_content = "Estoy bastante familiarizado con todo lo que nuestra ciudad tiene para ofrecer. Estoy seguro de que todos estarán satisfechos.",
  ui_story_1014_10140702_92_dialog_content = "Usted también luchó duro, capitán Leo. ¿Me harías el honor de acompañarnos a cenar?",
  ui_story_1014_10140702_93_dialog_content = "¿Me estás invitando solo a mí o a todos los Caballeros de Ironthorn?",
  ui_story_1014_10140702_94_dialog_content = "Me temo que el restaurante que tenía en mente no tiene capacidad para todos los caballeros.",
  ui_story_1014_10140702_95_dialog_content = "¡Ah, no puede mostrar favoritismo así, Su Santidad!",
  ui_story_1014_10140702_96_dialog_content = "¿No hemos derramado sangre por Crepúsculo también?",
  ui_story_1014_10140702_97_dialog_content = "Muy bien, muy bien, ustedes no se lo perderán.",
  ui_story_1014_10140702_98_dialog_content = "Para celebrar nuestra victoria, esta noche todos pueden comer hasta saciarse de lo que quieran. Invito yo.",
  ui_story_1014_10140702_99_dialog_content = "<size=45>¡SÍ! ¡¡Impresionante!!</size>",
  ui_story_1014_10140702_100_dialog_content = "Me temo que no podré unirme a ustedes, ya que la señorita Joselyne está siendo muy generosa.",
  ui_story_1014_10140702_101_dialog_content = "Acompañaré a nuestros nuevos amigos desde lejos.",
  ui_story_1014_10140702_102_dialog_content = "También me gustaría ver por mí mismo qué tipo de comida involucran los mejores gustos de Joselyne.",
  ui_story_1014_10140801_1_dialog_content = "¿Qué hacemos para la ropa de cama y esas cosas...? Almohadas, mantas, ropa...",
  ui_story_1014_10140801_2_dialog_content = "Oh, no traje nada.",
  ui_story_1014_10140801_3_dialog_content = "No es como si pudieras detenerte y empacar cuando estás huyendo para salvar tu vida.",
  ui_story_1014_10140801_4_dialog_content = "Ni siquiera tuve tiempo de encontrar mi billetera. Me preocupa pasar hambre pronto.",
  ui_story_1014_10140801_5_dialog_content = "Oye, escuché que pueden prestarte algunos conceptos básicos allí.",
  ui_story_1014_10140801_6_dialog_content = "¡Vamos juntos y echemos un vistazo!",
  ui_story_1014_10140801_7_dialog_content = "Hay tantos refugiados en la calle.",
  ui_story_1014_10140801_8_dialog_content = "¿Acabaron de llegar todos hoy?",
  ui_story_1014_10140801_9_dialog_content = "Sí. Lamentablemente, tales escenas son muy comunes en Crepúsculo.",
  ui_story_1014_10140801_10_dialog_content = "¿En serio?",
  ui_story_1014_10140801_11_dialog_content = "Si bien Lumopolis e Illumina tienen guarniciones aquí, las áreas fuera de nuestra ciudad no están gobernadas por ningún poder.",
  ui_story_1014_10140801_12_dialog_content = "Los pequeños pueblos dispersos alrededor suelen ser autosuficientes y contentos.",
  ui_story_1014_10140801_13_dialog_content = "Pero, cuando Aurorastorm y los Eclipsites comenzaron a atacar, esos pueblos básicamente no pudieron defenderse.",
  ui_story_1014_10140801_14_dialog_content = "Los aldeanos no tuvieron más remedio que abandonar sus hogares y buscar refugio en las guarniciones.",
  ui_story_1014_10140801_15_dialog_content = "Llegaron como granos de arena dispares, todos recogidos por el viento y llevados al mismo puerto seguro.",
  ui_story_1014_10140801_16_dialog_content = "Los granos de arena se acumularon en una duna, y los refugiados echaron raíces y establecieron Crepúsculo.",
  ui_story_1014_10140801_17_dialog_content = "Entiendo...",
  ui_story_1014_10140801_18_dialog_content = "¿Por qué la gente no optó por seguir moviéndose y buscar un lugar más seguro?",
  ui_story_1014_10140801_19_dialog_content = "¿Te refieres a Lumopolis o Gannon en el este?",
  ui_story_1014_10140801_20_dialog_content = "Por supuesto que querían ir. Pero con el día a día ya tan duro, no era tan sencillo.",
  ui_story_1014_10140801_21_dialog_content = "¿Cómo se ganarían la vida en tierras tan lejanas? ¿Dónde vivirían?",
  ui_story_1014_10140801_22_dialog_content = "Nadie proporcionaría voluntariamente tierras o viviendas a extraños.",
  ui_story_1014_10140801_23_dialog_content = "Pero aquí, en las Ruinas de Aurora, al menos el suelo es fértil y no necesitan preocuparse por las necesidades básicas. Incluso con la siempre presente amenaza Eclipsite...",
  ui_story_1014_10140801_24_dialog_content = "Todos pensaron que era mejor enfrentar las dificultades conocidas que estar desarraigado y errante.",
  ui_story_1014_10140801_25_dialog_content = "Ah... Lo siento, estaba siendo ingenuo.",
  ui_story_1014_10140801_26_dialog_content = "Jajaja, no te preocupes! Nadie te juzgaría.",
  ui_story_1014_10140801_27_dialog_content = "Estoy seguro de que este lugar es diferente a cualquier otro lugar en el que hayas estado, por lo que es natural preguntarse.",
  ui_story_1014_10140801_28_dialog_content = "Tienes razón, es totalmente diferente. ¡No solo se deja a la gente a su suerte, sino que aparentemente, Lumopolis e Illumina pueden coexistir en la misma ciudad!",
  ui_story_1014_10140801_29_dialog_content = "Dices que coexisten, pero en realidad, por lo general, se evitan entre sí.",
  ui_story_1014_10140801_30_dialog_content = "Hay representantes de facciones aquí con nosotros ahora mismo. Puedes preguntarles.",
  ui_story_1014_10140801_31_dialog_content = "La coexistencia de Lumopolis e Illumina es algo que ha estado sucediendo desde que llegué a Crepúsculo cuando era niño.",
  ui_story_1014_10140801_32_dialog_content = "Pero he escuchado a algunos de los ancianos hablar de problemas en el pasado.",
  ui_story_1014_10140801_33_dialog_content = "Todos los poderes fácticos quieren mantener segura la frontera de las Ruinas de Aurora. Pero aparte de eso, no hay órdenes más explícitas.",
  ui_story_1014_10140801_34_dialog_content = "Illumina y Lumopolis ven las Ruinas de Aurora de la misma manera: una frontera desolada que apenas vale la pena para nadie, pero aún así es una pena abandonarla.",
  ui_story_1014_10140801_35_dialog_content = "Dado que nadie en lo alto puede preocuparse por este lugar, los soldados de ambos bandos tienden a perder su meticulosidad sobre las cosas que les han enseñado sobre el otro.",
  ui_story_1014_10140801_36_dialog_content = "Si bien la tierra dentro y alrededor de las Ruinas de Aurora es bastante fértil, hay una clara falta de fuentes de energía. Los que tenemos se concentran principalmente en Crepúsculo y sus alrededores.",
  ui_story_1014_10140801_37_dialog_content = "Para poder satisfacer sus propias necesidades energéticas, ambas partes acordaron estar guarnecidas aquí de forma conjunta.",
  ui_story_1014_10140801_38_dialog_content = "¿No causaría conflicto pelear por los mismos escasos recursos?",
  ui_story_1014_10140801_39_dialog_content = "Lidiar con los Eclipsites ya es tan agotador que nadie tiene la fuerza de sobra para un conflicto interno.",
  ui_story_1014_10140801_40_dialog_content = "Supervivencia es el nombre del juego aquí.",
  ui_story_1014_10140801_41_dialog_content = "El campo de batalla pronto educa a aquellos que son incapaces de diferenciar prioridades.",
  ui_story_1014_10140801_42_dialog_content = "Entonces asi es como es.",
  ui_story_1014_10140801_43_dialog_content = "Me recuerda a la Coalición Auroriana sobre la que leí en un libro de historia.",
  ui_story_1014_10140801_44_dialog_content = "Frente a poderosos enemigos externos, las dos partes lograron resolver sus diferencias.",
  ui_story_1014_10140801_45_dialog_content = "<color=#e8d9bb>¡Silbido!</color>",
  ui_story_1014_10140801_46_dialog_content = "<anim type=Agitar>Nghn...</anim>",
  ui_story_1014_10140801_47_dialog_content = "¡Axelia! ¡Estas despierto!",
  ui_story_1014_10140801_48_dialog_content = "Buenos dias, PlayerName.",
  ui_story_1014_10140801_49_dialog_content = "No está ni remotamente cerca de la mañana...",
  ui_story_1014_10140801_50_dialog_content = "¿Eh? ¿Has tenido a una chica adorable escondida?",
  ui_story_1014_10140801_51_dialog_content = "Mi apariencia es normal y fundamentalmente sin importancia.",
  ui_story_1014_10140801_52_dialog_content = "Sin embargo, me muero de hambre.",
  ui_story_1014_10140801_53_dialog_content = "¡Buen tiempo! Este es el restaurante.",
  ui_story_1014_10140801_54_dialog_content = "¿Qué te gustaría comer?",
  ui_story_1014_10140801_55_dialog_content = "Azúcar.",
  ui_story_1014_10140801_56_dialog_content = "Aquí tenemos hojaldres, tartaletas de crema pastelera, hojaldres de nata o bizcocho con glaseado de mantequilla.",
  ui_story_1014_10140801_57_dialog_content = "Mmm, todo se ve excelente.",
  ui_story_1014_10140801_58_dialog_content = "¿Crees que está bien comer tantos postres, Joselyne?",
  ui_story_1014_10140801_59_dialog_content = "Está bien. Una indulgencia ocasional no es un problema.",
  ui_story_1014_10140801_60_dialog_content = "Parece que hay varias caras desconocidas contigo hoy.",
  ui_story_1014_10140801_61_dialog_content = "Sí, estos invitados vinieron desde Gannon City.",
  ui_story_1014_10140801_62_dialog_content = "Gannon, ¿eh? El viejo de al lado ha estado allí. Escuché que es un lugar terriblemente rígido...",
  ui_story_1014_10140801_63_dialog_content = "R-Rígido? No está tan mal...",
  ui_story_1014_10140801_64_dialog_content = "Aparte de ellos, también tenemos nuestros propios soldados locales.",
  ui_story_1014_10140801_65_dialog_content = "Este es Sean, un joven oficial Illuminan... Y este es Leo, capitán de los Lumopolis Ironthorn Knights.",
  ui_story_1014_10140801_66_dialog_content = "¡Sí! ¡Soy el segundo teniente Sean, de Twilight Garrison!",
  ui_story_1014_10140801_67_dialog_content = "Oye, esto no es un comedor de Illumina. No hace falta saludar.",
  ui_story_1014_10140801_68_dialog_content = "Jajaja, siempre es interesante ver la reacción de Sean.",
  ui_story_1014_10140801_69_dialog_content = "Jefe, su cerdo asado es absolutamente impresionante.",
  ui_story_1014_10140801_70_dialog_content = "¡La próxima vez traeré a todos mis caballeros aquí para que prueben!",
  ui_story_1014_10140801_71_dialog_content = "Ahí vas de nuevo, solo pensando en la carne.",
  ui_story_1014_10140801_72_dialog_content = "Este es un negocio, después de todo, y no sobrevivirás si no ofreces calidad.",
  ui_story_1014_10140801_73_dialog_content = "No veo a nadie más trabajando aquí. ¿No puedes ser el único que cuida un lugar tan grande?",
  ui_story_1014_10140801_74_dialog_content = "que soy",
  ui_story_1014_10140801_75_dialog_content = "¿No es eso agotador? Con su talento, definitivamente podría traer un par de manos nuevas para ayudar a hacer crecer el negocio.",
  ui_story_1014_10140801_76_dialog_content = "No estoy realmente interesado. Estoy feliz de ser un espectáculo de un solo hombre.",
  ui_story_1014_10140801_77_dialog_content = "Cuando abrí por primera vez, estaba con mi hermano, pero discutimos tanto que rápidamente se volvió aburrido.",
  ui_story_1014_10140801_78_dialog_content = "Es la primera vez que te escucho mencionar a un hermano.",
  ui_story_1014_10140801_79_dialog_content = "Sí. Falleció hace tres años.",
  ui_story_1014_10140801_80_dialog_content = "Fue asesinado por Eclipsites mientras huíamos a Crepúsculo.",
  ui_story_1014_10140801_81_dialog_content = "Oh...",
  ui_story_1014_10140801_82_dialog_content = "Tenía algunos problemas con las piernas y estaba luchando en la parte trasera del grupo.",
  ui_story_1014_10140801_83_dialog_content = "Los caballeros de Lumopolis llegaron justo cuando los Eclipsites se acercaban. Pero no lo salvaron.",
  ui_story_1014_10140801_84_dialog_content = "...",
  ui_story_1014_10140801_85_dialog_content = "(Los Caballeros...)",
  ui_story_1014_10140801_86_dialog_content = "No los odio. De hecho, me salvaron.",
  ui_story_1014_10140801_87_dialog_content = "La vida no vale mucho por aquí, y no hay mucho espacio para regatear.",
  ui_story_1014_10140801_88_dialog_content = "No importa quién se salva y quién no. Todo está destinado a ser.",
  ui_story_1014_10140801_89_dialog_content = "No digas eso. Todas las vidas son igualmente valiosas.",
  ui_story_1014_10140801_90_dialog_content = "Sé que así lo ves, Joselyne, porque eres diferente.",
  ui_story_1014_10140801_91_dialog_content = "Salvarás a todos y harás que todos quieran creer que hay alguna divinidad en este mundo.",
  ui_story_1014_10140801_92_dialog_content = "Pero no soy yo quien mantiene la paz en Crepúsculo. Son los soldados apostados aquí.",
  ui_story_1014_10140801_93_dialog_content = "Si no valoráramos todas las vidas, ¿cómo podría Twilight evolucionar hasta convertirse en el refugio que es hoy?",
  ui_story_1014_10140801_94_dialog_content = "La vida es maravillosa. Y tanto salvarlos como abandonarlos son actos de homenaje ante tal maravilla.",
  ui_story_1014_10140801_95_dialog_content = "Esos soldados se enfrentaron a la elección final antes que nadie.",
  ui_story_1014_10140801_96_dialog_content = "...",
  ui_story_1014_10140801_97_dialog_content = "En realidad, ellos—",
  ui_story_1014_10140801_98_dialog_content = "Joselyne, ¿me pasas ese plato de salchichas que tienes delante, por favor? Simplemente no puedo tener suficiente.",
  ui_story_1014_10140801_99_dialog_content = "Ah, aquí.",
  ui_story_1014_10140801_100_dialog_content = "Asi que, PlayerName, Realmente no he preguntado... ¿Qué te trae a Crepúsculo?",
  ui_story_1014_10140801_101_dialog_content = "(Hmm... Leo ha cambiado de tema.)",
  ui_story_1014_10140801_102_dialog_content = "¡Y que te acompañe un oficial de alto rango de Illumina! Eso es todo un honor.",
  ui_story_1014_10140801_103_dialog_content = "Por supuesto, si es confidencial, entonces olvida que pregunté.",
  ui_story_1014_10140801_104_dialog_content = "Oh, eh, estamos aquí para reparar el Coloso.",
  ui_story_1014_10140801_105_dialog_content = "¡¿Coloso?! ¿Estás diciendo que tienes...",
  ui_story_1014_10140801_106_dialog_content = "¡Así es! Eres un caelestita, así que supongo que es normal.",
  ui_story_1014_10140801_107_dialog_content = "Mencionaste reparaciones... ¿Qué le pasa?",
  ui_story_1014_10140801_108_dialog_content = "No estoy seguro de cuál es la mejor manera de explicar. No es que algo haya fallado, pero parece haber perdido el conocimiento temporalmente.",
  ui_story_1014_10140801_109_dialog_content = "Un Coloso perdiendo el conocimiento es quizás un poco difícil de entender...",
  ui_story_1014_10140801_110_dialog_content = "Está bien, lo entiendo. Es bastante fácil de entender.",
  ui_story_1014_10140801_111_dialog_content = "No es de extrañar que vinieras a Crepúsculo, entonces. ¿Supongo que estás buscando al investigador de Illumina?",
  ui_story_1014_10140801_112_dialog_content = "Sí. ¿Cómo lo supiste?",
  ui_story_1014_10140801_113_dialog_content = "Puede que no entienda los entresijos de Colossus, pero estoy familiarizado con su historia.",
  ui_story_1014_10140801_114_dialog_content = "Es más exacto decir que todos en Crepúsculo conocen la historia.",
  ui_story_1014_10140801_115_dialog_content = "No hay demasiadas leyendas que valga la pena volver a contar en un lugar tan remoto como este.",
  ui_story_1014_10140801_116_dialog_content = "Leyendas? ¿Qué tipo de historias has escuchado?",
  ui_story_1014_10140801_117_dialog_content = "Déjame pensar por dónde empezar.",
  ui_story_1014_10140801_118_dialog_content = "Oh olvídalo. Mejor deja que Joselyne te lo cuente. Ella sabe cómo contar una buena historia.",
  ui_story_1014_10140801_119_dialog_content = "¿no? Te veo parloteando en la taberna, toda la noche...",
  ui_story_1014_10140801_120_dialog_content = "Estoy ocupado comiendo carne ahora mismo.",
  ui_story_1014_10140801_121_dialog_content = "¡Decir ah! Multa. Te invité a cenar, supongo que no puedo dejar que pases hambre.",
  ui_story_1014_10140801_122_dialog_content = "Entonces, esta leyenda se remonta mil años atrás.",
  ui_story_1014_10140801_123_dialog_content = "No pasó mucho tiempo después de que los aurorianos abandonaran Northland, cuando Lumopolis acababa de fundarse.",
  ui_story_1014_10140801_124_dialog_content = "Con el fin de establecer un hogar adecuado, los aurorianos se militarizaron y comenzaron su interminable lucha contra los Eclipsites.",
  ui_story_1014_10140801_125_dialog_content = "El territorio auroriano siguió expandiéndose durante el conflicto, y finalmente se convirtió en algo similar a lo que tenemos hoy.",
  ui_story_1014_10140801_126_dialog_content = "El punto más lejano de esta expansión es el mismo lugar en el que te encuentras ahora: las Ruinas de Aurora.",
  ui_story_1014_10140801_127_dialog_content = "¡Guau! ¡Así que este lugar ha estado justo en la frontera durante tanto tiempo!",
  ui_story_1014_10140801_128_dialog_content = "No subestimes la posición estratégica de las Ruinas Aurora.",
  ui_story_1014_10140801_129_dialog_content = "Mientras se mantenga la línea defensiva de las Ruinas de Aurora, los Eclipsites estarán contenidos en la noche eterna y se les impedirá llegar al resto del continente.",
  ui_story_1014_10140801_130_dialog_content = "Por otro lado, si perdemos este paso angosto, un área mucho más grande estaría directamente expuesta a la amenaza del eclipse.",
  ui_story_1014_10140801_131_dialog_content = "Esta batalla fue un punto de inflexión crucial en la cruzada auroriana para hacerse con el control de Astra.",
  ui_story_1014_10140801_132_dialog_content = "¿Quieres continuar, o debería hacerlo yo?",
  ui_story_1014_10140801_133_dialog_content = "Tu sigue. Solo estaba agregando un poco de contexto adicional.",
  ui_story_1014_10140801_134_dialog_content = "La batalla por las Ruinas de Aurora fue muy difícil.",
  ui_story_1014_10140801_135_dialog_content = "Está demasiado cerca de la noche eterna aquí, con fenómenos de aurora impredecibles, y los eclipses tienen una fuerza sin precedentes.",
  ui_story_1014_10140801_136_dialog_content = "El conflicto se prolongó. No se pudo establecer completamente una línea defensiva, y los aurorianos fallecidos yacían en montones que solo parecían crecer.",
  ui_story_1014_10140801_137_dialog_content = "Amaneció un día sobre esta guerra interminable, un día del que no hay constancia escrita.",
  ui_story_1014_10140801_138_dialog_content = "El destino finalmente sonrió a los aurorianos.",
  ui_story_1014_10140801_139_dialog_content = "Sobre el campo de batalla, una nube oscura como nunca antes se había visto tapaba el mismísimo sol.",
  ui_story_1014_10140801_140_dialog_content = "Era una flota de <color=#FFB400>colosos</color>.",
  ui_story_1014_10140801_141_dialog_content = "¡¿Una flota?!",
  ui_story_1014_10140801_142_dialog_content = "(¡He visto eso! ¡He visto algo así!)",
  ui_story_1014_10140801_143_dialog_content = "(¿Fue LA flota?)",
  ui_story_1014_10140801_144_dialog_content = "La flota siguió navegando, en la distancia. Pero uno de ellos aterrizó.",
  ui_story_1014_10140801_145_dialog_content = "De alguna manera se comunicó con los aurorianos y decidió quedarse atrás y luchar junto a ellos.",
  ui_story_1014_10140801_146_dialog_content = "Espera, ¿estás seguro de que el Coloso se comunicó con los aurorianos?",
  ui_story_1014_10140801_147_dialog_content = "¿No es el Caelestite a bordo?",
  ui_story_1014_10140801_148_dialog_content = "No. En realidad, no había Caelestita a bordo de ese Coloso.",
  ui_story_1014_10140801_149_dialog_content = "era el coloso <color=#FFB400>propia conciencia</color> que tomó la decisión.",
  ui_story_1014_10140801_150_dialog_content = "El propio Coloso...",
  ui_story_1014_10140801_151_dialog_content = "Un amigo mío nerd me informó una vez que en la historia de Aurorian, la palabra Colossus es anterior a la palabra Caelestite.",
  ui_story_1014_10140801_152_dialog_content = "Eso en realidad podría apoyar la leyenda.",
  ui_story_1014_10140801_153_dialog_content = "Entonces, ¿qué pasó después? ¿Se quedó el Coloso en las Ruinas de Aurora?",
  ui_story_1014_10140801_154_dialog_content = "Sí. Era como un soldado especial, de alguna manera comprometido con esta guerra prolongada.",
  ui_story_1014_10140801_155_dialog_content = "No fue hasta muchos años después que finalmente se ganó la guerra y los aurorianos lograron establecer su propia fortaleza en las Ruinas de Aurora.",
  ui_story_1014_10140801_156_dialog_content = "Debido a la creciente inactividad de los años de daño de la batalla, el Coloso finalmente se convirtió en una estatua silenciosa.",
  ui_story_1014_10140801_157_dialog_content = "Los Aurorianos aquí veneran al Coloso, tratándolo como un tótem religioso para exaltar.",
  ui_story_1014_10140801_158_dialog_content = "Es increíble pensar que se saltó Caelestites para formar un vínculo con Aurorians.",
  ui_story_1014_10140801_159_dialog_content = "¿Está bien conservado?",
  ui_story_1014_10140801_160_dialog_content = "Déjame terminar la historia primero.",
  ui_story_1014_10140801_161_dialog_content = "Luego llegamos a tiempos más modernos. La emergente Federación Illumina envió tropas a las Ruinas de Aurora.",
  ui_story_1014_10140801_162_dialog_content = "Sus investigadores comenzaron a estudiar el Coloso en un intento de reparar el gigante dañado.",
  ui_story_1014_10140801_163_dialog_content = "Fueron... semi-exitosos, digámoslo así.",
  ui_story_1014_10140801_164_dialog_content = "Se solucionó temporalmente, solo por un mal funcionamiento desconocido que hizo que el Coloso se volviera loco.",
  ui_story_1014_10140801_165_dialog_content = "El incontrolable Coloso, por fin, se estrelló contra la inescrutable Zona Oscura.",
  ui_story_1014_10140801_166_dialog_content = "¿Se estrelló en la Zona Oscura? ¡Que pérdida!",
  ui_story_1014_10140801_167_dialog_content = "Sí, gran parte de la generación anterior todavía le guarda rencor a Illumina por eso.",
  ui_story_1014_10140801_168_dialog_content = "Y así sus soldados reciben la frialdad.",
  ui_story_1014_10140801_169_dialog_content = "¡Ya veo! Me preguntaba por qué los ancianos del mercado no me hablaban.",
  ui_story_1014_10140801_170_dialog_content = "Pensé que los ofendí de alguna manera...",
  ui_story_1014_10140801_171_dialog_content = "Así es como funcionan las cosas en Crepúsculo. Muchos eventos no tienen perpetradores claros, por lo que los conflictos nunca se resuelven.",
  ui_story_1014_10140801_172_dialog_content = "También es difícil determinar lo correcto o lo incorrecto cuando se trata de los esfuerzos de Illumina.",
  ui_story_1014_10140801_173_dialog_content = "Causar que la ciudad de Twilight perdiera el antiguo Coloso fue ciertamente su culpa.",
  ui_story_1014_10140801_174_dialog_content = "Pero si su investigación termina ayudando a arreglar Colossus de PlayerName, bueno, entonces no todo fue malo.",
  ui_story_1014_10140801_175_dialog_content = "Hablando de eso, el investigador de Illumina me contactó.",
  ui_story_1014_10140801_176_dialog_content = "Está muy interesado en reparar el Coloso y le gustaría empezar lo antes posible.",
  ui_story_1014_10140801_177_dialog_content = "¿En serio? Pero es muy tarde. Debería estar preparándose para ir a la cama.",
  ui_story_1014_10140801_178_dialog_content = "No te preocupes por eso, acaba de despertar.",
  ui_story_1014_10140801_179_dialog_content = "¿Acabo de despertarme?",
  ui_story_1014_10140801_180_dialog_content = "Ya los conoces, científicos... Un grupo excéntrico.",
  ui_story_1014_10140801_181_dialog_content = "Si cierto.",
  ui_story_1014_10140801_182_dialog_content = "En ese caso, vayamos al centro de investigación después de comer.",
  ui_story_1014_10140801_183_dialog_content = "No me gusta posponer las cosas cuando se trata de asuntos relacionados con Soroz.",
  ui_story_1014_10140801_184_dialog_content = "<color=#e8d9bb>Chirrido-</color>",
  ui_story_1014_10140801_185_dialog_content = "Se fueron.",
  ui_story_1014_10140801_186_dialog_content = "Interesante, estos forasteros.",
  ui_story_1014_10140801_187_dialog_content = "Sí, intrigante.",
  ui_story_1014_10140801_188_dialog_content = "Los oficiales de Illumina y la Princesa de Lumopolis... No imaginé que alguna vez se llevarían bien.",
  ui_story_1014_10140801_189_dialog_content = "El Caelestite es legendario por una razón.",
  ui_story_1014_10140801_190_dialog_content = "Oh sí, ¿no me vas a agradecer?",
  ui_story_1014_10140801_191_dialog_content = "¿Debo, Su Santidad? Habría asumido que serías lo suficientemente benévolo como para perdonarme ante los ciudadanos.",
  ui_story_1014_10140801_192_dialog_content = "Pensé que agradecerme te haría sentir mejor contigo mismo.",
  ui_story_1014_10140801_193_dialog_content = "En realidad, deberías estar agradeciéndome.",
  ui_story_1014_10140801_194_dialog_content = "¿Porqué crees?",
  ui_story_1014_10140801_195_dialog_content = "Porque fue un error de tu parte cargar de cabeza en la batalla, tratando de salvar a la gente de manera tan imprudente.",
  ui_story_1014_10140801_196_dialog_content = "Puedes ser el héroe cada vez solo porque alguien te cubre las espaldas.",
  ui_story_1014_10140801_197_dialog_content = "Tienes razón. Debo agradecer a alguien.",
  ui_story_1014_10140801_198_dialog_content = "Pero en ese caso, todavía tienes que agradecerme.",
  ui_story_1014_10140801_199_dialog_content = "¿Por qué dices eso?",
  ui_story_1014_10140801_200_dialog_content = "Porque te di menos motivos para arrepentirte.",
  ui_story_1014_10140801_201_dialog_content = "¡Dios mío, un coloso de una sola pieza!",
  ui_story_1014_10140801_202_dialog_content = "¡Esto es increíble! ¿Te das cuenta de lo valioso que es esto para la investigación?",
  ui_story_1014_10140801_203_dialog_content = "Perdóname, pero no te entregamos a Soroz para que lo estudies.",
  ui_story_1014_10140801_204_dialog_content = "vinimos a—",
  ui_story_1014_10140801_205_dialog_content = "Sí, lo sé, el comercio, ¿verdad?",
  ui_story_1014_10140801_206_dialog_content = "¿Trajiste el Combat Cyborg?",
  ui_story_1014_10140801_207_dialog_content = "Sí, aquí.",
  ui_story_1014_10140801_208_dialog_content = "Ese es. Solo déjalo ahí.",
  ui_story_1014_10140801_209_dialog_content = "Déjame la conciencia del Coloso a mí.",
  ui_story_1014_10140801_210_dialog_content = "Está bien que registre algunos datos mientras estoy en eso, ¿verdad? Eso es justo.",
  ui_story_1014_10140801_211_dialog_content = "Claro, mientras puedas hacer que Soroz recupere la conciencia.",
  ui_story_1014_10140801_212_dialog_content = "Muy bien, ¡déjame empezar ahora!",
  ui_story_1014_10140801_213_dialog_content = "¿Puedo quedarme y mirar?",
  ui_story_1014_10140801_214_dialog_content = "J-Solo en caso de que haya un accidente o algo así.",
  ui_story_1014_10140801_215_dialog_content = "No hay problema, si no te aburre.",
  ui_story_1014_10140801_216_dialog_content = "Es muy tarde, PlayerName. ¿Estás seguro de que quieres quedarte aquí?",
  ui_story_1014_10140801_217_dialog_content = "Sí. De todos modos, no puedo dormir mientras reparan a Soroz, así que también podría hacerlo.",
  ui_story_1014_10140801_218_dialog_content = "Deberían entregarse.",
  ui_story_1014_10140801_219_dialog_content = "¿Vas a estar bien por ti mismo?",
  ui_story_1014_10140801_220_dialog_content = "Está bien. Este es territorio Illumina, después de todo. No debería pasar nada.",
  ui_story_1014_10140801_221_dialog_content = "De acuerdo entonces. No te excedas.",
  ui_story_1014_10140801_222_dialog_content = "Entiendo.",
  ui_story_1014_10140801_223_dialog_content = "<color=#e8d9bb>¡Clang, clang!</color>",
  ui_story_1014_10140801_224_dialog_content = "Oye, despierta, Caelestite.",
  ui_story_1014_10140801_225_dialog_content = "Qué...",
  ui_story_1014_10140801_226_dialog_content = "Levántate y brilla. No más dormir.",
  ui_story_1014_10140801_227_dialog_content = "Oh...",
  ui_story_1014_10140801_228_dialog_content = "¿Por qué te estás dando la vuelta?",
  ui_story_1014_10140801_229_dialog_content = "Levántate y compruébalo por ti mismo...",
  ui_story_1014_10140801_230_dialog_content = "Ha sido un largo tiempo, PlayerName.",
  ui_story_1014_10140801_231_dialog_content = "<size=50>!!!</size>",
  ui_story_1014_10140801_232_dialog_content = "Soroz! ¿Estás... estás de vuelta?",
  ui_story_1014_10140801_233_dialog_content = "Continuar. He terminado con las reparaciones.",
  ui_story_1014_10140801_234_dialog_content = "Pero aún no tenemos suficientes datos para mantener su conocimiento.",
  ui_story_1014_10140801_235_dialog_content = "Será mejor que aproveches esta oportunidad.",
  ui_story_1014_10140801_236_dialog_content = "¿Esto no se puede mantener?",
  ui_story_1014_10140801_237_dialog_content = "Gracias, PlayerName, por seguir tratando de encontrar una manera de restaurarme.",
  ui_story_1014_10140801_238_dialog_content = "¡Qué bueno volver a escuchar tu voz, Soroz!",
  ui_story_1014_10140801_239_dialog_content = "Han pasado muchas cosas. Quiero empezar con—",
  ui_story_1014_10140801_240_dialog_content = "Disculpas, pero esta vez tampoco podré quedarme mucho tiempo.",
  ui_story_1014_10140801_241_dialog_content = "...",
  ui_story_1014_10140801_242_dialog_content = "Su enfoque es correcto, pero carece de datos de respaldo.",
  ui_story_1014_10140801_243_dialog_content = "Sí, no tuve la oportunidad de terminar mi investigación antes del Coloso... Suspiro.",
  ui_story_1014_10140801_244_dialog_content = "¿Q-Qué debemos hacer, entonces?",
  ui_story_1014_10140801_245_dialog_content = "Localicé ese otro Coloso.",
  ui_story_1014_10140801_246_dialog_content = "¡¿Qué?!",
  ui_story_1014_10140801_247_dialog_content = "¿Solo tenemos que encontrarlo entonces? ¿Dónde está?",
  ui_story_1014_10140801_248_dialog_content = "<anim type=Shake>Mi tiempo casi ha terminado...</anim>",
  ui_story_1014_10140801_249_dialog_content = "<anim type=Shake>Te dejo las coordenadas en la terminal...</anim>",
  ui_story_1014_10140801_250_dialog_content = "¿Coordenadas? ¿Para el Coloso?",
  ui_story_1014_10140801_251_dialog_content = "<anim type=Shake>PlayerName, Creo en ti.</anim>",
  ui_story_1014_10140801_252_dialog_content = "<anim type=Shake>Por favor... cree en ti también.</anim>",
  ui_story_1014_10140901_1_dialog_content = "Aquí está el mapa de batalla más completo de las Ruinas de Aurora.",
  ui_story_1014_10140901_2_dialog_content = "Obtuve esto a través de un acceso especial, así que no se lo muestres a nadie más.",
  ui_story_1014_10140901_3_dialog_content = "Las coordenadas que estás buscando deberían estar por aquí.",
  ui_story_1014_10140901_4_dialog_content = "¿Eso está en la Zona Oscura?",
  ui_story_1014_10140901_5_dialog_content = "Sí, y es una Entrañas en eso.",
  ui_story_1014_10140901_6_dialog_content = "Illumina mantuvo su exploración al nivel de la superficie y no más profundo.",
  ui_story_1014_10140901_7_dialog_content = "Entonces, es esencialmente un territorio desconocido.",
  ui_story_1014_10140901_8_dialog_content = "¿Podemos ir ahí?",
  ui_story_1014_10140901_9_dialog_content = "Sí, pero es muy peligroso, así que será mejor que lo medites.",
  ui_story_1014_10140901_10_dialog_content = "Comprendido. No hay nada que reflexionar. Es para Soroz, así que debo irme.",
  ui_story_1014_10140901_11_dialog_content = "No estaba tratando de detenerte. Sólo quería que lo pensaras bien.",
  ui_story_1014_10140901_12_dialog_content = "Digamos que encuentras el viejo Coloso, ¿entonces qué? ¿Cómo lo llevas de vuelta?",
  ui_story_1014_10140901_13_dialog_content = "Bueno, eh...",
  ui_story_1014_10140901_14_dialog_content = "¡Está bien, te ayudaré! ¡Hago que mi superior se apodere de un vehículo de transporte!",
  ui_story_1014_10140901_15_dialog_content = "Practiqué conducir antes. ¡Puedo llevar el Coloso de regreso!",
  ui_story_1014_10140901_16_dialog_content = "¿En serio? ¡Eso es maravilloso!",
  ui_story_1014_10140901_17_dialog_content = "Ustedes dos...",
  ui_story_1014_10140901_18_dialog_content = "Si ambos pudieran combinar su única célula cerebral en un cerebro funcional, lo llamaría un milagro.",
  ui_story_1014_10140901_19_dialog_content = "Primero ignoremos si el Colossus puede caber en la parte trasera de un vehículo.",
  ui_story_1014_10140901_20_dialog_content = "¿Las ciudades subterráneas mágicamente tienen caminos pavimentados para que conduzcas? ¿Cómo vas a escapar de los enjambres de eclipses?",
  ui_story_1014_10140901_21_dialog_content = "Eh... sobre eso...",
  ui_story_1014_10140901_22_dialog_content = "¿Qué piezas específicas necesitas para reparar a Soroz, Investigador?",
  ui_story_1014_10140901_23_dialog_content = "Bueno, preferiría un Coloso completo, para ser honesto.",
  ui_story_1014_10140901_24_dialog_content = "No sabemos todo sobre Colossi, por lo que cualquier cosa que falte podría ser un problema.",
  ui_story_1014_10140901_25_dialog_content = "Pero si tuviera que elegir uno...",
  ui_story_1014_10140901_26_dialog_content = "sería el <color=#FFB400>Módulo de control primario</color>.",
  ui_story_1014_10140901_27_dialog_content = "Tiene el mayor valor para la investigación y fue el tema del estudio anterior.",
  ui_story_1014_10140901_28_dialog_content = "Bueno. Reevaluemos nuestro objetivo. No todo el Colossus, sino el módulo de control principal.",
  ui_story_1014_10140901_29_dialog_content = "Esta operación excede los límites de lo que negociaron en Gannon.",
  ui_story_1014_10140901_30_dialog_content = "Por lo tanto, no recibirá ayuda adicional de Illumina.",
  ui_story_1014_10140901_31_dialog_content = "Si lo se. Este es un asunto personal.",
  ui_story_1014_10140901_32_dialog_content = "Sin embargo, aún puede recibir ayuda de ciertas personas.",
  ui_story_1014_10140901_33_dialog_content = "¿Ah?",
  ui_story_1014_10140901_34_dialog_content = "¿Estás insinuando que puedo ayudar, Yingel?",
  ui_story_1014_10140901_35_dialog_content = "Sí. Su horario está abierto. Eres libre de hacer lo que te gusta.",
  ui_story_1014_10140901_36_dialog_content = "¡Oh sí!",
  ui_story_1014_10140901_37_dialog_content = "Sean...",
  ui_story_1014_10140901_38_dialog_content = "Del mismo modo, Axelia y yo tampoco tenemos nada en nuestros platos.",
  ui_story_1014_10140901_39_dialog_content = "¿Ustedes también quieren ayudarme?",
  ui_story_1014_10140901_40_dialog_content = "Las ciudades subterráneas en la Zona Oscura son letales. Prefiero que Sean no lleve al único Caelestita del mundo a su muerte.",
  ui_story_1014_10140901_41_dialog_content = "Voy a comprobar el estado de Axelia. Nos iremos cuando estemos listos.",
  ui_story_1014_10140901_42_dialog_content = "Fresco, PlayerName! ¡Déjame ir a buscar un camión a mi superior!",
  ui_story_1014_10140901_43_dialog_content = "Estoy sin palabras...",
  ui_story_1014_10140901_44_dialog_content = "Muchísimas gracias.",
  ui_story_1014_10140901_45_dialog_content = "<color=#e8d9bb>¡Woosh!</color>",
  ui_story_1014_10140901_46_dialog_content = "Dulces para ti, Axelia.",
  ui_story_1014_10140901_47_dialog_content = "Está bien...",
  ui_story_1014_10140901_48_dialog_content = "¿Cómo va tu tarea, Yingel?",
  ui_story_1014_10140901_49_dialog_content = "Ya se termino. Llegamos aquí sanos y salvos, ¿no?",
  ui_story_1014_10140901_50_dialog_content = "Me refiero al otro.",
  ui_story_1014_10140901_51_dialog_content = "¿El otro?",
  ui_story_1014_10140901_52_dialog_content = "Si completaras tu misión, no seguirías ayudando a PlayerName.",
  ui_story_1014_10140901_53_dialog_content = "Tienes alguna otra agenda.",
  ui_story_1014_10140901_54_dialog_content = "...",
  ui_story_1014_10140901_55_dialog_content = "Nunca puedo decir lo que pasa por tu cabeza, a veces. No pareces prestar atención, pero lo sabes todo.",
  ui_story_1014_10140901_56_dialog_content = "Te conozco, Yingel.",
  ui_story_1014_10140901_57_dialog_content = "Si es una tarea que no debería saber, no tienes que decir nada.",
  ui_story_1014_10140901_58_dialog_content = "Estoy buscando <color=#FFB400>Abandonado</color>.",
  ui_story_1014_10140901_59_dialog_content = "¿Ese científico traidor?",
  ui_story_1014_10140901_60_dialog_content = "Sí.",
  ui_story_1014_10140901_61_dialog_content = "¿Está en Crepúsculo?",
  ui_story_1014_10140901_62_dialog_content = "Nadie sabe dónde está.",
  ui_story_1014_10140901_63_dialog_content = "Así que lo mejor que puedo hacer es atraerla.",
  ui_story_1014_10140901_64_dialog_content = "El Caelestite es el cebo?",
  ui_story_1014_10140901_65_dialog_content = "Mm. Nadie podría ser mejor.",
  ui_story_1014_10140901_66_dialog_content = "Supongo que no tiene idea.",
  ui_story_1014_10140901_67_dialog_content = "Se enfadará, lo sabes.",
  ui_story_1014_10140901_68_dialog_content = "...",
  ui_story_1014_10140901_69_dialog_content = "¿Te importaría tomar una siesta después de que termines con los dulces, Axelia?",
  ui_story_1014_10140901_70_dialog_content = "Quiero que duermas hasta que te despierte.",
  ui_story_1014_10140901_71_dialog_content = "Te escucharé.",
  ui_story_1014_10140901_72_dialog_content = "¡Dije que me voy!",
  ui_story_1014_10140901_73_dialog_content = "Y lo entiendo, Su Alteza.",
  ui_story_1014_10140901_74_dialog_content = "Entonces, ¿qué haces interponiéndote en mi camino?",
  ui_story_1014_10140901_75_dialog_content = "Por favor, comprenda que solo estoy siguiendo las órdenes del Señor de la Ciudad.",
  ui_story_1014_10140901_76_dialog_content = "¿El señor de la ciudad? ¿Por qué escucho este nombre incluso en Crepúsculo?",
  ui_story_1014_10140901_77_dialog_content = "Nunca le importa lo que sucede en las fronteras.",
  ui_story_1014_10140901_78_dialog_content = "Porque está aquí, Su Alteza. Es una situación difícil para nosotros también, por favor comprenda.",
  ui_story_1014_10140901_79_dialog_content = "Simplemente estamos de servicio de patrulla, la Fortaleza Lumo no tiene derecho a interferir.",
  ui_story_1014_10140901_80_dialog_content = "Muestre los documentos correspondientes si se trata de una orden del alcalde de la ciudad.",
  ui_story_1014_10140901_81_dialog_content = "Oh...",
  ui_story_1014_10140901_82_dialog_content = "¿Carleen? ¿Beretta? ¿Que está pasando aqui?",
  ui_story_1014_10140901_83_dialog_content = "¿Por qué te detienen los guardias de Lumopolis?",
  ui_story_1014_10140901_84_dialog_content = "Justo a tiempo, PlayerName, Vice.",
  ui_story_1014_10140901_85_dialog_content = "Beretta y yo queremos ir a Lumo Stronghold por provisiones antes de partir.",
  ui_story_1014_10140901_86_dialog_content = "Pero se niegan a dejarnos pasar.",
  ui_story_1014_10140901_87_dialog_content = "No lo detendremos, Su Alteza. Es que a donde vas es muy peligroso. Debemos enviar escoltas con usted para garantizar su seguridad.",
  ui_story_1014_10140901_88_dialog_content = "Nunca necesité la protección de nadie en el campo de batalla.",
  ui_story_1014_10140901_89_dialog_content = "Hola PlayerName, te he estado buscando por todas partes.",
  ui_story_1014_10140901_90_dialog_content = "Escuché que irás a Entrañas en la Zona Oscura. ¿Puedo acompañarlo?",
  ui_story_1014_10140901_91_dialog_content = "¿Quieres ir también?",
  ui_story_1014_10140901_92_dialog_content = "¿Eres el refuerzo que envía Lumo Stronghold?",
  ui_story_1014_10140901_93_dialog_content = "No no. He querido ir a Entrañas desde hace mucho tiempo.",
  ui_story_1014_10140901_94_dialog_content = "Las actividades recientes de Eclipsite alrededor de Crepúsculo están ligadas de alguna manera a ese lugar.",
  ui_story_1014_10140901_95_dialog_content = "Quiero comprobarlo, pero no es conveniente llevar a los otros caballeros, y me superarían en número solo.",
  ui_story_1014_10140901_96_dialog_content = "Ya que te vas, es la oportunidad perfecta para mí.",
  ui_story_1014_10140901_97_dialog_content = "Comprendo.",
  ui_story_1014_10140901_98_dialog_content = "En cuanto al refuerzo de Lumo Stronghold, esa es otra persona.",
  ui_story_1014_10140901_99_dialog_content = "Y aquí está.",
  ui_story_1014_10140901_100_dialog_content = "No he hecho esperar a todos, espero.",
  ui_story_1014_10140901_101_dialog_content = "El pedido llegó con bastante urgencia, así que solo hice los preparativos mínimos.",
  ui_story_1014_10140901_102_dialog_content = "finalmente estás aquí, <color=#FFB400>Padre José</color>.",
  ui_story_1014_10140901_103_dialog_content = "Lady Carleen, este es el Padre Joseph de la Iglesia y su escolta. Él te acompañará en tu viaje.",
  ui_story_1014_10140901_104_dialog_content = "Su reputación le precede, Su Alteza.",
  ui_story_1014_10140901_105_dialog_content = "Ya que él está aquí, no te retendremos aquí por más tiempo.",
  ui_story_1014_10140901_106_dialog_content = "Le deseo lo mejor, Su Alteza.",
  ui_story_1014_10140901_107_dialog_content = "¿Solo él?",
  ui_story_1014_10140901_108_dialog_content = "Sí. Mis disculpas. No es negligencia por parte de la Iglesia, simplemente estamos muy cortos de personal.",
  ui_story_1014_10140901_109_dialog_content = "No lo escuches. Tienes suerte de que la Iglesia lo haya enviado.",
  ui_story_1014_10140901_110_dialog_content = "Es agua profunda donde vamos. Necesitamos calidad, no cantidad.",
  ui_story_1014_10140901_111_dialog_content = "Veo que tus oraciones han sido respondidas por fin, Leo.",
  ui_story_1014_10140901_112_dialog_content = "Sí, gracias a PlayerName. No todos los días se arma un equipo así.",
  ui_story_1014_10140901_113_dialog_content = "Y eso no es todo. Esa chica civil viene por ti otra vez.",
  ui_story_1014_10140901_114_dialog_content = "chica civil...",
  ui_story_1014_10140901_115_dialog_content = "Me gusta mucho más que Su Santidad.",
  ui_story_1014_10140901_116_dialog_content = "¿Joselyne? ¿Qué estás haciendo aquí?",
  ui_story_1014_10140901_117_dialog_content = "Puedo unirme a ustedes, PlayerName?",
  ui_story_1014_10140901_118_dialog_content = "¿Qué? ¡Ah, claro, por supuesto!",
  ui_story_1014_10140901_119_dialog_content = "¿Pero por qué?",
  ui_story_1014_10140901_120_dialog_content = "No podía soportar ver a los visitantes desde lejos aventurarse directamente en la oscuridad.",
  ui_story_1014_10140901_121_dialog_content = "Al menos puedo iluminar una esquina para ti.",
  ui_story_1014_10140901_122_dialog_content = "<color=#e8d9bb>clank—clac—</color>",
  ui_story_1014_10140901_123_dialog_content = "<color=#e8d9bb>Sonido metálico seco-</color>",
  ui_story_1014_10140901_124_dialog_content = "Hmm, ¿por qué se detuvo de nuevo?",
  ui_story_1014_10140901_125_dialog_content = "¿Se atascó algo?",
  ui_story_1014_10140901_126_dialog_content = "Suficiente, Sean, deja de jugar con el camión.",
  ui_story_1014_10140901_127_dialog_content = "Te lo dije, no va a funcionar. Aquí está lo suficientemente lejos.",
  ui_story_1014_10140901_128_dialog_content = "Todos fuera del vehículo. Estamos fuera de Entrañas.",
  ui_story_1014_10140901_129_dialog_content = "Hora de levantarse, Axelia.",
  ui_story_1014_10140901_130_dialog_content = "Oh, está bien, tuve una buena siesta.",
  ui_story_1014_10140901_131_dialog_content = "Así que esto es todo...",
  ui_story_1014_10140901_132_dialog_content = "Como era de esperar, el Darkflow es muy intenso.",
  ui_story_1014_10140901_133_dialog_content = "La Zona Oscura está justo más adelante.",
  ui_story_1014_10140901_134_dialog_content = "Eso me pone nervioso. Tengo una impresión terrible de la Zona Oscura.",
  ui_story_1014_10140901_135_dialog_content = "¿Alguien de aquí ha estado alguna vez en Entrañas?",
  ui_story_1014_10140901_136_dialog_content = "Algunos ancianos lo han hecho, pero advirtieron a otros que nunca pusieran un pie en la Zona Oscura.",
  ui_story_1014_10140901_137_dialog_content = "Aunque no creo que haya nada que temer. Quiero decir, esos viejos no eran exactamente a prueba de balas.",
  ui_story_1014_10140901_138_dialog_content = "Entonces, si pudieron salir de allí con vida, no deberíamos tener ningún problema.",
  ui_story_1014_10140901_139_dialog_content = "Je, pensé que serías más perspicaz que eso.",
  ui_story_1014_10140901_140_dialog_content = "Nunca antes había estado en la Zona Oscura, ¿qué información podría ofrecer?",
  ui_story_1014_10140901_141_dialog_content = "Confiemos en Leo, siempre tiene razón en su juicio.",
  ui_story_1014_10140901_142_dialog_content = "Deja de halagarme. De hecho, preferiría escuchar sus pensamientos sobre el tema.",
  ui_story_1014_10140901_143_dialog_content = "Bueno, mirando alrededor, no creo que sea tan aterrador como pensaba.",
  ui_story_1014_10140901_144_dialog_content = "Incluso los eclipses parecen más formidables.",
  ui_story_1014_10140901_145_dialog_content = "Muy bien, si estamos todos listos, vayamos a Entrañas.",
  ui_story_1014_10140901_146_dialog_content = "Es hora de encontrar ese Coloso.",
  ui_story_1014_10140901_147_dialog_content = "Oh, todo este ruido. Que molesto.",
  ui_story_1014_10140901_148_dialog_content = "Ha pasado algún tiempo desde que ha sido tan cascarrabias.",
  ui_story_1014_10140901_149_dialog_content = "¿Qué, oh qué, podría ser esto? Más intenso que gotas de lluvia, más irritante que llamadas de insectos.",
  ui_story_1014_10140901_150_dialog_content = "Ah, sí. Debe ser el sonido de la gente.",
  ui_story_1014_10140901_151_dialog_content = "Los más despreciables, sonidos de personas.",
  ui_story_1014_10141101_1_dialog_content = "¿Son estas las ruinas con el Coloso?",
  ui_story_1014_10141101_2_dialog_content = "Eso es lo que dice en el mapa.",
  ui_story_1014_10141101_3_dialog_content = "Tenga cuidado, hay muchos eclipses aquí.",
  ui_story_1014_10141101_4_dialog_content = "...",
  ui_story_1014_10141101_5_dialog_content = "Eso es raro. ¿Por qué hay tantos eclipses aquí?",
  ui_story_1014_10141101_6_dialog_content = "Según su patrón de comportamiento, no deberían congregarse aquí.",
  ui_story_1014_10141101_7_dialog_content = "Pero este entorno es diferente y probablemente tiene características de las que aún no somos conscientes.",
  ui_story_1014_10141101_8_dialog_content = "No estoy seguro de qué atrae a los eclipses aquí, a menos que algo los esté controlando.",
  ui_story_1014_10141101_9_dialog_content = "Esto es muy inusual, así que tenga cuidado.",
  ui_story_1014_10141101_10_dialog_content = "Los eclipses no son algo que temer. Su derrota es el único resultado.",
  ui_story_1014_10141101_11_dialog_content = "¿Eres realmente tan poderoso?",
  ui_story_1014_10141101_12_dialog_content = "No la subestimes. ¡Ella es la más fuerte entre nosotros! Incluso yo no puedo vencerla a veces.",
  ui_story_1014_10141101_13_dialog_content = "Según mis observaciones de los mástiles de Sean y Axelia, perdió nueve de cada diez veces y solo empató con ella una vez.",
  ui_story_1014_10141101_14_dialog_content = "No necesito esforzarme mucho cuando lucho contra Sean.",
  ui_story_1014_10141101_15_dialog_content = "¡Oi, no seas tan directo al respecto!",
  ui_story_1014_10141101_16_dialog_content = "Jaja, seguro que te llevas bien.",
  ui_story_1014_10141101_17_dialog_content = "Pero no es seguro aquí, así que no bromeemos.",
  ui_story_1014_10141101_18_dialog_content = "Necesitamos encontrar el módulo que PlayerName necesita tan pronto como podamos y salir de aquí.",
  ui_story_1014_10141101_19_dialog_content = "Veo un montón de eclipses en el camino, ¿qué tal esto?",
  ui_story_1014_10141101_20_dialog_content = "¡Axelia, a ver quién mata más!",
  ui_story_1014_10141101_21_dialog_content = "Yingel puede ser el árbitro.",
  ui_story_1014_10141101_22_dialog_content = "Hay que ir de nuevo.",
  ui_story_1014_10141101_23_dialog_content = "Multa. Pero no te quejes si pierdes.",
  ui_story_1014_10141101_24_dialog_content = "<color=#e8d9bb>En algún lugar fuera de las Ruinas de Aurora</color>",
  ui_story_1014_10141101_25_dialog_content = "(Eclipsiano) Señor <color=#FFB400>asmodeo</color>, los aurorianos y los caelestitas han entrado en las ruinas.",
  ui_story_1014_10141101_26_dialog_content = "(Eclipsian) Han comprometido a nuestros parientes dentro.",
  ui_story_1014_10141101_27_dialog_content = "(Eclipsian) Déjalos marchar hacia adelante.",
  ui_story_1014_10141101_28_dialog_content = "(Eclipsian) Quizás su deseo me lleve a lo que he estado buscando.",
  ui_story_1014_10141102_1_dialog_content = "¡El último eclipse es mío!",
  ui_story_1014_10141102_2_dialog_content = "Gaaaaah!!",
  ui_story_1014_10141102_3_dialog_content = "Entonces, ¿quién ganó, Yingel?",
  ui_story_1014_10141102_4_dialog_content = "Bien, anunciaré los resultados.",
  ui_story_1014_10141102_5_dialog_content = "Sean mató 20 eclipses.",
  ui_story_1014_10141102_6_dialog_content = "Oh, todavía estoy un poco por debajo de mi mejor marca de todos los tiempos.",
  ui_story_1014_10141102_7_dialog_content = "Axelia mató—",
  ui_story_1014_10141102_8_dialog_content = "32!",
  ui_story_1014_10141102_9_dialog_content = "¡¿En serio?!",
  ui_story_1014_10141102_10_dialog_content = "¡Soy imposible!",
  ui_story_1014_10141102_11_dialog_content = "Pasaste demasiado tiempo persiguiendo a los rezagados que huían, Sean.",
  ui_story_1014_10141102_12_dialog_content = "Axelia centró su energía en las turbas lideradas por los Eclipsites más grandes.",
  ui_story_1014_10141102_13_dialog_content = "Bueno, no hay nada que pueda hacer al respecto...",
  ui_story_1014_10141102_14_dialog_content = "Donde está mi habilidad en este momento, primero tengo que reducir los Eclipsites más débiles y avanzar hasta los más grandes.",
  ui_story_1014_10141102_15_dialog_content = "Cierto, y esa es la razón por la que ganó Axelia.",
  ui_story_1014_10141102_16_dialog_content = "¡Ratas, Axelia volvió a ganar!",
  ui_story_1014_10141102_17_dialog_content = "Sean perdió de nuevo.",
  ui_story_1014_10141102_18_dialog_content = "Pero Sean no se dará por vencido. A Sean le gusta asumir desafíos y no se dará por vencido incluso si falla.",
  ui_story_1014_10141102_19_dialog_content = "Hasta que gana.",
  ui_story_1014_10141102_20_dialog_content = "Sabía que tú me conocías mejor, Axelia.",
  ui_story_1014_10141102_21_dialog_content = "Sin embargo, no es posible que Sean me derrote.",
  ui_story_1014_10141102_22_dialog_content = "No estés tan seguro. ¡Seguiré mejorando!",
  ui_story_1014_10141102_23_dialog_content = "¿Qué opinas de su actuación, Joseph?",
  ui_story_1014_10141102_24_dialog_content = "¿Estás pidiendo mi opinión?",
  ui_story_1014_10141102_25_dialog_content = "Por supuesto. Los has observado en silencio todo este tiempo, así que deberías tener algo.",
  ui_story_1014_10141102_26_dialog_content = "(¿Joseph apenas habló porque nos estaba mirando?)",
  ui_story_1014_10141102_27_dialog_content = "Creo que todos en Illumina son notables por derecho propio.",
  ui_story_1014_10141102_28_dialog_content = "Axelia es muy competente con las máquinas. Yingel es experta en la observación y el apoyo. Sean es bueno adaptando la experiencia a las habilidades.",
  ui_story_1014_10141102_29_dialog_content = "Ustedes tres juntos hacen un equipo perfecto.",
  ui_story_1014_10141102_30_dialog_content = "¡...!",
  ui_story_1014_10141102_31_dialog_content = "Coincido con tu apreciación.",
  ui_story_1014_10141102_32_dialog_content = "Gracias por el reconocimiento.",
  ui_story_1014_10141102_33_dialog_content = "(¡José tiene una percepción muy aguda!)",
  ui_story_1014_10141102_34_dialog_content = "Axelia es realmente impresionante.",
  ui_story_1014_10141102_35_dialog_content = "¡Probablemente tomaría el primer lugar en las clasificaciones individuales si participara en los ejercicios militares conjuntos!",
  ui_story_1014_10141102_36_dialog_content = "¿Conoces los ejercicios militares conjuntos?",
  ui_story_1014_10141102_37_dialog_content = "Sí, Reinhardt me habló de ellos antes.",
  ui_story_1014_10141102_38_dialog_content = "Incluso dijo que tenía muchas ganas de entrenar con el campeón.",
  ui_story_1014_10141102_39_dialog_content = "Suena como algo que ella haría.",
  ui_story_1014_10141102_40_dialog_content = "También espero verla pelear contra alguien como Axelia en el evento.",
  ui_story_1014_10141102_41_dialog_content = "Por supuesto, si se presentara una oportunidad, me encantaría entrenar con Lady Carleen, la ex campeona.",
  ui_story_1014_10141102_42_dialog_content = "¡Qué insolente!",
  ui_story_1014_10141102_43_dialog_content = "Todo está bien.",
  ui_story_1014_10141102_44_dialog_content = "Estaré participando en el próximo evento.",
  ui_story_1014_10141102_45_dialog_content = "Espero pelear contigo, Leo.",
  ui_story_1014_10141102_46_dialog_content = "Es un trato.",
  ui_story_1014_10141102_47_dialog_content = "¿También te apuntas al evento, Leo?",
  ui_story_1014_10141102_48_dialog_content = "Sí.",
  ui_story_1014_10141102_49_dialog_content = "Todos los Aurorianos son elegibles para ello.",
  ui_story_1014_10141102_50_dialog_content = "Iré solo para ponerme a prueba contra los mejores de todo Astra, sin importar lo lejos que esté.",
  ui_story_1014_10141102_X50_dialog_content = "<color=#e8d9bb>En lo profundo de las ruinas de Aurora</color>",
  ui_story_1014_10141102_51_dialog_content = "(Ya llegamos hasta aquí. Parece que este viaje terminará pronto).",
  ui_story_1014_10141102_52_dialog_content = "(Pero todavía no se ve a Forsakin... ¿Podría estar equivocada mi suposición?)",
  ui_story_1014_10141102_53_dialog_content = "(No, su objetivo siempre ha sido claro, y PlayerName es el mejor cebo.)",
  ui_story_1014_10141102_54_dialog_content = "(No puedo estar equivocado. Todo lo que puedo hacer ahora es esperar).",
  ui_story_1014_10141102_55_dialog_content = "Yingel, ¿por qué te has detenido? ¿Estás lastimado?",
  ui_story_1014_10141102_56_dialog_content = "Eh...? No, estoy bien, solo me preguntaba por qué hay tantos eclipses.",
  ui_story_1014_10141102_57_dialog_content = "Permítanme intercalar...",
  ui_story_1014_10141102_58_dialog_content = "El objetivo de esta misión es ayudar a PlayerName a encontrar un componente Colossus.",
  ui_story_1014_10141102_59_dialog_content = "Por lo que sé, no deberíamos estar lejos del antiguo Coloso.",
  ui_story_1014_10141102_60_dialog_content = "Sigamos avanzando, ¿de acuerdo?",
  ui_story_1014_10141102_61_dialog_content = "Sí, la señorita Joselyne tiene razón.",
  ui_story_1014_10141102_62_dialog_content = "Este lugar me está dando escalofríos como si alguien nos estuviera mirando...",
  ui_story_1014_10141102_63_dialog_content = "¡Deberíamos obtener la parte que necesitamos y volver a Crepúsculo!",
  ui_story_1014_10141102_64_dialog_content = "<color=#e8d9bb>En algún lugar fuera de las Ruinas de Aurora</color>",
  ui_story_1014_10141102_65_dialog_content = "(Eclipsian) El olor de su deseo se acerca al Coloso.",
  ui_story_1014_10141102_66_dialog_content = "(Eclipsian) ¿Podría ese objeto estar dentro del Coloso?",
  ui_story_1014_10141102_67_dialog_content = "(Eclipsian) ¿Deberíamos mudarnos ahora, Lord Asmodeus?",
  ui_story_1014_10141102_68_dialog_content = "(Eclipsian) Que su deseo se acerque más, más cerca...",
  ui_story_1014_10141102_69_dialog_content = "(Eclipsian) El deseo de ese Caelestite traidor será la señal que guíe.",
  ui_story_1014_10141102_70_dialog_content = "(Eclipsian) Solo necesitamos esperar.",
  ui_story_1014_10141201_1_dialog_content = "El Coloso está justo adelante. Mantén tus ojos abiertos.",
  ui_story_1014_10141201_2_dialog_content = "No puedo esperar a un coloso de la antigüedad...",
  ui_story_1014_10141201_3_dialog_content = "<size=45>¡Es tan grande!</size>",
  ui_story_1014_10141201_4_dialog_content = "¡El tamaño supera completamente mis expectativas!",
  ui_story_1014_10141201_5_dialog_content = "Su tamaño está entre los más grandes de todos los Colosos descubiertos.",
  ui_story_1014_10141201_6_dialog_content = "Las tropas de la Federación Illumina estacionadas en Crepúsculo estudiaron este Coloso y obtuvieron una gran cantidad de datos valiosos.",
  ui_story_1014_10141201_7_dialog_content = "¿Qué tipo de datos?",
  ui_story_1014_10141201_8_dialog_content = "Información sobre cómo se fabricaron ciertos dispositivos, como un plano parcial de su sistema médico.",
  ui_story_1014_10141201_9_dialog_content = "¿Algún otro descubrimiento, como datos de memoria o mensajes antiguos de Caelestita?",
  ui_story_1014_10141201_10_dialog_content = "Me temo que no puedo responder eso ya que es información clasificada.",
  ui_story_1014_10141201_11_dialog_content = "Sin embargo, debido a un percance operativo, el Colossus salió en un <color=#FFB400>alboroto</color> una vez.",
  ui_story_1014_10141201_12_dialog_content = "El incidente hizo que muchas áreas internas del Coloso fueran inaccesibles.",
  ui_story_1014_10141201_13_dialog_content = "Después de eso, fue designado como un objeto de alto riesgo y bajo valor, al igual que las Ruinas de Aurora en las que se encuentra.",
  ui_story_1014_10141201_14_dialog_content = "Es muy probable que el oficial Ulysses autorice esta expedición solo porque usted está en ella.",
  ui_story_1014_10141201_15_dialog_content = "¿Porque soy un caelestita?",
  ui_story_1014_10141201_16_dialog_content = "Correcto.",
  ui_story_1014_10141201_17_dialog_content = "Caelestites puede pilotar Colossi, por lo que podemos descubrir cosas inimaginables.",
  ui_story_1014_10141201_18_dialog_content = "... Vamonos.",
  ui_story_1014_10141201_19_dialog_content = "¿Deberíamos entrar?",
  ui_story_1014_10141201_20_dialog_content = "Míralo, PlayerName.",
  ui_story_1014_10141201_21_dialog_content = "Veo rastros de actividad de Eclipsite.",
  ui_story_1014_10141201_22_dialog_content = "Hay muchos Eclipsites dentro de este Coloso.",
  ui_story_1014_10141201_23_dialog_content = "No importa cuántos sean, debo obtener los datos.",
  ui_story_1014_10141201_24_dialog_content = "Por el bien de Soroz.",
  ui_story_1014_10141201_25_dialog_content = "Es muy espacioso aquí.",
  ui_story_1014_10141201_26_dialog_content = "Aparte de los eclipses, no hay rastros de nada más.",
  ui_story_1014_10141201_27_dialog_content = "¿Tu Colossus tiene habitaciones espaciosas como esta, PlayerName?",
  ui_story_1014_10141201_28_option_content = "Si",
  ui_story_1014_10141201_29_dialog_content = "La cabina de Soroz es muy grande, incluso puedes hacer jogging en ella sin problema.",
  ui_story_1014_10141201_30_dialog_content = "¡Impresionante!",
  ui_story_1014_10141201_31_option_content = "No",
  ui_story_1014_10141201_32_dialog_content = "Las habitaciones y los pasillos de Soroz son espaciosos, pero suele haber mucha gente a bordo.",
  ui_story_1014_10141201_33_dialog_content = "Eso hace que se sienta menos espacioso de lo que es.",
  ui_story_1014_10141201_34_dialog_content = "¡Tiene sentido!",
  ui_story_1014_10141201_35_dialog_content = "Hay una puerta adelante.",
  ui_story_1014_10141201_36_dialog_content = "Se parece a las puertas que dan a las habitaciones de Soroz.",
  ui_story_1014_10141201_37_dialog_content = "Esta puerta debe conducir al puente.",
  ui_story_1014_10141201_38_dialog_content = "Parece sellado, sin manija ni cerradura...",
  ui_story_1014_10141201_39_dialog_content = "¿Cómo vamos a abrirlo?",
  ui_story_1014_10141201_40_dialog_content = "Todas las puertas de Soroz se abren telepáticamente.",
  ui_story_1014_10141201_41_dialog_content = "Déjame probar eso con este.",
  ui_story_1014_10141201_42_option_content = "¡Potencia de fuerza!",
  ui_story_1014_10141201_43_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_1014_10141201_44_dialog_content = "<color=#e8d9bb>Visitante Caelestite no registrado detectado.</color>",
  ui_story_1014_10141201_45_dialog_content = "¿Es este el sistema principal de este Colossus? Suena tan rígido.",
  ui_story_1014_10141201_46_dialog_content = "Como Soroz sin su personalidad...",
  ui_story_1014_10141201_47_dialog_content = "<color=#e8d9bb>Regístrese usted mismo.</color>",
  ui_story_1014_10141201_48_dialog_content = "Me llamo PlayerName, soy Caelestita.",
  ui_story_1014_10141201_49_dialog_content = "<color=#e8d9bb>Usuario no registrado cambiado a PlayerName.</color>",
  ui_story_1014_10141201_50_dialog_content = "<color=#e8d9bb>Se te ha otorgado acceso completo a Naviduz.</color>",
  ui_story_1014_10141201_51_dialog_content = "<color=#FFB400>Navidad</color>...? ¡Ese fue uno de los Colosos de la antigüedad!",
  ui_story_1014_10141201_52_dialog_content = "¿Acceso completo, incluso? ¡Eso fue fácil!",
  ui_story_1014_10141201_53_dialog_content = "<color=#e8d9bb>Los protocolos de acceso de Naviduz cumplen con los permisos establecidos por todos sus pilotos.</color>",
  ui_story_1014_10141201_54_dialog_content = "<color=#e8d9bb>\"Menos de 100 años, sólo el administrador recibirá pleno acceso\".</color>",
  ui_story_1014_10141201_55_dialog_content = "<color=#e8d9bb>\"Más de 100 años pero menos... años, acceso completo... todos Caelestites\".</color>",
  ui_story_1014_10141201_56_dialog_content = "<color=#e8d9bb>\"Durante... años pero bajo... años, acceso total... a todas las entidades vivientes\".</color>",
  ui_story_1014_10141201_57_dialog_content = "<color=#e8d9bb>De acuerdo con el protocolo, Naviduz actualmente otorga acceso completo a todos los Caelestites.</color>",
  ui_story_1014_10141201_58_dialog_content = "¿Cuánto tiempo has estado esperando? ... Lo siento.",
  ui_story_1014_10141201_59_dialog_content = "<color=#e8d9bb>La personalidad de Naviduz quedó suspendida, incapaz de comprender el significado de \"Lo siento\".</color>",
  ui_story_1014_10141201_60_dialog_content = "<color=#e8d9bb>Todo en Naviduz es un regalo para futuros Caelestites.</color>",
  ui_story_1014_10141201_61_dialog_content = "¿Su personalidad fue suspendida? ¿Por qué?",
  ui_story_1014_10141201_62_dialog_content = "<color=#e8d9bb>La personalidad cuesta poder adicional para mantener.</color>",
  ui_story_1014_10141201_63_dialog_content = "<color=#e8d9bb>Para garantizar que Naviduz pueda conservar y transmitir todos los datos a Caelestites que puedan localizar el Coloso...</color>",
  ui_story_1014_10141201_64_dialog_content = "<color=#e8d9bb>Naviduz optó por suspender la personalidad e iniciar el modo de conservación.</color>",
  ui_story_1014_10141201_65_dialog_content = "¿Siguen funcionando sus sistemas y datos de personalidad?",
  ui_story_1014_10141201_66_dialog_content = "<color=#e8d9bb>Ejecutando autodiagnósticos.</color>",
  ui_story_1014_10141201_67_dialog_content = "<color=#e8d9bb>\"Sistema de control principal, en funcionamiento. La integridad de los componentes ha disminuido un 72 %. Se requiere mantenimiento\".</color>",
  ui_story_1014_10141201_68_dialog_content = "<color=#e8d9bb>Módulos biológicos fuera de línea.</color>",
  ui_story_1014_10141201_69_dialog_content = "<color=#e8d9bb>Soporte vital fuera de línea.</color>",
  ui_story_1014_10141201_70_dialog_content = "<color=#e8d9bb>Los datos de personalidad se deterioraron un 32 %, sin poder operar a un nivel normal.</color>",
  ui_story_1014_10141201_71_dialog_content = "¿Se ha deteriorado hasta el punto de no funcionar?",
  ui_story_1014_10141201_72_dialog_content = "Así que tú también, Naviduz...",
  ui_story_1014_10141201_73_dialog_content = "De todos modos, gracias por aguantar tanto tiempo.",
  ui_story_1014_10141201_74_dialog_content = "Por favor, abre la puerta del puente.",
  ui_story_1014_10141201_75_dialog_content = "<color=#e8d9bb>Comando aceptado.</color>",
  ui_story_1014_10141201_76_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_1014_10141201_77_dialog_content = "La puerta está abierta.",
  ui_story_1014_10141201_78_dialog_content = "Veo un puente maltrecho y una consola de control.",
  ui_story_1014_10141201_79_dialog_content = "<anim type=Shake><size=45>¡Gahhhhhhhh!</size></anim>",
  ui_story_1014_10141201_80_dialog_content = "¡Cuidado, aquí vienen los Eclipsitos errantes!",
  ui_story_1014_10141201_81_dialog_content = "¡Prepárate para luchar!",
  ui_story_1014_10141302_1_dialog_content = "Todos los eclipses despejados.",
  ui_story_1014_10141302_2_dialog_content = "Cierra la puerta, PlayerName, para que no tengamos más de sus compañeros.",
  ui_story_1014_10141302_3_dialog_content = "Le diré a Naviduz.",
  ui_story_1014_10141302_4_dialog_content = "...",
  ui_story_1014_10141302_5_dialog_content = "¿Estás bien, Axelia?",
  ui_story_1014_10141302_6_dialog_content = "Luchaste durante mucho tiempo. Necesitas descansar.",
  ui_story_1014_10141302_7_dialog_content = "Estoy bien.",
  ui_story_1014_10141302_8_dialog_content = "Las consecuencias de la batalla todavía están dentro de un rango aceptable.",
  ui_story_1014_10141302_9_dialog_content = "Bueno. Pero si sientes algo malo, dímelo inmediatamente.",
  ui_story_1014_10141302_10_dialog_content = "Lo haré.",
  ui_story_1014_10141302_11_dialog_content = "(Casi olvido que el poder de Axelia se deriva de la bioingeniería de Illumina).",
  ui_story_1014_10141302_12_dialog_content = "(Por lo general, no muestra emociones, pero por un segundo allí, parecía que estaba en agonía).",
  ui_story_1014_10141302_13_dialog_content = "(Probablemente soporta mucho más dolor del que muestra...)",
  ui_story_1014_10141302_14_dialog_content = "Eres libre de completar tu trabajo, PlayerName.",
  ui_story_1014_10141302_15_dialog_content = "Bien... gracias.",
  ui_story_1014_10141302_16_dialog_content = "Echaremos un vistazo, así que mantente alerta.",
  ui_story_1014_10141302_17_dialog_content = "ayudaré PlayerName echa un vistazo al coloso.",
  ui_story_1014_10141302_18_dialog_content = "Naviduz, me gustaría obtener sus datos de personalidad, por lo que necesito el módulo de control principal.",
  ui_story_1014_10141302_19_dialog_content = "<color=#e8d9bb>Comando aceptado. Comprobando el estado del módulo de control principal.</color>",
  ui_story_1014_10141302_20_dialog_content = "<color=#e8d9bb>Advertencia: El módulo de control primario sufrió daños graves. La extracción forzada causará daños irreversibles.</color>",
  ui_story_1014_10141302_21_dialog_content = "no podemos quitarlo?",
  ui_story_1014_10141302_22_dialog_content = "¿Q-Qué vamos a hacer ahora?",
  ui_story_1014_10141302_23_dialog_content = "Te ves preocupado. Tengo una sugerencia.",
  ui_story_1014_10141302_24_dialog_content = "Mi traje de batalla tiene un dispositivo de duplicación de datos. Puedes conectarlo al Coloso.",
  ui_story_1014_10141302_25_dialog_content = "Es posible que no obtengamos el módulo completo, pero aún podemos adquirir los datos de personalidad requeridos.",
  ui_story_1014_10141302_26_dialog_content = "Para Algol, los datos y el módulo son lo mismo.",
  ui_story_1014_10141302_27_dialog_content = "Supongo que esa es la única opción que tenemos.",
  ui_story_1014_10141302_28_dialog_content = "PlayerName debe conectar el dispositivo al módulo de control del Colossus.",
  ui_story_1014_10141302_29_dialog_content = "Presione este botón para comenzar a duplicar datos.",
  ui_story_1014_10141302_30_dialog_content = "Entiendo.",
  ui_story_1014_10141302_31_dialog_content = "<color=#e8d9bb>Duplicación de datos. Por favor espere.</color>",
  ui_story_1014_10141302_32_dialog_content = "Parece que tenemos más cosas esperando por hacer.",
  ui_story_1014_10141302_33_dialog_content = "Estamos rodeados de antiguas reliquias tecnológicas...",
  ui_story_1014_10141302_34_dialog_content = "Noche Blanca en lo alto, espero que no amenace nuestra existencia.",
  ui_story_1014_10141302_35_dialog_content = "<color=#e8d9bb>Bip, bip, bip...</color>",
  ui_story_1014_10141302_36_dialog_content = "Este es el cuartel general de los Caballeros de Ironthorn en Crepúsculo. Responda si está disponible, Sir Leo.",
  ui_story_1014_10141302_37_dialog_content = "Este es el Caballero de la Expedición Leo. Avanzar.",
  ui_story_1014_10141302_38_dialog_content = "Por favor transmita su ubicación y progreso.",
  ui_story_1014_10141302_39_dialog_content = "Actualmente estamos llevando a cabo la misión de salvaguardar la Caelestita PlayerName en el Coloso dentro de las Ruinas de Aurora.",
  ui_story_1014_10141302_40_dialog_content = "Lady Carleen y varios Aurorianos de Illumina están con nosotros.",
  ui_story_1014_10141302_41_dialog_content = "Lady Carleen... Copia eso.",
  ui_story_1014_10141302_42_dialog_content = "Continuar la misión. Si tiene problemas, solicite refuerzos directamente a los Caballeros de Ironthorn.",
  ui_story_1014_10141302_43_dialog_content = "Sí.",
  ui_story_1014_10141302_44_dialog_content = "Buena suerte. Sobre.",
  ui_story_1014_10141302_45_dialog_content = "¿Solicitar refuerzos de los Caballeros de Ironthorn?",
  ui_story_1014_10141302_46_dialog_content = "En comparación con los caballeros de expedición que pasan años lejos, los caballeros de Crepúsculo deberían ser superiores en número y armas.",
  ui_story_1014_10141302_47_dialog_content = "¿Por qué no les pides respaldo?",
  ui_story_1014_10141302_48_dialog_content = "Lady Carleen, como puede ver, hay ciertos problemas entre Ironthorn y los caballeros locales.",
  ui_story_1014_10141302_49_dialog_content = "La mayoría de los Expedition Knights tienen antecedentes civiles o son nobles exiliados. Su estatus es muy diferente al de los caballeros regulares.",
  ui_story_1014_10141302_50_dialog_content = "Incluso cuando solicitamos apoyo, a menudo no nos toman en serio.",
  ui_story_1014_10141302_51_dialog_content = "Entonces, como Expedition Knights, estamos acostumbrados a confiar en nosotros mismos.",
  ui_story_1014_10141302_52_dialog_content = "No puedo creerlo...",
  ui_story_1014_10141302_53_dialog_content = "Informaré de esto a los altos mandos de Lumopolis.",
  ui_story_1014_10141302_54_dialog_content = "Todos los ciudadanos de Lumopolis deberían recibir el mismo trato sin importar su posición social.",
  ui_story_1014_10141302_55_dialog_content = "Aprecio tu apertura de mente, aunque no creo que salga nada significativo de ello.",
  ui_story_1014_10141302_56_dialog_content = "La parcialidad y el conflicto persistirán mientras haya una brecha entre nobles y civiles.",
  ui_story_1014_10141302_57_dialog_content = "Nadie lo entiende mejor que un noble desterrado como yo.",
  ui_story_1014_10141302_58_dialog_content = "... He conocido a nobles exiliados en el pasado.",
  ui_story_1014_10141302_59_dialog_content = "Todos expresarían desprecio por su situación, de una forma u otra.",
  ui_story_1014_10141302_60_dialog_content = "¿Tú también sientes lo mismo, Leo?",
  ui_story_1014_10141302_61_dialog_content = "¿Estás pidiendo mi opinión?",
  ui_story_1014_10141302_62_dialog_content = "Sí lo soy.",
  ui_story_1014_10141302_63_dialog_content = "Yo era un noble rico en Lumopolis.",
  ui_story_1014_10141302_64_dialog_content = "En aquel entonces, consideraba que luchar y defender Lumopolis era el mayor honor para mí como caballero.",
  ui_story_1014_10141302_65_dialog_content = "Después de que me exiliaran, me convertí en nada más que un simple plebeyo en Crepúsculo.",
  ui_story_1014_10141302_66_dialog_content = "Ni siquiera podía cambiar mi antigua gloria o prometer defender Lumopolis con mi vida por una rebanada de pan.",
  ui_story_1014_10141302_67_dialog_content = "¿Entonces te sientes abandonado e irrespetado?",
  ui_story_1014_10141302_68_dialog_content = "No lo niego.",
  ui_story_1014_10141302_69_dialog_content = "Pero ser desterrado a Crepúsculo es exactamente cuando me di cuenta de que solo puedo confiar verdaderamente en mí mismo.",
  ui_story_1014_10141302_70_dialog_content = "Después de pasar la prueba para convertirme en un Caballero de Expedición y vivir en Crepúsculo por un tiempo, mi actitud cambió.",
  ui_story_1014_10141302_71_dialog_content = "No creo que sea tan malo como imaginaba.",
  ui_story_1014_10141302_72_dialog_content = "Al menos en Crepúsculo, los aurorianos de diferentes facciones pueden dejar de lado sus rivalidades y vivir juntos.",
  ui_story_1014_10141302_73_dialog_content = "Disfruto mucho pelear Eclipsites con otros, pero... todavía siento injusticia.",
  ui_story_1014_10141302_74_dialog_content = "Por favor elabora.",
  ui_story_1014_10141302_75_dialog_content = "¿Qué puede darte mi respuesta?",
  ui_story_1014_10141302_76_dialog_content = "Quiero escuchar a la gente para poder mejorar las leyes y políticas de Lumopolis.",
  ui_story_1014_10141302_77_dialog_content = "Quiero que todos en Lumopolis obtengan la igualdad que todos merecen.",
  ui_story_1014_10141302_78_dialog_content = "Bueno...",
  ui_story_1014_10141302_79_dialog_content = "<color=#e8d9bb>¡Bip!</color>",
  ui_story_1014_10141302_80_dialog_content = "<color=#e8d9bb>Duplicación de datos de Colossus completa. Es seguro desconectarse.</color>",
  ui_story_1014_10141302_81_dialog_content = "¡Creo que está hecho!",
  ui_story_1014_10141302_82_dialog_content = "¡Regresemos ahora!",
  ui_story_1014_10141302_83_dialog_content = "¡No tienes que decírmelo dos veces!",
  ui_story_1014_10141302_84_dialog_content = "(Gracias a Dios por el dispositivo de Algol...)",
  ui_story_1014_10141302_85_dialog_content = "(¡Si Carleen y Leo hubieran seguido hablando, podrían haber terminado peleando entre ellos!)",
  ui_story_1014_10141302_86_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_1014_10141302_87_dialog_content = "*Tose* ¿Qué está pasando?",
  ui_story_1014_10141302_88_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_1014_10141302_89_dialog_content = "El Coloso está temblando, PlayerName!",
  ui_story_1014_10141302_90_dialog_content = "¡No me digas que está a punto de hacer un alboroto otra vez!",
  ui_story_1014_10141302_91_dialog_content = "¡¿Alboroto?!",
  ui_story_1014_10141302_92_dialog_content = "Toma el dispositivo y sal de aquí. PlayerName!",
  ui_story_1014_10141302_93_dialog_content = "Las vibraciones son demasiado intensas... ¡El Coloso podría desmoronarse y colapsar!",
  ui_story_1014_10141302_94_dialog_content = "¡No podemos quedarnos aquí!",
  ui_story_1014_10141302_95_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_1014_10141302_96_dialog_content = "¡Oh, no!",
  ui_story_1014_10141302_97_dialog_content = "¡Estamos demasiado cerca de Crepúsculo, un alboroto probablemente arrasaría la ciudad!",
  ui_story_1014_10141302_98_dialog_content = "¡Hay tantos civiles allí!",
  ui_story_1014_10141302_99_dialog_content = "¡Tenemos que parar esto de alguna manera!",
  ui_story_1014_10141302_100_dialog_content = "Pero...",
  ui_story_1014_10141302_101_option_content = "¡Déjamelo a mí!",
  ui_story_1014_10141302_102_dialog_content = "Esta es la tecnología Caelestite.",
  ui_story_1014_10141302_103_dialog_content = "Probablemente se necesita un Caelestite para detenerlo.",
  ui_story_1014_10141302_104_dialog_content = "¡Vicio, Carleen, necesitaré tu ayuda!",
  ui_story_1014_10141302_105_dialog_content = "¡No hay problema!",
  ui_story_1014_10141302_106_dialog_content = "Lo tienes.",
  ui_story_1014_10141302_107_dialog_content = "Gracias. voy a empezar",
  ui_story_1014_10141302_108_dialog_content = "¡Potencia de fuerza!",
  ui_story_1014_10141401_1_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_1014_10141401_2_dialog_content = "Naviduz!",
  ui_story_1014_10141401_3_dialog_content = "<color=#e8d9bb>Naviduz esperando órdenes.</color>",
  ui_story_1014_10141401_4_dialog_content = "Lo que sea que estés tratando de hacer, ¡detente!",
  ui_story_1014_10141401_5_dialog_content = "¡No alborotes! ¡Pondrá en peligro muchas vidas inocentes!",
  ui_story_1014_10141401_6_dialog_content = "<color=#e8d9bb>Búsqueda de registros relevantes para el alboroto.</color>",
  ui_story_1014_10141401_7_dialog_content = "<color=#e8d9bb>Naviduz nunca ha arrasado.</color>",
  ui_story_1014_10141401_8_dialog_content = "¿Nunca? ¿Qué pasa con el incidente que mencionó Yingel...?",
  ui_story_1014_10141401_9_dialog_content = "<color=#e8d9bb>Buscando información sobre la última iniciación.</color>",
  ui_story_1014_10141401_10_dialog_content = "<color=#e8d9bb>Naviduz activó el modo de defensa debido al funcionamiento erróneo de las formas de vida Lumo.</color>",
  ui_story_1014_10141401_11_dialog_content = "<color=#e8d9bb>Para proteger los datos, Naviduz tomó las medidas de evasión necesarias.</color>",
  ui_story_1014_10141401_12_dialog_content = "<color=#e8d9bb>Durante esto, Naviduz no dañó ninguna forma de vida.</color>",
  ui_story_1014_10141401_13_dialog_content = "Así que ese temblor, ¿no estabas arrasando?",
  ui_story_1014_10141401_14_dialog_content = "<color=#e8d9bb>El sistema de propulsión de Naviduz está gravemente dañado y no funciona.</color>",
  ui_story_1014_10141401_15_dialog_content = "<color=#e8d9bb>Los resultados del análisis indican que el estruendo proviene del exterior. Proyectando grabación externa ahora.</color>",
  ui_story_1014_10141401_16_dialog_content = "(Eclipsian) Esta es una prisión, un recipiente para el deseo.",
  ui_story_1014_10141401_17_dialog_content = "(Eclipsian) Los deseos hicieron el mundo y finalmente lo destruirán.",
  ui_story_1014_10141401_18_dialog_content = "(Eclipsian) Por lo tanto, los deseos deben ser limpiados antes de que se vuelvan desenfrenados.",
  ui_story_1014_10141401_19_dialog_content = "¡¿Cómo es que hay tantos eclipses?!",
  ui_story_1014_10141401_20_dialog_content = "¿Ese del medio es su líder?",
  ui_story_1014_10141401_21_dialog_content = "(Eclipsian) Los aurorianos aún no han salido, Lord Asmodeus.",
  ui_story_1014_10141401_22_dialog_content = "(Eclipsian) Su deseo los llevará a nosotros.",
  ui_story_1014_10141401_23_dialog_content = "(Eclipsian) Porque ellos...",
  ui_story_1014_10141401_24_dialog_content = "(Eclipsian) ya nos han visto.",
  ui_story_1014_10141401_25_dialog_content = "!",
  ui_story_1014_10141401_26_dialog_content = "¿Estás bien, PlayerName?",
  ui_story_1014_10141401_27_dialog_content = "¿Por qué te ves tan pálido?",
  ui_story_1014_10141401_28_dialog_content = "El Coloso no estaba causando las vibraciones. ¡Fueron los eclipses afuera!",
  ui_story_1014_10141401_29_dialog_content = "Acabo de ver un Eclipsite muy poderoso a través de la cámara externa.",
  ui_story_1014_10141401_30_dialog_content = "Y aparentemente ella también podía verme a través de eso.",
  ui_story_1014_10141401_31_dialog_content = "¿Cómo es eso posible? ¿Podría ser tan poderosa como Forsakin?",
  ui_story_1014_10141401_32_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_1014_10141401_33_dialog_content = "<color=#e8d9bb>Advertencia, formas de vida no autorizadas están ingresando al Coloso.</color>",
  ui_story_1014_10141401_34_dialog_content = "Cuidado. ¡Poderosos eclipses vienen hacia aquí!",
  ui_story_1014_10141401_35_dialog_content = "Ay, tanto ruido. Pero no solo eso. Hay el olor persistente del deseo.",
  ui_story_1014_10141401_36_dialog_content = "Deseo de poder.",
  ui_story_1014_10141401_37_dialog_content = "Deseo de reconocimiento.",
  ui_story_1014_10141401_38_dialog_content = "Y... Hmm, ¿es esto...?",
  ui_story_1014_10141401_39_dialog_content = "Deseo de salvar a los propios compañeros.",
  ui_story_1014_10141401_40_dialog_content = "¿Quién eres? ¿Qué quieres?",
  ui_story_1014_10141401_41_dialog_content = "¿Yo? ¿Por qué me deseas también?",
  ui_story_1014_10141401_42_dialog_content = "Soy Asmodeo, nacido del deseo y destinado a purgar todo deseo de este mundo.",
  ui_story_1014_10141401_43_dialog_content = "¡Permíteme purgar tus deseos!",
  ui_story_1014_10141401_44_dialog_content = "¿Qué es lo que tanto deseas, lo guardarías con tu vida? Lo destruiré y veré.",
  ui_story_1014_10141401_45_dialog_content = "¡En tus sueños!",
  ui_story_1014_10141401_46_dialog_content = "¡Carleen!",
  ui_story_1014_10141401_47_dialog_content = "Ella es una dura. ¡Vamos a llevarla juntos, todos!",
  ui_story_1014_10141401_48_dialog_content = "¡Aléjate de Lady Carleen, Eclipsite!",
  ui_story_1014_10141401_49_dialog_content = "Deseos... deseos lamentables, intrascendentes...",
  ui_story_1014_10141401_50_dialog_content = "No tendrás éxito solo con eso.",
  ui_story_1014_10141401_51_dialog_content = "A veces desear más de lo que deberías no es bueno, Eclipsite... No, probablemente seas un <color=#FFB400>Espectro</color>, ¿verdad?",
  ui_story_1014_10141401_52_dialog_content = "Correcto, los deseos son malos, así que debo erradicarlos.",
  ui_story_1014_10141401_53_dialog_content = "Pero es una tarea imposible, ya que mientras haya Aurorianos, los deseos no tendrán fin.",
  ui_story_1014_10141401_54_dialog_content = "Por lo tanto, recurro a erradicar a los Aurorianos con deseos primero.",
  ui_story_1014_10141401_55_dialog_content = "También erradicaré al traidor Caelestite.",
  ui_story_1014_10141401_56_dialog_content = "no voy a permitir PlayerName ser dañado",
  ui_story_1014_10141401_57_dialog_content = "¿Vaya? ¿Es eso lo que deseas?",
  ui_story_1014_10141401_58_dialog_content = "Proteger PlayerName es mi deber",
  ui_story_1014_10141401_59_dialog_content = "Que curioso. No tienes deseos en absoluto.",
  ui_story_1014_10141401_60_dialog_content = "Oh no no. Mi error.",
  ui_story_1014_10141401_61_dialog_content = "Tú mismo eres un producto del deseo. Por eso eres tan poderoso.",
  ui_story_1014_10141401_62_dialog_content = "Absolutamente fascinante.",
  ui_story_1014_10141401_63_dialog_content = "Me pregunto cómo se verá ese deseo cuando sea destruido.",
  ui_story_1014_10141401_64_dialog_content = "¡Apenas puedo esperar!",
  ui_story_1014_10141401_65_dialog_content = "¡Cuidado, los Eclipsites están haciendo su movimiento!",
  ui_story_1014_10141402_1_dialog_content = "¡Uh!",
  ui_story_1014_10141402_2_dialog_content = "¡Axelia!",
  ui_story_1014_10141402_3_dialog_content = "Todavía puedo pelear...",
  ui_story_1014_10141402_4_dialog_content = "No, no puedes. ¡Necesitas tratamiento ahora!",
  ui_story_1014_10141402_5_dialog_content = "Decepcionante.",
  ui_story_1014_10141402_6_dialog_content = "La suma del deseo de Illumina no es más que una niña débil.",
  ui_story_1014_10141402_7_dialog_content = "Muy decepcionante. ¿Pasa esto por los deseos aurorianos en estos días?",
  ui_story_1014_10141402_8_dialog_content = "Inconcebible.",
  ui_story_1014_10141402_9_dialog_content = "¿Por qué Forsakin está obsesionado con algo tan indigno?",
  ui_story_1014_10141402_10_dialog_content = "¡No dirás eso de Axelia!",
  ui_story_1014_10141402_11_dialog_content = "¿Aún te niegas a enfrentar lo débil que eres?",
  ui_story_1014_10141402_12_dialog_content = "¿Qué tal esto, entonces?",
  ui_story_1014_10141402_13_dialog_content = "Oh no, más eclipses.",
  ui_story_1014_10141402_14_dialog_content = "Joselyne, Joseph, ¡observad los Eclipsitas más pequeños que vienen por vuestro flanco izquierdo!",
  ui_story_1014_10141402_15_dialog_content = "¡Entendido!",
  ui_story_1014_10141402_16_dialog_content = "¡Yingel, Sean, ustedes dos manejan los Eclipsites más grandes a la derecha!",
  ui_story_1014_10141402_17_dialog_content = "Espera, ¿por qué deberíamos escucharte?",
  ui_story_1014_10141402_18_dialog_content = "<anim type=Shake><size=45>¡Rugido!</size></anim>",
  ui_story_1014_10141402_19_dialog_content = "¡Déjame esto a mi!",
  ui_story_1014_10141402_20_dialog_content = "Suspiro.",
  ui_story_1014_10141402_21_dialog_content = "¡El resto de ustedes peleen esto conmigo!",
  ui_story_1014_10141402_22_dialog_content = "Veo que tus deseos no son más que esto.",
  ui_story_1014_10141402_23_dialog_content = "Cuanto más fuerte es el deseo, mayor es el poder.",
  ui_story_1014_10141402_24_dialog_content = "Tienes deseos mundanos, por lo que eres débil.",
  ui_story_1014_10141402_25_dialog_content = "¡Pero el mío es destruir todos los deseos del mundo!",
  ui_story_1014_10141402_26_dialog_content = "Pato, PlayerName!",
  ui_story_1014_10141402_27_dialog_content = "¿Qué?",
  ui_story_1014_10141402_28_dialog_content = "Ningún deseo puede escapar de mí.",
  ui_story_1014_10141402_29_dialog_content = "¡Tsk!",
  ui_story_1014_10141402_30_dialog_content = "¡PlayerName!",
  ui_story_1014_10141402_31_dialog_content = "¡Ouch eso duele!",
  ui_story_1014_10141402_32_dialog_content = "¡Oh no, el dispositivo!",
  ui_story_1014_10141402_33_dialog_content = "No interfieras con tu deseo banal.",
  ui_story_1014_10141402_34_dialog_content = "¡Uh!",
  ui_story_1014_10141402_35_dialog_content = "(¡Necesito ocultar el dispositivo!)",
  ui_story_1014_10141402_36_dialog_content = "¡¿Eh?!",
  ui_story_1014_10141402_37_dialog_content = "Así que ese es tu deseo, Caelestite traidor.",
  ui_story_1014_10141402_38_dialog_content = "...",
  ui_story_1014_10141402_39_dialog_content = "¿Eso es todo?",
  ui_story_1014_10141402_40_dialog_content = "¡Bajalo!",
  ui_story_1014_10141402_41_dialog_content = "Que aburrido.",
  ui_story_1014_10141402_42_dialog_content = "¿De qué está hablando esa cosa?",
  ui_story_1014_10141402_43_dialog_content = "Aburrido, aburrido, absolutamente aburrido.",
  ui_story_1014_10141402_44_dialog_content = "¿Limitas tu deseo a nada más que un montón de basura sin sentido causado por errores, traidor?",
  ui_story_1014_10141402_45_option_content = "¡No es basura!",
  ui_story_1014_10141402_46_dialog_content = "¡Esos datos son un milagro!",
  ui_story_1014_10141402_47_dialog_content = "Los Colosos lo intentaron sin parar durante mucho tiempo, acumulando experiencia hasta formar una personalidad...",
  ui_story_1014_10141402_48_dialog_content = "¡Un tonto mundano que no hace más que parlotear sobre los deseos todo el día como si no entendieras su verdadero valor!",
  ui_story_1014_10141402_49_dialog_content = "Jeje... ¿Simplón mundano?",
  ui_story_1014_10141402_50_dialog_content = "No pensé que el traidor compartiría mis puntos de vista.",
  ui_story_1014_10141402_51_dialog_content = "Así es, todos los deseos son mundanos y no deberían existir en el mundo.",
  ui_story_1014_10141402_52_dialog_content = "Los eclipses no tienen deseos y por lo tanto no pueden ser tentados. Eso los convierte en los organismos más aptos para la supervivencia.",
  ui_story_1014_10141402_53_dialog_content = "Yo mismo elegí convertirme en un Espectro para abandonar los deseos.",
  ui_story_1014_10141402_54_dialog_content = "No escuches sus tonterías, PlayerName.",
  ui_story_1014_10141402_55_dialog_content = "¡Hablaremos juntos y recuperaremos el dispositivo!",
  ui_story_1014_10141402_56_dialog_content = "Pero he cambiado de opinión.",
  ui_story_1014_10141402_57_dialog_content = "Si tanto lo quieres de vuelta, puedes tenerlo.",
  ui_story_1014_10141402_58_dialog_content = "¡Oh no, el dispositivo!",
  ui_story_1014_10141402_59_dialog_content = "Uf, eso estuvo cerca.",
  ui_story_1014_10141402_60_dialog_content = "(No parece dañado).",
  ui_story_1014_10141402_61_dialog_content = "(¿Qué quiere ella? No puede estar aquí solo para burlarse de nosotros).",
  ui_story_1014_10141402_62_dialog_content = "Pensé que tenías grandes deseos, pero parece que estaba equivocado.",
  ui_story_1014_10141402_63_dialog_content = "Veo que lo que buscabas era simplemente basura inútil.",
  ui_story_1014_10141402_64_dialog_content = "Tales deseos ni siquiera valen mi tiempo.",
  ui_story_1014_10141402_65_dialog_content = "¡Deja de ladrar!",
  ui_story_1014_10141402_66_dialog_content = "Desde que tosiste lo que PlayerName necesario, no tengo que contenerme.",
  ui_story_1014_10141402_67_dialog_content = "¡Toma esto, Eclipsita!",
  ui_story_1014_10141402_68_dialog_content = "La lealtad es el deseo más inútil.",
  ui_story_1014_10141402_69_dialog_content = "Muy poderoso...!",
  ui_story_1014_10141402_70_dialog_content = "Ni siquiera estaba usando toda su fuerza...",
  ui_story_1014_10141402_71_dialog_content = "<anim type=Shake><size=45>¡Rugido!</size></anim>",
  ui_story_1014_10141402_72_dialog_content = "¡Cuidado, Beretta! ¡Flor de hielo!",
  ui_story_1014_10141402_73_dialog_content = "Muy decepcionante.",
  ui_story_1014_10141402_74_dialog_content = "Estás demasiado lleno de deseos aburridos para incluso despertar mi interés.",
  ui_story_1014_10141402_75_dialog_content = "Pero tú, PlayerName, traidor de los caelestitas...",
  ui_story_1014_10141402_76_dialog_content = "...",
  ui_story_1014_10141402_77_dialog_content = "Tal vez todo lo que necesita es un poco más de tiempo para convertir su deseo en algo interesante... y delicioso.",
  ui_story_1014_10141402_78_dialog_content = "Y usted también, <color=#FFB400>Vicio</color>.",
  ui_story_1014_10141402_79_dialog_content = "¿Yo?",
  ui_story_1014_10141402_80_dialog_content = "Nos vamos, Eclipsitas.",
  ui_story_1014_10141402_81_dialog_content = "Esto ya no vale nuestro tiempo.",
  ui_story_1014_10141402_82_dialog_content = "¡No intentes correr!",
  ui_story_1014_10141402_83_dialog_content = "¡Cálmate, Beretta!",
  ui_story_1014_10141402_84_dialog_content = "Ella no es tu Eclipsite promedio. Lo mejor que podríamos manejar es un punto muerto contra ella.",
  ui_story_1014_10141402_85_dialog_content = "No tenemos los medios para perseguirlos. Lo que tenemos que hacer ahora es retroceder y conseguir refuerzos.",
  ui_story_1014_10141402_86_dialog_content = "Pero...",
  ui_story_1014_10141402_87_dialog_content = "Leo tiene razón, Beretta. No deberíamos ir tras ellos en este momento.",
  ui_story_1014_10141402_88_dialog_content = "Volvamos a Crepúsculo.",
  ui_story_1014_10141402_89_dialog_content = "Como desees.",
  ui_story_1014_10141402_90_dialog_content = "Gracias por estar de acuerdo, Knight Commander.",
  ui_story_1014_10141402_91_dialog_content = "Cualquier guerrero experimentado llegaría a la misma conclusión.",
  ui_story_1014_10141402_92_dialog_content = "(Forsakin no apareció, pero atraemos a otro Wraith...)",
  ui_story_1014_10141402_93_dialog_content = "(¿Es esto una coincidencia o estaba destinado a ser?)",
  ui_story_1014_10141402_94_dialog_content = "(Independientemente, la misión fue un fracaso. Forsakin no se mostró como se esperaba).",
  ui_story_1014_10141402_95_dialog_content = "(Tendré que rastrearlos de alguna otra manera).",
  ui_story_1014_10141402_95X1_dialog_content = "¿Vamos a irnos, así como así? ¿Simplemente deje Naviduz aquí y váyase...?",
  ui_story_1014_10141402_95X2_dialog_content = "¿No hay manera de que podamos traerlo de vuelta con nosotros? ¡Vicio, seguramente la tecnología de Illumina podría solucionarlo!",
  ui_story_1014_10141402_95X3_dialog_content = "Me temo que puede ser difícil...",
  ui_story_1014_10141402_95X4_dialog_content = "...",
  ui_story_1014_10141402_95X5_dialog_content = "PlayerName, entiendo cómo te sientes, pero realmente no hay nada que podamos hacer ahora.",
  ui_story_1014_10141402_95X6_dialog_content = "Yingel, este Coloso es muy importante para PlayerName. ¿Realmente no hay nada que podamos hacer?",
  ui_story_1014_10141402_95X7_dialog_content = "El Coloso ya estaba bastante golpeado, sin mencionar el daño colateral de ese último alboroto.",
  ui_story_1014_10141402_95X8_dialog_content = "El hecho de que todavía esté funcionando es un milagro en sí mismo...",
  ui_story_1014_10141402_95X9_dialog_content = "Cómo puede ser esto...",
  ui_story_1014_10141402_95X10_dialog_content = "<color=#e8d9bb>Siento que te vas, Caelestite PlayerName.</color>",
  ui_story_1014_10141402_95X11_dialog_content = "¿Naviduz?",
  ui_story_1014_10141402_95X12_dialog_content = "<color=#e8d9bb>Naviduz desea hacerle una pregunta a Caelestite.</color>",
  ui_story_1014_10141402_95X13_dialog_content = "<color=#e8d9bb>caelestita PlayerName, infórmeme sobre su próxima visita y cómo planea reparar Naviduz.</color>",
  ui_story_1014_10141402_95X14_dialog_content = "...",
  ui_story_1014_10141402_95X15_dialog_content = "Yo... no sé.",
  ui_story_1014_10141402_95X16_dialog_content = "Lo siento... Lo siento, pero vas a tener que esperar un poco más...",
  ui_story_1014_10141402_95X17_dialog_content = "<color=#e8d9bb>Comando recibido.</color>",
  ui_story_1014_10141402_95X18_dialog_content = "<color=#e8d9bb>Según la configuración de 35, aquí es donde debo darle mis mejores deseos a Caelestite. PlayerName.</color>",
  ui_story_1014_10141402_95X19_dialog_content = "<color=#e8d9bb>No se sienta mal por no poder reparar Naviduz. Mantén tus ojos fijos en el horizonte.</color>",
  ui_story_1014_10141402_95X20_dialog_content = "¿Qué? ¿Ese fue un mensaje de 35? Ella realmente pensó en todo...",
  ui_story_1014_10141402_95X21_dialog_content = "<color=#e8d9bb>Naviduz y 35 le desean un buen viaje.</color>",
  ui_story_1014_10141402_95X22_dialog_content = "Gracias...",
  ui_story_1014_10141402_95X23_dialog_content = "Te escucho. Continuaré mi viaje con vuestras almas en mi corazón...",
  ui_story_1014_10141402_95X24_dialog_content = "Vamos, PlayerName.",
  ui_story_1014_10141402_95X25_dialog_content = "Esta bien vamos. Todavía tenemos mucho trabajo que hacer.",
  ui_story_1014_10141402_96_dialog_content = "<color=#e8d9bb>Soroz, El Puente</color>",
  ui_story_1014_10141402_97_dialog_content = "¡Actívate, Soroz!",
  ui_story_1014_10141402_98_dialog_content = "Esos eclipses no nos siguieron, ¿verdad?",
  ui_story_1014_10141402_99_dialog_content = "Ya no los siento, así que probablemente no estén cerca.",
  ui_story_1014_10141402_100_dialog_content = "No sé qué traman, pero siento que nos menospreciaron.",
  ui_story_1014_10141402_101_dialog_content = "Un día, sin embargo, los Eclipsites pagarán por subestimarnos.",
  ui_story_1014_10141402_102_dialog_content = "¿Cómo estás, Axelia? Fuiste golpeado por muchos ataques...",
  ui_story_1014_10141402_103_dialog_content = "Estoy bien.",
  ui_story_1014_10141402_104_dialog_content = "El cuerpo de Axelia puede ser frágil, pero *tos*... No seré derrotado tan fácilmente.",
  ui_story_1014_10141402_105_dialog_content = "(¿Es ese uno de los efectos secundarios de la modificación?)",
  ui_story_1014_10141402_107_dialog_content = "(Aún así, Reinhardt debe tener sus razones para oponerse firmemente al proyecto).",
  ui_story_1014_10141402_109_dialog_content = "(Hablando de eso, Reinhardt parece tener habilidades de combate y recuperación sobrehumanas también...)",
  ui_story_1014_10141402_110_dialog_content = "Qué tienes en mente, PlayerName?",
  ui_story_1014_10141402_111_dialog_content = "¿Eh? Oh nada.",
  ui_story_1014_10141402_112_dialog_content = "¿Qué pasa, Vice?",
  ui_story_1014_10141402_113_dialog_content = "Nada en realidad. Es solo que hay algunas cosas que no entiendo.",
  ui_story_1014_10141402_114_dialog_content = "¿Cómo es que ese Eclipsite llamado Asmodeus me mencionó al final?",
  ui_story_1014_10141402_115_dialog_content = "No la conozco, y nunca le dije mi nombre.",
  ui_story_1014_10141402_116_option_content = "¿Podría ser el Chord Link?",
  ui_story_1014_10141402_117_dialog_content = "Obtuviste poderes especiales al usar Chord Link.",
  ui_story_1014_10141402_118_dialog_content = "¿Quizás Asmodeus lo sintió y atrajo su atención hacia ti?",
  ui_story_1014_10141402_119_dialog_content = "no sabríamos...",
  ui_story_1014_10141402_120_dialog_content = "Ella es difícil de entender.",
  ui_story_1014_10141402_121_option_content = "¿Será su estado físico?",
  ui_story_1014_10141402_122_dialog_content = "Después de usar Chord Link, su estado físico ha sido inusual.",
  ui_story_1014_10141402_123_dialog_content = "Y te hizo brillar.",
  ui_story_1014_10141402_124_dialog_content = "Pero prácticamente no hay diferencia en mi apariencia externa.",
  ui_story_1014_10141402_125_dialog_content = "¿Podría tener una habilidad especial que pueda detectar cambios internos?",
  ui_story_1014_10141402_126_dialog_content = "Realmente no...",
  ui_story_1014_10141402_127_dialog_content = "Vamos a discutirlo más tarde. ¿Cómo te sientes ahora, Vice?",
  ui_story_1014_10141402_128_dialog_content = "Hicimos muchas peleas. ¿Te sientes incómodo en algún lugar?",
  ui_story_1014_10141402_129_dialog_content = "Relax. Estoy un poco cansada, pero no es nada que un buen descanso no solucione.",
  ui_story_1014_10141402_130_dialog_content = "Mi cuerpo aguantó muy bien.",
  ui_story_1014_10141402_131_dialog_content = "Me alivia escuchar eso.",
  ui_story_1014_10141402_132_dialog_content = "¡Todo lo que tenemos que hacer ahora es volver a Gannon y arreglar a Soroz con el módulo y los datos!",
  ui_story_1014_10141402_133_dialog_content = "Después de que dejemos a Axelia y al resto en Crepúsculo.",
  ui_story_1014_10141402_134_dialog_content = "¡Sí!",
  ui_story_1014_10141402_135_dialog_content = "<color=#e8d9bb>Zumbido...</color>",
  ui_story_1014_10141402_136_dialog_content = "Soroz acaba de recibir una señal de comunicación remota, y el remitente es... ¡Naviduz!",
  ui_story_1014_10141402_137_dialog_content = "<color=#e8d9bb>Tzzst...</color>",
  ui_story_1014_10141402_137X1_dialog_content = "<color=#e8d9bb>Según las órdenes de 35, este comando se ejecutará después de que Caelestite se vaya.</color>",
  ui_story_1014_10141402_138_dialog_content = "<color=#e8d9bb>Se han cumplido las condiciones para la solicitud. Naviduz está enviando una solicitud a Caelestite PlayerName.</color>",
  ui_story_1014_10141402_139_dialog_content = "¿El Coloso me está enviando una solicitud?",
  ui_story_1014_10141402_140_dialog_content = "<color=#e8d9bb>PlayerName de Caelestites ha obtenido la totalidad de los datos de Naviduz.</color>",
  ui_story_1014_10141402_141_dialog_content = "<color=#e8d9bb>El núcleo de energía de Naviduz está dañado y no se puede reparar. Todas las operaciones cesarán pronto.</color>",
  ui_story_1014_10141402_142_dialog_content = "<color=#e8d9bb>Según la orden de 35, cuando se cumplan las dos condiciones anteriores, Naviduz enviará una solicitud al Caelestite más cercano...</color>",
  ui_story_1014_10141402_143_dialog_content = "Puede ser...",
  ui_story_1014_10141402_144_dialog_content = "<color=#e8d9bb> Naviduz solicita que PlayerName <color=#FFB400>escriba un poema</color> para Naviduz.</color>",
  ui_story_1014_10141402_145_dialog_content = "...",
  ui_story_1014_10141402_146_dialog_content = "Entiendo.",
  ui_story_1014_10141402_147_dialog_content = "Pero nunca he escrito poesía antes, así que puede que no salga bien.",
  ui_story_1014_10141402_148_dialog_content = "Una vez viajaste con nosotros",
  ui_story_1014_10141402_149_dialog_content = "Un cielo estrellado sin límites, el viento bajo tus alas",
  ui_story_1014_10141402_150_dialog_content = "Un viaje de una longitud inconmensurable, que dura un tiempo inconmensurable",
  ui_story_1014_10141402_151_dialog_content = "Un viaje que duró hasta que incluso las estrellas se desvanecieron",
  ui_story_1014_10141402_152_dialog_content = "Hasta que solo quedó una estancia solitaria",
  ui_story_1014_10141402_153_dialog_content = "Cuando la llamada para volver finalmente hizo señas",
  ui_story_1014_10141402_154_dialog_content = "El camino de regreso a casa se perdió",
  ui_story_1014_10141402_155_dialog_content = "Habías estado a la deriva en los cielos durante demasiado tiempo",
  ui_story_1014_10141402_156_dialog_content = "Permaneció en la oscuridad durante demasiado tiempo",
  ui_story_1014_10141402_157_dialog_content = "El tiempo había borrado todo rastro de hogar",
  ui_story_1014_10141402_158_dialog_content = "Pero ahora el faro brilla una vez más",
  ui_story_1014_10141402_159_dialog_content = "Que tu conciencia siga los dientes de león en el viento",
  ui_story_1014_10141402_160_dialog_content = "Hasta que vuela de regreso a Eraveil",
  ui_story_1014_10141402_161_dialog_content = "...",
  ui_story_1014_10141402_162_dialog_content = "(Eso fue una porquería... No es sorprendente para alguien que nunca antes ha escrito poesía...)",
  ui_story_1014_10141402_163_dialog_content = "<color=#e8d9bb>Poema recibido. Reproduciendo grabación.</color>",
  ui_story_1014_10141402_164_dialog_content = "¡Gracias, buen samaritano del futuro!",
  ui_story_1014_10141402_165_dialog_content = "¡Esa es la voz de 35!",
  ui_story_1014_10141402_166_dialog_content = "Naviduz debe estar feliz de tener un poema que lo acompañe.",
  ui_story_1014_10141402_166X1_dialog_content = "Aunque nunca nos hemos conocido, creo que en este momento, nuestros corazones son uno.",
  ui_story_1014_10141402_166X2_dialog_content = "Incluso sin usar tu habilidad psíquica, ¡tú también lo sentirás!",
  ui_story_1014_10141402_166X3_dialog_content = "Sí, incluso sin mi habilidad psíquica. Este sentimiento de querer romper en llanto...",
  ui_story_1014_10141402_166X4_dialog_content = "No importa en manos de quién termine este regalo, espero sinceramente que encuentre innumerables amigos que lo acompañen en su viaje y que nunca esté solo.",
  ui_story_1014_10141402_166X5_dialog_content = "Deja que viaje contigo. ¡Esto es lo que Naviduz y yo queremos!",
  ui_story_1014_10141402_166X6_dialog_content = "Gracias. Gracias a los dos...",
  ui_story_1014_10141402_166X7_dialog_content = "Prometo usar bien tu don.",
  ui_story_1014_10141402_168_dialog_content = "Adiós, Naviduz.",
  ui_story_1014_10141402_169_dialog_content = "Adiós, 35.",
  ui_story_1014_10141501_1_dialog_content = "<color=#e8d9bb>Crepúsculo, algún tiempo después...</color>",
  ui_story_1014_10141501_2_dialog_content = "Solo aquí está bien.",
  ui_story_1014_10141501_3_dialog_content = "Gracias, PlayerName.",
  ui_story_1014_10141501_4_dialog_content = "Debería estar agradeciéndote por ayudarme.",
  ui_story_1014_10141501_5_dialog_content = "Bueno, entonces, adiós a todos.",
  ui_story_1014_10141501_6_dialog_content = "Fue un honor luchar junto a ti, pero debo irme ahora.",
  ui_story_1014_10141501_7_dialog_content = "Deseando volver a verte, PlayerName.",
  ui_story_1014_10141501_8_dialog_content = "Espera.",
  ui_story_1014_10141501_9_dialog_content = "¿Hay algo más, Knight Commander?",
  ui_story_1014_10141501_10_dialog_content = "Todavía no me has respondido sobre lo que es injusto.",
  ui_story_1014_10141501_11_dialog_content = "Jajaja. ¿Todavía estabas esperando una respuesta?",
  ui_story_1014_10141501_12_dialog_content = "Seré franco, entonces.",
  ui_story_1014_10141501_13_dialog_content = "Creo que Lumopolis necesita una reforma importante.",
  ui_story_1014_10141501_14_dialog_content = "¡Por qué tú...!",
  ui_story_1014_10141501_15_dialog_content = "Ya sabes que los títulos en Lumopolis son puramente hereditarios.",
  ui_story_1014_10141501_16_dialog_content = "Se dan debido a la línea de sangre, no a las habilidades, y se retienen por interés propio.",
  ui_story_1014_10141501_17_dialog_content = "Eso significa que es difícil para aquellos que son muy capaces pero no de noble cuna avanzar.",
  ui_story_1014_10141501_18_dialog_content = "Lumopolis necesita una reforma completa, y me gustaría ser yo quien la ponga en marcha.",
  ui_story_1014_10141501_19_dialog_content = "¿Te das cuenta de que podría enviarte al Salón de la Justicia por cargos de conspiración con lo que acabas de decir?",
  ui_story_1014_10141501_20_dialog_content = "jajaja Pero no creo, más bien, sé con seguridad que no harías eso.",
  ui_story_1014_10141501_21_dialog_content = "Aunque eres un noble, el poder no te ha cegado.",
  ui_story_1014_10141501_22_dialog_content = "Eres diferente de los típicos Lumo Noble en que eres un verdadero caballero bautizado por la guerra.",
  ui_story_1014_10141501_23_dialog_content = "Como un caballero, eso es palpable para mí.",
  ui_story_1014_10141501_24_dialog_content = "¿En serio?",
  ui_story_1014_10141501_25_dialog_content = "Entonces deseo que sigas esforzándote por realizar tus ambiciones.",
  ui_story_1014_10141501_26_dialog_content = "Demostremos a través de nuestras respectivas acciones cuál de nuestras elecciones es la mejor para Lumopolis.",
  ui_story_1014_10141501_27_dialog_content = "¡Es una promesa!",
  ui_story_1014_10141501_28_dialog_content = "¿De verdad va a dejarlo ir, Lady Carleen?",
  ui_story_1014_10141501_29_dialog_content = "Está bien, déjalo en paz.",
  ui_story_1014_10141501_30_dialog_content = "¿Significa esto que Joselyne... Oye, adónde fue Joselyne?",
  ui_story_1014_10141501_31_dialog_content = "Un transeúnte la llamó para que la ayudara.",
  ui_story_1014_10141501_32_dialog_content = "Cuando PlayerName estaba mirando a Carleen y Leo.",
  ui_story_1014_10141501_33_dialog_content = "Así es Joselyne, ella nunca rechaza una llamada de ayuda.",
  ui_story_1014_10141501_34_dialog_content = "Es una lástima que no tuvimos la oportunidad de despedirnos.",
  ui_story_1014_10141501_35_dialog_content = "Nos veremos otra vez.",
  ui_story_1014_10141501_36_dialog_content = "Yingel, Sean y yo también tenemos que irnos a casa.",
  ui_story_1014_10141501_37_dialog_content = "La misión ha sido completada.",
  ui_story_1014_10141501_38_dialog_content = "Eso es cierto, pero todavía tenemos que informar a nuestros superiores sobre Asmodeus.",
  ui_story_1014_10141501_39_dialog_content = "Aquí es donde nos separamos entonces, PlayerName, Teniente Vice, Lady Carleen, Miss Beretta.",
  ui_story_1014_10141501_40_dialog_content = "¡Encontrémonos de nuevo alguna vez!",
  ui_story_1014_10141501_41_dialog_content = "Tendrás mi ayuda, PlayerName.",
  ui_story_1014_10141501_42_dialog_content = "Oh sí, estamos participando en el próximo evento militar conjunto.",
  ui_story_1014_10141501_43_dialog_content = "¡Nos vemos en la simulación!",
  ui_story_1014_10141501_44_dialog_content = "¡Sí, deseando que llegue!",
  ui_story_1014_10141501_45_dialog_content = "Veremos quién sale ganando.",
  ui_story_1014_10141501_46_option_content = "¡Luego!",
  ui_story_1014_10141501_47_dialog_content = "Finalmente los llevamos de regreso a Twilight a salvo.",
  ui_story_1014_10141501_48_dialog_content = "Deberíamos apresurarnos a regresar a Gannon nosotros mismos.",
  ui_story_1014_10141501_49_dialog_content = "Si bien Asmodeus merece atención, la prioridad es arreglar a Soroz.",
  ui_story_1014_10141501_50_dialog_content = "Sí, no lo demoremos más.",
  ui_story_1014_10141501_51_dialog_content = "¡Vamos!",
  ui_story_1014_10141501_52_dialog_content = "<color=#e8d9bb>Gannon, algún tiempo después...</color>",
  ui_story_1014_10141501_53_dialog_content = "¡Tenemos los datos que necesitabas, Algol!",
  ui_story_1014_10141501_54_dialog_content = "Bueno. Esperar...",
  ui_story_1014_10141501_55_dialog_content = "¿Ya regresaste?",
  ui_story_1014_10141501_56_dialog_content = "Sí.",
  ui_story_1014_10141501_57_dialog_content = "Nos topamos con enemigos inesperados, pero logramos obtener los datos.",
  ui_story_1014_10141501_58_dialog_content = "Sí, escuché sobre ese extraño Espectro... <color=#FFB400>Asmodeus</color>, ¿verdad?",
  ui_story_1014_10141501_59_dialog_content = "¡¿Usted ya sabe?!",
  ui_story_1014_10141501_60_dialog_content = "No debería sorprenderme. Illumina tiene gente en Crepúsculo.",
  ui_story_1014_10141501_61_dialog_content = "Pase lo que pase, todo lo que se necesita es un mensaje y todo Gannon se entera.",
  ui_story_1014_10141501_62_dialog_content = "Algo en ese sentido. Nunca debes subestimar la red de Illumina.",
  ui_story_1014_10141501_63_dialog_content = "Pero el trabajo del Gran Mariscal es lidiar con los Espectros y los de su calaña.",
  ui_story_1014_10141501_64_dialog_content = "Solo quiero ver los datos que trajiste del Coloso.",
  ui_story_1014_10141501_65_dialog_content = "¿Cómo lo conseguiste, cuando tantos escuadrones regresaron con las manos vacías?",
  ui_story_1014_10141501_66_dialog_content = "Eso es porque...",
  ui_story_1014_10141501_67_option_content = "Soy un Celestita.",
  ui_story_1014_10141501_68_dialog_content = "La conciencia de Colossus nació del esfuerzo persistente de Caelestite.",
  ui_story_1014_10141501_69_dialog_content = "Simplemente heredé un regalo muy preciado, como la última Caelestite.",
  ui_story_1014_10141501_70_dialog_content = "Interesante. Entonces, ¿esto es lo que Caelestites heredan unos de otros?",
  ui_story_1014_10141501_71_option_content = "Ese lugar también fue un \"regalo\"",
  ui_story_1014_10141501_72_dialog_content = "El Coloso había estado esperando que alguien viniera y le pasara los valiosos datos que poseía.",
  ui_story_1014_10141501_73_dialog_content = "Tal como lo hizo el Maestro Francis en el Obelisco del Retorno.",
  ui_story_1014_10141501_74_dialog_content = "El Coloso incluso me pidió que escribiera un poema para él.",
  ui_story_1014_10141501_75_dialog_content = "¿Lo hizo? ¡Que fascinante!",
  ui_story_1014_10141501_76_dialog_content = "Muéstrame los datos.",
  ui_story_1014_10141501_77_dialog_content = "...",
  ui_story_1014_10141501_78_dialog_content = "Hmm, es más complicado de lo que pensaba.",
  ui_story_1014_10141501_79_dialog_content = "¿Qué quieres decir?",
  ui_story_1014_10141501_80_dialog_content = "¿Complicado? ¿Se puede arreglar Soroz?",
  ui_story_1014_10141501_81_dialog_content = "Desacelerar. Dejame explicar.",
  ui_story_1014_10141501_82_dialog_content = "Sabes que la conciencia del Coloso se formó a partir de los esfuerzos persistentes de cierta Caelestita.",
  ui_story_1014_10141501_83_dialog_content = "Cierto.",
  ui_story_1014_10141501_84_dialog_content = "En su intento, el Coloso sufrió cambios desconocidos cuando se enfrentó a situaciones fuera de sus circuitos lógicos.",
  ui_story_1014_10141501_85_dialog_content = "Por lo general, llamamos a estos cambios \"errores\", pero aquí me inclino más a llamarlo \"<color=#FFB400>crecimiento</color>.\"",
  ui_story_1014_10141501_86_dialog_content = "Pero como los cambios fueron inesperados...",
  ui_story_1014_10141501_87_dialog_content = "Se reflejan en los datos como variables complicadas y caóticas.",
  ui_story_1014_10141501_88_dialog_content = "Algunas de estas variables podrían ser inútiles, mientras que otras podrían ser clave para la conciencia de Colossus.",
  ui_story_1014_10141501_89_dialog_content = "Además, debido a que los datos son independientes entre Colossi, los cambios también son diferentes.",
  ui_story_1014_10141501_90_dialog_content = "Los datos que descargó no se pueden aplicar directamente a Soroz.",
  ui_story_1014_10141501_91_dialog_content = "No entiendo muy bien toda esta jerga.",
  ui_story_1014_10141501_92_dialog_content = "¡Solo quiero saber si Soroz se puede restaurar!",
  ui_story_1014_10141501_93_dialog_content = "Necesito algo de tiempo para analizar los datos en busca de una respuesta más específica.",
  ui_story_1014_10141501_94_dialog_content = "Los propios datos de Soroz no son suficientes, pero con estos nuevos datos en la mano, puedo hacer comparaciones cruzadas.",
  ui_story_1014_10141501_95_dialog_content = "Y eso aumenta considerablemente las probabilidades a nuestro favor.",
  ui_story_1014_10141501_96_dialog_content = "Espero que confíes en mí y me des tiempo.",
  ui_story_1014_10141501_97_dialog_content = "No es que tenga otra opción.",
  ui_story_1014_10141501_98_dialog_content = "No seas tan pesimista. Tengo mucha confianza en mi investigación de IA.",
  ui_story_1014_10141501_99_dialog_content = "Después de lo que has pasado, deberías descansar un poco.",
  ui_story_1014_10141501_100_dialog_content = "Es mi batalla ahora.",
  ui_story_1014_10141501_101_dialog_content = "¿Cómo va Soroz? PlayerName?",
  ui_story_1014_10141501_102_dialog_content = "¿Fueron útiles los datos?",
  ui_story_1014_10141501_103_dialog_content = "No estoy del todo seguro. Algol dijo que necesitaba algo de tiempo para resolverlo.",
  ui_story_1014_10141501_104_dialog_content = "Oh...",
  ui_story_1014_10141501_105_dialog_content = "Espero que vaya bien.",
  ui_story_1014_10141501_106_dialog_content = "Yo también.",
  ui_story_1014_10141501_107_dialog_content = "<color=#e8d9bb>Bip, bip, bip...</color>",
  ui_story_1014_10141501_108_dialog_content = "Teniente Vice, PlayerName, ¿estás ahí?",
  ui_story_1014_10141501_109_dialog_content = "¿Oficial Ulises?",
  ui_story_1014_10141501_110_dialog_content = "Avanzamos en nuestra investigación sobre Chord Link.",
  ui_story_1014_10141501_111_dialog_content = "Teniente Vice, preséntese en la ubicación designada con PlayerName. Te mando las coordenadas en un rato.",
  ui_story_1014_10141501_112_dialog_content = "Las coordenadas específicas son clasificadas y ninguna persona no autorizada debe acompañarlo.",
  ui_story_1014_10141501_113_dialog_content = "Por favor responda al recibir.",
  ui_story_1014_10141501_114_dialog_content = "Sí, copia del teniente antivicio.",
  ui_story_1014_10141501_115_dialog_content = "Muy bien. Sobre.",
  ui_story_1014_10141501_116_dialog_content = "¿Clasificado, otra vez? Supongo que he terminado aquí.",
  ui_story_1014_10141501_117_dialog_content = "Debería volver a Lumopolis de todos modos.",
  ui_story_1014_10141501_118_dialog_content = "Quiero saber más sobre los Caballeros de Ironthorn.",
  ui_story_1014_10141501_119_dialog_content = "Y actualice al Señor de la Ciudad sobre la situación en Crepúsculo.",
  ui_story_1014_10141501_120_dialog_content = "¿Sigues preocupada por esa gente, Carleen?",
  ui_story_1014_10141501_121_dialog_content = "Es imposible no hacerlo.",
  ui_story_1014_10141501_122_dialog_content = "Se trata de Lumopolis, por lo que es necesario averiguar más sobre ellos, especialmente sobre Leo, el Caballero de la Expedición.",
  ui_story_1014_10141501_123_dialog_content = "No estoy en desacuerdo con sus ideas. Podría hacer de Lumopolis un lugar mejor.",
  ui_story_1014_10141501_124_dialog_content = "Sin embargo, tampoco puedo pasar por alto el hecho de que él podría ser una amenaza potencial para Lumopolis.",
  ui_story_1014_10141501_125_dialog_content = "Tan meticulosa como siempre, Carleen.",
  ui_story_1014_10141501_126_dialog_content = "Vayamos a donde tenemos que ir ahora.",
  ui_story_1014_10141501_127_dialog_content = "Vamos.",
  ui_story_1014_10141501_128_dialog_content = "<color=#e8d9bb>En algún lugar de la Federación Illumina</color>",
  ui_story_1014_10141501_129_dialog_content = "¡¿Las coordenadas nos llevaron a una ciudad subterránea?!",
  ui_story_1014_10141501_130_dialog_content = "No está marcado en ningún mapa de Illumina.",
  ui_story_1014_10141501_131_dialog_content = "Es imposible encontrar este lugar sin las coordenadas.",
  ui_story_1014_10141501_132_dialog_content = "...",
  ui_story_1014_10141501_133_dialog_content = "Parece muy defendido.",
  ui_story_1014_10141501_134_dialog_content = "Es una instalación de alto secreto, no es tan sorprendente.",
  ui_story_1014_10141501_135_dialog_content = "Ahí tienes.",
  ui_story_1014_10141501_136_dialog_content = "(¿Este tipo otra vez?)",
  ui_story_1014_10141501_137_dialog_content = "(Es incómodo hablar con él, como si siempre te estuviera interrogando o algo así...)",
  ui_story_1014_10141501_138_dialog_content = "¿Qué estás haciendo aquí? ¿No fue Ulises quien nos llamó?",
  ui_story_1014_10141501_139_dialog_content = "Ese oficial tenía asuntos urgentes que tratar, así que me ordenó que los escoltara a ustedes dos.",
  ui_story_1014_10141501_140_dialog_content = "¿Qué es tan urgente que tuvimos que venir aquí en tan poco tiempo?",
  ui_story_1014_10141501_141_dialog_content = "Ya sabes mucho, así que seré comunicativo.",
  ui_story_1014_10141501_142_dialog_content = "Comencemos con la situación actual.",
  ui_story_1014_10141501_143_dialog_content = "El origen del Programa Phospherus en realidad está ligado a <color=#FFB400>otro enlace de acorde</color> eso es aquí",
  ui_story_1014_10141501_144_dialog_content = "¿Qué? ¿Hay más de un Chord Link?",
  ui_story_1014_10141501_145_dialog_content = "Así es. Illumina descubrió un Chord Link hace años.",
  ui_story_1014_10141501_146_dialog_content = "través de nuestros estudios, descubrimos cómo modificar aurorianos.",
  ui_story_1014_10141501_147_dialog_content = "Sin embargo, por varias razones, esta máquina no está tan intacta como su contraparte en Eraveil.",
  ui_story_1014_10141501_148_dialog_content = "El proceso de modificación desarrollado por Illumina es, por lo tanto, imperfecto debido a las partes defectuosas.",
  ui_story_1014_10141501_149_dialog_content = "Incluso hoy en día, no podemos controlar los resultados y el proceso tiene una alta tasa de fallas.",
  ui_story_1014_10141501_150_dialog_content = "Entonces, ¿por qué no detienes el proyecto?",
  ui_story_1014_10141501_151_dialog_content = "Sabes que es peligroso y puede hacer sufrir a la gente.",
  ui_story_1014_10141501_152_dialog_content = "Entonces, ¿por qué insistes en continuarlo?",
  ui_story_1014_10141501_153_dialog_content = "No me importa enfatizar nuevamente que la gran mayoría de la población de Illumina es promedio.",
  ui_story_1014_10141501_154_dialog_content = "Esta es la única manera de asegurar la supervivencia de Illumina.",
  ui_story_1014_10141501_155_option_content = "...",
  ui_story_1014_10141501_156_option_content = "no estoy de acuerdo con eso",
  ui_story_1014_10141501_157_dialog_content = "Entiendo cómo te sientes, pero no olvides que tenemos un acuerdo.",
  ui_story_1014_10141501_158_dialog_content = "Si no se siente cómodo, ciertamente tiene derecho a dejar de permitirnos el acceso para estudiar el Obelisco del Retorno.",
  ui_story_1014_10141501_159_dialog_content = "Aunque eso también detendrá la investigación sobre Chord Link y sus efectos secundarios.",
  ui_story_1014_10141501_160_dialog_content = "(¡Me está amenazando con Vice y Barton!)",
  ui_story_1014_10141501_161_dialog_content = "(Él sabe que tiene la sartén por el mango...)",
  ui_story_1014_10141501_162_dialog_content = "A juzgar por tu comportamiento, te has dado cuenta.",
  ui_story_1014_10141501_163_dialog_content = "¿Qué estás tratando de hacer ahora?",
  ui_story_1014_10141501_164_dialog_content = "Después de estudiar la máquina en el Obelisco, hicimos mejoras a nuestro Chord Link incompleto.",
  ui_story_1014_10141501_165_dialog_content = "Nos gustaría construir un modelo completo e impecable utilizando las piezas de trabajo de ambas máquinas.",
  ui_story_1014_10141501_166_dialog_content = "Creo que un Chord Link completo resolverá muchos problemas,",
  ui_story_1014_10141501_167_dialog_content = "como los misteriosos efectos secundarios que le ocurren al teniente Vice y al comandante Barton.",
  ui_story_1014_10141501_168_dialog_content = "... ¿Que necesitas que haga?",
  ui_story_1014_10141501_169_dialog_content = "Chord Link es tecnología Caelestite después de todo, por lo que ciertos datos solo se pueden descifrar con habilidades psíquicas.",
  ui_story_1014_10141501_170_dialog_content = "Estamos tratando de restaurar esos datos ahora. Necesitaremos sus servicios cuando termine.",
  ui_story_1014_10141501_171_dialog_content = "Solo necesitamos que estés en espera por el momento.",
  ui_story_1014_10141501_172_dialog_content = "(¿Me apuraron solo para decirme eso?)",
  ui_story_1014_10141501_173_dialog_content = "Bien, lo tengo.",
  ui_story_1014_10141501_174_dialog_content = "Gracias por su cooperación.",
  ui_story_1014_10141501_175_dialog_content = "Debo irme, todavía tengo mucho trabajo por hacer.",
  ui_story_1014_10141501_176_dialog_content = "No me gusta este sentimiento.",
  ui_story_1014_10141501_177_dialog_content = "Es como si fuera una herramienta que están usando para llegar a ti.",
  ui_story_1014_10141501_178_dialog_content = "No pienses en ti de esa manera.",
  ui_story_1014_10141501_179_dialog_content = "No puedo deshacerme de sus efectos secundarios sin su ayuda.",
  ui_story_1014_10141501_180_dialog_content = "PlayerName...",
  ui_story_1014_10141501_181_dialog_content = "Puedes ignorar mi condición.",
  ui_story_1014_10141501_182_dialog_content = "Aparte del brillo ocasional, me siento bien.",
  ui_story_1014_10141501_183_dialog_content = "Así que está bien no recibir ayuda de ellos. Encontraremos una manera de lidiar con eso.",
  ui_story_1014_10141501_184_dialog_content = "No quiero verte hacer lo que no quieres hacer, PlayerName.",
  ui_story_1014_10141501_185_option_content = "Gracias, Vice.",
  ui_story_1014_10141501_186_dialog_content = "Pero no renunciaré a resolver estos problemas.",
  ui_story_1014_10141501_187_option_content = "No te dejaré solo",
  ui_story_1014_10141501_188_dialog_content = "Soroz me enseñó desde muy joven a apreciar a todos los amigos.",
  ui_story_1014_10141501_189_dialog_content = "Nunca dejaría a un amigo en peligro y no haría nada al respecto.",
  ui_story_1014_10141501_190_dialog_content = "...",
  ui_story_1014_10141501_191_dialog_content = "(Oh chico, el estado de ánimo se volvió intenso de repente...)",
  ui_story_1014_10141501_192_dialog_content = "Dime, ¿quieres dar un paseo y matar el tiempo?",
  ui_story_1014_10141501_193_dialog_content = "No estamos haciendo nada en este momento, de todos modos. Tampoco mencionaron cuándo seríamos necesarios.",
  ui_story_1014_10141501_194_dialog_content = "Sí, estoy seguro de que estaría bien.",
  ui_story_1014_10141501_195_dialog_content = "(Esta ciudad subterránea es enorme...)",
  ui_story_1014_10141501_196_dialog_content = "(Casi todas las habitaciones en los pasajes son laboratorios).",
  ui_story_1014_10141501_197_dialog_content = "(Me pregunto cuántos experimentos secretos se llevaron a cabo en estos laboratorios...)",
  ui_story_1014_10141501_198_dialog_content = "Debo rechazar su solicitud.",
  ui_story_1014_10141501_199_dialog_content = "Ese dispositivo aún se encuentra en su etapa experimental. Además, su sujeto aún no es estable.",
  ui_story_1014_10141501_200_dialog_content = "Es muy probable que someter al sujeto a ese experimento arruine la preciosa máquina.",
  ui_story_1014_10141501_201_dialog_content = "Y no se garantiza que una máquina incompleta cure el tema.",
  ui_story_1014_10141501_202_dialog_content = "Este es mi proyecto, no hay lugar para tu opinión.",
  ui_story_1014_10141501_203_dialog_content = "Todo lo que necesita hacer es autorizarme a usar el aparato y mantener la boca cerrada.",
  ui_story_1014_10141501_204_dialog_content = "Creo que escucho a alguien hablando en la distancia.",
  ui_story_1014_10141501_205_dialog_content = "Esa voz me suena familiar...",
  ui_story_1014_10141501_206_dialog_content = "No estoy de acuerdo.",
  ui_story_1014_10141501_207_dialog_content = "Las máquinas preciosas no son juguetes con los que jugar, sin mencionar...",
  ui_story_1014_10141501_208_dialog_content = "Ya no tienes autorización para hacerme tales demandas.",
  ui_story_1014_10141501_209_dialog_content = "Ahí vas con eso otra vez.",
  ui_story_1014_10141501_210_dialog_content = "Tú das autorización y te la quitas cuando te conviene.",
  ui_story_1014_10141501_211_dialog_content = "Cuando comencé a trabajar contigo, tuve que obtener innumerables resultados para obtener la autorización para acceder a todo aquí.",
  ui_story_1014_10141501_212_dialog_content = "Pero ahora, quitas todas mis contribuciones así como así.",
  ui_story_1014_10141501_213_dialog_content = "Solo obtienes lo que te mereces.",
  ui_story_1014_10141501_214_dialog_content = "Eso suena como... <color=#FFB400>Abandonado</color>!",
  ui_story_1014_10141501_215_dialog_content = "¿Está reteniendo a alguien como rehén?",
  ui_story_1014_10141501_216_dialog_content = "¡Vamos a echar un vistazo!",
  ui_story_1014_10141501_217_dialog_content = "Muy pocos investigadores pueden luchar. ¡Estarían en problemas si Forsakin los atrapara!",
  ui_story_1014_10141501_218_dialog_content = "¡Congela, déjalo ir!",
  ui_story_1014_10141501_219_dialog_content = "(¡Es Forsakin! ¿Pero cómo es que no sentí su presencia?)",
  ui_story_1014_10141501_220_dialog_content = "(Espera, ella no está reteniendo al investigador como rehén...)",
  ui_story_1014_10141501_221_dialog_content = "(¡Se dio la vuelta y corrió!)",
  ui_story_1014_10141501_222_dialog_content = "¡Qué sorpresa! El <color=#FFB400>material de experimentación</color> ¡Necesitaba vino solo!",
  ui_story_1014_10141501_223_dialog_content = "¡Abandonado! ¿Qué estás haciendo aquí y por qué estabas abordando al investigador?",
  ui_story_1014_10141501_224_dialog_content = "Yo no abordé a nadie.",
  ui_story_1014_10141501_225_dialog_content = "Solo estoy aquí para recuperar algunas de las cosas que dejé atrás.",
  ui_story_1014_10141501_226_dialog_content = "Pero como me ha llegado el material, ¡lo aceptaré con mucho gusto!",
  ui_story_1014_10141501_227_dialog_content = "Pato, PlayerName! ¡Detrás de ti!",
  ui_story_1014_10141501_228_dialog_content = "¿Qué?",
  ui_story_1014_10141501_229_dialog_content = "<anim type=Shake><size=50>¡Rugido!</size></anim>",
  ui_story_1014_10141501_230_dialog_content = "¡Uh!",
  ui_story_1014_10141501_231_dialog_content = "Se siente como si estuviera noqueado por mucho tiempo...",
  ui_story_1014_10141501_232_dialog_content = "Creo recordar haberme topado con Forsakin hablando con alguien, entonces...",
  ui_story_1014_10141501_233_dialog_content = "¡Vicio! ¿Estás bien, Vice?",
  ui_story_1014_10141501_234_dialog_content = "Y... ¿Renegados?",
  ui_story_1014_10141501_235_dialog_content = "Nos encontramos de nuevo, Caelestite.",
  ui_story_1014_10141501_236_dialog_content = "Haz lo que te digo si no quieres que la lastimen.",
  ui_story_1014_10141501_237_dialog_content = "...",
  ui_story_1014_10141501_238_dialog_content = "¿Que estás tratando de hacer? ¡Déjala ir!",
  ui_story_1014_10141501_239_dialog_content = "Solo déjala ir, y yo iré contigo.",
  ui_story_1014_10141501_240_dialog_content = "Tal vez no entiendas la situación.",
  ui_story_1014_10141501_241_dialog_content = "Como sujeto, no está autorizado para hacer demandas.",
  ui_story_1014_10141501_242_dialog_content = "Especialmente eso...",
  ui_story_1014_10141501_243_dialog_content = "Ambos son necesarios para el experimento.",
  ui_story_1015_10150101_1_dialog_content = "¡Cau, cau!",
  ui_story_1015_10150101_2_dialog_content = "Pronto oscurecerá.",
  ui_story_1015_10150101_3_dialog_content = "Bien. Vamos a movernos.",
  ui_story_1015_10150101_4_dialog_content = "<color=#e8d9bb>*Pasos*</color>",
  ui_story_1015_10150101_5_dialog_content = "Escucha atentamente, Caelestite.",
  ui_story_1015_10150101_6_dialog_content = "A partir de este momento, debes seguir mis instrucciones al pie de la letra.",
  ui_story_1015_10150101_7_dialog_content = "Ni siquiera pienses en buscar ayuda, resistirte o hacer cualquier movimiento precipitado.",
  ui_story_1015_10150101_8_dialog_content = "Realizaré una investigación muy importante y necesitaré su ayuda.",
  ui_story_1015_10150101_9_dialog_content = "¿Estás planeando implantar algo en mi cuerpo de nuevo?",
  ui_story_1015_10150101_10_dialog_content = "Entonces, todavía recuerdas nuestro último pequeño proyecto.",
  ui_story_1015_10150101_11_dialog_content = "¿Cómo podría olvidar? ¡Casi me transformas en una de esas cosas!",
  ui_story_1015_10150101_12_dialog_content = "Casi, de hecho. Fue una pena que las cosas no salieran como esperaba.",
  ui_story_1015_10150101_13_dialog_content = "Fue intrascendente, pero estaba bastante interesado en ver qué habría pasado si tú y Schummer fueran parientes una vez más...",
  ui_story_1015_10150101_14_dialog_content = "Debería haber sido entretenido.",
  ui_story_1015_10150101_15_dialog_content = "¿Inconsecuente? ¿Qué pasa con los demás? Qué pasa Eve, Dawn, y todo lo demás? ¿Fue \"inconsecuente\" lo que les sucedió?",
  ui_story_1015_10150101_16_dialog_content = "¡¿Qué has hecho?! Por que lo harias-",
  ui_story_1015_10150101_17_dialog_content = "Estás haciendo que me duelan los oídos.",
  ui_story_1015_10150101_18_dialog_content = "Vosotros Caelestitas... Vuestras voces parecen hacerse más fuertes por segundos. ¿Qué tal si te corto las cuerdas vocales?",
  ui_story_1015_10150101_19_dialog_content = "Después de todo, ni siquiera necesitas tu voz para comunicarte, ¿verdad?",
  ui_story_1015_10150101_20_dialog_content = "...",
  ui_story_1015_10150101_21_dialog_content = "Tú eres el que tiene que callarse...",
  ui_story_1015_10150101_22_dialog_content = "Lo que estoy tratando de decir aquí es, cuida tu boca, Caelestite.",
  ui_story_1015_10150101_23_dialog_content = "Sé un niño obediente y haz exactamente lo que te pido. No tengo tiempo ni ganas de negociar contigo.",
  ui_story_1015_10150101_24_dialog_content = "Mientras el experimento se desarrolle sin problemas, tú y Vice todavía puede tener una oportunidad de sobrevivir.",
  ui_story_1015_10150101_25_dialog_content = "... ¿Y si el experimento no sale bien?",
  ui_story_1015_10150101_26_dialog_content = "Sus vidas deberían ser más que suficientes para pagar el precio del fracaso.",
  ui_story_1015_10150101_27_dialog_content = "...",
  ui_story_1015_10150101_28_dialog_content = "¿Estás tratando de usar nuestras vidas para amenazarnos?",
  ui_story_1015_10150101_29_dialog_content = "No soy tan tonto como para creer en las promesas hechas por el Eclipse.",
  ui_story_1015_10150101_30_dialog_content = "Incluso si el experimento tiene éxito, nos matarás de todos modos.",
  ui_story_1015_10150101_31_dialog_content = "Matarte realmente no me beneficiará de ninguna manera.",
  ui_story_1015_10150101_32_dialog_content = "Tengo ante mí la última Caelestite superviviente y un producto exitoso de Chord Link.",
  ui_story_1015_10150101_33_dialog_content = "Ustedes dos son especímenes invaluables. Si tuviera la oportunidad, preferiría llevarlos de regreso a mi laboratorio que terminar con sus vidas prematuramente.",
  ui_story_1015_10150101_34_dialog_content = "Pero desafortunadamente, no tengo tales libertades dentro de las fronteras de Illumina.",
  ui_story_1015_10150101_35_dialog_content = "Por lo tanto, prometo darte al menos la oportunidad de salir de aquí con vida.",
  ui_story_1015_10150101_36_dialog_content = "No como un gran gesto de misericordia, por supuesto, sino por el bien de futuras oportunidades de investigación.",
  ui_story_1015_10150101_37_dialog_content = "Tú...",
  ui_story_1015_10150101_38_dialog_content = "La investigación parece ser lo único que importa en tu mente.",
  ui_story_1015_10150101_39_dialog_content = "Por supuesto. Personalmente, no veo qué más en la vida podría valer la pena molestarse.",
  ui_story_1015_10150101_40_dialog_content = "Hablemos del próximo experimento. Podría hacer las cosas un poco más fáciles si sabe qué esperar.",
  ui_story_1015_10150101_41_dialog_content = "¡Oye, ni siquiera hemos acordado cumplir contigo!",
  ui_story_1015_10150101_42_dialog_content = "Realmente no tienes elección.",
  ui_story_1015_10150101_43_dialog_content = "...",
  ui_story_1015_10150101_44_dialog_content = "Estoy investigando métodos para estimular la metamorfosis en el cuerpo auroriano.",
  ui_story_1015_10150101_45_dialog_content = "Mi objetivo es convertir a los Aurorianos en una especie más avanzada sin sacrificar las habilidades que ya tienen.",
  ui_story_1015_10150101_46_dialog_content = "... Suenas loco.",
  ui_story_1015_10150101_47_dialog_content = "Has usado el Chord Link que los caelestitas dejaron antes. Piensa por un momento, y deberías ser capaz de entender.",
  ui_story_1015_10150101_48_dialog_content = "Tiene tal potencial.",
  ui_story_1015_10150101_49_dialog_content = "¿Quieres hacer algo con Chord Link?",
  ui_story_1015_10150101_50_dialog_content = "Sí, por eso estoy aquí.",
  ui_story_1015_10150101_51_dialog_content = "Debes saber que Illumina excavó un enlace de cuerda escondido aquí en Entrañas, ¿correcto?",
  ui_story_1015_10150101_52_dialog_content = "Sí, lo sabemos...",
  ui_story_1015_10150101_53_dialog_content = "Este equipo es de suma importancia para mi investigación.",
  ui_story_1015_10150101_54_dialog_content = "Necesito usarlo para experimentos, recopilar datos y encontrar el uso más adecuado para Chord Link.",
  ui_story_1015_10150101_55_dialog_content = "Si es posible, deseo crear formas de vida superiores a los aurorianos.",
  ui_story_1015_10150101_56_dialog_content = "T-quieres transformarte Vice para tu experimento?!",
  ui_story_1015_10150101_57_dialog_content = "Hah, mis esperanzas para ella no son tan altas. Vice solo servirá como muestra para medir datos experimentales. Ella no estará involucrada en la transformación final.",
  ui_story_1015_10150101_58_dialog_content = "Él será el primero en recibir este honor.",
  ui_story_1015_10150101_59_dialog_content = "...",
  ui_story_1015_10150101_60_dialog_content = "Oh...",
  ui_story_1015_10150101_61_dialog_content = "(¿Forsakin lo salvó solo por el bien de este experimento?)",
  ui_story_1015_10150101_62_dialog_content = "(O tal vez al revés, el verdadero propósito de esta investigación es en realidad salvarlo...)",
  ui_story_1015_10150101_63_dialog_content = "Sin embargo, si mi investigación va bien, también te beneficiarás.",
  ui_story_1015_10150101_64_dialog_content = "He visto los datos en Illumina. Vice parecía exhibir ciertos efectos secundarios después de ser mejorado por Chord Link, ¿correcto?",
  ui_story_1015_10150101_65_dialog_content = "¿Cómo conseguiste tus manos en esos datos?",
  ui_story_1015_10150101_66_dialog_content = "¡Eso no es de tu interés!",
  ui_story_1015_10150101_67_dialog_content = "Una vez que complete mi investigación, es posible que estos efectos secundarios puedan eliminarse utilizando Chord Link.",
  ui_story_1015_10150101_68_dialog_content = "Entonces, como puede ver, esta es realmente una situación en la que todos ganan.",
  ui_story_1015_10150101_69_dialog_content = "... ¿Crees que puedes persuadirnos para que cumplamos tan fácilmente?",
  ui_story_1015_10150101_70_dialog_content = "Realmente no creo que necesite persuadirte. Ayudarme es la única manera de que puedas salir de esto con vida.",
  ui_story_1015_10150101_71_dialog_content = "Simplemente estaba declarando un hecho, que esta investigación puede ser de beneficio para usted.",
  ui_story_1015_10150101_72_dialog_content = "Bien bien. Como dijiste, no tenemos elección.",
  ui_story_1015_10150101_73_dialog_content = "Pero no entiendo. ¿En qué exactamente quieres que te ayudemos?",
  ui_story_1015_10150101_74_dialog_content = "Necesito que me ayudes a eliminar algunos obstáculos que bloquean el camino de mi investigación.",
  ui_story_1015_10150101_75_dialog_content = "Mi investigación requiere equipo y datos. Ambos están en las garras de Illumina.",
  ui_story_1015_10150101_76_dialog_content = "Pero obviamente, nunca le darían acceso a un extraño.",
  ui_story_1015_10150101_77_dialog_content = "<color=#e8d9bb>borde crepuscular</color>",
  ui_story_1015_10150101_78_dialog_content = "¡Date prisa, lleva al caballero herido primero!",
  ui_story_1015_10150101_79_dialog_content = "¡Sí señor!",
  ui_story_1015_10150101_80_dialog_content = "Haz lo que puedas por los heridos de Illumina también. Están aún más cortos de personal que nosotros.",
  ui_story_1015_10150101_81_dialog_content = "gracias capitán Leo...",
  ui_story_1015_10150101_82_dialog_content = "No hay necesidad de agradecerme. Todos estamos peleando la misma batalla.",
  ui_story_1015_10150101_83_dialog_content = "No tenía idea de que hoy nos enfrentaríamos a un enemigo tan fuerte. Hemos sufrido bajas considerables...",
  ui_story_1015_10150101_84_dialog_content = "Todo es mi culpa. No soy lo suficientemente bueno para servir como comandante...",
  ui_story_1015_10150101_85_dialog_content = "Deja de culparte a ti mismo. Cuando te enfrentas a un enemigo tan poderoso, la pérdida es inevitable.",
  ui_story_1015_10150101_86_dialog_content = "Y de alguna manera creo que nuestras pérdidas de hoy fueron inevitables.",
  ui_story_1015_10150101_87_dialog_content = "¿Por qué dices eso?",
  ui_story_1015_10150101_88_dialog_content = "Algo parece extraño en estas incursiones en Crepúsculo.",
  ui_story_1015_10150101_89_dialog_content = "En los últimos días, la ciudad ha sido blanco de varios ataques consecutivos a gran escala.",
  ui_story_1015_10150101_90_dialog_content = "Esto me parece extraño. El enemigo nunca ha estado tan activo.",
  ui_story_1015_10150101_91_dialog_content = "¿Estás diciendo que los Eclipsites están planeando algo grande?",
  ui_story_1015_10150101_92_dialog_content = "No estoy seguro, pero sería prudente prepararse con anticipación.",
  ui_story_1015_10150101_93_dialog_content = "Sean, escuché que tu jefe regresó recientemente. ¿Es eso correcto?",
  ui_story_1015_10150101_94_dialog_content = "Sí, regresó no hace mucho.",
  ui_story_1015_10150101_95_dialog_content = "Déjame tomarlo prestado por un tiempo. Solo dile que lo recogeré en el lugar de siempre.",
  ui_story_1015_10150101_96_dialog_content = "¡Bienvenido! ¿Mesa para uno?",
  ui_story_1015_10150101_97_dialog_content = "Estoy buscando a alguien.",
  ui_story_1015_10150101_98_dialog_content = "No todos los días me invitan a cenar los más famosos de Crepúsculo.",
  ui_story_1015_10150101_99_dialog_content = "Tome asiento y profundice.",
  ui_story_1015_10150101_100_dialog_content = "No gracias, ya he comido.",
  ui_story_1015_10150101_101_dialog_content = "¡Aun mejor! Pásame tu plato.",
  ui_story_1015_10150101_102_dialog_content = "Creo que sería más apropiado mantenerlo frente a mí. Después de todo, esta es mi cena de bienvenida a casa.",
  ui_story_1015_10150101_103_dialog_content = "Asumo que me pediste algo más importante que una comida.",
  ui_story_1015_10150101_104_dialog_content = "Por supuesto, nunca le pediría a alguien que me acompañe simplemente con el propósito de verme llenarme la boca.",
  ui_story_1015_10150101_105_dialog_content = "¿Has leído los informes de bajas de Illumina de los últimos días?",
  ui_story_1015_10150101_106_dialog_content = "Tengo. Las cifras son bastante anormales.",
  ui_story_1015_10150101_107_dialog_content = "La guarnición Illumina de Twilight nunca ha experimentado pérdidas tan concentradas.",
  ui_story_1015_10150101_108_dialog_content = "La intensidad de los combates de los últimos días ha llegado a un punto crítico. Estamos al límite de lo que somos capaces de soportar.",
  ui_story_1015_10150101_109_dialog_content = "Lo más desconcertante no es el grado de bajas en las que hemos incurrido, sino que hasta ahora no hemos podido derrotar decisivamente al enemigo.",
  ui_story_1015_10150101_110_dialog_content = "Cada batalla ha resultado en la retirada de ambos lados después de un punto muerto.",
  ui_story_1015_10150101_111_dialog_content = "Claramente, no hemos sido capaces de averiguar la fuerza de las fuerzas de nuestro enemigo.",
  ui_story_1015_10150101_112_dialog_content = "El peor de los casos es que todos estos encuentros sean, de hecho, grupos independientes de eclipses.",
  ui_story_1015_10150101_113_dialog_content = "Si convergen para asediar a Crepúsculo, las consecuencias serán incalculables.",
  ui_story_1015_10150101_114_dialog_content = "Bien dicho. Es tan refrescante escuchar los pensamientos de una mente inteligente.",
  ui_story_1015_10150101_115_dialog_content = "¿Ha elaborado una estrategia para hacer frente a la situación?",
  ui_story_1015_10150101_116_dialog_content = "Desplegué tropas para realizar un reconocimiento encubierto en un intento de comprender completamente los movimientos del enemigo.",
  ui_story_1015_10150101_117_dialog_content = "Pero en mi opinión, nuestra fuerza militar actual es insuficiente para mantener nuestro dominio sobre Crepúsculo.",
  ui_story_1015_10150101_118_dialog_content = "Es por eso que voy a enviar una solicitud de refuerzos.",
  ui_story_1015_10150101_119_dialog_content = "Hmm... Sí, esta es la opción más segura.",
  ui_story_1015_10150101_120_dialog_content = "Querías verme con respecto a este asunto, así que asumo que tienes la intención de asegurarte la ayuda de Illumina, ¿correcto?",
  ui_story_1015_10150101_121_dialog_content = "Eso sí, aún no sabemos a cuántos enemigos debemos enfrentarnos en el futuro.",
  ui_story_1015_10150101_122_dialog_content = "Sería bastante miope dejar que las diferencias de Lumopolis e Illumina se interpongan entre nosotros en este momento, ¿no es así?",
  ui_story_1015_10150101_123_dialog_content = "Entiendo. Enviaré el mensaje tan pronto como regrese.",
  ui_story_1015_10150101_124_dialog_content = "Bien, cuanto antes mejor. Lo que más nos falta ahora mismo es tiempo.",
  ui_story_1015_10150101_125_dialog_content = "Tengo el presentimiento de que la situación que hemos previsto muy probablemente se hará realidad muy pronto.",
  ui_story_1015_10150101_126_dialog_content = "<color=#e8d9bb>Lumopolis, Corte Real</color>",
  ui_story_1015_10150101_127_dialog_content = "Suspiro...",
  ui_story_1015_10150101_128_dialog_content = "Carleen, ¿has terminado tu informe?",
  ui_story_1015_10150101_129_dialog_content = "Sí.",
  ui_story_1015_10150101_130_dialog_content = "Pareces un poco cansado.",
  ui_story_1015_10150101_131_dialog_content = "Hablar con él es una tarea agotadora.",
  ui_story_1015_10150101_132_dialog_content = "Creo que es una pérdida de tiempo. Lo que él quiere oír no tiene casi nada que ver con lo que yo quiero decir.",
  ui_story_1015_10150101_133_dialog_content = "Estás hablando del asunto Crepúsculo, ¿sí?",
  ui_story_1015_10150101_134_dialog_content = "Sí. No entiendo por qué sigue haciendo esas preguntas sobre la asignación de recursos y la estructura organizativa.",
  ui_story_1015_10150101_135_dialog_content = "Claramente, los hechos que le informé son—",
  ui_story_1015_10150101_136_dialog_content = "Olvídalo. No debería quejarme de esas cosas.",
  ui_story_1015_10150101_137_dialog_content = "Sí, eso es suficiente de eso. Ahora, vamos a tomar un poco de té.",
  ui_story_1015_10150101_138_dialog_content = "¿Tienes algún plan para los próximos días?",
  ui_story_1015_10150101_139_dialog_content = "Poco. El Señor de la Ciudad me pidió que permaneciera en espera en Lumopolis.",
  ui_story_1015_10150101_140_dialog_content = "¿En modo de espera? Oh, es cierto, es porque el <color=#FFB400>Ejercicio militar conjunto</color> se acerca rápidamente, ¿no?",
  ui_story_1015_10150101_141_dialog_content = "Sí, debería serlo.",
  ui_story_1015_10150101_142_dialog_content = "Deberías prepararte. Eres la estrella del espectáculo, lo sabes.",
  ui_story_1015_10150101_143_dialog_content = "Pero... me siento algo inquieto en este momento.",
  ui_story_1015_10150101_144_dialog_content = "¿Qué pasa?",
  ui_story_1015_10150101_145_dialog_content = "Todavía tengo que recibir noticias de PlayerName.",
  ui_story_1015_10150101_146_dialog_content = "no sé cómo él y Vice estás haciendo...",
  ui_story_1015_10150101_147_dialog_content = "Oh, es Carleen! ¡Ha sido tan largo!",
  ui_story_1015_10150101_148_dialog_content = "De hecho, ha pasado un tiempo, Gronru. Espero no haberte molestado con mi repentina llamada.",
  ui_story_1015_10150101_149_dialog_content = "No, llamaste en el momento justo.",
  ui_story_1015_10150101_150_dialog_content = "Acabo de hacer un gran avance en mi trabajo en Soroz.",
  ui_story_1015_10150101_151_dialog_content = "Escucha esto.",
  ui_story_1015_10150101_152_dialog_content = "¡Actívate, Soroz!",
  ui_story_1015_10150101_153_dialog_content = "Activación de Soroz completa.",
  ui_story_1015_10150101_154_dialog_content = "¡¿Se enteró que?!",
  ui_story_1015_10150101_155_dialog_content = "Lo escuché, pero... ¿Soroz no ha podido activarse siempre sin incidentes?",
  ui_story_1015_10150101_156_dialog_content = "¡Sé que sé! Siempre hemos podido volarlo, pero antes no poseía conciencia, ¿verdad?",
  ui_story_1015_10150101_157_dialog_content = "Cierto.",
  ui_story_1015_10150101_158_dialog_content = "No se preocupe, su plantilla de eco básicamente ha sido restaurada.",
  ui_story_1015_10150101_159_dialog_content = "Es solo que los aurorianos no podemos comunicarnos con él directamente.",
  ui_story_1015_10150101_160_dialog_content = "Pero solo espera PlayerName volver, ¡entonces podrá hablar con Soroz!",
  ui_story_1015_10150101_161_dialog_content = "¡Oh, es cierto! En realidad quería preguntarte qué está pasando con PlayerName... y Vice, ¡por supuesto!",
  ui_story_1015_10150101_162_dialog_content = "¿Qué pasó con ellos después de que los vi por última vez?",
  ui_story_1015_10150101_163_dialog_content = "No me han contactado desde que regresé a Lumopolis.",
  ui_story_1015_10150101_164_dialog_content = "Bueno, he visto sus informes.",
  ui_story_1015_10150101_165_dialog_content = "Dijeron que entraron en una Ciudad Subterránea secreta para recuperarse y pueden verse obligados a oscurecerse por un tiempo.",
  ui_story_1015_10150101_166_dialog_content = "Probablemente se comunicarán contigo cuando estén de vuelta con toda su fuerza.",
  ui_story_1015_10150101_167_dialog_content = "¿Una ciudad secreta secreta?",
  ui_story_1015_10150101_168_dialog_content = "Sí. No te preocupes, el nivel de confidencialidad allí es bastante alto.",
  ui_story_1015_10150101_169_dialog_content = "Creo que el nombre era...",
  ui_story_1015_10150101_170_dialog_content = "Oh sí, es <color=#FFB400>Instituto X</color>.",
  ui_story_1015_10150101_171_dialog_content = "<color=#e8d9bb>Estación de tren de la ciudad de Gannon</color>",
  ui_story_1015_10150101_172_dialog_content = "¡Apartese del camino! ¡No puedo ver nada desde aquí atrás!",
  ui_story_1015_10150101_173_dialog_content = "Oye, ¿no te parece un poco torcido?",
  ui_story_1015_10150101_174_dialog_content = "¡Así es! ¡Cuelga nuestra bandera un poco más arriba!",
  ui_story_1015_10150101_175_dialog_content = "¿Cuál es la conmoción aquí? ¿Qué están mirando todos?",
  ui_story_1015_10150101_176_dialog_content = "¿No sabes? El Ejercicio Militar Conjunto está a punto de comenzar. Esas son las banderas de las diversas fuerzas participantes que ondean adelante.",
  ui_story_1015_10150101_177_dialog_content = "¡Oh! Es hora del Ejercicio Militar Conjunto nuevamente.",
  ui_story_1015_10150101_178_dialog_content = "El ejercicio de este año debería ser bastante interesante. Los periódicos han estado haciendo fila en el mostrador de recepción todos los días en masa.",
  ui_story_1015_10150101_179_dialog_content = "¿En realidad? ¿Hay algo particularmente especial sobre el ejercicio militar de este año?",
  ui_story_1015_10150101_180_dialog_content = "Por supuesto. Esta vez habrá un participante de Caelestite, por primera vez en más de una década.",
  ui_story_1015_10150101_181_dialog_content = "<color=#e8d9bb>Departamento de inteligencia de la ciudad de Gannon</color>",
  ui_story_1015_10150101_182_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc. </color>",
  ui_story_1015_10150101_183_dialog_content = "Pasa adelante...",
  ui_story_1015_10150101_184_dialog_content = "Coronel Yingel, hay un telegrama urgente para ti.",
  ui_story_1015_10150101_185_dialog_content = "Por favor, eche un vistazo a su primera conveniencia.",
  ui_story_1015_10150101_186_dialog_content = "¿Un telegrama urgente?",
  ui_story_1015_10150101_187_dialog_content = "Bien, ya veo. Solo déjalo en mi escritorio.",
  ui_story_1015_10150101_188_dialog_content = "¡Sí, señora!",
  ui_story_1015_10150101_189_dialog_content = "A ver de quién puede ser este pedido urgente...",
  ui_story_1015_10150101_190_dialog_content = "¿Mmm? Señor Ulises?",
  ui_story_1015_10150201_1_dialog_content = "Apresúrate. Deja de holgazanear.",
  ui_story_1015_10150201_2_dialog_content = "Será mejor que camines más rápido que mi cuchillo, si sabes lo que te conviene.",
  ui_story_1015_10150201_3_dialog_content = "...Okey.",
  ui_story_1015_10150201_4_dialog_content = "Pero realmente, ¿tenemos que levantarnos tan temprano todos los días?",
  ui_story_1015_10150201_5_dialog_content = "No he tenido una buena noche de sueño en mucho tiempo.",
  ui_story_1015_10150201_6_dialog_content = "Claramente, más de una década de holgazanear te ha convertido en un mocoso malcriado quejumbroso.",
  ui_story_1015_10150201_7_dialog_content = "Nuestro horario no es gratuitamente severo. Como puede ver, los guardias ya se despertaron para sus turnos.",
  ui_story_1015_10150201_8_dialog_content = "*Suspiro* ¿Cuánto tiempo durará esto?",
  ui_story_1015_10150201_9_dialog_content = "Tenemos un plazo claro.",
  ui_story_1015_10150201_10_dialog_content = "Seguro que lo has oído: Illumina se está preparando para un evento llamado Ejercicio militar conjunto. Ambos recibirán una invitación.",
  ui_story_1015_10150201_11_dialog_content = "Si no estás presente cuando comience el evento, Illumina definitivamente enviará a alguien para causar problemas.",
  ui_story_1015_10150201_12_dialog_content = "Entonces, esa es nuestra fecha límite.",
  ui_story_1015_10150201_13_dialog_content = "(¡Correcto, el Ejercicio Militar Conjunto! ¿Será eso lo que nos salve aquí?)",
  ui_story_1015_10150201_14_dialog_content = "La buena noticia para ti es que este secuestro no durará mucho.",
  ui_story_1015_10150201_15_dialog_content = "La mala noticia es que, si el experimento no se completa con éxito dentro de la fecha límite, sus vidas serán significativamente más cortas de lo que esperaban.",
  ui_story_1015_10150201_16_dialog_content = "...",
  ui_story_1015_10150201_17_dialog_content = "No pierdas mi tiempo. De esa manera, pueden mantenerse con vida.",
  ui_story_1015_10150201_18_dialog_content = "¡Oye, deja de presionarme! ¡Conozco el camino!",
  ui_story_1015_10150201_19_dialog_content = "Ya he estado en el laboratorio muchas veces.",
  ui_story_1015_10150201_20_dialog_content = "No quiero perder demasiado tiempo en nada que no esté relacionado con el experimento.",
  ui_story_1015_10150201_21_dialog_content = "Concéntrate y ni se te ocurra intentar delatar nuestro paradero.",
  ui_story_1015_10150201_22_dialog_content = "Si intentas pedir ayuda a gritos como lo hiciste antes, te prometo que te cortaré la lengua.",
  ui_story_1015_10150201_23_dialog_content = "Entendemos. Mira, estamos haciendo exactamente lo que pediste esta vez.",
  ui_story_1015_10150201_24_dialog_content = "Las rutas de patrulla y los turnos de guardia son fijos. no habrá percances...",
  ui_story_1015_10150201_25_dialog_content = "...",
  ui_story_1015_10150201_26_dialog_content = "<size=50>¡Guau!</size> Esto es...",
  ui_story_1015_10150201_27_dialog_content = "<size=50><anim type=Shake>¡¡¡Rugido!!!</anim></size>",
  ui_story_1015_10150201_28_dialog_content = "Forsakin, tu perro nos sigue de nuevo.",
  ui_story_1015_10150201_29_dialog_content = "Permítanme decir esto una vez más, Jade no es un perro.",
  ui_story_1015_10150201_30_dialog_content = "Bien. Tu mascota.",
  ui_story_1015_10150201_31_dialog_content = "¿No es un poco llamativo tener una cosa tan grande siguiéndonos?",
  ui_story_1015_10150201_32_dialog_content = "Necesitaremos ayuda con la investigación de hoy. Por eso lo llamé aquí.",
  ui_story_1015_10150201_33_dialog_content = "Investigación...",
  ui_story_1015_10150201_34_dialog_content = "Ahora que lo menciona, ¿es esto también resultado de su investigación?",
  ui_story_1015_10150201_35_dialog_content = "...",
  ui_story_1015_10150201_36_dialog_content = "¿Qué tipo de animal era Jade para empezar?",
  ui_story_1015_10150201_37_dialog_content = "Una chinchilla.",
  ui_story_1015_10150201_38_dialog_content = "¿Una chinchilla?",
  ui_story_1015_10150201_39_dialog_content = "¿Convertiste a un animalito tan lindo en esto...?",
  ui_story_1015_10150201_40_dialog_content = "Palabras como \"lindo\" y \"pequeño\" simplemente demuestran la arrogancia de tu perspectiva desde la supuesta cima de la cadena alimenticia.",
  ui_story_1015_10150201_41_dialog_content = "¿Ah?",
  ui_story_1015_10150201_42_dialog_content = "Como sois vosotros los que determináis la vida y la muerte de otras criaturas, su capacidad para complaceros se convierte en su ventaja.",
  ui_story_1015_10150201_43_dialog_content = "En la naturaleza, el tamaño de la chinchilla sin duda limita su capacidad para ocupar un nicho ecológico superior.",
  ui_story_1015_10150201_44_dialog_content = "Y ahora Jade ha superado esta limitación.",
  ui_story_1015_10150201_45_dialog_content = "¿De qué manera, exactamente?",
  ui_story_1015_10150201_46_dialog_content = "En pocas palabras, ahora tiene una gama más rica de opciones de depredación.",
  ui_story_1015_10150201_47_dialog_content = "Momento perfecto, ahora es el momento de que entremos en batalla con los soldados que custodian la puerta.",
  ui_story_1015_10150201_48_dialog_content = "¡Ey! No estarás planeando darle de comer a los soldados a tu mascota, ¿verdad?",
  ui_story_1015_10150201_49_dialog_content = "Acordamos ayudarlos a luchar, ¡pero no pondremos en peligro la vida de los soldados!",
  ui_story_1015_10150201_50_dialog_content = "Pareces tan despreocupado por el futuro de toda una raza, pero te preocupas tanto por la pérdida de una o dos vidas insignificantes.",
  ui_story_1015_10150201_51_dialog_content = "Bien. No me interesa corregir tus defectos.",
  ui_story_1015_10150201_52_dialog_content = "¿De verdad puedes decir que un par de vidas no son importantes? Ellos-",
  ui_story_1015_10150201_53_dialog_content = "Al igual que antes, debes proporcionarme datos de combate, Caelestite.",
  ui_story_1015_10150201_54_dialog_content = "El laboratorio ha reforzado sus defensas. Esta batalla será más difícil que la última vez.",
  ui_story_1015_10150201_55_dialog_content = "Puedo aguantar más que lo mío en el campo de batalla. Realmente deberías considerar dejarme pelear.",
  ui_story_1015_10150201_56_dialog_content = "En cuanto a ti, quédate donde estás y no hagas nada a menos que yo te lo diga, de lo contrario me aseguraré de que te conviertas en el primer bocado de desayuno de Jade.",
  ui_story_1015_10150201_57_dialog_content = "Hmph.",
  ui_story_1015_10150201_58_dialog_content = "Caelestite, quédate sobre mis talones.",
  ui_story_1015_10150201_59_dialog_content = "Terminemos esto.",
  ui_story_1015_10150302_1_dialog_content = "<color=#e8d9bb>Ruido sordo-</color>",
  ui_story_1015_10150302_2_dialog_content = "¡No, no, no, para! ¡No seas demasiado duro con ellos!",
  ui_story_1015_10150302_3_dialog_content = "¡¿Qué vamos a hacer si los lastima gravemente?!",
  ui_story_1015_10150302_4_dialog_content = "Se acabó. Mueve a estos soldados inconscientes a un lado.",
  ui_story_1015_10150302_5_dialog_content = "No dejes que los soldados de la patrulla los descubran, al menos mientras hacemos el experimento.",
  ui_story_1015_10150302_6_dialog_content = "<size=45><anim type=Shake>Graah!</anim></size>",
  ui_story_1015_10150302_7_dialog_content = "¡Sé amable con ellos!",
  ui_story_1015_10150302_8_dialog_content = "Sólo déjame encargarme de eso.",
  ui_story_1015_10150302_9_dialog_content = "Rápidamente. Para de perder el tiempo.",
  ui_story_1015_10150302_10_dialog_content = "Sé que sé. Esta no es mi primera vez.",
  ui_story_1015_10150302_11_dialog_content = "Lo siento por ayudar a Forsakin a darles una paliza.",
  ui_story_1015_10150302_12_dialog_content = "¿Eh? Un montón de cosas acaban de caer al suelo.",
  ui_story_1015_10150302_13_dialog_content = "Pongamos todo esto de vuelta en sus bolsillos.",
  ui_story_1015_10150302_14_dialog_content = "Cuchillo... llaves... tarjeta...",
  ui_story_1015_10150302_15_dialog_content = "¿Qué es esto? ¿Un costurero?",
  ui_story_1015_10150302_16_dialog_content = "Creo que puedo abrirlo.",
  ui_story_1015_10150302_17_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_1015_10150302_18_dialog_content = "Oh, es un <color=#FFB400>encendedor</color>...",
  ui_story_1015_10150302_19_dialog_content = "<size=50><anim type=Shake>¡Rugido!</anim></size>",
  ui_story_1015_10150302_20_dialog_content = "¡Guau! ¡¿Qué estás haciendo Jade?!",
  ui_story_1015_10150302_21_dialog_content = "<size=45><anim type=Shake>Graah!</anim></size>",
  ui_story_1015_10150302_22_dialog_content = "<color=#e8d9bb>¡Grieta!</color>",
  ui_story_1015_10150302_23_dialog_content = "¿Pisó el encendedor?",
  ui_story_1015_10150302_24_dialog_content = "Es solo un encendedor. ¿Cual es el problema?",
  ui_story_1015_10150302_25_dialog_content = "...",
  ui_story_1015_10150302_26_dialog_content = "El área alrededor del laboratorio es altamente combustible. Incluso la chispa más pequeña podría significar un desastre.",
  ui_story_1015_10150302_27_dialog_content = "No dejes que algo así vuelva a suceder.",
  ui_story_1015_10150302_28_dialog_content = "Cierto...",
  ui_story_1015_10150302_29_dialog_content = "(Si ese es realmente el caso, ¿por qué a los guardias todavía se les permite llevar encendedores?)",
  ui_story_1015_10150302_30_dialog_content = "Vamos. Para de perder el tiempo.",
  ui_story_1015_10150302_31_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_1015_10150302_32_dialog_content = "La puerta está abierta. Ahora entra.",
  ui_story_1015_10150302_33_dialog_content = "Adelante, espérame allí.",
  ui_story_1015_10150302_34_dialog_content = "¿Qué estás haciendo?",
  ui_story_1015_10150302_35_dialog_content = "¿Estás... cambiando el código de acceso de la puerta?",
  ui_story_1015_10150302_36_dialog_content = "... Tsk.",
  ui_story_1015_10150302_37_dialog_content = "(Probablemente sea para evitar que los guardias los alcancen, usando la cerradura para ganar tiempo).",
  ui_story_1015_10150302_38_dialog_content = "Hmm... Se supone que estas puertas deben detener a personas como nosotros, pero ahora se están usando para detener a los guardias.",
  ui_story_1015_10150302_39_dialog_content = "Las máquinas no poseen conciencia. Solo sirven a quien sabe usarlos.",
  ui_story_1015_10150302_40_dialog_content = "Parece que conoces muy bien este lugar.",
  ui_story_1015_10150302_41_dialog_content = "¿Mmm?",
  ui_story_1015_10150302_42_dialog_content = "Podría infiltrarse en el instituto de investigación, familiarizarse con el diseño interno e incluso obtener acceso a la mayoría de las puertas y maquinaria.",
  ui_story_1015_10150302_43_dialog_content = "Las medidas de seguridad de Illumina son una broma a tus ojos.",
  ui_story_1015_10150302_44_dialog_content = "Todas estas fueron condiciones previas necesarias para implementar mi plan.",
  ui_story_1015_10150302_45_dialog_content = "Si no pudiera hacerlo, no estaría aquí ahora.",
  ui_story_1015_10150302_46_dialog_content = "¿Pero cómo? ¿Porque solías ser un investigador de Illumina?",
  ui_story_1015_10150302_47_dialog_content = "Porque yo mismo construí este instituto de investigación.",
  ui_story_1015_10150302_48_dialog_content = "¡¿Qué?!",
  ui_story_1015_10150302_49_dialog_content = "Tú lo construiste...",
  ui_story_1015_10150302_50_dialog_content = "En ese momento, se llamaba Entrañas X.",
  ui_story_1015_10150302_51_dialog_content = "Muy bien, el código de acceso se ha restablecido.",
  ui_story_1015_10150302_52_dialog_content = "Es hora de comenzar el experimento de hoy.",
  ui_story_1015_10150302_53_dialog_content = "¡Vaya, realmente hay un Chord Link aquí!",
  ui_story_1015_10150302_54_dialog_content = "Aunque hay algunas diferencias entre este y el del Obelisco del Retorno, es claramente lo mismo.",
  ui_story_1015_10150302_55_dialog_content = "Illumina ha estado investigando en secreto durante muchos años bajo un alto grado de confidencialidad.",
  ui_story_1015_10150302_56_dialog_content = "Solo se ha permitido el acceso a los fósiles antiguos del Comité y del Consejo de Ciencias.",
  ui_story_1015_10150302_57_dialog_content = "Me pregunto hasta dónde ha progresado la investigación de Illumina al respecto...",
  ui_story_1015_10150302_58_dialog_content = "Nunca nos dejaste entrar aquí antes... ¿Por qué cambiaste de opinión hoy?",
  ui_story_1015_10150302_59_dialog_content = "Porque mi investigación ha avanzado a la siguiente etapa.",
  ui_story_1015_10150302_60_dialog_content = "Illumina ha invertido décadas de investigación para encontrar una manera de usar este instrumento, pero no tengo tanto tiempo.",
  ui_story_1015_10150302_61_dialog_content = "Entonces, necesito usar experimentación eficiente para aprender sus métodos.",
  ui_story_1015_10150302_62_dialog_content = "¿A qué estás llegando?",
  ui_story_1015_10150302_63_dialog_content = "Quiero activar Chord Link para entender los principios de su funcionamiento.",
  ui_story_1015_10150302_64_dialog_content = "¿Sabes por qué te traje aquí?",
  ui_story_1015_10150302_65_dialog_content = "¿Activar el enlace de acordes? ¿Con quién quieres usarlo?",
  ui_story_1015_10150302_66_dialog_content = "He preparado un tema de prueba de antemano, por supuesto.",
  ui_story_1015_10150302_67_dialog_content = "¡Tú!",
  ui_story_1015_10150302_68_dialog_content = "¡No! no toques Vice!!!",
  ui_story_1015_10150302_69_dialog_content = "Jade.",
  ui_story_1015_10150302_70_dialog_content = "<size=50><anim type=Shake>¡¡¡Rugido!!!</anim></size>",
  ui_story_1015_10150302_71_dialog_content = "Urgh... Es tan... pesado...",
  ui_story_1015_10150302_72_dialog_content = "L-Déjalo ir Vice! ¡No juegues con esa cosa si ni siquiera has descubierto cómo usarla!",
  ui_story_1015_10150302_73_dialog_content = "El objetivo de este tema de prueba es ayudarme a aclarar exactamente cómo usarlo.",
  ui_story_1015_10150302_74_dialog_content = "La investigación científica implica llegar a la oscuridad, donde la mano debe picarse y rascarse para determinar la forma del mundo.",
  ui_story_1015_10150302_75_dialog_content = "Si no lo intentamos, la ciencia nunca avanzará.",
  ui_story_1015_10150302_76_dialog_content = "Si crees que esta es una empresa tan noble, ¿por qué no lo intentas tú mismo?",
  ui_story_1015_10150302_77_dialog_content = "Cuando se usa a sí mismo como sujeto de prueba, solo puede darse el lujo de fallar una vez, pero puede fallar innumerables veces cuando usa sujetos de prueba desechables.",
  ui_story_1015_10150302_78_dialog_content = "La investigación científica no es una apuesta de una sola vez. Por supuesto que necesitaré tantas oportunidades como sea necesario.",
  ui_story_1015_10150302_79_dialog_content = "<size=45>Tú... despreciable...</size>",
  ui_story_1015_10150302_80_dialog_content = "Extrañar Vice, espero que estés listo.",
  ui_story_1015_10150302_81_dialog_content = "Esto irá como la primera vez que usó Chord Link.",
  ui_story_1015_10150302_82_dialog_content = "¡Suéltame, tú!",
  ui_story_1015_10150302_83_dialog_content = "La prueba Chord Link, la cámara de prueba y el sujeto están listos.",
  ui_story_1015_10150302_84_dialog_content = "Comencemos el experimento.",
  ui_story_1015_10150302_85_dialog_content = "Oficial Ulysses, esta no es la forma en que debemos proceder.",
  ui_story_1015_10150302_86_dialog_content = "Les hemos pedido a los guardias que intensifiquen tanto sus patrullas como sus búsquedas específicas, pero aún no pueden localizar al intruso.",
  ui_story_1015_10150302_87_dialog_content = "Nuestro personal ahora está en estado de pánico y muchos de los investigadores tienen demasiado miedo de regresar al laboratorio.",
  ui_story_1015_10150302_88_dialog_content = "¿Has logrado descubrir la identidad del intruso?",
  ui_story_1015_10150302_89_dialog_content = "Estoy seguro de que, tal como adivinaste anteriormente, es Forsakin.",
  ui_story_1015_10150302_90_dialog_content = "No tengo idea de cómo irrumpió. No solo logró evadir nuestras búsquedas, sino que también parece capaz de eludir todas nuestras medidas de seguridad.",
  ui_story_1015_10150302_91_dialog_content = "Asimismo, algunos militares aseguran haber visto a Caelestite, quien lleva días incomunicado. ¿Podría ser realmente el hombre de Forsakin en el interior?",
  ui_story_1015_10150302_92_dialog_content = "Si es Forsakin, no necesita a nadie adentro.",
  ui_story_1015_10150302_93_dialog_content = "¿Qué?",
  ui_story_1015_10150302_94_dialog_content = "Forsakin conoce este lugar mejor que nadie. Ella es quien construyó el Instituto X.",
  ui_story_1015_10150302_95_dialog_content = "¿Ella lo construyó? Pensé que eras tú...",
  ui_story_1015_10150302_96_dialog_content = "Hace once años, Forsakin todavía era miembro de Illumina y era la investigadora más prometedora de su generación.",
  ui_story_1015_10150302_97_dialog_content = "Me envió una solicitud: quería apoderarse en secreto de una ciudad subterránea abandonada sin nombre.",
  ui_story_1015_10150302_98_dialog_content = "Lo llamó Entrañas X, el precursor de este instituto de investigación.",
  ui_story_1015_10150302_99_dialog_content = "Comprendo.",
  ui_story_1015_10150302_100_dialog_content = "Entonces, cuando Forsakin finalmente desertó de Illumina, ¿el instituto de investigación evolucionó hasta convertirse en lo que es ahora?",
  ui_story_1015_10150302_101_dialog_content = "Puedes decir eso.",
  ui_story_1015_10150302_102_dialog_content = "Ella es muy talentosa, pero el talento puede ser algo aterrador.",
  ui_story_1015_10150302_103_dialog_content = "La diferenció de la gente común, llevándola a emprender constantemente experimentos radicales y peligrosos.",
  ui_story_1015_10150302_104_dialog_content = "A través de sus métodos, Entrañas X dominó la biotecnología más avanzada de la Federación Illumina.",
  ui_story_1015_10150302_105_dialog_content = "Pero al mismo tiempo, el peligro que representaba su trabajo crecía constantemente.",
  ui_story_1015_10150302_106_dialog_content = "Al final, ni ella ni Illumina pudieron soportarlo.",
  ui_story_1015_10150302_107_dialog_content = "Recuerdo haber oído que la despidieron después de que ocurriera un gran accidente durante uno de sus experimentos...",
  ui_story_1015_10150302_108_dialog_content = "Sí, un gran incendio destruyó Entrañas X.",
  ui_story_1015_10150302_109_dialog_content = "Pero este accidente fue solo el detonante. Simplemente llevó a funcionarios de alto nivel a profundizar en los secretos de Forsakin.",
  ui_story_1015_10150302_110_dialog_content = "Lo que realmente la hizo intolerable a los ojos de Illumina fue la naturaleza controvertida e incontrolable de su investigación.",
  ui_story_1015_10150302_111_dialog_content = "Si la fuente no se extingue, el fuego solo arderá más fuerte y más feroz.",
  ui_story_1015_10150302_112_dialog_content = "En efecto. Las consecuencias habrían sido inimaginables si este accidente hubiera ocurrido en Gannon City.",
  ui_story_1015_10150302_113_dialog_content = "Pero si este es el caso... ¿por qué Entrañas X no fue abandonada después de un incidente tan devastador?",
  ui_story_1015_10150302_114_dialog_content = "Hay muchas otras Entrañas que pueden servir como lugares de investigación, ¿no es así?",
  ui_story_1015_10150302_115_dialog_content = "Ah... Bueno, es por eso que dije que el talento podría ser algo aterrador.",
  ui_story_1015_10150302_116_dialog_content = "No importa cuán poco éticos y dañinos hayan sido esos experimentos, no pudieron eclipsar los logros sobresalientes de su investigación.",
  ui_story_1015_10150302_117_dialog_content = "Después de todo, yo también soy bastante similar a ella.",
  ui_story_1015_10150302_118_dialog_content = "No podía soportar descuidar lo que dejó atrás.",
  ui_story_1015_10150302_119_dialog_content = "Entiendo...",
  ui_story_1015_10150302_120_dialog_content = "Después del incidente, reconstruí Entrañas dañadas, que se convirtió en el actual Instituto X.",
  ui_story_1015_10150302_121_dialog_content = "Con la ayuda de los instrumentos y logros que nos dejó Forsakin, la investigación de Illumina en el campo de la biología avanzó a pasos agigantados.",
  ui_story_1015_10150302_122_dialog_content = "Entonces, en cierto modo, parece que ella ha hecho algo bueno por Illumina.",
  ui_story_1015_10150302_123_dialog_content = "Todo tiene un precio, y ahora es el momento de que paguemos.",
  ui_story_1015_10150302_124_dialog_content = "Aunque el Instituto X fue completamente renovado, sus propiedades y principios fundamentales permanecen.",
  ui_story_1015_10150302_125_dialog_content = "A los ojos de Forsakin, simplemente le dimos cuerda a su caja de música y le dimos una nueva apariencia.",
  ui_story_1015_10150302_126_dialog_content = "Si quiere tocar su propia canción, simplemente puede estirar la mano y arrancar las cañas.",
  ui_story_1015_10150401_1_dialog_content = "Así que... la situación aquí se ha vuelto peligrosa.",
  ui_story_1015_10150401_2_dialog_content = "Aunque tenemos una ventaja en términos de fuerza militar, nuestra eficacia de combate se ha vuelto unidimensional.",
  ui_story_1015_10150401_3_dialog_content = "Forsakin está familiarizada con el diseño del instituto y nunca nos dará la oportunidad de concentrar nuestras tropas y rodearla.",
  ui_story_1015_10150401_4_dialog_content = "Ella puede hacer prácticamente lo que quiera aquí...",
  ui_story_1015_10150401_5_dialog_content = "Así es. Los guardias no pueden tocarla.",
  ui_story_1015_10150401_6_dialog_content = "Nadie aquí posee la capacidad de combate individual para competir con ella. No importa cuántos guardias tengamos, son prácticamente inútiles.",
  ui_story_1015_10150401_7_dialog_content = "No podemos seguir así...",
  ui_story_1015_10150401_8_dialog_content = "Señor, tal vez deberíamos buscar la ayuda de Gannon.",
  ui_story_1015_10150401_9_dialog_content = "Si logramos asegurar los refuerzos adecuados, definitivamente...",
  ui_story_1015_10150401_10_dialog_content = "No.",
  ui_story_1015_10150401_11_dialog_content = "¿Por qué Señor?",
  ui_story_1015_10150401_12_dialog_content = "No es un asunto tan sencillo.",
  ui_story_1015_10150401_13_dialog_content = "Si buscar ayuda pudiera resolver este problema, ya habría informado la situación a Gannon City, y ciertamente no necesitaría que me lo sugieras.",
  ui_story_1015_10150401_14_dialog_content = "No entiendo...",
  ui_story_1015_10150401_15_dialog_content = "Este es un instituto de investigación secreto, y todo sobre este lugar debe mantenerse confidencial.",
  ui_story_1015_10150401_16_dialog_content = "Informar a los militares no es una opción. No olvides las circunstancias del despido de Forsakin.",
  ui_story_1015_10150401_17_dialog_content = "... Sí, señor.",
  ui_story_1015_10150401_18_dialog_content = "No había considerado eso, solo sentí que el asunto en cuestión era más importante.",
  ui_story_1015_10150401_19_dialog_content = "Forsakin es una ex investigadora, se infiltra en el instituto para realizar sus experimentos.",
  ui_story_1015_10150401_20_dialog_content = "Al final, esto es actualmente solo un conflicto entre científicos.",
  ui_story_1015_10150401_21_dialog_content = "Una vez que involucremos a los militares, el asunto tomará otra forma.",
  ui_story_1015_10150401_22_dialog_content = "Si entiendo.",
  ui_story_1015_10150401_23_dialog_content = "¿Realmente entiendes?",
  ui_story_1015_10150401_24_dialog_content = "...",
  ui_story_1015_10150401_25_dialog_content = "Je, después de todo eres un soldado justo, ejecutar órdenes es todo lo que se requiere de ti. No hay necesidad de que entiendas completamente mis pensamientos.",
  ui_story_1015_10150401_26_dialog_content = "Piensa en todo esto como un experimento.",
  ui_story_1015_10150401_27_dialog_content = "De acuerdo con las regulaciones, el contenido del experimento debe mantenerse confidencial para el público. ¿Entender?",
  ui_story_1015_10150401_28_dialog_content = "¡Sí señor!",
  ui_story_1015_10150401_29_dialog_content = "Muy bien, ahora hablemos de algo que realmente puedas entender.",
  ui_story_1015_10150401_30_dialog_content = "Optar por no buscar refuerzos de Gannon no significa que simplemente me sentaré aquí esperando la muerte inminente.",
  ui_story_1015_10150401_31_dialog_content = "También tengo mi propia forma de tratar con Forsakin.",
  ui_story_1015_10150401_32_dialog_content = "¿Tienes un plan? Quieres decir...",
  ui_story_1015_10150401_33_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc. </color>",
  ui_story_1015_10150401_34_dialog_content = "Pasa adelante...",
  ui_story_1015_10150401_35_dialog_content = "Coronel oficial de inteligencia de Illumina Yingel, informes, señor!",
  ui_story_1015_10150401_36_dialog_content = "<color=#e8d9bb>bip—bip—</color>",
  ui_story_1015_10150401_37_dialog_content = "Entonces, así es como funciona...",
  ui_story_1015_10150401_38_dialog_content = "Sí, cambiar sólo la estructura corporal es inútil.",
  ui_story_1015_10150401_39_dialog_content = "Aquí no es donde se encuentra el rastro de Lumina. Está escondido más profundo...",
  ui_story_1015_10150401_40_dialog_content = "(Vice! ¿Cómo te sientes ahora?)",
  ui_story_1015_10150401_41_dialog_content = "(¿Estás herido?)",
  ui_story_1015_10150401_42_dialog_content = "(Estoy bien, solo siento que hay una fuerza reorganizando el Lumina dentro de mí).",
  ui_story_1015_10150401_43_dialog_content = "(¿En serio? Supongo que eso es lo suficientemente bueno por ahora. Espero que nada salga mal...)",
  ui_story_1015_10150401_44_dialog_content = "(No se preocupe demasiado. Después de todo, este no es mi primer encuentro con Chord Link).",
  ui_story_1015_10150401_45_dialog_content = "(Pero...)",
  ui_story_1015_10150401_46_dialog_content = "(Oye, escucha, ¿no crees que esta podría ser una oportunidad?)",
  ui_story_1015_10150401_47_dialog_content = "(¿Una oportunidad?)",
  ui_story_1015_10150401_48_dialog_content = "(El Chord Link puede mejorar el poder de un Aurorian, ¿verdad?)",
  ui_story_1015_10150401_49_dialog_content = "(Tal vez pueda usar esta mejora para liberarme de estas cuerdas).",
  ui_story_1015_10150401_50_dialog_content = "(¡Vas a intentar liberarte de esas cuerdas! ¿Realmente puedes hacerlo?)",
  ui_story_1015_10150401_51_dialog_content = "(No debería ser imposible. Probablemente podría hacerlo incluso ahora).",
  ui_story_1015_10150401_52_dialog_content = "(Sin embargo, el verdadero problema es cómo vamos a lidiar con Forsakin y Jade después de que me libere).",
  ui_story_1015_10150401_53_dialog_content = "(Todavía necesito más poder. Solo espero que los efectos de mejora de Chord Link funcionen).",
  ui_story_1015_10150401_54_dialog_content = "(Hmm... La atención de Forsakin está completamente enfocada en los datos. De hecho, esta es una buena oportunidad para un contraataque).",
  ui_story_1015_10150401_55_dialog_content = "(¡Correcto! ¡Deberíamos darle una idea de cuán efectiva es su investigación!)",
  ui_story_1015_10150401_56_dialog_content = "(Tendremos que trabajar juntos para hacer esto. Solo tendremos una oportunidad).",
  ui_story_1015_10150401_57_dialog_content = "(Sería mejor si pudiéramos someter a Forsakin antes de que pueda reaccionar. Arrastrarla a una batalla prolongada no sería bueno para nosotros).",
  ui_story_1015_10150401_58_dialog_content = "(Entendido. Buscaré una oportunidad para vencerla de un solo golpe).",
  ui_story_1015_10150401_59_dialog_content = "(¡Está bien! ¡Cuento contigo!)",
  ui_story_1015_10150401_60_dialog_content = "Forsakin, ¿cuánto más durará este experimento?",
  ui_story_1015_10150401_61_dialog_content = "La cola de Jade es tan pesada que no puedo respirar bajo su peso.",
  ui_story_1015_10150401_62_dialog_content = "Pronto. Guarda silencio.",
  ui_story_1015_10150401_63_dialog_content = "¿Cuánto tiempo es pronto? ¿No puedes darme una hora precisa?",
  ui_story_1015_10150401_64_dialog_content = "Estamos en la etapa final.",
  ui_story_1015_10150401_65_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1015_10150401_66_dialog_content = "(PlayerName! ¡Puedo sentir el flujo de Lumina comenzando a acelerarse!)",
  ui_story_1015_10150401_67_dialog_content = "(Prepárese. ¡Podemos hacer nuestro movimiento tan pronto como se complete la mejora!)",
  ui_story_1015_10150401_68_dialog_content = "(¡Está bien!)",
  ui_story_1015_10150401_69_dialog_content = "(En el momento en que te liberes, ataca a Forsakin primero. Jade instintivamente intentará ayudarla, y luego tú...)",
  ui_story_1015_10150401_70_dialog_content = "Por cierto, Caelestita.",
  ui_story_1015_10150401_71_dialog_content = "¿Eh? ¿Estás hablando conmigo?",
  ui_story_1015_10150401_72_dialog_content = "¿Por qué solo le importa cuánto tiempo durará el experimento, pero no si se completa con éxito?",
  ui_story_1015_10150401_73_dialog_content = "Yo...",
  ui_story_1015_10150401_74_dialog_content = "(Oh no... ¿Regalaré el juego?)",
  ui_story_1015_10150401_75_dialog_content = "(Vice, ¿cuánto tiempo hasta que se complete la mejora...?)",
  ui_story_1015_10150401_76_dialog_content = "No te preocupes, el cuerpo de Vice no ha sufrido ningún cambio.",
  ui_story_1015_10150401_77_dialog_content = "No se produjeron heridos ni se ejecutaron las mejoras previstas.",
  ui_story_1015_10150401_78_dialog_content = "El experimento ha terminado.",
  ui_story_1015_10150401_79_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_1015_10150401_80_dialog_content = "(¡¿Qué está pasando?! ¡¿La mejora se detuvo?!)",
  ui_story_1015_10150401_81_dialog_content = "¿Q-Qué hiciste?",
  ui_story_1015_10150401_82_dialog_content = "Acabo de cerrar el Chord Link.",
  ui_story_1015_10150401_83_dialog_content = "Alcanzar este paso en el experimento es suficiente por hoy. No esperaba que ocurrieran cambios innecesarios en el sujeto de prueba.",
  ui_story_1015_10150401_84_dialog_content = "¿A menos que ustedes dos estuvieran anticipando algo?",
  ui_story_1015_10150401_85_dialog_content = "(Qué podemos hacer, Vice? Parece saber lo que estábamos planeando...)",
  ui_story_1015_10150401_86_dialog_content = "(¡No importa eso, esta es la única oportunidad que tenemos!)",
  ui_story_1015_10150401_87_dialog_content = "(Me liberaré de estas cuerdas. ¡Prepárate para la acción!)",
  ui_story_1015_10150401_88_dialog_content = "¿Nada que decir? Parece que llené tu imaginación con algunas expectativas poco realistas.",
  ui_story_1015_10150401_89_dialog_content = "¡Hmph! Solo espera hasta que te noquee, entonces sabrás lo que es poco realista.",
  ui_story_1015_10150401_90_dialog_content = "<color=#e8d9bb>Quebrar-</color>",
  ui_story_1015_10150401_91_dialog_content = "Entonces, en realidad lograste liberarte de tus cuerdas con la ayuda de Chord Link.",
  ui_story_1015_10150401_92_dialog_content = "Pero eso está bien. Tal evento ya se ha contabilizado en mi evaluación de riesgos y plan de contingencia.",
  ui_story_1015_10150401_93_dialog_content = "Te atrapé una vez, puedo atraparte de nuevo.",
  ui_story_1015_10150401_94_dialog_content = "Vice! ¡Está invocando eclipses ocultos!",
  ui_story_1015_10150401_95_dialog_content = "¡Ahora!",
  ui_story_1015_10150502_1_dialog_content = "Jadeo... Jadeo...",
  ui_story_1015_10150502_2_dialog_content = "No funciona...?",
  ui_story_1015_10150502_3_dialog_content = "Usando la mejora de Chord Link para liberarte de tus cuerdas... ¿De verdad crees que no había previsto esto?",
  ui_story_1015_10150502_4_dialog_content = "No creas que esta es una oportunidad. Me he preparado para todo.",
  ui_story_1015_10150502_5_dialog_content = "Y todavía tienes tiempo para charlar durante la batalla.",
  ui_story_1015_10150502_6_dialog_content = "Esto no es una batalla. La batalla ya ha terminado.",
  ui_story_1015_10150502_7_dialog_content = "No tengo tiempo para disfrutar de esta farsa.",
  ui_story_1015_10150502_8_dialog_content = "¿Qué te hace pensar que tienes la última palabra en esto?",
  ui_story_1015_10150502_9_dialog_content = "Bueno, ¿acaso él tiene la última palabra?",
  ui_story_1015_10150502_10_dialog_content = "<size=45>Vice! ¡Detrás de ti!</size>",
  ui_story_1015_10150502_11_dialog_content = "¿Qué...?",
  ui_story_1015_10150502_12_dialog_content = "<size=45>¡Ahhhhh—!</size>",
  ui_story_1015_10150502_13_dialog_content = "<size=45>Vice!!!</size>",
  ui_story_1015_10150502_14_dialog_content = "Helios... ¡¿Qué hace este tipo aquí?!",
  ui_story_1015_10150502_15_dialog_content = "En la actualidad, resistir es la decisión más tonta que podrías tomar.",
  ui_story_1015_10150502_16_dialog_content = "Su probabilidad de éxito es cero. Y su interferencia solo retrasará el progreso del experimento.",
  ui_story_1015_10150502_17_dialog_content = "No me gusta cuando la gente interfiere con mis experimentos.",
  ui_story_1015_10150502_18_dialog_content = "¿Q-Qué estás haciendo?",
  ui_story_1015_10150502_19_dialog_content = "El experimento de hoy se ha completado. Nos iremos de aquí una vez que termine de organizar los datos.",
  ui_story_1015_10150502_20_dialog_content = "Vice Irás con Helios, y tú conmigo, Caelestite. De ahora en adelante, ustedes dos serán <color=#FFB400>apartado</color>.",
  ui_story_1015_10150502_21_dialog_content = "¡¿Apartado?!",
  ui_story_1015_10150502_22_dialog_content = "Por el incidente de ahora, puedo ver que si ustedes dos permanecen juntos formarían un factor inestable.",
  ui_story_1015_10150502_23_dialog_content = "Como este es el caso, tendrán que mantenerse alejados el uno del otro en el futuro.",
  ui_story_1015_10150502_24_dialog_content = "Escucha bien, Yingel. Esto es lo que está pasando.",
  ui_story_1015_10150502_25_dialog_content = "Forsakin se ha infiltrado en este instituto de investigación y se está saliendo con la suya con nuestro equipo.",
  ui_story_1015_10150502_26_dialog_content = "Además, el teniente Vice, que estaba visitando el instituto de investigación en ese momento, y Caelestite, han estado inaccesibles durante varios días.",
  ui_story_1015_10150502_27_dialog_content = "Según los informes de los testigos oculares de los soldados, especulo que Forsakin los ha secuestrado.",
  ui_story_1015_10150502_28_dialog_content = "PlayerName y Vice...",
  ui_story_1015_10150502_29_dialog_content = "Profesor Ulises, ¿qué necesita que haga?",
  ui_story_1015_10150502_30_dialog_content = "Rescata a los rehenes y captura a Forsakin.",
  ui_story_1015_10150502_31_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_1015_10150502_32_dialog_content = "(¿De verdad le está confiando una tarea tan difícil a un coronel?)",
  ui_story_1015_10150502_33_dialog_content = "... Acepto la misión.",
  ui_story_1015_10150502_34_dialog_content = "Pero, profesor, según la situación actual, la probabilidad de que complete esta misión es muy baja.",
  ui_story_1015_10150502_35_dialog_content = "Forsakin está familiarizada con el diseño del sitio, es increíblemente fuerte y ha tomado rehenes.",
  ui_story_1015_10150502_36_dialog_content = "Si tuviera que intentar esto solo, estaría en una desventaja extrema.",
  ui_story_1015_10150502_37_dialog_content = "Si pudiera aplicar para usar el <color=#FFB400>arma</color>...",
  ui_story_1015_10150502_38_dialog_content = "deseas Axelia para ayudarte, ¿correcto?",
  ui_story_1015_10150502_39_dialog_content = "...Sí.",
  ui_story_1015_10150502_40_dialog_content = "No debes confiar demasiado en su fuerza.",
  ui_story_1015_10150502_41_dialog_content = "Ambos fueron participantes de la <color=#FFB400>Programa Fósforo</color>, pero sus especialidades difieren.",
  ui_story_1015_10150502_42_dialog_content = "Esta misión no es una que pueda ser resuelta a través de la fuerza pura. Necesito que hagas uso de tus habilidades únicas.",
  ui_story_1015_10150502_43_dialog_content = "... Entiendo, profesor.",
  ui_story_1015_10150502_44_dialog_content = "Además, Axelia necesita prepararse para otra misión importante. Te dejaré saber más sobre esto en una fecha posterior.",
  ui_story_1015_10150502_45_dialog_content = "Por supuesto, cuando se trata de un enemigo así, debes preparar bien tu mano.",
  ui_story_1015_10150502_46_dialog_content = "Afortunadamente, tengo dos cartas de triunfo para ti.",
  ui_story_1015_10150502_47_dialog_content = "Por favor elabora.",
  ui_story_1015_10150502_48_dialog_content = "El primero es el refuerzo.",
  ui_story_1015_10150502_49_dialog_content = "He seleccionado un asistente confiable para usted. Está de camino hacia aquí ahora.",
  ui_story_1015_10150502_50_dialog_content = "Es Anatoli, uno de los oficiales de inteligencia de confianza del Comité.",
  ui_story_1015_10150502_51_dialog_content = "¡Sé de él! ¡Sin duda será de gran ayuda!",
  ui_story_1015_10150502_52_dialog_content = "En cuanto a la otra carta de triunfo...",
  ui_story_1015_10150502_53_dialog_content = "Quiero que te aferres a él hasta el final.",
  ui_story_1015_10150601_1_dialog_content = "<color=#e8d9bb>Crepúsculo, Fortaleza Lumo</color>",
  ui_story_1015_10150601_2_dialog_content = "...",
  ui_story_1015_10150601_3_dialog_content = "<color=#e8d9bb>TOC Toc-</color>",
  ui_story_1015_10150601_4_dialog_content = "¡Adelante!",
  ui_story_1015_10150601_5_dialog_content = "... Joselyne.",
  ui_story_1015_10150601_6_dialog_content = "Ha llegado el anochecer y la oración está a punto de comenzar... ¿Estás esperando a alguien?",
  ui_story_1015_10150601_7_dialog_content = "Parece que llegué en un mal momento.",
  ui_story_1015_10150601_8_dialog_content = "Estoy esperando el informe de inteligencia. Este es el asunto más urgente para Ironthorn en este momento.",
  ui_story_1015_10150601_9_dialog_content = "La situación en la línea del frente no parece optimista, y un número cada vez mayor de asentamientos circundantes han sido atacados por Eclipsites.",
  ui_story_1015_10150601_10_dialog_content = "Aunque Entrañas tiene espacio más que suficiente para absorber a los residentes de estos asentamientos...",
  ui_story_1015_10150601_11_dialog_content = "Si las cosas continúan así, algún día perderemos nuestro control sobre este territorio.",
  ui_story_1015_10150601_12_dialog_content = "Sí. No deseo que suceda tal cosa.",
  ui_story_1015_10150601_13_dialog_content = "Los Eclipsites continúan reuniéndose y, sin embargo, no han lanzado ningún ataque a gran escala. Lumopolis y la Federación Illumina tampoco han enviado instrucciones para atacar.",
  ui_story_1015_10150601_14_dialog_content = "Los soldados ya están agotados por la falta de acción. Este tipo de espera prolongada es realmente perjudicial para ellos.",
  ui_story_1015_10150601_15_dialog_content = "Espero que la oración de hoy pueda calmar al menos un poco la ansiedad de sus soldados.",
  ui_story_1015_10150601_16_dialog_content = "Gracias Joseline.",
  ui_story_1015_10150601_17_dialog_content = "<color=#e8d9bb>TOC Toc-</color>",
  ui_story_1015_10150601_18_dialog_content = "Jadeo... Jadeo...",
  ui_story_1015_10150601_19_dialog_content = "Capitán Leo... ¡Hemos recibido noticias de Illumina!",
  ui_story_1015_10150601_20_dialog_content = "¡Illumina ha enviado una señal, ordenando a todas las tropas estacionadas que se preparen de inmediato!",
  ui_story_1015_10150601_21_dialog_content = "¡Dime qué está pasando! ¡Rápidamente!",
  ui_story_1015_10150601_22_dialog_content = "Son los preparativos para el <color=#FFB400>Ejercicio militar conjunto</color>.",
  ui_story_1015_10150601_23_dialog_content = "?!?",
  ui_story_1015_10150601_24_dialog_content = "<color=#e8d9bb>Crepúsculo, Entrañas cogobernadas</color>",
  ui_story_1015_10150601_25_dialog_content = "¿Es esta una invitación de rutina a Crepúsculo?",
  ui_story_1015_10150601_26_dialog_content = "Sí, señor. Aunque las fechas de los ejercicios militares dependen totalmente de los altos mandos, esto todavía se considera una tradición.",
  ui_story_1015_10150601_27_dialog_content = "Veo. Esta no es una buena noticia para los soldados.",
  ui_story_1015_10150601_28_dialog_content = "En efecto. ¡¿Por qué ahora, de todos los tiempos?!",
  ui_story_1015_10150601_29_dialog_content = "Sí. Los tambores de guerra han levantado su moral, y ahora serán ahogados por la fanfarria del ejercicio militar. No importa cuán grandioso pueda ser el ejercicio militar, no puede compararse con la emoción de la batalla.",
  ui_story_1015_10150601_30_dialog_content = "¿Qué dice la carta de invitación? ¿Cuántas personas tenemos que enviar?",
  ui_story_1015_10150601_31_dialog_content = "Tres personas. Un soldado de Illumina, un Lumo Knight y un miembro del clero. Contigo, eso hace...",
  ui_story_1015_10150601_32_dialog_content = "<color=#e8d9bb>Crepúsculo, Fortaleza Lumo</color>",
  ui_story_1015_10150601_33_dialog_content = "Veo. Aunque esta es un área cogobernada, está claro que no está satisfecho con esta orden de Illumina.",
  ui_story_1015_10150601_34_dialog_content = "¡Por supuesto! Esos soldados de Gannon se dedican a seguir estrictas formalidades y pedirles a los demás que hagan lo mismo dondequiera que vayan.",
  ui_story_1015_10150601_35_dialog_content = "La guerra en el frente es inminente... ¡¿Por qué necesitamos cooperar solo para satisfacer sus intereses?!",
  ui_story_1015_10150601_36_dialog_content = "La llegada de esta invitación fue sin duda una agradable sorpresa.",
  ui_story_1015_10150601_37_dialog_content = "¿Una sorpresa agradable? Leo, ¿Ya tomaste tu decisión?",
  ui_story_1015_10150601_38_dialog_content = "Sí. Voy.",
  ui_story_1015_10150601_39_dialog_content = "¡¿Capitán?!",
  ui_story_1015_10150601_40_dialog_content = "Si el ejercicio es un escenario donde las fuerzas del mundo se reúnen para ser vistas por todo el continente...",
  ui_story_1015_10150601_41_dialog_content = "La noticia de los disturbios en la frontera se hará pública en todo el continente.",
  ui_story_1015_10150601_42_dialog_content = "Capitán Leo...",
  ui_story_1015_10150601_43_dialog_content = "Haré algunos preparativos y luego me reuniré con Joseph y Zhao.",
  ui_story_1015_10150601_44_dialog_content = "En cuanto a cuando Joseph y yo estemos fuera, dejaré todo en tus manos, Joselyne.",
  ui_story_1015_10150601_45_dialog_content = "Mmm, entiendo.",
  ui_story_1015_10150601_46_dialog_content = "Luchando codo a codo con los Caballeros de Ironthorn, trayendo energía tranquilizadora a la gente...",
  ui_story_1015_10150601_47_dialog_content = "Después de su regreso, espero que me muestre su más completo aprecio.",
  ui_story_1015_10150601_48_dialog_content = "Jaja, bueno, por supuesto.",
  ui_story_1015_10150601_49_dialog_content = "<color=#e8d9bb>Federación Illumina, en algún lugar de la ciudad de Gannon</color>",
  ui_story_1015_10150601_50_dialog_content = "Estoy firmemente en contra.",
  ui_story_1015_10150601_51_dialog_content = "Tengo derecho a oponerme, ¿no?",
  ui_story_1015_10150601_52_dialog_content = "Sí, Gran Mariscal, según las normas del Consejo de Ciencias, el Gran Mariscal tiene derecho a votar sobre las opiniones del Consejo.",
  ui_story_1015_10150601_53_dialog_content = "¿Podría aconsejarles que celebren una votación lo antes posible?",
  ui_story_1015_10150601_54_dialog_content = "Aquí está la cosa... Gran Mariscal, la decisión de realizar un Ejercicio Militar Conjunto fue una decisión tomada por el Consejo después de sopesar cuidadosamente los pros y los contras.",
  ui_story_1015_10150601_55_dialog_content = "Incluso si votas en contra, los miembros del Consejo no se rendirán tan fácilmente...",
  ui_story_1015_10150601_56_dialog_content = "Hablar contigo realmente es agotador. Sólo dile a Ulises que venga a verme.",
  ui_story_1015_10150601_57_dialog_content = "Lo siento, pero el profesor Ulysses dijo que no te vería si venías aquí por este asunto.",
  ui_story_1015_10150601_58_dialog_content = "Al diablo esto.",
  ui_story_1015_10150601_59_dialog_content = "Primero, nunca he estado interesado en involucrarme en este ridículo festival de fanfarronería al que todos ustedes parecen tan inflexibles acerca de someternos a todos.",
  ui_story_1015_10150601_60_dialog_content = "Del mismo modo, no deseo que mi despliegue estratégico se vea interrumpido por ningún factor redundante.",
  ui_story_1015_10150601_61_dialog_content = "Las Ruinas de Aurora necesitan el apoyo militar de Illumina, pero en cambio, ¡les estás privando de tropas y personal con este ejercicio militar!",
  ui_story_1015_10150601_62_dialog_content = "¡Esto es una completa tontería!",
  ui_story_1015_10150601_63_dialog_content = "Perdóname, Gran Mariscal, yo...",
  ui_story_1015_10150601_64_dialog_content = "¿Por qué molestas a este pobre soldado?",
  ui_story_1015_10150601_65_dialog_content = "Si el viejo Ulises se niega a salir, será mejor que hables conmigo.",
  ui_story_1015_10150601_66_dialog_content = "Reinhardt, pareces nervioso. Te sugiero que te calmes un poco. ¿Qué tal si jugamos una ronda de Joker?",
  ui_story_1015_10150601_67_dialog_content = "Dama <color=#FFB400>Máscara de hierro</color>...",
  ui_story_1015_10150601_68_dialog_content = "Eso no es divertido, <color=#FFB400>Belisaría</color>. Estoy incluso menos interesado en jugar al Guasón contigo en este momento.",
  ui_story_1015_10150601_69_dialog_content = "Estoy bastante sorprendido de que hayas mostrado tu rostro aquí.",
  ui_story_1015_10150601_70_dialog_content = "No estaba bromeando. Hay un límite en el tiempo y la paciencia que estoy dispuesto a extender.",
  ui_story_1015_10150601_71_dialog_content = "Elija una tarjeta y diga su pieza dentro del marco de tiempo. ¿Puedes hacer eso?",
  ui_story_1015_10150601_72_dialog_content = "...",
  ui_story_1015_10150601_73_dialog_content = "La izquierda.",
  ui_story_1015_10150601_74_dialog_content = "Mi punto de vista es simple. No apoyo esta estrategia de evitar las realidades de la guerra.",
  ui_story_1015_10150601_75_dialog_content = "¡Suspender el Ejercicio Militar Conjunto y priorizar el apoyo a las tropas estacionadas en Crepúsculo!",
  ui_story_1015_10150601_76_dialog_content = "Oh, lo siento, dibujaste al Guasón. Tú pierdes.",
  ui_story_1015_10150601_77_dialog_content = "Tomar decisiones sin observación previa parece ser un rasgo común entre los Grandes Mariscales, tanto del pasado como del presente.",
  ui_story_1015_10150601_78_dialog_content = "Reinhardt, la guerra no es un juego en el que uno se permite entregarse a la extravagancia temeraria. Es esencialmente un negocio.",
  ui_story_1015_10150601_79_dialog_content = "Ganar o perder es irrelevante. Lo que importa es lo que pierdes y lo que ganas.",
  ui_story_1015_10150601_80_dialog_content = "Perdiste, así que el tiempo que puedo permitirme dedicarte termina aquí.",
  ui_story_1015_10150601_81_dialog_content = "Si no puede entender este concepto, el Comité encontrará a alguien más que pueda.",
  ui_story_1015_10150601_82_dialog_content = "...",
  ui_story_1015_10150601_83_dialog_content = "<color=#e8d9bb>*rechinar los dientes*</color>",
  ui_story_1015_10150601_84_dialog_content = "<color=#e8d9bb>Jardines de Lumópolis</color>",
  ui_story_1015_10150601_85_dialog_content = "Tal como esperaba, el Ejercicio Militar Conjunto de Illumina también está llamando a personas de Dawn Academia.",
  ui_story_1015_10150601_86_dialog_content = "¡Hmph! Por supuesto, los Cuatro Ángeles no tenemos objeciones. ¿Por qué no dar a los jóvenes emergentes más oportunidades para demostrar su valía?",
  ui_story_1015_10150601_87_dialog_content = "Caballero Raphael... ¡Claramente, tú mismo eres un niño!",
  ui_story_1015_10150601_88_dialog_content = "Erm, de todos modos, ya que el Capitán Carleen está a cargo, no necesitaré hacer acto de presencia.",
  ui_story_1015_10150601_89_dialog_content = "¡Aproveche esta oportunidad, capitán! ¡Esta es una gran oportunidad para completar el período de prueba para su reincorporación de una sola vez!",
  ui_story_1015_10150601_90_dialog_content = "Además de ti, ¿qué otros niños se mencionan en la carta de invitación?",
  ui_story_1015_10150601_91_dialog_content = "Es un poco extraño cómo Dawn Academy recibió cuatro invitaciones esta vez.",
  ui_story_1015_10150601_92_dialog_content = "Además de mí, hay uno para Chloe, Uriah... y Beretta.",
  ui_story_1015_10150601_93_dialog_content = "Pero para ser honesto, no estoy particularmente interesado en este Ejercicio Militar Conjunto.",
  ui_story_1015_10150601_94_dialog_content = "En el último ejercicio militar, llevé a mi equipo a la victoria.",
  ui_story_1015_10150601_95_dialog_content = "Y no necesito usar este honor sin sentido para recuperar mi posición oficial.",
  ui_story_1015_10150601_96_dialog_content = "¡Ja! Sabía que dirías algo así...",
  ui_story_1015_10150601_97_dialog_content = "Entonces... Beretta, estarás bien? ¿Tiene algún problema para trabajar con Chloe y Uriah?",
  ui_story_1015_10150601_98_dialog_content = "¡¿Qué?!",
  ui_story_1015_10150601_99_dialog_content = "Espero que puedas hacerte cargo y liderar el equipo. Beretta a la victoria de Lumopolis.",
  ui_story_1015_10150601_100_dialog_content = "Esta no es la primera vez que deja Lumopolis para emprender una tarea externa. Creo que deberías ser capaz de manejarlo.",
  ui_story_1015_10150601_101_dialog_content = "¡Por supuesto! ¡Apreciaré esta oportunidad!",
  ui_story_1015_10150601_102_dialog_content = "jeje, Chloe y Uriah están a punto de encontrarse en manos de la pequeña Beretta.",
  ui_story_1015_10150601_103_dialog_content = "¡Asegúrate de protegerlos bien!",
  ui_story_1015_10150601_104_dialog_content = "¡Lo haré!",
  ui_story_1015_10150601_105_dialog_content = "Sin embargo... lo único de lo que no estoy seguro es del viaje al Ejercicio Militar Conjunto.",
  ui_story_1015_10150601_106_dialog_content = "Escuché que las Entrañas de Illumina son como laberintos, y nunca antes había estado en uno...",
  ui_story_1015_10150601_107_dialog_content = "Oh, no tienes que preocuparte por eso.",
  ui_story_1015_10150601_108_dialog_content = "Aunque no estaré al frente de su equipo, planeo ir a Gannon City con usted.",
  ui_story_1015_10150601_109_dialog_content = "¿Oh, pero por que?",
  ui_story_1015_10150601_110_dialog_content = "Bueno... esos dos de ahí me están dando motivo de preocupación...",
  ui_story_1015_10150701_1_dialog_content = "<color=#e8d9bb>Federación Illumina, Entrañas X</color>",
  ui_story_1015_10150701_2_dialog_content = "Oficial de inteligencia de la Federación Illumina Anatoli, reportándose para el deber. Por orden del Comité, estoy aquí para asistirlo, Coronel Yingel.",
  ui_story_1015_10150701_3_dialog_content = "¿También es oficial de inteligencia?",
  ui_story_1015_10150701_4_dialog_content = "Ah... te conozco. Eres el diputado que acompañó al Gran Mariscal a Eraveil hace un tiempo para luchar contra el Eclipse.",
  ui_story_1015_10150701_5_dialog_content = "si, coronel Yingel, su información es realmente muy precisa. He estado esperando la oportunidad de trabajar contigo durante mucho tiempo.",
  ui_story_1015_10150701_6_dialog_content = "Basta de halagos. Preparémonos para la acción lo más rápido posible.",
  ui_story_1015_10150701_7_dialog_content = "¿Qué es eso que estás anotando?",
  ui_story_1015_10150701_8_dialog_content = "Oh, este es mi cuaderno. Acabo de hacer un boceto de usted con una nota: \"un coronel con una personalidad directa\".",
  ui_story_1015_10150701_9_dialog_content = "Tú... Bueno, si así es como sueles operar, no interferiré.",
  ui_story_1015_10150701_10_dialog_content = "Tu misión esta vez es trabajar conmigo para rescatar a los rehenes y capturar a Forsakin.",
  ui_story_1015_10150701_11_dialog_content = "Disculpe la interrupción, coronel. Yingel. Forsakin está... ¿en esta Ciudad Subterránea? ¿Y quiénes son los rehenes?",
  ui_story_1015_10150701_12_dialog_content = "Ejem... Déjame informarte sobre la situación actual.",
  ui_story_1015_10150701_13_dialog_content = "Forsakin, a quien Illumina alguna vez quiso, se ha llevado al teniente Vice y PlayerName.",
  ui_story_1015_10150701_14_dialog_content = "También ha intentado infiltrarse en el laboratorio de investigación para realizar sus experimentos.",
  ui_story_1015_10150701_15_dialog_content = "Creo que sus acciones deben estar relacionadas con lo que sucedió durante el conflicto en Eraveil.",
  ui_story_1015_10150701_16_dialog_content = "Ella está interesada en los cambios a teniente. Vice producido por la tecnología Caelestite.",
  ui_story_1015_10150701_17_dialog_content = "¡Si ese es el caso, los dos están en una situación muy peligrosa!",
  ui_story_1015_10150701_18_dialog_content = "La red de inteligencia de Illumina es intrincada y compleja. Con Forsakin secuestrando a dos figuras prominentes, no hay forma de que un incidente así pase desapercibido.",
  ui_story_1015_10150701_19_dialog_content = "Lo preocupante es que el teniente Vice se separó de PlayerName.",
  ui_story_1015_10150701_20_dialog_content = "Entonces, nuestra operación se dividirá en dos etapas.",
  ui_story_1015_10150701_21_dialog_content = "Etapa uno: localizar al teniente Vice tan pronto como sea posible, y asegúrate de llegar a ella antes que Forsakin.",
  ui_story_1015_10150701_22_dialog_content = "Etapa dos: poner fin al plan de Forsakin. ella puede tener PlayerName, pero ella no se atrevería a tomar ningún tipo de acción imprudente contra él.",
  ui_story_1015_10150701_23_dialog_content = "Si tenemos una oportunidad adecuada, sería mejor si capturáramos a Forsakin de una sola vez.",
  ui_story_1015_10150701_24_dialog_content = "¡Sí, señora! Entiendo...",
  ui_story_1015_10150701_25_dialog_content = "¿Qué estás haciendo ahora?",
  ui_story_1015_10150701_26_dialog_content = "Estoy dibujando un mapa basado en mis registros anteriores de las personas involucradas y las acciones de estos individuos para predecir sus próximos cursos de acción posibles.",
  ui_story_1015_10150701_27_dialog_content = "... Eres realmente algo.",
  ui_story_1015_10150701_28_dialog_content = "<color=#e8d9bb>¡Bip, bip!</color>",
  ui_story_1015_10150701_29_dialog_content = "¿Eh...?",
  ui_story_1015_10150701_30_dialog_content = "(¿Es esto... un nuevo visitante?)",
  ui_story_1015_10150701_31_dialog_content = "<color=#e8d9bb>Mientras tanto en Entrañas X</color>",
  ui_story_1015_10150701_32_dialog_content = "...",
  ui_story_1015_10150701_33_dialog_content = "no te detengas Mantenga.",
  ui_story_1015_10150701_34_dialog_content = "¿Qué es?",
  ui_story_1015_10150701_35_dialog_content = "Cuando nos pidió que cooperáramos con usted, no dijo que nuestras vidas estarían en peligro.",
  ui_story_1015_10150701_36_dialog_content = "Estás hablando de Vice? No te preocupes, ella estará bien. ¿Cómo podría permitir que ella muriera voluntariamente?",
  ui_story_1015_10150701_37_dialog_content = "¿Desea resistir, o tal vez retractarse de su promesa de cumplimiento?",
  ui_story_1015_10150701_38_dialog_content = "¡¿Por qué debería creerte?!",
  ui_story_1015_10150701_39_dialog_content = "Eres muy molesto.",
  ui_story_1015_10150701_40_dialog_content = "Toma esto.",
  ui_story_1015_10150701_41_dialog_content = "<color=#e8d9bb>Buzz Buzz...</color>",
  ui_story_1015_10150701_42_dialog_content = "Así que esto es para... Vice?",
  ui_story_1015_10150701_43_dialog_content = "Sí, cada pueblo de Illumina lleva un <color=#FFB400>comunicador</color>. Esta es su banda de frecuencia. He estado conectado a él todo el tiempo.",
  ui_story_1015_10150701_44_dialog_content = "Helios está con ella. Tendrá la oportunidad de hablar con ella y confirmar su estado en un momento.",
  ui_story_1015_10150701_45_dialog_content = "¿Y ahora?",
  ui_story_1015_10150701_46_dialog_content = "Ahora, por supuesto, me ayudarás a deshacerme de estos soldados entrometidos.",
  ui_story_1015_10150702_1_dialog_content = "Hola, Vice, ¿Puedes oírme?",
  ui_story_1015_10150702_2_dialog_content = "PlayerName! ¡¿Eres tu?!",
  ui_story_1015_10150702_3_dialog_content = "¿Estás aguantando bien, Vice?",
  ui_story_1015_10150702_4_dialog_content = "Estoy bien. Solo atrapado aquí por ahora.",
  ui_story_1015_10150702_5_dialog_content = "Parece que aquí no hay nada más que un almacén vacío.",
  ui_story_1015_10150702_6_dialog_content = "¿Un almacén?",
  ui_story_1015_10150702_7_dialog_content = "Le advierto que no se involucre en comunicaciones innecesarias.",
  ui_story_1015_10150702_8_dialog_content = "Si darte comunicadores aumenta los problemas que me traes...",
  ui_story_1015_10150702_9_dialog_content = "Bien, entiendo! ¿Podemos hablar de algo mas?",
  ui_story_1015_10150702_10_dialog_content = "Basta de hablar.",
  ui_story_1015_10150702_11_dialog_content = "Nuestro destino está más adelante, así que ocupémonos primero de los negocios.",
  ui_story_1015_10150702_12_dialog_content = "¿Qué es este lugar? ¿Qué estamos haciendo aquí?",
  ui_story_1015_10150702_13_dialog_content = "No te preocupes, es solo un gran <color=#FFB400>sala de referencia</color>. Una vez que consiga lo que quiero, podemos irnos.",
  ui_story_1015_10150702_14_dialog_content = "Después de todo, mi tiempo es valioso.",
  ui_story_1015_10150702_15_dialog_content = "Entonces, ¿por qué seguimos aquí parados en lugar de seguir adelante?",
  ui_story_1015_10150702_16_dialog_content = "Ven aquí.",
  ui_story_1015_10150702_17_dialog_content = "¿Qué es eso?",
  ui_story_1015_10150702_18_dialog_content = "Escaneando la información facial del visitante...",
  ui_story_1015_10150702_19_dialog_content = "Analizando datos de acceso...",
  ui_story_1015_10150702_20_dialog_content = "Acceso al archivo concedido.",
  ui_story_1015_10150702_21_dialog_content = "¿Cómo es que puedo abrirlo?",
  ui_story_1015_10150702_22_dialog_content = "¿No dije que todo el instituto de investigación solía ser mío? Sin embargo, Ulises hizo algunos cambios.",
  ui_story_1015_10150702_23_dialog_content = "Ya que lograste entrar a la gran sala de conferencias de Ulysses, ciertamente podrías ayudarme a abrir esta puerta.",
  ui_story_1015_10150702_24_dialog_content = "(El monitor debe haber capturado a Forsakin parado detrás de mí cuando escaneó mi rostro...)",
  ui_story_1015_10150702_25_dialog_content = "(Si alguien ve, no tardará mucho...)",
  ui_story_1015_10150702_26_dialog_content = "No te entretengas. Entra aquí rápido.",
  ui_story_1015_10150702_27_dialog_content = "Tú y Jade se paran en la puerta. Ciérralo y no hagas ningún problema.",
  ui_story_1015_10150702_28_dialog_content = "Si alguien entra de repente, Jade se encargará de ellos.",
  ui_story_1015_10150702_29_dialog_content = "... Al menos déjame saber qué archivo estás buscando.",
  ui_story_1015_10150702_30_dialog_content = "Busco datos que Ulises nunca hará públicos.",
  ui_story_1015_10150702_31_dialog_content = "Quiero ver los datos de prueba para el <color=#FFB400>Programa Fósforo</color>.",
  ui_story_1015_10150801_1_dialog_content = "<color=#e8d9bb>No hace mucho...</color>",
  ui_story_1015_10150801_2_dialog_content = "Um... Política de privacidad: de acuerdo, términos de usuario: ¡de acuerdo!",
  ui_story_1015_10150801_3_dialog_content = "Actualizar los archivos necesarios...",
  ui_story_1015_10150801_4_dialog_content = "<color=#e8d9bb>¡Bang, bang!</color>",
  ui_story_1015_10150801_5_dialog_content = "Pasa adelante...",
  ui_story_1015_10150801_6_dialog_content = "Oficial técnico, una chica que dice ser la capitana de la guardia de Lumopolis desea verte.",
  ui_story_1015_10150801_7_dialog_content = "Oh, la chica de Lumopolis. Dile que se pare en el lado izquierdo de la pantalla de inicio...",
  ui_story_1015_10150801_8_dialog_content = "S-Pantalla de inicio?",
  ui_story_1015_10150801_9_dialog_content = "¡Ja! ¡Lo siento, tengo juegos en el cerebro!",
  ui_story_1015_10150801_10_dialog_content = "¿Mmm? Carleen?",
  ui_story_1015_10150801_11_dialog_content = "Jeje! Sr. científico, será mejor que tenga cuidado con sus modales: la persona que está a su lado es el campeón del último Ejercicio Militar Conjunto, ¿no lo sabe?",
  ui_story_1015_10150801_12_dialog_content = "Perdóneme, pero debido a preocupaciones sobre el estado de Soroz, planeé venir aquí para confirmar la situación con usted primero.",
  ui_story_1015_10150801_13_dialog_content = "Por cierto, ¿no Vice y PlayerName ¿aquí?",
  ui_story_1015_10150801_14_dialog_content = "¿Dices Soroz? Oye, gracias por tu viaje a Crepúsculo—",
  ui_story_1015_10150801_15_dialog_content = "¡Echar un vistazo! Ahora está levantado y puede incluso batir sus alas.",
  ui_story_1015_10150801_16_dialog_content = "Después de algunos arreglos con Illumina Tech, ahora ha vuelto a ser el mismo de siempre, sin miedo a fallar.",
  ui_story_1015_10150801_17_dialog_content = "Gracias por todos los mejores deseos, señorita Gronru.",
  ui_story_1015_10150801_18_dialog_content = "Ah, es una pena... Sin PlayerName y sus servicios de traducción psíquica, ¡no puedo escuchar a Soroz dándome las gracias en este momento!",
  ui_story_1015_10150801_19_dialog_content = "Si Soroz está bien, eso es simplemente notable.",
  ui_story_1015_10150801_20_dialog_content = "Carleen, ¿confía en el Ejercicio Militar Conjunto?",
  ui_story_1015_10150801_21_dialog_content = "Permítanme compartir con ustedes otra pequeña estrategia por adelantado. Tus oponentes esta vez no serán tan fáciles de tratar como lo fueron en el pasado.",
  ui_story_1015_10150801_22_dialog_content = "No, en realidad, ya elegí no participar. El equipo de Lumopolis estará dirigido por otra persona.",
  ui_story_1015_10150801_23_dialog_content = "¿Eh? Ah, claro...",
  ui_story_1015_10150801_24_dialog_content = "Ustedes tres realmente necesitan reunirse rápido porque—",
  ui_story_1015_10150801_25_dialog_content = "¡La invitación que tienes está bajo la formación de Team PlayerName!",
  ui_story_1015_10150801_26_dialog_content = "Veo. En ese caso, esta también será la primera vez que los caelestitas estén representados en ejercicios militares en muchos años.",
  ui_story_1015_10150801_27_dialog_content = "Así es, ¡así que hazme un favor y no te andes con rodeos!",
  ui_story_1015_10150801_28_dialog_content = "Veo. Gracias.",
  ui_story_1015_10150801_29_dialog_content = "Entonces, PlayerName y Vice son...",
  ui_story_1015_10150801_30_dialog_content = "Hmm, espera un segundo...",
  ui_story_1015_10150801_31_dialog_content = "<color=#e8d9bb>¡Bip-bip-!</color>",
  ui_story_1015_10150801_32_dialog_content = "He implantado un pase y un mapa en su invitación.",
  ui_story_1015_10150801_33_dialog_content = "Las coordenadas resaltadas en el mapa son para Entrañas X, que es donde Illumina trata y estudia aurorianos especiales.",
  ui_story_1015_10150801_34_dialog_content = "(Pero... PlayerName y Vice He estado allí por tanto tiempo...)",
  ui_story_1015_10150801_35_dialog_content = "Esencialmente, este pase le otorgará acceso a la mayoría de las instalaciones de Illumina.",
  ui_story_1015_10150801_36_dialog_content = "Muchas gracias. No hay tiempo que perder entonces, me despediré.",
  ui_story_1015_10150801_37_dialog_content = "¡Adelante! Este lugar no es como Lumopolis: no encontrarás guardias que te acompañen... ¡Mantente a salvo ahí fuera!",
  ui_story_1015_10150801_38_dialog_content = "<color=#e8d9bb>Federación Illumina, Entrañas X</color>",
  ui_story_1015_10150801_39_dialog_content = "(Según las instrucciones en el mapa, esta debería ser la ubicación Gronru mencionado...)",
  ui_story_1015_10150801_40_dialog_content = "(Sin embargo, este lugar es aún más grande de lo que imaginaba).",
  ui_story_1015_10150801_41_dialog_content = "(Si no me equivoco, usar edificios grandes y densos para mantener a su gran población es la estrategia de supervivencia de Illumina).",
  ui_story_1015_10150801_42_dialog_content = "?!?",
  ui_story_1015_10150801_43_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_1015_10150801_44_dialog_content = "¿Quién está ahí?",
  ui_story_1015_10150801_45_dialog_content = "... Yingel?",
  ui_story_1015_10150801_46_dialog_content = "Entonces, usted es quien activó la alerta de visitante.",
  ui_story_1015_10150801_47_dialog_content = "¿Qué estás haciendo aquí? Oh, lo sé.",
  ui_story_1015_10150801_48_dialog_content = "Todos estamos más o menos motivados por el mismo objetivo.",
  ui_story_1015_10150801_49_dialog_content = "¿Cuál es la situación en la actualidad? ¿Me lo podrías explicar por favor?",
  ui_story_1015_10150801_50_dialog_content = "¡Shhh—!",
  ui_story_1015_10150801_51_dialog_content = "<anim type=Shake>Gaah... Graaah...</anim>",
  ui_story_1015_10150801_52_dialog_content = "Al menos esperemos hasta que terminemos de luchar contra estos eclipses.",
  ui_story_1015_10150801_53_dialog_content = "¿Que estas esperando? Hagámoslo.",
  ui_story_1015_10150802_1_dialog_content = "¡¿Cómo podría suceder tal cosa?! ¡Todo esto es demasiado ridículo!",
  ui_story_1015_10150802_2_dialog_content = "¿Qué quiere exactamente Forsakin?",
  ui_story_1015_10150802_3_dialog_content = "¿Por qué Illumina no ha enviado tropas para rodearla y neutralizarla todavía?",
  ui_story_1015_10150802_4_dialog_content = "Mantenga la calma, Carleen. Esto no es Lumopolis: cada decisión importante requiere el consentimiento conjunto de varias partes.",
  ui_story_1015_10150802_5_dialog_content = "El Comité ya ha comenzado a hacer los preparativos, y somos simplemente el equipo de vanguardia enviado antes del proceso de toma de decisiones.",
  ui_story_1015_10150802_6_dialog_content = "Entonces, ¿cuál es nuestro próximo curso de acción?",
  ui_story_1015_10150802_7_dialog_content = "Desde la perspectiva de un oficial de inteligencia, necesitamos consolidar nuestra inteligencia y acercarnos a Forsakin de la manera más eficiente posible.",
  ui_story_1015_10150802_8_dialog_content = "En cuanto a las pistas de inteligencia, creo que podemos empezar con las omnipresentes cámaras de vigilancia por aquí.",
  ui_story_1015_10150802_9_dialog_content = "Todo lo que necesito hacer es solicitar permiso para revisar los registros de vigilancia, y deberíamos poder ver claramente dónde Forsakin y Vice son de un vistazo.",
  ui_story_1015_10150802_10_dialog_content = "Me temo que no podemos hacer eso.",
  ui_story_1015_10150802_11_dialog_content = "No sé por qué, pero las cámaras aquí solo se usan para verificar la identidad y todos los registros se eliminan de inmediato.",
  ui_story_1015_10150802_12_dialog_content = "Cómo...",
  ui_story_1015_10150802_13_dialog_content = "¿Por qué todo esto suena tan sospechoso?",
  ui_story_1015_10150802_14_dialog_content = "De todos modos, no podemos deambular a ciegas por esta Ciudad Subterránea.",
  ui_story_1015_10150802_15_dialog_content = "No te preocupes, acabo de pensar en algo.",
  ui_story_1015_10150802_16_dialog_content = "Cuando se trata de asuntos de Illumina, por supuesto, debemos utilizar las soluciones de Illumina.",
  ui_story_1015_10150901_1_dialog_content = "(He buscado en todos los archivos de prefijo A numerados entre 1 y 50, pero aún no puedo encontrarlo).",
  ui_story_1015_10150901_2_dialog_content = "(Necesito encontrar otra manera. Me llevará un mes leer todos los encabezados de los archivos solo en estos gabinetes).",
  ui_story_1015_10150901_3_dialog_content = "(Además de preguntarle a Ulysses directamente, necesito averiguar rápidamente las reglas de clasificación de estos gabinetes...)",
  ui_story_1015_10150901_4_dialog_content = "Vice, ¿tienes suficiente comida y agua allí?",
  ui_story_1015_10150901_5_dialog_content = "No te preocupes... Yo... todo... necesito.",
  ui_story_1015_10150901_6_dialog_content = "¿Qué?",
  ui_story_1015_10150901_7_dialog_content = "¿Eh? ¿Puedes oírme?",
  ui_story_1015_10150901_8_dialog_content = "Oh, puedo oírte claramente ahora. El sonido se volvió extraño y se estaba cortando justo ahora.",
  ui_story_1015_10150901_9_dialog_content = "¿Se está agotando la batería? Estas cosas no tienen mucha duración de la batería. Se agotan bastante rápido si los usas constantemente.",
  ui_story_1015_10150901_10_dialog_content = "¿Eh? Se van a quedar sin energía—",
  ui_story_1015_10150901_11_dialog_content = "Eres tan ruidoso. dámelo",
  ui_story_1015_10150901_12_dialog_content = "¡Ey! ¡¿Por qué me arrebataste el comunicador?!",
  ui_story_1015_10150901_13_dialog_content = "Te dejaré jugar con él más tarde. Ven y ayúdame primero.",
  ui_story_1015_10150901_14_dialog_content = "¿Qué quieres esta vez?",
  ui_story_1015_10150901_15_dialog_content = "¿Pueden ustedes Caelestites sentir objetos que Aurorianos específicos pueden haber tocado recientemente?",
  ui_story_1015_10150901_16_dialog_content = "Ayúdame a echar un vistazo.",
  ui_story_1015_10150901_17_dialog_content = "... ¿Qué crees que soy, un perro?!",
  ui_story_1015_10150901_18_dialog_content = "Tsk, debería haberte arrojado a esa máquina en la torre.",
  ui_story_1015_10150901_19_dialog_content = "Si no puede hacer eso, venga y dígame si puede descifrar la contraseña de esta consola.",
  ui_story_1015_10150901_20_dialog_content = "Me acabo de dar cuenta yo mismo... Esta máquina es realmente algo.",
  ui_story_1015_10150901_21_dialog_content = "Cada sitio de investigación tiene un dispositivo como este.",
  ui_story_1015_10150901_22_dialog_content = "Se puede utilizar para buscar información y controlar operaciones mecánicas. En definitiva, es una herramienta de ayuda a los investigadores.",
  ui_story_1015_10150901_23_dialog_content = "Comprendo.",
  ui_story_1015_10150901_24_dialog_content = "¿Tengo que operarlo? Tal vez no debería, solo para estar seguro.",
  ui_story_1015_10150901_25_dialog_content = "Realmente no sé nada sobre la tecnología Illumina.",
  ui_story_1015_10150901_26_dialog_content = "... Menos charla mas accion.",
  ui_story_1015_10150901_27_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1015_10150901_28_dialog_content = "E-Espera un minuto, no ingreses dígitos aleatorios así...",
  ui_story_1015_10150901_29_dialog_content = "El propósito de la tecnología es servir a la investigación científica. Si no puedo usarlo, no tiene sentido que exista.",
  ui_story_1015_10150901_30_dialog_content = "<color=#e8d9bb>Bip, bip—bip—</color>",
  ui_story_1015_10150901_31_dialog_content = "... Bien.",
  ui_story_1015_10150901_32_dialog_content = "(Afortunadamente, parece que ella realmente sabe cómo descifrar esta cosa).",
  ui_story_1015_10150901_33_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1015_10150901_34_dialog_content = "<color=#e8d9bb>¡Advertencia! ¡Advertencia!</color>",
  ui_story_1015_10150901_35_dialog_content = "<color=#e8d9bb>Error de contraseña, medidas de alerta de emergencia activadas—</color>",
  ui_story_1015_10150901_36_dialog_content = "¡¿Qué?!",
  ui_story_1015_10150901_37_dialog_content = "<anim type=Shake><size=45>bip—bip—</size></anim>",
  ui_story_1015_10150901_38_dialog_content = "¿Qué es esta cosa...?",
  ui_story_1015_10150901_39_dialog_content = "¿¡¿No estás siendo un poco demasiado confiado?!? ¡Abandonado!",
  ui_story_1015_10150901_40_dialog_content = "Los errores son inevitables y la tecnología electrónica no es mi fuerte.",
  ui_story_1015_10150901_41_dialog_content = "Piensa en algo... ¡Ahora no es el momento de analizar tus defectos!",
  ui_story_1015_10150901_42_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1015_10150901_43_dialog_content = "Todo lo que tomó fue tirar del freno eléctrico de este archivo.",
  ui_story_1015_10150901_44_dialog_content = "¿Estás seguro?",
  ui_story_1015_10150901_45_dialog_content = "...",
  ui_story_1015_10150901_46_dialog_content = "<anim type=Shake><size=45>bip—bip—</size></anim>",
  ui_story_1015_10150901_47_dialog_content = "¡Eso no sirvió de nada!",
  ui_story_1015_10150901_48_dialog_content = "Tsk... Qué problemático.",
  ui_story_1015_10150901_49_dialog_content = "Todavía tenemos que lidiar con este perro mecánico primero. Jade-",
  ui_story_1015_10150901_50_dialog_content = "<anim type=Shake><size=50>Graagh!!!</size></anim>",
  ui_story_1015_10150901_51_dialog_content = "Carga adelante y masticalo.",
  ui_story_1015_10150902_1_dialog_content = "<anim type=Shake><size=45>Chom... Chom...</size></anim>",
  ui_story_1015_10150902_2_dialog_content = "Bien hecho. Come hasta saciarte.",
  ui_story_1015_10150902_3_dialog_content = "Sigue vigilando la puerta por mí, ¿entendido?",
  ui_story_1015_10150902_4_dialog_content = "<anim type=Shake><size=45>Rugido...</size></anim>",
  ui_story_1015_10150902_5_dialog_content = "¿Es esta máquina... algún tipo de medida de seguridad?",
  ui_story_1015_10150902_6_dialog_content = "No sé. No estaba aquí cuando me fui.",
  ui_story_1015_10150902_7_dialog_content = "Ya hemos perdido demasiado tiempo. Tenemos que ser rápidos a partir de ahora.",
  ui_story_1015_10150902_8_dialog_content = "<color=#e8d9bb>Bip, bip—bip—</color>",
  ui_story_1015_10150902_9_dialog_content = "<color=#e8d9bb>¡Centro de almacenamiento activado!</color>",
  ui_story_1015_10150902_10_dialog_content = "Continuar la búsqueda, Programa Phospherus.",
  ui_story_1015_10150902_11_dialog_content = "... No, si no podemos encontrar más información...",
  ui_story_1015_10150902_12_dialog_content = "Cambio de palabra clave, búsqueda de <color=#FFB400>Proyecto Sol Artificial</color>.",
  ui_story_1015_10150902_13_dialog_content = "(Artificial... ¿Sol? ¿Qué significa eso? ¿Tiene algo que ver con la creación de un sol enorme?)",
  ui_story_1015_10150902_14_dialog_content = "(En un momento es Phospherus, al siguiente es esto... ¿Qué está buscando exactamente Forsakin...?)",
  ui_story_1015_10150902_15_dialog_content = "Lo encontré.",
  ui_story_1015_10150902_16_dialog_content = "Está bien, muévete.",
  ui_story_1015_10150902_17_dialog_content = "Forsakin, ¿cuál es exactamente el significado de esta información, y realmente vale la pena romper tus lazos con Ulysses de esta manera?",
  ui_story_1015_10150902_18_dialog_content = "¿De verdad quieres saber?",
  ui_story_1015_10150902_19_dialog_content = "Incluso si lo supieras, sería inútil para ti, ya que el dispositivo en Eraveil ya ha fallado.",
  ui_story_1015_10150902_20_dialog_content = "Además, mi investigación ha superado con creces el nivel de la tecnología Illumina y Caelestite.",
  ui_story_1015_10150902_21_dialog_content = "Te aconsejo que no intentes nada.",
  ui_story_1015_10150902_22_dialog_content = "Solo pregunto por curiosidad. Te ayudé con la batalla hace un momento, así que ¿no puedo al menos saber por qué he estado luchando?",
  ui_story_1015_10150902_23_dialog_content = "Teniendo en cuenta mi situación actual, no tienes que ser tan cauteloso, ¿verdad?",
  ui_story_1015_10150902_24_dialog_content = "...",
  ui_story_1015_10150902_25_dialog_content = "Bien. No estaría de más decírtelo.",
  ui_story_1015_10150902_26_dialog_content = "Es algo que ya sabes.",
  ui_story_1015_10150902_27_dialog_content = "¿Algo que yo sepa...?",
  ui_story_1015_10150902_28_dialog_content = "Fue cuando fuiste al Lodo y despertaste a Helios, que dormía mucho.",
  ui_story_1015_10150902_29_dialog_content = "Durante este tiempo, ella debe haberte contado todo sobre las experiencias pasadas compartidas por nosotros tres.",
  ui_story_1015_10150902_30_dialog_content = "En aquel entonces, los tres crecimos juntos, nos unimos al ejército juntos y luchamos juntos...",
  ui_story_1015_10150902_31_dialog_content = "Esta asociación a largo plazo ciertamente no se debió a razones sentimentales como la llamada amistad o lazos.",
  ui_story_1015_10150902_32_dialog_content = "Fue porque éramos los primeros sujetos de prueba de <color=#FFB400>Proyecto Sol Artificial</color>.",
  ui_story_1015_10150902_33_dialog_content = "Solo si experimentamos el mismo curso de desarrollo, enfrentamos las mismas batallas y aceptamos el mismo conjunto de modificaciones, podemos compararnos cualitativamente entre nosotros.",
  ui_story_1015_10150902_34_dialog_content = "Pero los primitivos métodos de investigación que utilizaron fueron totalmente insatisfactorios.",
  ui_story_1015_10150902_35_dialog_content = "Reinhardt resulta como ella es hoy en realidad me sorprendió.",
  ui_story_1015_10150902_36_dialog_content = "Más tarde, el nombre de este proyecto se cambió por el que suena más agradable. <color=#FFB400>fósforo</color>.",
  ui_story_1015_10150902_37_dialog_content = "Así que eso fue lo que pasó... Esa es la razón por la que estás haciendo todo esto.",
  ui_story_1015_10150902_38_dialog_content = "Tu expresión es repugnante. ¿Son todos los Caelestitas tan enfermizamente compasivos?",
  ui_story_1015_10150902_39_dialog_content = "Toma esto. Puedes intentar hablar con ella ahora.",
  ui_story_1015_10150902_40_dialog_content = "¡Oye!",
  ui_story_1015_10150902_41_dialog_content = "<color=#e8d9bb>Buzz Buzz...</color>",
  ui_story_1015_10150902_42_dialog_content = "¡PlayerName! ¿Estás bien?",
  ui_story_1015_10150902_43_dialog_content = "... Vice!",
  ui_story_1015_10150902_44_dialog_content = "<color=#e8d9bb>Buzz Buzz...</color>",
  ui_story_1015_10150902_45_dialog_content = "Ah...",
  ui_story_1015_10150902_46_dialog_content = "¡La banda de frecuencia de Vice está activa!",
  ui_story_1015_10150902_47_dialog_content = "¿Eres capaz de localizar inmediatamente la posición de Vice basándote en las ondas de radio?",
  ui_story_1015_10150902_48_dialog_content = "Con la tecnología actual de Illumina, podría no ser posible.",
  ui_story_1015_10150902_49_dialog_content = "Pero al menos sabemos que el teniente Vice está usando su comunicador.",
  ui_story_1015_10150902_50_dialog_content = "Esto indica que posee libertad de movimiento hasta cierto punto.",
  ui_story_1015_10150902_51_dialog_content = "Si mis sospechas son correctas, Forsakin debe estar al otro lado del comunicador del teniente antivicio.",
  ui_story_1015_10150902_52_dialog_content = "Acordado. Anatoli, vigile cualquier cambio de banda de frecuencia en el lado de Vice.",
  ui_story_1015_10150902_53_dialog_content = "Sí, señora. Servirá.",
  ui_story_1015_10150902_54_dialog_content = "Repasemos el plan de rescate.",
  ui_story_1015_10150902_55_dialog_content = "Mi información muestra que el sistema de alerta del archivo del profesor Ulysses acaba de activarse.",
  ui_story_1015_10150902_56_dialog_content = "Sin duda, Forsakin debe haber estado allí, y PlayerName estaba justo a su lado.",
  ui_story_1015_10150902_57_dialog_content = "Tan pronto como localicemos Vice, oficialmente comenzará el plan de rescate.",
  ui_story_1015_10151001_1_dialog_content = "Estoy bien, Vice! ¡Actualmente estoy en una sala de archivo en Undercity X con Forsakin!",
  ui_story_1015_10151001_2_dialog_content = "¿Qué pasa contigo? ¿Estás lastimado? ¡¿Dónde estás?!",
  ui_story_1015_10151001_3_dialog_content = "<anim type=Shake>Estoy en... puerta... luz...</anim>",
  ui_story_1015_10151001_4_dialog_content = "¿Eh? ¿Qué dijiste? Vice?",
  ui_story_1015_10151001_5_dialog_content = "¡Maldita sea! ¿Por qué no puedo oírla? ¿Este comunicador está muerto otra vez?",
  ui_story_1015_10151001_6_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1015_10151001_7_dialog_content = "Tu llamada ha terminado. Preguntaste algo que no deberías haber preguntado.",
  ui_story_1015_10151001_8_dialog_content = "¡No me dijiste si había algo que no debería preguntar! ¡Por supuesto que trataría de averiguar lo que quería saber!",
  ui_story_1015_10151001_9_dialog_content = "¿Qué estás tratando de ocultar, presionando el comunicador con tanta prisa?",
  ui_story_1015_10151001_10_dialog_content = "No me malinterpreten, yo no hice nada.",
  ui_story_1015_10151001_11_dialog_content = "La batería de esta patética máquina está agotada.",
  ui_story_1015_10151001_12_dialog_content = "(Esto es realmente...)",
  ui_story_1015_10151001_13_dialog_content = "(Esto es demasiado, y en un momento tan crítico...)",
  ui_story_1015_10151001_14_dialog_content = "Muy bien, no perdamos más tiempo.",
  ui_story_1015_10151001_15_dialog_content = "Preparémonos para partir. Nuevos experimentos están a la espera de ser llevados a cabo.",
  ui_story_1015_10151001_16_dialog_content = "Prácticamente nadie ha pisado esta zona salvo el profesor Ulises.",
  ui_story_1015_10151001_17_dialog_content = "Aquí solo hay dos puntos de referencia importantes. Además de los archivos donde sonó la alarma, también hay un laboratorio.",
  ui_story_1015_10151001_18_dialog_content = "No esperaba menos de usted, coronel Yingel... Aunque he estado trabajando en el Comité durante mucho tiempo, no sé nada sobre este lugar.",
  ui_story_1015_10151001_19_dialog_content = "Piense en ello como un informe confidencial: el profesor no desea que demasiadas personas sepan estas cosas.",
  ui_story_1015_10151001_20_dialog_content = "Entonces, depende de mí eliminar a cualquiera que ingrese a este lugar sin permiso con prejuicio extremo.",
  ui_story_1015_10151001_21_dialog_content = "¿Hay algún movimiento en el rango de frecuencia de Vice?",
  ui_story_1015_10151001_22_dialog_content = "Ella está en un estado de silencio de radio en este momento. Su transmisión debe haber sido cortada.",
  ui_story_1015_10151001_23_dialog_content = "dámelo—",
  ui_story_1015_10151001_24_dialog_content = "Teniente Vice? Vocación Vice, esto es Yingel, ¿Puedes oírme?",
  ui_story_1015_10151001_25_dialog_content = "Si puede ponerse en contacto conmigo, ¡hágalo inmediatamente!",
  ui_story_1015_10151001_26_dialog_content = "¡Ey! ¡¿Forsakin no te escucharía también si la llamaras así?!",
  ui_story_1015_10151001_27_dialog_content = "Normalmente, este sería el caso, pero el comunicador de Forsakin no tiene energía.",
  ui_story_1015_10151001_28_dialog_content = "¡¿Fuera del poder?!",
  ui_story_1015_10151001_29_dialog_content = "Estaba escuchando su conversación. PlayerName ha estado usando el comunicador con demasiada frecuencia, por lo que la batería se agotó muy rápidamente.",
  ui_story_1015_10151001_30_dialog_content = "A juzgar por lo que escuché, ahora está completamente fuera de servicio.",
  ui_story_1015_10151001_31_dialog_content = "El éxito o el fracaso de nuestra misión descansa en este momento.",
  ui_story_1015_10151001_32_dialog_content = "Es eso... Coronel Yingel?",
  ui_story_1015_10151001_33_dialog_content = "(¡Sí!)",
  ui_story_1015_10151001_34_dialog_content = "¡Reporta tu ubicación!",
  ui_story_1015_10151001_35_dialog_content = "¿Hay alguna característica distintiva en el lugar en el que te retienen? ¡Eso también servirá!",
  ui_story_1015_10151001_36_dialog_content = "¡Sí! Estoy encerrado en un almacén en Entrañas X, con puertas grises... ¡Aquí hay una ventana con luz natural!",
  ui_story_1015_10151001_37_dialog_content = "Copiado.",
  ui_story_1015_10151001_38_dialog_content = "Estaré inactivo en esta frecuencia indefinidamente. Preste atención al nivel de batería de su comunicador. Incluso si Forsakin te contacta de nuevo, todavía puedo escuchar todo.",
  ui_story_1015_10151001_39_dialog_content = "¿Quién más está contigo?",
  ui_story_1015_10151001_40_dialog_content = "Helios me trajo aquí, pero se fue hace un momento.",
  ui_story_1015_10151001_41_dialog_content = "Comprendido. Nos dirigiremos a usted de inmediato.",
  ui_story_1015_10151001_42_dialog_content = "Coronel Yingel, ¿Tienes alguna idea?",
  ui_story_1015_10151001_43_dialog_content = "Los almacenes de Entrañas X se concentran en el sur, ya que el terreno en el sur es bajo y fácil de defender, pero difícil de atacar.",
  ui_story_1015_10151001_44_dialog_content = "Entre ellos, los almacenes con puertas grises se utilizan específicamente para almacenar diversos productos farmacéuticos sólidos.",
  ui_story_1015_10151001_45_dialog_content = "El eco en el extremo de Vice era muy fuerte en este momento, por lo que debe estar en un gran almacén.",
  ui_story_1015_10151001_46_dialog_content = "Esto descarta todos los almacenes subterráneos y los diversos pequeños trasteros repartidos por el lugar.",
  ui_story_1015_10151001_47_dialog_content = "Así, el almacén en el que Vice está retenido se puede reducir a los almacenes X-106, X-107 y X-108.",
  ui_story_1015_10151001_48_dialog_content = "Entonces comencemos la búsqueda inmediatamente.",
  ui_story_1015_10151001_49_dialog_content = "Iré allí con Anatoli. Carleen, necesito que te encargues de algo por mí.",
  ui_story_1015_10151001_50_dialog_content = "Quiero que vayas a los archivos y rescates. PlayerName.",
  ui_story_1015_10151001_51_dialog_content = "Para garantizar la seguridad de ambos rehenes, sería mejor si completáramos el rescate simultáneamente.",
  ui_story_1015_10151001_52_dialog_content = "Veo. Comprendido.",
  ui_story_1015_10151001_53_dialog_content = "Está bien. Le proporcionaremos apoyo tan pronto como se haya completado el rescate por nuestra parte.",
  ui_story_1015_10151001_54_dialog_content = "Por favor tenga cuidado.",
  ui_story_1015_10151001_55_dialog_content = "<color=#e8d9bb>Entrañas X, Almacén del Sur</color>",
  ui_story_1015_10151001_56_dialog_content = "Como esperaba, es exactamente como lo predijo, coronel.",
  ui_story_1015_10151001_57_dialog_content = "Según las características que hay por aquí, creo que hemos encontrado el lugar adecuado.",
  ui_story_1015_10151001_58_dialog_content = "Coronel Yingel, ¿qué debemos hacer a continuación?",
  ui_story_1015_10151001_59_dialog_content = "Todo lo que podemos hacer ahora es probarlos uno por uno.",
  ui_story_1015_10151001_60_dialog_content = "Afortunadamente, Forsakin aún no ha tomado ninguna medida...",
  ui_story_1015_10151001_61_dialog_content = "<color=#e8d9bb>Ruido sordo-!</color>",
  ui_story_1015_10151001_62_dialog_content = "<anim type=Shake><size=50>Graagh!!!</size></anim>",
  ui_story_1015_10151001_63_dialog_content = "¿Q-Qué es esa cosa...?",
  ui_story_1015_10151001_64_dialog_content = "(¡Debe haber detectado nuestros movimientos...!)",
  ui_story_1015_10151001_65_dialog_content = "<anim type=Shake><size=50>Graagh!!!</size></anim>",
  ui_story_1015_10151001_66_dialog_content = "¡Cuidado! ¡Viene por aquí!",
  ui_story_1015_10151101_1_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_1015_10151101_2_dialog_content = "Golpe perfecto!",
  ui_story_1015_10151101_3_dialog_content = "<anim type=Shake><size=50>Grahhhhhhhh!</size></anim>",
  ui_story_1015_10151101_4_dialog_content = "¡¿Lo que está mal con él?!",
  ui_story_1015_10151101_5_dialog_content = "Según nuestra inteligencia, Gran Mariscal Reinhardt le asestó un duro golpe en su último encuentro...",
  ui_story_1015_10151101_6_dialog_content = "¿Cómo puede mantener un poder tan formidable?",
  ui_story_1015_10151101_7_dialog_content = "<anim type=Shake><size=50>¡Gahhhh!</size></anim>",
  ui_story_1015_10151101_8_dialog_content = "¡Cuidado!",
  ui_story_1015_10151101_9_dialog_content = "¡Urgh...!",
  ui_story_1015_10151101_10_dialog_content = "Gracias...",
  ui_story_1015_10151101_11_dialog_content = "No puede confiar demasiado en la inteligencia, coronel. Yingel, ya que a veces puede ser inexacto.",
  ui_story_1015_10151101_12_dialog_content = "Si esta inteligencia es realmente cierta, entonces...",
  ui_story_1015_10151101_13_dialog_content = "No, él, el Capitán Helios, probablemente ha estado viviendo solo en la Zona Oscura por más de diez años. Su mente debe estar retorcida más allá de la imaginación.",
  ui_story_1015_10151101_14_dialog_content = "Con este poder en su poder, no podemos permitirnos subestimarlo.",
  ui_story_1015_10151101_15_dialog_content = "Además, ha pasado por un proceso de mejora y transformación, al igual que el Gran Mariscal Reinhardt...",
  ui_story_1015_10151101_16_dialog_content = "Incluso nosotros dos combinados podríamos no ser ni la mitad de fuertes que el Gran Mariscal.",
  ui_story_1015_10151101_17_dialog_content = "Eso ya lo sé... No tiene que decirlo, mayor. Anatoli.",
  ui_story_1015_10151101_18_dialog_content = "Aquí hay demasiado espacio para maniobrar, y su movilidad es mucho mayor que la nuestra. Si continuamos comprometiéndonos, ¡solo terminaremos agotándonos!",
  ui_story_1015_10151101_19_dialog_content = "Retirémonos al corredor para restringir su movimiento.",
  ui_story_1015_10151101_20_dialog_content = "¡Entendido!",
  ui_story_1015_10151101_21_dialog_content = "<anim type=Shake>Grrr...</anim>",
  ui_story_1015_10151101_22_dialog_content = "...",
  ui_story_1015_10151101_23_dialog_content = "Él se está alejando.",
  ui_story_1015_10151101_24_dialog_content = "No podemos enfrentarlo de frente, pero podemos usar el terreno aquí para lanzar un ataque sorpresa dirigido a sus debilidades.",
  ui_story_1015_10151101_25_dialog_content = "Mientras Forsakin no...",
  ui_story_1015_10151101_26_dialog_content = "Oh no...",
  ui_story_1015_10151101_27_dialog_content = "<size=45>¡Esto es malo!</size>",
  ui_story_1015_10151101_28_dialog_content = "¿Qué es?",
  ui_story_1015_10151101_29_dialog_content = "Los aurorianos que han sido mejorados y modificados provocan reacciones especiales entre ellos.",
  ui_story_1015_10151101_30_dialog_content = "¡Me temo que Forsakin sentirá que estamos en combate con su compañero mutante!",
  ui_story_1015_10151101_31_dialog_content = "¡...!",
  ui_story_1015_10151101_32_dialog_content = "¡Esto parece ser información particularmente importante! ¿Por qué no me avisaste antes?",
  ui_story_1015_10151101_33_dialog_content = "El experimento es altamente confidencial.",
  ui_story_1015_10151101_34_dialog_content = "Si no fuera por la urgencia de la situación, toda la información relacionada con el experimento no habría estado disponible ni para usted ni para mí.",
  ui_story_1015_10151101_35_dialog_content = "Lo siento, cometí un error. No pude actualizarlo sobre la situación de manera oportuna con respecto a esto.",
  ui_story_1015_10151101_36_dialog_content = "Esto va a traer problemas...",
  ui_story_1015_10151101_37_dialog_content = "(El Comité... ¿Cuántos secretos siguen ocultando?)",
  ui_story_1015_10151101_38_dialog_content = "(Ya sea la modificación biológica secreta o el hecho de que la inteligencia que recuperó mi equipo fue manipulada...)",
  ui_story_1015_10151101_39_dialog_content = "(¿Realmente puedo confiar en ellos?)",
  ui_story_1015_10151101_40_dialog_content = "No podemos seguir luchando contra esta cosa aquí.",
  ui_story_1015_10151101_41_dialog_content = "Suponiendo que Forsakin ya haya detectado nuestra incursión, sería imposible para ella no estar en guardia.",
  ui_story_1015_10151101_42_dialog_content = "Teniente Vice todavía es seguro por el momento, pero no hay manera Carleen podría saber que nuestra presencia aquí ha sido descubierta.",
  ui_story_1015_10151101_43_dialog_content = "Tenemos que deshacernos de él rápidamente y apoyar Carleen.",
  ui_story_1015_10151101_44_dialog_content = "Por supuesto, pero no podemos hacer ambas cosas al mismo tiempo.",
  ui_story_1015_10151101_45_dialog_content = "El sigilo es tu punto fuerte: encuentra la oportunidad de escabullirte, rescata al teniente Vice, y luego diríjase rápidamente a Carleen.",
  ui_story_1015_10151101_46_dialog_content = "¿Y que hay de ti? ¿Qué vas a hacer?",
  ui_story_1015_10151101_47_dialog_content = "Forsakin será aún más difícil de tratar que este monstruo. Incluso con más que solo nosotros dos, nuestras posibilidades de ganar serán escasas.",
  ui_story_1015_10151101_48_dialog_content = "Necesito preparar mi carta de triunfo, una lo suficientemente poderosa como para nivelar el campo de juego.",
  ui_story_1015_10151101_49_dialog_content = "<color=#e8d9bb>Mientras tanto en PlayerName y la ubicación de Forsakin...</color>",
  ui_story_1015_10151101_50_dialog_content = "...",
  ui_story_1015_10151101_51_dialog_content = "<anim type=Shake>Rrr... Rugido...!</anim>",
  ui_story_1015_10151101_52_dialog_content = "Cállate, Jade.",
  ui_story_1015_10151101_53_dialog_content = "<anim type=Shake>Rugido...</anim>",
  ui_story_1015_10151101_54_dialog_content = "Eres tan ruidoso.",
  ui_story_1015_10151101_55_dialog_content = "Es. Cada vez que ruge, siento que mis tímpanos están a punto de estallar.",
  ui_story_1015_10151101_56_dialog_content = "Callarse la boca.",
  ui_story_1015_10151101_57_dialog_content = "Los ratones han salido a jugar.",
  ui_story_1015_10151101_58_dialog_content = "¿Ratones?",
  ui_story_1015_10151101_59_dialog_content = "(Esta Lumina... ¿Podría ser...?)",
  ui_story_1015_10151101_60_option_content = "Usa la habilidad psíquica",
  ui_story_1015_10151101_61_dialog_content = "(Carleen?!)",
  ui_story_1015_10151101_62_dialog_content = "Salga.",
  ui_story_1015_10151101_63_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1015_10151101_64_dialog_content = "Que tonto.",
  ui_story_1015_10151101_65_dialog_content = "<size=45>(Carleen! ¡Cuidado!)</size>",
  ui_story_1015_10151101_66_dialog_content = "(Qué...)",
  ui_story_1015_10151101_67_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_1015_10151101_68_dialog_content = "¡Tos... tos, tos!",
  ui_story_1015_10151101_69_dialog_content = "¿Como lo descubriste?",
  ui_story_1015_10151101_70_dialog_content = "Tus tácticas son torpes en el mejor de los casos.",
  ui_story_1015_10151101_71_dialog_content = "...",
  ui_story_1015_10151101_72_dialog_content = "Sin embargo, como factor que puede afectar los resultados de mi experimento, el esfuerzo que me llevará eliminarte debería valer la pena.",
  ui_story_1015_10151101_73_dialog_content = "<anim type=Shake>Rugido...</anim>",
  ui_story_1015_10151101_74_dialog_content = "Hay muchos de ellos...",
  ui_story_1015_10151101_75_dialog_content = "Ataque.",
  ui_story_1015_10151101_76_dialog_content = "<anim type=Shake><size=50>Graagh!!!</size></anim>",
  ui_story_1015_10151102_1_dialog_content = "¡¡¡Urgh...!!!",
  ui_story_1015_10151102_2_dialog_content = "<anim type=Shake><size=45>¡Grahhhh!</size></anim>",
  ui_story_1015_10151102_3_dialog_content = "No hay final para ellos...",
  ui_story_1015_10151102_4_dialog_content = "¡¡¡Carleen!!!",
  ui_story_1015_10151102_5_dialog_content = "Planeaste un ataque de dos frentes, con la intención de tomar Caelestite y esa niña al mismo tiempo.",
  ui_story_1015_10151102_6_dialog_content = "Sin embargo, para dividir y vencer, uno debe tener absoluta confianza en la propia habilidad.",
  ui_story_1015_10151102_7_dialog_content = "¿Cómo lo supiste?",
  ui_story_1015_10151102_8_dialog_content = "Todo es gracias a esos viejos perros y su proyecto.",
  ui_story_1015_10151102_9_dialog_content = "¿Te refieres a la conexión especial? Reinhardt ¿mencionado?",
  ui_story_1015_10151102_10_dialog_content = "Oh no, si posees esta habilidad, entonces Yingel y Anatoli—",
  ui_story_1015_10151102_11_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1015_10151102_12_dialog_content = "¡Tos... tos, tos, tos!",
  ui_story_1015_10151102_13_dialog_content = "Esto es-!",
  ui_story_1015_10151102_14_dialog_content = "<anim type=Shake>Rugido...</anim>",
  ui_story_1015_10151102_15_dialog_content = "Otro ratón.",
  ui_story_1015_10151102_16_dialog_content = "Anatoli! ¿Cómo has llegado hasta aquí?",
  ui_story_1015_10151102_17_dialog_content = "donde esta Vice!",
  ui_story_1015_10151102_18_dialog_content = "Lo siento. Fui descubierto y no pude encontrar donde Teniente Vice estaba siendo retenido. no pude rescatarla...",
  ui_story_1015_10151102_19_dialog_content = "Parece que lo único que tenéis entre vosotros es arrogancia e incompetencia.",
  ui_story_1015_10151102_20_dialog_content = "Mi trabajo aquí pronto se completará. Ya no estás en uso.",
  ui_story_1015_10151102_21_dialog_content = "...",
  ui_story_1015_10151102_22_dialog_content = "¡No!",
  ui_story_1015_10151102_23_dialog_content = "Y así estamos rodeados...",
  ui_story_1015_10151102_24_dialog_content = "Cuelga ahí PlayerName, Carleen.",
  ui_story_1015_10151102_25_dialog_content = "No lo olvides, todavía tenemos Coronel Yingel.",
  ui_story_1015_10151102_26_dialog_content = "Ir. Cuida de ellos-",
  ui_story_1015_10151102_27_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_1015_10151102_28_dialog_content = "Forsakin, ¿me lees?",
  ui_story_1015_10151102_29_dialog_content = "Me preguntaba dónde podría estar el ratón perdido.",
  ui_story_1015_10151102_30_dialog_content = "Resulta que se esconde en algún lugar lejano.",
  ui_story_1015_10151102_31_dialog_content = "Sea lo que sea que estés tratando de hacer, detente en este instante.",
  ui_story_1015_10151102_32_dialog_content = "De lo contrario, te prometo que te arrepentirás.",
  ui_story_1015_10151102_33_dialog_content = "...",
  ui_story_1015_10151102_34_dialog_content = "¿Qué has hecho?",
  ui_story_1015_10151102_35_dialog_content = "Gracias a Anatoli y los esfuerzos de Carleen, pude cubrir el área alrededor del laboratorio Chord Link con <color=#FFB400>explosivos</color> mientras me compraban algo de tiempo.",
  ui_story_1015_10151102_36_dialog_content = "Mi arma apunta ahora a uno de los cañones. Tan pronto como apriete el gatillo, el Chord Link se perderá para siempre en llamas, junto con sus valiosos datos.",
  ui_story_1015_10151102_37_dialog_content = "¡¿?!",
  ui_story_1015_10151102_38_dialog_content = "Una escena familiar, ¿no crees, Forsakin?",
  ui_story_1015_10151102_39_dialog_content = "Ahora, ríndete inmediatamente y suelta PlayerName y los otros.",
  ui_story_1015_10151102_40_dialog_content = "...",
  ui_story_1015_10151102_41_dialog_content = "<size=45>Fuego... ¡Hay fuego por todas partes!</size>",
  ui_story_1015_10151102_42_dialog_content = "<size=45>¡Mi experimento! Mi experimento!!!</size>",
  ui_story_1015_10151102_43_dialog_content = "Je.",
  ui_story_1015_10151102_44_dialog_content = "Esas cosas viejas no tienen mucho talento para la investigación, pero son bastante buenas para entrenar perros.",
  ui_story_1015_10151102_45_dialog_content = "¡Tú!",
  ui_story_1015_10151102_46_dialog_content = "No te atreverías.",
  ui_story_1015_10151102_47_dialog_content = "El Chord Link es el epítome de la antigua tecnología Caelestite. No es algo con lo que puedas tropezar al costado del camino.",
  ui_story_1015_10151102_48_dialog_content = "Solo existe un dispositivo de este tipo en toda la Federación Illumina.",
  ui_story_1015_10151102_49_dialog_content = "Sin mencionar los datos almacenados dentro de la máquina. La totalidad del Programa Phospherus puede ser solo la punta del iceberg.",
  ui_story_1015_10151102_50_dialog_content = "Como su perro entrenado, no hay forma de que no te des cuenta de todo esto.",
  ui_story_1015_10151102_51_dialog_content = "Si esos viejos fósiles tuvieran que pesar el Chord Link y sus datos en la balanza de sus mejores intereses, sus vidas ni siquiera calificarían como contrapesos.",
  ui_story_1015_10151102_52_dialog_content = "¿En serio?",
  ui_story_1015_10151102_53_dialog_content = "Bueno, entonces intentémoslo.",
  ui_story_1015_10151102_54_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1015_10151201_1_dialog_content = "<color=#e8d9bb>Boom—!!!</color>",
  ui_story_1015_10151201_2_dialog_content = "Fuego...",
  ui_story_1015_10151201_3_dialog_content = "Esta en llamas...",
  ui_story_1015_10151201_4_dialog_content = "¡Helios, ven conmigo al laboratorio!",
  ui_story_1015_10151201_5_dialog_content = "<anim type=Shake><size=45>Rugido-!</size></anim>",
  ui_story_1015_10151201_6_dialog_content = "¡Es nuestra oportunidad!",
  ui_story_1015_10151201_7_dialog_content = "¡Dispérsate, flor de hielo!",
  ui_story_1015_10151201_8_dialog_content = "¡Cuidado, los eclipses se están acercando de nuevo!",
  ui_story_1015_10151201_9_dialog_content = "<anim type=Shake><size=45>Graagh!!!</size></anim>",
  ui_story_1015_10151201_10_dialog_content = "<color=#e8d9bb>¡Estallido! ¡Blam!</color>",
  ui_story_1015_10151201_11_dialog_content = "<anim type=Shake>Graah...</anim>",
  ui_story_1015_10151201_12_dialog_content = "¡Ahora! Aprovecha esta oportunidad de ahorrar PlayerName!",
  ui_story_1015_10151201_13_dialog_content = "¡Sí, señora!",
  ui_story_1015_10151201_14_dialog_content = "PlayerName¡Te desataré!",
  ui_story_1015_10151201_15_dialog_content = "Gracias...",
  ui_story_1015_10151201_16_dialog_content = "Es Vice ¿está bien? ¿Donde esta ella?",
  ui_story_1015_10151201_17_dialog_content = "Lo siento, fui descubierto por el enemigo y no pude encontrar al teniente. Vice...",
  ui_story_1015_10151201_18_dialog_content = "Pero no hay otros enemigos en esa área, así que al menos puedo garantizarle que el teniente Vice es seguro.",
  ui_story_1015_10151201_19_dialog_content = "No te preocupes, alguien más está en camino para salvar Vice.",
  ui_story_1015_10151201_20_dialog_content = "Lo que debes hacer ahora es evitar que Forsakin complete su experimento.",
  ui_story_1015_10151201_21_dialog_content = "Entonces, no destruiste el Chord Link.",
  ui_story_1015_10151201_22_dialog_content = "¿Qué? ¿No fue destruido?",
  ui_story_1015_10151201_23_dialog_content = "¿Cómo pude permitir que algo así fuera destruido tan fácilmente?",
  ui_story_1015_10151201_24_dialog_content = "Si realmente fue destruido, no se sabe cuántos problemas Coronel Yingel se encontraría en el tribunal militar.",
  ui_story_1015_10151201_25_dialog_content = "Muy bien, eso es suficiente.",
  ui_story_1015_10151201_26_dialog_content = "¡Eliminemos estos eclipses y detengamos a Forsakin!",
  ui_story_1015_10151201_27_dialog_content = "¡Me quitaste las palabras de la boca!",
  ui_story_1015_10151202_1_dialog_content = "<color=#e8d9bb>Entrañas X, hace muchos años</color>",
  ui_story_1015_10151202_2_dialog_content = "Mi experimento... ¡Mi experimento!",
  ui_story_1015_10151202_3_dialog_content = "¡Todos mis datos y materiales de prueba todavía están adentro! ¡Tenemos que sacarlos de ahí!",
  ui_story_1015_10151202_4_dialog_content = "<anim type=Shake><size=45>¡Chirrido! ¡Chirriar, chirriar!</size></anim>",
  ui_story_1015_10151202_5_dialog_content = "Jade, métete dentro de mi abrigo, ¡tenemos que volver!",
  ui_story_1015_10151202_6_dialog_content = "<anim type=Shake><size=45>¡Chirrido!</size></anim>",
  ui_story_1015_10151202_7_dialog_content = "Necesitamos recuperar los datos experimentales, rápidamente...",
  ui_story_1015_10151202_8_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1015_10151202_9_dialog_content = "¡¡¡Ah!!!",
  ui_story_1015_10151202_10_dialog_content = "¡Maldita sea! No esperaba que pudiera provocar un incendio tan grande...",
  ui_story_1015_10151202_11_dialog_content = "Si solo tenemos que confiar en las instalaciones de extinción de incendios existentes en Entrañas, es posible que no podamos extinguir un incendio tan grande.",
  ui_story_1015_10151202_12_dialog_content = "¿Será que ya no tengo más remedio que pedirle ayuda a ya-sabes-a-quién...?",
  ui_story_1015_10151202_13_dialog_content = "<color=#e8d9bb>Buzz Buzz-</color>",
  ui_story_1015_10151202_14_dialog_content = "Ese gran incendio casi destruyó todos mis logros de investigación.",
  ui_story_1015_10151202_15_dialog_content = "¡No dejaré que vuelva a suceder!",
  ui_story_1015_10151202_16_dialog_content = "Esto es-!",
  ui_story_1015_10151202_17_dialog_content = "(No hay ni una sola chispa en el laboratorio Chord Link...)",
  ui_story_1015_10151202_18_dialog_content = "(¿Esos viejos fósiles instalaron estos rociadores después de que me fui?)",
  ui_story_1015_10151202_19_dialog_content = "Parece que el fuego no solo se quedó conmigo sino también con ellos.",
  ui_story_1015_10151202_20_dialog_content = "Pero...",
  ui_story_1015_10151202_21_dialog_content = "<color=#e8d9bb>Tzzst—</color>",
  ui_story_1015_10151202_22_dialog_content = "Ríndete, Renegado.",
  ui_story_1015_10151202_23_dialog_content = "Los rehenes están todos a salvo. Sus fichas de negociación han desaparecido en el aire.",
  ui_story_1015_10151202_24_dialog_content = "Usar ese pequeño truco para forzarme a irme... ¿Era ese tu plan?",
  ui_story_1015_10151202_25_dialog_content = "Así es, pero no era sólo un truco.",
  ui_story_1015_10151202_26_dialog_content = "Sabía que no te dejarías engañar por meros accesorios, así que los barriles de explosivos alrededor del laboratorio son todos reales.",
  ui_story_1015_10151202_27_dialog_content = "Solo que no sabías que desde el incendio de entonces, el Gran Mariscal ordenó una actualización completa del equipo de extinción de incendios de Entrañas.",
  ui_story_1015_10151202_28_dialog_content = "Ahora hay más del doble de extintores y rociadores, e incluso las paredes han sido reforzadas con materiales a prueba de explosiones e ignífugos.",
  ui_story_1015_10151202_29_dialog_content = "Entonces, era ella.",
  ui_story_1015_10151202_30_dialog_content = "Hizo muchas cosas, pero desafortunadamente, todas fueron simplemente obstáculos inútiles.",
  ui_story_1015_10151202_31_dialog_content = "...",
  ui_story_1015_10151202_32_dialog_content = "¿El gato te comió la lengua?",
  ui_story_1015_10151202_33_dialog_content = "Todavía no puedes superar el incendio de hace tantos años, ¿verdad?",
  ui_story_1015_10151202_34_dialog_content = "¿Pero no quieres saber qué sucedió realmente en ese entonces?",
  ui_story_1015_10151202_35_dialog_content = "Escúpelo.",
  ui_story_1015_10151202_36_dialog_content = "Después de que enviaste una señal de socorro en ese entonces, Gran Mariscal Reinhardt inmediatamente lanzó una operación de rescate en Entrañas X.",
  ui_story_1015_10151202_37_dialog_content = "Solo porque el fuego era demasiado feroz, Entrañas ya estaba llena de humo espeso cuando llegó el equipo de rescate.",
  ui_story_1015_10151202_38_dialog_content = "Aun así, el Gran Mariscal seguía siendo el primero en precipitarse hacia el fuego. Te buscó en el infierno ardiente durante varias horas.",
  ui_story_1015_10151202_39_dialog_content = "Escuché de los rescatistas cuando el Gran Mariscal finalmente emergió, su cuerpo estaba cubierto de marcas de quemaduras carbonizadas y su ropa quemada hasta convertirse en harapos.",
  ui_story_1015_10151202_40_dialog_content = "Pero no le importaba el dolor que sentía, todo lo que sentía era arrepentimiento, arrepentimiento por no poder encontrar a su amada hermana.",
  ui_story_1015_10151202_41_dialog_content = "...",
  ui_story_1015_10151202_42_dialog_content = "Entonces, ahora ya sabes.",
  ui_story_1015_10151202_43_dialog_content = "En ese entonces, el Gran Mariscal se negó a rendirse contigo. Nadie se dio por vencido contigo.",
  ui_story_1015_10151202_44_dialog_content = "Fuiste tú quien obstinadamente pensó que había sido abandonado, le dio la espalda a Illumina y desertó a ese grupo de malvados Eclipsites.",
  ui_story_1015_10151202_45_dialog_content = "Todo lo que has hecho a lo largo de los años, ¿no fue solo una represalia contra aquellos que creías que se habían dado por vencidos contigo?",
  ui_story_1015_10151202_46_dialog_content = "Ahora sabes que si no te hubieras ido por tu propia voluntad, nadie hubiera querido renunciar a ti.",
  ui_story_1015_10151202_47_dialog_content = "¡Tu venganza se basó en una proposición falsa desde el principio!",
  ui_story_1015_10151202_48_dialog_content = "Deja de resistir. No tienes motivos para ser hostil hacia Illumina y no hay salida.",
  ui_story_1015_10151202_49_dialog_content = "Je.",
  ui_story_1015_10151202_50_dialog_content = "Después de todos estos años, esos viejos fósiles de alguna manera se las han arreglado para conservar su mal gusto único.",
  ui_story_1015_10151202_51_dialog_content = "Todavía tienen una predilección por los perros completamente tontos.",
  ui_story_1015_10151202_52_dialog_content = "...",
  ui_story_1015_10151202_53_dialog_content = "¿Crees que la razón por la que elegí dejar Illumina fue por algo tan trivial como sentirme traicionado?",
  ui_story_1015_10151202_54_dialog_content = "Estás completamente equivocado.",
  ui_story_1015_10151202_55_dialog_content = "Entonces, ¿por qué traicionaste a Illumina?",
  ui_story_1015_10151202_56_dialog_content = "La razón de mi partida es simple.",
  ui_story_1015_10151202_57_dialog_content = "El entorno proporcionado por la Federación Illumina ya no era suficiente para llevar a cabo mi investigación científica avanzada.",
  ui_story_1015_10151202_58_dialog_content = "Ni los sujetos de prueba disponibles ni los materiales de investigación provistos pudieron ayudarme a hacer nuevos avances.",
  ui_story_1015_10151202_59_dialog_content = "Así que decidí irme debido a la posibilidad de nuevos avances que ofrecía la tecnología que Eclipse había dominado.",
  ui_story_1015_10151202_60_dialog_content = "Eso es todo.",
  ui_story_1015_10151202_61_dialog_content = "<color=#e8d9bb>Mientras tanto, en algún lugar de Entrañas...</color>",
  ui_story_1015_10151202_62_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1015_10151202_63_dialog_content = "Justo a tiempo.",
  ui_story_1015_10151202_64_dialog_content = "Sus planes son siempre tan precisos como impecables.",
  ui_story_1015_10151202_65_dialog_content = "<color=#e8d9bb>Zumbido...</color>",
  ui_story_1015_10151202_66_dialog_content = "es hora de la <color=#FFB400>barrendero</color> para hacer acto de presencia.",
  ui_story_1015_10151301_1_dialog_content = "<color=#e8d9bb>Bwee-Bwee-</color>",
  ui_story_1015_10151301_2_dialog_content = "No puedo soportar todo este ruido.",
  ui_story_1015_10151301_3_dialog_content = "¿Qué?",
  ui_story_1015_10151301_4_dialog_content = "Pensé que podrías ser algo más fuerte que esos ratones.",
  ui_story_1015_10151301_5_dialog_content = "Ahora me parece claro que no eres mejor que ellos.",
  ui_story_1015_10151301_6_dialog_content = "Corta la energía.",
  ui_story_1015_10151301_7_dialog_content = "¡No! ¡Cuidado con el interruptor de encendido!",
  ui_story_1015_10151301_8_dialog_content = "<anim type=Shake><size=45>Gaaah!</size></anim>",
  ui_story_1015_10151301_9_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1015_10151301_10_dialog_content = "Maldición... La puerta principal de Entrañas está conectada al sistema de energía.",
  ui_story_1015_10151301_11_dialog_content = "Una vez que se va la energía, la puerta se bloqueará.",
  ui_story_1015_10151301_12_dialog_content = "¿La salida está detrás de esa puerta?",
  ui_story_1015_10151301_13_dialog_content = "No, hay algo... más problemático que una salida detrás.",
  ui_story_1015_10151301_14_dialog_content = "¿Qué es exactamente?",
  ui_story_1015_10151301_15_dialog_content = "<color=#e8d9bb>Crepitar-</color>",
  ui_story_1015_10151301_16_dialog_content = "Déjame decirte la respuesta.",
  ui_story_1015_10151301_17_dialog_content = "Un Chord Link está detrás de esa puerta.",
  ui_story_1015_10151301_19_dialog_content = "Sea lo que sea que estés tratando de hacer, ¡detente ahora mismo!",
  ui_story_1015_10151301_20_dialog_content = "Ese dispositivo está incompleto... ¡Nadie sabe cuáles podrían ser las consecuencias de usarlo imprudentemente!",
  ui_story_1015_10151301_21_dialog_content = "Debo admitir que estás muy bien informado.",
  ui_story_1015_10151301_22_dialog_content = "Pero no olvides, ratoncito...",
  ui_story_1015_10151301_23_dialog_content = "No eres un investigador, y tu comprensión de esta máquina proviene de ese anciano.",
  ui_story_1015_10151301_24_dialog_content = "La razón por la que crees que esta máquina representa una amenaza es simplemente que—",
  ui_story_1015_10151301_25_dialog_content = "No tienes idea de cómo usarlo.",
  ui_story_1015_10151301_26_dialog_content = "<color=#e8d9bb>Crujido-</color>",
  ui_story_1015_10151301_27_dialog_content = "Los factores de interferencia de este experimento han sido eliminados. Continuemos.",
  ui_story_1015_10151301_28_dialog_content = "Ven aquí, sujeto de prueba.",
  ui_story_1015_10151301_29_dialog_content = "...",
  ui_story_1015_10151301_30_dialog_content = "<color=#e8d9bb>Mientras tanto en la ciudad de Gannon...</color>",
  ui_story_1015_10151301_31_dialog_content = "<color=#e8d9bb>Tzzst—</color>",
  ui_story_1015_10151301_32_dialog_content = "Capitán Wrath, una misión urgente requiere tu atención. ¡Por favor, responda si copia!",
  ui_story_1015_10151301_33_dialog_content = "¿Una misión urgente? ¿Qué tipo de misión urgente podría estar llegando en este momento?",
  ui_story_1015_10151301_34_dialog_content = "Que curioso... Escuchemos y averigüemos.",
  ui_story_1015_10151301_35_dialog_content = "Recibido, adelante.",
  ui_story_1015_10151301_36_dialog_content = "Se sospecha que Entrañas X ha sido invadida por Forsakin. El Comité te ha ordenado que brindes apoyo y captures a Forsakin y Helios de inmediato.",
  ui_story_1015_10151301_37_dialog_content = "<size=45>¡¿Qué?!</size>",
  ui_story_1015_10151301_38_dialog_content = "¿Abandonado? ¿Ella realmente corrió de regreso al territorio de Illumina...?",
  ui_story_1015_10151301_39_dialog_content = "...",
  ui_story_1015_10151301_40_dialog_content = "Si ese es el caso, Wrath, Iré contigo.",
  ui_story_1015_10151301_41_dialog_content = "Sabía que no podías dejarlo ir.",
  ui_story_1015_10151301_42_dialog_content = "Pero tienes que prometerme que no harás ninguna tontería.",
  ui_story_1015_10151301_43_dialog_content = "Por supuesto, te lo prometo. Esta es tu misión: no me involucraré más de lo necesario.",
  ui_story_1015_10151301_44_dialog_content = "Bien, entonces... Vamos.",
  ui_story_1015_10151302_1_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc!</color>",
  ui_story_1015_10151302_2_dialog_content = "Pasa adelante...",
  ui_story_1015_10151302_3_dialog_content = "Jadeo... Jadeo... ¡Reportando!",
  ui_story_1015_10151302_4_dialog_content = "Señor, Wrath está en camino, según nuestro plan, y se espera que llegue dentro de una hora.",
  ui_story_1015_10151302_5_dialog_content = "Pero ha habido un ligero cambio en el plan—Reinhardt también ha venido.",
  ui_story_1015_10151302_6_dialog_content = "¿Oh?",
  ui_story_1015_10151302_7_dialog_content = "Está bien. Esperaba tanto.",
  ui_story_1015_10151302_8_dialog_content = "¿Era esto también parte de su plan?",
  ui_story_1015_10151302_9_dialog_content = "Je, esto no era parte de mi plan.",
  ui_story_1015_10151302_10_dialog_content = "Pero el humo negro sale del laboratorio Chord Link...",
  ui_story_1015_10151302_11_dialog_content = "No te preocupes por esos incendios. Vi a través de los monitores de vigilancia que no se quemarán por mucho tiempo.",
  ui_story_1015_10151302_12_dialog_content = "Siéntate y toma algo de beber. De ahora en adelante, todo lo que tenemos que hacer es sentarnos y ver el programa.",
  ui_story_1015_10151302_13_dialog_content = "¡Sí señor!",
  ui_story_1015_10151302_14_dialog_content = "Con razón no pude ganar ese juego de Joker contra ella.",
  ui_story_1015_10151302_15_dialog_content = "Resulta que ella ya había visto en los corazones de la gente.",
  ui_story_1015_10151302_16_dialog_content = "Denier, no, Forsakin, realmente merece nuestra envidia.",
  ui_story_1015_10151302_17_dialog_content = "¿...?",
  ui_story_1015_10151302_18_dialog_content = "¿No la envidias?",
  ui_story_1015_10151302_19_dialog_content = "Señor, yo...",
  ui_story_1015_10151302_20_dialog_content = "En efecto. No eres un investigador. Es perfectamente normal que no la envidies.",
  ui_story_1015_10151302_21_dialog_content = "...",
  ui_story_1015_10151302_22_dialog_content = "¿Te estás preguntando qué es lo que envidio de ella?",
  ui_story_1015_10151302_23_dialog_content = "¡Sí señor!",
  ui_story_1015_10151302_24_dialog_content = "Ella posee un rasgo único que la convierte en la investigadora perfecta.",
  ui_story_1015_10151302_25_dialog_content = "¿Persistencia?",
  ui_story_1015_10151302_26_dialog_content = "Crueldad.",
  ui_story_1015_10151302_27_dialog_content = "Hay un viejo dicho de Illumina:",
  ui_story_1015_10151302_28_dialog_content = "\"No existe el bien o el mal inherente en la ciencia y la tecnología, sino solo en los corazones de los aurorianos que las manejan\".",
  ui_story_1015_10151302_29_dialog_content = "Sin embargo, a menudo llega un momento en que uno primero debe convertirse en un villano para impulsar la civilización.",
  ui_story_1015_10151302_30_dialog_content = "No siempre puedes tener tu pastel y comértelo, y Forsakin lo sabe muy bien. Y esa señora también lo sabe bien...",
  ui_story_1015_10151302_31_dialog_content = "Para obtener los resultados de investigación que buscaba, pudo tratar a sus antiguos camaradas como sujetos de prueba sin dudarlo.",
  ui_story_1015_10151302_32_dialog_content = "Esta es la prueba más decisiva de su crueldad.",
  ui_story_1015_10151302_33_dialog_content = "¿Pero no es cierto que no tenía otra opción?",
  ui_story_1015_10151302_34_dialog_content = "No, no, no, no la obligamos.",
  ui_story_1015_10151302_35_dialog_content = "Todo lo que hicimos fue crear una oportunidad ligeramente restrictiva pero increíblemente atractiva para ella.",
  ui_story_1015_10151302_36_dialog_content = "Aprovechar esta oportunidad fue enteramente su propia decisión.",
  ui_story_1015_10151302_37_dialog_content = "Su investigación nunca se ha desviado de la esencia de este experimento: usar métodos científicos para explorar los límites del potencial biológico.",
  ui_story_1015_10151302_38_dialog_content = "Este ha sido el caso desde el Proyecto Sol Artificial inicial.",
  ui_story_1015_10151302_39_dialog_content = "Estás familiarizado con el Proyecto Sol Artificial, ¿verdad? Fue el predecesor del Programa Phospherus.",
  ui_story_1015_10151302_40_dialog_content = "Su mayor logro fue la tecnología de mejora de Aurorian, desarrollada de forma independiente por Illumina. Sin embargo, los resultados fueron inestables debido a las limitaciones de nuestra tecnología no desarrollada.",
  ui_story_1015_10151302_41_dialog_content = "Una sola fuerza poderosa se mueve libremente dentro de los aurorianos, y solo puede ser domesticada por una fuerte voluntad.",
  ui_story_1015_10151302_42_dialog_content = "El resultado de hacerlo es que la tasa de éxito es extremadamente baja y el sujeto también es propenso a perder el control de su poder.",
  ui_story_1015_10151302_43_dialog_content = "A su vez, el resultado de perder el control es la muerte, la discapacidad permanente o... convertirse en uno de esos monstruos.",
  ui_story_1015_10151302_44_dialog_content = "Sin embargo, el ex Denier, también conocido como Forsakin, no sucumbió a ninguno de estos destinos.",
  ui_story_1015_10151302_45_dialog_content = "¿Ha sido considerada un fracaso?",
  ui_story_1015_10151302_46_dialog_content = "Estrictamente hablando, no.",
  ui_story_1015_10151302_47_dialog_content = "Ella fue un tema exitoso, pero la trayectoria de su éxito no coincidió con nuestras expectativas.",
  ui_story_1015_10151302_48_dialog_content = "Lo que queríamos era un sujeto con mayor fuerza, pero en su caso, su intelecto fue mejorado.",
  ui_story_1015_10151302_49_dialog_content = "Su éxito la convirtió en la investigadora más talentosa y la mayor amenaza oculta en Illumina.",
  ui_story_1015_10151302_50_dialog_content = "Ya has visto cómo termina esta historia. Sin duda, se ha convertido en una traidora, oponiéndose directamente a Illumina.",
  ui_story_1015_10151302_51_dialog_content = "Entonces, con respecto a todos los Illumina, Reinhardt fue el producto más exitoso del Proyecto Sol Artificial.",
  ui_story_1015_10151302_52_dialog_content = "Pero todavía hay una cosa que no entiendo.",
  ui_story_1015_10151302_53_dialog_content = "¿Cómo se determina si un Aurorian modificado por Project Artificial Sun tiene éxito?",
  ui_story_1015_10151302_54_dialog_content = "Después de todo, no todas las características del fracaso pueden manifestarse inmediatamente después de la mejora.",
  ui_story_1015_10151302_55_dialog_content = "¿Todavía recuerdas la batalla que ocurrió en Entrañas 80?",
  ui_story_1015_10151302_56_dialog_content = "Si, lo recuerdo.",
  ui_story_1015_10151302_57_dialog_content = "En ese momento, revisé la información transmitida al equipo individual, modificada por el Proyecto Sol Artificial, de acuerdo con los requisitos del Comité.",
  ui_story_1015_10151302_58_dialog_content = "Esa falsa inteligencia se usó para guiarlos hacia un cerco de Eclipsite.",
  ui_story_1015_10151302_59_dialog_content = "Todavía recuerdo que muchos equipos de reconocimiento se vieron comprometidos en ese momento para obtener suficiente inteligencia precisa.",
  ui_story_1015_10151302_60_dialog_content = "El equipo de mi subordinado era uno de ellos, y él fue el único de su equipo que sobrevivió.",
  ui_story_1015_10151302_61_dialog_content = "Oh, creo que recuerdo haber escuchado su historia. ¿Cual era su nombre?",
  ui_story_1015_10151302_62_dialog_content = "<color=#FFB400>Anatoli</color>.",
  ui_story_1015_10151302_63_dialog_content = "Ah, sí, ese era el nombre. Escuché que recientemente lo ascendiste para convertirse en adjunto de Reinhardt.",
  ui_story_1015_10151302_64_dialog_content = "¿Él sabe de este asunto? Más importante aún, ¿es lo suficientemente confiable como para monitorear las acciones de Reinhardt?",
  ui_story_1015_10151302_65_dialog_content = "Creo que es digno de confianza en su capacidad para recopilar información.",
  ui_story_1015_10151302_66_dialog_content = "Además, esta tarea en sí misma es una prueba de su lealtad.",
  ui_story_1015_10151302_67_dialog_content = "Si crees que eso es cierto, adelante, hazlo de esa manera.",
  ui_story_1015_10151302_68_dialog_content = "Nos hemos desviado del tema. Hablemos de Entrañas 80.",
  ui_story_1015_10151302_69_dialog_content = "Esa batalla fue una proyección de los sujetos modificados.",
  ui_story_1015_10151302_70_dialog_content = "Dirigiéndolos intencionalmente a una lucha desesperada, permitiéndoles llevar su Lumina al límite, y luego...",
  ui_story_1015_10151302_71_dialog_content = "Los individuos más débiles fueron eliminados directamente.",
  ui_story_1015_10151302_72_dialog_content = "Las personas con defectos e inestabilidades mentales también podrían perder el control y, en última instancia, ser eliminadas en situaciones tan extremas.",
  ui_story_1015_10151302_73_dialog_content = "Pero los sujetos exitosos resistieron esta amarga batalla y sobrevivieron.",
  ui_story_1015_10151302_74_dialog_content = "Pero... ¿no fue precisamente porque la tasa de éxito fue extremadamente baja que el proyecto finalmente se canceló?",
  ui_story_1015_10151302_75_dialog_content = "Hasta que Illumina obtuvo ese Chord Link incompleto.",
  ui_story_1015_10151302_76_dialog_content = "Así es, el Proyecto Sol Artificial no se habría reiniciado.",
  ui_story_1015_10151302_77_dialog_content = "Pero ese Chord Link marcó un punto de inflexión.",
  ui_story_1015_10151302_78_dialog_content = "El Chord Link fue el pináculo de la tecnología Caelestite, representando una nueva fuente de energía diferente del Proyecto Sol Artificial.",
  ui_story_1015_10151302_79_dialog_content = "Al integrar estas dos tecnologías, nacieron los sujetos de prueba del Programa Phospherus.",
  ui_story_1015_10151302_80_dialog_content = "Los Aurorianos modificados por el Programa Phospherus poseen el poder derivado de estas dos tecnologías diferentes dentro de sus cuerpos.",
  ui_story_1015_10151302_81_dialog_content = "Estas dos fuerzas se equilibran entre sí y, hasta cierto punto, aumentan la tasa de éxito de la mejora.",
  ui_story_1015_10151302_82_dialog_content = "Sin embargo, el equilibrio no es lo suficientemente estable, por lo que la mayoría de los Aurorianos modificados por el Programa Phospherus son muy frágiles.",
  ui_story_1015_10151302_83_dialog_content = "Una vez que se abusa de su tremendo poder, el delicado equilibrio entre las dos fuerzas se puede romper fácilmente.",
  ui_story_1015_10151302_84_dialog_content = "Y sus cuerpos también colapsarán con él.",
  ui_story_1015_10151302_85_dialog_content = "Axelia es un muy buen ejemplo de esto.",
  ui_story_1015_10151302_86_dialog_content = "Pero esta vez es diferente. Forsakin generó un nuevo poder, y su investigación podría llevar el experimento a nuevas alturas.",
  ui_story_1015_10151302_87_dialog_content = "¿Quieres decir... la <color=#FFB400>semilla</color>?",
  ui_story_1015_10151302_88_dialog_content = "Correcto.",
  ui_story_1015_10151302_89_dialog_content = "Forsakin ha estudiado la semilla durante tantos años y ya se ha convertido en el mayor logro de la tecnología Eclipsite.",
  ui_story_1015_10151302_90_dialog_content = "La semilla se convertirá en la última pieza del rompecabezas, y Forsakin es el único capaz de colocarla.",
  ui_story_1015_10151302_91_dialog_content = "En última instancia, estas tres fuerzas formarán un todo equilibrado dentro del cuerpo auroriano, convirtiéndose en una fuerza nueva y estable.",
  ui_story_1015_10151302_92_dialog_content = "¡...!",
  ui_story_1015_10151302_93_dialog_content = "En cuanto a los resultados cruciales de la primera prueba, solo podemos esperar y ver.",
  ui_story_1015_10151302_94_dialog_content = "<color=#e8d9bb>Mientras tanto, en el laboratorio de enlaces de cuerdas de la Federación Illumina.</color>",
  ui_story_1015_10151302_95_dialog_content = "<color=#e8d9bb>¡Bang, bang!</color>",
  ui_story_1015_10151302_96_dialog_content = "Tan ruidoso.",
  ui_story_1015_10151302_97_dialog_content = "Aunque este entorno es apenas adecuado para este experimento, será suficiente.",
  ui_story_1015_10151302_98_dialog_content = "Comenzando las verificaciones finales de parámetros.",
  ui_story_1015_10151302_99_dialog_content = "Todos los parámetros verificados para ser exactos.",
  ui_story_1015_10151302_100_dialog_content = "Es hora de agregar los materiales experimentales finales.",
  ui_story_1015_10151302_101_dialog_content = "Comencemos el experimento.",
  ui_story_1015_10151302_102_dialog_content = "La semilla guiará la dirección de la evolución.",
  ui_story_1015_10151302_103_dialog_content = "<color=#e8d9bb>Fuera del laboratorio Chord Link</color>",
  ui_story_1015_10151302_104_dialog_content = "¡Dispersión, pétalos de hielo!",
  ui_story_1015_10151302_105_dialog_content = "<color=#e8d9bb>Ruido sordo-!!!</color>",
  ui_story_1015_10151302_106_dialog_content = "Incluso después de soportar una explosión y tantos golpes, parece que no podemos hacer una sola abolladura en esta puerta.",
  ui_story_1015_10151302_107_dialog_content = "Parece que la entrada forzada ya no es una opción factible.",
  ui_story_1015_10151302_108_dialog_content = "Después de todo, durante la construcción de esta instalación se utilizaron los materiales a prueba de explosiones más fuertes que existen.",
  ui_story_1015_10151302_109_dialog_content = "Las características originalmente destinadas a prevenir posibles incendios ahora se han convertido en obstáculos.",
  ui_story_1015_10151302_110_dialog_content = "El Chord Link detrás de esta puerta es probablemente una parte esencial del experimento de Forsakin.",
  ui_story_1015_10151302_111_dialog_content = "Si se le permite usarlo imprudentemente, causará aún más problemas en el futuro.",
  ui_story_1015_10151302_112_dialog_content = "¡Sí, tenemos que detenerla de inmediato!",
  ui_story_1015_10151302_113_dialog_content = "¿No hay nada que podamos hacer?",
  ui_story_1015_10151302_114_dialog_content = "Déjame pensar.",
  ui_story_1015_10151302_115_dialog_content = "Tal vez hay una manera.",
  ui_story_1015_10151302_116_dialog_content = "¿Qué es?",
  ui_story_1015_10151302_117_dialog_content = "Esta Entrañas solía ser el laboratorio secreto de Forsakin. Por lo tanto, una gran cantidad de sujetos de prueba fallidos fueron descartados aquí todos los días.",
  ui_story_1015_10151302_118_dialog_content = "Para ahorrar tiempo, construyó una tubería desde el laboratorio hasta la sala de tratamiento de desechos en el sótano.",
  ui_story_1015_10151302_119_dialog_content = "Durante la reconstrucción de Entrañas, esta tubería se selló dentro de las paredes pero no se desmontó.",
  ui_story_1015_10151302_120_dialog_content = "Aunque pueda parecer un desvío colosal, abrir la pared y sellar la tubería será mucho más fácil que derribar esta puerta.",
  ui_story_1015_10151302_121_dialog_content = "Podemos usar este atajo que usó como vertedero de basura para saltar sobre ella.",
  ui_story_1015_10151401_1_dialog_content = "¡Esta es la parte más débil de la pared!",
  ui_story_1015_10151401_2_dialog_content = "<color=#e8d9bb>¡Bang! ¡Bang!</color>",
  ui_story_1015_10151401_3_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_1015_10151401_4_dialog_content = "¡El conducto está abierto!",
  ui_story_1015_10151401_5_dialog_content = "¡Detente ahí mismo, Renegado!",
  ui_story_1015_10151401_6_dialog_content = "¡Ya hemos derrotado a todos los Eclipsites bajo tu mando!",
  ui_story_1015_10151401_7_dialog_content = "Llegas muy tarde.",
  ui_story_1015_10151401_8_dialog_content = "Mi experimento ya ha dado resultados.",
  ui_story_1015_10151401_9_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_1015_10151401_10_dialog_content = "PlayerName, ¡mirar! ¡El enlace de acordes!",
  ui_story_1015_10151401_11_dialog_content = "¡Algo parece estar emergiendo de su interior!",
  ui_story_1015_10151401_12_dialog_content = "¡¿Qué... qué es esto?!",
  ui_story_1015_10151401_13_dialog_content = "¡¿Qué clase de monstruo es este?!",
  ui_story_1015_10151401_14_dialog_content = "Registro de laboratorio del experimento 112 en el sujeto de prueba Helios—",
  ui_story_1015_10151401_15_dialog_content = "Proceso de experimentación: mientras usa Chord Link para mejorar el tema del Proyecto Sol Artificial—",
  ui_story_1015_10151401_16_dialog_content = "Se agregó una semilla al Chord Link.",
  ui_story_1015_10151401_17_dialog_content = "Resultados del experimento: el experimento fue inicialmente exitoso y el riesgo de que el sujeto dejara de hacer actividad se redujo significativamente.",
  ui_story_1015_10151401_18_dialog_content = "¿Está grabando su experimento?",
  ui_story_1015_10151401_19_dialog_content = "Ella personalmente transformó a su antiguo compañero en este monstruo, y todavía tiene la insensible presencia de ánimo para completar un registro del experimento...",
  ui_story_1015_10151401_20_dialog_content = "El oficial Ulysses tenía razón: eres un animal de sangre fría hasta la médula.",
  ui_story_1015_10151401_21_dialog_content = "Ulises?",
  ui_story_1015_10151401_22_dialog_content = "Ese anciano probablemente espera los resultados de este experimento más que yo.",
  ui_story_1015_10151401_23_dialog_content = "¿Qué dijiste?",
  ui_story_1015_10151401_24_dialog_content = "Es hora de continuar con el siguiente experimento.",
  ui_story_1015_10151401_25_dialog_content = "Verificando la estabilidad del sujeto a través del combate real.",
  ui_story_1015_10151401_26_dialog_content = "Adelante, sujeto de prueba, destrúyelos.",
  ui_story_1015_10151401_27_dialog_content = "!",
  ui_story_1015_10151401_28_dialog_content = "PlayerName¡Encuentra un lugar donde esconderte!",
  ui_story_1015_10151401_29_dialog_content = "¡E-está bien!",
  ui_story_1015_10151401_30_dialog_content = "...",
  ui_story_1015_10151401_31_dialog_content = "(¿Ese monstruo no respondió? ¿Eso significa que el experimento de Forsakin falló?)",
  ui_story_1015_10151401_32_dialog_content = "Ya veo, parece que mi experimento ha logrado aún más éxito.",
  ui_story_1015_10151401_33_dialog_content = "(¿Más éxito? ¿Qué quiere decir ella?)",
  ui_story_1015_10151401_34_dialog_content = "De hecho, parece que es necesario un enfoque diferente.",
  ui_story_1015_10151401_35_dialog_content = "Helios, soldado de la Illumina—",
  ui_story_1015_10151401_36_dialog_content = "¡...!",
  ui_story_1015_10151401_37_dialog_content = "¡Él reaccionó! ¡¿Podría ser que él realmente entiende?!",
  ui_story_1015_10151401_38_dialog_content = "De pie ante ustedes ahora están los traidores y enemigos de la Federación Illumina.",
  ui_story_1015_10151401_39_dialog_content = "Tu misión es eliminarlos.",
  ui_story_1015_10151401_40_dialog_content = "<anim type=Shake><size=50>¡Gahhhhhhhh!</size></anim>",
  ui_story_1015_10151401_41_dialog_content = "¡Esperar! ¡Detener!",
  ui_story_1015_10151401_42_dialog_content = "¡No somos tus enemigos! ¡Forsakin es un traidor y enemigo de Illumina!",
  ui_story_1015_10151401_43_dialog_content = "<anim type=Shake><size=50>Graagh!!!</size></anim>",
  ui_story_1015_10151401_44_dialog_content = "¡Urgh!",
  ui_story_1015_10151401_45_dialog_content = "Es inútil... No parece haber recuperado completamente la cordura todavía.",
  ui_story_1015_10151401_46_dialog_content = "Vamos a desmontarlo primero.",
  ui_story_1015_10151402_1_dialog_content = "<anim type=Shake><size=50>¡Gahhhhhhhh!</size></anim>",
  ui_story_1015_10151402_2_dialog_content = "¿Cómo se volvió tan fuerte...?",
  ui_story_1015_10151402_3_dialog_content = "No solo es más fuerte, sus acciones también se han vuelto más impredecibles.",
  ui_story_1015_10151402_4_dialog_content = "Todos, ¡cuidado!",
  ui_story_1015_10151402_5_dialog_content = "Si antes solo estaba contraatacando instintivamente, parece que ahora comenzó a usar tácticas.",
  ui_story_1015_10151402_6_dialog_content = "¿Este monstruo ha aprendido a hacer estrategia?",
  ui_story_1015_10151402_7_dialog_content = "La situación ha tomado un giro problemático...",
  ui_story_1015_10151402_8_dialog_content = "De hecho, el experimento logró un mayor éxito. Mi teoría era correcta.",
  ui_story_1015_10151402_9_dialog_content = "Las tres fuerzas diferentes que interactúan dentro del sujeto de prueba han formado un estado estable.",
  ui_story_1015_10151402_10_dialog_content = "Incluso durante el combate de alta intensidad, el equilibrio permanece intacto.",
  ui_story_1015_10151402_11_dialog_content = "Y el punto más importante es que este experimento se puede replicar.",
  ui_story_1015_10151402_12_dialog_content = "Ahora, todo lo que necesito hacer es verificar los resultados finales para demostrar que el experimento fue completamente exitoso.",
  ui_story_1015_10151402_13_dialog_content = "<anim type=Shake>Rugido...</anim>",
  ui_story_1015_10151402_14_dialog_content = "¡Cuidado, le pasa algo!",
  ui_story_1015_10151402_15_dialog_content = "¿Eso es Lumina o Darkflow? Cuando se mezclan así, ¡ni siquiera puedo distinguirlos!",
  ui_story_1015_10151402_16_dialog_content = "No te preocupes por eso ahora, ¡prepárate para defender!",
  ui_story_1015_10151402_17_dialog_content = "<anim type=Shake><size=50>¡Gahhhh!</size></anim>",
  ui_story_1015_10151402_18_dialog_content = "¡¿Qué es esto?!",
  ui_story_1015_10151402_19_dialog_content = "¡¿Acaba de cambiar su apariencia?!",
  ui_story_1015_10151402_20_dialog_content = "Vi esto una vez antes, en los fragmentos de recuerdos que percibí en Entrañas 80...",
  ui_story_1015_10151402_21_dialog_content = "¡Así es como se veía originalmente!",
  ui_story_1015_10151402_22_dialog_content = "Finalmente se ha llegado a este paso.",
  ui_story_1015_10151402_23_dialog_content = "Los resultados finales del experimento también han sido verificados.",
  ui_story_1015_10151402_24_dialog_content = "Un estado estable trae mayores beneficios, ya que hace que este poder sea controlable.",
  ui_story_1015_10151402_25_dialog_content = "Puede frenar los efectos secundarios del Proyecto Sol Artificial, que hizo que los aurorianos perdieran la cordura y se convirtieran en monstruos.",
  ui_story_1015_10151402_26_dialog_content = "Al mismo tiempo, también puede permitir que el Aurorian cambie su forma de forma autónoma.",
  ui_story_1015_10151402_27_dialog_content = "Esto es exactamente lo que esperaba lograr.",
  ui_story_1015_10151402_28_dialog_content = "<anim type=Shake>Urgh...</anim>",
  ui_story_1015_10151402_29_dialog_content = "<anim type=Shake>Dónde estoy...?</anim>",
  ui_story_1015_10151402_30_dialog_content = "¡¿Él puede hablar?!",
  ui_story_1015_10151402_31_dialog_content = "No... no... ¿Por qué... no estoy en Entrañas 80?",
  ui_story_1015_10151402_32_dialog_content = "¿Quién eres?",
  ui_story_1015_10151402_33_dialog_content = "De hecho, ha sido restaurado a su forma auroriana... ¿Su cordura también ha sido restaurada?",
  ui_story_1015_10151402_34_dialog_content = "Soy Yingel, un oficial de inteligencia que trabaja directamente bajo la autoridad del Comité.",
  ui_story_1015_10151402_35_dialog_content = "Capitán Helios, se sospecha que está en connivencia con el enemigo... de colaborar con Eclipsites.",
  ui_story_1015_10151402_36_dialog_content = "¡Baja tu arma inmediatamente, cesa tu resistencia y coopera con la investigación del Comité!",
  ui_story_1015_10151402_37_dialog_content = "No, no lo hice...",
  ui_story_1015_10151402_38_dialog_content = "¿Cómo... podría posiblemente coludirme con el enemigo?",
  ui_story_1015_10151402_39_dialog_content = "yo soy... yo...",
  ui_story_1015_10151402_40_dialog_content = "¡Cálmese, Capitán Helios!",
  ui_story_1015_10151402_41_dialog_content = "Mira a tu alrededor. Esto no es Entrañas 80.",
  ui_story_1015_10151402_42_dialog_content = "Ya no necesitas pelear...",
  ui_story_1015_10151402_43_dialog_content = "¿Qué pasó? ¿Por qué estoy aquí?",
  ui_story_1015_10151402_44_dialog_content = "¿Por qué... no puedo recordar...?",
  ui_story_1015_10151402_45_dialog_content = "¡Urgh...!",
  ui_story_1015_10151402_46_dialog_content = "La capacidad cognitiva del sujeto está intacta, pero su memoria parece desordenada e incompleta. No se formaron nuevos recuerdos después de perder el control.",
  ui_story_1015_10151402_47_dialog_content = "Registrado temporalmente como un efecto secundario que requiere atención. Se necesitan más estudios para eliminar por completo este efecto secundario.",
  ui_story_1015_10151402_48_dialog_content = "Por supuesto, existe una mayor posibilidad de que esta situación haya sido causada por defectos en el sujeto mismo.",
  ui_story_1015_10151402_49_dialog_content = "En general, el experimento fue exitoso.",
  ui_story_1015_10151402_50_dialog_content = "Finalmente he dominado el proceso de evolución.",
  ui_story_1015_10151402_51_dialog_content = "Solo queda una pregunta...",
  ui_story_1015_10151402_52_dialog_content = "(Este sujeto de prueba será necesario para la verificación posterior).",
  ui_story_1015_10151402_53_dialog_content = "(Necesito pensar en una manera de hacer que venga conmigo).",
  ui_story_1015_10151402_54_dialog_content = "(Sin embargo, está recuperando gradualmente la conciencia y la cognición, una variable que no es propicia para mi plan).",
  ui_story_1015_10151402_55_dialog_content = "(Sin embargo, hay formas de lidiar con este tipo de sujeto de prueba de mente simple).",
  ui_story_1015_10151402_56_dialog_content = "Tú... te reconozco...",
  ui_story_1015_10151402_57_dialog_content = "Eres... ¿Denier?",
  ui_story_1015_10151402_58_dialog_content = "¿Por qué... te ves así...?",
  ui_story_1015_10151402_59_dialog_content = "donde esta... Reinhardt...?",
  ui_story_1015_10151402_60_dialog_content = "¿Por qué ella... no está contigo...?",
  ui_story_1015_10151402_61_dialog_content = "...",
  ui_story_1015_10151402_62_dialog_content = "Tanto Denier como la persona que solías ser hace tiempo que Illumina los abandonó.",
  ui_story_1015_10151402_63_dialog_content = "No soy negador.",
  ui_story_1015_10151402_64_dialog_content = "¿Abandonado?",
  ui_story_1015_10151402_65_dialog_content = "<anim type=Shake>¡¡¡Urgh...!!!</anim>",
  ui_story_1015_10151402_66_dialog_content = "¡Está reuniendo Darkflow!",
  ui_story_1015_10151402_67_dialog_content = "¡¿Forsakin está tratando de agitarlo con sus palabras para sumergirlo nuevamente en el caos y convertirlo en un monstruo?!",
  ui_story_1015_10151402_68_dialog_content = "Todo el mundo está más o menos en sus últimas piernas como está...",
  ui_story_1015_10151402_69_dialog_content = "Escucha... Te están llamando monstruo.",
  ui_story_1015_10151402_70_dialog_content = "<anim type=Shake>No... no soy... no soy un monstruo...</anim>",
  ui_story_1015_10151402_71_dialog_content = "<anim type=Shake>Soy... un soldado... de Illumina...</anim>",
  ui_story_1015_10151402_72_dialog_content = "Tsk...",
  ui_story_1015_10151402_73_dialog_content = "La Federación Illumina ya no tiene un lugar para ti.",
  ui_story_1015_10151402_74_dialog_content = "Ven conmigo, y tendrás una oportunidad de sobrevivir.",
  ui_story_1015_10151402_75_dialog_content = "Quédate aquí y solo te esperará la muerte.",
  ui_story_1015_10151402_76_dialog_content = "¡No le creas! ¡Illumina nunca se rinde con nadie!",
  ui_story_1015_10151402_77_dialog_content = "La Federación Illumina abandona a aquellos que no pueden contribuir más a su causa, especialmente a aquellos que fallan.",
  ui_story_1015_10151402_78_dialog_content = "Gran Mariscal Reinhardt nunca ha dejado de buscarte.",
  ui_story_1015_10151402_79_dialog_content = "Reinhardt Nunca volvió con refuerzos.",
  ui_story_1015_10151402_80_dialog_content = "¡Ella no tenía nada que decir en el asunto! ¡Los oficiales de Illumina la drogaron para que no pudiera rescatarte!",
  ui_story_1015_10151402_81_dialog_content = "Lo vi todo con mi habilidad psíquica. ¡Sé que es absolutamente cierto!",
  ui_story_1015_10151402_82_dialog_content = "No olvides, en Entrañas 80, Reinhardt se enfrentó a nosotros, con las dagas desenvainadas.",
  ui_story_1015_10151402_83_dialog_content = "Abre los ojos y mira. Tu antiguo compañero ya no es auroriano.",
  ui_story_1015_10151402_84_dialog_content = "¡Ella es la que tiene sangre en sus manos!",
  ui_story_1015_10151402_85_dialog_content = "¿No odias a estos hipócritas?",
  ui_story_1015_10151402_86_dialog_content = "<size=45>¡Tranquilo, tú!</size>",
  ui_story_1015_10151402_87_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1015_10151402_88_dialog_content = "<anim type=Shake><size=50>¡¡¡Urgh!!!</size></anim>",
  ui_story_1015_10151402_89_dialog_content = "Por qué-!",
  ui_story_1015_10151402_90_dialog_content = "... ¿Qué estás haciendo?",
  ui_story_1015_10151402_91_dialog_content = "Soy... un soldado... de Illumina...",
  ui_story_1015_10151402_92_dialog_content = "Cooperaré... con la investigación...",
  ui_story_1015_10151402_93_dialog_content = "Pero también... deseo proteger a mi amigo...",
  ui_story_1015_10151402_94_dialog_content = "...",
  ui_story_1015_10151402_95_dialog_content = "Que tonto.",
  ui_story_1015_10151402_96_dialog_content = "Parece que la percepción que tiene el sujeto de sí mismo y de los demás es defectuosa.",
  ui_story_1015_10151402_97_dialog_content = "Esto puede ser algún tipo de trastorno mental. Esta cognición errónea debe ser completamente erradicada.",
  ui_story_1015_10151402_98_dialog_content = "Esto es-!",
  ui_story_1015_10151402_99_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1015_10151402_100_dialog_content = "¡¿Q-Qué fue eso?!",
  ui_story_1015_10151402_101_dialog_content = "Volver, PlayerName! ¡Un enorme agujero apareció en la puerta!",
  ui_story_1015_10151402_102_dialog_content = "¡Algo realmente poderoso está atravesando la puerta!",
  ui_story_1015_10151402_103_dialog_content = "¡Ay!",
  ui_story_1015_10151402_104_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_1015_10151402_105_dialog_content = "Esa es una descripción precisa, pero no es algo, solo soy yo.",
  ui_story_1015_10151402_106_dialog_content = "Entonces, en realidad estás aquí, Forsakin.",
  ui_story_1015_10151402_107_dialog_content = "Justo en el clavo.",
  ui_story_1015_10151402_108_dialog_content = "Nos encontremos de nuevo, Reinhardt. Incluso después de todo este tiempo, no has hecho ningún progreso.",
  ui_story_1015_10151402_109_dialog_content = "Todavía voluntariamente siendo utilizado.",
  ui_story_1015_10151402_110_dialog_content = "Mucho tiempo sin verte, Renegado.",
  ui_story_1015_10151402_111_dialog_content = "Parece que no te ha ido muy bien con los Eclipsites. Y ahora, incluso has caído en este nuevo mínimo.",
  ui_story_1015_10151402_112_dialog_content = "¿Mmm? ¿Cómo te llamas? ¿Qué...?",
  ui_story_1015_10151402_113_dialog_content = "No vale la pena recordar a un jugador secundario que confía en un antiguo compañero de clase para asegurar su posición.",
  ui_story_1015_10151402_114_dialog_content = "¿Se supone que eso es un insulto? Debes estar confundiéndome con alguien a quien le importa.",
  ui_story_1015_10151402_115_dialog_content = "Cuando te tire al suelo más tarde, no vayas llorando a buscar a tu hermana.",
  ui_story_1015_10151402_116_dialog_content = "Que inmaduro.",
  ui_story_1015_10151402_117_dialog_content = "Es eso... Reinhardt?",
  ui_story_1015_10151402_118_dialog_content = "Helios?! Tu apariencia...",
  ui_story_1015_10151402_119_dialog_content = "¿Estos son... los refuerzos? tu finalmente...",
  ui_story_1015_10151402_120_dialog_content = "...",
  ui_story_1015_10151402_121_dialog_content = "Sí, lo siento por llegar tan tarde.",
  ui_story_1015_10151402_122_dialog_content = "Vine a buscarte y traje refuerzos.",
  ui_story_1015_10151402_123_dialog_content = "¡Asegura este lugar!",
  ui_story_1015_10151402_124_dialog_content = "¡Sí, señora!",
  ui_story_1015_10151402_125_dialog_content = "Exactamente como lo predije.",
  ui_story_1015_10151402_126_dialog_content = "Reinhardt, vamos a hacer un trato.",
  ui_story_1015_10151402_127_dialog_content = "¿Qué...?",
  ui_story_1015_10151402_128_dialog_content = "Permitir que mi sujeto de prueba y yo dejemos Illumina no tendría ningún efecto adverso para usted.",
  ui_story_1015_10151402_129_dialog_content = "¿Eh? Quizás llevas demasiado tiempo en la Noche Eterna. Parece que el Darkflow llegó a tu cerebro.",
  ui_story_1015_10151402_130_dialog_content = "No estás en posición de negociar con nosotros ahora mismo.",
  ui_story_1015_10151402_131_dialog_content = "No estoy negociando contigo.",
  ui_story_1015_10151402_132_dialog_content = "Esos viejos fósiles no me quieren a mí, lo quieren a él.",
  ui_story_1015_10151402_133_dialog_content = "(¿Qué quiere decir? ¿El Comité quiere a Helios?)",
  ui_story_1015_10151402_134_dialog_content = "(Pero mi misión era simplemente capturar a Forsakin y rescatar al teniente Vice.)",
  ui_story_1015_10151402_135_dialog_content = "Sabes exactamente lo que sucederá si cae en manos de esas personas.",
  ui_story_1015_10151402_136_dialog_content = "No puedo estar de acuerdo con su solicitud.",
  ui_story_1015_10151402_137_dialog_content = "Habría elegido creerte si hubiera sido hace más de una década, antes de que te fueras de Illumina.",
  ui_story_1015_10151402_138_dialog_content = "Pero después de todos estos años de lucha, te conozco mejor que nadie.",
  ui_story_1015_10151402_139_dialog_content = "Lo que quieres hacer no es diferente de lo que ellos quieren.",
  ui_story_1015_10151402_140_dialog_content = "Entrégamelo y usaré mi estatus de Gran Mariscal para protegerlo. No dejaré que nadie le ponga un dedo encima.",
  ui_story_1015_10151402_141_dialog_content = "No tienes el poder.",
  ui_story_1015_10151402_142_dialog_content = "Estas negociaciones no van a ninguna parte. No necesito perder más tiempo aquí.",
  ui_story_1015_10151402_143_dialog_content = "Jade.",
  ui_story_1015_10151402_144_dialog_content = "<anim type=Shake><size=50>Graaaaah!</size></anim>",
  ui_story_1015_10151402_145_dialog_content = "Adiós.",
  ui_story_1015_10151402_146_dialog_content = "<color=#e8d9bb>Fwooosh!!!</color>",
  ui_story_1015_10151501_1_dialog_content = "Informando. De acuerdo con la inteligencia transmitida por el Coronel Yingel y mayor Anatoli, encontramos al teniente Vice en un laboratorio abandonado.",
  ui_story_1015_10151501_2_dialog_content = "Teniente Vice, volviendo al deber!",
  ui_story_1015_10151501_3_dialog_content = "Vice! ¿Estás bien? ¿Estabas herido?",
  ui_story_1015_10151501_4_dialog_content = "Estoy bien!",
  ui_story_1015_10151501_5_dialog_content = "Lo siento, fui tan descuidado y causé tantos problemas para todos...",
  ui_story_1015_10151501_6_dialog_content = "Mientras estés de vuelta, sano y salvo, entonces todo está bien.",
  ui_story_1015_10151501_7_dialog_content = "Así es. No seas demasiado duro contigo mismo.",
  ui_story_1015_10151501_8_dialog_content = "Forsakin es un enemigo astuto. Tomó todos nuestros esfuerzos concertados para tratar con ella.",
  ui_story_1015_10151501_9_dialog_content = "Cierto...",
  ui_story_1015_10151501_10_dialog_content = "¿Cómo va la búsqueda? ¿Has encontrado algún rastro de Forsakin?",
  ui_story_1015_10151501_11_dialog_content = "¡Reportando en! Hemos buscado en toda Entrañas y no hemos encontrado rastro de Forsakin.",
  ui_story_1015_10151501_12_dialog_content = "¿Qué pasa con las diversas entradas y salidas, y el pasaje de la antigua Entrañas?",
  ui_story_1015_10151501_13_dialog_content = "Todas las entradas y salidas estaban vigiladas y no se veía a nadie entrando o saliendo.",
  ui_story_1015_10151501_14_dialog_content = "Veo. Sin embargo, no podemos estar demasiado seguros. Continuar la búsqueda.",
  ui_story_1015_10151501_15_dialog_content = "¡Sí, señora!",
  ui_story_1015_10151501_16_dialog_content = "Forsakin en realidad logró desaparecer justo debajo de nuestras narices sin siquiera sudar.",
  ui_story_1015_10151501_17_dialog_content = "Ella arrojó su veneno y corrió como el viento.",
  ui_story_1015_10151501_18_dialog_content = "Gran Mariscal, Capitán Wrath—Creo que podría saber cómo escapó Forsakin.",
  ui_story_1015_10151501_19_dialog_content = "¿Mmm? Cuéntanos entonces.",
  ui_story_1015_10151501_20_dialog_content = "Forsakin diseñó y construyó esta Entrañas.",
  ui_story_1015_10151501_21_dialog_content = "Después de construir Entrañas y antes de desertar de la Federación Illumina, Forsakin viajó en secreto entre aquí y Gannon City varias veces.",
  ui_story_1015_10151501_22_dialog_content = "Según la inteligencia que he reunido, Forsakin es alguien que no soporta perder el tiempo en cosas sin sentido.",
  ui_story_1015_10151501_23_dialog_content = "Así que especulo que ella también puede haber construido un pasaje secreto que puede usarse para viajar rápidamente entre aquí y la ciudad de Gannon.",
  ui_story_1015_10151501_24_dialog_content = "¿Estás diciendo que es posible que ya haya huido a Gannon?",
  ui_story_1015_10151501_25_dialog_content = "Sí.",
  ui_story_1015_10151501_26_dialog_content = "Hmm, eso tiene sentido. Organizaré inmediatamente una búsqueda en Gannon City para investigar.",
  ui_story_1015_10151501_27_dialog_content = "Reinhardt, permíteme manejar esto.",
  ui_story_1015_10151501_28_dialog_content = "No, como este asunto está relacionado con Forsakin y Helios, debo tomarlo en mis propias manos.",
  ui_story_1015_10151501_29_dialog_content = "Es preciso porque este asunto involucra a esos dos, que no se le puede pedir que se ocupe de eso.",
  ui_story_1015_10151501_30_dialog_content = "El Comité me asignó esta misión, por lo que debería ser yo quien se asegure de que se lleve a cabo.",
  ui_story_1015_10151501_31_dialog_content = "Además, nuestros objetivos son su hermana y ex camarada...",
  ui_story_1015_10151501_32_dialog_content = "Incluso si creo que puedes manejar este lío de manera justa, hay quienes no confían tanto.",
  ui_story_1015_10151501_33_dialog_content = "Cualquiera que tenga ojos puede ver que ha estado tratando de encontrar alguna excusa para meterse contigo recientemente.",
  ui_story_1015_10151501_34_dialog_content = "Y el Ejercicio Militar Conjunto está a punto de comenzar. Todas las fuerzas de Astra tendrán sus ojos firmemente puestos en Illumina.",
  ui_story_1015_10151501_35_dialog_content = "Lo que debes hacer ahora es simplemente regresar con Gannon.",
  ui_story_1015_10151501_36_dialog_content = "El regreso no solo ayudará a estabilizar la situación y asegurar su autoridad...",
  ui_story_1015_10151501_37_dialog_content = "Mientras estés a cargo, incluso si Forsakin está realmente en Gannon, no se atreverá a causar problemas.",
  ui_story_1015_10151501_38_dialog_content = "...",
  ui_story_1015_10151501_39_dialog_content = "Si no confías en mí, puedes enviar a un supervisor para que me vigile o algo así. Ni siquiera me importa tener varios supervisores observándome, cuantos más, mejor.",
  ui_story_1015_10151501_40_dialog_content = "Como siempre he dicho, solo me interesa vencerte justamente.",
  ui_story_1015_10151501_41_dialog_content = "Así ha sido siempre, así es y así será siempre.",
  ui_story_1015_10151501_42_dialog_content = "Tengo fe en ti.",
  ui_story_1015_10151501_43_dialog_content = "Dejaré la tarea de perseguir a Forsakin y traer de vuelta a Helios en tus manos.",
  ui_story_1015_10151501_44_dialog_content = "No te preocupes, te prometo que los encontraré.",
  ui_story_1015_10151501_45_dialog_content = "Bueno, ahora que está arreglado, ¿por qué no regresan todos a Gannon City conmigo? Qué dices, PlayerName?",
  ui_story_1015_10151501_46_dialog_content = "Pero, la misión...",
  ui_story_1015_10151501_47_dialog_content = "Dado que el Comité encomendó este asunto al Capitán Wrath, ya no tienes que preocuparte por eso.",
  ui_story_1015_10151501_48_dialog_content = "Ocupémonos primero del asunto que nos ocupa.",
  ui_story_1015_10151501_49_dialog_content = "Sí, señora.",
  ui_story_1015_10151501_50_dialog_content = "Si entiendo.",
  ui_story_1015_10151501_51_dialog_content = "<size=30>De hecho, todavía tengo mucho que hacer para ayudarlo a planificar el programa del Gran Mariscal para el período de ejercicio, así como también...</size>",
  ui_story_1015_10151501_52_dialog_content = "Anatoli.",
  ui_story_1015_10151501_53_dialog_content = "<size=45>¡Señora!</size>",
  ui_story_1015_10151501_54_dialog_content = "¿Tiene alguna instrucción adicional, Gran Mariscal?",
  ui_story_1015_10151501_55_dialog_content = "Ya no hace falta que me acompañes. Ve y participa en el ejercicio.",
  ui_story_1015_10151501_56_dialog_content = "Sí, espere un momento, Gran Mariscal, no me he unido a ningún equipo, así que no puedo participar en el ejercicio.",
  ui_story_1015_10151501_57_dialog_content = "No tienes que preocuparte por eso, uno de los miembros del equipo tiene algunos asuntos que atender y no puede participar.",
  ui_story_1015_10151501_58_dialog_content = "Estarás llenando el lugar.",
  ui_story_1015_10151501_59_dialog_content = "Sí, señora. ¿En qué equipo estaré?",
  ui_story_1015_10151501_60_dialog_content = "Deberías estar bastante familiarizado con ella ahora. Es el equipo de Yingel.",
  ui_story_1015_10151501_61_dialog_content = "¿Qué? ¿Mi equipo?",
  ui_story_1015_10151501_62_dialog_content = "¿Le pasó algo a Axelia?",
  ui_story_1015_10151501_63_dialog_content = "No, no es ella. Soy Sean.",
  ui_story_1015_10151501_64_dialog_content = "Acabo de recibir noticias de Twilight.",
  ui_story_1015_10151501_65_dialog_content = "Aparentemente, la condición física de Sean de repente empeoró y necesita quedarse en Crepúsculo para observación temporal.",
  ui_story_1015_10151501_66_dialog_content = "¿Como es el? ¿El está bien?",
  ui_story_1015_10151501_67_dialog_content = "El mensaje de Twilight decía que simplemente experimentó algunos fenómenos extraños cuando usaba Luminatic que nunca antes había experimentado.",
  ui_story_1015_10151501_68_dialog_content = "Puede estar relacionado con un defecto genético innato.",
  ui_story_1015_10151501_69_dialog_content = "¿Es así...?",
  ui_story_1015_10151501_70_dialog_content = "Después de que terminemos con Gannon, vayamos a Crepúsculo y hagámosle una visita.",
  ui_story_1015_10151501_71_dialog_content = "Entonces, ¿quieres que haga equipo con Yingel y Axelia?",
  ui_story_1015_10151501_72_dialog_content = "Cumpliré con tus órdenes.",
  ui_story_1015_10151501_73_dialog_content = "(Es una ligera desviación del plan original, pero aún así no es un problema. Debería poder hacer que esto funcione).",
  ui_story_1015_10151501_74_dialog_content = "Yo tampoco tengo objeciones.",
  ui_story_1015_10151501_75_dialog_content = "Eso lo resuelve entonces.",
  ui_story_1015_10151501_76_dialog_content = "Es hora de volver a Gannon City.",
  ui_story_1015_10151501_77_dialog_content = "<color=#e8d9bb>Unos días después, en la ciudad de Gannon...</color>",
  ui_story_1015_10151501_78_dialog_content = "El tren está a punto de llegar a Gannon. Prepárese para desembarcar y tenga cuidado con el espacio entre el tren y la plataforma.",
  ui_story_1015_10151501_79_dialog_content = "May la luz de la iluminación te guíe en tu viaje.",
  ui_story_1015_10151501_80_dialog_content = "Disculpe, déjenos bajar del tren, por favor.",
  ui_story_1015_10151501_81_dialog_content = "Hay tanta gente hoy... ¡Este es realmente el ejercicio militar más grande de Astra!",
  ui_story_1015_10151501_82_dialog_content = "Pero este lugar es tan grande... No nos equivocamos de camino, ¿verdad? ¿Es esta la estación correcta?",
  ui_story_1015_10151501_83_dialog_content = "Esto debería ser todo, según las instrucciones de Lady Carleen.",
  ui_story_1015_10151501_84_dialog_content = "Espero que no nos perdamos...",
  ui_story_1015_10151501_85_dialog_content = "Beretta.",
  ui_story_1015_10151501_86_dialog_content = "Dama Carleen!",
  ui_story_1015_10151501_87_dialog_content = "Según lo acordado, estoy aquí para recogerte.",
  ui_story_1015_10151501_88_dialog_content = "¡Muchas gracias! Sin ti aquí, definitivamente terminaríamos perdiéndonos...",
  ui_story_1015_10151501_89_dialog_content = "No lo menciones. Participe en más de estos ejercicios y pronto estará familiarizado con esta área.",
  ui_story_1015_10151501_90_dialog_content = "Vamos.",
  ui_story_1015_10151501_91_dialog_content = "¡Sí, señora Carleen!",
  ui_story_1015_10151501_92_dialog_content = "¿La chica de hace un momento no se parecía a esa Dama?",
  ui_story_1015_10151501_93_dialog_content = "De hecho, ese ciertamente parece ser el caso.",
  ui_story_1015_10151501_94_dialog_content = "¿No vas a saludar?",
  ui_story_1015_10151501_95_dialog_content = "Jajaja, ahora mismo no.",
  ui_story_1015_10151501_96_dialog_content = "Hay tanta gente aquí. No nos interpongamos en su camino, ¿eh?",
  ui_story_1015_10151501_97_dialog_content = "Todavía tenemos mucho tiempo para recordar y saludarnos antes de que comience oficialmente el Ejercicio Militar Conjunto.",
  ui_story_1015_10151501_98_dialog_content = "Buen punto.",
  ui_story_1015_10151501_99_dialog_content = "Especialmente cuando nuestros nuevos compañeros de equipo todavía tienen una misión en sus manos...",
  ui_story_1015_10151501_100_dialog_content = "Abran paso, abran paso.",
  ui_story_1015_10151501_101_dialog_content = "Cuervo, ven aquí, y ten cuidado de no chocar con la puerta.",
  ui_story_1015_10151501_102_dialog_content = "Lo se.",
  ui_story_1015_10151501_103_dialog_content = "Lo siento mucho por esto...",
  ui_story_1015_10151501_104_dialog_content = "Claramente soy yo quien se suponía que debía encargarse de esta misión, pero realmente necesito su ayuda.",
  ui_story_1015_10151501_105_dialog_content = "Soy tu asistente. Es mi deber asistirlos y protegerlos.",
  ui_story_1015_10151501_106_dialog_content = "Además, si no te ayudara, no podrías llevar esto solo a Gannon City.",
  ui_story_1015_10151501_107_dialog_content = "Era la única forma... Después de todo, no soy exactamente del tipo físico.",
  ui_story_1015_10151501_108_dialog_content = "¿Necesitas ayuda, táctico de Illumina?",
  ui_story_1015_10151501_109_dialog_content = "Eso no será necesario, estamos a punto de llegar a nuestro destino.",
  ui_story_1015_10151501_110_dialog_content = "Si necesito algo, me encargaré de buscarte.",
  ui_story_1015_10151501_111_dialog_content = "Bien bien. No hay necesidad de ser tímido solo porque no hemos trabajado juntos antes.",
  ui_story_1015_10151501_112_dialog_content = "Incluso si algún día decides que quieres unirte a los Caballeros de Ironthorn, házmelo saber y te prometo que no me importará.",
  ui_story_1015_10151501_113_dialog_content = "Tienes bastante sentido del humor.",
  ui_story_1015_10151501_114_dialog_content = "Si no le importa, siga adelante y obtenga el registro con el Sr. Joseph primero.",
  ui_story_1015_10151501_115_dialog_content = "Cuervo y yo debemos llevársela al encargado antes de que podamos registrarnos.",
  ui_story_1015_10151501_116_dialog_content = "Está bien, vamos a seguir entonces.",
  ui_story_1015_10151501_117_dialog_content = "Hasta luego, Zhao.",
  ui_story_1015_10151501_118_dialog_content = "...",
  ui_story_1015_10151501_119_dialog_content = "¿Qué pasa, Cuervo?",
  ui_story_1015_10151501_120_dialog_content = "...",
  ui_story_1015_10151501_121_dialog_content = "Quieres preguntar por qué me estoy asociando con ellos en lugar de contigo otra vez, ¿no?",
  ui_story_1015_10151501_122_dialog_content = "Puedo protegerte, ellos no.",
  ui_story_1015_10151501_123_dialog_content = "Eso lo sé.",
  ui_story_1015_10151501_124_dialog_content = "Pero esta fue una decisión que tomamos todos juntos, todos los ciudadanos de Crepúsculo.",
  ui_story_1015_10151501_125_dialog_content = "Yo también soy ciudadano de Crepúsculo.",
  ui_story_1015_10151501_126_dialog_content = "Lo sé, pero esta vez es diferente.",
  ui_story_1015_10151501_127_dialog_content = "Esta colaboración con Ironthorn Knights y la Iglesia del Dios de la Luz tiene como objetivo mostrar al mundo exterior la unidad y la fuerza de Twilight.",
  ui_story_1015_10151501_128_dialog_content = "Si llegamos a la cima, solo entonces tendremos suficiente reconocimiento e influencia para hablar y ejercer presión sobre las otras fuerzas de Astra.",
  ui_story_1015_10151501_129_dialog_content = "¿A todos les desagrada tanto Crepúsculo?",
  ui_story_1015_10151501_130_dialog_content = "No, no les desagrada Crepúsculo.",
  ui_story_1015_10151501_131_dialog_content = "Simplemente no les importa.",
  ui_story_1015_10151501_132_dialog_content = "Pero lo hacemos. El crepúsculo es nuestro hogar, no podemos quedarnos de brazos cruzados y ver cómo las olas de eclipses lo engullen.",
  ui_story_1015_10151501_133_dialog_content = "Así que esta vez, debemos ganar. Debemos hacer que se preocupen, para que envíen más refuerzos a Crepúsculo.",
  ui_story_1015_10151501_134_dialog_content = "...",
  ui_story_1015_10151501_135_dialog_content = "Seguiré tu ejemplo.",
  ui_story_1015_10151501_136_dialog_content = "Gracias por su comprensión.",
  ui_story_1015_10151501_137_dialog_content = "Se está haciendo tarde. Démonos prisa y entreguémosla.",
  ui_story_1015_10151501_138_dialog_content = "¿Son ellos los objetivos?",
  ui_story_1015_10151501_139_dialog_content = "¡No parecen nada divertidos! No tan divertido como el oso de peluche en mi sueño, de todos modos...",
  ui_story_1015_10151501_140_dialog_content = "No te apresures a juzgar, amigo mío.",
  ui_story_1015_10151501_141_dialog_content = "La misión del Maestro para nosotros hoy es observarlos, así que eso es lo que haremos.",
  ui_story_1015_10151501_142_dialog_content = "La intuición del Maestro rara vez se equivoca. Creo que deben tener una agenda oculta.",
  ui_story_1015_10151501_143_dialog_content = "Solo espero que les gusten los pequeños bichos tanto como a mí...",
  ui_story_1015_10151501_144_dialog_content = "Y esa es la situación actual.",
  ui_story_1015_10151501_145_dialog_content = "Reinhardt ha regresado a la ciudad de Gannon, y se desconoce el paradero de Forsakin y el sujeto de prueba objetivo, aunque es muy probable que también se encuentren en algún lugar de la ciudad de Gannon.",
  ui_story_1015_10151501_146_dialog_content = "Además, varias fuerzas se han reunido ahora en Gannon, ya que el Ejercicio Militar Conjunto está a punto de comenzar.",
  ui_story_1015_10151501_147_dialog_content = "Sin embargo, el equipo conjunto Crepúsculo formado por miembros de Illumina y Lumopolis es de hecho un giro inesperado de los acontecimientos.",
  ui_story_1015_10151501_148_dialog_content = "¿Le gustaría que encontrara dos especialistas para formar un equipo y contener sus acciones?",
  ui_story_1015_10151501_149_dialog_content = "De hecho, vale la pena vigilarlos, pero no hay necesidad de tomarlos demasiado en serio.",
  ui_story_1015_10151501_150_dialog_content = "Yingel y Axelia son dos soldados muy confiables.",
  ui_story_1015_10151501_151_dialog_content = "Además, tienes otros asuntos que atender.",
  ui_story_1015_10151501_152_dialog_content = "¡Sí señor!",
  ui_story_1015_10151501_153_dialog_content = "<color=#e8d9bb>Mientras tanto, en algún lugar de la ciudad de Gannon...</color>",
  ui_story_1015_10151501_154_dialog_content = "<anim type=Shake><size=45>Rugido...</size></anim>",
  ui_story_1015_10151501_155_dialog_content = "Ponlo aquí abajo.",
  ui_story_1015_10151501_156_dialog_content = "<anim type=Shake><size=45>¡Gahhhh!</size></anim>",
  ui_story_1015_10151501_157_dialog_content = "<anim type=Shake>Gruñido-</anim>",
  ui_story_1015_10151501_158_dialog_content = "Buena niña.",
  ui_story_1015_10151501_159_dialog_content = "Vuelve a cambiar y sigue estos conductos. Deja esta Entrañas.",
  ui_story_1015_10151501_160_dialog_content = "<anim type=Shake><size=45>¡¿Grrr?!</size></anim>",
  ui_story_1015_10151501_161_dialog_content = "<anim type=Shake><size=45>Rrr... Rugido...!</size></anim>",
  ui_story_1015_10151501_162_dialog_content = "No hay nada que puedas hacer por mí aquí.",
  ui_story_1015_10151501_163_dialog_content = "Si te quedas aquí más tiempo, solo me retrasarás.",
  ui_story_1015_10151501_164_dialog_content = "Ya sabes dónde esperarme.",
  ui_story_1015_10151501_165_dialog_content = "<anim type=Shake>Rugido...</anim>",
  ui_story_1015_10151501_166_dialog_content = "¡Chirrido!",
  ui_story_1015_10151501_167_dialog_content = "¿Negador...?",
  ui_story_1015_10151501_168_dialog_content = "...",
  ui_story_1015_10151501_169_dialog_content = "Estas despierto.",
  ui_story_1015_10151501_170_dialog_content = "Cierto...",
  ui_story_1015_10151501_171_dialog_content = "¿Dónde... me has... llevado?",
  ui_story_1015_10151501_172_dialog_content = "¿La capacidad cognitiva se recupera gradualmente?",
  ui_story_1015_10151501_173_dialog_content = "Aunque esto indicó que el experimento fue un éxito, el momento es desafortunado.",
  ui_story_1015_10151501_174_dialog_content = "De qué estás hablando...? No entiendo...",
  ui_story_1015_10151501_175_dialog_content = "Nada.",
  ui_story_1015_10151501_176_dialog_content = "¿Dónde estoy? Aún no me has respondido...",
  ui_story_1015_10151501_177_dialog_content = "...",
  ui_story_1015_10151501_178_dialog_content = "Ciudad de Ganon.",
  ui_story_1015_10151501_179_dialog_content = "¿Estamos de vuelta?",
  ui_story_1015_10151501_180_dialog_content = "Sí.",
  ui_story_1015_10151501_181_dialog_content = "Estamos de vuelta.",
  ui_story_1016_10160101_1_dialog_content = "<color=#e8d9bb>ELIGE—</color>",
  ui_story_1016_10160101_2_dialog_content = "<color=#e8d9bb>Ka-pedazo, ka-pedazo, ka-pedazo—</color>",
  ui_story_1016_10160101_3_dialog_content = "Atención, todos los participantes del Ejercicio Militar Conjunto.",
  ui_story_1016_10160101_4_dialog_content = "El tren ha llegado a su destino. Ahora puede salir del tren.",
  ui_story_1016_10160101_5_dialog_content = "Espere más instrucciones en la estación.",
  ui_story_1016_10160101_6_dialog_content = "¡Guau! ¡Qué increíble primera vez en un tren!",
  ui_story_1016_10160101_7_dialog_content = "Los trenes son mucho más rápidos que los carruajes tirados por caballos, ¿no es así?",
  ui_story_1016_10160101_8_dialog_content = "El traqueteo constante era un poco excesivo si me preguntas. Me siento mucho mejor ahora que nos hemos apeado.",
  ui_story_1016_10160101_9_dialog_content = "Este lugar es donde se llevará a cabo el ejercicio conjunto, ¿verdad? ¿Qué debemos hacer ahora?",
  ui_story_1016_10160101_10_dialog_content = "Solo espera aquí por ahora. Alguien explicará las cosas en breve.",
  ui_story_1016_10160101_11_dialog_content = "Anatoli! ¡Mucho tiempo sin verlo!",
  ui_story_1016_10160101_12_dialog_content = "¿También participa en el ejercicio conjunto?",
  ui_story_1016_10160101_13_dialog_content = "Por supuesto. Todos aquí son participantes entusiastas en el próximo ejercicio de entrenamiento.",
  ui_story_1016_10160101_14_dialog_content = "¡Veo! ¡Eso explica la emoción en el aire!",
  ui_story_1016_10160101_15_dialog_content = "Esperemos que Illumina mantenga las cosas civilizadas.",
  ui_story_1016_10160101_16_dialog_content = "No hay necesidad de preocuparse. Después de todo, la opresión es el punto fuerte de Lumopolis.",
  ui_story_1016_10160101_17_dialog_content = "Hmph.",
  ui_story_1016_10160101_18_dialog_content = "¡Por favor, despejen el camino, todos! ¡Estamos descargando un cargamento frágil ahora mismo!",
  ui_story_1016_10160101_19_dialog_content = "No tropieces con nada, no tropieces con nada.",
  ui_story_1016_10160101_20_dialog_content = "Entonces, ¿a dónde llevamos esto, Zhao?",
  ui_story_1016_10160101_21_dialog_content = "Se supone que el destinatario nos encontrará aquí...",
  ui_story_1016_10160101_22_dialog_content = "Gracias a los dos por su ayuda. Puedes dejar esto conmigo ahora.",
  ui_story_1016_10160101_23_dialog_content = "Has completado tu misión.",
  ui_story_1016_10160101_24_dialog_content = "Ah, entonces usted fue el destinatario todo el tiempo, Coronel. Yingel.",
  ui_story_1016_10160101_25_dialog_content = "¿Hay algo extraño en eso?",
  ui_story_1016_10160101_26_dialog_content = "Su participación en el ejercicio conjunto es un poco extraña, eso sí.",
  ui_story_1016_10160101_27_dialog_content = "Siempre pensé que eventos como este estaban por debajo de alguien de tu estatus.",
  ui_story_1016_10160101_28_dialog_content = "Debes pensar muy bien de mí, entonces.",
  ui_story_1016_10160101_29_dialog_content = "Aquí tienes. Transportar esta cosa no fue muy fácil, ya sabes.",
  ui_story_1016_10160101_30_dialog_content = "¿Te gustaría comprobar y asegurarte de que todo está intacto?",
  ui_story_1016_10160101_31_dialog_content = "Sí.",
  ui_story_1016_10160101_32_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_1016_10160101_33_dialog_content = "Hora de despertar, Axelia.",
  ui_story_1016_10160101_34_dialog_content = "<color=#e8d9bb>Tssss—</color>",
  ui_story_1016_10160101_35_dialog_content = "Yaaaawn.",
  ui_story_1016_10160101_36_dialog_content = "Buenos dias, Yingel.",
  ui_story_1016_10160101_37_dialog_content = "¿Dormiste bien?",
  ui_story_1016_10160101_38_dialog_content = "Sí, me siento muy bien descansado ahora.",
  ui_story_1016_10160101_39_dialog_content = "Uf, qué asfixiante.",
  ui_story_1016_10160101_40_dialog_content = "Realmente no me importa estar encerrado en un espacio tan sofocante.",
  ui_story_1016_10160101_41_dialog_content = "Estás sudando como si acabaras de terminar una batalla, Leo.",
  ui_story_1016_10160101_42_dialog_content = "Sí, y me siento igual de cansada también.",
  ui_story_1016_10160101_43_dialog_content = "¿No crees que estás exagerando un poco? Es solo otra forma de transporte.",
  ui_story_1016_10160101_44_dialog_content = "Nunca estuvimos en peligro.",
  ui_story_1016_10160101_45_dialog_content = "No tiene nada que ver con si estábamos o no en peligro...",
  ui_story_1016_10160101_46_dialog_content = "¿Quieres una servilleta?",
  ui_story_1016_10160101_47_dialog_content = "Por qué sí, gracias... ¿Hmm? L-dama Carleen?!",
  ui_story_1016_10160101_48_dialog_content = "Entiendo como te sientes. Muchas personas de Lumopolis tienen dificultades para adaptarse a estas máquinas.",
  ui_story_1016_10160101_49_dialog_content = "Veo. Si tan solo todos fueran tan comprensivos como usted, milady.",
  ui_story_1016_10160101_50_dialog_content = "Debo decir que encontrarte aquí es toda una sorpresa.",
  ui_story_1016_10160101_51_dialog_content = "Supuse que nuestro próximo encuentro sería en Lumopolis.",
  ui_story_1016_10160101_52_dialog_content = "Dados nuestros estados, una reunión en Lumopolis habría estado plagada de complicaciones. Aquí, sin embargo, somos libres de hablar como participantes del ejercicio.",
  ui_story_1016_10160101_53_dialog_content = "Jajajaja! ¡Bien dicho, mi señora!",
  ui_story_1016_10160101_54_dialog_content = "Un poco de simplicidad siempre es bienvenida cuando las personas llevan vidas tan complicadas.",
  ui_story_1016_10160101_55_dialog_content = "Oye es Leo y José! ¿Ustedes también están aquí para el ejercicio conjunto?",
  ui_story_1016_10160101_56_dialog_content = "¡Debe haber sido un largo viaje desde Crepúsculo!",
  ui_story_1016_10160101_57_dialog_content = "PlayerName! ¿Qué estás haciendo aquí?",
  ui_story_1016_10160101_58_dialog_content = "Me invitaron al ejercicio conjunto, así que vine con Carleen y Vice.",
  ui_story_1016_10160101_59_dialog_content = "Veo. Habría pedido un paseo a bordo de tu Colossus si hubiera sabido que vendrías...",
  ui_story_1016_10160101_60_dialog_content = "¡Jajaja! Siempre eres bienvenido a subir a bordo, ¿sabes?",
  ui_story_1016_10160101_61_dialog_content = "¡Ejem! Todos los participantes, por favor reúnanse aquí.",
  ui_story_1016_10160101_62_dialog_content = "Ahora daré más instrucciones sobre el Ejercicio Militar Conjunto.",
  ui_story_1016_10160101_63_dialog_content = "¿Escuché la voz de Vivian hace un momento?",
  ui_story_1016_10160101_64_dialog_content = "¡Sí! ¡Vámonos!",
  ui_story_1016_10160101_65_dialog_content = "C-Cuidado, Vice. Hay mucha gente aquí.",
  ui_story_1016_10160101_66_dialog_content = "Puedes relajarte un rato. No es como si me lastimara por lo que pasó antes o algo así.",
  ui_story_1016_10160101_67_dialog_content = "Además, ¿no recuerdas lo que dijo el examen médico? ¡Estoy tan saludable como puede ser!",
  ui_story_1016_10160101_68_dialog_content = "Pero sigo pensando...",
  ui_story_1016_10160101_69_dialog_content = "¡Vamos, vamos!",
  ui_story_1016_10160101_70_dialog_content = "En primer lugar, gracias a todos por venir hoy a Gannon City para participar en nuestro Ejercicio Militar Conjunto.",
  ui_story_1016_10160101_71_dialog_content = "Soy Vivian, Jefa de Estado Mayor de la Federación Illumina, y seré su guía.",
  ui_story_1016_10160101_72_dialog_content = "Illumina otorga gran importancia a la eficiencia, así que continuemos sin más demora.",
  ui_story_1016_10160101_73_dialog_content = "Después de que termine mi explicación de las reglas, el Ejercicio Militar Conjunto comenzará oficialmente.",
  ui_story_1016_10160101_74_dialog_content = "Realmente no andan por las ramas, ¿eh?",
  ui_story_1016_10160101_75_dialog_content = "Para ser honesto, esto me sienta mejor que un discurso formal y prolijo.",
  ui_story_1016_10160101_76_dialog_content = "Como todos saben muy bien, este Ejercicio Militar Conjunto tiene como objetivo mejorar la capacidad de las generaciones más jóvenes para hacer frente a los rigores de la guerra.",
  ui_story_1016_10160101_77_dialog_content = "Cada participante reunido aquí hoy tiene menos de veinticinco años.",
  ui_story_1016_10160101_78_dialog_content = "Todos ustedes son oficiales jóvenes que recién comienzan a mostrar su talento o estudiantes que aún no han dejado la seguridad de la torre de marfil de la academia.",
  ui_story_1016_10160101_79_dialog_content = "Independientemente de las diferencias de edad o experiencia, todos y cada uno de ustedes verán la batalla algún día.",
  ui_story_1016_10160101_80_dialog_content = "Todos deben hacer todo lo posible para perfeccionar sus capacidades de combate a través del estudio, la cooperación y la competencia.",
  ui_story_1016_10160101_81_dialog_content = "Para preparar el escenario para su entrenamiento, el ejercicio militar se dividirá en dos fases: educación y evaluación de combate.",
  ui_story_1016_10160101_82_dialog_content = "Durante la fase de educación, Illumina les brindará recursos de la más alta calidad y el conocimiento de sus predecesores para mejorar.",
  ui_story_1016_10160101_83_dialog_content = "Durante la fase de evaluación, formará equipos y competirá entre sí para determinar el vencedor final.",
  ui_story_1016_10160101_84_dialog_content = "Dudo que alguien deba recordar que, de acuerdo con la tradición, el ganador de la evaluación recibirá un premio único:",
  ui_story_1016_10160101_85_dialog_content = "Una oportunidad para entrenar con el Gran Mariscal.",
  ui_story_1016_10160101_86_dialog_content = "¿Una oportunidad de luchar contra el Gran Mariscal? Eso da demasiado miedo... ¿Quién querría eso?",
  ui_story_1016_10160101_87_dialog_content = "Pero, de nuevo, el campeón del ejercicio conjunto también será bastante duro...",
  ui_story_1016_10160101_88_dialog_content = "¡Tienes razón! La última vez fue esa princesa de Lumopolis...",
  ui_story_1016_10160101_89_dialog_content = "Con esto concluye la introducción básica del ejercicio.",
  ui_story_1016_10160101_90_dialog_content = "¡Levanta la pancarta!",
  ui_story_1016_10160101_91_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_1016_10160101_92_dialog_content = "¡Guau! ¡Esa es una larga cadena de banderas!",
  ui_story_1016_10160101_93_dialog_content = "Este es el <color=#FFB400>estandarte de campeones</color>.",
  ui_story_1016_10160101_94_dialog_content = "Solo el campeón del Ejercicio Militar Conjunto tiene el privilegio de agregarle la bandera de su facción.",
  ui_story_1016_10160101_95_dialog_content = "Con cada ejercicio conjunto realizado, el Estandarte de los Campeones se ha convertido en lo que ven ante ustedes ahora.",
  ui_story_1016_10160101_96_dialog_content = "Puedes ver pruebas de las victorias pasadas de cada facción importante.",
  ui_story_1016_10160101_97_dialog_content = "Como las innumerables estrellas que brillan arriba en los cielos—",
  ui_story_1016_10160101_98_dialog_content = "¡Este estandarte es un símbolo de nuestro ejercicio conjunto, así como del deseo inquebrantable de cada generación de lograr la victoria en la batalla!",
  ui_story_1016_10160101_99_dialog_content = "(!!!)",
  ui_story_1016_10160101_100_dialog_content = "(¡¿Estoy viendo cosas, o es una bandera de los Caelestitas...?!)",
  ui_story_1016_10160101_101_dialog_content = "Ahora bien, todos. Sin más preámbulos, es un honor para mí anunciar—",
  ui_story_1016_10160101_102_dialog_content = "¡El inicio oficial de este Ejercicio Militar Conjunto!",
  ui_story_1016_10160101_103_dialog_content = "<color=#e8d9bb>*Aplausos*</color>",
  ui_story_1016_10160101_104_dialog_content = "Ahora comenzaremos a registrar formalmente a todos para el evento.",
  ui_story_1016_10160101_105_dialog_content = "En tus cartas de invitación encontrarás el equipo al que has sido asignado.",
  ui_story_1016_10160101_106_dialog_content = "Un equipo está compuesto por tres participantes, que representan la unidad operativa más básica en este Ejercicio Militar Conjunto.",
  ui_story_1016_10160101_107_dialog_content = "La facción del capitán del equipo también servirá como la facción de todo el equipo.",
  ui_story_1016_10160101_108_dialog_content = "Tómese un momento para ubicar a los otros miembros de su equipo.",
  ui_story_1016_10160101_109_dialog_content = "Entonces, Carleen y Vice estará en mi equipo, ¿verdad?",
  ui_story_1016_10160101_110_dialog_content = "¿Se te olvidó o algo? ¡Por supuesto que somos!",
  ui_story_1016_10160101_111_dialog_content = "La invitación también dice que liderarás el equipo, Capitán.",
  ui_story_1016_10160101_112_dialog_content = "Oh, por favor no digas eso...",
  ui_story_1016_10160101_113_dialog_content = "Una vez que haya confirmado a los otros miembros de su equipo, venga a mí para registrarse.",
  ui_story_1016_10160101_114_dialog_content = "Una vez que se complete el registro, los acompañaré a todos a sus barracas para dejar su equipaje. Después, eres libre de hacer lo que quieras dentro del área permitida.",
  ui_story_1016_10160101_115_dialog_content = "Su primera clase se llevará a cabo mañana por la mañana.",
  ui_story_1016_10160101_116_dialog_content = "¡Estoy tan emocionada!",
  ui_story_1016_10160101_117_dialog_content = "Conozco estos ejercicios para las articulaciones desde que era una niña, ¡pero esta es la primera vez que participo en uno!",
  ui_story_1016_10160101_118_dialog_content = "¿Cómo fue la última vez que viniste, Carleen?",
  ui_story_1016_10160101_119_dialog_content = "Me sentí igual que tú, más o menos.",
  ui_story_1016_10160101_120_dialog_content = "Emocionado, pero no completamente seguro de mí mismo.",
  ui_story_1016_10160101_121_dialog_content = "No estoy completamente seguro y, sin embargo, saliste victorioso, ¿eh?",
  ui_story_1016_10160101_122_dialog_content = "¡Ser un genio nato debe ser tan agradable!",
  ui_story_1016_10160101_123_dialog_content = "¡N-No estaba tratando de presumir! ¡En realidad!",
  ui_story_1016_10160101_124_dialog_content = "¡Jejeje! Estoy bromeando, Carleen!",
  ui_story_1016_10160101_125_dialog_content = "Que piensas sobre todo esto, PlayerName? Apenas has hablado desde que llegamos aquí.",
  ui_story_1016_10160101_126_dialog_content = "¿Todavía no estás acostumbrado a entornos estresantes como este?",
  ui_story_1016_10160101_127_dialog_content = "Estaba pensando... La mayoría de los otros participantes son nuestros amigos.",
  ui_story_1016_10160101_128_dialog_content = "Supongo que no estaba mentalmente preparado para enfrentarme a ellos, eso es todo.",
  ui_story_1016_10160101_129_dialog_content = "Tiene sentido, considerando cuán reacio a los conflictos tiendes a ser.",
  ui_story_1016_10160101_130_dialog_content = "¡Pero eso está bien! ¡Concentrémonos más en aprender en lugar de competir!",
  ui_story_1016_10160101_131_dialog_content = "P-Pero también quiero ganar esta vez...",
  ui_story_1016_10160101_132_dialog_content = "¿Ah?",
  ui_story_1016_10160101_133_dialog_content = "Vi la bandera de Caelestites en el Estandarte de Campeones antes.",
  ui_story_1016_10160101_134_dialog_content = "Me hizo muy feliz ver la huella de mi pueblo en la historia, pero...",
  ui_story_1016_10160101_135_dialog_content = "Cuando vi lo lejos que estaba de la bandera agregada más recientemente, no pude evitar sentirme un poco triste también.",
  ui_story_1016_10160101_136_dialog_content = "Hace tanto tiempo que los caelestitas no participan en esta competición...",
  ui_story_1016_10160101_137_dialog_content = "No quiero que el orgullo de mi pueblo quede tan anclado en el pasado, como esa bandera.",
  ui_story_1016_10160101_138_dialog_content = "¡Quiero colgar otro en la parte delantera de la pancarta!",
  ui_story_1016_10160101_139_dialog_content = "¡Escucha atentamente! Todos en nuestro equipo son oriundos de Lumopolis.",
  ui_story_1016_10160101_140_dialog_content = "¡Esto significa que nuestras acciones reflejan directamente sus ilustres estándares educativos!",
  ui_story_1016_10160101_141_dialog_content = "No debemos avergonzar a Lumopolis ni a los Dawn ¡Academia!",
  ui_story_1016_10160101_142_dialog_content = "¿Ya está haciendo grandiosos discursos, capitán?",
  ui_story_1016_10160101_143_dialog_content = "¡No estoy dando un discurso!",
  ui_story_1016_10160101_144_dialog_content = "Solo quería levantar la moral de todos para la próxima competencia...",
  ui_story_1016_10160101_145_dialog_content = "Ella está en lo correcto. La competencia por este Ejercicio Militar Conjunto es feroz.",
  ui_story_1016_10160101_146_dialog_content = "Tendremos que mantener el ánimo alto si no queremos quedarnos atrás.",
  ui_story_1016_10160101_147_dialog_content = "¿Es eso así? ¿Cuáles son sus impresiones de los otros equipos, entonces?",
  ui_story_1016_10160101_148_dialog_content = "solo soy consciente de PlayerName y su equipo",
  ui_story_1016_10160101_149_dialog_content = "Las habilidades psíquicas de Caelestite, combinadas con Lady Carleen y la fuerza combinada de Miss Vice, los convierte en una poderosa amenaza.",
  ui_story_1016_10160101_150_dialog_content = "Bueno, señora Carleen es el actual campeón después de todo. Estoy seguro de que no perderá su título muy fácilmente.",
  ui_story_1016_10160101_151_dialog_content = "Aparte de PlayerNameEl equipo de, hay otros dos equipos dignos de mención.",
  ui_story_1016_10160101_152_dialog_content = "Uno es el equipo de Leo. Él y sus camaradas provienen de Crepúsculo.",
  ui_story_1016_10160101_153_dialog_content = "Durante una de mis misiones anteriores, tuve el privilegio de ver de primera mano cómo luchaban esos guerreros de Crepúsculo.",
  ui_story_1016_10160101_154_dialog_content = "Los tres tienen una gran experiencia en combate. Ningún otro equipo podría compararse en este departamento.",
  ui_story_1016_10160101_155_dialog_content = "Veo. La experiencia de combate real les da una ventaja sobre el resto de nosotros.",
  ui_story_1016_10160101_156_dialog_content = "Aunque la diferencia de edad no es muy amplia, la diferencia de experiencia es enorme.",
  ui_story_1016_10160101_157_dialog_content = "El otro equipo a tener en cuenta es el equipo de Yingel, ya que ella tiene Axelia y Anatoli a su lado",
  ui_story_1016_10160101_158_dialog_content = "Esos tres son los mejores guerreros de Illumina para su generación.",
  ui_story_1016_10160101_159_dialog_content = "Además de eso, tienen a su disposición todo el peso del conocimiento científico y tecnológico de Illumina. No se sabe cuán poderosos los hace eso.",
  ui_story_1016_10160101_160_dialog_content = "Uf... La ciencia y la tecnología no son exactamente nuestro punto fuerte.",
  ui_story_1016_10160101_161_dialog_content = "No podría estar más de acuerdo, por lo que debemos mantenernos fuera de su camino.",
  ui_story_1016_10160101_162_dialog_content = "Recuerda, hemos venido a Gannon City como invitados, así que debemos aceptar su forma de hacer las cosas.",
  ui_story_1016_10160101_163_dialog_content = "Tomemos esto como una valiosa experiencia de aprendizaje.",
  ui_story_1016_10160101_164_dialog_content = "Decir eso es una cosa, pero hacerlo no será tarea fácil.",
  ui_story_1016_10160101_165_dialog_content = "Al igual que todavía no has descubierto las calles de Gannon City a pesar de haber estado perdido durante tanto tiempo.",
  ui_story_1016_10160101_166_dialog_content = "¡¿P-Por qué me atacas de repente?!",
  ui_story_1016_10160101_167_dialog_content = "Porque quiero volver al cuartel, Capitán. ¿Cuánto tiempo antes de que finalmente puedas guiarnos en la dirección correcta?",
  ui_story_1016_10160101_168_dialog_content = "¡J-Solo dame un momento! ¡Casi lo he descubierto!",
  ui_story_1016_10160101_169_dialog_content = "Si giramos a la derecha aquí...",
  ui_story_1016_10160101_170_dialog_content = "<color=#e8d9bb>¡Wham!</color>",
  ui_story_1016_10160101_171_dialog_content = "<size=45>¡Urgh!</size>",
  ui_story_1016_10160101_172_dialog_content = "Mmm...",
  ui_story_1016_10160101_173_dialog_content = "¡Lo siento mucho! ¡Debería haber estado prestando más atención a la carretera!",
  ui_story_1016_10160101_174_dialog_content = "¿Estás bien?",
  ui_story_1016_10160101_175_dialog_content = "Estoy bien, y por favor no te culpes. La gente tiende a tropezarse conmigo bastante a menudo.",
  ui_story_1016_10160101_176_dialog_content = "¿Podrías pasarme mi bastón? Parece que no puedo encontrarlo.",
  ui_story_1016_10160101_177_dialog_content = "Por supuesto. Aquí tienes.",
  ui_story_1016_10160101_178_dialog_content = "Perdóname, pero... ¿estás ciego?",
  ui_story_1016_10160101_179_dialog_content = "Oh, mis disculpas por molestarte.",
  ui_story_1016_10160101_180_dialog_content = "Boohoo, ¡soy yo quien debería arrepentirse! ¡Nunca debí encontrarme contigo!",
  ui_story_1016_10160101_181_dialog_content = "¿Adónde vas? ¡Déjame acompañarte allí!",
  ui_story_1016_10160101_182_dialog_content = "Eso no será necesario, gracias. Sin embargo, estoy buscando a una niña con un traje de muñeca. ¿La has visto?",
  ui_story_1016_10160101_183_dialog_content = "Para nada...",
  ui_story_1016_10160101_184_dialog_content = "Entonces no te molestaré más. Puedo seguir buscando por mi cuenta.",
  ui_story_1016_10160101_185_dialog_content = "Ah, y por cierto... Yo también participo en el Ejercicio Militar Conjunto, al igual que ustedes tres.",
  ui_story_1016_10160101_186_dialog_content = "¿Ah?",
  ui_story_1016_10160101_187_dialog_content = "Mi nombre es Dysis. Espero verte en clase mañana.",
  ui_story_1016_10160101_188_dialog_content = "Nuestra misión es tener el mayor perfil posible, ¿entendido?",
  ui_story_1016_10160101_189_dialog_content = "No tenemos ningún interés en leer libros o jugar a los soldados. Estamos aquí para encontrar una manera de amplificar nuestro mensaje.",
  ui_story_1016_10160101_190_dialog_content = "¡Tenemos que advertir al mundo entero de la catástrofe inminente de Twilight!",
  ui_story_1016_10160101_191_dialog_content = "Ahora sé lo que realmente buscas, Leo.",
  ui_story_1016_10160101_192_dialog_content = "¿Es eso así? Entonces cuéntanos, si eres tan inteligente.",
  ui_story_1016_10160101_193_dialog_content = "Quieres tener la oportunidad de enfrentarte al Gran Mariscal.",
  ui_story_1016_10160101_194_dialog_content = "Jajajaja! ¡Así es! ¿Qué podría ser una mejor noticia que alguien golpeando Reinhardt ¿En batalla?",
  ui_story_1016_10160101_195_dialog_content = "Estás mordiendo más de lo que puedes masticar.",
  ui_story_1016_10160101_196_dialog_content = "¿De verdad lo crees?",
  ui_story_1016_10160101_197_dialog_content = "Ganar la competencia por el derecho a batirse en duelo con el Gran Mariscal no debería ser un desafío.",
  ui_story_1016_10160101_198_dialog_content = "Pero no creo que puedas vencerla en una pelea uno contra uno.",
  ui_story_1016_10160101_199_dialog_content = "Contundente como siempre, por lo que veo.",
  ui_story_1016_10160101_200_dialog_content = "El combate en solitario no es tu punto fuerte. No debería tener que recordártelo, ¿verdad?",
  ui_story_1016_10160101_201_dialog_content = "No, lo tengo perfectamente claro.",
  ui_story_1016_10160101_202_dialog_content = "Pero yo no soy el que va a enfrentar Reinhardt en la batalla, si tenemos éxito.",
  ui_story_1016_10160101_203_dialog_content = "!",
  ui_story_1016_10160101_204_dialog_content = "Así que por eso lo trajiste...",
  ui_story_1016_10160101_205_dialog_content = "No sé las posibilidades de Joseph de ganar.",
  ui_story_1016_10160101_206_dialog_content = "Pero estoy seguro de que nuestro mensaje se escuchará alto y claro.",
  ui_story_1016_10160101_207_dialog_content = "¿Escucha eso? Alguien está llorando.",
  ui_story_1016_10160101_208_dialog_content = "¿Ah?",
  ui_story_1016_10160101_209_dialog_content = "Solo cálmate y escucha atentamente.",
  ui_story_1016_10160101_210_dialog_content = "<size=30>*sollozando*</size>",
  ui_story_1016_10160101_211_dialog_content = "¡Estás en lo correcto!",
  ui_story_1016_10160101_212_dialog_content = "Que raro, el llanto de la persona no suena nada triste.",
  ui_story_1016_10160101_213_dialog_content = "Se está acercando. Deben estar caminando hacia nosotros.",
  ui_story_1016_10160101_214_dialog_content = "*Sollozo*",
  ui_story_1016_10160101_215_dialog_content = "¿Un demi-humano? Esa es una vista rara.",
  ui_story_1016_10160101_216_dialog_content = "¿Está todo bien? Te escuché llorar desde lejos.",
  ui_story_1016_10160101_217_dialog_content = "¿Eh? A-¿Me estás preguntando?",
  ui_story_1016_10160101_218_dialog_content = "Lo siento si te molestó.",
  ui_story_1016_10160101_219_dialog_content = "Es solo porque me duele mucho la cabeza. Es un viejo problema.",
  ui_story_1016_10160101_220_dialog_content = "Suena grave, si tus dolores de cabeza son lo suficientemente dolorosos como para hacerte llorar...",
  ui_story_1016_10160101_221_dialog_content = "Te vi en la estación de tren antes. También participas en el Ejercicio Militar Conjunto, ¿verdad?",
  ui_story_1016_10160101_222_dialog_content = "Sí. Mi nombre es feliz.",
  ui_story_1016_10160101_223_dialog_content = "¿De dónde eres?",
  ui_story_1016_10160101_224_dialog_content = "Umbratón.",
  ui_story_1016_10160101_225_dialog_content = "¿Cuántos de ustedes están ahí?",
  ui_story_1016_10160101_226_dialog_content = "Tres, incluyéndome a mí.",
  ui_story_1016_10160101_227_dialog_content = "Ahora, si puedo hacerte una pregunta, ¿has visto a una niña vestida de muñeca por aquí?",
  ui_story_1016_10160101_228_dialog_content = "Es mi compañera de equipo y parece haberse perdido cerca.",
  ui_story_1016_10160101_229_dialog_content = "No lo hemos hecho, lo siento. Eres el único otro participante que hemos visto hasta ahora.",
  ui_story_1016_10160101_230_dialog_content = "Veo. Bueno, si no tienes más preguntas para mí, debería continuar buscándola.",
  ui_story_1016_10160101_231_dialog_content = "Gracias por tu tiempo. Espero verte durante el entrenamiento.",
  ui_story_1016_10160101_232_dialog_content = "¡¿Qué te pasa, interrogándola así?!",
  ui_story_1016_10160101_233_dialog_content = "¿Interrogando? Sólo estaba reuniendo información, eso es todo.",
  ui_story_1016_10160101_234_dialog_content = "¿Sospechas de ella?",
  ui_story_1016_10160101_235_dialog_content = "No puedo decirlo con seguridad, al menos no ahora. Esperemos y veamos.",
  ui_story_1016_10160101_236_dialog_content = "Tengo una actualización para compartir con todos.",
  ui_story_1016_10160101_237_dialog_content = "Debemos ganar el campeonato a toda costa.",
  ui_story_1016_10160101_238_dialog_content = "¿Hay alguna pregunta?",
  ui_story_1016_10160101_239_dialog_content = "No.",
  ui_story_1016_10160101_240_dialog_content = "... ¿Son esos realmente los decretos del Comité?",
  ui_story_1016_10160101_241_dialog_content = "Sí.",
  ui_story_1016_10160101_242_dialog_content = "Entonces supongo que no tengo más preguntas.",
  ui_story_1016_10160101_243_dialog_content = "No hay una estrategia específica para la fase de aprendizaje del Ejercicio Militar Conjunto, así que solo asista a las lecciones con normalidad.",
  ui_story_1016_10160101_244_dialog_content = "Y recuerda mantener un perfil bajo, para evitar cualquier atención o altercados innecesarios.",
  ui_story_1016_10160101_245_dialog_content = "Nuestras órdenes son permanecer en secreto. Nadie fuera de esta sala debe saber acerca de nuestra misión.",
  ui_story_1016_10160101_246_dialog_content = "Entendido.",
  ui_story_1016_10160101_247_dialog_content = "Entendido.",
  ui_story_1016_10160101_248_dialog_content = "Eso es todo por ahora. Reunión aplazada.",
  ui_story_1016_10160101_249_dialog_content = "Bien, estoy empezando a sentirme cansado.",
  ui_story_1016_10160101_250_dialog_content = "Toma, te escoltaré de regreso a tu cámara de estasis.",
  ui_story_1016_10160101_251_dialog_content = "Anatoli, ¿podrías ayudarme a abrir la puerta?",
  ui_story_1016_10160101_252_dialog_content = "Seguro-",
  ui_story_1016_10160101_253_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_1016_10160101_254_dialog_content = "¡Ahhh!",
  ui_story_1016_10160101_255_dialog_content = "¡Alguien está afuera de la puerta!",
  ui_story_1016_10160101_256_dialog_content = "¡¿Quién está ahí?!",
  ui_story_1016_10160101_257_dialog_content = "¡Eso duele! ¡No abras las puertas así!",
  ui_story_1016_10160101_258_dialog_content = "¡Oh, simplemente genial! ¡Mira este enorme bulto en mi cabeza!",
  ui_story_1016_10160101_259_dialog_content = "...",
  ui_story_1016_10160101_260_dialog_content = "¿Es este niño un enemigo?",
  ui_story_1016_10160101_261_dialog_content = "H-Oye! ¡¿Qué pasa con esa mirada?!",
  ui_story_1016_10160101_262_dialog_content = "¡N-no los estaba escuchando a escondidas ni nada!",
  ui_story_1016_10160101_263_dialog_content = "No dijimos nada sobre que estuvieras escuchando a escondidas.",
  ui_story_1016_10160101_264_dialog_content = "Tú...",
  ui_story_1016_10160101_265_dialog_content = "¡Ahí estás, Minch! ¡Te he estado buscando por todas partes!",
  ui_story_1016_10160101_266_dialog_content = "¿Por qué te escapaste así? ¿No te advertí lo fácil que es perderse en Gannon City?",
  ui_story_1016_10160101_267_dialog_content = "¡Te tomó mucho tiempo, Merry!",
  ui_story_1016_10160101_268_dialog_content = "¿Ustedes dos se conocen? Podría ser...",
  ui_story_1016_10160101_269_dialog_content = "Pido disculpas si nuestro amigo le causó algún problema.",
  ui_story_1016_10160101_270_dialog_content = "Esta es nuestra primera vez en la ciudad de Gannon, y el diseño de la ciudad facilita que los recién llegados como nosotros se pierdan.",
  ui_story_1016_10160101_271_dialog_content = "¿Estamos... interrumpiendo algo?",
  ui_story_1016_10160101_272_dialog_content = "¡¿Por qué te disculpas, Dysis?! ¡Son los que me golpearon en la cara con la puerta!",
  ui_story_1016_10160101_273_dialog_content = "Déjalo ir, Minch. Deberías ser más respetuoso con nuestros nuevos conocidos.",
  ui_story_1016_10160101_274_dialog_content = "...",
  ui_story_1016_10160101_275_dialog_content = "Bueno, entonces, deberíamos irnos ahora.",
  ui_story_1016_10160101_276_dialog_content = "Sí, mientras aún recuerdo el camino de regreso.",
  ui_story_1016_10160101_277_dialog_content = "¡Hmph! ¡Hasta luego, idiotas!",
  ui_story_1016_10160101_278_dialog_content = "Esos tres son los participantes de Umbraton.",
  ui_story_1016_10160101_279_dialog_content = "¿Deberíamos realmente dejarlos ir así? Es posible que hayan escuchado nuestra conversación.",
  ui_story_1016_10160101_280_dialog_content = "Si realmente nos escucharon, encontraré una manera de resolver el asunto.",
  ui_story_1016_10160101_281_dialog_content = "Por ahora, regresemos y descansemos un poco.",
  ui_story_1016_10160101_282_dialog_content = "Todavía tenemos que prepararnos para la clase de mañana.",
  ui_story_1016_10160101_283_dialog_content = "<color=#e8d9bb>Pozo, pat, pozo, pat...</color>",
  ui_story_1016_10160101_284_dialog_content = "¿Se han ido...?",
  ui_story_1016_10160101_285_dialog_content = "Sí, el último grupo de soldados se ha ido.",
  ui_story_1016_10160101_286_dialog_content = "¿Cómo te sientes, Helios?",
  ui_story_1016_10160101_287_dialog_content = "Es sólo un rasguño... No te preocupes por mí.",
  ui_story_1016_10160101_288_dialog_content = "Yo... todavía puedo luchar.",
  ui_story_1016_10160101_289_dialog_content = "Pelear no nos llevará a ninguna parte en Gannon City, Helios. En el momento en que seamos descubiertos, todos los soldados de Illumina estarán disparando contra nosotros.",
  ui_story_1016_10160101_290_dialog_content = "La fuerza bruta no es la respuesta.",
  ui_story_1016_10160101_291_dialog_content = "Pero...",
  ui_story_1016_10160101_292_dialog_content = "Sopórtalo por ahora. En situaciones como estas, lo mejor para nosotros es mantener la calma.",
  ui_story_1016_10160101_293_dialog_content = "Solo tenemos que esperar un poco más.",
  ui_story_1016_10160101_294_dialog_content = "¿Qué estamos esperando exactamente?",
  ui_story_1016_10160101_295_dialog_content = "El <color=#FFB400>Fantasma</color>.",
  ui_story_1016_10160201_1_dialog_content = "<anim type=Shake>Bostezo-</anim> No pude dormir nada anoche.",
  ui_story_1016_10160201_2_dialog_content = "Toda esta ciudad huele a fábrica.",
  ui_story_1016_10160201_3_dialog_content = "¡¿Un laboratorio?! ¡¿Qué planeas hacer con nosotros aquí?!",
  ui_story_1016_10160201_4_dialog_content = "¡No tengo intención de ser una rata de laboratorio para Illumina!",
  ui_story_1016_10160201_5_dialog_content = "Wow, qué lugar tan familiar.",
  ui_story_1016_10160201_6_dialog_content = "Creo que sé lo que estamos haciendo aquí hoy.",
  ui_story_1016_10160201_7_dialog_content = "<color=#e8d9bb>Anillo-</color>",
  ui_story_1016_10160201_8_dialog_content = "¡Demasiado fuerte, DEMASIADO FUERTE! ¡Cállense todos!",
  ui_story_1016_10160201_9_dialog_content = "Mi nombre es Gronru, y seré su instructor en todas sus clases relacionadas con la investigación.",
  ui_story_1016_10160201_10_dialog_content = "Obviamente, a la mayoría de ustedes no les importa un bledo la ciencia, ¡pero no se preocupen! ¡Mis clases son cualquier cosa menos aburridas!",
  ui_story_1016_10160201_11_dialog_content = "Entonces, para nuestra primera lección, preparé algo muy divertido para todos ustedes... ¡Nuestro último y mejor invento!",
  ui_story_1016_10160201_12_dialog_content = "Deleita tus ojos con el nuevo dispositivo de entrenamiento militar de Illumina:",
  ui_story_1016_10160201_13_dialog_content = "<color=#FFB400>El simulador de batalla</color>!",
  ui_story_1016_10160201_14_dialog_content = "¡Lo sabía!",
  ui_story_1016_10160201_15_dialog_content = "¿Un casco? ¿Cómo exactamente se supone que esto nos entrena?",
  ui_story_1016_10160201_16_dialog_content = "¿Estás bromeando? ¡Este pequeño artilugio funciona mejor que cualquier espada o arma!",
  ui_story_1016_10160201_17_dialog_content = "Dime, ¿qué crees que es lo más difícil de entrenar para un soldado?",
  ui_story_1016_10160201_18_dialog_content = "¿Es la fuerza física? ¿O tal vez Luminática?",
  ui_story_1016_10160201_19_dialog_content = "Es experiencia en combate.",
  ui_story_1016_10160201_20_dialog_content = "¡Bingo! ¡Lo más difícil de entrenar para un soldado es su experiencia en combate!",
  ui_story_1016_10160201_21_dialog_content = "Durante mucho tiempo, la única forma de obtener ese tipo de experiencia fue luchando y sobreviviendo en un combate real.",
  ui_story_1016_10160201_22_dialog_content = "Desafortunadamente, la guerra es brutal, y no todos los soldados tienen la suerte de salir vivos y bien de ella.",
  ui_story_1016_10160201_23_dialog_content = "¡A menos, por supuesto, que hayan experimentado toneladas y toneladas de batallas simuladas!",
  ui_story_1016_10160201_24_dialog_content = "Pero, ¿cómo se puede simular una guerra realista...?",
  ui_story_1016_10160201_25_dialog_content = "¡Esta es una gran pregunta, considerando que eso es lo que cubriremos en la lección de hoy!",
  ui_story_1016_10160201_26_dialog_content = "Cada uno de ustedes recibirá un dispositivo como el que tengo ahora.",
  ui_story_1016_10160201_27_dialog_content = "Después de ponérselo, todos ustedes serán enviados a un campo de batalla virtual al mismo tiempo.",
  ui_story_1016_10160201_28_dialog_content = "Una vez allí, podrás usar Luminatics y todo tipo de armas como lo harías normalmente en la vida real, y tus oponentes serán nuestros viejos amigos, los Eclipsites.",
  ui_story_1016_10160201_29_dialog_content = "¡Trátalos como siempre y no te detengas hasta que estés derrotado!",
  ui_story_1016_10160201_30_dialog_content = "¡Jajaja! ¡Esto empieza a sonar interesante!",
  ui_story_1016_10160201_31_dialog_content = "¡Veamos qué tan bien estos cascos pueden simular una guerra real!",
  ui_story_1016_10160201_32_dialog_content = "¡Genial, parece que todos están ansiosos por ir!",
  ui_story_1016_10160201_33_dialog_content = "Luego, sin más preámbulos, entregaré los cascos para que podamos comenzar con la simulación de entrenamiento de combate de hoy.",
  ui_story_1016_10160201_34_dialog_content = "Durante la simulación, su desempeño también será monitoreado y calificado. Puede realizar un seguimiento de sus estadísticas en la pantalla cercana.",
  ui_story_1016_10160201_35_dialog_content = "Los números no mienten, ¡así que haz tu mejor esfuerzo para acumular puntos y alcanzar la cima del marcador!",
  ui_story_1016_10160201_36_dialog_content = "<color=#e8d9bb>Has entrado en la simulación de combate.</color>",
  ui_story_1016_10160201_37_dialog_content = "Parece que esto será como la última vez.",
  ui_story_1016_10160201_38_dialog_content = "Dónde están Vice y Carleen? ¿Aún no se han puesto los cascos?",
  ui_story_1016_10160201_39_dialog_content = "Espera, esto es...",
  ui_story_1016_10160201_40_dialog_content = "¡Guau! ¡Cargué casi al instante!",
  ui_story_1016_10160201_41_dialog_content = "Parece que han realizado muchas mejoras en Battlefield Simulator. ¡Mi cuerpo apenas puede notar la diferencia entre la simulación y la vida real!",
  ui_story_1016_10160201_42_dialog_content = "Supongo que cuanto más realista es la simulación de combate, más se activan nuestros instintos de supervivencia.",
  ui_story_1016_10160201_43_dialog_content = "Esto parece la línea defensiva de Illumina, ¿no?",
  ui_story_1016_10160201_44_dialog_content = "<color=#e8d9bb>Todos los participantes del ejercicio se han cargado con éxito en la simulación.</color>",
  ui_story_1016_10160201_45_dialog_content = "<color=#e8d9bb>Advertencia: La batalla que estás a punto de experimentar es una recreación de una batalla real en Illumina.</color>",
  ui_story_1016_10160201_46_dialog_content = "<color=#e8d9bb>En esta batalla, oleadas de Eclipsites atravesaron con éxito la línea defensiva de la Federación, provocando numerosas bajas.</color>",
  ui_story_1016_10160201_47_dialog_content = "<color=#e8d9bb>Para evaluar mejor las capacidades de combate de los participantes, la escala de la simulación se ha reducido a un nivel que puede ser manejado por un escuadrón de tres personas.</color>",
  ui_story_1016_10160201_48_dialog_content = "<color=#e8d9bb>Cada equipo ha sido colocado en puntos aleatorios a lo largo del campo de batalla. May la suerte este a tu favor.</color>",
  ui_story_1016_10160201_49_dialog_content = "<color=#e8d9bb>Que comience la batalla.</color>",
  ui_story_1016_10160201_50_dialog_content = "Así que todos han sido colocados en diferentes áreas, ¿eh?",
  ui_story_1016_10160201_51_dialog_content = "Presumiblemente para evitar que los equipos interfieran entre sí durante la batalla, sí.",
  ui_story_1016_10160201_52_dialog_content = "El sistema dijo que esto era una simulación de una batalla real de Illumina. Ayudaría si supiéramos más sobre lo que sucedió en la batalla original.",
  ui_story_1016_10160201_53_dialog_content = "Sabes algo al respecto, Vice?",
  ui_story_1016_10160201_54_dialog_content = "Realmente no lo hago. Han ocurrido demasiadas batallas en las fronteras para contarlas, y hemos recibido tantos informes de Eclipsites rompiendo nuestras defensas.",
  ui_story_1016_10160201_55_dialog_content = "Si la historia sirve de indicación, así es como se ven nuestras líneas defensivas la mayor parte del tiempo.",
  ui_story_1016_10160201_56_dialog_content = "Un constante estado de batalla...",
  ui_story_1016_10160201_57_dialog_content = "¡Veo eclipses!",
  ui_story_1016_10160201_58_dialog_content = "Hay tantos de ellos... ¿Podemos realmente manejar esto solo nosotros tres?",
  ui_story_1016_10160201_59_dialog_content = "Espera... El sistema dijo que los Eclipsites lograron atravesar la línea defensiva militar.",
  ui_story_1016_10160201_60_dialog_content = "¿Significa esto que aunque la simulación se haya reducido, no tenemos forma de cambiar el resultado de esta batalla?",
  ui_story_1016_10160201_61_dialog_content = "Esta sensación de impotencia... Así debe ser como se sintieron esos soldados de Illumina cuando vieron todos estos eclipses.",
  ui_story_1016_10160201_62_dialog_content = "Sí, pero menos mal que esto es solo una simulación.",
  ui_story_1016_10160201_63_dialog_content = "¡Ahora démosle todo lo que tenemos!",
  ui_story_1016_10160201_64_dialog_content = "¡Acordado! ¡Hagámoslo!",
  ui_story_1016_10160202_1_dialog_content = "Carleen! ¡Tienes que retirarte ahora mismo!",
  ui_story_1016_10160202_2_dialog_content = "Quiero, pero...",
  ui_story_1016_10160202_3_dialog_content = "Parece que cuantos más eclipses superamos, más comienzan a aparecer.",
  ui_story_1016_10160202_4_dialog_content = "Tienes razón. Es como si estuvieran enfocándose en nuestra ubicación exacta.",
  ui_story_1016_10160202_5_dialog_content = "Si no salimos de aquí enseguida, nos van a invadir...",
  ui_story_1016_10160202_6_dialog_content = "¿Mmm? Dama Carleen!",
  ui_story_1016_10160202_7_dialog_content = "Beretta? ¡¿Qué estás haciendo aquí?!",
  ui_story_1016_10160202_8_dialog_content = "M-Mi equipo fue barrido por los Eclipsites.",
  ui_story_1016_10160202_9_dialog_content = "No tuve más remedio que mantenerme firme durante el mayor tiempo posible, pero los Eclipsites me obligaban a retroceder más y más.",
  ui_story_1016_10160202_10_dialog_content = "Me encontré con varios participantes durante la interminable escaramuza...",
  ui_story_1016_10160202_11_dialog_content = "Basta de hablar. Enfócate en el enemigo.",
  ui_story_1016_10160202_12_dialog_content = "¡Me estoy centrando en ellos! ¡No necesito que me lo recuerdes!",
  ui_story_1016_10160202_13_dialog_content = "¡Anatoli también está aquí! Estás en el equipo de Yingel, ¿verdad?",
  ui_story_1016_10160202_14_dialog_content = "¿Ella y tu otro compañero de equipo también fueron barridos?",
  ui_story_1016_10160202_15_dialog_content = "Sí, pero solo porque alguien interfirió en nuestra batalla.",
  ui_story_1016_10160202_16_dialog_content = "¡Ey! ¿A qué te refieres con interferir? Estamos del mismo lado, ¿no?",
  ui_story_1016_10160202_17_dialog_content = "¿De qué otra manera lo llamaría cuando nos abrumaste así?",
  ui_story_1016_10160202_18_dialog_content = "¡Tsk!",
  ui_story_1016_10160202_19_dialog_content = "No creo que nos hayamos conocido antes. Estas con...",
  ui_story_1016_10160202_20_dialog_content = "Ahora no es el momento, PlayerName! ¡Prácticamente nos estamos ahogando en eclipses!",
  ui_story_1016_10160202_21_dialog_content = "¡A este ritmo, no podremos aguantar mucho más!",
  ui_story_1016_10160202_22_dialog_content = "Tienes razón, sus números siguen multiplicándose...",
  ui_story_1016_10160202_23_dialog_content = "Beretta! Anatoli! Y, eh, ¡tú allí!",
  ui_story_1016_10160202_24_dialog_content = "<size=45>Mi nombre es Minch!!!</size>",
  ui_story_1016_10160202_25_dialog_content = "¡Tenemos que hacer equipo! ¡Es nuestra única forma de escapar del medio de toda esta lucha!",
  ui_story_1016_10160202_26_dialog_content = "Me temo que es demasiado tarde... Realmente no puedo pensar en nada ahora...",
  ui_story_1016_10160202_27_dialog_content = "Urgh—!",
  ui_story_1016_10160202_28_dialog_content = "<size=45>Beretta!!!</size>",
  ui_story_1016_10160202_29_dialog_content = "Oh, no, ahora tenemos que enfrentarnos a todos los Eclipsites de su equipo nosotros mismos.",
  ui_story_1016_10160202_30_dialog_content = "¡Ahhhh! ¡Vienen directamente hacia nosotros! ¡¿Qué debemos hacer?!",
  ui_story_1016_10160202_31_dialog_content = "Sólo tenemos que seguir manteniendo la línea...",
  ui_story_1016_10160202_32_dialog_content = "¡Todos, intenten atravesar a los enemigos detrás de ustedes! ¡Parece que hay menos de ellos allí!",
  ui_story_1016_10160202_34_dialog_content = "¡Cuidado, PlayerName!",
  ui_story_1016_10160202_35_dialog_content = "Puaj-!",
  ui_story_1016_10160202_36_dialog_content = "¡Detrás de ti! Respuesta rápida-",
  ui_story_1016_10160202_37_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1016_10160202_38_dialog_content = "<color=#e8d9bb>Has salido de la simulación de combate.</color>",
  ui_story_1016_10160202_39_dialog_content = "Uf... Estoy fuera, ¿eh?",
  ui_story_1016_10160202_40_dialog_content = "Incluso morir en Battle Simulator se siente dolorosamente real...",
  ui_story_1016_10160202_41_dialog_content = "Me pregunto cómo Vice y Carleen están aguantando?",
  ui_story_1016_10160202_42_dialog_content = "Ah, parece que nos mataron a todos.",
  ui_story_1016_10160202_43_dialog_content = "En efecto. Contra tantos Eclipsites, nunca hubo ninguna posibilidad de victoria.",
  ui_story_1016_10160202_44_dialog_content = "Jaja, también te atraparon a ti. ¿Cómo te sientes acerca de esta simulación?",
  ui_story_1016_10160202_45_dialog_content = "Se sentía sorprendentemente real. Gronru tenía razón, esta es la herramienta definitiva para proporcionar a los soldados una experiencia de combate real.",
  ui_story_1016_10160202_46_dialog_content = "Una batalla tensa como esa es bastante difícil de experimentar en el mundo real, y mucho menos de sobrevivir.",
  ui_story_1016_10160202_47_dialog_content = "En serio. Si realmente hubiéramos luchado en esa batalla, no hay forma de que todos nosotros hubiéramos regresado con vida.",
  ui_story_1016_10160202_48_dialog_content = "¿Yo se, verdad? Después de esa batalla, siento que entiendo mucho mejor la gravedad de la situación de Illumina.",
  ui_story_1016_10160202_49_dialog_content = "Supongo que algunos soldados... No tienen más remedio que pelear una batalla perdida.",
  ui_story_1016_10160202_50_dialog_content = "Sí...",
  ui_story_1016_10160202_51_dialog_content = "¡Muy bien, clase! Para aquellos de ustedes que están fuera de la simulación, dirija su atención aquí.",
  ui_story_1016_10160202_52_dialog_content = "Estoy seguro de que la batalla y los simuladores dejaron una impresión duradera en todos y cada uno de ustedes.",
  ui_story_1016_10160202_53_dialog_content = "¡Así que aquí hay una encuesta de experiencia del usuario para que compartas tus comentarios sobre Battle Simulator!",
  ui_story_1016_10160202_54_dialog_content = "¡Nadie se va hasta que todos hayan escrito algo!",
  ui_story_1016_10160202_55_dialog_content = "Eh... ¿Una encuesta?",
  ui_story_1016_10160202_56_dialog_content = "Instructor Gronru? ¿Estás seguro de que no nos estás usando solo para hacer una prueba?",
  ui_story_1016_10160202_57_dialog_content = "¿Qué? ¡¿Cómo puedes decir algo así?!",
  ui_story_1016_10160202_58_dialog_content = "¡Tus comentarios son muy importantes para mejorar las funciones de Battle Simulator!",
  ui_story_1016_10160202_59_dialog_content = "Todo el mundo se beneficiaría de eso, ¿no crees?",
  ui_story_1016_10160202_60_dialog_content = "Si, claro...",
  ui_story_1016_10160202_61_dialog_content = "<color=#e8d9bb>Veinte minutos después</color>",
  ui_story_1016_10160202_62_dialog_content = "¡Finalmente! Esa fue la encuesta más larga que he tenido que completar...",
  ui_story_1016_10160202_63_dialog_content = "¡Lo sé! ¡Me duele la mano de tanto escribir!",
  ui_story_1016_10160202_64_dialog_content = "La encuesta nos pide que proporcionemos nuestros puntajes de la simulación de batalla. ¿Alguien sabe cuántos puntos ganamos?",
  ui_story_1016_10160202_65_dialog_content = "Ninguna pista. Ni siquiera sé si lo hicimos bien o no.",
  ui_story_1016_10160202_66_dialog_content = "Instructor Gronru, ¿dónde podemos ver nuestras puntuaciones?",
  ui_story_1016_10160202_67_dialog_content = "¡Correcto! Tendrás que esperar un poco más.",
  ui_story_1016_10160202_68_dialog_content = "Todavía hay algunos participantes luchando dentro de la simulación.",
  ui_story_1016_10160202_69_dialog_content = "¿Siguen ahí? Pero ha pasado tanto tiempo ahora...",
  ui_story_1016_10160202_70_dialog_content = "<color=#e8d9bb>La simulación de combate ahora está completa.</color>",
  ui_story_1016_10160202_71_dialog_content = "<color=#e8d9bb>Calculando todos los resultados del combate—</color>",
  ui_story_1016_10160202_72_dialog_content = "<color=#e8d9bb>Cálculos completos. Los aurorianos ganan.</color>",
  ui_story_1016_10160202_73_dialog_content = "¿Qué? ¡¿Ganamos?!",
  ui_story_1016_10160202_74_dialog_content = "<size=45>Ganaron?!?</size>",
  ui_story_1016_10160202_75_dialog_content = "¡Imposible! ¡Nadie ha sido capaz de superar esta etapa...!",
  ui_story_1016_10160202_76_dialog_content = "¿Quién fue el último en salir de la simulación?",
  ui_story_1016_10160202_77_dialog_content = "¡Uf! Este casco se vuelve muy incómodo si lo usas demasiado tiempo.",
  ui_story_1016_10160202_78_dialog_content = "¡Esa simulación se sintió bastante real! ¡No estuvo nada mal si me preguntas!",
  ui_story_1016_10160202_79_dialog_content = "Supongo que estar constantemente envuelto en la guerra le ha dado a Illumina una idea dolorosamente clara de cómo es el combate.",
  ui_story_1016_10160202_80_dialog_content = "Pero una experiencia demasiado realista también tiene sus inconvenientes.",
  ui_story_1016_10160202_81_dialog_content = "Si sabes cómo progresó la pelea original, puedes predecir cada cambio en el campo de batalla.",
  ui_story_1016_10160202_82_dialog_content = "Eso, a su vez, reduce drásticamente la dificultad de la simulación.",
  ui_story_1016_10160202_83_dialog_content = "¡¿P-Pensó que era demasiado fácil?!",
  ui_story_1016_10160202_84_dialog_content = "No me gusta el entorno de simulación.",
  ui_story_1016_10160202_85_dialog_content = "Por muy sinceras que fueran mis invocaciones, sólo me respondió una luz artificial.",
  ui_story_1016_10160202_86_dialog_content = "¡No seas tan serio, José! ¡Piensa en ello como un juego!",
  ui_story_1016_10160202_87_dialog_content = "Oye, mira, ¡nuestros puntajes finalmente están disponibles!",
  ui_story_1016_10160202_88_dialog_content = "El equipo de Leo... Marcaron tan alto...",
  ui_story_1016_10160202_89_dialog_content = "Nadie se acercó siquiera...",
  ui_story_1016_10160202_90_dialog_content = "Estábamos luchando en el mismo campo de batalla, ¿no?",
  ui_story_1016_10160202_91_dialog_content = "¿Cómo lograron superar todos esos eclipses...?",
  ui_story_1016_10160202_92_dialog_content = "Vi la forma en que lo hicieron.",
  ui_story_1016_10160202_93_dialog_content = "Fueron ellos... Ellos son los que trajeron todos esos Eclipsites sobre nuestras cabezas...",
  ui_story_1016_10160202_94_dialog_content = "¡¿Qué?!",
  ui_story_1016_10160202_95_dialog_content = "¿Pero cómo? ¿Cómo pudieron haber hecho algo así?",
  ui_story_1016_10160202_96_dialog_content = "Es cierto. Sabían cómo atraer a los Eclipsites entrantes para que los siguieran hasta que estuvieran todos reunidos en un solo lugar.",
  ui_story_1016_10160202_97_dialog_content = "Después de eso, usaron el terreno a su favor y obligaron a los Eclipsites a luchar contra ellos en estrechos corredores. Una vez que no pudieron confiar en sus números para ganar, el equipo de Leo los eliminó fácilmente.",
  ui_story_1016_10160202_98_dialog_content = "Los Eclipsites no eran diferentes a un rebaño de ovejas, caminando una por una hacia una guarida de lobos hambrientos...",
  ui_story_1016_10160202_99_dialog_content = "Pastoreando Eclipsitos... No tenía ni idea de que se pudiera hacer...",
  ui_story_1016_10160202_100_dialog_content = "No fue una estrategia particularmente inteligente, pero cuando te enfrentas a decenas de enemigos como ese, todo lo que puedes hacer es devanarte los sesos para encontrar una solución.",
  ui_story_1016_10160202_101_dialog_content = "Tampoco encontrarás la respuesta en un libro. Ningún libro puede decirle verdaderamente cómo ganar una batalla imposible de ganar.",
  ui_story_1016_10160202_102_dialog_content = "Su única opción es idear un plan y ponerlo en práctica, sin importar cuán ridículo pueda parecer.",
  ui_story_1016_10160202_103_dialog_content = "Y si tienes la suerte de sobrevivir una y otra vez gracias a esas ridículas estrategias, significa que has descubierto tu propia manera de salir victorioso en la batalla.",
  ui_story_1016_10160202_104_dialog_content = "(¡Así es! Cuando vi por primera vez Leo, usó los métodos menos convencionales para pelear sus batallas).",
  ui_story_1016_10160202_105_dialog_content = "(No creo que ninguno de nosotros pueda compararse con la gente de Crepúsculo cuando se trata de improvisar en el campo de batalla).",
  ui_story_1016_10160202_106_dialog_content = "Heh, cosas bastante poderosas allí, Leo! ¡Ustedes lograron aturdir a toda la clase en silencio!",
  ui_story_1016_10160202_107_dialog_content = "¿Alguno de ustedes está tomando notas? ¿O estás demasiado ocupado mirando el marcador?",
  ui_story_1016_10160202_108_dialog_content = "Honestamente, ¡es como si fueran un grupo de niños que acaban de ver un arma por primera vez!",
  ui_story_1016_10160301_1_dialog_content = "<color=#e8d9bb>Una semana más tarde</color>",
  ui_story_1016_10160301_2_dialog_content = "¿Eh? ¿Qué estoy haciendo en las oficinas? ¿Hice un giro equivocado en alguna parte?",
  ui_story_1016_10160301_3_dialog_content = "Estoy bastante seguro de que el salón de clases es...",
  ui_story_1016_10160301_4_dialog_content = "¿Estás dando un paseo, PlayerName?",
  ui_story_1016_10160301_5_dialog_content = "La clase empieza pronto, ya sabes.",
  ui_story_1016_10160301_6_dialog_content = "Anatoli! ¡Oh, gracias a Dios!",
  ui_story_1016_10160301_7_dialog_content = "¿Sabes cómo llegar al salón de clases desde aquí? Llevo tanto tiempo caminando por estos pasillos que me estoy empezando a marear, jejeje.",
  ui_story_1016_10160301_8_dialog_content = "Veo. Sígueme.",
  ui_story_1016_10160301_9_dialog_content = "Tienes suerte de que te haya encontrado, o quizás hayas perdido algunos créditos por llegar tarde.",
  ui_story_1016_10160301_10_dialog_content = "Todo el mundo ha estado hablando de créditos hoy. ¿Qué son exactamente?",
  ui_story_1016_10160301_11_dialog_content = "¿Quieres decir que no has mirado el manual que te dieron ayer?",
  ui_story_1016_10160301_12_dialog_content = "No, todavía no. Gronru me arrastró para hacer un trabajo de depuración en Soroz ayer.",
  ui_story_1016_10160301_13_dialog_content = "Entonces déjame darte una breve explicación.",
  ui_story_1016_10160301_14_dialog_content = "A partir de hoy, el desempeño de todos en sus clases se registrará como una cierta cantidad de créditos.",
  ui_story_1016_10160301_15_dialog_content = "Cada participante seguirá acumulando créditos hasta el final de la fase de aprendizaje.",
  ui_story_1016_10160301_16_dialog_content = "El uso más obvio de estos créditos es para juzgar su habilidad. Sin embargo, también sirven para otro propósito.",
  ui_story_1016_10160301_17_dialog_content = "Tus créditos también te ayudarán durante la evaluación.",
  ui_story_1016_10160301_18_dialog_content = "¿Cómo es eso?",
  ui_story_1016_10160301_19_dialog_content = "Antes del comienzo de la fase de evaluación, se le permitirá intercambiar sus créditos por ciertos elementos, lo que puede aumentar su poder general.",
  ui_story_1016_10160301_20_dialog_content = "Cuantos más créditos gane, más apoyo podrá obtener.",
  ui_story_1016_10160301_21_dialog_content = "Por esta razón, todos esperan obtener tantos créditos como sea posible durante sus clases.",
  ui_story_1016_10160301_22_dialog_content = "¡No es de extrañar que todos hayan sido tan competitivos últimamente!",
  ui_story_1016_10160301_23_dialog_content = "Así es. Tendrás que tomarte las cosas más en serio si quieres tener alguna esperanza de ganar aquí.",
  ui_story_1016_10160301_24_dialog_content = "Parece que lo hicimos justo a tiempo.",
  ui_story_1016_10160301_25_dialog_content = "¿Memorizaste el camino aquí esta vez?",
  ui_story_1016_10160301_26_dialog_content = "Jaja, ¡espero que sí!",
  ui_story_1016_10160301_27_dialog_content = "Entonces, ¿qué estamos aprendiendo hoy?",
  ui_story_1016_10160301_28_dialog_content = "Estrategias ofensivas en combate real.",
  ui_story_1016_10160301_29_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_1016_10160301_30_dialog_content = "¡Ey! ¡Ustedes dos allí!",
  ui_story_1016_10160301_31_dialog_content = "¡Veinte segundos más y habrías llegado tarde!",
  ui_story_1016_10160301_32_dialog_content = "Eso estuvo cerca...",
  ui_story_1016_10160301_33_dialog_content = "Muy bien, ahora que los estudiantes más lentos finalmente están aquí, podemos comenzar nuestra lección.",
  ui_story_1016_10160301_34_dialog_content = "Mi nombre es Wrath. Soy el Capitán de la Legión de Guardias de Illumina, así como su instructor por hoy.",
  ui_story_1016_10160301_35_dialog_content = "Y el tema de la clase de hoy es muy simple: ¡luchar!",
  ui_story_1016_10160301_36_dialog_content = "¿Lucha?",
  ui_story_1016_10160301_37_dialog_content = "Ahora probablemente todos estén pensando, \"¿Luchar? ¿Qué podemos aprender de la pelea?\"",
  ui_story_1016_10160301_38_dialog_content = "Sé que todos los que están aquí tienen algún tipo de confianza en sus habilidades de lucha.",
  ui_story_1016_10160301_39_dialog_content = "Sin embargo, estoy seguro de que muchos de vosotros también sois holgazanes a la hora de luchar.",
  ui_story_1016_10160301_40_dialog_content = "¡Lo que estoy a punto de enseñarte no es cómo ganar sino cómo lograr la victoria perfecta!",
  ui_story_1016_10160301_41_dialog_content = "En una pelea ganable, terminar las cosas rápidamente te ayudará a conservar tu fuerza para la próxima batalla.",
  ui_story_1016_10160301_42_dialog_content = "La victoria no siempre es fácil. Cada acción que conduce a ella debe ejecutarse sin problemas.",
  ui_story_1016_10160301_43_dialog_content = "Supongo que tiene sentido...",
  ui_story_1016_10160301_44_dialog_content = "No creo haber recibido ningún entrenamiento de combate que se centre específicamente en la eficiencia.",
  ui_story_1016_10160301_45_dialog_content = "Tiene razón, aunque hacer todo a la perfección parece un poco irreal.",
  ui_story_1016_10160301_46_dialog_content = "¿Es capaz de desempeñarse a un nivel perfecto, Instructor? Wrath?",
  ui_story_1016_10160301_47_dialog_content = "¿Estás dudando de mí, punk?",
  ui_story_1016_10160301_48_dialog_content = "En absoluto, solo me preocupa no poder aprender nada práctico.",
  ui_story_1016_10160301_49_dialog_content = "Tch. Estoy más preocupado de que no puedas soportar mi entrenamiento.",
  ui_story_1016_10160301_50_dialog_content = "Basta de charlas triviales. ¡Reúnanse con sus grupos, todos ustedes!",
  ui_story_1016_10160301_51_dialog_content = "Hoy nos centraremos en el combate real y en la clase de hoy te enfrentarás a soldados Illumina altamente capacitados.",
  ui_story_1016_10160301_52_dialog_content = "¡Primer grupo, prepárense!",
  ui_story_1016_10160301_53_dialog_content = "<size=45>¡Sí, señora!</size>",
  ui_story_1016_10160301_54_dialog_content = "Démosles a estos estudiantes un saludo Illumina adecuado.",
  ui_story_1016_10160301_55_dialog_content = "<size=45>¡Sí, señora!</size>",
  ui_story_1016_10160301_56_dialog_content = "Y asegúrate de darle una bienvenida especialmente cálida a ese chico caballero de Lumopolis.",
  ui_story_1016_10160301_57_dialog_content = "Si eso todavía no es suficiente para ti, ¡no dudes en venir a verme después de clase para una tutoría individual!",
  ui_story_1016_10160301_58_dialog_content = "Creo que me centraré un poco más en la lección de hoy.",
  ui_story_1016_10160301_59_dialog_content = "Necesitaremos todos los créditos que podamos conseguir, ¿verdad?",
  ui_story_1016_10160301_60_dialog_content = "Así es. Esta es nuestra primera oportunidad de obtener créditos, ¡así que hagamos lo mejor que podamos!",
  ui_story_1016_10160301_61_dialog_content = "Qué tengo que hacer, Yingel?",
  ui_story_1016_10160301_62_dialog_content = "Solo tómalo con calma por ahora.",
  ui_story_1016_10160301_63_dialog_content = "<size=32>¿Soy solo yo... o estos estudiantes se ven un poco aterradores...?</size>",
  ui_story_1016_10160301_64_dialog_content = "<size=32>Estoy ahí contigo...</size>",
  ui_story_1016_10160401_1_dialog_content = "<color=#e8d9bb>Un mes después</color>",
  ui_story_1016_10160401_2_dialog_content = "Muy bien, eso servirá para la lección de hoy.",
  ui_story_1016_10160401_3_dialog_content = "Clase perdida.",
  ui_story_1016_10160401_4_dialog_content = "Camino a seguir, PlayerName! ¡Obtuvimos muchos créditos hoy!",
  ui_story_1016_10160401_5_dialog_content = "Sí, pero no es fácil cuando todos los demás luchan por hacer lo mismo. Estoy agotado.",
  ui_story_1016_10160401_6_dialog_content = "Ahora que nos acercamos al final de la fase de aprendizaje de lecciones, es natural que la competencia se haya vuelto tan feroz.",
  ui_story_1016_10160401_7_dialog_content = "¿Has visto las clasificaciones de hoy?",
  ui_story_1016_10160401_8_dialog_content = "Aún no. ¿Dónde estamos en la lista?",
  ui_story_1016_10160401_9_dialog_content = "Tercer lugar.",
  ui_story_1016_10160401_10_dialog_content = "¡Guau! ¡Subimos del cuarto!",
  ui_story_1016_10160401_11_dialog_content = "¡Las cosas están mejorando! ¿Cómo van el primer y segundo lugar?",
  ui_story_1016_10160401_12_dialog_content = "Equipo Leo está muy por delante de todos los demás en primer lugar. No hay sorpresas allí.",
  ui_story_1016_10160401_13_dialog_content = "De hecho... me temo que ningún equipo será capaz de cerrar la brecha antes del comienzo de la siguiente fase.",
  ui_story_1016_10160401_14_dialog_content = "Así que todavía están bien a la cabeza...",
  ui_story_1016_10160401_15_dialog_content = "En segundo lugar está el Equipo Yingel, aunque fue solo recientemente que comenzaron a mostrar sus talentos.",
  ui_story_1016_10160401_16_dialog_content = "Su equipo no tiene deficiencias obvias y hasta ahora se ha desempeñado bien en todas las categorías, lo que les ha asegurado un lugar en la clasificación.",
  ui_story_1016_10160401_17_dialog_content = "¿A qué distancia estamos nosotros de ellos?",
  ui_story_1016_10160401_18_dialog_content = "Aproximadamente la mitad de lo lejos que están detrás del equipo Leo?",
  ui_story_1016_10160401_19_dialog_content = "Parece que están bastante adelantados, entonces...",
  ui_story_1016_10160401_20_dialog_content = "El desempeño de Yingel en clase ha sido sobresaliente hasta el momento. Superarla en este aspecto sería difícil, de hecho.",
  ui_story_1016_10160401_21_dialog_content = "Pero fuera del aula es una historia completamente diferente.",
  ui_story_1016_10160401_22_dialog_content = "fuera del aula?",
  ui_story_1016_10160401_23_dialog_content = "Ayer, vi a varios equipos realizando sesiones de entrenamiento extracurriculares por su cuenta.",
  ui_story_1016_10160401_24_dialog_content = "Posteriormente, presentaron los resultados de su formación a los instructores a cambio de créditos.",
  ui_story_1016_10160401_25_dialog_content = "¿Qué? ¡No sabía que podíamos hacer eso!",
  ui_story_1016_10160401_26_dialog_content = "En efecto. Parece que los organizadores de este Ejercicio Militar Conjunto están poniendo mucho énfasis en el entrenamiento de todos nosotros.",
  ui_story_1016_10160401_27_dialog_content = "Y aunque este método no ofrece muchos créditos, pueden acumularse con el tiempo.",
  ui_story_1016_10160401_28_dialog_content = "Esta puede ser nuestra forma de superar al Equipo Yingel.",
  ui_story_1016_10160401_29_dialog_content = "¡Sí! ¡Pienso que es una idea genial!",
  ui_story_1016_10160401_30_dialog_content = "Seguro que ustedes dos están entusiasmados. ¡A este ritmo, estaremos compitiendo con los demás cada hora del día!",
  ui_story_1016_10160401_31_dialog_content = "Bueno, vamos a echar un vistazo a la programación.",
  ui_story_1016_10160401_32_dialog_content = "Necesitamos planificar las cosas cuidadosamente si queremos maximizar nuestros créditos.",
  ui_story_1016_10160401_33_dialog_content = "<color=#e8d9bb>Al día siguiente, en el salón de clases.</color>",
  ui_story_1016_10160401_34_dialog_content = "Más y más participantes se quedan atrás después de que termina la clase.",
  ui_story_1016_10160401_35_dialog_content = "¿Deberíamos hacer algún entrenamiento extracurricular también?",
  ui_story_1016_10160401_36_dialog_content = "Eres más que bienvenido a hacerlo por tu cuenta.",
  ui_story_1016_10160401_37_dialog_content = "Pero si es solo para ganar más créditos, es innecesario.",
  ui_story_1016_10160401_38_dialog_content = "Pero cuantos más créditos obtengamos, más ventaja tendremos en la evaluación. ¿No es eso importante?",
  ui_story_1016_10160401_39_dialog_content = "Lo es, pero no tenemos que tomarnos demasiado en serio este ejercicio conjunto...",
  ui_story_1016_10160401_40_dialog_content = "Mirar, Yingel.",
  ui_story_1016_10160401_41_dialog_content = "El piso y los compañeros de combate ahora son muy coloridos.",
  ui_story_1016_10160401_42_dialog_content = "¿Muy colorido?",
  ui_story_1016_10160401_43_dialog_content = "¿Qué pasó? ¿Es pintura?",
  ui_story_1016_10160401_44_dialog_content = "El muñeco de entrenamiento explotó repentinamente hace un momento.",
  ui_story_1016_10160401_45_dialog_content = "...",
  ui_story_1016_10160401_46_dialog_content = "Supongo que alguien lo llenó con diferentes tipos de pintura por adelantado.",
  ui_story_1016_10160401_47_dialog_content = "Es posible que Vivian y los otros hicieron esto?",
  ui_story_1016_10160401_48_dialog_content = "Seguramente no jugarían bromas tan infantiles, ¿verdad?",
  ui_story_1016_10160401_49_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_1016_10160401_50_dialog_content = "<size=45>¿Era eso un arma?</size>",
  ui_story_1016_10160401_51_dialog_content = "¿¡¿Qué crees que estás haciendo?!?",
  ui_story_1016_10160401_52_dialog_content = "Yo...",
  ui_story_1016_10160401_53_dialog_content = "Chloe, ¿estás bien?",
  ui_story_1016_10160401_54_dialog_content = "Estoy bien. No se dispararon balas. Lo único que salió es un montón de confeti.",
  ui_story_1016_10160401_55_dialog_content = "Sin embargo, todavía me zumban los oídos por lo fuerte que sonó el disparo...",
  ui_story_1016_10160401_56_dialog_content = "¡Explícate, soldado! ¡¿Cómo pudo pasar algo así?!",
  ui_story_1016_10160401_57_dialog_content = "No creo que sea su culpa, Beretta.",
  ui_story_1016_10160401_58_dialog_content = "Mira las miradas de sorpresa en sus rostros.",
  ui_story_1016_10160401_59_dialog_content = "¿Ah?",
  ui_story_1016_10160401_60_dialog_content = "Es verdad... Algo no se sentía bien cuando apreté el gatillo, así que alejé el arma lo más rápido que pude.",
  ui_story_1016_10160401_61_dialog_content = "Parece que mi corazonada era correcta, después de todo. Alguien reemplazó uno de mis espacios en blanco con... ¿confeti?",
  ui_story_1016_10160401_62_dialog_content = "¿Alguien cambió tu munición? ¡¿Pero cómo podría ser eso?!",
  ui_story_1016_10160401_63_dialog_content = "Estoy tan confundido como tú.",
  ui_story_1016_10160401_64_dialog_content = "Por favor, perdóname. Informaré de esto a mis superiores de inmediato.",
  ui_story_1016_10160401_65_dialog_content = "¿Se cambiaron los espacios en blanco?",
  ui_story_1016_10160401_66_dialog_content = "¿Pero quién haría algo tan peligroso...?",
  ui_story_1016_10160401_67_dialog_content = "Es más tonto que peligroso.",
  ui_story_1016_10160401_68_dialog_content = "Alguien quiere interferir con el entrenamiento de los demás para evitar que obtengan créditos.",
  ui_story_1016_10160401_69_dialog_content = "Pero, ¿quién recurriría a cosas tan inmaduras?",
  ui_story_1016_10160401_70_dialog_content = "Es difícil de decir. Con tantas facciones reunidas aquí, las apuestas son altas y complicadas.",
  ui_story_1016_10160401_71_dialog_content = "Pero mientras podamos evitar ser absorbidos por este fango, no es de nuestra incumbencia.",
  ui_story_1016_10160401_72_dialog_content = "No te metas con nada ni nadie fuera de nuestras clases, ¿entendido?",
  ui_story_1016_10160401_73_dialog_content = "Entendido.",
  ui_story_1016_10160401_74_dialog_content = "Vamos, Axelia.",
  ui_story_1016_10160401_75_dialog_content = "Está bien...",
  ui_story_1016_10160401_76_dialog_content = "<color=#e8d9bb>Mientras tanto, en el Laboratorio Illumina</color>",
  ui_story_1016_10160401_77_dialog_content = "¡Lo hice! ¡Obtuve permiso para usar el Simulador de Batalla!",
  ui_story_1016_10160401_78_dialog_content = "¡Podremos ahorrarnos mucho tiempo y energía con esto!",
  ui_story_1016_10160401_79_dialog_content = "Acordado. Una vez que el resto de los participantes abandonen el aula, podemos volver y realizar un entrenamiento de resistencia.",
  ui_story_1016_10160401_80_dialog_content = "Esa debería ser nuestra ruta más eficiente para ganar más créditos.",
  ui_story_1016_10160401_81_dialog_content = "Has pensado mucho en esto, ¿verdad? Carleen?",
  ui_story_1016_10160401_82_dialog_content = "Fui participante en el último ejercicio conjunto, ¿recuerdas? Todavía tengo algunos conocimientos útiles de mi experiencia previa.",
  ui_story_1016_10160401_83_dialog_content = "No hay tiempo que perder. Comencemos de inmediato.",
  ui_story_1016_10160401_84_dialog_content = "¡Seguro! Acabamos de ponernos los cascos en la cabeza como la última vez, ¿verdad?",
  ui_story_1016_10160401_85_dialog_content = "¿Eh? ¿Dónde estoy?",
  ui_story_1016_10160401_86_dialog_content = "Esto no se parece en nada a la última simulación.",
  ui_story_1016_10160401_87_dialog_content = "¿Dónde están los enemigos?",
  ui_story_1016_10160401_88_dialog_content = "Déjame explorar el área...",
  ui_story_1016_10160401_89_option_content = "¡Potencia de fuerza!",
  ui_story_1016_10160401_90_dialog_content = "<anim type=Shake>Silbido...</anim>",
  ui_story_1016_10160401_91_dialog_content = "¡Siento muchos enemigos! ¡Incluso más que la última vez!",
  ui_story_1016_10160401_92_dialog_content = "¡El flujo oscuro que emiten también es realmente poderoso!",
  ui_story_1016_10160401_93_dialog_content = "¿No me digas que tenemos que huir otra vez?",
  ui_story_1016_10160401_94_dialog_content = "No creo que haya ningún lugar para que huyamos...",
  ui_story_1016_10160401_95_dialog_content = "¡Ellos vienen!",
  ui_story_1016_10160401_96_dialog_content = "<anim type=Shake><size=50>Graaaaah!!!</size></anim>",
  ui_story_1016_10160401_97_dialog_content = "¡Dispersión, pétalos de hielo!",
  ui_story_1016_10160401_98_dialog_content = "Mi ataque... no tuvo efecto...",
  ui_story_1016_10160401_99_dialog_content = "¡Algo está definitivamente mal con estos eclipses!",
  ui_story_1016_10160401_100_dialog_content = "Lo que sea, esto sigue siendo solo una simulación. ¡Solo sigue luchando!",
  ui_story_1016_10160402_11_dialog_content = "¡Cuidado, ustedes dos!",
  ui_story_1016_10160402_12_dialog_content = "Hay aún más por aquí...",
  ui_story_1016_10160402_13_dialog_content = "Carleen! Vice!",
  ui_story_1016_10160402_14_dialog_content = "<size=45>Ah—!!!</size>",
  ui_story_1016_10160402_15_dialog_content = "<anim type=Shake>Jadeo—jadeo—</anim>",
  ui_story_1016_10160402_16_dialog_content = "Que clase de batalla fue esa...",
  ui_story_1016_10160402_17_dialog_content = "Usted tenía razón. Algo andaba mal con esos eclipses.",
  ui_story_1016_10160402_18_dialog_content = "Poderoso ni siquiera comienza a describir esos monstruos.",
  ui_story_1016_10160402_19_dialog_content = "Tienes razón. Sus ataques no eran diferentes a los de los Eclipsites normales, pero su Darkflow era anormalmente denso...",
  ui_story_1016_10160402_20_dialog_content = "No creerá que alguien podría haber manipulado el Simulador de batalla, ¿verdad?",
  ui_story_1016_10160402_21_dialog_content = "Seguir.",
  ui_story_1016_10160402_22_dialog_content = "Guardian One me dijo una vez que no importa cuán realista se sienta una simulación, siguen siendo solo datos.",
  ui_story_1016_10160402_23_dialog_content = "Las batallas que experimentamos dentro de la simulación se parecen más a algún tipo de cálculo de datos.",
  ui_story_1016_10160402_24_dialog_content = "Si alguien cambiara los números en los datos y los hiciera realmente grandes, el equilibrio en la simulación se perdería por completo.",
  ui_story_1016_10160402_25_dialog_content = "El resultado podría incluso parecerse a lo que vimos hace un momento.",
  ui_story_1016_10160402_26_dialog_content = "¡Tienes razón! ¡Los datos que involucran los niveles de fuerza de esos Eclipsites deben haber sido cambiados para hacerlos increíblemente poderosos!",
  ui_story_1016_10160402_27_dialog_content = "Pero, ¿quién haría algo tan malo?",
  ui_story_1016_10160402_28_dialog_content = "PlayerName, ¿puedes sentir a alguien cerca?",
  ui_story_1016_10160402_29_dialog_content = "Lo intento, pero no veo a nadie sospechoso.",
  ui_story_1016_10160402_30_dialog_content = "Entiendo...",
  ui_story_1016_10160402_31_dialog_content = "Si nuestras sospechas son correctas, debemos informarlas a nuestros instructores.",
  ui_story_1016_10160402_32_dialog_content = "Creo que es mejor si posponemos nuestro entrenamiento por ahora. Las cosas son bastante extrañas, tal como son.",
  ui_story_1016_10160402_33_dialog_content = "Acordado. Volvamos al cuartel.",
  ui_story_1016_10160402_34_dialog_content = "Así que alguien realmente manipuló la simulación, ¿eh?",
  ui_story_1016_10160402_35_dialog_content = "Sí. Gronru ejecutó un escaneo de diagnóstico completo del Simulador de Batalla y encontró un montón de datos que habían sido alterados manualmente.",
  ui_story_1016_10160402_36_dialog_content = "Desafortunadamente, todavía no sabemos quién lo hizo.",
  ui_story_1016_10160402_37_dialog_content = "¿Cuál fue el motivo del culpable para hacer esto...?",
  ui_story_1016_10160402_38_dialog_content = "Pase lo que pase dentro del Simulador de Batalla no tiene ningún efecto tangible en nosotros o en el mundo real.",
  ui_story_1016_10160402_39_dialog_content = "Con eso en mente... Es probable que el culpable intentara evitar que obtuviéramos más créditos.",
  ui_story_1016_10160402_40_dialog_content = "Cuando lo pones de esa manera, tiene sentido.",
  ui_story_1016_10160402_41_dialog_content = "¿Pero eso no significaría que el culpable es uno de los participantes?",
  ui_story_1016_10160402_42_dialog_content = "Es muy probable. Después de todo, la competencia intensa está obligada a invitar a competidores aún más viciosos.",
  ui_story_1016_10160402_43_dialog_content = "En Ejercicios Militares Conjuntos anteriores, siempre surgieron tensiones entre los participantes de Lumopolis e Illumina.",
  ui_story_1016_10160402_44_dialog_content = "Desde esa perspectiva, el ejercicio es solo una versión reducida de la competencia entre diferentes facciones.",
  ui_story_1016_10160402_45_dialog_content = "Pero entonces, ¿por qué apuntarían a nuestro equipo?",
  ui_story_1016_10160402_46_dialog_content = "Soy Caelestite, Carleen de Lumopolis, y Vice es de Ilumina.",
  ui_story_1016_10160402_47_dialog_content = "Una competencia entre diferentes facciones no debería tener nada que ver con nosotros, ¿verdad?",
  ui_story_1016_10160402_48_dialog_content = "No creo que fuéramos necesariamente un objetivo.",
  ui_story_1016_10160402_49_dialog_content = "Recuerde, acabamos de recibir permiso para usar Battle Simulator fuera del horario habitual.",
  ui_story_1016_10160402_50_dialog_content = "Es posible que quien haya manipulado el simulador no supiera que lo usaríamos a continuación.",
  ui_story_1016_10160402_51_dialog_content = "Entonces el objetivo real...",
  ui_story_1016_10160402_52_dialog_content = "Según el cronograma, el equipo de Leo fue el siguiente equipo en usar el Simulador de Batalla.",
  ui_story_1016_10160402_53_dialog_content = "¡Oh! ¡Eso tiene mucho sentido entonces!",
  ui_story_1016_10160402_54_dialog_content = "Ya que están en primer lugar, ¡es natural que alguien intente ralentizarlos!",
  ui_story_1016_10160402_55_dialog_content = "En efecto. De todas las posibilidades, creo que esta es la más probable.",
  ui_story_1016_10160402_56_dialog_content = "Pero por ahora, concentrémonos en nosotros mismos.",
  ui_story_1016_10160402_57_dialog_content = "Deberíamos preocuparnos más por nuestra situación que por lo que hacen los demás.",
  ui_story_1016_10160402_58_dialog_content = "Ven, hagamos un plan para el entrenamiento de mañana.",
  ui_story_1016_10160402_59_dialog_content = "¡Está bien!",
  ui_story_1016_10160402_60_dialog_content = "Jajajajaja! ¡Esto es demasiado divertido!",
  ui_story_1016_10160402_61_dialog_content = "¡No tenía idea de que supieras cómo jugar con el Simulador de batalla de esa manera, Dysis!",
  ui_story_1016_10160402_62_dialog_content = "Aprendí a hacerlo hace poco.",
  ui_story_1016_10160402_63_dialog_content = "El Ejercicio Militar Conjunto nos brinda la oportunidad de leer libros a los que normalmente no tenemos acceso. Sugiero que ambos hagan lo mismo.",
  ui_story_1016_10160402_64_dialog_content = "Oportunidades de aprendizaje como esta no vienen todos los días, ya sabes.",
  ui_story_1016_10160402_65_dialog_content = "¿Leer libros, dices? Eso es rico, viniendo de una persona ciega. ¡No cuentes conmigo!",
  ui_story_1016_10160402_66_dialog_content = "¡Hagamos aún más travesuras mañana, Merry!",
  ui_story_1016_10160402_67_dialog_content = "¿Ver? ¡Ya están empezando a sospechar unos de otros! ¡Esto es genial!",
  ui_story_1016_10160402_68_dialog_content = "Solo trata de que no te atrapen. Parece que se van a enojar.",
  ui_story_1016_10160402_69_dialog_content = "¡De ninguna manera! Los de Illumina están demasiado ocupados sospechando de los de Lumopolis y viceversa.",
  ui_story_1016_10160402_70_dialog_content = "¡Nunca sospecharán de nosotros, con nuestras puntuaciones bajas y nuestra postura neutral!",
  ui_story_1016_10160402_71_dialog_content = "Tienes mi voto en esto, Minch.",
  ui_story_1016_10160402_72_dialog_content = "La razón es la cadena que encadena nuestras mentes, obligándonos constantemente a buscar significado en todo lo que hacemos.",
  ui_story_1016_10160402_73_dialog_content = "Oh chico, aquí vamos de nuevo...",
  ui_story_1016_10160402_74_dialog_content = "Pero no se dan cuenta de que su forma de pensar es demasiado estrecha.",
  ui_story_1016_10160402_75_dialog_content = "Como criaturas pequeñas e insignificantes, todas nuestras acciones carecen por completo de sentido.",
  ui_story_1016_10160402_76_dialog_content = "Su incapacidad para comprender esto significa que nunca tendrán una respuesta para la malicia no provocada.",
  ui_story_1016_10160402_77_dialog_content = "Así que haz tus juegos, mi querido Minch. Juégalos al contenido de tu corazón.",
  ui_story_1016_10160402_78_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1016_10160402_79_dialog_content = "donde ellos...",
  ui_story_1016_10160402_80_dialog_content = "Suspiro, me dejaron atrás de nuevo.",
  ui_story_1016_10160402_81_dialog_content = "Muy bien, volveré por mi cuenta. Ahora, ¿en qué dirección estaban los cuarteles otra vez...?",
  ui_story_1016_10160402_82_dialog_content = "¿Mmm?",
  ui_story_1016_10160501_1_dialog_content = "¡Encontramos signos de eclipses! ¡Ve a pedir refuerzos!",
  ui_story_1016_10160501_2_dialog_content = "¡No podemos dejar escapar a uno solo!",
  ui_story_1016_10160501_3_dialog_content = "Capitán Wrath ya ha sido notificado! ¡Tenemos que unirnos a los demás ahora mismo!",
  ui_story_1016_10160501_4_dialog_content = "Entendido...",
  ui_story_1016_10160501_5_dialog_content = "Oye, ¿por qué estás parado así? ¿No nos escuchaste? ¡Hay eclipses más adelante!",
  ui_story_1016_10160501_6_dialog_content = "Lo siento, son mis ojos...",
  ui_story_1016_10160501_7_dialog_content = "¡Oh, no, está ciego!",
  ui_story_1016_10160501_8_dialog_content = "¿Él es? Oh... P-Por favor disculpe mi rudeza justo ahora.",
  ui_story_1016_10160501_9_dialog_content = "Desafortunadamente, no podemos prescindir de nadie para que lo acompañe a casa en este momento.",
  ui_story_1016_10160501_10_dialog_content = "¿Te importaría esconderte cerca de la calle por ahora? Esta zona sigue siendo segura, te lo aseguro.",
  ui_story_1016_10160501_11_dialog_content = "Está bien, por favor no se preocupen por mí.",
  ui_story_1016_10160501_12_dialog_content = "Es una emergencia, después de todo. Adelante, y por favor tenga cuidado.",
  ui_story_1016_10160501_13_dialog_content = "Lo sentimos mucho... ¡Por favor, cuídate mucho!",
  ui_story_1016_10160501_14_dialog_content = "¡Vamos, vamos!",
  ui_story_1016_10160501_15_dialog_content = "¡Entendido!",
  ui_story_1016_10160501_16_dialog_content = "Eclipses en Gannon City...",
  ui_story_1016_10160501_17_dialog_content = "Parece que alguien está haciendo más travesuras que nosotros.",
  ui_story_1016_10160501_18_dialog_content = "<color=#e8d9bb>Pozo, pat, pozo, pat...</color>",
  ui_story_1016_10160501_19_dialog_content = "¡Allá! ¡Justo adelante!",
  ui_story_1016_10160501_20_dialog_content = "Estamos casi—",
  ui_story_1016_10160501_21_dialog_content = "¡¡¡Cuidado!!!",
  ui_story_1016_10160501_22_dialog_content = "<anim type=Shake><size=50>Graaaaah!!!</size></anim>",
  ui_story_1016_10160501_23_dialog_content = "¿Qué? ¡E-Se están volviendo hacia nosotros!",
  ui_story_1016_10160501_24_dialog_content = "Hay demasiados para nosotros...",
  ui_story_1016_10160501_25_dialog_content = "¡No tenemos más remedio que luchar!",
  ui_story_1016_10160501_26_dialog_content = "Al menos hasta que lleguen los refuerzos...",
  ui_story_1016_10160501_27_dialog_content = "¡No se vean tan desesperanzados, ustedes dos! Esta es la ciudad de Gannon, ¿no?",
  ui_story_1016_10160501_28_dialog_content = "¡¿Quién eres?!",
  ui_story_1016_10160501_29_dialog_content = "Sólo un transeúnte de buen corazón.",
  ui_story_1016_10160501_30_dialog_content = "Increíble...",
  ui_story_1016_10160501_31_dialog_content = "G-Gracias!",
  ui_story_1016_10160501_32_dialog_content = "Si quieres agradecer a alguien, dale las gracias a este chico. Es el que le gusta salir a caminar todos los días.",
  ui_story_1016_10160501_33_dialog_content = "¿Estás tratando de rodear a las fuerzas enemigas?",
  ui_story_1016_10160501_34_dialog_content = "La forma en que lo está haciendo es tremendamente ineficiente y tiene una alta probabilidad de incurrir en bajas.",
  ui_story_1016_10160501_35_dialog_content = "Si se entera de esta torpe maniobra, serás el hazmerreír de toda la ciudad.",
  ui_story_1016_10160501_36_dialog_content = "Lección aprendida, señor.",
  ui_story_1016_10160501_37_dialog_content = "(A juzgar por su apariencia, parece que podría ser un oficial. Aun así...)",
  ui_story_1016_10160501_38_dialog_content = "(¿Por qué anda con alguien que claramente es de Lumopolis?)",
  ui_story_1016_10160501_39_dialog_content = "¿Cuántas tropas están esperando en esta área?",
  ui_story_1016_10160501_40_dialog_content = "Póngame al mando y yo me encargaré de la ofensiva.",
  ui_story_1016_10160501_41_dialog_content = "Pero señor, esto...",
  ui_story_1016_10160501_42_dialog_content = "¡No importa si sigue o no el protocolo! ¡No hay tiempo que perder!",
  ui_story_1016_10160501_43_dialog_content = "¡Sí señor!",
  ui_story_1016_10160501_44_dialog_content = "Notifique a todas las tropas cercanas que se desplieguen en abanico desde cada intersección dentro de un radio de cinco cuadras.",
  ui_story_1016_10160501_45_dialog_content = "Disminuiremos la velocidad de nuestra persecución mientras ellos se ponen en formación.",
  ui_story_1016_10160501_46_dialog_content = "Recuerda, no todas las batallas se pueden ganar solo con la fuerza bruta.",
  ui_story_1016_10160501_47_dialog_content = "Un pescador no se mete en el agua para atrapar un pez, sino para perseguirlo en su red.",
  ui_story_1016_10160502_1_dialog_content = "¿Un pequeño grupo de eclipses? Pero de donde vinieron?",
  ui_story_1016_10160502_2_dialog_content = "Aún no lo sabemos, señora. Ya hemos asignado a alguien para que investigue el asunto.",
  ui_story_1016_10160502_3_dialog_content = "Pero considerando el momento de su aparición, ¿podrían tener algo que ver con Forsakin? Todavía está escondida en algún lugar de la ciudad.",
  ui_story_1016_10160502_4_dialog_content = "Por supuesto que están atados a ella de alguna manera. El verdadero misterio es cómo logró hacerlo en primer lugar.",
  ui_story_1016_10160502_5_dialog_content = "Hemos aumentado el alcance y la frecuencia de nuestras patrullas en los últimos días.",
  ui_story_1016_10160502_6_dialog_content = "Y, sin embargo, todavía no hemos encontrado ninguna señal de Forsakin.",
  ui_story_1016_10160502_7_dialog_content = "Quizás... ¿Quizás se ha vuelto mucho más experta en ocultar sus movimientos?",
  ui_story_1016_10160502_8_dialog_content = "Es posible, pero algo me dice que no es tan simple.",
  ui_story_1016_10160502_9_dialog_content = "Últimamente, he estado sintiendo que algo anda mal aquí en la ciudad de Gannon...",
  ui_story_1016_10160502_10_dialog_content = "¡Capitán! ¡Acabamos de recibir noticias del frente de batalla!",
  ui_story_1016_10160502_11_dialog_content = "¡Todas las unidades cercanas están organizando un cerco de los enemigos!",
  ui_story_1016_10160502_12_dialog_content = "¿Circunvalación? ¿Dónde están y cuántos de ellos han sido desplegados?",
  ui_story_1016_10160502_13_dialog_content = "¡Nunca di tal orden! ¡¿Quién está al mando de mis tropas?!",
  ui_story_1016_10160502_14_dialog_content = "No dijeron, señora...",
  ui_story_1016_10160502_15_dialog_content = "¡Entonces ve a averiguarlo!",
  ui_story_1016_10160502_16_dialog_content = "¡Sigo siendo el general por aquí! ¡Nadie debería estar dando órdenes aparte de mí!",
  ui_story_1016_10160502_17_dialog_content = "¡Se acaba de recibir un nuevo mensaje, capitán!",
  ui_story_1016_10160502_18_dialog_content = "¡El pequeño grupo de Eclipsites que se infiltró en Gannon City ha sido exterminado!",
  ui_story_1016_10160502_19_dialog_content = "<size=50>¡¿Qué?!</size>",
  ui_story_1016_10160502_20_dialog_content = "¿Todos ellos? ¿Está seguro?",
  ui_story_1016_10160502_21_dialog_content = "Sí, señora. No se han detectado signos de actividad de Eclipsite en los alrededores.",
  ui_story_1016_10160502_22_dialog_content = "En tan poco tiempo...",
  ui_story_1016_10160502_23_dialog_content = "je. Que interesante.",
  ui_story_1016_10160502_24_dialog_content = "Me gustaría saber a quién tengo que agradecer por todo esto.",
  ui_story_1016_10160502_25_dialog_content = "Muy bien, creo que hemos terminado aquí.",
  ui_story_1016_10160502_26_dialog_content = "Ahora mismo tenemos que estar en otro sitio, así que os dejaremos la limpieza a ti y a tus tropas.",
  ui_story_1016_10160502_27_dialog_content = "Oh, y es mejor si no les dices a tus superiores que yo tomaré el mando hoy.",
  ui_story_1016_10160502_28_dialog_content = "Creo que les ahorrará a todos muchos problemas si nos lo guardamos para nosotros...",
  ui_story_1016_10160502_29_dialog_content = "¿Guardarlo para vosotros? Pero todos merecen saber quién salvó a nuestra ciudad de los eclipses, ¿no crees?",
  ui_story_1016_10160502_30_dialog_content = "¡Incluso estaba planeando hacer medallas para ti y todo!",
  ui_story_1016_10160502_31_dialog_content = "Instructor Wrath...",
  ui_story_1016_10160502_32_dialog_content = "Ya no estamos en el salón de clases, así que no es necesario que me llames así. Aquí fuera, todos somos soldados.",
  ui_story_1016_10160502_33_dialog_content = "Por favor, perdóname por asumir el mando de tus tropas.",
  ui_story_1016_10160502_34_dialog_content = "Aceptaré cualquier castigo que crea conveniente dispensar.",
  ui_story_1016_10160502_35_dialog_content = "Hmm... Creo que unas bonitas medallas serían mejores que un castigo.",
  ui_story_1016_10160502_36_dialog_content = "Dejemos ese tema a un lado por ahora.",
  ui_story_1016_10160502_37_dialog_content = "No solo nos ayudó en nuestro momento de necesidad, sino que también resolvió el asunto con notable rapidez y eficiencia. Eso es digno de elogio, no importa cómo lo cortes.",
  ui_story_1016_10160502_38_dialog_content = "Y no soy de los que castigan los bienes dignos de elogio.",
  ui_story_1016_10160502_39_dialog_content = "Gracias, Comandante.",
  ui_story_1016_10160502_40_dialog_content = "Tu experiencia en combate y tu velocidad de ejecución son altamente encomiables.",
  ui_story_1016_10160502_41_dialog_content = "No creo que nadie más pudiera haber manejado esta crisis mejor que tú.",
  ui_story_1016_10160502_42_dialog_content = "Tus capacidades son sin duda el producto de tus constantes batallas en el frente.",
  ui_story_1016_10160502_43_dialog_content = "No solo eso, sus experiencias también han infundido un sentido de practicidad en sus tácticas.",
  ui_story_1016_10160502_44_dialog_content = "Como tal, no me ofende seriamente tu forma de pensar. Este tipo de decisión es absolutamente necesaria en el campo de batalla.",
  ui_story_1016_10160502_45_dialog_content = "Pero aquí en Gannon City, nuestras reglas e instituciones tienen mucha más prioridad.",
  ui_story_1016_10160502_46_dialog_content = "Me tomó mucho tiempo aprender eso, y espero que tú también hagas lo mismo.",
  ui_story_1016_10160502_47_dialog_content = "Reglas e instituciones...",
  ui_story_1016_10160502_48_dialog_content = "Esos son los que mantienen el sistema estable, ¿verdad?",
  ui_story_1016_10160502_49_dialog_content = "Así es. La estabilidad lo es todo.",
  ui_story_1016_10160502_50_dialog_content = "No podemos darnos el lujo de ser abrumados por fuerzas externas o conflictos internos.",
  ui_story_1016_10160502_51_dialog_content = "Para preservar esta estabilidad, a veces no tenemos más remedio que sacrificar parte de nuestras victorias.",
  ui_story_1016_10160502_52_dialog_content = "Ya veo. Ahora entiendo.",
  ui_story_1016_10160502_53_dialog_content = "Gracias, instructor.",
  ui_story_1016_10160502_54_dialog_content = "Esto se hará aún más claro, si alguna vez abandonas las tierras fronterizas.",
  ui_story_1016_10160502_55_dialog_content = "Eso es todo por ahora.",
  ui_story_1016_10160502_56_dialog_content = "Voy a dar la clase mañana, así que no llegues tarde.",
  ui_story_1016_10160502_57_dialog_content = "¡Sí, señora!",
  ui_story_1016_10160502_58_dialog_content = "... Pero, ¿y si ese sistema está deformado para empezar, señora?",
  ui_story_1016_10160502_59_dialog_content = "¿Puedes repetir?",
  ui_story_1016_10160502_60_dialog_content = "Una estructura construida sobre una base irregular está destinada a colapsar tarde o temprano, independientemente de cuántas reglas e instituciones la respalden.",
  ui_story_1016_10160502_61_dialog_content = "Si ese es el caso, cualquier sacrificio que hagamos por su bien será en vano.",
  ui_story_1016_10160502_62_dialog_content = "Veo. Entonces, ¿no está satisfecho con la estructura actual, supongo?",
  ui_story_1016_10160502_63_dialog_content = "Perdóneme si sueno grosero, pero ¿sabe por qué estamos participando en este Ejercicio Militar Conjunto?",
  ui_story_1016_10160502_64_dialog_content = "En este momento, en la Zona Oscura en los confines de nuestras tierras, los eclipses se están reuniendo en masa.",
  ui_story_1016_10160502_65_dialog_content = "Están preparados para atravesar nuestras defensas en cualquier momento.",
  ui_story_1016_10160502_66_dialog_content = "Pero nuestras llamadas de socorro solo se encuentran con el silencio.",
  ui_story_1016_10160502_67_dialog_content = "Díganos, comandante, ¿nuestra defensa de Twilight es algo necesario para la estabilidad del sistema?",
  ui_story_1016_10160502_68_dialog_content = "¿O es simplemente otro sacrificio en el gran esquema de las cosas?",
  ui_story_1016_10160502_69_dialog_content = "... ¿Cuánto tiempo ha sido así en las zonas fronterizas?",
  ui_story_1016_10160502_70_dialog_content = "Parece que tenía razón: no sabías nada, después de todo.",
  ui_story_1016_10160502_71_dialog_content = "Lo que significa que los otros comandantes tampoco lo saben.",
  ui_story_1016_10160502_72_dialog_content = "Lo siento si he dicho demasiado.",
  ui_story_1016_10160502_73_dialog_content = "...",
  ui_story_1016_10160502_74_dialog_content = "Deberías volver al cuartel.",
  ui_story_1016_10160502_75_dialog_content = "Revisaré todo lo que me acabas de decir.",
  ui_story_1016_10160502_76_dialog_content = "Entendido.",
  ui_story_1016_10160502_77_dialog_content = "(¿Cómo podría haber sido completamente ignorante de algo tan urgente?)",
  ui_story_1016_10160502_78_dialog_content = "(Qué significa esto, Reinhardt?)",
  ui_story_1016_10160502_79_dialog_content = "(¿O podría ser que esto también está fuera de tu control...?)",
  ui_story_1016_10160502_80_dialog_content = "negador.",
  ui_story_1016_10160502_81_dialog_content = "¡Negador!",
  ui_story_1016_10160502_82_dialog_content = "... Lo siento, estaba distraído hace un momento.",
  ui_story_1016_10160502_83_dialog_content = "Es mala...?",
  ui_story_1016_10160502_84_dialog_content = "Te ves... muy pálida.",
  ui_story_1016_10160502_85_dialog_content = "Todos los Eclipsites que colé en Gannon City han sido aniquilados.",
  ui_story_1016_10160502_86_dialog_content = "La persona al mando no me dio tiempo de reaccionar... Quienesquiera que sean, deben ser poderosos.",
  ui_story_1016_10160502_87_dialog_content = "¿Significa esto... que no tenemos opciones?",
  ui_story_1016_10160502_88_dialog_content = "Hasta que aparece el Espectro, ese parece ser el caso.",
  ui_story_1016_10160502_89_dialog_content = "No me gusta colocar todas nuestras apuestas en ellos.",
  ui_story_1016_10160502_90_dialog_content = "No es una apuesta, es un intercambio.",
  ui_story_1016_10160502_91_dialog_content = "La investigación que tengo en mis manos es suficiente para salvar la vida de ambos.",
  ui_story_1016_10160601_1_dialog_content = "<color=#e8d9bb>Varios días después, cerca del final de la fase de aprendizaje de la lección</color>",
  ui_story_1016_10160601_2_dialog_content = "¿Bien? ¿Dónde estamos en la clasificación ahora?",
  ui_story_1016_10160601_3_dialog_content = "Déjeme ver-",
  ui_story_1016_10160601_4_dialog_content = "¡Segundo lugar! ¡Llegamos al segundo lugar!",
  ui_story_1016_10160601_5_dialog_content = "¡¡¡Impresionante!!! ¡En realidad lo logramos!",
  ui_story_1016_10160601_6_dialog_content = "<color=#e8d9bb>Anillo-</color>",
  ui_story_1016_10160601_7_dialog_content = "Vamos a buscar nuestros asientos. Deberíamos estar en nuestro mejor comportamiento hoy.",
  ui_story_1016_10160601_8_dialog_content = "Tienes razón. Es la última clase de la fase, después de todo.",
  ui_story_1016_10160601_9_dialog_content = "¡Buen día a todos los participantes del ejercicio!",
  ui_story_1016_10160601_10_dialog_content = "Como todos saben, la clase de hoy es la última de la fase de aprendizaje del Ejercicio Militar Conjunto.",
  ui_story_1016_10160601_11_dialog_content = "Después de hoy, comenzarán los preparativos de combate para la fase de evaluación y competirán para determinar el campeón definitivo.",
  ui_story_1016_10160601_12_dialog_content = "Los créditos que ha acumulado en el transcurso de la fase de aprendizaje también le brindarán apoyo en las próximas batallas.",
  ui_story_1016_10160601_13_dialog_content = "Dirija su atención a las clasificaciones en la pared para ver dónde se encuentra su equipo.",
  ui_story_1016_10160601_14_dialog_content = "En primer lugar, y por amplio margen, se encuentra Team Leo.",
  ui_story_1016_10160601_15_dialog_content = "¡Gracias Gracias!",
  ui_story_1016_10160601_16_dialog_content = "Llegando al segundo lugar en la undécima hora está Team PlayerName!",
  ui_story_1016_10160601_17_dialog_content = "Tampoco fue fácil lograrlo...",
  ui_story_1016_10160601_18_dialog_content = "Equipo Yingel, con su desempeño constante, ¡se asegura el tercer lugar!",
  ui_story_1016_10160601_19_dialog_content = "Gracias.",
  ui_story_1016_10160601_20_dialog_content = "En cuanto al resto de clasificaciones, podréis consultarlas vosotros mismos más adelante.",
  ui_story_1016_10160601_21_dialog_content = "Volviendo al tema de su lección final, al comité organizador le gustaría que todos hicieran un calentamiento antes del comienzo de la fase de evaluación.",
  ui_story_1016_10160601_22_dialog_content = "Como tal, la clase de hoy se centrará en el combate.",
  ui_story_1016_10160601_23_dialog_content = "¿Combate? ¿Será diferente de la última clase de combate que tuvimos?",
  ui_story_1016_10160601_24_dialog_content = "Lo hará, en el sentido de que te enfrentarás a un oponente diferente.",
  ui_story_1016_10160601_25_dialog_content = "La seguridad fue la principal prioridad en todas sus clases anteriores. En ningún momento estuviste en peligro real.",
  ui_story_1016_10160601_26_dialog_content = "Ya fuera contra soldados entrenados o enemigos simulados, tus lecciones de combate no tenían forma de infligirte daño real.",
  ui_story_1016_10160601_27_dialog_content = "En la fase de evaluación, sin embargo, nadie podrá garantizar su seguridad.",
  ui_story_1016_10160601_28_dialog_content = "Por este motivo, me gustaría ver si estáis todos preparados para enfrentaros a eclipses reales.",
  ui_story_1016_10160601_29_dialog_content = "¿Eclipsitos reales? ¿En el aula?",
  ui_story_1016_10160601_30_dialog_content = "El Departamento de Investigación Biológica de Illumina tuvo la amabilidad de proporcionarnos algunos especímenes de entrenamiento valiosos.",
  ui_story_1016_10160601_31_dialog_content = "¡Prepárense para la batalla, todos!",
  ui_story_1016_10160601_32_dialog_content = "<color=#e8d9bb>¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡</color>",
  ui_story_1016_10160601_33_dialog_content = "¡Guau! ¡No me di cuenta de que iba a haber tantos eclipses!",
  ui_story_1016_10160601_34_dialog_content = "¿Ilumina ha estado investigando sobre todos ellos? Que empresa tan audaz...",
  ui_story_1016_10160601_35_dialog_content = "Conocer a tu oponente es de suma importancia en la guerra.",
  ui_story_1016_10160601_36_dialog_content = "¿Sabes lo que nos costó asegurar tantos especímenes de investigación valiosos? Las vidas de innumerables soldados, señorita Beretta.",
  ui_story_1016_10160601_37_dialog_content = "Pero...",
  ui_story_1016_10160601_38_dialog_content = "No te preocupes. Estos eclipses están bien bajo nuestro control.",
  ui_story_1016_10160601_39_dialog_content = "¡Ahora bien, todos! No hay reglas o restricciones adicionales para su clase final.",
  ui_story_1016_10160601_40_dialog_content = "¡Utiliza todos y cada uno de los métodos a tu disposición para eliminar a tus oponentes!",
  ui_story_1016_10160601_41_dialog_content = "<anim type=Shake><size=50>Graaaaah!!!</size></anim>",
  ui_story_1016_10160601_42_dialog_content = "¡¿E-Empezamos ahora?!",
  ui_story_1016_10160601_43_dialog_content = "Todavía no estoy listo...",
  ui_story_1016_10160601_44_dialog_content = "Cuidadoso, PlayerName.",
  ui_story_1016_10160601_45_dialog_content = "¡Lo siento! ¡No estaba prestando atención!",
  ui_story_1016_10160601_46_dialog_content = "Vigila a los otros equipos durante la batalla.",
  ui_story_1016_10160601_47_dialog_content = "Esta es una buena oportunidad para que echemos un vistazo a sus capacidades de combate reales.",
  ui_story_1016_10160601_48_dialog_content = "Haz tu mejor esfuerzo para mantenerte fuera de la pelea, Axelia.",
  ui_story_1016_10160601_49_dialog_content = "déjalo todo a Anatoli y yo.",
  ui_story_1016_10160601_50_dialog_content = "¿Está bien?",
  ui_story_1016_10160601_51_dialog_content = "Sigue siendo solo una clase. Estoy seguro de que no corremos demasiado peligro.",
  ui_story_1016_10160601_52_dialog_content = "Los otros equipos también están presentes.",
  ui_story_1016_10160601_53_dialog_content = "Dices eso, pero...",
  ui_story_1016_10160601_54_dialog_content = "Tampoco parecen estar luchando con toda su fuerza.",
  ui_story_1016_10160601_55_dialog_content = "Cubre mi flanco izquierdo, Uriah!",
  ui_story_1016_10160601_56_dialog_content = "¡Entendido!",
  ui_story_1016_10160601_57_dialog_content = "¡No es bueno! Estamos rodeados por todos lados...",
  ui_story_1016_10160601_58_dialog_content = "Chloe!",
  ui_story_1016_10160601_59_dialog_content = "¡Estoy un poco ocupado ahora mismo!",
  ui_story_1016_10160601_60_dialog_content = "¿Lo que está sucediendo? ¡Se siente como si estuviéramos peleando solos!",
  ui_story_1016_10160601_61_dialog_content = "¿Cómo terminamos al frente de la batalla?",
  ui_story_1016_10160601_62_dialog_content = "Creo que es porque todos se están retirando...",
  ui_story_1016_10160601_63_dialog_content = "¡¿Qué?!",
  ui_story_1016_10160601_64_dialog_content = "¡Pero todos estaban clasificados muy por encima de nosotros! ¡¿Cómo podrían huir cuando comienza la verdadera lucha?!",
  ui_story_1016_10160601_65_dialog_content = "Nosotros también tenemos las manos llenas, ¿sabes?",
  ui_story_1016_10160601_66_dialog_content = "¡¿De qué estás hablando?! ¡Ni siquiera has desenvainado tu espada!",
  ui_story_1016_10160601_67_dialog_content = "Parece que todos se están conteniendo...",
  ui_story_1016_10160601_68_dialog_content = "Que tiene sentido. Todos intentan mantener oculto su verdadero poder hasta la fase de evaluación.",
  ui_story_1016_10160601_69_dialog_content = "Pero a este ritmo, no tendremos forma de vencer a todos estos eclipses...",
  ui_story_1016_10160601_70_dialog_content = "Si nadie quiere luchar con toda su fuerza, ¡entonces todos deberíamos trabajar juntos!",
  ui_story_1016_10160601_71_dialog_content = "El enemigo no es muy poderoso, así que si todos colaboran un poco, ¡podríamos ganar sin problemas!",
  ui_story_1016_10160601_72_dialog_content = "¿Oh? Eso vale la pena intentarlo, supongo.",
  ui_story_1016_10160601_73_dialog_content = "¡No me importaría luchar junto a gente de otras facciones!",
  ui_story_1016_10160601_74_dialog_content = "Acordado. Si no hay nada más por lo que competir en nuestra clase final, trabajemos juntos y acabemos con esto.",
  ui_story_1016_10160601_75_dialog_content = "¡También estamos de acuerdo! ¡Ahora por favor ayúdanos!",
  ui_story_1016_10160601_76_dialog_content = "¡Suena divertido! ¡Cuenta conmigo!",
  ui_story_1016_10160601_77_dialog_content = "¡Está bien! ¡Combinemos nuestras fuerzas para ganar, todos!",
  ui_story_1016_10160601_78_dialog_content = "¡Primero, tenemos que hacer retroceder al enemigo y sacar al equipo de Beretta del peligro!",
  ui_story_1016_10160602_1_dialog_content = "¡Excelente! ¡Todos los Eclipsites han sido exterminados!",
  ui_story_1016_10160602_2_dialog_content = "Felicitaciones a todos por completar su lección final, así como la fase de aprendizaje del Ejercicio Militar Conjunto.",
  ui_story_1016_10160602_3_dialog_content = "Esperábamos que la competencia fuera mucho más intensa, pero en un sorprendente giro de los acontecimientos, ¡los equipos decidieron trabajar juntos y eliminar a sus oponentes!",
  ui_story_1016_10160602_4_dialog_content = "Bueno, no es como si fuera por la bondad del corazón de todos, jaja.",
  ui_story_1016_10160602_5_dialog_content = "¡Y con eso, la fase de aprendizaje concluye oficialmente! Antes de continuar, permítanme presentarles brevemente las próximas evaluaciones.",
  ui_story_1016_10160602_6_dialog_content = "Seguro que muchos de vosotros estáis ansiosos por saber más al respecto, ¿no?",
  ui_story_1016_10160602_7_dialog_content = "La fase de evaluación de este Ejercicio Militar Conjunto tendrá lugar en Entrañas abandonadas.",
  ui_story_1016_10160602_8_dialog_content = "Ubicado cerca de nuestras líneas defensivas, hace mucho tiempo que ha sido invadido por eclipses. El área circundante ha estado desprovista de vida auroriana durante muchos, muchos años.",
  ui_story_1016_10160602_9_dialog_content = "Tu objetivo es abrirte camino hasta los confines más profundos de esta Entrañas y recuperar un estandarte que se ha plantado allí.",
  ui_story_1016_10160602_10_dialog_content = "Las reglas para esto son increíblemente simples: quien recupere el estandarte será nombrado campeón y tendrá la oportunidad de batirse en duelo con el Gran Mariscal.",
  ui_story_1016_10160602_11_dialog_content = "Puede lograr este objetivo por cualquier medio necesario. No hay otras reglas o restricciones en esta fase.",
  ui_story_1016_10160602_12_dialog_content = "¿Habrá alguna garantía para nuestra seguridad?",
  ui_story_1016_10160602_13_dialog_content = "Es mejor si no cuentas con ello.",
  ui_story_1016_10160602_14_dialog_content = "Para sacar todo el potencial de combate de cada participante, la dificultad y el peligro de la fase de evaluación se han incrementado significativamente.",
  ui_story_1016_10160602_15_dialog_content = "Recuerda, el combate real es muy diferente del entrenamiento. El éxito en la fase de aprendizaje no se traduce necesariamente en éxito en la fase de evaluación.",
  ui_story_1016_10160602_16_dialog_content = "Durante su misión, nuestros instructores emplearán una variedad de métodos para monitorear su desempeño.",
  ui_story_1016_10160602_17_dialog_content = "Cualquier acción maliciosa tomada contra los participantes puede y será utilizada como prueba en su contra en un tribunal militar.",
  ui_story_1016_10160602_18_dialog_content = "Aparte de eso, no podremos interferir o ayudarlo con ninguno de los peligros que enfrenta.",
  ui_story_1016_10160602_19_dialog_content = "Con eso en mente, lo mejor para usted es confiar solo en ustedes mismos, no en el apoyo que podamos ofrecerle.",
  ui_story_1016_10160602_20_dialog_content = "Veo. Gracias por la aclaración.",
  ui_story_1016_10160602_21_dialog_content = "Eso me queda muy bien. Si tuviéramos gente dispuesta a salvarnos, todo esto sería solo un gran juego.",
  ui_story_1016_10160602_22_dialog_content = "¡Ahora es el momento de que todos se preparen para la fase de evaluación!",
  ui_story_1016_10160602_23_dialog_content = "En aras de la equidad, solo se le proporcionará el mínimo indispensable del equipo de combate necesario.",
  ui_story_1016_10160602_24_dialog_content = "Para cualquier soporte más allá de eso, puede usar sus créditos de la fase de aprendizaje para comprarlo.",
  ui_story_1016_10160602_25_dialog_content = "¡Lindo! ¡Finalmente podemos darle un buen uso a nuestros créditos ganados con tanto esfuerzo!",
  ui_story_1016_10160602_26_dialog_content = "¡Correcto! Mañana, lo guiaré a uno de los principales centros de investigación de Illumina, donde hemos preparado todo tipo de artículos de apoyo para usted.",
  ui_story_1016_10160602_27_dialog_content = "Algunos mejorarán tus capacidades de combate, mientras que otros te proporcionarán información crucial en el campo de batalla.",
  ui_story_1016_10160602_28_dialog_content = "Los recursos disponibles estarán determinados por los créditos que ganes.",
  ui_story_1016_10160602_29_dialog_content = "En otras palabras, aquellos con más créditos podrán obtener aún más apoyo para la próxima fase.",
  ui_story_1016_10160602_30_dialog_content = "Ya sea que elija mejorar sus fortalezas o compensar sus deficiencias, depende totalmente de usted.",
  ui_story_1016_10160602_31_dialog_content = "Hmm, ¿qué deberíamos elegir...?",
  ui_story_1016_10160602_32_dialog_content = "Una vez que haya hecho todos los preparativos necesarios, regrese al cuartel lo antes posible. Nos reuniremos en el salón de clases mañana por la mañana para el inicio de la fase de evaluación.",
  ui_story_1016_10160602_33_dialog_content = "Eso es todo lo que tengo por hoy. ¡Clase perdida!",
  ui_story_1016_10160602_34_dialog_content = "<color=#e8d9bb>El día siguiente</color>",
  ui_story_1016_10160602_35_dialog_content = "¡Guau! ¡Mira todo este equipo!",
  ui_story_1016_10160602_36_dialog_content = "Rifles y bayonetas, granadas y todo tipo de equipo de protección...",
  ui_story_1016_10160602_37_dialog_content = "¡¿Cómo se supone que debemos elegir?! ¡Los quiero todos!",
  ui_story_1016_10160602_38_dialog_content = "Si miras todo de cerca, la mayoría de estas cosas cuestan muchos créditos.",
  ui_story_1016_10160602_39_dialog_content = "A pesar de que ocupamos el segundo lugar, todavía estamos bastante limitados en cuanto a cuánto podemos pagar.",
  ui_story_1016_10160602_40_dialog_content = "En efecto. Parece que la mayoría de estas cosas fueron solo incentivos para que lo hiciéramos mejor en la fase anterior. Después de todo, los organizadores no quieren que dependamos demasiado de la ayuda externa.",
  ui_story_1016_10160602_41_dialog_content = "Debemos elegir lo que más necesitamos.",
  ui_story_1016_10160602_42_dialog_content = "Si me preguntas, tener PlayerName en nuestro equipo nos da una ventaja natural cuando se trata de recopilar información.",
  ui_story_1016_10160602_43_dialog_content = "Entonces, ¿tal vez deberíamos usar nuestros créditos para mejorar nuestras habilidades de combate?",
  ui_story_1016_10160602_44_dialog_content = "Cuando lo pones de esa manera, creo que deberíamos invertir en más elementos defensivos.",
  ui_story_1016_10160602_45_dialog_content = "PlayerName es relativamente indefenso en la batalla. Deberíamos priorizar mantenerlo a salvo en las próximas batallas.",
  ui_story_1016_10160602_46_dialog_content = "¿Eh? N-No necesitas gastar tanto en mí, sabes...",
  ui_story_1016_10160602_47_dialog_content = "Estoy totalmente de acuerdo contigo, Carleen!",
  ui_story_1016_10160602_48_dialog_content = "Ven aquí, PlayerName! ¡A ver si este traje protector te queda bien!",
  ui_story_1016_10160602_49_dialog_content = "Espera, ¿quieres decir justo aquí?",
  ui_story_1016_10160602_50_dialog_content = "Oh, supongo que está bien, si eso significa que no los retendré a ustedes dos...",
  ui_story_1016_10160602_51_dialog_content = "Es todo un montón de maquinaria...",
  ui_story_1016_10160602_52_dialog_content = "Realmente no puedo emocionarme con estas cosas. Tú eliges, Zhao.",
  ui_story_1016_10160602_53_dialog_content = "Seguro. Ya lo he pensado mucho.",
  ui_story_1016_10160602_54_dialog_content = "Lo que necesitamos más que nada es información.",
  ui_story_1016_10160602_55_dialog_content = "Si logramos estar un paso por delante del enemigo, ninguna batalla será demasiado para nosotros.",
  ui_story_1016_10160602_56_dialog_content = "Sí, eso tiene sentido. Prefiero que no me pille por sorpresa tampoco.",
  ui_story_1016_10160602_57_dialog_content = "Tomemos un mapa, así como este comunicador.",
  ui_story_1016_10160602_58_dialog_content = "Sin embargo, ese comunicador es bastante caro. Nos costará más de la mitad de nuestros créditos conseguirlo.",
  ui_story_1016_10160602_59_dialog_content = "Según la descripción, este comunicador se puede utilizar para contactar a los instructores en cualquier momento durante la fase de evaluación.",
  ui_story_1016_10160602_60_dialog_content = "Nada más podría proporcionarnos información más útil.",
  ui_story_1016_10160602_61_dialog_content = "Bien entonces. Te dejaremos tomar las decisiones en este caso.",
  ui_story_1016_10160602_62_dialog_content = "Cierre la puerta.",
  ui_story_1016_10160602_63_dialog_content = "¡Sí señor!",
  ui_story_1016_10160602_64_dialog_content = "<color=#e8d9bb>Ruido sordo.</color>",
  ui_story_1016_10160602_65_dialog_content = "¿Eres plenamente consciente de tu misión?",
  ui_story_1016_10160602_66_dialog_content = "Sí. Debemos ganar el campeonato a toda costa.",
  ui_story_1016_10160602_67_dialog_content = "Ya se lo he dicho a los demás.",
  ui_story_1016_10160602_68_dialog_content = "Creo en tu fuerza combinada, pero no necesitas seguir las reglas.",
  ui_story_1016_10160602_69_dialog_content = "He preparado algunos suministros para ti. Los encontrará mucho más útiles que cualquier cosa que sus créditos puedan comprar.",
  ui_story_1016_10160602_70_dialog_content = "Y no te preocupes, con estos podrás entrar en la fase de evaluación.",
  ui_story_1016_10160602_71_dialog_content = "Para obtener información, se le proporcionó un mapa completamente detallado que también incluye la ubicación exacta del banner.",
  ui_story_1016_10160602_72_dialog_content = "No tendrás que buscar a tientas en la oscuridad como el resto de los equipos con esto. Simplemente diríjase directamente a la ubicación de destino.",
  ui_story_1016_10160602_73_dialog_content = "En ese casillero de allí, encontrarás varias piezas de equipo para mejorar el combate. Toma lo que necesites.",
  ui_story_1016_10160602_74_dialog_content = "(¿Lo que necesitemos? Incluso uno de estos artículos cuesta los créditos de todo un equipo...)",
  ui_story_1016_10160602_75_dialog_content = "(Los de arriba se indignarán si nos atrapan haciendo trampa tan descaradamente).",
  ui_story_1016_10160602_76_dialog_content = "(¿El Comité necesita tanto al campeón?)",
  ui_story_1016_10160602_77_dialog_content = "Eso es todo por ahora. Dejo el resto en tus manos.",
  ui_story_1016_10160602_78_dialog_content = "No le digas a nadie sobre nuestra reunión de hoy.",
  ui_story_1016_10160602_79_dialog_content = "<color=#e8d9bb>Ruido sordo.</color>",
  ui_story_1016_10160602_80_dialog_content = "tengo los cubos No necesito nada más.",
  ui_story_1016_10160602_81_dialog_content = "Tampoco necesito ningún equipo adicional. Elige tu opción, Anatoli.",
  ui_story_1016_10160602_82_dialog_content = "¿Yo?",
  ui_story_1016_10160602_83_dialog_content = "Darle a una sola persona todo este equipo debería aumentar nuestras posibilidades de éxito.",
  ui_story_1016_10160602_84_dialog_content = "... Bien. Haré lo que me digan.",
  ui_story_1016_10160602_85_dialog_content = "Todos estamos haciendo lo que nos dicen, Anatoli.",
  ui_story_1016_10160602_86_dialog_content = "Después de tratar con el Comité durante tanto tiempo, ustedes dos ya deben estar acostumbrados a este tipo de órdenes, ¿verdad?",
  ui_story_1016_10160602_87_dialog_content = "¿Tienes algo que decir?",
  ui_story_1016_10160602_88_dialog_content = "No. Solo estaba preguntando.",
  ui_story_1016_10160602_89_dialog_content = "Como Oficial de Inteligencia, debe tratar de evitar hacer preguntas tan descuidadamente.",
  ui_story_1016_10160602_90_dialog_content = "En cuanto a hacer lo que me dicen, sí, hace mucho tiempo que me acostumbré. Los pedidos son primordiales, sin importar lo que impliquen.",
  ui_story_1016_10160602_91_dialog_content = "Entiendo...",
  ui_story_1016_10160602_92_dialog_content = "Sin embargo, eso no significa que esté de acuerdo con mis órdenes todo el tiempo.",
  ui_story_1016_10160602_93_dialog_content = "Cuando eso sucede, elijo ocultar mi desacuerdo detrás de mis acciones.",
  ui_story_1016_10160701_1_dialog_content = "<color=#e8d9bb>Toc, toc—</color>",
  ui_story_1016_10160701_2_dialog_content = "¡Muy bien, todos fuera! ¡Hemos llegado a nuestro destino!",
  ui_story_1016_10160701_3_dialog_content = "¡Esa Entrañas de aspecto decrépito más adelante es donde se llevará a cabo la fase de evaluación!",
  ui_story_1016_10160701_4_dialog_content = "Nuestros soldados ahora escoltarán a cada equipo a un punto de partida diferente en Entrañas.",
  ui_story_1016_10160701_5_dialog_content = "A ver, ¿se me olvida algo...?",
  ui_story_1016_10160701_6_dialog_content = "¡Correcto! ¡Ten mucho cuidado ahí fuera! ¡Pueden pelear entre sí, pero no golpes mortales!",
  ui_story_1016_10160701_7_dialog_content = "Estaré observando desde las sombras cada paso del camino, ¿me oyes?",
  ui_story_1016_10160701_8_dialog_content = "Oh, me estás dando escalofríos...",
  ui_story_1016_10160701_9_dialog_content = "¡Llévenlos a sus puntos de partida, soldados!",
  ui_story_1016_10160701_10_dialog_content = "¡Tengo grandes esperanzas para todos ustedes!",
  ui_story_1016_10160701_11_dialog_content = "Asegurémonos de que nuestro equipo esté en orden.",
  ui_story_1016_10160701_12_dialog_content = "¡Sí! ¡Me parece bien!",
  ui_story_1016_10160701_13_dialog_content = "Estamos armados hasta los dientes, ¡así que es mejor que esos Eclipsites tengan cuidado!",
  ui_story_1016_10160701_14_dialog_content = "Sigamos con el plan que discutimos anteriormente.",
  ui_story_1016_10160701_15_dialog_content = "Los otros equipos definitivamente compraron mapas y otros elementos de recopilación de información. Todo lo que tenemos que hacer es usar PlayerNamelas habilidades psíquicas de para seguir a uno de ellos a Entrañas.",
  ui_story_1016_10160701_16_dialog_content = "Entendido. Ya estoy buscando a los otros equipos.",
  ui_story_1016_10160701_17_dialog_content = "Pero parece que todavía están fuera de alcance. Nuestros puntos de partida deben estar muy separados.",
  ui_story_1016_10160701_18_dialog_content = "Estaremos bien una vez que nos adentremos más en la ciudad.",
  ui_story_1016_10160701_19_dialog_content = "¿Qué demonios compraste, Minch...?",
  ui_story_1016_10160701_20_dialog_content = "Muy bien, ¿eh? Mira lo que sucede cuando lanzo esta granada de destello—",
  ui_story_1016_10160701_21_dialog_content = "<size=50>¡Guau!</size>",
  ui_story_1016_10160701_22_dialog_content = "¿Qué es? ¿Ya estamos bajo ataque?",
  ui_story_1016_10160701_23_dialog_content = "No, Merry solo estaba bromeando.",
  ui_story_1016_10160701_24_dialog_content = "Oh, ¿estás llorando de nuevo?",
  ui_story_1016_10160701_25_dialog_content = "¡Por supuesto que no! Me pican mucho los ojos...",
  ui_story_1016_10160701_26_dialog_content = "¿Cuál fue el punto de gastar nuestros créditos en eso, Minch?",
  ui_story_1016_10160701_27_dialog_content = "¡Divertirse! ¡Eh!",
  ui_story_1016_10160701_28_dialog_content = "Mira, no teníamos suficientes créditos para comprar nada útil.",
  ui_story_1016_10160701_29_dialog_content = "Así que pensé para mis adentros: \"¿Por qué no divertirme un poco?\"",
  ui_story_1016_10160701_30_dialog_content = "Supongo que tiene sentido...",
  ui_story_1016_10160701_31_dialog_content = "Después de todo, no estamos aquí para ganar el campeonato.",
  ui_story_1016_10160701_32_dialog_content = "Solo haría las cosas más problemáticas si ganáramos, considerando que el campeón tiene que colocar la bandera de su propia facción en el estandarte.",
  ui_story_1016_10160701_33_dialog_content = "¿Qué facción dijimos que éramos, de nuevo?",
  ui_story_1016_10160701_34_dialog_content = "Umbraton, aunque nunca he estado allí.",
  ui_story_1016_10160701_35_dialog_content = "Qué asco, ¿de verdad? La bandera de Umbraton se ve tan fea.",
  ui_story_1016_10160701_36_dialog_content = "Además, el campeón se enfrenta a eso. Reinhardt, ¿bien? ¡Pues cuenta conmigo!",
  ui_story_1016_10160701_37_dialog_content = "No serías tú quien peleara con ella, Minch. Dysis es el capitán de nuestro equipo, después de todo.",
  ui_story_1016_10160701_38_dialog_content = "Tampoco tengo interés en pelear con ella. Ella no es más que una heroína sin sentido respaldada por un sistema igualmente sin sentido.",
  ui_story_1016_10160701_39_dialog_content = "Nuestros esfuerzos estarían mejor invertidos en los participantes.",
  ui_story_1016_10160701_40_dialog_content = "No olvides por qué vinimos aquí en primer lugar.",
  ui_story_1016_10160701_41_dialog_content = "¿Te mataría dejar de ser tan pedante todo el tiempo, Dysis?",
  ui_story_1016_10160701_42_dialog_content = "¡Vamos, vamos a divertirnos mientras podamos!",
  ui_story_1016_10160701_43_dialog_content = "¡Los otros equipos están prácticamente esperando que nos metamos con ellos!",
  ui_story_1016_10160701_44_dialog_content = "¡Encontré un equipo!",
  ui_story_1016_10160701_45_dialog_content = "¿En realidad? ¿OMS?",
  ui_story_1016_10160701_46_dialog_content = "Es ese grupo de bichos raros de Umbraton.",
  ui_story_1016_10160701_47_dialog_content = "Creo que el nombre de su capitán es Dysis o algo así.",
  ui_story_1016_10160701_48_dialog_content = "¡Ay, los recuerdo! ¡Disis, Minch y Merry!",
  ui_story_1016_10160701_49_dialog_content = "Si lo preguntas, no me parecen personas muy respetuosas de las reglas.",
  ui_story_1016_10160701_50_dialog_content = "Se dirigen directamente a Entrañas, y rápido.",
  ui_story_1016_10160701_51_dialog_content = "A juzgar por sus movimientos, ¡creo que podrían estar en algo!",
  ui_story_1016_10160701_52_dialog_content = "Estoy de acuerdo. Deben tener un objetivo claro si se mueven tan rápido.",
  ui_story_1016_10160701_53_dialog_content = "Deberíamos alcanzarlos de inmediato.",
  ui_story_1016_10160701_54_dialog_content = "No tendremos que hacerlo. Pronto pasarán por nuestra ubicación.",
  ui_story_1016_10160701_55_dialog_content = "Oye, creo que ya los escucho...",
  ui_story_1016_10160701_56_dialog_content = "¡Yu-hoo! Alcanzanos si puedes!",
  ui_story_1016_10160701_57_dialog_content = "Despacio, Minch...",
  ui_story_1016_10160701_58_dialog_content = "¡Espera, algo no está bien!",
  ui_story_1016_10160701_59_dialog_content = "¡Están siendo perseguidos por un montón de Eclipsitas!",
  ui_story_1016_10160701_60_dialog_content = "¡¿Qué?!",
  ui_story_1016_10160701_61_dialog_content = "Aparentemente lograron provocar a todos los Eclipsite en el área con sus movimientos imprudentes.",
  ui_story_1016_10160701_62_dialog_content = "No solo eso... parece que esos tres tampoco tienen intención de luchar contra ellos.",
  ui_story_1016_10160701_63_dialog_content = "¡Simplemente están guiando a los Eclipsites por la nariz!",
  ui_story_1016_10160701_64_dialog_content = "¿Qué están haciendo? ¿No saben que esto ya no es un juego?",
  ui_story_1016_10160701_65_dialog_content = "Dudo que tengan un objetivo claro en mente. Date prisa, vámonos antes de que nos veamos atrapados en su lío.",
  ui_story_1016_10160701_66_dialog_content = "Estoy de acuerdo, pero...",
  ui_story_1016_10160701_67_dialog_content = "¡Están corriendo directamente hacia nosotros ahora!",
  ui_story_1016_10160701_68_dialog_content = "¡Mira, Minch! ¡El equipo de Caelestite está justo adelante!",
  ui_story_1016_10160701_69_dialog_content = "La Caelestita, ¿eh? ¡Apuesto a que es muy divertido! ¡Vamos a ver si quiere jugar!",
  ui_story_1016_10160701_70_dialog_content = "<size=50>¡Ayuda! ¡Los eclipses nos van a comer! Alguien ayúdenos!!!</size>",
  ui_story_1016_10160701_71_dialog_content = "Es demasiado tarde, nos vieron...",
  ui_story_1016_10160701_72_dialog_content = "...",
  ui_story_1016_10160701_73_dialog_content = "disis! ¡Usted y su equipo, escuchen!",
  ui_story_1016_10160701_74_dialog_content = "¡Tienes que darte la vuelta y empezar a luchar contra esos eclipses!",
  ui_story_1016_10160701_75_dialog_content = "¿Eh? ¡¿Quién te crees que eres para mandarme?!",
  ui_story_1016_10160701_76_dialog_content = "¡Date la vuelta y lucha, y nos uniremos a ti!",
  ui_story_1016_10160701_77_dialog_content = "¡Sigue corriendo hacia nosotros y no tendremos más remedio que tratarte como enemigo y atacar!",
  ui_story_1016_10160701_78_dialog_content = "¡¿¡¿Ataque?!?!",
  ui_story_1016_10160701_79_dialog_content = "Esta es la única forma en que podemos mantener la ventaja.",
  ui_story_1016_10160701_80_dialog_content = "¡Ay, no seas tan serio! ¡Solo quería divertirme un poco, eso es todo!",
  ui_story_1016_10160701_81_dialog_content = "¡Bien, haremos lo que dices y formaremos un equipo!",
  ui_story_1016_10160701_82_dialog_content = "¡Merry, date la vuelta y dale a esos Eclipsites una paliza que no olvidarán!",
  ui_story_1016_10160701_83_dialog_content = "¡Con placer!",
  ui_story_1016_10160701_84_dialog_content = "¡Están al ataque! ¡Deberíamos unirnos a ellos también!",
  ui_story_1016_10160701_85_dialog_content = "¡Bien! ¡Acabemos con esto rápido!",
  ui_story_1016_10160802_1_dialog_content = "<anim type=Shake>Gaah...</anim>",
  ui_story_1016_10160802_2_dialog_content = "¡je! ¡Eso fue mucho más fácil de lo que pensaba!",
  ui_story_1016_10160802_3_dialog_content = "Desafortunadamente, parece que el resto de los equipos están muy por delante de nosotros ahora.",
  ui_story_1016_10160802_4_dialog_content = "¡Esto apesta! Nunca podremos ponernos al día debido a esos estúpidos eclipses...",
  ui_story_1016_10160802_5_dialog_content = "Tal vez sea solo yo, pero desde que nos encontramos con esos tres...",
  ui_story_1016_10160802_6_dialog_content = "¡No puedo evitar sentir que nos han engañado!",
  ui_story_1016_10160802_7_dialog_content = "Ahora no es el momento de quejarse.",
  ui_story_1016_10160802_8_dialog_content = "A este ritmo, el campeonato estará completamente fuera de nuestro alcance pronto.",
  ui_story_1016_10160802_9_dialog_content = "Vamos. Dysis, usted y su equipo harían bien en mantenerse al día con nosotros.",
  ui_story_1016_10160802_10_dialog_content = "Ah, gracias por su preocupación, pero no deseamos aventurarnos más en la ciudad.",
  ui_story_1016_10160802_11_dialog_content = "Tenemos asuntos más importantes que manejar en este momento.",
  ui_story_1016_10160802_12_dialog_content = "(Algo en ellos parece realmente extraño...)",
  ui_story_1016_10160802_13_dialog_content = "Si ese es el caso, entonces nos vamos ahora. PlayerName, Vice, sigamos adelante.",
  ui_story_1016_10160802_14_dialog_content = "Uh, claro.",
  ui_story_1016_10160802_15_dialog_content = "<color=#e8d9bb>En lo profundo de la Zona Oscura de Entrañas</color>",
  ui_story_1016_10160802_16_dialog_content = "¿Alguna señal de los otros equipos?",
  ui_story_1016_10160802_17_dialog_content = "Ninguno en absoluto. A juzgar por la situación, parece que hemos hecho el mayor progreso de todos.",
  ui_story_1016_10160802_18_dialog_content = "Genial, todavía estamos a la cabeza. La fase de evaluación ha sido mucho más fácil de lo que esperaba.",
  ui_story_1016_10160802_19_dialog_content = "Por otra parte, con un caballero, un táctico y un poderoso maestro de Luminatics en nuestro equipo...",
  ui_story_1016_10160802_20_dialog_content = "Es básicamente imposible que perdamos, ¿verdad?",
  ui_story_1016_10160802_21_dialog_content = "Jeje, seguro que te sientes humilde hoy, ¿no?",
  ui_story_1016_10160802_22_dialog_content = "Hemos logrado mantener el liderazgo hasta ahora, así que pongamos fin a esto lo antes posible.",
  ui_story_1016_10160802_23_dialog_content = "Instructor Gronru—",
  ui_story_1016_10160802_24_dialog_content = "Adelante, te escucho.",
  ui_story_1016_10160802_25_dialog_content = "Nos gustaría gastar nuestros créditos restantes para identificar la ubicación exacta de nuestro objetivo. ¿Puedes hacer eso por nosotros?",
  ui_story_1016_10160802_26_dialog_content = "Por supuesto que puedo, pero ¿no creen que esto es un poco exagerado?",
  ui_story_1016_10160802_27_dialog_content = "Casi hemos llegado al final, así que también podemos usar todos los recursos a nuestra disposición.",
  ui_story_1016_10160802_28_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1016_10160802_29_dialog_content = "Muy bien, sigue adelante y revisa tu mapa. El área resaltada es donde encontrará su objetivo.",
  ui_story_1016_10160802_30_dialog_content = "Dado que todo es juego justo de acuerdo con las reglas que te dimos, no tengo forma de arrestarte por hacer trampa.",
  ui_story_1016_10160802_31_dialog_content = "De hecho, estoy absolutamente encantado de verlos usar las reglas del juego a su favor.",
  ui_story_1016_10160802_32_dialog_content = "¡Así que sigue adelante y despeja esta etapa!",
  ui_story_1016_10160802_33_dialog_content = "Este es el momento que hemos estado esperando.",
  ui_story_1016_10160802_34_dialog_content = "Sigamos adelante, mientras aún estemos muy por delante de los demás.",
  ui_story_1016_10160802_35_dialog_content = "<color=#e8d9bb>En lo profundo de la Zona Oscura de Entrañas, cerca del objetivo</color>",
  ui_story_1016_10160802_36_dialog_content = "<anim type=Shake>Graaah...</anim>",
  ui_story_1016_10160802_37_dialog_content = "Muy bien, ese debería ser el último Eclipsite.",
  ui_story_1016_10160802_38_dialog_content = "Aunque has elegido caminar por el camino de la oscuridad, oro para que el Dios de la Luz te libre de tu sufrimiento.",
  ui_story_1016_10160802_39_dialog_content = "Sigo pensando que suenas mucho más aterrador cuando hablas así, Joseph...",
  ui_story_1016_10160802_40_dialog_content = "Aunque estamos lo más cerca posible de nuestro objetivo, su ubicación exacta...",
  ui_story_1016_10160802_41_dialog_content = "... ¡podría estar en cualquier lugar de Entrañas así de grande!",
  ui_story_1016_10160802_42_dialog_content = "<color=#e8d9bb>¡Bang, bang—!</color>",
  ui_story_1016_10160802_43_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_1016_10160802_44_dialog_content = "¡Una emboscada!",
  ui_story_1016_10160802_45_dialog_content = "Eso suena como un trabajo para un oficial de inteligencia.",
  ui_story_1016_10160802_46_dialog_content = "Lamento haberlos hecho esperar y gracias por abrirnos el camino. Este lugar es perfecto para un enfrentamiento final, ¿no le parece?",
  ui_story_1016_10160802_47_dialog_content = "<size=32>Tch...</size>",
  ui_story_1016_10160802_48_dialog_content = "<size=32>Llegaron aquí incluso antes que nosotros, Leo.</size>",
  ui_story_1016_10160802_49_dialog_content = "<size=32>Es su hogar, debería haberlo visto venir hace mucho tiempo.</size>",
  ui_story_1016_10160802_50_dialog_content = "Bueno, dado que dispararon el primer tiro, es obvio para qué están aquí.",
  ui_story_1016_10160802_51_dialog_content = "Esto nunca fue algo que podríamos haber evitado. Después de todo, solo puede haber un campeón.",
  ui_story_1016_10160802_52_dialog_content = "Me alegra que entiendas. Parece que finalmente podemos empezar a tomar las cosas en serio ahora.",
  ui_story_1016_10160802_53_dialog_content = "Estoy listo para pelear.",
  ui_story_1016_10160901_1_dialog_content = "<color=#e8d9bb>Bang Bang Bang-!</color>",
  ui_story_1016_10160901_2_dialog_content = "Parece que no somos bienvenidos aquí.",
  ui_story_1016_10160901_3_dialog_content = "Me tienen atrapado. Cuidado, Leo, esa chica viene directamente hacia ti.",
  ui_story_1016_10160901_4_dialog_content = "Aún no ha terminado.",
  ui_story_1016_10160901_5_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_1016_10160901_6_dialog_content = "Leo!",
  ui_story_1016_10160901_7_dialog_content = "¡Gracias!",
  ui_story_1016_10160901_8_dialog_content = "¿Quién diría que una niña tan pequeña podría dar un golpe tan serio, eh?",
  ui_story_1016_10160901_9_dialog_content = "La Federación Illumina tiene jóvenes talentos, eso es seguro. No puedo decir que no estoy un poco celoso, sinceramente.",
  ui_story_1016_10160901_10_dialog_content = "Cubitos.",
  ui_story_1016_10160901_11_dialog_content = "¡Agh!",
  ui_story_1016_10160901_12_dialog_content = "(Ella sabe exactamente en qué dirección estoy tratando de moverme. ¿Podría estar manteniéndonos separados?)",
  ui_story_1016_10160901_13_dialog_content = "(Ahora es nuestra oportunidad.)",
  ui_story_1016_10160901_14_dialog_content = "(Usar estos equipos mal adquiridos me deja un mal sabor de boca).",
  ui_story_1016_10160901_15_dialog_content = "(¿Es esto realmente... cómo esas personas quieren que nuestro equipo gane?)",
  ui_story_1016_10160901_16_dialog_content = "(Todavía no tengo suficiente información. Parece que tengo que resolver las cosas sobre la marcha).",
  ui_story_1016_10160901_17_dialog_content = "(¡Empezando con esto!)",
  ui_story_1016_10160901_18_dialog_content = "Sabía que vendrías tras de mí.",
  ui_story_1016_10160901_19_dialog_content = "<size=45>¡¿Qué?!</size>",
  ui_story_1016_10160901_20_dialog_content = "Ya he visto tu estrategia de principio a fin.",
  ui_story_1016_10160901_21_dialog_content = "¡Por favor, no subestimes ni a una sola persona de Crepúsculo!",
  ui_story_1016_10160901_22_dialog_content = "¡¡¡Argh!!!",
  ui_story_1016_10160901_23_dialog_content = "(¡Es poderoso!)",
  ui_story_1016_10160901_24_dialog_content = "(Aunque estoy usando todo este equipo, su ataque logró atravesar mis defensas...)",
  ui_story_1016_10160901_25_dialog_content = "(¡Este hombre es mucho más poderoso de lo que indica mi inteligencia!)",
  ui_story_1016_10160901_26_dialog_content = "Perdóname, pero tengo que derrotarte ahora.",
  ui_story_1016_10160901_27_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_1016_10160901_28_dialog_content = "Yingel! ¡Necesito un refuerzo!",
  ui_story_1016_10160901_29_dialog_content = "¡¿Qué?!",
  ui_story_1016_10160901_30_dialog_content = "Anatoli!",
  ui_story_1016_10160901_31_dialog_content = "¡Ahora es el momento equivocado para perder el enfoque!",
  ui_story_1016_10160901_32_dialog_content = "—!",
  ui_story_1016_10160901_33_dialog_content = "(Esto no es bueno, ahora nos tienen a la defensiva).",
  ui_story_1016_10160901_34_dialog_content = "<color=#e8d9bb>Mientras tanto, en algún otro lugar de Entrañas</color>",
  ui_story_1016_10160901_35_dialog_content = "¿Dónde estamos?",
  ui_story_1016_10160901_36_dialog_content = "No pensé que seguir a ese equipo nos llevaría a un lugar como este...",
  ui_story_1016_10160901_37_dialog_content = "Parece un corredor...",
  ui_story_1016_10160901_38_dialog_content = "Pero es obvio que este lugar ha estado abandonado durante mucho tiempo.",
  ui_story_1016_10160901_39_dialog_content = "¿Yo se, verdad? Aquí no hay nada más que polvo y telarañas.",
  ui_story_1016_10160901_40_dialog_content = "Se siente como si algo aterrador estuviera a punto de saltar y asustarnos...",
  ui_story_1016_10160901_41_dialog_content = "<anim type=Shake><size=45>Grrr...</size></anim>",
  ui_story_1016_10160901_42_dialog_content = "Este sentimiento... ¡Cuidado, todos!",
  ui_story_1016_10160901_43_dialog_content = "¡Algo grande se está cargando contra nosotros!",
  ui_story_1016_10160901_44_dialog_content = "<anim type=Shake><size=50>Grahhhh—!!!</size></anim>",
  ui_story_1016_10160901_45_dialog_content = "¡Ah—!",
  ui_story_1016_10160901_46_dialog_content = "¡¿E-Es una araña gigante?!",
  ui_story_1016_10160901_47_dialog_content = "¡Mantente en guardia! Esa cosa parece fuerte.",
  ui_story_1016_10160901_48_dialog_content = "Terminemos esto rápido. ¡Aún tenemos que encontrar ese cartel!",
  ui_story_1016_10160902_1_dialog_content = "<anim type=Shake><size=50>Grahhhh—!!!</size></anim>",
  ui_story_1016_10160902_2_dialog_content = "Atacamos juntos, Vice!",
  ui_story_1016_10160902_3_dialog_content = "¡Entendido!",
  ui_story_1016_10160902_4_dialog_content = "¡Flor de Hielo—!",
  ui_story_1016_10160902_5_dialog_content = "<anim type=Shake><size=50>Graagh!!!</size></anim>",
  ui_story_1016_10160902_6_dialog_content = "<size=45>¡Ahora!</size>",
  ui_story_1016_10160902_7_dialog_content = "¡Un tiro es todo lo que necesito!",
  ui_story_1016_10160902_8_dialog_content = "<anim type=Shake><size=40>Rugido-!</size></anim>",
  ui_story_1016_10160902_9_dialog_content = "Finalmente lo derribamos...",
  ui_story_1016_10160902_10_dialog_content = "Uf, lo sé.",
  ui_story_1016_10160902_11_dialog_content = "¡Esa cosa fue demasiado dura!",
  ui_story_1016_10160902_12_dialog_content = "¡Los eclipses a los que nos habíamos enfrentado hasta ahora no eran nada comparados con este gran error!",
  ui_story_1016_10160902_13_dialog_content = "En efecto. Un Eclipsite tan poderoso no debería estar en la fase de evaluación en absoluto.",
  ui_story_1016_10160902_14_dialog_content = "Se supone que esto es un programa de entrenamiento. ¿Por qué algo tan peligroso acechaba en las sombras aquí?",
  ui_story_1016_10160902_15_dialog_content = "¿Será que alguien lo puso aquí a propósito?",
  ui_story_1016_10160902_16_dialog_content = "No puedo decir con seguridad. Es posible que hayamos tenido muy mala suerte hasta ahora.",
  ui_story_1016_10160902_17_dialog_content = "Esta Entrañas ha estado abandonada durante mucho tiempo, por lo que es probable que haya Eclipses escondidos por todas partes.",
  ui_story_1016_10160902_18_dialog_content = "Guardemos esta discusión para más adelante.",
  ui_story_1016_10160902_19_dialog_content = "Ya hemos perdido bastante tiempo.",
  ui_story_1016_10160902_20_dialog_content = "Más retrasos, y perderemos cualquier posibilidad de ganar.",
  ui_story_1016_10160902_21_dialog_content = "<color=#e8d9bb>Retumbar-</color>",
  ui_story_1016_10160902_22_dialog_content = "¡¿Qué fue ese sonido?!",
  ui_story_1016_10160902_23_dialog_content = "¿Eclipsites?",
  ui_story_1016_10160902_24_dialog_content = "¿Podrían ser más eclipses?",
  ui_story_1016_10160902_25_dialog_content = "Me temo que no. Escucha atentamente...",
  ui_story_1016_10160902_26_dialog_content = "<color=#e8d9bb>Boom... Estruendo... Bang...</color>",
  ui_story_1016_10160902_27_dialog_content = "Ese es el sonido de disparos y Luminatics, y no parece que provenga de un solo equipo.",
  ui_story_1016_10160902_28_dialog_content = "Tienes razón. ¡Casi suena como si dos equipos diferentes estuvieran peleando entre sí!",
  ui_story_1016_10160902_29_dialog_content = "Nuestro objetivo para esta fase es recuperar el estandarte, no luchar entre nosotros. La única razón por la que podrían estar peleando...",
  ui_story_1016_10160902_30_dialog_content = "¡Es porque deben haber encontrado la pancarta!",
  ui_story_1016_10160902_31_dialog_content = "¿El anuncio?",
  ui_story_1016_10160902_32_dialog_content = "¿Crees que alguien encontró la pancarta?",
  ui_story_1016_10160902_33_dialog_content = "Es posible. Escuchemos más de cerca.",
  ui_story_1016_10160902_34_dialog_content = "<color=#e8d9bb>Boom... Estruendo... Bang...</color>",
  ui_story_1016_10160902_35_dialog_content = "Ese es el sonido de disparos y Luminatics, y no parece que provenga de un solo equipo.",
  ui_story_1016_10160902_36_dialog_content = "¿Podría ser que dos equipos encontraron la bandera al mismo tiempo y ahora están peleando por ella?",
  ui_story_1016_10160902_37_dialog_content = "¡Diría que es una apuesta bastante segura!",
  ui_story_1016_10160902_38_dialog_content = "¡Entonces tenemos que darnos prisa antes de que termine su batalla!",
  ui_story_1016_10160902_39_dialog_content = "¡Aceptar!",
  ui_story_1016_10160902_40_dialog_content = "<color=#e8d9bb>Mientras tanto, en las profundidades de Entrañas</color>",
  ui_story_1016_10160902_41_dialog_content = "¡Objetivo bloqueado!",
  ui_story_1016_10160902_42_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_1016_10160902_43_dialog_content = "¡No me pasarás!",
  ui_story_1016_10160902_44_dialog_content = "(No pensé que serían tan fuertes. Incluso después de perder la ventaja, todavía nos igualan golpe por golpe).",
  ui_story_1016_10160902_45_dialog_content = "(Especialmente ese Oficial de Inteligencia, Anatoli. ¿Cómo entró en la fase de evaluación con tal equipo?)",
  ui_story_1016_10160902_46_dialog_content = "(He estado vigilando a su equipo todo este tiempo. A pesar de tener muchos menos créditos que nosotros, lograron asegurar un equipo aún mejor).",
  ui_story_1016_10160902_47_dialog_content = "(No cuadra. En todo caso, parece que Illumina les está proporcionando en secreto una ventaja injusta).",
  ui_story_1016_10160902_48_dialog_content = "(Pero ya no importa. La Federación Illumina sabe todo sobre nuestra situación en Crepúsculo, por lo que nuestra misión está completa. Todo lo que queda...)",
  ui_story_1016_10160902_49_dialog_content = "¡Joseph!",
  ui_story_1016_10160902_50_dialog_content = "Qué es, Leo?",
  ui_story_1016_10160902_51_dialog_content = "...",
  ui_story_1016_10160902_52_dialog_content = "(Espera, ¿quiere decir...?)",
  ui_story_1016_10160902_53_dialog_content = "Entiendo.",
  ui_story_1016_10160902_54_dialog_content = "(Sus ataques se han vuelto más lentos. ¿Es esto una trampa?)",
  ui_story_1016_10160902_55_dialog_content = "(¡No, es la oportunidad perfecta para nosotros!)",
  ui_story_1016_10160902_56_dialog_content = "Yingel!",
  ui_story_1016_10160902_57_dialog_content = "¡Entendido!",
  ui_story_1016_10160902_58_dialog_content = "Zhao! ¡Atrás y prepárate para defender!",
  ui_story_1016_10160902_59_dialog_content = "¡Entendido!",
  ui_story_1016_10160902_60_dialog_content = "¡No te dejaremos!",
  ui_story_1016_10160902_61_dialog_content = "<color=#e8d9bb>Bang Bang Bang-!</color>",
  ui_story_1016_10160902_62_dialog_content = "¡Maldita sea, está cortando nuestra ruta de escape!",
  ui_story_1016_10160902_63_dialog_content = "¡Ahora, Axelia!",
  ui_story_1016_10160902_64_dialog_content = "Pido disculpas por la demora.",
  ui_story_1016_10160902_65_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_1016_10160902_66_dialog_content = "Urgh—!",
  ui_story_1016_10160902_67_dialog_content = "¡Zhao está caído!",
  ui_story_1016_10160902_68_dialog_content = "¡Quedate cerca de mi! ¡Usaré mi Luminatics para apoyarte!",
  ui_story_1016_10160902_69_dialog_content = "Un ejercicio de futilidad.",
  ui_story_1016_10160902_70_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_1016_10160902_71_dialog_content = "¡Tos... tos, tos, tos!",
  ui_story_1016_10160902_72_dialog_content = "No debería sorprenderme, pero el arma definitiva de Illumina realmente tiene un gran impacto.",
  ui_story_1016_10160902_73_dialog_content = "Parece que ya no tenemos ninguna posibilidad, Leo.",
  ui_story_1016_10160902_74_dialog_content = "En serio. Nos rendimos.",
  ui_story_1016_10160902_75_dialog_content = "Una sabia elección.",
  ui_story_1016_10160902_76_dialog_content = "Recuperar la pancarta, Axelia.",
  ui_story_1016_10160902_77_dialog_content = "Entendido.",
  ui_story_1016_10160902_78_dialog_content = "Y el ganador es-",
  ui_story_1016_10160902_79_dialog_content = "<size=45>¡¡¡Lo hicimos!!!</size>",
  ui_story_1016_10160902_80_dialog_content = "...",
  ui_story_1016_10160902_81_dialog_content = "...",
  ui_story_1016_10160902_82_dialog_content = "...",
  ui_story_1016_10160902_83_dialog_content = ".... ¿Bien?",
  ui_story_1016_10160902_84_dialog_content = "Lamentablemente no.",
  ui_story_1016_10160902_85_dialog_content = "Si hubieras llegado cinco segundos antes, habrías tenido la oportunidad de luchar contra nosotros por el estandarte.",
  ui_story_1016_10160902_86_dialog_content = "¿En realidad? Parece que nos retrasamos demasiado, después de todo.",
  ui_story_1016_10160902_87_dialog_content = "Cómo podría ser esto...?",
  ui_story_1016_10160902_88_dialog_content = "Lo extrañamos tanto...",
  ui_story_1016_10160902_89_dialog_content = "Eso es suficiente. Hicimos nuestro mejor esfuerzo, después de todo.",
  ui_story_1016_10160902_90_dialog_content = "Ahora que se ha decidido el vencedor, no sirve de nada lamentar el resultado.",
  ui_story_1016_10160902_91_dialog_content = "En su lugar, deberíamos esforzarnos por seguir mejorando.",
  ui_story_1016_10160902_92_dialog_content = "Si, tienes razón...",
  ui_story_1016_10160902_93_dialog_content = "Sin más preámbulos, permítanme anunciar los resultados.",
  ui_story_1016_10160902_94_dialog_content = "El ganador de la fase de evaluación es—<color=#FFB400>Equipo Yingel</color>!",
  ui_story_1016_10160902_95_dialog_content = "Además, el premio para el participante de mayor rendimiento en este Ejercicio Militar Conjunto es: Teniente <color=#FFB400>Axelia</color>!",
  ui_story_1016_10160902_96_dialog_content = "¡Felicitaciones a los tres!",
  ui_story_1016_10160902_97_dialog_content = "Gracias.",
  ui_story_1016_10160902_98_dialog_content = "(Nuestra misión finalmente está completa).",
  ui_story_1016_10160902_99_dialog_content = "Gané.",
  ui_story_1016_10160902_100_dialog_content = "Precisamente como se esperaba.",
  ui_story_1016_10160902_101_dialog_content = "(Esos dos no parecen sorprendidos ni emocionados por su victoria).",
  ui_story_1016_10160902_102_dialog_content = "(Sé que no son las personas más expresivas, pero esto parece extraño incluso para ellos).",
  ui_story_1016_10160902_103_dialog_content = "(¿Podría ser que todo esto también sea parte del plan...?)",
  ui_story_1016_10161001_1_dialog_content = "Felicitaciones, teniente Axelia!",
  ui_story_1016_10161001_2_dialog_content = "¡Todos en la Federación Illumina están celebrando tu victoria!",
  ui_story_1016_10161001_3_dialog_content = "Solo estaba cumpliendo con mis deberes.",
  ui_story_1016_10161001_4_dialog_content = "Fuera del camino, todos ustedes—",
  ui_story_1016_10161001_5_dialog_content = "Ella necesita su descanso ahora.",
  ui_story_1016_10161001_6_dialog_content = "Parece que todo Illumina está tratando de estrechar la mano de esa pobre chica ahora.",
  ui_story_1016_10161001_7_dialog_content = "Sí lo hace.",
  ui_story_1016_10161001_8_dialog_content = "Ahora que ha terminado, creo que merezco saber la verdad detrás de tu decisión—",
  ui_story_1016_10161001_9_dialog_content = "La razón por la que perdiste la pelea voluntariamente.",
  ui_story_1016_10161001_10_dialog_content = "Porque ya hemos logrado nuestro objetivo.",
  ui_story_1016_10161001_11_dialog_content = "Capitán Wrath tiene plena conciencia de la situación de Twilight ahora. Con su experiencia en combate, estoy seguro de que sabe exactamente por lo que estamos pasando.",
  ui_story_1016_10161001_12_dialog_content = "Ese conocimiento, a su vez, se propagará rápidamente a través de la red de inteligencia de Illumina antes de llegar a los altos mandos de Lumopolis.",
  ui_story_1016_10161001_13_dialog_content = "Incluso si ese es el caso, sigo pensando que teníamos la obligación de ganar el campeonato para nosotros.",
  ui_story_1016_10161001_14_dialog_content = "Eso nos habría llamado más la atención, lo que podría haberse utilizado para obtener más apoyo para Crepúsculo.",
  ui_story_1016_10161001_15_dialog_content = "Con la coyuntura cada vez más cerca, necesitamos toda la ayuda que podamos obtener.",
  ui_story_1016_10161001_16_dialog_content = "Y aun así elegiste seguir mi decisión de rendirte.",
  ui_story_1016_10161001_17_dialog_content = "Eso es porque confío en tu juicio. Todavía lo hago, de hecho, pero solo quiero saber por qué.",
  ui_story_1016_10161001_18_dialog_content = "Porque esta es nuestra mejor oportunidad de convencer a otros para que nos ayuden.",
  ui_story_1016_10161001_19_dialog_content = "Creo que el equipo de Illumina tuvo algunos trucos bajo la manga todo este tiempo.",
  ui_story_1016_10161001_20_dialog_content = "Los he estado observando desde el momento en que comenzamos el Ejercicio Militar Conjunto, y tantas cosas sobre ellos parecen extrañas.",
  ui_story_1016_10161001_21_dialog_content = "Son fuertes, sin duda, pero parecen menos que satisfechos con su victoria.",
  ui_story_1016_10161001_22_dialog_content = "¿Estás tratando de decir... que hicieron trampa?",
  ui_story_1016_10161001_23_dialog_content = "No tengo ninguna prueba real, pero estoy seguro de ello.",
  ui_story_1016_10161001_24_dialog_content = "El equipo que trajeron a la batalla final era mejor de lo que podían pagar sus créditos.",
  ui_story_1016_10161001_25_dialog_content = "La diferencia no era especialmente notable, al menos no en la superficie, pero definitivamente llevó su fuerza al siguiente nivel.",
  ui_story_1016_10161001_26_dialog_content = "Alguien los ha estado ayudando detrás de escena.",
  ui_story_1016_10161001_27_dialog_content = "¿Crees que podrían ser los altos mandos de Illumina?",
  ui_story_1016_10161001_28_dialog_content = "Es posible, lo que significaría que su victoria estaba asegurada desde el principio.",
  ui_story_1016_10161001_29_dialog_content = "Pero no parece que ganar sea su verdadero objetivo. Creo que debe ser otra cosa.",
  ui_story_1016_10161001_30_dialog_content = "Si es así, entonces ganar era solo un paso necesario en el camino...",
  ui_story_1016_10161001_31_dialog_content = "¿Podría ser?",
  ui_story_1016_10161001_32_dialog_content = "¿Quién sabe?",
  ui_story_1016_10161001_33_dialog_content = "Pero algo me dice que las cosas están a punto de ponerse un poco agitadas.",
  ui_story_1016_10161001_34_dialog_content = "Qué-",
  ui_story_1016_10161001_35_dialog_content = "PlayerName y su equipo lograron anotar cada sorpresa que preparamos para ese equipo de Crepúsculo...",
  ui_story_1016_10161001_36_dialog_content = "¡Esos tres han sido un verdadero dolor en el trasero! ¡¿Están tratando de arruinar nuestros planes o algo así?!",
  ui_story_1016_10161001_37_dialog_content = "Por lo que puedo decir, todo esto ha sido pura coincidencia, pero eso no significa que nuestros planes se hayan frustrado.",
  ui_story_1016_10161001_38_dialog_content = "El equipo de Crepúsculo demostró con éxito su fuerza y nuestras sorpresas resultaron en un descubrimiento bastante inesperado.",
  ui_story_1016_10161001_39_dialog_content = "Estoy seguro de que nuestro maestro estará encantado de conocer a todas las personas poderosas con las que nos hemos encontrado aquí.",
  ui_story_1016_10161001_40_dialog_content = "No solo eso, Caelestite y su equipo derrotaron a Spider Queen mucho más rápido de lo que habíamos anticipado. Esto solo puede significar que su fuerza también ha mejorado mucho.",
  ui_story_1016_10161001_41_dialog_content = "Aún así, nuestras trampas parecen haberles costado la oportunidad de ganar el campeonato.",
  ui_story_1016_10161001_42_dialog_content = "Solo espero que no se molesten demasiado con nosotros...",
  ui_story_1016_10161001_43_dialog_content = "<anim type=Shake>bostezo—</anim>Estoy exhausto.",
  ui_story_1016_10161001_44_dialog_content = "¿Podemos volver ahora? No quiero levantarme de la cama hasta dentro de tres días después de esto...",
  ui_story_1016_10161001_45_dialog_content = "Ten paciencia, Minch.",
  ui_story_1016_10161001_46_dialog_content = "Todavía tenemos trabajo que hacer. No podemos volver todavía.",
  ui_story_1016_10161001_47_dialog_content = "Así es. Todavía tenemos una tarea muy importante que llevar a cabo.",
  ui_story_1016_10161001_48_dialog_content = "<color=#e8d9bb>Ciudad de Gannon, Oficina de Ulises</color>",
  ui_story_1016_10161001_49_dialog_content = "De vuelta en Ciudad Gannon de nuevo.",
  ui_story_1016_10161001_50_dialog_content = "Lo que suceda a continuación será el comienzo de un nuevo capítulo para Illumina.",
  ui_story_1016_10161001_51_dialog_content = "¿Mmm? Qué es esto...",
  ui_story_1016_10161001_52_dialog_content = "Como de costumbre, su plan es perfecto, hasta el más mínimo detalle. Si tan solo hubiera incluido tiempo para que yo recuperara el aliento.",
  ui_story_1016_10161001_53_dialog_content = "Esien, ¿podrías venir a verme, por favor?",
  ui_story_1016_10161001_54_dialog_content = "De inmediato.",
  ui_story_1016_10161001_55_dialog_content = "<color=#e8d9bb>Toc, toc, toc</color>",
  ui_story_1016_10161001_56_dialog_content = "¿Cómo puedo ayudarlo señor?",
  ui_story_1016_10161001_57_dialog_content = "Toma esto y entrégaselo a la Señora. <color=#FFB400>Máscara de hierro</color>... Dile a ella-",
  ui_story_1016_10161001_58_dialog_content = "Estos son mis cambios propuestos a las estructuras de defensa de la ciudad, y requiero su cooperación.",
  ui_story_1016_10161001_59_dialog_content = "Entendido.",
  ui_story_1016_10161001_60_dialog_content = "<color=#e8d9bb>Mientras tanto, en algún lugar de la ciudad de Gannon...</color>",
  ui_story_1016_10161001_61_dialog_content = "Todavía no es el momento, pero la búsqueda de Illumina se vuelve cada vez más frenética.",
  ui_story_1016_10161001_62_dialog_content = "Maldito seas, anciano... ¿Estás tan desesperado por los frutos de mi investigación?",
  ui_story_1016_10161001_63_dialog_content = "Si ese es el caso, entonces tal vez Jade pueda...",
  ui_story_1016_10161001_64_dialog_content = "...",
  ui_story_1016_10161001_65_dialog_content = "Casi lo olvido. Jade probablemente ya se haya ido.",
  ui_story_1016_10161001_66_dialog_content = "¡Negador!",
  ui_story_1016_10161001_67_dialog_content = "Qué es, Reinhardt?",
  ui_story_1016_10161001_68_dialog_content = "¿No recuerdas qué día es hoy?",
  ui_story_1016_10161001_69_dialog_content = "Hoy...?",
  ui_story_1016_10161001_70_dialog_content = "¿Es hora de entregar los resultados de nuestro experimento? ¿O tal vez es el último día de nuestro período de evaluación?",
  ui_story_1016_10161001_71_dialog_content = "¡Error en ambas cuentas!",
  ui_story_1016_10161001_72_dialog_content = "¿De verdad te olvidas? ¡Hoy es tu cumpleaños, Denier!",
  ui_story_1016_10161001_73_dialog_content = "¿Mi cumpleaños? Oh sí, eso es correcto.",
  ui_story_1016_10161001_74_dialog_content = "¿Cómo podrías olvidar tu propio cumpleaños?",
  ui_story_1016_10161001_75_dialog_content = "No es nada especial, de verdad. Aparte de algunos gestos habituales, un cumpleaños en realidad no es diferente a cualquier otro día.",
  ui_story_1016_10161001_76_dialog_content = "Suspiro... Otra respuesta típica de Denier.",
  ui_story_1016_10161001_77_dialog_content = "Eres la única persona que daría una evaluación tan tranquila y racional de tu propio cumpleaños.",
  ui_story_1016_10161001_78_dialog_content = "Pero el hecho de que no te importe no significa que no sea importante para otras personas.",
  ui_story_1016_10161001_79_dialog_content = "¿Ah?",
  ui_story_1016_10161001_80_dialog_content = "Te traje un regalo de cumpleaños.",
  ui_story_1016_10161001_81_dialog_content = "¡Aquí tomaló!",
  ui_story_1016_10161001_82_dialog_content = "¡Chirrido!",
  ui_story_1016_10161001_83_dialog_content = "¡¿Qué es esto?!",
  ui_story_1016_10161001_84_dialog_content = "¡Jajaja! ¡Creo que le gustas, Denier!",
  ui_story_1016_10161001_85_dialog_content = "La encontré en el campo de batalla durante mi último despliegue. No estaba seguro de qué tipo de animal era, ¡pero pensé que era muy lindo!",
  ui_story_1016_10161001_86_dialog_content = "Así que decidí traerla de vuelta y cuidarla por un tiempo. Intenté alimentarla con bollos de aserrín, pero parece que no le gustan.",
  ui_story_1016_10161001_87_dialog_content = "Considérala mi suplente cuando no esté a tu lado, ¿de acuerdo?",
  ui_story_1016_10161001_88_dialog_content = "Estás bromeando, verdad...?",
  ui_story_1016_10161001_89_dialog_content = "Esta es una chinchilla. Los bollos de aserrín no existen en ninguna parte de su dieta natural.",
  ui_story_1016_10161001_90_dialog_content = "Si vas a cuidarlo, debes intentar alimentarlo con heno o granos. Incluso unas pocas zanahorias recorrerían un largo camino.",
  ui_story_1016_10161001_91_dialog_content = "¿Ver? ¡Sabía que serías la persona perfecta para cuidarla!",
  ui_story_1016_10161001_92_dialog_content = "Solo lo sé porque constantemente realizamos experimentos con animales como este. Mantenerlos bien alimentados es solo una parte del proceso.",
  ui_story_1016_10161001_93_dialog_content = "<anim type=Shake><size=45>¡¡¡Chirrido!!!</size></anim>",
  ui_story_1016_10161001_94_dialog_content = "¡Basta, negador! ¡La estás asustando!",
  ui_story_1016_10161001_95_dialog_content = "...",
  ui_story_1016_10161001_96_dialog_content = "<anim type=Shake>Chirrido...</anim>",
  ui_story_1016_10161001_97_dialog_content = "Te prometo que no le haré nada. Ella es un regalo tuyo, después de todo.",
  ui_story_1016_10161001_98_dialog_content = "Entonces, ¿eso significa que aceptas mi regalo?",
  ui_story_1016_10161001_99_dialog_content = "Sí.",
  ui_story_1016_10161001_100_dialog_content = "¡Entonces pensemos en un nombre para ella!",
  ui_story_1016_10161001_101_dialog_content = "Un nombre, eh...",
  ui_story_1016_10161001_102_dialog_content = "Solo llamémosla <color=#FFB400>Jade</color>.",
  ui_story_1016_10161001_103_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_1016_10161001_104_dialog_content = "M-Mis experimentos...",
  ui_story_1016_10161001_105_dialog_content = "Todos se han ido ahora...",
  ui_story_1016_10161001_106_dialog_content = "Por qué, Reinhardt... ¡¿Por qué no has vuelto todavía?!",
  ui_story_1016_10161001_107_dialog_content = "<anim type=Shake><size=45>Chirrido, chirrido—</size></anim>",
  ui_story_1016_10161001_108_dialog_content = "Tú...",
  ui_story_1016_10161001_109_dialog_content = "Considérala mi suplente cuando no esté a tu lado, ¿de acuerdo?",
  ui_story_1016_10161001_110_dialog_content = "¡¿Tú...?!",
  ui_story_1016_10161001_111_dialog_content = "<anim type=Shake><size=45>¡Chirrido! Chirrido-!!!</size></anim>",
  ui_story_1016_10161001_112_dialog_content = "<anim type=Shake>Chirrido...</anim>",
  ui_story_1016_10161001_113_dialog_content = "—!!!",
  ui_story_1016_10161001_114_dialog_content = "¡Chirrido!",
  ui_story_1016_10161001_115_dialog_content = "<anim type=Shake>Chirrido... Chirrido...</anim>",
  ui_story_1016_10161001_116_dialog_content = "Por qué sigues aquí? ¿No sabes que podría partirte el cuello cuando me dé la gana?",
  ui_story_1016_10161001_117_dialog_content = "¿Por qué no te has escapado como ella?",
  ui_story_1016_10161001_118_dialog_content = "<anim type=Shake><size=32>Chirrido...</size></anim>",
  ui_story_1016_10161001_119_dialog_content = "...",
  ui_story_1016_10161001_120_dialog_content = "Olvídalo...",
  ui_story_1016_10161001_121_dialog_content = "Dejaré que te quedes por ahora.",
  ui_story_1016_10161001_122_dialog_content = "Como mínimo, tienes algún valor como sujeto de prueba.",
  ui_story_1016_10161001_123_dialog_content = "Valor, ¿eh?",
  ui_story_1016_10161001_124_dialog_content = "Es cierto que en este mundo todo se mide por su valor.",
  ui_story_1016_10161001_125_dialog_content = "<color=#e8d9bb>susurro, susurro...</color>",
  ui_story_1016_10161001_126_dialog_content = "Denier... Siento movimiento... Ten cuidado...",
  ui_story_1016_10161001_127_dialog_content = "Gruñido...",
  ui_story_1016_10161001_128_dialog_content = "Es... ¡un eclipse!",
  ui_story_1016_10161001_129_dialog_content = "...",
  ui_story_1016_10161001_130_dialog_content = "Baja tu arma. No te hará daño.",
  ui_story_1016_10161001_131_dialog_content = "(Eclipsian) Lady Forsakin, traigo un mensaje del Señor <color=#FFB400>Figerald</color>.",
  ui_story_1016_10161001_132_dialog_content = "(Eclipsiano) Habla.",
  ui_story_1016_10161001_133_dialog_content = "(Eclipsian) \"Para poder acoger adecuadamente a nuestros <color=#FFB400>queridos invitados</color>, debes destruir los sistemas de defensa de Illumina desde adentro\".",
  ui_story_1016_10161001_134_dialog_content = "(Eclipsian) Así que finalmente es hora.",
  ui_story_1016_10161001_135_dialog_content = "<color=#e8d9bb>El día de la exhibición final, 15 minutos antes del inicio del partido</color>",
  ui_story_1016_10161001_136_dialog_content = "Suspiro-",
  ui_story_1016_10161001_137_dialog_content = "No puedo creer que no pudimos ayudar Carleen proteger su título.",
  ui_story_1016_10161001_138_dialog_content = "Yo sé...",
  ui_story_1016_10161001_139_dialog_content = "No parezcas tan derrotado. No hubo nada vergonzoso en nuestra pérdida.",
  ui_story_1016_10161001_140_dialog_content = "Quienes toman parte en el Ejercicio Militar Conjunto se encuentran entre los mejores y más brillantes de sus respectivas facciones. Ver personas que son más fuertes que nosotros no debería sorprendernos.",
  ui_story_1016_10161001_141_dialog_content = "La victoria y la derrota nunca están escritas en piedra. Puede que hayamos fallado, pero ahora sabemos lo fuertes que pueden ser nuestros rivales. En todo caso, nos han dado un nuevo objetivo por el que trabajar.",
  ui_story_1016_10161001_142_dialog_content = "Nada como uno de los poderosos discursos motivacionales de Carleen para levantarnos el ánimo, ¿eh?",
  ui_story_1016_10161001_143_dialog_content = "¿D-De veras?",
  ui_story_1016_10161001_144_dialog_content = "¿Ustedes también vienen a ver el partido?",
  ui_story_1016_10161001_145_dialog_content = "Ey, Leo! No esperaba verte aquí.",
  ui_story_1016_10161001_146_dialog_content = "¿Zhao y Joseph no están contigo?",
  ui_story_1016_10161001_147_dialog_content = "El Ejercicio Militar Conjunto realmente pasó factura a Zhao, por lo que decidió pasar el partido.",
  ui_story_1016_10161001_148_dialog_content = "Joseph se quedó para hacerle compañía mientras los médicos lo examinaban en el hospital.",
  ui_story_1016_10161001_149_dialog_content = "Ustedes realmente parecen estar llevándose bien ahora. ¡Incluso se están cuidando el uno al otro!",
  ui_story_1016_10161001_150_dialog_content = "¡Jajaja! ¡Puede que tengas razón!",
  ui_story_1016_10161001_151_dialog_content = "Trabajar en equipo realmente nos ayudó a conocernos mucho más también.",
  ui_story_1016_10161001_152_dialog_content = "Aunque somos de diferentes facciones, todavía nos respetamos como rivales y compañeros de armas.",
  ui_story_1016_10161001_153_dialog_content = "Una rivalidad amistosa, ya veo...",
  ui_story_1016_10161001_154_dialog_content = "Lo tendré en mente.",
  ui_story_1016_10161001_155_dialog_content = "Oye, ¿no es eso? Yingel? Y Anatoli ¡también!",
  ui_story_1016_10161001_156_dialog_content = "¿Eh? ¿Dónde? ¿Deberíamos ir a saludar?",
  ui_story_1016_10161001_157_dialog_content = "Allí, al lado del asiento del juez.",
  ui_story_1016_10161001_158_dialog_content = "esto no puede ser...",
  ui_story_1016_10161001_159_dialog_content = "¿Fueron los eclipses?",
  ui_story_1016_10161001_160_dialog_content = "La situación es extremadamente grave en este momento.",
  ui_story_1016_10161001_161_dialog_content = "Vamos a investigar.",
  ui_story_1016_10161001_162_dialog_content = "Eso es raro, me pregunto por qué se ven tan serios.",
  ui_story_1016_10161001_163_dialog_content = "Estamos demasiado lejos para escuchar lo que sea que estén hablando.",
  ui_story_1016_10161001_164_dialog_content = "¿Crees que es algo importante?",
  ui_story_1016_10161001_165_dialog_content = "Deberíamos ir a preguntarles nosotros mismos.",
  ui_story_1016_10161001_166_dialog_content = "Para ser un caballero de Lumopolis, pareces bastante preocupado por los asuntos de Illumina. Leo.",
  ui_story_1016_10161001_167_dialog_content = "Perdone mi rudeza, pero siento que debo corregir su declaración. No es Illumina lo que me preocupa, sino la seguridad de Twilight.",
  ui_story_1016_10161001_168_dialog_content = "¿Seguro que ya has oído hablar del gran peligro al que se enfrenta Twilight? Ese peligro se vuelve más inminente con cada día que pasa.",
  ui_story_1016_10161001_169_dialog_content = "Twilight necesita toda la ayuda que pueda obtener si quiere sobrevivir al ataque de los Eclipsites.",
  ui_story_1016_10161001_170_dialog_content = "Tal como está, parece que nuestros amigos de Illumina necesitan ayuda.",
  ui_story_1016_10161001_171_dialog_content = "Además de ser lo correcto, ganar el favor de los futuros líderes de Illumina ahora también nos ayudará a largo plazo.",
  ui_story_1016_10161001_172_dialog_content = "He oído hablar de la situación en Crepúsculo, sí. También soy muy consciente de la presión tuya y de tus camaradas.",
  ui_story_1016_10161001_173_dialog_content = "Informé el asunto a los altos mandos de Lumopolis y solicité su apoyo.",
  ui_story_1016_10161001_174_dialog_content = "Gracias por su preocupación, señora Carleen.",
  ui_story_1016_10161001_175_dialog_content = "Pero a juzgar por nuestras experiencias pasadas, me temo que su solicitud solo caerá en oídos sordos.",
  ui_story_1016_10161001_176_dialog_content = "Lo que Twilight necesita en este momento no son promesas habladas, sino acción. Acción real, resolutiva y solidaria.",
  ui_story_1016_10161001_177_dialog_content = "...",
  ui_story_1016_10161001_178_dialog_content = "De todos modos, haré mi mejor esfuerzo.",
  ui_story_1016_10161001_179_dialog_content = "Twilight te agradece por tus esfuerzos, Lady Carleen. Como yo lo hice.",
  ui_story_1016_10161001_180_dialog_content = "Incluso un solo acto de bondad puede cambiar el rumbo a nuestro favor.",
  ui_story_1016_10161001_181_dialog_content = "Por favor quédense aquí y disfruten el partido, todos. Sólo me iré un minuto.",
  ui_story_1016_10161001_182_dialog_content = "Espera, yo también voy. ¡Como soldado de Illumina, también tengo el deber de ayudarlos si están en problemas!",
  ui_story_1016_10161001_183_dialog_content = "¡Cuenta conmigo también!",
  ui_story_1016_10161001_184_dialog_content = "Y yo, también.",
  ui_story_1016_10161001_185_dialog_content = "¡Excelente! Entonces pongámonos en marcha.",
  ui_story_1016_10161001_186_dialog_content = "¿Hemos descubierto motivos o sospechosos?",
  ui_story_1016_10161001_187_dialog_content = "Todavía están investigando.",
  ui_story_1016_10161001_188_dialog_content = "¿Cuántos de los sistemas de defensa de Gannon City se han visto comprometidos?",
  ui_story_1016_10161001_189_dialog_content = "De los sistemas que hemos revisado hasta ahora, aproximadamente el 16 % de ellos han resultado gravemente dañados o completamente desactivados.",
  ui_story_1016_10161001_190_dialog_content = "Sin embargo, solo hemos examinado la mitad de ellos. El gran tamaño y los complejos pasajes de Gannon City dificultan la evaluación rápida de toda nuestra red de sistemas de defensa.",
  ui_story_1016_10161001_191_dialog_content = "Pero a pesar de que solo una fracción de nuestros sistemas está inactiva, es suficiente para dejar una clara brecha en nuestras defensas. La situación requiere acción inmediata.",
  ui_story_1016_10161001_192_dialog_content = "Un acto de sabotaje tan grave... ¿Podría haber sido obra de Forsakin?",
  ui_story_1016_10161001_193_dialog_content = "Es muy posible.",
  ui_story_1016_10161001_194_dialog_content = "Ven conmigo. Tenemos que informar esto de inmediato...",
  ui_story_1016_10161001_195_dialog_content = "Yingel! Anatoli! ¡Espera!",
  ui_story_1016_10161001_196_dialog_content = "PlayerName? Junto con el teniente Vice y nuestros invitados de Lumopolis?",
  ui_story_1016_10161001_197_dialog_content = "El partido está a punto de comenzar, ¿no es así? ¿Por qué estáis aquí y no en vuestros asientos?",
  ui_story_1016_10161001_198_dialog_content = "Los vimos salir a toda prisa hace un momento. Parecía que algo te estaba molestando.",
  ui_story_1016_10161001_199_dialog_content = "Si necesita ayuda, estaré feliz de ayudar.",
  ui_story_1016_10161001_200_dialog_content = "¿Ofreciendo su ayuda? Eso no es como tú en absoluto, Leo. Además, ¿por qué nuestros asuntos deberían preocupar a un caballero de Lumopolis?",
  ui_story_1016_10161001_201_dialog_content = "Veo. Si vas a hablar tan sin rodeos, entonces también puedo hacer lo mismo.",
  ui_story_1016_10161001_202_dialog_content = "Te ofrezco mi ayuda ahora mismo para asegurar tu apoyo a Crepúsculo en el futuro.",
  ui_story_1016_10161001_203_dialog_content = "¿Y qué te hace estar tan seguro de que necesitamos tu ayuda?",
  ui_story_1016_10161001_204_dialog_content = "Sin mencionar que solo soy un oficial de inteligencia. No represento a Illumina, por lo que no tengo forma de prometer su apoyo a su causa.",
  ui_story_1016_10161001_205_dialog_content = "Soy muy consciente de eso, pero no busco todo el apoyo de Illumina. Solo necesito su apoyo, así como el apoyo de sus aliados.",
  ui_story_1016_10161001_206_dialog_content = "Tus camaradas y tú sois fuertes, y justo ahora eso es lo que Twilight necesita.",
  ui_story_1016_10161001_207_dialog_content = "No solo eso...",
  ui_story_1016_10161001_208_dialog_content = "Con el último partido de exhibición del Ejercicio Militar Conjunto en marcha, todo el mundo está mirando el partido o vigilando el perímetro.",
  ui_story_1016_10161001_209_dialog_content = "Eso me dice que estás un poco falto de personal en este momento. ¿Me equivoco?",
  ui_story_1016_10161001_210_dialog_content = "...",
  ui_story_1016_10161001_211_dialog_content = "Yingel, si algo está realmente mal, no nos quedaríamos de brazos cruzados y no haríamos nada al respecto. Somos aliados, ¿no?",
  ui_story_1016_10161001_212_dialog_content = "Especialmente si Forsakin está involucrado...",
  ui_story_1016_10161001_213_dialog_content = "¡¿Forsakin?!",
  ui_story_1016_10161001_214_dialog_content = "Tú...",
  ui_story_1016_10161001_215_dialog_content = "Lo siento, no quise escuchar a escondidas nuestro camino hacia aquí...",
  ui_story_1016_10161001_216_dialog_content = "Tus poderes realmente son algo más, Caelestite.",
  ui_story_1016_10161001_217_dialog_content = "Lo siento mucho...",
  ui_story_1016_10161001_218_dialog_content = "¿Puedes hablarme de la situación actual, Yingel? Si Forsakin está involucrado, ¡definitivamente no podemos ignorarlo!",
  ui_story_1016_10161001_219_dialog_content = "¡Hemos peleado al lado del otro muchas veces! ¡Puedes confiar en nosotros, te lo prometo!",
  ui_story_1016_10161001_220_dialog_content = "¡Así es!",
  ui_story_1016_10161001_221_dialog_content = "...",
  ui_story_1016_10161001_222_dialog_content = "Tu corazonada es correcta. Necesitamos ayuda ahora más que nunca.",
  ui_story_1016_10161001_223_dialog_content = "Las defensas de Gannon City se han visto gravemente comprometidas. Hemos desplegado la mayor parte de nuestras fuerzas para proteger los sistemas que aún están operativos mientras el resto se inspecciona y repara.",
  ui_story_1016_10161001_224_dialog_content = "Desafortunadamente, no tenemos suficientes personas para hacerlo de manera efectiva. Si estás dispuesto a ayudar, entonces no te rechazaré.",
  ui_story_1016_10161001_225_dialog_content = "Pero si usted o sus aliados encuentran alguna señal de Forsakin o de los otros Wraiths, deben notificarnos de inmediato.",
  ui_story_1016_10161001_226_dialog_content = "Renegados... ¡¿O los otros Espectros?!",
  ui_story_1016_10161001_227_dialog_content = "Así es. Y si logras capturarlos, debes entregarlos a la custodia de Illumina.",
  ui_story_1016_10161001_228_dialog_content = "Tu ciudad, tus reglas.",
  ui_story_1016_10161001_229_dialog_content = "Dijiste que las defensas habían sido comprometidas, ¿verdad?",
  ui_story_1016_10161001_230_dialog_content = "¿Qué tan seriamente fueron dañados?",
  ui_story_1016_10161001_231_dialog_content = "Es difícil de decir en este momento.",
  ui_story_1016_10161001_232_dialog_content = "Normalmente, este nivel de daño no justificaría demasiada preocupación, pero dado el momento y la presencia de Forsakin en Gannon City...",
  ui_story_1016_10161001_233_dialog_content = "Tenemos que estar preparados para cualquier cosa. No podemos darnos el lujo de dejar pasar nada.",
  ui_story_1016_10161001_234_dialog_content = "Entonces estás diciendo que el traidor de Illumina está en algún lugar de la ciudad en este momento, ¿sí?",
  ui_story_1016_10161001_235_dialog_content = "(Si ese es el caso, estoy bastante seguro de que los Eclipsites con los que nos encontramos antes estaban bajo su mando).",
  ui_story_1016_10161001_236_dialog_content = "Todavía no tenemos pistas sobre su paradero, pero es muy probable que todavía esté aquí.",
  ui_story_1016_10161001_237_dialog_content = "Si insiste en ayudarnos, debe permanecer alerta en todo momento.",
  ui_story_1016_10161001_238_dialog_content = "Importante Anatoli, asígnelos a un área que necesite apoyo.",
  ui_story_1016_10161001_239_dialog_content = "De inmediato.",
  ui_story_1016_10161001_240_dialog_content = "Teniente Vice, como alguien que conoce bastante bien Gannon City, estarás a cargo del equipo.",
  ui_story_1016_10161001_241_dialog_content = "¡No es un problema! ¡Usted puede contar conmigo!",
  ui_story_1016_10161001_242_dialog_content = "Su tarea es patrullar los sectores A a C, todos los cuales están cerca de la estación de tren de la ciudad de Gannon. Una vez allí, inspeccione el estado de nuestros sistemas de defensa y anote cualquier daño.",
  ui_story_1016_10161001_243_dialog_content = "Reportar a Yingel o yo mismo una vez que haya terminado su tarea.",
  ui_story_1016_10161001_244_dialog_content = "¡Entendido!",
  ui_story_1016_10161101_1_dialog_content = "El partido final está a punto de comenzar. ¿Estás listo?",
  ui_story_1016_10161101_2_dialog_content = "Por supuesto. Estoy más que listo, de hecho.",
  ui_story_1016_10161101_3_dialog_content = "¿Qué pasa contigo? ¿Tu gente encontró algo?",
  ui_story_1016_10161101_4_dialog_content = "Aún no.",
  ui_story_1016_10161101_5_dialog_content = "Lo más probable es que Forsakin se esconda en el sector subdesarrollado de Gannon City. Ese lugar tiene pasadizos que van en todas direcciones, así que nos llevará tiempo registrarlo a fondo.",
  ui_story_1016_10161101_6_dialog_content = "Aprecio el esfuerzo.",
  ui_story_1016_10161101_7_dialog_content = "No es nada, de verdad.",
  ui_story_1016_10161101_8_dialog_content = "Yo mismo iba a dirigir la búsqueda, pero luego pensé en el Ejercicio Militar Conjunto y me di cuenta de que tenía que quedarme aquí.",
  ui_story_1016_10161101_9_dialog_content = "Tiene sentido. ¿Quién sabe qué tipo de problemas podrían provocar esos tontos chismosos si el Capitán de la Guardia Real no está presente para el partido final?",
  ui_story_1016_10161101_10_dialog_content = "Siempre es el mismo grupo de idiotas interponiéndose en el camino.",
  ui_story_1016_10161101_11_dialog_content = "Pero no importa Ya he asignado fuertes medidas de seguridad en todo el perímetro.",
  ui_story_1016_10161101_12_dialog_content = "Incluso si no estoy aquí, Forsakin estaría en apuros para interrumpir el partido final.",
  ui_story_1016_10161101_13_dialog_content = "Gracias. Con su ayuda, deberíamos poder concluir el Ejercicio Militar Conjunto sin más problemas.",
  ui_story_1016_10161101_14_dialog_content = "<color=#e8d9bb> Mientras tanto, en el laboratorio de Algol</color>",
  ui_story_1016_10161101_15_dialog_content = "¡Aquí vamos! Los ajustes finales ya están completos.",
  ui_story_1016_10161101_16_dialog_content = "Aún así, ese pequeño parece estar volando un poco más lento de lo habitual. ¿Quizás sus partes están comenzando a desgastarse?",
  ui_story_1016_10161101_17_dialog_content = "No te servirá de mucho ahí fuera, así que ¿por qué no me lo dejas a mí por ahora? ¡Lo tendré funcionando como nuevo en poco tiempo!",
  ui_story_1016_10161101_18_dialog_content = "Eso no será necesario.",
  ui_story_1016_10161101_19_dialog_content = "Necesito que este pequeño me ayude a levantarme las mangas.",
  ui_story_1016_10161101_20_dialog_content = "Voy a tener muchos más problemas para luchar sin él.",
  ui_story_1016_10161101_21_dialog_content = "¿Es eso así? Muy bien, hazlo a tu manera.",
  ui_story_1016_10161101_22_dialog_content = "Tendré que arreglarlo una vez que termines tu batalla con Reinhardt.",
  ui_story_1016_10161101_23_dialog_content = "El Cubic Trio ahora está en óptimas condiciones de combate. Úsalos al máximo, Axelia.",
  ui_story_1016_10161101_24_dialog_content = "Tú los creaste, Algol. Los conoces mejor que nadie.",
  ui_story_1016_10161101_25_dialog_content = "Confío en ti, al igual que confío en los Cubos.",
  ui_story_1016_10161101_26_dialog_content = "Jajajaja! Bueno, gracias, querida. Estoy encantado de escucharlo.",
  ui_story_1016_10161101_27_dialog_content = "Te he visto crecer la mayor parte de tu vida, así que es natural que quiera cuidarte.",
  ui_story_1016_10161101_28_dialog_content = "¿Cómo te sientes ahora?",
  ui_story_1016_10161101_29_dialog_content = "Sin anomalías de estado. En espera para el combate.",
  ui_story_1016_10161101_30_dialog_content = "Bueno, eso es bueno.",
  ui_story_1016_10161101_31_dialog_content = "Pero no subestimes Reinhardt solo por eso, Axelia.",
  ui_story_1016_10161101_32_dialog_content = "Aunque las modificaciones de combate de Reinhardt están un poco desactualizadas, sigue siendo una de las Aurorians más poderosas de toda Illumina.",
  ui_story_1016_10161101_33_dialog_content = "Tú también conoces tus limitaciones. Bajo ninguna circunstancia se le permite esforzarse demasiado.",
  ui_story_1016_10161101_34_dialog_content = "Lucharé hasta el final y obtendré la victoria.",
  ui_story_1016_10161101_35_dialog_content = "Nadie te dice qué hacer cuando te propones algo, ¿verdad?",
  ui_story_1016_10161101_36_dialog_content = "Incluso si soy yo quien te dice que no lo hagas, siempre existe la posibilidad de que no me escuches.",
  ui_story_1016_10161101_37_dialog_content = "Escucharé al profesor Ulises.",
  ui_story_1016_10161101_38_dialog_content = "Y trata de escuchar las sugerencias de otras personas de vez en cuando, ¿eh?",
  ui_story_1016_10161101_39_dialog_content = "Pero eso es suficiente lectura por un día. Vete, querida.",
  ui_story_1016_10161101_40_dialog_content = "Ve directamente a la arena.",
  ui_story_1016_10161101_41_dialog_content = "Entendido.",
  ui_story_1016_10161101_42_dialog_content = "Bien. Toda la suerte, Axelia.",
  ui_story_1016_10161101_43_dialog_content = "<color=#e8d9bb>de vuelta en la arena</color>",
  ui_story_1016_10161101_44_dialog_content = "Como juez de hoy, es un gran honor para mí anunciar el inicio del partido final del Ejercicio Militar Conjunto.",
  ui_story_1016_10161101_45_dialog_content = "<size=45>Guauuuuu!!!</size>",
  ui_story_1016_10161101_46_dialog_content = "Primero, demos la bienvenida al Gran Mariscal de Illumina, la Iluminación Iluminada invicta—Reinhardt!",
  ui_story_1016_10161101_47_dialog_content = "<size=45>Reinhardt—! Reinhardt—!</size>",
  ui_story_1016_10161101_48_dialog_content = "¡Vamos a aplaudir a todos los participantes del Ejercicio Militar Conjunto que trabajan arduamente!",
  ui_story_1016_10161101_49_dialog_content = "¡A los ojos del mundo y a los míos, habéis demostrado no solo vuestra fuerza sino también vuestra capacidad para aprender y mejorar!",
  ui_story_1016_10161101_50_dialog_content = "¡No tengo nada más que el mayor respeto por todos ustedes!",
  ui_story_1016_10161101_51_dialog_content = "<size=45>Guauuuuu!!!</size>",
  ui_story_1016_10161101_52_dialog_content = "Y ahora, demos la bienvenida a la retadora de hoy, la participante que superó a sus compañeros y se ganó el privilegio de enfrentarse a Gran Mariscal. Reinhardt En batalla-",
  ui_story_1016_10161101_53_dialog_content = "Axelia, de la Federación Illumina!",
  ui_story_1016_10161101_54_dialog_content = "Axelia—!",
  ui_story_1016_10161101_55_dialog_content = "...",
  ui_story_1016_10161101_56_dialog_content = "Axelia, ¿eh? Nunca he oído hablar de ella... ¡Debe ser muy fuerte!",
  ui_story_1016_10161101_57_dialog_content = "En serio. ¡Incluso a nosotros, la gente de Illumina, nos tomó por sorpresa!",
  ui_story_1016_10161101_58_dialog_content = "¡No sabía que había otra potencia como ella!",
  ui_story_1016_10161101_59_dialog_content = "Combatientes, por favor dense la mano.",
  ui_story_1016_10161101_60_dialog_content = "Axelia...",
  ui_story_1016_10161101_61_dialog_content = "He oído hablar de ti. Tu fuerza es algo para ser admirado.",
  ui_story_1016_10161101_62_dialog_content = "Gracias por tu elogio.",
  ui_story_1016_10161101_63_dialog_content = "¿Has podido descansar lo suficiente antes del partido? El Ejercicio Militar Conjunto terminó ayer, después de todo.",
  ui_story_1016_10161101_64_dialog_content = "No seré fácil contigo solo porque no estás completamente descansado.",
  ui_story_1016_10161101_65_dialog_content = "Me siento perfectamente bien, porque...",
  ui_story_1016_10161101_66_dialog_content = "Todo lo que he hecho fue en preparación para este momento.",
  ui_story_1016_10161101_67_dialog_content = "¡...!",
  ui_story_1016_10161101_68_dialog_content = "Mis órdenes son enfrentarte en la batalla.",
  ui_story_1016_10161101_69_dialog_content = "Agotaré todas las opciones posibles para derrotarte.",
  ui_story_1016_10161101_70_dialog_content = "¿Es eso así? Lo espero entonces.",
  ui_story_1016_10161101_71_dialog_content = "Competir contra un miembro poderoso de la generación más joven siempre es emocionante.",
  ui_story_1016_10161101_72_dialog_content = "...",
  ui_story_1016_10161101_73_dialog_content = "(¿Qué le pasa a esta chica?)",
  ui_story_1016_10161101_74_dialog_content = "(Algo en su expresión es inquietante. No se parece a ningún soldado que haya visto...)",
  ui_story_1016_10161101_75_dialog_content = "(Pero la de un moribundo.)",
  ui_story_1016_10161101_76_dialog_content = "(¿Realmente la he asustado tanto?)",
  ui_story_1016_10161101_77_dialog_content = "(O es otra cosa...?)",
  ui_story_1016_10161101_78_dialog_content = "Ahora bien, si ambos combatientes toman sus lugares, ¡podemos comenzar el combate!",
  ui_story_1016_10161101_79_dialog_content = "...",
  ui_story_1016_10161101_80_dialog_content = "Listo-",
  ui_story_1016_10161101_81_dialog_content = "<size=50><color=#FFB400>Comenzar</color>!</size>",
  ui_story_1016_10161101_82_dialog_content = "—!",
  ui_story_1016_10161101_83_dialog_content = "¡Cubitos!",
  ui_story_1016_10161101_84_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_1016_10161101_85_dialog_content = "¡Qué poderoso ataque!",
  ui_story_1016_10161101_86_dialog_content = "Parece que tendré que hacer todo lo posible también.",
  ui_story_1016_10161101_87_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_1016_10161101_88_dialog_content = "<size=45>¡¡¡Sí!!!</size>",
  ui_story_1016_10161101_89_dialog_content = "Reinhardt—! Reinhardt—!",
  ui_story_1016_10161101_90_dialog_content = "Ataque inicial exitoso. Evaluación de daños: el objetivo no ha sufrido ningún daño visible.",
  ui_story_1016_10161101_91_dialog_content = "La fuerza del enemigo es ligeramente más alta de lo esperado, pero aún dentro de parámetros manejables.",
  ui_story_1016_10161101_92_dialog_content = "Aumento de la salida de Lumina.",
  ui_story_1016_10161101_93_dialog_content = "Tres-",
  ui_story_1016_10161101_94_dialog_content = "(¡¿Está cargando un ataque?!)",
  ui_story_1016_10161101_95_dialog_content = "(¡Necesito detenerla!)",
  ui_story_1016_10161101_96_dialog_content = "Dos-",
  ui_story_1016_10161101_97_dialog_content = "<size=45>¡Atraviesa todo!</size>",
  ui_story_1016_10161101_98_dialog_content = "—!",
  ui_story_1016_10161101_99_dialog_content = "¡Fuera del camino!",
  ui_story_1016_10161101_100_dialog_content = "¡Uno!",
  ui_story_1016_10161101_101_dialog_content = "(Demasiado tarde, ¿eh?)",
  ui_story_1016_10161101_103_dialog_content = "¡Ve, mi lanza!",
  ui_story_1016_10161101_104_dialog_content = "Pido disculpas por la demora.",
  ui_story_1016_10161101_105_dialog_content = "<color=#e8d9bb>Auge-!!!</color>",
  ui_story_1016_10161101_106_dialog_content = "<size=45>Guauuuuu!!!</size>",
  ui_story_1016_10161101_107_dialog_content = "Tos tos...!",
  ui_story_1016_10161101_108_dialog_content = "Cielos... Eso duele mucho más de lo que pensaba.",
  ui_story_1016_10161101_109_dialog_content = "Realmente eres increíble, chico.",
  ui_story_1016_10161101_110_dialog_content = "Segundo ataque exitoso.",
  ui_story_1016_10161101_111_dialog_content = "Valoración de daños: mínimos. Target logró anular la mayor parte del ataque con su propia Luminática.",
  ui_story_1016_10161101_112_dialog_content = "Aumentando aún más la producción de Lumina.",
  ui_story_1016_10161101_113_dialog_content = "(¡¿Aún puede aumentar su producción?!)",
  ui_story_1016_10161101_114_dialog_content = "(Una explosión de Lumina tan poderosa estaría fuera de mis límites. Estaré en problemas si ella consigue un golpe directo...)",
  ui_story_1016_10161101_115_dialog_content = "Tres-",
  ui_story_1016_10161101_116_dialog_content = "<color=#e8d9bb>Grieta-</color>",
  ui_story_1016_10161101_117_dialog_content = "<size=45>!</size>",
  ui_story_1016_10161101_118_dialog_content = "(Espera, son esos <color=#FFB400>grietas</color> apareciendo en su cuerpo?)",
  ui_story_1016_10161101_119_dialog_content = "(¡¿Su cuerpo está empezando a descomponerse?! ¡¿Ese colosal poder suyo tiene un precio tan alto?!)",
  ui_story_1016_10161101_120_dialog_content = "(No tenía idea de que el Comité había creado tal cañón de vidrio...)",
  ui_story_1016_10161101_121_dialog_content = "Detener, Axelia!",
  ui_story_1016_10161101_122_dialog_content = "¡Tu cuerpo no puede soportar la tensión de un ataque como ese!",
  ui_story_1016_10161101_123_dialog_content = "Urgh...",
  ui_story_1016_10161101_124_dialog_content = "Dos...",
  ui_story_1016_10161101_125_dialog_content = "Sin escuchar, ¿eh? Supongo que no tengo elección...",
  ui_story_1016_10161101_126_dialog_content = "¡Juez! ¡Tienes que detener el partido ahora mismo!",
  ui_story_1016_10161101_127_dialog_content = "¡La vida de Axelia estará en peligro a este paso!",
  ui_story_1016_10161101_128_dialog_content = "¿De qué está hablando tu Gran Mariscal?",
  ui_story_1016_10161101_129_dialog_content = "Ni idea. no puedo escucharla...",
  ui_story_1016_10161101_130_dialog_content = "¡Silencio! ¡Continúa el partido!",
  ui_story_1016_10161101_131_dialog_content = "(¡El juez y el público no pueden oírme! Espera...)",
  ui_story_1016_10161101_132_dialog_content = "(Puedo sentir un desmayo <color=#FFB400>Barrera de flujo oscuro</color> entre la arena y las gradas! ¡¿Cuándo apareció esto?!)",
  ui_story_1016_10161101_133_dialog_content = "(¿Podría ser la razón por la que no pueden oírme? ¡Tendré que romperlo para averiguarlo!)",
  ui_story_1016_10161101_134_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_1016_10161101_135_dialog_content = "(¡¿Está cortando mis movimientos?!)",
  ui_story_1016_10161101_136_dialog_content = "Objetivo... Bloqueado...",
  ui_story_1016_10161101_137_dialog_content = "¡Uno!",
  ui_story_1016_10161101_138_dialog_content = "<size=45>¡Pido disculpas por la demora!</size>",
  ui_story_1016_10161101_139_dialog_content = "¡...!",
  ui_story_1016_10161101_140_dialog_content = "<color=#e8d9bb>Auge-!!!</color>",
  ui_story_1016_10161101_141_dialog_content = "<color=#e8d9bb>Mientras tanto, en la ciudad de Gannon</color>",
  ui_story_1016_10161101_142_dialog_content = "Revisé el interior de la estación. No hay problemas allí.",
  ui_story_1016_10161101_143_dialog_content = "Nada en los alrededores tampoco.",
  ui_story_1016_10161101_144_dialog_content = "Lo mismo por mi parte.",
  ui_story_1016_10161101_145_dialog_content = "PlayerName! ¡Encontré algo por aquí!",
  ui_story_1016_10161101_146_dialog_content = "Todo el equipo de defensa en este túnel de mantenimiento ha sido destruido. ¡Aquí también hay signos de actividad de Eclipsite!",
  ui_story_1016_10161101_147_dialog_content = "¡Estoy en camino!",
  ui_story_1016_10161101_148_dialog_content = "<anim type=Shake><size=50>Grahhh-!</size></anim>",
  ui_story_1016_10161101_149_dialog_content = "¡Así que hay eclipses aquí, después de todo!",
  ui_story_1016_10161101_150_dialog_content = "¡No dejes que ninguno de ellos escape!",
  ui_story_1016_10161102_1_dialog_content = "Deben haber llegado a la ciudad de Gannon a estas alturas.",
  ui_story_1016_10161102_2_dialog_content = "Pero no podemos irnos todavía. Todavía no es el momento adecuado.",
  ui_story_1016_10161102_3_dialog_content = "¿Por qué nos escondemos...?",
  ui_story_1016_10161102_4_dialog_content = "¿Por qué no... confías en ellos...",
  ui_story_1016_10161102_5_dialog_content = "¿Confía en ellos?",
  ui_story_1016_10161102_6_dialog_content = "¿Qué pasaría si te dijera que la ciudad de Gannon ya estaba repleta de eclipses?",
  ui_story_1016_10161102_7_dialog_content = "¿O que las personas que gobiernan esta ciudad ya han elegido ponerse del lado de los Eclipsites también?",
  ui_story_1016_10161102_8_dialog_content = "Si te dijera todo eso, ¿seguirías confiando en ellos?",
  ui_story_1016_10161102_9_dialog_content = "...",
  ui_story_1016_10161102_10_dialog_content = "En este momento, el único en quien puedes confiar soy yo.",
  ui_story_1016_10161102_11_dialog_content = "Soy el único que puede salvarte y sacarte de este lugar.",
  ui_story_1016_10161102_12_dialog_content = "...",
  ui_story_1016_10161102_13_dialog_content = "(Eclipsian) Lady Forsakin.",
  ui_story_1016_10161102_14_dialog_content = "(Eclipsiano) Habla.",
  ui_story_1016_10161102_15_dialog_content = "(Eclipsian) Traigo otro mensaje más de Lord Figerald.",
  ui_story_1016_10161102_16_dialog_content = "(Eclipsian) \"Todo está en su lugar ahora. Puedes retirarte\".",
  ui_story_1016_10161102_17_dialog_content = "(Eclipsian) Ya era hora. Hazlo más rápido la próxima vez, tontos.",
  ui_story_1016_10161102_18_dialog_content = "(Eclipsian) Mis disculpas.",
  ui_story_1016_10161102_19_dialog_content = "(Eclipsian) Ya hemos identificado una ruta de escape oculta.",
  ui_story_1016_10161102_20_dialog_content = "(Eclipsian) Puedes usarlo para escapar de Gannon City, si lo deseas.",
  ui_story_1016_10161102_21_dialog_content = "(Eclipsian) ¿Dónde?",
  ui_story_1016_10161102_22_dialog_content = "(Eclipsiano) Aquí.",
  ui_story_1016_10161102_23_dialog_content = "Ya veo... Qué lugar tan remoto para una ruta de escape.",
  ui_story_1016_10161102_24_dialog_content = "Vamos, espécimen.",
  ui_story_1016_10161201_1_dialog_content = "<color=#e8d9bb>Auge-!!!</color>",
  ui_story_1016_10161201_2_dialog_content = "<size=45>Tos, tos, tos!!!</size>",
  ui_story_1016_10161201_3_dialog_content = "Urgh...",
  ui_story_1016_10161201_4_dialog_content = "Tercer ataque... Tos, tos... Exitoso.",
  ui_story_1016_10161201_5_dialog_content = "Evaluación de daños... El objetivo ha sufrido heridas visibles.",
  ui_story_1016_10161201_6_dialog_content = "Continuando la ofensiva.",
  ui_story_1016_10161201_7_dialog_content = "(Pero mis niveles de Lumina son demasiado bajos...)",
  ui_story_1016_10161201_8_dialog_content = "(Necesito tiempo para reunir fuerzas si quiero seguir atacando).",
  ui_story_1016_10161201_9_dialog_content = "(Se va a morir si esto continúa...)",
  ui_story_1016_10161201_10_dialog_content = "(¿Por qué? ¿Por qué está dispuesta a arriesgar su vida solo para derrotarme?)",
  ui_story_1016_10161201_11_dialog_content = "(¿Podría ser que ella está haciendo esto bajo las órdenes de Ulysses? ¡¿El Comité la puso en esto?!)",
  ui_story_1016_10161201_12_dialog_content = "¡Cubitos!",
  ui_story_1016_10161201_13_dialog_content = "—!",
  ui_story_1016_10161201_14_dialog_content = "(Su patrón de ataque ha cambiado. Su Lumina no parece tan fuerte como antes).",
  ui_story_1016_10161201_15_dialog_content = "(Parece que está tratando de reunir fuerzas para su próximo ataque).",
  ui_story_1016_10161201_16_dialog_content = "(Esta podría ser mi oportunidad.)",
  ui_story_1016_10161201_17_dialog_content = "Axelia, ¿por qué estás tan decidido a vencerme?",
  ui_story_1016_10161201_18_dialog_content = "Porque soy capaz de hacerlo. Por eso debo ganar.",
  ui_story_1016_10161201_19_dialog_content = "Realmente no estás respondiendo a mi pregunta.",
  ui_story_1016_10161201_20_dialog_content = "¿Ulysses te ordenó hacer esto?",
  ui_story_1016_10161201_21_dialog_content = "...",
  ui_story_1016_10161201_22_dialog_content = "(Ella no lo niega. Parece que esto es obra del Comité, después de todo).",
  ui_story_1016_10161201_23_dialog_content = "(¿Están realmente tan ansiosos por potenciar sus voces al derrotarme?)",
  ui_story_1016_10161201_24_dialog_content = "(Si realmente está siguiendo sus órdenes, una chica como ella sacrificaría su vida para llevar a cabo su misión sin dudarlo).",
  ui_story_1016_10161201_25_dialog_content = "(Pero en este momento, lo último que necesita el Comité es más autoridad).",
  ui_story_1016_10161201_26_dialog_content = "(Si quiero salvar a esta niña, tendré que someterla y obligarla a rendirse).",
  ui_story_1016_10161201_27_dialog_content = "Aún no ha terminado—",
  ui_story_1016_10161201_28_dialog_content = "<size=45>¡Una abertura!</size>",
  ui_story_1016_10161201_29_dialog_content = "<color=#e8d9bb>¡Clang—!</color>",
  ui_story_1016_10161201_30_dialog_content = "Tú pierdes.",
  ui_story_1016_10161201_31_dialog_content = "<size=50>Wooooo—!!!</size>",
  ui_story_1016_10161201_32_dialog_content = "¡El Gran Mariscal logró dominarla!",
  ui_story_1016_10161201_33_dialog_content = "¿Significa esto que ella ganó?",
  ui_story_1016_10161201_34_dialog_content = "...",
  ui_story_1016_10161201_35_dialog_content = "Rendirse.",
  ui_story_1016_10161201_36_dialog_content = "Entiendo muy bien tu determinación, pero todos tenemos nuestras razones para no querer perder.",
  ui_story_1016_10161201_37_dialog_content = "No quiero lastimarte, y definitivamente no quiero verte lastimarte así.",
  ui_story_1016_10161201_38_dialog_content = "No solo eres más joven que yo, Axelia, también tienes un potencial mucho mayor que yo. El futuro de la Federación Illumina es aún más esperanzador gracias a ti.",
  ui_story_1016_10161201_39_dialog_content = "Así que, por favor, no lo tires todo solo por esto.",
  ui_story_1016_10161201_40_dialog_content = "<anim type=Shake>I...</anim>",
  ui_story_1016_10161201_41_dialog_content = "<anim type=Shake><size=45>¡Yo... aún no he perdido!</size></anim>",
  ui_story_1016_10161201_42_dialog_content = "¡¿?!",
  ui_story_1016_10161201_43_dialog_content = "¡Cubitos!",
  ui_story_1016_10161201_44_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_1016_10161201_45_dialog_content = "Argh... ¡¡¡Tos, tos!!!",
  ui_story_1016_10161201_46_dialog_content = "(¡¿Ese pequeño robot de aspecto débil llevaba un explosivo de alto impacto todo el tiempo?!)",
  ui_story_1016_10161201_47_dialog_content = "(Usando un movimiento tan desesperado, solo para mantenerme a raya... Parece que ella recibió más daño que yo).",
  ui_story_1016_10161201_48_dialog_content = "<anim type=Shake>Duele...</anim>",
  ui_story_1016_10161201_49_dialog_content = "<anim type=Shake>Pero aún puedo pelear...</anim>",
  ui_story_1016_10161201_50_dialog_content = "<anim type=Shake>Nunca me rendiré...</anim>",
  ui_story_1016_10161201_51_dialog_content = "(Ella se ha decidido, ¿no es así? Eso significa que solo hay dos resultados posibles para este partido...)",
  ui_story_1016_10161201_52_dialog_content = "(Si gano, ella muere).",
  ui_story_1016_10161201_53_dialog_content = "(Y si me rindo antes de que intente incinerarme, el consejo se saldrá con la suya... Pero al menos ella seguirá con vida).",
  ui_story_1016_10161201_54_dialog_content = "<anim type=Shake>Yo... llevaré a cabo mis órdenes y... te derrotaré...</anim>",
  ui_story_1016_10161201_55_dialog_content = "<color=#e8d9bb>Grieta-</color>",
  ui_story_1016_10161201_56_dialog_content = "<anim type=Shake>Yo... todavía puedo...</anim>",
  ui_story_1016_10161201_57_dialog_content = "...",
  ui_story_1016_10161201_58_dialog_content = "¿Qué está sucediendo? ¿Por qué no es Reinhardt ¿Defiéndete?",
  ui_story_1016_10161201_59_dialog_content = "¡Déjala, Gran Mariscal!",
  ui_story_1016_10161201_60_dialog_content = "¡Tienes razón! ¿Qué le pasa?",
  ui_story_1016_10161201_61_dialog_content = "Parece que finalmente ha llegado el momento.",
  ui_story_1016_10161201_62_dialog_content = "<color=#e8d9bb>Bzzzzt—</color>",
  ui_story_1016_10161201_63_dialog_content = "Comience la siguiente fase de la operación.",
  ui_story_1016_10161201_64_dialog_content = "¿Y estás seguro de que tienes todo bajo control?",
  ui_story_1016_10161201_65_dialog_content = "Sí.",
  ui_story_1016_10161201_66_dialog_content = "Ella no tiene forma de ganar ahora.",
  ui_story_1016_10161201_67_dialog_content = "<color=#e8d9bb>Mientras tanto, en lo profundo de Gannon City</color>",
  ui_story_1016_10161201_68_dialog_content = "Jadeo... Jadeo...",
  ui_story_1016_10161201_69_dialog_content = "¿Adónde... adónde fueron los eclipses?",
  ui_story_1016_10161201_70_dialog_content = "Nos echaron un vistazo y corrieron como el viento.",
  ui_story_1016_10161201_71_dialog_content = "¿Donde exactamente estamos?",
  ui_story_1016_10161201_72_dialog_content = "Nunca he estado aquí antes. Sabes dónde estamos, Vice?",
  ui_story_1016_10161201_73_dialog_content = "yo tampoco tengo idea...",
  ui_story_1016_10161201_74_dialog_content = "Pero por lo que puedo decir, deberíamos estar bastante cerca del nivel inferior de Gannon City.",
  ui_story_1016_10161201_75_dialog_content = "Teniente Vice? PlayerName? ¿Qué estás haciendo aquí?",
  ui_story_1016_10161201_76_dialog_content = "¿Ah?",
  ui_story_1016_10161201_77_dialog_content = "¿No se supone que deberías estar inspeccionando la estación de tren?",
  ui_story_1016_10161201_78_dialog_content = "C-Coronel Yingel?!",
  ui_story_1016_10161201_79_dialog_content = "Tampoco esperábamos verlos a ustedes dos aquí.",
  ui_story_1016_10161201_80_dialog_content = "Durante nuestra inspección de la estación de tren, encontramos un grupo de Eclipsites al acecho dentro de uno de los túneles de mantenimiento.",
  ui_story_1016_10161201_81_dialog_content = "Es cierto, pero huyeron en cuanto nos vieron. Los seguimos hasta aquí, pero aún no hay señales de ellos.",
  ui_story_1016_10161201_82_dialog_content = "¿Qué pasa contigo? ¿Pensé que ustedes dos estaban patrullando la ciudad?",
  ui_story_1016_10161201_83_dialog_content = "¿Cómo terminaste aquí también?",
  ui_story_1016_10161201_84_dialog_content = "Nos encontramos en una situación similar a la tuya.",
  ui_story_1016_10161201_85_dialog_content = "Esos Eclipsites se estaban comportando de manera extraña, como si no tuvieran ninguna intención de pelear...",
  ui_story_1016_10161201_86_dialog_content = "Debe ser parte de su plan. Tenemos que estar aún más atentos.",
  ui_story_1016_10161201_87_dialog_content = "Estoy de acuerdo en que ellos también deben estar tramando algo.",
  ui_story_1016_10161201_88_dialog_content = "Entonces, ¿deberíamos dejar de perseguirlos por ahora?",
  ui_story_1016_10161201_89_dialog_content = "¡Nunca!",
  ui_story_1016_10161201_90_dialog_content = "Dejar que se vuelvan locos en la ciudad de Gannon solo creará problemas aún mayores.",
  ui_story_1016_10161201_91_dialog_content = "Estamos en los confines más profundos de la ciudad, donde guardamos grandes cantidades de equipos tecnológicos esenciales. Si solo uno de esos dispositivos es destruido por un Eclipsite, será una pérdida catastrófica para la Federación Illumina.",
  ui_story_1016_10161201_92_dialog_content = "¡Tenemos que atraparlos y poner fin a sus planes antes de que se hagan realidad!",
  ui_story_1016_10161201_93_dialog_content = "¿Puedes sentir en qué dirección fueron los eclipses, PlayerName?",
  ui_story_1016_10161201_94_dialog_content = "Puedo intentarlo, pero el diseño complejo de este lugar realmente obstaculiza mis habilidades psíquicas. Solo puedo sentir su dirección general, como mucho.",
  ui_story_1016_10161201_95_dialog_content = "No tengo forma de decir exactamente dónde están ahora.",
  ui_story_1016_10161201_96_dialog_content = "No te preocupes por eso. Solo apúntame en la dirección correcta y encontraré el camino a seguir.",
  ui_story_1016_10161201_97_dialog_content = "Muy bien, aquí voy.",
  ui_story_1016_10161201_98_option_content = "¡Potencia de fuerza!",
  ui_story_1016_10161201_99_dialog_content = "El Darkflow se está reuniendo debajo de nosotros en algún lugar...",
  ui_story_1016_10161201_100_dialog_content = "Espera, ¿eso es...?",
  ui_story_1016_10161201_101_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_1016_10161201_102_dialog_content = "Es <color=#FFB400>Figerald!</color>!!!",
  ui_story_1016_10161201_103_dialog_content = "estas hablando de eso <color=#FFB400>Fantasma</color>?! ¡¿Dónde está?!",
  ui_story_1016_10161201_104_dialog_content = "¡Directamente debajo de nosotros! ¡También está muy cerca!",
  ui_story_1016_10161201_105_dialog_content = "Debajo de nosotros, ¿eh...?",
  ui_story_1016_10161201_106_dialog_content = "(Ya estamos cerca de la parte más profunda de Gannon City. Lo único que se encuentra debajo de nosotros es <color=#FFB400>Guardián Uno</color> Marco principal.)",
  ui_story_1016_10161201_107_dialog_content = "(¿Eclipse va tras Guardian One?)",
  ui_story_1016_10161201_108_dialog_content = "¡Tenemos que darnos prisa! ¡Sígueme!",
  ui_story_1016_10161201_109_dialog_content = "Las personas que construyeron esta maldita Entrañas deben haber tenido gusanos por cerebro.",
  ui_story_1016_10161201_110_dialog_content = "¿Por qué si no habrían hecho que sea tan difícil de navegar?",
  ui_story_1016_10161201_111_dialog_content = "¡Espera ahí mismo, Espectro!",
  ui_story_1016_10161201_112_dialog_content = "¡No hay ningún lugar para que corras! ¡Ríndete y ven en paz!",
  ui_story_1016_10161201_113_dialog_content = "¿Qué? ¡¿Pero cómo podría ser esto?!",
  ui_story_1016_10161201_114_dialog_content = "Se suponía que ya se habían ocupado de todos los aurorianos entrometidos...",
  ui_story_1016_10161201_114X1_dialog_content = "¿Eh? Dónde es <color=#FFB400>ella</color>? ¿Ya se ha ido? <color=#FFB400>allá</color>?",
  ui_story_1016_10161201_115_dialog_content = "¡Malditos sean todos! ¡¿No hay nadie en quien pueda confiar?!",
  ui_story_1016_10161201_116_dialog_content = "¡Detenedlos, desgraciados! ¡Te ordeno!",
  ui_story_1016_10161201_117_dialog_content = "<anim type=Shake><size=45>Graagh!!!</size></anim>",
  ui_story_1016_10161201_118_dialog_content = "¡¡¡Prepárense todos!!!",
  ui_story_1016_10161301_1_dialog_content = "Durante mucho tiempo, constantemente tuve la misma pregunta en mi mente:",
  ui_story_1016_10161301_2_dialog_content = "¿Qué es lo más importante para la Federación Illumina?",
  ui_story_1016_10161301_3_dialog_content = "¿Armas poderosas y sofisticadas?",
  ui_story_1016_10161301_4_dialog_content = "¿Soldados altamente entrenados?",
  ui_story_1016_10161301_5_dialog_content = "¿Tecnología de vanguardia?",
  ui_story_1016_10161301_6_dialog_content = "Lo pensé durante tanto tiempo, pero nunca pude encontrar una respuesta.",
  ui_story_1016_10161301_7_dialog_content = "Pero luego puse un pie en el campo de batalla.",
  ui_story_1016_10161301_8_dialog_content = "Ahí lo vi todo...",
  ui_story_1016_10161301_9_dialog_content = "Perserverancia.",
  ui_story_1016_10161301_10_dialog_content = "Deber.",
  ui_story_1016_10161301_11_dialog_content = "Sacrificio.",
  ui_story_1016_10161301_12_dialog_content = "En ese momento, finalmente me di cuenta de lo que era más importante para la Federación Illumina:",
  ui_story_1016_10161301_13_dialog_content = "Es <color=#FFB400>gente</color>.",
  ui_story_1016_10161301_14_dialog_content = "En la superficie, Illumina no tiene barreras naturales ni tecnología antigua para defenderse de los eclipses.",
  ui_story_1016_10161301_15_dialog_content = "La sangre, el sudor y las lágrimas de innumerables generaciones de nuestra gente es lo que construyó Entrañas.",
  ui_story_1016_10161301_16_dialog_content = "Cuando pasó una generación, la siguiente aceptó el desafío sin vacilar. Así fue durante años y años.",
  ui_story_1016_10161301_17_dialog_content = "La vida es algo tan preciado, pero por el bien de sus camaradas, así como de sus generaciones futuras—",
  ui_story_1016_10161301_18_dialog_content = "Se sacrificaron sin dudarlo.",
  ui_story_1016_10161301_19_dialog_content = "Pero nunca se debe sacrificar una vida por algo tan trivial como una lucha interna.",
  ui_story_1016_10161301_20_dialog_content = "Si no se controla, este tipo de tragedia sin sentido está destinada a repetirse.",
  ui_story_1016_10161301_21_dialog_content = "Incluso si derroto Axelia ahora, esos cobardes solo seguirán tirando a más personas como ella a mi lanza...",
  ui_story_1016_10161301_22_dialog_content = "La única razón por la que quieren que pierda contra Axelia no es más que despojarme de mi título de Gran Mariscal.",
  ui_story_1016_10161301_23_dialog_content = "No puedo decir que el título no sea importante, pero no tanto como para que valga la pena sacrificar la vida de mi gente.",
  ui_story_1016_10161301_24_dialog_content = "En cualquier caso, salvar a esta pobre chica debería ser lo primero.",
  ui_story_1016_10161301_25_dialog_content = "Es por eso...",
  ui_story_1016_10161301_26_dialog_content = "<size=45>Detener-!</size>",
  ui_story_1016_10161301_27_dialog_content = "<anim type=Shake>Nunca me detendré...</anim>",
  ui_story_1016_10161301_28_dialog_content = "<color=#e8d9bb>¡Clang—!</color>",
  ui_story_1016_10161301_29_dialog_content = "Detener, Axelia. <color=#FFB400>me rindo</color>.",
  ui_story_1016_10161301_30_dialog_content = "Si los que están detrás de ti quieren que ganes tanto, déjalos tener lo que quieren.",
  ui_story_1016_10161301_31_dialog_content = "Solo quiero que vivas, y que vivas bien.",
  ui_story_1016_10161301_32_dialog_content = "No como su cañón de cristal, o un activo valioso, sino como un <color=#FFB400>persona</color>.",
  ui_story_1016_10161301_33_dialog_content = "¡...!",
  ui_story_1016_10161301_34_dialog_content = "¿Qué dijo ella hace un momento?",
  ui_story_1016_10161301_35_dialog_content = "Ni idea. Todavía no puedo escucharlos.",
  ui_story_1016_10161301_36_dialog_content = "¿Por qué la Gran Mariscal dejó caer su arma? ¿Está a punto de usar algún tipo de movimiento especial?",
  ui_story_1016_10161301_37_dialog_content = "Me escuchaste hace un momento, ¿no juzgaste?",
  ui_story_1016_10161301_38_dialog_content = "¿Qué... qué fue eso, Gran Mariscal?",
  ui_story_1016_10161301_39_dialog_content = "Así que por fin puedes oírme, ¿eh? Madre mía, qué casualidad.",
  ui_story_1016_10161301_40_dialog_content = "Dije que me rendí. Axelia gana",
  ui_story_1016_10161301_41_dialog_content = "...",
  ui_story_1016_10161301_42_dialog_content = "P-Pero eso es...",
  ui_story_1016_10161301_43_dialog_content = "Deja de perder el tiempo y anuncia ya al ganador.",
  ui_story_1016_10161301_44_dialog_content = "No es educado hacer esperar a una niña.",
  ui_story_1016_10161301_45_dialog_content = "E-Entendido... ¡El partido ha terminado!",
  ui_story_1016_10161301_46_dialog_content = "Gran Mariscal Reinhardt se ha rendido voluntariamente! El ganador del partido de exhibición es—<color=#FFB400>Axelia</color>!",
  ui_story_1016_10161301_47_dialog_content = "<color=#e8d9bb>Mientras tanto, en lo profundo de Gannon City</color>",
  ui_story_1016_10161301_48_dialog_content = "Y después de todos los problemas que me tomó llegar aquí, esas plagas terminaron siguiéndome.",
  ui_story_1016_10161301_48X1_dialog_content = "¿Ya entró? Entonces de acuerdo al plan...",
  ui_story_1016_10161301_49_dialog_content = "¡No te vas a escapar!",
  ui_story_1016_10161301_50_dialog_content = "<color=#e8d9bb>¡Bang, bang, bang!</color>",
  ui_story_1016_10161301_51_dialog_content = "¡Tch! Niña persistente, ¿no es así?",
  ui_story_1016_10161301_52_dialog_content = "Así que se las arregló para llegar aquí, después de todo...",
  ui_story_1016_10161301_53_dialog_content = "Huff... huff... Finalmente alcanzado.",
  ui_story_1016_10161301_53X1_dialog_content = "Caelestite, nos encontramos de nuevo.",
  ui_story_1016_10161301_53X2_dialog_content = "Realmente salvaste el día en el Obelisco del Retorno... Recientemente, parece que no puedo dejar este mal humor en el que siempre estoy.",
  ui_story_1016_10161301_53X3_dialog_content = "¡¿Qué planeas hacer?!",
  ui_story_1016_10161301_53X4_dialog_content = "¡No te dejaré escapar esta vez!",
  ui_story_1016_10161301_53X5_dialog_content = "¡Este es el final de la línea para ti! ¡No hay manera de salir!",
  ui_story_1016_10161301_53X6_dialog_content = "Tsk, tsk, tsk... No te emociones demasiado.",
  ui_story_1016_10161301_54_dialog_content = "Si no me equivoco, este debe ser el nivel más bajo de Gannon City, ¿verdad?",
  ui_story_1016_10161301_55_dialog_content = "Esta bóveda parece extremadamente fortificada. Algo realmente importante debe estar dentro.",
  ui_story_1016_10161301_56_dialog_content = "¡La computadora central de Guardian One se encuentra más allá de esas puertas! ¡No podemos permitir que Eclipse se haga con él!",
  ui_story_1016_10161301_57_dialog_content = "¡¿Qué?! ¡Pero pensé que Guardian One era incluso más bajo que yo!",
  ui_story_1016_10161301_58_dialog_content = "Ese droide es solo uno de los muchos terminales de interfaz de Guardian One.",
  ui_story_1016_10161301_59_dialog_content = "Su cuerpo real, por así decirlo, está aquí.",
  ui_story_1016_10161301_60_dialog_content = "Por lo que he oído, la mayoría de los sistemas de defensa de Illumina son controlados automáticamente por Guardian One.",
  ui_story_1016_10161301_61_dialog_content = "¡Si algo le sucediera a Guardian One, toda Illumina estaría en peligro!",
  ui_story_1016_10161301_62_dialog_content = "<size=45>¡Tsk, tsk, tsk!</size>",
  ui_story_1016_10161301_63_dialog_content = "Tienes toda la razón, mi amigo de pelo blanco.",
  ui_story_1016_10161301_64_dialog_content = "Pero ya es demasiado tarde. Nuestras fuerzas han entrado.",
  ui_story_1016_10161301_65_dialog_content = "¡¿Qué?!",
  ui_story_1016_10161301_66_dialog_content = "¿Cómo es eso posible? Sin la llave—",
  ui_story_1016_10161301_67_dialog_content = "Dejaré que lo averigüen ustedes mismos.",
  ui_story_1016_10161301_68_dialog_content = "Solo un poco más, solo un poco más, y luego el Eclipse no...",
  ui_story_1016_10161301_69_dialog_content = "¡Consíguelos, mis secuaces! ¡No dejes que interfieran!",
  ui_story_1016_10161301_70_dialog_content = "¡Graagh!",
  ui_story_1016_10161301_71_dialog_content = "¡Manténganse juntos, todos! ¡No podemos dejar que se salga con la suya!",
  ui_story_1016_10161302_1_dialog_content = "<color=#e8d9bb>En el sector residencial de Gannon City</color>",
  ui_story_1016_10161302_2_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1016_10161302_3_dialog_content = "Esto no es un laboratorio secreto, ni nada por el estilo. Es solo una residencia ordinaria.",
  ui_story_1016_10161302_4_dialog_content = "¿Hay realmente un pasaje al mundo exterior en algún lugar aquí?",
  ui_story_1016_10161302_5_dialog_content = "Te estas yendo.",
  ui_story_1016_10161302_6_dialog_content = "¿Por qué?",
  ui_story_1016_10161302_7_dialog_content = "Porque este es el final de la línea para nosotros.",
  ui_story_1016_10161302_8_dialog_content = "Illumina se ha dado por vencida con los dos. Ya no tiene sentido quedarse aquí.",
  ui_story_1016_10161302_9_dialog_content = "Así es. El Comité se dio por vencido con nosotros...",
  ui_story_1016_10161302_10_dialog_content = "Yo... ahora recuerdo...",
  ui_story_1016_10161302_11_dialog_content = "¿Que recuerdas?",
  ui_story_1016_10161302_12_dialog_content = "...",
  ui_story_1016_10161302_13_dialog_content = "Todo.",
  ui_story_1016_10161302_14_dialog_content = "Mis recuerdos pasados, esa batalla, la espera interminable...",
  ui_story_1016_10161302_15_dialog_content = "Y la desesperación.",
  ui_story_1016_10161302_16_dialog_content = "Entonces deberías ser plenamente consciente de tu situación en este momento.",
  ui_story_1016_10161302_17_dialog_content = "Todo lo que una vez te perteneció ya no existe.",
  ui_story_1016_10161302_18_dialog_content = "Ya no eres un soldado de Illumina, sino un desertor y un monstruo.",
  ui_story_1016_10161302_19_dialog_content = "Así que si quieres vivir, ayúdame a encontrar la salida.",
  ui_story_1016_10161302_20_dialog_content = "Eso no será necesario.",
  ui_story_1016_10161302_21_dialog_content = "Nunca hubo una ruta de escape en este lugar.",
  ui_story_1016_10161302_22_dialog_content = "...",
  ui_story_1016_10161302_23_dialog_content = "Hmph, así que este fue tu plan todo el tiempo.",
  ui_story_1016_10161302_24_dialog_content = "No puedo decir que estoy sorprendido.",
  ui_story_1016_10161302_25_dialog_content = "Entrega tu investigación y ríndete.",
  ui_story_1016_10161302_26_dialog_content = "Coopera y haré que tu muerte sea lo más rápida e indolora posible.",
  ui_story_1016_10161302_27_dialog_content = "Fuera del camino.",
  ui_story_1016_10161302_28_dialog_content = "Parece que no estás dispuesto a cooperar, después de todo.",
  ui_story_1016_10161302_29_dialog_content = "Hazlo a tu manera entonces. ¡Soldados!",
  ui_story_1016_10161302_30_dialog_content = "¿Qué... qué crees que estás haciendo?",
  ui_story_1016_10161302_31_dialog_content = "Aprovecharlas.",
  ui_story_1016_10161302_32_dialog_content = "¡Entendido!",
  ui_story_1016_10161302_33_dialog_content = "Que presuntuoso.",
  ui_story_1016_10161302_34_dialog_content = "<size=45>¡Defender!</size>",
  ui_story_1016_10161302_35_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1016_10161302_36_dialog_content = "...",
  ui_story_1016_10161302_37_dialog_content = "No desperdicies tu fuerza.",
  ui_story_1016_10161302_38_dialog_content = "Para derribarte, mis soldados han sido equipados con un nuevo tipo de armadura experimental, cortesía del Consejo Científico.",
  ui_story_1016_10161302_39_dialog_content = "Serás derrotado mucho antes de que desaparezcan sus efectos.",
  ui_story_1016_10161302_40_dialog_content = "Parece que ustedes tienen algo de cerebro, después de todo.",
  ui_story_1016_10161302_41_dialog_content = "Aun así, no sois más que una manada de tontos.",
  ui_story_1016_10161302_42_dialog_content = "<color=#e8d9bb>Mientras tanto, en la arena</color>",
  ui_story_1016_10161302_43_dialog_content = "¿Gané?",
  ui_story_1016_10161302_44_dialog_content = "Así es. Eres el vencedor.",
  ui_story_1016_10161302_45_dialog_content = "Ahora detente antes de que te lastimes aún más.",
  ui_story_1016_10161302_46_dialog_content = "...",
  ui_story_1016_10161302_47_dialog_content = "¿Qué? ¿Escuché eso bien?",
  ui_story_1016_10161302_48_dialog_content = "El legendario Reinhardt realmente perder la pelea?!",
  ui_story_1016_10161302_49_dialog_content = "¿Pero cómo?",
  ui_story_1016_10161302_50_dialog_content = "esto no puede ser...",
  ui_story_1016_10161302_51_dialog_content = "<size=45>¡¿A qué demonios están jugando ustedes?!</size>",
  ui_story_1016_10161302_52_dialog_content = "Reinhardt entregarse? ¡Ni siquiera estaba peleando en su mejor momento!",
  ui_story_1016_10161302_53_dialog_content = "¡¿Qué tipo de tácticas sucias y encubiertas usaron ustedes, viejos cobardes, para que esto sucediera?!",
  ui_story_1016_10161302_54_dialog_content = "Por favor, tenga en cuenta sus palabras, Comandante. Barton. ¡Este es un partido oficial, después de todo!",
  ui_story_1016_10161302_55_dialog_content = "Cálmate, Barton.",
  ui_story_1016_10161302_56_dialog_content = "Este no es el momento de dejar que la ira se apodere de ti.",
  ui_story_1016_10161302_57_dialog_content = "Si esta fue la decisión de Reinhardt, estoy seguro de que tenía una buena razón para hacerlo.",
  ui_story_1016_10161302_58_dialog_content = "Confío en su juicio, así que vamos a preguntarle sobre eso más tarde.",
  ui_story_1016_10161302_59_dialog_content = "<size=45>¡¿Me estás tomando el pelo?!</size>",
  ui_story_1016_10161302_60_dialog_content = "<size=45>¿Es así realmente como termina? ¡¿Qué clase de pelea es esta?!</size>",
  ui_story_1016_10161302_61_dialog_content = "¡Silencio, todos!",
  ui_story_1016_10161302_62_dialog_content = "¡Debo pedirte que respetes el resultado de este partido!",
  ui_story_1016_10161302_63_dialog_content = "¡Qué escena tan animada!",
  ui_story_1016_10161302_64_dialog_content = "Creo que es casi la hora ahora.",
  ui_story_1016_10161302_65_dialog_content = "¡Oficial Ulises! ¡Tengo un mensaje urgente para ti!",
  ui_story_1016_10161302_66_dialog_content = "Adelante.",
  ui_story_1016_10161302_67_dialog_content = "La situación es...",
  ui_story_1016_10161302_68_dialog_content = "Sí, sí... Muy bien, entonces.",
  ui_story_1016_10161302_69_dialog_content = "Puede continuar con sus deberes ahora.",
  ui_story_1016_10161302_70_dialog_content = "¡Sí señor!",
  ui_story_1016_10161302_71_dialog_content = "May ¿Le pido prestado su micrófono, juez?",
  ui_story_1016_10161302_72_dialog_content = "Pero señor, esto...",
  ui_story_1016_10161302_73_dialog_content = "Tengo un anuncio urgente para todos—",
  ui_story_1016_10161302_74_dialog_content = "Es un mensaje del Comité.",
  ui_story_1016_10161302_75_dialog_content = "V-Muy bien, entonces...",
  ui_story_1016_10161302_76_dialog_content = "Ejem... Atención a todos. Tengo una orden de emergencia para declarar.",
  ui_story_1016_10161302_77_dialog_content = "¿Qué? ¿Una orden de emergencia?",
  ui_story_1016_10161302_78_dialog_content = "¿Qué orden de emergencia?",
  ui_story_1016_10161302_79_dialog_content = "Esos viejos tontos definitivamente están tramando algo.",
  ui_story_1016_10161302_80_dialog_content = "Están podridos hasta la médula, hasta el último de ellos.",
  ui_story_1016_10161302_81_dialog_content = "Tengo un mal presentimiento sobre esto...",
  ui_story_1016_10161302_82_dialog_content = "Hace unos momentos, el Comité recibió un informe impactante.",
  ui_story_1016_10161302_83_dialog_content = "Los Oficiales de Inteligencia del Comité encontraron señales de Forsakin y Helios, dos de los criminales más buscados de Illumina, aquí en Gannon City. Gracias a sus esfuerzos, hemos descubierto su paradero actual.",
  ui_story_1016_10161302_84_dialog_content = "¡Imposible! ¡He estado a cargo de encontrarlos todo este tiempo! ¡Mis soldados son los que han estado recorriendo toda la ciudad en busca de esos dos!",
  ui_story_1016_10161302_85_dialog_content = "¡Mis patrullas y yo aún no hemos encontrado ninguna señal de Forsakin!",
  ui_story_1016_10161302_86_dialog_content = "Eso solo prueba que tus esfuerzos no fueron lo suficientemente buenos.",
  ui_story_1016_10161302_87_dialog_content = "Mientras perseguían a Forsakin, los oficiales de inteligencia también descubrieron un pasadizo secreto que no se encuentra en ninguno de nuestros mapas de la ciudad.",
  ui_story_1016_10161302_88_dialog_content = "Para nuestra inmensa sorpresa, ese túnel... Conduce directamente a la zona residencial del Gran Mariscal Reinhardt.",
  ui_story_1016_10161302_89_dialog_content = "No queriendo renunciar al elemento sorpresa, los oficiales de inteligencia continuaron sigilosamente siguiéndola, solo para descubrirla entrando con arrogancia a la casa de Reinhardt.",
  ui_story_1016_10161302_90_dialog_content = "<size=45>¡¿Qué?! ¡¡Eso es imposible!!</size>",
  ui_story_1016_10161302_91_dialog_content = "...",
  ui_story_1016_10161302_92_dialog_content = "Así que este fue tu plan todo el tiempo...",
  ui_story_1016_10161302_93_dialog_content = "¡¿Me estás tomando el pelo?!",
  ui_story_1016_10161302_94_dialog_content = "Malditos cabrones...",
  ui_story_1016_10161302_95_dialog_content = "¡Siempre rápido para calumniar a otras personas, aunque te niegues a poner un pie en el campo de batalla!",
  ui_story_1016_10161302_96_dialog_content = "Por su bien, será mejor que tenga pruebas suficientes para respaldar estas afirmaciones descabelladas.",
  ui_story_1016_10161302_97_dialog_content = "Así es. Mi espada no tolerará a una sola persona que manche la reputación de mi camarada.",
  ui_story_1016_10161302_98_dialog_content = "Por favor cálmense, todos ustedes.",
  ui_story_1016_10161302_99_dialog_content = "Entiendo que este desarrollo es bastante alarmante. El Comité tampoco quería creerlo al principio.",
  ui_story_1016_10161302_100_dialog_content = "Pero, de hecho, tenemos pruebas innegables de irregularidades. Cada patrulla puede dar fe de la verdad de este asunto.",
  ui_story_1016_10161302_101_dialog_content = "En este momento, esos dos criminales buscados están tratando desesperadamente de escapar de Gannon City.",
  ui_story_1016_10161302_102_dialog_content = "¡Esto es absurdo! ¡Me voy!",
  ui_story_1016_10161302_103_dialog_content = "¡¿Se supone que debemos sentarnos aquí y esperar pacientemente a que nos ataquen?!",
  ui_story_1016_10161302_104_dialog_content = "Por favor, no entren en pánico, todos; hemos asignado seguridad adicional al perímetro de la arena. Su seguridad es la mayor preocupación del Comité.",
  ui_story_1016_10161302_105_dialog_content = "Sin más demora, el Comité ha llegado a una decisión:",
  ui_story_1016_10161302_106_dialog_content = "Reinhardt, está bajo sospecha de ayudar e instigar al enemigo.",
  ui_story_1016_10161302_107_dialog_content = "Como tal, el Comité ha optado por despojarlo de su condición de Gran Mariscal.",
  ui_story_1016_10161302_108_dialog_content = "Además, debe someterse completamente a nuestra investigación de sus posibles delitos.",
  ui_story_1016_10161401_1_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_1016_10161401_2_dialog_content = "¡Intrusión ilegal detectada, intrusión ilegal detectada!",
  ui_story_1016_10161401_2X1_dialog_content = "¡Alguien está ahí! ¡Fuera de mi camino, Espectro!",
  ui_story_1016_10161401_3_dialog_content = "Tsk, muestra un poco de respeto, e incluso podría considerar darte una muerte rápida.",
  ui_story_1016_10161401_4_dialog_content = "En cuanto a los demás...",
  ui_story_1016_10161401_5_dialog_content = "Ve.",
  ui_story_1016_10161401_6_dialog_content = "<anim type=Shake><size=45>Grahhh-!</size></anim>",
  ui_story_1016_10161401_7_dialog_content = "¡Flor de hielo! Extendido-!",
  ui_story_1016_10161401_8_dialog_content = "<anim type=Shake>Graaah...</anim>",
  ui_story_1016_10161401_9_dialog_content = "(Eclipsian) Nuestras fuerzas están disminuyendo, Lord Figerald...",
  ui_story_1016_10161401_10_dialog_content = "Tu única obligación es morir. Así que date prisa.",
  ui_story_1016_10161401_11_dialog_content = "Solo dale suficiente tiempo, ¡y estos aurorianos seguramente perderán!",
  ui_story_1016_10161401_12_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_1016_10161401_24_dialog_content = "Jejeje... <size=50>Jajajaja</size>!",
  ui_story_1016_10161401_26_dialog_content = "¡Te mostrare! ¡Les mostraré a todos que todavía merezco mi lugar!",
  ui_story_1016_10161401_27_dialog_content = "(¿Su lugar? ¿Significa esto que está siendo expulsado de Eclipse?)",
  ui_story_1016_10161401_28_dialog_content = "Mira a tu alrededor.",
  ui_story_1016_10161401_29_dialog_content = "Tus secuaces han sido casi erradicados.",
  ui_story_1016_10161401_30_dialog_content = "Eres el comandante de nada ahora.",
  ui_story_1016_10161401_31_dialog_content = "¿Comandante de nada, dices?",
  ui_story_1016_10161401_32_dialog_content = "¿Y qué hay de eso? ¡Soy más que suficiente para aplastarlos bichos insignificantes!",
  ui_story_1016_10161401_33_dialog_content = "<anim type=Shake><size=45>¡¡¡Hrrrrgh—!!!</size></anim>",
  ui_story_1016_10161401_34_dialog_content = "¿Que esta haciendo?",
  ui_story_1016_10161401_35_dialog_content = "¡Cuidado, PlayerName!",
  ui_story_1016_10161401_36_dialog_content = "<anim type=Shake><size=45>¡Tsk, tsk, tsk!</size></anim>",
  ui_story_1016_10161401_37_dialog_content = "¡Ha pasado tanto tiempo desde que desaté mi verdadero poder!",
  ui_story_1016_10161401_38_dialog_content = "He estado guardando este ataque para esa desdichada chica de Northland...",
  ui_story_1016_10161401_39_dialog_content = "¡Pero usarlo en tus tontos debería ser igual de satisfactorio!",
  ui_story_1016_10161401_40_dialog_content = "¡Acobardaos ante mí, gusanos!",
  ui_story_1016_10161401_41_dialog_content = "¡Aprovecha este momento final para hacer las paces con tus dioses!",
  ui_story_1016_10161402_0X1_dialog_content = "Malditas alimañas... En realidad me empujaron a tal...",
  ui_story_1016_10161402_0X2_dialog_content = "¡Morir! Todos ustedes deben morir!!!",
  ui_story_1016_10161402_0X3_dialog_content = "¡Cuidado! ¡Todavía le queda algo de poder!",
  ui_story_1016_10161402_0X4_dialog_content = "¡Y tú, Caelestita! Deberías haber muerto hace mucho tiempo!!!",
  ui_story_1016_10161402_0X5_dialog_content = "¡Rápido! Volver, PlayerName!",
  ui_story_1016_10161402_0X6_dialog_content = "¡No intentes detenerme!",
  ui_story_1016_10161402_0X7_dialog_content = "¡Ah!",
  ui_story_1016_10161402_0X8_dialog_content = "<color=#e8d9bb>¡Zoom!</color>",
  ui_story_1016_10161402_0X9_dialog_content = "(Qué-?!)",
  ui_story_1016_10161402_0X10_dialog_content = "(No la toques.)",
  ui_story_1016_10161402_0X11_dialog_content = "(¿Lo has encontrado? ¿Qué estás esperando? Salgamos de aquí—)",
  ui_story_1016_10161402_0X12_dialog_content = "(Quítale las manos de encima.)",
  ui_story_1016_10161402_0X13_dialog_content = "(No digas que no te lo advertí).",
  ui_story_1016_10161402_1_dialog_content = "<anim type=Shake><size=45>¡Argh!</size></anim>",
  ui_story_1016_10161402_2_dialog_content = "<anim type=Shake>Malditos... ¡Aurorianos asquerosos...!</anim>",
  ui_story_1016_10161402_3_dialog_content = "<anim type=Shake>¡Malditos! ¡Maldita sea Forsakin, y maldita sea todo Eclipse también!</anim>",
  ui_story_1016_10161402_4_dialog_content = "<anim type=Shake>¡Todos ustedes pueden irse al infierno!</anim>",
  ui_story_1016_10161402_4X1_dialog_content = "Urgh...",
  ui_story_1016_10161402_5_dialog_content = "¡Vice!",
  ui_story_1016_10161402_6_dialog_content = "<anim type=Shake>¡Si debo morir, me niego a morir a manos de ustedes, insectos sin valor!</anim>",
  ui_story_1016_10161402_7_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_1016_10161402_7X1_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_1016_10161402_8_dialog_content = "—!!!",
  ui_story_1016_10161402_9_dialog_content = "Hablas demasiado.",
  ui_story_1016_10161402_10_dialog_content = "¡Tos tos!",
  ui_story_1016_10161402_10X1_dialog_content = "¡Vice! ¡¿Estás bien?!",
  ui_story_1016_10161402_11_dialog_content = "¡Rápidamente! Podría estar fingiendo la muerte para hacernos bajar la guardia.",
  ui_story_1016_10161402_12_dialog_content = "Iré a echar un vistazo.",
  ui_story_1016_10161402_13_dialog_content = "...",
  ui_story_1016_10161402_14_dialog_content = "El enemigo está completamente inconsciente. Deberíamos estar bien por ahora.",
  ui_story_1016_10161402_15_dialog_content = "Logró sobrevivir, no sin antes perder el conocimiento.",
  ui_story_1016_10161402_15X1_dialog_content = "(¿Mi ataque de hace un momento fue realmente tan poderoso?)",
  ui_story_1016_10161402_15X2_dialog_content = "(¿Podría esto significar...)",
  ui_story_1016_10161402_16_dialog_content = "Entonces permítanme sacarlo de su miseria y vengar las vidas de todos los que fueron víctimas de él y los de su especie.",
  ui_story_1016_10161402_17_dialog_content = "¡Esperar! ¡No lo mates!",
  ui_story_1016_10161402_18_dialog_content = "¿Eh? ¿Por qué no?",
  ui_story_1016_10161402_19_dialog_content = "¿No recuerdas lo que te dije antes? Si se captura a Forsakin o cualquier otro Espectro, deben ser entregados a la custodia de Illumina.",
  ui_story_1016_10161402_20_dialog_content = "... Lo que usted diga entonces.",
  ui_story_1016_10161402_21_dialog_content = "Pero dado el estado en el que se encuentra, dudo que responda a sus preguntas pronto.",
  ui_story_1016_10161402_22_dialog_content = "Esa no es tu preocupación. Nos encargaremos de eso.",
  ui_story_1016_10161402_23_dialog_content = "¿Por qué perdonarlo, Yingel? ¡Ya ha lastimado a tanta gente!",
  ui_story_1016_10161402_24_dialog_content = "Por favor calmate, PlayerName. Sé que estás molesto, también.",
  ui_story_1016_10161402_25_dialog_content = "Pero tenga en cuenta esto: en la historia de Astra, no hemos realizado una investigación significativa sobre los Wraiths.",
  ui_story_1016_10161402_26_dialog_content = "Además de ser un tema de investigación valioso, Figerald también podría proporcionarnos información crucial sobre <color=#FFB400>Eclipse</color>.",
  ui_story_1016_10161402_27_dialog_content = "Lo más importante, fue capaz de entrar en este tipo de lugar sin encontrar resistencia...",
  ui_story_1016_10161402_28_dialog_content = "Esto significa que confiaba en quien le proporcionó la clave y otra información.",
  ui_story_1016_10161402_29_dialog_content = "Es muy probable que este informante sea un traidor dentro de la Federación Illumina.",
  ui_story_1016_10161402_30_dialog_content = "Haces puntos válidos, pero todavía no puedo estar de acuerdo contigo.",
  ui_story_1016_10161402_31_dialog_content = "Nuestra falta de conocimiento de los Wraiths podría ser una indicación de que no tenemos forma de mantenerlos bajo control. Ni siquiera la Federación Illumina.",
  ui_story_1016_10161402_32_dialog_content = "¿Qué harás, si finalmente vuelve en sí y escapa de tu custodia?",
  ui_story_1016_10161402_33_dialog_content = "La Federación hará todo lo que esté a su alcance para evitar que eso suceda.",
  ui_story_1016_10161402_34_dialog_content = "Pero no puedes garantizar que no suceda.",
  ui_story_1016_10161402_35_dialog_content = "Tampoco podemos abandonar la perspectiva de promover nuestra causa solo porque los riesgos son demasiado grandes.",
  ui_story_1016_10161402_36_dialog_content = "...",
  ui_story_1016_10161402_37_dialog_content = "Entonces haz lo que quieras.",
  ui_story_1016_10161402_38_dialog_content = "Vice, Anatoli, PlayerName, ¿cuáles son sus pensamientos sobre esto?",
  ui_story_1016_10161402_39_dialog_content = "No tengo ninguna objeción.",
  ui_story_1016_10161402_40_dialog_content = "Si esta es su decisión, Coronel Yingel, entonces tampoco tengo objeciones.",
  ui_story_1016_10161402_41_option_content = "No hay objeciones aquí.",
  ui_story_1016_10161402_42_option_content = "No estoy de acuerdo.",
  ui_story_1016_10161402_43_dialog_content = "Carleen tiene razón, Yingel. No podemos arriesgarnos a que Figerald se escape.",
  ui_story_1016_10161402_44_dialog_content = "Tomó todo lo que teníamos para derribarlo esta vez. ¡No se sabe qué hará si lo dejamos vivir!",
  ui_story_1016_10161402_45_dialog_content = "¿Tienes idea de cuántas vidas ha arruinado...",
  ui_story_1016_10161402_46_dialog_content = "Entiendo su frustración, pero debo insistir en mi propio curso de acción.",
  ui_story_1016_10161402_47_dialog_content = "Confía en mí, así como en tus aliados en Illumina.",
  ui_story_1016_10161402_48_dialog_content = "Muchos de los nuestros dieron su vida para ayudarnos a aprender más sobre los eclipses. ¡Me niego a que sus sacrificios sean en vano!",
  ui_story_1016_10161402_49_dialog_content = "...",
  ui_story_1016_10161402_50_dialog_content = "...",
  ui_story_1016_10161402_51_dialog_content = "Está bien.",
  ui_story_1016_10161402_52_dialog_content = "Gracias por comprender.",
  ui_story_1016_10161402_53_dialog_content = "Me pondré en contacto con el Departamento de Inteligencia y haré que detengan e interroguen a este Wraith de inmediato.",
  ui_story_1016_10161402_54_dialog_content = "Pero nuestro trabajo aún no ha terminado. Me temo que su cohorte está detrás de esa puerta.",
  ui_story_1016_10161402_55_dialog_content = "Efectivamente, y dentro tenemos a Guardian One...",
  ui_story_1016_10161402_56_dialog_content = "Bueno, no importa quién o qué sea nuestro próximo enemigo, ¡déjalos hacer lo peor!",
  ui_story_1016_10161402_57_dialog_content = "Solo espero que todo esto termine pronto.",
  ui_story_1016_10161402_58_dialog_content = "(no se como Axelia está haciendo. ¿Está ella... todavía viva?)",
  ui_story_1016_10161402_59_dialog_content = "(Estábamos listos para llevar a cabo nuestra misión a toda costa, pero cuando la vi alejarse...)",
  ui_story_1016_10161402_60_dialog_content = "¡Manténganse alerta, todos!",
  ui_story_1016_10161402_61_dialog_content = "¡Hay algo justo detrás de esa puerta!",
  ui_story_1016_10161402_62_dialog_content = "(¡Esta aura...!)",
  ui_story_1016_10161402_63_dialog_content = "<color=#e8d9bb>Retumbar-</color>",
  ui_story_1016_10161402_64_dialog_content = "<color=#e8d9bb>Bwee—Bwee—</color>",
  ui_story_1016_10161402_65_dialog_content = "Prepárate para otra batalla, PlayerName!",
  ui_story_1016_10161402_66_dialog_content = "¡Mantente en formación! ¡No muestres ninguna debilidad!",
  ui_story_1016_10161402_67_dialog_content = "<color=#e8d9bb>Auge-</color>",
  ui_story_1016_10161402_68_dialog_content = "¡Alguien está saliendo!",
  ui_story_1016_10161402_69_dialog_content = "Es eso...?!",
  ui_story_1016_10161402_70_dialog_content = "(Vi una figura extraña saliendo de detrás de las puertas).",
  ui_story_1016_10161402_71_dialog_content = "(Fue solo por un momento, pero sentí un Darkflow aún más poderoso que el de Figerald saliendo de su cuerpo).",
  ui_story_1016_10161402_72_dialog_content = "(Ya habíamos usado la mayor parte de nuestra fuerza luchando contra Figerald).",
  ui_story_1016_10161402_73_dialog_content = "(En ese momento, el extraño podría habernos derrotado cuando quisiera...)",
  ui_story_1016_10161402_74_dialog_content = "Cuidado, Vice! ¡Vienen directamente hacia ti!",
  ui_story_1016_10161402_75_dialog_content = "¡¿Eh?!",
  ui_story_1016_10161402_76_dialog_content = "Después de estar en mundos separados durante tanto tiempo...",
  ui_story_1016_10161402_77_dialog_content = "Por fin, por fin nos volvemos a encontrar.",
  ui_story_1016_10161402_78_dialog_content = "¿Quién eres?",
  ui_story_1016_10161402_79_dialog_content = "(Ella se parece a una <color=#FFB400>Fantasma</color>!)",
  ui_story_1016_10161402_80_dialog_content = "(Ni siquiera sé su nombre, así que por qué...)",
  ui_story_1016_10161402_81_dialog_content = "(¿Por qué parece tan <color=#FFB400>familiar</color>?!)",
  ui_story_1016_10161402_82_dialog_content = "¡Esperar! ¡No te vayas!",
  ui_story_1016_10161402_83_dialog_content = "Pronto lo sabrás todo...",
  ui_story_1016_10161402_84_dialog_content = "En el futuro.",
  ui_story_1016_10161402_85_dialog_content = "¡Detenla!",
  ui_story_1016_10161402_86_dialog_content = "ella lleva <color=#FFB400>la consola central de Guardian One</color>!",
  ui_story_1016_10161402_87_dialog_content = "¡Brillar!",
  ui_story_1016_10161402_88_dialog_content = "Carece de sentido.",
  ui_story_1016_10161402_89_dialog_content = "¡¿N-No tuvo ningún efecto?!",
  ui_story_1016_10161402_90_dialog_content = "¡Después de ella! ¡No podemos dejarla escapar con la consola principal de Guardian One!",
  ui_story_1016_10161402_91_dialog_content = "<color=#e8d9bb>Mientras tanto, en la ciudad de Gannon</color>",
  ui_story_1016_10161402_92_dialog_content = "No podrían haber llegado muy lejos. Busca en todos los rincones del lugar.",
  ui_story_1016_10161402_93_dialog_content = "¡Sí señor!",
  ui_story_1016_10161402_94_dialog_content = "...",
  ui_story_1016_10161402_95_dialog_content = "Son terriblemente persistentes.",
  ui_story_1016_10161402_96_dialog_content = "A este paso, es solo cuestión de tiempo antes de que nos encuentren aquí.",
  ui_story_1016_10161402_97_dialog_content = "Tenemos que irnos.",
  ui_story_1016_10161402_98_dialog_content = "Este lugar... Se parece a Entrañas 80.",
  ui_story_1016_10161402_99_dialog_content = "Ya no tiene sentido decir cosas así.",
  ui_story_1016_10161402_100_dialog_content = "¿Crees que sí? Quizás tengas razón...",
  ui_story_1016_10161402_101_dialog_content = "En aquel entonces... No éramos diferentes de lo que somos ahora. Atrapado en Entrañas, rodeado de enemigos...",
  ui_story_1016_10161402_102_dialog_content = "Solo entonces... Estábamos en contra de los Eclipsites... no de nuestros camaradas...",
  ui_story_1016_10161402_103_dialog_content = "Hay realmente alguna diferencia?",
  ui_story_1016_10161402_104_dialog_content = "En lo que a mí respecta, cualquiera que se interponga en mi camino es el enemigo.",
  ui_story_1016_10161402_105_dialog_content = "Aurorian, Eclipsites, no me importa.",
  ui_story_1016_10161402_106_dialog_content = "No... No es lo mismo en absoluto.",
  ui_story_1016_10161402_107_dialog_content = "Los eclipses eran nuestros enemigos naturales... ¿Pero nuestros camaradas? Simplemente no saben por lo que hemos pasado.",
  ui_story_1016_10161402_108_dialog_content = "Todo esto es un malentendido.",
  ui_story_1016_10161402_109_dialog_content = "No hay malentendidos, Helios.",
  ui_story_1016_10161402_110_dialog_content = "Esto es lo que realmente son: tontos ignorantes y ciegamente obedientes.",
  ui_story_1016_10161402_111_dialog_content = "...",
  ui_story_1016_10161402_112_dialog_content = "¿Qué... qué te pasó... para que terminaras así?",
  ui_story_1016_10161402_113_dialog_content = "¿Cuándo se volvieron tan claros tus pensamientos?",
  ui_story_1016_10161402_114_dialog_content = "Poco a poco, en los últimos días...",
  ui_story_1016_10161402_115_dialog_content = "Al principio, sentí que mi mente... estaba cubierta por una espesa niebla...",
  ui_story_1016_10161402_116_dialog_content = "Pero ahora... las cosas están un poco más claras...",
  ui_story_1016_10161402_117_dialog_content = "¿En serio?",
  ui_story_1016_10161402_118_dialog_content = "Parece que los resultados de mi experimento han superado con creces mis expectativas.",
  ui_story_1016_10161402_119_dialog_content = "Todavía... no me has contestado...",
  ui_story_1016_10161402_120_dialog_content = "Dime... por qué nos vamos...",
  ui_story_1016_10161402_121_dialog_content = "Déjame... ayudarte a regresar a Illumina.",
  ui_story_1016_10161402_122_dialog_content = "Que inmaduro.",
  ui_story_1016_10161402_123_dialog_content = "¿De verdad esperabas que fuéramos bienvenidos aquí? ¿Qué te dio exactamente esa idea?",
  ui_story_1016_10161402_124_dialog_content = "Esta es nuestra casa.",
  ui_story_1016_10161402_125_dialog_content = "Nuestros amigos y Reinhardt, nos están esperando.",
  ui_story_1016_10161402_126_dialog_content = "Reinhardt no es amigo mio Ella me abandonó hace mucho tiempo, al igual que te abandonó a ti.",
  ui_story_1016_10161402_127_dialog_content = "En todos los niveles, Illumina está completamente corrupta.",
  ui_story_1016_10161402_128_dialog_content = "Tu ira...",
  ui_story_1016_10161402_129_dialog_content = "Tu odio... te consumirá...",
  ui_story_1016_10161402_130_dialog_content = "¿Ah, de verdad? Entonces déjame contarte la verdad detrás de todo.",
  ui_story_1016_10161402_131_dialog_content = "Si aún quieres creer en ellos después, entonces no hay nada que te ayude.",
  ui_story_1016_10161402_132_dialog_content = "¿La verdad?",
  ui_story_1016_10161402_133_dialog_content = "Sí, y la verdad es que todos éramos armas creadas en aras de los intereses de Illumina. tú, yo e incluso Reinhardt.",
  ui_story_1016_10161402_134_dialog_content = "El Comité nos sometió a un programa de modificación experimental llamado Proyecto: Sol Artificial para mejorar nuestra fuerza.",
  ui_story_1016_10161402_135_dialog_content = "Nuestra batalla en Entrañas 80 fue solo una prueba para nosotros, sus valiosos sujetos de prueba.",
  ui_story_1016_10161402_136_dialog_content = "Nuestra supuesta misión estaba condenada desde el principio.",
  ui_story_1016_10161402_137_dialog_content = "¡¿Pero cómo podría ser eso?!",
  ui_story_1016_10161402_138_dialog_content = "Tanta gente... ¡Tantos de nosotros morimos en esa batalla!",
  ui_story_1016_10161402_139_dialog_content = "Ese fue su objetivo todo el tiempo.",
  ui_story_1016_10161402_140_dialog_content = "El Comité quería que peleáramos una batalla sin esperanza para que pudiéramos desbloquear todo nuestro potencial.",
  ui_story_1016_10161402_141_dialog_content = "La mayoría de nosotros fuimos considerados fracasados durante el proceso de modificación, y morimos en la batalla o terminamos de la misma manera que tú.",
  ui_story_1016_10161402_142_dialog_content = "Por qué... ¿Por qué harían esto?",
  ui_story_1016_10161402_143_dialog_content = "Ya te lo dije, por el bien de su experimento. Project Artificial Sun tuvo una tasa de éxito abismalmente baja con la modificación de sus sujetos de prueba.",
  ui_story_1016_10161402_144_dialog_content = "La única forma de medir realmente su éxito era forzarnos a una batalla brutal contra los Eclipsites y ver quién sobrevivía.",
  ui_story_1016_10161402_145_dialog_content = "Reinhardt fue el único que se consideró un éxito.",
  ui_story_1016_10161402_146_dialog_content = "El resto de nosotros fuimos arrojados a un lado como basura.",
  ui_story_1016_10161402_147_dialog_content = "¿Aún no entiendes? Entonces déjame hacerlo aún más simple, no eres una persona a los ojos de la Federación Illumina. Eres un arma, una herramienta y nada más.",
  ui_story_1016_10161402_148_dialog_content = "No dejes que te engañen con su charla sobre parentesco y país. Si quieres sobrevivir, tienes que empezar a pensar por ti mismo.",
  ui_story_1016_10161402_149_dialog_content = "No hay lugar en su mundo para armas rotas como las nuestras.",
  ui_story_1016_10161402_150_dialog_content = "Ya lo has visto por ti mismo, ¿no? La forma en que todos sacan sus armas con solo verte.",
  ui_story_1016_10161402_151_dialog_content = "...",
  ui_story_1016_10161402_152_dialog_content = "Tú... Tú mismo lo dijiste... Son unos ignorantes...",
  ui_story_1016_10161402_153_dialog_content = "Por eso... tenemos que hacerles... ver las cosas claras...",
  ui_story_1016_10161402_154_dialog_content = "Y acaba con la gente... que los mantiene ciegos.",
  ui_story_1016_10161402_155_dialog_content = "Eso pondrá a Illumina en el camino correcto nuevamente.",
  ui_story_1016_10161402_156_dialog_content = "Necesitamos solucionar el problema... no revolcarnos en nuestro odio.",
  ui_story_1016_10161402_157_dialog_content = "Así que todavía crees todas sus mentiras, después de todo.",
  ui_story_1016_10161402_158_dialog_content = "No. Dejé de creer hace mucho tiempo.",
  ui_story_1016_10161402_159_dialog_content = "Esto es solo... mi propia respuesta al problema. Me dijiste que pensara por mí mismo, ¿verdad?",
  ui_story_1016_10161402_160_dialog_content = "Si quieres irte, no te detendré.",
  ui_story_1016_10161402_161_dialog_content = "Pero yo me quedo aquí. Necesito saber toda la verdad... y evitar que envíen a más personas a la muerte.",
  ui_story_1016_10161402_162_dialog_content = "no lo permitiré",
  ui_story_1016_10161402_163_dialog_content = "Eres mi sujeto de prueba. Hasta que ya no me sirvas absolutamente para nada, te vienes conmigo.",
  ui_story_1016_10161402_164_dialog_content = "No hay otra opción para ti.",
  ui_story_1016_10161402_165_dialog_content = "¡Aqui! ¡Encontré los objetivos!",
  ui_story_1016_10161402_166_dialog_content = "Tch.",
  ui_story_1016_10161402_167_dialog_content = "Plagas molestas.",
  ui_story_1016_10161402_168_dialog_content = "!",
  ui_story_1016_10161402_169_dialog_content = "¡No vaciles! ¡Sus ataques no funcionarán contigo!",
  ui_story_1016_10161402_170_dialog_content = "¿Aún no te rindes, eh...?",
  ui_story_1016_10161402_171_dialog_content = "Por supuesto que no. Hemos tomado todas las medidas para garantizar que el criminal más buscado de Illumina no se escape.",
  ui_story_1016_10161402_172_dialog_content = "¡Fuera del camino!",
  ui_story_1016_10161402_173_dialog_content = "¡Concéntrense, hombres! ¡No dejes que se escapen esta vez!",
  ui_story_1016_10161402_174_dialog_content = "¡Escuadrón A, forma una línea defensiva y avanza hacia el enemigo!",
  ui_story_1016_10161402_175_dialog_content = "¡Escuadrón B, flánquelos por detrás y córteles la huida!",
  ui_story_1016_10161402_176_dialog_content = "¡Sí señor!",
  ui_story_1016_10161402_177_dialog_content = "Que molesto.",
  ui_story_1016_10161402_178_dialog_content = "¿Que estas esperando? Vamos, espécimen.",
  ui_story_1016_10161402_179_dialog_content = "No...",
  ui_story_1016_10161402_180_dialog_content = "Yo... los mantendré a raya tanto como pueda. Tómese ese tiempo para escapar.",
  ui_story_1016_10161402_181_dialog_content = "¡¿Qué crees que estás haciendo?!",
  ui_story_1016_10161402_182_dialog_content = "<size=45>¡Volver!</size>",
  ui_story_1016_10161402_183_dialog_content = "¡Derríbalo!",
  ui_story_1016_10161402_184_dialog_content = "<color=#e8d9bb>Auge-!!!</color>",
  ui_story_1016_10161402_185_dialog_content = "¡Tos, tos, tos—!",
  ui_story_1016_10161402_186_dialog_content = "¡Él derribó el techo y se atrapó de nuestro lado!",
  ui_story_1016_10161402_187_dialog_content = "Corre, Denier.",
  ui_story_1016_10161402_188_dialog_content = "Esto es lo último que puedo hacer por ti.",
  ui_story_1016_10161402_189_dialog_content = "¡Estúpido!",
  ui_story_1016_10161402_190_dialog_content = "¡Increíble idiota!",
  ui_story_1016_10161402_191_dialog_content = "Correr...",
  ui_story_1016_10161402_192_dialog_content = "Ayudando a Forsakin a escapar, veo...",
  ui_story_1016_10161402_193_dialog_content = "No importa. Después de todo-",
  ui_story_1016_10161402_194_dialog_content = "Fuiste nuestro objetivo principal todo el tiempo.",
  ui_story_1016_10161402_195_dialog_content = "apoderarse de él.",
  ui_story_1016_10161402_196_dialog_content = "¡Sí señor!",
  ui_story_1016_10161402_197_dialog_content = "Quedarse atrás...",
  ui_story_1016_10161402_198_dialog_content = "No quiero lastimar a mis camaradas...",
  ui_story_1016_10161402_199_dialog_content = "¡Baja tu arma!",
  ui_story_1016_10161402_200_dialog_content = "<size=45>¡Quedarse atrás!</size>",
  ui_story_1016_10161402_201_dialog_content = "¡¡¡Argh!!!",
  ui_story_1016_10161402_202_dialog_content = "No tiene sentido resistirse.",
  ui_story_1016_10161402_203_dialog_content = "¡...!",
  ui_story_1016_10161402_204_dialog_content = "¡Sujétalo!",
  ui_story_1016_10161402_205_dialog_content = "Nuestro objetivo principal ha sido capturado.",
  ui_story_1016_10161402_206_dialog_content = "El objetivo secundario escapó, pero no importa.",
  ui_story_1016_10161402_207_dialog_content = "La misión está completa.",
  ui_story_1016_10161402_208_dialog_content = "Ahora a esperar la señal del oficial Ulises.",
  ui_story_1016_10161402_209_dialog_content = "<color=#e8d9bb>de vuelta en la arena</color>",
  ui_story_1016_10161402_210_dialog_content = "Teniente Axelia, por favor ayude al Comité deteniendo Reinhardt.",
  ui_story_1016_10161402_211_dialog_content = "...",
  ui_story_1016_10161402_212_dialog_content = "Entendido...",
  ui_story_1016_10161402_213_dialog_content = "Detener, Axelia! Tu cuerpo ya está—",
  ui_story_1016_10161402_214_dialog_content = "¡...!",
  ui_story_1016_10161402_215_dialog_content = "¡Axelia!",
  ui_story_1016_10161402_216_dialog_content = "Hmm... ¿Ya se ha esforzado demasiado?",
  ui_story_1016_10161402_217_dialog_content = "Pensé que duraría un poco más.",
  ui_story_1016_10161402_218_dialog_content = "Pero no cambia nada. Soldados, arrestadla.",
  ui_story_1016_10161402_219_dialog_content = "¡Sí señor!",
  ui_story_1016_10161402_220_dialog_content = "¡Alto, todos!",
  ui_story_1016_10161402_221_dialog_content = "Ulises! ¡Ya deberías saber que las acciones del Consejo están completamente fuera de lugar!",
  ui_story_1016_10161402_222_dialog_content = "¡Ustedes, viejos cobardes, han estado tratando de mantenernos bajos por mucho tiempo!",
  ui_story_1016_10161402_223_dialog_content = "¿No sabían idiotas que Reinhardt ¡¿Fue la única persona que nos impidió ir tras de ti?!",
  ui_story_1016_10161402_224_dialog_content = "Pero ahora... ¡Ahora sí que lo has hecho!",
  ui_story_1016_10161402_225_dialog_content = "Tiene que decirnos exactamente qué está pasando, Gran Mariscal.",
  ui_story_1016_10161402_226_dialog_content = "Si realmente están conspirando contra nosotros, lucharemos a tu lado con todo lo que tenemos.",
  ui_story_1016_10161402_227_dialog_content = "Por favor, cálmense, Comandantes. El Comité sólo ha estado actuando de acuerdo con nuestras reglas.",
  ui_story_1016_10161402_228_dialog_content = "Todos ustedes, por otro lado, han estado doblando esas reglas para su propio beneficio personal. Si alguien está actuando fuera de lugar, eres tú.",
  ui_story_1016_10161402_229_dialog_content = "Si tiene alguna objeción a las decisiones del Comité, puede presentarla por escrito en lugar de recurrir a la violencia y la intimidación.",
  ui_story_1016_10161402_230_dialog_content = "Hijo de un...",
  ui_story_1016_10161402_231_dialog_content = "Ahora debo pedirles a todos ustedes que muestren un adecuado sentido del decoro. De lo contrario, el Comité no tendrá más remedio que etiquetarlos como los cómplices sospechosos de Reinhardt.",
  ui_story_1016_10161402_232_dialog_content = "Suficiente.",
  ui_story_1016_10161402_233_dialog_content = "Esto no tiene nada que ver con ellos.",
  ui_story_1016_10161402_234_dialog_content = "¿Reinhardt?",
  ui_story_1016_10161402_235_dialog_content = "Déjame defenderme, Wrath.",
  ui_story_1016_10161402_236_dialog_content = "Quiero ver si puedo probar legalmente mi inocencia a todos Illumina.",
  ui_story_1016_10161402_237_dialog_content = "...",
  ui_story_1016_10161402_238_dialog_content = "Está bien.",
  ui_story_1016_10161402_239_dialog_content = "Gracias...",
  ui_story_1016_10161402_240_dialog_content = "Estoy dejando todo en tus manos ahora.",
  ui_story_1016_10161402_241_dialog_content = "Incluyendo a esa chica. Está en muy mal estado, así que consíguele atención médica de inmediato.",
  ui_story_1016_10161402_242_dialog_content = "...",
  ui_story_1016_10161402_243_dialog_content = "Gran Mariscal...?!",
  ui_story_1016_10161402_244_dialog_content = "Gran Mariscal...",
  ui_story_1016_10161402_245_dialog_content = "...",
  ui_story_1016_10161402_246_dialog_content = "No necesitas preocuparte más, Ulises.",
  ui_story_1016_10161402_247_dialog_content = "Estoy de acuerdo con su investigación.",
  ui_story_1016_10161402_248_dialog_content = "Gracias por su cooperación, Reinhardt.",
  ui_story_1016_10161402_249_dialog_content = "llévatela.",
  ui_story_1016_10161402_250_dialog_content = "¡Sí señor!",
  ui_story_1016_10161501_1_dialog_content = "Eso concluye mi informe.",
  ui_story_1016_10161501_2_dialog_content = "Así que un Wraith no identificado robó <color=#FFB400>Guardián uno</color> consola central, y no se encuentra por ninguna parte...",
  ui_story_1016_10161501_3_dialog_content = "Coronel Yingel, esto es un grave abandono del deber.",
  ui_story_1016_10161501_4_dialog_content = "Me disculpo y estoy dispuesto a aceptar cualquier castigo por mi fracaso.",
  ui_story_1016_10161501_5_dialog_content = "Además de las personas que estaban allí en ese momento, ¿alguien más sabe sobre este asunto?",
  ui_story_1016_10161501_6_dialog_content = "No señor. El asunto debe ser conocido sólo por nosotros.",
  ui_story_1016_10161501_7_dialog_content = "Todos los que estuvieron presentes durante el incidente están reunidos aquí ahora mismo. En ningún momento tuvieron oportunidad de divulgar esta información.",
  ui_story_1016_10161501_8_dialog_content = "Hmm... Entendido.",
  ui_story_1016_10161501_9_dialog_content = "Coronel Yingel, por la presente queda relevado de su misión. Yo personalmente me haré cargo de encontrar y capturar al Wraith no identificado.",
  ui_story_1016_10161501_10_dialog_content = "Descansa un poco por ahora. El Comité tendrá órdenes para usted más adelante.",
  ui_story_1016_10161501_11_dialog_content = "En cuanto al resto de ustedes, por favor no revelen ninguna información sobre este asunto a nadie más.",
  ui_story_1016_10161501_12_dialog_content = "¡Sí señor!",
  ui_story_1016_10161501_13_dialog_content = "¡Sí señor!",
  ui_story_1016_10161501_14_dialog_content = "Entendido.",
  ui_story_1016_10161501_15_dialog_content = "Entiendo. Compartir esta información solo nos complicaría las cosas.",
  ui_story_1016_10161501_16_dialog_content = "Mantendré mis labios sellados también.",
  ui_story_1016_10161501_17_dialog_content = "Gracias a todos por su cooperación.",
  ui_story_1016_10161501_18_dialog_content = "Eso es todo por ahora.",
  ui_story_1016_10161501_19_dialog_content = "Espera, ¿puedo preguntar cómo? Axelia ¿está haciendo?",
  ui_story_1016_10161501_20_dialog_content = "Teniente Axelia se esforzó demasiado durante el partido final y actualmente se encuentra en un estado inconsciente.",
  ui_story_1016_10161501_21_dialog_content = "Ella está siendo tratada en el centro médico, y el Capitán Wrath la está vigilando.",
  ui_story_1016_10161501_22_dialog_content = "¿En realidad? ella todavía está...",
  ui_story_1016_10161501_23_dialog_content = "¡Tengo que ir a verla ahora mismo!",
  ui_story_1016_10161501_24_dialog_content = "En ese caso, me voy a informar al Gran Mariscal. Reinhardt.",
  ui_story_1016_10161501_25_dialog_content = "PlayerName, teniente Vice, Dama Carleen, Leo... Aquí es donde nos separamos.",
  ui_story_1016_10161501_26_dialog_content = "No hay necesidad de eso.",
  ui_story_1016_10161501_27_dialog_content = "¿Mmm?",
  ui_story_1016_10161501_28_dialog_content = "Reinhardt ha sido despojada de su rango. Por el momento, la Federación Illumina no tiene Gran Mariscal.",
  ui_story_1016_10161501_29_dialog_content = "<size=45>¡¿Qué?!</size>",
  ui_story_1016_10161501_30_option_content = "¡¿Estás bromeando no?!",
  ui_story_1016_10161501_31_dialog_content = "¿Qué pasó? ¿Por qué solo escuchamos sobre esto ahora?",
  ui_story_1016_10161501_32_option_content = "¡¿Qué pasó?!",
  ui_story_1016_10161501_33_dialog_content = "Por qué era Reinhardt removida de su cargo?",
  ui_story_1016_10161501_34_dialog_content = "Por favor cálmense todos.",
  ui_story_1016_10161501_35_dialog_content = "Entiendo que esto es muy repentino, pero sucedió mientras perseguías a los Eclipsites escondidos en Gannon City. Naturalmente, no tenías forma de saberlo hasta ahora.",
  ui_story_1016_10161501_36_dialog_content = "Nuestras patrullas encontraron señales de Forsakin y Helios, dos de los criminales más buscados de Illumina, aquí en Gannon City.",
  ui_story_1016_10161501_37_dialog_content = "Se han estado escondiendo en la ciudad durante los últimos días, esperando su oportunidad de interrumpir el Ejercicio Militar Conjunto.",
  ui_story_1016_10161501_38_dialog_content = "Desafortunadamente, el lugar en el que se escondían no era otro que la casa de Reinhardt.",
  ui_story_1016_10161501_39_dialog_content = "Después de que los arrestáramos, el Comité colocó Reinhardt bajo sospecha de conspirar con el enemigo y la despojó de su rango.",
  ui_story_1016_10161501_40_dialog_content = "¡¿Pero cómo podría ser eso posible?!",
  ui_story_1016_10161501_41_dialog_content = "Gran Mariscal Reinhardt ¡Nunca se pondría del lado del enemigo!",
  ui_story_1016_10161501_42_dialog_content = "Como ya he dicho, ella ya no es la Gran Mariscal de la Federación Illumina.",
  ui_story_1016_10161501_43_dialog_content = "El Comité aún está realizando una investigación completa sobre el asunto. Si logra demostrar su inocencia, será reincorporada como Gran Mariscal.",
  ui_story_1016_10161501_44_dialog_content = "Lo que requerimos de todos ustedes es su cooperación y comprensión, nada más.",
  ui_story_1016_10161501_45_dialog_content = "Pero...",
  ui_story_1016_10161501_46_dialog_content = "todavia no lo compro...",
  ui_story_1016_10161501_47_dialog_content = "Ya sea que \"lo compre\" o no, es irrelevante. Solo necesita esperar a que el Comité termine su investigación.",
  ui_story_1016_10161501_48_dialog_content = "Además, aquellos de ustedes que tienen contacto cercano y frecuente con Reinhardt—",
  ui_story_1016_10161501_49_dialog_content = "A saber PlayerName, Vice, y Anatoli, también deberá someterse a su investigación.",
  ui_story_1016_10161501_50_dialog_content = "¡¿Hablas en serio?!",
  ui_story_1016_10161501_51_dialog_content = "Una investigación...?",
  ui_story_1016_10161501_52_dialog_content = "Esto es-!",
  ui_story_1016_10161501_53_option_content = "Bien",
  ui_story_1016_10161501_54_dialog_content = "No tengo nada que ocultar, así que pregunta lo que quieras.",
  ui_story_1016_10161501_55_dialog_content = "Creo en la inocencia de Reinhardt. Nunca ha hecho nada malo, que yo sepa.",
  ui_story_1016_10161501_56_dialog_content = "Bien dicho.",
  ui_story_1016_10161501_57_option_content = "¿Y si me niego?",
  ui_story_1016_10161501_58_dialog_content = "No estaba preguntando justo ahora.",
  ui_story_1016_10161501_59_dialog_content = "No tienes otra opción que cooperar con la investigación.",
  ui_story_1016_10161501_60_dialog_content = "¿Es esa alguna forma de tratar a los valiosos invitados de Illumina?",
  ui_story_1016_10161501_61_dialog_content = "Capitán Wrath?!",
  ui_story_1016_10161501_62_dialog_content = "Bien bien. Vice, PlayerNamey asistente de Reinhardt.",
  ui_story_1016_10161501_63_dialog_content = "Capitán WrathDebo pedirle que no interfiera con los asuntos oficiales del Comité.",
  ui_story_1016_10161501_64_dialog_content = "No estoy aquí para interponerme en tu camino. Solo vine a recordarte que ser demasiado estricto con los demás puede tener un impacto negativo en tu trabajo.",
  ui_story_1016_10161501_65_dialog_content = "...",
  ui_story_1016_10161501_66_dialog_content = "Perdóname si mi redacción sonó bastante dura.",
  ui_story_1016_10161501_67_dialog_content = "Estaríamos muy agradecidos por su cooperación en este asunto tan importante.",
  ui_story_1016_10161501_68_dialog_content = "Por el momento, les pedimos humildemente que ustedes tres permanezcan aquí en Illumina hasta que concluya la investigación.",
  ui_story_1016_10161501_69_dialog_content = "...",
  ui_story_1016_10161501_70_dialog_content = "No es como si tuviéramos elección, ¿verdad?",
  ui_story_1016_10161501_71_dialog_content = "Por favor, trata de entender.",
  ui_story_1016_10161501_72_dialog_content = "Entonces eso lo resuelve.",
  ui_story_1016_10161501_73_dialog_content = "PlayerName y el resto de ustedes, cálmense por ahora. Nada bueno saldrá de convertir esto en un conflicto mayor.",
  ui_story_1016_10161501_74_dialog_content = "Multa...",
  ui_story_1016_10161501_75_dialog_content = "Si no hay más preguntas, se despide a todos.",
  ui_story_1016_10161501_76_dialog_content = "Con tu permiso, todavía tengo otros asuntos que atender. Adiós.",
  ui_story_1016_10161501_77_dialog_content = "No perdió el tiempo, ¿verdad...?",
  ui_story_1016_10161501_78_dialog_content = "¿Qué sucedió exactamente mientras estábamos fuera, Capitán? Wrath? ¿Por qué fue Gran Mariscal Reinhardt...",
  ui_story_1016_10161501_79_dialog_content = "Todavía no está claro.",
  ui_story_1016_10161501_80_dialog_content = "Incluso yo no tengo una comprensión muy clara de lo que está sucediendo en este momento.",
  ui_story_1016_10161501_81_dialog_content = "Todo lo que sé es que ahora es el momento equivocado para entrar en un conflicto frontal con el Comité.",
  ui_story_1016_10161501_82_dialog_content = "En todo caso, les encantaría que los ataquemos abiertamente, ya que solo perjudicaría aún más las posibilidades de Reinhardt.",
  ui_story_1016_10161501_83_dialog_content = "¿Estará bien...?",
  ui_story_1016_10161501_84_dialog_content = "...",
  ui_story_1016_10161501_85_dialog_content = "Confía en ella.",
  ui_story_1016_10161501_86_dialog_content = "Dama Carleen—!",
  ui_story_1016_10161501_87_dialog_content = "¡Finalmente le encontré!",
  ui_story_1016_10161501_88_dialog_content = "¿Qué pasa?",
  ui_story_1016_10161501_89_dialog_content = "¡Acabo de recibir una llamada urgente del Señor de la Ciudad! ¡Todos los participantes de Lumopolis en el Ejercicio Militar Conjunto, incluyéndote a ti, deben regresar a Lumopolis de inmediato!",
  ui_story_1016_10161501_90_dialog_content = "¿Una orden del Señor de la Ciudad...?",
  ui_story_1016_10161501_91_dialog_content = "Comprendido. Solo dame un momento para recoger mis cosas primero.",
  ui_story_1016_10161501_92_dialog_content = "¡Sí, mi señora! ¡Te estaremos esperando!",
  ui_story_1016_10161501_93_dialog_content = "Parece que algo increíble está por suceder... O mejor dicho, ya ha comenzado.",
  ui_story_1016_10161501_94_dialog_content = "Regresaré a buscar a Joseph y Zhao, para que podamos planificar nuestro viaje de regreso a Crepúsculo.",
  ui_story_1016_10161501_95_dialog_content = "Me iré ahora. Buena suerte a todos.",
  ui_story_1016_10161501_96_dialog_content = "Tú también...",
  ui_story_1016_10161501_97_dialog_content = "<color=#e8d9bb>Mientras tanto, en un centro de investigación no revelado</color>",
  ui_story_1016_10161501_98_dialog_content = "¿Mmm? Finalmente despierto, ¿verdad?",
  ui_story_1016_10161501_99_dialog_content = "Tan poderosa vitalidad es de esperar del fruto de los experimentos de Forsakin.",
  ui_story_1016_10161501_100_dialog_content = "Te recuerdo...",
  ui_story_1016_10161501_101_dialog_content = "Ulises. Solías ser mi oficial al mando.",
  ui_story_1016_10161501_102_dialog_content = "No has cambiado en absoluto.",
  ui_story_1016_10161501_103_dialog_content = "¿Oh? Entonces, ¿incluso tus recuerdos están comenzando a recuperarse lentamente?",
  ui_story_1016_10161501_104_dialog_content = "Qué sorpresa inesperada.",
  ui_story_1016_10161501_105_dialog_content = "Qué lamentable, entonces, que tus niveles de inteligencia sigan siendo tan escasos.",
  ui_story_1016_10161501_106_dialog_content = "...",
  ui_story_1016_10161501_107_dialog_content = "Hay una cosa que todavía no entiendo muy bien. ¿Por qué elegirías seguir las órdenes de Forsakin cuando claramente no tienes intención de luchar contra nosotros?",
  ui_story_1016_10161501_108_dialog_content = "Incluso permitiste que te capturaran, solo para que ella pudiera escapar. ¿Porqué es eso?",
  ui_story_1016_10161501_109_dialog_content = "No estaba siguiendo sus órdenes.",
  ui_story_1016_10161501_110_dialog_content = "Soy... un soldado de Illumina...",
  ui_story_1016_10161501_111_dialog_content = "Mis órdenes son proteger a mis camaradas y al pueblo de Illumina.",
  ui_story_1016_10161501_112_dialog_content = "!",
  ui_story_1016_10161501_113_dialog_content = "¡Jajaja! ¡Esto sí que es toda una sorpresa!",
  ui_story_1016_10161501_114_dialog_content = "Tengo curiosidad, pero ¿qué te dijo? ¿Dijo que las acciones del Comité fueron la razón por la que se convirtió en la persona que es hoy?",
  ui_story_1016_10161501_115_dialog_content = "No, no, claro que no. Estoy seguro de que traicionar a Illumina y a toda su gente fue completamente su propia decisión.",
  ui_story_1016_10161501_116_dialog_content = "...",
  ui_story_1016_10161501_117_dialog_content = "Que penosa existencia. Vivir en mentira tras mentira, y nunca tanto como dudar de nada de eso.",
  ui_story_1016_10161501_118_dialog_content = "Pero en lugar de creer las palabras de un Eclipsite a medio formar sobre las de tus compañeros aurorianos.",
  ui_story_1016_10161501_119_dialog_content = "Aún así, no debería ser una sorpresa. Después de todo, no eres más que un producto defectuoso.",
  ui_story_1016_10161501_120_dialog_content = "Solo que ahora, finalmente tienes algo parecido a valor.",
  ui_story_1016_10161501_121_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_1016_10161501_122_dialog_content = "Ingresar.",
  ui_story_1016_10161501_123_dialog_content = "Señor.",
  ui_story_1016_10161501_124_dialog_content = "¿No estaba perfectamente claro? Estoy en medio de un experimento importante y nadie puede interrumpirme en este momento.",
  ui_story_1016_10161501_125_dialog_content = "Por favor, perdóname, pero tienes un invitado muy importante aquí para verte.",
  ui_story_1016_10161501_126_dialog_content = "<color=#FFB400>La máscara de hierro</color>, ¿eh? Jejeje... Supongo que es natural que quiera verme.",
  ui_story_1016_10161501_127_dialog_content = "<color=#e8d9bb>Momentos después, en algún lugar de Gannon City</color>",
  ui_story_1016_10161501_128_dialog_content = "Déjame adivinar: ¿has venido a interrogarme?",
  ui_story_1016_10161501_129_dialog_content = "Hacerlo ahora mismo sería impaciente de mí.",
  ui_story_1016_10161501_130_dialog_content = "Vine aquí hoy con un solo motivo: pedir su ayuda para confirmar mis sospechas.",
  ui_story_1016_10161501_131_dialog_content = "Pero tus sospechas siempre son correctas, ¿no es así?",
  ui_story_1016_10161501_132_dialog_content = "Ahórrame tus halagos. No nos sirve para nada.",
  ui_story_1016_10161501_133_dialog_content = "De acuerdo.",
  ui_story_1016_10161501_134_dialog_content = "Ahora bien, permítanme resumir el plan hasta ahora.",
  ui_story_1016_10161501_135_dialog_content = "Esencialmente, el plan era derrocar Reinhardt usando los bienes desechados de Eclipse para causar pánico, y luego haciendo que tus hombres tomen el control de la situación.",
  ui_story_1016_10161501_136_dialog_content = "Desafortunadamente, Eclipse no solo quiere recuperar a Forsakin y su sujeto de prueba, sino que también quiere el núcleo de Guardian One.",
  ui_story_1016_10161501_137_dialog_content = "Además de esto, cierto grupo de entrometidos no deseados ahora está muy al tanto del plan.",
  ui_story_1016_10161501_138_dialog_content = "¿Quién?",
  ui_story_1016_10161501_139_dialog_content = "<color=#FFB400>Crepúsculo</color>.",
  ui_story_1016_10161501_140_dialog_content = "Ese equipo de Crepúsculo se enteró de tu plan, por lo que entregaron la victoria a tus subordinados.",
  ui_story_1016_10161501_141_dialog_content = "¿Será que... alguien les filtró el plan?",
  ui_story_1016_10161501_142_dialog_content = "Hay otras posibilidades. Para principiantes...",
  ui_story_1016_10161501_143_dialog_content = "Tus subordinados nunca lucharon con toda su fuerza.",
  ui_story_1016_10161501_144_dialog_content = "Su equipo en la fase final fue inconsistente con sus créditos.",
  ui_story_1016_10161501_145_dialog_content = "Y se les dio todas las respuestas a las preguntas en la fase académica por adelantado.",
  ui_story_1016_10161501_146_dialog_content = "...",
  ui_story_1016_10161501_147_dialog_content = "Tus acciones fueron demasiado obvias.",
  ui_story_1016_10161501_148_dialog_content = "Por pequeña que sea, hay una razón por la que Illumina y Lumopolis no están dispuestos a provocar a la ciudad de Twilight.",
  ui_story_1016_10161501_149_dialog_content = "Ahora que tienen la iniciativa, se han convertido en una variable en la última fase de nuestro plan.",
  ui_story_1016_10161501_150_dialog_content = "Su trabajo ahora es asegurarse de que se conviertan en una variable controlada.",
  ui_story_1016_10161501_151_dialog_content = "No solo eso, debe recuperar la consola central de Guardian One lo antes posible.",
  ui_story_1016_10161501_152_dialog_content = "Preferiría jugar este juego lo mejor posible, en lugar de que la incertidumbre de demasiadas variables afecte mi desempeño.",
  ui_story_1016_10161501_153_dialog_content = "Ya veo... Entonces haré exactamente eso.",
  ui_story_1016_10161501_154_dialog_content = "Hmph. Pareces bastante confiado en tu experimento, Ulysses.",
  ui_story_1016_10161501_155_dialog_content = "Pero por supuesto.",
  ui_story_1016_10161501_156_dialog_content = "Una vez que analice por completo la investigación de Forsakin, resultará en el mayor avance tecnológico que la Federación Illumina haya visto en muchos años.",
  ui_story_1016_10161501_157_dialog_content = "Con este conocimiento a nuestra disposición, podremos usar Chord Link en Entrañas X para producir súper soldados en masa.",
  ui_story_1016_10161501_158_dialog_content = "Después de todo, ya sean del Programa Phospherus o del Proyecto Sol Artificial, tenemos muchos temas para elegir.",
  ui_story_1016_10161501_159_dialog_content = "Pronto, la fuerza de la Federación Illumina crecerá a pasos agigantados.",
  ui_story_1016_10161501_160_dialog_content = "Entonces será mejor que seas rápido. El tiempo es un recurso mucho más preciado que la luz.",
  ui_story_1016_10161501_161_dialog_content = "Una última cosa. Al final, lo que estás haciendo no es más que plagiar el trabajo de Forsakin.",
  ui_story_1016_10161501_162_dialog_content = "¿Le permitirá su integridad como investigador profesional hacer esto?",
  ui_story_1016_10161501_163_dialog_content = "Eso no será un problema.",
  ui_story_1016_10161501_164_dialog_content = "Para asegurar la continuación de nuestra civilización, debemos estar preparados para hacer lo que sea necesario.",
  ui_story_1016_10161501_165_dialog_content = "<color=#e8d9bb>Varios días después, en el Centro Médico de la Ciudad de Gannon</color>",
  ui_story_1016_10161501_166_dialog_content = "(Han pasado varios días desde el final del partido final, pero Axelia todavía no se ha despertado.)",
  ui_story_1016_10161501_167_dialog_content = "(Parece que casi destruyó su cuerpo nuevamente esta vez).",
  ui_story_1016_10161501_168_dialog_content = "(Afortunadamente, los médicos e investigadores pudieron reparar su cuerpo rápidamente, dada su experiencia de la última vez).",
  ui_story_1016_10161501_169_dialog_content = "(Desafortunadamente, el alcance de su daño significa que nadie sabe cuándo se despertará).",
  ui_story_1016_10161501_170_dialog_content = "Ngh...",
  ui_story_1016_10161501_171_dialog_content = "Axelia?!",
  ui_story_1016_10161501_172_dialog_content = "Se siente como... Me acabo de despertar de un largo sueño.",
  ui_story_1016_10161501_173_dialog_content = "Estás... finalmente estás despierto...",
  ui_story_1016_10161501_174_dialog_content = "Buenos dias, Yingel.",
  ui_story_1016_10161501_175_dialog_content = "Pareces exhausto.",
  ui_story_1016_10161501_176_dialog_content = "¿En realidad? Tal vez un poco...",
  ui_story_1016_10161501_177_dialog_content = "¿Cómo te sientes? ¿Te duele algo?",
  ui_story_1016_10161501_178_dialog_content = "Me siento completamente normal.",
  ui_story_1016_10161501_179_dialog_content = "Pero todavía necesito más tiempo antes de que se restablezcan mis funciones de combate.",
  ui_story_1016_10161501_180_dialog_content = "No te preocupes por el combate en este momento. Tienes suerte de estar vivo, Axelia.",
  ui_story_1016_10161501_181_dialog_content = "...",
  ui_story_1016_10161501_182_dialog_content = "Reinhardt dijo algo similar a mí durante nuestra batalla.",
  ui_story_1016_10161501_183_dialog_content = "Escuché que se entregó voluntariamente...",
  ui_story_1016_10161501_184_dialog_content = "Cuál es la razón por la que todavía estás vivo.",
  ui_story_1016_10161501_185_dialog_content = "Lo que me recuerda, aquí está tu medalla de victoria.",
  ui_story_1016_10161501_186_dialog_content = "Illumina ha estado en un estado de caos últimamente, y con usted inconsciente, no hubo oportunidad de realizar una ceremonia de premiación adecuada.",
  ui_story_1016_10161501_187_dialog_content = "Así que esto tendrá que hacer.",
  ui_story_1016_10161501_188_dialog_content = "Esta medalla... se siente pesada.",
  ui_story_1016_10161501_189_dialog_content = "...",
  ui_story_1016_10161501_190_dialog_content = "Yingel? ¿Puedo hacerte una pregunta?",
  ui_story_1016_10161501_191_dialog_content = "¿Qué es?",
  ui_story_1016_10161501_192_dialog_content = "Durante nuestra batalla, Reinhardt me dijo algo -",
  ui_story_1016_10161501_193_dialog_content = "Que ella quería que yo viviera como persona.",
  ui_story_1016_10161501_194_dialog_content = "¿Puedes decirme qué significa <color=#FFB400>vivir como una persona</color>?",
  ui_story_1017_10170101_1_dialog_content = "¿Puedes escucharme, Gran Mariscal?",
  ui_story_1017_10170101_2_dialog_content = "Puedo.",
  ui_story_1017_10170101_3_dialog_content = "Entonces comencemos.",
  ui_story_1017_10170101_4_dialog_content = "Soy Nemesis, Inspector General de la Federación Illumina, juez que preside este caso.",
  ui_story_1017_10170101_5_dialog_content = "Supervisaré el tercer juicio interno relacionado con sus cargos por ayudar y albergar a un enemigo y fugitivo, de acuerdo con la ley de la Federación Illumina.",
  ui_story_1017_10170101_6_dialog_content = "De acuerdo con la Ley de Investigación de la Federación Illumina, tú tienes el derecho—",
  ui_story_1017_10170101_7_dialog_content = "Omite el rollo.",
  ui_story_1017_10170101_8_dialog_content = "Entonces comenzaremos el proceso oficial. ¿Desea hacer una declaración sobre los cargos presentados por Ulysses en su contra?",
  ui_story_1017_10170101_9_dialog_content = "Reitero que realmente no estaba al tanto de que Forsakin se escondía en Gannon durante el ejercicio militar.",
  ui_story_1017_10170101_10_dialog_content = "No hubo complicidad de ninguna forma entre ella y yo.",
  ui_story_1017_10170101_11_dialog_content = "Dado que ha mantenido esta declaración en las tres sesiones de interrogatorio, no puedo emitir un juicio favorable para usted.",
  ui_story_1017_10170101_12_dialog_content = "¿No es esto lo que todos querían?",
  ui_story_1017_10170101_13_dialog_content = "Seamos directos el uno con el otro. ¿Cuál es tu objetivo final?",
  ui_story_1017_10170101_14_dialog_content = "Me gustaría dar un testimonio adicional, Su Señoría.",
  ui_story_1017_10170101_15_dialog_content = "Puedes.",
  ui_story_1017_10170101_16_dialog_content = "Según informes de inteligencia, antes del ejercicio, Forsakin y Reinhardt acordaron el siguiente pacto en persona en el Instituto X:",
  ui_story_1017_10170101_17_dialog_content = "Reinhardt prometió a Forsakin dejarla ir siempre y cuando Helios se quedara atrás.",
  ui_story_1017_10170101_18_dialog_content = "Yingel y Anatoli pueden dar fe de eso.",
  ui_story_1017_10170101_19_dialog_content = "Su Señoría—",
  ui_story_1017_10170101_20_dialog_content = "<size=30>No interrumpas, Wrath.</size>",
  ui_story_1017_10170101_21_dialog_content = "Por favor, testifique, Coronel Yingel.",
  ui_story_1017_10170101_22_dialog_content = "Solo tienes que decirle al juez si Forsakin hizo un trato con Reinhardt.",
  ui_story_1017_10170101_23_dialog_content = "...Sí.",
  ui_story_1017_10170101_24_dialog_content = "Por qué tú-",
  ui_story_1017_10170101_25_dialog_content = "Cállate, hablar fuera de turno solo empeorará las cosas para el Gran Mariscal.",
  ui_story_1017_10170101_26_dialog_content = "Siguiendo el acuerdo, el demandado optó por actuar de manera pasiva debido a viejos lazos.",
  ui_story_1017_10170101_27_dialog_content = "Ordenó refuerzos para ayudar al fugitivo a escapar, lo que llevó al robo del núcleo de Guardian One.",
  ui_story_1017_10170101_28_dialog_content = "¿Se declara culpable de eso, Gran Mariscal?",
  ui_story_1017_10170101_29_dialog_content = "Soy parcialmente responsable del robo del núcleo, pero muéstrame las pruebas de los otros cargos.",
  ui_story_1017_10170101_30_dialog_content = "Anatoli.",
  ui_story_1017_10170101_31_dialog_content = "¿Sí, señor?",
  ui_story_1017_10170101_32_dialog_content = "¿Reinhardt les dijo a Forsakin y Helios que, \"Vine a buscarlos y traje refuerzos?\"",
  ui_story_1017_10170101_33_dialog_content = "...",
  ui_story_1017_10170101_34_dialog_content = "¿Sí o no?",
  ui_story_1017_10170101_35_dialog_content = "Si...",
  ui_story_1017_10170101_36_dialog_content = "Presente su defensa con respecto al testimonio, Gran Mariscal.",
  ui_story_1017_10170101_37_dialog_content = "...",
  ui_story_1017_10170101_38_dialog_content = "Descanso mi caso, Su Señoría.",
  ui_story_1017_10170101_39_dialog_content = "(No fue así como sucedió...)",
  ui_story_1017_10170101_40_dialog_content = "(Espera un minuto, si el Coronel Yingel y yo somos los testigos...)",
  ui_story_1017_10170101_41_dialog_content = "¿Se declara culpable de los cargos mencionados, Gran Mariscal? ¿Tiene algo más que decir?",
  ui_story_1017_10170101_42_dialog_content = "Je, admito que mi negligencia causó el lío en el que está Illumina ahora mismo!",
  ui_story_1017_10170101_43_dialog_content = "Entonces, si quieres una declaración de mí—",
  ui_story_1017_10170101_44_dialog_content = "¡Jajaja!",
  ui_story_1017_10170101_45_dialog_content = "Eso es todo lo que tengo que decir, Su Señoría. Adelante y dictamine mi sentencia.",
  ui_story_1017_10170101_46_dialog_content = "...",
  ui_story_1017_10170101_47_dialog_content = "Siguiendo la conclusión del tercer juicio de Reinhardt, por la presente declaro...",
  ui_story_1017_10170101_48_dialog_content = "La ex Gran Mariscal Reinhardt de la Federación Illumina está acusada de lo siguiente:",
  ui_story_1017_10170101_49_dialog_content = "Abusando de su posición y poder para llevar a cabo acuerdos encubiertos con el fugitivo Forsakin, quien había infiltrado una Entrañas de Illumina.",
  ui_story_1017_10170101_50_dialog_content = "Dicha acción provocó que el núcleo de Guardian One fuera robado, 78 soldados de Illumina y sus familiares resultaron heridos, y ha dejado la seguridad federal en una posición vulnerable.",
  ui_story_1017_10170101_51_dialog_content = "El acusado se declara culpable de negligencia.",
  ui_story_1017_10170101_52_dialog_content = "Pero la evidencia es insuficiente para respaldar la acusación de ayudar a un enemigo. Se llevará a cabo un juicio adicional cuando se cumplan las condiciones para un juicio o cuando ambas partes puedan presentar pruebas suficientes.",
  ui_story_1017_10170101_53_dialog_content = "De acuerdo con la Ley de Investigación de la Federación Illumina, el Departamento Judicial emite los siguientes juicios:",
  ui_story_1017_10170101_54_dialog_content = "El acusado será removido de la posición de Gran Mariscal.",
  ui_story_1017_10170101_55_dialog_content = "El acusado será despojado de todos los derechos que le corresponden como soldado de Illumina.",
  ui_story_1017_10170101_56_dialog_content = "El acusado será encarcelado, efectivo de inmediato.",
  ui_story_1017_10170101_57_dialog_content = "Aplazado.",
  ui_story_1017_10170101_58_dialog_content = "¡Ha salido, ha salido!",
  ui_story_1017_10170101_59_dialog_content = "M-Señora!",
  ui_story_1017_10170101_60_dialog_content = "Ah...",
  ui_story_1017_10170101_61_dialog_content = "<size=30>¿Quién es ella?</size>",
  ui_story_1017_10170101_62_dialog_content = "Oficial Belisaria. Ella tiene mucho poder sobre el Comité.",
  ui_story_1017_10170101_63_dialog_content = "Estaba tan nervioso que olvidé saludar.",
  ui_story_1017_10170101_64_option_content = "Me estás poniendo nervioso.",
  ui_story_1017_10170101_65_option_content = "Estás acabado.",
  ui_story_1017_10170101_66_dialog_content = "Un poco de optimismo sería apreciado, gracias.",
  ui_story_1017_10170101_67_dialog_content = "Bueno, ya es demasiado tarde para saludar ahora.",
  ui_story_1017_10170101_68_dialog_content = "...",
  ui_story_1017_10170101_69_dialog_content = "Si incluso ella ha aparecido... Me pregunto si hay alguna posibilidad de un desarrollo positivo para el Gran Mariscal.",
  ui_story_1017_10170101_70_dialog_content = "Te extrañé antes.",
  ui_story_1017_10170101_71_dialog_content = "Debes ser el Celestita, ¿verdad?",
  ui_story_1017_10170101_72_dialog_content = "Sí... Señora.",
  ui_story_1017_10170101_73_dialog_content = "¡Oficial Belisaria!",
  ui_story_1017_10170101_74_dialog_content = "Escuché que tú, el Celestita, y tu amigo de Lumopolis participaron en el Ejercicio Militar Conjunto.",
  ui_story_1017_10170101_75_dialog_content = "Sí, señora.",
  ui_story_1017_10170101_76_dialog_content = "Jeje, no está mal...",
  ui_story_1017_10170101_77_dialog_content = "Tengo esta inexplicable sensación sobre ustedes dos.",
  ui_story_1017_10170101_78_dialog_content = "Pronto pondrás a prueba mi corazonada.",
  ui_story_1017_10170101_79_dialog_content = "Disculpa por ahora, Caelestite. La próxima vez que nos encontremos, será en un entorno oficial.",
  ui_story_1017_10170101_80_dialog_content = "...",
  ui_story_1017_10170101_81_dialog_content = "E-Eso me asustó...",
  ui_story_1017_10170101_82_dialog_content = "Al menos saludaste esta vez.",
  ui_story_1017_10170101_83_dialog_content = "Pero ella nos seguía mirando de manera extraña.",
  ui_story_1017_10170101_84_dialog_content = "Tal vez estoy exagerando...",
  ui_story_1017_10170101_85_dialog_content = "¡Oye, los generales—Comandante Hiiro!",
  ui_story_1017_10170101_86_dialog_content = "...",
  ui_story_1017_10170101_87_dialog_content = "Probablemente este no sea el lugar para hablar.",
  ui_story_1017_10170101_88_dialog_content = "Todos se ven tan serios...",
  ui_story_1017_10170101_89_dialog_content = "PlayerName, Teniente Vice.",
  ui_story_1017_10170101_90_dialog_content = "Anatoli! ¿Cómo van las cosas?",
  ui_story_1017_10170101_91_dialog_content = "...",
  ui_story_1017_10170101_92_dialog_content = "Hablemos en un lugar tranquilo.",
  ui_story_1017_10170101_93_dialog_content = "Comandantes, los Eclipsites en la frontera se han estado moviendo. La situación lleva así varios días.",
  ui_story_1017_10170101_94_dialog_content = "Ya hemos hecho que el <color=#FFB400>Equipo de Reconocimiento de la Zona Oscura</color> ajuste su exploración según los datos detectados.",
  ui_story_1017_10170101_95_dialog_content = "Al comparar los datos históricos con lo que tenemos ahora, se hace evidente que los <color=#FFB400>trastornos de aurora</color> han sido más frecuentes de lo que han sido en los últimos 20 años.",
  ui_story_1017_10170101_96_dialog_content = "Lo cual podría significar que el Eclipse está preparando una posible Crisis de Darkover.",
  ui_story_1017_10170101_97_dialog_content = "¿Todos escuchan eso?",
  ui_story_1017_10170101_98_dialog_content = "Cuando la última Crisis de Darkover golpeó, también éramos nosotros los que estábamos aquí sentados.",
  ui_story_1017_10170101_99_dialog_content = "Han pasado muchos años desde entonces, y nosotros también nos hemos vuelto silenciosos.",
  ui_story_1017_10170101_100_dialog_content = "¿Tiene algo que ver el aumento del Darkover con el robo del núcleo de Guardian One?",
  ui_story_1017_10170101_101_dialog_content = "Claramente, considerando lo que Eclipse ha estado haciendo.",
  ui_story_1017_10170101_102_dialog_content = "Pero esta vez, lograron hacerse con el núcleo de Guardian One, lo que cambia las cosas.",
  ui_story_1017_10170101_103_dialog_content = "¿Cómo va el seguimiento?",
  ui_story_1017_10170101_104_dialog_content = "Escuchaste el informe, se ha enviado un equipo de élite de reconocimiento en la Zona Oscura.",
  ui_story_1017_10170101_105_dialog_content = "¿Un equipo de reconocimiento de élite de la Zona Oscura?",
  ui_story_1017_10170101_106_dialog_content = "Si te refieres a ella, entonces supongo que es un equipo élite.",
  ui_story_1017_10170101_107_dialog_content = "¿No es responsabilidad de Essen rastrear a Wraith y recuperar Guardian One?",
  ui_story_1017_10170101_108_dialog_content = "Si él pudiera hacer eso, no habría enviado Pepita.",
  ui_story_1017_10170101_109_dialog_content = "¿Te refieres a ese prisionero que desertó de Illumina y se unió a True Order?",
  ui_story_1017_10170101_110_dialog_content = "¿Prisionero?",
  ui_story_1017_10170101_111_dialog_content = "¿No creen todos que están exagerando un poco?",
  ui_story_1017_10170101_112_dialog_content = "Debería estar tras las rejas en este momento.",
  ui_story_1017_10170101_113_dialog_content = "Algunas cartas deben mantenerse cerca hasta la hora de necesidad.",
  ui_story_1017_10170101_114_dialog_content = "Ella tiene experiencia en infiltración en la Zona Oscura. En ciertos aspectos, solo ella puede lograr esta misión.",
  ui_story_1017_10170101_115_dialog_content = "Belisaria, el comité nunca te otorgó la autoridad para entrenar mercenarios privados sin permiso.",
  ui_story_1017_10170101_116_dialog_content = "Pero es mi deber rehabilitar a los prisioneros y ponerlos en uso.",
  ui_story_1017_10170101_117_dialog_content = "¿Cuándo se va el otro equipo?",
  ui_story_1017_10170101_118_dialog_content = "Comandante, la información del equipo está organizada y puede dar órdenes cuando esté listo. Están preparados para salir mañana como muy pronto.",
  ui_story_1017_10170101_119_dialog_content = "¿Hay otro equipo?",
  ui_story_1017_10170101_120_dialog_content = "Nuestras investigaciones nos indican que el Teniente Vice tiene una conexión interesante con uno de los miembros de Eclipse que infiltraron Gannon.",
  ui_story_1017_10170101_121_dialog_content = "Además, los tres miembros de Umbraton que participaron en el ejercicio militar también proporcionaron pistas de diversos grados.",
  ui_story_1017_10170101_122_dialog_content = "Teniendo todo en cuenta, creemos que podrían ser capaces de localizar el núcleo de Guardián Uno.",
  ui_story_1017_10170101_123_dialog_content = "Estamos formando un equipo temporal para respaldar al Equipo de Reconocimiento de la Zona Oscura.",
  ui_story_1017_10170101_124_dialog_content = "Vamos, no crees que esos tres tontos sean realmente de Umbraton, ¿verdad?",
  ui_story_1017_10170101_125_dialog_content = "No te dejes llevar por la nariz, Máscara de Hierro.",
  ui_story_1017_10170101_126_dialog_content = "Les ofrecí un aventón porque sé que serán útiles.",
  ui_story_1017_10170101_127_dialog_content = "¿Por qué no escuchamos algunas actualizaciones de ti, Ulysses? ¿Cómo va el progreso de tu arma?",
  ui_story_1017_10170101_128_dialog_content = "El \"prototipo experimental\" de Forsakin ha sido analizado. Creo que es hora de darle nueva vida al Programa Phospherus.",
  ui_story_1017_10170101_129_dialog_content = "Con el Programa Phospherus 2.0, la fuerza de combate de los Aurorianos mejorará significativamente.",
  ui_story_1017_10170101_130_dialog_content = "Entonces, ahora es el momento perfecto para seleccionar al próximo Gran Mariscal.",
  ui_story_1017_10170101_131_dialog_content = "¿Algún candidato adecuado?",
  ui_story_1017_10170101_132_dialog_content = "Esta es el eslabón más débil del proyecto.",
  ui_story_1017_10170101_133_dialog_content = "Realmente me preocupa que la próxima Crisis de Darkover nos alcance y nos encontremos indefensos.",
  ui_story_1017_10170101_134_dialog_content = "¿La candidatura es la parte más débil?",
  ui_story_1017_10170101_135_dialog_content = "No estoy de acuerdo.",
  ui_story_1017_10170101_136_dialog_content = "La influencia que Reinhardt ha acumulado a lo largo de los años ha superado por mucho las expectativas.",
  ui_story_1017_10170101_137_dialog_content = "La situación actual es una consecuencia directa del \"Programa Phospherus\". ¿Realmente deberíamos seguir adelante con él?",
  ui_story_1017_10170101_138_dialog_content = "No hay suficiente evidencia de la interrogación de Reinhardt para condenarla. Su destitución probablemente sea temporal.",
  ui_story_1017_10170101_139_dialog_content = "Dr. Ulysses, por otro lado... ¿no te estás adelantando un poco?",
  ui_story_1017_10170101_140_dialog_content = "No tiene sentido discutir algo que ya es una conclusión inevitable.",
  ui_story_1017_10170101_141_dialog_content = "Si tienes un problema, sigue los canales adecuados y presenta una demanda.",
  ui_story_1017_10170101_142_dialog_content = "Ulysses, deberías dejar de lado tu investigación de vez en cuando y experimentar lo que sucede más allá de estas paredes.",
  ui_story_1017_10170101_143_dialog_content = "Dices que quieres carne. ¿Pedirías al ganado que se dirija por sí mismo al matadero?",
  ui_story_1017_10170101_144_dialog_content = "Si quieres presumir de tu \"arma definitiva\", adelante. No tengo problema con eso.",
  ui_story_1017_10170101_145_dialog_content = "Pero cuando se trata de seleccionar al próximo Gran Mariscal, probablemente sea prudente, como dijiste, seguir los canales adecuados.",
  ui_story_1017_10170101_146_dialog_content = "Basta. En Illumina, siempre priorizamos resolver problemas públicos por encima de disputas personales.",
  ui_story_1017_10170101_147_dialog_content = "Dado que todos están aquí, deberíamos revisar los candidatos a Gran Mariscal.",
  ui_story_1017_10170101_148_dialog_content = "¿Se han enviado todos los archivos?",
  ui_story_1017_10170101_149_dialog_content = "Sí. Estimados comandantes, lo que tienen ante ustedes son archivos detallados sobre el personal militar desde el rango de coronel en adelante.",
  ui_story_1017_10170101_150_dialog_content = "También se incluyen sus redes de relaciones privadas y evaluaciones de colegas.",
  ui_story_1017_10170101_151_dialog_content = "Cuando se fundó Illumina, hubo una decisión unánime de que el soldado más poderoso debería ocupar el cargo de Gran Mariscal.",
  ui_story_1017_10170101_152_dialog_content = "Con el tiempo, esto se convirtió en una regla no escrita que el candidato a Gran Mariscal debe someterse a un mejoramiento físico.",
  ui_story_1017_10170101_153_dialog_content = "No tengo nada en contra de un Programa Fosférico 2.0. Pero cuando se trata de pura capacidad, solo esos cuatro generales son aptos para el papel de Gran Mariscal.",
  ui_story_1017_10170101_154_dialog_content = "Si solo íbamos a cultivar otro Reinhardt entre ellos, ¿cuál era el punto de reemplazar al Gran Mariscal desde un principio?",
  ui_story_1017_10170101_155_dialog_content = "¿No sería elegir a uno de ellos como Gran Mariscal algo así como dispararnos en el pie?",
  ui_story_1017_10170101_156_dialog_content = "¿Qué te parece, Ulises?",
  ui_story_1017_10170101_157_dialog_content = "...",
  ui_story_1017_10170101_158_dialog_content = "De esos cuatro, hay uno que cumple con el perfil...",
  ui_story_1017_10170201_1_dialog_content = "Quienquiera que esté afuera, entre.",
  ui_story_1017_10170201_2_dialog_content = "Eh, saludos, Comandante Hiiro, ¡y a todos los demás!",
  ui_story_1017_10170201_3_dialog_content = "Hola, oficiales.",
  ui_story_1017_10170201_4_dialog_content = "Perdón por molestarlos. Estoy aquí para ver al Comandante Hiiro, pero no esperaba que todos ustedes estuvieran presentes...",
  ui_story_1017_10170201_5_dialog_content = "Escuchamos sobre el Gran Mariscal y queríamos—",
  ui_story_1017_10170201_X5_dialog_content = "<color=#e8d9bb>bip—bip—</color>",
  ui_story_1017_10170201_6_dialog_content = "...",
  ui_story_1017_10170201_7_dialog_content = "A todos, han llegado órdenes para llamarnos de vuelta a la zona de guerra.",
  ui_story_1017_10170201_8_dialog_content = "¿Tan pronto?",
  ui_story_1017_10170201_9_dialog_content = "Lo tengo también, y nunca había visto una descripción tan breve para una tarea antes.",
  ui_story_1017_10170201_10_dialog_content = "Igual.",
  ui_story_1017_10170201_11_dialog_content = "Hmph, ¿preocupados de que estemos tramando rebelarnos juntos, verdad?",
  ui_story_1017_10170201_12_dialog_content = "Me convertí en un general de la Federación luchando en guerras. ¡No tengo problema en jugar duro!",
  ui_story_1017_10170201_13_dialog_content = "Por precaución, realicemos nuestras respectivas tareas por separado por ahora. Iremos sobre la marcha.",
  ui_story_1017_10170201_14_dialog_content = "Seguro.",
  ui_story_1017_10170201_15_dialog_content = "¿Y tú, Wrath?",
  ui_story_1017_10170201_X15_dialog_content = "¿Eh, qué?",
  ui_story_1017_10170201_X16_dialog_content = "También has recibido las órdenes, ¿verdad?",
  ui_story_1017_10170201_X17_dialog_content = "... Mi Legión de Guardias siempre ha sido solo para mostrar. De todos modos, ustedes serán los primeros en entrar.",
  ui_story_1017_10170201_X18_dialog_content = "Mantente en contacto si pasa algo. Cuídate.",
  ui_story_1017_10170201_X19_dialog_content = "Está bien, cuídate.",
  ui_story_1017_10170201_16_dialog_content = "¿Yo? <color=#FFB400>Mi Legión de Guardias es solo una fachada, de todos modos</color>. Ustedes van primero. No voy a salir de Gannon en mucho tiempo.",
  ui_story_1017_10170201_17_dialog_content = "Está bien, cuídate.",
  ui_story_1017_10170201_18_dialog_content = "...",
  ui_story_1017_10170201_19_dialog_content = "Todos se fueron.",
  ui_story_1017_10170201_20_dialog_content = "¿Qué pasó? Incluso el Comandante Hiiro estaba...",
  ui_story_1017_10170201_21_dialog_content = "¿Qué crees que estaban discutiendo?",
  ui_story_1017_10170201_22_option_content = "Rebelión",
  ui_story_1017_10170201_23_dialog_content = "Puedo sentir que las cosas están muy tensas entre ellos y los que tienen el poder.",
  ui_story_1017_10170201_24_dialog_content = "Probablemente estén preocupados por la reacción después de lo que le pasó al Gran Mariscal...",
  ui_story_1017_10170201_25_dialog_content = "¡Shh! ¡Cuida lo que dices en voz alta!",
  ui_story_1017_10170201_26_option_content = "Salvando al Gran Mariscal",
  ui_story_1017_10170201_27_dialog_content = "La Gran Mariscal fue atrapada. Los comandantes querrían liberarla de alguna manera.",
  ui_story_1017_10170201_28_dialog_content = "En ese caso, ¿qué podemos hacer...?",
  ui_story_1017_10170201_29_option_content = "No estoy seguro",
  ui_story_1017_10170201_30_dialog_content = "Se fueron tan rápido. No puede ser por algo bueno.",
  ui_story_1017_10170201_31_dialog_content = "Suspiro, supongo que vinimos por nada...",
  ui_story_1017_10170201_32_dialog_content = "*Jadeando* ¡Ahí estás, Vice!",
  ui_story_1017_10170201_33_dialog_content = "¡Tengo una misión urgente para ti!",
  ui_story_1017_10170201_34_dialog_content = "¿Son esos los compañeros de equipo que van contigo?",
  ui_story_1017_10170201_35_dialog_content = "Vivian se fue tan apresuradamente. Simplemente nos dijo qué hacer y desapareció.",
  ui_story_1017_10170201_36_dialog_content = "Sí, se veía ansiosa. Grandes cambios están por llegar a Illumina, me imagino.",
  ui_story_1017_10170201_37_dialog_content = "Hay mucho pasando... No puedo entenderlo ni pies ni cabeza en este momento.",
  ui_story_1017_10170201_38_dialog_content = "Y ahora incluso escucho un silbido extraño...",
  ui_story_1017_10170201_39_dialog_content = "También lo escucho.",
  ui_story_1017_10170201_40_dialog_content = "Los he estado esperando, pasajeros del Barquero de Acheron.",
  ui_story_1017_10170201_41_dialog_content = "¡Oficial Charon! ¿Entonces estoy en esta misión contigo?",
  ui_story_1017_10170201_42_dialog_content = "Hola, Vice, y tú también, Caelestita.",
  ui_story_1017_10170201_43_dialog_content = "Hola, Vice, y tú también, Caelestita.",
  ui_story_1017_10170201_44_dialog_content = "Hola, Vice, y tú también, Caelestita.",
  ui_story_1017_10170201_45_dialog_content = "La pandilla finalmente está toda aquí—Ejem, saludos a todos.",
  ui_story_1017_10170201_46_dialog_content = "¿Qué están haciendo ustedes aquí?",
  ui_story_1017_10170201_47_dialog_content = "No lo esperabas, ¿verdad? ¡Somos miembros oficiales del <color=#FFB400>Escuadrón de Rastreo</color>!",
  ui_story_1017_10170201_48_dialog_content = "¡Sí, es agradable tener la oportunidad de viajar con todos!",
  ui_story_1017_10170201_49_dialog_content = "¿De qué se trata esto, oficial Charon?",
  ui_story_1017_10170201_50_dialog_content = "Todos ustedes son amigos invitados a viajar con el Barquero de Acheron, como tú.",
  ui_story_1017_10170201_51_dialog_content = "¿Amigos?",
  ui_story_1017_10170201_52_dialog_content = "Sí, pero no estás en esa lista, Caelestite.",
  ui_story_1017_10170201_53_dialog_content = "Así que sigue tu camino, porque el Barquero de Acheron se va.",
  ui_story_1017_10170201_54_dialog_content = "Espera, ¡déjame subir al tren!",
  ui_story_1017_10170201_55_dialog_content = "PlayerName, ¿qué estás...",
  ui_story_1017_10170201_56_dialog_content = "Dime, Caelestite, ¿por qué debería dejarte subir?",
  ui_story_1017_10170201_57_option_content = "Estoy preocupado por Vice.",
  ui_story_1017_10170201_58_dialog_content = "Vivian dijo que hay una posibilidad de que esta operación te lleve profundamente a la Zona Oscura...",
  ui_story_1017_10170201_59_dialog_content = "Me preocupa que el enemigo misterioso del ejercicio militar pueda hacer otro movimiento en Vice.",
  ui_story_1017_10170201_60_dialog_content = "Entonces, por favor llévame contigo.",
  ui_story_1017_10170201_61_option_content = "Estoy preocupado por ti.",
  ui_story_1017_10170201_62_dialog_content = "Vivian dijo que Illumina formó un escuadrón de rastreo, pero no pensé que incluiría a esos tres.",
  ui_story_1017_10170201_63_dialog_content = "Me preocupa que te causen problemas, así que déjame acompañarte.",
  ui_story_1017_10170201_64_dialog_content = "Naturalmente, a mi amigo no le importará, pero hacia donde nos dirigimos está lleno de peligros.",
  ui_story_1017_10170201_65_dialog_content = "El destino de nuestro viaje podría ser el fin de tu vida.",
  ui_story_1017_10170201_66_dialog_content = "Créeme, ¡tengo mucha experiencia con peligros!",
  ui_story_1017_10170201_67_dialog_content = "PlayerName...",
  ui_story_1017_10170201_68_dialog_content = "Oye, ¿escuchaste eso, Otro Extremo? ¡El Celestita quiere marchar directamente al infierno con nosotros!",
  ui_story_1017_10170201_69_dialog_content = "No tienes que ponerlo así...",
  ui_story_1017_10170201_70_dialog_content = "Lástima que tenga que pedirle al no invitado tú que te hagas a un lado para que podamos seguir en el camino.",
  ui_story_1017_10170201_71_dialog_content = "Aún tenemos mucha preparación que hacer antes de entrar en la Zona Oscura.",
  ui_story_1017_10170201_72_dialog_content = "Supongo que me iré ahora, PlayerName.",
  ui_story_1017_10170201_73_option_content = "Adiós, Vice.",
  ui_story_1017_10170201_74_dialog_content = "¿Algo que quieras decirme?",
  ui_story_1017_10170201_75_dialog_content = "Si...",
  ui_story_1017_10170201_76_option_content = "Vice, espera.",
  ui_story_1017_10170201_77_dialog_content = "¿Y?",
  ui_story_1017_10170201_78_dialog_content = "La Zona Oscura es muy peligrosa, así que cuídate.",
  ui_story_1017_10170201_79_dialog_content = "Lo sé, pero siempre logro salir de los problemas, ¿no es cierto?",
  ui_story_1017_10170201_80_dialog_content = "Eso es porque...",
  ui_story_1017_10170201_81_dialog_content = "¿Por qué?",
  ui_story_1017_10170201_82_dialog_content = "De todos modos, simplemente tengo un mal presentimiento sobre esto...",
  ui_story_1017_10170201_83_dialog_content = "Entiendo. Eres un Caelestite, tienes increíbles poderes telequinéticos, bla bla bla...",
  ui_story_1017_10170201_84_dialog_content = "Estaré bien con el oficial Charon cerca!",
  ui_story_1017_10170201_85_dialog_content = "De acuerdo. Pero si te metes en un gran problema, solo... ¡di mi nombre!",
  ui_story_1017_10170201_86_dialog_content = "¿Llamar tu nombre? ¿Puedes escucharlo desde tan lejos?",
  ui_story_1017_10170201_87_dialog_content = "No tengo idea, pero inténtalo de todos modos.",
  ui_story_1017_10170201_88_dialog_content = "Eso es algo raro... Bueno, adiós.",
  ui_story_1017_10170201_89_dialog_content = "Adiós, Vice.",
  ui_story_1017_10170201_90_dialog_content = "<color=#e8d9bb>Golpe... Golpe...</color>",
  ui_story_1017_10170201_X90_dialog_content = "\"Vice\"...",
  ui_story_1017_10170201_91_dialog_content = "Si tienes preguntas, hazlas.",
  ui_story_1017_10170201_92_dialog_content = "No lo entiendo. Figerald lo arriesgó todo por ti, ¿cómo terminó de la manera en que lo hizo?",
  ui_story_1017_10170201_93_dialog_content = "Aquellos que se buscan problemas no terminan bien; no es como si no le hubieran dado una oportunidad.",
  ui_story_1017_10170201_94_dialog_content = "En resumen, el trabajo no se manejó de manera fluida y ambos merecen ser castigados.",
  ui_story_1017_10170201_95_dialog_content = "Es una pena, sin embargo, que al final obtuve lo que quería, haciendo que la misión fuera un éxito.",
  ui_story_1017_10170201_96_dialog_content = "¿Ya ocupado celebrando, Anemone?",
  ui_story_1017_10170201_97_dialog_content = "Lo tenemos.",
  ui_story_1017_10170201_98_dialog_content = "Déjame revisar... Bueno, ¿alguna idea de qué es esto, pequeña chica Illumina?",
  ui_story_1017_10170201_99_dialog_content = "¿No te dije que nunca me llames así?",
  ui_story_1017_10170201_100_dialog_content = "Je, qué ingenuo... Vamos, dime lo que sabes.",
  ui_story_1017_10170201_101_dialog_content = "Una máquina vieja. ¿Pasaste por todos esos problemas solo por esto?",
  ui_story_1017_10170201_102_dialog_content = "Es antiguo, en efecto. Pero pertenece a <color=#FFB400>El Ingeniero</color>. Es solo que, bueno... se quedó atrás en la ciudad de Gannon.",
  ui_story_1017_10170201_103_dialog_content = "¿El Ingeniero?",
  ui_story_1017_10170201_104_dialog_content = "Parece que realmente estás en la oscuridad, pequeña chica Illumina.",
  ui_story_1017_10170201_105_dialog_content = "El Ingeniero ha estado presente desde antes de la historia de Illumina. Illumina no sería nada sin él.",
  ui_story_1017_10170201_106_dialog_content = "¿Qué planeas hacer?",
  ui_story_1017_10170201_107_dialog_content = "Devolver las cosas a su legítimo dueño, obviamente. El mundo es mucho más de lo que has visto. Una vez que El Ingeniero despierte, obtendrás una perspectiva más amplia.",
  ui_story_1017_10170201_108_dialog_content = "Oh, ¿acaso te interesa desplegar una alfombra roja para la llegada del Ingeniero...",
  ui_story_1017_10170201_109_dialog_content = "Extendiendo desde el Salón del Eclipse hasta el mismo núcleo de Astra...",
  ui_story_1017_10170201_110_dialog_content = "Una alfombra roja colosal tejida a partir de la mezcla de Darkflow y los restos de Aurorianos... Apuesto a que eso seguramente sería todo un espectáculo.",
  ui_story_1017_10170201_111_dialog_content = "¿Y qué obtengo yo de esto?",
  ui_story_1017_10170201_112_dialog_content = "Trabajar para Eclipse ya es una benevolencia que se te ha otorgado.",
  ui_story_1017_10170201_113_dialog_content = "Basta de charlas, Asmodeus. ¿No se supone que debes regresar e informar?",
  ui_story_1017_10170201_114_dialog_content = "Eres muy divertido en las fiestas...",
  ui_story_1017_10170201_115_dialog_content = "¿Qué tal esto: tú te encargas de poner la \"alfombra roja\" y te prometo que, una vez terminado el trabajo, habrá un lugar para ti dentro del Eclipse.",
  ui_story_1017_10170201_116_dialog_content = "Sabes muy bien que es más fácil decirlo que hacerlo.",
  ui_story_1017_10170201_117_dialog_content = "Descuida. Entre la chatarra que has inventado, sorprendentemente hay algo realmente útil. Te lo llevaré.",
  ui_story_1017_10170201_118_dialog_content = "Si El Ingeniero supiera que fuiste tú quien orquestó todo esto, ¿no querría conocer a uno de sus parientes de Illumina?",
  ui_story_1017_10170201_119_dialog_content = "Me encargaré de ello, pero mientras tanto tengo algunos asuntos personales que tratar.",
  ui_story_1017_10170201_120_dialog_content = "Haz lo que quieras. Sin embargo, Forsakin, tal vez quieras acelerar un poco las cosas. Tus camaradas de Illumina se están impacientando.",
  ui_story_1017_10170201_121_dialog_content = "Ya lo había deducido. No necesitaba que me lo dijeras.",
  ui_story_1017_10170201_122_dialog_content = "Concéntrate en tu negocio. Esas molestas plagas pueden dejarse a los Eclipsites.",
  ui_story_1017_10170202_1_dialog_content = "¡Todo despejado, Capitán! ¡Los Eclipsites han sido eliminados!",
  ui_story_1017_10170202_2_dialog_content = "¿No dije que no me llames capitán?",
  ui_story_1017_10170202_3_dialog_content = "Los que se adelantaron ya se fueron. Los que tú enfrentaste—",
  ui_story_1017_10170202_4_dialog_content = "¡Eso! ¡Es! ¡Aburrido!",
  ui_story_1017_10170202_5_dialog_content = "Pero Capitán Pepita, ¡aquellos a los que seguimos son adversarios notablemente poderosos!",
  ui_story_1017_10170202_6_dialog_content = "¡Los datos de Darkflow en el tablero están casi en su punto máximo!",
  ui_story_1017_10170202_7_dialog_content = "Por eso dije que simplemente los atropelláramos cuando aparecieron esos tres.",
  ui_story_1017_10170202_8_dialog_content = "En cambio, seguía siendo interrumpido por informes sobre esto y aquello... Puedo tolerar que ustedes arruinen mi diversión, pero no será su cabeza la que ruede por perder a nuestros objetivos!",
  ui_story_1017_10170202_9_dialog_content = "Capitán, solo estoy siguiendo el protocolo de reconocimiento, informando todo tal como lo veo.",
  ui_story_1017_10170202_10_dialog_content = "Las anomalías climáticas que hemos detectado... la velocidad a la que se propaga el Darkflow hacia el interior del continente... coordenadas en cada kilómetro que avanzamos...",
  ui_story_1017_10170202_11_dialog_content = "Está bien, está bien. Belisaria me prometió que no habría ninguna de estas formalidades.",
  ui_story_1017_10170202_12_dialog_content = "Dado que son tantos, ¿no podrían informar las cosas más rápido?",
  ui_story_1017_10170202_13_dialog_content = "Eh, yo...",
  ui_story_1017_10170202_14_dialog_content = "De todos modos, sigamos adelante. Nuestro objetivo es rastrear el núcleo de Guardian One. Recuperarlo a toda costa es de suma importancia.",
  ui_story_1017_10170202_15_dialog_content = "¡Sí, Capitán! ¿Continuamos en la misma dirección que antes?",
  ui_story_1017_10170202_16_dialog_content = "Estamos cerca de la Zona Oscura. Yo me encargo. Podría caminar este camino con los ojos cerrados.",
  ui_story_1017_10170202_17_dialog_content = "¿Ya? ¡Parece que estamos haciendo un excelente progreso!",
  ui_story_1017_10170202_18_dialog_content = "Es una cosa alcanzar, otra recuperar la cosa.",
  ui_story_1017_10170202_19_dialog_content = "Establezcamos algunas reglas básicas. Si vemos a los Eclipsites intentando retrasarnos de nuevo, yo conduzco el vehículo, ustedes se bajan y despejan el camino.",
  ui_story_1017_10170202_20_dialog_content = "Las cosas son urgentes, así que no voy a reducir la velocidad de nuevo.",
  ui_story_1017_10170202_21_dialog_content = "¡Sí, Capitán!",
  ui_story_1017_10170202_22_dialog_content = "Una vez más, ¡no soy tu capitán!",
  ui_story_1017_10170301_1_dialog_content = "El general no entró en detalles, pero ya se están desplegando soldados en las diferentes zonas de guerra.",
  ui_story_1017_10170301_2_dialog_content = "Pero parece que todo lo del Gran Mariscal simplemente se desvaneció, y ahora esto...",
  ui_story_1017_10170301_3_dialog_content = "Sin un Gran Mariscal en escena, ¿quién tomará las decisiones de ahora en adelante?",
  ui_story_1017_10170301_4_dialog_content = "\"Queridos compatriotas de Illumina, tengo un anuncio muy importante—\"",
  ui_story_1017_10170301_5_dialog_content = "...",
  ui_story_1017_10170301_6_dialog_content = "\"Desde la fundación de la Federación Illumina, los Grandes Mariscales siempre nos han liderado en la lucha contra las invasiones de Eclipsite.\"",
  ui_story_1017_10170301_7_dialog_content = "\"Illumina representa a los aurorianos unidos por los mismos ideales, y el Gran Mariscal siempre ha sido parte de la gloria.\"",
  ui_story_1017_10170301_8_dialog_content = "\"Ahora, sin embargo, quizás sea el momento más crucial en nuestra historia...\"",
  ui_story_1017_10170301_9_dialog_content = "\"Pero aunque el camino sea sombrío, debemos seguir adelante juntos.\"",
  ui_story_1017_10170301_10_dialog_content = "\"Por la presente, en nombre del Comité de Asuntos Militares y Políticos de la Federación Illumina, declaro a todos los compatriotas—\"",
  ui_story_1017_10170301_11_dialog_content = "\"El nuevo Gran Mariscal está listo y capacitado para liderarnos en la guerra contra los Eclipsites.\"",
  ui_story_1017_10170301_12_dialog_content = "\"Aquí brindamos por el Gran Mariscal—\"",
  ui_story_1017_10170301_13_dialog_content = "\"Wrath, ¡y un nuevo futuro para la Federación!\"",
  ui_story_1017_10170301_14_dialog_content = "... ¿General Wrath?!",
  ui_story_1017_10170301_15_dialog_content = "... ¿El nuevo Gran Mariscal?!",
  ui_story_1017_10170301_16_dialog_content = "Entonces resultó ser el General Wrath, ¿verdad?",
  ui_story_1017_10170301_17_dialog_content = "¿Qué están haciendo todos aquí?",
  ui_story_1017_10170301_18_dialog_content = "PlayerName, acabo de recibir noticias de que los Eclipsites están atacando Twilight!",
  ui_story_1017_10170301_19_dialog_content = "¡¿Ahora?!",
  ui_story_1017_10170301_20_dialog_content = "Sí. Los altos mandos de Illumina no perdieron tiempo, incluso al reemplazar al Gran Mariscal.",
  ui_story_1017_10170301_21_dialog_content = "Los extraños sucesos durante el ejercicio militar, el antiguo mariscal encarcelado, los inquietos Eclipsites en las fronteras... Todo esto no puede ser una coincidencia.",
  ui_story_1017_10170301_22_dialog_content = "(Y Vice fue enviado a la Zona Oscura en una misión...)",
  ui_story_1017_10170301_23_dialog_content = "No tenemos tiempo para diseccionarlo ahora, PlayerName.",
  ui_story_1017_10170301_24_dialog_content = "Escuché que tu Coloso fue reparado. Estoy aquí para pedir un aventón de regreso a Twilight.",
  ui_story_1017_10170301_25_dialog_content = "Es la forma más rápida de regresar que se me ocurre.",
  ui_story_1017_10170301_26_dialog_content = "No me opongo a ello, excepto que Gronru todavía ha estado haciendo ajustes en Soroz.",
  ui_story_1017_10170301_27_dialog_content = "Por eso estoy aquí.",
  ui_story_1017_10170301_28_dialog_content = "Todavía estoy lejos de entender a Soroz, pero puede despegar en cualquier momento.",
  ui_story_1017_10170301_29_dialog_content = "¿En serio?",
  ui_story_1017_10170301_30_dialog_content = "Por supuesto.",
  ui_story_1017_10170301_31_dialog_content = "Por favor, PlayerName! El viaje no será fácil, pero debo regresar y ayudar a Twilight.",
  ui_story_1017_10170301_32_dialog_content = "¡Entonces vamos!",
  ui_story_1017_10170301_33_dialog_content = "Ustedes vayan, Leo. Yo intentaré Lumopolis.",
  ui_story_1017_10170301_34_dialog_content = "¿Lumopolis? Incluso Carleen no pudo hacer nada. ¿Qué te hace pensar que tú puedes?",
  ui_story_1017_10170301_35_dialog_content = "No creo que la situación pueda ser peor que aquí.",
  ui_story_1017_10170301_36_dialog_content = "Ustedes regresen con PlayerName. Por nuestro pueblo, tengo que intentarlo sin importar lo difícil que sea.",
  ui_story_1017_10170301_37_dialog_content = "...",
  ui_story_1017_10170301_38_dialog_content = "¿Es así como realmente te sientes?",
  ui_story_1017_10170301_39_dialog_content = "Sí, Crepúsculo está en problemas y los Caballeros de Ironthorn no pueden salvarlo sin ti.",
  ui_story_1017_10170301_40_dialog_content = "Confía en mí, mi objetivo es averiguar qué está pasando en Crepúsculo, e ir a Lumopolis en busca de ayuda también es parte del plan.",
  ui_story_1017_10170301_41_dialog_content = "Sabes lo que puede pasar si nos falta nuestro estratega en la batalla.",
  ui_story_1017_10170301_42_dialog_content = "Tienes PlayerName contigo. Estarás bien, incluso mejor, de hecho.",
  ui_story_1017_10170301_43_dialog_content = "¿Y qué? Tú lideras a los soldados y matas a los Eclipsites, yo traigo buenas noticias más tarde.",
  ui_story_1017_10170301_44_dialog_content = "¿Qué opinas, padre?",
  ui_story_1017_10170301_45_dialog_content = "Tengo fe en todos ustedes.",
  ui_story_1017_10170301_46_dialog_content = "¡Lo daré todo!",
  ui_story_1017_10170301_47_dialog_content = "Ese es el plan, entonces.",
  ui_story_1017_10170301_48_dialog_content = "Cuidarse.",
  ui_story_1017_10170301_49_dialog_content = "Cuidarse.",
  ui_story_1017_10170301_50_dialog_content = "<color=#e8d9bb>Mientras tanto, en el laboratorio de Ulysses</color>",
  ui_story_1017_10170301_51_dialog_content = "Profesor, los datos de simulación de selección direccional para el primer lote de semillas han pasado la prueba de significancia.",
  ui_story_1017_10170301_52_dialog_content = "Nos estamos moviendo más rápido de lo esperado. ¿Esto significa que estamos listos para iniciar los ensayos clínicos?",
  ui_story_1017_10170301_53_dialog_content = "Escuchaste la transmisión. Hay un nuevo Gran Mariscal, así que no podemos cometer errores.",
  ui_story_1017_10170301_54_dialog_content = "Sí, profesor. Pero sus experimentos de investigación nunca han encontrado problemas.",
  ui_story_1017_10170301_55_dialog_content = "Bueno, no creo que debamos quedarnos atrapados en el pasado.",
  ui_story_1017_10170301_56_dialog_content = "Eres demasiado humilde, Doctor. Todo debe estar yendo según el plan.",
  ui_story_1017_10170301_57_dialog_content = "Puedes irte ahora.",
  ui_story_1017_10170301_58_dialog_content = "Sí, Profesor.",
  ui_story_1017_10170301_59_dialog_content = "Para llegar al resultado esperado, un experimento debe someterse a ajustes regulares.",
  ui_story_1017_10170301_60_dialog_content = "¿Es Wrath a quien esperabas?",
  ui_story_1017_10170301_61_dialog_content = "Sabes lo que pienso.",
  ui_story_1017_10170301_62_dialog_content = "Solo tengo un objetivo. Puedo aceptar cualquier cambio siempre que no afecte la estabilidad de Illumina.",
  ui_story_1017_10170301_63_dialog_content = "¿Te parece aceptable el Programa Phospherus 2.0?",
  ui_story_1017_10170301_64_dialog_content = "Los Eclipsites ya están tocando a la puerta de Twilight. El último movimiento de Eclipse está prácticamente hecho a medida para tu proyecto.",
  ui_story_1017_10170301_65_dialog_content = "Nunca confíes en nada cuando se trata de luchar contra los Eclipsites.",
  ui_story_1017_10170301_66_dialog_content = "Tan pronto como terminó la Crisis de Darkover, supe que debía adentrarme en la bio-modificación Aurorian.",
  ui_story_1017_10170301_67_dialog_content = "Y lentamente me di cuenta a lo largo de los años que la Semilla de Forsakin es un componente vital.",
  ui_story_1017_10170301_68_dialog_content = "Espero que tus intenciones coincidan con las mías. Debo recordarte que los celos son un pecado entre los científicos.",
  ui_story_1017_10170301_69_dialog_content = "No viniste aquí para recibir consejería psicológica, ¿verdad?",
  ui_story_1017_10170301_70_dialog_content = "Charlaremos otro día. Por ahora, quiero saber si tus planes para el Programa Phospherus 2.0 son consistentes con los míos.",
  ui_story_1017_10170301_71_dialog_content = "Ya que la mejor manera de dar la bienvenida a un nuevo Gran Mariscal es con una victoria.",
  ui_story_1017_10170301_72_dialog_content = "No es sólo la ira. Espero que su legión debute en el campo de batalla con una presencia completamente nueva.",
  ui_story_1017_10170301_73_dialog_content = "Sabes, Máscara de Hierro, no creo que seas tan imparcial como sugiere tu apodo.",
  ui_story_1017_10170301_74_dialog_content = "Honor, fama, adoración del público... Hubiera sido mejor si te convirtieras en Gran Mariscal.",
  ui_story_1017_10170301_75_dialog_content = "Sé por mis cuarenta años de experiencia que manejar una defensa es mucho más difícil que lanzar una ofensiva.",
  ui_story_1017_10170301_76_dialog_content = "Los jóvenes tienen su propio destino y tenemos que prepararles el terreno.",
  ui_story_1017_10170301_77_dialog_content = "Entonces, que Crepúsculo sea el escenario para Phospherus 2.0.",
  ui_story_1017_10170301_78_dialog_content = "Ya sea Wrath o los soldados Illuminan, todos serán parte de mi plan...",
  ui_story_1017_10170301_79_dialog_content = "conviértete en estrellas de la Federación cuando consigan una aplastante victoria en Crepúsculo.",
  ui_story_1017_10170301_80_dialog_content = "Pasa adelante...",
  ui_story_1017_10170301_81_dialog_content = "Profesor, el experimento de funcionalidad de Eclipsesite de hoy está por comenzar. ¿Quieres observar?",
  ui_story_1017_10170301_82_dialog_content = "¿Interesado, Máscara de Hierro? Aunque es sólo un registro de rutina de los datos de capacidad de Eclipsesite.",
  ui_story_1017_10170301_83_dialog_content = "Iré. Ya he estado sentado en esta banca de hierro suficiente tiempo.",
  ui_story_1017_10170302_1_dialog_content = "Pasa adelante...",
  ui_story_1017_10170302_2_dialog_content = "El ejército del Gran Mariscal se desplegará pronto. ¿Hay algo más que hacer para el experimento?",
  ui_story_1017_10170302_3_dialog_content = "Echa un vistazo a estos informes.",
  ui_story_1017_10170302_4_dialog_content = "Los datos... Muy bien, señor, ¡su proyecto es un éxito!",
  ui_story_1017_10170302_5_dialog_content = "Gracias por permitirme ser parte de este magnífico esfuerzo.",
  ui_story_1017_10170302_6_dialog_content = "Está lejos de ser suficiente.",
  ui_story_1017_10170302_7_dialog_content = "Sentido...?",
  ui_story_1017_10170302_8_dialog_content = "Esta es solo la primera tanda de semillas. Habrá una segunda, tercera...",
  ui_story_1017_10170302_9_dialog_content = "¿Quieres decir que Crepúsculo es una prueba de campo para el primer lote?",
  ui_story_1017_10170302_10_dialog_content = "Sí. Los datos clínicos son fantásticos, pero la investigación científica es una caja de Pandora que es mitad milagros y mitad destrucción.",
  ui_story_1017_10170302_11_dialog_content = "Antes de saber todo lo que hay en este cuadro, todo lo que podemos hacer es seguir mejorando el experimento. Nuestros datos recientes parecen mostrar resultados positivos.",
  ui_story_1017_10170302_12_dialog_content = "Sí, sí, entiendo...",
  ui_story_1017_10170302_13_dialog_content = "Siento duda en ti.",
  ui_story_1017_10170302_14_dialog_content = "Hay algo que no estoy seguro de debería decir.",
  ui_story_1017_10170302_15_dialog_content = "Di lo que piensas.",
  ui_story_1017_10170302_16_dialog_content = "Hay rumores en el pueblo de que los soldados han obtenido poderes aterradores al inyectarse sustancias especiales...",
  ui_story_1017_10170302_17_dialog_content = "¿No es un hecho?",
  ui_story_1017_10170302_18_dialog_content = "Parcialmente, pero me preocupa que afecte nuestros planes en el futuro.",
  ui_story_1017_10170302_19_dialog_content = "¿Es así?",
  ui_story_1017_10170302_20_dialog_content = "Además... Me preocupa que lo que hicimos en el juicio de Reinhardt nos persiga.",
  ui_story_1017_10170302_21_dialog_content = "Je, sé a lo que quieres llegar, Esien.",
  ui_story_1017_10170302_22_dialog_content = "Tu visión es limitada porque eres uno de los miembros más jóvenes del Comité.",
  ui_story_1017_10170302_23_dialog_content = "No entiendo lo que quiere decir, señor.",
  ui_story_1017_10170302_24_dialog_content = "Tenía las mismas preocupaciones cuando tenía tu edad.",
  ui_story_1017_10170302_25_dialog_content = "Seguí los procedimientos del experimento al pie de la letra e hice planes de contingencia para cada resultado posible...",
  ui_story_1017_10170302_26_dialog_content = "En ese entonces, disfrutaba mucho la sensación de tener el control de todo.",
  ui_story_1017_10170302_27_dialog_content = "Pero ese mismo perfeccionismo es lo que me causó grandes pérdidas.",
  ui_story_1017_10170302_28_dialog_content = "¿Qué perdiste?",
  ui_story_1017_10170302_29_dialog_content = "Avances, sorpresas, todo lo que pueda llamarse un milagro.",
  ui_story_1017_10170302_30_dialog_content = "Pero señor, ¿no es \"reglas, planes, ejecución, repetición\" el apodo que se les ha inculcado a los Illuminan desde la juventud?",
  ui_story_1017_10170302_31_dialog_content = "Reitero. Aún eres joven y deberías explorar tu propio camino.",
  ui_story_1017_10170302_32_dialog_content = "El orden es un concepto ridículo. El caos es la verdadera naturaleza del mundo.",
  ui_story_1017_10170302_33_dialog_content = "...",
  ui_story_1017_10170302_34_dialog_content = "¿Convertirse en el mejor científico de Illumina es su sueño, señor?",
  ui_story_1017_10170302_35_dialog_content = "¿No soy eso ahora?",
  ui_story_1017_10170302_36_dialog_content = "¡Seguro que sí!",
  ui_story_1017_10170302_37_dialog_content = "Ven conmigo a inspeccionar el próximo lote de Semillas.",
  ui_story_1017_10170302_38_dialog_content = "¡Sí señor!",
  ui_story_1017_10170401_1_dialog_content = "\"Hoy, el Gran Mariscal Wrath liderará la Legión de la Guardia para reforzar Crepúsculo y erradicar a los Eclipsites.\"",
  ui_story_1017_10170401_2_dialog_content = "\"Esta es también el debut del Gran Mariscal desde que asumió el cargo.\"",
  ui_story_1017_10170401_3_dialog_content = "\"Se informa que los soldados deben pasar por una estricta selección y entrenamiento para convertirse en élites de combate para la Legión de Guardias.\"",
  ui_story_1017_10170401_4_dialog_content = "\"Muchos de los soldados pilotarán el arma más nueva de Illumina, Engine VII, en la batalla.\"",
  ui_story_1017_10170401_5_dialog_content = "\"La Tercera Legión, liderada por el General Hiiro, se ha movilizado.\"",
  ui_story_1017_10170401_6_dialog_content = "\"Muchos soldados y civiles de Illumina se han reunido en espera de la llegada del Gran Mariscal.\"",
  ui_story_1017_10170401_7_dialog_content = "¡Mira! Están aquí—",
  ui_story_1017_10170401_8_dialog_content = "¡Mira esa formación! Tan imponente...",
  ui_story_1017_10170401_9_dialog_content = "\"¡El Gran Mariscal Wrath y la Legión de la Guardia se acercan entre vítores y aplausos!\"",
  ui_story_1017_10170401_10_dialog_content = "\"El Gran Mariscal y los soldados parecen confiados en que la victoria está asegurada. Es como si esto fuera realmente un desfile de victoria.\"",
  ui_story_1017_10170401_11_dialog_content = "\"Junto al Gran Mariscal, todas las miradas también están centradas en Engine VII, desarrollado y construido por la Oficial Técnica Gronru y su equipo.\"",
  ui_story_1017_10170401_12_dialog_content = "Se dice que el proceso de creación tuvo que superar varios contratiempos. Hoy te traeré los detalles en vivo.",
  ui_story_1017_10170401_13_dialog_content = "¡Ay! Eso duele...",
  ui_story_1017_10170401_14_dialog_content = "Lo siento...",
  ui_story_1017_10170401_15_dialog_content = "¡Oye, te conozco... Eres Axelia, ganador del partido de exhibición!",
  ui_story_1017_10170401_16_dialog_content = "¡Estás con la Legión de la Guardia! ¡Eso te hace más impresionante que el Gran Mariscal Reinhardt!",
  ui_story_1017_10170401_17_dialog_content = "El Cyborg de Combate Axelia fue creado para Illumina.",
  ui_story_1017_10170401_18_dialog_content = "La Legión de la Guardia... ¿Son todas cosas así?",
  ui_story_1017_10170401_19_dialog_content = "Mira su físico, es totalmente diferente al nuestro...",
  ui_story_1017_10170401_20_dialog_content = "Capaz de liderar a estos soldados en la guerra, el Gran Mariscal Wrath es realmente algo especial...",
  ui_story_1017_10170401_21_dialog_content = "¡Sí, es evidente que ella es incluso más poderosa que el Gran Mariscal Reinhardt!",
  ui_story_1017_10170401_22_dialog_content = "¿Has notado lo serio que luce el general Hiiro?",
  ui_story_1017_10170401_23_dialog_content = "Ella siempre luce así.",
  ui_story_1017_10170401_24_dialog_content = "El gran mariscal no puede oírte si sólo estás susurrando.",
  ui_story_1017_10170401_25_dialog_content = "Co-Comandante! Solo estábamos...",
  ui_story_1017_10170401_26_dialog_content = "Puedes guardar las explicaciones para tu comandante.",
  ui_story_1017_10170401_27_dialog_content = "Comandante...",
  ui_story_1017_10170401_28_dialog_content = "¿Qué hace aquí, coronel Yingel? ¿No quería perderse la primera aparición pública del nuevo gran mariscal?",
  ui_story_1017_10170401_29_dialog_content = "Solo me preocupa Axelia.",
  ui_story_1017_10170401_30_dialog_content = "Siendo ella la obra maestra de Ulises y todo eso, ¿de qué tienes que preocuparte?",
  ui_story_1017_10170401_31_dialog_content = "Axelia estaba al límite en esa pelea, pero Ulysses no lo pensaba así...",
  ui_story_1017_10170401_32_dialog_content = "Puedes leer su mente, impresionante.",
  ui_story_1017_10170401_33_dialog_content = "Puede que no sea justo para los soldados en el Programa Phospherus, pero Ulysses sí sacrificó mucho.",
  ui_story_1017_10170401_34_dialog_content = "¿Entonces enviar a los aurorianos a la batalla como armas desechables no es un sacrificio? ¡El proyecto Ulysses está sacudiendo los cimientos de Illumina!",
  ui_story_1017_10170401_35_dialog_content = "La Federación construida sobre la carne y sangre de los Aurorianos está al borde de la extinción, ¡y ustedes dos aún toman su partido!",
  ui_story_1017_10170401_36_dialog_content = "Carne y sangre... ¿Realmente crees que eso solo puede defenderse de los Eclipsites?",
  ui_story_1017_10170401_37_dialog_content = "Claro que no.",
  ui_story_1017_10170401_38_dialog_content = "Pero en las innumerables guerras con los eclipses durante todos estos años, nunca abandonamos nuestra dignidad como aurorianos como lo estamos haciendo hoy.",
  ui_story_1017_10170401_39_dialog_content = "Los sacrificios que Axelia, los soldados y tú hicisteis no nos harán ganar la paz. Sólo harán que el público tenga más miedo a los eclipses.",
  ui_story_1017_10170401_40_dialog_content = "¡Esto no es diferente a entregarnos a ellos!",
  ui_story_1017_10170401_41_dialog_content = "Odio la guerra, pero tampoco me rendiré. Si Illumina me necesita, lucharé por Illumina.",
  ui_story_1017_10170401_42_dialog_content = "Recuerde esas palabras, coronel Yingel, mientras observa a estos soldados a punto de partir hacia la guerra.",
  ui_story_1017_10170401_43_dialog_content = "Probablemente no se den cuenta del sacrificio que van a hacer y Axelia tampoco, pero tú sí.",
  ui_story_1017_10170401_44_dialog_content = "...",
  ui_story_1017_10170401_45_dialog_content = "\"El Gran Mariscal Wrath ha tomado posición frente a la Legión de Guardias...\"",
  ui_story_1017_10170401_46_dialog_content = "¡Atención, todos los soldados Illuminan!",
  ui_story_1017_10170401_47_dialog_content = "Yo, Gran Mariscal Wrath de la Federación Illumina, por la presente declaro:",
  ui_story_1017_10170401_48_dialog_content = "Los eclipses han invadido Crepúsculo, devastando a nuestros hermanos estacionados allí. ¡Hoy nos dirigiremos a la frontera y nos desharemos de todos ellos!",
  ui_story_1017_10170401_49_dialog_content = "La Legión de la Guardia se ha reunido hoy para representar lo mejor de Illumina. Has sido elegido para encabezar el batallón conmigo y luchar por nuestra gloria.",
  ui_story_1017_10170401_50_dialog_content = "¡Debemos ganar esta batalla por cualquier medio necesario! ¡Esplendor Illumina!",
  ui_story_1017_10170401_51_dialog_content = "Esplendor Ilumina!!!",
  ui_story_1017_10170401_52_dialog_content = "Atención, Comandante Hiiro de la 3ra Legión!",
  ui_story_1017_10170401_53_dialog_content = "¡Sí!",
  ui_story_1017_10170401_54_dialog_content = "Prepare a sus hombres, envíe órdenes y prepárese para el despliegue.",
  ui_story_1017_10170401_55_dialog_content = "¡Sí!",
  ui_story_1017_10170401_56_dialog_content = "Legión de Guardias, ¡marcha!",
  ui_story_1017_10170401_57_dialog_content = "¡¡¡Sí!!!",
  ui_story_1017_10170401_58_dialog_content = "¿Puedes creerlo... realmente estamos en espera de órdenes?",
  ui_story_1017_10170401_59_dialog_content = "Esta aura... ¡es más que intimidante!",
  ui_story_1017_10170401_60_dialog_content = "¿Acaba de tocar su placa de solapa?",
  ui_story_1017_10170401_61_dialog_content = "Sí, lo vi.",
  ui_story_1017_10170401_62_dialog_content = "Aun así, ella lo hizo.",
  ui_story_1017_10170401_63_dialog_content = "Bueno, pero me pregunto qué estará pasando por su mente en este momento...",
  ui_story_1017_10170401_64_dialog_content = "...",
  ui_story_1017_10170401_65_dialog_content = "(Así que esto es lo que se siente al ser un Gran Mariscal al mando de todo el ejército.)",
  ui_story_1017_10170401_66_dialog_content = "(Debes haberte acostumbrado a esto después de todos estos años, Reinhardt...)",
  ui_story_1017_10170401_67_dialog_content = "(Me pregunto qué estabas pensando cuando estuviste aquí por primera vez).",
  ui_story_1017_10170401_68_dialog_content = "(¿Sabías ya que el puesto era tuyo o te alegrabas de que tu incansable esfuerzo y sacrificio finalmente hubieran dado sus frutos...?)",
  ui_story_1017_10170401_69_dialog_content = "Creo que eres muy capaz. Seamos amigos.",
  ui_story_1017_10170401_70_dialog_content = "¿Amigos? No necesito amigos. Todo lo que necesito es entrenamiento.",
  ui_story_1017_10170401_71_dialog_content = "(Me recordaba constantemente que la amistad me debilitaría, así que no quería ser tu amigo.)",
  ui_story_1017_10170401_72_dialog_content = "(Hice de convertirme en Gran Mariscal mi objetivo y seguí perfeccionándome para lograrlo).",
  ui_story_1017_10170401_73_dialog_content = "(Pero justo cuando pensé que había llegado lo suficientemente lejos...)",
  ui_story_1017_10170401_74_dialog_content = "Estos son los últimos dispositivos de manipulación de energía desarrollados por el departamento de investigación. Vamos a pedirle a Reinhardt que venga adelante y nos haga una demostración.",
  ui_story_1017_10170401_75_dialog_content = "¿Ella?",
  ui_story_1017_10170401_76_dialog_content = "Entre todos ustedes, ella es la única capaz de un control perfecto.",
  ui_story_1017_10170401_77_dialog_content = "...",
  ui_story_1017_10170401_78_dialog_content = "(Controlar el dispositivo de energía, ¿verdad? Está bien, dedicaré diez veces más tiempo para perfeccionarlo.)",
  ui_story_1017_10170401_79_dialog_content = "(Cuando llegue el momento del simulacro oficial, no habrá ninguna brecha de habilidades entre nosotros).",
  ui_story_1017_10170401_80_dialog_content = "Reinhardt, Wrath, ustedes dos ahora son un equipo. Y Reinhardt, serás responsable de transmitir las órdenes de combate.",
  ui_story_1017_10170401_81_dialog_content = "¿Por qué no puedo hacer eso?",
  ui_story_1017_10170401_82_dialog_content = "Transmitir órdenes de combate afecta directamente la seguridad de tu equipo.",
  ui_story_1017_10170401_83_dialog_content = "Asegúrate de observar y aprender los fundamentos del liderazgo de equipo mientras estás en acción.",
  ui_story_1017_10170401_84_dialog_content = "...",
  ui_story_1017_10170401_85_dialog_content = "(Liderar escuadrones, ser responsable de la seguridad de los soldados... Nunca dejé de aprender y progresar, y gradualmente, fui ganando seguidores).",
  ui_story_1017_10170401_86_dialog_content = "¡Felicidades! Wrath of the 1st Legion, ¡has sido ascendido a Capitán! Sigan con el gran trabajo en futuras misiones.",
  ui_story_1017_10170401_87_dialog_content = "(Todo salió como esperaba. Solo necesitaba una oportunidad para demostrar mi valía.)",
  ui_story_1017_10170401_88_dialog_content = "(Pero cuando los Eclipsites atacaron Subciudad 19...)",
  ui_story_1017_10170401_89_dialog_content = "(Fui el primero en recibir la orden de ir a soporte, solo para que tú me quitaras la misión y el crédito...)",
  ui_story_1017_10170401_90_dialog_content = "Y la Medalla de Contribución Illumina se otorga a—Reinhardt!",
  ui_story_1017_10170401_91_dialog_content = "(Siempre atacaste primero y, debido a lo sobresaliente que eras, se agregaron muchos criterios innecesarios a las evaluaciones de promoción.)",
  ui_story_1017_10170401_92_dialog_content = "(No tenía ninguna ambición de buscar méritos fuera del campo de batalla. ¡Los guerreros tenían que resolver las cosas como guerreros!)",
  ui_story_1017_10170401_93_dialog_content = "(¡Así que finalmente me di cuenta de que no tenía motivos para no desafiarte directamente!)",
  ui_story_1017_10170401_94_dialog_content = "Ahora no es el momento de actuar según tus emociones. ¡Todavía tenemos muchos eclipses a nuestro alrededor!",
  ui_story_1017_10170401_95_dialog_content = "Déjense de tonterías y tomen las armas. O me matas o reconoces que soy más poderoso que tú.",
  ui_story_1017_10170401_96_dialog_content = "Que inmaduro.",
  ui_story_1017_10170401_97_dialog_content = "Pato—",
  ui_story_1017_10170401_98_dialog_content = "No tienes que matar Eclipses por mí. ¡Dije, levanta tu arma y tráela!",
  ui_story_1017_10170401_99_dialog_content = "Lo diré de nuevo, ¡no te dejes llevar y concéntrate en la batalla!",
  ui_story_1017_10170401_100_dialog_content = "Vete al infierno—",
  ui_story_1017_10170401_101_dialog_content = "¿Vas a aceptar mi desafío después de lidiar con los Eclipsites?",
  ui_story_1017_10170401_102_dialog_content = "Mientras vivas, lo que quieras.",
  ui_story_1017_10170401_103_dialog_content = "¡Acuerdo!",
  ui_story_1017_10170401_104_dialog_content = "¡Ni se os ocurra interponerme en mi camino, Eclipses!",
  ui_story_1017_10170502_1_dialog_content = "(Qué familiar era para mí terminar cada desafío contra ti en la misma posición.)",
  ui_story_1017_10170502_2_dialog_content = "(En entrenamiento o en una pelea real, nunca perdiste ni una sola vez. ¿Cómo lograste eso?)",
  ui_story_1017_10170502_3_dialog_content = "(Con eso en mente, nos enfrentamos nuevamente en la batalla final por el título de Gran Mariscal...)",
  ui_story_1017_10170502_4_dialog_content = "Nuestro ganador es... Reinhardt!",
  ui_story_1017_10170502_5_dialog_content = "¡Felicidades a Reinhardt por convertirse en el Gran Mariscal de la Federación Illumina!",
  ui_story_1017_10170502_6_dialog_content = "¡Gran Mariscal Reinhardt!",
  ui_story_1017_10170502_7_dialog_content = "Aunque Wrath pudo haberse quedado corta esta vez, su habilidad como soldado de Illumina sigue siendo incuestionable.",
  ui_story_1017_10170502_8_dialog_content = "(¡No puedo aceptar esto, aún no he terminado!)",
  ui_story_1017_10170502_9_dialog_content = "(¡Te desafiaré de nuevo!)",
  ui_story_1017_10170502_10_dialog_content = "(¡100 veces más si no puedo hacerlo en 10, y 1,000 veces más si no puedo hacerlo en 100!)",
  ui_story_1017_10170502_11_dialog_content = "Volvamos. El pronóstico decía que el clima estaría mal hoy. Probablemente esté lloviendo en la superficie.",
  ui_story_1017_10170502_12_dialog_content = "No necesito tu lástima.",
  ui_story_1017_10170502_13_dialog_content = "Para mí, no eres alguien a quien compadecer, sino un amigo mío.",
  ui_story_1017_10170502_14_dialog_content = "¿Amigo?",
  ui_story_1017_10170502_15_dialog_content = "Sí, un amigo que siempre se interpone y nos mejora a ambos.",
  ui_story_1017_10170502_16_dialog_content = "¿A quién llamas amigo? Nunca somos amigos.",
  ui_story_1017_10170502_17_dialog_content = "(No tengo amigos, nada excepto tú como objetivo.)",
  ui_story_1017_10170502_18_dialog_content = "Luchamos por el futuro de Illumina, pero deberíamos estar usando nuestros puños contra un enemigo común en una verdadera pelea.",
  ui_story_1017_10170502_19_dialog_content = "Tu futuro está en la palma de tu mano. Si lo mantienes cerrado, terminarás con nada.",
  ui_story_1017_10170502_20_dialog_content = "Toma tu insignia de Gran Mariscal y celebra. Seguiré persiguiéndote.",
  ui_story_1017_10170502_21_dialog_content = "No te daré tregua, incluso si eres el Gran Mariscal.",
  ui_story_1017_10170502_22_dialog_content = "Si puedes vencerme, el asiento es tuyo.",
  ui_story_1017_10170502_23_dialog_content = "¿Estás tan seguro de que me ganarás por el resto de tu vida?",
  ui_story_1017_10170502_24_dialog_content = "...",
  ui_story_1017_10170502_25_dialog_content = "¿Lo estás?",
  ui_story_1017_10170502_26_dialog_content = "Sí lo soy.",
  ui_story_1017_10170502_27_dialog_content = "Entonces cuida tu espalda, porque voy tras de ti.",
  ui_story_1017_10170502_28_dialog_content = "Ya sea el título de Gran Mariscal u otro, ¡te lo quitaré con el tiempo!",
  ui_story_1017_10170502_29_dialog_content = "(¿Quién podría haber imaginado que te reemplacé, pero no de la manera que quería?)",
  ui_story_1017_10170502_30_dialog_content = "(Escucho tanto vítores como abucheos, pero no soy un títere como tú.)",
  ui_story_1017_10170502_31_dialog_content = "(Aquellos que esperan que me adapte solo verán a alguien más...)",
  ui_story_1017_10170502_32_dialog_content = "(Un Gran Mariscal recalcitrante.)",
  ui_story_1017_10170601_1_dialog_content = "<color=#e8d9bb>En el pueblo de Crepúsculo, una multitud de residentes se dirige hacia el hospital...</color>",
  ui_story_1017_10170601_2_dialog_content = "Aguanta un poco más. El <color=#FFB400>hospital</color> está justo adelante.",
  ui_story_1017_10170601_3_dialog_content = "Mis piernas me han abandonado...",
  ui_story_1017_10170601_4_dialog_content = "Vamos. Te cargaré. Las zonas de guerra cercanas están infestadas de Eclipsites. No se sabe si vendrán por aquí.",
  ui_story_1017_10170601_5_dialog_content = "¡Argh! Ay, ay...",
  ui_story_1017_10170601_6_dialog_content = "Ponla en la camilla.",
  ui_story_1017_10170601_7_dialog_content = "¿Mmm? Y tú eres...",
  ui_story_1017_10170601_8_dialog_content = "Firme y cuidado con su pierna.",
  ui_story_1017_10170601_9_dialog_content = "Entendido, Joselyne.",
  ui_story_1017_10170601_10_dialog_content = "Trabajas en el hospital, ¿verdad?",
  ui_story_1017_10170601_11_dialog_content = "Hola, soy Joselyne y junto a mí está una enfermera del hospital.",
  ui_story_1017_10170601_12_dialog_content = "Encantado de conocerlos a todos. Soy Chi.",
  ui_story_1017_10170601_13_dialog_content = "Chi, eres tan joven, pero es increíble lo capaz que eres.",
  ui_story_1017_10170601_14_dialog_content = "¡Jeje!",
  ui_story_1017_10170601_15_dialog_content = "Joselyne...",
  ui_story_1017_10170601_16_dialog_content = "¡Ah! No serás... ¿la Santa de la Iglesia de la Noche Blanca, verdad?",
  ui_story_1017_10170601_17_dialog_content = "¿Santa?!",
  ui_story_1017_10170601_18_dialog_content = "No, no soy la Santa. Solo soy una persona común.",
  ui_story_1017_10170601_19_dialog_content = "¿Qué es la Santa, Joselyne?",
  ui_story_1017_10170601_20_dialog_content = "La Santa es la diosa viviente que cuida a las personas del Dios de la Luz.",
  ui_story_1017_10170601_21_dialog_content = "Mientras la Santa esté aquí, los Eclipsites no se atreverán a poner un pie en nuestras casas.",
  ui_story_1017_10170601_22_dialog_content = "¡Guau! ¿Es esto de verdad, Su Santidad?",
  ui_story_1017_10170601_23_dialog_content = "En realidad, no soy una Santa. Solo llámame Joselyne.",
  ui_story_1017_10170601_24_dialog_content = "Aunque creo que La Luz cortará la oscuridad y será el faro eterno para todas las personas.",
  ui_story_1017_10170601_25_dialog_content = "Haré lo mejor que pueda hasta ese día.",
  ui_story_1017_10170601_26_dialog_content = "\"Dios de la Luz\", ¿de qué se trata todo eso? Es realmente desconcertante, Joselyne...",
  ui_story_1017_10170601_27_dialog_content = "Eso significa que el bien derrotará al mal y todos seremos abrazados por el Dios de la Luz.",
  ui_story_1017_10170601_28_dialog_content = "Joselyne—",
  ui_story_1017_10170601_29_dialog_content = "¿Cómo va todo en el hospital, Joselyne?",
  ui_story_1017_10170601_30_dialog_content = "Nunca hemos tenido tanta gente aquí a la vez, pero aún deberíamos tener espacio.",
  ui_story_1017_10170601_31_dialog_content = "¿Cómo está en la primera línea?",
  ui_story_1017_10170601_32_dialog_content = "¡Ay! Los Eclipsites realizaron un ataque repentino, golpeándonos fuertemente. ¡Nuestros soldados han sufrido muchas bajas!",
  ui_story_1017_10170601_33_dialog_content = "Las defensas exteriores de Crepúsculo se han derrumbado, dejando a numerosos residentes bajo ataque...",
  ui_story_1017_10170601_34_dialog_content = "¡Santo cielo!",
  ui_story_1017_10170601_35_dialog_content = "Se acabó. Todo se acabó...",
  ui_story_1017_10170601_36_dialog_content = "¿No hay noticias de Leo y los demás en absoluto?",
  ui_story_1017_10170601_37_dialog_content = "Enviamos mensajes hace un tiempo, ¡pero no hay señales del capitán!",
  ui_story_1017_10170601_38_dialog_content = "Llevaré el caballo y el equipo del Capitán a la <color=#FFB400>puerta</color> de Crepúsculo para recibirlo.",
  ui_story_1017_10170601_39_dialog_content = "Cuando el Capitán estaba ausente, este caballo parecía ansioso por luchar por él, lanzándose a la batalla y escapando por poco de los daños causados por los Eclipsites.",
  ui_story_1017_10170601_40_dialog_content = "Los Caballeros de Ironthorn aún están en plena batalla... Saldré primero. Las cosas aquí están en tus manos ahora.",
  ui_story_1017_10170601_41_dialog_content = "Noche Blanca en lo alto—",
  ui_story_1017_10170601_42_dialog_content = "Chi, por favor ayuda a este hombre a llevar a la mujer herida al hospital.",
  ui_story_1017_10170601_43_dialog_content = "Y dile a la enfermera jefa que envíe más médicos a las afueras de Crepúsculo.",
  ui_story_1017_10170601_44_dialog_content = "¿A dónde vas, Joselyne?",
  ui_story_1017_10170601_45_dialog_content = "Al campo de batalla.",
  ui_story_1017_10170601_46_dialog_content = "¿Al campo de batalla? Digo... deberían ser los guerreros quienes vayan al campo de batalla, ¿verdad?",
  ui_story_1017_10170601_47_dialog_content = "Soy un guerrero, y ahí es donde debería estar en este momento.",
  ui_story_1017_10170601_48_dialog_content = "Lo tienes, Chi. Nos vemos luego.",
  ui_story_1017_10170601_49_dialog_content = "...",
  ui_story_1017_10170601_50_dialog_content = "¿Estás dispuesto a hacerlo?",
  ui_story_1017_10170601_51_dialog_content = "La edad no me define; ¡tengo una fuerza impresionante!",
  ui_story_1017_10170601_52_dialog_content = "<color=#e8d9bb>Joselyne se aventura en las afueras de la zona de guerra...</color>",
  ui_story_1017_10170601_53_dialog_content = "¡Cuida tus pies!",
  ui_story_1017_10170601_54_dialog_content = "¡Sin piedad!",
  ui_story_1017_10170601_55_dialog_content = "Pensé que este estaba fuera de servicio.",
  ui_story_1017_10170601_56_dialog_content = "Ten cuidado con los enemigos caídos. A veces, sus ataques pueden ser los más letales.",
  ui_story_1017_10170601_57_dialog_content = "Entendido. ¡Gracias por el recordatorio!",
  ui_story_1017_10170601_58_dialog_content = "Son las enseñanzas del Capitán; ahora, sin él presente, algo parece faltar.",
  ui_story_1017_10170601_59_dialog_content = "Todos pueden que no lo digan en voz alta, pero en el fondo, definitivamente están preocupados...",
  ui_story_1017_10170601_60_dialog_content = "Puedo empatizar... Esta es la primera vez que veo tantos Eclipsites.",
  ui_story_1017_10170601_61_dialog_content = "¿Sabes qué es lo que buscan?",
  ui_story_1017_10170601_62_dialog_content = "No tengo ni idea. Toda la operación es un desastre caótico y nuestras líneas de defensa siguen cediendo...",
  ui_story_1017_10170601_63_dialog_content = "Si seguimos así, Crepúsculo será una causa perdida.",
  ui_story_1017_10170601_64_dialog_content = "¡Detrás tuyo!",
  ui_story_1017_10170601_65_dialog_content = "¡Uh!",
  ui_story_1017_10170601_66_dialog_content = "¿Cómo puedes, Caballero de Ironthorn, ser tan pesimista?",
  ui_story_1017_10170601_67_dialog_content = "Incluso sin Leo presente, ¡debemos hacer todo lo posible para eliminar a los Eclipsites!",
  ui_story_1017_10170601_68_dialog_content = "Hemos estado estacionados aquí durante mucho tiempo. Así que somos muy conscientes de que Crepúsculo es solo un páramo abandonado, olvidado por los dioses. Si no llega ayuda, los Eclipsites lo devoran a su antojo.",
  ui_story_1017_10170601_69_dialog_content = "Defendemos este lugar simplemente porque nacimos y crecimos aquí, sin otras opciones disponibles.",
  ui_story_1017_10170601_70_dialog_content = "Si tan solo pudiéramos regresar a... ¿Quién soportaría voluntariamente este tormento, luchando por sobrevivir en esta tierra olvidada por Dios?",
  ui_story_1017_10170601_71_dialog_content = "...",
  ui_story_1017_10170601_72_dialog_content = "Dicho todo esto... no significa que me esté echando atrás. Sin embargo, incluso nosotros, los soldados sin nombre, deberíamos saber por qué estamos luchando...",
  ui_story_1017_10170601_73_dialog_content = "¿Es mucho pedir?",
  ui_story_1017_10170601_74_dialog_content = "¿Proteger este lugar no es una razón suficientemente buena?",
  ui_story_1017_10170601_75_dialog_content = "Los niños locales que nunca vieron el exterior pensaban que Crepúsculo era todo el mundo.",
  ui_story_1017_10170601_76_dialog_content = "Yo creo que todos pensábamos lo mismo antes de darnos cuenta de que hay un mundo más grande allá afuera.",
  ui_story_1017_10170601_77_dialog_content = "Y los soldados que se sacrificaron, ¿no lo hicieron para proteger este pequeño mundo?",
  ui_story_1017_10170601_78_dialog_content = "...",
  ui_story_1017_10170601_79_dialog_content = "Los guerreros no necesitan demostrar su valía en alguna gran batalla.",
  ui_story_1017_10170601_80_dialog_content = "Son geniales simplemente defendiendo un pedazo de tierra.",
  ui_story_1017_10170601_81_dialog_content = "Quizás... Aunque tus palabras contienen verdad, estos últimos años nos han demostrado que todos estamos luchando por el Capitán...",
  ui_story_1017_10170601_82_dialog_content = "Leo también luchó por ti, ¿no es así?",
  ui_story_1017_10170601_83_dialog_content = "En efecto. Para nosotros, él ha sacrificado mucho.",
  ui_story_1017_10170601_84_dialog_content = "Para evitar más pérdidas, ¡protejamos la tierra donde se libraron las batallas!",
  ui_story_1017_10170601_85_dialog_content = "Ya sea que hayas nacido aquí o llegado por diferentes razones, ¡luchemos el uno por el otro!",
  ui_story_1017_10170601_86_dialog_content = "¡Sí, tienes toda la razón! ¡Le diré a los compañeros ahora mismo!",
  ui_story_1017_10170601_87_dialog_content = "¡Escuchen! ¡Caballeros de Ironthorn! Permitir que esos Eclipsites avancen una pulgada más es un insulto para nuestros hermanos caídos.",
  ui_story_1017_10170601_88_dialog_content = "Recuerda esto sobre los Caballeros de Ironthorn: no se trata solo del hierro en nuestra armadura, sino también del hierro en nuestra determinación y espíritu.",
  ui_story_1017_10170601_89_dialog_content = "¡No cederemos ni un centímetro a esos Eclipsites, aunque eso signifique que tengamos que construir muros con nuestra propia carne!",
  ui_story_1017_10170601_90_dialog_content = "¡Todos juntos ahora!",
  ui_story_1017_10170601_91_dialog_content = "¡Yo también!",
  ui_story_1017_10170601_92_dialog_content = "¡Defendamos Crepúsculo con nuestras vidas!",
  ui_story_1017_10170601_93_dialog_content = "¡Defendamos Crepúsculo con nuestras vidas!",
  ui_story_1017_10170602_1_dialog_content = "¿Ya casi estamos en Crepúsculo, Soroz?",
  ui_story_1017_10170602_2_dialog_content = "PlayerName, has hecho la misma pregunta 10 veces en el último minuto.",
  ui_story_1017_10170602_3_dialog_content = "Estoy muy nervioso...",
  ui_story_1017_10170602_4_dialog_content = "Ya veo. He revisado si hay alguna latencia en nuestra conexión, pero parece que no hay ninguna.",
  ui_story_1017_10170602_5_dialog_content = "Sin retrasos en la comunicación, aunque parece que te estás moviendo muy despacio...",
  ui_story_1017_10170602_6_dialog_content = "Confirmando velocidad de vuelo: siempre mantener <color=#FFB400>velocidad máxima</color>.",
  ui_story_1017_10170602_7_dialog_content = "...",
  ui_story_1017_10170602_8_dialog_content = "Pareces desanimado. ¿Te gustaría compartir la razón conmigo?",
  ui_story_1017_10170602_9_dialog_content = "Acabo de recordar cuánto tiempo atrás fue cuando perdiste el conocimiento.",
  ui_story_1017_10170602_10_dialog_content = "Y ni siquiera me molesté en preguntar cómo estás antes de pedirte que nos lleves a Crepúsculo.",
  ui_story_1017_10170602_11_dialog_content = "Puede que haya sido mucho tiempo para ti, pero en mi programación, nunca hemos estado separados.",
  ui_story_1017_10170602_12_dialog_content = "Supongo que te sientes así, ¿verdad?",
  ui_story_1017_10170602_13_dialog_content = "Puedo presenciar tantos paisajes diferentes solo porque tú y tus amigos tienen muchos lugares a donde ir.",
  ui_story_1017_10170602_14_dialog_content = "Hablando de eso, <color=#FFB400>un nuevo paisaje</color>. Nuestro destino está justo adelante.",
  ui_story_1017_10170602_15_dialog_content = "¿Estamos allí ahora?",
  ui_story_1017_10170602_16_dialog_content = "Casi estamos allí. Por favor, confirma el lugar de aterrizaje.",
  ui_story_1017_10170602_17_dialog_content = "Cuando terminemos en Crepúsculo, te contaré toda la historia.",
  ui_story_1017_10170602_18_dialog_content = "Vamos a reducir la velocidad y volar a baja altitud, luego <color=#FFB400>abramos la escotilla</color>.",
  ui_story_1017_10170602_19_dialog_content = "Desacelerando. Abriendo la <color=#FFB400>Escotilla 3</color>...",
  ui_story_1017_10170602_20_dialog_content = "Leo—",
  ui_story_1017_10170602_21_dialog_content = "Muchas gracias, PlayerName. Cuando todo se calme en Twilight, reconoceré formalmente tu ayuda.",
  ui_story_1017_10170602_22_dialog_content = "Sin problemas. Soroz está descendiendo. ¿Dónde deberíamos aterrizar?",
  ui_story_1017_10170602_23_dialog_content = "¿Ves a ese soldado en la puerta?",
  ui_story_1017_10170602_24_dialog_content = "Veo a alguien... y tal vez tres caballos...",
  ui_story_1017_10170602_25_dialog_content = "Él es uno de mis chicos, esperándome con mi caballo.",
  ui_story_1017_10170602_26_option_content = "¡Tienes una vista estupenda!",
  ui_story_1017_10170602_27_dialog_content = "No puedo creer que puedas distinguir cuál es la persona y cuál es el caballo desde tan lejos.",
  ui_story_1017_10170602_28_dialog_content = "Bueno, Crepúsculo es un lugar excelente para entrenar.",
  ui_story_1017_10170602_29_option_content = "No puedo decir que fue inesperado",
  ui_story_1017_10170602_30_dialog_content = "Definitivamente hay química entre el capitán y sus hombres.",
  ui_story_1017_10170602_31_dialog_content = "Tomó años desarrollarlo.",
  ui_story_1017_10170602_32_dialog_content = "Estaría dispuesto a enseñarte un poco sobre campañas y lucha cuando tengamos la oportunidad.",
  ui_story_1017_10170602_33_dialog_content = "Altitud de aterrizaje alcanzada. PlayerName, por favor confirma el lugar de aterrizaje.",
  ui_story_1017_10170602_34_dialog_content = "¿Qué tal si aterrizamos cerca de esa puerta de allí, Leo?",
  ui_story_1017_10170602_35_dialog_content = "Claro... Casi, casi... Justo aquí, perfecto. Bueno, entonces—",
  ui_story_1017_10170602_36_dialog_content = "Cuida de Joseph por mí, PlayerName!",
  ui_story_1017_10170602_37_dialog_content = "Nos vemos, Joseph.",
  ui_story_1017_10170602_38_dialog_content = "Nos vemos, Leo.",
  ui_story_1017_10170602_39_dialog_content = "¿¿¿???",
  ui_story_1017_10170602_40_dialog_content = "¿Simplemente saltó así?!",
  ui_story_1017_10170602_41_dialog_content = "Oye, ¿qué—sobre—mí—",
  ui_story_1017_10170602_42_dialog_content = "Tú—deberías—volver—atrás—",
  ui_story_1017_10170602_43_dialog_content = "...",
  ui_story_1017_10170602_44_dialog_content = "¡Capitán! ¡Nunca pensé que el que saltó de esa cosa enorme serías tú!",
  ui_story_1017_10170602_45_dialog_content = "¿Es ese... el legendario Coloso?!",
  ui_story_1017_10170602_46_dialog_content = "¡Así es! ¡Lamento hacerte esperar!",
  ui_story_1017_10170602_47_dialog_content = "Vamos a la batalla ahora mismo. Dime, ¿cómo se ve Crepúsculo?",
  ui_story_1017_10170602_48_dialog_content = "Los Eclipsites están avanzando desde la <color=#FFB400>Noche Eterna</color>. Aunque las fortificaciones exteriores han sido violadas, nuestros camaradas aún mantienen su posición.",
  ui_story_1017_10170602_49_dialog_content = "¿Quién lidera a los Eclipsites?",
  ui_story_1017_10170602_50_dialog_content = "No hay un líder específico entre los Eclipsites. ¡Se agrupan en grandes cantidades y sus acciones son puro caos!",
  ui_story_1017_10170602_51_dialog_content = "¿Cuántas bajas hay?",
  ui_story_1017_10170602_52_dialog_content = "Muchos residentes en las afueras fueron atacados. Actualmente los hemos trasladado a zonas más seguras. Cientos de soldados están heridos y también...",
  ui_story_1017_10170602_53_dialog_content = "Hemos perdido a <color=#FFB400>75</color> de nuestros camaradas...",
  ui_story_1017_10170602_54_dialog_content = "¿<color=#FFB400>75</color> perdió?! Entonces, ¿por qué sigues aquí?",
  ui_story_1017_10170602_55_dialog_content = "Capitán... Antes de que regresaras, tu caballo se soltó de las riendas y se lanzó a la batalla, derribando a los Eclipsites...",
  ui_story_1017_10170602_56_dialog_content = "Apenas pude mantenerlo contenido. ¡No tengo idea de qué hacer ahora!",
  ui_story_1017_10170602_57_dialog_content = "¡Hmph, se necesitará mucho más para derrotar a Crepúsculo!",
  ui_story_1017_10170602_58_dialog_content = "¿Hablaste con los pueblos cercanos?",
  ui_story_1017_10170602_59_dialog_content = "Aquellos capaces de luchar ya han venido a apoyarnos... pero algunos pueblos aún luchan por defenderse del peligro por sí mismos.",
  ui_story_1017_10170602_60_dialog_content = "Esta vez, no solo la batalla es desafiante... el consumo de recursos médicos también es increíblemente inmenso...",
  ui_story_1017_10170602_61_dialog_content = "¿No hay ayuda médica de Lumo Stronghold?",
  ui_story_1017_10170602_62_dialog_content = "No. El hospital cuenta con médicos y enfermeras del pueblo. Incluso algunos de los niños mayores se han ofrecido para ayudar...",
  ui_story_1017_10170602_63_dialog_content = "Todo es más difícil cuando está en Crepúsculo.",
  ui_story_1017_10170602_64_dialog_content = "La buena noticia es que volví y no dejaré que los chicos mueran en vano.",
  ui_story_1017_10170602_65_dialog_content = "La mala noticia es que aún solo podemos contar con nosotros mismos.",
  ui_story_1017_10170602_66_dialog_content = "Hmm... Capitán, ¿cómo es que Zhao no está contigo?",
  ui_story_1017_10170602_67_dialog_content = "Está ocupado con algo, pero sé que dará la vuelta a la situación para nosotros a su debido tiempo.",
  ui_story_1017_10170602_68_dialog_content = "¿Es realmente posible cambiar la situación considerando la crisis que enfrenta Twilight?",
  ui_story_1017_10170602_69_dialog_content = "¡Arriba de ti!",
  ui_story_1017_10170602_70_dialog_content = "¡Atrapa!",
  ui_story_1017_10170602_71_dialog_content = "<color=#e8d9bb>El soldado atrapa a PlayerName mientras caen del cielo, y los dos casi se caen de sus caballos...</color>",
  ui_story_1017_10170602_72_dialog_content = "Espera, ¡te conozco! ¡Casi me aplastas por completo!",
  ui_story_1017_10170602_73_dialog_content = "Pensé... ¡que el Coloso también estaba a punto de caerse encima de mí!",
  ui_story_1017_10170602_74_dialog_content = "Lo siento por esto...",
  ui_story_1017_10170602_75_dialog_content = "¿Estás bien?",
  ui_story_1017_10170602_76_option_content = "Estoy bien",
  ui_story_1017_10170602_77_dialog_content = "Soroz estaba navegando a la altitud perfecta.",
  ui_story_1017_10170602_78_option_content = "¿Dónde estoy? ¿Estoy vivo?",
  ui_story_1017_10170602_79_dialog_content = "Pensé que mi corazón iba a parar en la caída.",
  ui_story_1017_10170602_80_dialog_content = "Afortunadamente, Soroz estaba navegando a la altura adecuada.",
  ui_story_1017_10170602_81_dialog_content = "¿Por qué estás aquí?",
  ui_story_1017_10170602_82_dialog_content = "Se supone que debemos llegar a Crepúsculo juntos. ¿Por qué iba a dar marcha atrás?",
  ui_story_1017_10170602_83_dialog_content = "Gracias, pero hasta aquí llegas.",
  ui_story_1017_10170602_84_dialog_content = "Da la vuelta y acompaña a este de regreso.",
  ui_story_1017_10170602_85_dialog_content = "Capitán...",
  ui_story_1017_10170602_86_dialog_content = "¡No quiero perder a más de mis soldados!",
  ui_story_1017_10170602_87_dialog_content = "Vaya, no tengo planes de ser tu soldado.",
  ui_story_1017_10170602_88_dialog_content = "Soroz y yo seremos muy beneficiosos para la batalla en Twilight.",
  ui_story_1017_10170602_89_dialog_content = "Soroz está a la altura perfecta para ver a todo el ejército enemigo en este momento.",
  ui_story_1017_10170602_90_dialog_content = "Puede ser el ojo en el cielo mientras te guío a través de la batalla.",
  ui_story_1017_10170602_91_dialog_content = "El ojo en el cielo es bastante convincente.",
  ui_story_1017_10170602_92_dialog_content = "Dada la ausencia de Zhao, la orientación de PlayerName en el campo de batalla podría ser crucial para nosotros.",
  ui_story_1017_10170602_93_dialog_content = "Eso es verdad.",
  ui_story_1017_10170602_94_dialog_content = "Pero la batalla no es un simulacro o ejercicio. Mueres de verdad.",
  ui_story_1017_10170602_95_dialog_content = "¿Seguro que aún quieres venir?",
  ui_story_1017_10170602_96_dialog_content = "¡Claro!",
  ui_story_1017_10170602_97_dialog_content = "¡Vale, a toda velocidad hacia la batalla!",
  ui_story_1017_10170602_98_dialog_content = "¡Sí, Capitán!",
  ui_story_1017_10170602_99_dialog_content = "Parece que esto no tiene fin...",
  ui_story_1017_10170602_100_dialog_content = "Y aún no vemos un líder para ellos.",
  ui_story_1017_10170602_101_dialog_content = "Todos están exhaustos, Joselyne. No aguantaremos mucho más si seguimos así.",
  ui_story_1017_10170602_102_dialog_content = "La nueva fortaleza aún no está terminada. ¡Si nos rendimos ahora, todo el esfuerzo que gastamos defendiéndola se desperdiciará!",
  ui_story_1017_10170602_103_dialog_content = "Pero la moral está por los suelos. Me temo que incluso si el Capitán regresa, podría no marcar la diferencia...",
  ui_story_1017_10170602_104_dialog_content = "¿Quién dijo que incluso yo no puedo evitarlo?",
  ui_story_1017_10170602_105_dialog_content = "¡Por fin has vuelto! ¡Capitán!",
  ui_story_1017_10170602_106_dialog_content = "¡El Capitán ha vuelto!",
  ui_story_1017_10170602_107_dialog_content = "Muy arriba... es...",
  ui_story_1017_10170602_108_dialog_content = "¡He regresado, mis hermanos Caballeros de Ironthorn!",
  ui_story_1017_10170602_109_dialog_content = "Desde este momento en adelante, ¡muéstrales cómo luce un caballero!",
  ui_story_1017_10170602_110_dialog_content = "PlayerName y Soroz el Coloso nos proporcionarán cobertura!",
  ui_story_1017_10170602_111_dialog_content = "Entonces, ¿este es el legendario Coloso, eh? ¡Es aún más masivo de lo que imaginaba!",
  ui_story_1017_10170602_112_dialog_content = "¡Luchemos junto al Coloso!",
  ui_story_1017_10170602_113_dialog_content = "Así es, tenemos Soroz. ¡Ahora, estén atentos y escuchen mis órdenes!",
  ui_story_1017_10170602_114_dialog_content = "¡Sigue la ruta de vuelo de Soroz a toda velocidad y aplasta a los Eclipsites!",
  ui_story_1017_10170602_115_dialog_content = "¡Sí!",
  ui_story_1017_10170602_116_dialog_content = "Cuento contigo, PlayerName!",
  ui_story_1017_10170602_117_dialog_content = "¡Lo daré todo!",
  ui_story_1017_10170701_1_dialog_content = "El acceso principal a Lumopolis debería estar por aquí...",
  ui_story_1017_10170701_2_dialog_content = "¡Ay!",
  ui_story_1017_10170701_X2_dialog_content = "¡Mordida y Chom!",
  ui_story_1017_10170701_3_dialog_content = "Tan aburrido, ¡tan aburrido! ¿Qué tal si molestamos a alguien?",
  ui_story_1017_10170701_4_dialog_content = "¿Quiénes son ustedes dos?",
  ui_story_1017_10170701_5_dialog_content = "¡Adivina!",
  ui_story_1017_10170701_6_dialog_content = "Por favor, deja de acosarme. Tengo un asunto urgente y debo irme.",
  ui_story_1017_10170701_7_dialog_content = "Pídeme ayuda, ¡pero no puedo garantizar que se hará!",
  ui_story_1017_10170701_8_dialog_content = "...",
  ui_story_1017_10170701_9_dialog_content = "¿Sabes qué camino tomar para llegar a Lumopolis?",
  ui_story_1017_10170701_10_dialog_content = "Nadie quiere ir a ese lugar pálido, flotante y helado.",
  ui_story_1017_10170701_11_dialog_content = "Recuerdo que hay un acceso especial para...",
  ui_story_1017_10170701_12_dialog_content = "Recordatorio amistoso: El acceso a Lumopolis ha sido cerrado.",
  ui_story_1017_10170701_13_dialog_content = "¿Fue cerrado recientemente? ¿Sabes la razón específica por qué?",
  ui_story_1017_10170701_14_dialog_content = "Tienes demasiadas preguntas. Dime tus malas intenciones directamente o—",
  ui_story_1017_10170701_15_dialog_content = "¡Llévame contigo!",
  ui_story_1017_10170701_16_dialog_content = "<size=30>La noticia sobre Illumina se difundió y Lumopolis está reaccionando mucho más rápido de lo que esperaba.</size>",
  ui_story_1017_10170701_17_dialog_content = "<size=30>Quizás pueda pedir prestado transporte de la Unión de Mensajería...</size>",
  ui_story_1017_10170701_18_dialog_content = "<size=30>¿Pero qué excusa puedo dar...?</size>",
  ui_story_1017_10170701_19_dialog_content = "¡Uh!",
  ui_story_1017_10170701_20_dialog_content = "¿Qué estás haciendo?",
  ui_story_1017_10170701_21_dialog_content = "¡No puedes pasar desapercibido ante nuestras narices con la cantidad de conspiraciones que desprendes!",
  ui_story_1017_10170701_22_dialog_content = "No vienes en paz, ¡y te convertiremos en el jefe!",
  ui_story_1017_10170701_23_dialog_content = "¿No puedes oler la pólvora de Crepúsculo en mí? Estoy en una misión urgente, ¡así que por favor déjame salir!",
  ui_story_1017_10170701_24_dialog_content = "Estoy mareado... aquí adentro...",
  ui_story_1017_10170701_25_dialog_content = "¡Esto es Umbraton, no Crepúsculo!",
  ui_story_1017_10170701_26_dialog_content = "Todo lo delicioso está en la basura. ¡Recuerda calentarlo antes de comer!",
  ui_story_1017_10170701_27_dialog_content = "¡Hola, jefe, encontramos algo nuevo, así que no olvides alimentarnos extra!",
  ui_story_1017_10170701_28_dialog_content = "¿No te dije que no trajeras basura vieja?",
  ui_story_1017_10170701_29_dialog_content = "¡No es basura, es un mal tipo! ¡Mira!",
  ui_story_1017_10170701_30_dialog_content = "Sospechoso y astuto.",
  ui_story_1017_10170701_31_dialog_content = "¡Intentó correr cuando nos vio!",
  ui_story_1017_10170701_32_dialog_content = "...",
  ui_story_1017_10170701_33_dialog_content = "¡Oh no, se rompió!",
  ui_story_1017_10170701_34_dialog_content = "¿Qué hace un elegante chico de Illumina como él aquí?",
  ui_story_1017_10170701_35_dialog_content = "Mencionó capturar Lumopolis, destruir la Unión de Mensajeros y cosas así...",
  ui_story_1017_10170701_36_dialog_content = "¡Exacto, y convierte a Umbraton en crepúsculo!",
  ui_story_1017_10170701_37_dialog_content = "¡No, hacia el pueblo de Crepúsculo!",
  ui_story_1017_10170701_38_dialog_content = "¿Crepúsculo?",
  ui_story_1017_10170701_39_dialog_content = "¡Sí, Crepúsculo! ¡Y también apesta a pólvora!",
  ui_story_1017_10170701_40_dialog_content = "Encuéntrame <color=#FFB400>Kleken</color>. Ustedes dos, vayan a comer.",
  ui_story_1017_10170701_41_dialog_content = "¡Claro, jefe! Fuera del trabajo, ¡hora de comer!",
  ui_story_1017_10170701_42_dialog_content = "Señor de la Ciudad, ¿cuánto tiempo más necesitas para tomar una decisión?",
  ui_story_1017_10170701_43_dialog_content = "Estas cartas que tengo vienen directamente de la Fortaleza Lumo.",
  ui_story_1017_10170701_44_dialog_content = "Estamos viendo una disminución del cuarenta por ciento en la producción de las <color=#FFB400>Minas Vok</color> si no enviamos a nuestros soldados ahora.",
  ui_story_1017_10170701_45_dialog_content = "Piénsalo, esto podría llevar a escaseces y alteraciones en nuestras materias primas, y eso afectará aún más el volumen de comercio exterior de Lumopolis...",
  ui_story_1017_10170701_46_dialog_content = "Confía en mí. ¡Las pérdidas no se limitarán solo a estas!",
  ui_story_1017_10170701_47_dialog_content = "¿Cuándo comenzó la seguridad de Crepúsculo a afectar la economía de Lumopolis?",
  ui_story_1017_10170701_48_dialog_content = "Te preocupa la riqueza que has acumulado en Crepúsculo a lo largo de los años, ¿verdad?",
  ui_story_1017_10170701_49_dialog_content = "¡Tonterías! Aunque la Casa <color=#FFB400>Dietrich</color> puede que no tenga raíces antiguas, hemos estado extrayendo recursos durante años, abasteciendo a Lumopolis...",
  ui_story_1017_10170701_50_dialog_content = "Y en tiempos difíciles, hemos ofrecido refugio a numerosos caballeros exiliados...",
  ui_story_1017_10170701_51_dialog_content = "Teniendo en cuenta nuestras contribuciones, la Casa <color=#FFB400>Dietrich</color> debería haber sido recompensada con un lugar privilegiado en la Zona residencial hace años!",
  ui_story_1017_10170701_52_dialog_content = "Ahora, <color=#FFB400>Troy</color>, aquí está el asunto. Mientras has estado viviendo la buena vida junto al Señor de la Ciudad, apuesto a que tu habilidad para lidiar con esos Eclipsites se ha oxidado.",
  ui_story_1017_10170701_53_dialog_content = "Illumina siempre tiene una inclinación hacia la guerra. Que ellos mismos pacifiquen a los Eclipsites.",
  ui_story_1017_10170701_54_dialog_content = "Además, los Caballeros de Ironthorn tienen mucho prestigio en Crepúsculo.",
  ui_story_1017_10170701_55_dialog_content = "Hablando de ofrecer refugio a los caballeros, ¿hacia dónde apuntará esa espada tuya a continuación? Apuesto a que lo tenías planeado desde hace mucho tiempo.",
  ui_story_1017_10170701_56_dialog_content = "Puede que no lo sepas, pero lo que los Caballeros de Ironthorn están defendiendo es todo Crepúsculo.",
  ui_story_1017_10170701_57_dialog_content = "Están muy unidos a los soldados de Illumina, e incluso Leo se unió a ellos para el Ejercicio Militar Conjunto.",
  ui_story_1017_10170701_58_dialog_content = "Hasta donde sé, la casa de Leo ha caído. ¿O es que te sientes amenazado por su fama en Crepúsculo?",
  ui_story_1017_10170701_59_dialog_content = "Ejem, ¿alguna actualización sobre algo que no sea Crepúsculo?",
  ui_story_1017_10170701_60_dialog_content = "Señor de la Ciudad, permítame informarle lo que aprendí durante el Ejercicio Militar Conjunto.",
  ui_story_1017_10170701_61_dialog_content = "Seguir.",
  ui_story_1017_10170701_62_dialog_content = "Me hice amigo de un soldado de Crepúsculo. Él—",
  ui_story_1017_10170701_63_dialog_content = "¿Todavía Crepúsculo? Está bien, no digas más.",
  ui_story_1017_10170701_64_dialog_content = "Pero-",
  ui_story_1017_10170701_65_dialog_content = "¿Ves esa mesa?",
  ui_story_1017_10170701_66_dialog_content = "He visto suficientes mensajes de Crepúsculo, Fortaleza Lumo e incluso Umbraton para toda una vida.",
  ui_story_1017_10170701_67_dialog_content = "Entonces, ¿por qué no has tomado ninguna acción?",
  ui_story_1017_10170701_68_dialog_content = "Has vivido en Crepúsculo tanto tiempo que su impaciencia se te ha pegado.",
  ui_story_1017_10170701_69_dialog_content = "...",
  ui_story_1017_10170701_70_dialog_content = "(Padre puede parecer despreocupado al respecto, pero su dedo nunca dejó de tamborilear en la mesa...)",
  ui_story_1017_10170701_71_dialog_content = "(Él no quiere escuchar sobre Crepúsculo, pero ¿qué está esperando?)",
  ui_story_1017_10170701_72_dialog_content = "¡Señor de la Ciudad! ¡Tenemos nueva información sobre la Federación Illumina!",
  ui_story_1017_10170701_73_dialog_content = "Habla.",
  ui_story_1017_10170701_74_dialog_content = "Las nuevas fuerzas de Illumina han cruzado las defensas y ya casi están en Crepúsculo.",
  ui_story_1017_10170701_75_dialog_content = "¿Han cruzado las defensas?",
  ui_story_1017_10170701_76_dialog_content = "¡Sí!",
  ui_story_1017_10170701_77_dialog_content = "¿Qué pasa con estas nuevas fuerzas?",
  ui_story_1017_10170701_78_dialog_content = "Las nuevas fuerzas son la Legión de Guardias formada después de que Wrath asumió como Gran Mariscal.",
  ui_story_1017_10170701_79_dialog_content = "Tienen equipo de combate completamente nuevo y guerreros a bordo, y escucha esto: uno de sus soldados realmente derrotó a Reinhardt en un ejercicio militar.",
  ui_story_1017_10170701_80_dialog_content = "(Axelia? Ella debería estar recuperándose en este momento...)",
  ui_story_1017_10170701_81_dialog_content = "¿Hay noticias sobre los generales de Illumina y el Caelestite?",
  ui_story_1017_10170701_82_dialog_content = "Aparte de Hiiro, otros Comandantes están en diferentes misiones, y parece que aún no han llegado a Twilight.",
  ui_story_1017_10170701_83_dialog_content = "En cuanto al Caelestite, nos enteramos de que su Colossus se dirigió hacia el Crepúsculo poco después de que comenzara la guerra.",
  ui_story_1017_10170701_84_dialog_content = "¿PlayerName fue a Crepúsculo?",
  ui_story_1017_10170701_85_dialog_content = "¿Eso es un problema?",
  ui_story_1017_10170701_86_dialog_content = "No podría estar más claro: las vulnerabilidades de Crepúsculo están a la vista de todas las principales potencias después del ejercicio militar.",
  ui_story_1017_10170701_87_dialog_content = "Parece que la Federación Illumina cree que tienen a Crepúsculo en el bolsillo, por eso han enviado esta fuerza formidable.",
  ui_story_1017_10170701_88_dialog_content = "De ahora en adelante, quién sabe si todavía habrá un lugar para White Night in Twilight.",
  ui_story_1017_10170701_89_dialog_content = "Reemplazar al mariscal y enviar un nuevo ejército para pacificar a los Eclipsites en un momento crucial como este...",
  ui_story_1017_10170701_90_dialog_content = "Para mí, es una decisión increíblemente ridícula.",
  ui_story_1017_10170701_91_dialog_content = "Será mejor que averigües si tienen la intención de reforzar o hacer algo más, Schwartz.",
  ui_story_1017_10170701_92_dialog_content = "Envíe la orden para movilizar refuerzos para la salida inmediata hacia Crepúsculo.",
  ui_story_1017_10170701_93_dialog_content = "Gracias, Señor de la Ciudad. ¿Le importaría compartir sus pensamientos?",
  ui_story_1017_10170701_94_dialog_content = "Una vez que el ejército de Illumina cruzó la línea de defensa, Lumopolis debe hacer un movimiento.",
  ui_story_1017_10170701_95_dialog_content = "Ya sea por un esfuerzo cooperativo o por intereses privados, lo mejor para nosotros es enviar fuerzas.",
  ui_story_1017_10170701_96_dialog_content = "Recuerda, prioriza la seguridad de la Fortaleza Lumo por encima de todo y no te involucres en ninguna operación de Illumina.",
  ui_story_1017_10170701_97_dialog_content = "Debo aprobar personalmente cada acción de las tropas de refuerzo.",
  ui_story_1017_10170701_98_dialog_content = "¡Sí!",
  ui_story_1017_10170701_99_dialog_content = "(Papá desconfía de las fuerzas de Illumina...)",
  ui_story_1017_10170701_100_dialog_content = "¿Quién liderará el refuerzo, Señor de la Ciudad? Me gustaría volun—",
  ui_story_1017_10170701_101_dialog_content = "Estás despedido. Reforzar Twilight no es una de tus responsabilidades.",
  ui_story_1017_10170701_102_dialog_content = "Pero-",
  ui_story_1017_10170701_103_dialog_content = "Lo dejaremos aquí por hoy.",
  ui_story_1017_10170801_1_dialog_content = "Disculpa... Mi familia aún no ha regresado. ¿Podrías mantener la puerta abierta un poco más, por favor?",
  ui_story_1017_10170801_2_dialog_content = "Las órdenes del Señor son claras: aseguren bien esas puertas. Nadie entra excepto los residentes de la Noche Blanca.",
  ui_story_1017_10170801_3_dialog_content = "Entiendo, pero... mi hijo también es residente de la Noche Blanca... Fue al frente de batalla para protegernos.",
  ui_story_1017_10170801_4_dialog_content = "¿No fui lo suficientemente claro? Las puertas están a punto de cerrarse. ¡Paso atrás!",
  ui_story_1017_10170801_5_dialog_content = "Poderoso Dios de la Luz, cómo desearía que no nos hubieras abandonado...",
  ui_story_1017_10170801_6_dialog_content = "Después del crepúsculo llega la noche, y después de la noche vuelve el crepúsculo...",
  ui_story_1017_10170801_7_dialog_content = "Para los niños en primera línea, mis oraciones son sinceras con ustedes.",
  ui_story_1017_10170801_8_dialog_content = "¡Retrocede, PlayerName!",
  ui_story_1017_10170801_9_dialog_content = "¡Los comandantes no retroceden en las batallas!",
  ui_story_1017_10170801_10_dialog_content = "Nunca he visto una invasión de Eclipsites de esta magnitud antes.",
  ui_story_1017_10170801_11_dialog_content = "Las dos ofensivas anteriores fueron invadidas por Eclipsites. Ahora no es el momento de forzarlo.",
  ui_story_1017_10170801_12_dialog_content = "Bueno, siento que el Darkflow se está volviendo cada vez más fuerte...",
  ui_story_1017_10170801_13_dialog_content = "No tienen líder, ningún motivo discernible y son numerosos. No podemos atacar a ciegas sin saber más.",
  ui_story_1017_10170801_14_dialog_content = "Capitán, ambos equipos que custodian las líneas de defensa han sido dispersados por los Eclipsites. Los soldados están sufriendo muchas bajas.",
  ui_story_1017_10170801_15_dialog_content = "¡Todas las unidades, retrocedan 100 pasos inmediatamente!",
  ui_story_1017_10170801_16_dialog_content = "¡Sí!",
  ui_story_1017_10170801_17_dialog_content = "Pide a Logística que construya carros improvisados y transporte a los heridos al mesón del pueblo.",
  ui_story_1017_10170801_18_dialog_content = "¡Nosotros nos encargaremos de los heridos!",
  ui_story_1017_10170801_19_dialog_content = "¡Sí, Capitán!",
  ui_story_1017_10170801_20_dialog_content = "Leo, intentemos descubrirlo mientras nos retiramos. ¿Qué crees que están tramando los Eclipsites?",
  ui_story_1017_10170801_21_dialog_content = "Solo intentan debilitarnos a través de la cantidad. No tiene mucho sentido.",
  ui_story_1017_10170801_22_dialog_content = "¿Alguna idea sobre los planes de los Eclipsites, PlayerName?",
  ui_story_1017_10170801_23_dialog_content = "Déjame probar mi poder.",
  ui_story_1017_10170801_24_dialog_content = "(Todo son Eclipsites fuera de Twilight... El Darkflow es denso...)",
  ui_story_1017_10170801_25_dialog_content = "(Se mueven lentamente y agrupados muy cerca como si...)",
  ui_story_1017_10170801_26_dialog_content = "(Como si estuvieran formando una enorme red de Darkflow para cubrir Crepúsculo...)",
  ui_story_1017_10170801_27_dialog_content = "(Muchos nodos... en la red...)",
  ui_story_1017_10170801_28_dialog_content = "(Espera... La intensidad del Darkflow es diferente en cada nodo, pero parece que apuntan a...)",
  ui_story_1017_10170801_29_dialog_content = "Leo, el Darkflow cubre una gran distancia y parece que están bajo un mando central.",
  ui_story_1017_10170801_30_dialog_content = "¿Sabes qué es ese comando central?",
  ui_story_1017_10170801_31_dialog_content = "Lo siento, no está dentro de mi alcance.",
  ui_story_1017_10170801_32_dialog_content = "Al menos eso significa que los Eclipsites no actúan al azar.",
  ui_story_1017_10170801_33_dialog_content = "Sí. Y por ahora, localizar ese comando central es la clave.",
  ui_story_1017_10170801_34_dialog_content = "Soroz, intenta buscar el comando central.",
  ui_story_1017_10170801_35_dialog_content = "Buscando...",
  ui_story_1017_10170801_36_dialog_content = "Ampliando el campo de visión...",
  ui_story_1017_10170801_37_dialog_content = "\"Centro\" aún no detectado. Búsqueda en curso...",
  ui_story_1017_10170801_38_dialog_content = "No encontrado...",
  ui_story_1017_10170801_39_dialog_content = "Si es debido al alcance, la ubicación probablemente esté muy cerca de la Zona Oscura o incluso dentro de la Zona Oscura.",
  ui_story_1017_10170801_40_dialog_content = "Supongo que solo eliminando a quien esté al mando lograremos detener a los Eclipsites.",
  ui_story_1017_10170801_41_dialog_content = "¿Estás pensando en aventurarte en la Zona Oscura?",
  ui_story_1017_10170801_42_dialog_content = "Es cierto. Twilight será destruido si no hacemos algo.",
  ui_story_1017_10170801_43_dialog_content = "¡Estoy contigo, Capitán!",
  ui_story_1017_10170801_44_dialog_content = "No, tú toma el cargo de comandante en jefe y mantén la línea.",
  ui_story_1017_10170801_45_dialog_content = "Equipo de reconocimiento, esperen mi orden—",
  ui_story_1017_10170801_46_dialog_content = "PlayerName, desde atrás, se acerca una fuerza militar hacia ti.",
  ui_story_1017_10170801_47_dialog_content = "¿Puedes decir a qué ejército pertenecen?",
  ui_story_1017_10170801_48_dialog_content = "La bandera en el vehículo de transporte frontal muestra una imagen:",
  ui_story_1017_10170801_49_dialog_content = "¡Illumina!",
  ui_story_1017_10170801_50_dialog_content = "Leo, ¡son las fuerzas Illumina detrás de nosotros!",
  ui_story_1017_10170801_51_dialog_content = "¡Atención, Legión de la Guardia!",
  ui_story_1017_10170801_52_dialog_content = "¡Todas las compañías avanzan en formación de diamante!",
  ui_story_1017_10170801_53_dialog_content = "Engine VII, prioriza llenar los huecos en las barreras. ¡No dejes que los Eclipsites avancen ni un paso más!",
  ui_story_1017_10170801_54_dialog_content = "¡¡¡Sí!!!",
  ui_story_1017_10170801_55_dialog_content = "¿Esto es todo para ustedes, invasores? ¡Ni siquiera durarán 10 minutos como práctica de tiro al blanco!",
  ui_story_1017_10170801_56_dialog_content = "Esta... aura tan imponente... ¿Es este el nuevo Gran Mariscal de Illumina?",
  ui_story_1017_10170801_57_dialog_content = "Ella solo era mi oficial de entrenamiento para el ejercicio, pero ahora se ve totalmente diferente como la Gran Mariscal.",
  ui_story_1017_10170801_58_dialog_content = "Sí, un uniforme totalmente nuevo y probablemente mucho más poderoso.",
  ui_story_1017_10170801_59_dialog_content = "Sus soldados también son realmente formidables. Mira ese de allí—",
  ui_story_1017_10170801_60_dialog_content = "Ha derrotado a diez Eclipsites seguidos, sin un momento de pausa...",
  ui_story_1017_10170801_61_dialog_content = "Tengo curiosidad acerca de estas armas de Illumina que son controladas por soldados desde adentro.",
  ui_story_1017_10170801_62_option_content = "(Me encantaría pilotar uno de esos)",
  ui_story_1017_10170801_63_dialog_content = "Por razones de seguridad, no recomendaría intentar eso.",
  ui_story_1017_10170801_64_option_content = "(Me encantaría reacondicionar Soroz)",
  ui_story_1017_10170801_65_dialog_content = "Incompatibilidad de estilo. No te recomendaría intentar eso.",
  ui_story_1017_10170801_66_dialog_content = "Es solo un pensamiento...",
  ui_story_1017_10170801_67_dialog_content = "Veo que ese soldado también está aquí.",
  ui_story_1017_10170801_68_dialog_content = "Derrotó a Reinhardt en el ejercicio militar y ya está luchando por Wrath ahora. Impresionante.",
  ui_story_1017_10170801_69_dialog_content = "Axelia... Pero estaba gravemente herida. ¿Qué hace aquí?",
  ui_story_1017_10170801_70_dialog_content = "Oye, qué casualidad verte aquí, PlayerName. ¿Te dejó boquiabierto la exhibición?",
  ui_story_1017_10170801_71_dialog_content = "...",
  ui_story_1017_10170801_72_dialog_content = "Nos encontramos de nuevo, Capitán de los Caballeros.",
  ui_story_1017_10170801_73_dialog_content = "Hace tiempo, oficial... Oh, mis disculpas, debería llamarte Gran Mariscal!",
  ui_story_1017_10170801_74_dialog_content = "A pesar de estar de vuelta en tu territorio, parece que no lo estás pasando fácil.",
  ui_story_1017_10170801_75_dialog_content = "¿Te importaría revelar el propósito de tu presencia y la de los soldados de Illumina?",
  ui_story_1017_10170801_76_dialog_content = "Como Gran Mariscal de la Federación Illumina, lidero una fuerza de élite para ayudar a Twilight en pacificar a los Eclipsites.",
  ui_story_1017_10170801_77_dialog_content = "¿Es difícil de comprender?",
  ui_story_1017_10170801_78_dialog_content = "Es algo sorprendente que un ego como Illumina ceda tropas para Crepúsculo.",
  ui_story_1017_10170801_79_dialog_content = "Bueno, si Crepúsculo cae, Illumina es el siguiente, así que esa es la lógica.",
  ui_story_1017_10170801_80_dialog_content = "Tienes previsión, Gran Mariscal. Espero que no haya golpes bajos como en el ejercicio.",
  ui_story_1017_10170801_81_dialog_content = "También estoy investigando eso. Como aliado de Crepúsculo esta vez, espero que disfrutemos trabajando juntos.",
  ui_story_1017_10170801_82_dialog_content = "Salud.",
  ui_story_1017_10170801_83_dialog_content = "¡Escuchen, Legión de la Guardia, los Caballeros de Ironthorn han mantenido el terreno durante mucho tiempo!",
  ui_story_1017_10170801_84_dialog_content = "¡No nos contengamos y destruyamos a todos los Eclipsites!",
  ui_story_1017_10170801_85_dialog_content = "¡¡¡Sí!!!",
  ui_story_1017_10170801_86_dialog_content = "¡Atención, Caballeros de Ironthorn!",
  ui_story_1017_10170801_87_dialog_content = "Ataquen en formación de cuña. ¡Aquellos que no deseen ser tratados como un chiste, tomen la punta conmigo!",
  ui_story_1017_10170801_88_dialog_content = "¡¡¡Sí!!!",
  ui_story_1017_10170901_1_dialog_content = "Ulysses está triste por ajustar mis descartes y lanzarlos a la primera batalla que ve.",
  ui_story_1017_10170901_2_dialog_content = "¿Todavía tienes agallas para seguir adelante?",
  ui_story_1017_10170901_3_dialog_content = "(Eclipsiano) Estas basuras realmente saben cómo luchar.",
  ui_story_1017_10170901_4_dialog_content = "¿Esperabas algo diferente? Tienen mis semillas en su cuerpo. Ya deberías haberlo sentido.",
  ui_story_1017_10170901_5_dialog_content = "(Eclipsiano)...",
  ui_story_1017_10170901_6_dialog_content = "Sé lo que estás pensando, que alguien debería estar aquí.",
  ui_story_1017_10170901_7_dialog_content = "Entonces, ¿me estabas esperando? ¿No puedes manejar ni un pequeño ataque como este?",
  ui_story_1017_10170901_8_dialog_content = "Es diferente de lo anticipado. Tenemos colados en la fiesta.",
  ui_story_1017_10170901_9_dialog_content = "¿No es esta una oportunidad ideal para la venganza? Deberías estar emocionado.",
  ui_story_1017_10170901_10_dialog_content = "Eso no es asunto tuyo. ¿Dónde está?",
  ui_story_1017_10170901_11_dialog_content = "Aquí.",
  ui_story_1017_10170901_12_dialog_content = "Mudbundle¿?",
  ui_story_1017_10170901_13_dialog_content = "Bueno, es un poco nauseabundo mirarlo, pero aumentará tu velocidad de propulsión. ¿Alguna opinión?",
  ui_story_1017_10170901_14_dialog_content = "Si recuerdo correctamente, puede consumir su entorno, crear pantanos y sus formas de atormentar a los Aurorianos son... bastante únicas, de hecho, muy únicas.",
  ui_story_1017_10170901_15_dialog_content = "Vamos a probarlo.",
  ui_story_1017_10170901_16_dialog_content = "(Eclipsiano) Sí.",
  ui_story_1017_10170901_17_dialog_content = "(Flujo oscuro de Eclipsian)... convergiendo, una sensación de... ¡hambre insaciable!",
  ui_story_1017_10170901_18_dialog_content = "Los Eclipsites solo tienen que estar en el pantano de Mudbundle para que las semillas dentro de ellos se conecten a su núcleo.",
  ui_story_1017_10170901_19_dialog_content = "(Eclipsian) ¡El poder sigue fluyendo sin parar!",
  ui_story_1017_10170901_20_dialog_content = "Todo lo que tienen que hacer a continuación es simplemente devorar a los Aurorianos y alimentarse. Cuando llegue el momento, Mudbundle se encargará de la limpieza.",
  ui_story_1017_10170901_21_dialog_content = "No soy fanático de estas explicaciones tediosas. Te lo dejo a ti. Nuestra próxima reunión será cuando inspeccionemos la \"alfombra\".",
  ui_story_1017_10170901_22_dialog_content = "(¡Eclipsiano) ¡COMIDA!",
  ui_story_1017_10170901_23_dialog_content = "¡Vamos, toda esa comida es tuya antes de que Crepúsculo quede atrapado en el barro!",
  ui_story_1017_10170901_24_dialog_content = "(Eclipsiano) ¡Grrr!",
  ui_story_1017_10170901_25_dialog_content = "¡Oh no, estoy sintiendo un Darkflow muy fuerte que se acerca!",
  ui_story_1017_10170901_26_dialog_content = "¿Tan pronto? ¿Es alguien del mando central?",
  ui_story_1017_10170901_27_dialog_content = "No estoy seguro, pero la red de Darkflow ciertamente se está cerrando a nuestro alrededor.",
  ui_story_1017_10170901_28_dialog_content = "Eh... Ah...",
  ui_story_1017_10170901_29_dialog_content = "¿Qué está pasando allí?",
  ui_story_1017_10170901_30_dialog_content = "Informando, Gran Mariscal! Parece que algunos soldados podrían verse afectados por el Flujo Oscuro...",
  ui_story_1017_10170901_31_dialog_content = "Proporcione ayuda médica lo más pronto posible y envíeme un informe sobre el estado de los heridos.",
  ui_story_1017_10170901_32_dialog_content = "¡Sí!",
  ui_story_1017_10170901_33_dialog_content = "(De repente siento... una oleada de poder...)",
  ui_story_1017_10170901_34_dialog_content = "¿Estás bien, Gran Mariscal?",
  ui_story_1017_10170901_35_dialog_content = "El Darkflow... sí hace que las personas se sientan incómodas...",
  ui_story_1017_10170901_36_dialog_content = "Retrocedan con sus soldados. Escuadrones 1 y 2 de Caballeros de Ironthorn, ataquen al enemigo. ¡3 y 4 cubrirán!",
  ui_story_1017_10170901_37_dialog_content = "No tan rápido. Estos Eclipsites no tienen oportunidad.",
  ui_story_1017_10170901_38_dialog_content = "¡Sigue ayudándome, PlayerName!",
  ui_story_1017_10170901_39_dialog_content = "Un Eclipsite con una forma única se acerca adelante.",
  ui_story_1017_10170901_40_dialog_content = "¿Puede ser alguien de su comando central?",
  ui_story_1017_10170901_41_dialog_content = "No se puede confirmar. Pero el Darkflow detectado es más fuerte que otros Eclipsites.",
  ui_story_1017_10170901_42_dialog_content = "Entiendo. ¿Algo más para compartir?",
  ui_story_1017_10170901_43_dialog_content = "Detección en curso. Me sincronizaré contigo una vez que los resultados estén disponibles.",
  ui_story_1017_10170901_44_dialog_content = "¡Vale, cuento contigo!",
  ui_story_1017_10170901_45_dialog_content = "Un Eclipsite muy poderoso viene hacia aquí, todos. ¡Estén listos para atacar!",
  ui_story_1017_10170901_46_dialog_content = "Por fin, no solo carne de cañón.",
  ui_story_1017_10170901_47_dialog_content = "Observen y aprendan, caballeros. La Legión de la Guardia no caerá. ¡Lo tenemos!",
  ui_story_1017_10170901_48_dialog_content = "Está bien. ¡Cúbranlos, Caballeros de Ironthorn!",
  ui_story_1017_10170901_49_dialog_content = "¡¡¡Sí!!!",
  ui_story_1017_10171001_1_dialog_content = "Uf... ¡Terminado al fin!",
  ui_story_1017_10171001_2_dialog_content = "No puedo creer cuántos Eclipsites invocó antes de caer. Eso nos tomó desprevenidos.",
  ui_story_1017_10171001_3_dialog_content = "Empiezo a ver su estrategia ahora, y deberíamos estar a salvo por el momento.",
  ui_story_1017_10171001_4_dialog_content = "¡Informando, Gran Mariscal! ¡La cantidad de soldados afectados por el Darkflow sigue aumentando!",
  ui_story_1017_10171001_5_dialog_content = "¿Ya sabemos la causa?",
  ui_story_1017_10171001_6_dialog_content = "Aún no. Muchos soldados están perdiendo el control de sus cuerpos, entrando en un frenesí <color=#FFB400>sanguinario</color>. La curación resulta completamente inútil.",
  ui_story_1017_10171001_7_dialog_content = "...",
  ui_story_1017_10171001_8_dialog_content = "(Fuera de control y sediento de sangre... Me pregunto si todos se sintieron así en la batalla...)",
  ui_story_1017_10171001_9_dialog_content = "¡Sector este! Capitán, un grupo de Eclipsites está causando problemas de nuevo en las trincheras.",
  ui_story_1017_10171001_10_dialog_content = "Parece que este Eclipsite no es el líder.",
  ui_story_1017_10171001_11_dialog_content = "¿Alguien tiene alguna pista?",
  ui_story_1017_10171001_12_dialog_content = "Cuando los estaba tratando, noté que la influencia del Darkflow en los soldados era peor de lo que normalmente vemos.",
  ui_story_1017_10171001_13_dialog_content = "Quizás debamos enviarlos a un hospital para un tratamiento más avanzado y así puedan mejorar.",
  ui_story_1017_10171001_14_dialog_content = "Gran Mariscal Wrath, permítame llevar a los soldados afectados de sus fuerzas al hospital.",
  ui_story_1017_10171001_15_dialog_content = "Estaba a punto de hacer esa solicitud. ¡Gracias! Illumina te compensará después de la guerra.",
  ui_story_1017_10171001_16_dialog_content = "Es lo que hago.",
  ui_story_1017_10171001_17_dialog_content = "Gran Mariscal, los informes indican que algunos soldados se han separado de la unidad y se están moviendo en la misma dirección...",
  ui_story_1017_10171001_18_dialog_content = "Como si fueran impulsados por alguna fuerza desconocida.",
  ui_story_1017_10171001_19_dialog_content = "¿Es posible que su comando central esté detrás de esto?",
  ui_story_1017_10171001_20_dialog_content = "No puedo descartar eso. Teorizamos que el curso del Darkflow fue manipulado por el mando central.",
  ui_story_1017_10171001_21_dialog_content = "¿Y los soldados en Crepúsculo, sienten lo mismo?",
  ui_story_1017_10171001_22_dialog_content = "Capitán, hemos notado algo...",
  ui_story_1017_10171001_23_dialog_content = "¿Estás seguro?",
  ui_story_1017_10171001_24_dialog_content = "Sí, capitán.",
  ui_story_1017_10171001_25_dialog_content = "Todos esos soldados que se comportan de manera extraña son de sus fuerzas, Gran Mariscal.",
  ui_story_1017_10171001_26_dialog_content = "¿A qué estás llegando?",
  ui_story_1017_10171001_27_dialog_content = "No voy a andarme con rodeos, entonces. En las últimas ofensivas, tus soldados actuaron de manera errática.",
  ui_story_1017_10171001_28_dialog_content = "¿Fue porque el enemigo era demasiado fuerte...?",
  ui_story_1017_10171001_29_dialog_content = "¿O tiene topos en su unidad, Gran Mariscal?",
  ui_story_1017_10171001_30_dialog_content = "¿Dudas de las intenciones de Illumina al venir en ayuda de Crepúsculo?",
  ui_story_1017_10171001_31_dialog_content = "Para nada. Solo creo que nuestro enemigo no es común y corriente. Como capitán, tengo que ser responsable ante mis hombres.",
  ui_story_1017_10171001_32_dialog_content = "A juzgar por lo que tenemos, tus soldados están empezando a confundir a los Aurorianos con los Eclipsites.",
  ui_story_1017_10171001_33_dialog_content = "¡Muerde tu lengua! ¡Nunca haría trucos turbios como ese!",
  ui_story_1017_10171001_34_dialog_content = "Capitán Leo, Gran Mariscal Wrath, creo que todos estamos aquí por el bien de Crepúsculo.",
  ui_story_1017_10171001_35_dialog_content = "Aunque aún no entiendo por qué los soldados no siguieron sus órdenes...",
  ui_story_1017_10171001_36_dialog_content = "Me preocupa que sea un truco de nuestro enemigo para nublar deliberadamente nuestro juicio.",
  ui_story_1017_10171001_37_dialog_content = "Mis soldados definitivamente no siguieron mis órdenes por completo en la última batalla.",
  ui_story_1017_10171001_38_dialog_content = "Y como Gran Mariscal, soy responsable de todo aquí en nombre de Illumina.",
  ui_story_1017_10171001_39_dialog_content = "Te daré una respuesta satisfactoria con el tiempo.",
  ui_story_1017_10171001_40_dialog_content = "Pero si insistes en dudar de los motivos de Illumina, lo tomaré como un acto de guerra.",
  ui_story_1017_10171001_41_dialog_content = "\"Acto de guerra\" sería una exageración enorme de lo que fue simplemente un recordatorio rápido de mi parte.",
  ui_story_1017_10171001_42_dialog_content = "Eres nuevo en tu posición, así que por favor aprende las tendencias de combate de aquellos bajo tu mando.",
  ui_story_1017_10171001_43_dialog_content = "Si muestran más traición o incluso dañan a mis soldados, responderé de la misma manera.",
  ui_story_1017_10171001_44_dialog_content = "Tu ladrido es peor que tu mordida.",
  ui_story_1017_10171001_45_dialog_content = "Si lo que quieres es luchar contra Illumina, confía en mí, ¡yo solo seré más de lo que puedas manejar!",
  ui_story_1017_10171001_46_dialog_content = "Gran Mariscal! ¡Informando una situación urgente!",
  ui_story_1017_10171001_47_dialog_content = "El equipo de combate del teniente Axelia ha desaparecido.",
  ui_story_1017_10171001_48_dialog_content = "¿¿¿???",
  ui_story_1017_10171001_49_dialog_content = "¿De qué área está a cargo ella?",
  ui_story_1017_10171001_50_dialog_content = "Sector oeste, Grand Marshal, donde un grupo de eclipses todavía se está moviendo hacia Crepúsculo.",
  ui_story_1017_10171001_51_dialog_content = "Legión de Guardias, nos dirigimos al oeste para matar Eclipsites.",
  ui_story_1017_10171001_52_dialog_content = "¡Todos los heridos, sigan adelante a menos que tengan una pierna rota o hayan perdido la cabeza!",
  ui_story_1017_10171001_53_dialog_content = "¡Infórmame de inmediato si ves a un soldado con comportamientos sospechosos!",
  ui_story_1017_10171001_54_dialog_content = "¡Sí!",
  ui_story_1017_10171001_55_dialog_content = "Vienes conmigo, PlayerName.",
  ui_story_1017_10171001_56_dialog_content = "¿Yo?",
  ui_story_1017_10171001_57_dialog_content = "¡Ahora!",
  ui_story_1017_10171001_58_dialog_content = "...",
  ui_story_1017_10171001_59_dialog_content = "Capitán, ¿deberíamos movernos por nuestra cuenta?",
  ui_story_1017_10171001_60_dialog_content = "Una escoba nueva barre bien. No abordar los problemas ahora solo hará que las cosas sean más difíciles más tarde.",
  ui_story_1017_10171001_61_dialog_content = "Prepárate para ir hacia el este. Está cerca de la zona residencial. No podemos dejar entrar ni a un solo Eclipsite.",
  ui_story_1017_10171001_62_dialog_content = "¡Sí, Capitán!",
  ui_story_1017_10171001_63_dialog_content = "Leo, el personal del hospital está aquí. Llevaré a los heridos graves.",
  ui_story_1017_10171001_64_dialog_content = "¿Por qué no salvamos el hospital para los civiles heridos? Conseguiré que mis amigos de la <color=#FFB400>posada</color> ayuden a nuestros heridos.",
  ui_story_1017_10171001_65_dialog_content = "Capitán, el bar ya ha...",
  ui_story_1017_10171001_66_dialog_content = "Entonces, convirtamos al personal de Logística en una unidad médica por el momento y cambiemos el <color=#FFB400>mineral</color> restante en Lumo Stronghold por suministros médicos.",
  ui_story_1017_10171001_67_dialog_content = "¡Pero Capitán, la Fortaleza Lumo ya ha cerrado sus puertas!",
  ui_story_1017_10171001_68_dialog_content = "¡Por eso dije que les intercambies el mineral!",
  ui_story_1017_10171001_69_dialog_content = "¡Entendido, Capitán!",
  ui_story_1017_10171001_70_dialog_content = "Todo se vuelve problemático cuando la Fortaleza Lumo está involucrada.",
  ui_story_1017_10171001_71_dialog_content = "Aunque nací en Crepúsculo, todavía soy de Lumopolis y trataré de ayudar.",
  ui_story_1017_10171001_72_dialog_content = "Es raro ver a alguien orgulloso de ser de Lumopolis.",
  ui_story_1017_10171001_73_dialog_content = "Las facciones no son importantes. Solo quiero que todos en Crepúsculo vivan en paz.",
  ui_story_1017_10171001_74_dialog_content = "Estás pensando demasiado adelante.",
  ui_story_1017_10171001_75_dialog_content = "Sin ayuda de Illumina y Lumopolis, Twilight no durará, mucho menos en paz.",
  ui_story_1017_10171001_76_dialog_content = "¿Quieres saber cuál es la cosa más importante para un ejército?",
  ui_story_1017_10171001_77_dialog_content = "Corazón. Debemos estar unidos de corazón para ganar. Desafortunadamente, el ejército de Illumina que vemos carece totalmente de cohesión.",
  ui_story_1017_10171001_78_dialog_content = "¿El Colossus puede ver cada movimiento del enemigo?",
  ui_story_1017_10171001_79_dialog_content = "Cristalino, PlayerName.",
  ui_story_1017_10171001_80_dialog_content = "Sí, Wrath... Gran Mariscal.",
  ui_story_1017_10171001_81_dialog_content = "¿No crees que es incómodo?",
  ui_story_1017_10171001_82_dialog_content = "...",
  ui_story_1017_10171001_83_dialog_content = "¿Qué pasa con esa expresión?",
  ui_story_1017_10171001_84_dialog_content = "Eh, nada... simplemente no estoy muy acostumbrado a trabajar con el Gran Mariscal.",
  ui_story_1017_10171001_85_dialog_content = "Hmm, ¿no estás bastante cerca de Reinhardt?",
  ui_story_1017_10171001_86_dialog_content = "Entonces, ¿por qué estás nervioso cerca de mí? ¿Cuál es la diferencia entre ella y yo?",
  ui_story_1017_10171001_87_dialog_content = "(¿Tienes que preguntar...?)",
  ui_story_1017_10171001_88_dialog_content = "Solo llámame por mi nombre. También te llamaré por tu nombre por respeto.",
  ui_story_1017_10171001_89_dialog_content = "Entendido, Wrath...",
  ui_story_1017_10171001_90_dialog_content = "Tengo un favor que pedirte en relación a mis soldados.",
  ui_story_1017_10171001_91_dialog_content = "Seguro.",
  ui_story_1017_10171001_92_dialog_content = "No estoy seguro de si empeorarán en las próximas batallas.",
  ui_story_1017_10171001_93_dialog_content = "Por ahora, necesito que fijes sus posiciones y lo resuelvas antes de que nuestro enemigo lance un ataque importante.",
  ui_story_1017_10171001_94_dialog_content = "Sin problema. Soroz también puede ayudar.",
  ui_story_1017_10171001_95_dialog_content = "Buscando soldados anormales. Tiempo estimado: 60s.",
  ui_story_1017_10171001_96_dialog_content = "Tengo una pregunta.",
  ui_story_1017_10171001_97_dialog_content = "¿Qué es?",
  ui_story_1017_10171001_98_dialog_content = "¿Cómo es que Axelia está en tu equipo?",
  ui_story_1017_10171001_99_dialog_content = "Si mal no recuerdo, ella resultó gravemente herida en el ejercicio y todavía debería estar recuperándose.",
  ui_story_1017_10171001_100_dialog_content = "Esa es la determinación de los soldados Illumina, ¿entendido?",
  ui_story_1017_10171001_101_dialog_content = "¿Arriesgar la vida e ir a la batalla una y otra vez?",
  ui_story_1017_10171001_102_dialog_content = "¿No crees que ella pueda hacerlo?",
  ui_story_1017_10171001_103_dialog_content = "Creo que sí puede, solo siento que Axelia...",
  ui_story_1017_10171001_104_dialog_content = "Ella no temería ni codiciaría la guerra como las personas que conozco.",
  ui_story_1017_10171001_105_dialog_content = "Casi no sentí ninguna emoción de ella en nuestros encuentros anteriores.",
  ui_story_1017_10171001_106_dialog_content = "La emoción no es un arma para la victoria, Caelestite.",
  ui_story_1017_10171001_107_dialog_content = "No, lo que quiero decir es—",
  ui_story_1017_10171001_108_dialog_content = "Sé lo que dices.",
  ui_story_1017_10171001_109_dialog_content = "Antes de convertirme en Gran Mariscal, tenía las mismas dudas que tú.",
  ui_story_1017_10171001_110_dialog_content = "Pero ahora entiendo esto:",
  ui_story_1017_10171001_111_dialog_content = "Para vencer a alguien completamente invencible, debes abandonar tu antigua identidad y ver las cosas desde la perspectiva de esa persona.",
  ui_story_1017_10171001_112_dialog_content = "Abandonar la vieja identidad... Pero veo que sigues liderando la carga como siempre.",
  ui_story_1017_10171001_113_dialog_content = "Para un Caelestite dotado de percepción sobrenatural, tu mente seguro que es simple.",
  ui_story_1017_10171001_114_dialog_content = "Estoy verde de envidia...",
  ui_story_1017_10171001_115_dialog_content = "Eso no suena como un cumplido...",
  ui_story_1017_10171001_116_dialog_content = "Te confundiste. Mantén tus ojos en la carretera y cuidado con los hoyos.",
  ui_story_1017_10171001_117_dialog_content = "Encontré un soldado anormal debajo de un obstáculo a 20 metros adelante.",
  ui_story_1017_10171001_118_dialog_content = "Soldado errático adelante, Wrath!",
  ui_story_1017_10171001_119_dialog_content = "Vamos.",
  ui_story_1017_10171001_120_dialog_content = "...",
  ui_story_1017_10171001_121_dialog_content = "¿Qué estás sintiendo?",
  ui_story_1017_10171001_122_dialog_content = "...",
  ui_story_1017_10171001_123_dialog_content = "Todavía está un poco consciente, pero no puede oírte hablar.",
  ui_story_1017_10171001_124_dialog_content = "Déjame intentar establecer un vínculo mental con él y ver qué puedo encontrar.",
  ui_story_1017_10171001_125_dialog_content = "Seguro.",
  ui_story_1017_10171001_126_option_content = "Enlace mental—",
  ui_story_1017_10171001_127_dialog_content = "(¿Estoy en un pantano?)",
  ui_story_1017_10171001_128_dialog_content = "(Cubre el suelo como una alfombra gigante...)",
  ui_story_1017_10171001_129_dialog_content = "(Los edificios deteriorados de aquí parecen familiares...)",
  ui_story_1017_10171001_130_dialog_content = "(Debería ser Crepúsculo, sin duda...)",
  ui_story_1017_10171001_131_dialog_content = "(Pero, ¿de dónde viene todo este barro? No deja de acumularse debajo de mis pies...)",
  ui_story_1017_10171001_132_dialog_content = "(No parece que esté fluyendo en una dirección específica...)",
  ui_story_1017_10171001_133_dialog_content = "Urgh...",
  ui_story_1017_10171001_134_dialog_content = "¿Cómo te sientes? ¿Mal?",
  ui_story_1017_10171001_135_dialog_content = "El Darkflow me está dando un leve dolor de cabeza, pero lo superaré.",
  ui_story_1017_10171001_136_dialog_content = "Lo que tienen en mente los soldados es un Crepúsculo cubierto en un atolladero que parece durar para siempre...",
  ui_story_1017_10171001_137_dialog_content = "El barro seguía acumulándose bajo mis pies y sentía que podía caerme en cualquier momento.",
  ui_story_1017_10171001_138_dialog_content = "Pantano, Darkflow... El lodo en sus mentes probablemente esté relacionado con el Darkflow en la realidad.",
  ui_story_1017_10171001_139_dialog_content = "Esa podría ser la razón de su comportamiento errático...",
  ui_story_1017_10171001_140_dialog_content = "Si podemos descubrir de dónde vino el lodo, quizás podamos localizar al enemigo central...",
  ui_story_1017_10171001_141_dialog_content = "¡¿Qué demonios...?!",
  ui_story_1017_10171001_142_dialog_content = "Espera, ¿cómo puede ser esto?",
  ui_story_1017_10171001_143_dialog_content = "¿Es este uno de los tuyos?",
  ui_story_1017_10171001_144_dialog_content = "¿No es obvio? ¡Casi lo mato!",
  ui_story_1017_10171001_145_dialog_content = "El Darkflow parecía haberlo golpeado lo suficientemente fuerte como para hacerle perder la cabeza...",
  ui_story_1017_10171001_146_dialog_content = "Déjame intentar sondear su mente.",
  ui_story_1017_10171001_147_dialog_content = "Ve tan lejos como puedas, pero detente en cuanto sientas peligro.",
  ui_story_1017_10171001_148_option_content = "Enlace mental—",
  ui_story_1017_10171001_149_dialog_content = "(Este es el mismo escenario, pero el barro fluye mucho más rápido que antes...)",
  ui_story_1017_10171001_150_dialog_content = "(Y viene de la misma dirección esta vez.)",
  ui_story_1017_10171001_151_dialog_content = "(¿Es esa la Noche Eterna?)",
  ui_story_1017_10171001_152_dialog_content = "(El cielo sombrío se mezcla a la perfección con el barro.)",
  ui_story_1017_10171001_153_dialog_content = "(Tiene que ser... Ahí es donde está el mando central...)",
  ui_story_1017_10171001_154_dialog_content = "(Oh, no—)",
  ui_story_1017_10171001_155_dialog_content = "Tú... ¡Eclipsite!",
  ui_story_1017_10171001_156_dialog_content = "¡Retírate!",
  ui_story_1017_10171001_157_dialog_content = "Wrath? ¿Qué le pasó?",
  ui_story_1017_10171001_158_dialog_content = "No te preocupes, él solo se desmayó.",
  ui_story_1017_10171001_159_dialog_content = "Pero ya no es necesario investigar más. Incluso yo puedo sentir el Darkflow en él ahora.",
  ui_story_1017_10171001_160_dialog_content = "Echa un vistazo al horizonte allá, se está haciendo más y más oscuro...",
  ui_story_1017_10171001_161_dialog_content = "¡Esa es la dirección! El barro fluía cada vez más rápido desde la Noche Eterna en su mente.",
  ui_story_1017_10171001_162_dialog_content = "¡Ese debe ser el lugar donde está el comando central!",
  ui_story_1017_10171001_163_dialog_content = "¿Así que hemos encontrado la ubicación del enemigo?",
  ui_story_1017_10171001_164_dialog_content = "Estoy bastante seguro. Probablemente he pasado demasiado tiempo con el Darkflow, ya que me mareo solo de mirar a mi alrededor...",
  ui_story_1017_10171001_165_dialog_content = "Tienes razón, el cielo sobre la Noche Eterna se está oscureciendo.",
  ui_story_1017_10171001_166_dialog_content = "Parece que el Darkflow puede controlar a los soldados y alterar el entorno. Hay un olor rancio en el ambiente.",
  ui_story_1017_10171001_167_dialog_content = "<color=#e8d9bb>Balbuceo, balbuceo...</color>",
  ui_story_1017_10171001_168_dialog_content = "¿Escuchas eso?",
  ui_story_1017_10171001_169_dialog_content = "Eso suena como líquido fluyendo...",
  ui_story_1017_10171001_170_dialog_content = "Líquido fluyendo... ¡Oh no, no me digas que hay un deslizamiento de tierra en Crepúsculo!",
  ui_story_1017_10171001_171_dialog_content = "¡Y viene de la Noche Eterna!",
  ui_story_1017_10171001_172_dialog_content = "Creo que el enemigo central se está acercando.",
  ui_story_1017_10171001_173_dialog_content = "<color=#e8d9bb>Babble, babble...</color>",
  ui_story_1017_10171001_174_dialog_content = "PlayerName, se detectó un gran enjambre de Eclipsites en tu oeste. Se estima que entrarán en tu radio de detección en 5 segundos.",
  ui_story_1017_10171001_175_dialog_content = "¿Tan rápido? Déjame ver...",
  ui_story_1017_10171001_176_option_content = "Enlace mental—",
  ui_story_1017_10171001_177_dialog_content = "(¡Todo negro... Realmente es un atolladero!)",
  ui_story_1017_10171001_178_dialog_content = "¡Esto es exactamente lo que vi en sus mentes, Wrath! ¡Los Eclipsites vienen por aquí con el lodo!",
  ui_story_1017_10171001_179_dialog_content = "¿Ah?",
  ui_story_1017_10171001_180_dialog_content = "¡Actualiza a los Caballeros Lumo ahora y diles que evacuen a la gente!",
  ui_story_1017_10171001_181_dialog_content = "Sí, Gran Mariscal!",
  ui_story_1017_10171001_182_dialog_content = "Recon, ven conmigo a revisarlo. Engine VII, ¡cubre el trasero!",
  ui_story_1017_10171001_183_dialog_content = "Nadie se mueve sin mi comando. Si sientes que algo anda mal contigo, ¡retírate de inmediato!",
  ui_story_1017_10171001_184_dialog_content = "Gran Mariscal! ¡Los soldados del pelotón este se están volviendo locos uno tras otro!",
  ui_story_1017_10171001_185_dialog_content = "¿Este? Pero lo que siento es hacia el oeste...",
  ui_story_1017_10171001_186_dialog_content = "¡Cuidado!",
  ui_story_1017_10171001_187_dialog_content = "¿Incluso aquí? ¿Pero cómo?",
  ui_story_1017_10171001_188_dialog_content = "Es obvio que estamos rodeados.",
  ui_story_1017_10171001_189_dialog_content = "¡Quédate cerca de mí, PlayerName!",
  ui_story_1017_10171101_1_dialog_content = "<color=#e8d9bb>Un edificio de laboratorio en Illumina, no hace mucho tiempo...</color>",
  ui_story_1017_10171101_2_dialog_content = "¿Qué estás haciendo?",
  ui_story_1017_10171101_3_dialog_content = "Solo, ya sabes, patrullando... Sí, es mi turno de vigilar esta área hoy...",
  ui_story_1017_10171101_4_dialog_content = "Este es el laboratorio del profesor Ulysses y no hay patrullas regulares programadas.",
  ui_story_1017_10171101_5_dialog_content = "Um, bueno...",
  ui_story_1017_10171101_6_dialog_content = "¿Quién te envió?",
  ui_story_1017_10171101_7_dialog_content = "Yo...",
  ui_story_1017_10171101_8_dialog_content = "Lo siento, Comandante Yingel! No debería haber mentido. Solo estaba...",
  ui_story_1017_10171101_9_dialog_content = "Sabía que mi hermano era parte del más grandioso <color=#FFB400>experimento</color> en la historia de Illumina, y realmente estaba envidioso, por eso yo...",
  ui_story_1017_10171101_10_dialog_content = "Este proyecto es altamente clasificado y ningún miembro de la familia debe saberlo hasta que tenga éxito.",
  ui_story_1017_10171101_11_dialog_content = "Mi hermano y yo somos muy cercanos, así que sé todo sobre él. ¡Por favor, confía en mí! Estoy diciendo la verdad...",
  ui_story_1017_10171101_12_dialog_content = "...",
  ui_story_1017_10171101_13_dialog_content = "Desde que se unió a este experimento, ¡tanto mamá como yo hemos estado muy felices por él!",
  ui_story_1017_10171101_14_dialog_content = "Pero debido a mi limitada experiencia, no fui seleccionado...",
  ui_story_1017_10171101_15_dialog_content = "¿Te sientes abatido?",
  ui_story_1017_10171101_16_dialog_content = "Si...",
  ui_story_1017_10171101_17_dialog_content = "Habrá otras oportunidades en el futuro...",
  ui_story_1017_10171101_18_dialog_content = "¿En serio? ¿Todavía tendré otra oportunidad de ser la Estrella de Illumina?",
  ui_story_1017_10171101_19_dialog_content = "Seguro.",
  ui_story_1017_10171101_20_dialog_content = "Gracias, Comandante Yingel! Me iré enseguida.",
  ui_story_1017_10171101_21_dialog_content = "Está bien. Deberían estar luchando contra los Eclipsites en este momento.",
  ui_story_1017_10171101_22_dialog_content = "Sí, mi hermano es increíblemente talentoso... ¡Los Eclipsites no tendrán oportunidad contra él!",
  ui_story_1017_10171101_23_dialog_content = "...",
  ui_story_1017_10171101_24_dialog_content = "Ah, perdón, Comandante Yingel, no tomaré más de su tiempo. ¡Buen día!",
  ui_story_1017_10171101_25_dialog_content = "Entonces, ¿es ese el futuro de Illumina?",
  ui_story_1017_10171101_26_dialog_content = "...",
  ui_story_1017_10171101_27_dialog_content = "<size=30>Profesor...</size>",
  ui_story_1017_10171101_28_dialog_content = "...",
  ui_story_1017_10171101_29_dialog_content = "¿Profesor Ulysses?",
  ui_story_1017_10171101_30_dialog_content = "Ah, ahí estás. ¿Cómo va la sonda?",
  ui_story_1017_10171101_31_dialog_content = "Esto no es sobre el trabajo. Es otra cosa...",
  ui_story_1017_10171101_32_dialog_content = "¿Qué es?",
  ui_story_1017_10171101_33_dialog_content = "Señor, Axelia resultó gravemente herido en el ejercicio conjunto.",
  ui_story_1017_10171101_34_dialog_content = "Su oponente era Reinhardt, el más difícil al que se había enfrentado hasta ese momento.",
  ui_story_1017_10171101_35_dialog_content = "...",
  ui_story_1017_10171101_36_dialog_content = "¿Hay algo que quieras decir?",
  ui_story_1017_10171101_37_dialog_content = "Señor, Axelia ha sufrido muchas heridas graves, pero aún sigue luchando por Illumina.",
  ui_story_1017_10171101_38_dialog_content = "Me preocupa que, siguiendo el Programa Fosferus 2.0, ella...",
  ui_story_1017_10171101_39_dialog_content = "En este caso, estás exagerando.",
  ui_story_1017_10171101_40_dialog_content = "Aquí está la comparación de los dos conjuntos de datos. Echa un vistazo.",
  ui_story_1017_10171101_41_dialog_content = "Después de Phospherus 2.0, el rendimiento físico de los soldados mejoró 10 veces.",
  ui_story_1017_10171101_42_dialog_content = "Podría llegar hasta 20, incluso 50 veces en el futuro.",
  ui_story_1017_10171101_43_dialog_content = "Axelia obtuvo una puntuación muy alta en los datos post-experimento con mucho menos desgaste en batalla.",
  ui_story_1017_10171101_44_dialog_content = "Lo que significa que está en la cima de su habilidad.",
  ui_story_1017_10171101_45_dialog_content = "Y eso aplica para todos los soldados enviados a Crepúsculo.",
  ui_story_1017_10171101_46_dialog_content = "Pero señor, aún creo que enviar a Axelia de vuelta a la batalla justo después de que se recuperó es... despiadado...",
  ui_story_1017_10171101_47_dialog_content = "Y eso aplica para todos los jóvenes soldados que creen ser las \"futuras estrellas\" de Illumina.",
  ui_story_1017_10171101_48_dialog_content = "Sí, la realidad es despiadada y ese es su deber como soldados de Illumina.",
  ui_story_1017_10171101_49_dialog_content = "¿Realmente tiene que ser de esa manera?",
  ui_story_1017_10171101_50_dialog_content = "Si no se dan cuenta de que así es como obtuvieron sus poderes...",
  ui_story_1017_10171101_51_dialog_content = "Sería devastador para ellos cuando estén en caída libre después de alcanzar su punto máximo.",
  ui_story_1017_10171101_52_dialog_content = "Yingel, tu línea de preguntas no es apropiada para un oficial de inteligencia.",
  ui_story_1017_10171101_53_dialog_content = "A menos que tengas otras solicitudes, debo reanudar mi experimento.",
  ui_story_1017_10171101_54_dialog_content = "Pero Profesor—",
  ui_story_1017_10171101_55_dialog_content = "Antes de explicarte a ti mismo, intenta averiguar el objetivo.",
  ui_story_1017_10171101_56_dialog_content = "Si no puedes, creo que es necesario que dejes lo que estás haciendo y vengas a mi laboratorio más a menudo.",
  ui_story_1017_10171101_57_dialog_content = "Los sujetos uno en diez mil vinieron aquí por una sola razón—",
  ui_story_1017_10171101_58_dialog_content = "Sobrepasar los límites físicos, derrotar a los Eclipsites, proteger a Illumina y a los aurorianos, eso es todo.",
  ui_story_1017_10171101_59_dialog_content = "Un Aurorian muere en este laboratorio todos los días, pero eso es mejor que todos nosotros muriendo cuando lleguen los Eclipsites.",
  ui_story_1017_10171101_60_dialog_content = "Mi objetivo es lograr avances y mejorar el arsenal. Sin mejoras, no hay futuro para los Aurorians.",
  ui_story_1017_10171101_61_dialog_content = "El experimento, arsenal, datos... Aprecio todo lo que estás haciendo.",
  ui_story_1017_10171101_62_dialog_content = "Pero no puedo justificar sacrificar a los soldados, especialmente cuando desconocen las consecuencias.",
  ui_story_1017_10171101_63_dialog_content = "Bueno, algunos son conscientes de las consecuencias.",
  ui_story_1017_10171101_64_dialog_content = "Ella está dispuesta a hacer eso por el objetivo. ¿Y tú?",
  ui_story_1017_10171101_65_dialog_content = "No, así no es como Illumina llegó tan lejos...",
  ui_story_1017_10171101_66_dialog_content = "¡Uh!",
  ui_story_1017_10171101_67_dialog_content = "¿Qué es ese sonido...?",
  ui_story_1017_10171101_68_dialog_content = "Ya que el experimento está comenzando, podrías observar la brecha entre los dos grupos.",
  ui_story_1017_10171101_69_dialog_content = "(No... el sonido...)",
  ui_story_1017_10171101_70_dialog_content = "Ambos mejoran las condiciones físicas, pero los resultados son completamente diferentes.",
  ui_story_1017_10171101_71_dialog_content = "El sujeto de la izquierda es más explosivo durante más tiempo con la nueva Semilla.",
  ui_story_1017_10171101_72_dialog_content = "El de la derecha está casi completamente devorado por los Eclipsites.",
  ui_story_1017_10171101_73_dialog_content = "Ahora, ¿sabes por qué Reinhardt debe ser eliminado a toda costa?",
  ui_story_1017_10171101_74_dialog_content = "El tema a la izquierda...",
  ui_story_1017_10171101_75_dialog_content = "Independientemente de cómo interpretes la historia y la verdad, así es como es el mundo real.",
  ui_story_1017_10171101_76_dialog_content = "Esta es la única forma de sobrevivir y avanzar para nosotros.",
  ui_story_1017_10171101_77_dialog_content = "Se acerca Darkover, así que debemos recurrir a esto para mantenernos por delante.",
  ui_story_1017_10171101_X78_dialog_content = "(Me duele la cabeza...)",
  ui_story_1017_10171101_78_dialog_content = "Profesor, ¡el sujeto de la izquierda muestra una fuerte reacción al Darkflow en la habitación de la derecha!",
  ui_story_1017_10171101_79_dialog_content = "Doctor, el sujeto de la izquierda muestra una fuerte reacción al Darkflow en la habitación de la derecha.",
  ui_story_1017_10171101_80_dialog_content = "Sí, así es como debe ser. Las semillas reaccionan a otras semillas.",
  ui_story_1017_10171101_81_dialog_content = "Me pregunto qué hará a continuación...",
  ui_story_1017_10171101_X82_dialog_content = "...",
  ui_story_1017_10171101_82_dialog_content = "Profesor, ¡está intentando romper el vidrio y llegar a la habitación de la derecha!",
  ui_story_1017_10171101_83_dialog_content = "Doctor, ¡está intentando romper el vidrio y llegar a la habitación de la derecha!",
  ui_story_1017_10171101_84_dialog_content = "Veo que ni siquiera intenta abrir la puerta, simplemente rompe el vidrio.",
  ui_story_1017_10171101_85_dialog_content = "Muy bien, esta vez no mejoró el cerebro y compensó los defectos del primer lote de Semillas.",
  ui_story_1017_10171101_86_dialog_content = "¿En qué se diferencia esto de crear Eclipsites reales?",
  ui_story_1017_10171101_87_dialog_content = "Derrotar a los Eclipsites requiere medios extraordinarios.",
  ui_story_1017_10171101_88_dialog_content = "Fuera de combate, sigue siendo un compañero Aurorian.",
  ui_story_1017_10171101_89_dialog_content = "No, los Aurorians de Illumina nunca serán compañeros de los Eclipsites... Te lo suplico, por favor detén el experimento de inmediato.",
  ui_story_1017_10171101_90_dialog_content = "...",
  ui_story_1017_10171101_91_dialog_content = "Profesor, ¡lo logró! ¡Ha comenzado a devorar al Eclipsite!",
  ui_story_1017_10171101_92_dialog_content = "Profesor Ulysses, ¡por favor detenga el experimento de inmediato!",
  ui_story_1017_10171101_93_dialog_content = "Apenas está comenzando.",
  ui_story_1017_10171101_94_dialog_content = "¡Un soldado Illumina está comiendo Eclipsites! Esto es una grave violación de los procedimientos... ¡Por favor, detente ahora!",
  ui_story_1017_10171101_95_dialog_content = "Si mal no recuerdo, escribí los procedimientos.",
  ui_story_1017_10171101_96_dialog_content = "Las verificaciones y los avances son el objetivo de todos los experimentos.",
  ui_story_1017_10171101_97_dialog_content = "¡Profesor! ¡El sujeto de prueba está golpeando nuestro vidrio!",
  ui_story_1017_10171101_98_dialog_content = "(Tanta furia asesina en sus ojos... ¿Me está mirando a mí?)",
  ui_story_1017_10171101_99_dialog_content = "Por favor... Detén el experimento...",
  ui_story_1017_10171101_100_dialog_content = "Profesor, algo anda mal con el Comandante Yingel!",
  ui_story_1017_10171101_101_dialog_content = "¿Cómo te sientes, Yingel?",
  ui_story_1017_10171101_102_dialog_content = "Mi cabeza... duele... mucho...",
  ui_story_1017_10171101_103_dialog_content = "¿Por qué no te vas y tomas un descanso?",
  ui_story_1017_10171101_104_dialog_content = "Toma notas, la reacción y la distancia entre las Semillas necesitan más confirmación.",
  ui_story_1017_10171101_105_dialog_content = "¡Profesor! El vidrio acaba de—",
  ui_story_1017_10171101_106_dialog_content = "¡Llama a seguridad!",
  ui_story_1017_10171101_107_dialog_content = "¡No! ¡Muévete, profesor!",
  ui_story_1017_10171101_108_dialog_content = "...",
  ui_story_1017_10171201_1_dialog_content = "¡No podemos avanzar más! El pantano se extiende demasiado rápido.",
  ui_story_1017_10171201_2_dialog_content = "¡Todos, dispersense y retrocedan!",
  ui_story_1017_10171201_3_dialog_content = "Pero, ¿vas a seguir adelante?",
  ui_story_1017_10171201_4_dialog_content = "Algunos de mis soldados están atrapados adentro. No voy a dejarlos atrás.",
  ui_story_1017_10171201_5_dialog_content = "Pero la mitad de Crepúsculo está cubierta de lodo ahora...",
  ui_story_1017_10171201_6_dialog_content = "Por eso debemos eliminar al enemigo central antes de que inunde todo el pueblo.",
  ui_story_1017_10171201_7_dialog_content = "A raíz del ataque, el enemigo central se mueve de manera errática.",
  ui_story_1017_10171201_8_dialog_content = "Es una píldora, sin duda. Nos rodea de Eclipsites mientras se esconde en el barro y dispara a escondidas.",
  ui_story_1017_10171201_9_dialog_content = "Debemos seguir adelante para encontrarlo.",
  ui_story_1017_10171201_10_dialog_content = "Me preocupa que más soldados mueran si esto sigue así...",
  ui_story_1017_10171201_11_dialog_content = "Nadie muere en vano, PlayerName. ¡No sientas lástima por ellos!",
  ui_story_1017_10171201_12_dialog_content = "Solo soy...",
  ui_story_1017_10171201_13_dialog_content = "No es necesario. Todos conocían la posibilidad antes de venir.",
  ui_story_1017_10171201_14_dialog_content = "En realidad, quería preguntar, ¿por qué algunos de ellos serían enviados a la batalla?",
  ui_story_1017_10171201_15_dialog_content = "¿A qué información tienes acceso?",
  ui_story_1017_10171201_16_dialog_content = "Solo estoy suponiendo aquí...",
  ui_story_1017_10171201_17_dialog_content = "Para tener una reacción tan intensa al Darkflow, probablemente compartieron lo mismo en sus cuerpos con los Eclipsites.",
  ui_story_1017_10171201_18_dialog_content = "Se sintió tan familiar cuando conecté mentalmente con ellos.",
  ui_story_1017_10171201_19_dialog_content = "Fue lo mismo cuando me implantaron una Semilla...",
  ui_story_1017_10171201_20_dialog_content = "Esa es la única explicación para su cambio de rumbo e incluso siguiendo el mando central.",
  ui_story_1017_10171201_21_dialog_content = "Eso no les ocurrió a los soldados en Crepúsculo.",
  ui_story_1017_10171201_22_dialog_content = "¿Qué sientes por mí?",
  ui_story_1017_10171201_23_dialog_content = "Tú...",
  ui_story_1017_10171201_24_dialog_content = "Bueno, francamente, me di cuenta de por qué me enviaron a Crepúsculo en el momento en que los soldados comenzaron a mostrar señales.",
  ui_story_1017_10171201_25_dialog_content = "¿No estás aquí para ayudar a Crepúsculo?",
  ui_story_1017_10171201_26_dialog_content = "Realmente necesitamos ayuda ahora, pero ¿ves a alguien venir?",
  ui_story_1017_10171201_27_dialog_content = "...",
  ui_story_1017_10171201_28_dialog_content = "Los mensajes y señales de socorro no han sido respondidos durante toda la batalla.",
  ui_story_1017_10171201_29_dialog_content = "¿Tal vez se deba a la interferencia de Darkflow?",
  ui_story_1017_10171201_30_dialog_content = "No entiendes a Illumina. Nunca peleamos batallas para las que no estábamos preparados, a menos que hubiera otro propósito.",
  ui_story_1017_10171201_31_dialog_content = "Ahora solo podemos confiar en nosotros mismos.",
  ui_story_1017_10171201_32_dialog_content = "Mi único arrepentimiento es que probablemente terminaré como Reinhardt...",
  ui_story_1017_10171201_33_dialog_content = "¡Qué píldora amarga para tragar!",
  ui_story_1017_10171201_34_dialog_content = "Estaré contigo en esto, Wrath...",
  ui_story_1017_10171201_35_dialog_content = "Ya basta, ahora no es el momento de ponerse sentimental. ¿Qué ve Soroz?",
  ui_story_1017_10171201_36_dialog_content = "A unos 300 metros adelante, hay un gran grupo de Darkflow moviéndose en el pantano.",
  ui_story_1017_10171201_37_dialog_content = "¿Es ese el comando central o...?",
  ui_story_1017_10171201_38_dialog_content = "El Darkflow se está acumulando y dispersando en las cercanías. La evaluación preliminar sugiere que es un Eclipsite de alto nivel.",
  ui_story_1017_10171201_39_dialog_content = "¿Viene hacia nosotros?",
  ui_story_1017_10171201_40_dialog_content = "Las apariciones de la entidad son erráticas, lo que dificulta predecir su trayectoria de movimiento o anticipar su hora de llegada.",
  ui_story_1017_10171201_41_dialog_content = "¿Ves a alguien liderando?",
  ui_story_1017_10171201_42_dialog_content = "Sigue buscando...",
  ui_story_1017_10171201_43_dialog_content = "Gracias, Soroz.",
  ui_story_1017_10171201_44_dialog_content = "Oye, ¿a dónde fue ella?",
  ui_story_1017_10171201_45_dialog_content = "¡Vaya! ¿De dónde salieron todos estos Eclipsites?",
  ui_story_1017_10171201_46_dialog_content = "¿Qué está pasando, PlayerName!",
  ui_story_1017_10171201_47_dialog_content = "(Espera, mi cuerpo se siente...)",
  ui_story_1017_10171201_48_dialog_content = "¡Hay un Eclipsite de alto nivel moviéndose en el pantano!",
  ui_story_1017_10171201_49_dialog_content = "¿Ves eso? ¡Incluso si no atacamos, el Eclipsite aún intentará hacernos!",
  ui_story_1017_10171201_50_dialog_content = "¡Así que bien podríamos luchar la buena batalla!",
  ui_story_1017_10171201_51_dialog_content = "Probablemente haya innumerables Eclipsites acechando en el pantano. ¡Estoy listo para matar!",
  ui_story_1017_10171201_52_dialog_content = "Espera, Wrath, ¡es demasiado peligroso subir al barro!",
  ui_story_1017_10171201_53_dialog_content = "No, ¡debo seguir adelante! Aunque el lodo me ahogue, ¡tengo que matarlo!",
  ui_story_1017_10171201_54_dialog_content = "¡Todas las empresas, atraigan a los Eclipsites comunes a ambos lados!",
  ui_story_1017_10171201_55_dialog_content = "Engine VII, embiste a los Eclipsites que están adelante y despeja un camino para mí!",
  ui_story_1017_10171201_56_dialog_content = "¡Sí!",
  ui_story_1017_10171201_57_dialog_content = "¿Quién te crees que eres, escondiéndote detrás de tus secuaces...",
  ui_story_1017_10171201_58_dialog_content = "¡Gran Mariscal! ¡Eclipsites avistados en el flanco oeste!",
  ui_story_1017_10171201_59_dialog_content = "¡Gran Mariscal, se han movido al lado este!",
  ui_story_1017_10171201_60_dialog_content = "Entonces, seguir el intento de flanqueo debería ser...",
  ui_story_1017_10171201_61_dialog_content = "¡Cuida tus pies, Wrath!",
  ui_story_1017_10171201_62_dialog_content = "Sabía que tu estrategia de movimiento es—",
  ui_story_1017_10171201_63_dialog_content = "¡Completamente tonto!",
  ui_story_1017_10171201_64_dialog_content = "¡Gran Mariscal! ¿Estás bien?",
  ui_story_1017_10171201_65_dialog_content = "Esto es... ni siquiera suficiente... para afectarme...",
  ui_story_1017_10171201_66_dialog_content = "¡Te ves terrible! ¡Vuelve conmigo!",
  ui_story_1017_10171201_67_dialog_content = "No, lo golpeé...",
  ui_story_1017_10171201_68_dialog_content = "Es rápido. Solo lo vi salir del lodo por un segundo antes de sumergirse de nuevo.",
  ui_story_1017_10171201_69_dialog_content = "¿Lo lastimaste?",
  ui_story_1017_10171201_70_dialog_content = "No lo creo. Pero esa cosa... estaba intentando...",
  ui_story_1017_10171201_71_dialog_content = "Estás temblando por todas partes, Wrath!",
  ui_story_1017_10171201_72_dialog_content = "Esa es... Esa cosa... estaba intentando...",
  ui_story_1017_10171201_73_dialog_content = "Gran Mariscal! Engine VII viene a buscarte! ¡Súbete y sal del atolladero!",
  ui_story_1017_10171201_74_dialog_content = "¡Nadie se acerca!",
  ui_story_1017_10171201_75_dialog_content = "Este pantano es territorio de ese Eclipsite.",
  ui_story_1017_10171201_76_dialog_content = "Si te subes... lo lograrás...",
  ui_story_1017_10171201_77_dialog_content = "¡Pero ahora estás en ello!",
  ui_story_1017_10171201_78_dialog_content = "(¡Mantén tus sentidos, mantén tus sentidos!)",
  ui_story_1017_10171201_79_dialog_content = "¡Sal de ahí, Wrath!",
  ui_story_1017_10171201_80_dialog_content = "Se está acercando... No puedo retroceder.",
  ui_story_1017_10171201_81_dialog_content = "¡Si te caes, Crepúsculo está acabado!",
  ui_story_1017_10171201_82_dialog_content = "No caeré... lo sé ahora...",
  ui_story_1017_10171201_83_dialog_content = "Siento... el poder recorriendo mi ser...",
  ui_story_1017_10171201_84_dialog_content = "¡Debo matarlo!",
  ui_story_1017_10171201_85_dialog_content = "¡Entonces lo veré por ti!",
  ui_story_1017_10171201_86_dialog_content = "¡Atrás!",
  ui_story_1017_10171201_87_dialog_content = "El Darkflow es comparativamente más débil a tus diez. ¡Rodea por ese lado y ponte detrás de los Eclipsites!",
  ui_story_1017_10171201_88_dialog_content = "¡Eclipsite viene hacia ti, retrocede!",
  ui_story_1017_10171201_89_dialog_content = "El Darkflow está disminuyendo 5 pasos detrás de ti, por favor continúa...",
  ui_story_1017_10171201_90_dialog_content = "(¿Qué? De repente... estoy congelado en el lugar...)",
  ui_story_1017_10171201_91_dialog_content = "¡PlayerName!",
  ui_story_1017_10171201_92_dialog_content = "(¡Vamos, muévete, los Eclipsites se acercan!)",
  ui_story_1017_10171201_93_dialog_content = "¡¿PlayerName?!",
  ui_story_1017_10171201_94_dialog_content = "(No, no puedo moverme en absoluto...)",
  ui_story_1017_10171201_95_dialog_content = "(Tendré que guiar a Wrath telepáticamente...)",
  ui_story_1017_10171301_1_dialog_content = "¡Otro! ¡Lanza relámpago, perfora!",
  ui_story_1017_10171301_2_dialog_content = "(Cuanto más tiempo pasa, menos control tengo sobre mi cuerpo...)",
  ui_story_1017_10171301_3_dialog_content = "(Y el sentimiento ha pasado de confusión a sed de sangre...)",
  ui_story_1017_10171301_4_dialog_content = "(¿Terminaré como esos soldados...?)",
  ui_story_1017_10171301_5_dialog_content = "(¡No!)",
  ui_story_1017_10171301_6_dialog_content = "(¡No puedo caer! ¡No aquí, no ahora!)",
  ui_story_1017_10171301_7_dialog_content = "¡Oye, cuidado!",
  ui_story_1017_10171301_8_dialog_content = "¡Ay!",
  ui_story_1017_10171301_9_dialog_content = "¿De vuelta con nosotros ahora?",
  ui_story_1017_10171301_10_dialog_content = "Después del lanzamiento, sí.",
  ui_story_1017_10171301_11_dialog_content = "¿Qué dijiste?",
  ui_story_1017_10171301_12_dialog_content = "(Espera, PlayerName es quien está hablando...)",
  ui_story_1017_10171301_13_dialog_content = "(¿Por qué creo que estoy hablando con un Eclipsite?)",
  ui_story_1017_10171301_14_dialog_content = "¿Estás bien?",
  ui_story_1017_10171301_15_dialog_content = "Estoy bien.",
  ui_story_1017_10171301_16_dialog_content = "(¡Es PlayerName! ¡Es PlayerName antes que yo!)",
  ui_story_1017_10171301_17_dialog_content = "Wrath!",
  ui_story_1017_10171301_18_dialog_content = "Estoy bien.",
  ui_story_1017_10171301_19_dialog_content = "¿No te dije que te mantuvieras alejado del pantano?",
  ui_story_1017_10171301_20_dialog_content = "Pero entraste directamente en ello, como lo hicieron los soldados antes...",
  ui_story_1017_10171301_21_dialog_content = "...",
  ui_story_1017_10171301_22_dialog_content = "¿Ira?",
  ui_story_1017_10171301_23_dialog_content = "(Algo anda mal con Wrath...)",
  ui_story_1017_10171301_24_dialog_content = "Hay Eclipsites allí. ¡Tengo que ir a matarlos!",
  ui_story_1017_10171301_25_dialog_content = "¿Qué? ¡No veo ningún Eclipsite!",
  ui_story_1017_10171301_26_dialog_content = "¡Lanza relámpago, perfora!",
  ui_story_1017_10171301_27_dialog_content = "Wrath, eso no es Eclipsite. Es solo lodo común.",
  ui_story_1017_10171301_28_dialog_content = "¡Lanza relámpago, perfora!",
  ui_story_1017_10171301_29_dialog_content = "¿Qué está pasando acá?",
  ui_story_1017_10171301_30_dialog_content = "Supongo que todavía estás desorientado.",
  ui_story_1017_10171301_31_dialog_content = "Entonces, ¿los Eclipsites se esconden en el barro esperando emboscarnos?",
  ui_story_1017_10171301_32_dialog_content = "(Ella puede detectar y reaccionar a los Eclipsites, pero no parece tener el control total de sus acciones...)",
  ui_story_1017_10171301_33_dialog_content = "¡Empieza a buscar mientras aún puedo seguir!",
  ui_story_1017_10171301_34_dialog_content = "¡Claro! ¡La una en punto!",
  ui_story_1017_10171301_35_dialog_content = "¡Entendido!",
  ui_story_1017_10171301_36_dialog_content = "Una en punto, Wrath!",
  ui_story_1017_10171301_37_dialog_content = "...",
  ui_story_1017_10171301_38_dialog_content = "¡Vas por el camino equivocado!",
  ui_story_1017_10171301_39_dialog_content = "PlayerName, Wrath se ha lanzado hacia el enjambre de Eclipsites.",
  ui_story_1017_10171301_40_dialog_content = "¡Los Eclipsites la van a abrumar!",
  ui_story_1017_10171301_41_dialog_content = "¡Potencia de fuerza!",
  ui_story_1017_10171301_42_dialog_content = "(Es el pantano...)",
  ui_story_1017_10171301_43_dialog_content = "(Está moviendo rápido, y en todas direcciones.)",
  ui_story_1017_10171301_44_dialog_content = "(Oye, este lugar ha sido perturbado...)",
  ui_story_1017_10171301_45_dialog_content = "(¡Un brillo!)",
  ui_story_1017_10171301_46_dialog_content = "(El barro se amontona y forma una imagen...)",
  ui_story_1017_10171301_47_dialog_content = "(Esto es... Ulysses, Belisaria, y en la pantalla está...)",
  ui_story_1017_10171301_48_dialog_content = "(Desapareció antes de que pudiera entender el resto... Wrath no está aquí, sin embargo.)",
  ui_story_1017_10171301_49_dialog_content = "(¡Otro brillo!)",
  ui_story_1017_10171301_50_dialog_content = "(¡Es Reinhardt!)",
  ui_story_1017_10171301_51_dialog_content = "(Un joven Reinhardt... y espectadores, pancartas...)",
  ui_story_1017_10171301_52_dialog_content = "(\"Prueba Final del Gran Mariscal de Illumina\"... Perdido ante Reinhardt, veo...)",
  ui_story_1017_10171301_53_dialog_content = "(¿Lluvia...?)",
  ui_story_1017_10171301_54_dialog_content = "(¿Lluvia en lo que parecía ser una ciudad subterránea?)",
  ui_story_1017_10171301_55_dialog_content = "(Debe haber sido un día inolvidable para Wrath...)",
  ui_story_1017_10171301_56_dialog_content = "(Esto es... un laboratorio de Illumina.)",
  ui_story_1017_10171301_57_dialog_content = "(Veo a Ulysses y otros alrededor de una cama de laboratorio.)",
  ui_story_1017_10171301_58_dialog_content = "(En la cama está...)",
  ui_story_1017_10171301_59_dialog_content = "(¿Reinhardt?)",
  ui_story_1017_10171301_60_dialog_content = "(¿Cómo puede ser Reinhardt?)",
  ui_story_1017_10171301_61_dialog_content = "(¿Y no Wrath?!)",
  ui_story_1017_10171301_62_dialog_content = "(Espera un minuto, eso no es Ulysses junto a la cama... ¡Es Wrath!)",
  ui_story_1017_10171301_63_dialog_content = "(¿Puedes escucharme, Wrath?!)",
  ui_story_1017_10171301_64_dialog_content = "(...)",
  ui_story_1017_10171301_65_dialog_content = "(¡Despierta, estás en Twilight luchando contra Eclipsites ahora mismo!)",
  ui_story_1017_10171301_66_dialog_content = "(Eclipsitos... Cualquiera que se suba a la cama se convertirá en Eclipsitos...)",
  ui_story_1017_10171301_67_dialog_content = "(¡Crepúsculo está a punto de ser arrasado y tú estás herido por todas partes! ¡Despierta!)",
  ui_story_1017_10171301_68_dialog_content = "(¿Cómo es que Reinhardt nunca se lastima?)",
  ui_story_1017_10171301_69_dialog_content = "(Porque ella es una Eclipsite.)",
  ui_story_1017_10171301_70_dialog_content = "(¡Todos se lastiman! Pero tú eres el Gran Mariscal y los soldados te necesitan!)",
  ui_story_1017_10171301_71_dialog_content = "(Gran Mariscal...)",
  ui_story_1017_10171301_72_dialog_content = "(¿Está funcionando? Déjame intentar algo más.)",
  ui_story_1017_10171301_73_dialog_content = "(¡La Prueba Final del Gran Mariscal!)",
  ui_story_1017_10171301_74_dialog_content = "(No has vencido a Reinhardt todavía. ¡Vuelve a la batalla!)",
  ui_story_1017_10171301_75_dialog_content = "(Reinhardt... ¡Rayos Reinhardt!)",
  ui_story_1017_10171301_76_dialog_content = "(Sí, Reinhardt sigue en la arena. ¡Ve a demostrar que eres mejor!)",
  ui_story_1017_10171301_77_dialog_content = "(Wrath...!)",
  ui_story_1017_10171301_78_dialog_content = "PlayerName, finalmente has recuperado la conciencia.",
  ui_story_1017_10171301_79_dialog_content = "Estoy bien. ¿Dónde está Wrath? ¿Cómo está ella?",
  ui_story_1017_10171301_80_dialog_content = "La evaluación inicial indica que su conciencia parece haberse recuperado por completo y ha logrado reprimir a los Eclipsites una vez más.",
  ui_story_1017_10171301_81_dialog_content = "¡Maravilloso!",
  ui_story_1017_10171301_82_dialog_content = "Lo que acabas de hacer, iniciar un Impulso Forzado cuando la condición de Wrath era incierta, fue extremadamente arriesgado.",
  ui_story_1017_10171301_83_dialog_content = "Lo sé, pero era una emergencia y no tenía tiempo para perder...",
  ui_story_1017_10171301_84_dialog_content = "Tal vez me sentí seguro porque estás cerca.",
  ui_story_1017_10171301_85_dialog_content = "Mira a tu derecha, son los Caballeros de Ironthorn quienes te han mantenido a salvo.",
  ui_story_1017_10171301_86_dialog_content = "Leo y compañía están aquí!",
  ui_story_1017_10171301_87_dialog_content = "Se unieron a la pelea cuando estabas enlazando con Wrath.",
  ui_story_1017_10171301_88_dialog_content = "¡Gracias, Soroz!",
  ui_story_1017_10171301_89_dialog_content = "Soroz seguirá navegando por ti.",
  ui_story_1017_10171301_90_dialog_content = "¡Lanza relámpago, perfora!",
  ui_story_1017_10171301_91_dialog_content = "¿De qué estabas balbuceando hace un momento?",
  ui_story_1017_10171301_92_option_content = "Intentaba ayudar",
  ui_story_1017_10171301_93_dialog_content = "Qué bueno verte de vuelta con nosotros.",
  ui_story_1017_10171301_94_dialog_content = "Ocúpate de tus asuntos.",
  ui_story_1017_10171301_95_option_content = "No quise decir eso",
  ui_story_1017_10171301_96_dialog_content = "Solo intentaba sacarte de eso...",
  ui_story_1017_10171301_97_dialog_content = "Deja de mirar cosas que no deberías ver, ¿entendido?",
  ui_story_1017_10171301_98_dialog_content = "Bueno, ¡qué bueno verte regañándome así de nuevo!",
  ui_story_1017_10171301_99_dialog_content = "Todavía tenemos que proteger a Crepúsculo.",
  ui_story_1017_10171301_100_dialog_content = "Incluso si me convierto en un Eclipsite, ¡seré yo quien se asegure de que la ciudad permanezca intacta!",
  ui_story_1017_10171301_101_dialog_content = "¡Atención, Legión de la Guardia!",
  ui_story_1017_10171301_102_dialog_content = "Todos hemos experimentado incomodidades de diversos grados en la batalla, pero confía en mí, es temporal.",
  ui_story_1017_10171301_103_dialog_content = "Intenta concentrarte, esto reducirá muchos de los efectos negativos del Darkflow.",
  ui_story_1017_10171301_104_dialog_content = "Te garantizo que encontraré a cada soldado desaparecido, pero hasta entonces, ¡necesito a cada uno de ustedes!",
  ui_story_1017_10171301_105_dialog_content = "¡Cualquiera que esté herido o no esté completamente consciente, regrese a Illumina de inmediato!",
  ui_story_1017_10171301_106_dialog_content = "Aquellos de ustedes que aún puedan luchar o <color=#FFB400>no teman la influencia del Darkflow</color>, síganme en el ataque al comando central.",
  ui_story_1017_10171301_107_dialog_content = "¡¡¡Sí!!!",
  ui_story_1017_10171401_1_dialog_content = "¿Estás saciado?",
  ui_story_1017_10171401_2_dialog_content = "Ni siquiera cerca—",
  ui_story_1017_10171401_3_dialog_content = "Todas las cosas buenas deben guardarse hasta el final, por supuesto. La \"alfombra\" estaba muy bien colocada.",
  ui_story_1017_10171401_4_dialog_content = "Devóralos a todos—",
  ui_story_1017_10171401_5_dialog_content = "Deja de moverte. Estoy haciendo el ajuste final.",
  ui_story_1017_10171401_6_dialog_content = "Este lugar es lamentable comparado con un verdadero laboratorio. El progreso es demasiado lento.",
  ui_story_1017_10171401_7_dialog_content = "(Eclipsiano) Hay un Aurorian que se niega a caer...",
  ui_story_1017_10171401_8_dialog_content = "No te preocupes, el nuevo Gran Mariscal es el último curso de Mudbundle.",
  ui_story_1017_10171401_9_dialog_content = "Dame todo—",
  ui_story_1017_10171401_10_dialog_content = "(Eclipsiano) No ella, otro. Este Aurorian apenas ha sido afectado.",
  ui_story_1017_10171401_11_dialog_content = "¿Algo nuevo? Debo comprobarlo de inmediato.",
  ui_story_1017_10171401_12_dialog_content = "...",
  ui_story_1017_10171401_13_dialog_content = "Suspiro, esperaba mucho más que un tonto que no podría luchar para salir de una bolsa de papel mojada.",
  ui_story_1017_10171401_14_dialog_content = "Axelia es una máquina de guerra. Axelia ha estado luchando.",
  ui_story_1017_10171401_15_dialog_content = "Veo que no eres mudo. Ya que puedes abrir la boca, prueba esto.",
  ui_story_1017_10171401_16_dialog_content = "...",
  ui_story_1017_10171401_17_dialog_content = "Genial. ¿Cuál es tu objetivo si no es matar a los Eclipsites?",
  ui_story_1017_10171401_18_dialog_content = "\"Axelia debe derrotar al Gran Mariscal Reinhardt a toda costa.\"",
  ui_story_1017_10171401_19_dialog_content = "Je, no puedo creer que Ulysses lo haya estropeado tan mal. Probablemente no le importaba si sobrevivías.",
  ui_story_1017_10171401_20_dialog_content = "\"Axelia debe vivir como una persona.\"",
  ui_story_1017_10171401_21_dialog_content = "Basta de hablar. Es hora de que Mudbundle disfrute de su comida.",
  ui_story_1017_10171401_22_dialog_content = "Buen trabajo atrapando a todo el ejército aquí. Puedes encargarte de esto tú mismo.",
  ui_story_1017_10171401_23_dialog_content = "(Eclipsiano) Sí.",
  ui_story_1017_10171401_24_dialog_content = "...",
  ui_story_1017_10171401_25_dialog_content = "¡Morirás por emboscar a mis soldados!",
  ui_story_1017_10171401_26_dialog_content = "¡Te encontré! Pensé que te habías caído en el pantano.",
  ui_story_1017_10171401_27_dialog_content = "Gran Mariscal, hemos localizado a los miembros del equipo del Teniente Axelia uno por uno.",
  ui_story_1017_10171401_28_dialog_content = "Bien. Revisa si alguien está herido y mantente alerta ante otro ataque desde el mando central.",
  ui_story_1017_10171401_29_dialog_content = "¿Hay más soldados por aquí, Soroz?",
  ui_story_1017_10171401_30_dialog_content = "Buscando...",
  ui_story_1017_10171401_31_dialog_content = "...",
  ui_story_1017_10171401_32_dialog_content = "¿Por qué solo bloqueaste y no mataste a los Eclipsites que encontraste, Axelia?",
  ui_story_1017_10171401_33_dialog_content = "\"Axelia debe derrotar al Gran Mariscal Reinhardt a toda costa.\"",
  ui_story_1017_10171401_34_dialog_content = "¿Eso es lo que Ulysses te dijo?",
  ui_story_1017_10171401_35_dialog_content = "\"Axelia debe derrotar al Gran Mariscal Reinhardt a toda costa.\"",
  ui_story_1017_10171401_36_dialog_content = "Ya lograste ese objetivo. La venciste en el ejercicio conjunto.",
  ui_story_1017_10171401_37_dialog_content = "...",
  ui_story_1017_10171401_38_dialog_content = "No parece seriamente corrompida, pero aún está un poco desorientada.",
  ui_story_1017_10171401_39_dialog_content = "¿Qué te dijo Reinhardt antes de rendirse, Axelia?",
  ui_story_1017_10171401_40_dialog_content = "El Gran Mariscal Reinhardt quería que \"Axelia viviera como una persona.\"",
  ui_story_1017_10171401_41_dialog_content = "Oh, guau...",
  ui_story_1017_10171401_42_dialog_content = "Incluso cuando iba a la cárcel, no olvidó dejar maravillosos consejos. ¿Algo más?",
  ui_story_1017_10171401_43_dialog_content = "Axelia debe completar dos objetivos.",
  ui_story_1017_10171401_44_dialog_content = "\"Axelia debe derrotar al Gran Mariscal Reinhardt a toda costa.\"",
  ui_story_1017_10171401_45_dialog_content = "\"Axelia debe vivir como una persona.\"",
  ui_story_1017_10171401_46_dialog_content = "...",
  ui_story_1017_10171401_47_dialog_content = "Has cumplido tu primera misión, Axelia. El segundo objetivo es ahora tu única misión.",
  ui_story_1017_10171401_48_dialog_content = "El único objetivo es \"Axelia debe vivir como una persona.\"",
  ui_story_1017_10171401_49_dialog_content = "Así es. Solo podemos vivir derrotando a los Eclipsites. Eres un guerrero de Illumina y tienes derecho a vivir.",
  ui_story_1017_10171401_50_dialog_content = "Axelia debe derrotar a los Eclipsites, Axelia quiere vivir.",
  ui_story_1017_10171401_51_dialog_content = "Axelia está moviendo su cuerpo...?",
  ui_story_1017_10171401_52_dialog_content = "Ella está fuera de peligro, al menos por ahora. Podría necesitar más tiempo para recuperarse completamente.",
  ui_story_1017_10171401_53_dialog_content = "Gran Mariscal, el equipo del Teniente Axelia ha sido golpeado duramente por el Darkflow, y apenas se mantienen en la batalla.",
  ui_story_1017_10171401_54_dialog_content = "Creo que su fortaleza probablemente no está lejos de aquí...",
  ui_story_1017_10171401_55_dialog_content = "Gracias por tu ayuda y la de Soroz, PlayerName.",
  ui_story_1017_10171401_56_dialog_content = "Solo un último favor, transporta a los soldados que ya no pueden luchar de vuelta a casa por mí.",
  ui_story_1017_10171401_57_dialog_content = "¿Ahora mismo?",
  ui_story_1017_10171401_58_dialog_content = "¡Sin mencionar que los Eclipsites acechando en el pantano pueden salir en cualquier momento!",
  ui_story_1017_10171401_59_dialog_content = "¡Y siento que el mando central se está acercando!",
  ui_story_1017_10171401_60_dialog_content = "¿Sabes por qué?",
  ui_story_1017_10171401_61_dialog_content = "¿Por qué?",
  ui_story_1017_10171401_62_dialog_content = "Porque donde quiera que vaya, va.",
  ui_story_1017_10171401_63_dialog_content = "¿Ah?",
  ui_story_1017_10171401_64_dialog_content = "Probablemente no pudimos encontrar el escuadrón de Axelia antes porque estableció su base por aquí y nos aisló con el pantano.",
  ui_story_1017_10171401_65_dialog_content = "Enviar Eclipsites para hostigar a las tropas desde todas las direcciones fue solo una táctica de retraso, allanando el camino para el ataque final.",
  ui_story_1017_10171401_66_dialog_content = "No me atrajo hasta ahora... Supongo que la paliza que di estaba siendo demasiado.",
  ui_story_1017_10171401_67_dialog_content = "Pero, ¿por qué haría eso el enemigo principal?",
  ui_story_1017_10171401_68_dialog_content = "Apuntando a mis soldados y luego a mí, todo el tiempo escondiéndose detrás del pantano. Debe odiar a Illumina con pasión.",
  ui_story_1017_10171401_69_dialog_content = "¿Sabes quién está detrás de esto?",
  ui_story_1017_10171401_70_dialog_content = "Por supuesto. Derrota el corazón del pantano y ella no tendrá dónde esconderse.",
  ui_story_1017_10171401_71_dialog_content = "Más adelante, a 500 metros, un enorme grupo de Darkflow avanza rápidamente hacia tu posición.",
  ui_story_1017_10171401_72_dialog_content = "Wrath, Soroz sintieron—",
  ui_story_1017_10171401_73_dialog_content = "¡Cuidado con los pies!",
  ui_story_1017_10171401_74_dialog_content = "Leo! ¿Qué estás haciendo aquí?",
  ui_story_1017_10171401_75_dialog_content = "Ese Eclipsite asomaba por todas partes pero seguía moviéndose en una dirección.",
  ui_story_1017_10171401_76_dialog_content = "Entonces, ¿estás aquí para señalar con el dedo?",
  ui_story_1017_10171401_77_dialog_content = "No, la gente en Crepúsculo defenderá a todos los que lucharon junto a ellos.",
  ui_story_1017_10171401_78_dialog_content = "Has estado revisando a los soldados y eso te convierte en un líder confiable.",
  ui_story_1017_10171401_79_dialog_content = "Esta batalla se ha prolongado demasiado. Terminémosla.",
  ui_story_1017_10171401_80_dialog_content = "No tienes que decirlo dos veces. Pero no olvides nuestro partido después de que todo esto termine.",
  ui_story_1017_10171401_81_dialog_content = "Por supuesto.",
  ui_story_1017_10171401_82_dialog_content = "(Todavía puedo ir y estoy completamente consciente...)",
  ui_story_1017_10171401_83_dialog_content = "(Ojalá esta sea la última vez que tenga que dar la orden de atacar.)",
  ui_story_1017_10171401_84_dialog_content = "100 metros, PlayerName.",
  ui_story_1017_10171401_85_dialog_content = "Se estima que el enemigo entrará en tu rango de detección en 5 segundos.",
  ui_story_1017_10171401_86_dialog_content = "Ni siquiera puedo verlo de cerca. Tengo que cambiar a usar mi habilidad psíquica...",
  ui_story_1017_10171401_87_dialog_content = "Rooarrrrr—",
  ui_story_1017_10171401_88_dialog_content = "¿Qué diablos es esto...",
  ui_story_1017_10171401_89_dialog_content = "Wrath, ¡tiene una boca sangrienta!",
  ui_story_1017_10171401_90_dialog_content = "Suficientemente grande como para tragarnos enteros...",
  ui_story_1017_10171401_91_dialog_content = "¡Cúbrenos, Engine VII!",
  ui_story_1017_10171401_92_dialog_content = "¡La ráfaga! ¿Es creada por el atacante...",
  ui_story_1017_10171401_93_dialog_content = "Mi-Mira! Algo está saliendo del lodo...",
  ui_story_1017_10171401_94_dialog_content = "¡Rooooarrrrr!",
  ui_story_1017_10171401_95_dialog_content = "¡Tengan cuidado, este Darkflow es aún más duro que en el ataque anterior!",
  ui_story_1017_10171401_96_dialog_content = "Gran Mariscal, ¿qué debemos hacer—",
  ui_story_1017_10171401_97_dialog_content = "¡Los soldados adelante han sido arrastrados al lodo por el enemigo!",
  ui_story_1017_10171401_98_dialog_content = "...",
  ui_story_1017_10171401_99_dialog_content = "(No, todavía puedo hacer esto...)",
  ui_story_1017_10171401_100_dialog_content = "Wrath, ¡el pantano se está extendiendo! ¡Sal de aquí ahora!",
  ui_story_1017_10171401_101_dialog_content = "Atención, Legión de Guardias—",
  ui_story_1017_10171401_102_dialog_content = "...",
  ui_story_1017_10171401_103_dialog_content = "(Incluso dar órdenes es agotador...)",
  ui_story_1017_10171401_104_dialog_content = "Todos los demás... salgan del atolladero...",
  ui_story_1017_10171401_105_dialog_content = "Asegúrate de mantenerte lejos de mí...",
  ui_story_1017_10171401_106_dialog_content = "¡Mis soldados, síganme al pantano y cubran la retirada del ejército de Illumina!",
  ui_story_1017_10171401_107_dialog_content = "¡Resiste, Gran Mariscal Wrath!",
  ui_story_1017_10171401_108_dialog_content = "¡Dije que te alejes de mí!",
  ui_story_1017_10171401_109_dialog_content = "...",
  ui_story_1017_10171401_110_dialog_content = "Pero no deberías esforzarte más, Wrath!",
  ui_story_1017_10171401_111_dialog_content = "Caballero... Protege a mis soldados... Te lo imploro...",
  ui_story_1017_10171401_112_dialog_content = "Ya sea Eclipsite o lo que sea, no cederé...",
  ui_story_1017_10171401_113_dialog_content = "Entiendo...",
  ui_story_1017_10171401_114_dialog_content = "¡Sube al caballo, PlayerName!",
  ui_story_1017_10171401_115_dialog_content = "(Si Wrath queda atrapado en el lodo otra vez...)",
  ui_story_1017_10171401_116_dialog_content = "Wrath, ¡no olvides que aún no has terminado la pelea entre tú y Reinhardt!",
  ui_story_1017_10171401_117_dialog_content = "(!!!)",
  ui_story_1017_10171401_118_dialog_content = "(Enfócate... Concéntrate...)",
  ui_story_1017_10171401_119_dialog_content = "(Esto es...)",
  ui_story_1017_10171401_120_dialog_content = "(Mi batalla, la batalla del Gran Mariscal Wrath...)",
  ui_story_1017_10171402_1_dialog_content = "<color=#e8d9bb>En el pueblo de Crepúsculo, la tierra se ha convertido en un lodazal...</color>",
  ui_story_1017_10171402_2_dialog_content = "¡Capitán! Nuestras líneas de defensa han caído y el pantano ha inundado Crepúsculo, provocando pánico entre los residentes.",
  ui_story_1017_10171402_3_dialog_content = "Incluso el Gran Mariscal de Illumina fue tragado por el lodo...",
  ui_story_1017_10171402_4_dialog_content = "Lleven a los residentes al hospital. Nosotros seguiremos buscando.",
  ui_story_1017_10171402_X1_dialog_content = "¡Apúrate! ¡Corre! ¡El lodo está inundando el pueblo!",
  ui_story_1017_10171402_X2_dialog_content = "¿Qué está pasando?! Mi niño... ¿Dónde está mi niño?",
  ui_story_1017_10171402_X3_dialog_content = "Joselyne todavía está en el campo de batalla...",
  ui_story_1017_10171402_X4_dialog_content = "Nuestras líneas de defensa han caído y el pantano ha inundado Crepúsculo, ¡haciendo que los residentes entren en pánico!",
  ui_story_1017_10171402_X5_dialog_content = "El Capitán aún no ha vuelto a Crepúsculo... ¡Ve e infórmales ahora!",
  ui_story_1017_10171402_5_dialog_content = "Gran Mariscal—",
  ui_story_1017_10171402_6_dialog_content = "Wrath! Ira...",
  ui_story_1017_10171402_7_dialog_content = "¿Sigues aguantando, PlayerName?",
  ui_story_1017_10171402_8_dialog_content = "Estoy bien, solo demasiado agotado para usar habilidades psíquicas.",
  ui_story_1017_10171402_9_dialog_content = "También buscamos por todo el vecindario...",
  ui_story_1017_10171402_10_dialog_content = "No podía sentir su ubicación en absoluto incluso antes de que cayera ese Eclipsite.",
  ui_story_1017_10171402_11_dialog_content = "La última vez que Soroz la vio, estaba junto a la boca de esa cosa, cubierta de barro.",
  ui_story_1017_10171402_12_dialog_content = "Todo es mi culpa. No me mantuve cerca de ella como debía...",
  ui_story_1017_10171402_13_dialog_content = "Tuve que verla cargar contra el enemigo con los ojos vidriosos y claramente agotada...",
  ui_story_1017_10171402_14_dialog_content = "Aun así, ella eligió alejar al Eclipsite...",
  ui_story_1017_10171402_15_dialog_content = "No es tu culpa. Tuvimos que trabajar juntos y así fue como los vencimos.",
  ui_story_1017_10171402_16_dialog_content = "Pero para protegernos, el Mariscal Wrath en realidad ordenó a Engine VII que nos detuviera de ayudar...",
  ui_story_1017_10171402_17_dialog_content = "Una decisión tan peligrosa... Ella y sus soldados lo arriesgaron todo.",
  ui_story_1017_10171402_18_dialog_content = "...",
  ui_story_1017_10171402_19_dialog_content = "Axelia sobrevivió, pero no puede encontrar al Gran Mariscal Wrath.",
  ui_story_1017_10171402_20_dialog_content = "Me alegra verte lograrlo, Axelia.",
  ui_story_1017_10171402_21_dialog_content = "El Gran Mariscal Wrath es un guerrero de Illumina, y \"los guerreros de Illumina tienen derecho a vivir.\"",
  ui_story_1017_10171402_22_dialog_content = "...",
  ui_story_1017_10171402_23_dialog_content = "Aceleremos y demos otra vuelta fuera de los límites.",
  ui_story_1017_10171402_24_dialog_content = "Si nuestra nueva oponente ataca ahora, ¡será más difícil encontrarla!",
  ui_story_1017_10171402_25_dialog_content = "¡Seguro!",
  ui_story_1017_10171402_26_dialog_content = "PlayerName, no se ha detectado rastro de Wrath dentro de los límites de Crepúsculo.",
  ui_story_1017_10171402_27_dialog_content = "Basado en la duración de la búsqueda y nuestras estimaciones, la tasa de mortalidad de Wrath: 99%.",
  ui_story_1017_10171402_28_dialog_content = "No puede ser...",
  ui_story_1017_10171402_29_dialog_content = "¡Eso no puede ser!",
  ui_story_1017_10171402_30_dialog_content = "<size=50>Wrath¡¡¡</size>",
  ui_story_1017_10171501_1_dialog_content = "(¿Es esto Crepúsculo después de oscurecer?)",
  ui_story_1017_10171501_2_dialog_content = "(Estoy totalmente solo...)",
  ui_story_1017_10171501_3_dialog_content = "(Hmm, estoy separado de nuevo. Reinhardt sigue siendo tan bueno en la lucha...)",
  ui_story_1017_10171501_4_dialog_content = "(Me siento... débil... es difícil incluso moverme...)",
  ui_story_1017_10171501_5_dialog_content = "(La Subciudad... tan inquietantemente silenciosa...)",
  ui_story_1017_10171501_6_dialog_content = "(Maldita sea la cosa en mi espalda...)",
  ui_story_1017_10171501_7_dialog_content = "(Después de perder contra Reinhardt, pusieron restricciones dentro de mi cuerpo...)",
  ui_story_1017_10171501_8_dialog_content = "(¿Es este el precio final que tengo que pagar por perder el enfrentamiento?)",
  ui_story_1017_10171501_9_dialog_content = "(Obviamente, la batalla aún no ha terminado...)",
  ui_story_1017_10171501_10_dialog_content = "(¡Esa cosa no puede hacerme daño!)",
  ui_story_1017_10171501_11_dialog_content = "(¡No pueden lastimarme!)",
  ui_story_1017_10171501_12_dialog_content = "(Propongo una revancha...)",
  ui_story_1017_10171501_13_dialog_content = "(La multitud está gritando mi nombre al unísono...)",
  ui_story_1017_10171501_14_dialog_content = "(Devuélveme mi Lanza Relámpago... mi uniforme...)",
  ui_story_1017_10171501_15_dialog_content = "(Quiero ser un Gran Mariscal para Illumina...)",
  ui_story_1017_10171501_16_dialog_content = "(Nadie... puede detenerme...)",
  ui_story_1017_10171501_17_dialog_content = "Hace unos días, en la reunión confidencial de los superiores de Illumina...",
  ui_story_1017_10171501_18_dialog_content = "Ella está aquí, Comandante.",
  ui_story_1017_10171501_19_dialog_content = "Toma asiento.",
  ui_story_1017_10171501_20_dialog_content = "Sea lo que sea, dímelo directamente para que pueda volver a mi tarea.",
  ui_story_1017_10171501_21_dialog_content = "Siéntate.",
  ui_story_1017_10171501_22_dialog_content = "...",
  ui_story_1017_10171501_23_dialog_content = "¿Cómo te sentirías si te pidieran ser el Gran Mariscal de Illumina?",
  ui_story_1017_10171501_24_dialog_content = "¿Yo? ¿Pero por qué?",
  ui_story_1017_10171501_25_dialog_content = "Porque tú quieres y porque la Federación tiene la necesidad.",
  ui_story_1017_10171501_26_dialog_content = "No entiendo. ¿Qué hizo mal Reinhardt?",
  ui_story_1017_10171501_27_dialog_content = "¿No quedó claro en el juicio? Estabas allí.",
  ui_story_1017_10171501_28_dialog_content = "Pero eso no era la verdad, entonces ¿qué es lo que realmente estás haciendo?",
  ui_story_1017_10171501_29_dialog_content = "Lo que ves no siempre es real. Aprende a ser más pragmático.",
  ui_story_1017_10171501_30_dialog_content = "Decide si quieres ser el Gran Mariscal o dejar que alguien más lo sea.",
  ui_story_1017_10171501_31_dialog_content = "¿Esos tres lo saben?",
  ui_story_1017_10171501_32_dialog_content = "Eso depende de ti. Espero que lo pienses seriamente.",
  ui_story_1017_10171501_33_dialog_content = "...",
  ui_story_1017_10171501_34_dialog_content = "¿No tienes algo que agregar, Ulysses?",
  ui_story_1017_10171501_35_dialog_content = "Eres fantástico en todos los aspectos, excepto en lo físico.",
  ui_story_1017_10171501_36_dialog_content = "Cuando seas el Gran Mariscal, eliminaré esa debilidad para ti.",
  ui_story_1017_10171501_37_dialog_content = "...",
  ui_story_1017_10171501_38_dialog_content = "¿Que planeas hacer?",
  ui_story_1017_10171501_39_dialog_content = "No te preocupes, solo es el mismo pequeño experimento por el que pasó Reinhardt.",
  ui_story_1017_10171501_40_dialog_content = "Mejoras físicas para convertirse en el guerrero más poderoso de Illumina.",
  ui_story_1017_10171501_41_dialog_content = "¿Reinhardt tenía modificaciones biológicas?",
  ui_story_1017_10171501_42_dialog_content = "¿Estás sorprendido?",
  ui_story_1017_10171501_43_dialog_content = "(¿Reinhardt!?)",
  ui_story_1017_10171501_44_dialog_content = "(¡Poderoso! ¡Invencible! ¡Cima insuperable?!)",
  ui_story_1017_10171501_45_dialog_content = "(¡Todo es falso!)",
  ui_story_1017_10171501_46_dialog_content = "Ella aún era joven cuando se unió al Proyecto Sol Artificial.",
  ui_story_1017_10171501_47_dialog_content = "Pero es normal que ella no revele eso incluso cuando conoce la verdad, ya que a todos les gustaría ser geniales de forma natural.",
  ui_story_1017_10171501_48_dialog_content = "...",
  ui_story_1017_10171501_49_dialog_content = "Necesitas una oportunidad para demostrar si naciste para ser el Gran Mariscal.",
  ui_story_1017_10171501_50_dialog_content = "Y ahora es esa oportunidad.",
  ui_story_1017_10171501_51_dialog_content = "¿Qué oportunidad?",
  ui_story_1017_10171501_52_dialog_content = "Una gran batalla está destinada a estallar alrededor de Crepúsculo tarde o temprano. Estoy seguro de que podemos ganar con tú al mando.",
  ui_story_1017_10171501_53_dialog_content = "Ganaré, pero lo haré a mi manera.",
  ui_story_1017_10171501_54_dialog_content = "No tienes que responder eso ahora mismo.",
  ui_story_1017_10171501_55_dialog_content = "Otra cosa... ¿Recuerdas algo que dijiste hace mucho tiempo?",
  ui_story_1017_10171501_56_dialog_content = "Estabas parado al margen después de perder el enfrentamiento.",
  ui_story_1017_10171501_57_dialog_content = "Te dije que no deberías perder contra ella, pero tú respondiste—",
  ui_story_1017_10171501_58_dialog_content = "¡Pagaré cualquier precio para superar mis límites físicos!",
  ui_story_1017_10171501_59_dialog_content = "Esta es mi respuesta para ti.",
  ui_story_1017_10171501_60_dialog_content = "...",
  ui_story_1017_10171501_61_dialog_content = "<color=#e8d9bb>Wrath relata los detalles de la reunión confidencial a Barton, Hiiro y Sharona.</color>",
  ui_story_1017_10171501_62_dialog_content = "...",
  ui_story_1017_10171501_63_dialog_content = "¡Esos sinvergüenzas del Comité se rebajarían a cualquier nivel!",
  ui_story_1017_10171501_64_dialog_content = "Creo que todavía hay una oportunidad siempre y cuando no sea uno de los chicos de Ulysses.",
  ui_story_1017_10171501_65_dialog_content = "¿Qué opinas, Barton?",
  ui_story_1017_10171501_66_dialog_content = "No tengo nada más que añadir, excepto que no dejaré que el problema muera.",
  ui_story_1017_10171501_67_dialog_content = "En cuanto a quién la reemplazará en el futuro, no me importa de una forma u otra.",
  ui_story_1017_10171501_68_dialog_content = "De todos modos, no es que escucharía o seguiría a alguien que no sea Reinhardt.",
  ui_story_1017_10171501_69_dialog_content = "Pero, ¿qué pasaría si te hubieran convocado a ti en lugar de a mí?",
  ui_story_1017_10171501_70_dialog_content = "No dejaría que Ulysses jugara con este cuerpo. Lo mataría.",
  ui_story_1017_10171501_71_dialog_content = "Si eso fuera la verdad sobre el Gran Mariscal, no dependería de ti.",
  ui_story_1017_10171501_72_dialog_content = "La Zona Oscura se está volviendo más y más inquieta. Creo que los de arriba reaccionarán pronto.",
  ui_story_1017_10171501_73_dialog_content = "Sin un Gran Mariscal que lidere, será difícil enfrentar las incursiones de los Eclipsites.",
  ui_story_1017_10171501_74_dialog_content = "¿Estás listo para ello, Wrath?",
  ui_story_1017_10171501_75_dialog_content = "Reinhardt no tenía miedo cuando era la gran mariscal, así que no tengo nada que temer.",
  ui_story_1017_10171501_76_dialog_content = "¿Qué pasa si te conviertes en un monstruo?",
  ui_story_1017_10171501_77_dialog_content = "Entonces solo tengo una petición, y es que traigan a Reinhardt para que me mate personalmente.",
  ui_story_1017_10171501_78_dialog_content = "Eso es realmente... absurdo.",
  ui_story_1017_10171501_79_dialog_content = "No digas eso. Verás al Gran Mariscal siempre que regreses con vida.",
  ui_story_1017_10171501_80_dialog_content = "Puedes ir a buscarla tú mismo.",
  ui_story_1017_10171501_81_dialog_content = "Espera, no estaba bromeando acerca de Reinhardt.",
  ui_story_1017_10171501_82_dialog_content = "De todos nosotros aquí, solo tú puedes lograr eso.",
  ui_story_1017_10171501_83_dialog_content = "Te refieres a...",
  ui_story_1017_10171501_84_dialog_content = "Así es, una vez que el Eclipse haga su movimiento, Sharona y Barton regresarán a la zona de guerra y estarán en espera.",
  ui_story_1017_10171501_85_dialog_content = "Hasta que la línea esté en problemas, guardaré tu refuerzo hasta el último momento.",
  ui_story_1017_10171501_86_dialog_content = "En otras palabras, cuanto más intensa sea la lucha, mejores serán nuestras posibilidades.",
  ui_story_1017_10171501_87_dialog_content = "Las consecuencias de eso son encarcelamiento o muerte. ¿Estás seguro, Wrath?",
  ui_story_1017_10171501_88_dialog_content = "Estoy seguro. No creo que haya otras posibilidades.",
  ui_story_1017_10171501_89_dialog_content = "¿Qué tal unirse al Programa Fósforo?",
  ui_story_1017_10171501_90_dialog_content = "La verdad, aún no.",
  ui_story_1017_10171501_91_dialog_content = "Pero confía en mí, tomo mejores decisiones en situaciones urgentes.",
  ui_story_1017_10171501_92_dialog_content = "¿En serio?",
  ui_story_1017_10171501_93_dialog_content = "De todos modos, ten la seguridad de que no deshonrarás a Illumina en esta batalla bajo mi mando.",
  ui_story_1017_10171501_94_dialog_content = "<color=#e8d9bb>El siguiente día...</color>",
  ui_story_1017_10171501_95_dialog_content = "¿Cómo te sientes?",
  ui_story_1017_10171501_96_dialog_content = "Nada en absoluto.",
  ui_story_1017_10171501_97_dialog_content = "Muy pronto, tus pensamientos serán borrosos.",
  ui_story_1017_10171501_98_dialog_content = "Cuando despiertes de nuevo, encontrarás que el mundo es mucho más justo contigo.",
  ui_story_1017_10171501_99_dialog_content = "Justo...",
  ui_story_1017_10171501_100_dialog_content = "Cuando los fuertes dominan a los débiles, los débiles solo se quejan de que el mundo no es justo.",
  ui_story_1017_10171501_101_dialog_content = "Creen que los Eclipsites son abusivos, cuando en realidad son ellos los que no son lo suficientemente fuertes.",
  ui_story_1017_10171501_102_dialog_content = "Es lo mismo que tú intentando vencer a Reinhardt.",
  ui_story_1017_10171501_103_dialog_content = "Después del procedimiento, el campo estará equilibrado entre ustedes.",
  ui_story_1017_10171501_104_dialog_content = "(El campo... Incluso...)",
  ui_story_1017_10171501_105_dialog_content = "(Alguna vez pensé que no me detendría ante nada para alcanzar mis metas.)",
  ui_story_1017_10171501_106_dialog_content = "(Pero mientras los bordes afilados se clavaban en mi cuerpo, era como si me viera desmantelar este recipiente...)",
  ui_story_1017_10171501_107_dialog_content = "(Llevándose consigo mi ambición y arrogancia, reducidas a polvo.)",
  ui_story_1017_10171501_108_dialog_content = "(Cada paso del camino, cada elección que he tomado ha sido como luchar por respirar bajo el agua...)",
  ui_story_1017_10171501_109_dialog_content = "(Pero entre las corrientes subterráneas crecientes, me encuentro hundiéndome más profundo...)",
  ui_story_1017_10171501_110_dialog_content = "(¿Debería seguir luchando? ¿Es este realmente el resultado que deseo?)",
  ui_story_1017_10171501_111_dialog_content = "(El campo estaría nivelado, en efecto.)",
  ui_story_1017_10171501_112_dialog_content = "(Pero tal justicia...)",
  ui_story_1017_10171501_113_dialog_content = "(Llega muy tarde.)",
  ui_story_1018_10180101_1_dialog_content = "<color=#e8d9bb>En las sombras ocultas de la Zona Oscura...</color>",
  ui_story_1018_10180101_2_dialog_content = "Capitán... ¡Tengo suerte de que no me haya alcanzado ese aterrador <color=#FFB400>Eclipsite de resplandor verde</color> hace un momento!",
  ui_story_1018_10180101_3_dialog_content = "Esas enormes columnas de hielo y extrañas puntas de escarcha con las que nos hemos encontrado, están más allá de lo que imaginaba para la región de la Noche Eterna...",
  ui_story_1018_10180101_4_dialog_content = "Pero, ya que nuestra misión se trata de rastrear el núcleo de Guardian One, ¿por qué nos escondemos aquí, observando a estos Eclipsites?",
  ui_story_1018_10180101_5_dialog_content = "¡Shhh, no tan fuerte!",
  ui_story_1018_10180101_6_dialog_content = "Oh... Viendo lo emocionado que estabas hace un momento, pensé que ya habíamos encontrado la <color=#FFB400>guarida de los Eclipsites</color>...",
  ui_story_1018_10180101_7_dialog_content = "Pero es <color=#FFB400>todo terreno plano aquí</color>, con Eclipsites agrupándose en grupos a intervalos...",
  ui_story_1018_10180101_8_dialog_content = "Simplemente no entiendo qué vale la pena mirar fijamente en ellos.",
  ui_story_1018_10180101_9_dialog_content = "Bueno, eso demuestra que tienes una mente unidireccional como los Eclipsites.",
  ui_story_1018_10180101_10_dialog_content = "¡Pero no le digas a nadie que estás en mi escuadrón cuando regresemos!",
  ui_story_1018_10180101_11_dialog_content = "¿Eh? ¿Por qué? ¿Qué dije mal esta vez...?",
  ui_story_1018_10180101_12_dialog_content = "El secreto para rastrear es pasar de ser reactivo a proactivo y pensar como el enemigo.",
  ui_story_1018_10180101_13_dialog_content = "El Eclipsite que tomó el núcleo utilizó todos los trucos posibles para mantenernos en ese lugar extraño, porque no quería que llegáramos aquí.",
  ui_story_1018_10180101_14_dialog_content = "Después de todo, los ladrones nunca quieren que nadie descubra dónde se esconden.",
  ui_story_1018_10180101_15_dialog_content = "Este lugar parece simple, pero está custodiado por tantos Eclipsites, así que debe ser muy importante para Eclipse.",
  ui_story_1018_10180101_16_dialog_content = "Entonces... ¿qué es exactamente lo que los Eclipsites están protegiendo?",
  ui_story_1018_10180101_17_dialog_content = "Si estoy en lo correcto, lo que sea que sea, es tan crucial como el núcleo de Guardian One.",
  ui_story_1018_10180101_18_dialog_content = "Mira esto...",
  ui_story_1018_10180101_19_dialog_content = "¡Capitán! ¡Los Eclipsites acaban de empezar a alterarse!",
  ui_story_1018_10180101_20_dialog_content = "Mira, esa cosa reaccionó igual que el núcleo de Guardian One.",
  ui_story_1018_10180101_21_dialog_content = "Es un proyecto importante, ya veo.",
  ui_story_1018_10180101_22_dialog_content = "¿Estás diciendo que además del núcleo de Guardian One, podríamos encontrar una recompensa extra?",
  ui_story_1018_10180101_23_dialog_content = "Bueno, ¿no crees que deberíamos darle a Belisaria una sorpresa o dos?",
  ui_story_1018_10180101_24_dialog_content = "¡Capitán, realmente eres un maestro del reconocimiento!",
  ui_story_1018_10180101_25_dialog_content = "Pero aquí está el problema... Me preocupa que los Eclipsites nos hayan eliminado antes de que lleguemos allí.",
  ui_story_1018_10180101_26_dialog_content = "¡Piensa positivo! Nuestro vehículo está prácticamente unido a la Zona Oscura.",
  ui_story_1018_10180101_27_dialog_content = "El exterior está tratado especialmente para integrarse perfectamente con el entorno.",
  ui_story_1018_10180101_28_dialog_content = "Todos ustedes también fueron seleccionados porque su Lumina es débil, lo que hace más difícil que los Eclipsites los detecten.",
  ui_story_1018_10180101_29_dialog_content = "Hmm, ¿será esa la razón por la que no pudiste mejorar tus Luminatics?",
  ui_story_1018_10180101_30_dialog_content = "Suspiro... Mi comandante anterior me dijo una vez: estoy destinado a ser solo un conductor en esta vida.",
  ui_story_1018_10180101_31_dialog_content = "¡Solo te estaba molestando! Cuando regreses, ¡no olvides decirle que ahora eres un peón que me ha seguido a la Zona Oscura!",
  ui_story_1018_10180101_32_dialog_content = "De todos modos, tómalo de alguien experimentado, en realidad es más seguro cuanto más adentro estés en la Zona Oscura.",
  ui_story_1018_10180101_33_dialog_content = "Capitán... ¿De verdad no eres un exmiembro de Eclipse que desertó y se unió a Illumina?",
  ui_story_1018_10180101_34_dialog_content = "La pregunta que deberías hacer es si solía estar con Illumina pero ahora cambié de bando al Eclipse.",
  ui_story_1018_10180101_35_dialog_content = "...",
  ui_story_1018_10180101_36_dialog_content = "Ustedes acérquense y cúbranme. Háganlo en silencio.",
  ui_story_1018_10180101_37_dialog_content = "Voy a ver cómo exactamente esto es similar al núcleo de Guardian One.",
  ui_story_1018_10180101_38_dialog_content = "Entendido, Capitán. ¿Deberíamos compartir nuestras coordenadas actuales con el equipo de rastreo que está detrás de nosotros?",
  ui_story_1018_10180101_39_dialog_content = "Justo después de salir del lío... No parece que les esté yendo bien.",
  ui_story_1018_10180101_40_dialog_content = "<color=#e8d9bb>Lumopolis, Corte Real</color>",
  ui_story_1018_10180101_41_dialog_content = "Señor de la Ciudad, si la intención del refuerzo era únicamente proteger la Fortaleza Lumo, ¿por qué fueron a Crepúsculo?",
  ui_story_1018_10180101_42_dialog_content = "¿Sabes qué compone este nuevo ejército Illumina?",
  ui_story_1018_10180101_43_dialog_content = "¿Por qué preguntas?",
  ui_story_1018_10180101_44_dialog_content = "Echa un vistazo.",
  ui_story_1018_10180101_45_dialog_content = "Esto... es una carta urgente de la Iglesia de la Noche Blanca en Twilight y ni siquiera está firmada.",
  ui_story_1018_10180101_46_dialog_content = "\"Quagmire aplastó la base de Twilight. Eclipsites desatados. El esfuerzo conjunto de resistencia de Illumina y Lumo Knights es casi inútil...\"",
  ui_story_1018_10180101_47_dialog_content = "\"Los soldados de Illumina sufrieron graves bajas. El Gran Mariscal sigue desaparecido. Solo los Caballeros mantienen su posición.\"",
  ui_story_1018_10180101_48_dialog_content = "\"El hospital está lleno. Los suministros se están agotando. Todos están al límite...\"",
  ui_story_1018_10180101_49_dialog_content = "¿El Gran Mariscal está desaparecido? ¿Cómo puede ser eso?",
  ui_story_1018_10180101_50_dialog_content = "La Federación Illumina no es invencible, aunque aún no he visto un resultado como la batalla de Crepúsculo.",
  ui_story_1018_10180101_51_dialog_content = "Aun así, las otras legiones de Illumina permanecen firmes en Gannon y nunca se aventuran fuera.",
  ui_story_1018_10180101_52_dialog_content = "No tienen intención de ayudar a Twilight, sino que en realidad están probando en campo la nueva tecnología militar a través del recién nombrado Gran Mariscal.",
  ui_story_1018_10180101_53_dialog_content = "Si el curso sigue así, el nuevo ejército será víctima de esta prueba.",
  ui_story_1018_10180101_54_dialog_content = "¿Lo sabías todo este tiempo, Señor de la Ciudad?",
  ui_story_1018_10180101_55_dialog_content = "Es solo la historia repitiéndose. El motivo encaja perfectamente con Illumina.",
  ui_story_1018_10180101_56_dialog_content = "Entonces, ¿qué pasa con los soldados que aún luchan en el frente?",
  ui_story_1018_10180101_57_dialog_content = "Dejando a un lado Illumina, creo que un refuerzo debe garantizar la seguridad de la gente en Crepúsculo.",
  ui_story_1018_10180101_58_dialog_content = "Todavía estoy reflexionando.",
  ui_story_1018_10180101_59_dialog_content = "Pero si no decides pronto, ¡no solo Twilight, sino también las ciudades superficiales de Lumopolis se verán afectadas!",
  ui_story_1018_10180101_60_dialog_content = "<size=45>Estoy reflexionando.</size>",
  ui_story_1018_10180101_61_dialog_content = "...",
  ui_story_1018_10180101_62_dialog_content = "Señor de la Ciudad, un mensajero del Señor Sombrío Istvan solicita una audiencia.",
  ui_story_1018_10180101_63_dialog_content = "Envíalo adentro.",
  ui_story_1018_10180101_64_dialog_content = "Veo que esta isla voladora está tan desierta como siempre. ¡Saludos, Señor de la Ciudad y Lady Carleen!",
  ui_story_1018_10180101_65_dialog_content = "¿Qué negocio tienes, emisario de la Ciudad del Ajetreo y Bullicio?",
  ui_story_1018_10180101_66_dialog_content = "¡Vaya, no sabía que estoy capacitado para ser un emisario!",
  ui_story_1018_10180101_67_dialog_content = "Solo estoy aquí para transmitir algunas palabras de Istvan.",
  ui_story_1018_10180101_68_dialog_content = "Creo que también estás pendiente del alboroto en Crepúsculo.",
  ui_story_1018_10180101_69_dialog_content = "Pero aunque enviaste refuerzos, dejaste a los pueblos cercanos a su suerte. ¿Por qué es eso?",
  ui_story_1018_10180101_70_dialog_content = "¿Son esas las palabras exactas de Istvan?",
  ui_story_1018_10180101_71_dialog_content = "Cierto... Ligeramente exagerado.",
  ui_story_1018_10180101_72_dialog_content = "Probablemente no sepas que un visitante de Crepúsculo congenió con Istvan por pura casualidad en su camino para verte.",
  ui_story_1018_10180101_73_dialog_content = "Por lo que dijo, la situación en Crepúsculo se ha vuelto mucho peor.",
  ui_story_1018_10180101_74_dialog_content = "¿Sería este visitante de Crepúsculo Zhao?",
  ui_story_1018_10180101_75_dialog_content = "¡Sí, ese es el nombre!",
  ui_story_1018_10180101_76_dialog_content = "Señor de la Ciudad, Zhao de Crepúsculo solicita una audiencia.",
  ui_story_1018_10180101_77_dialog_content = "Mira, él ya está aquí.",
  ui_story_1018_10180101_78_dialog_content = "Pero todo el tráfico hacia Lumopolis ha sido cerrado.",
  ui_story_1018_10180101_79_dialog_content = "Mientras Istvan quiera, no hay nada que no se pueda hacer.",
  ui_story_1018_10180101_80_dialog_content = "Este Zhao se ha movido entre las facciones. Fue Umbraton después de Illumina, luego Lumopolis después de Umbraton...",
  ui_story_1018_10180101_81_dialog_content = "Si lo rechazas, él seguirá hacia Northland, el desierto de Rediesel...",
  ui_story_1018_10180101_82_dialog_content = "\"Cuerpo débil, pero nunca se rinde antes de conseguir lo que quiere. Ese es Zhao, la persona que quiere verte.\"",
  ui_story_1018_10180101_83_dialog_content = "Ahora esas son las palabras exactas de Istvan.",
  ui_story_1018_10180101_84_dialog_content = "Ciertamente pasó rápido la papa caliente que es Crepúsculo. ¿Por qué Istvan no vino él mismo?",
  ui_story_1018_10180101_85_dialog_content = "Solo soy el mensajero. Tienes que preguntarle al visitante sobre eso, Señor de la Ciudad.",
  ui_story_1018_10180101_86_dialog_content = "Este lugar es demasiado brillante. Es hora de que vuelva al mar. Me despido, Señor de la Ciudad y Lady Carleen!",
  ui_story_1018_10180101_87_dialog_content = "...",
  ui_story_1018_10180101_88_dialog_content = "¿No piensas invitar a Zhao a entrar?",
  ui_story_1018_10180101_89_dialog_content = "El problema con Crepúsculo involucra a Lumopolis e Illumina. Nadie más tiene derecho a negociar.",
  ui_story_1018_10180101_90_dialog_content = "Y como Illumina ha mostrado sus cartas, depende de Lumopolis defender Crepúsculo.",
  ui_story_1018_10180101_91_dialog_content = "Vendrás conmigo.",
  ui_story_1018_10180101_92_dialog_content = "¿Vas a Crepúsculo personalmente?",
  ui_story_1018_10180101_93_dialog_content = "No soy quien para ventilar los trapos sucios de Illumina. La atrocidad que han cometido contra los Aurorians es para que el Templo juzgue.",
  ui_story_1018_10180201_1_dialog_content = "<color=#e8d9bb>Pueblo del Crepúsculo</color>",
  ui_story_1018_10180201_2_dialog_content = "(Hemos estado buscando durante tanto tiempo...)",
  ui_story_1018_10180201_3_dialog_content = "(¿Dónde estás, Wrath?)",
  ui_story_1018_10180201_4_dialog_content = "Capitán, eliminamos a los Eclipsites que se arrastraron con el lodo después de derribar a los enemigos en el mando central.",
  ui_story_1018_10180201_5_dialog_content = "Mientras el pantano permanezca, Crepúsculo estará temporalmente fuera de peligro.",
  ui_story_1018_10180201_6_dialog_content = "Dada la situación actual, ¿diría que es el fin de esta fase de batalla, Capitán?",
  ui_story_1018_10180201_7_dialog_content = "Aunque hemos avanzado en la batalla, aún falta un tiempo hasta que todo termine.",
  ui_story_1018_10180201_8_dialog_content = "El Darkflow en el Crepúsculo ha disminuido bastante, ¿verdad, PlayerName?",
  ui_story_1018_10180201_9_dialog_content = "Sí. Soroz no está detectando ningún enemigo atraído por Darkflow.",
  ui_story_1018_10180201_10_dialog_content = "Bueno, el lodo que cubre Crepúsculo sigue siendo un problema.",
  ui_story_1018_10180201_11_dialog_content = "Cierto. El hospital solo puede estabilizar a los soldados afectados por el momento. Aún no se ha encontrado una cura.",
  ui_story_1018_10180201_12_dialog_content = "Va a ser un gran dolor de cabeza...",
  ui_story_1018_10180201_13_dialog_content = "Capitán, todos los residentes de Crepúsculo han sido trasladados al hospital temporal.",
  ui_story_1018_10180201_14_dialog_content = "Aquellos que residen más cerca del corazón del país han contribuido con sus casas para alojar a los refugiados.",
  ui_story_1018_10180201_15_dialog_content = "La mayoría de las personas no sufrieron gracias a tu esfuerzo desinteresado.",
  ui_story_1018_10180201_16_dialog_content = "Pero no es factible que todos se amontonen en Crepúsculo. Consideraré reubicar a los refugiados de la línea Illumina en las ciudades vecinas.",
  ui_story_1018_10180201_17_dialog_content = "Capitán, las afueras de la zona de guerra siguen siendo un desastre y me preocupa que una transferencia ahora podría no ser la opción más segura.",
  ui_story_1018_10180201_18_dialog_content = "Gran Mariscal Wrath y sus valientes fuerzas, quienes han estado liderando la carga, también están atrapados dentro, y no tenemos idea de dónde están...",
  ui_story_1018_10180201_19_dialog_content = "Hagamos la preparación primero y lo resolveremos una vez que la batalla se calme.",
  ui_story_1018_10180201_20_dialog_content = "Perdona, soldado, ¿cuántos de ustedes faltan, aproximadamente?",
  ui_story_1018_10180201_21_dialog_content = "Dos equipos se unieron a la carga del Gran Mariscal, sumando más de cien soldados...",
  ui_story_1018_10180201_22_dialog_content = "Y casi todos ellos... son nuevos reclutas.",
  ui_story_1018_10180201_23_dialog_content = "Eso es casi la mitad de los Caballeros de Ironthorn.",
  ui_story_1018_10180201_24_dialog_content = "Capitán, avistamos a algunos soldados cerca del muro oeste. Pero con la situación incierta, nuestros camaradas mantienen distancia.",
  ui_story_1018_10180201_25_dialog_content = "¡Compruébalo ahora!",
  ui_story_1018_10180201_26_dialog_content = "Ellos... Sí, eran soldados que se lanzaron a la batalla junto al Gran Mariscal.",
  ui_story_1018_10180201_27_dialog_content = "Echando un vistazo rápido y hay docenas de ellos...",
  ui_story_1018_10180201_28_dialog_content = "Mueva cuidadosamente a los soldados muertos a la base y esté atento a los enemigos escondidos en el barro.",
  ui_story_1018_10180201_29_dialog_content = "¡Sí!",
  ui_story_1018_10180201_30_dialog_content = "...",
  ui_story_1018_10180201_31_dialog_content = "Están muertos así nomás... Ni siquiera tuve tiempo de conocerlos...",
  ui_story_1018_10180201_32_dialog_content = "Eso es un soldado para ti, PlayerName.",
  ui_story_1018_10180201_33_dialog_content = "Luchando en guerras regularmente, a veces sin siquiera tener la oportunidad de llorar a tus compañeros caídos antes de ir a la siguiente batalla.",
  ui_story_1018_10180201_34_dialog_content = "...",
  ui_story_1018_10180201_35_dialog_content = "¡Tenemos uno que aún respira, Leo!",
  ui_story_1018_10180201_36_dialog_content = "¿Cuál es su situación?",
  ui_story_1018_10180201_37_dialog_content = "Deberíamos poder estabilizarlo con tratamiento...",
  ui_story_1018_10180201_38_dialog_content = "...",
  ui_story_1018_10180201_39_dialog_content = "¿Está asustado o intenta decir algo?",
  ui_story_1018_10180201_40_dialog_content = "Parece que está masticando algo.",
  ui_story_1018_10180201_41_dialog_content = "¡¡¡Rugido!!!",
  ui_story_1018_10180201_42_dialog_content = "¡Espada de rayo!",
  ui_story_1018_10180201_43_dialog_content = "¡Se convirtió en un Eclipsite de la nada!",
  ui_story_1018_10180201_44_dialog_content = "Veo que mi peor miedo se ha hecho realidad...",
  ui_story_1018_10180201_45_dialog_content = "¡¡¡Rugido!!!",
  ui_story_1018_10180201_46_dialog_content = "¿Y por ahí también?",
  ui_story_1018_10180201_47_dialog_content = "¡Capitán! Estos soldados caídos... No, ¡los Eclipsites nos están atacando!",
  ui_story_1018_10180201_48_dialog_content = "La situación es peor de lo que imaginaba. ¡Tenemos que detener la búsqueda y el rescate!",
  ui_story_1018_10180201_49_dialog_content = "¡Prepárate para luchar!",
  ui_story_1018_10180201_50_dialog_content = "Espera, Leo...",
  ui_story_1018_10180202_1_dialog_content = "¿Estos soldados están realmente muertos?",
  ui_story_1018_10180202_2_dialog_content = "...",
  ui_story_1018_10180202_3_dialog_content = "No sientas lástima por los Eclipsites.",
  ui_story_1018_10180202_4_dialog_content = "Incluso si alguna vez fueron soldados, solo causarían mayores pérdidas si se les permite mantenerse en pie.",
  ui_story_1018_10180202_5_dialog_content = "Soldados Illumina, déjennos esto a nosotros. ¡Ustedes salgan de Crepúsculo lo más pronto posible!",
  ui_story_1018_10180202_6_dialog_content = "Capitán Leo, los soldados Illumina... aún no podemos salir de Crepúsculo.",
  ui_story_1018_10180202_7_dialog_content = "Dije, todos los soldados Illumina, salgan de Crepúsculo.",
  ui_story_1018_10180202_8_dialog_content = "...",
  ui_story_1018_10180202_9_dialog_content = "En ese caso, Capitán Leo, debo llamar su atención sobre un asunto en particular.",
  ui_story_1018_10180202_10_dialog_content = "Por favor, escúchame y luego puedes decidir si quieres que nos vayamos.",
  ui_story_1018_10180202_11_dialog_content = "Habla.",
  ui_story_1018_10180202_12_dialog_content = "Antes de llegar a Crepúsculo, nuestra Legión de la Guardia Illumina estaba compuesta por los soldados más hábiles, razón por la cual también se nos conoce como la Reserva de Élite.",
  ui_story_1018_10180202_13_dialog_content = "Los hermanos que están detrás de mí son todos miembros de la Reserva Élite, los seguidores más dedicados del Gran Mariscal Wrath.",
  ui_story_1018_10180202_14_dialog_content = "Nunca antes habíamos estado en batallas tan intensas, pero el hecho de que aún estemos de pie es prueba de nuestra fuerza.",
  ui_story_1018_10180202_15_dialog_content = "Entiendo a lo que te refieres, pero estos novatos que se convirtieron en Eclipsites recibieron entrenamiento especial de Illumina.",
  ui_story_1018_10180202_16_dialog_content = "Después de llegar a Crepúsculo, ellos, incluido tu Gran Mariscal, se vieron manchados por el pantano.",
  ui_story_1018_10180202_17_dialog_content = "Esa es la realidad... sin embargo, te prometo que, antes de entrar en la batalla, ninguno de nosotros podría haber anticipado que algo así sucediera.",
  ui_story_1018_10180202_18_dialog_content = "Con las numerosas bajas de nuestros camaradas y sin saber dónde está el Gran Mariscal, todos estamos bastante devastados.",
  ui_story_1018_10180202_19_dialog_content = "Como tal, en representación de los soldados de la Reserva de Élite, estoy aquí para expresar nuestra petición: quedémonos aquí y defendamos Twilight.",
  ui_story_1018_10180202_20_dialog_content = "Hasta que encontremos al Gran Mariscal, este es el orden que todos nuestros soldados de Illumina deben seguir.",
  ui_story_1018_10180202_21_dialog_content = "Nos ofrecemos como voluntarios para unirnos a la fuerza que protege a Twilight y, en ausencia del Gran Mariscal, tomaré el mando temporalmente.",
  ui_story_1018_10180202_22_dialog_content = "Como líder, como soldado, veo.",
  ui_story_1018_10180202_23_dialog_content = "¿Incluso si los enemigos alguna vez fueron tus compatriotas?",
  ui_story_1018_10180202_24_dialog_content = "Si se han convertido en eclipses causando estragos en Crepúsculo... no mostraré piedad...",
  ui_story_1018_10180202_25_dialog_content = "¡¡¡Rugido!!!",
  ui_story_1018_10180202_26_dialog_content = "¡Aquí hay más, Capitán!",
  ui_story_1018_10180202_27_dialog_content = "Yo...",
  ui_story_1018_10180202_28_dialog_content = "¡Espada de rayo!",
  ui_story_1018_10180202_29_dialog_content = "Tu acción no respaldó tu juramento, soldado. Hazte a un lado. Están más allá de la redención.",
  ui_story_1018_10180202_30_dialog_content = "No saques conclusiones precipitadas, Leo. Los que no atacaron no son exactamente un caso perdido.",
  ui_story_1018_10180202_31_dialog_content = "Sí, dudaron...",
  ui_story_1018_10180202_32_dialog_content = "Pero todos lo vieron, contenerse solo les dio la oportunidad de lastimarlos.",
  ui_story_1018_10180202_33_dialog_content = "¡Pero aún son Aurorianos!",
  ui_story_1018_10180202_34_dialog_content = "¡¡¡Rugido!!!",
  ui_story_1018_10180202_35_dialog_content = "Mira de nuevo, ¡no son diferentes a un Eclipsite! Cualquiera que intente dañar a un soldado de Crepúsculo es un enemigo.",
  ui_story_1018_10180202_36_dialog_content = "Soldados de Illumina, si desean defender el Crepúsculo, ¡muestren su fuerza y sean implacables con el enemigo!",
  ui_story_1018_10180202_37_dialog_content = "De lo contrario, abandona Crepúsculo, tu servicio ya no es necesario.",
  ui_story_1018_10180202_38_dialog_content = "Yo—",
  ui_story_1018_10180202_39_dialog_content = "No te corresponde ordenar a mis soldados...",
  ui_story_1018_10180202_40_dialog_content = "Afectados por el Darkflow... Pero ellos... no merecen morir...",
  ui_story_1018_10180202_41_dialog_content = "Estoy seguro...",
  ui_story_1018_10180202_42_dialog_content = "Leo, ¡es Wrath!",
  ui_story_1018_10180202_43_dialog_content = "...",
  ui_story_1018_10180202_44_dialog_content = "Porque... he estado allí...",
  ui_story_1018_10180202_45_dialog_content = "Gran Mariscal!",
  ui_story_1018_10180301_1_dialog_content = "Wrath! ¡Te hemos estado buscando por todas partes!",
  ui_story_1018_10180301_2_dialog_content = "Lograste controlar a los soldados enloquecidos tan pronto como apareciste...",
  ui_story_1018_10180301_3_dialog_content = "No podían controlarse... bajo la influencia del pantano...",
  ui_story_1018_10180301_4_dialog_content = "No querían... lastimar a nadie...",
  ui_story_1018_10180301_5_dialog_content = "...",
  ui_story_1018_10180301_6_dialog_content = "Noche Blanca en lo alto... ¡Me alegra que estés a salvo, Gran Mariscal!",
  ui_story_1018_10180301_7_option_content = "Pareces muy cansado ahora mismo",
  ui_story_1018_10180301_8_dialog_content = "¿Estás herido o sientes molestias en alguna parte?",
  ui_story_1018_10180301_9_dialog_content = "Aparte del dolor causado por el impacto del pantano...",
  ui_story_1018_10180301_10_dialog_content = "No recuerdo nada.",
  ui_story_1018_10180301_11_option_content = "¿Qué paso?",
  ui_story_1018_10180301_12_dialog_content = "¿Por qué no pudimos encontrarte en absoluto?",
  ui_story_1018_10180301_13_dialog_content = "Yo tampoco estoy seguro...",
  ui_story_1018_10180301_14_dialog_content = "Todo lo que recuerdo es que todo se volvió oscuro después de salir del barro...",
  ui_story_1018_10180301_15_dialog_content = "No te preocupes, solo me llené de barro.",
  ui_story_1018_10180301_16_dialog_content = "¿Cuántos soldados más como este siguen ahí afuera...?",
  ui_story_1018_10180301_17_dialog_content = "Leo ha estado buscando por ellos...",
  ui_story_1018_10180301_18_dialog_content = "¡Pero afortunadamente, estás de vuelta!",
  ui_story_1018_10180301_19_dialog_content = "Si...",
  ui_story_1018_10180301_20_dialog_content = "Dije que salvaría a Crepúsculo antes de convertirme en un Eclipsite.",
  ui_story_1018_10180301_21_dialog_content = "Ahora tengo que agregar a mis soldados a esa lista...",
  ui_story_1018_10180301_22_dialog_content = "No toleraré ningún intento de desestimarlos como Eclipsites y matarlos...",
  ui_story_1018_10180301_23_dialog_content = "Me alegra ver que estás bien, Gran Mariscal.",
  ui_story_1018_10180301_24_dialog_content = "Nunca he tenido la intención de dañar a los soldados de Illumina. Solo estoy cuidando de Crepúsculo.",
  ui_story_1018_10180301_25_dialog_content = "Matar al enemigo cuando sea conveniente, abandonar a las tropas ante la adversidad... Lo siento si me niego a aceptar la estrategia de los Caballeros.",
  ui_story_1018_10180301_26_dialog_content = "Gran Mariscal, yo...",
  ui_story_1018_10180301_27_dialog_content = "Ahora que he vuelto, lideraré a mis soldados.",
  ui_story_1018_10180301_28_dialog_content = "No tengo suficiente energía para otra ronda contigo, así que no te pases de la raya...",
  ui_story_1018_10180301_29_dialog_content = "Como desees, Gran Mariscal.",
  ui_story_1018_10180301_30_dialog_content = "Gran Mariscal Wrath, parece que estás debilitado en este momento.",
  ui_story_1018_10180301_31_dialog_content = "¡Por favor, ven conmigo al hospital para recibir tratamiento!",
  ui_story_1018_10180301_32_dialog_content = "Estamos en un campo de batalla. No me voy mientras mis soldados sigan en pie.",
  ui_story_1018_10180301_33_dialog_content = "Bueno, al menos permítame vendar sus heridas. ¡Por favor, tome un descanso en mi caballo!",
  ui_story_1018_10180301_34_dialog_content = "Si quieres hacerlo por tus tropas, te aconsejaría que te hagas revisar.",
  ui_story_1018_10180301_35_dialog_content = "Sí, pasaste bastante tiempo en el atolladero, así que probablemente no deberías arriesgarte.",
  ui_story_1018_10180301_36_dialog_content = "Está bien. Gracias de antemano, Joselyne.",
  ui_story_1018_10180301_37_dialog_content = "Noche Blanca en lo alto... Es sorprendente que aún puedas activar Luminatics.",
  ui_story_1018_10180301_38_dialog_content = "Tienes muchas lesiones, pero ninguna es mortal, aunque estás gravemente debilitado.",
  ui_story_1018_10180301_39_dialog_content = "¿Severamente debilitado? No lo creo...",
  ui_story_1018_10180301_40_dialog_content = "Por el contrario, siento que mi cuerpo se está recuperando rápidamente.",
  ui_story_1018_10180301_41_dialog_content = "En retrospectiva, había una fuerza fluyendo a través de mí cuando estaba inconsciente...",
  ui_story_1018_10180301_42_dialog_content = "Como si alguien me estuviera sanando... Era difícil describir esa sensación.",
  ui_story_1018_10180301_43_dialog_content = "¿Sanándote? ¿Cómo podría haber alguien más allí?",
  ui_story_1018_10180301_44_dialog_content = "Eso es absurdo... Pero no está fuera del ámbito de lo posible, ya que estoy aquí de pie en este momento.",
  ui_story_1018_10180301_45_dialog_content = "Es una lástima que no pude proteger a mis soldados...",
  ui_story_1018_10180301_46_dialog_content = "Gran Mariscal, aún no hemos localizado a los dos equipos que entraron en combate junto a usted.",
  ui_story_1018_10180301_47_dialog_content = "El Capitán Axelia ha estado liderando la misión de búsqueda.",
  ui_story_1018_10180301_48_dialog_content = "Pero... Los que acabas de encontrar podrían ser ellos...",
  ui_story_1018_10180301_49_dialog_content = "Los entregué directamente al enemigo...",
  ui_story_1018_10180301_50_dialog_content = "No, Gran Mariscal! Fuimos nosotros, yendo en contra de sus órdenes...",
  ui_story_1018_10180301_51_dialog_content = "¡Estábamos decididos a avanzar junto a ti! Y estos nuevos reclutas, ellos eran...",
  ui_story_1018_10180301_52_dialog_content = "Lanzaste un ataque contra ese enemigo sin dudarlo y cambiaste el rumbo.",
  ui_story_1018_10180301_53_dialog_content = "Si podemos encontrarlos pronto, ¡tal vez aún haya esperanza!",
  ui_story_1018_10180301_54_dialog_content = "...",
  ui_story_1018_10180301_55_dialog_content = "De todos modos, no puedo permitir que sigas corriendo riesgos conmigo...",
  ui_story_1018_10180301_56_dialog_content = "<color=#e8d9bb>Todos llegan al borde oeste de la zona de guerra...</color>",
  ui_story_1018_10180301_57_dialog_content = "Nunca pensé que el pantano llegaría tan lejos... Parece que sigue moviéndose.",
  ui_story_1018_10180301_58_dialog_content = "Quizás vengan más enemigos, y quién sabe a dónde llevará el cenagal fluyente May a los soldados desaparecidos.",
  ui_story_1018_10180301_59_dialog_content = "En ese caso, la batalla no terminará mientras el atolladero siga presente.",
  ui_story_1018_10180301_60_dialog_content = "Lo que más me preocupa es el enemigo atacando junto a mis soldados...",
  ui_story_1018_10180301_61_dialog_content = "Soy responsable del impacto negativo en esta batalla debido a mi mal juicio.",
  ui_story_1018_10180301_62_dialog_content = "No podrías haberlo sabido, Gran Mariscal. Continuemos la búsqueda a lo largo del pantano.",
  ui_story_1018_10180301_63_dialog_content = "Seguro...",
  ui_story_1018_10180301_64_dialog_content = "Gran Mariscal Wrath! Mira el flanco oeste de la línea de defensa—",
  ui_story_1018_10180301_65_dialog_content = "¡Tres Engine VII mechas están ahí! ¡Junto con nuestros soldados!",
  ui_story_1018_10180301_66_dialog_content = "Ese es el mecha cubriendo mi ataque... No esperaba que estuviera aquí.",
  ui_story_1018_10180301_67_dialog_content = "Todo está en ruinas... La base detrás de ellos ha sido destrozada en mil pedazos. Afortunadamente, mantuvieron el terreno.",
  ui_story_1018_10180301_68_dialog_content = "Esto deja solo 1 Engine VII desaparecido, pero debería estar cerca. Vamos a revisar...",
  ui_story_1018_10180301_69_dialog_content = "<color=#e8d9bb>¡Chomp! ¡Chomp!</color>",
  ui_story_1018_10180301_70_dialog_content = "Eh... ¿Capitán?!",
  ui_story_1018_10180301_71_dialog_content = "...",
  ui_story_1018_10180301_72_dialog_content = "El mecha está totalmente destrozado...",
  ui_story_1018_10180301_73_dialog_content = "Y los soldados alrededor de Engine VII... están royendo la capa exterior del mech...",
  ui_story_1018_10180301_74_dialog_content = "Rugido...",
  ui_story_1018_10180301_75_dialog_content = "¿Recargándote con estos como un Eclipsito?",
  ui_story_1018_10180301_76_dialog_content = "Vaya...",
  ui_story_1018_10180301_77_dialog_content = "¡Rarrr!",
  ui_story_1018_10180301_78_dialog_content = "...",
  ui_story_1018_10180301_79_dialog_content = "Manténgase en el caballo, Gran Mariscal. Parece que no se han dado cuenta de que nos acercamos. Podemos encargarnos desde aquí.",
  ui_story_1018_10180301_80_dialog_content = "Así es, puedo eliminar a este puñado de Eclipsites yo mismo.",
  ui_story_1018_10180301_81_dialog_content = "No son Eclipsites... Son mis soldados...",
  ui_story_1018_10180301_82_dialog_content = "Simplemente somételos...",
  ui_story_1018_10180301_83_dialog_content = "...",
  ui_story_1018_10180301_84_dialog_content = "¿Cómo puede ser tan firme como Gran Mariscal y tan indeciso cuando se trata de sus hombres?",
  ui_story_1018_10180301_85_dialog_content = "Sometedlos... Tal vez aún haya esperanza para ellos...",
  ui_story_1018_10180301_86_dialog_content = "Wrath tiene razón, ¡puedo intentar salvarlos!",
  ui_story_1018_10180302_1_dialog_content = "Uf... Ya están bien ahora.",
  ui_story_1018_10180302_2_dialog_content = "Podemos entregarlos al equipo médico. Veo que PlayerName sabe cómo curar y coordinar en la batalla.",
  ui_story_1018_10180302_3_dialog_content = "Cuando Wrath estuvo en la misma situación antes, así fue como salió de ella.",
  ui_story_1018_10180302_4_dialog_content = "Están atrapados en su propia mente y no pueden controlarse a sí mismos.",
  ui_story_1018_10180302_5_dialog_content = "Pero lo siento por el soldado que devoró gran parte de esa armadura.",
  ui_story_1018_10180302_6_dialog_content = "Noche Blanca en lo alto... Leo intentó someterlo y creo que hizo todo lo posible.",
  ui_story_1018_10180302_7_dialog_content = "Ese soldado fue mutilado y solo el Darkflow lo sostenía...",
  ui_story_1018_10180302_8_dialog_content = "Creo que el Gran Mariscal debería mirar el panorama general y estar menos apegado a un... soldado así.",
  ui_story_1018_10180302_9_dialog_content = "Eso lo sé, no tienes que recordármelo...",
  ui_story_1018_10180302_10_dialog_content = "¿Planeas enviar a todos los soldados que encontramos al hospital?",
  ui_story_1018_10180302_11_dialog_content = "Varios cientos es un número considerable.",
  ui_story_1018_10180302_12_dialog_content = "De hecho, estos heridos que hemos rescatado no cabrán en la instalación...",
  ui_story_1018_10180302_13_dialog_content = "Pero, debido a su condición especial, deben ser tratados lo más pronto posible.",
  ui_story_1018_10180302_14_dialog_content = "Uno de mis soldados ya está manejando esto. Cuando regrese, trasladaré a los residentes a los pueblos más grandes.",
  ui_story_1018_10180302_15_dialog_content = "¿Con qué los vas a mover? ¿Carritos?",
  ui_story_1018_10180302_16_dialog_content = "Sí, los pocos carruajes que nos quedan, y tal vez algunos de ellos tengan que caminar...",
  ui_story_1018_10180302_17_dialog_content = "Caminar es prácticamente entregarlos a los Eclipsites como comida.",
  ui_story_1018_10180302_18_dialog_content = "Tengo una sugerencia... Aunque la decisión depende de PlayerName.",
  ui_story_1018_10180302_19_dialog_content = "En realidad, yo también tengo uno...",
  ui_story_1018_10180302_20_dialog_content = "Soroz.",
  ui_story_1018_10180302_21_dialog_content = "No será un problema evacuar a la gente de Crepúsculo lo más pronto posible, y Eraveil probablemente sea el lugar más seguro en este momento.",
  ui_story_1018_10180302_22_dialog_content = "Pero, ¿cuál es tu plan para los heridos que encontremos más tarde?",
  ui_story_1018_10180302_23_dialog_content = "Antes de que se disperse el atolladero... Encontraremos una solución. Los residentes indefensos son la máxima prioridad.",
  ui_story_1018_10180302_24_dialog_content = "Leo, déjame intentar la Fortaleza Lumo.",
  ui_story_1018_10180302_25_dialog_content = "Muchos miembros de la iglesia se ofrecieron como voluntarios para quedarse y brindar ayuda médica.",
  ui_story_1018_10180302_26_dialog_content = "Pediré la ayuda de la iglesia para aquellos que requieran atención inmediata. Con suerte, eso también facilitará el esfuerzo de rescate futuro del Gran Mariscal.",
  ui_story_1018_10180302_27_dialog_content = "Fortaleza Lumo... apenas estoy optimista al respecto.",
  ui_story_1018_10180302_28_dialog_content = "Pero debemos garantizar la seguridad de los refugiados ante todo, y nadie puede decir con certeza cuál es el mejor camino a seguir, así que no te detendré.",
  ui_story_1018_10180302_29_dialog_content = "Creo que sin importar los problemas entre facciones, la Iglesia de la Noche Blanca no rechazará a los Aurorianos.",
  ui_story_1018_10180302_30_dialog_content = "Sin embargo, ¿le importaría que los Soldados Illumina se refugien en la Iglesia de la Noche Blanca, Gran Mariscal Wrath?",
  ui_story_1018_10180302_31_dialog_content = "No me incluyas. Illumina nunca trata con religiones.",
  ui_story_1018_10180302_32_dialog_content = "Pero, dada la situación, agradecería si pudieras cuidar de mis soldados.",
  ui_story_1018_10180302_33_dialog_content = "¿Estás seguro de que no necesitas ayuda médica?",
  ui_story_1018_10180302_34_dialog_content = "Solo me siento cansado... Me sentí mejor después de hablar con ustedes.",
  ui_story_1018_10180302_35_dialog_content = "May ¿Me prestas tu caballo, Joselyne?",
  ui_story_1018_10180302_36_dialog_content = "¡Por supuesto! No se preocupe, Gran Mariscal, conseguiré ayuda para sus soldados.",
  ui_story_1018_10180302_37_dialog_content = "Espero que la guerra haya terminado la próxima vez que nos encontremos. Ahora me prepararé.",
  ui_story_1018_10180302_38_dialog_content = "Cuidarse.",
  ui_story_1018_10180302_39_dialog_content = "PlayerName, reúnete con mis soldados en la salida oeste más tarde.",
  ui_story_1018_10180302_40_dialog_content = "Cuando termine la crisis en Crepúsculo, te encontraré y nos encargaremos de establecer a los refugiados.",
  ui_story_1018_10180302_41_dialog_content = "Ejem, gracias por todo lo que has hecho. Estoy seguro de que nos volveremos a encontrar.",
  ui_story_1018_10180302_42_dialog_content = "¿Qué...? Nunca dije que me iba.",
  ui_story_1018_10180302_43_dialog_content = "Soroz llevará a los residentes a un lugar seguro en piloto automático.",
  ui_story_1018_10180302_44_dialog_content = "Dije que protegería Crepúsculo contigo. No me iré hasta que termine esta guerra.",
  ui_story_1018_10180302_45_dialog_content = "Eres mucho más tenaz de lo que imaginaba, PlayerName.",
  ui_story_1018_10180302_46_dialog_content = "Hemos estado luchando juntos tanto tiempo que ya esperaba esto de ti.",
  ui_story_1018_10180302_47_dialog_content = "PlayerName, aterricé en la entrada oeste de Crepúsculo. Estamos dentro del alcance de comunicación.",
  ui_story_1018_10180302_48_dialog_content = "Soroz, por favor lleva a la gente de Crepúsculo a la seguridad de nuestro hogar.",
  ui_story_1018_10180302_49_dialog_content = "Destino para establecerse: Eraveil",
  ui_story_1018_10180302_50_dialog_content = "PlayerName, asegúrate de mantenerte a salvo.",
  ui_story_1018_10180302_51_dialog_content = "Gracias, los dejaré a tu cuidado.",
  ui_story_1018_10180401_1_dialog_content = "<color=#e8d9bb>En un tren avanzando rápidamente hacia la Zona Oscura...</color>",
  ui_story_1018_10180401_2_dialog_content = "Uno, dos, tres... Hemos dado la vuelta cuatro veces. ¿Algún pedido, señor?",
  ui_story_1018_10180401_3_dialog_content = "Tómalo con calma, Merry, con el tiempo habrá una respuesta a ese misterio.",
  ui_story_1018_10180401_4_dialog_content = "¿Realmente confía el Sr. Charon en la dirección dada por Minch?",
  ui_story_1018_10180401_5_dialog_content = "Hemos trabajado juntos durante mucho tiempo, así que es obvio... Hablando de eso, ¿estás bien ahí, Minch?",
  ui_story_1018_10180401_6_dialog_content = "Tengo dolor de cabeza desde el principio. Probablemente sea el viento...",
  ui_story_1018_10180401_7_dialog_content = "¡No hay viento en el tren!",
  ui_story_1018_10180401_8_dialog_content = "Fuera de la ventana. Nos encontramos con ráfagas de viento a una velocidad muy inusual.",
  ui_story_1018_10180401_9_dialog_content = "Solo con las luces tenues, pude notar que el pueblo por el que acabamos de pasar tenía problemas. Quizás por eso él llega tarde.",
  ui_story_1018_10180401_10_dialog_content = "Entonces, esa mancha de oscuridad en realidad era un pueblo... Era como una garra de obsidiana que se extendía desde la Zona Oscura...",
  ui_story_1018_10180401_11_dialog_content = "Suspiro. Apenas tengo la oportunidad de viajar en un tren que sea cómodo y artístico, y esta es la vista que tengo...",
  ui_story_1018_10180401_12_dialog_content = "¿Realmente confías en esos tres, oficial Charon? Nos dijiste que descansáramos desde que nos fuimos.",
  ui_story_1018_10180401_13_dialog_content = "Esta es la tercera vez que me levanto, ¿entonces por qué aún no hemos llegado a la Zona Oscura?",
  ui_story_1018_10180401_14_dialog_content = "Estamos llevando a cabo la misión, Vice. No te preocupes, el Otro Extremo se asegurará de que estemos a salvo.",
  ui_story_1018_10180401_15_dialog_content = "Pero señor, no recuerdo que la distancia entre Illumina y la Zona Oscura fuera tan larga...",
  ui_story_1018_10180401_16_dialog_content = "La persona que me dio la misión también proporcionó dos pistas precisas, y este es el pasaje necesario para desentrañar el misterio.",
  ui_story_1018_10180401_17_dialog_content = "¿Pistas precisas? ¿Qué son?",
  ui_story_1018_10180401_18_dialog_content = "Uno incluía varias coordenadas fuera de las líneas de Illumina. Todos los lugares a los que hemos ido estaban en el mapa.",
  ui_story_1018_10180401_19_dialog_content = "Entonces, estoy seguro de que no pasamos por ningún lugar donde no deberíamos.",
  ui_story_1018_10180401_20_dialog_content = "Pero según las marcas, ¿no hemos estado dando vueltas aquí todo el tiempo?",
  ui_story_1018_10180401_21_dialog_content = "Shhh... No quieres asustar a nuestros invitados.",
  ui_story_1018_10180401_22_dialog_content = "¿Esos tres? Entonces, ¿tú también sentiste que algo anda mal?",
  ui_story_1018_10180401_23_dialog_content = "Llámalo una agenda secreta. Rodear también es parte de la misión.",
  ui_story_1018_10180401_24_dialog_content = "Un pajarito me dice que pronto tendremos la respuesta al misterio.",
  ui_story_1018_10180401_25_dialog_content = "¿Misterio otra vez?",
  ui_story_1018_10180401_26_dialog_content = "Entonces, ¿quién es el segundo protagonista?",
  ui_story_1018_10180401_27_dialog_content = "La segunda pista es llegar a una ubicación especialmente marcada y luego hacer una videoconferencia con el Equipo de Reconocimiento de la Zona Oscura.",
  ui_story_1018_10180401_28_dialog_content = "¿Eh? Pero no hemos recibido ninguna señal de posición de ellos desde hace mucho tiempo.",
  ui_story_1018_10180401_29_dialog_content = "¿El capitán apagó el comunicador? ¿O hay un inhibidor cerca de ellos?",
  ui_story_1018_10180401_30_dialog_content = "Señor, creo que necesitamos una actualización sobre la situación actual, ¡o no tendremos esperanza de completar la misión!",
  ui_story_1018_10180401_31_dialog_content = "Estoy muy preocupado por la situación actual de Illumina.",
  ui_story_1018_10180401_32_dialog_content = "Controla tus dudas por el momento y quizás pueda proporcionar respuestas.",
  ui_story_1018_10180401_33_dialog_content = "¿Estás escuchando la voz de una mujer, Oficial Charon?",
  ui_story_1018_10180401_34_dialog_content = "Acaba de pasar junto a mí.",
  ui_story_1018_10180401_35_dialog_content = "¡Dama Victoria!",
  ui_story_1018_10180401_36_dialog_content = "¡Está aquí, señora!",
  ui_story_1018_10180401_37_dialog_content = "¿Me recuerdas, Conductor de Illumina? Tal vez frente a extraños, no debería dirigirme a ti como pariente... o un familiar lejano.",
  ui_story_1018_10180401_38_dialog_content = "Ahorra tus palabras crípticas, Lady Victoria. ¿Qué planean hacer tú y tus tres subordinados?",
  ui_story_1018_10180401_39_dialog_content = "Lady Victoria...? ¿Entonces estos tres chicos son del Orden Verdadero?",
  ui_story_1018_10180401_40_dialog_content = "Espero que no hayan hecho desagradable su viaje, señorita Vice.",
  ui_story_1018_10180401_41_dialog_content = "Bueno, deberías preguntarle a Charon eso. ¿Hemos estado dando vueltas por tu culpa?",
  ui_story_1018_10180401_42_dialog_content = "No completamente. Pero mi presencia ahora legitima oficialmente este tren lleno de miembros de la Orden Verdadera.",
  ui_story_1018_10180401_43_dialog_content = "Señorita Vice, supongo que estás aquí porque te intriga el misterioso visitante de Illumina...",
  ui_story_1018_10180401_44_dialog_content = "Así como lo que sucedió en el pueblo de Crepúsculo por el que pasaste.",
  ui_story_1018_10180401_45_dialog_content = "¿Cómo sabes del tipo que se coló en Illumina? ¿Y pasó algo en Crepúsculo?",
  ui_story_1018_10180401_46_dialog_content = "Ves, ¡por eso este tren necesita mi iluminación!",
  ui_story_1018_10180401_47_dialog_content = "En cuanto a lo que pasó en Crepúsculo... Digamos que el Celestita y el nuevo Gran Mariscal aún no han descubierto los trucos para sobrevivir.",
  ui_story_1018_10180401_48_dialog_content = "¿PlayerName también fue a Crepúsculo?!",
  ui_story_1018_10180401_49_dialog_content = "Sabía sobre el Gran Mariscal, pero ¿tuvieron problemas en Twilight?",
  ui_story_1018_10180401_50_dialog_content = "Su situación en Crepúsculo depende de cómo los percibas. No te preocupes por lo desconocido antes de la revelación.",
  ui_story_1018_10180401_51_dialog_content = "¿Es cierto eso, Charon? PlayerName y el Gran Mariscal no están en peligro, ¿verdad?",
  ui_story_1018_10180401_52_dialog_content = "...",
  ui_story_1018_10180401_53_dialog_content = "Entonces, ¿te gustaría ir a ver el pantano por ti mismo?",
  ui_story_1018_10180401_54_dialog_content = "Aunque el tomo reveló que el destino de esta joven es... la Noche Eterna.",
  ui_story_1018_10180401_55_dialog_content = "Cayendo en la noche eterna tras olvidar al ser amado, pero aún nutrido por la lanza oscura para completar el sacrificio y la redención.",
  ui_story_1018_10180401_56_dialog_content = "Felicidades, señorita Vice, porque encontrarás la verdad en este viaje.",
  ui_story_1018_10180401_57_dialog_content = "¿De qué estás hablando...?",
  ui_story_1018_10180401_58_dialog_content = "¡Tonterías! Este viaje no se trata de destino, sino de soldados Illumina cumpliendo una misión.",
  ui_story_1018_10180401_59_dialog_content = "Por favor, no te interpongas en nuestro camino, Lady Victoria, o de lo contrario.",
  ui_story_1018_10180401_60_dialog_content = "Todo este tiempo has estado con mis miembros, ¿todavía no sientes que El Warp está en acción?",
  ui_story_1018_10180401_61_dialog_content = "El Warp... ¿No eres tú el responsable de que estemos dando vueltas sin parar?",
  ui_story_1018_10180401_62_dialog_content = "Veo que la marca ancestral en ti se ha desvanecido. Es hora de ciertas revelaciones.",
  ui_story_1018_10180401_63_dialog_content = "Debido a varias razones, Eclipse lo está utilizando para evitar que te acerques.",
  ui_story_1018_10180401_64_dialog_content = "Después de cierta distancia, vuelves al punto de inicio. Ese es el poder de The Warp.",
  ui_story_1018_10180401_65_dialog_content = "Y \"punto de partida\" se refiere al centro de un círculo, por lo que solo puedes moverte dentro de la línea del radio.",
  ui_story_1018_10180401_66_dialog_content = "¿Cómo se logra eso?",
  ui_story_1018_10180401_67_dialog_content = "No profundices en ello, Srta. Vice, ya que solo te volverá loca.",
  ui_story_1018_10180401_68_dialog_content = "Pero con mi guía, escaparemos de este aprieto. Ahora, ¿se negará el Conductor a darme paso considerando ese hecho?",
  ui_story_1018_10180401_69_dialog_content = "...",
  ui_story_1018_10180401_70_dialog_content = "Tomaré el silencio como permiso para abordar. Puedes aumentar la velocidad, conductor.",
  ui_story_1018_10180401_71_dialog_content = "Estoy confundido, señor. ¿Seguimos avanzando hacia la Noche Eterna?",
  ui_story_1018_10180401_72_dialog_content = "El tren se detendrá donde desee, señorita Vice.",
  ui_story_1018_10180401_73_dialog_content = "Depende de mí, ¿verdad...",
  ui_story_1018_10180401_74_dialog_content = "<color=#e8d9bb>*Silbato del tren*</color>",
  ui_story_1018_10180401_75_dialog_content = "¡Espera!",
  ui_story_1018_10180401_76_dialog_content = "¿Qué pasa con la repentina ráfaga? No será una señal de ataque enemigo, ¿verdad?",
  ui_story_1018_10180401_77_dialog_content = "Axelia debe proteger a los subordinados...",
  ui_story_1018_10180401_78_dialog_content = "Es extraño que el vendaval no cause ni una ondulación en el cenagal...",
  ui_story_1018_10180401_79_dialog_content = "Axelia, ¿viste algo inusual en tu esfuerzo de rescate aquí?",
  ui_story_1018_10180401_80_dialog_content = "Tal vez el enemigo central no fue derrotado y simplemente está al acecho...",
  ui_story_1018_10180401_81_dialog_content = "<color=#e8d9bb>Gorgoteo...</color>",
  ui_story_1018_10180401_82_dialog_content = "Capitán, el sector bajo mi cargo ha sido registrado. Estamos trasladando a los heridos al hospital.",
  ui_story_1018_10180401_83_dialog_content = "Entendido. La operación de rescate es mucho más fluida sin la interferencia de Eclipsite.",
  ui_story_1018_10180401_84_dialog_content = "<color=#e8d9bb>Gorgoteo...</color>",
  ui_story_1018_10180401_85_dialog_content = "Axelia está escuchando un ruido extraño...",
  ui_story_1018_10180401_86_dialog_content = "También lo escucho, es como algo saliendo del agua...",
  ui_story_1018_10180401_87_dialog_content = "Rugido...",
  ui_story_1018_10180401_88_dialog_content = "Eso es...",
  ui_story_1018_10180401_89_dialog_content = "Gran Mariscal! ¡Mira al soldado en la camilla!",
  ui_story_1018_10180401_90_dialog_content = "¡Imposible!",
  ui_story_1018_10180401_91_dialog_content = "El barro en ellos fluye como si estuviera vivo.",
  ui_story_1018_10180401_92_dialog_content = "Entonces ese ruido era...",
  ui_story_1018_10180401_93_dialog_content = "¡Ah—! ¡Ayuda!",
  ui_story_1018_10180401_94_dialog_content = "¡Todos, aléjense de la camilla y reúnanse a mi alrededor!",
  ui_story_1018_10180401_95_dialog_content = "Claramente, no hubo ningún problema cuando fueron rescatados...",
  ui_story_1018_10180401_96_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_1018_10180401_97_dialog_content = "Rugido...",
  ui_story_1018_10180401_98_dialog_content = "¡Espera, es el viento otra vez! ¡Esto podría ser una emboscada!",
  ui_story_1018_10180401_99_dialog_content = "¡Ponte detrás de cualquier barrera que encuentres!",
  ui_story_1018_10180401_100_dialog_content = "Estoy a punto de quedar impresionado...",
  ui_story_1018_10180401_101_dialog_content = "Aférrate a mí, PlayerName!",
  ui_story_1018_10180401_102_dialog_content = "No puedo abrir los ojos... ¿Es este un nuevo enemigo?",
  ui_story_1018_10180401_103_dialog_content = "<color=#e8d9bb>¡Chapoteo!</color>",
  ui_story_1018_10180401_104_dialog_content = "¡Cuidado, el barro está salpicando hacia aquí!",
  ui_story_1018_10180401_105_dialog_content = "¡Detrás de ti, Gran Mariscal Wrath!",
  ui_story_1018_10180401_106_dialog_content = "Lo veo... No es solo el barro, ¡hay algo en él!",
  ui_story_1018_10180401_107_dialog_content = "¡Grahhhh!",
  ui_story_1018_10180401_108_dialog_content = "¡Muchos Eclipsites en el pantano!",
  ui_story_1018_10180401_109_dialog_content = "De hecho, el charco está liderando a los Eclipsites, con los soldados bajo la influencia del Darkflow ayudando...",
  ui_story_1018_10180401_110_dialog_content = "¡Gah!",
  ui_story_1018_10180401_111_dialog_content = "¡Ah—! ¡Ayuda!",
  ui_story_1018_10180401_112_dialog_content = "Se han vuelto locos, Gran Mariscal Wrath. ¡Debo tratarlos como a los Eclipsites!",
  ui_story_1018_10180401_113_dialog_content = "No eso no es...",
  ui_story_1018_10180401_114_dialog_content = "¡Tenemos Eclipsites detrás de nosotros! El lodo nos ahogará a todos si no tomamos medidas.",
  ui_story_1018_10180401_115_dialog_content = "Leo...",
  ui_story_1018_10180401_116_dialog_content = "<color=#e8d9bb>*Silbato del tren en la ráfaga*</color>",
  ui_story_1018_10180401_117_dialog_content = "¡Oh no, otro más!",
  ui_story_1018_10180401_118_dialog_content = "Escucho silbidos de tren...",
  ui_story_1018_10180401_119_dialog_content = "¡Señor! El mapa muestra que esto es... ¿Crepúsculo?",
  ui_story_1018_10180401_120_dialog_content = "¿Lo hizo The Warp, Lady Victoria? ¿Por qué estamos aquí?",
  ui_story_1018_10180401_121_dialog_content = "Hemos escapado de El Warp y guié el tren aquí según el deseo de la señorita Vice.",
  ui_story_1018_10180401_122_dialog_content = "Crepúsculo resulta estar al final de la línea de radio.",
  ui_story_1018_10180401_123_dialog_content = "No puedo creerlo...",
  ui_story_1018_10180401_124_dialog_content = "Señor, veo a muchas personas allá. ¿Puede ser PlayerName y otros?",
  ui_story_1018_10180401_125_dialog_content = "Hay mucho barro debajo del tren. Ten cuidado con los Eclipsites que puedan estar en él.",
  ui_story_1018_10180401_126_dialog_content = "Suciedad, asquerosos Eclipsites! ¡El Otro Extremo los aplastará!",
  ui_story_1018_10180401_127_dialog_content = "Agárrate fuerte, todos. ¡Vamos a pasar por el barro para una parada adelante!",
  ui_story_1018_10180401_128_dialog_content = "<color=#e8d9bb>*Silbato del tren*</color>",
  ui_story_1018_10180401_129_dialog_content = "Hola, Gran Mariscal Wrath—",
  ui_story_1018_10180401_130_dialog_content = "¡Felicidades por tu cita! ¡Lo siento, llego tarde!",
  ui_story_1018_10180401_131_dialog_content = "Gran Mariscal Wrath! PlayerName!",
  ui_story_1018_10180401_132_dialog_content = "¡Vice!",
  ui_story_1018_10180401_133_dialog_content = "Charon, Vice... ¿Qué hacen aquí?",
  ui_story_1018_10180401_134_dialog_content = "¿No estás en una misión? ¿Por qué estás en Crepúsculo?",
  ui_story_1018_10180401_135_dialog_content = "Tenga en cuenta el tiempo, conductor. Esta es solo una parada temporal.",
  ui_story_1018_10180401_136_dialog_content = "Escuché sobre la batalla en Crepúsculo y me preocupé, Gran Mariscal. Sin embargo, no puedo quedarme mucho tiempo antes de tener que retomar mi misión.",
  ui_story_1018_10180401_137_dialog_content = "Ya atropellaste a los Eclipsites, así que eso ya es de gran ayuda.",
  ui_story_1018_10180401_138_dialog_content = "Por otro lado, ¿creaste tú el vendaval y no el enemigo?",
  ui_story_1018_10180401_139_dialog_content = "No llegamos aquí por casualidad, pero no tengo tiempo para explicarlo. El lodo se extiende muy lejos, probablemente con muchos más Eclipsites también.",
  ui_story_1018_10180401_140_dialog_content = "¿Significa el viento que El Warp se activará de nuevo, mi señora...?",
  ui_story_1018_10180401_141_dialog_content = "¿No es inquieto? Siéntate un rato, llevaré a todos conmigo.",
  ui_story_1018_10180401_142_dialog_content = "Juzgando por la distancia, en 20 segundos.",
  ui_story_1018_10180401_143_dialog_content = "Contemos hacia atrás, mi señora...",
  ui_story_1018_10180401_144_dialog_content = "¿Te encontraste con problemas en el camino, Vice?",
  ui_story_1018_10180401_145_dialog_content = "Comparado con ustedes en Crepúsculo, lo que pasé no fue nada.",
  ui_story_1018_10180401_146_dialog_content = "Excepto el galimatías críptico de Lady Victoria... que simplemente no entiendo.",
  ui_story_1018_10180401_147_dialog_content = "De todos modos, cuídate. La aparición de True Order nunca es auspiciosa.",
  ui_story_1018_10180401_148_dialog_content = "¿Cuándo empezaste a regañar también?",
  ui_story_1018_10180401_149_dialog_content = "De hecho, creo que la Dama Victoria nos está ayudando.",
  ui_story_1018_10180401_150_dialog_content = "Si esa también es la intención de Charon...",
  ui_story_1018_10180401_151_dialog_content = "15, 14, 13...",
  ui_story_1018_10180401_152_dialog_content = "10, 9...",
  ui_story_1018_10180401_153_dialog_content = "Por lo tanto, por favor continúa adelante, Gran Mariscal. ¡Todos en Illumina esperan ansiosamente tu regreso seguro!",
  ui_story_1018_10180401_154_dialog_content = "Claro, y tú también. May que completes la misión de manera segura.",
  ui_story_1018_10180401_155_dialog_content = "5, 4, 3...",
  ui_story_1018_10180401_156_dialog_content = "¿Recuerdas lo que te dije?",
  ui_story_1018_10180401_157_dialog_content = "Dijiste que solo llamara tu nombre si estoy en peligro. ¡Lo recuerdo!",
  ui_story_1018_10180401_158_dialog_content = "2, 1, 0.",
  ui_story_1018_10180401_159_dialog_content = "Bueno, entonces, adiós a todos.",
  ui_story_1018_10180401_160_dialog_content = "<color=#e8d9bb>Retumbar-</color>",
  ui_story_1018_10180401_161_dialog_content = "Simplemente desaparecieron...",
  ui_story_1018_10180401_162_dialog_content = "Increíble. Eso ha superado mi entendimiento de Luminatics.",
  ui_story_1018_10180401_163_dialog_content = "¡Gah!",
  ui_story_1018_10180401_164_dialog_content = "¡Gran Mariscal! Los Caballeros Lumo ya no pueden contener a esos soldados...",
  ui_story_1018_10180401_165_dialog_content = "¿Realmente nos hemos quedado sin opciones...?",
  ui_story_1018_10180401_166_dialog_content = "Capitán, nuestros hermanos se preguntan, ¿quiénes son exactamente nuestros enemigos?",
  ui_story_1018_10180401_167_dialog_content = "Los exsoldados del Gran Mariscal convertidos en Eclipsites son brutalmente despiadados...",
  ui_story_1018_10180401_168_dialog_content = "No voy a retroceder, incluso si ella intenta detenerme esta vez.",
  ui_story_1018_10180401_169_dialog_content = "¡Quien dañe a mis soldados será enfrentado por mí!",
  ui_story_1018_10180401_170_dialog_content = "¡Síganme, caballeros, y acaben con todos!",
  ui_story_1018_10180401_171_dialog_content = "¡Sí señor!",
  ui_story_1018_10180401_X171_dialog_content = "¿Qué pasa con esta repentina ráfaga de viento? No estamos bajo ataque, ¿verdad...?",
  ui_story_1018_10180401_X172_dialog_content = "Los Eclipsites están aumentando en número, pero la misión de búsqueda y rescate sigue en marcha. ¿Se han encontrado resultados anormales hasta ahora?",
  ui_story_1018_10180401_X173_dialog_content = "¡Informando, Gran Mariscal! ¡Las operaciones de búsqueda y rescate en mi área designada no se han visto afectadas hasta ahora!",
  ui_story_1018_10180401_X174_dialog_content = "Informando, Gran Mariscal. Apareció un gran número de Eclipsites en mi área. Los he eliminado a todos.",
  ui_story_1018_10180401_X175_dialog_content = "Gran Mariscal, parece que el Capitán Leo ha encontrado algunas dificultades en el Pantano.",
  ui_story_1018_10180401_X176_dialog_content = "Entendido, voy para allá. El resto de ustedes, manténganse alerta.",
  ui_story_1018_10180401_X177_dialog_content = "Todos los heridos han sido cargados en camillas, Capitán. Los llevaré a la enfermería en breve.",
  ui_story_1018_10180401_X178_dialog_content = "Bien. Cada vez aparecen más Eclipsites en el Pantano, debemos retirarnos antes de que lancen su próximo ataque.",
  ui_story_1018_10180401_X179_dialog_content = "¡Sí, Capitán!",
  ui_story_1018_10180401_X180_dialog_content = "Escuché un ruido extraño hace un momento... Venía de uno de los soldados.",
  ui_story_1018_10180401_X181_dialog_content = "No te acerques demasiado a ellos, Axelia. Estos soldados fueron sacados del Pantano antes.",
  ui_story_1018_10180401_X182_dialog_content = "El lodo que cubre sus cuerpos fluye como si estuviera vivo...",
  ui_story_1018_10180401_X183_dialog_content = "Actualmente no tenemos una manera de limpiarlo de sus cuerpos...",
  ui_story_1018_10180401_X184_dialog_content = "Rugido...",
  ui_story_1018_10180401_X185_dialog_content = "Rugido...",
  ui_story_1018_10180401_X186_dialog_content = "¡Los heridos no pueden resistir mucho más, Gran Mariscal!",
  ui_story_1018_10180401_X187_dialog_content = "El barro en sus cuerpos... ¿Está empezando a moverse más rápido?",
  ui_story_1018_10180401_X188_dialog_content = "¿Es así? Entonces eso solo puede significar una cosa...",
  ui_story_1018_10180401_X189_dialog_content = "¡Atrás, todos! ¡El lodo está a punto de salpicar!",
  ui_story_1018_10180401_X190_dialog_content = "No es solo barro... ¡Hay algo más en él!",
  ui_story_1018_10180401_X191_dialog_content = "¡Gahhhh!",
  ui_story_1018_10180401_X192_dialog_content = "Como sospechaba, el lodo está guiando a los Eclipsites hacia nosotros. El Darkflow también está empezando a afectar a estos soldados...",
  ui_story_1018_10180401_X193_dialog_content = "... Necesito un equipo de caballeros para proteger a los heridos. El resto de ustedes, ¡prepárense para la batalla!",
  ui_story_1018_10180401_X194_dialog_content = "¡Sí señor!",
  ui_story_1018_10180401_X195_dialog_content = "<color=#e8d9bb>Jaa... Jaa...</color>",
  ui_story_1018_10180401_X196_dialog_content = "Más de ellos... ¡Y están atacando desde la retaguardia!",
  ui_story_1018_10180401_X197_dialog_content = "Apenas puedo mantenerme de pie—",
  ui_story_1018_10180401_X198_dialog_content = "¡Ponte detrás de cualquier barrera que encuentres!",
  ui_story_1018_10180401_X199_dialog_content = "Mis ojos... No puedo mantenerlos abiertos. ¿Es eso... un enemigo nuevo?",
  ui_story_1018_10180401_X200_dialog_content = "Aférrate a mí, PlayerName!",
  ui_story_1018_10180401_X201_dialog_content = "<color=#e8d9bb>Psssh— ¡Woo-woooo!</color>",
  ui_story_1018_10180401_X202_dialog_content = "PlayerName, ¿Estás bien?",
  ui_story_1018_10180401_X203_dialog_content = "Creo... creo que escucho silbatos de tren...",
  ui_story_1018_10180401_X204_dialog_content = "¿Estoy viendo cosas? Esa cara sucia allá... PlayerName?!",
  ui_story_1018_10180401_X205_dialog_content = "¿C-Cómo ya estamos en Crepúsculo?! Esto es increíble...",
  ui_story_1018_10180401_X206_dialog_content = "La urdimbre es bastante interesante, ¿no es así? Pero lo que es aún más interesante es que el deseo de tu corazón nos llevó aquí, Señorita Vice.",
  ui_story_1018_10180401_X207_dialog_content = "Realmente, toda una hazaña...",
  ui_story_1018_10180401_X208_dialog_content = "Todavía no entiendo del todo, pero ¿podemos detenernos más adelante? Parece que PlayerName y los demás están en grave peligro...",
  ui_story_1018_10180401_X209_dialog_content = "El pantano y los Eclipsites están comenzando a rodearlos por todas partes...",
  ui_story_1018_10180401_X210_dialog_content = "Lamentablemente, señorita Vice, este no es nuestro destino final. No hay freno una vez que entramos en el Warp.",
  ui_story_1018_10180401_X211_dialog_content = "Pero nos estamos acercando cada vez más a ellos... ¿No hay algo que podamos hacer para ayudar?",
  ui_story_1018_10180401_X212_dialog_content = "Quizás no podamos detener...",
  ui_story_1018_10180401_X213_dialog_content = "Pero el Other End está más que preparado para acabar con estos sucios y cubiertos de lodo Eclipsites. ¡Aférrense bien, todos!",
  ui_story_1018_10180401_X214_dialog_content = "<color=#e8d9bb>Choque—</color>",
  ui_story_1018_10180401_X215_dialog_content = "Graah—",
  ui_story_1018_10180401_X216_dialog_content = "C-Capitán! ¿Fue eso... fue eso un tren justo ahora?! ¡Parece que atropelló a todos los Eclipsites cercanos!",
  ui_story_1018_10180401_X217_dialog_content = "Parecía ser de diseño Illumina... ¡Pero no importa eso ahora! ¡Necesitamos atender a los heridos!",
  ui_story_1018_10180401_X218_dialog_content = "¡Sí señor!",
  ui_story_1018_10180401_X219_dialog_content = "No hay duda... Ese era el tren de Charon justo ahora. Creo que incluso vi a Vice en él también...",
  ui_story_1018_10180401_X220_dialog_content = "Pero, ¿por qué aparecerían de repente aquí, solo para desaparecer justo después?",
  ui_story_1018_10180401_X221_dialog_content = "No estoy seguro... Vice y Charon se fueron a la misión en la Zona Oscura antes de que llegara a Crepúsculo.",
  ui_story_1018_10180401_X222_dialog_content = "Aparecieron inesperadamente, eliminaron a los Eclipsites por nosotros y desaparecieron. Eso es algo inusual.",
  ui_story_1018_10180401_X223_dialog_content = "¡Informando, Gran Mariscal! ¡Hemos descubierto otro equipo perdido en la zona!",
  ui_story_1018_10180401_X224_dialog_content = "Entendido. Ahora voy.",
  ui_story_1018_10180401_X225_dialog_content = "PlayerName, es muy probable que su misión esté más allá de nuestro entendimiento, pero debemos confiar en que ellos la manejarán por sí mismos.",
  ui_story_1018_10180401_X226_dialog_content = "En este momento, tenemos nuestros propios problemas que enfrentar.",
  ui_story_1018_10180401_X227_dialog_content = "Lo sé. Solo espero que todo les salga bien.",
  ui_story_1018_10180401_X228_dialog_content = "(Por favor ten cuidado, Vice.)",
  ui_story_1018_10180501_1_dialog_content = "<color=#e8d9bb>El tren flota en un espacio desconocido...</color>",
  ui_story_1018_10180501_2_dialog_content = "Quítate las mangas, Minch, ¡me has estado asfixiando en el camino!",
  ui_story_1018_10180501_3_dialog_content = "¡Oye, mira, la campana está brillando! ¿Eso significa que tuvimos éxito?",
  ui_story_1018_10180501_4_dialog_content = "De hecho, la sensación de una sustancia espesa golpeando mis párpados es inconfundible.",
  ui_story_1018_10180501_5_dialog_content = "¿Dónde estamos, Dama Victoria...?",
  ui_story_1018_10180501_6_dialog_content = "Sin luz ni oscuridad, solo La Verdad. Este es mi santuario secreto.",
  ui_story_1018_10180501_7_dialog_content = "¡Oh, Dios mío! Me arrodillaré para que mi maestro predique el evangelio.",
  ui_story_1018_10180501_8_dialog_content = "Este es el dolor sordo de la Palabra de la Verdad que recuerdo. ¡Escucharé con total atención!",
  ui_story_1018_10180501_9_dialog_content = "¿Alguien se molesta en hablar en lenguaje claro? ¿Qué es este lugar?",
  ui_story_1018_10180501_10_dialog_content = "No te preocupes, Srta. Vice. Hemos huido de The Warp.",
  ui_story_1018_10180501_11_dialog_content = "Entonces, ¿nos salvaste?",
  ui_story_1018_10180501_12_dialog_content = "El punto es que seguiste mi guía—",
  ui_story_1018_10180501_13_dialog_content = "Mi sra., ¡\"veo\" sangre!",
  ui_story_1018_10180501_14_dialog_content = "¡\"Escucho\" palabras vívidas y el dolor me atraviesa los oídos!",
  ui_story_1018_10180501_15_dialog_content = "No esperaba que El Tomo Negro diera la revelación ahora...",
  ui_story_1018_10180501_16_dialog_content = "Las letras cambian tan rápido...",
  ui_story_1018_10180501_17_dialog_content = "\"Después de la operación, se encontrará el fracaso.\"",
  ui_story_1018_10180501_18_dialog_content = "¿Es esto a lo que llaman \"El Eclipse expandirá su cola, y cuando llegue la Aurora, Él comenzará el viaje de regreso\"?",
  ui_story_1018_10180501_19_dialog_content = "No, sigue cambiando...",
  ui_story_1018_10180501_20_dialog_content = "\"Tras los contratiempos, surgirá un esfuerzo magnífico.\"",
  ui_story_1018_10180501_21_dialog_content = "Esto se relaciona con \"En el momento de la catástrofe, los Aurorianos se encontrarán con Él, pero obstaculizados por Aurora.\"",
  ui_story_1018_10180501_22_dialog_content = "La Revelación no está clara...",
  ui_story_1018_10180501_23_dialog_content = "Mi lady, un odio intenso arde en los ojos del Señor...",
  ui_story_1018_10180501_24_dialog_content = "Cierra tus ojos, Dysis! Ese no es el Señor, ¡porque Él no odia!",
  ui_story_1018_10180501_25_dialog_content = "Sostengan la respiración, todos.",
  ui_story_1018_10180501_26_dialog_content = "...",
  ui_story_1018_10180501_27_dialog_content = "Señor, hay una señal débil que llega al tablero.",
  ui_story_1018_10180501_28_dialog_content = "Es una coordenada del Equipo de Expedición de la Zona Oscura, y la ubicación no está en el mapa.",
  ui_story_1018_10180501_29_dialog_content = "Porque no es un <color=#FFB400>lugar real</color>, sino el \"Todos se van de casa, pero el viaje de regreso es el comienzo\" en la revelación.",
  ui_story_1018_10180501_30_dialog_content = "¿Qué significa eso? ¿Podemos encontrarlos?",
  ui_story_1018_10180501_31_dialog_content = "Creo que es hora de que la Luz y la Oscuridad resuelvan su guerra, y el Señor de la Verdad vendrá.",
  ui_story_1018_10180501_32_dialog_content = "Para ser testigo del momento, te llevaré al destino.",
  ui_story_1018_10180501_33_dialog_content = "Sin embargo, necesito tu ayuda, Conductor.",
  ui_story_1018_10180501_34_dialog_content = "...",
  ui_story_1018_10180501_35_dialog_content = "Me siento muy incómodo en este momento, oficial Charon...",
  ui_story_1018_10180501_36_dialog_content = "El santuario secreto de Lady Victoria parece estar comprimiéndose... Tengo problemas para respirar...",
  ui_story_1018_10180501_37_dialog_content = "Yo también...",
  ui_story_1018_10180501_38_dialog_content = "Lo encontré después de todo, ya veo...",
  ui_story_1018_10180501_39_dialog_content = "¿Qué hace Anemone dejándote atrás todo este tiempo?",
  ui_story_1018_10180501_40_dialog_content = "¿Quién habla...?",
  ui_story_1018_10180501_41_dialog_content = "Te odio, pero no puedo recordar por qué...",
  ui_story_1018_10180501_42_dialog_content = "¡Deja a mi gente en paz, inmundicia!",
  ui_story_1018_10180501_43_dialog_content = "No me interesas. Pero la mujer rubia, me gusta el objeto en tu mano.",
  ui_story_1018_10180501_44_dialog_content = "La Verdad te sacudirá hasta lo más profundo, siervo del mal.",
  ui_story_1018_10180501_45_dialog_content = "Creo que ustedes deberían ser los que tiemblan. ¿Qué están haciendo con los ojos cerrados?",
  ui_story_1018_10180501_46_dialog_content = "Ofreciendo sangre para protección del Señor de la Verdad.",
  ui_story_1018_10180501_47_dialog_content = "Oh, estás realizando un ritual.",
  ui_story_1018_10180501_48_dialog_content = "Soy tu oponente, canalla temeroso de mostrar su rostro! ¡Toma este Fuego Infernal!",
  ui_story_1018_10180501_49_dialog_content = "El discípulo Dysis ha hecho la ofrenda.",
  ui_story_1018_10180501_50_dialog_content = "Con la ofrenda del dolor, el Señor te hablará el evangelio.",
  ui_story_1018_10180501_51_dialog_content = "El discípulo Merry ha hecho la ofrenda.",
  ui_story_1018_10180501_52_dialog_content = "Déjame hacerlo, es más eficiente.",
  ui_story_1018_10180501_53_dialog_content = "¡Sea testigo del milagro!",
  ui_story_1018_10180501_54_dialog_content = "¡El ritual estará completo pronto, Conductor!",
  ui_story_1018_10180501_55_dialog_content = "¿Estás bien, oficial Charon?",
  ui_story_1018_10180501_56_dialog_content = "¡Mantente firme, el Barquero de Acheron está pasando! ¡Girando el tren hacia abajo!",
  ui_story_1018_10180501_57_dialog_content = "¿Mis pies están fuera del suelo?",
  ui_story_1018_10180501_58_dialog_content = "Con la ofrenda de una mascota, el Señor revelará el misterio.",
  ui_story_1018_10180501_59_dialog_content = "El discípulo Minch ha hecho la ofrenda.",
  ui_story_1018_10180501_60_dialog_content = "¿Estás corriendo?",
  ui_story_1018_10180501_61_dialog_content = "May que el Señor acepte las ofrendas, tome el poder de mi sangre y muestre la verdad carmesí al mundo!",
  ui_story_1018_10180501_62_dialog_content = "Un milagro se ha manifestado... ¡El Reino de los Wraiths ha sido vulnerado!",
  ui_story_1018_10180501_63_dialog_content = "¡Esperen, todos...!",
  ui_story_1018_10180501_64_dialog_content = "No, no puedo, estoy cayendo demasiado rápido...",
  ui_story_1018_10180501_65_dialog_content = "En el camino hacia la Zona Oscura, pasaremos por el <color=#FFB400>Río Styx</color>, también conocido como el <color=#FFB400>Páramo Olvidado</color>.",
  ui_story_1018_10180501_66_dialog_content = "Por favor, mantén los ojos cerrados antes de ver la luz para evitar ser detectado por elementos peligrosos.",
  ui_story_1018_10180501_67_dialog_content = "Pero veo multitudes de Eclipsites acercándose a mí cuando cierro los ojos...",
  ui_story_1018_10180501_68_dialog_content = "Están únicamente en tu mente, no son reales.",
  ui_story_1018_10180501_69_dialog_content = "Pero son soldados de Illumina...",
  ui_story_1018_10180501_70_dialog_content = "Los veo alimentándose de mechas...",
  ui_story_1018_10180501_71_dialog_content = "Se están matando entre sí...",
  ui_story_1018_10180501_72_dialog_content = "También veo un pantano negro que se extiende desde la Zona Oscura hasta el frente de batalla de Illumina...",
  ui_story_1018_10180501_73_dialog_content = "(Vete, no te acerques.)",
  ui_story_1018_10180501_74_dialog_content = "(Eres tú... ¿Quién eres?)",
  ui_story_1018_10180501_75_dialog_content = "(Vete, no te acerques.)",
  ui_story_1018_10180501_76_dialog_content = "(Pero siento una fuerza desconocida impulsándome hacia adelante...)",
  ui_story_1018_10180501_77_dialog_content = "¿Vice?",
  ui_story_1018_10180501_78_dialog_content = "Hay una voz que nos dice que nos vayamos...",
  ui_story_1018_10180501_79_dialog_content = "No escuches ni mires fijamente, o puede que nunca vuelvas a despertar.",
  ui_story_1018_10180501_80_dialog_content = "No puedo verla claramente, pero puedo escuchar su voz y latidos del corazón. Es tan real...",
  ui_story_1018_10180501_81_dialog_content = "Como si fuera ella...",
  ui_story_1018_10180501_82_dialog_content = "Esa es precisamente la señal de que el peligro está a la vuelta de la esquina.",
  ui_story_1018_10180501_83_dialog_content = "(PlayerName dijo que llamara si estoy en peligro.)",
  ui_story_1018_10180501_84_dialog_content = "(Debería llegar, ¿verdad...)",
  ui_story_1018_10180501_85_dialog_content = "(Salir, peligro.)",
  ui_story_1018_10180501_86_dialog_content = "(Pero sin importar qué, te voy a ver...)",
  ui_story_1018_10180501_87_dialog_content = "(Porque la primera vez que sentí que alguien podía estar tan cerca de mí...)",
  ui_story_1018_10180501_88_dialog_content = "(...)",
  ui_story_1018_10180501_89_dialog_content = "(¿Qué es esto...?)",
  ui_story_1018_10180501_90_dialog_content = "(El latido del corazón de Vice...)",
  ui_story_1018_10180501_91_dialog_content = "(Ella está en peligro...)",
  ui_story_1018_10180501_92_dialog_content = "PlayerName, ¡cuidado detrás de ti!",
  ui_story_1018_10180601_1_dialog_content = "Rugido...",
  ui_story_1018_10180601_2_dialog_content = "Gran Mariscal, por favor dé la orden... Mi arma está apuntando a su cabeza...",
  ui_story_1018_10180601_X2_dialog_content = "¡Guarda tu arma!",
  ui_story_1018_10180601_X3_dialog_content = "Pero... Pero él ha matado a tantos de nuestros compañeros soldados! Incluso te atacó a ti, su oficial al mando. No merece ser un soldado de Illumina, y mucho menos el líder del Noveno Escuadrón.",
  ui_story_1018_10180601_X4_dialog_content = "No fue su culpa. Algo en sus ojos me dice que él sigue ahí.",
  ui_story_1018_10180601_X5_dialog_content = "Gran Mariscal! Los caballeros ya no pueden contener a esos soldados... A este ritmo, todos estaremos en grave peligro muy pronto...",
  ui_story_1018_10180601_3_dialog_content = "Aunque pueda tener el mando del Noveno Escuadrón, sus manos están manchadas con la sangre de nuestros hermanos. ¡No merece ser tratado como un soldado Illumina!",
  ui_story_1018_10180601_4_dialog_content = "¡Sus ojos me dicen que todavía hay una persona allí adentro!",
  ui_story_1018_10180601_5_dialog_content = "Echa un buen vistazo, soy tu Gran Mariscal. ¡Ahora quita tus manos de encima!",
  ui_story_1018_10180601_6_dialog_content = "... Gran Mariscal...",
  ui_story_1018_10180601_7_dialog_content = "En realidad puede escucharnos...",
  ui_story_1018_10180601_8_dialog_content = "Te llevaré de vuelta a Illumina. No vas a morir aquí.",
  ui_story_1018_10180601_9_dialog_content = "...",
  ui_story_1018_10180601_10_dialog_content = "Su cuerpo está controlado por el Darkflow. Tarde o temprano te romperá el cuello si esperas.",
  ui_story_1018_10180601_11_dialog_content = "Rugido...",
  ui_story_1018_10180601_12_dialog_content = "(El poder dentro de mí... Parece que ha sido despertado...)",
  ui_story_1018_10180601_13_dialog_content = "(Tengo el impulso de matarlo...)",
  ui_story_1018_10180601_14_dialog_content = "Wrath, él está mentalmente perdido como tú estabas, así que no te precipites...",
  ui_story_1018_10180601_15_dialog_content = "¿Tal vez debería intentarlo con mi habilidad psíquica?",
  ui_story_1018_10180601_16_dialog_content = "No sabemos en qué estado está, así que podrías lastimarte.",
  ui_story_1018_10180601_17_dialog_content = "Pero probablemente es la única oportunidad que tenemos...",
  ui_story_1018_10180601_18_dialog_content = "Si algo empieza a salir mal, pararé de inmediato, lo prometo.",
  ui_story_1018_10180601_19_dialog_content = "Si él te hace daño, no dudaré...",
  ui_story_1018_10180601_20_dialog_content = "Bien...",
  ui_story_1018_10180601_21_option_content = "Prueba el enlace mental",
  ui_story_1018_10180601_22_dialog_content = "(Estoy en... Esto es... la Subciudad de Illumina...)",
  ui_story_1018_10180601_23_dialog_content = "(Esto debe ser la zona de vivienda. Incluso puedo oler los detergentes.)",
  ui_story_1018_10180601_24_dialog_content = "Pero mamá, ¡esta es una oportunidad única en la vida!",
  ui_story_1018_10180601_25_dialog_content = "(¿Discutiendo con mamá?)",
  ui_story_1018_10180601_26_dialog_content = "Innumerables desafíos hacia sus objetivos hicieron que la Comandante Wrath llegara a donde está hoy en día.",
  ui_story_1018_10180601_27_dialog_content = "Si no aprovecho este programa de entrenamiento para soldados, ¡mi sueño de convertirme en Gran Mariscal nunca se hará realidad!",
  ui_story_1018_10180601_28_dialog_content = "La Comandante Wrath cree en mis habilidades y dijo que tengo lo necesario para desempeñar roles de mayor rango!",
  ui_story_1018_10180601_29_dialog_content = "Para surgir como líder... Para salir victorioso en batalla, una tras otra... Tal como lo que tu padre persiguió, y ahora, eres tú...",
  ui_story_1018_10180601_30_dialog_content = "Realmente has heredado la valentía e inteligencia de tu padre. En mis ojos, siempre eres el mejor...",
  ui_story_1018_10180601_31_dialog_content = "Pero cariño... He escuchado que el programa de entrenamiento puede ser extremadamente exigente...",
  ui_story_1018_10180601_32_dialog_content = "Si no logras superar ese entrenamiento, es posible que nunca puedas volver al campo de batalla otra vez...",
  ui_story_1018_10180601_33_dialog_content = "¿Te quedarás conmigo? Ustedes dos son todo lo que tengo ahora...",
  ui_story_1018_10180601_34_dialog_content = "Mamá... Tengo fe en mi hermano...",
  ui_story_1018_10180601_35_dialog_content = "Sí, mamá. ¡Por favor, ten fe en mí también! Voy a aguantar, ¡sin duda!",
  ui_story_1018_10180601_36_dialog_content = "No hay futuro para mí si sigo quedándome en Gannon City. ¡Ir al campo de batalla y aceptar la muerte como parte inevitable, eso es lo que hacen los verdaderos soldados!",
  ui_story_1018_10180601_37_dialog_content = "Ay... Por favor, no digas cosas así de nuevo.",
  ui_story_1018_10180601_38_dialog_content = "De todos modos, ¡ya he tomado mi decisión!",
  ui_story_1018_10180601_39_dialog_content = "(...)",
  ui_story_1018_10180601_40_dialog_content = "(¿Qué pensaría su madre si supiera lo que le está pasando en la batalla?)",
  ui_story_1018_10180601_41_dialog_content = "(¡Vaya, perdí la noción escuchándolos!)",
  ui_story_1018_10180601_42_dialog_content = "(Hmm, este es un lugar nuevo y la luz es cegadora...)",
  ui_story_1018_10180601_43_dialog_content = "Comandante, ¿es esta la prueba final del Programa Phospherus?",
  ui_story_1018_10180601_44_dialog_content = "Correcto, este es el último paso.",
  ui_story_1018_10180601_45_dialog_content = "Sin restricciones ahora. Tu único objetivo es derrotar al siguiente oponente y vivir.",
  ui_story_1018_10180601_46_dialog_content = "(¡Oye, sal de aquí ahora!)",
  ui_story_1018_10180601_47_dialog_content = "(Mamá, ¿qué haces aquí? Ya tomé mi decisión, así que por favor no me detengas...)",
  ui_story_1018_10180601_48_dialog_content = "(Él me tomó como su madre. En ese caso...)",
  ui_story_1018_10180601_49_dialog_content = "(No le escuches. Unirte al proyecto te convertirá en un Eclipsite. ¡No quiero verte así!)",
  ui_story_1018_10180601_50_dialog_content = "(No, mamá... El comandante piensa que soy realmente talentoso y debo pasar la prueba.)",
  ui_story_1018_10180601_51_dialog_content = "Podemos empezar cuando estés listo.",
  ui_story_1018_10180601_52_dialog_content = "(¡Te está mintiendo! ¡Estás luchando en una batalla en Crepúsculo ahora mismo!)",
  ui_story_1018_10180601_53_dialog_content = "(No es un enemigo frente a ti, sino Wrath, tu superior. ¡Ahora sal de la habitación!)",
  ui_story_1018_10180601_54_dialog_content = "(¿Wrath, el Gran Mariscal, también está mirando?)",
  ui_story_1018_10180601_55_dialog_content = "(Crepúsculo, mencionaste... Siento como si hubiera estado allí...)",
  ui_story_1018_10180601_56_dialog_content = "¿Que estas esperando?",
  ui_story_1018_10180601_57_dialog_content = "No... Comandante, estoy listo.",
  ui_story_1018_10180601_58_dialog_content = "(¡Por favor, despierta!)",
  ui_story_1018_10180601_59_dialog_content = "(Mamá, mírame... Me convertiré en un valiente guerrero.)",
  ui_story_1018_10180601_60_dialog_content = "Grah!",
  ui_story_1018_10180601_61_dialog_content = "(¡Ey, despierta! ¡No te resistas!)",
  ui_story_1018_10180601_62_dialog_content = "Comandante, en el momento en que veo al Eclipsite, siento... un torrente de fuerza recorriendo mi cuerpo.",
  ui_story_1018_10180601_63_dialog_content = "Así es, siente el poder y luego controla ese poder.",
  ui_story_1018_10180601_64_dialog_content = "Grah!",
  ui_story_1018_10180601_65_dialog_content = "Todos los Eclipsites... ¡DEBEN MORIR!",
  ui_story_1018_10180601_66_dialog_content = "(Oh no, si no termino esto ahora...)",
  ui_story_1018_10180601_67_dialog_content = "¡MUERAN!!!",
  ui_story_1018_10180601_68_dialog_content = "Grah!",
  ui_story_1018_10180601_69_dialog_content = "<color=#e8d9bb>¡¡¡Rooooooooooooooooooooooooooooooooooo!!!</color>",
  ui_story_1018_10180601_70_dialog_content = "¡Oh, no! Parece que su rugido ha alterado a todos los demás soldados corruptos.",
  ui_story_1018_10180602_1_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1018_10180602_2_dialog_content = "...",
  ui_story_1018_10180602_3_dialog_content = "Lo siento, Gran Mariscal. Esta es la única manera.",
  ui_story_1018_10180602_4_dialog_content = "¿Estás bien, PlayerName?",
  ui_story_1018_10180602_5_dialog_content = "Lo siento, no pude salvarlo...",
  ui_story_1018_10180602_6_dialog_content = "Pero era un soldado excelente.",
  ui_story_1018_10180602_7_dialog_content = "Axelia está triste...",
  ui_story_1018_10180602_8_dialog_content = "¿Qué vas a hacer con esos soldados allá?",
  ui_story_1018_10180602_9_dialog_content = "...",
  ui_story_1018_10180602_10_dialog_content = "Matarlos yo mismo. No soy apto para ser el Gran Mariscal...",
  ui_story_1018_10180602_11_dialog_content = "(¿Qué debo hacer?)",
  ui_story_1018_10180602_12_dialog_content = "(¿Qué harías, Reinhardt, si fueras tú?)",
  ui_story_1018_10180602_13_dialog_content = "Déjame hacerlo.",
  ui_story_1018_10180602_14_dialog_content = "Leo...",
  ui_story_1018_10180602_15_dialog_content = "Solo finge que no pudiste detenerme cuando me esforcé por matarlos.",
  ui_story_1018_10180602_16_dialog_content = "Solo soy un caballero residente de Crepúsculo. No tengo la responsabilidad de dirigir un ejército completo como tú.",
  ui_story_1018_10180602_17_dialog_content = "La misericordia solo llevará a mayores pérdidas. Debes aprender a enfrentarte a esa realidad.",
  ui_story_1018_10180602_18_dialog_content = "No, no puedo soportar toda esta sangre en mis manos...",
  ui_story_1018_10180602_19_dialog_content = "Les prometí que los llevaría a la victoria en esta batalla...",
  ui_story_1018_10180602_20_dialog_content = "En cambio, los llevé directamente a la tumba...",
  ui_story_1018_10180602_21_dialog_content = "(Pensé que mientras tenga el poder, si soy lo suficientemente fuerte, podría hacer cualquier cosa.)",
  ui_story_1018_10180602_22_dialog_content = "(Fuerte suficiente... Qué broma...)",
  ui_story_1018_10180602_23_dialog_content = "Wrath, creo que lo que estás haciendo es más difícil que intentar ser más poderoso.",
  ui_story_1018_10180602_24_dialog_content = "...",
  ui_story_1018_10180602_25_dialog_content = "Poner su propio cuerpo en peligro es el propósito de un guerrero.",
  ui_story_1018_10180602_26_dialog_content = "Cuando ellos mismos se convierten en el peligro y no pueden proteger vidas...",
  ui_story_1018_10180602_27_dialog_content = "Esta es la única cosa que podemos hacer por ellos como comandantes.",
  ui_story_1018_10180602_28_dialog_content = "Comandante...",
  ui_story_1018_10180602_29_dialog_content = "(¿Esto es a lo que te referías al decir dejar ir, Reinhardt...?)",
  ui_story_1018_10180602_30_dialog_content = "Confía en mí, tus soldados están muriendo donde deben y su dolor terminará pronto.",
  ui_story_1018_10180602_31_dialog_content = "Espera, Leo.",
  ui_story_1018_10180602_32_dialog_content = "Probablemente tengas razón sobre que mueran donde deben...",
  ui_story_1018_10180602_33_dialog_content = "Debo enfrentar la realidad.",
  ui_story_1018_10180602_34_dialog_content = "En lugar de vivir en agonía, haré que sea rápido y fácil para ellos.",
  ui_story_1018_10180602_35_dialog_content = "Gran Mariscal...",
  ui_story_1018_10180602_36_dialog_content = "Todos los soldados, permítanme decir unas últimas palabras a sus antiguos compañeros.",
  ui_story_1018_10180602_37_dialog_content = "¡No importa qué, siempre te seguiremos!",
  ui_story_1018_10180602_38_dialog_content = "...",
  ui_story_1018_10180602_39_dialog_content = "Aunque no puedas entender lo que digo, te prometo aquí y ahora...",
  ui_story_1018_10180602_40_dialog_content = "Sois soldados de Illumina, nacidos para servir con orgullo a Illumina, asumiendo el deber de destruir a los Eclipsites.",
  ui_story_1018_10180602_41_dialog_content = "Sabes que una batalla es el camino más rápido hacia la muerte, pero avanzaste sin miedo...",
  ui_story_1018_10180602_42_dialog_content = "Morirás como valientes guerreros de Illumina...",
  ui_story_1018_10180602_43_dialog_content = "No alguien obligado a ser abandonado...",
  ui_story_1018_10180602_44_dialog_content = "Continuaremos tu misión inconclusa y seguiremos luchando!",
  ui_story_1018_10180602_45_dialog_content = "Rugido...",
  ui_story_1018_10180602_46_dialog_content = "(Eso es todo, Wrath, esto terminará muy rápido...)",
  ui_story_1018_10180602_47_dialog_content = "Y estás libre de tus obligaciones y libre para celebrar...",
  ui_story_1018_10180602_48_dialog_content = "La victoria en un lugar libre de guerra.",
  ui_story_1018_10180602_49_dialog_content = "Grah!",
  ui_story_1018_10180602_50_dialog_content = "Francotiradores apuntan...",
  ui_story_1018_10180602_51_dialog_content = "¡Fuego!",
  ui_story_1018_10180602_52_dialog_content = "<color=#e8d9bb>¡Estallido! ¡Estallido! ¡Estallido!</color>",
  ui_story_1018_10180602_53_dialog_content = "...",
  ui_story_1018_10180602_54_dialog_content = "La guerra ha terminado para ti. Descansa en paz.",
  ui_story_1018_10180602_55_dialog_content = "...",
  ui_story_1018_10180602_56_dialog_content = "...",
  ui_story_1018_10180701_1_dialog_content = "<color=#e8d9bb>En camino a la Fortaleza Lumo...</color>",
  ui_story_1018_10180701_2_dialog_content = "La Fortaleza Lumo está justo adelante, Chi. ¿Cómo estás?",
  ui_story_1018_10180701_3_dialog_content = "Mmm... Todavía me queda algo de energía...",
  ui_story_1018_10180701_4_dialog_content = "No te ves bien. ¿Te asustó el soldado que se soltó de la cuerda?",
  ui_story_1018_10180701_5_dialog_content = "No, Joselyne...",
  ui_story_1018_10180701_6_dialog_content = "Al verte luchar tanto para proteger a todos, no tengo miedo en absoluto.",
  ui_story_1018_10180701_7_dialog_content = "Pero esta vez... hay tantos heridos... algunos incluso necesitan ser sujetados con cuerdas...",
  ui_story_1018_10180701_8_dialog_content = "Oh, ¡no quería quejarme ni nada! Entiendo que estos soldados están aquí para protegernos...",
  ui_story_1018_10180701_9_dialog_content = "Es solo que... Joselyne, debe ser realmente difícil para ti enfrentarte a situaciones como esta todo el tiempo, ¿verdad...",
  ui_story_1018_10180701_10_dialog_content = "...",
  ui_story_1018_10180701_11_dialog_content = "¿Sabes, Chi, que la vida en Crepúsculo cuando era niño era más difícil de lo que es ahora?",
  ui_story_1018_10180701_12_dialog_content = "Cuando eras pequeño, Joselyne?",
  ui_story_1018_10180701_13_dialog_content = "Cuando tenía 12 años, los Eclipsites atacaron Crepúsculo. Mis padres perdieron sus vidas para protegerme.",
  ui_story_1018_10180701_14_dialog_content = "Nadie vino a ayudar a nuestro pueblo, así que solo pudimos contar con nosotros mismos.",
  ui_story_1018_10180701_15_dialog_content = "Recuerdo que incluso niños un poco mayores que yo tomaron las armas y lucharon. No volví a ver a muchos de ellos...",
  ui_story_1018_10180701_16_dialog_content = "Entonces... ¿Qué pasó después?",
  ui_story_1018_10180701_17_dialog_content = "Entonces los Eclipsites entraron en la aldea. Me llevé a los niños que quedaban conmigo y nos escondimos en todas partes. Ese miedo permaneció conmigo durante muchos años.",
  ui_story_1018_10180701_18_dialog_content = "Afortunadamente, fuimos rescatados por los Caballeros de la Expedición, y los soldados me llevaron al orfanato de la Iglesia de la Noche Blanca, donde me convertí en monja.",
  ui_story_1018_10180701_19_dialog_content = "Eso suena bastante difícil... Entonces, ¿por qué decidiste unirte a los Caballeros de Expedición más adelante?",
  ui_story_1018_10180701_20_dialog_content = "Porque creo que solo enfrentándonos activamente a los Eclipsites, la gente de Crepúsculo tendrá una oportunidad de sobrevivir.",
  ui_story_1018_10180701_21_dialog_content = "Fui salvado por los Caballeros, así que me gustaría crear un ambiente seguro para Crepúsculo como lo hicieron ellos.",
  ui_story_1018_10180701_22_dialog_content = "Joselyne, ¡eres realmente una persona increíble!",
  ui_story_1018_10180701_23_dialog_content = "Ayudaste a muchas personas, Chi. ¡Eres mejor que yo a esta edad!",
  ui_story_1018_10180701_24_dialog_content = "Aquí estamos. Solo empuja un poco más y los heridos estarán a salvo.",
  ui_story_1018_10180701_25_dialog_content = "¡Está bien!",
  ui_story_1018_10180701_26_dialog_content = "<color=#e8d9bb>Toc-toc, toc, toc-toc</color>",
  ui_story_1018_10180701_27_dialog_content = "Soy Joselyne, un guerrero de Crepúsculo. Hemos traído heridos y solicitamos ayuda médica y refugio en la Fortaleza Lumo!",
  ui_story_1018_10180701_28_dialog_content = "El Señor de la Ciudad ha ordenado que solo se permite la entrada a los residentes de Lumo. Deberías buscar refugio en otro lugar.",
  ui_story_1018_10180701_29_dialog_content = "Por favor escuchen, los heridos detrás de mí incluyen caballeros de la Fortaleza Lumo. Lucharon con nosotros. Lo menos que pueden hacer es dejarlos entrar.",
  ui_story_1018_10180701_30_dialog_content = "Los Caballeros de Ironthorn han solicitado ayuda varias veces anteriormente. Desafortunadamente, la Fortaleza Lumo solo tiene recursos limitados y no podemos ofrecer atención médica para más soldados.",
  ui_story_1018_10180701_31_dialog_content = "Pero señor—",
  ui_story_1018_10180701_32_dialog_content = "<color=#e8d9bb>¡Golpear! ¡Pum!</color>",
  ui_story_1018_10180701_33_dialog_content = "Joselyne! Se está volviendo más difícil controlar a esos dos soldados Illumina!",
  ui_story_1018_10180701_34_dialog_content = "Si logran liberarse de las cuerdas nuevamente y atacar a los heridos...",
  ui_story_1018_10180701_35_dialog_content = "Los miembros de tu equipo representan una amenaza para los residentes de la Fortaleza Lumo. ¡Hay más razones para no dejarte entrar!",
  ui_story_1018_10180701_36_dialog_content = "Entiendo...",
  ui_story_1018_10180701_37_dialog_content = "Por favor, envía un mensaje al Padre Joseph de la Iglesia de la Noche Blanca de mi parte—",
  ui_story_1018_10180701_38_dialog_content = "Yo, Joselyne, solicito asilo para los Aurorianos de la Iglesia de la Noche Blanca como la Santa del Crepúsculo.",
  ui_story_1018_10180701_39_dialog_content = "El padre Joseph está ocupado con asuntos importantes y no está en la ciudad. En cuanto a ti, eres simplemente la \"Santa\" de la que hablan los de Crepúsculo.",
  ui_story_1018_10180701_40_dialog_content = "Incluso si fueras una verdadera Santa, ¡aún así no desobedecería la orden del Señor de la Ciudad!",
  ui_story_1018_10180701_41_dialog_content = "¿La Iglesia va a ignorar las vidas de los Aurorianos cuando el pueblo del Dios de la Luz está en apuros?!",
  ui_story_1018_10180701_42_dialog_content = "¡Rarrr!",
  ui_story_1018_10180701_43_dialog_content = "Dios mío... ¿Estos soldados se han convertido en Eclipsites?",
  ui_story_1018_10180701_44_dialog_content = "Joselyne!",
  ui_story_1018_10180701_45_dialog_content = "¡No se asusten! Aléjense lo más posible de los carros. ¡Yo me encargo de esto!",
  ui_story_1018_10180701_46_dialog_content = "<size=30>Abre la puerta.</size>",
  ui_story_1018_10180701_47_dialog_content = "Dejar entrar a esos soldados sería prácticamente cavar nuestra propia tumba...",
  ui_story_1018_10180701_48_dialog_content = "Abre la puerta.",
  ui_story_1018_10180701_49_dialog_content = "¿Cómo te atreves a desafiar a la Santa! ¿Le has dado la espalda a la Iglesia?",
  ui_story_1018_10180701_50_dialog_content = "Yo, Capitán Carleen de los Guardianes de los Jardines de Lumopolis, ¡te ordeno abrir la puerta para los refugiados como Señor de la Ciudad interino de Lumo Stronghold!",
  ui_story_1018_10180701_51_dialog_content = "Me encargaré de los Eclipsites. ¡Ahora abran la puerta!",
  ui_story_1018_10180701_52_dialog_content = "Señora Carleen... ¡S-Sí!",
  ui_story_1018_10180701_53_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_1018_10180702_1_dialog_content = "<color=#e8d9bb>Al ver este resplandor sobrenatural, todos no pueden evitar querer inclinarse en reverencia...</color>",
  ui_story_1018_10180702_2_dialog_content = "¡Una verdadera señora santa!",
  ui_story_1018_10180702_3_dialog_content = "¡Esto no puede estar equivocado, la única Santa Señora en la luz sagrada!",
  ui_story_1018_10180702_4_dialog_content = "Como el Dios de la Luz es mi testigo, no he dicho nada más que la verdad—",
  ui_story_1018_10180702_5_dialog_content = "Por tu luz sagrada, guía a los Aurorianos perdidos.",
  ui_story_1018_10180702_6_dialog_content = "Joselyne! La luz dorada resplandece en los cuerpos de los soldados!",
  ui_story_1018_10180702_7_dialog_content = "Esto se siente extraño... de una buena manera. Quiero decir... el dolor en mi cuerpo está desapareciendo...",
  ui_story_1018_10180702_8_dialog_content = "Eh, Joselyne... ¿Estás... llorando?",
  ui_story_1018_10180702_9_dialog_content = "Ver a la Señora Santa en persona... Esto es abrumador para mí...",
  ui_story_1018_10180702_10_dialog_content = "Chi, ¡ella es la mismísima mensajera de Dios, la Santa Señora de la Iglesia de la Noche Blanca!",
  ui_story_1018_10180702_11_dialog_content = "Señora Santa...",
  ui_story_1018_10180702_12_dialog_content = "Joselyne—",
  ui_story_1018_10180702_13_dialog_content = "Papá Joseph! Noche Blanca en lo alto—",
  ui_story_1018_10180702_14_dialog_content = "Noche Blanca en lo alto— Condolencias a los soldados en Crepúsculo. ¿Cómo está Leo por allá?",
  ui_story_1018_10180702_15_dialog_content = "Ahora hay muchos menos Eclipsites, gracias a los soldados de Illumina y al Caelestite.",
  ui_story_1018_10180702_16_dialog_content = "Pero el atolladero sigue siendo un problema, y los soldados de Illumina están luchando...",
  ui_story_1018_10180702_17_dialog_content = "Lamento mucho escuchar eso. Los soldados en la fortaleza siguen las órdenes de los nobles de Lumopolis, y los refuerzos enviados por el Señor de la Ciudad tenían como objetivo principal fines defensivos.",
  ui_story_1018_10180702_18_dialog_content = "Aparte de seguir suplicándome a Schwartz mismo, no pude hacer mucho más...",
  ui_story_1018_10180702_19_dialog_content = "Solo pude enviar miembros de la iglesia a Twilight para ayudar y luego enviar cartas constantes al Templo de la Noche Blanca pidiendo ayuda.",
  ui_story_1018_10180702_20_dialog_content = "¡Ya veo! Ahora que la Dama Santa está aquí, la Iglesia de la Noche Blanca está bendecida con la gracia divina.",
  ui_story_1018_10180702_21_dialog_content = "Tampoco lo esperaba. Planeaba visitar Lumopolis después de enviar mi última solicitud.",
  ui_story_1018_10180702_22_dialog_content = "Pero antes de partir, recibí instrucciones personales de Su Santidad la Santa misma, así que me quedé y esperé.",
  ui_story_1018_10180702_23_dialog_content = "Hablaremos de los detalles más tarde. Debo ir a hacer preparativos en la iglesia.",
  ui_story_1018_10180702_24_dialog_content = "Enviaré a miembros de la iglesia a Crepúsculo para transportar a los heridos.",
  ui_story_1018_10180702_25_dialog_content = "Gracias por tu ayuda, Padre Joseph!",
  ui_story_1018_10180702_26_dialog_content = "Pero algunos de los heridos están afectados de manera bastante única, así que por favor mantén un ojo en ellos.",
  ui_story_1018_10180702_27_dialog_content = "No hay nada de qué preocuparse. El séquito con la Dama Santa es tan experto en tratamiento como ella. Yo los cuidaré.",
  ui_story_1018_10180702_28_dialog_content = "Noche Blanca en lo alto.",
  ui_story_1018_10180702_29_dialog_content = "Noche Blanca en lo alto.",
  ui_story_1018_10180702_30_dialog_content = "Uf... Gracias al eterno Dios de la Luz, no debería haber más problemas.",
  ui_story_1018_10180702_31_dialog_content = "Tú... Realmente eres la Señora Santa... ¡Una llegada divina en este reino abandonado!",
  ui_story_1018_10180702_32_dialog_content = "Con la presencia de la Señora Santa, ¡el lodo no se extenderá más!",
  ui_story_1018_10180702_33_dialog_content = "Mira, las nubes oscuras sobre Crepúsculo han sido disipadas por Lady Saintess, ¡lo que deja a los eclipses sin ningún lugar al que huir!",
  ui_story_1018_10180702_34_dialog_content = "¡Gratitud a usted, Su Santidad!",
  ui_story_1018_10180702_35_dialog_content = "De nada, y no es necesario llamarme Lady Santa.",
  ui_story_1018_10180702_36_dialog_content = "Su Santidad, hay un favor que le pido humildemente: mi hijo todavía está peleando en Crepúsculo...",
  ui_story_1018_10180702_37_dialog_content = "Su Santidad, le suplico que me escuche—",
  ui_story_1018_10180702_38_dialog_content = "Su Santidad...",
  ui_story_1018_10180702_39_dialog_content = "A todos, simplemente llámenme Hilda, por favor.",
  ui_story_1018_10180702_40_dialog_content = "He escuchado todas tus oraciones...",
  ui_story_1018_10180702_41_dialog_content = "Su Santidad, por favor no nos abandone de nuevo...",
  ui_story_1018_10180702_42_dialog_content = "...",
  ui_story_1018_10180702_43_dialog_content = "No es necesario responder a todos, Su Santidad.",
  ui_story_1018_10180702_44_dialog_content = "Pero esta es la primera vez que encuentro Aurorianos fuera del Templo...",
  ui_story_1018_10180702_45_dialog_content = "No necesitas responder.",
  ui_story_1018_10180702_46_dialog_content = "Está bien...",
  ui_story_1018_10180702_47_dialog_content = "La Señora Santa ha recibido todos sus saludos.",
  ui_story_1018_10180702_48_dialog_content = "Gracias, Carleen. ¡En realidad estoy muy feliz!",
  ui_story_1018_10180702_49_dialog_content = "Mmm, ¿quién eres? ¿Por qué me miras...?",
  ui_story_1018_10180702_50_dialog_content = "¿Qué pasa con el cuerno en tu cabeza?",
  ui_story_1018_10180702_51_dialog_content = "Cuida tus modales—",
  ui_story_1018_10180702_52_dialog_content = "¡Está bien!",
  ui_story_1018_10180702_53_dialog_content = "En realidad, es una historia relacionada con <color=#FFB400>rinocerontes</color>...",
  ui_story_1018_10180702_54_dialog_content = "Estás hablando de la leyenda del Guardián Rhinohorn, ¿verdad? La he escuchado desde que era niño. Así es como va la historia...",
  ui_story_1018_10180702_55_dialog_content = "<color=#e8d9bb>Después de que Joselyne haya atendido a los heridos...</color>",
  ui_story_1018_10180702_56_dialog_content = "Saludos, Lady Santa! Yo, Joselyne, pido disculpas por mi tardanza.",
  ui_story_1018_10180702_57_dialog_content = "Hola, Joselyne. El Padre Joseph me habló de ti y estoy encantado de ayudar.",
  ui_story_1018_10180702_58_dialog_content = "Me avergüenza no haber podido salvar a los Aurorians lastimados por los Eclipsites, y estoy agradecido por curarlos con tu aura.",
  ui_story_1018_10180702_59_dialog_content = "No te sientas avergonzado. Hiciste todo lo posible para rescatarlos, siendo la buena persona que eres.",
  ui_story_1018_10180702_60_dialog_content = "Si no te importa, por favor llámame simplemente Hilda. Ese es mi nombre y tengo muchas cosas que me gustaría preguntarte.",
  ui_story_1018_10180702_61_dialog_content = "¿Cómo podría dirigirme a ti por tu nombre? ¡Después de todo, eres la Dama Santa!",
  ui_story_1018_10180702_62_dialog_content = "Joselyne, encuentro a Lady Saintess tan cálida y amable como las hermanas aquí en Crepúsculo.",
  ui_story_1018_10180702_63_dialog_content = "¡Oh, y no pude terminar la historia, Chi! Al final...",
  ui_story_1018_10180702_64_dialog_content = "...",
  ui_story_1018_10180702_65_dialog_content = "¿Qué estás pensando, Lady Joselyne?",
  ui_story_1018_10180702_66_dialog_content = "Lady Carleen, simplemente nunca imaginé que...",
  ui_story_1018_10180702_67_dialog_content = "La señora santa en realidad tenía un aire de inocencia infantil.",
  ui_story_1018_10180702_68_dialog_content = "Para ser honesto, la primera vez que la conocí, también me sorprendió su... falta de conocimiento del mundo.",
  ui_story_1018_10180702_69_dialog_content = "Pero viste cómo ella se acercaba naturalmente a chicas de la edad de Chi y lo curiosa que estaba con las historias que circulaban en Crepúsculo.",
  ui_story_1018_10180702_70_dialog_content = "Quizás todavía esté buscando su camino más allá de ser la Lady Santa.",
  ui_story_1018_10180702_71_dialog_content = "Tienes razón, estoy siendo de mente estrecha.",
  ui_story_1018_10180702_72_dialog_content = "¿No planeas quedarte después de entregar a los heridos a la Iglesia?",
  ui_story_1018_10180702_73_dialog_content = "La batalla en Crepúsculo aún no ha terminado. Debo regresar y luchar junto a los guerreros.",
  ui_story_1018_10180702_74_dialog_content = "Me siento tranquilo sabiendo que Papá Joseph está aquí.",
  ui_story_1018_10180702_75_dialog_content = "De acuerdo, lideraré el refuerzo de Lumopolis e iré contigo.",
  ui_story_1018_10180702_76_dialog_content = "¡También voy! Aún podemos lograrlo, ¿verdad?",
  ui_story_1018_10180702_77_dialog_content = "Sí, Su Santidad.",
  ui_story_1018_10180702_78_dialog_content = "Con la Dama Santa con nosotros, Crepúsculo seguramente será salvado. ¡Vamos!",
  ui_story_1018_10180801_1_dialog_content = "<color=#e8d9bb>Fuera del Crepúsculo</color>",
  ui_story_1018_10180801_2_dialog_content = "(Mi señor Eclipsiano), no entiendo muy bien por qué elegirías curarla.",
  ui_story_1018_10180801_3_dialog_content = "(Eclipsian) Ella debería unirse a nosotros, al igual que esos soldados.",
  ui_story_1018_10180801_4_dialog_content = "Sobrevivió al ser llevada al límite. Estoy sorprendido por el resultado de este experimento en particular.",
  ui_story_1018_10180801_5_dialog_content = "Si puedo descubrir por qué la semilla dentro de ella es tan especial, este viaje no será en vano.",
  ui_story_1018_10180801_6_dialog_content = "(Eclipsiano) Mi señor, ha pasado mucho tiempo desde que tuve una buena sesión de rechinar mis dientes.",
  ui_story_1018_10180801_7_dialog_content = "Mudbundle está cerca de recuperarse por completo. Prepárate para colocar más alfombra.",
  ui_story_1018_10180801_8_dialog_content = "(En eclipsiano) ¿Deberíamos seguir avanzando?",
  ui_story_1018_10180801_9_dialog_content = "Así es, pero esta vez, rodea Crepúsculo.",
  ui_story_1018_10180801_10_dialog_content = "Convertiremos a todos los soldados de Ulysses en Eclipsites una vez que inundemos Illumina.",
  ui_story_1018_10180801_11_dialog_content = "(Eclipsian) ¿Cuál es el plan para estos soldados, mi señor?",
  ui_story_1018_10180801_12_dialog_content = "Haz que Mudbundle los reubique en la línea defensiva y no olvides esa \"obra de arte\".",
  ui_story_1018_10180801_13_dialog_content = "Pero antes de irme, quiero ver si le gusta el regalo que tengo para ella.",
  ui_story_1018_10180801_14_dialog_content = "Capitán Axelia, Gran Mariscal! Hemos encontrado al Noveno Escuadrón...",
  ui_story_1018_10180801_15_dialog_content = "Estaban... en realidad, acostados en el lodo cerca de la barrera todo el tiempo.",
  ui_story_1018_10180801_16_dialog_content = "Logramos verlos una vez que el lodo retrocedió... pero ya...",
  ui_story_1018_10180801_17_dialog_content = "...",
  ui_story_1018_10180801_18_dialog_content = "Llévame allí.",
  ui_story_1018_10180801_19_dialog_content = "Excepto la tripulación del tanque, todos los soldados del Noveno Escuadrón están aquí.",
  ui_story_1018_10180801_20_dialog_content = "El resto de ellos han hecho el sacrificio definitivo, incluyendo... el conductor de Engine VII.",
  ui_story_1018_10180801_21_dialog_content = "¿Por qué el soldado murió así...",
  ui_story_1018_10180801_22_dialog_content = "Hay una herida de bala debajo de su barbilla y su dedo sigue firmemente en el gatillo. Obviamente, se quitó la vida antes de perder el control...",
  ui_story_1018_10180801_23_dialog_content = "...",
  ui_story_1018_10180801_24_dialog_content = "Estos son solo soldados ordinarios, ¿verdad?",
  ui_story_1018_10180801_25_dialog_content = "Sí, lo eran...",
  ui_story_1018_10180801_26_dialog_content = "Se sostenían mutuamente, probablemente intentando resistir el fango, ¿no?",
  ui_story_1018_10180801_27_dialog_content = "Esto es brutal... Apenas queda carne, en su mayoría solo huesos...",
  ui_story_1018_10180801_28_dialog_content = "Sacrificándose así... Son muy valientes.",
  ui_story_1018_10180801_29_dialog_content = "Pido disculpas por los juicios apresurados que hice.",
  ui_story_1018_10180801_30_dialog_content = "...",
  ui_story_1018_10180801_31_dialog_content = "Wrath...",
  ui_story_1018_10180801_32_dialog_content = "Esto es algo que nunca había visto en mis años de guarnición.",
  ui_story_1018_10180801_33_dialog_content = "¿Hay algo que podamos hacer?",
  ui_story_1018_10180801_34_dialog_content = "Sigan revisando el perímetro y encuentren a todos los heridos.",
  ui_story_1018_10180801_35_dialog_content = "<color=#e8d9bb>Glup, glup...</color>",
  ui_story_1018_10180801_36_dialog_content = "¡Capitán! ¡Algo se está moviendo en el lodo detrás de los soldados!",
  ui_story_1018_10180801_37_dialog_content = "¿Así que esta es la atracción principal de Crepúsculo?",
  ui_story_1018_10180801_38_dialog_content = "Resulta que es esta auténtica \"obra de arte.\"",
  ui_story_1018_10180801_39_dialog_content = "¿Renegado?",
  ui_story_1018_10180801_40_dialog_content = "¿Eres tú el que está detrás de todo esto?",
  ui_story_1018_10180801_41_dialog_content = "Solo estoy aquí para saludar al Gran Mariscal. ¿Te lo estás pasando bien luchando?",
  ui_story_1018_10180801_42_dialog_content = "Por... sakin...!",
  ui_story_1018_10180801_43_dialog_content = "Relájate. No puedes hablar en serio en tu condición.",
  ui_story_1018_10180801_44_dialog_content = "¡No dañarás al Gran Mariscal Wrath!",
  ui_story_1018_10180801_45_dialog_content = "¿Tú de nuevo? Veo que no debería haber sido fácil contigo, tonto.",
  ui_story_1018_10180801_46_dialog_content = "¡Te haré pagar el doble por lo que hiciste a mis soldados!",
  ui_story_1018_10180801_47_dialog_content = "¿Qué hice? No sería suficiente para compensar mis pérdidas si los mataba a todos.",
  ui_story_1018_10180801_48_dialog_content = "Probablemente no tengas idea de cómo pudiste llegar hasta este momento. Lo que Illumina te ha hecho podría matarte mil veces.",
  ui_story_1018_10180801_49_dialog_content = "¿No quieres saber por qué has estado luchando tanto y, sin embargo, a Illumina no le ha importado en lo más mínimo?",
  ui_story_1018_10180801_50_dialog_content = "¡Cállate, bruja sin honor!",
  ui_story_1018_10180801_51_dialog_content = "Hmm, parece que tienes una idea, después de todo. ¿Saben que matar a sus propios soldados es el motivo del nuevo Gran Mariscal?",
  ui_story_1018_10180801_52_dialog_content = "Lo estás pidiendo, Forsakin!",
  ui_story_1018_10180801_53_dialog_content = "Cálmate, Wrath! Ella está tratando de irritarte a propósito.",
  ui_story_1018_10180801_54_dialog_content = "...",
  ui_story_1018_10180801_55_dialog_content = "Sabía que estabas detrás de todo lo que pasó en Crepúsculo, ¡y no te dejaré escapar!",
  ui_story_1018_10180801_56_dialog_content = "No lo niego y me alegra hacerlo para castigar un robo.",
  ui_story_1018_10180801_57_dialog_content = "Ya que todos vieron la obra de arte, pasemos al verdadero espectáculo. ¡Mantengan los ojos bien abiertos ahora!",
  ui_story_1018_10180801_58_dialog_content = "¿Qué estás haciendo?",
  ui_story_1018_10180801_59_dialog_content = "Mmm, ¿me estás desafiando al interponerte frente a ella?",
  ui_story_1018_10180801_60_dialog_content = "Y Axelia también.",
  ui_story_1018_10180801_61_dialog_content = "¡Sí, cuenta conmigo!",
  ui_story_1018_10180801_62_dialog_content = "Lo que sea. Me he divertido. No soy yo con quien estás peleando...",
  ui_story_1018_10180801_63_dialog_content = "Rugido...",
  ui_story_1018_10180801_64_dialog_content = "Esa es la voz del piloto de mecha... ¿Pero no está muerto?",
  ui_story_1018_10180801_65_dialog_content = "Rugido...",
  ui_story_1018_10180801_66_dialog_content = "Ya os habéis sacrificado una vez...",
  ui_story_1018_10180801_67_dialog_content = "No puedo dejarte...",
  ui_story_1018_10180801_68_dialog_content = "Axelia sintió tu enojo, Gran Mariscal...",
  ui_story_1018_10180801_69_dialog_content = "Qué es esto...",
  ui_story_1018_10180801_70_dialog_content = "Axelia quiere proteger al Gran Mariscal, y aunque Axelia no puede sentir el calor de un cuerpo...",
  ui_story_1018_10180801_71_dialog_content = "Yingel me dijo que aquí es donde estaba el corazón de Axelia.",
  ui_story_1018_10180801_72_dialog_content = "Creo que está más caliente que esa fuerza dentro de nosotros.",
  ui_story_1018_10180801_73_dialog_content = "Axelia...",
  ui_story_1018_10180801_74_dialog_content = "No te preocupes, no dejaré que me controle.",
  ui_story_1018_10180801_75_dialog_content = "¡Capitán... todo el escuadrón viene hacia nosotros! ¿Qué hacemos ahora?",
  ui_story_1018_10180801_76_dialog_content = "El pantano... no, el Darkflow, ¡está filtrándose de sus cuerpos! ¡Puedo ver eso! Hay un brillo espeluznante en los ojos de los soldados.",
  ui_story_1018_10180801_77_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_1018_10180801_78_dialog_content = "¡Lanza relámpago, perfora!",
  ui_story_1018_10180801_79_dialog_content = "Sus espíritus ya se fueron hace mucho tiempo. Solo empañaría su legado si siguieran luchando.",
  ui_story_1018_10180801_80_dialog_content = "¡Todos, escuchen! No permitamos que nuestros soldados sufran más. Nos protegieron y no deberían haber sacrificado en vano.",
  ui_story_1018_10180801_81_dialog_content = "Sí, Gran Mariscal.",
  ui_story_1018_10180801_82_dialog_content = "Ahí tienes, sin piedad. Entonces no te importará si me llevo el resto conmigo...",
  ui_story_1018_10180801_83_dialog_content = "¡No intentes correr!",
  ui_story_1018_10180801_84_dialog_content = "¿No van los soldados al barro...?",
  ui_story_1018_10180801_85_dialog_content = "Son subordinados de Axelia.",
  ui_story_1018_10180801_86_dialog_content = "Axelia liderará el Escuadrón Ocho!",
  ui_story_1018_10180801_87_dialog_content = "Axelia estará bien, ¿verdad...?",
  ui_story_1018_10180801_88_dialog_content = "Los soldados que avanzan con ella han sido leales, así que no debería haber problema.",
  ui_story_1018_10180801_89_dialog_content = "¡Pongámonos al día después de terminar aquí!",
  ui_story_1018_10180801_90_dialog_content = "¡Seguro!",
  ui_story_1018_10180802_1_dialog_content = "¿Aún me persigues en tu estado?",
  ui_story_1018_10180802_2_dialog_content = "Axelia... debo protegerlos... por favor devuélvemelos.",
  ui_story_1018_10180802_3_dialog_content = "Entonces supongo que tendrás que matarme de alguna manera.",
  ui_story_1018_10180802_4_dialog_content = "Axelia... traerá al Escuadrón Ocho de vuelta a casa!",
  ui_story_1018_10180802_5_dialog_content = "¡Así es como debería verse matar!",
  ui_story_1018_10180802_6_dialog_content = "No...",
  ui_story_1018_10180802_7_dialog_content = "Capitán Axelia, ¿estás... bien?",
  ui_story_1018_10180802_8_dialog_content = "...",
  ui_story_1018_10180802_9_dialog_content = "¿Es esa tristeza la que veo en el rostro de la creación sin emociones de Ulysses?",
  ui_story_1018_10180802_10_dialog_content = "Axelia... no es insensible.",
  ui_story_1018_10180802_11_dialog_content = "¿Todavía no lo admites?",
  ui_story_1018_10180802_12_dialog_content = "No les hagas daño... Están sufriendo...",
  ui_story_1018_10180802_13_dialog_content = "¿Parece que pueden escuchar tus palabras?",
  ui_story_1018_10180802_14_dialog_content = "Axelia no te dejará salirte con la tuya...",
  ui_story_1018_10180802_15_dialog_content = "Además de verme exprimirles la vida, ¿qué más puedes hacer?",
  ui_story_1018_10180802_16_dialog_content = "(Eclipsian) Mi señor, Mudbundle está listo y en espera.",
  ui_story_1018_10180802_17_dialog_content = "Muy bien entonces, ya que lo ruegas, te dejaré algunos. El resto, sin embargo...",
  ui_story_1018_10180802_18_dialog_content = "Capitán Axelia, todos... han desaparecido en el pantano...",
  ui_story_1018_10180802_19_dialog_content = "Devuélvemelos...",
  ui_story_1018_10180802_20_dialog_content = "Grah!",
  ui_story_1018_10180802_21_dialog_content = "Capitán Axelia, ¡cuidado!",
  ui_story_1018_10180802_22_dialog_content = "Grah!",
  ui_story_1018_10180802_23_dialog_content = "Para...",
  ui_story_1018_10180802_24_dialog_content = "¡Ayuda! Capitán Axelia!",
  ui_story_1018_10180802_25_dialog_content = "Grah!",
  ui_story_1018_10180802_26_dialog_content = "Agh...",
  ui_story_1018_10180802_27_dialog_content = "No son máquinas de guerra... Por favor, no los maten...",
  ui_story_1018_10180802_28_dialog_content = "Grah!",
  ui_story_1018_10180802_29_dialog_content = "¡Arghhhh—!",
  ui_story_1018_10180802_30_dialog_content = "...",
  ui_story_1018_10180802_31_dialog_content = "(Su grito... el viento, los ruidos de las armas... Todo en silencio ahora...)",
  ui_story_1018_10180802_32_dialog_content = "(¿Está él... muerto?)",
  ui_story_1018_10180802_33_dialog_content = "(O tal vez... Axelia está muerto...)",
  ui_story_1018_10180802_34_dialog_content = "(...)",
  ui_story_1018_10180802_35_dialog_content = "Capitán Axelia, ¡sálvame!",
  ui_story_1018_10180802_36_dialog_content = "(Me siento tan pesado... no puedo moverme...)",
  ui_story_1018_10180802_37_dialog_content = "(¡Rápido... debo salvarlo!)",
  ui_story_1018_10180802_38_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_1018_10180802_39_dialog_content = "(Su cuerpo es golpeado fuertemente contra el suelo...)",
  ui_story_1018_10180802_40_dialog_content = "(Parece que el cuerpo de Axelia ha sido golpeado contra el suelo...)",
  ui_story_1018_10180802_41_dialog_content = "<color=#e8d9bb>¡¡¡Rooooooooooooooooooooooooooooooooooo!!!</color>",
  ui_story_1018_10180802_42_dialog_content = "(Él abrió el pecho del soldado y está comenzando a darse un festín...)",
  ui_story_1018_10180802_43_dialog_content = "(El soldado ha caído en un charco de su propia sangre...)",
  ui_story_1018_10180802_44_dialog_content = "(Pero Axelia siento que... soy yo quien ha caído allí...)",
  ui_story_1018_10180802_45_dialog_content = "<color=#e8d9bb>¡Sonido metálico! ¡Sonido metálico!</color>",
  ui_story_1018_10180802_46_dialog_content = "(Cinco veces, seis veces...)",
  ui_story_1018_10180802_47_dialog_content = "(Axelia ha caído seis veces...)",
  ui_story_1018_10180802_48_dialog_content = "(Decima vez...)",
  ui_story_1018_10180802_49_dialog_content = "(Vigésima tercera vez, vigésima cuarta vez...)",
  ui_story_1018_10180802_50_dialog_content = "(Ciento dos veces...)",
  ui_story_1018_10180802_51_dialog_content = "(Dos mil veces...)",
  ui_story_1018_10180802_52_dialog_content = "(...)",
  ui_story_1018_10180802_53_dialog_content = "Once mil, ciento once veces...",
  ui_story_1018_10180802_54_dialog_content = "(Axelia sigue perdiendo...)",
  ui_story_1018_10180802_55_dialog_content = "(Papá dijo que Axelia es una excelente máquina de guerra, y las máquinas de guerra nunca ceden.)",
  ui_story_1018_10180802_56_dialog_content = "(Pero Axelia sigue siendo derrotado...)",
  ui_story_1018_10180802_57_dialog_content = "(Axelia no tiene idea de cómo detener esto en absoluto.)",
  ui_story_1018_10180802_58_dialog_content = "¡Axelia!",
  ui_story_1018_10180802_59_dialog_content = "(Padre, por favor perdona a Axelia...)",
  ui_story_1018_10180802_60_dialog_content = "Recuerda, Axelia, ¡debes vivir como una persona!",
  ui_story_1018_10180802_61_dialog_content = "(Vivir... Pero ¿qué puede hacer Axelia...?)",
  ui_story_1018_10180802_62_dialog_content = "(Quizás Axelia pueda...)",
  ui_story_1018_10180802_63_dialog_content = "Rugido...",
  ui_story_1018_10180802_64_dialog_content = "Grah!",
  ui_story_1018_10180802_65_dialog_content = "¡Trueno rugiente!",
  ui_story_1018_10180802_66_dialog_content = "Despierta, Axelia! ¡Escucha mi voz!",
  ui_story_1018_10180802_67_dialog_content = "No puedes avanzar más, Wrath!",
  ui_story_1018_10180802_68_dialog_content = "Rugido...",
  ui_story_1018_10180802_69_dialog_content = "Incluso Axelia va a...",
  ui_story_1018_10180802_70_dialog_content = "<color=#e8d9bb>¡Hola—</color>",
  ui_story_1018_10180802_71_dialog_content = "Ese sonido...",
  ui_story_1018_10180802_72_dialog_content = "La luz es tan brillante...",
  ui_story_1018_10180802_73_dialog_content = "Gran Mariscal, Leo, ¡perdón por llegar tarde!",
  ui_story_1018_10180802_74_dialog_content = "Yo, Joselyne, en el Aura de la Santa Señora, redimiré a los Aurorianos y los devolveré a las gracias de Dios.",
  ui_story_1018_10180802_75_dialog_content = "¡Los siniestros Eclipsites nunca más te harán daño!",
  ui_story_1018_10180802_76_dialog_content = "¡Capitán! ¡Es Joselyne! Y... Lady Carleen y los Skyriders de Lumopolis!",
  ui_story_1018_10180802_77_dialog_content = "¿Es esa chica parada en la luz quien creo que es...?",
  ui_story_1018_10180802_78_dialog_content = "Escuché, pero aún no es el momento para que regresen.",
  ui_story_1018_10180802_79_dialog_content = "Todas las vidas son preciosas. Serás limpiado del mal por las gracias de Dios.",
  ui_story_1018_10180802_80_dialog_content = "Bañado en la luz sagrada, escucha las oraciones y recibe la bendición divina.",
  ui_story_1018_10180802_81_dialog_content = "Deja que el poder fluya para sanar heridas y erradicar pensamientos malvados.",
  ui_story_1018_10180802_82_dialog_content = "May que el eterno Dios de la Luz siempre esté con los Aurorianos.",
  ui_story_1018_10180802_83_dialog_content = "¡Capitán, mira a los soldados! ¡Están brillando con una luz dorada!",
  ui_story_1018_10180802_84_dialog_content = "Sí, Joselyne ha logrado traer a Su Santidad la Santa con ella...",
  ui_story_1018_10180802_85_dialog_content = "¿Está curando a esos soldados corrompidos?",
  ui_story_1018_10180802_86_dialog_content = "Sí. Supuestamente, ella no solo podía romper el control del Darkflow, sino que incluso la simple vista del aura sagrada podía sanar a los Aurorians promedio.",
  ui_story_1018_10180802_87_dialog_content = "De verdad...",
  ui_story_1018_10180802_88_dialog_content = "Siento que una cierta fuerza en mi cuerpo se dispersa para brindar mucho alivio...",
  ui_story_1018_10180802_89_dialog_content = "Además, los soldados que se convirtieron en Eclipsites han cesado sus ataques...",
  ui_story_1018_10180802_90_dialog_content = "Siento tu dolor. Solo necesitas recuperarte en paz por ahora.",
  ui_story_1018_10180802_91_dialog_content = "¡Noche Blanca en lo alto!",
  ui_story_1018_10180802_92_dialog_content = "¡Perdón por llegar tarde!",
  ui_story_1018_10180802_93_dialog_content = "Hola...",
  ui_story_1018_10180802_94_dialog_content = "A todos, esta es la Santa Señora del Templo de Lumopolis.",
  ui_story_1018_10180802_95_dialog_content = "¿Templo de Lumopolis? ¿Qué está pasando aquí?",
  ui_story_1018_10180802_96_dialog_content = "Gran Mariscal Wrath, la Dama Santa está aquí para ayudar a curar a los soldados heridos.",
  ui_story_1018_10180802_97_dialog_content = "Aquellos que me siguieron a Lumo Stronghold están estables ahora, gracias a ella.",
  ui_story_1018_10180802_98_dialog_content = "¿La Señora Santa posee poder divino...?",
  ui_story_1018_10180802_99_dialog_content = "No. Soy un auroriano igual que tú, Gran Mariscal.",
  ui_story_1018_10180802_100_dialog_content = "Pero ¿cómo es que simplemente no creo...",
  ui_story_1018_10180802_101_dialog_content = "Me angustió saber lo que les sucedió a ti y a tus soldados, así que los traté sin tu consentimiento. Espero que puedas perdonarme.",
  ui_story_1018_10180802_102_dialog_content = "No, soy yo quien debería agradecerte.",
  ui_story_1018_10180802_103_dialog_content = "¿Por qué viniste, si puedo preguntar?",
  ui_story_1018_10180802_104_dialog_content = "He estado escuchando los murmullos de los Aurorianos en sus pesadillas. Puedo sentir el dolor y la angustia.",
  ui_story_1018_10180802_105_dialog_content = "Tú también te sentiste perturbado por eso y te oí.",
  ui_story_1018_10180802_106_dialog_content = "...",
  ui_story_1018_10180802_107_dialog_content = "Oh, lo siento, este no es el momento para que yo hable sin parar.",
  ui_story_1018_10180802_108_dialog_content = "Por favor, revise a sus soldados, Gran Mariscal. Deberían estar fuera de peligro ahora.",
  ui_story_1018_10180802_109_dialog_content = "Sí. De nuevo, muchas gracias.",
  ui_story_1018_10180802_110_dialog_content = "La Señora Santa realmente es algo especial...",
  ui_story_1018_10180802_111_dialog_content = "Escuché eso.",
  ui_story_1018_10180802_112_dialog_content = "¿Qué? ¡Pero eso fue apenas un susurro!",
  ui_story_1018_10180802_113_dialog_content = "No eres como los demás.",
  ui_story_1018_10180802_114_dialog_content = "Esta es la Caelestita, Lady Santa.",
  ui_story_1018_10180802_115_dialog_content = "Saludos, Lady Santa. Soy PlayerName.",
  ui_story_1018_10180802_116_dialog_content = "¿Cómo estás, PlayerName? Por favor, solo llámame Hilda.",
  ui_story_1018_10180802_117_dialog_content = "Hilda...",
  ui_story_1018_10180802_118_dialog_content = "He leído un libro de cuentos antes y el personaje principal también se llamaba Hilda.",
  ui_story_1018_10180802_119_dialog_content = "¿En serio? ¿Cómo es ese Hilda?",
  ui_story_1018_10180802_120_dialog_content = "Bueno, Hilda en realidad es un animal...",
  ui_story_1018_10180802_121_dialog_content = "¡Cómo te atreves a llamar a la Señora Santa...!",
  ui_story_1018_10180802_122_dialog_content = "No, me refiero a la del libro. A Hilda le gusta cultivar flores...",
  ui_story_1018_10180802_123_dialog_content = "Je... ¿Un animal al que le gusta cultivar flores? ¿Es un poco moe o un poco zorro?",
  ui_story_1018_10180802_124_dialog_content = "¿Tiene cuernos? ¿Alas? ¿Ha visitado muchos lugares...?",
  ui_story_1018_10180802_125_dialog_content = "Capitán, ¿es ella la \"Santa\" de la Iglesia de Lumopolis?",
  ui_story_1018_10180802_126_dialog_content = "Sí.",
  ui_story_1018_10180901_1_dialog_content = "<color=#e8d9bb>Ciudad Gannon</color>",
  ui_story_1018_10180901_2_dialog_content = "Bueno... ¿qué tal si presentamos las noticias así:",
  ui_story_1018_10180901_3_dialog_content = "Debido a los informes de batalla desfavorables que llegan desde Crepúsculo, las familias de los soldados que pronto serán desplegados están luchando con la inminente separación...",
  ui_story_1018_10180901_4_dialog_content = "Oye, ¿podrías usar un tono un poco más optimista? No queremos dar la impresión de que estamos perdiendo la guerra...",
  ui_story_1018_10180901_5_dialog_content = "¿No es esa la verdad? Twilight nunca ha enviado buenas noticias. Si la cosa sigue así nos quedaremos sin noticias que contar...",
  ui_story_1018_10180901_6_dialog_content = "General Hiiro, ¿cómo es que esta vez no estamos reforzando a Twilight sino la línea de defensa?",
  ui_story_1018_10180901_7_dialog_content = "Porque esa es la orden que nos dieron.",
  ui_story_1018_10180901_8_dialog_content = "Pero la batalla en Crepúsculo es muy sospechosa...",
  ui_story_1018_10180901_9_dialog_content = "Canaliza tus preocupaciones en el impulso para resolver la crisis inminente.",
  ui_story_1018_10180901_10_dialog_content = "Si...",
  ui_story_1018_10180901_11_dialog_content = "General, las tropas están listas.",
  ui_story_1018_10180901_12_dialog_content = "¿Qué pasa con las armas enviadas por la jefa de personal?",
  ui_story_1018_10180901_13_dialog_content = "¡En posición!",
  ui_story_1018_10180901_14_dialog_content = "Vamos.",
  ui_story_1018_10180901_15_dialog_content = "¡Sí!",
  ui_story_1018_10180901_16_dialog_content = "¡La Tercera Legión ha partido! Tenemos fe en que la batalla en Crepúsculo puede dar un giro positivo.",
  ui_story_1018_10180901_17_dialog_content = "¿Mmm? El comunicador parece estar captando una señal extraña.",
  ui_story_1018_10180901_18_dialog_content = "¡Yo también lo he notado!",
  ui_story_1018_10180901_19_dialog_content = "¿Es una broma o...? Veamos si podemos aclararlo...",
  ui_story_1018_10180901_20_dialog_content = "El Programa Phospherus es un plan ideado por Ulysses y el Forsakin de Eclipse...",
  ui_story_1018_10180901_21_dialog_content = "¿Qué es esto...?",
  ui_story_1018_10180901_22_dialog_content = "Eres el que envió la señal, ¿verdad?",
  ui_story_1018_10180901_23_dialog_content = "¿Por qué dices eso?",
  ui_story_1018_10180901_24_dialog_content = "Permíteme elaborar.",
  ui_story_1018_10180901_25_dialog_content = "Comenzaste como informante de Essen, ubicado junto a la Gran Mariscal para observar cada uno de sus movimientos.",
  ui_story_1018_10180901_26_dialog_content = "Entonces, te vieron obligado a ayudar a Ulysses a realizar una operación de \"bandera falsa\" en el ejercicio conjunto.",
  ui_story_1018_10180901_27_dialog_content = "A continuación, en el juicio de Reinhardt, finalmente te diste cuenta de que solo eras un peón en una lucha política...",
  ui_story_1018_10180901_28_dialog_content = "Así que expiaste al hacer la vista gorda a lo que hicimos e incluso nos ayudaste en secreto.",
  ui_story_1018_10180901_29_dialog_content = "Simplemente no esperaba que un oficial de inteligencia supiera tanto sobre comunicaciones. ¿Está bien tu superior con esto?",
  ui_story_1018_10180901_30_dialog_content = "Los oficiales de inteligencia recopilan información y también la filtran en el momento adecuado. Estoy haciendo esto por mi cuenta. No tiene nada que ver con nadie más.",
  ui_story_1018_10180901_31_dialog_content = "Veo que hablas en serio.",
  ui_story_1018_10180901_32_dialog_content = "Hacer lo que predicas es cómo juzgo a las personas. Tu información es precisa y tu actitud es firme.",
  ui_story_1018_10180901_33_dialog_content = "Eso significa que ahora creo todo lo que me dijiste en la prisión.",
  ui_story_1018_10180901_34_dialog_content = "<color=#e8d9bb>Hace poco, Vivian hizo su tercera visita a la prisión de Illumina...</color>",
  ui_story_1018_10180901_35_dialog_content = "El hecho de que entramos en la prisión de alta seguridad significa que la información de Anatoli es impecable.",
  ui_story_1018_10180901_36_dialog_content = "Oficial Vivian, dada la gravedad de esta operación, ¿por qué confiarías en la información de un tipo conocido por perjurio?",
  ui_story_1018_10180901_37_dialog_content = "Presentimientos.",
  ui_story_1018_10180901_38_dialog_content = "Wrath pensó que Anatoli tenía una razón desconocida para perjurar, y la forma en que continuó entrometiéndose en nuestro objetivo me dice que está vacilando.",
  ui_story_1018_10180901_39_dialog_content = "Debe haber tomado la decisión de ayudarnos esta vez.",
  ui_story_1018_10180901_40_dialog_content = "Bueno... ¿son estos guardias de patrulla que aparecieron de la nada la llamada \"mano amiga\"?",
  ui_story_1018_10180901_41_dialog_content = "...",
  ui_story_1018_10180901_42_dialog_content = "Jefe de Estado Mayor Vivian, cualquiera que intente ingresar a esta prisión de alta seguridad debe presentar las credenciales relevantes.",
  ui_story_1018_10180901_43_dialog_content = "Ve a consultar con tus superiores sobre eso. No obtuve nada de mi jefe.",
  ui_story_1018_10180901_44_dialog_content = "Tu superior inmediato, Reinhardt, se encuentra actualmente encarcelado dentro de estos muros. Te aconsejo a ti y a tu equipo que lo piensen dos veces antes de continuar.",
  ui_story_1018_10180901_45_dialog_content = "Jefe, parece que su intuición sobre el oficial de inteligencia no fue del todo precisa.",
  ui_story_1018_10180901_46_dialog_content = "Él sería el primero en el que me equivoqué.",
  ui_story_1018_10180901_47_dialog_content = "Pero sigamos con el plan. Pase lo que pase, tenemos que liberar al Gran Mariscal antes de que Hiiro envíe las tropas.",
  ui_story_1018_10180901_48_dialog_content = "Esta es nuestra última oportunidad, ¡así que prepárense para luchar!",
  ui_story_1018_10180901_49_dialog_content = "¡Absolutamente! ¡Para el Gran Mariscal!",
  ui_story_1018_10180901_50_dialog_content = "Jefe de Personal, ¿planea entrar a la fuerza? En ese caso, nosotros...",
  ui_story_1018_10180901_51_dialog_content = "Ay, ay, ay...",
  ui_story_1018_10180901_52_dialog_content = "... Ni siquiera hemos puesto un dedo encima de ti.",
  ui_story_1018_10180901_53_dialog_content = "Manejaré esto.",
  ui_story_1018_10180901_54_dialog_content = "¡Sí, oficial!",
  ui_story_1018_10180901_55_dialog_content = "... Anatoli, ¿qué está pasando? ¡Nos engañaste, verdad!",
  ui_story_1018_10180901_56_dialog_content = "Lo siento, debo eliminar mis dudas de esta manera.",
  ui_story_1018_10180901_57_dialog_content = "¿Qué duda?",
  ui_story_1018_10180901_58_dialog_content = "¿Qué camino elegiste con respecto al futuro de Illumina y hasta dónde estás dispuesto a llegar?",
  ui_story_1018_10180901_59_dialog_content = "¿Cuál es tu conclusión?",
  ui_story_1018_10180901_60_dialog_content = "A partir de mi prolongada observación, el Gran Mariscal es un líder confiable.",
  ui_story_1018_10180901_61_dialog_content = "Como oficial de inteligencia, es un instinto básico dudar de todo, por eso odio la fe ciega.",
  ui_story_1018_10180901_62_dialog_content = "Pero una vez gané la confianza incondicional de alguien, y veo eso de nuevo en ti.",
  ui_story_1018_10180901_63_dialog_content = "Este es el futuro que anhelo, así que elijo estar contigo.",
  ui_story_1018_10180901_64_dialog_content = "Je, perdóname por no confiar en alguien que apuñaló por la espalda al mariscal, aunque disfruté mucho de tu discurso.",
  ui_story_1018_10180901_65_dialog_content = "Habrá muchas oportunidades para que me conozcan. Los patrulleros trabajan para mí, así que ustedes deberían seguir adelante.",
  ui_story_1018_10180901_66_dialog_content = "¡Bienvenido al equipo, intrépido compañero!",
  ui_story_1018_10180901_67_dialog_content = "Omitiré las operaciones de alto perfil, gracias. Estoy acostumbrado a trabajar detrás de escena.",
  ui_story_1018_10180901_68_dialog_content = "Si tienes éxito, tengo algunas fichas que pueden ser útiles.",
  ui_story_1018_10180901_69_dialog_content = "Está bien, tenemos un acuerdo.",
  ui_story_1018_10180901_70_dialog_content = "<color=#e8d9bb>Buzz Buzz...</color>",
  ui_story_1018_10180901_71_dialog_content = "¿Por qué todos los dispositivos hacen ese ruido?",
  ui_story_1018_10180901_72_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1018_10180901_73_dialog_content = "Esto es tan extraño... ¿Se rompió el comunicador? La señal se volvió loca de repente.",
  ui_story_1018_10180901_74_dialog_content = "Aquí igual...",
  ui_story_1018_10180901_75_dialog_content = "¿Qué demonios... está pasando?",
  ui_story_1018_10180901_76_dialog_content = "Parece que el Comité ha hecho un movimiento...",
  ui_story_1018_10180901_77_dialog_content = "Jefe de Estado Mayor, perdimos contacto con las unidades del frente justo cuando ocurrió la falla de comunicación.",
  ui_story_1018_10180901_78_dialog_content = "No puedo creer que se rebajen a este nivel...",
  ui_story_1018_10180901_79_dialog_content = "La Federación nunca ha cortado las comunicaciones con ninguna fuerza defensora cuando bloquearon señales en el pasado.",
  ui_story_1018_10180901_80_dialog_content = "Se nos acabó el tiempo. Cuida tus espaldas, Anatoli.",
  ui_story_1018_10180901_81_dialog_content = "...",
  ui_story_1018_10180901_82_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_1018_10180901_83_dialog_content = "Profesor, la interrupción del canal se ha resuelto. Puedes continuar con la reunión en línea ahora.",
  ui_story_1018_10180901_84_dialog_content = "...",
  ui_story_1018_10180901_85_dialog_content = "Para reducir posibles riesgos, tuve que recurrir a este método.",
  ui_story_1018_10180901_86_dialog_content = "Continuaremos investigando la fuente de la señal. La recuperación completa podría necesitar aún más tiempo.",
  ui_story_1018_10180901_87_dialog_content = "Parece que nos acercamos al momento en que tu plan se revele a todos los compañeros de Illumina, doc.",
  ui_story_1018_10180901_88_dialog_content = "Enviaré a Esien para que lo compruebe de inmediato.",
  ui_story_1018_10180901_89_dialog_content = "El costo de crear una distracción es mucho menor que un enfrentamiento directo. Deberías concentrarte en solucionar las fallas en tus experimentos, Doctor.",
  ui_story_1018_10180901_90_dialog_content = "Entonces, ¿tienes una solución para la batalla en Crepúsculo?",
  ui_story_1018_10180901_91_dialog_content = "Siempre tengo una solución, solo es cuestión de elegir cuál. Dependerá de cómo se desarrollen las cosas.",
  ui_story_1018_10180901_92_dialog_content = "Voy a rectificar los defectos con el cuarto lote de Semillas.",
  ui_story_1018_10180901_93_dialog_content = "Por mi experiencia, es sabio no agotar la paciencia en solo una cosa.",
  ui_story_1018_10180901_94_dialog_content = "¿Alguna buena noticia del Equipo de Reconocimiento de la Zona Oscura?",
  ui_story_1018_10180901_95_dialog_content = "El Equipo de Reconocimiento de la Zona Oscura ha transmitido múltiples imágenes de sospechosos <color=#FFB400>dispositivos réplica</color> que se asemejan al núcleo de Guardian One.",
  ui_story_1018_10180901_96_dialog_content = "Según nuestra evaluación preliminar, el robo del núcleo de Guardian One por parte de Eclipsian parece ser parte de los preparativos para el proyecto relacionado con The Engineer.",
  ui_story_1018_10180901_97_dialog_content = "...",
  ui_story_1018_10180901_98_dialog_content = "La Crisis de Darkover terminó hace 10 años. Mira lo que hemos logrado desde entonces.",
  ui_story_1018_10180901_99_dialog_content = "Tus preocupaciones son infundadas, Máscara de Hierro.",
  ui_story_1018_10180901_100_dialog_content = "Estoy familiarizado con Guardian One. Tomará algún tiempo para que su núcleo sea útil.",
  ui_story_1018_10180901_101_dialog_content = "Por cierto, para acelerar la investigación sobre las semillas, no participaré en ninguna reunión de aquí en adelante. Adiós.",
  ui_story_1018_10180901_102_dialog_content = "Profesor, aquí están los resultados. Por favor, écheles un vistazo.",
  ui_story_1018_10180901_103_dialog_content = "¿Por qué los últimos datos de batalla son tan malos?",
  ui_story_1018_10180901_104_dialog_content = "Profesor, hay una llamada del Comandante Belisaria...",
  ui_story_1018_10180901_105_dialog_content = "Pásalo.",
  ui_story_1018_10180901_106_dialog_content = "Aún quiero recordarte, doctor.",
  ui_story_1018_10180901_107_dialog_content = "Incluso esa chica reclusa apareció, así que eso debería decirte cuánto nos hemos quedado atrás.",
  ui_story_1018_10180901_108_dialog_content = "La incursión descarada de Eclipse significa que la operación en la Zona Oscura se pospone... Si eso cuenta como buenas noticias para ti.",
  ui_story_1018_10180901_109_dialog_content = "¿Qué estás tratando de decir?",
  ui_story_1018_10180901_110_dialog_content = "Puedes seguir experimentando, lástima que el proyecto ya no sea mi máxima prioridad.",
  ui_story_1018_10180901_111_dialog_content = "Cuídate, doctor.",
  ui_story_1018_10180901_112_dialog_content = "...",
  ui_story_1018_10180901_113_dialog_content = "Profesor... ¿Deberíamos continuar con nuestro experimento?",
  ui_story_1018_10180901_114_dialog_content = "Por supuesto, ¡esto no es ni de cerca suficiente para detenernos!",
  ui_story_1018_10180901_115_dialog_content = "¿Algo que debamos mejorar? ¿Pasos, ambiente, evaluaciones?",
  ui_story_1018_10180901_116_dialog_content = "Profesor... creo que estos no son problemas.",
  ui_story_1018_10180901_117_dialog_content = "Tal vez podríamos ajustar el enfoque de investigación...",
  ui_story_1018_10180901_118_dialog_content = "¡Esos son exactamente sus pensamientos!",
  ui_story_1018_10180901_119_dialog_content = "Tecnología Illumina, Chord Link, Semillas... Dime, ¿qué se puede modificar de esos tres?",
  ui_story_1018_10180901_120_dialog_content = "Profesor, la tasa de iteración actual de las Semillas está bien, pero los efectos de mejora en cada versión son apenas notables...",
  ui_story_1018_10180901_121_dialog_content = "Veo que fui demasiado conservador con respecto a la dosis...",
  ui_story_1018_10180901_122_dialog_content = "El tiempo se acaba. ¡Aumenta la dosis extraída del próximo lote de Semillas!",
  ui_story_1018_10180901_123_dialog_content = "Dile a Esien que haga otra conscripción y haga una excepción para que los soldados que fueron rechazados se unan nuevamente al proyecto.",
  ui_story_1018_10180901_124_dialog_content = "...",
  ui_story_1018_10180901_125_dialog_content = "¡Así que el laboratorio del profesor Ulysses es un lugar tan popular, ya veo!",
  ui_story_1018_10180901_126_dialog_content = "Profesor...",
  ui_story_1018_10180901_127_dialog_content = "¿Qué hacen ustedes aquí?",
  ui_story_1018_10180901_128_dialog_content = "Tranquilízate. Acabo de recibir una orden de prestar a mis chicos del laboratorio al médico por unos días.",
  ui_story_1018_10180901_129_dialog_content = "¿El Comité?",
  ui_story_1018_10180901_130_dialog_content = "¿No has recibido el aviso? Oh, tal vez el Coronel Yingel olvidó decírtelo.",
  ui_story_1018_10180901_131_dialog_content = "Sí, también recibí la orden. Tal vez esperan que aceleremos el proyecto trabajando juntos...",
  ui_story_1018_10180901_132_dialog_content = "Belisaria solo está enviando gente para vigilarme...",
  ui_story_1018_10180901_133_dialog_content = "Como sea. No voy a rendirme, de todos modos.",
  ui_story_1018_10180901_134_dialog_content = "Te dejaré encargarte del reclutamiento, Yingel. Mi asistente de al lado te informará.",
  ui_story_1018_10180901_135_dialog_content = "Entiendo...",
  ui_story_1018_10180901_136_dialog_content = "Oficial Técnico Gronru, ¿cuánto saben tus chicos del laboratorio sobre el Programa Phospherus?",
  ui_story_1018_10180901_137_dialog_content = "Oh, puedes preguntarles tú mismo. ¡Todos están ansiosos por aprender!",
  ui_story_1018_10180901_138_dialog_content = "Estoy todo oídos para las enseñanzas del profesor Ulysses.",
  ui_story_1018_10180901_139_dialog_content = "Aquí estás, Coronel Yingel. Hiciste un buen espectáculo allí atrás. ¡No creo que el Profesor Ulysses sospechara de algo!",
  ui_story_1018_10180901_140_dialog_content = "Gracias, Sra. Gronru, aunque no era mi trabajo hacer eso...",
  ui_story_1018_10180901_141_dialog_content = "Pero desde que presencié su experimento personalmente, ya no pude fingir que nada había pasado.",
  ui_story_1018_10180901_142_dialog_content = "Cada vez que cerraba los ojos, podía ver a Axelia luchando contra los soldados en la batalla...",
  ui_story_1018_10180901_143_dialog_content = "Relájate, amable pajarito. Lo hiciste muy bien. Nosotros nos encargaremos de las cosas de la batalla.",
  ui_story_1018_10180901_144_dialog_content = "¿A qué te refieres con eso?",
  ui_story_1018_10180901_145_dialog_content = "Todos en Illumina tienen las mismas preocupaciones que tú, así que, estrictamente hablando, eres tú quien nos está ayudando.",
  ui_story_1018_10180901_146_dialog_content = "Es mi turno de irme después. ¡Llevaré a todos los heridos de vuelta a casa!",
  ui_story_1018_10180901_147_dialog_content = "¿En serio? ¿El Comité también autorizó esto?",
  ui_story_1018_10180901_148_dialog_content = "Eso es para que decidas, Coronel Yingel!",
  ui_story_1018_10180901_149_dialog_content = "...",
  ui_story_1018_10180901_150_dialog_content = "Sra. Gronru, ¿puedo pedirle un favor...",
  ui_story_1018_10180901_151_dialog_content = "Vamos a oírlo.",
  ui_story_1018_10180901_152_dialog_content = "¿Puedo... ir al campo de batalla contigo?",
  ui_story_1018_10180901_153_dialog_content = "Bueno, eso no es un problema, en sí...",
  ui_story_1018_10180901_154_dialog_content = "Pero no te veías bien la última vez que te vi aquí. Si no me equivoco, el sonido de las armas chocando te hace sentir incómodo.",
  ui_story_1018_10180901_155_dialog_content = "Tienes razón. Como soldado, sé que debo portar armas.",
  ui_story_1018_10180901_156_dialog_content = "Pero cuando estoy solo, los sonidos fríos e implacables de la batalla retumban en mis oídos y me asustan hasta dejarme paralizado...",
  ui_story_1018_10180901_157_dialog_content = "Sin embargo, Illumina me necesita ahora y debo hacer algo, tal como le dije al Oficial Vivian...",
  ui_story_1018_10180901_158_dialog_content = "Oh, Vivian está—oops, casi lo suelto.",
  ui_story_1018_10180901_159_dialog_content = "El pequeño pajarito amable tiene que encontrar su propio camino. ¡Ven a verme al patio cuando estés listo!",
  ui_story_1018_10180901_160_dialog_content = "Claro. Gracias, señorita Gronru.",
  ui_story_1018_10181002_1_dialog_content = "Capitán de la guardia, el fango se ha dispersado en su mayor parte y ahora no hay señales de actividad de eclipses alrededor de Crepúsculo.",
  ui_story_1018_10181002_2_dialog_content = "Con nuestra ayuda, la misión de búsqueda y rescate de Illumina se ha completado. El Gran Mariscal Wrath está recopilando información de sus subordinados.",
  ui_story_1018_10181002_3_dialog_content = "Entendido. En espera después de que las tropas estén listas.",
  ui_story_1018_10181002_4_dialog_content = "Veo que así es como se ve Crepúsculo sin el barro, un lugar bullicioso.",
  ui_story_1018_10181002_5_dialog_content = "Sí, Lady Santa, aquí solía ser el mercado y todavía se pueden distinguir apenas los puestos.",
  ui_story_1018_10181002_6_dialog_content = "La pared rota de allí solía cercar un pequeño macizo de flores.",
  ui_story_1018_10181002_7_dialog_content = "Es extraño, pero había muchas variedades de flores en el jardín y florecían durante todo el año.",
  ui_story_1018_10181002_8_dialog_content = "A los niños les encantaba jugar aquí, y a mí también cuando era pequeño.",
  ui_story_1018_10181002_9_dialog_content = "Pero su área de juegos ha sido arruinada por los Eclipsites.",
  ui_story_1018_10181002_10_dialog_content = "Aunque sí creo que las flores volverán a florecer.",
  ui_story_1018_10181002_11_dialog_content = "Y creo que bajo el cuidado de la señorita Joselyne, los niños disfrutarán de la vida aquí de nuevo.",
  ui_story_1018_10181002_12_dialog_content = "¡Ya puedo escuchar sus risas!",
  ui_story_1018_10181002_13_dialog_content = "Gracias por su aliento, ¡Lady Santa! Pero me preocupa que...",
  ui_story_1018_10181002_14_dialog_content = "Los Eclipsites no solo destruyeron hogares, sino también la confianza que la gente de Crepúsculo tenía en los guerreros...",
  ui_story_1018_10181002_15_dialog_content = "Tal vez no crean que este lugar les brindará comodidad y paz nuevamente.",
  ui_story_1018_10181002_16_dialog_content = "Creo que sí.",
  ui_story_1018_10181002_17_dialog_content = "Leo...?",
  ui_story_1018_10181002_18_dialog_content = "Bajo el barro yacen los guerreros que se sacrificaron en esta batalla.",
  ui_story_1018_10181002_19_dialog_content = "Crepúsculo comenzó como un lugar construido sobre los cuerpos de los soldados. La situación actual solo les convenció de que la guerra siempre existirá.",
  ui_story_1018_10181002_20_dialog_content = "Mientras haya personas dispuestas a vivir aquí, la determinación de proteger Crepúsculo nunca flaqueará.",
  ui_story_1018_10181002_21_dialog_content = "Antes de esto, Crepúsculo era mi zona de confort.",
  ui_story_1018_10181002_22_dialog_content = "Sin esta campaña, probablemente seguiría preocupado por cuándo caerá la ciudad y dudaría en avanzar.",
  ui_story_1018_10181002_23_dialog_content = "El resultado actual es una oportunidad para que tanto Crepúsculo como yo reevaluemos nuestras opiniones.",
  ui_story_1018_10181002_24_dialog_content = "Leo, ¿lo que acabas de decir indica que has cambiado tu perspectiva sobre Lumopolis?",
  ui_story_1018_10181002_25_dialog_content = "No, señora Carleen, lamento decepcionarte.",
  ui_story_1018_10181002_26_dialog_content = "Sin embargo, la acción del Mariscal Wrath me hizo darme cuenta de que cualquier descontento con una situación no puede ser simplemente superficial.",
  ui_story_1018_10181002_27_dialog_content = "Debo hacer el cambio para que mi habilidad esté a la altura de mi ambición.",
  ui_story_1018_10181002_28_dialog_content = "Les prometo a todos ustedes que el futuro de Crepúsculo también es el mío.",
  ui_story_1018_10181002_29_dialog_content = "¿Eso te tranquilizó más ahora, Joselyne?",
  ui_story_1018_10181002_30_dialog_content = "Leo, estoy muy conmovido por lo que dijiste...",
  ui_story_1018_10181002_31_dialog_content = "¡Creo que Crepúsculo puede ser reconstruido y mejor que nunca!",
  ui_story_1018_10181002_32_dialog_content = "De hecho, he estado pensando en una idea y me pregunto si Su Santidad la Santa podría ofrecerme alguna orientación.",
  ui_story_1018_10181002_33_dialog_content = "Su Santidad, aún tenemos asuntos urgentes que atender.",
  ui_story_1018_10181002_34_dialog_content = "Sí, pero ¿puedo intercambiar algunas palabras más con Joselyne?",
  ui_story_1018_10181002_35_dialog_content = "Señora Joselyne, por favor hazlo corto.",
  ui_story_1018_10181002_36_dialog_content = "Lady Santa, quiero construir una iglesia en Crepúsculo que albergue a todas las personas, no solo a los seguidores del Dios de la Luz.",
  ui_story_1018_10181002_37_dialog_content = "Aurorianos, semihumanos, Caelestites, incluso aquellos obligados a inclinarse hacia la oscuridad...",
  ui_story_1018_10181002_38_dialog_content = "Puede que no sean aceptados en sus campamentos, pero todos los que pisan Crepúsculo pueden quedarse, siempre y cuando tengan amor y compasión en su corazón.",
  ui_story_1018_10181002_39_dialog_content = "El crepúsculo no debería tener solo puestas de sol, sino ser iluminado por la luz.",
  ui_story_1018_10181002_40_dialog_content = "Al igual que las personas en Astra y otros lugares, deberían poder ver la luz del día, la luna y las estrellas.",
  ui_story_1018_10181002_41_dialog_content = "Sé que es un trabajo muy duro, pero espero recibir sus bendiciones primero.",
  ui_story_1018_10181002_42_dialog_content = "Eres tan piadosa y generosa, Sra. Joselyne.",
  ui_story_1018_10181002_43_dialog_content = "Al igual que los aurorianos originales que se aventuraron hacia el sur para predicar, también es un desafío para ti construir tu iglesia ideal aquí.",
  ui_story_1018_10181002_44_dialog_content = "Pero la luz sagrada puede iluminar cada rincón de la fe, especialmente bajo tu guía.",
  ui_story_1018_10181002_45_dialog_content = "Da el paso si estás dispuesto. Cuentas con mi apoyo.",
  ui_story_1018_10181002_46_dialog_content = "¡Gracias, Lady Santa! ¡Nunca olvidaré esto!",
  ui_story_1018_10181002_47_dialog_content = "Uf... ¿Fue ese un buen discurso?",
  ui_story_1018_10181002_48_dialog_content = "Su elección de palabras es impecable, Su Santidad. Pero es hora de que sigamos adelante.",
  ui_story_1018_10181002_49_dialog_content = "Está bien, te dejo tomarlo desde aquí.",
  ui_story_1018_10181002_50_dialog_content = "Oh, Carleen, una vez que Crepúsculo esté seguro, ve al frente y únete al ejército del Señor de la Ciudad.",
  ui_story_1018_10181002_51_dialog_content = "¡¿Él envió tropas al frente de batalla?!",
  ui_story_1018_10181002_52_dialog_content = "Pero, ¿por qué parecía tan apático en la cancha?",
  ui_story_1018_10181002_53_dialog_content = "Bueno, él mencionó \"Aprovechar al máximo la situación\"... Tampoco estoy seguro.",
  ui_story_1018_10181002_54_dialog_content = "No solo el ejército del Señor de la Ciudad, sino también los colegas del Mariscal.",
  ui_story_1018_10181002_55_dialog_content = "¿No ha terminado la batalla?",
  ui_story_1018_10181002_56_dialog_content = "Descansa tranquilo, la batalla en Crepúsculo ha terminado.",
  ui_story_1018_10181002_57_dialog_content = "Pero la guerra apenas está comenzando para los Aurorianos, razón por la cual dejé el Templo.",
  ui_story_1018_10181002_58_dialog_content = "Me complace mucho conocerte en mi viaje. Rezaré por ti.",
  ui_story_1018_10181002_59_dialog_content = "May Que el Dios de la Luz esté contigo. Espero ansiosamente el momento en que nos volvamos a encontrar.",
  ui_story_1018_10181002_60_dialog_content = "El eterno Dios de la Luz.",
  ui_story_1018_10181002_61_dialog_content = "Noche Blanca en lo alto.",
  ui_story_1018_10181002_62_dialog_content = "Los Eclipsites no se retiraron, sino que se trasladaron al frente de Illumina. No creo que terminemos fácilmente con este ascenso de Darkover...",
  ui_story_1018_10181002_63_dialog_content = "Veo que todos lo saben.",
  ui_story_1018_10181002_64_dialog_content = "Gran Mariscal Wrath! Al menos la Dama Santa dijo que Crepúsculo está fuera de peligro por ahora.",
  ui_story_1018_10181002_65_dialog_content = "La ciudad sobrevivió, ¡gracias al esfuerzo conjunto de Illumina y los Caballeros!",
  ui_story_1018_10181002_66_dialog_content = "Gracias por el reconocimiento, pero no es necesario consolarme, Joselyne.",
  ui_story_1018_10181002_67_dialog_content = "De hecho, me siento agradecido de que la situación se esté volviendo clara.",
  ui_story_1018_10181002_68_dialog_content = "Tuvimos éxito en términos de resultado, pero para mí, fue un fracaso catastrófico...",
  ui_story_1018_10181002_69_dialog_content = "Gran Mariscal Wrath, Illumina no puede enfrentar el actual predicamento por sí sola.",
  ui_story_1018_10181002_70_dialog_content = "Lumopolis no debería haberse quedado de brazos cruzados cuando la batalla en Crepúsculo estaba progresando desfavorablemente.",
  ui_story_1018_10181002_71_dialog_content = "Ahora el ejército del Señor de la Ciudad se está reuniendo en el frente, sin importar cómo reaccione Illumina, Lumopolis no volverá a ser un espectador.",
  ui_story_1018_10181002_72_dialog_content = "No entendiste, Lady Carleen. Solo el fracaso podría darle sentido a todo esto.",
  ui_story_1018_10181002_73_dialog_content = "La campaña de Crepúsculo, los soldados sacrificados y el proyecto de los superiores... Todos deben terminar en mi fracaso.",
  ui_story_1018_10181002_74_dialog_content = "Esa es la única manera para que Illumina tenga un futuro.",
  ui_story_1018_10181002_75_dialog_content = "Gran Mariscal, ¿tú y tus colegas están planeando algo?",
  ui_story_1018_10181002_76_dialog_content = "Debo confirmar en lo que creo firmemente por mí mismo, sin importar los peligros que me esperen en el frente.",
  ui_story_1018_10181002_77_dialog_content = "Me preocupa que lo que le pasó a Crepúsculo pueda pasarle a Illumina.",
  ui_story_1018_10181002_78_dialog_content = "¿No dijo Axelia que Forsakin también llevó a sus soldados?",
  ui_story_1018_10181002_79_dialog_content = "Mientras sean ellos defendiendo, aún de carne y hueso, estoy seguro de que no será una repetición.",
  ui_story_1018_10181002_80_dialog_content = "Prometí a los soldados caídos que los llevaría de vuelta a Illumina, sin importar qué.",
  ui_story_1018_10181002_81_dialog_content = "Hablaremos de Crepúsculo más tarde. Mi ejército Illumina regresará al frente.",
  ui_story_1018_10181002_82_dialog_content = "Si es a donde te diriges, los Caballeros del Crepúsculo te acompañarán.",
  ui_story_1018_10181002_83_dialog_content = "Los adversarios aún no han sido eliminados, así que seguimos siendo aliados.",
  ui_story_1018_10181002_84_dialog_content = "¡Está bien! No olvidaré a nuestros aliados de Crepúsculo.",
  ui_story_1018_10181002_85_dialog_content = "En ese caso, ¿puedo llevarlos en un dirigible de Lumopolis, Leo y Gran Mariscal Wrath?",
  ui_story_1018_10181002_86_dialog_content = "Respetuosamente rechazo. Los caballeros estamos acostumbrados a montar a caballo en batalla, no a utilizar vehículos aéreos.",
  ui_story_1018_10181002_87_dialog_content = "Gracias por la oferta, Lady Carleen, pero eso no cumple con los procedimientos de Illumina.",
  ui_story_1018_10181002_88_dialog_content = "Pero puedo ver que los soldados están agotados. Quizás puedan tomar un descanso en el dirigible.",
  ui_story_1018_10181002_89_dialog_content = "Carleen tiene razón. Si nos enfrentamos a una batalla difícil, deberían descansar un poco ahora.",
  ui_story_1018_10181002_90_dialog_content = "Tampoco creo que los soldados heridos puedan manejar el viaje a pie.",
  ui_story_1018_10181002_91_dialog_content = "Entonces, ¿incluso tú conoces las claves para liderar un ejército en la batalla ahora?",
  ui_story_1018_10181002_92_dialog_content = "Supongo que Crepúsculo es un verdadero campo de entrenamiento.",
  ui_story_1018_10181002_93_dialog_content = "Gran Mariscal, entonces obedeceremos humildemente su orden.",
  ui_story_1018_10181002_94_dialog_content = "Capitán, ¿deberíamos...?",
  ui_story_1018_10181002_95_dialog_content = "...",
  ui_story_1018_10181002_96_dialog_content = "Vamos, Leo.",
  ui_story_1018_10181002_97_dialog_content = "Deja de divagar si vamos a eliminar enemigos juntos, Caballero.",
  ui_story_1018_10181002_98_dialog_content = "¡Seguro!",
  ui_story_1018_10181101_1_dialog_content = "<color=#e8d9bb>Línea de defensa de Illumina</color>",
  ui_story_1018_10181101_2_dialog_content = "Comandante, hemos confirmado que los caballeros avistados en las líneas de defensa este y oeste son de Lumopolis.",
  ui_story_1018_10181101_3_dialog_content = "Hasta ahora, no se han detectado signos de Eclipsites en las líneas de defensa este y oeste. Los caballeros de Lumopolis y nuestras unidades defensivas están manteniendo una vigilancia cercana.",
  ui_story_1018_10181101_4_dialog_content = "Entiendo.",
  ui_story_1018_10181101_5_dialog_content = "¿Algún cambio en su movimiento?",
  ui_story_1018_10181101_6_dialog_content = "Su ruta es la misma de siempre: recta desde el centro, avanzando hacia el interior de forma vertical. Nuestras unidades de asalto están enfrentando al enemigo de frente y listas para romper sus formaciones.",
  ui_story_1018_10181101_7_dialog_content = "Su objetivo aún es desconocido, así que el escuadrón de asalto simplemente debe contener a los Eclipsites desde las trincheras.",
  ui_story_1018_10181101_8_dialog_content = "Pero, Comandante... incluso si rechazamos a un enjambre de Eclipsites, simplemente enviarán al siguiente. ¿Realmente estamos bien si seguimos defendiendo así?",
  ui_story_1018_10181101_9_dialog_content = "Los Eclipsites solo nos están probando, no intentan lanzar un ataque.",
  ui_story_1018_10181101_10_dialog_content = "No podemos ser precipitados hasta que los hayamos entendido.",
  ui_story_1018_10181101_11_dialog_content = "¿Cómo va todo con las fortificaciones?",
  ui_story_1018_10181101_12_dialog_content = "El General Barton está supervisando los asuntos de defensa entre las Subciudades, y las fuerzas bajo el mando del General Hiiro deberían llegar pronto a la línea defensiva.",
  ui_story_1018_10181101_13_dialog_content = "La falla en el equipo de comunicación anterior aún no se ha solucionado. Por lo tanto, ya hemos enviado notificaciones según su solicitud. Las operaciones de combate terrestre ahora están en manos de las fuerzas del frente.",
  ui_story_1018_10181101_14_dialog_content = "Cada una de las Subciudades está dedicada a su propia estrategia de defensa y no responderá a acciones a lo largo de la línea defensiva.",
  ui_story_1018_10181101_15_dialog_content = "Vale. ¿Todavía no hay noticias de Crepúsculo?",
  ui_story_1018_10181101_16_dialog_content = "Sin noticias del Gran Mariscal. Pero a juzgar por la mayor vigilancia de las tropas de Lumopolis, la batalla en Crepúsculo debería estar llegando a su fin.",
  ui_story_1018_10181101_17_dialog_content = "Espero que haya salido como esperabas.",
  ui_story_1018_10181101_18_dialog_content = "¡Comandante! Fuera de la línea defensiva, pantanos han aparecido repentinamente en la trinchera y atraparon a algunos soldados.",
  ui_story_1018_10181101_19_dialog_content = "¡El ataque de los Eclipsites esta vez es mucho más feroz que antes!",
  ui_story_1018_10181101_20_dialog_content = "¿En las trincheras? No había habido señales de que el atolladero se extendiera antes.",
  ui_story_1018_10181101_21_dialog_content = "Comandante, la expansión del pantano no fue gradual, ¡surgió repentinamente desde el subsuelo!",
  ui_story_1018_10181101_22_dialog_content = "Como describieron los soldados, inicialmente, solo había algo de barro en la trinchera, y luego, de repente, el barro se agitó, acumulándose como loco!",
  ui_story_1018_10181101_23_dialog_content = "¡Ya se ha extendido a las barreras adyacentes!",
  ui_story_1018_10181101_24_dialog_content = "...",
  ui_story_1018_10181101_25_dialog_content = "Informa de la situación a los Caballeros Lumo en el frente occidental y traslada las reservas al centro, ¡rápido!",
  ui_story_1018_10181101_26_dialog_content = "¡Comandos, síganme al frente central!",
  ui_story_1018_10181101_27_dialog_content = "¡Sí!",
  ui_story_1018_10181101_28_dialog_content = "¿A esto le llaman barrera? Era así hace diez años y sigue igual diez años después.",
  ui_story_1018_10181101_29_dialog_content = "Alimento—",
  ui_story_1018_10181101_30_dialog_content = "No estás aquí para comer. Solo tienes que llevar a esos compañeros competentes.",
  ui_story_1018_10181101_31_dialog_content = "Pronto, surgirá el paso de la Zona Oscura al corazón del territorio.",
  ui_story_1018_10181101_32_dialog_content = "La llama azul está ardiendo—",
  ui_story_1018_10181101_33_dialog_content = "Je, te mueves rápido, debo decir.",
  ui_story_1018_10181101_34_dialog_content = "Oh, eres tú, el traidor.",
  ui_story_1018_10181101_35_dialog_content = "Je, tetera, hervidor, negro. ¿Olvidaste a los soldados que mataste?",
  ui_story_1018_10181101_36_dialog_content = "¡Tonto ignorante! ¿Mataste a todos los soldados de Crepúsculo?",
  ui_story_1018_10181101_37_dialog_content = "No todos. Bastantes murieron a manos de sus compañeros, aunque eso encaja con la tradición de Illumina de usar y olvidar.",
  ui_story_1018_10181101_38_dialog_content = "¡Cállate y prepárate para morir!",
  ui_story_1018_10181101_39_dialog_content = "El que se encontrará con la muerte eres tú. Ese nuevo Gran Mariscal tuyo sufrió mucho antes que ellos.",
  ui_story_1018_10181101_40_dialog_content = "¿Ellos?",
  ui_story_1018_10181101_41_dialog_content = "¿Te parece familiar? Eso es lo que obtiene por intentar ser astuta.",
  ui_story_1018_10181101_42_dialog_content = "¿Qué pasa con Wrath?",
  ui_story_1018_10181101_43_dialog_content = "Solo es cuestión de tiempo hasta que ella muera. Luego será tu turno de ser el Gran Mariscal.",
  ui_story_1018_10181101_44_dialog_content = "¡No puedes insultar al Gran Mariscal!",
  ui_story_1018_10181101_45_dialog_content = "Grah!",
  ui_story_1018_10181101_46_dialog_content = "...",
  ui_story_1018_10181101_47_dialog_content = "¿Qué, no puedes hacerlo? Tienes que decidirte rápido.",
  ui_story_1018_10181101_48_dialog_content = "Comandante, en realidad desapareció en el pantano...",
  ui_story_1018_10181101_49_dialog_content = "Espera, ¿el pantano ya está tragando a Crepúsculo, extendiéndose aquí desde abajo...",
  ui_story_1018_10181101_50_dialog_content = "La línea defensiva de Illumina... ¿También será devorada?",
  ui_story_1018_10181101_51_dialog_content = "Mata a los Eclipsites primero y espera mi actualización sobre lo que está pasando debajo de las trincheras.",
  ui_story_1018_10181101_52_dialog_content = "Ya que salió de debajo de la tierra, sería más rápido meterse con las ciudades subterráneas.",
  ui_story_1018_10181101_53_dialog_content = "¡No entres en pánico y mantén la línea!",
  ui_story_1018_10181101_54_dialog_content = "¡Entendido!",
  ui_story_1018_10181101_55_dialog_content = "Equipo de asalto, retrocedan junto a la pared y eliminen a los Eclipsites.",
  ui_story_1018_10181101_56_dialog_content = "Grah!",
  ui_story_1018_10181101_57_dialog_content = "Comandante, él... ¿es uno de nuestros soldados de Illumina?",
  ui_story_1018_10181101_58_dialog_content = "Lleno de Darkflow, devorando Eclipsites, dañando a compañeros...",
  ui_story_1018_10181101_59_dialog_content = "¡Son Eclipsites, sin piedad!",
  ui_story_1018_10181101_60_dialog_content = "¡E-Entendido, Comandante!",
  ui_story_1018_10181102_1_dialog_content = "<color=#e8d9bb>¡Boooom!</color>",
  ui_story_1018_10181102_2_dialog_content = "¡Las artillerías están en acción! ¡Parece que los pantanos han dejado de extenderse!",
  ui_story_1018_10181102_3_dialog_content = "¡Los Eclipsites también se han detenido!",
  ui_story_1018_10181102_4_dialog_content = "¡Sus órdenes llegan justo a tiempo, Comandante!",
  ui_story_1018_10181102_5_dialog_content = "No di la orden...",
  ui_story_1018_10181102_6_dialog_content = "Esos proyectiles fueron disparados desde tres fortificaciones diferentes.",
  ui_story_1018_10181102_7_dialog_content = "Podría ser...",
  ui_story_1018_10181102_8_dialog_content = "¡Oh sí, qué emoción! ¡Hacía mucho tiempo que no me emocionaba tanto un bombardeo!",
  ui_story_1018_10181102_9_dialog_content = "Un poco desviado del objetivo, pero aún se logró el resultado esperado.",
  ui_story_1018_10181102_10_dialog_content = "Comandante, ¡es el General Barton y el General Hiiro!",
  ui_story_1018_10181102_11_dialog_content = "¡De verdad son ellos! ¡Vienen a apoyarnos!",
  ui_story_1018_10181102_12_dialog_content = "El fortalecimiento de la Subciudad salió bien, ¡y no me iba a perder esta pelea por nada del mundo!",
  ui_story_1018_10181102_13_dialog_content = "No hay razón para perdérselo cuando la pelea ya está en tu puerta.",
  ui_story_1018_10181102_14_dialog_content = "Estoy realmente agradecido por la ayuda de ambos. Los Eclipsites están actualmente bajo control.",
  ui_story_1018_10181102_15_dialog_content = "Sin embargo, se detectó un pantano en las trincheras y me preocupa que se filtre en la ciudad subterránea.",
  ui_story_1018_10181102_16_dialog_content = "No vimos señales de eso en nuestro camino hasta aquí. Probablemente los enemigos acaban de llegar también.",
  ui_story_1018_10181102_17_dialog_content = "Eso es correcto, he estado vigilando el perímetro como un halcón.",
  ui_story_1018_10181102_18_dialog_content = "El lodo inundó Crepúsculo, y Forsakin está involucrado...",
  ui_story_1018_10181102_19_dialog_content = "De todos modos, lo enfrentaremos juntos.",
  ui_story_1018_10181102_20_dialog_content = "Solo estamos esperando a Wrath. Esperamos que todo salga según lo planeado...",
  ui_story_1018_10181102_21_dialog_content = "Creo que sí.",
  ui_story_1018_10181102_22_dialog_content = "Gran Mariscal!",
  ui_story_1018_10181102_23_dialog_content = "¡También creo en Wrath!",
  ui_story_1018_10181102_24_dialog_content = "¡Jefe de Personal! ¿Qué haces aquí?",
  ui_story_1018_10181102_25_dialog_content = "De acuerdo con el plan de Wrath, si los Eclipsites atacaban el frente, yo sería el último en desplegarme.",
  ui_story_1018_10181102_26_dialog_content = "El Gran Mariscal también actuará conmigo después de recibir la orden.",
  ui_story_1018_10181102_27_dialog_content = "Entonces, ¿eso significa que uno de los tres grandes cañones estaba bajo el control del Gran Mariscal?",
  ui_story_1018_10181102_28_dialog_content = "No he <color=#FFB400>conducido un carruaje con cañón</color> desde hace un tiempo, pero creo que aún lo tengo.",
  ui_story_1018_10181102_29_dialog_content = "Gran Mariscal, ¿cómo hiciste...",
  ui_story_1018_10181102_30_dialog_content = "¡Oh, casi lo olvido!",
  ui_story_1018_10181102_31_dialog_content = "Operación: Fuga de la prisión es un éxito para la Jefa de Personal Vivian, ¡Señora!",
  ui_story_1018_10181102_32_dialog_content = "Guau...",
  ui_story_1018_10181102_33_dialog_content = "Gran Mariscal, el Capitán Sharona de la 1ª Legión mantuvo la línea y negó la entrada a todos los Eclipsites.",
  ui_story_1018_10181102_34_dialog_content = "Mientras yo, Capitán Barton de la 2ª Legión, esté presente, ¡ningún Eclipsite entrará en la ciudad subterránea!",
  ui_story_1018_10181102_35_dialog_content = "Capitán Hiiro de la 3ra Legión, responsable del refuerzo final, ha completado la tarea.",
  ui_story_1018_10181102_36_dialog_content = "Muy bien hecho, todos ustedes. Y buen trabajo a todos mis compañeros de Illumina.",
  ui_story_1018_10181102_37_dialog_content = "Los generales y el Gran Mariscal están todos aquí... Todavía me cuesta creerlo...",
  ui_story_1018_10181102_38_dialog_content = "Gran Mariscal!",
  ui_story_1018_10181102_39_dialog_content = "¡Salve!",
  ui_story_1018_10181201_1_dialog_content = "Comandante, no se encontró rastro de Forsakin en la trinchera.",
  ui_story_1018_10181201_2_dialog_content = "Actualmente, los caballeros de Lumopolis todavía mantienen la línea de defensa, y se dice que el refuerzo que se dirige a Twilight ya está en camino de regreso.",
  ui_story_1018_10181201_3_dialog_content = "Copiado. Informa de inmediato cuando veas el refuerzo.",
  ui_story_1018_10181201_4_dialog_content = "Parece que Lumopolis no tiene intención de involucrarse en la batalla.",
  ui_story_1018_10181201_5_dialog_content = "No estamos seguros de lo que está pasando en Crepúsculo, pero aún hay espacio para la esperanza. Solo me preocupo por Wrath...",
  ui_story_1018_10181201_6_dialog_content = "Es cierto, no ha habido ninguna actualización de Crepúsculo desde hace mucho tiempo.",
  ui_story_1018_10181201_7_dialog_content = "Es mi negligencia. Me he quedado aquí desde que Wrath fue a Crepúsculo.",
  ui_story_1018_10181201_8_dialog_content = "Si atacara, la línea podría caer, pero si retrocediera detrás de la línea, podría perderme el informe que sale de Crepúsculo.",
  ui_story_1018_10181201_9_dialog_content = "No pude llegar al fondo del atolladero que se extendía y dejé escapar a Forsakin.",
  ui_story_1018_10181201_10_dialog_content = "No es tu culpa. Escuché sobre la situación en Crepúsculo en el camino y el enemigo utilizó un ataque sin precedentes, así que todos deben tener cuidado.",
  ui_story_1018_10181201_11_dialog_content = "Algo se acerca rápidamente desde el barro adelante, Gran Mariscal.",
  ui_story_1018_10181201_12_dialog_content = "¡Tiene un deseo de muerte! ¡Permíteme cumplirlo!",
  ui_story_1018_10181201_13_dialog_content = "Ten cuidado con el pantano, Forsakin podría estar acechando.",
  ui_story_1018_10181201_14_dialog_content = "¿Atacas la línea escabulléndote como un ratón?",
  ui_story_1018_10181201_15_dialog_content = "¡Golpe de leopardo!",
  ui_story_1018_10181201_16_dialog_content = "Trágate todo—",
  ui_story_1018_10181201_17_dialog_content = "¿Finalmente te muestras, gusano?!",
  ui_story_1018_10181201_18_dialog_content = "Graaaaah-!",
  ui_story_1018_10181201_19_dialog_content = "¡Comandante! ¡Los Eclipsites están emergiendo de los pantanos y una fuerza considerable de soldados no identificados se dirige hacia la línea defensiva!",
  ui_story_1018_10181201_20_dialog_content = "¡Por favor, dé su orden, Gran Mariscal!",
  ui_story_1018_10181201_21_dialog_content = "...",
  ui_story_1018_10181201_22_dialog_content = "No daré órdenes. No soy el comandante de esta batalla.",
  ui_story_1018_10181201_23_dialog_content = "Pero Gran Mariscal...",
  ui_story_1018_10181201_24_dialog_content = "No es negociable. Estoy en esta pelea como un ciudadano privado.",
  ui_story_1018_10181201_25_dialog_content = "Todos, simplemente hagan lo que deben hacer.",
  ui_story_1018_10181201_26_dialog_content = "...",
  ui_story_1018_10181201_27_dialog_content = "En ese caso, ¡no quiero registrar las balas aquí en vano! Apunta, ¡arma del lado este!",
  ui_story_1018_10181201_28_dialog_content = "¡Apunta, arma del lado oeste!",
  ui_story_1018_10181201_29_dialog_content = "Comandante, las legiones defensivas en los lados este y oeste están reunidas y listas.",
  ui_story_1018_10181201_30_dialog_content = "Reservas del este y oeste, busquen Forsakin a lo largo del pantano. ¡Equipo de asalto, prepárense para atacar a los Eclipsites!",
  ui_story_1018_10181201_31_dialog_content = "Espera, Sharona, ¿no son esos Eclipsites cubiertos de lodo soldados de Illumina?",
  ui_story_1018_10181201_32_dialog_content = "...",
  ui_story_1018_10181201_33_dialog_content = "Algunos de ellos están ligeramente conscientes, pero muchos se han convertido irreversiblemente en Eclipsites.",
  ui_story_1018_10181201_34_dialog_content = "¿Cómo hacemos...",
  ui_story_1018_10181201_35_dialog_content = "Te ayudare.",
  ui_story_1018_10181201_36_dialog_content = "Gran Mariscal...",
  ui_story_1018_10181201_37_dialog_content = "No te preocupes. Los salvaré mientras haya esperanza.",
  ui_story_1018_10181201_38_dialog_content = "Pero Gran Mariscal, se alimentan de soldados. Solo que...",
  ui_story_1018_10181201_39_dialog_content = "Yo también lo haría si fuera tú, pero mi cuerpo podría resistir su mordida.",
  ui_story_1018_10181201_40_dialog_content = "Sigue liderando a tus soldados. El equipo para transportar a los heridos ya está en camino.",
  ui_story_1018_10181201_41_dialog_content = "Sí, Gran Mariscal.",
  ui_story_1018_10181201_42_dialog_content = "<color=#e8d9bb>¡Boooom!</color>",
  ui_story_1018_10181201_43_dialog_content = "Es... el fuego de artillería del Comandante Hiiro, ¡impactando justo en el centro del pantano!",
  ui_story_1018_10181201_44_dialog_content = "Aún no hay disparos de los artilleros del oeste.",
  ui_story_1018_10181201_45_dialog_content = "No me mires, tampoco a mi lado.",
  ui_story_1018_10181201_46_dialog_content = "Eso solo puede significar...",
  ui_story_1018_10181201_47_dialog_content = "Je, ¿pensaste que podrías detener Mudbundle?",
  ui_story_1018_10181201_48_dialog_content = "Destruyó Crepúsculo.",
  ui_story_1018_10181201_49_dialog_content = "Lodo entrante—",
  ui_story_1018_10181201_50_dialog_content = "Ya destruiste el Crepúsculo, Forsakin, ¿por qué estás atacando el frente ahora?",
  ui_story_1018_10181201_51_dialog_content = "Vamos, no me digas que sigues del lado de Illumina después de que te metieron en una celda.",
  ui_story_1018_10181201_52_dialog_content = "En lugar de hacerlo de la manera difícil, ¿por qué no simplemente abres la puerta y me dejas incinerar a aquellos que te tendieron una trampa?",
  ui_story_1018_10181201_53_dialog_content = "Illumina sigue sus propias reglas y principios. Hasta aquí llegas.",
  ui_story_1018_10181201_54_dialog_content = "Sigues interpretando al noble, veo. No es de extrañar que te hayan arrastrado por el lodo.",
  ui_story_1018_10181201_55_dialog_content = "¡No le hables así al Gran Mariscal!",
  ui_story_1018_10181201_56_dialog_content = "Abre los ojos, perro faldero. No hay ningún Gran Mariscal aquí.",
  ui_story_1018_10181201_57_dialog_content = "¿No hay Gran Mariscal? Creo que hablaste demasiado pronto.",
  ui_story_1018_10181201_58_dialog_content = "<color=#e8d9bb>La tierra temblorosa resonaba con ruedas atronadoras y cascos galopantes...</color>",
  ui_story_1018_10181201_59_dialog_content = "Aterrizar temprano fue, de hecho, la decisión correcta. ¡Es más práctico movernos en tierra!",
  ui_story_1018_10181201_60_dialog_content = "El enemigo no tendrá adónde huir una vez que crucemos las trincheras. ¡Todas las armas, disparen al pantano!",
  ui_story_1018_10181201_61_dialog_content = "Oye, la línea de Illumina está realmente activa. Su plan de ataque sigue siendo tan directo como siempre.",
  ui_story_1018_10181201_62_dialog_content = "Eso lo hace aún mejor. Seremos el último muro para encerrarla.",
  ui_story_1018_10181201_63_dialog_content = "Axelia recuperará a todos los subordinados...",
  ui_story_1018_10181201_64_dialog_content = "¿Te recuperaste tan rápido? Axelia debe estar construido como un mecha de Illumina...",
  ui_story_1018_10181201_65_dialog_content = "Creo que Axelia está aún mejor para estar como nueva ahora con todo el daño que recibió.",
  ui_story_1018_10181201_66_dialog_content = "Prepárate para luchar, PlayerName. Todavía nos quedan Eclipsites por eliminar antes de llegar a nuestra parada.",
  ui_story_1018_10181201_67_dialog_content = "No hay problema.",
  ui_story_1018_10181201_68_dialog_content = "Entonces manténganse firmes. Los artilleros derribarán a los rezagados como si fueran Eclipsites.",
  ui_story_1018_10181201_69_dialog_content = "Entiendo...",
  ui_story_1018_10181201_70_dialog_content = "<color=#e8d9bb>Sonido metálico seco-</color>",
  ui_story_1018_10181201_71_dialog_content = "¡Cuidado! ¡Desvíate!",
  ui_story_1018_10181201_72_dialog_content = "Engine VII? ¡Surgiendo repentinamente... de la trinchera!",
  ui_story_1018_10181201_73_dialog_content = "Esa es la que resultó dañada en Crepúsculo...",
  ui_story_1018_10181201_74_dialog_content = "No puedo creer que lo trajeran aquí... No es de extrañar que los soldados desaparecieran en masa.",
  ui_story_1018_10181201_75_dialog_content = "Rugido...",
  ui_story_1018_10181201_76_dialog_content = "La voz... ¿Quizás el piloto retuvo algo de conciencia?",
  ui_story_1018_10181201_77_dialog_content = "¡No te acerques a eso—los soldados están arrastrándose justo al lado de sus pies!",
  ui_story_1018_10181201_78_dialog_content = "¿Justo cuántos de ellos hay ahí...?",
  ui_story_1018_10181201_79_dialog_content = "<color=#e8d9bb>Zumbido...¡Crujido!</color>",
  ui_story_1018_10181201_80_dialog_content = "La pausa... Está vacilando...",
  ui_story_1018_10181201_81_dialog_content = "Gran Mariscal, puede que haya esperanza para el soldado después de todo. Axelia está intentando salvarlo.",
  ui_story_1018_10181201_82_dialog_content = "¡Estuviste roto una vez!",
  ui_story_1018_10181201_83_dialog_content = "Axelia se ha roto muchas veces antes de esto.",
  ui_story_1018_10181201_84_dialog_content = "Pero Axelia pudo recuperarse cada vez.",
  ui_story_1018_10181201_85_dialog_content = "El piloto dentro es miembro del escuadrón de Axelia. Es deber de Axelia protegerlos.",
  ui_story_1018_10181201_86_dialog_content = "...",
  ui_story_1018_10181201_87_dialog_content = "¡¡¡Rooooooooooooooooooooooooooooooooooooo!!!",
  ui_story_1018_10181201_88_dialog_content = "Su cuerpo se ha fusionado completamente con el mecha. Esto debe ser muy difícil para el piloto.",
  ui_story_1018_10181201_89_dialog_content = "Mecha también es parte de Axelia. Axelia sabe que es difícil para él.",
  ui_story_1018_10181201_90_dialog_content = "Lamento escuchar eso, Axelia...",
  ui_story_1018_10181201_91_dialog_content = "Wrath, ¡déjame ir con Axelia! ¡Salvaré a los soldados con ella!",
  ui_story_1018_10181201_92_dialog_content = "Como Gran Mariscal, es mi deber detenerte, pero dadas las circunstancias de este caso...",
  ui_story_1018_10181201_93_dialog_content = "Leo, por favor distrae a Engine VII para nosotros!",
  ui_story_1018_10181201_94_dialog_content = "Sin problema.",
  ui_story_1018_10181201_95_dialog_content = "Wrath...¿?",
  ui_story_1018_10181201_96_dialog_content = "No puedo dejar que ustedes dos enfrenten esto solos.",
  ui_story_1018_10181201_97_dialog_content = "Engine VII era el escudo del ejército en Crepúsculo, pero ahora está en el lado opuesto.",
  ui_story_1018_10181201_98_dialog_content = "Tiene que pasar por este escudo para hacerte daño.",
  ui_story_1018_10181201_99_dialog_content = "Grah!",
  ui_story_1018_10181201_100_dialog_content = "Oh no, soldados saliendo de las trincheras...",
  ui_story_1018_10181201_101_dialog_content = "Son subordinados de Axelia.",
  ui_story_1018_10181201_102_dialog_content = "¡No se saldrá con la suya usando a mis soldados para retrasarme!",
  ui_story_1018_10181201_103_dialog_content = "Haz lo que quieras, Axelia, ¡y salva a tus chicos! ¡Yo me encargo de los soldados!",
  ui_story_1018_10181201_104_dialog_content = "Axelia copia.",
  ui_story_1018_10181202_1_dialog_content = "Los soldados aquí han sido sometidos pero aún están conscientes.",
  ui_story_1018_10181202_2_dialog_content = "Lo mismo por aquí también. Cuidado con los tiros de Engine VII.",
  ui_story_1018_10181202_3_dialog_content = "¡¡¡Rooooooooooooooooooooooooooooooooooooo!!!",
  ui_story_1018_10181202_4_dialog_content = "Axelia sabe que estás pasando por una experiencia difícil.",
  ui_story_1018_10181202_5_dialog_content = "No quieres hacer daño a la gente... Axelia lo sabe todo.",
  ui_story_1018_10181202_6_dialog_content = "Rugido...",
  ui_story_1018_10181202_7_dialog_content = "Él se está alejando lentamente del frente. No hay enemigos allí.",
  ui_story_1018_10181202_8_dialog_content = "¡Sigue con precaución! ¡Después de que él despeje las trincheras, somételo por detrás!",
  ui_story_1018_10181202_9_dialog_content = "Grah!",
  ui_story_1018_10181202_10_dialog_content = "¡Tengo que hacer un movimiento!",
  ui_story_1018_10181202_11_dialog_content = "¡Aparta, Axelia!",
  ui_story_1018_10181202_12_dialog_content = "¡Lanza relámpago, perfora!",
  ui_story_1018_10181202_13_dialog_content = "Rugido...",
  ui_story_1018_10181202_14_dialog_content = "¡Se detuvo! Pero Axelia...",
  ui_story_1018_10181202_15_dialog_content = "Leo, ¡Axelia viene hacia ti!",
  ui_story_1018_10181202_16_dialog_content = "Hola—",
  ui_story_1018_10181202_17_dialog_content = "La distancia no es un problema.",
  ui_story_1018_10181202_18_dialog_content = "Hola—",
  ui_story_1018_10181202_19_dialog_content = "<color=#e8d9bb>¡Relincho—</color>",
  ui_story_1018_10181202_20_dialog_content = "Uf—",
  ui_story_1018_10181202_21_dialog_content = "He sido testigo de tu valentía nuevamente, Leo de Crepúsculo.",
  ui_story_1018_10181202_22_dialog_content = "¿Qué estás haciendo acá?",
  ui_story_1018_10181202_23_dialog_content = "Buen trabajo, Axelia.",
  ui_story_1018_10181202_24_dialog_content = "El Gran Mariscal atrapó Axelia.",
  ui_story_1018_10181202_25_dialog_content = "Has superado la versión de ti mismo del partido de exhibición. Eres un guerrero notable.",
  ui_story_1018_10181202_26_dialog_content = "Axelia ha estado pensando en lo que dijo el Gran Mariscal...",
  ui_story_1018_10181202_27_dialog_content = "Axelia quiere preguntar al Gran Mariscal, derrotando a los Eclipsites y protegiendo a los guerreros de Illumina...",
  ui_story_1018_10181202_28_dialog_content = "¿Eso cuenta como \"vivir como una persona\"?",
  ui_story_1018_10181202_29_dialog_content = "Ya estás ahí, Axelia.",
  ui_story_1018_10181202_30_dialog_content = "Gracias, Gran Mariscal. Axelia seguirá luchando.",
  ui_story_1018_10181202_31_dialog_content = "Tendrás tus oportunidades, Axelia. Aquí vienen tus amigos que se preocupan por ti.",
  ui_story_1018_10181202_32_dialog_content = "Axelia! Me alegra haberte alcanzado...",
  ui_story_1018_10181202_33_dialog_content = "Yingel...",
  ui_story_1018_10181202_34_dialog_content = "¡Lo siento! Sabía sobre esto, pero aún así te dejé pasar por ello... ¡Perdón!",
  ui_story_1018_10181202_35_dialog_content = "Axelia solo sabe que Yingel quiere proteger a Axelia.",
  ui_story_1018_10181202_36_dialog_content = "¡Es genial que Axelia esté bien! ¿No dije que el amable pajarito recibiría una recompensa?",
  ui_story_1018_10181202_37_dialog_content = "Gran Mariscal, Oficial de Tecnología Gronru y Coronel Yingel llevarán a los soldados de Illumina a casa!",
  ui_story_1018_10181202_38_dialog_content = "Claro. Ocúpate de estos guerreros.",
  ui_story_1018_10181202_39_dialog_content = "Acerca de lo que pasó en la investigación, Gran Mariscal... lo siento mucho.",
  ui_story_1018_10181202_40_dialog_content = "Además, los experimentos del profesor Ulysses...",
  ui_story_1018_10181202_41_dialog_content = "Pero créeme, nunca lo defenderé en este asunto de nuevo. No quiero ver a compañeros inocentes lastimados.",
  ui_story_1018_10181202_42_dialog_content = "Por favor, permítame llevarlos de vuelta a Illumina para tratamiento. Buscaré una solución a su problema...",
  ui_story_1018_10181202_43_dialog_content = "Todos son víctimas, no hay necesidad de sentir pena.",
  ui_story_1018_10181202_44_dialog_content = "Pero te hice perder el puesto de Gran Mariscal...",
  ui_story_1018_10181202_45_dialog_content = "Esa posición no es algo que puedas cambiar con tus palabras.",
  ui_story_1018_10181202_46_dialog_content = "Debo agradecerte por darme la oportunidad de ser el Gran Mariscal.",
  ui_story_1018_10181202_47_dialog_content = "Has vuelto, Wrath.",
  ui_story_1018_10181202_48_dialog_content = "¡Vaya, dos Grandes Mariscales!",
  ui_story_1018_10181202_49_dialog_content = "¡Sabía que Wrath estaría bien!",
  ui_story_1018_10181202_50_dialog_content = "Debo decir que te comportaste como un Gran Mariscal.",
  ui_story_1018_10181202_51_dialog_content = "Eso es lo que una dura batalla en Crepúsculo te haría.",
  ui_story_1018_10181202_52_dialog_content = "Te hemos estado esperando en el frente.",
  ui_story_1018_10181202_53_dialog_content = "Prometí que asumiría temporalmente como Gran Mariscal por ti y volvería con vida. No rompo mis promesas.",
  ui_story_1018_10181202_54_dialog_content = "Gran Mariscal y los cuatro comandantes, no me digas...",
  ui_story_1018_10181202_55_dialog_content = "...",
  ui_story_1018_10181202_56_dialog_content = "He estado luchando por un resultado, pero ahora también he demostrado una cosa...",
  ui_story_1018_10181202_57_dialog_content = "Estás absolutamente calificado, Wrath.",
  ui_story_1018_10181202_58_dialog_content = "Pero no he terminado...",
  ui_story_1018_10181202_59_dialog_content = "Estás absolutamente calificado.",
  ui_story_1018_10181202_60_dialog_content = "...",
  ui_story_1018_10181202_61_dialog_content = "Ejem, ¿crees que aceptaré lo que acabas de decir?",
  ui_story_1018_10181202_62_dialog_content = "Si no puedo vencerte, no merezco ser el Gran Mariscal.",
  ui_story_1018_10181202_63_dialog_content = "La batalla no ha terminado, así que tú das las órdenes.",
  ui_story_1018_10181202_64_dialog_content = "...",
  ui_story_1018_10181202_65_dialog_content = "La capitana Wrath de la Guardia Real ha repelido con éxito a los Eclipsites de Crepúsculo.",
  ui_story_1018_10181202_66_dialog_content = "La Cuarta Legión de Illumina se ha reunido y espera la orden del Gran Mariscal.",
  ui_story_1018_10181401_1_dialog_content = "Todavía tenemos mucho tiempo, pero pensé que ya habría un enorme cráter aquí.",
  ui_story_1018_10181401_2_dialog_content = "¿Qué, te pones sentimental por despedirte de ella?",
  ui_story_1018_10181401_3_dialog_content = "Eso es ridículo. Pensé que ya habías terminado con lo tuyo, por eso no deberíamos perder más tiempo.",
  ui_story_1018_10181401_4_dialog_content = "Vamos, el momento que estás esperando está llegando.",
  ui_story_1018_10181401_5_dialog_content = "De acuerdo. Pero antes de irnos, todavía tengo algunas cosas que limpiar.",
  ui_story_1018_10181401_6_dialog_content = "Conozco a Forsakin. Ella no arriesgaría hacer todo esto a menos que fuera beneficioso para sus experimentos.",
  ui_story_1018_10181401_7_dialog_content = "Por no mencionar que dejar a Helios atrás en Gannon probablemente fue algo que ella no esperaba.",
  ui_story_1018_10181401_8_dialog_content = "Eso significa que Forsakin se infiltró en las Entrañas de Illumina porque Ulysses prometió darle lo que ella quería.",
  ui_story_1018_10181401_9_dialog_content = "Y Ulysses la jugó. Añadió las Semillas al Programa Phospherus en el momento en que las obtuvo.",
  ui_story_1018_10181401_10_dialog_content = "Eso es ciertamente posible.",
  ui_story_1018_10181401_11_dialog_content = "Entonces, ¿el núcleo de Guardian One también es parte de su trato?",
  ui_story_1018_10181401_12_dialog_content = "Es parte del plan de Eclipse, pero aún no está claro si estaba en su acuerdo.",
  ui_story_1018_10181401_13_dialog_content = "Estoy más inclinado a creer que el robo del núcleo no era parte del plan de Ulysses.",
  ui_story_1018_10181401_14_dialog_content = "El Comité no tenía razón para perder el núcleo en favor del Programa Phospherus a manos de Eclipse.",
  ui_story_1018_10181401_15_dialog_content = "No solo el costo fue demasiado alto, sino que incluso si los soldados implantados con las Semillas lo lograran, no podrían luchar en futuras batallas.",
  ui_story_1018_10181401_16_dialog_content = "¿Qué dijiste?",
  ui_story_1018_10181401_17_dialog_content = "...",
  ui_story_1018_10181401_18_dialog_content = "...",
  ui_story_1018_10181401_19_dialog_content = "¿Te han implantado una Semilla...?",
  ui_story_1018_10181401_20_dialog_content = "¿Y qué? Todavía estoy bien, ¿no?",
  ui_story_1018_10181401_21_dialog_content = "...",
  ui_story_1018_10181401_22_dialog_content = "Veo que insistí en hacerte el Gran Mariscal solo para que te pusieras el implante...",
  ui_story_1018_10181401_23_dialog_content = "No tiene nada que ver contigo. Fue mi decisión.",
  ui_story_1018_10181401_24_dialog_content = "No debí haber...",
  ui_story_1018_10181401_25_dialog_content = "¡No hay forma de que hubiera llegado hasta ahora por sí sola sin mi Semilla!",
  ui_story_1018_10181401_26_dialog_content = "Finalmente muéstrate, Forsakin.",
  ui_story_1018_10181401_27_dialog_content = "¡Asquerosa escoria!",
  ui_story_1018_10181401_28_dialog_content = "Forsakin, has hecho sufrir a mis soldados. ¡Ahora es el momento de acabar con esto!",
  ui_story_1018_10181401_29_dialog_content = "Espera, Wrath, ¡hay soldados en el barro detrás de ella!",
  ui_story_1018_10181401_30_dialog_content = "Rugido...",
  ui_story_1018_10181401_31_dialog_content = "No puedo creer que ella se haya rebajado tanto...",
  ui_story_1018_10181401_32_dialog_content = "¡Manténlos bajo control y protege la línea! ¡Yo manejaré esto!",
  ui_story_1018_10181401_33_dialog_content = "¡Entendido!",
  ui_story_1018_10181401_34_dialog_content = "Bastante animado, veo. ¿No quieres saber por qué la Semilla en ti no te puso patas arriba?",
  ui_story_1018_10181401_35_dialog_content = "¿O en realidad te encanta masacrar a tus chicos en un frenesí de sangre?",
  ui_story_1018_10181401_36_dialog_content = "Cállate, Forsakin, fuiste tú quien lastimó a los soldados.",
  ui_story_1018_10181401_37_dialog_content = "...",
  ui_story_1018_10181401_38_dialog_content = "Entonces fuiste tú quien me curó en el barro...",
  ui_story_1018_10181401_39_dialog_content = "Torturaste a mis soldados, me llevaste al límite... Todo para ver cómo reaccionaría con la Semilla dentro de mí...",
  ui_story_1018_10181401_40_dialog_content = "Veo que no eres tan tonto como pensaba. Solo estoy ayudando a Ulysses de manera incidental, ya que es un fracaso épico como científico.",
  ui_story_1018_10181401_41_dialog_content = "¿Qué te prometió Eclipse, Forsakin?",
  ui_story_1018_10181401_42_dialog_content = "¿Cómo puedes comprender algo así? ¿Crees que tienes el poder para protegerlo todo?",
  ui_story_1018_10181401_43_dialog_content = "Incluso con una revisión, los Aurorianos siguen siendo un grupo de desechos físicamente débiles y mentalmente endebles.",
  ui_story_1018_10181401_44_dialog_content = "En lugar de ser utilizado y descartado por la jerarquía de Illumina más tarde, deberías buscar una salida ahora.",
  ui_story_1018_10181401_45_dialog_content = "Tu alineación con Eclipse te convierte en nada más que un títere Eclipsite tú mismo.",
  ui_story_1018_10181401_46_dialog_content = "Crees que eres tan inteligente porque estuviste en el proyecto Sol Artificial.",
  ui_story_1018_10181401_47_dialog_content = "Pero todos los presentes, más aquellos que cayeron en Crepúsculo, llegaron hasta aquí por su propia voluntad.",
  ui_story_1018_10181401_48_dialog_content = "Comparado con ellos, tú eres el verdadero pelele.",
  ui_story_1018_10181401_49_dialog_content = "¡Tú eres el que es débil y frágil!",
  ui_story_1018_10181401_50_dialog_content = "¡Cállate, idiota! Sigues vivo solo gracias a mi Semilla.",
  ui_story_1018_10181401_51_dialog_content = "El mundo no es un cuento de hadas para niños de tres años. Para sobrevivir, uno debe seguir subiendo la escalera a toda costa.",
  ui_story_1018_10181401_52_dialog_content = "Ustedes ignorantes Aurorians que se arrastran como cucarachas nunca conocerán la verdad, ni siquiera en la muerte.",
  ui_story_1018_10181401_53_dialog_content = "Sé que tienes ambiciones, Forsakin, pero no puedo permitir que sacrifiques a otros para realizarlas.",
  ui_story_1018_10181401_54_dialog_content = "Esta es la última vez que te lo diré—",
  ui_story_1018_10181401_55_dialog_content = "Lastimaste a tu compañero en Illumina, y Illumina no te perdonará. Pero ahora no soy el Gran Mariscal y espero que te detengas.",
  ui_story_1018_10181401_56_dialog_content = "Deja de responder a Eclipse. Eso no es lo que realmente querías.",
  ui_story_1018_10181401_57_dialog_content = "Tú eres el que responde a los demás, Reinhardt! No puedes proteger a todos.",
  ui_story_1018_10181401_58_dialog_content = "Y no me tengas lástima. Dejé de querer estar de tu lado hace mucho tiempo.",
  ui_story_1018_10181401_59_dialog_content = "Puedes perseguirme todo lo que quieras, pero nunca me detendré.",
  ui_story_1018_10181401_60_dialog_content = "<color=#e8d9bb>Crujiente-</color>",
  ui_story_1018_10181401_61_dialog_content = "Ejem, ¿es el discurso de despedida tu regalo para ella?",
  ui_story_1018_10181401_62_dialog_content = "¡Toma esto, Espectro!",
  ui_story_1018_10181401_63_dialog_content = "Los soldados ya estaban sometidos, pero luego incluso apareció Wraith.",
  ui_story_1018_10181401_64_dialog_content = "Si hubiera querido, ya estarías muerto.",
  ui_story_1018_10181401_65_dialog_content = "Sigue hablando y podría cambiar de opinión, Forsakin.",
  ui_story_1018_10181401_66_dialog_content = "Deja de seguir a Eclipse o perderás la vida por ello, Forsakin.",
  ui_story_1018_10181401_67_dialog_content = "Eso es asunto mío. Lo que tienes que cuidar, Reinhardt, es que no te mate.",
  ui_story_1018_10181401_68_dialog_content = "<color=#e8d9bb>Crujiente-</color>",
  ui_story_1018_10181401_69_dialog_content = "La Semilla en mí está vibrando ligeramente... ¡Cuidado, enemigos cerca!",
  ui_story_1018_10181401_70_dialog_content = "*Arcadas*",
  ui_story_1018_10181401_71_dialog_content = "Grah!",
  ui_story_1018_10181401_72_dialog_content = "Está escupiendo a aquellos tomados del Crepúsculo por Forsakin...",
  ui_story_1018_10181401_73_dialog_content = "Grah!",
  ui_story_1018_10181401_74_dialog_content = "¿No fue derrotado el mecha ya? ¡Está de pie otra vez!",
  ui_story_1018_10181401_75_dialog_content = "Veo que Forsakin tenía un plan de contingencia.",
  ui_story_1018_10181401_76_dialog_content = "Las trincheras estaban llenas de barro, donde el mecha derrotado había estado yaciendo todo este tiempo.",
  ui_story_1018_10181401_77_dialog_content = "Ahora que el Eclipsite pantanoso ha reaparecido, no caerá tan fácilmente...",
  ui_story_1018_10181401_78_dialog_content = "¿Qué hacemos ahora, Gran Mariscal?",
  ui_story_1018_10181401_79_dialog_content = "...",
  ui_story_1018_10181401_80_dialog_content = "...",
  ui_story_1018_10181401_81_dialog_content = "Es mi culpa que mis soldados no puedan descansar en paz...",
  ui_story_1018_10181401_82_dialog_content = "¡Te juro que recuperaré sus cuerpos, cueste lo que cueste!",
  ui_story_1018_10181401_83_dialog_content = "Pero Forsakin te acaba de herir...",
  ui_story_1018_10181401_84_dialog_content = "Conozco mis límites. Me abstendré de usar ese poder.",
  ui_story_1018_10181401_85_dialog_content = "¡Cargaré directo al corazón y lo pulverizaré!",
  ui_story_1018_10181401_86_dialog_content = "Atacaré contigo, Wrath. Déjame a mí los soldados rabiosos.",
  ui_story_1018_10181401_87_dialog_content = "¡Mantendremos las líneas!",
  ui_story_1018_10181401_88_dialog_content = "¡Sí!",
  ui_story_1018_10181401_89_dialog_content = "Gran Mariscal—",
  ui_story_1018_10181401_90_dialog_content = "¿Cómo es que tú...?",
  ui_story_1018_10181401_91_dialog_content = "Los Lumo Skyriders proporcionarán cobertura. Los Eclipsites no te tocarán.",
  ui_story_1018_10181401_92_dialog_content = "Estoy muy familiarizado con la estrategia del Gran Mariscal. Los Caballeros de Crepúsculo complementarán la carga.",
  ui_story_1018_10181401_93_dialog_content = "Y yo también, Wrath, ¡te ayudaré en la lucha!",
  ui_story_1018_10181401_94_dialog_content = "Noche Blanca en lo alto... ¡Qué fuerza de coalición multifacción tenemos!",
  ui_story_1018_10181401_95_dialog_content = "¡Entonces cumplamos nuestros respectivos roles y reunámonos después de destruir al enemigo!",
  ui_story_1018_10181401_96_dialog_content = "¿Qué dices, Reinhardt?",
  ui_story_1018_10181401_97_dialog_content = "¡No importa qué, nunca dejes atrás a los compañeros de Illumina!",
  ui_story_1018_10181501_1_dialog_content = "<color=#e8d9bb>Golpeteo de pitter...</color>",
  ui_story_1018_10181501_2_dialog_content = "Oye, está lloviendo...",
  ui_story_1018_10181501_3_dialog_content = "Esto es bastante inusual.",
  ui_story_1018_10181501_4_dialog_content = "No hay señales de Eclipsites en ninguna parte, Gran Mariscal.",
  ui_story_1018_10181501_5_dialog_content = "Las unidades de Lumopolis se dirigen a las líneas este y oeste.",
  ui_story_1018_10181501_6_dialog_content = "Está bien donde estoy. El lodo está retrocediendo y todo está de maravilla.",
  ui_story_1018_10181501_7_dialog_content = "Wrath ¡seguro que sabe cómo luchar!",
  ui_story_1018_10181501_8_dialog_content = "¿Podría la lluvia hacer que el barro retroceda?",
  ui_story_1018_10181501_9_dialog_content = "No me di cuenta de eso. Eso podría significar que realmente se acabó ahora...",
  ui_story_1018_10181501_10_dialog_content = "Despierto. ¿Te sientes bien?",
  ui_story_1018_10181501_11_dialog_content = "He estado despierto, solo pensando en lo que me dijiste antes...",
  ui_story_1018_10181501_12_dialog_content = "<color=#e8d9bb>Antes de que Wrath saliera a buscar a Ulysses...</color>",
  ui_story_1018_10181501_13_dialog_content = "¿Cuánto tiempo vas a quedarte ahí dentro?",
  ui_story_1018_10181501_14_dialog_content = "¿Qué hay que decir? Escuchaste la pregunta-",
  ui_story_1018_10181501_15_dialog_content = "¡Reinhardt!",
  ui_story_1018_10181501_16_dialog_content = "¿Crees que caería en algo tan tonto como tú conspirando con el enemigo?",
  ui_story_1018_10181501_17_dialog_content = "...",
  ui_story_1018_10181501_18_dialog_content = "¿Eras tan callado cuando te inscribiste en el Sol Artificial?",
  ui_story_1018_10181501_19_dialog_content = "Descubriste, ya veo.",
  ui_story_1018_10181501_20_dialog_content = "Te sometiste a una modificación. ¿Es así como pudiste vencerme en el duelo?",
  ui_story_1018_10181501_21_dialog_content = "...",
  ui_story_1018_10181501_22_dialog_content = "¡Respóndeme!",
  ui_story_1018_10181501_23_dialog_content = "Muchas cosas no son tan simples como podrías pensar. Deja de preguntar, por el bien de Illumina.",
  ui_story_1018_10181501_24_dialog_content = "Como un honorable Gran Mariscal, podrías haber—",
  ui_story_1018_10181501_25_dialog_content = "Es por eso que debo aceptar este resultado.",
  ui_story_1018_10181501_26_dialog_content = "...",
  ui_story_1018_10181501_27_dialog_content = "Afloja el puño si lo entendiste. Este no es el momento para pelear conmigo.",
  ui_story_1018_10181501_28_dialog_content = "...",
  ui_story_1018_10181501_29_dialog_content = "Tu futuro está en la palma de tu mano.",
  ui_story_1018_10181501_30_dialog_content = "Si lo mantienes todo guardado, terminarás sin nada.",
  ui_story_1018_10181501_31_dialog_content = "\"Manteniéndolo en bola, terminaremos sin nada.\"",
  ui_story_1018_10181501_32_dialog_content = "¿Por qué recordaría eso ahora...",
  ui_story_1018_10181501_33_dialog_content = "Es porque es hora de balancear nuestros puños contra el enemigo común.",
  ui_story_1018_10181501_34_dialog_content = "Los puños cerrados deben apuntar al enemigo común.",
  ui_story_1018_10181501_35_dialog_content = "...",
  ui_story_1018_10181501_36_dialog_content = "Confía en mí, te darás cuenta del poder que tengo.",
  ui_story_1018_10181501_37_dialog_content = "¿Es todo esto parte de tu plan?",
  ui_story_1018_10181501_38_dialog_content = "...",
  ui_story_1018_10181501_39_dialog_content = "¿Estás listo para dejarme hacer lo que sea necesario...?",
  ui_story_1018_10181501_40_dialog_content = "...",
  ui_story_1018_10181501_41_dialog_content = "Entiendo.",
  ui_story_1018_10181501_42_dialog_content = "Me pondré en tu lugar como Gran Mariscal.",
  ui_story_1018_10181501_43_dialog_content = "Pero llegará un momento en que seas mi único oponente.",
  ui_story_1018_10181501_44_dialog_content = "Sin embargo, antes de eso, balancearemos nuestros puños y derribaremos a nuestro enemigo común.",
  ui_story_1018_10181501_45_dialog_content = "Wrath.",
  ui_story_1018_10181501_46_dialog_content = "¿Ah?",
  ui_story_1018_10181501_47_dialog_content = "Ve y haz lo que sea necesario, pero asegúrate de volver con vida.",
  ui_story_1018_10181501_48_dialog_content = "...",
  ui_story_1018_10181501_49_dialog_content = "<color=#e8d9bb>Golpeteo de pitter...</color>",
  ui_story_1018_10181501_50_dialog_content = "He vuelto con vida, pero los soldados... Ya no tienen ayuda, ¿verdad?",
  ui_story_1018_10181501_51_dialog_content = "Lo hicieron bien solo con aguantar hasta ahora.",
  ui_story_1018_10181501_52_dialog_content = "Son verdaderos guerreros. Illumina les dará el respeto adecuado.",
  ui_story_1018_10181501_53_dialog_content = "No pude salvarlos en Crepúsculo... Luego tuve que matarlos de nuevo como si fueran el enemigo...",
  ui_story_1018_10181501_54_dialog_content = "Otro fracaso...",
  ui_story_1018_10181501_55_dialog_content = "Aunque me convertí en el Gran Mariscal, aún estoy destinado a fracasar.",
  ui_story_1018_10181501_56_dialog_content = "No fallaste, Wrath. Guiaste a todos en salvar a Crepúsculo y mantener la línea.",
  ui_story_1018_10181501_57_dialog_content = "La lluvia está cayendo fuerte. Regresemos.",
  ui_story_1018_10181501_58_dialog_content = "...",
  ui_story_1018_10181501_59_dialog_content = "Volvamos. El pronóstico decía que el clima estaría mal hoy. Probablemente esté lloviendo en la superficie.",
  ui_story_1018_10181501_60_dialog_content = "<color=#e8d9bb>Sonido metálico seco-</color>",
  ui_story_1018_10181501_61_dialog_content = "Je... Reinhardt...",
  ui_story_1018_10181501_62_dialog_content = "¿De qué te ríes?",
  ui_story_1018_10181501_63_dialog_content = "¿Está un Gran Mariscal condenado a sentir tal desesperación en cualquier momento?",
  ui_story_1018_10181501_64_dialog_content = "Cuando cerré mis ojos, pude ver a los guerreros sacrificándose en Crepúsculo...",
  ui_story_1018_10181501_65_dialog_content = "Para evitar convertirse en Eclipsites y lastimar a las personas, eligieron dispararse en la cabeza...",
  ui_story_1018_10181501_66_dialog_content = "Axelia fue dañada innumerables veces, pero se levantó después de cada una solo para salvar a su escuadra...",
  ui_story_1018_10181501_67_dialog_content = "Entonces estaba ese hombre, muriendo por regresar a Illumina en su último hilo de cordura...",
  ui_story_1018_10181501_68_dialog_content = "Todos queremos ganar la guerra, pero exige un gran costo...",
  ui_story_1018_10181501_69_dialog_content = "Debes haber pasado por escenarios similares innumerables veces...",
  ui_story_1018_10181501_70_dialog_content = "Pero en todos tus años como Gran Mariscal, nunca vi un atisbo de arrepentimiento en ti.",
  ui_story_1018_10181501_71_dialog_content = "Incluso cediste en el campo de batalla para proteger a Axelia.",
  ui_story_1018_10181501_72_dialog_content = "Y arrojado a una celda con tu destino dictado por otros, solo por el futuro de Illumina.",
  ui_story_1018_10181501_73_dialog_content = "Solo tú podrías haber hecho todo eso, Reinhardt.",
  ui_story_1018_10181501_74_dialog_content = "...",
  ui_story_1018_10181501_75_dialog_content = "El Gran Mariscal es un juramento, una creencia, un paraguas... Alguien que no puede morir y debe seguir lamentando a los demás.",
  ui_story_1018_10181501_76_dialog_content = "El Gran Mariscal es alguien que protege a la gente con su propia carne y sangre.",
  ui_story_1018_10181501_77_dialog_content = "¿Solo yo podría haber hecho eso? Bueno, tú aguantaste hasta ahora para preservar Illumina por ti mismo.",
  ui_story_1018_10181501_78_dialog_content = "¿Es así...?",
  ui_story_1018_10181501_79_dialog_content = "<color=#e8d9bb>La lluvia lava el suelo embarrado mientras un tenue resplandor se filtra a través de las lejanas capas de nubes.</color>",
  ui_story_1018_10181501_80_dialog_content = "<color=#e8d9bb>Los hombros de Wrath son delgados, pero mientras se mantiene firme y fuerte en el juego de luces y sombras, sus contornos se vuelven más definidos y erguidos.</color>",
  ui_story_1018_10181501_81_dialog_content = "Pero estoy seguro de que ya no quiero ser el Gran Mariscal...",
  ui_story_1018_10181501_82_dialog_content = "Cargaste con el peso por mí en la crisis. Ahora es el momento de que retome el deber.",
  ui_story_1018_10181501_83_dialog_content = "Los problemas que surgen son igual de desafiantes, pero confía en mí, eliminaré a todos los enemigos desde adentro.",
  ui_story_1018_10181501_84_dialog_content = "¿Cómo planeas lidiar con el Comité?",
  ui_story_1018_10181501_85_dialog_content = "Dirigimos el ejército, Gran Mariscal. Solo dí la palabra y arruinaré su día!",
  ui_story_1018_10181501_86_dialog_content = "El hecho de que esté aquí para pelear significa que tenemos la aprobación silenciosa del Comité.",
  ui_story_1018_10181501_87_dialog_content = "No aceleraron el Programa Phospherus solo por Crepúsculo.",
  ui_story_1018_10181501_88_dialog_content = "Con el aumento de Darkover y el robo del núcleo de Guardian One, lo que Eclipse está tramando es el problema más grande.",
  ui_story_1018_10181501_89_dialog_content = "No te volverán a meter en una celda si regresas a Gannon, ¿verdad?",
  ui_story_1018_10181501_90_dialog_content = "Lo que ha estado ocurriendo con los soldados hará que Ulysses sean llamados al tapete.",
  ui_story_1018_10181501_91_dialog_content = "De cualquier manera, a Belisaria se le respeta. Tomarán la decisión correcta con respecto a mí.",
  ui_story_1018_10181501_92_dialog_content = "Hablando de Eclipse, enviamos dos escuadrones a la Zona Oscura, Gran Mariscal.",
  ui_story_1018_10181501_93_dialog_content = "No sé cuál es el plan del Comité, pero creo que Charon y Vice necesitan nuestra ayuda.",
  ui_story_1018_10181501_94_dialog_content = "Es cierto... Se encontraron conmigo brevemente, y actualmente no están en una buena situación...",
  ui_story_1018_10181501_95_dialog_content = "¿Qué vas a hacer, PlayerName?",
  ui_story_1018_10181501_96_dialog_content = "Todavía hay refugiados de Crepúsculo en Eraveil, así que regresaré con Leo para ayudar.",
  ui_story_1018_10181501_97_dialog_content = "Pero también estoy muy preocupado por Vice y los demás...",
  ui_story_1018_10181501_98_dialog_content = "No dejaré que les pase nada, PlayerName, te lo prometo.",
  ui_story_1018_10181501_99_dialog_content = "No importa qué tipo de golpe pueda dar el Comité más tarde, priorizaré encontrarlos.",
  ui_story_1018_10181501_100_dialog_content = "Entonces, me encargaré de los problemas en Crepúsculo. Después de luchar hombro a hombro con Leo durante tanto tiempo, quiero que Illumina le dé algo de esperanza a la ciudad.",
  ui_story_1018_10181501_101_dialog_content = "Y no olvides recibir tratamiento rápidamente...",
  ui_story_1018_10181501_102_dialog_content = "Entendido. Me pondré en contacto contigo si no hay otra opción.",
  ui_story_1018_10181501_103_dialog_content = "Claro, si puedo ayudar.",
  ui_story_1018_10181501_104_dialog_content = "<color=#e8d9bb>*Estático*</color>",
  ui_story_1018_10181501_105_dialog_content = "Todo esto se ha convertido en todo un espectáculo, no, espera, una comedia. Y nuestro dramaturgo Ulysses ni siquiera tiene el valor de presentarse en la reunión de hoy.",
  ui_story_1018_10181501_106_dialog_content = "¿Cómo planeas terminar esto?",
  ui_story_1018_10181501_107_dialog_content = "Aún no es momento de tirar la toalla.",
  ui_story_1018_10181501_108_dialog_content = "¿Estás bromeando? Los dos Grandes Mariscales de Illumina acaban de lograr una gran victoria en el campo de batalla.",
  ui_story_1018_10181501_109_dialog_content = "¿De verdad crees que vendrían arrastrándose hacia ti para negociaciones pacíficas?",
  ui_story_1018_10181501_110_dialog_content = "¿Crees que no sabía que Reinhardt salió de una celda de Illumina?",
  ui_story_1018_10181501_111_dialog_content = "Aún no es momento para la evidencia clave. Cómo se desarrolle depende de su actitud.",
  ui_story_1018_10181501_112_dialog_content = "Clásico movimiento de Belisaria, nunca dejando las cosas sin un plan de respaldo.",
  ui_story_1018_10181501_113_dialog_content = "Pero esta batalla en las líneas defensivas no es solo un enfrentamiento, todo el continente de Astra está observando.",
  ui_story_1018_10181501_114_dialog_content = "Correcto, todos están mirando, y ojalá aún más cerca.",
  ui_story_1018_10181501_115_dialog_content = "Si llega la Crisis de Darkover, ¿hasta dónde irá cada facción?",
  ui_story_1018_10181501_116_dialog_content = "Estás apoyando el plan de Ulysses para hacer que Lumopolis finalmente muestre sus cartas, ¿eh?",
  ui_story_1018_10181501_117_dialog_content = "Esa es una parte, sí.",
  ui_story_1018_10181501_118_dialog_content = "Ya sea en Crepúsculo o en el frente, todos ustedes vieron que aún somos una amenaza para los Eclipsites.",
  ui_story_1018_10181501_119_dialog_content = "Y hasta mostraron su tarjeta de agujero.",
  ui_story_1018_10181501_120_dialog_content = "¿Te refieres a esa chica?",
  ui_story_1018_10181501_121_dialog_content = "Sí, pero definitivamente eso no es todo.",
  ui_story_1018_10181501_122_dialog_content = "¿Quién lo hubiera pensado? Este es el mismo \"ejercicio militar\" que tú, Belisaria, esperabas presenciar.",
  ui_story_1018_10181501_123_dialog_content = "Dejemos de lado otras cosas por ahora. Dado el enorme costo, ¿has considerado las consecuencias?",
  ui_story_1018_10181501_124_dialog_content = "Estoy dispuesto a escuchar a cualquiera con un plan mejor.",
  ui_story_1018_10181501_125_dialog_content = "El arma para Eclipse esta vez sigue siendo las Semillas de Forsakin, pero al menos ahora también las tenemos nosotros.",
  ui_story_1018_10181501_126_dialog_content = "Por eso apoyo a Ulysses.",
  ui_story_1018_10181501_127_dialog_content = "En el futuro, debemos apoderarnos de todas las armas que potencialmente puedan destruirnos.",
  ui_story_1018_10181501_128_dialog_content = "Ya sean de Lumopolis o Northland, e incluso cultos radicales.",
  ui_story_1018_10181501_129_dialog_content = "El núcleo de Guardian One ha sido robado, ¿y tu mayor preocupación es el equilibrio entre estas facciones?",
  ui_story_1018_10181501_130_dialog_content = "Sin prioridades. Ser presionado por todos lados es el dilema actual de Illumina.",
  ui_story_1018_10181501_131_dialog_content = "Ese ingeniero que dejó Illumina no fue criticado solo por Lumopolis.",
  ui_story_1018_10181501_132_dialog_content = "Dadas las circunstancias, probablemente necesitemos cambiar de rumbo y mostrarle a todos quién es realmente El Ingeniero.",
  ui_story_1018_10181501_133_dialog_content = "¿Estas seguro acerca de esto?",
  ui_story_1018_10181501_134_dialog_content = "La noticia del Equipo de Reconocimiento de la Zona Oscura es la esperada.",
  ui_story_1018_10181501_135_dialog_content = "El núcleo de Guardian One es precisamente la pieza final para el despertar del Ingeniero.",
  ui_story_1018_10181501_136_dialog_content = "Dado que la campaña en el frente ha terminado, el Ingeniero debería despertar pronto.",
  ui_story_1018_10181501_137_dialog_content = "...",
  ui_story_1018_10181501_138_dialog_content = "El Ingeniero, el primer verdadero Señor de la Ciudad de Gannon.",
  ui_story_1018_10181501_139_dialog_content = "Si algo tan antiguo como eso realmente despierta, bueno... estoy un poco emocionado por ello.",
  ui_story_1018_10181501_140_dialog_content = "Je, aún más para mí.",
  ui_story_1018_10181501_141_dialog_content = "*Estático*",
  ui_story_1018_10181501_142_dialog_content = "¿Otra vez?",
  ui_story_1018_10181501_143_dialog_content = "No... Yo...",
  ui_story_1018_10181501_144_dialog_content = "Parece... Motor...",
  ui_story_1018_10181501_145_dialog_content = "Ha despertado...",
  ui_story_1019_10190101_1_dialog_content = "<color=#e8d9bb>Zumbido...</color>",
  ui_story_1019_10190101_2_dialog_content = "En efecto, la Semilla no mejora las habilidades, sino que las convierte.",
  ui_story_1019_10190101_3_dialog_content = "Así que incluso cuando su acceso central es duplicado, Darkflow aún puede corromper en el pantano...",
  ui_story_1019_10190101_4_dialog_content = "Ja... ¿Cómo se te ocurrió esto?",
  ui_story_1019_10190101_5_dialog_content = "(Tos fuerte)",
  ui_story_1019_10190101_6_dialog_content = "Debería estar por aquí en alguna parte...",
  ui_story_1019_10190101_7_dialog_content = "... Pero estos resultados definitivamente valen la pena por los sujetos que murieron en Crepúsculo.",
  ui_story_1019_10190101_8_dialog_content = "<color=#e8d9bb>Sonido metálico-</color>",
  ui_story_1019_10190101_9_dialog_content = "Las últimas tres pastillas...",
  ui_story_1019_10190101_10_dialog_content = "Cuarenta años de investigación, y veinte de esos dedicados a compilar la <color=#FFB400>base de datos de genes especiales</color>... Hice todo lo que pude.",
  ui_story_1019_10190101_11_dialog_content = "¿Pero por qué aún me siento amargado e insatisfecho?",
  ui_story_1019_10190101_12_dialog_content = "Apenas estoy satisfecho con el resultado, <color=#FFB400>Robby</color>...",
  ui_story_1019_10190101_13_dialog_content = "<color=#e8d9bb>Silbido... Silbido...</color>",
  ui_story_1019_10190101_14_dialog_content = "Qué viento tan fuerte...",
  ui_story_1019_10190101_15_dialog_content = "Espera, ¿cómo es que estoy en las nubes?",
  ui_story_1019_10190101_16_dialog_content = "Esta sensación de ingravidez es familiar... ¡¿No estaré estrellándome de nuevo, verdad?!",
  ui_story_1019_10190101_17_dialog_content = "¡Tengo que mantener la calma! Soroz me atrapará.",
  ui_story_1019_10190101_18_dialog_content = "¿Me estás llamando, Navegante?",
  ui_story_1019_10190101_19_dialog_content = "Tu vuelo de hoy coincide con lo revuelto que ha estado mi estómago últimamente. ¿A dónde vamos?",
  ui_story_1019_10190101_20_dialog_content = "Nos dirigimos al <color=#FFB400>Campo de Batalla de la Cumbre</color> para una misión de lanzamiento aéreo.",
  ui_story_1019_10190101_21_dialog_content = "... ¿Una misión de lanzamiento aéreo? ¿Para quién?",
  ui_story_1019_10190101_22_dialog_content = "La siguiente directiva de combate ha sido transmitida a todos los navegantes:",
  ui_story_1019_10190101_23_dialog_content = "\"Todos los navegadores, por favor diríjanse al Campo de Batalla de la Cumbre para dejar sus armas.\"",
  ui_story_1019_10190101_24_dialog_content = "Velocidad reducida para el descenso final. Esperando órdenes, Navegador. Por favor, asegura el aterrizaje seguro de las armas.",
  ui_story_1019_10190101_25_dialog_content = "¡E-Espera, de qué estás hablando?!",
  ui_story_1019_10190101_26_dialog_content = "¿Soroz? ¡Soroz...!",
  ui_story_1019_10190101_27_dialog_content = "¡¡¡Ahhhhhhhh!!!",
  ui_story_1019_10190101_28_dialog_content = "¡Roaaarrrr!",
  ui_story_1019_10190101_29_dialog_content = "¿De dónde vienen estos Eclipsites?! ¿Por qué... estoy cayendo con los Eclipsites?!",
  ui_story_1019_10190101_30_dialog_content = "¡Soroz! ¿Qué está pasando?!",
  ui_story_1019_10190101_31_dialog_content = "Navegador, por favor asegúrate de que todas las armas aterricen de manera segura. Este es tu deber como Celestita.",
  ui_story_1019_10190101_32_dialog_content = "¡Roaaarrrr!",
  ui_story_1019_10190101_33_dialog_content = "Tonterías... ¡E-Esto debe ser un sueño!",
  ui_story_1019_10190101_34_dialog_content = "Navegante, no estás soñando.",
  ui_story_1019_10190101_35_dialog_content = "Las coordenadas confirman que este es el Campo de Batalla de la Cumbre. Por favor, asegúrate de que todas las armas aterricen de manera segura.",
  ui_story_1019_10190101_36_dialog_content = "¿Espira...? ¡Pero esto es Eraveil! ¡Reconozco ese alto Obelisco del Retorno!",
  ui_story_1019_10190101_37_dialog_content = "¿Son esos... Caelestites corriendo por todas partes en el suelo? ¿O son ellos...",
  ui_story_1019_10190101_38_dialog_content = "Esto es un sueño. ¡Debe ser un sueño! Quizás despertaré después de caer al suelo...",
  ui_story_1019_10190101_39_dialog_content = "¡Al diablo con esto!",
  ui_story_1019_10190101_40_dialog_content = "...",
  ui_story_1019_10190101_41_dialog_content = "... Todavía estoy en el aire...",
  ui_story_1019_10190101_42_dialog_content = "Cuando te resignas a una caída inevitable, por alguna razón el viaje hacia abajo se vuelve extremadamente largo...",
  ui_story_1019_10190101_43_dialog_content = "<color=#e8d9bb>Auge-!!!</color>",
  ui_story_1019_10190101_44_dialog_content = "¡Aah—!",
  ui_story_1019_10190101_45_dialog_content = "...",
  ui_story_1019_10190101_46_dialog_content = "¿Estás despierto ahora?",
  ui_story_1019_10190101_47_dialog_content = "Noche Blanca en lo alto, hemos llegado a salvo.",
  ui_story_1019_10190101_48_dialog_content = "Leo... Joselyne? ¿Dónde estamos...?",
  ui_story_1019_10190101_49_dialog_content = "De vuelta en Eraveil.",
  ui_story_1019_10190101_50_dialog_content = "El dirigible se balanceaba tan fuerte que los soldados apenas podían mantenerse de pie, sin embargo, tú estabas profundamente dormido...",
  ui_story_1019_10190101_51_dialog_content = "Eraveil...",
  ui_story_1019_10190101_52_dialog_content = "Correcto... sí, este es Eraveil...",
  ui_story_1019_10190101_53_dialog_content = "Siguiendo las campañas en Crepúsculo y en la línea defensiva de Illumina, montamos un dirigible de Lumopolis de regreso a Eraveil...",
  ui_story_1019_10190101_54_dialog_content = "¡Así que todo fue solo un sueño... ¡Uf!",
  ui_story_1019_10190101_55_dialog_content = "¿Estás seguro de que estás bien, corriendo así?",
  ui_story_1019_10190101_56_dialog_content = "¡Estoy bien! Esto es maravilloso, Leo!",
  ui_story_1019_10190101_57_dialog_content = "La ingravidez se sentía tan real, como revivir un recuerdo...",
  ui_story_1019_10190101_58_dialog_content = "¡Pero fue un sueño... Gracias a Dios que fue un sueño!",
  ui_story_1019_10190101_59_dialog_content = "Eh, puedes soltarme ya...",
  ui_story_1019_10190101_60_dialog_content = "<color=#e8d9bb>(Acurrucarse)</color>",
  ui_story_1019_10190101_61_dialog_content = "Mis zapatos están sucios, PlayerName. Probablemente no deberías pisarlos.",
  ui_story_1019_10190101_62_dialog_content = "Oh, lo siento... Pero no creo que sea yo...",
  ui_story_1019_10190101_63_dialog_content = "Cachero... Cachero...",
  ui_story_1019_10190101_64_dialog_content = "¿Qué es esta cosa blanca en forma de cubo y por qué está abrazando mis botas?",
  ui_story_1019_10190101_65_dialog_content = "Ese es Chubb, mi amigo de Eraveil. Pero, ¿por qué parece borracho?",
  ui_story_1019_10190101_66_dialog_content = "Cachero... (Eructos)",
  ui_story_1019_10190101_67_dialog_content = "¡Oye! ¡Capitán Leo! ¡Lady Santa! ¡Caelestita!",
  ui_story_1019_10190101_68_dialog_content = "¡Por fin has vuelto!",
  ui_story_1019_10190101_69_dialog_content = "¡Cuando los hombres escucharon que habías expulsado a los Eclipsites de Twilight, inmediatamente comenzaron a regresar!",
  ui_story_1019_10190101_70_dialog_content = "¡Las damas de la cervecería y yo nos hemos encargado de preparar comida y vino para recompensar a todos los soldados!",
  ui_story_1019_10190101_71_dialog_content = "Aunque este vino no ha fermentado durante mucho tiempo, las frutas de Eraveil utilizadas para hacerlo le dan un sabor único.",
  ui_story_1019_10190101_72_dialog_content = "Así que Cachero tenía vino de frutas...",
  ui_story_1019_10190101_73_dialog_content = "Caelestite, ¿el Gran Mariscal Wrath está bien? ¿Por qué no la he visto?",
  ui_story_1019_10190101_74_dialog_content = "Wrath está más o menos bien, pero aún tuvo que regresar a Illumina para recuperarse.",
  ui_story_1019_10190101_75_dialog_content = "¡Eso es una gran noticia! Realmente quiero agradecer personalmente a todos los soldados que defendieron a Crepúsculo.",
  ui_story_1019_10190101_76_dialog_content = "¡Oh, cierto, Caelestite. Gracias por acogernos!",
  ui_story_1019_10190101_77_dialog_content = "No teníamos mucho que hacer aquí, así que alimentamos a los peces, elaboramos vino y eliminamos las plagas de los árboles frutales...",
  ui_story_1019_10190101_78_dialog_content = "¡Limpié mi habitación todos los días! Además, las banderas colgadas en la cima de los árboles fueron diseñadas especialmente para darte la bienvenida a ti y a todos los caballeros para tu triunfal regreso...",
  ui_story_1019_10190101_79_dialog_content = "Ustedes hicieron tanto...",
  ui_story_1019_10190101_80_dialog_content = "¡Por favor acepte nuestra buena voluntad como agradecimiento por acogernos aquí en Eraveil!",
  ui_story_1019_10190101_81_dialog_content = "¡Debería ser yo quien te agradezca! Eraveil nunca ha estado tan animado...",
  ui_story_1019_10190101_82_dialog_content = "Puedes quedarte en Eraveil todo el tiempo que quieras.",
  ui_story_1019_10190101_83_dialog_content = "Bueno, eso ciertamente significa mucho menos vino fino en Crepúsculo.",
  ui_story_1019_10190101_84_dialog_content = "Noche Blanca en lo alto. Gracias por todo lo que has hecho por Twilight, PlayerName.",
  ui_story_1019_10190101_85_dialog_content = "¡Cachero! Ch... ¡Eructo! Nngh...",
  ui_story_1019_10190101_86_dialog_content = "<color=#e8d9bb>¡¡¡Salud!!!</color>",
  ui_story_1019_10190101_87_dialog_content = "No pensé que tu viaje a Lumopolis sería tan emocionante. Gran trabajo al hacerlo todo por tu cuenta.",
  ui_story_1019_10190101_88_dialog_content = "No fue nada. Mientras todo saliera bien para Crepúsculo, todo lo que hice valió la pena.",
  ui_story_1019_10190101_89_dialog_content = "Sabía que tenía razón sobre ti. ¡Salud!",
  ui_story_1019_10190101_90_dialog_content = "...",
  ui_story_1019_10190101_91_dialog_content = "¿Qué pasa? ¿Ni siquiera una bebida después de la batalla?",
  ui_story_1019_10190101_92_dialog_content = "No puedo beber mucho debido a mi condición, así que dejaré la bebida para ustedes. No he visto una escena así en muchos años.",
  ui_story_1019_10190101_93_dialog_content = "Estoy de acuerdo.",
  ui_story_1019_10190101_94_dialog_content = "Pero los conozco bien. Incluso mientras beben y ríen, Crepúsculo sigue en sus mentes.",
  ui_story_1019_10190101_95_dialog_content = "Todos llevan el peso de la ansiedad sobre ellos, excepto esas criaturas de cubos blancos que están libres de preocupaciones.",
  ui_story_1019_10190101_96_dialog_content = "Así que he decidido volver mañana.",
  ui_story_1019_10190101_97_dialog_content = "Los guerreros duermen con el olor a pólvora. Después de acabar con estas bebidas, es hora de prepararnos para la próxima batalla.",
  ui_story_1019_10190101_98_dialog_content = "<color=#e8d9bb>La fiesta jubilosa continúa hasta tarde en la noche...</color>",
  ui_story_1019_10190101_99_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1019_10190101_100_dialog_content = "Oh, eres tú. ¿Cómo van las cosas en Eraveil?",
  ui_story_1019_10190101_101_dialog_content = "Bastante bien...",
  ui_story_1019_10190101_102_dialog_content = "Viendo que me contactas tan tarde en la noche, supongo que quieres una actualización sobre Vice?",
  ui_story_1019_10190101_103_dialog_content = "Sí... ¿Algún noticia sobre Vice y los demás?",
  ui_story_1019_10190101_104_dialog_content = "Hay noticias, pero aún no puedo darte nada definitivo sobre su estado exacto.",
  ui_story_1019_10190101_105_dialog_content = "¿En serio? ¡¿Qué sabes tú?!",
  ui_story_1019_10190101_106_dialog_content = "El escuadrón de rastreo liderado por Charon ha estado enviando señales de vuelta. Así es como nuestros equipos de reconocimiento comunican que las cosas van bien.",
  ui_story_1019_10190101_107_dialog_content = "Pero supongamos que se encuentran con algo problemático, como en Crepúsculo–",
  ui_story_1019_10190101_108_dialog_content = "Ya escuché sobre eso, por eso todavía estoy tratando de corroborar lo que está pasando. No te preocupes. Te avisaré cuando tenga algo.",
  ui_story_1019_10190101_109_dialog_content = "¿Entonces qué puedo hacer ahora? Estuve en la batalla en Crepúsculo. Tal vez pueda ayudar de alguna manera.",
  ui_story_1019_10190101_110_dialog_content = "No necesitas hacer nada, PlayerName.",
  ui_story_1019_10190101_111_dialog_content = "Pero–",
  ui_story_1019_10190101_112_dialog_content = "Aprecio el pensamiento, pero ahora no es el momento de venir a Illumina.",
  ui_story_1019_10190101_113_dialog_content = "Desde que perdimos el núcleo de Guardián Uno, ha habido problemas en las defensas de Gannon, y en eso estamos trabajando.",
  ui_story_1019_10190101_114_dialog_content = "El coraje y la buena voluntad que mostraste en Crepúsculo es la mayor ayuda que podrías darme.",
  ui_story_1019_10190101_115_dialog_content = "Me encargaré de las cosas desde aquí. Mira, es tarde. Ve a descansar un poco.",
  ui_story_1019_10190101_116_dialog_content = "Bien...",
  ui_story_1019_10190101_117_dialog_content = "...",
  ui_story_1019_10190101_118_dialog_content = "No puedes dormir porque estás preocupado por la seguridad de Vice.",
  ui_story_1019_10190101_119_dialog_content = "Sí...",
  ui_story_1019_10190101_120_dialog_content = "<color=#e8d9bb>Cuentas en silencio durante 20 segundos y tomas nota de tu ritmo cardíaco.</color>",
  ui_story_1019_10190101_121_dialog_content = "Soroz...",
  ui_story_1019_10190101_122_dialog_content = "Soroz siempre está aquí.",
  ui_story_1019_10190101_123_dialog_content = "La meditación de 20 segundos parece estar funcionando. Estoy llegando a mi lugar feliz.",
  ui_story_1019_10190101_124_dialog_content = "...",
  ui_story_1019_10190101_125_dialog_content = "He recuperado datos de imágenes de tus momentos más felices. Hacías paradas de cabeza cuando estabas feliz como un niño pequeño.",
  ui_story_1019_10190101_126_dialog_content = "¿Paradas de manos?!",
  ui_story_1019_10190101_127_dialog_content = "Incluso exigiste que los hiciera por ti también, sin importar qué.",
  ui_story_1019_10190101_128_dialog_content = "Bueno, una parada de cabeza es difícil ahora, para ti y para mí.",
  ui_story_1019_10190101_129_dialog_content = "Según mis cálculos, la probabilidad de que Soroz haga una parada de cabeza exitosa es del 59%. Necesitarías encontrar un lugar seguro en caso de que ejecute tal maniobra.",
  ui_story_1019_10190101_130_dialog_content = "¿Qué? ¡Jaja! Gracias por la advertencia, Soroz, pero creo que estamos bien como estamos.",
  ui_story_1019_10190101_131_dialog_content = "Hace mucho tiempo que no me siento en el control sin hacer nada, sin preocupaciones en el mundo...",
  ui_story_1019_10190101_132_dialog_content = "Lograste muchas cosas después de que mi Plantilla de Eco fuera dañada.",
  ui_story_1019_10190101_133_dialog_content = "Sí. Probablemente todavía no sabes lo que pasó, ahora que lo pienso...",
  ui_story_1019_10190101_134_dialog_content = "Después de que tu plantilla de eco fue dañada, seguimos tus coordenadas y encontramos una llave en una Subciudad.",
  ui_story_1019_10190101_135_dialog_content = "Luego seguimos el siguiente conjunto de coordenadas a Eraveil.",
  ui_story_1019_10190101_136_dialog_content = "Fue la primera vez que pisaba mi tierra natal, pero todos mis parientes ya se habían ido hace mucho tiempo.",
  ui_story_1019_10190101_137_dialog_content = "Ah, y casi perdimos a nuestro mejor amigo...",
  ui_story_1019_10190101_138_dialog_content = "Vi a los antepasados Caelestite abandonar el continente en sus Colosos, y luego presencié su regreso después de mucho tiempo.",
  ui_story_1019_10190101_139_dialog_content = "Al recordar, todo aún me parece un sueño. No puedo evitar preguntarme qué les sucedió al final.",
  ui_story_1019_10190101_140_dialog_content = "Después de eso, para salvarme, quedaste atrapado en el antiguo campo de batalla.",
  ui_story_1019_10190101_141_dialog_content = "Afortunadamente, encontramos la conciencia de Naviduz y finalmente te despertamos.",
  ui_story_1019_10190101_142_dialog_content = "...",
  ui_story_1019_10190101_143_dialog_content = "Independientemente de cuántas veces revise el registro de reparaciones, no se compara con escuchar la historia de ti, PlayerName.",
  ui_story_1019_10190101_144_dialog_content = "¿Así que lo sabías? ¿Acabo de contar todo eso para nada?",
  ui_story_1019_10190101_145_dialog_content = "El Oficial de Tecnología Gronru detalló tus experiencias en mi registro de reparaciones.",
  ui_story_1019_10190101_146_dialog_content = "¿Pero te importaría contarme sobre tu participación en el Ejercicio Militar Conjunto como representante de Caelestite?",
  ui_story_1019_10190101_147_dialog_content = "Oh, eso...",
  ui_story_1019_10190201_1_dialog_content = "<color=#e8d9bb>Varios días después: Centro Médico Illumina, mañana</color>",
  ui_story_1019_10190201_2_dialog_content = "Estos... fueron todos destruidos por mi mano...",
  ui_story_1019_10190201_3_dialog_content = "L-Lo siento, Dr. Chandra. Todavía no puedo controlarme...",
  ui_story_1019_10190201_4_dialog_content = "No hay necesidad de disculparse, Capitán Helios!",
  ui_story_1019_10190201_5_dialog_content = "El entrenamiento de combate con moderación sirve como una salida para tus emociones y es terapéutico.",
  ui_story_1019_10190201_6_dialog_content = "Realmente no sé qué puedo hacer por Illumina en este estado...",
  ui_story_1019_10190201_7_dialog_content = "Descarte ese pensamiento, Capitán Helios.",
  ui_story_1019_10190201_8_dialog_content = "Mencionaste muchos lugares en tus recuerdos, especialmente la Zona Oscura, que es una pieza clave de inteligencia para Illumina.",
  ui_story_1019_10190201_9_dialog_content = "En cuanto a las personas y encuentros que has estado intentando recordar...",
  ui_story_1019_10190201_10_dialog_content = "Nuestro cerebro procesa rutinariamente percepciones sensoriales y emociones cuando estamos cerca de otros.",
  ui_story_1019_10190201_11_dialog_content = "A medida que obtienes un mejor control sobre tus sentimientos, esas funciones también se restaurarán gradualmente.",
  ui_story_1019_10190201_12_dialog_content = "Ya veo... Entonces, debo trabajar más duro.",
  ui_story_1019_10190201_13_dialog_content = "Oh, arreglaré los modelos rotos, y... en el futuro, déjame ayudarte a construirlos también.",
  ui_story_1019_10190201_14_dialog_content = "¡Oh, y otra cosa! Lamento haberte despertado tan tarde en la noche...",
  ui_story_1019_10190201_15_dialog_content = "Está bien, Capitán Helios. Este es mi trabajo. (Bosteza)",
  ui_story_1019_10190201_16_dialog_content = "Bueno entonces, dejémoslo así por hoy.",
  ui_story_1019_10190201_17_dialog_content = "Espero que sigas anotando tus pensamientos y lo que sueñas.",
  ui_story_1019_10190201_18_dialog_content = "No sé por qué el Gran Mariscal quiere ver estas notas, pero obviamente es importante para ella.",
  ui_story_1019_10190201_19_dialog_content = "Y no pases por alto ninguna emoción o imagen abrupta que venga a la mente.",
  ui_story_1019_10190201_20_dialog_content = "Debajo de una llama suele haber leña que ha estado ardiendo durante mucho tiempo.",
  ui_story_1019_10190201_21_dialog_content = "Nunca olvidaré nada de ese mundo frío y oscuro mientras viva.",
  ui_story_1019_10190201_22_dialog_content = "Gracias de nuevo, Dr. Chandra.",
  ui_story_1019_10190201_23_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1019_10190201_24_dialog_content = "¿Quién me está enviando mensajes tan temprano en la mañana?",
  ui_story_1019_10190201_25_dialog_content = "<color=#e8d9bb>Whoosh, whoosh—</color>",
  ui_story_1019_10190201_26_dialog_content = "(Eclipsiano) 1011X.",
  ui_story_1019_10190201_27_dialog_content = "(Eclipsiano) Sí, hemos conseguido el último <color=#FFB400>Anillo de Conducción</color>.",
  ui_story_1019_10190201_28_dialog_content = "(Eclipsiano) 01X11.",
  ui_story_1019_10190201_29_dialog_content = "(Eclipsiano) Leí su honorable nombre y espero que lo mire...",
  ui_story_1019_10190201_30_dialog_content = "(Eclipsian) Esperamos humildemente tu llegada...",
  ui_story_1019_10190201_31_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1019_10190201_32_dialog_content = "¿Dónde estoy?",
  ui_story_1019_10190201_33_dialog_content = "¿Qué son estas figuras sombrías?",
  ui_story_1019_10190201_34_dialog_content = "¡Deja de mirar, PlayerName!",
  ui_story_1019_10190201_35_dialog_content = "Espera, ¿eres tú, Vice?",
  ui_story_1019_10190201_36_dialog_content = "¡Eres tú! ¡Realmente eres tú, Vice!",
  ui_story_1019_10190201_37_dialog_content = "Vete a casa.",
  ui_story_1019_10190201_38_dialog_content = "¿Estás perdido, Vice? ¿Estás en peligro?",
  ui_story_1019_10190201_39_dialog_content = "¡Rápido, dime dónde estás! Te sacaré de allí.",
  ui_story_1019_10190201_40_dialog_content = "Vete a casa.",
  ui_story_1019_10190201_41_dialog_content = "...",
  ui_story_1019_10190201_42_dialog_content = "¿A dónde vas, Vice?",
  ui_story_1019_10190201_43_dialog_content = "Vete a casa.",
  ui_story_1019_10190201_44_dialog_content = "¿Casa? ¿Dónde estoy?",
  ui_story_1019_10190201_45_dialog_content = "Vete a casa.",
  ui_story_1019_10190201_46_dialog_content = "¿Quién eres? ¿Dónde está Vice?",
  ui_story_1019_10190201_47_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1019_10190201_48_dialog_content = "Es peligroso aquí, PlayerName!",
  ui_story_1019_10190201_49_dialog_content = "¡Vice! ¿Dónde estás?!",
  ui_story_1019_10190201_50_dialog_content = "<color=#e8d9bb>Bip-bip-bip-</color>",
  ui_story_1019_10190201_51_dialog_content = "Vice... Vice!",
  ui_story_1019_10190201_52_dialog_content = "¿Otra pesadilla, PlayerName?",
  ui_story_1019_10190201_53_dialog_content = "Sueño...",
  ui_story_1019_10190201_54_dialog_content = "Estaba soñando otra vez...",
  ui_story_1019_10190201_55_dialog_content = "Algo va mal, Soroz. Desde que volví a Eraveil, no dejo de tener sueños extraños...",
  ui_story_1019_10190201_56_dialog_content = "Se siente más como si estuviera sintiendo cosas... pero tampoco puedo describirlo realmente.",
  ui_story_1019_10190201_57_dialog_content = "Quizás estás demasiado estresado, PlayerName. Has estado aquí esperando noticias varias noches seguidas. Deberías volver a tu habitación para descansar un poco.",
  ui_story_1019_10190201_58_dialog_content = "¿Qué hora es ahora?",
  ui_story_1019_10190201_59_dialog_content = "El sol sale en tres horas.",
  ui_story_1019_10190201_60_dialog_content = "Otro día ha pasado...",
  ui_story_1019_10190201_61_dialog_content = "Es terrible simplemente sentarse aquí esperando, impotente para hacer algo...",
  ui_story_1019_10190201_62_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1019_10190201_63_dialog_content = "Reconozco ese sonido... Has encontrado más coordenadas antiguas en los datos de Naviduz.",
  ui_story_1019_10190201_64_dialog_content = "Los llamas \"ecos del pasado\".",
  ui_story_1019_10190201_65_dialog_content = "Sí.",
  ui_story_1019_10190201_66_dialog_content = "Naviduz repitió estas coordenadas una y otra vez antes de caer en silencio, pero nunca se encontró una ubicación correspondiente en esta tierra.",
  ui_story_1019_10190201_67_dialog_content = "¿Es eso porque el terreno ha cambiado?",
  ui_story_1019_10190201_68_dialog_content = "El tiempo también ha cambiado.",
  ui_story_1019_10190201_69_dialog_content = "Aún así nunca dejaste de buscar...",
  ui_story_1019_10190201_70_dialog_content = "Puedo restaurar completamente mi conciencia una vez que haya examinado todos los datos.",
  ui_story_1019_10190201_71_dialog_content = "De hecho, ya eres el Soroz que conozco.",
  ui_story_1019_10190201_72_dialog_content = "Nuestra compatibilidad psíquica es solo del 90% en comparación con la anterior a la reparación, PlayerName.",
  ui_story_1019_10190201_73_dialog_content = "¿En serio? No siento ninguna diferencia.",
  ui_story_1019_10190201_74_dialog_content = "Continuaré aprendiendo.",
  ui_story_1019_10190201_75_dialog_content = "Quiero hacerte una pregunta...",
  ui_story_1019_10190201_76_dialog_content = "Sé que Reinhardt me dijo que no me preocupara por Illumina, pero aún así lo hago.",
  ui_story_1019_10190201_77_dialog_content = "Cuanto más tranquilo está en Eraveil, más ansioso me pongo. Me hace pensar que cuando sentí el latido del corazón de Vice...",
  ui_story_1019_10190201_78_dialog_content = "ella estaba tratando de decirme algo, pero no pude entenderlo...",
  ui_story_1019_10190201_79_dialog_content = "Entonces, ¿qué es lo que te gustaría preguntarme, PlayerName?",
  ui_story_1019_10190201_80_dialog_content = "¡No, ya he tomado una decisión! Incluso si Reinhardt se niega a dejarme ir a Illumina, ¡yo—",
  ui_story_1019_10190201_81_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1019_10190201_82_dialog_content = "¿Por qué es ella...",
  ui_story_1019_10190201_83_dialog_content = "¿Es la noticia que has estado esperando?",
  ui_story_1019_10190201_84_dialog_content = "¡Sí! ¡Mira!",
  ui_story_1019_10190201_85_dialog_content = "...",
  ui_story_1019_10190201_86_dialog_content = "\"Ven a Illumina ahora\"",
  ui_story_1019_10190201_87_dialog_content = "\"Lo antes posible\"",
  ui_story_1019_10190301_1_dialog_content = "<color=#e8d9bb>Patio de Servicio Illumina</color>",
  ui_story_1019_10190301_2_dialog_content = "Oh no, olvidé preguntar a dónde debería ir.",
  ui_story_1019_10190301_3_dialog_content = "Disculpe, señor, puede-",
  ui_story_1019_10190301_4_dialog_content = "No se permite la entrada de civiles al patio de servicio. Por favor, desaloje el lugar inmediatamente.",
  ui_story_1019_10190301_5_dialog_content = "Oh, no soy un civil. Soy un Caeles—",
  ui_story_1019_10190301_6_dialog_content = "¡Reúnanse!",
  ui_story_1019_10190301_7_dialog_content = "¡Sí!",
  ui_story_1019_10190301_8_dialog_content = "De nuevo, este lugar no es seguro debido a vulnerabilidades en sus defensas. Por favor, sal ahora.",
  ui_story_1019_10190301_9_dialog_content = "Vulnerabilidades...",
  ui_story_1019_10190301_10_dialog_content = "Parece que la seguridad sigue siendo un problema incluso con todos estos soldados.",
  ui_story_1019_10190301_11_dialog_content = "¡Ja! Toma esto, PlayerName!",
  ui_story_1019_10190301_12_dialog_content = "Espera un minuto... ¿Quién eres tú otra vez?",
  ui_story_1019_10190301_13_dialog_content = "¡Vamos, me olvidaste?!",
  ui_story_1019_10190301_14_dialog_content = "Oh, ahora recuerdo. Tú eres...",
  ui_story_1019_10190301_15_option_content = "Verdecito",
  ui_story_1019_10190301_16_dialog_content = "No, me refiero a Sean!",
  ui_story_1019_10190301_17_dialog_content = "(No puedo creer que dejé escapar mi primera impresión de él...)",
  ui_story_1019_10190301_18_dialog_content = "Ja, bueno, ¡algunas personas sí me llaman así!",
  ui_story_1019_10190301_19_option_content = "Cuervo",
  ui_story_1019_10190301_20_dialog_content = "No, espera, no es Crow... ¡Es Sean!",
  ui_story_1019_10190301_21_dialog_content = "Hmm, comparado con Crow, supongo que soy bastante imperceptible.",
  ui_story_1019_10190301_22_option_content = "sean",
  ui_story_1019_10190301_23_dialog_content = "Así es. Tú eres Sean...",
  ui_story_1019_10190301_24_dialog_content = "¡Lo siento! Te ves... diferente, de lo que recuerdo.",
  ui_story_1019_10190301_25_dialog_content = "Bueno, por supuesto. ¡He estado practicando mis habilidades de boxeo y me hago más fuerte cada día!",
  ui_story_1019_10190301_26_dialog_content = "No importa, te daré un pase esta vez.",
  ui_story_1019_10190301_27_dialog_content = "¿Qué haces aquí, Sean?",
  ui_story_1019_10190301_28_dialog_content = "Vuelvo regularmente a Gannon para un chequeo físico. Llegué temprano esta vez pero no esperaba encontrarte.",
  ui_story_1019_10190301_29_dialog_content = "Entonces, ¿por qué no te uniste a la patrulla y ayudaste a desenmascarar a los Eclipsites?",
  ui_story_1019_10190301_30_dialog_content = "¡Saludos, oficial Vivian! Es porque yo...",
  ui_story_1019_10190301_31_dialog_content = "Solo bromeaba. Ve a hacer lo que se supone que debes hacer y ten cuidado.",
  ui_story_1019_10190301_32_dialog_content = "¡Sí, señora! ¡Nos vemos, PlayerName!",
  ui_story_1019_10190301_33_dialog_content = "¡Nos vemos, Sean!",
  ui_story_1019_10190301_34_dialog_content = "Como predijo el Gran Mariscal, la falta de noticias te llevaría inevitablemente a Illumina.",
  ui_story_1019_10190301_35_dialog_content = "Ella pensó que vendría por mi cuenta, así que te tenía a ti...",
  ui_story_1019_10190301_36_dialog_content = "Por supuesto. Conocemos cada movimiento que tú y tu Colossus hacen en Astra como la palma de nuestras manos.",
  ui_story_1019_10190301_37_dialog_content = "Pero Illumina es un desastre en este momento; los altos mandos están ocupados resolviendo una lucha de poder.",
  ui_story_1019_10190301_38_dialog_content = "Y como ya has visto, la seguridad sigue siendo un gran problema.",
  ui_story_1019_10190301_39_dialog_content = "Oh, es el Gran Mariscal...",
  ui_story_1019_10190301_40_option_content = "¿Reinhardt?",
  ui_story_1019_10190301_41_dialog_content = "¿Quién más? Ella es la líder espiritual de cada soldado en Illumina. Nadie se le acerca.",
  ui_story_1019_10190301_42_option_content = "¿Ira?",
  ui_story_1019_10190301_43_dialog_content = "Wrath es la Gran Mariscal en nombre, pero le dijo al comité que devolvería la posición a Reinhardt.",
  ui_story_1019_10190301_44_dialog_content = "Sin embargo, independientemente de quién asuma el papel de Gran Mariscal, ninguno parece alinearse con los deseos del comité, pero el ejército no puede permitirse carecer de un mando unificado...",
  ui_story_1019_10190301_45_dialog_content = "Entonces, el comité retrasó la investigación sobre la supuesta colusión del Gran Mariscal, y decidió que los asuntos de Illuminan serían supervisados conjuntamente por el comité y el ejército.",
  ui_story_1019_10190301_46_dialog_content = "Parece que tu trabajo se ha vuelto más difícil.",
  ui_story_1019_10190301_47_dialog_content = "En efecto. Es tan desorganizado en Illumina que la mayoría de las veces ni siquiera puedo llegar al mariscal.",
  ui_story_1019_10190301_48_dialog_content = "¡No es de extrañar que no haya sabido de ella... Perdón por hacer las cosas más difíciles para todos ustedes!",
  ui_story_1019_10190301_49_dialog_content = "Entonces... ¿Wrath todavía quiere duelar con Reinhardt?",
  ui_story_1019_10190301_50_dialog_content = "Ay, sí. Obviamente no para el papel de Gran Mariscal, pero eso no la detiene de querer luchar Reinhardt.",
  ui_story_1019_10190301_51_dialog_content = "Suena justo como ella... ¿Y cómo está Wrath? ¿La cirugía salió bien?",
  ui_story_1019_10190301_52_dialog_content = "También quiero saber eso, pero la burocracia es tan densa en este momento que cualquier cosa que involucre el Programa Phospherus está bloqueada.",
  ui_story_1019_10190301_53_dialog_content = "Entonces, si estás aquí para visitarla, eso es un rotundo no se puede.",
  ui_story_1019_10190301_54_dialog_content = "En realidad, vine aquí para–",
  ui_story_1019_10190301_55_dialog_content = "¡Graaagh!",
  ui_story_1019_10190301_56_dialog_content = "¡Jefe de personal! Los mecánicos dijeron que el conducto de ventilación en el lado oeste del patio de servicio está fuera de servicio. ¡Los Eclipsites deben haber entrado por allí!",
  ui_story_1019_10190301_57_dialog_content = "¡Finalmente, encontramos la brecha después de toda una noche!",
  ui_story_1019_10190301_58_dialog_content = "¡Pónganse en formación, cubran a los ingenieros y síganme para matar a los Eclipsites!",
  ui_story_1019_10190301_59_dialog_content = "¡Sí, señora!!!",
  ui_story_1019_10190301_60_dialog_content = "¡Oye, tú al frente, fuera del camino!",
  ui_story_1019_10190301_61_dialog_content = "¡Jefe de personal! Detrás de ti... ¡Los Eclipsites han estrangulado a alguien hasta la muerte!",
  ui_story_1019_10190301_62_dialog_content = "¿Podría ser eso...?",
  ui_story_1019_10190301_63_dialog_content = "¡Boo boo boo!",
  ui_story_1019_10190301_64_dialog_content = "Delante de tanta gente también...",
  ui_story_1019_10190301_65_dialog_content = "¡Boo boo boo!",
  ui_story_1019_10190301_66_dialog_content = "Vale, vale. Aunque aún no es hora de hacer ejercicio...",
  ui_story_1019_10190301_67_dialog_content = "¡Prepárate para ejecutar el programa!",
  ui_story_1019_10190301_68_dialog_content = "¡Bu!",
  ui_story_1019_10190301_69_dialog_content = "¿Quién en el mundo es ese?",
  ui_story_1019_10190402_1_dialog_content = "Subir, subir... Hmm, todavía no hay suficientes datos sobre actividades al aire libre en absoluto.",
  ui_story_1019_10190402_2_dialog_content = "Así es como se ve cuando un científico pelea...",
  ui_story_1019_10190402_3_dialog_content = "Oye, antes de que empieces a repetir estereotipos sobre los científicos, permíteme recordarte...",
  ui_story_1019_10190402_4_dialog_content = "No todos somos unos aburridos, deprimentes y poco atléticos ratones de biblioteca.",
  ui_story_1019_10190402_5_dialog_content = "No no, eso no es lo que quise decir...",
  ui_story_1019_10190402_6_dialog_content = "¿Quién es este, PlayerName?",
  ui_story_1019_10190402_7_dialog_content = "Algol, un científico del Consejo Científico de Illumina.",
  ui_story_1019_10190402_8_dialog_content = "Ella me invitó a Illumina, pero creo... ella no es exactamente la misma que cuando la vi por última vez.",
  ui_story_1019_10190402_9_dialog_content = "¿El Consejo de Ciencias? Esta es la primera vez que veo a uno de ellos en persona.",
  ui_story_1019_10190402_10_dialog_content = "¡Con-firmado!",
  ui_story_1019_10190402_11_dialog_content = "¡Hola, Caelestita! Además, ¿te invité?",
  ui_story_1019_10190402_12_dialog_content = "Hola, Profesor Algol. Soy Vivian, el Jefe de Estado Mayor de la Federación Illumina.",
  ui_story_1019_10190402_13_dialog_content = "Bueno... ya que estás aquí, sígueme.",
  ui_story_1019_10190402_14_dialog_content = "Profesor Algol, me gustaría informarle que el Gran Mariscal me envió para ayudar a PlayerName en Illumina.",
  ui_story_1019_10190402_15_dialog_content = "Debo ser informado sobre sus planes e informarlo al Gran Mariscal.",
  ui_story_1019_10190402_16_dialog_content = "Nuestro encuentro fue espontáneo y no quedará registrado. Si insistes en hacer un registro, usa esto.",
  ui_story_1019_10190402_17_dialog_content = "Te refieres a...",
  ui_story_1019_10190402_18_dialog_content = "Tu cabeza.",
  ui_story_1019_10190402_19_dialog_content = "¡Bu!",
  ui_story_1019_10190402_20_dialog_content = "...",
  ui_story_1019_10190402_21_dialog_content = "Por razones de seguridad, sin embargo, tengo una pregunta que hacerte. Eso... la cosa que estaba luchando a tu lado no es un arma normal, ¿verdad?",
  ui_story_1019_10190402_22_dialog_content = "¡Por supuesto que no! Su nombre es Bool, y es mi p–",
  ui_story_1019_10190402_23_dialog_content = "¡Booo!",
  ui_story_1019_10190402_24_dialog_content = "¡Eso duele! Detente, amigo...!",
  ui_story_1019_10190402_25_dialog_content = "Vaya... Mm, sí, ¡eso se siente bien! Sube un poco más...",
  ui_story_1019_10190402_26_dialog_content = "¿Bool también da masajes?",
  ui_story_1019_10190402_27_dialog_content = "Bool dice que has ganado unos cuantos kilos desde la última vez.",
  ui_story_1019_10190402_28_dialog_content = "¡¿Qué?! ¿Cómo habla?",
  ui_story_1019_10190402_29_dialog_content = "Como Caelestite, deberías saber que no toda la comunicación ocurre verbalmente.",
  ui_story_1019_10190402_30_dialog_content = "Nosotros—Bool y yo—tenemos una forma única de hablar el uno con el otro.",
  ui_story_1019_10190402_31_dialog_content = "Por ejemplo, ¡Bool ahora dice que está muy satisfecho con el sistema de combate que actualicé para él!",
  ui_story_1019_10190402_32_dialog_content = "¡Bu!",
  ui_story_1019_10190402_33_dialog_content = "¡Jeje! ¡No lo menciones!",
  ui_story_1019_10190402_34_dialog_content = "(Esa gran entrada de ellos fue algo horrible...)",
  ui_story_1019_10190402_35_dialog_content = "¿Hmm? Caelestita, ¿tienes algo que decir?",
  ui_story_1019_10190402_36_dialog_content = "¡Bu!",
  ui_story_1019_10190402_37_dialog_content = "En efecto... También veo el desdén vagamente oculto en su rostro.",
  ui_story_1019_10190402_38_dialog_content = "¿Tú también podías decir lo que estaba pensando?",
  ui_story_1019_10190402_39_dialog_content = "Jaja, relájate! Vamos.",
  ui_story_1019_10190402_40_dialog_content = "Oh... ¿Qué era tan urgente que necesitabas que viniera a Illumina, Profesor Algol?",
  ui_story_1019_10190402_41_dialog_content = "¿Viniste sin siquiera saber para qué venías?",
  ui_story_1019_10190402_42_dialog_content = "Aunque eso encaja con el estereotipo que tengo de los Caelestites.",
  ui_story_1019_10190402_43_dialog_content = "¿Todavía recuerdas los datos de personalidad de Naviduz que copiaste para restaurar Soroz?",
  ui_story_1019_10190402_44_dialog_content = "Las coordenadas en los datos no tenían ubicaciones coincidentes.",
  ui_story_1019_10190402_45_dialog_content = "Pero Illumina recientemente actualizó partes de su mapa de la Noche Eterna, y podría haber pistas para encontrar el núcleo de Guardian One en algún lugar.",
  ui_story_1019_10190402_46_dialog_content = "Es posible que los datos incluso proporcionen respuestas a las coordenadas desconocidas descubiertas por el escuadrón de rastreo.",
  ui_story_1019_10190402_47_dialog_content = "¿En serio? ¡Eso es genial! ¿Qué quieres que haga?",
  ui_story_1019_10190402_48_dialog_content = "No necesitamos tus habilidades psíquicas esta vez, sino la capacidad de aprendizaje de Soroz.",
  ui_story_1019_10190402_49_dialog_content = "¿Capacidad de aprendizaje?",
  ui_story_1019_10190402_50_dialog_content = "Sí. La capacidad de Soroz para recuperar la conciencia en tan poco tiempo demuestra que es un aprendiz rápido.",
  ui_story_1019_10190402_51_dialog_content = "Me gustaría aprovechar esa habilidad para mejorar la eficiencia del proceso de mapeo de la Zona Oscura, mientras me proporciona nuevas perspectivas para mi investigación.",
  ui_story_1019_10190402_52_dialog_content = "Eso suena impresionante... De todos modos, estaremos encantados de ayudar.",
  ui_story_1019_10190402_53_dialog_content = "Luego conecta Soroz a mi <color=#FFB400>terminal</color>. Eso llevará algún tiempo.",
  ui_story_1019_10190402_54_dialog_content = "En cuanto a cuánto tiempo exactamente, déjame ver...",
  ui_story_1019_10190402_55_dialog_content = "¿No es tu <color=#FFB400>terminal</color> esa cosa en tu muñeca?",
  ui_story_1019_10190402_56_dialog_content = "Este es una pulsera tecnológica. Por supuesto, prefiero llamarlo brazalete deportivo.",
  ui_story_1019_10190402_57_dialog_content = "Oh, es hora de hacer ejercicio. ¿Quieren unirse a mí?",
  ui_story_1019_10190402_58_dialog_content = "Pero es temprano en la mañana. ¿Suele hacer ejercicio a esta hora del día, Profesor Algol?",
  ui_story_1019_10190402_59_dialog_content = "Así es como funciona mi reloj biológico.",
  ui_story_1019_10190402_60_dialog_content = "¿Qué tal si llamamos a la batalla que acabamos de tener un entrenamiento? Entonces, ¡podemos ponernos manos a la obra de inmediato!",
  ui_story_1019_10190402_61_dialog_content = "...",
  ui_story_1019_10190402_62_dialog_content = "Mayordomo... Mayordomo... Abre la puerta y mientras tanto, sírveme tres tazas de café.",
  ui_story_1019_10190402_63_dialog_content = "Guardian One se niega. Guardian One no es un mayordomo.",
  ui_story_1019_10190402_64_dialog_content = "...",
  ui_story_1019_10190402_65_dialog_content = "Uh, bueno, tal vez se acaba de levantar...",
  ui_story_1019_10190501_1_dialog_content = "<color=#e8d9bb>Oficina de Algol</color>",
  ui_story_1019_10190501_2_dialog_content = "¡Bienvenido a mi laboratorio! Está un poco desordenado. De todos modos, encuentra un lugar para sentarte.",
  ui_story_1019_10190501_3_dialog_content = "No sabía que un laboratorio de Illumina podría verse así...",
  ui_story_1019_10190501_4_dialog_content = "Plantas en maceta, máquinas de entrenamiento y todas estas cosas de aspecto genial...",
  ui_story_1019_10190501_5_dialog_content = "¿Es esto una cama o un sofá?",
  ui_story_1019_10190501_6_dialog_content = "¿Por qué no te acuestas en él y lo compruebas por ti mismo? El botón de masaje está justo ahí.",
  ui_story_1019_10190501_7_dialog_content = "Vaya, esto es extremadamente cómodo. Me está dando sueño.",
  ui_story_1019_10190501_8_dialog_content = "Esto es tan diferente al estilo típico de Illumina...",
  ui_story_1019_10190501_9_dialog_content = "Así es. Nada de esta configuración cumple con las Regulaciones de Vivienda de Illumina...",
  ui_story_1019_10190501_10_dialog_content = "¿Eh? Todo lo que ves aquí fue construido principalmente con materiales viejos y reciclados.",
  ui_story_1019_10190501_11_dialog_content = "Y he integrado mis espacios de vida y trabajo en una sola habitación. ¿No cuenta eso como conservación de recursos?",
  ui_story_1019_10190501_12_dialog_content = "Por no mencionar que es contra las Regulaciones para los Soldados Illumina que el Jefe de Personal reciba un masaje durante el horario de trabajo.",
  ui_story_1019_10190501_13_dialog_content = "T-Tú no me viste recibiendo un masaje...",
  ui_story_1019_10190501_14_dialog_content = "¿No acabas de decir que te estaba dando sueño?",
  ui_story_1019_10190501_15_dialog_content = "No te quedes ahí parado, Caelestite. ¿Ves esa rueda allá?",
  ui_story_1019_10190501_16_dialog_content = "Estar de pie en él durante 10 minutos quemará más libras que correr diez vueltas alrededor del Colossus.",
  ui_story_1019_10190501_17_dialog_content = "Hablemos de eso más tarde...",
  ui_story_1019_10190501_18_dialog_content = "¡Bip!",
  ui_story_1019_10190501_19_dialog_content = "¡Hace un tiempo que no te veo, Caelestite!",
  ui_story_1019_10190501_20_dialog_content = "¡Hola, Guardián Uno! ¡Así que eres el droide mayordomo!",
  ui_story_1019_10190501_21_dialog_content = "Guardian One nunca aceptó ser el mayordomo de Algol.",
  ui_story_1019_10190501_22_dialog_content = "... Entonces, ¿qué es eso que llevas?",
  ui_story_1019_10190501_23_dialog_content = "Estas son dos tazas de café refrescante para los dos invitados, hechas especialmente por Guardian One. Algol tendrá que hacer la suya propia.",
  ui_story_1019_10190501_24_dialog_content = "Eso es injusto...",
  ui_story_1019_10190501_25_dialog_content = "Oye, ¿le pusiste mantequilla a esto? Solo he probado café de este sabor en Umbraton antes.",
  ui_story_1019_10190501_26_dialog_content = "Esta es una mezcla especial que debería adaptarse a tu gusto.",
  ui_story_1019_10190501_27_dialog_content = "Me gusta mucho.",
  ui_story_1019_10190501_28_dialog_content = "Déjame tomar un sorbo...",
  ui_story_1019_10190501_29_dialog_content = "Hmm... Estoy percibiendo el aroma de hierba fresca. ¡Es sorprendentemente delicioso!",
  ui_story_1019_10190501_30_dialog_content = "Es una mezcla especial de Eraveil.",
  ui_story_1019_10190501_31_dialog_content = "Algol ha desarrollado muchos programas interesantes recientemente. Guardian One puede hacer café con sabores especiales de acuerdo con tus hábitos alimenticios en Illumina.",
  ui_story_1019_10190501_32_dialog_content = "Realmente haces un buen trabajo como mayordomo, ya sabes.",
  ui_story_1019_10190501_33_dialog_content = "...",
  ui_story_1019_10190501_34_dialog_content = "¡Booo!",
  ui_story_1019_10190501_35_dialog_content = "¡Está bien, tenemos las configuraciones. Comenzaré a ejecutar los datos!",
  ui_story_1019_10190501_36_dialog_content = "Introducidor, introducidor... ¿Dónde está esa maldita cosa?",
  ui_story_1019_10190501_37_dialog_content = "Vaya... Recógelo por mí, ¿lo harías, Guardián Uno?",
  ui_story_1019_10190501_38_dialog_content = "...",
  ui_story_1019_10190501_39_dialog_content = "... Lo haré.",
  ui_story_1019_10190501_40_dialog_content = "Oye, ¿por qué hay corazones rosas por todo el reverso?",
  ui_story_1019_10190501_41_dialog_content = "\"Queridísimo Algol, ¿puedes enseñarme matemáticas?\"",
  ui_story_1019_10190501_42_dialog_content = "Y esta también... \"Tu sabiduría me ilumina como los reflectores de la subciudad.\"",
  ui_story_1019_10190501_43_dialog_content = "Firmado \"Adivina Quién\"...",
  ui_story_1019_10190501_44_dialog_content = "Oh, esas... Solo son algunas viejas cartas de amor que recibí en el pasado.",
  ui_story_1019_10190501_45_option_content = "... Eso es tan vergonzoso.",
  ui_story_1019_10190501_46_option_content = "... No importa, no quiero saber.",
  ui_story_1019_10190501_47_dialog_content = "Algol, es bastante asombroso que hayas usado la carta de amor de alguien como papel de borrador.",
  ui_story_1019_10190501_48_dialog_content = "¿Por qué no usaría el papel que está justo frente a mí? Además, significa que nunca he tirado uno.",
  ui_story_1019_10190501_49_dialog_content = "Podrías haber usado la pizarra blanca.",
  ui_story_1019_10190501_50_dialog_content = "Este enorme tablero tiene mapas... cálculos, cálculos y aún más cálculos.",
  ui_story_1019_10190501_51_dialog_content = "También veo muchas revisiones basadas en el humor del Dr. Algol en estos memorandos.",
  ui_story_1019_10190501_52_dialog_content = "¿También ves la angustia oculta en ellos?",
  ui_story_1019_10190501_53_dialog_content = "¿De mi incapacidad para resolver el misterio del Guardián?",
  ui_story_1019_10190501_54_dialog_content = "¿Guardián? ¿Te refieres a Guardian One?",
  ui_story_1019_10190501_55_dialog_content = "¡No!",
  ui_story_1019_10190501_56_dialog_content = "Guardian One es una antigua IA encargada de las operaciones diarias de todo el sistema tecnológico de Illumina.",
  ui_story_1019_10190501_57_dialog_content = "En realidad es un enorme conjunto de computadoras. Los Wraiths robaron el núcleo y has visto el impacto que eso tuvo en Gannon City.",
  ui_story_1019_10190501_X57_dialog_content = "Este clúster fue desarrollado utilizando la tecnología antigua, el Guardián, como fundamento.",
  ui_story_1019_10190501_58_dialog_content = "Podrías decir que Guardian es el prototipo para Guardian One.",
  ui_story_1019_10190501_59_dialog_content = "Guardian One es parte de un clúster de computadoras con un núcleo independiente para procesar datos. También almacena mucha información de tiempos antiguos.",
  ui_story_1019_10190501_X59_dialog_content = "Por lo tanto, aunque en teoría tienen el mismo nombre, para diferenciar, puedes llamar a Guardian One... um, \"Buzón\".",
  ui_story_1019_10190501_60_dialog_content = "Guardian One no es un buzón.",
  ui_story_1019_10190501_61_dialog_content = "Bip, bip, bip, bip, bip...",
  ui_story_1019_10190501_62_dialog_content = "Guardian One no entiende lo que Algol dijo.",
  ui_story_1019_10190501_63_dialog_content = "Parece que aún necesitas aprender cómo procesar diálogos aurorianos complejos.",
  ui_story_1019_10190501_64_dialog_content = "Guardian One entiende.",
  ui_story_1019_10190501_65_dialog_content = "(Tan difícil de creer que Algol no está ignorando a Guardian One...)",
  ui_story_1019_10190501_66_dialog_content = "De todos modos, mi trabajo es estudiar al Guardián y desarrollar sus otras características.",
  ui_story_1019_10190501_67_dialog_content = "¿Es esta máquina el prototipo?",
  ui_story_1019_10190501_68_dialog_content = "Este es un <color=#FFB400>simulador</color>. El original ha sido bloqueado desde hace mucho tiempo por razones de seguridad.",
  ui_story_1019_10190501_69_dialog_content = "Es cierto. Parecería descompuesto si fuera tecnología antigua.",
  ui_story_1019_10190501_70_dialog_content = "No siempre. Vi el original antes, y solo podría describir el exterior como... exudando un aura antigua pero sofisticada.",
  ui_story_1019_10190501_71_dialog_content = "Hemos visto progreso en todas las tecnologías de vanguardia durante los últimos años, excepto en el Guardián, que aún sigue siendo el cuello de botella.",
  ui_story_1019_10190501_72_dialog_content = "Si tan solo pudiera examinarlo antes de que fuera guardado...",
  ui_story_1019_10190501_73_dialog_content = "¡Oh, me enfado cada vez que lo pienso!",
  ui_story_1019_10190501_74_dialog_content = "¡Bu!",
  ui_story_1019_10190501_75_dialog_content = "¿Qué? ¡Incluso tú te estás burlando de mí!",
  ui_story_1019_10190501_76_dialog_content = "Bool no parece que se esté burlando de ti, sino que está en desacuerdo con lo que dijiste.",
  ui_story_1019_10190501_77_dialog_content = "¡Boo!",
  ui_story_1019_10190501_78_dialog_content = "¡Oh genial, incluso el Celestita es ahora más inteligente que yo!",
  ui_story_1019_10190501_79_dialog_content = "...",
  ui_story_1019_10190501_80_dialog_content = "Hablando de malentendidos...",
  ui_story_1019_10190501_81_dialog_content = "Dado que puedes vincularte psíquicamente con Guardian One, tal vez también puedas indagar en la mente de Bool.",
  ui_story_1019_10190501_82_dialog_content = "¡Booo!",
  ui_story_1019_10190501_83_dialog_content = "Está escondido detrás de ti. No creo que esté receptivo a esa idea.",
  ui_story_1019_10190501_84_dialog_content = "Boo...",
  ui_story_1019_10190501_85_dialog_content = "¿Puedes notarlo? Solo se está haciendo el difícil.",
  ui_story_1019_10190501_86_dialog_content = "Está bien... Entonces, déjame intentarlo.",
  ui_story_1019_10190501_87_dialog_content = "Boo...",
  ui_story_1019_10190501_88_option_content = "Enlace Telepático",
  ui_story_1019_10190501_89_dialog_content = "(Espera, ¿Bool se está escondiendo detrás de Algol otra vez? Solo veo Algol...)",
  ui_story_1019_10190501_90_dialog_content = "(¿Algo salió mal?)",
  ui_story_1019_10190501_91_dialog_content = "(No veo ningún alrededor...)",
  ui_story_1019_10190501_92_dialog_content = "(¿No es Algol un Aurorian sino un droide? ¿¡IA, tal vez?!)",
  ui_story_1019_10190501_93_dialog_content = "(De ninguna manera... ¿Qué tipo de idea loca es esa? ¡Acaba de pelear una batalla con Lumina!)",
  ui_story_1019_10190501_94_dialog_content = "(Quizás no estoy yendo lo suficientemente profundo y tengo que ir más profundo.)",
  ui_story_1019_10190501_95_dialog_content = "(Ve más profundo...)",
  ui_story_1019_10190501_96_dialog_content = "(Más profundo...)",
  ui_story_1019_10190501_97_dialog_content = "(¿Eh? ¿Fue eso... Bool?)",
  ui_story_1019_10190501_98_dialog_content = "(Puedo alternar entre dos objetos sensoriales. Esta sensación es increíble. Es como si tuviera dos pares de ojos...)",
  ui_story_1019_10190501_99_dialog_content = "<color=#e8d9bb>¡Boo!!! Bofetada—</color>",
  ui_story_1019_10190501_100_dialog_content = "¡Ah!",
  ui_story_1019_10190601_1_dialog_content = "¡Veo que Bool también se preocupa mucho por ti!",
  ui_story_1019_10190601_2_dialog_content = "Frecuencia cardíaca, presión arterial... Todo normal, y tu nivel de oxígeno en sangre ha mejorado.",
  ui_story_1019_10190601_3_dialog_content = "¿Llamas a una paliza un entrenamiento?",
  ui_story_1019_10190601_4_dialog_content = "¿A qué te refieres con \"paliza\"? No tienes ni un solo moretón en ti, sin mencionar que esta es una forma avanzada de comunicarse.",
  ui_story_1019_10190601_5_dialog_content = "¡Bu!",
  ui_story_1019_10190601_6_dialog_content = "¡Recuerdo ese tono! ¿No crees que es demasiado tarde para ofrecer simpatía ahora...",
  ui_story_1019_10190601_7_dialog_content = "Dr. Algol, ¿cómo te estás comunicando con Bool?",
  ui_story_1019_10190601_8_dialog_content = "Bueno, Bool transmite diferentes mensajes golpeándome con intensidades variables. Obviamente, todavía tiene que trabajar en eso con el Caelestite.",
  ui_story_1019_10190601_9_dialog_content = "Está bien. Eso es algo que podría hacer sin ello.",
  ui_story_1019_10190601_10_dialog_content = "Pero Bool siempre ha sido amigable contigo antes. ¿Por qué se comportaría de esa manera...?",
  ui_story_1019_10190601_11_dialog_content = "Bueno, vi algo en la mente de Bool.",
  ui_story_1019_10190601_12_dialog_content = "Pero a diferencia de Guardian One, la imagen no era ni específica ni clara.",
  ui_story_1019_10190601_13_dialog_content = "Después de todo, la mente de Bool funciona más como una computadora.",
  ui_story_1019_10190601_14_dialog_content = "De todos modos, por favor perdona el arrebato. No te lastimó tan mal, ¿verdad?",
  ui_story_1019_10190601_15_dialog_content = "...",
  ui_story_1019_10190601_16_dialog_content = "<color=#e8d9bb>Bip-bip-bip-</color>",
  ui_story_1019_10190601_17_dialog_content = "Hola, ciertas coordenadas en los datos de Soroz sí aparecen en el nuevo mapa.",
  ui_story_1019_10190601_18_dialog_content = "Nunca hemos revisado ese lugar antes, ¿verdad?",
  ui_story_1019_10190601_19_dialog_content = "Espera, ¿esto significa que tenemos varios conjuntos de coordenadas?",
  ui_story_1019_10190601_20_dialog_content = "Podría ser de la misma fuente pero con señales fluctuantes.",
  ui_story_1019_10190601_21_dialog_content = "Al noroeste de Gannon, a unas 2,500 millas...",
  ui_story_1019_10190601_22_dialog_content = "Bueno, aún es posible. No está tan lejos como pensaba que estaría.",
  ui_story_1019_10190601_23_dialog_content = "Pero estas señales son mucho más antiguas que las del Obelisco del Retorno.",
  ui_story_1019_10190601_24_dialog_content = "¿Quieres decir que Eraveil no es donde se originaron los Colossi?",
  ui_story_1019_10190601_25_dialog_content = "Así es. La ubicación actual de Eraveil servía más como un fuerte fronterizo de los Eclipsites en su invasión de Astra.",
  ui_story_1019_10190601_26_dialog_content = "Probablemente los Colosos vinieron de la Zona Oscura.",
  ui_story_1019_10190601_27_dialog_content = "Así que Eraveil no es el hogar de Soroz...",
  ui_story_1019_10190601_28_dialog_content = "Probablemente ni siquiera la casa de los Caelestites...",
  ui_story_1019_10190601_29_dialog_content = "La ubicación de la casa de uno no tiene importancia, Caelestite.",
  ui_story_1019_10190601_30_dialog_content = "El punto es que, Soroz ha estado viviendo con los Caelestites en Eraveil desde que comprendió por primera vez el concepto de \"hogar\".",
  ui_story_1019_10190601_31_dialog_content = "Desde una perspectiva biomecánica, la versión actual de Soroz debería considerarse como tu creación.",
  ui_story_1019_10190601_32_dialog_content = "...",
  ui_story_1019_10190601_33_dialog_content = "No te desanimes. Solo estamos especulando en este momento.",
  ui_story_1019_10190601_34_dialog_content = "Encontraremos la respuesta una vez que confirmemos la ubicación.",
  ui_story_1019_10190601_35_dialog_content = "Dr. Algol, ¿qué deberíamos hacer para prepararnos para la búsqueda en la Zona Oscura?",
  ui_story_1019_10190601_36_dialog_content = "Con la información de Helios y el Equipo de Expedición de la Zona Oscura, estamos empezando a conocer un poco sobre la Zona Oscura.",
  ui_story_1019_10190601_37_dialog_content = "Un experto está haciendo un mapa ahora, apoyado por los datos de Soroz.",
  ui_story_1019_10190601_38_dialog_content = "Vamos a hablar con él. Debería ser interesante.",
  ui_story_1019_10190601_39_dialog_content = "Seguro.",
  ui_story_1019_10190601_40_dialog_content = "<color=#828282>¡Ding!</color>",
  ui_story_1019_10190601_41_dialog_content = "¿Hmm? Hay Eclipsites en el Parque Tecnológico... ¿Quién está a cargo de la patrulla?",
  ui_story_1019_10190601_42_dialog_content = "Barton debería estar de guardia en este momento. ¿Cómo sabes que hay Eclipsites en el Parque Tecnológico?",
  ui_story_1019_10190601_43_dialog_content = "Mi pulsera puede detectar amenazas en las cercanías, pero no será un problema si Barton está de guardia.",
  ui_story_1019_10190601_44_dialog_content = "El Parque Tecnológico es un sitio vital en Gannon. No podemos tener Eclipsites por aquí.",
  ui_story_1019_10190601_45_dialog_content = "¿Dónde están los Eclipsites? Tengo que investigarlo y desplegar guardias de inmediato.",
  ui_story_1019_10190601_46_dialog_content = "Barton ya está en ello.",
  ui_story_1019_10190601_47_dialog_content = "Informar amenazas, evaluar Eclipsites, enviar soldados, matar Eclipsites, reparar brechas... la pulsera puede hacer todo esto.",
  ui_story_1019_10190601_48_dialog_content = "Pero...",
  ui_story_1019_10190601_49_dialog_content = "Créeme, está bien. No puedes manejar todo tú mismo. Eso te va a cansar.",
  ui_story_1019_10190601_50_dialog_content = "Es mi deber. No me siento cansado.",
  ui_story_1019_10190601_51_dialog_content = "Bastante estoico, pero Bool dice que las ojeras debajo de tus ojos ya te delataron.",
  ui_story_1019_10190601_52_dialog_content = "¡Bu!",
  ui_story_1019_10190601_53_dialog_content = "Vamos, pasaremos por la fuente de la amenaza en nuestro camino. Podemos revisarlo si aún estás preocupado.",
  ui_story_1019_10190601_54_dialog_content = "¡Bu!",
  ui_story_1019_10190702_1_dialog_content = "No puedo imaginar Eclipsites en el Parque Tecnológico...",
  ui_story_1019_10190702_2_dialog_content = "¿Es realmente un Eclipsite? ¿Por qué se parece más a un soldado de Illumina?",
  ui_story_1019_10190702_3_dialog_content = "Pregunta a Barton. Debería haber terminado con los Eclipsites en su zona.",
  ui_story_1019_10190702_4_dialog_content = "¿Qué estás haciendo aquí? ¿No te dijo el Gran Mariscal que te quedaras en Eraveil?",
  ui_story_1019_10190702_5_dialog_content = "Bueno, es una larga historia ...",
  ui_story_1019_10190702_6_dialog_content = "Le dije al Celestita que viniera.",
  ui_story_1019_10190702_7_dialog_content = "Eres Algol, el científico que me envió el mensaje, ¿verdad?",
  ui_story_1019_10190702_8_dialog_content = "Sí. Los Eclipsites no se colaron desde el exterior, ¿verdad?",
  ui_story_1019_10190702_9_dialog_content = "Cuanto menos interfieran ustedes, los científicos, con los Eclipsites, mejor.",
  ui_story_1019_10190702_10_dialog_content = "Estoy seguro de que escuchaste lo que pasó en Crepúsculo. Aunque Ulysses no tuvo éxito, aún así afectó mucho a los militares.",
  ui_story_1019_10190702_11_dialog_content = "No me agrupes con los otros científicos. No tengo interés en los aurorianos.",
  ui_story_1019_10190702_12_dialog_content = "Barton, el Dr. Algol tiene buenas intenciones. Por favor, dinos qué está pasando con los Eclipsites.",
  ui_story_1019_10190702_13_dialog_content = "...",
  ui_story_1019_10190702_14_dialog_content = "Bueno, es extraño, ¡para ser honesto! No vi a los Eclipsites cuando llegué al sitio. Solo vi a dos soldados pasando por el edificio del laboratorio...",
  ui_story_1019_10190702_15_dialog_content = "¡Quién iba a saber que cuando me acerqué, me atacaron como perros rabiosos!",
  ui_story_1019_10190702_16_dialog_content = "Nos cruzamos con lo mismo.",
  ui_story_1019_10190702_17_dialog_content = "Ahora que lo pienso, podrían ser del Programa Phospherus. ¿Qué piensas, chico?",
  ui_story_1019_10190702_18_dialog_content = "Cuando dirigía tu operación, podía sentir que el Darkflow en ellos era diferente.",
  ui_story_1019_10190702_19_dialog_content = "Si eran Eclipsites, podría haber un problema con el sistema de defensa que les permitió escapar del confinamiento del laboratorio.",
  ui_story_1019_10190702_20_dialog_content = "Eso es posible. El Parque Tecnológico Illumina tiene más que centros médicos y Laboratorios Black Umbrella...",
  ui_story_1019_10190702_21_dialog_content = "¡Como el científico que experimenta con sujetos aurorianos!",
  ui_story_1019_10190702_22_dialog_content = "Boo...",
  ui_story_1019_10190702_23_dialog_content = "¿Por qué no confrontas a Ulysses al respecto?",
  ui_story_1019_10190702_24_dialog_content = "¿Crees que no quería?",
  ui_story_1019_10190702_25_dialog_content = "La investigación de Fósfero no ha terminado y el Comité ha hecho la vista gorda a Ulysses transformando a los soldados!",
  ui_story_1019_10190702_26_dialog_content = "¡Si me preguntas, solo pone a Gannon en mayor peligro cada día!",
  ui_story_1019_10190702_27_dialog_content = "¿Por qué Illumina no condenó a Ulysses por hacer daño a tantos soldados?",
  ui_story_1019_10190702_28_dialog_content = "Puedo explicar eso.",
  ui_story_1019_10190702_29_dialog_content = "Es por el bien de los soldados, ya que Ulysses tiene la obligación de ayudar a tratar a los heridos.",
  ui_story_1019_10190702_30_dialog_content = "Y cada documento relevante para el caso está en su edificio. El panel de revisión todavía está accediendo y revisándolos.",
  ui_story_1019_10190702_31_dialog_content = "Además, aunque Ulysses está bajo vigilancia, todavía tiene bastante libertad para hacer lo que quiera.",
  ui_story_1019_10190702_32_dialog_content = "Así que a menos que sea urgente, no podemos entrar en su laboratorio.",
  ui_story_1019_10190702_33_dialog_content = "Puedes usar la brecha de Eclipsite como excusa para interrogar a Ulysses.",
  ui_story_1019_10190702_34_dialog_content = "¡Bu!",
  ui_story_1019_10190702_35_dialog_content = "Lo intenté. No funcionó.",
  ui_story_1019_10190702_36_dialog_content = "Entonces, síganme. Estoy autorizado para entrar en su laboratorio. Diré que ustedes están aquí para ayudarme.",
  ui_story_1019_10190702_37_dialog_content = "Por lo menos de lo que sé, no hay forma de que los Eclipsites puedan penetrar el nivel más bajo en Gannon desde el exterior.",
  ui_story_1019_10190702_38_dialog_content = "Además, no quiero que el Parque Tecnológico Illumina se convierta en una guarida de Eclipsites después de perder el núcleo de Guardian One.",
  ui_story_1019_10190702_39_dialog_content = "Esa es una idea. ¿Qué piensas, Barton?",
  ui_story_1019_10190702_40_dialog_content = "Intentemos...",
  ui_story_1019_10190702_41_dialog_content = "Vamos entonces, pero ten cuidado, si los Eclipsites escaparon del almacén, habría más de ellos adentro.",
  ui_story_1019_10190802_1_dialog_content = "¡Booo!",
  ui_story_1019_10190802_2_dialog_content = "Oye, no te apresures. Te estoy enviando los datos ahora mismo...",
  ui_story_1019_10190802_3_dialog_content = "Los soldados de patrulla informaron que no se avistó ningún Eclipsite en otros edificios, por lo que este debería ser el lugar correcto.",
  ui_story_1019_10190802_4_dialog_content = "¿Ulysses liberó a estos Eclipsites a propósito?",
  ui_story_1019_10190802_5_dialog_content = "No creo que tenga las agallas. Además, no es lo suficientemente estúpido como para querer morir con el resto de Illumina.",
  ui_story_1019_10190802_6_dialog_content = "Ejem, ¿es eso un cumplido para mí?",
  ui_story_1019_10190802_7_dialog_content = "¿Sabes que hay Eclipsites en tu laboratorio, Ulysses?",
  ui_story_1019_10190802_8_dialog_content = "Nunca ha habido escasez de sujetos Eclipsite en este edificio de laboratorio para el bien de la investigación Auroriana y Eclipsite.",
  ui_story_1019_10190802_9_dialog_content = "Eso no es un secreto. Ni tampoco es tu preocupación.",
  ui_story_1019_10190802_10_dialog_content = "Pero desde que se robó el núcleo, ha habido muchas lagunas en las válvulas del almacén del edificio del laboratorio. Probablemente de ahí es de donde escaparon los Eclipsites.",
  ui_story_1019_10190802_11_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_1019_10190802_12_dialog_content = "No son Eclipsites utilizados para fines experimentales. Además, está claramente prohibido transformar a los Aurorianos.",
  ui_story_1019_10190802_13_dialog_content = "Y si son soldados transformados o verdaderos sujetos Eclipsite...",
  ui_story_1019_10190802_14_dialog_content = "Tenemos el derecho de investigar cuando escaparon de tu laboratorio y amenazaron a nuestra gente.",
  ui_story_1019_10190802_15_dialog_content = "¿Claramente prohibido? Eh...",
  ui_story_1019_10190802_16_dialog_content = "Aun así, ¿quién te autorizó a entrar en mi edificio y tratar con esos sujetos Eclipsites?",
  ui_story_1019_10190802_17_dialog_content = "No importa lo que diga el Comité. ¡Nuestro deber es matar a todos los Eclipsites!",
  ui_story_1019_10190802_18_dialog_content = "No tienes razón solo porque seas el más ruidoso. Sin embargo, sí tienes que ser bueno para rastrear los sujetos para mí.",
  ui_story_1019_10190802_19_dialog_content = "¡¿Cómo puedes...?!",
  ui_story_1019_10190802_20_dialog_content = "Solo estaba revisando el sistema de Bool justo ahora... ¿Cómo se ha vuelto la escena tan tumultuosa?",
  ui_story_1019_10190802_21_dialog_content = "Los invité para que me ayudaran, Ulysses. No tiene nada que ver contigo.",
  ui_story_1019_10190802_22_dialog_content = "No tan rápido...",
  ui_story_1019_10190802_23_dialog_content = "Tiene un mensaje del Comité, señora.",
  ui_story_1019_10190802_24_dialog_content = "Esperan que asistas a la revisión final a tiempo.",
  ui_story_1019_10190802_25_dialog_content = "... Lo tengo.",
  ui_story_1019_10190802_26_dialog_content = "(¿Ulysses me está mirando?)",
  ui_story_1019_10190802_27_dialog_content = "No te he visto por un tiempo, Caelestite.",
  ui_story_1019_10190802_28_dialog_content = "Fue en la sala de conferencias la última vez, tú y Reinhardt. Algol también estaba allí.",
  ui_story_1019_10190802_29_dialog_content = "Qué pérdida de tiempo fue esa tediosa, aburrida y pretenciosa reunión.",
  ui_story_1019_10190802_30_dialog_content = "Eso fue hace mucho tiempo, después de lo cual han ocurrido nuevos cambios en este mundo. Pero nada se te escapa. ¿Tengo razón, Caelestite?",
  ui_story_1019_10190802_31_dialog_content = "¿Qué estás tratando de decir?",
  ui_story_1019_10190802_32_dialog_content = "He estado teniendo visiones peculiares durante mucho tiempo, y me han llegado con más frecuencia en los últimos años.",
  ui_story_1019_10190802_33_dialog_content = "Esas escenas eran tan reales como si controlaran físicamente los movimientos de mi cuerpo, mis latidos del corazón...",
  ui_story_1019_10190802_34_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1019_10190802_35_dialog_content = "¿Qué es eso?",
  ui_story_1019_10190802_36_dialog_content = "¿Latidos del corazón?",
  ui_story_1019_10190802_37_dialog_content = "Ambos podemos ver la verdad, sin embargo, siempre hay alguien intentando alejarme de ella...",
  ui_story_1019_10190802_38_dialog_content = "Y te ciega el propósito de la vida... Eso es una pena para ti.",
  ui_story_1019_10190802_39_dialog_content = "Ejem, ¿quién quedará para luchar contra los Eclipsites después de la revisión final?",
  ui_story_1019_10190802_40_dialog_content = "¿De qué estás parloteando? No he conocido a nadie a quien no pudiera vencer.",
  ui_story_1019_10190802_41_dialog_content = "¡Creo que estás intentando ganarte a PlayerName y excusar tus crímenes!",
  ui_story_1019_10190802_42_dialog_content = "Difícilmente. Simplemente le pregunto al Último Caelestita en Astra por curiosidad.",
  ui_story_1019_10190802_43_dialog_content = "Si aprovechas la oportunidad, podrías ver la verdad aquí...",
  ui_story_1019_10190802_44_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1019_10190802_45_dialog_content = "Oye, espera un segundo. Estoy confundido...",
  ui_story_1019_10190802_46_dialog_content = "¿Qué pasa con Bool?",
  ui_story_1019_10190802_47_dialog_content = "Está actuando raro. Nunca se ha comportado así antes.",
  ui_story_1019_10190802_48_dialog_content = "Je, ¿quién dice que este comportamiento inusual no es una bendición?",
  ui_story_1019_10190802_49_dialog_content = "¿Una bendición?",
  ui_story_1019_10190802_50_dialog_content = "Cuando una pesadilla llama a la puerta, es una bendición cuando alguien está allí para guardar la entrada.",
  ui_story_1019_10190802_51_dialog_content = "Pero hasta ahora, todo sigue pareciendo borroso...",
  ui_story_1019_10190802_52_dialog_content = "Sabes, el tiempo que pasas siendo críptico podría ser mejor invertido en averiguar qué es lo que está mal contigo.",
  ui_story_1019_10190802_53_dialog_content = "Ah, es bueno ser joven.",
  ui_story_1019_10190802_54_dialog_content = "Entonces, PlayerName, ¿qué verdad te gustaría saber?",
  ui_story_1019_10190802_55_dialog_content = "(No me digas que él sabe...)",
  ui_story_1019_10190802_56_option_content = "(¿La verdad detrás de los sueños?)",
  ui_story_1019_10190802_57_option_content = "(¿La verdad de los latidos del corazón de Vice?)",
  ui_story_1019_10190802_58_dialog_content = "(Pero, ¿cómo podría él saberlo posiblemente?)",
  ui_story_1019_10190802_59_dialog_content = "(¿O simplemente me está utilizando para absolver su propia culpa, tal como dijo Vivian?)",
  ui_story_1019_10190802_60_dialog_content = "A juzgar por cómo dudas, debes tener preguntas.",
  ui_story_1019_10190802_61_dialog_content = "Todo lo que tienes que hacer es venir a mi laboratorio y ayudarme con un pequeño \"experimento\". Entonces, conocerás la respuesta.",
  ui_story_1019_10190802_62_dialog_content = "Incluso podemos descubrir tus... límites.",
  ui_story_1019_10190802_63_dialog_content = "El Gran Mariscal ya dejó claro que se detengan todos los experimentos, Ulysses!",
  ui_story_1019_10190802_64_dialog_content = "Olvida los experimentos. Toca PlayerName, y te conseguiré yo mismo.",
  ui_story_1019_10190802_65_dialog_content = "Ustedes dos se equivocaron. Yo soy el que va a ser el sujeto del experimento, que PlayerName va a realizar.",
  ui_story_1019_10190802_66_dialog_content = "Después de todo, cualquier especulación nacida de la curiosidad debe ser verificada a través de la experimentación, ¿correcto?",
  ui_story_1019_10190802_67_dialog_content = "¿Qué experimento tienes en mente?",
  ui_story_1019_10190802_68_dialog_content = "Quiero que uses tu habilidad psíquica para ver algunos de mis sueños peculiares y ver si la respuesta que estás buscando está entre ellos.",
  ui_story_1019_10190802_69_dialog_content = "¡Sueños peculiares!",
  ui_story_1019_10190802_70_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1019_10190802_71_dialog_content = "¿Qué está pasando? Deberíamos salir de aquí ahora, Celestita.",
  ui_story_1019_10190802_72_dialog_content = "Pero quiero quedarme...",
  ui_story_1019_10190802_73_dialog_content = "¡¿PlayerName?!",
  ui_story_1019_10190802_74_dialog_content = "Quiero probar este experimento.",
  ui_story_1019_10190802_75_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1019_10190802_76_dialog_content = "Oye, espera... Deja de arrastrarme...",
  ui_story_1019_10190802_77_dialog_content = "Lo siento, primero tengo que resolver el problema con Bool.",
  ui_story_1019_10190802_78_dialog_content = "No te preocupes. Estaré atento, aunque no es mi responsabilidad.",
  ui_story_1019_10190802_79_dialog_content = "Pero es mi deber asegurarme de que PlayerName esté seguro.",
  ui_story_1019_10190802_80_dialog_content = "Mi laboratorio es seguro. Venga.",
  ui_story_1019_10190901_1_dialog_content = "¿Estás lista, Caelestite? Me gustaría hacerte una pregunta antes de comenzar.",
  ui_story_1019_10190901_2_dialog_content = "¿Cómo crees que se verá el fin del mundo?",
  ui_story_1019_10190901_3_dialog_content = "Si la Crisis de Darkover sucede de nuevo, ¿cómo pueden los Aurorianos resistirla?",
  ui_story_1019_10190901_4_dialog_content = "Uh, eso nunca pasó por mi mente.",
  ui_story_1019_10190901_5_dialog_content = "Los Celestitas una vez lograron la gran hazaña de dejar Astra. ¿No quieres saber cómo es ese cielo inexplorado?",
  ui_story_1019_10190901_6_dialog_content = "Eso es un antiguo milagro de los Caelestitas y los Colosos demasiado alejado del presente.",
  ui_story_1019_10190901_7_dialog_content = "Solo soy un chico normal. El rincón más lejano al que he llegado es la tierra oriental no muy lejos de Astra.",
  ui_story_1019_10190901_8_dialog_content = "Je, ustedes siempre dejan que el miedo limite su imaginación.",
  ui_story_1019_10190901_9_dialog_content = "¿Por qué dices eso?",
  ui_story_1019_10190901_10_dialog_content = "Lo descubrirás muy pronto. Ahora, comencemos.",
  ui_story_1019_10190901_11_dialog_content = "...",
  ui_story_1019_10190901_12_option_content = "Enlace Telepático",
  ui_story_1019_10190901_13_dialog_content = "¿Es esto Northland...?",
  ui_story_1019_10190901_14_dialog_content = "Tantos pilares de hielo, apuntando hacia el cielo como espadas.",
  ui_story_1019_10190901_15_dialog_content = "No, la penumbra se asemeja más a la de la Zona Oscura...",
  ui_story_1019_10190901_16_dialog_content = "Exploré las Ruinas de Aurora antes. Tienen unas rocas negras que emiten la misma vibra fría.",
  ui_story_1019_10190901_17_dialog_content = "Pero esas rocas estaban planas sobre el suelo sólido, mientras que estos pilares levitan en el aire.",
  ui_story_1019_10190901_18_dialog_content = "Algunos incluso están brillando y estirándose hacia arriba...",
  ui_story_1019_10190901_19_dialog_content = "¿Es esto parte de los recuerdos de Ulysses? ¿Por qué vino aquí?",
  ui_story_1019_10190901_20_dialog_content = "¿Y cómo podrían existir tales recuerdos dentro de su conciencia?",
  ui_story_1019_10190901_21_dialog_content = "Este es un lugar abandonado sin ninguna señal de vida...",
  ui_story_1019_10190901_22_dialog_content = "<color=#e8d9bb>¡Clink, clink!</color>",
  ui_story_1019_10190901_23_dialog_content = "¿Qué está pasando?",
  ui_story_1019_10190901_24_dialog_content = "Los pilares están cambiando como si alguna fuerza los atrajera en un grupo hacia el cielo.",
  ui_story_1019_10190901_25_dialog_content = "¿Se están fusionando en algo?",
  ui_story_1019_10190901_26_dialog_content = "¿Qué es exactamente este lugar?",
  ui_story_1019_10190901_27_dialog_content = "<color=#e8d9bb>Chocar...</color>",
  ui_story_1019_10190901_28_dialog_content = "*jadeo*",
  ui_story_1019_10190901_29_dialog_content = "Entonces, ¿cómo te sientes, Caelestite?",
  ui_story_1019_10190901_30_dialog_content = "¿Qué te mostró él, niño?!",
  ui_story_1019_10190901_31_option_content = "¿Dónde está ese lugar?",
  ui_story_1019_10190901_32_dialog_content = "Dónde...",
  ui_story_1019_10190901_33_option_content = "¿Por qué me muestras esto?",
  ui_story_1019_10190901_34_dialog_content = "Porque...",
  ui_story_1019_10190901_35_dialog_content = "Ese es el fin del mundo.",
  ui_story_1019_10190901_36_dialog_content = "Donde los Eclipsites acechan e intentan despertar al demonio...",
  ui_story_1019_10190901_37_dialog_content = "¿Demonio...?",
  ui_story_1019_10190901_38_dialog_content = "(¿Es eso de lo que escuché en el antiguo campo de batalla?)",
  ui_story_1019_10190901_39_dialog_content = "Pero no vi ningún Eclipsite, solo innumerables pilares de hielo.",
  ui_story_1019_10190901_40_dialog_content = "Eso es porque ya han comenzado.",
  ui_story_1019_10190901_41_dialog_content = "¿Comenzado?",
  ui_story_1019_10190901_42_dialog_content = "¡Despertando al demonio!",
  ui_story_1019_10190901_43_dialog_content = "...",
  ui_story_1019_10190901_44_dialog_content = "Ulysses, ¡eres un lunático! ¡Aléjate de PlayerName!",
  ui_story_1019_10190901_45_dialog_content = "Veo que el Jefe de Estado Mayor, Comandante Barton, y PlayerName están todos aquí...",
  ui_story_1019_10190901_46_dialog_content = "Justo a tiempo, Anatoli.",
  ui_story_1019_10190901_47_dialog_content = "El Comité te envió aquí, ¿verdad?",
  ui_story_1019_10190901_48_dialog_content = "Sí, Dr. Ulysses. Es la sesión informativa de la investigación de Phospherus, de la cual se le informó.",
  ui_story_1019_10190901_49_dialog_content = "Asistiré. Sin embargo...",
  ui_story_1019_10190901_50_dialog_content = "Espero que el Caelestite también pueda participar ya que el Comité lo considera el salvador de los Aurorianos.",
  ui_story_1019_10190901_51_dialog_content = "Me temo que eso es una violación de las reglas, Dr. Ulysses.",
  ui_story_1019_10190901_52_dialog_content = "¿Y cuál regla permitió al Caelestite entrar y salir de Gannon a voluntad?",
  ui_story_1019_10190901_53_dialog_content = "Considera mi propuesta, Caelestite. Sé que hay cosas que deseas saber.",
  ui_story_1019_10190901_54_dialog_content = "Quizás solo yo, en todo Illumina, puedo y te diré la verdad.",
  ui_story_1019_10190901_55_dialog_content = "...",
  ui_story_1019_10190901_56_dialog_content = "¿Te das cuenta de lo que es más importante para ti en este momento? ¡Haz preparativos para sobrevivir antes de que llegue el demonio!",
  ui_story_1019_10190901_57_dialog_content = "...",
  ui_story_1019_10190901_58_dialog_content = "Quita Ulysses, Anatoli.",
  ui_story_1019_10190901_59_dialog_content = "¿Celestita?",
  ui_story_1019_10190901_60_dialog_content = "...",
  ui_story_1019_10190901_61_dialog_content = "Jajaja... ¿Cómo puedes ser tú el que salve a los Aurorians, verdad? *tos*",
  ui_story_1019_10190901_62_dialog_content = "¡Vacilante, débil, sin ambiciones! Tú eres... *tose*",
  ui_story_1019_10190901_63_dialog_content = "Lo siento, llego tarde, señor. Por favor, permítame ayudarlo.",
  ui_story_1019_10190901_64_dialog_content = "¡Eso no es necesario!",
  ui_story_1019_10190901_65_dialog_content = "Ja...",
  ui_story_1019_10190901_66_dialog_content = "(Darkflow? No, no exactamente...)",
  ui_story_1019_10190901_67_dialog_content = "Nunca me detendré... ¡Todos ustedes se arrepentirán de esto! *tos*",
  ui_story_1019_10190901_68_dialog_content = "Estás tambaleante, doctor... ¿Estás seguro de que estás bien?",
  ui_story_1019_10190901_69_dialog_content = "¡Soy yo! ¡No me toques!",
  ui_story_1019_10190901_70_dialog_content = "¡¡¡Hraaagh!!!",
  ui_story_1019_10190901_71_dialog_content = "Brillo, acechando en las sombras.",
  ui_story_1019_10190901_72_dialog_content = "Un enemigo que se parece a un Eclipsite, igual a lo que encontramos antes...",
  ui_story_1019_10190901_73_dialog_content = "No es tu enemigo...",
  ui_story_1019_10190901_74_dialog_content = "¡¿Entonces qué es?!",
  ui_story_1019_10190901_75_dialog_content = "Guárdalo para el panel de revisión. Guíanos, PlayerName, ¡y lo destruiremos!",
  ui_story_1019_10190901_76_dialog_content = "¡Seguro!",
  ui_story_1019_10190902_1_dialog_content = "¡Baja la cuchilla, Barton!",
  ui_story_1019_10190902_2_dialog_content = "Ya informé de esto al Gran Mariscal. Su gente está en camino y ella quiere que solucionemos los problemas del laboratorio.",
  ui_story_1019_10190902_3_dialog_content = "¿Vas a dejar vivo a ese lunático? ¡Esa cosa nos atacó pero no a Ulysses!",
  ui_story_1019_10190902_4_dialog_content = "¡Sería el fin de Illumina si liberara a los Eclipsites en el laboratorio!",
  ui_story_1019_10190902_5_dialog_content = "Anatoli está a cargo de los asuntos relacionados con Ulysses ahora, Barton. La Gran Mariscal afirmó que llegaría al fondo de esto.",
  ui_story_1019_10190902_6_dialog_content = "¡Oye, veo una multitud! ¿Qué me perdí?",
  ui_story_1019_10190902_7_dialog_content = "Los jóvenes también están aquí. Veo que has sido bautizado por el fuego. ¡Incluso tus olores son diferentes!",
  ui_story_1019_10190902_8_dialog_content = "...",
  ui_story_1019_10190902_9_dialog_content = "Me llevaré al Dr. Ulysses conmigo incluso si ustedes dos se interponen.",
  ui_story_1019_10190902_10_dialog_content = "No te preocupes por eso. Estamos aquí solo para apoderarnos de su laboratorio. ¡Muy bien, todos fuera!",
  ui_story_1019_10190902_11_dialog_content = "¿Apoderarte de mi laboratorio? Qué ridículo...",
  ui_story_1019_10190902_12_dialog_content = "¡Soy el presidente del Consejo de Ciencias! No puedes igualar mis logros en diez vidas.",
  ui_story_1019_10190902_13_dialog_content = "¡Es bueno que hayas logrado todo eso! Aunque el monopolio no está permitido en Illumina. Y no creo que haya ningún archivo aquí que no pueda descifrar.",
  ui_story_1019_10190902_14_dialog_content = "Pero antes de que te vayas, doc, ¿te importaría darme acceso al ordenador?",
  ui_story_1019_10190902_15_dialog_content = "Nosotros, los Laboratorios Black Umbrella, nos encargaremos también de los sujetos Eclipsite y los materiales biológicos.",
  ui_story_1019_10190902_16_dialog_content = "Relájate, mientras yo esté aquí, ningún Eclipsite se soltará en el Parque Tecnológico.",
  ui_story_1019_10190902_17_dialog_content = "¿Realmente no quieres descubrir la verdad, Caelestite?",
  ui_story_1019_10190902_18_option_content = "No, no lo hago.",
  ui_story_1019_10190902_19_dialog_content = "(Hay una extraña conexión entre Ulysses y las visiones...)",
  ui_story_1019_10190902_20_dialog_content = "(Tengo que contarle a Vivian sobre lo que vi.)",
  ui_story_1019_10190902_21_option_content = "Sí.",
  ui_story_1019_10190902_22_dialog_content = "(¿Por qué Ulysses me mostraría la visión... Estaba tratando de decirme algo?)",
  ui_story_1019_10190902_23_dialog_content = "(Pero él no parece correcto, así que tal vez no debería confiar en él...)",
  ui_story_1019_10190902_24_dialog_content = "Creo que la verdad será revelada después de la revisión.",
  ui_story_1019_10190902_25_dialog_content = "Jajaja...",
  ui_story_1019_10190902_26_dialog_content = "Así que este es el fin de los Aurorianos, veo... Mi esfuerzo fue finalmente pisoteado por ustedes, tontos.",
  ui_story_1019_10190902_27_dialog_content = "Olvídalo, simplemente olvídalo...",
  ui_story_1019_10190902_28_dialog_content = "En ese caso, déjame revelarlo personalmente.",
  ui_story_1019_10190902_29_dialog_content = "Será una especie de honor para ustedes presenciar la historia por ustedes mismos...",
  ui_story_1019_10190902_30_dialog_content = "Dile a Belisaria que convoque a mis testigos.",
  ui_story_1019_10190902_31_dialog_content = "¿Testigos? ¿A quién te refieres?",
  ui_story_1019_10190902_32_dialog_content = "Yingel, Axelia, Sean. Solo envíalos.",
  ui_story_1019_10190902_33_dialog_content = "¡Sí señor!",
  ui_story_1019_10190902_34_dialog_content = "...",
  ui_story_1019_10190902_35_dialog_content = "Le pasé sus preocupaciones al Gran Mariscal, PlayerName, pero ahora debemos entregar Ulysses al comité de revisión.",
  ui_story_1019_10190902_36_dialog_content = "Antes de que lleguen a una conclusión, tenemos cosas más importantes que hacer. No olvidemos que tenemos coordenadas que investigar.",
  ui_story_1019_10190902_37_dialog_content = "Pero todavía estoy obsesionado con la pregunta que me hizo...",
  ui_story_1019_10190902_38_dialog_content = "¿Cómo crees que se verá el fin del mundo?",
  ui_story_1019_10190902_39_dialog_content = "Si la Crisis de Darkover sucede de nuevo, ¿cómo pueden los Aurorianos resistirla?",
  ui_story_1019_10190902_40_dialog_content = "*respiración profunda* Whoosh—",
  ui_story_1019_10190902_41_dialog_content = "Probablemente se deba a que no he dormido bien últimamente, pero me he sentido un poco perdido como si me faltara algo importante.",
  ui_story_1019_10190902_42_dialog_content = "Si realmente te faltara algo, estoy seguro de que seguirías adelante y lo buscarías, sin importar cuán lejos y oscuro sea.",
  ui_story_1019_10190902_43_dialog_content = "Pero Illumina es diferente. Es nuestro hogar, nuestra esperanza.",
  ui_story_1019_10190902_44_dialog_content = "Si podemos ver el cielo sobre las subciudades desde aquí...",
  ui_story_1019_10190902_45_dialog_content = "El sol debería estar arriba en la superficie.",
  ui_story_1019_10190902_46_dialog_content = "Sin embargo, para la gente de Illumina, salir de las Subciudades para estar bajo el sol es lo más lejos que podrían llegar.",
  ui_story_1019_10190902_47_dialog_content = "Gannon no ha visto el sol en años, pero sigue a salvo de la oscuridad.",
  ui_story_1019_10190902_48_dialog_content = "Excepto que vamos más profundo bajo tierra a medida que pasa el tiempo.",
  ui_story_1019_10190902_49_dialog_content = "Realmente me pregunto cómo era Gannon cuando se construyó por primera vez.",
  ui_story_1019_10190902_50_dialog_content = "Una cosa era segura: los Eclipsites estaban en todas partes.",
  ui_story_1019_10190902_51_dialog_content = "La amenaza de los Eclipsites nos empujó a sobrevivir aquí y nos hizo nuestro objetivo matarlos.",
  ui_story_1019_10190902_52_dialog_content = "Realmente no puedo decir qué le depara el futuro a Illumina después del juicio.",
  ui_story_1019_10190902_53_dialog_content = "...",
  ui_story_1019_10190902_54_dialog_content = "Sé que tienes muchas cosas en tu cabeza, chico, ¡pero aguanta!",
  ui_story_1019_10190902_55_dialog_content = "Realmente me siento con más energía después de hablar con todos ustedes.",
  ui_story_1019_10190902_56_dialog_content = "Probablemente eso sea producto del reloj biológico Algol mencionado. Ahora es el comienzo de un nuevo día.",
  ui_story_1019_10190902_57_dialog_content = "Entiendo...",
  ui_story_1019_10190902_58_dialog_content = "Bueno entonces. Buenos días, Vivian, y Barton.",
  ui_story_1019_10190902_59_dialog_content = "Buenos dias, PlayerName.",
  ui_story_1019_10190902_60_dialog_content = "¡Buenos días, Illumina! Ve a hacer tus cosas y esperemos que termine pronto.",
  ui_story_1019_10191001_1_dialog_content = "<color=#e8d9bb>En una sala de conferencias de alto nivel del Salón de Conferencias Illumina, todos parecen estar en silencio.</color>",
  ui_story_1019_10191001_2_dialog_content = "Ustedes se quedan callados cuando es hora de sentenciarme.",
  ui_story_1019_10191001_3_dialog_content = "Ejem...",
  ui_story_1019_10191001_4_dialog_content = "Mmm...",
  ui_story_1019_10191001_5_dialog_content = "Esta es la quinta revisión ya, así que ¿por qué no cambiamos y tenemos una charla informal? ¿No llamaste a los testigos?",
  ui_story_1019_10191001_6_dialog_content = "...",
  ui_story_1019_10191001_7_dialog_content = "¿Charla casual? ¿Cuánto más vas a prolongar esto? ¿No han demostrado las batallas en Twilight y la línea defensiva de Illumina la resolución y el poderío de nuestro ejército?",
  ui_story_1019_10191001_8_dialog_content = "Helios, un testigo del ejercicio militar, todavía se está recuperando de un coma, y los soldados en el Programa Phospherus todavía están siendo examinados también.",
  ui_story_1019_10191001_9_dialog_content = "Eso son solo excusas. ¡Exijo pruebas más concretas!",
  ui_story_1019_10191001_10_dialog_content = "Estoy de acuerdo. Ya sea el ejercicio o el Programa Fósforo, como alguien que ha pasado por ambos, ¡mi testimonio solo debería ser suficiente!",
  ui_story_1019_10191001_11_dialog_content = "Veo que te estás recuperando bien del procedimiento, Gran Mariscal Wrath.",
  ui_story_1019_10191001_12_dialog_content = "Entiendo tu punto, pero no podemos simplemente ignorar las opiniones y contribuciones del Dr. Ulysses.",
  ui_story_1019_10191001_13_dialog_content = "¿Todavía no estás contento con cuánto tiempo ha durado la revisión?",
  ui_story_1019_10191001_14_dialog_content = "Podemos darle otra oportunidad, pero será la última.",
  ui_story_1019_10191001_15_dialog_content = "¿Reinhardt?",
  ui_story_1019_10191001_16_dialog_content = "Pero con una condición: mis fuerzas no cederán más. Tendré a mi testigo presente antes del veredicto final.",
  ui_story_1019_10191001_17_dialog_content = "Entonces te verás obligado a sentenciar a Ulysses.",
  ui_story_1019_10191001_18_dialog_content = "Seguro. Ahora, aprovecha el momento, Ulysses, porque me gustaría escuchar algo diferente en tu declaración final.",
  ui_story_1019_10191001_19_dialog_content = "Je. Yo... *tose*",
  ui_story_1019_10191001_20_dialog_content = "Tu medicina y agua, doctor...",
  ui_story_1019_10191001_21_dialog_content = "...",
  ui_story_1019_10191001_22_dialog_content = "Estoy bien, solo un poco bajo el clima debido a la fatiga.",
  ui_story_1019_10191001_23_dialog_content = "Ya dije que no te oculté nada.",
  ui_story_1019_10191001_24_dialog_content = "Sí, pero solo para las preguntas hechas y nada más.",
  ui_story_1019_10191001_25_dialog_content = "Esta vez, esperamos que reveles los resultados de tu investigación y si tu equipo continuará trabajando después de que dejes el laboratorio con toda honestidad.",
  ui_story_1019_10191001_26_dialog_content = "Después de todo, tu trabajo es un legado de la historia, y es hora de pasarlo a una nueva generación.",
  ui_story_1019_10191001_27_dialog_content = "Jeje, ¿estás insinuando que soy demasiado mayor?",
  ui_story_1019_10191001_28_dialog_content = "Yo, Ulysses, nacido en 1945 del Calendario de la Mañana, he vivido durante más de medio siglo...",
  ui_story_1019_10191001_29_dialog_content = "Como mis compañeros, debería estar muerto hace mucho tiempo según la esperanza de vida promedio de los Aurorianos de Illumina.",
  ui_story_1019_10191001_30_dialog_content = "¿Realmente quieres confiar el pesado problema del Ingeniero desde la fundación de Illumina a los soldados que solo conocían armas y proyectiles?",
  ui_story_1019_10191001_31_dialog_content = "...",
  ui_story_1019_10191001_32_dialog_content = "¿Problema del ingeniero? ¿Qué significa eso?",
  ui_story_1019_10191001_33_dialog_content = "¿Sabes de qué está hablando, Reinhardt?",
  ui_story_1019_10191001_34_dialog_content = "...",
  ui_story_1019_10191001_35_dialog_content = "No te desvíes del tema, Ulysses. ¿Cuál es tu objetivo para implementar el Programa Phospherus?",
  ui_story_1019_10191001_36_dialog_content = "Como ya sabes, para mejorar la supervivencia de los Aurorianos, Illumina ha estado experimentando con la transformación de Aurorianos durante años.",
  ui_story_1019_10191001_37_dialog_content = "Excepto por Helios y Denier, todos los sujetos destacados, desde los primeros experimentos de mejora hasta el Programa Phospherus, están presentes aquí.",
  ui_story_1019_10191001_38_dialog_content = "...",
  ui_story_1019_10191001_39_dialog_content = "...",
  ui_story_1019_10191001_40_dialog_content = "¿Experimentos de mejora y... sujetos destacados?",
  ui_story_1019_10191001_41_dialog_content = "Muchos soldados de la Federación Illumina han elegido mejorar su destreza en combate para proteger las vidas de las masas.",
  ui_story_1019_10191001_42_dialog_content = "Y hay aún más Aurorianos con discapacidades físicas que extendieron sus vidas a través de la tecnología.",
  ui_story_1019_10191001_43_dialog_content = "¿Soy uno, doctor, ya que me estás mirando directamente a mí?",
  ui_story_1019_10191001_44_dialog_content = "¿Soy uno de aquellos a quienes su tecnología les ha prolongado la vida?",
  ui_story_1019_10191001_45_dialog_content = "...",
  ui_story_1019_10191001_46_dialog_content = "¿Esto es una broma, verdad? Solo vine aquí para chequeos regulares... ¿pero una transformación para prolongar la vida?",
  ui_story_1019_10191001_47_dialog_content = "No eres un Aurorian normal, Sean. Eres un sujeto sobresaliente del Programa Phospherus.",
  ui_story_1019_10191001_48_dialog_content = "...",
  ui_story_1019_10191001_49_dialog_content = "Te resulta difícil de creer, ¿verdad? Sin embargo, simplemente no te das cuenta de lo afortunado que eres.",
  ui_story_1019_10191001_50_dialog_content = "Para alguien que vivió en una época de guerra como yo, cualquiera que fuera capaz de luchar podría quitarle el derecho a vivir a aquellos que no lo eran.",
  ui_story_1019_10191001_51_dialog_content = "Entonces, ¿qué elección harías si estuvieras en mi lugar?",
  ui_story_1019_10191001_52_dialog_content = "¿Qué nueva idea estás pensando hoy, Uly?",
  ui_story_1019_10191001_53_dialog_content = "El mismo de siempre.",
  ui_story_1019_10191001_54_dialog_content = "Ah, ingeniería genética. ¿Cómo crees que se les ocurrió ese término?",
  ui_story_1019_10191001_55_dialog_content = "¿Tiene sentido preguntarse?",
  ui_story_1019_10191001_56_dialog_content = "Lo importante es que lo estoy estudiando ahora.",
  ui_story_1019_10191001_57_dialog_content = "\"¿Cómo se les ocurrió el término?\" nunca cruzó por mi mente, porque a menudo es ridículo rastrear el origen.",
  ui_story_1019_10191001_58_dialog_content = "Gannon fue descubierto por una fuerza avanzada de Lumopolis.",
  ui_story_1019_10191001_59_dialog_content = "Aquellos guerreros sin miedo, casi exterminados al luchar contra los Eclipsites, solo se encontraron abandonados por Lumopolis...",
  ui_story_1019_10191001_60_dialog_content = "Esa fuerza eventualmente evolucionó en un poder militar en un rincón de la Subciudad.",
  ui_story_1019_10191001_61_dialog_content = "Pero por razones desconocidas, nunca puedo sacar las palabras de Robby de mi cabeza.",
  ui_story_1019_10191001_62_dialog_content = "¿Qué nueva idea estás pensando hoy, Uly?",
  ui_story_1019_10191001_63_dialog_content = "...",
  ui_story_1019_10191001_64_dialog_content = "¿Qué es eso que te tiene tan interesado?",
  ui_story_1019_10191001_65_dialog_content = "Las Crónicas de la Federación Illumina... ¿Por qué estás leyendo esto? ¿Ya no te burlas de la historia?",
  ui_story_1019_10191001_66_dialog_content = "¿Sabes cuántos años lleva la Federación Illumina, Robby?",
  ui_story_1019_10191001_67_dialog_content = "<color=#FFB400>649.</color>",
  ui_story_1019_10191001_68_dialog_content = "¿Lo sabes al pie de la letra?",
  ui_story_1019_10191001_69_dialog_content = "Por supuesto. Si mi padre no se hubiera opuesto, probablemente me habría convertido en historiador bajo el estímulo de mi mamá.",
  ui_story_1019_10191001_70_dialog_content = "¿No me estás poniendo a prueba sobre la hora de fundación de Illumina, verdad?",
  ui_story_1019_10191001_71_dialog_content = "Mientras profundizaba en la historia de la ingeniería genética, noté un problema en los Anales de la Federación Illumina.",
  ui_story_1019_10191001_72_dialog_content = "No se menciona cómo comenzó la ingeniería genética en Illumina, como si siempre hubiera habido un alto umbral que cruzar.",
  ui_story_1019_10191001_73_dialog_content = "¿Estás sugiriendo que en realidad es una tecnología de Lumopolis, que existía antes de Illumina?",
  ui_story_1019_10191001_74_dialog_content = "¿O que la historia de Illumina se remonta a más de 649 años?",
  ui_story_1019_10191001_75_dialog_content = "Eso es posible. Seguiré investigando eso.",
  ui_story_1019_10191001_76_dialog_content = "Por lo tanto, me obsesioné y me determiné a encontrar la respuesta.",
  ui_story_1019_10191001_77_dialog_content = "No estaba seguro si era paz o caos fuera del archivo.",
  ui_story_1019_10191001_78_dialog_content = "Solo sabía que la guerra no podía llegar a una habitación tan pequeña e interrumpir mi esfuerzo por encontrar la verdad.",
  ui_story_1019_10191001_79_dialog_content = "Un día, luego pasó un mes...",
  ui_story_1019_10191001_80_dialog_content = "Había una voz en mi cabeza diciéndome que no temiera fracasar porque la historia eventualmente proporcionaría la respuesta.",
  ui_story_1019_10191001_81_dialog_content = "Un año, luego dos años pasaron...",
  ui_story_1019_10191001_82_dialog_content = "Hasta que un día...",
  ui_story_1019_10191001_83_dialog_content = "¡Robby, mira esto! ¿Qué dice en la parte inferior derecha?",
  ui_story_1019_10191001_84_dialog_content = "¿El Ingeniero?",
  ui_story_1019_10191001_85_dialog_content = "¿Quién o qué es eso?",
  ui_story_1019_10191001_86_dialog_content = "Había notado muchas lagunas y despidos intencionales con respecto a la fuente de la ingeniería genética en mi investigación.",
  ui_story_1019_10191001_87_dialog_content = "Pero encontré una respuesta en algún lugar del libro.",
  ui_story_1019_10191001_88_dialog_content = "\"El problema de la sobrecarga de Lumina se resolvió bajo la guía de...\"",
  ui_story_1019_10191001_89_dialog_content = "¿Bajo la guía de quién?",
  ui_story_1019_10191001_90_dialog_content = "¡Exactamente! Alguien los guió, ¿verdad?",
  ui_story_1019_10191001_91_dialog_content = "¿El Ingeniero? ¿Crees que el Ingeniero fue omitido en el libro?",
  ui_story_1019_10191001_92_dialog_content = "Eso es lo que mi intuición me dice.",
  ui_story_1019_10191001_93_dialog_content = "Intrigante cómo fue eliminado en el texto principal pero se mantuvo en los márgenes...",
  ui_story_1019_10191001_94_dialog_content = "Pero, ¿puedes estar seguro, Uly? ¿Más de lo mismo en otro lugar?",
  ui_story_1019_10191001_95_dialog_content = "No, pero si incluyes al Ingeniero en todas esas descripciones oscuras...",
  ui_story_1019_10191001_96_dialog_content = "Eso explicaría muchas cosas.",
  ui_story_1019_10191001_97_dialog_content = "\"Los Aurorianos formaron rápidamente una unidad tecnológica para comenzar a estudiar la tecnología antigua bajo el liderazgo del Ingeniero.\"",
  ui_story_1019_10191001_98_dialog_content = "\"El Ingeniero lideró la unidad técnica para examinar la estructura de la Ciudad Gannon y les enseñó a usar ciertas tecnologías.\"",
  ui_story_1019_10191001_99_dialog_content = "Nunca te he visto más feliz, Uly.",
  ui_story_1019_10191001_100_dialog_content = "¡Seguiré cavando!",
  ui_story_1019_10191001_101_dialog_content = "Al constante sonido de los bombardeos de artillería fuera del archivo...",
  ui_story_1019_10191001_102_dialog_content = "Dame más tiempo. ¡Sé que se convertirán en gritos de victoria de los Aurorians sobre los Eclipsites!",
  ui_story_1019_10191101_1_dialog_content = "¿Cómo va con el mapa de la Zona Oscura?",
  ui_story_1019_10191101_2_dialog_content = "¡Oye, si no es el Dr. Algol! ¡No todos los días te aventuras fuera de tu laboratorio!",
  ui_story_1019_10191101_3_dialog_content = "Hola, Dr. Joyce.",
  ui_story_1019_10191101_4_dialog_content = "Hola. Oye, ¿no eres tú el Caelestita?",
  ui_story_1019_10191101_5_dialog_content = "Hola.",
  ui_story_1019_10191101_6_dialog_content = "Algol me dijo que tu Colossus ha sido de gran ayuda en mi mapeo de la Zona Oscura. ¡Muchas gracias!",
  ui_story_1019_10191101_7_dialog_content = "Un placer. Prometí ayudar a Illumina y también me ayuda en el proceso.",
  ui_story_1019_10191101_8_dialog_content = "Deja la charla, Joyce. Quiero tu opinión sobre una coordenada de la Zona Oscura y qué tan factible es explorarla.",
  ui_story_1019_10191101_9_dialog_content = "¿Nuevos datos sobre la Zona Oscura? Casi estás alcanzando la <color=#FFB400>simulación geográfica</color>.",
  ui_story_1019_10191101_10_dialog_content = "Como sabes, mi modelo actual se deduce de los terrenos que ya hemos trazado.",
  ui_story_1019_10191101_11_dialog_content = "También significa que si la coordenada está demasiado lejos de Gannon con discontinuidad en medio, los cálculos se vuelven, bueno, complicados.",
  ui_story_1019_10191101_12_dialog_content = "Solo puedo calcular la contigüidad y la discontinuidad por separado basándome en las probabilidades y simular los entornos en consecuencia.",
  ui_story_1019_10191101_13_dialog_content = "Entonces, ¿cuál es el resultado? ¿Ya se te ocurrió uno?",
  ui_story_1019_10191101_14_dialog_content = "Tsk, tan impaciente...",
  ui_story_1019_10191101_15_dialog_content = "Solo dime.",
  ui_story_1019_10191101_16_dialog_content = "Vale, vale. Todavía estoy perfeccionando el modelo a partir de las pistas proporcionadas por Helios.",
  ui_story_1019_10191101_17_dialog_content = "Fuera de las regiones habitables de Astra se encuentra una capa irregular de pantano congelado cubierto de nieve fina.",
  ui_story_1019_10191101_18_dialog_content = "Más allá del pantano, tienes un bosque de pilares de hielo de diferentes formas y tamaños...",
  ui_story_1019_10191101_19_dialog_content = "Algunos son puntiagudos como una espiga, algunos se parecen a conos al revés, y algunos parecen espirales retorcidas...",
  ui_story_1019_10191101_20_dialog_content = "¡Ve al grano!",
  ui_story_1019_10191101_21_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1019_10191101_22_dialog_content = "¿Te parece interesante?",
  ui_story_1019_10191101_23_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1019_10191101_24_dialog_content = "...",
  ui_story_1019_10191101_25_dialog_content = "<color=#e8d9bb>Después de charlar con Joyce durante quince minutos...</color>",
  ui_story_1019_10191101_26_dialog_content = "... Así que entre estos pilares, parte del aire se licuaría debido a la temperatura y se formaría en monolitos extraños.",
  ui_story_1019_10191101_27_dialog_content = "No estoy seguro del principio exacto, aunque puede estar relacionado con la tecnología de levitación de Lumopolis.",
  ui_story_1019_10191101_28_dialog_content = "Y a medida que el flujo de aire se solidificaba, algunos subían mientras que otros descendían...",
  ui_story_1019_10191101_29_dialog_content = "Espera, ¿qué acabas de decir?",
  ui_story_1019_10191101_30_dialog_content = "... Esa es mi conclusión de por qué se veían tan diferentes entre sí.",
  ui_story_1019_10191101_31_dialog_content = "¿Qué estás preguntando exactamente?",
  ui_story_1019_10191101_32_dialog_content = "Pilares de roca que se elevan hacia arriba...",
  ui_story_1019_10191101_33_dialog_content = "Los vi en la mente de Ulysses.",
  ui_story_1019_10191101_34_dialog_content = "Estoy seguro de que eso es lo que vi... ¿Podría ser una coincidencia?",
  ui_story_1019_10191101_35_dialog_content = "...",
  ui_story_1019_10191101_36_dialog_content = "Repite lo que acabas de decir, Joyce.",
  ui_story_1019_10191101_37_dialog_content = "Dije, \"A medida que el flujo de aire se solidificaba, algunos subían mientras que otros descendían. Por eso se veían tan diferentes entre sí.\"",
  ui_story_1019_10191101_38_dialog_content = "Hablando de subir y bajar, una vez hicimos un experimento...",
  ui_story_1019_10191101_39_dialog_content = "No puede estar mal...",
  ui_story_1019_10191101_40_dialog_content = "Ahora que lo pienso, algunas de las columnas de roca helada voladoras tenían halos brillantes en ellas...",
  ui_story_1019_10191101_41_dialog_content = "¿Quieres decir que viste el núcleo de Guardian One? ¿Estaba en esos pilares voladores?!",
  ui_story_1019_10191101_42_dialog_content = "... ¿Es eso así?",
  ui_story_1019_10191101_43_dialog_content = "¡Sí! ¡Lo es!",
  ui_story_1019_10191101_44_dialog_content = "¡Esto es interesante! ¡Qué maravilloso!",
  ui_story_1019_10191101_45_dialog_content = "Lo que viste en la mente de Ulysses coincide precisamente con la imagen que se sospecha es el núcleo de Guardian One, que fue enviada por el equipo de expedición de la Zona Oscura.",
  ui_story_1019_10191101_46_dialog_content = "Y si las columnas voladoras estuvieran dentro del rango de las coordenadas de Soroz...",
  ui_story_1019_10191101_47_dialog_content = "Lo entiendo... Las señales intermitentes no se traducen en múltiples coordenadas, ¡sino porque los pilares se están moviendo!",
  ui_story_1019_10191101_48_dialog_content = "Permíteme entender esto. Entonces, no solo Ulysses sabe dónde está el núcleo, sino que probablemente también es de donde vinieron los Colosos?",
  ui_story_1019_10191101_49_dialog_content = "¡Incluso insinuó que sabía con qué se encontró Vice!",
  ui_story_1019_10191101_50_dialog_content = "...",
  ui_story_1019_10191101_51_dialog_content = "Ya veo. No solo te he sido de gran ayuda, sino que también he resuelto un gran misterio.",
  ui_story_1019_10191101_52_dialog_content = "Tch... Pero si está conectado con el Eclipse, eso no es una buena noticia de ninguna manera que lo veas.",
  ui_story_1019_10191101_53_dialog_content = "Ulysses nunca ha abandonado la Subciudad, sin embargo, está tan profundamente involucrado en el plan del Eclipse...",
  ui_story_1019_10191101_54_dialog_content = "Estoy pensando, ¿los Wraiths se infiltraron en Gannon y se llevaron el núcleo de Guardian One gracias a Ulysses?",
  ui_story_1019_10191101_55_dialog_content = "Tengo una teoría aún más audaz...",
  ui_story_1019_10191101_56_dialog_content = "Es imposible que Guardian One pueda eludir mi sistema de seguridad a menos que alguien use esa cosa para sortearlo...",
  ui_story_1019_10191101_57_dialog_content = "Ese prototipo \"guardado por razones de seguridad\".",
  ui_story_1019_10191101_58_dialog_content = "...",
  ui_story_1019_10191101_59_dialog_content = "Si Ulysses es el que opera el prototipo en secreto, debemos ir a la Asamblea de Illumina y exigir una explicación.",
  ui_story_1019_10191101_60_dialog_content = "No, vayamos directo a su oficina.",
  ui_story_1019_10191101_61_dialog_content = "¡Si tenemos razón, ese lugar será el más peligroso en Illumina!",
  ui_story_1019_10191101_62_dialog_content = "...",
  ui_story_1019_10191201_1_dialog_content = "May Pregunto, ¿qué estás haciendo? Borrando texto, ocultando la historia...",
  ui_story_1019_10191201_2_dialog_content = "¿Qué estás ocultando sobre el Ingeniero? ¿O es ese algún secreto inconfesable de Lumopolis?",
  ui_story_1019_10191201_3_dialog_content = "Lo que puedo confirmar es que toda la información sobre el Ingeniero solo está disponible en los archivos de Illumina y el Comité no tiene conocimiento más allá de eso.",
  ui_story_1019_10191201_4_dialog_content = "¡¿Me tomas por tonto?!",
  ui_story_1019_10191201_5_dialog_content = "El Comité no eliminó la información.",
  ui_story_1019_10191201_6_dialog_content = "Al menos no el Comité actual.",
  ui_story_1019_10191201_7_dialog_content = "Si la Crisis de Darkover no hubiera ocurrido, lo que obligó a los altos mandos a levantar las restricciones sobre la investigación del Guardián, nunca me habría encontrado con nada sobre el Ingeniero.",
  ui_story_1019_10191201_8_dialog_content = "¿Guardián?",
  ui_story_1019_10191201_9_dialog_content = "Una misteriosa máquina antigua descubierta en Gannon por un equipo avanzado de Lumopolis.",
  ui_story_1019_10191201_10_dialog_content = "Los colonos posteriores lo nombraron Guardián.",
  ui_story_1019_10191201_11_dialog_content = "¿El Guardián sigue en estudio?",
  ui_story_1019_10191201_12_dialog_content = "Algol solo tiene una copia <color=#FFB400>en caja de arena</color>. El prototipo fue sellado debido a preocupaciones de seguridad.",
  ui_story_1019_10191201_13_dialog_content = "Ese era solo el plan original...",
  ui_story_1019_10191201_14_dialog_content = "¿Ulysses?!",
  ui_story_1019_10191201_15_dialog_content = "Siempre sospeché que había conexiones entre el encubrimiento del prototipo y la falta de transparencia sobre el Ingeniero.",
  ui_story_1019_10191201_16_dialog_content = "Hasta que encontré numerosas notas del Ingeniero en el prototipo.",
  ui_story_1019_10191201_17_dialog_content = "<color=#e8d9bb>¡Clink, clink!</color>",
  ui_story_1019_10191201_18_dialog_content = "¡Ahí estás, Uly! Te he estado buscando todo el día. Estábamos preocupados de que te hubieras ido a la batalla.",
  ui_story_1019_10191201_19_dialog_content = "Dijeron que nunca volverías a ponerte de pie, pero sabía que nada podía mantenerte abajo.",
  ui_story_1019_10191201_20_dialog_content = "¿Verdad?",
  ui_story_1019_10191201_21_dialog_content = "...",
  ui_story_1019_10191201_22_dialog_content = "... Estás terriblemente callado. ¿Qué sucede, Uly?",
  ui_story_1019_10191201_23_dialog_content = "¿Todavía recuerdas los archivos del Ingeniero en los que he estado investigando?",
  ui_story_1019_10191201_24_dialog_content = "Sí. Pero pensé que con lo mal que ha ido la guerra, más tú... que acabas de perder a tu familia, ya habrías abandonado hace tiempo.",
  ui_story_1019_10191201_25_dialog_content = "No lo vas a creer, Robby, pero esa antigua IA recientemente revelada por el Comité es la clave para el misterio del Ingeniero.",
  ui_story_1019_10191201_26_dialog_content = "¿IA antigua? ¿El Guardián, verdad? ¿No está trabajando Algol en ese caso?",
  ui_story_1019_10191201_27_dialog_content = "Eso es solo una copia virtualizada. Este que estás viendo ahora es el original, el prototipo.",
  ui_story_1019_10191201_28_dialog_content = "¡Uly! ¿Moviste el prototipo sellado...? ¿Te das cuenta de que irás a la cárcel por esto?",
  ui_story_1019_10191201_29_dialog_content = "Sería diferente si pudiera desenterrar las notas de investigación del Ingeniero...",
  ui_story_1019_10191201_30_dialog_content = "...",
  ui_story_1019_10191201_31_dialog_content = "El Ingeniero no solo se encargó de la ingeniería genética...",
  ui_story_1019_10191201_32_dialog_content = "Sus hipótesis sobre los experimentos aurorianos y la tecnología mágica, así como sus pensamientos sobre la naturaleza del cuerpo y la mente...",
  ui_story_1019_10191201_33_dialog_content = "¡Golpearon mi cerebro como poderosas corrientes eléctricas! ¡Nunca había estado tan emocionado!",
  ui_story_1019_10191201_34_dialog_content = "Ulises...",
  ui_story_1019_10191201_35_dialog_content = "Déjame terminar.",
  ui_story_1019_10191201_36_dialog_content = "Mencionó un intento de edición genética auroriana dirigida en una de sus notas...",
  ui_story_1019_10191201_37_dialog_content = "¡El resultado fueron rasgos físicos varias cientos de veces superiores a los Aurorianos modernos! ¿Te das cuenta de lo que eso significa?",
  ui_story_1019_10191201_38_dialog_content = "¿La era en la que estaba el Ingeniero tenía un nivel tecnológico más alto que ahora?",
  ui_story_1019_10191201_39_dialog_content = "¿Qué otra cosa?",
  ui_story_1019_10191201_40_dialog_content = "¡Oh, y el Ingeniero \"posee\" al Guardián!",
  ui_story_1019_10191201_41_dialog_content = "No, Robby, ninguno de esos es el punto.",
  ui_story_1019_10191201_42_dialog_content = "El punto es: si la tecnología pudiera replicarse, no tendríamos que refugiarnos de los Eclipsites en esta sombría ciudad subterránea.",
  ui_story_1019_10191201_43_dialog_content = "...",
  ui_story_1019_10191201_44_dialog_content = "Si todo lo que dijiste es verdad, Uly, eso sería...",
  ui_story_1019_10191201_45_dialog_content = "¿Sorprendente, verdad? ¡Será sin duda un avance y el futuro de Illumina! También significa la realización de mi sueño: ¡derrotar a los Eclipsites y volver a la superficie!",
  ui_story_1019_10191201_46_dialog_content = "¡Y también tu sueño de viajar por todo Eoria!",
  ui_story_1019_10191201_47_dialog_content = "Viajando por todo Eoria...",
  ui_story_1019_10191201_48_dialog_content = "Hay un coraje y fuerza inigualables en lo profundo de tu corazón, Uly.",
  ui_story_1019_10191201_49_dialog_content = "Y ahí estaba yo, preocupado por ti... Me alegra verte de vuelta en espíritu.",
  ui_story_1019_10191201_50_dialog_content = "De todos modos, mientras estés bien...",
  ui_story_1019_10191201_51_dialog_content = "No sentí nada cuando Robby dijo eso por primera vez.",
  ui_story_1019_10191201_52_dialog_content = "No fue hasta que perdió esa sonrisa y luego fue abrumado por el dolor de la guerra que entendí el verdadero mensaje.",
  ui_story_1019_10191201_53_dialog_content = "Debo apresurarme y recrear el trabajo del Ingeniero antes de que los Eclipsites erradiquen a los Aurorianos.",
  ui_story_1019_10191201_54_dialog_content = "Incluso si eso significaba que tenía que bloquear a todos, incluyéndome a mí mismo.",
  ui_story_1019_10191201_55_dialog_content = "Porque solo me sentía vivo cuando descubría formas de mejorar el poder de combate de los aurorianos en las notas del Ingeniero...",
  ui_story_1019_10191201_56_dialog_content = "*Tose* ¡Y alegría también!",
  ui_story_1019_10191201_57_dialog_content = "¿Se siente bien, señor? ¿Necesita...?",
  ui_story_1019_10191201_58_dialog_content = "¡Estoy bien...! *tose*",
  ui_story_1019_10191201_59_dialog_content = "Me llevó casi 10 años buscar la pista que dejó el Ingeniero y reconstruir su trabajo.",
  ui_story_1019_10191201_60_dialog_content = "¡10 años! ¿Qué pueden lograr ahora que han tomado mi laboratorio?",
  ui_story_1019_10191201_61_dialog_content = "<color=#e8d9bb>Golpeteo de pitter...</color>",
  ui_story_1019_10191201_62_dialog_content = "Los documentos están increíblemente organizados. El TOC de ese anciano nos está ahorrando tiempo y esfuerzo. Oye, ¿qué es esto...?",
  ui_story_1019_10191201_63_dialog_content = "...",
  ui_story_1019_10191201_64_dialog_content = "Oye, ¿no acordamos solo una última ronda? Ya ha pasado media hora. ¿Estás intentando hacer trampa?",
  ui_story_1019_10191201_65_dialog_content = "Bueno, puedes hacerlo tú solo si requiere poco esfuerzo, Migard!",
  ui_story_1019_10191201_66_dialog_content = "Hacía mucho tiempo que no jugaba a un juego tan fácil como este. El único inconveniente es que corre muy lento!",
  ui_story_1019_10191201_67_dialog_content = "¿Falta algo en las actualizaciones generales de las computadoras de Illumina? ¿O es esta máquina el tesoro privado de ese anciano?",
  ui_story_1019_10191201_68_dialog_content = "¿Qué falta?",
  ui_story_1019_10191201_69_dialog_content = "Uh, te juro que no estoy jugando mientras estoy de servicio! Es, uh...",
  ui_story_1019_10191201_70_dialog_content = "Déjame ver la computadora.",
  ui_story_1019_10191201_71_dialog_content = "¿Es esta la máquina, Dr. Algol?",
  ui_story_1019_10191201_72_dialog_content = "No. Quizás hay alguna pista que nos estamos perdiendo...",
  ui_story_1019_10191201_73_dialog_content = "Espera, no te muevas...",
  ui_story_1019_10191201_74_dialog_content = "¿Qué haces, acercándote tanto?",
  ui_story_1019_10191201_75_dialog_content = "¿Cómo se supone que descubra qué está mal sin acercarme a ello?",
  ui_story_1019_10191201_76_dialog_content = "¿Se encontraron con algo terrible en el camino? Tengo un mal presentimiento...",
  ui_story_1019_10191201_77_dialog_content = "¿Estás hablando de mí o de Bool?",
  ui_story_1019_10191201_78_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1019_10191201_79_dialog_content = "¿Peligro? No, ¿gran peligro? Ese fue el caso cuando nos conocimos por primera vez Ulysses...",
  ui_story_1019_10191201_80_dialog_content = "Algo se sintió mal desde que entraste. Ahora tengo la sensación de que nos están observando en este laboratorio...",
  ui_story_1019_10191201_81_dialog_content = "¿Puedes sentirlo, joven?",
  ui_story_1019_10191201_82_dialog_content = "Un poquito...",
  ui_story_1019_10191201_83_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1019_10191201_84_dialog_content = "¡Ay! ¿Cuántas veces tengo que decirte que no me tires del cuello así, Bool!",
  ui_story_1019_10191201_85_dialog_content = "¿Fuera de la puerta? ¿Qué hay allí...?",
  ui_story_1019_10191201_86_dialog_content = "Oh no, estoy detectando una corriente muy poderosa de Darkflow...",
  ui_story_1019_10191201_87_dialog_content = "El Eclipsite que pasó desapercibido... Logró evadir las Espinas de Buceo.",
  ui_story_1019_10191201_88_dialog_content = "¡Cuidado, todos!",
  ui_story_1019_10191201_89_dialog_content = "<color=#828282>¡Bam!</color>",
  ui_story_1019_10191202_1_dialog_content = "¡Hraaagh—!",
  ui_story_1019_10191202_2_dialog_content = "¿Finalmente está muerto?",
  ui_story_1019_10191202_3_dialog_content = "Tan grande... ¡Sería un jefe en cualquier juego!",
  ui_story_1019_10191202_4_dialog_content = "Pero no tiene marcas de ningún tipo. ¿Cómo sabemos de dónde vino?",
  ui_story_1019_10191202_5_dialog_content = "No tiene un número de serie como los sujetos Eclipsite.",
  ui_story_1019_10191202_6_dialog_content = "Además, ni siquiera sabemos si realmente es un sujeto Eclipsite o qué...",
  ui_story_1019_10191202_7_dialog_content = "¿Es uno de los sujetos de Ulysses? ¿Tiene la intención de usar estos monstruos contra el Comité como lo hizo con Wrath y sus guardias?",
  ui_story_1019_10191202_8_dialog_content = "Sin embargo, crear armas contra tu propia gente te hace igual que el Eclipse.",
  ui_story_1019_10191202_9_dialog_content = "¿El Comité ha llegado a una decisión?",
  ui_story_1019_10191202_10_dialog_content = "Todavía no podemos ponernos en contacto con el Gran Mariscal. Probablemente la revisión aún no ha terminado.",
  ui_story_1019_10191202_11_dialog_content = "No podemos esperar al Comité. Tenemos que actuar ahora para rastrear el prototipo y la laguna. Eso es más urgente que el juicio de Ulysses.",
  ui_story_1019_10191202_12_dialog_content = "Correcto. Discutamos nuestros hallazgos en 10 minutos.",
  ui_story_1019_10191202_13_dialog_content = "Tengo que revisar el edificio del laboratorio primero y aislar a los investigadores. Podrían tener información útil.",
  ui_story_1019_10191202_14_dialog_content = "Por favor notifique a todos los patrulleros en la proximidad de la amenaza, Dr. Algol, y solicite refuerzos.",
  ui_story_1019_10191202_15_dialog_content = "Todavía no sabemos cuántos Eclipsites están alrededor y debemos estar en alerta máxima.",
  ui_story_1019_10191202_16_dialog_content = "No hay problema. Tengo que seguir buscando el prototipo yo mismo.",
  ui_story_1019_10191301_1_dialog_content = "¿Dónde lo dejé, Esien?",
  ui_story_1019_10191301_2_dialog_content = "Cómo solo te sentías vivo y alegre cuando leías las notas del Ingeniero...",
  ui_story_1019_10191301_3_dialog_content = "Así es, alegría...",
  ui_story_1019_10191301_4_dialog_content = "Alegría porque vi la magnífica visión del Ingeniero. ¡Utilizó la ingeniería genética Auroriana dirigida para crear un lote tras otro de súper soldados!",
  ui_story_1019_10191301_5_dialog_content = "¿Los súper soldados producidos en masa se convirtieron eventualmente en el Proyecto: Sol Artificial y el Programa Phospherus?",
  ui_story_1019_10191301_6_dialog_content = "Lo que realmente me sorprendió no fue duplicar el experimento, sino la nota final.",
  ui_story_1019_10191301_7_dialog_content = "El número de super soldados alcanzó repentinamente su punto máximo hace <color=#FFB400>600 años</color>.",
  ui_story_1019_10191301_8_dialog_content = "Pero eso fue cuando el Guardián fue cerrado por razones desconocidas.",
  ui_story_1019_10191301_9_dialog_content = "Y el Ingeniero fue borrado para siempre de la historia de Illumina.",
  ui_story_1019_10191301_10_dialog_content = "¿Porqué crees?",
  ui_story_1019_10191301_11_dialog_content = "...",
  ui_story_1019_10191301_12_dialog_content = "¿Qué opinas, Yingel?",
  ui_story_1019_10191301_13_dialog_content = "Um... ¿Porque el experimento del Ingeniero falló?",
  ui_story_1019_10191301_14_dialog_content = "No, fue un éxito rotundo.",
  ui_story_1019_10191301_15_dialog_content = "Fue porque Illumina finalmente se dio cuenta...",
  ui_story_1019_10191301_16_dialog_content = "Los súper soldados producidos en masa que el Ingeniero estaba generando eran en realidad los mismos Eclipsites que matarían a los Aurorians en la batalla.",
  ui_story_1019_10191301_17_dialog_content = "Creo que podría estar equivocado, Robby...",
  ui_story_1019_10191301_18_dialog_content = "Los Eclipsites recuperados del campo de batalla tenían composiciones genéticas más complicadas, pero aún se podían aislar ciertas muestras individuales.",
  ui_story_1019_10191301_19_dialog_content = "Los genes de los Aurorianos y algunos Eclipsites individuales son compatibles en más del 90%.",
  ui_story_1019_10191301_20_dialog_content = "¿90%?",
  ui_story_1019_10191301_21_dialog_content = "La mayoría de los Eclipsites compuestos inorgánicamente no son más que conchas que el enemigo disparó en el campo de batalla.",
  ui_story_1019_10191301_22_dialog_content = "Aun así, muchos de los otros enemigos tienen composiciones genéticas muy similares a las de los Aurorianos. Quizás sean ellos los que disparan los proyectiles.",
  ui_story_1019_10191301_23_dialog_content = "Nunca podremos derrotarlos a menos que hagamos armas similares. Ni siquiera podremos identificar a los enemigos que nos están lanzando estos proyectiles.",
  ui_story_1019_10191301_24_dialog_content = "¿Estás pensando en crear Eclipsites, Uly?",
  ui_story_1019_10191301_25_dialog_content = "No, nuestras armas serán más potentes que eso.",
  ui_story_1019_10191301_26_dialog_content = "Nuestras armas son tanto conchas de Eclipsites como Aurorianos con poderosos Luminatics.",
  ui_story_1019_10191301_27_dialog_content = "¿Integración genética de Eclipsites y Aurorianos...?",
  ui_story_1019_10191301_28_dialog_content = "Estás loco, Uly...",
  ui_story_1019_10191301_29_dialog_content = "No, finalmente lo he descubierto todo.",
  ui_story_1019_10191301_30_dialog_content = "Esta es la única forma en que nosotros, los Aurorianos, tenemos una oportunidad de vencer a los Eclipsites.",
  ui_story_1019_10191301_31_dialog_content = "Solo habría un resultado si lucháramos contra ellos con nuestras formas natales...",
  ui_story_1019_10191301_32_dialog_content = "Entonces, para ese fin, ¿debemos convertirnos en los Eclipsites?",
  ui_story_1019_10191301_33_dialog_content = "¡No transformándose! ¡Superándolos! Ahí es donde yace el genio del Ingeniero. Hizo a los Aurorians mucho más poderosos.",
  ui_story_1019_10191301_34_dialog_content = "¿Te das cuenta de lo que estás diciendo, Uly? ¡Estás dando la espalda a nuestro credo al rechazar el propósito de nuestra resistencia!",
  ui_story_1019_10191301_35_dialog_content = "Desde que descubriste las obras del Ingeniero, has llevado tu investigación demasiado lejos.",
  ui_story_1019_10191301_36_dialog_content = "¿Alguna vez se te pasó por la cabeza que, esto es lo que quería el Ingeniero, engañarnos para que creáramos Eclipsites, incluso convirtiéndonos en ellos mismos?",
  ui_story_1019_10191301_37_dialog_content = "¡No nos convertiré en Eclipsites sino en Aurorians más fuertes!",
  ui_story_1019_10191301_38_dialog_content = "Ya encontré el cómo. El proyecto pronto dará paso a una nueva fase.",
  ui_story_1019_10191301_39_dialog_content = "¿Siempre crees en mí, verdad? Puedo hacer realidad nuestros sueños. ¡Puedo cambiar el destino de todos los Aurorianos!",
  ui_story_1019_10191301_40_dialog_content = "No así, Uly... No así...",
  ui_story_1019_10191301_41_dialog_content = "Ni siquiera hemos descubierto una cosa en particular...",
  ui_story_1019_10191301_42_dialog_content = "Si afirmas que el Ingeniero lo hizo posible, ¿quién era él? ¿Por qué desapareció de la historia de Illumina?",
  ui_story_1019_10191301_43_dialog_content = "¿Por qué traicionó a Illumina y por qué se convirtió en enemigo de todos los Aurorianos?",
  ui_story_1019_10191301_44_dialog_content = "...",
  ui_story_1019_10191301_45_dialog_content = "¿Quién diablos era el Ingeniero?",
  ui_story_1019_10191301_46_dialog_content = "¿Eclipsito? ¿Auroriano? ¿Demonio? ¿O tal vez...",
  ui_story_1019_10191301_47_dialog_content = "¿Ninguna? *Tose*",
  ui_story_1019_10191301_48_dialog_content = "¿Cuánto más vas a toser? ¿No ibas a decir nada hasta que murieras si no intentábamos obligarte a hablar?",
  ui_story_1019_10191301_49_dialog_content = "Jeje... Incluso si quisiera detallar los 40 años de proceso laborioso, la carga que llevo sería tan grande, que no sabría por dónde empezar...",
  ui_story_1019_10191301_50_dialog_content = "Gracias a ti, recuerdo a Robby y lo entusiasmado que estaba.",
  ui_story_1019_10191301_51_dialog_content = "Pero la identidad del Ingeniero ya no me interesa.",
  ui_story_1019_10191301_52_dialog_content = "...",
  ui_story_1019_10191301_53_dialog_content = "Quizás ya no te importa quién es el Ingeniero, Ulysses.",
  ui_story_1019_10191301_54_dialog_content = "Pero me importa hacia dónde va Illumina.",
  ui_story_1019_10191301_55_dialog_content = "Te he dado suficiente tiempo para describir tu visión.",
  ui_story_1019_10191301_56_dialog_content = "Dime, ¿cómo debería decidir si el Programa Phospherus benefició a Illumina?",
  ui_story_1019_10191301_57_dialog_content = "Ante ustedes se encuentra alguien que ha traído una década de paz a Illumina, así como la persona con el mayor potencial para los próximos diez años.",
  ui_story_1019_10191301_58_dialog_content = "Solo hay una forma en que los Aurorians pueden superar a los Eclipsites, y ese es el camino que emprenderé, incluso sobre los huesos de los Aurorians.",
  ui_story_1019_10191301_59_dialog_content = "¿Quieres saber el beneficio? Esa es mi respuesta.",
  ui_story_1019_10191401_1_dialog_content = "Oficiales... Oigo algo...",
  ui_story_1019_10191401_2_dialog_content = "Todos los investigadores han sido notificados para evacuar el centro. ¿Qué estás haciendo aquí?",
  ui_story_1019_10191401_3_dialog_content = "Espera un minuto, te conozco... Eres el asistente de Ulysses.",
  ui_story_1019_10191401_4_dialog_content = "¿De qué contención escapó el sujeto?",
  ui_story_1019_10191401_5_dialog_content = "Los sujetos de prueba... Los sujetos de prueba del doctor están todos etiquetados y almacenados en lotes.",
  ui_story_1019_10191401_6_dialog_content = "Estos... lo siento, pero nunca los había visto antes. Sin embargo, los archivos relevantes deberían estar en la computadora del doctor.",
  ui_story_1019_10191401_7_dialog_content = "He revisado la computadora de Ulysses. Solo hay datos de experimentos e informes.",
  ui_story_1019_10191401_8_dialog_content = "¿Entonces, de dónde vinieron?",
  ui_story_1019_10191401_9_dialog_content = "Déjame ver...",
  ui_story_1019_10191401_10_dialog_content = "¿Acceso denegado? Supongo que hizo una contingencia.",
  ui_story_1019_10191401_11_dialog_content = "¿Qué opinas, Bool?",
  ui_story_1019_10191401_12_dialog_content = "¡Booo!",
  ui_story_1019_10191401_13_dialog_content = "Sí, eso es maravilloso!",
  ui_story_1019_10191401_14_dialog_content = "Introduce tu contraseña, asistente.",
  ui_story_1019_10191401_15_dialog_content = "Está bien.",
  ui_story_1019_10191401_16_dialog_content = "<color=#e8d9bb>Clic, clic-</color>",
  ui_story_1019_10191401_17_dialog_content = "<color=#e8d9bb>¡Zoom!</color>",
  ui_story_1019_10191401_18_dialog_content = "¡Sí, lo encontré!",
  ui_story_1019_10191401_19_dialog_content = "Los archivos sobre super soldados... ¿Cuántas iteraciones han pasado?",
  ui_story_1019_10191401_20_dialog_content = "Nunca había visto estos antes en el laboratorio...",
  ui_story_1019_10191401_21_dialog_content = "Por supuesto que no. ¡Son los experimentos secretos de Ulysses!",
  ui_story_1019_10191401_22_dialog_content = "Estos super soldados deben ser los que nos han estado atacando. ¿Dónde los mantienen?",
  ui_story_1019_10191401_23_dialog_content = "Guardado, guardado...",
  ui_story_1019_10191401_24_dialog_content = "¡Booo!",
  ui_story_1019_10191401_25_dialog_content = "¡Lo encontré!",
  ui_story_1019_10191401_26_dialog_content = "<color=#FFB400>Almacén Cero</color>? ¿No es eso...",
  ui_story_1019_10191401_27_dialog_content = "¿Existe un Almacén Cero en Gannon?",
  ui_story_1019_10191401_28_dialog_content = "Nunca lo escuché.",
  ui_story_1019_10191401_29_dialog_content = "Si es el Almacén Cero en el que estoy pensando...",
  ui_story_1019_10191401_30_dialog_content = "Sígueme!",
  ui_story_1019_10191401_31_dialog_content = "...",
  ui_story_1019_10191401_32_dialog_content = "Todos son simplemente demasiado rápidos para mí...",
  ui_story_1019_10191401_33_dialog_content = "Esto va más allá de transformar a los Aurorians... ¡Es una producción masiva de Eclipsites!",
  ui_story_1019_10191401_34_dialog_content = "Los que están violando el sistema de defensa ya son lo suficientemente peligrosos. Estaremos muertos si no encontramos la fuente rápidamente.",
  ui_story_1019_10191401_35_dialog_content = "<color=#e8d9bb>¡Crujido!</color>",
  ui_story_1019_10191401_36_dialog_content = "... ¿Este es el Almacén Cero?",
  ui_story_1019_10191401_37_dialog_content = "¡Tan enorme!",
  ui_story_1019_10191401_38_dialog_content = "Todas las puertas están abiertas... Es lo suficientemente grande para estacionar varios Engine VII.",
  ui_story_1019_10191401_39_dialog_content = "Huele a soluciones... ¿Es aquí donde se realizan los experimentos? Tengan cuidado, todos.",
  ui_story_1019_10191401_40_dialog_content = "<color=#e8d9bb>*Estático*</color>",
  ui_story_1019_10191401_41_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1019_10191401_42_dialog_content = "Es real...",
  ui_story_1019_10191401_43_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_1019_10191401_44_dialog_content = "¡Ese ruido vino del aparato de adelante! ¡Es un súper soldado!",
  ui_story_1019_10191401_45_dialog_content = "Parece un experimento a medio hacer, muy similar a los monstruos que nos emboscaron antes.",
  ui_story_1019_10191401_46_dialog_content = "¡Menos mal que encontramos la fuente! Tengan cuidado al revisar las cosas, todos.",
  ui_story_1019_10191401_47_dialog_content = "<color=#e8d9bb>*Estático*</color>",
  ui_story_1019_10191401_48_dialog_content = "Vaya, ¡je!",
  ui_story_1019_10191401_49_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1019_10191401_50_dialog_content = "Es mejor que no toques estos, Dr. Algol. ¡No queremos activar ninguna trampa!",
  ui_story_1019_10191401_51_dialog_content = "Panel de control de temperatura, botón de abortar, entrada...",
  ui_story_1019_10191401_52_dialog_content = "No puede estar equivocado...",
  ui_story_1019_10191401_53_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_1019_10191401_54_dialog_content = "¡Ese súper soldado realmente está luchando duro para escapar de ese aparato!",
  ui_story_1019_10191401_55_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1019_10191401_56_dialog_content = "El exterior de la pantalla y la unidad central fue reemplazado, pero el sistema operativo, la interfaz y los paneles de comando...",
  ui_story_1019_10191401_57_dialog_content = "¿Fueron las \"preocupaciones de seguridad\" solo una farsa?",
  ui_story_1019_10191401_58_dialog_content = "Y aquí...",
  ui_story_1019_10191401_59_dialog_content = "Sigue funcionando...",
  ui_story_1019_10191401_60_dialog_content = "¿Qué diablos ha estado haciendo aquí todo este tiempo?",
  ui_story_1019_10191401_61_dialog_content = "¡¡¡Booooo!!!",
  ui_story_1019_10191401_62_dialog_content = "¡Bool es increíblemente rápido!",
  ui_story_1019_10191401_63_dialog_content = "<color=#e8d9bb>Clang... Tintineo...!!!</color>",
  ui_story_1019_10191401_64_dialog_content = "rugir—",
  ui_story_1019_10191401_65_dialog_content = "¡Oh no, el súper soldado está suelto!",
  ui_story_1019_10191401_66_dialog_content = "No es seguro aquí, Dr. Algol, ¡por favor vete!",
  ui_story_1019_10191401_67_dialog_content = "...",
  ui_story_1019_10191401_68_dialog_content = "¡¡¡Dr. Algol!!!",
  ui_story_1019_10191401_69_dialog_content = "...",
  ui_story_1019_10191401_70_dialog_content = "<color=#e8d9bb>¡¡¡Grieta—!!!</color>",
  ui_story_1019_10191401_71_dialog_content = "¡Habilidad de Mecha!",
  ui_story_1019_10191401_72_dialog_content = "¡No son muros sino puertas en un espacio tan copioso!",
  ui_story_1019_10191401_73_dialog_content = "Sal de aquí. ¡Tenemos un gran monstruo en nuestra cola!",
  ui_story_1019_10191401_74_dialog_content = "Retrocede a la entrada... No lo entiendo. ¡Estaba vacío cuando entramos!",
  ui_story_1019_10191401_75_dialog_content = "... Fue aterrador cuando se puso de pie.",
  ui_story_1019_10191401_76_dialog_content = "Pero una vez que el Dr. Algol entró, ella estaba demasiado intrigada para mover sus pasos.",
  ui_story_1019_10191401_77_dialog_content = "¡Dr. Algol!",
  ui_story_1019_10191401_78_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1019_10191401_79_dialog_content = "Luchar contra los Eclipsites es tu especialidad.",
  ui_story_1019_10191401_80_dialog_content = "¡Eso es un Eclipsite detrás de ti! ¡No puedes ignorar tu propia seguridad, sin importar qué!",
  ui_story_1019_10191401_81_dialog_content = "Entenderás mi elección si has pasado por el dolor.",
  ui_story_1019_10191401_82_dialog_content = "Todos esos pelos que arranqué uno por uno...",
  ui_story_1019_10191401_83_dialog_content = "Todos los dedos que mordí hasta que sangraron...",
  ui_story_1019_10191401_84_dialog_content = "Y todos los códigos que me atormentaban pero a la vez me emocionaban...",
  ui_story_1019_10191401_85_dialog_content = "¡No hay posibilidad de que deje este prototipo otra vez!",
  ui_story_1019_10191401_86_dialog_content = "...",
  ui_story_1019_10191401_87_dialog_content = "¡Protege al Dr. Algol y prepárate para luchar!",
  ui_story_1019_10191502_1_dialog_content = "¿Todos están bien?",
  ui_story_1019_10191502_2_dialog_content = "Solo rasguños. No es gran cosa.",
  ui_story_1019_10191502_3_dialog_content = "Estás sangrando... ¿No me digas que vas a convertirte en un monstruo por infección como los de los juegos?",
  ui_story_1019_10191502_4_dialog_content = "... ¿Qué estás diciendo? Rasguños como estos son comunes en Black Umbrella Laboratories.",
  ui_story_1019_10191502_5_dialog_content = "Pero las Espinas de Buceo respondieron más allá de lo normal. Su composición y salida de energía mostraron cambios sustanciales.",
  ui_story_1019_10191502_6_dialog_content = "¡Concedido! ¡Pero estos monstruos aún no son rival para mi Trono!",
  ui_story_1019_10191502_7_dialog_content = "¿Cuál es el plan de Ulysses para hacer estos súper soldados en secreto? Y el prototipo sigue funcionando...",
  ui_story_1019_10191502_8_dialog_content = "Dado lo terco que es con el Programa Phospherus, no es difícil deducir que quería reemplazar a los Aurorianos con súper soldados y aumentar las posibilidades de supervivencia de los Aurorianos.",
  ui_story_1019_10191502_9_dialog_content = "Lo que me preocupa es: ¿son estos todos los super-soldados? Hay más de cien Aurorianos transformados solo en la Legión de Guardia de Wrath...",
  ui_story_1019_10191502_10_dialog_content = "Veamos si la Dra. Algol descubrió algo nuevo. Tal vez ella ha encontrado la fuente y el número total de los super-soldados.",
  ui_story_1019_10191502_11_dialog_content = "<color=#e8d9bb>Clic, clic-</color>",
  ui_story_1019_10191502_12_dialog_content = "Bool puede presionar botones... ¡y rápido en eso!",
  ui_story_1019_10191502_13_dialog_content = "Es correcto.",
  ui_story_1019_10191502_14_dialog_content = "Ahora sé por qué Bool me tiró del pelo.",
  ui_story_1019_10191502_15_dialog_content = "¡Bu!",
  ui_story_1019_10191502_16_dialog_content = "Dr. Algol, ¿cómo está Bool manejando el prototipo?",
  ui_story_1019_10191502_17_dialog_content = "¿Está vinculado a tu cerebro mientras le indica a sus tentáculos que ejecuten tus comandos?",
  ui_story_1019_10191502_18_dialog_content = "Buena suposición, pero no. Probablemente Bool está copiando mi acción anterior utilizando su sentido táctil y memoria.",
  ui_story_1019_10191502_19_dialog_content = "¿Algo nuevo aquí, Dr. Algol?",
  ui_story_1019_10191502_20_dialog_content = "Estos súper soldados a medio terminar son efectivamente los mismos que nos atacaron.",
  ui_story_1019_10191502_21_dialog_content = "¿Son todos estos?",
  ui_story_1019_10191502_22_dialog_content = "Ya es lo suficientemente increíble para mí descubrir el prototipo en funcionamiento...",
  ui_story_1019_10191502_23_dialog_content = "Pero probablemente no sabré más detalles sobre estos soldados hasta que inicie sesión en el sistema.",
  ui_story_1019_10191502_24_dialog_content = "Espero que podamos revisar a fondo el almacén mientras Bool ejecuta los algoritmos, para ver si hay algún otro sujeto o almacén presente.",
  ui_story_1019_10191502_25_dialog_content = "Todo, desde el robo del núcleo de Guardian One hasta las brechas en las defensas de Gannon, tiene algo que ver con Ulysses.",
  ui_story_1019_10191502_26_dialog_content = "Lo que necesito hacer ahora es encontrar cualquier otro riesgo que este prototipo aún en funcionamiento pueda representar, y para qué lo usó Ulysses.",
  ui_story_1019_10191502_27_dialog_content = "Realmente quiero darle a Ulysses una entrevista uno a uno ahora mismo...",
  ui_story_1019_10191502_28_dialog_content = "Apagado debido a preocupaciones de seguridad... Qué gracioso.",
  ui_story_1019_10191502_29_dialog_content = "¿Por qué es eso gracioso?",
  ui_story_1019_10191502_30_dialog_content = "Antes de que se permitiera cualquier investigación sobre el Guardián, había visitado esta máquina como uno de los estudiantes de Ulysses.",
  ui_story_1019_10191502_31_dialog_content = "No parecía interesado en la IA en ese momento y solo hizo lo que se suponía que debía hacer. Luego, cuando escuché que se cerró por razones de seguridad, pensé que había renunciado completamente a la idea.",
  ui_story_1019_10191502_32_dialog_content = "Entonces, ¿por qué lo ha estado usando en secreto?",
  ui_story_1019_10191502_33_dialog_content = "Ninguno de los cero avances en el estudio se debió a la mala configuración o a la falta de registros históricos...",
  ui_story_1019_10191502_34_dialog_content = "Siempre se debió a las personas que realizaban la investigación.",
  ui_story_1019_10191502_35_dialog_content = "¡¡¡Booooo!!!",
  ui_story_1019_10191502_36_dialog_content = "<color=#e8d9bb>¡Zoom!</color>",
  ui_story_1019_10191502_37_dialog_content = "Bien hecho...",
  ui_story_1019_10191502_38_dialog_content = "¿Finalmente vamos a ver la verdadera forma del Guardián?",
  ui_story_1019_10191502_39_dialog_content = "Un círculo y cuatro cursores... ¿De qué se trata esto?",
  ui_story_1019_10191502_40_dialog_content = "Parece que se necesita una contraseña de inicio de sesión. Pero no tengo idea si es el propio protocolo del prototipo o la medida de seguridad de Ulysses...",
  ui_story_1019_10191502_41_dialog_content = "¿Qué encontraremos después de iniciar sesión?",
  ui_story_1019_10191502_42_dialog_content = "Lo averiguaremos después de entrar.",
  ui_story_1019_10191502_43_dialog_content = "¡Prepárate para saltarte las instrucciones, Bool!",
  ui_story_1019_10191502_44_dialog_content = "¡Bu!",
  ui_story_1020_10200101_1_dialog_content = "<size=45>¡Booooo!</size>",
  ui_story_1020_10200101_2_dialog_content = "¿Realmente Bool puede manejar el descifrado de la contraseña?",
  ui_story_1020_10200101_3_dialog_content = "Bool es tan rápido... Es increíble verlo incluso de cerca.",
  ui_story_1020_10200101_4_dialog_content = "Esto solo confirma mis sospechas...",
  ui_story_1020_10200101_5_dialog_content = "Bool mostró una respuesta tan poderosa hacia la entrada a la oficina de Ulysses y hacia el mismo Ulysses.",
  ui_story_1020_10200101_6_dialog_content = "Quizás Bool estaba tratando de decirme que el prototipo está de alguna manera conectado con Ulysses.",
  ui_story_1020_10200101_7_dialog_content = "¿Cómo sabe Bool?",
  ui_story_1020_10200101_8_dialog_content = "También me gustaría saber. Después de todo, no parece que sea la primera vez que Bool opera este prototipo.",
  ui_story_1020_10200101_9_dialog_content = "Todo comenzó cuando Bool y yo nos conocimos por primera vez.",
  ui_story_1020_10200101_10_dialog_content = "Antes de que el prototipo fuera sellado, un equipo de investigadores y yo creamos una copia aislada del Sistema Guardián aquí mismo en este almacén en ruinas.",
  ui_story_1020_10200101_11_dialog_content = "Preocupado de que nos perdiéramos ciertos detalles, me quedé hasta tarde todos los días. Admito que parte de eso también se debía a mi deseo de pasar más tiempo con el prototipo.",
  ui_story_1020_10200101_12_dialog_content = "El zumbido de la maquinaria me ayudaba a dormir por la noche, pero de vez en cuando, me despertaba un extraño pitido...",
  ui_story_1020_10200101_13_dialog_content = "Llevé el simulador de vuelta a mi cuarto cuando terminó, solo para descubrir que algo parecido a un cable o un tentáculo se había enrollado alrededor de mi cuello...",
  ui_story_1020_10200101_14_dialog_content = "Desde entonces, una parte del prototipo se ha adherido a ti como un parásito.",
  ui_story_1020_10200101_15_dialog_content = "Eso suena como si compartiera ciertas similitudes con el Trono y las Espinas de Buceo.",
  ui_story_1020_10200101_16_dialog_content = "Quizás, pero ninguno de ustedes podría imaginar lo aterrador que fue conocer a Bool por primera vez!",
  ui_story_1020_10200101_17_dialog_content = "Destruyó cada pieza de muebles en mi habitación sin descanso ni vacilación.",
  ui_story_1020_10200101_18_dialog_content = "Siempre que intentaba comunicarme con Bool, se volvía un poco confrontacional...",
  ui_story_1020_10200101_19_dialog_content = "Mi clavícula, mis costillas, mi escápula... Fracturó casi cualquier parte de mi cuerpo a la que pudiera rodear...",
  ui_story_1020_10200101_20_dialog_content = "¿Llamas a eso \"confrontacional\"? ¡Suena como si Bool estuviera tratando de matarte!",
  ui_story_1020_10200101_21_dialog_content = "Precisamente por eso estoy tan enfocado en el entrenamiento físico.",
  ui_story_1020_10200101_22_dialog_content = "Espera un minuto... ¿Es por eso que tienes tanto equipo de ejercicio en tu laboratorio? ¿Para fortalecer tu cuerpo contra los ataques de Bool?",
  ui_story_1020_10200101_23_dialog_content = "Eso y mis exámenes físicos diarios, sí... De hecho, incluso me consideraría un habitual en el Centro Médico Illumina!",
  ui_story_1020_10200101_24_dialog_content = "Es increíble hasta dónde llegarás para estudiar a Bool, Dr. Algol...",
  ui_story_1020_10200101_25_dialog_content = "Es realmente emocionante ver a una mujer dedicada a la ciencia.",
  ui_story_1020_10200101_26_dialog_content = "Sabía que Bool no tenía ninguna mala intención hacia mí. A veces, simplemente lleva un tiempo para que los amigos se acostumbren el uno al otro.",
  ui_story_1020_10200101_27_dialog_content = "Pero cuando comencé a concentrarme de nuevo en mi trabajo, me di cuenta de que Bool era mucho más que una criatura parásita.",
  ui_story_1020_10200101_28_dialog_content = "Estaba extremadamente interesado en mi investigación e incluso me proporcionó comentarios muy útiles.",
  ui_story_1020_10200101_29_dialog_content = "Es difícil imaginar por lo que pasó Bool, desde ser parte del prototipo hasta lo que es ahora...",
  ui_story_1020_10200101_30_dialog_content = "De todos modos, para cuando me acostumbré a la presencia de Bool, me di cuenta de repente que había pasado casi seis meses encerrado en mi laboratorio.",
  ui_story_1020_10200101_31_dialog_content = "Pero ese medio año fue el momento más relajante y satisfactorio de mi vida.",
  ui_story_1020_10200101_32_dialog_content = "Fue entonces cuando la gente empezó a etiquetarme como un robot y un solitario sin amigos, pero no me importaba.",
  ui_story_1020_10200101_33_dialog_content = "No tengo que explicarme a los aurorianos que nunca podrán entenderme. De todos modos, siempre me he sentido más cómodo con las máquinas.",
  ui_story_1020_10200101_34_dialog_content = "No fue fácil lidiar con Guardian One tampoco... y me agotó mucho.",
  ui_story_1020_10200101_35_dialog_content = "Entonces primero fue Guardian One, ¿y luego Bool? Dr. Algol, realmente eres—",
  ui_story_1020_10200101_36_dialog_content = "¿Extraño?",
  ui_story_1020_10200101_37_dialog_content = "¡Un poco, pero eso solo te hace aún más interesante!",
  ui_story_1020_10200101_38_dialog_content = "Estoy de acuerdo. Siempre me ha gustado ser raro, ya sabes.",
  ui_story_1020_10200101_39_dialog_content = "Eso es realmente música para mis oídos. También encajo en esa etiqueta.",
  ui_story_1020_10200101_40_dialog_content = "¡Nada malo con las etiquetas! Solo mira las mías: As de los Juegos, Máquina de Raid, y Maldición de la Próxima Ronda...",
  ui_story_1020_10200101_41_dialog_content = "¡Quiero conseguir tantas etiquetas en esa línea como sea posible!",
  ui_story_1020_10200101_42_dialog_content = "Yo también, porque suenan únicos. ¿Y tú, joven, cuál es tu etiqueta?",
  ui_story_1020_10200101_43_dialog_content = "No creo que tenga ninguna etiqueta...",
  ui_story_1020_10200101_44_dialog_content = "¡Lo sé, es el Perdedor!",
  ui_story_1020_10200101_45_dialog_content = "S-Sí, claro...",
  ui_story_1020_10200101_46_dialog_content = "¿Así que ahora aceptas eso con gusto aunque antes lo odiabas?",
  ui_story_1020_10200101_47_dialog_content = "Simplemente no puedo pensar en nada más en este momento...",
  ui_story_1020_10200101_48_dialog_content = "Basta de hablar. ¿Qué debemos hacer ahora, Dr. Algol?",
  ui_story_1020_10200101_49_dialog_content = "Oh, nada por el momento.",
  ui_story_1020_10200101_50_dialog_content = "¿Escuchas esos sonidos? Suena como si Bool estuviera revisando los archivos de datos actualizados del prototipo por instinto.",
  ui_story_1020_10200101_51_dialog_content = "Después de esto, Bool ajustará su lógica operativa y descifrará la contraseña. Sin embargo, podría tomar un poco más de tiempo.",
  ui_story_1020_10200101_52_dialog_content = "Pero una vez que esté hecho, tendremos acceso a más que solo los planes de Ulysses.",
  ui_story_1020_10200101_53_dialog_content = "Incluso podríamos ser capaces de usar los códigos de defensa del Guardián para construir un nuevo núcleo y reforzar las defensas de Illumina.",
  ui_story_1020_10200101_54_dialog_content = "¡Eso será maravilloso!",
  ui_story_1020_10200101_55_dialog_content = "Me sorprende que este prototipo siga funcionando después de todos estos años. Encima de eso, solo se descubrió gracias a un Caelestite.",
  ui_story_1020_10200101_56_dialog_content = "Supongo que no puedes descartar ninguna posibilidad cuando se trata de investigación.",
  ui_story_1020_10200101_57_dialog_content = "Jajaja... ¡Es alucinante, de verdad! ¡Jajajaja!",
  ui_story_1020_10200101_58_dialog_content = "Tengo una pregunta... Si Ulysses realmente está produciendo secretamente súper soldados en este lugar...",
  ui_story_1020_10200101_59_dialog_content = "¿No se sentiría incómodo tratando a tantos soldados heridos en el centro médico?",
  ui_story_1020_10200101_60_dialog_content = "No creo que se sintiera así si el prototipo nos hubiera dicho que estaba trabajando con Eclipsites.",
  ui_story_1020_10200101_61_dialog_content = "Las personas no buscan razones para explicar sus acciones malvadas. Simplemente se deleitan en sus métodos.",
  ui_story_1020_10200201_1_dialog_content = "Ante ti se encuentra alguien que trajo una década de paz a Illumina, así como la persona con el mayor potencial para los próximos diez años.",
  ui_story_1020_10200201_2_dialog_content = "¿Quieres saber el beneficio? Esa es mi respuesta.",
  ui_story_1020_10200201_3_dialog_content = "¿Trajo una década de paz a Illumina... Te refieres a Reinhardt?",
  ui_story_1020_10200201_4_dialog_content = "Illumina ha tenido numerosos Grandes Mariscales, algunos eran naturalmente fuertes, pero muchos más confiaron en el trabajo duro.",
  ui_story_1020_10200201_5_dialog_content = "Antes de Reinhardt, muchos de esos Grandes Mariscales no podían controlar sus poderes...",
  ui_story_1020_10200201_6_dialog_content = "Terminaron sus vidas voluntaria o forzosamente.",
  ui_story_1020_10200201_7_dialog_content = "Experimentos similares se habían estado realizando durante años antes de que yo naciera.",
  ui_story_1020_10200201_8_dialog_content = "Creo que este es el pasado que Illumina nunca querría mencionar. Además, es una bofetada en la cara para los investigadores.",
  ui_story_1020_10200201_9_dialog_content = "Si no hubiera propuesto la idea de modificar a los soldados cuando son solo niños pequeños y el proceso de selección para <color=#FFB400>Subciudad 80</color>...",
  ui_story_1020_10200201_10_dialog_content = "No habría existido un valiente Gran Mariscal como Reinhardt en Illumina.",
  ui_story_1020_10200201_11_dialog_content = "...",
  ui_story_1020_10200201_12_dialog_content = "El lanzamiento del Proyecto: Sol Artificial finalmente puso la tecnología de Illumina en el camino correcto. Incluso se podría decir que sobresalió.",
  ui_story_1020_10200201_13_dialog_content = "Probablemente sacrificamos a algunas personas en el ínterin, pero eso fue necesario para mantener la paz y el progreso.",
  ui_story_1020_10200201_14_dialog_content = "Así que admites que el desastre en <color=#FFB400>Entrañas 80</color> no se debió a un informe erróneo...",
  ui_story_1020_10200201_15_dialog_content = "Por supuesto que no, pero no tengo que explicar cada paso del experimento al público.",
  ui_story_1020_10200201_16_dialog_content = "Una administración estable requiere un control estricto. Solo haría que el impacto ético y moral sea más letal para la gente de Illumina.",
  ui_story_1020_10200201_17_dialog_content = "Impacto ético y moral...",
  ui_story_1020_10200201_18_dialog_content = "La información que costó la vida de mis compañeros solo fue un paso en el experimento para ti...",
  ui_story_1020_10200201_19_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1020_10200201_20_dialog_content = "¿Todavía recuerdas el objetivo de esta misión de reconocimiento en Entrañas 80?",
  ui_story_1020_10200201_21_dialog_content = "¡Debemos tener éxito!",
  ui_story_1020_10200201_22_dialog_content = "¡Graaah!",
  ui_story_1020_10200201_23_dialog_content = "¡Señor! Esta es la información que <color=#FFB400>Peng</color> me dio... ¡No deshonró al equipo de exploración!",
  ui_story_1020_10200201_24_dialog_content = "Peng... ¡Buen trabajo! ¡Lo hiciste extremadamente bien!",
  ui_story_1020_10200201_25_dialog_content = "La salida está delante de nosotros, Anatoli. ¡Corramos todo el camino hacia afuera!",
  ui_story_1020_10200201_26_dialog_content = "¡Sí señor!",
  ui_story_1020_10200201_27_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1020_10200201_28_dialog_content = "¡Señor!",
  ui_story_1020_10200201_29_dialog_content = "¡Dale a Anatoli la información! Tú, y vosotros, cubrid la retirada conmigo!",
  ui_story_1020_10200201_30_dialog_content = "¡Sí señor!",
  ui_story_1020_10200201_31_dialog_content = "Señor, yo—",
  ui_story_1020_10200201_32_dialog_content = "¿Todavía recuerdas lo que te enseñé sobre el trabajo de reconocimiento?",
  ui_story_1020_10200201_33_dialog_content = "...",
  ui_story_1020_10200201_34_dialog_content = "¡Si un compañero te entrega alguna información, debes escapar con ella inmediatamente a toda costa!",
  ui_story_1020_10200201_35_dialog_content = "¡Entendido, señor! ¡Pero todos saldremos de aquí!",
  ui_story_1020_10200201_36_dialog_content = "¡Graaah!",
  ui_story_1020_10200201_37_dialog_content = "Argh-",
  ui_story_1020_10200201_38_dialog_content = "¿Ya has olvidado lo que te dije? ¡No dejes que las emociones interfieran con tu trabajo! Cuando haces trabajo de reconocimiento, solo hay información, Eclipsites y personas muertas!",
  ui_story_1020_10200201_39_dialog_content = "¡Vete!",
  ui_story_1020_10200201_40_dialog_content = "¡Graaah!",
  ui_story_1020_10200201_41_dialog_content = "¡Señor!",
  ui_story_1020_10200201_42_dialog_content = "... ¡Ve!",
  ui_story_1020_10200201_43_dialog_content = "... Regresa con la información que te di, Anatoli...",
  ui_story_1020_10200201_44_dialog_content = "... Conmigo cubriendo tu retiro, deberías poder correr... más rápido...",
  ui_story_1020_10200201_45_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1020_10200201_46_dialog_content = "¡Descartaste sus vidas y propósitos sin ningún remordimiento!",
  ui_story_1020_10200201_47_dialog_content = "Reinhardt obtuvo su título de Iluminación Iluminada de la recuperación en Entrañas 80. Su sacrificio condujo a una década de paz.",
  ui_story_1020_10200201_48_dialog_content = "¿No crees que valió la pena permitir que personas como tú y yo vivamos?",
  ui_story_1020_10200201_49_dialog_content = "... Respeto todo lo que el Gran Mariscal ha hecho por Illumina.",
  ui_story_1020_10200201_50_dialog_content = "Pero la determinación de descubrir por qué murieron mis compañeros es lo que me ha mantenido vivo.",
  ui_story_1020_10200201_51_dialog_content = "Todos estos años siguiéndote, debería haberme dado cuenta antes...",
  ui_story_1020_10200201_52_dialog_content = "Como Oficial de Inteligencia, mi objetivo es que más soldados sobrevivan a las batallas a través de información precisa, Gran Mariscal.",
  ui_story_1020_10200201_53_dialog_content = "Pero fue la misma información que traje la que causó que fueras asediado por los Eclipsites y perdieras a miembros clave.",
  ui_story_1020_10200201_54_dialog_content = "Acepto completamente el castigo por las consecuencias de mi informe erróneo, pero antes de eso...",
  ui_story_1020_10200201_55_dialog_content = "¡Espero que condenes al Dr. Ulysses a la ejecución!",
  ui_story_1020_10200201_56_dialog_content = "Anatoli...",
  ui_story_1020_10200201_57_dialog_content = "¡Estoy dispuesto a esperar! No importa qué, ¡debo vengar el sacrificio de mis compañeros sin falta!",
  ui_story_1020_10200201_58_dialog_content = "¡Lo juré por mi vida!",
  ui_story_1020_10200201_59_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_1020_10200201_60_dialog_content = "Reinhardt...",
  ui_story_1020_10200201_61_dialog_content = "¡Belisaria!",
  ui_story_1020_10200201_62_dialog_content = "Independientemente de dónde se encuentren las lealtades de Ulysses, ¡no condenaré a ninguno de mis gente a un destino tan cruel!",
  ui_story_1020_10200201_63_dialog_content = "¡Ahora toma tu decisión! Si te niegas... ¡entonces la tomaré por ti!",
  ui_story_1020_10200201_64_dialog_content = "Espada lista.",
  ui_story_1020_10200201_65_dialog_content = "¡Trueno rugiente!",
  ui_story_1020_10200201_66_dialog_content = "Detener-",
  ui_story_1020_10200201_67_dialog_content = "¡Suelten su arma, todos ustedes!",
  ui_story_1020_10200201_68_dialog_content = "...",
  ui_story_1020_10200201_69_dialog_content = "No voy a condenar a nadie, porque en mi opinión, cada uno de ustedes estaba tomando decisiones para la supervivencia de Illumina.",
  ui_story_1020_10200201_70_dialog_content = "Por eso apoyé los experimentos de Ulysses, así como el hecho de que el ejército pasara por encima del Comité y enviara tropas a su antojo.",
  ui_story_1020_10200201_71_dialog_content = "Pero cuando termina una partida de ajedrez, los peones deberían retomar sus lugares.",
  ui_story_1020_10200201_72_dialog_content = "¿Un peón en un tablero de ajedrez? ¿Es así como te ves a ti mismo?",
  ui_story_1020_10200201_73_dialog_content = "Hasta ahora, la Federación Illumina ha estado luchando en dos frentes separados. Mientras un ejército de Eclipsites se acerca más a la ciudad de Gannon, un cáncer ha estado propagándose y dañándonos desde dentro...",
  ui_story_1020_10200201_74_dialog_content = "¿Realmente puedes sentarte ahí y fingir que nada está pasando?",
  ui_story_1020_10200201_75_dialog_content = "Illumina no será el punto en luchar contra los Eclipsites y explorar lo desconocido letal por segunda vez.",
  ui_story_1020_10200201_76_dialog_content = "No haremos un movimiento antes que ellos.",
  ui_story_1020_10200201_77_dialog_content = "¿Qué estás diciendo?",
  ui_story_1020_10200201_78_dialog_content = "Hasta que llegue la crisis, Illumina no será el primero en cargar, mucho menos en cortar ambos brazos, incluso cuando están llenos de quistes.",
  ui_story_1020_10200201_79_dialog_content = "¿Lo entiendes?",
  ui_story_1020_10200201_80_dialog_content = "Jajaja... Máscara de Hierro, ¿no has tenido suficiente de este juego de equilibrio entre los Aurorians?",
  ui_story_1020_10200201_81_dialog_content = "¿Quieres que te diga cómo terminará eso para todos?",
  ui_story_1020_10200201_82_dialog_content = "Incluso si morimos, ¡no será porque lideramos la carga por Lumopolis!",
  ui_story_1020_10200201_83_dialog_content = "Ugh... me estás dejando sordo.",
  ui_story_1020_10200201_84_dialog_content = "¿Por qué no me cuentas qué potencial tiene Illumina para los próximos diez años?",
  ui_story_1020_10200201_X84_dialog_content = "¿Es ese prospecto de Gran Mariscal al que quieres enviar a la batalla sin importar el costo?",
  ui_story_1020_10200201_85_dialog_content = "Jejeje...",
  ui_story_1020_10200201_86_dialog_content = "Hay más de un potencial para el Programa Phospherus. La persona que puede ser el pilar de Illumina en diez años es Sean.",
  ui_story_1020_10200201_87_dialog_content = "...",
  ui_story_1020_10200201_88_dialog_content = "... ¿Yo?",
  ui_story_1020_10200301_1_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_1020_10200301_2_dialog_content = "Bool ha estado en ello desde hace un tiempo...",
  ui_story_1020_10200301_3_dialog_content = "...",
  ui_story_1020_10200301_4_dialog_content = "No creo que ella me haya escuchado...",
  ui_story_1020_10200301_5_dialog_content = "Bip—Algol puede estar en modo de espera. Guardián Uno la despertará.",
  ui_story_1020_10200301_6_dialog_content = "¿Guardián Uno? ¿Por qué trajiste... tantas cosas?",
  ui_story_1020_10200301_7_dialog_content = "Estos son dispositivos de computación que Algol suele usar. Guardian One piensa que Algol construirá el núcleo aún más rápido con su ayuda.",
  ui_story_1020_10200301_8_dialog_content = "<color=#e8d9bb>Sonido metálico-</color>",
  ui_story_1020_10200301_9_dialog_content = "¡Ah! ¡Reconozco ese sonido en cualquier lugar! Guardian One, ven aquí y ayúdame a armarlo.",
  ui_story_1020_10200301_10_dialog_content = "(¡Ella realmente se despertó!)",
  ui_story_1020_10200301_11_dialog_content = "La velocidad de operación de Algol es lenta hoy.",
  ui_story_1020_10200301_12_dialog_content = "Eso es porque esta máquina es de hace miles de años...",
  ui_story_1020_10200301_13_dialog_content = "De cierta manera, es como tu antepasado.",
  ui_story_1020_10200301_14_dialog_content = "Este antepasado no se parece en nada a mí.",
  ui_story_1020_10200301_15_dialog_content = "Bool está tardando mucho más de lo que esperaba en descifrar esa contraseña.",
  ui_story_1020_10200301_16_dialog_content = "¿Podría ser que después de tantas actualizaciones, Bool ya no esté familiarizado con las reglas del lenguaje de esos símbolos?",
  ui_story_1020_10200301_17_dialog_content = "Desde que entró en contacto con su prototipo, no ha dejado de funcionar ni un segundo. ¿Cuántos datos está procesando Bool...",
  ui_story_1020_10200301_18_dialog_content = "Algol está tan ansiosa que ha comenzado a caminar de un lado a otro.",
  ui_story_1020_10200301_19_dialog_content = "¡Por supuesto que estoy caminando de un lado a otro! ¡Estoy nervioso, después de todo!",
  ui_story_1020_10200301_20_dialog_content = "¡Si solo Bool pudiera comunicarse telepáticamente con nuestro amigo Caelestite como tú lo hiciste! Ver incluso una pequeña porción de los datos sería muy útil...",
  ui_story_1020_10200301_21_dialog_content = "¡Si hago funcionar todos estos dispositivos informáticos al mismo tiempo, nada es imposible!",
  ui_story_1020_10200301_22_dialog_content = "Es posible que no podamos usar el habla para comunicarnos, pero antes percibí algunos de los \"mensajes\" de Bool.",
  ui_story_1020_10200301_23_dialog_content = "Tal vez pueda usar mis poderes en Bool e intentar encontrar algunas pistas.",
  ui_story_1020_10200301_24_dialog_content = "Agradezco la oferta, pero deberías considerarte afortunado de que Bool no te esté atacando en este momento.",
  ui_story_1020_10200301_25_dialog_content = "... Pero dijiste que Bool es realmente bueno aprendiendo, ¿verdad? ¿Quizás confía en mí después de ese pequeño episodio de ahora?",
  ui_story_1020_10200301_26_dialog_content = "PlayerName es tan inteligente.",
  ui_story_1020_10200301_27_dialog_content = "Tiene sentido... Supongo que no tenemos nada más que hacer, así que adelante y prueba tu valía.",
  ui_story_1020_10200301_28_dialog_content = "¿Poner a prueba mi temple?",
  ui_story_1020_10200301_29_dialog_content = "Oh... ¡Por favor, sé amable, Bool!",
  ui_story_1020_10200301_30_option_content = "Enlace Telepático—",
  ui_story_1020_10200301_31_dialog_content = "...",
  ui_story_1020_10200301_32_dialog_content = "Eso fue rápido... ¿Bool te rechazó o algo así?",
  ui_story_1020_10200301_33_dialog_content = "No... ¡Simplemente había demasiada información llegando a mí muy rápido!",
  ui_story_1020_10200301_34_dialog_content = "... Entonces, ¿encontraste algo útil?",
  ui_story_1020_10200301_35_dialog_content = "Algo útil...",
  ui_story_1020_10200301_36_option_content = "Vi algunas líneas.",
  ui_story_1020_10200301_37_dialog_content = "Muchas líneas, en realidad... Como si estuvieran cayendo del cielo.",
  ui_story_1020_10200301_38_dialog_content = "Pero tal vez no eran líneas en absoluto...",
  ui_story_1020_10200301_39_dialog_content = "¡Eso es un montón de palabras que no significan nada!",
  ui_story_1020_10200301_40_dialog_content = "¡Argh! ¿Por qué no puedo ser yo el que se conecte al prototipo?",
  ui_story_1020_10200301_41_option_content = "Vi muchos números.",
  ui_story_1020_10200301_42_dialog_content = "¡Ellos también se movían tan rápido!",
  ui_story_1020_10200301_43_dialog_content = "¿Números? ¿Como ceros y unos? ¿Cuántos de ellos? ¿Estaban en algún orden en particular?",
  ui_story_1020_10200301_44_dialog_content = "Creo que había más números que esos...",
  ui_story_1020_10200301_45_dialog_content = "Pero no estoy seguro de cuántos eran o si estaban en algún tipo de secuencia...",
  ui_story_1020_10200301_46_option_content = "No pude entender nada.",
  ui_story_1020_10200301_47_dialog_content = "Todo pasó tan rápido que terminó antes de que pudiera echar un vistazo más de cerca.",
  ui_story_1020_10200301_48_dialog_content = "¡Déjame intentar de nuevo!",
  ui_story_1020_10200301_49_dialog_content = "Ahora que sé qué esperar, intentaré algo un poco diferente.",
  ui_story_1020_10200301_50_dialog_content = "No te esfuerces. Incluso yo no he descubierto completamente cómo funciona Bool.",
  ui_story_1020_10200301_51_dialog_content = "Si comienzas a sentirte incómodo, simplemente detente por ahora.",
  ui_story_1020_10200301_52_dialog_content = "Entendido.",
  ui_story_1020_10200301_53_dialog_content = "Para ser honesto, mis habilidades psíquicas se han fortalecido desde el ascenso del Obelisco del Retorno.",
  ui_story_1020_10200301_54_dialog_content = "Ahora puedo ver rápidamente a través de todo Astra desde la cima de ese obelisco, no con mis propios ojos sino con los ojos del entorno...",
  ui_story_1020_10200301_55_dialog_content = "Me suena bastante abstracto. ¿Realmente crees que puedes usar eso para ver los datos de Bool?",
  ui_story_1020_10200301_56_dialog_content = "Tal vez con los ojos del entorno...",
  ui_story_1020_10200301_57_dialog_content = "¡Pero no lo sabremos a menos que lo intente!",
  ui_story_1020_10200301_58_option_content = "Enlace Telepático—",
  ui_story_1020_10200301_59_dialog_content = "(¡T-Tan rápido!)",
  ui_story_1020_10200301_60_dialog_content = "(Necesito... seguir el ritmo...)",
  ui_story_1020_10200301_61_dialog_content = "(¡Argh! Me duelen los ojos solo de mirar—)",
  ui_story_1020_10200301_62_dialog_content = "(¡Espera! Necesito usar los ojos del entorno, no los míos...)",
  ui_story_1020_10200301_63_dialog_content = "(Primero intentaré enfocarme en una sola secuencia, y luego...)",
  ui_story_1020_10200301_64_option_content = "Alcance Telepático—",
  ui_story_1020_10200301_65_dialog_content = "(...)",
  ui_story_1020_10200301_66_dialog_content = "(Estos son números, está bien...)",
  ui_story_1020_10200301_67_dialog_content = "(01105745630112... 2311111... 0010112231...)",
  ui_story_1020_10200301_68_dialog_content = "(Si puedo transmitir estos números a Algol, tal vez ella pueda descifrar la contraseña de inmediato...)",
  ui_story_1020_10200301_69_dialog_content = "(Pero... ¿Cómo se supone que voy a recordar a todos ellos?)",
  ui_story_1020_10200301_70_dialog_content = "¡Lo vi! Cadenas de números cayendo como lluvia!",
  ui_story_1020_10200301_71_dialog_content = "¡Guau! ¿Incluye el código de trucos para pasar este nivel?",
  ui_story_1020_10200301_72_dialog_content = "No creo que sea tan fácil... Pero tal vez ese código esté escondido en algún lugar de allí.",
  ui_story_1020_10200301_73_dialog_content = "¿Eres capaz de copiar esos números mientras usas tus poderes, Caelestite?",
  ui_story_1020_10200301_74_dialog_content = "Si puedes traerme suficientes datos, podría ser capaz de usar estas computadoras para encontrar la contraseña.",
  ui_story_1020_10200301_75_dialog_content = "Ya me resultó difícil distinguir los números en esas cadenas de datos. No creo que pueda copiarlos...",
  ui_story_1020_10200301_76_dialog_content = "Además...",
  ui_story_1020_10200301_77_dialog_content = "¿Qué es?",
  ui_story_1020_10200301_78_dialog_content = "No creo que puedas memorizar tantos números de una vez...",
  ui_story_1020_10200301_79_dialog_content = "¿Confías en mí?",
  ui_story_1020_10200301_80_dialog_content = "Por supuesto que sí... Pero, ¿por qué preguntas?",
  ui_story_1020_10200301_81_dialog_content = "Tengo una corazonada...",
  ui_story_1020_10200301_82_dialog_content = "Desde el momento en que desarrolla una personalidad, la compleja y automatizada fábrica conocida como Coloso se vuelve capaz de creatividad y adaptabilidad.",
  ui_story_1020_10200301_83_dialog_content = "Nuestros cerebros también poseen ambas de estas características únicas.",
  ui_story_1020_10200301_84_dialog_content = "Sin embargo, aunque podemos adaptarnos a una variedad de escenarios complejos, este nivel de creatividad y adaptabilidad...",
  ui_story_1020_10200301_85_dialog_content = "Solo interferirán con los procesos computacionales de una máquina, obstaculizando así su eficiencia general.",
  ui_story_1020_10200301_86_dialog_content = "Así que si realmente confías en mí, simplemente apaga la creatividad y adaptabilidad de tu cerebro.",
  ui_story_1020_10200301_87_dialog_content = "¿Eh? Pero... ¿Cómo se supone que haga eso?",
  ui_story_1020_10200301_88_dialog_content = "Para decirlo simplemente, necesitas dejar de pensar como una persona y comenzar a operar como una máquina.",
  ui_story_1020_10200301_89_dialog_content = "Supongo que no lo he intentado antes...",
  ui_story_1020_10200301_90_dialog_content = "Es lo que hago cuando mi trabajo es especialmente difícil. No te preocupes, te ayudaré a memorizar tantos de esos números como sea posible.",
  ui_story_1020_10200301_91_dialog_content = "Solo concéntrate en el proceso y no te preocupes por toda la información que te llega. Cuando suficientes datos pasan por la superficie de nuestra conciencia, tienden a dejar algunas huellas.",
  ui_story_1020_10200301_92_dialog_content = "Confía en mí, una vez que estés en el estado mental correcto, todo se sentirá infinitamente más lento.",
  ui_story_1020_10200301_93_dialog_content = "Concéntrate en el proceso...",
  ui_story_1020_10200301_94_dialog_content = "Quizás me despierte después de caer al suelo...",
  ui_story_1020_10200301_95_dialog_content = "... ¿Todavía estoy en el aire?",
  ui_story_1020_10200301_96_dialog_content = "Cuando te resignas a una caída inevitable, por alguna razón el proceso se vuelve extremadamente largo...",
  ui_story_1020_10200301_97_dialog_content = "Creo que entiendo lo que estabas diciendo antes.",
  ui_story_1020_10200301_98_dialog_content = "¿Qué se te vino a la mente?",
  ui_story_1020_10200301_99_dialog_content = "No fue un accidente, para ser precisos... Bueno, de todos modos, creo que ya sé qué hacer ahora.",
  ui_story_1020_10200301_100_option_content = "Sensación—Más Profundo—",
  ui_story_1020_10200301_101_dialog_content = "Guau, los ojos de PlayerName se mueven rápido.",
  ui_story_1020_10200301_102_dialog_content = "¡Qué maravilloso es PlayerName! Tengo curiosidad por saber qué hay en esa cabeza.",
  ui_story_1020_10200301_103_dialog_content = "Por la presente, reclamo a este Caelestite como mi asistente personal de investigación. ¡Una vez que todo esto termine, incluso le haré un traje!",
  ui_story_1020_10200301_104_dialog_content = "Algol quiere hacerse amigo de Caelestite.",
  ui_story_1020_10200301_105_dialog_content = "No será como la ropa que lleva puesta ahora. No, será más como tu caparazón exterior.",
  ui_story_1020_10200301_106_dialog_content = "Bip—",
  ui_story_1020_10200301_107_dialog_content = "11101100...",
  ui_story_1020_10200301_108_dialog_content = "¡Hay!",
  ui_story_1020_10200301_109_dialog_content = "¿Código binario?",
  ui_story_1020_10200301_110_dialog_content = "010221111, 022211110101...",
  ui_story_1020_10200301_111_dialog_content = "... ¿O quizás no?",
  ui_story_1020_10200301_112_dialog_content = "Guardian One, graba su voz para que no nos perdamos nada.",
  ui_story_1020_10200301_113_dialog_content = "Bip. Guardián Uno entiende.",
  ui_story_1020_10200301_114_dialog_content = "Gronru, Vivian y Migard, ¡también pónganse en esas computadoras! Concéntrate y apóyate con Lumina.",
  ui_story_1020_10200301_115_dialog_content = "¡Está bien!",
  ui_story_1020_10200301_116_dialog_content = "0101157567565500101... 100150115332234560101...",
  ui_story_1020_10200301_117_dialog_content = "(Número cinco... número seis... siete, ocho, nueve...)",
  ui_story_1020_10200301_118_dialog_content = "(¿Cuánto más hay?)",
  ui_story_1020_10200301_119_dialog_content = "(Espera... ¿Estoy viendo cosas? ¿Por qué siento que... algo está parpadeando...)",
  ui_story_1020_10200301_120_dialog_content = "(Oh no... Empiezo a pensar de nuevo...)",
  ui_story_1020_10200301_121_dialog_content = "(¡Argh! Todo es tan rápido... ¡Apenas puedo seguir el ritmo!)",
  ui_story_1020_10200401_1_dialog_content = "¿Qué estás diciendo exactamente, Dr. Ulysses?",
  ui_story_1020_10200401_2_dialog_content = "Tú, Yingel, y Axelia. Los tres son productos del Programa Phospherus.",
  ui_story_1020_10200401_3_dialog_content = "...",
  ui_story_1020_10200401_4_dialog_content = "...",
  ui_story_1020_10200401_5_dialog_content = "Un producto de Phospherus debería ser inteligente como Yingel o una poderosa máquina de golpear Eclipsites como Axelia.",
  ui_story_1020_10200401_6_dialog_content = "Yo no...",
  ui_story_1020_10200401_7_dialog_content = "Eres más poderoso de lo que crees, Sean.",
  ui_story_1020_10200401_8_dialog_content = "Poderoso... Es la primera vez que me asocian con esa palabra.",
  ui_story_1020_10200401_9_dialog_content = "¡Toma esto, Axelia! ¡Ja!",
  ui_story_1020_10200401_10_dialog_content = "¡Ay!",
  ui_story_1020_10200401_11_dialog_content = "...",
  ui_story_1020_10200401_12_dialog_content = "Incluso me lastimaría golpeando a Axelia... Realmente poderoso...",
  ui_story_1020_10200401_13_dialog_content = "¿Nuevo recluta? ¡Más bien un niño! ¡Oye! Crepúsculo no es un lugar para ti!",
  ui_story_1020_10200401_14_dialog_content = "...",
  ui_story_1020_10200401_15_dialog_content = "¿Qué hiciste en Gannon City antes de venir aquí? ¿Por qué ni siquiera puedes eliminar a Eclipsites como estos?",
  ui_story_1020_10200401_16_dialog_content = "...",
  ui_story_1020_10200401_17_dialog_content = "No es mi lugar decir esto, pero afinémonos todos bajo condiciones difíciles, Sean.",
  ui_story_1020_10200401_18_dialog_content = "Trabajaré en ello, señor...",
  ui_story_1020_10200401_19_dialog_content = "Cuanto más fuerte es el poder, mayor es la responsabilidad. No es mi culpa que sea más fuerte que Sean, ¡jajaja! ¿No es así?",
  ui_story_1020_10200401_20_dialog_content = "Pero... soy responsable de esta área.",
  ui_story_1020_10200401_21_dialog_content = "Está bien. Le diré al líder del escuadrón que los Eclipsites en esta área son demasiado fuertes.",
  ui_story_1020_10200401_22_dialog_content = "...",
  ui_story_1020_10200401_23_dialog_content = "¡Corre más rápido, Sean! ¡Solo un poco más rápido!",
  ui_story_1020_10200401_24_dialog_content = "... Sí... ¡Sí, señor!",
  ui_story_1020_10200401_25_dialog_content = "El profesor Ulysses dijo que soy tan poderoso como Yingel y Axelia.",
  ui_story_1020_10200401_26_dialog_content = "Pero, ¿por qué soy el único con manos...?",
  ui_story_1020_10200401_27_dialog_content = "... ¿cubierto de callos?",
  ui_story_1020_10200401_28_dialog_content = "Son marcas de mi entrenamiento... No importa cómo lo veas, solo las verás en un tipo inútil como yo.",
  ui_story_1020_10200401_29_dialog_content = "No solo en las manos, tengo cicatrices de entrenamiento casi en todas partes...",
  ui_story_1020_10200401_30_dialog_content = "¿No entrené lo suficiente?",
  ui_story_1020_10200401_31_dialog_content = "Sean...",
  ui_story_1020_10200401_32_dialog_content = "Solo te enviaron a Crepúsculo porque te consideraron un fracaso en las primeras etapas.",
  ui_story_1020_10200401_33_dialog_content = "Sin embargo, los errores de juicio son inevitables en la fase inicial de cualquier experimento.",
  ui_story_1020_10200401_34_dialog_content = "Un fracaso...",
  ui_story_1020_10200401_35_dialog_content = "Así que estaba en Crepúsculo porque era un fracaso... Jaja...",
  ui_story_1020_10200401_36_dialog_content = "Esto no fue tu culpa, Sean. No escuches nada de lo que dice Ulysses.",
  ui_story_1020_10200401_37_dialog_content = "Todos nosotros somos un fracaso en el programa.",
  ui_story_1020_10200401_38_dialog_content = "Gracias por intentar consolarme, Gran Mariscal, pero sé que al final, no soy como ninguno de ustedes...",
  ui_story_1020_10200401_39_dialog_content = "Pregúntale cómo el fracaso de Crepúsculo se convertirá en el potencial futuro de Illumina.",
  ui_story_1020_10200401_40_dialog_content = "Llega al grano, Ulysses.",
  ui_story_1020_10200401_41_dialog_content = "Bueno, tú eres el juez, Máscara de Hierro...",
  ui_story_1020_10200401_42_dialog_content = "Abandonamos nuestro estudio sobre Sean, pero su cuerpo experimentó cambios cuando estuvo más cerca de la Zona Oscura en Crepúsculo.",
  ui_story_1020_10200401_43_dialog_content = "Después de repetidas verificaciones, descubrí que las Luminatics de Sean no estaban limitadas por defectos genéticos. Justo lo contrario, él podía absorber Darkflow.",
  ui_story_1020_10200401_44_dialog_content = "No podía convertir la energía en Lumina, pero le proporcionaba una fuerte inmunidad natural al luchar contra los Eclipsites.",
  ui_story_1020_10200401_45_dialog_content = "De hecho, es un rasgo similar compartido por aquellos en la expedición liderada por Pepita a la Zona Oscura.",
  ui_story_1020_10200401_46_dialog_content = "¡No entraré en jerga, pero ellos son la esperanza de los Aurorianos para derrotar a los Eclipsites!",
  ui_story_1020_10200401_47_dialog_content = "He finalizado el plan para mejoras físicas. Creo que un nuevo lote de mis creaciones estará listo para la Zona Oscura muy pronto.",
  ui_story_1020_10200401_48_dialog_content = "¿Es esto algún tipo de broma, Ulysses? ¿Por qué la Federación Illumina te permitiría continuar con estas tonterías?",
  ui_story_1020_10200401_49_dialog_content = "Sean! Debo decirte, Sean—",
  ui_story_1020_10200401_50_dialog_content = "Quizás descubriste por los archivos que los soldados de Illumina te rescataron de los Eclipsites y te enviaron al orfanato como un huérfano.",
  ui_story_1020_10200401_51_dialog_content = "¡Pero los que te llevaron a los Eclipsites para morir no fueron otros que tus propios padres!",
  ui_story_1020_10200401_52_dialog_content = "No querían que vivieras y sufrieras de los mismos defectos físicos que ellos tenían.",
  ui_story_1020_10200401_53_dialog_content = "Pero gracias al Programa Phospherus, ya no sufrirías más.",
  ui_story_1020_10200401_54_dialog_content = "Modifiqué tu cuerpo y te di una nueva oportunidad en la vida. Si quieres ser reconocido como poderoso, debes—",
  ui_story_1020_10200401_55_dialog_content = "¿Qué estás haciendo, profesor Ulysses?",
  ui_story_1020_10200401_56_dialog_content = "Prométeme que te adentrarás en la Zona Oscura y erradicarás a los Eclipsites.",
  ui_story_1020_10200401_57_dialog_content = "En comparación con ser un peón insignificante en Crepúsculo, es mejor maximizar tu potencial genético y ser un héroe auroriano que lucha contra el Eclipse en su propio terreno!",
  ui_story_1020_10200401_58_dialog_content = "Entonces... Podrás ver al demonio que ha estado escondiéndose detrás de la escena...",
  ui_story_1020_10200401_59_dialog_content = "¡Detente, Ulysses!",
  ui_story_1020_10200401_60_dialog_content = "¡Mantente alejado de Sean, Profesor!",
  ui_story_1020_10200401_61_dialog_content = "Estabas dispuesto a sacrificar a cualquiera en tu experimento, solo para afirmar que fuiste tú quien salvó a Sean.",
  ui_story_1020_10200401_62_dialog_content = "¡Tu crueldad y egoísmo me están disgustando!",
  ui_story_1020_10200401_63_dialog_content = "¡Nadie puede abandonarlo, quitarle la vida, o incluso dictar cómo debería vivir ahora!",
  ui_story_1020_10200401_64_dialog_content = "¡Nadie puede abandonarlo, quitarle la vida, o incluso dictar cómo debería vivir!",
  ui_story_1020_10200401_65_dialog_content = "Bueno, no creo que tengas que rodearme como una manta, Yingel, Axelia...",
  ui_story_1020_10200401_66_dialog_content = "El profesor Ulysses dijo que fueron mis padres quienes me llevaron a los Eclipsites.",
  ui_story_1020_10200401_67_dialog_content = "Siempre me he estado diciendo a mí mismo que no era más que un sueño...",
  ui_story_1020_10200401_68_dialog_content = "Pero, ¿cómo podría ser un simple sueño una experiencia tan inolvidable?",
  ui_story_1020_10200401_69_dialog_content = "Aun así, elegí interpretarlo como mis padres sacrificándose para salvarme.",
  ui_story_1020_10200401_70_dialog_content = "Fue tonto, lo sé, pero esa era la única manera de engañarme a mí mismo para vivir, ¿verdad?",
  ui_story_1020_10200401_71_dialog_content = "Lo que pasó en ese entonces ya no importa, Sean.",
  ui_story_1020_10200401_72_dialog_content = "Eres un buen Crepúsculo, no, ¡guerrero de Illumina!",
  ui_story_1020_10200401_73_dialog_content = "Como yo, ahora eres un soldado de Illumina capaz de matar a innumerables Eclipsites.",
  ui_story_1020_10200401_74_dialog_content = "Probablemente sea egoísta decir esto, pero creo que no tienes que ser un guerrero o un héroe.",
  ui_story_1020_10200401_75_dialog_content = "Solo sé Sean.",
  ui_story_1020_10200401_76_dialog_content = "¡Jajajaja! ¿Así que quieres repetir la derrota en esa guerra antigua?",
  ui_story_1020_10200401_77_dialog_content = "Este mundo no es tan simple... Presencié cuán poderoso es el Eclipse. Sé que esta es la única oportunidad para los Aurorianos.",
  ui_story_1020_10200401_78_dialog_content = "¡Sacrificaste a tu propia gente en nombre de la ciencia! ¡Tus acciones solo destruirán tanto a la Federación Illumina como a todos los aurorianos!",
  ui_story_1020_10200401_79_dialog_content = "¡Una máquina de guerra no está capacitada para debatir conmigo sobre sacrificios y destrucciones!",
  ui_story_1020_10200401_80_dialog_content = "Realmente envidio a Forsakin por ofrecer una teoría sobre la misteriosa fuerza oculta tanto en Lumina como en Darkflow a tan temprana edad, y luego seguir adelante con ella.",
  ui_story_1020_10200401_81_dialog_content = "Tú, por otro lado, prefieres depositar fe en tus sentimientos y detenerte en vidas insignificantes...",
  ui_story_1020_10200401_82_dialog_content = "Son tus emociones las que retienen a los Aurorians...",
  ui_story_1020_10200401_83_dialog_content = "Es tu tontería la que causó más sacrificios...",
  ui_story_1020_10200401_84_dialog_content = "Le dijiste a los Aurorianos que temieran a la muerte, sumiéndolos en una aburrida espera de sus destinos condenados...",
  ui_story_1020_10200401_85_dialog_content = "Yo, sin embargo, no seré un esclavo de las emociones...",
  ui_story_1020_10200401_86_dialog_content = "¡Nunca!",
  ui_story_1020_10200401_87_dialog_content = "Me acostumbraré...",
  ui_story_1020_10200401_88_dialog_content = "¡Acostúmbrate a que los Aurorianos mueran cada segundo! ¡Por docenas, cientos, miles!",
  ui_story_1020_10200401_89_dialog_content = "¡Pisaré sobre todos sus cuerpos podridos para crear Aurorianos poderosos tanto en cuerpo como en mente!",
  ui_story_1020_10200401_90_dialog_content = "Creo que has oído hablar de la evolución. Bueno, los Aurorianos deben evolucionar.",
  ui_story_1020_10200401_91_dialog_content = "Cada minuto, cada segundo...",
  ui_story_1020_10200401_92_dialog_content = "Esa es la única forma de sobrevivir al día del juicio final, con nuestros horizontes ampliados y cuerpos poderosos...",
  ui_story_1020_10200401_93_dialog_content = "Para ascender...",
  ui_story_1020_10200401_94_dialog_content = "¿Está bien, señor?",
  ui_story_1020_10200401_95_dialog_content = "Evolución... Qué término maravilloso.",
  ui_story_1020_10200401_96_dialog_content = "Cada minuto, cada segundo...",
  ui_story_1020_10200401_97_dialog_content = "¡Oficial Ulysses!",
  ui_story_1020_10200401_98_dialog_content = "¿Está loco?",
  ui_story_1020_10200401_99_dialog_content = "Si no lo hubiera visto por mí mismo... No lo habría creído...",
  ui_story_1020_10200401_100_dialog_content = "¿Qué le pasó a él?",
  ui_story_1020_10200401_101_dialog_content = "Por eso estoy decidida a convocar a Chandra, mi testigo.",
  ui_story_1020_10200401_102_dialog_content = "He estado con él todo el tiempo, Gran Mariscal.",
  ui_story_1020_10200401_103_dialog_content = "Haz que las acciones de Ulysses sean conocidas por todos.",
  ui_story_1020_10200401_104_dialog_content = "Sí, Gran Mariscal. Cuando el Dr. Ulysses estaba en terapia, ocasionalmente miraba hacia la distancia de esta manera...",
  ui_story_1020_10200401_105_dialog_content = "Solo para luego actuar como si nada hubiera pasado al siguiente momento.",
  ui_story_1020_10200401_106_dialog_content = "...",
  ui_story_1020_10200401_107_dialog_content = "Continúa, Testigo Chandra.",
  ui_story_1020_10200401_108_dialog_content = "El profesor Ulysses comenzó la psicoterapia hace diez años. Aquí está su historial médico.",
  ui_story_1020_10200401_109_dialog_content = "No estaba involucrado en ese momento, pero como puedes ver en el archivo, fue cuando los Eclipsites comenzaron a infiltrarse en varias facciones.",
  ui_story_1020_10200401_110_dialog_content = "Y varios meses antes del ejercicio militar, el profesor Ulysses aumentó sus sesiones de terapia una vez más.",
  ui_story_1020_10200401_111_dialog_content = "Después, Forsakin se infiltró en el Laboratorio X y los Wraiths se llevaron el núcleo de Guardian One de Gannon.",
  ui_story_1020_10200401_112_dialog_content = "El Dr. Ulysses estuvo involucrado en ambos incidentes clave. Por lo tanto, sospechamos que podría haber una comunicación especial entre él y el Eclipse.",
  ui_story_1020_10200401_113_dialog_content = "...",
  ui_story_1020_10200401_114_dialog_content = "Lo que llamó mi atención fueron algunas de las cosas extrañas que Ulysses mencionó durante sus sesiones de tratamiento...",
  ui_story_1020_10200401_115_dialog_content = "Las columnas de hielo no son agua de lluvia condensada, sino más bien rocas que se elevan...",
  ui_story_1020_10200401_116_dialog_content = "La unidad de conducción está agotada y desconectada, pero el único ojo sigue observando desde arriba...",
  ui_story_1020_10200401_117_dialog_content = "Pilares de hielo emergiendo, unidad impulsada... y un ojo vigilante en el cielo...",
  ui_story_1020_10200401_118_dialog_content = "Esto no suena a nada en Astra. ¿Cómo podría alguien como él, que nunca ha salido de Gannon City, saber sobre esto?",
  ui_story_1020_10200401_119_dialog_content = "¡Esto difícilmente puede ser una coincidencia! Estoy seguro de que tú también tienes tus sospechas, Belisaria!",
  ui_story_1020_10200401_120_dialog_content = "¿Cómo puede ella estar tan segura?",
  ui_story_1020_10200401_121_dialog_content = "¿Prueba?",
  ui_story_1020_10200401_122_dialog_content = "¡Porque está escrito en las memorias de Helios, un ex soldado que se aventuró en la Zona Oscura y se convirtió en un Eclipsite!",
  ui_story_1020_10200401_123_dialog_content = "El Comité me ha estado negando la oportunidad de probar mis sospechas porque él aún no ha recuperado la conciencia.",
  ui_story_1020_10200401_124_dialog_content = "Pero si su testimonio coincide con mis acusaciones contra Ulysses, ¿cómo lo explicarás de otra manera?",
  ui_story_1020_10200401_125_dialog_content = "Tengo una idea. ¿Y tú?",
  ui_story_1020_10200401_126_dialog_content = "¿Ese Fantasma?",
  ui_story_1020_10200401_127_dialog_content = "Así que a eso se refería...",
  ui_story_1020_10200401_128_dialog_content = "...",
  ui_story_1020_10200401_129_dialog_content = "No hay necesidad de perder tanto tiempo conmigo.",
  ui_story_1020_10200401_130_dialog_content = "Cuando él llegue, aquellos sin anillos serán dejados para arrastrarse en el suelo y morir en su miedo e insignificancia.",
  ui_story_1020_10200401_131_dialog_content = "¿Qué anillos?",
  ui_story_1020_10200401_132_dialog_content = "¡Miserable ladrón! ¡Parásito! Codicias sus anillos, ¿no es así?",
  ui_story_1020_10200401_133_dialog_content = "Hace seiscientos años, esa ciudad flotante era mi pedestal para la ascensión, ¡que estaba destinada a llevarme a alturas aún mayores!",
  ui_story_1020_10200401_134_dialog_content = "¿Ciudad flotante... Lumopolis?",
  ui_story_1020_10200401_135_dialog_content = "Pero cuando llegue, ascenderé a la gloria una vez más. Regresaré a su palacio y a su amoroso abrazo.",
  ui_story_1020_10200401_136_dialog_content = "¿Por qué ves a los Aurorianos como tus enemigos?",
  ui_story_1020_10200401_137_dialog_content = "¡Por tu codicia sin límites, por supuesto! ¡Los Aurorians desean robar sus creaciones y llamarlas suyas!",
  ui_story_1020_10200401_138_dialog_content = "¡Pero pronto, él tomará todo de vuelta!",
  ui_story_1020_10200401_139_dialog_content = "¡Tsk, tsk, tsk!",
  ui_story_1020_10200401_140_dialog_content = "...",
  ui_story_1020_10200401_141_dialog_content = "La raíz de todo esto es esa antigua máquina de la era anterior a la fundación de Illumina...",
  ui_story_1020_10200401_142_dialog_content = "¿Es este el destino de Illumina? Jeje...",
  ui_story_1020_10200401_143_dialog_content = "¿Dónde está ese dispositivo?",
  ui_story_1020_10200401_144_dialog_content = "En un almacén, siendo vigilado por ese genio que tanto te gusta.",
  ui_story_1020_10200401_145_dialog_content = "Evolución... Qué término maravilloso.",
  ui_story_1020_10200401_146_dialog_content = "Cada minuto, cada segundo...",
  ui_story_1020_10200401_147_dialog_content = "...",
  ui_story_1020_10200501_1_dialog_content = "... ¿Son todos estos?",
  ui_story_1020_10200501_2_dialog_content = "Todo revisado, sin errores ni omisiones. ¿Cree que falta algo, Dr. Algol?",
  ui_story_1020_10200501_3_dialog_content = "Esperaba muchos más números. La secuencia también es cíclica... Tal vez sea un conjunto finito de caracteres.",
  ui_story_1020_10200501_4_dialog_content = "Además, el primer lenguaje de computadora provino del Sistema Guardián. Independientemente de su desarrollo a lo largo de los años, las reglas que rigen su lenguaje deberían seguir intactas.",
  ui_story_1020_10200501_5_dialog_content = "Mi programa puede analizar estos datos y determinar la lógica detrás de su agrupación.",
  ui_story_1020_10200501_6_dialog_content = "¡Pronto, podré usar estas computadoras para acceder a todo el \"Sistema Guardián\", junto con Bool! ¡En cualquier momento ahora!",
  ui_story_1020_10200501_7_dialog_content = "Pero, si es un conjunto finito, ¿cómo es que PlayerName todavía está vinculado? ¿Está bien?",
  ui_story_1020_10200501_8_dialog_content = "Oye, su pelo está de punta... Eso me parece familiar, pero no puedo recordar exactamente qué es.",
  ui_story_1020_10200501_9_dialog_content = "Casi allí... Casi allí...",
  ui_story_1020_10200501_10_dialog_content = "¡Booo!",
  ui_story_1020_10200501_11_dialog_content = "¡Hecho!",
  ui_story_1020_10200501_12_dialog_content = "Ahora solo necesito ingresar estos en el orden correcto...",
  ui_story_1020_10200501_13_dialog_content = "<color=#e8d9bb>Bip-bip-bip-</color>",
  ui_story_1020_10200501_14_dialog_content = "... No es bueno, ¿eh?",
  ui_story_1020_10200501_15_dialog_content = "¡Ahora recuerdo! Es Bool. ¡Su cabello ahora se ve exactamente como los tentáculos de Bool!",
  ui_story_1020_10200501_16_dialog_content = "¿Quizás la cabeza de PlayerName es una supercomputadora como Bool?",
  ui_story_1020_10200501_17_dialog_content = "Me preocupa que algo pueda estar mal con PlayerName, Dr. Algol!",
  ui_story_1020_10200501_18_dialog_content = "... Incluso si tiene las habilidades psíquicas más poderosas del mundo, eso no lo convierte en una computadora...",
  ui_story_1020_10200501_19_dialog_content = "Simplemente despertémoslo—",
  ui_story_1020_10200501_20_dialog_content = "85... X... 32875... X...",
  ui_story_1020_10200501_21_dialog_content = "¿Ah?",
  ui_story_1020_10200501_22_dialog_content = "¿De qué está murmurando él?",
  ui_story_1020_10200501_23_dialog_content = "... \"X\"?",
  ui_story_1020_10200501_24_dialog_content = "¿No solo números?",
  ui_story_1020_10200501_25_dialog_content = "3292... X... 4782... X... 2212323293845...",
  ui_story_1020_10200501_26_dialog_content = "¡Su cara se ha puesto roja como un tomate!",
  ui_story_1020_10200501_27_dialog_content = "... 12983289... X...",
  ui_story_1020_10200501_28_dialog_content = "50227833... X...",
  ui_story_1020_10200501_29_dialog_content = "Este tipo realmente está manteniendo el ritmo con la velocidad de cálculo de Bool... Estará en grave peligro si esto continúa...",
  ui_story_1020_10200501_30_dialog_content = "... Pero si lo detenemos ahora, será aún más difícil obtener esta información de nuevo...",
  ui_story_1020_10200501_31_dialog_content = "¡Aquí! Pondré mi pulsera en él y le daré dos minutos más.",
  ui_story_1020_10200501_32_dialog_content = "... ¿Qué va a hacer eso?",
  ui_story_1020_10200501_33_dialog_content = "Dos minutos es el tiempo más largo que las células cerebrales de una persona pueden sostener operaciones de alta velocidad, y esta pulsera puede monitorear de cerca la salud del portador.",
  ui_story_1020_10200501_34_dialog_content = "Si los datos comienzan a sobrecargar su mente, la pulsera nos advertirá.",
  ui_story_1020_10200501_35_dialog_content = "Antes de que eso suceda, necesitaré ayuda para registrar más datos. Gronru, Guardián Uno, tenemos que recopilar tanta información útil como sea posible en los próximos dos minutos.",
  ui_story_1020_10200501_36_dialog_content = "Incluso una parte de ello funcionará. ¡Esta puede ser nuestra única oportunidad para acceder a los archivos de memoria más seguros del prototipo!",
  ui_story_1020_10200501_37_dialog_content = "¡No hay problema!",
  ui_story_1020_10200501_38_dialog_content = "Guardian One entiende.",
  ui_story_1020_10200501_39_dialog_content = "Mantén un ojo en el reloj, Vivian. Avísanos cuando pasen los dos minutos, y pararemos.",
  ui_story_1020_10200501_40_dialog_content = "Seguro.",
  ui_story_1020_10200501_41_dialog_content = "Migard, si la pulsera emite una advertencia dentro de esos dos minutos, recoge a PlayerName y sácalo de aquí.",
  ui_story_1020_10200501_42_dialog_content = "¡Lo tengo!",
  ui_story_1020_10200501_43_dialog_content = "862033934... X...",
  ui_story_1020_10200501_44_dialog_content = "385782493666... X...",
  ui_story_1020_10200501_45_dialog_content = "Bip, bip, bip, bip, bip...",
  ui_story_1020_10200501_46_dialog_content = "236758423423... X...",
  ui_story_1020_10200501_47_dialog_content = "(\"X\"?)",
  ui_story_1020_10200501_48_dialog_content = "(¿Ese personaje brillante es una \"X\"?)",
  ui_story_1020_10200501_49_dialog_content = "(Argh... Probablemente ha pasado mucho tiempo ya...)",
  ui_story_1020_10200501_50_dialog_content = "(¡Parece que mi cabeza no duele tanto como antes!)",
  ui_story_1020_10200501_51_dialog_content = "(¿Pero qué pasa con esta \"X\"?)",
  ui_story_1020_10200501_52_dialog_content = "(Ahhh... Está acelerando de nuevo...)",
  ui_story_1020_10200502_1_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10200502_2_dialog_content = "Exactamente dos minutos.",
  ui_story_1020_10200502_3_dialog_content = "¡Excelente!",
  ui_story_1020_10200502_4_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10200502_5_dialog_content = "¡Vale, vale... Desacelera un poco!",
  ui_story_1020_10200502_6_dialog_content = "Ahora bien, usemos estas computadoras para analizar los datos que acabamos de recibir. Estoy seguro de que funcionará esta vez.",
  ui_story_1020_10200502_7_dialog_content = "¡Bu!",
  ui_story_1020_10200502_8_dialog_content = "Argh-",
  ui_story_1020_10200502_9_dialog_content = "¿Estás bien, PlayerName?",
  ui_story_1020_10200502_10_dialog_content = "¡Vaya, hablamos de alta presión arterial! Y tu saturación de oxígeno en el pulso... ¿Puedes vernos claramente?",
  ui_story_1020_10200502_11_dialog_content = "S-Sí, te veo...",
  ui_story_1020_10200502_12_dialog_content = "Siéntate y no te muevas. Sigue mi dedo con tus ojos.",
  ui_story_1020_10200502_13_dialog_content = "Izquierda derecha...",
  ui_story_1020_10200502_14_dialog_content = "¿Cómo te sientes ahora?",
  ui_story_1020_10200502_15_dialog_content = "Mi cabeza... Se siente un poco mareada... Y mis extremidades se sienten realmente débiles...",
  ui_story_1020_10200502_16_dialog_content = "¿Algún problema de náuseas o visión?",
  ui_story_1020_10200502_17_dialog_content = "No se me ocurre ninguna...",
  ui_story_1020_10200502_18_dialog_content = "Aquí, bebe esto.",
  ui_story_1020_10200502_19_dialog_content = "¿Qué es?",
  ui_story_1020_10200502_20_dialog_content = "Una actividad cerebral intensa como esa suele ir seguida de síntomas de hipoxia. Créeme, soy algo así como un experto en esto.",
  ui_story_1020_10200502_21_dialog_content = "Aun así, no tenía idea de que pudieras usar tus habilidades psíquicas hasta este punto. ¡Realmente me ayudaste justo ahora!",
  ui_story_1020_10200502_22_dialog_content = "No sabía que yo también pudiera... Al principio, los números se movían tan rápido que apenas podía leer una sola cadena claramente.",
  ui_story_1020_10200502_23_dialog_content = "Pero cuando dejé de intentar concentrarme en la secuencia y, tal como tú dijiste, dejé de pensar... De repente, los números comenzaron a fluir de manera más natural...",
  ui_story_1020_10200502_24_dialog_content = "En un momento, incluso me detuve para pensar por un instante...",
  ui_story_1020_10200502_25_dialog_content = "\"Pero tan pronto como lo hice, los números se aceleraron de nuevo...",
  ui_story_1020_10200502_26_dialog_content = "Rápido... Despacio... Luego pensando... La velocidad fue afectada por el pensamiento... Una curva de aprendizaje completamente receptiva...",
  ui_story_1020_10200502_27_dialog_content = "Espera, pero ¿no dijiste que habías renunciado a pensar por completo? ¿Cómo pudiste ver los números tan claramente? ¿Qué eres exactamente?",
  ui_story_1020_10200502_28_dialog_content = "¿Estás seguro... No eres algún tipo de inteligencia artificial o algo así, verdad?",
  ui_story_1020_10200502_29_dialog_content = "¿D-De verdad tienes que preguntar?",
  ui_story_1020_10200502_30_dialog_content = "De todos modos, recuerdo haber visto una \"X\" mientras estaba allí. ¿Qué significa eso?",
  ui_story_1020_10200502_31_dialog_content = "No estoy recordando las cosas incorrectamente... ¿verdad?",
  ui_story_1020_10200502_32_dialog_content = "No, tú no eres...",
  ui_story_1020_10200502_33_dialog_content = "Pero desafortunadamente... solo Bool, otra parte de ese antiguo dispositivo, sabría qué hacer con esa información...",
  ui_story_1020_10200502_34_dialog_content = "Algol también se siente impotente.",
  ui_story_1020_10200502_35_dialog_content = "Qué sensación tan extraña... ser dejado en el polvo por alguna tecnología que fue creada mucho antes de nuestro tiempo...",
  ui_story_1020_10200502_36_dialog_content = "¿Esta máquina fue construida por alguna persona, o fue obra de un dios? ¡Jajajaja!",
  ui_story_1020_10200502_37_dialog_content = "...",
  ui_story_1020_10200502_38_dialog_content = "¡La Federación Illumina ha estado atascada usando computadoras basadas en binario durante los últimos seiscientos años!",
  ui_story_1020_10200502_39_dialog_content = "Desde cálculos matemáticos hasta la medición de materia en un estado estable, siempre hemos creído que el sistema binario es la solución óptima para todas nuestras necesidades computacionales.",
  ui_story_1020_10200502_40_dialog_content = "Pero esta máquina... ¡Su lenguaje de computación más básico utiliza caracteres distintos de ceros y unos! Podría ser un lenguaje ternario o incluso uno cuaternario...",
  ui_story_1020_10200502_41_dialog_content = "¿Y qué pasa con esa \"X\"? Ni siquiera puedo comprender la ciencia detrás de esto... ¡Una \"X\"!",
  ui_story_1020_10200502_42_dialog_content = "Casi parece que se está burlando de mí, ¿no crees? ¡Jajajaja!",
  ui_story_1020_10200502_43_dialog_content = "¿Cómo llegó a ser? ¿Qué tan compleja es la lógica que procesa?",
  ui_story_1020_10200502_44_dialog_content = "¿Y qué demonios le pasó a esta antigua civilización?",
  ui_story_1020_10200502_45_dialog_content = "¿Por qué no queda nada de ello aparte de los Caelestites, Aurorianos y Eclipsites?",
  ui_story_1020_10200502_46_dialog_content = "¡Oh! Casi lo olvido... ¡También está el Dios de la Luz! ¡Y el Señor de la Verdad también! ¿Podría la Bloody Bible estar ocultando las respuestas?",
  ui_story_1020_10200502_47_dialog_content = "Jejeje... Jajajaja...",
  ui_story_1020_10200502_48_dialog_content = "¿Qué le está pasando? Esto se está volviendo muy espeluznante...",
  ui_story_1020_10200502_49_dialog_content = "Algol se da cuenta de que es un poco inútil.",
  ui_story_1020_10200502_50_dialog_content = "¿Inútil? ¡No me hagas reír! Ya estoy haciendo suficiente de eso por mi cuenta...",
  ui_story_1020_10200502_51_dialog_content = "¡Jajajaja!",
  ui_story_1020_10200502_52_dialog_content = "¡Guardián Uno! No me importa si es un dios vengativo o algún espíritu maligno!",
  ui_story_1020_10200502_53_dialog_content = "¡A este mundo no le importa quién llega primero, y me niego a dejar mi incertidumbre en manos de los muertos!",
  ui_story_1020_10200502_54_dialog_content = "Puede que no pueda desentrañar sus misterios ahora mismo, pero eso no me impedirá investigar y desarrollar el Sistema Guardian.",
  ui_story_1020_10200502_55_dialog_content = "¿Me escuchas?",
  ui_story_1020_10200502_56_dialog_content = "Guardian One entiende en todos los sentidos de la palabra.",
  ui_story_1020_10200502_57_dialog_content = "¡Booo!",
  ui_story_1020_10200502_58_dialog_content = "¡Bien! Todo depende de ti ahora, ¡Bool!",
  ui_story_1020_10200502_59_dialog_content = "... Boo...",
  ui_story_1020_10200502_60_dialog_content = "Por fin ha llegado el momento...",
  ui_story_1020_10200502_61_dialog_content = "¡Vamos a la guarida del jefe!",
  ui_story_1020_10200502_62_dialog_content = "...",
  ui_story_1020_10200502_63_dialog_content = "¿Qué es esto?",
  ui_story_1020_10200502_64_dialog_content = "Celestita.",
  ui_story_1020_10200502_65_dialog_content = "...",
  ui_story_1020_10200502_66_dialog_content = "Esa luz intermitente en mi mente... ¿No fue un sueño?",
  ui_story_1020_10200502_67_dialog_content = "El sol negro que vi... ¿Está de alguna manera conectado con el prototipo?",
  ui_story_1020_10200601_1_dialog_content = "Mencionaste que el anillo estaba en tu sueño...",
  ui_story_1020_10200601_2_dialog_content = "¿También viste a Wraith y a Vice?",
  ui_story_1020_10200601_3_dialog_content = "Sí...",
  ui_story_1020_10200601_4_dialog_content = "¿El Eclipse construyó el prototipo de Ulysses? ¿Crees que hay una conexión entre todo esto, Dr. Algol?",
  ui_story_1020_10200601_5_dialog_content = "¡Por supuesto que lo hay... Jajajajajaja!",
  ui_story_1020_10200601_6_dialog_content = "...",
  ui_story_1020_10200601_7_dialog_content = "... ¿Por qué todos ustedes tienen esa mirada en sus caras?",
  ui_story_1020_10200601_8_dialog_content = "Pero esta es la tecnología muy antigua en la que Illumina ha estado confiando para su supervivencia desde su fundación...",
  ui_story_1020_10200601_9_dialog_content = "¿No sería una amenaza peligrosa si fue creado por el Eclipse?",
  ui_story_1020_10200601_10_dialog_content = "Celestita.",
  ui_story_1020_10200601_11_dialog_content = "(Ahí está de nuevo...)",
  ui_story_1020_10200601_12_dialog_content = "Al menos, mis escaneos no han encontrado ninguna diferencia entre él y mi simulador.",
  ui_story_1020_10200601_13_dialog_content = "Si se alojan más súper soldados en otra ubicación, me temo que el prototipo no tendrá ningún registro de ello.",
  ui_story_1020_10200601_14_dialog_content = "Parece haber alguna conexión entre las marcas en el prototipo y el sueño de PlayerName. La trama se complica...",
  ui_story_1020_10200601_15_dialog_content = "Por el contrario, creo que es cada vez más fácil de entender.",
  ui_story_1020_10200601_16_dialog_content = "Al principio, todos pensamos que Ulysses no era más que un megalómano sin esperanza, pero después de ver esto, ya no estoy tan convencido.",
  ui_story_1020_10200601_17_dialog_content = "Durante todos estos años, la Ciudad de Gannon nunca ha sido destruida... ¿Realmente insistió en realizar esos experimentos por pura locura?",
  ui_story_1020_10200601_18_dialog_content = "Jefe de Personal, me gustaría traer a Ulysses aquí.",
  ui_story_1020_10200601_19_dialog_content = "Uh, no creo que el Comité consienta eso, pero puedo intentar contactar al Gran Mariscal...",
  ui_story_1020_10200601_20_dialog_content = "...",
  ui_story_1020_10200601_21_dialog_content = "Pero Ulysses posee el mayor entendimiento de esta máquina en este momento.",
  ui_story_1020_10200601_22_dialog_content = "Bool solo puede ayudarnos a recuperar los datos del módulo necesarios para construir un núcleo. La información que registramos justo ahora solo era para ayudar con los cálculos, y nada más.",
  ui_story_1020_10200601_23_dialog_content = "El prototipo ha estado sellado todo este tiempo. En adelante, no tengo idea de qué tipo de obstáculos encontrará nuestra investigación.",
  ui_story_1020_10200601_24_dialog_content = "Celestita.",
  ui_story_1020_10200601_25_dialog_content = "...",
  ui_story_1020_10200601_26_dialog_content = "¿Estás bien, PlayerName?",
  ui_story_1020_10200601_27_dialog_content = "Yo... creo que vi algo parpadeando hace un momento...",
  ui_story_1020_10200601_28_dialog_content = "¿Qué era?",
  ui_story_1020_10200601_29_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10200601_30_dialog_content = "<color=#e8d9bb>Bip-bip-bip-</color>",
  ui_story_1020_10200601_31_dialog_content = "¿Está bloqueado?",
  ui_story_1020_10200601_32_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200601_33_dialog_content = "Oye, ¿qué pasa?",
  ui_story_1020_10200601_34_dialog_content = "¡El almacén está temblando!",
  ui_story_1020_10200601_35_dialog_content = "...",
  ui_story_1020_10200601_36_dialog_content = "Espera... No debería haberse bloqueado ya que pudimos recuperar los datos del módulo...",
  ui_story_1020_10200601_37_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10200601_38_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200601_39_dialog_content = "¿No estaba Bool extrayendo códigos de defensa del prototipo para construir un nuevo núcleo?",
  ui_story_1020_10200601_40_dialog_content = "¿Esto está relacionado con el proceso de resolver las brechas de defensa?",
  ui_story_1020_10200601_41_dialog_content = "Parece que ese podría ser el caso, ¡pero este temblor es demasiado fuerte!",
  ui_story_1020_10200601_42_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200601_43_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10200601_44_dialog_content = "¡Tienes razón! Es más como si algo hubiera comenzado a atacar mis computadoras y los sistemas de defensa de Illumina después de que recuperamos los datos del módulo de Guardian!",
  ui_story_1020_10200601_45_dialog_content = "¿Es este un caso de algún juego imitando la realidad? ¿Intrusión de datos?",
  ui_story_1020_10200601_46_dialog_content = "Espera... Módulo de defensa, módulo de defensa... Solo un segundo...",
  ui_story_1020_10200601_47_dialog_content = "Ustedes vayan a evaluar la situación a nuestro alrededor. Intentaré recuperar el módulo de defensa nuevamente.",
  ui_story_1020_10200601_48_dialog_content = "Si el Guardián no está reforzando sus defensas, sino deteriorándolas aún más...",
  ui_story_1020_10200601_49_dialog_content = "Entonces toda la ciudad subterránea está en problemas...",
  ui_story_1020_10200601_50_dialog_content = "No. Lo que sea que nos esté luchando ahora está dentro del prototipo o posiblemente en el otro lado.",
  ui_story_1020_10200601_51_dialog_content = "...",
  ui_story_1020_10200601_52_dialog_content = "Pero, ¿qué podría ser?",
  ui_story_1020_10200601_53_dialog_content = "Solo Ulysses lo sabría...",
  ui_story_1020_10200601_54_dialog_content = "<color=#e8d9bb>Bip-bip-bip-</color>",
  ui_story_1020_10200601_55_dialog_content = "¡No! ¡Cortó mi ruta de acceso!",
  ui_story_1020_10200601_56_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200601_57_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1020_10200601_58_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1020_10200601_59_dialog_content = "<color=#e8d9bb>Bip-bip-bip-</color>",
  ui_story_1020_10200601_60_dialog_content = "Tanta información de una vez...",
  ui_story_1020_10200601_61_dialog_content = "Túnel... Puerta 10... La situación es peor de lo que pensaba, Dr. Algol!",
  ui_story_1020_10200601_62_dialog_content = "¡Muchos de los sistemas de defensa de la Subciudad están siendo atacados!",
  ui_story_1020_10200601_63_dialog_content = "... Es probable que muchos de los controles hayan sido bloqueados. Jefe de Personal, me temo que tendrás que salir y echar una mano por ahora!",
  ui_story_1020_10200601_64_dialog_content = "Bool, ¡reinicia el módulo!",
  ui_story_1020_10200601_65_dialog_content = "¡Bu!",
  ui_story_1020_10200601_66_dialog_content = "Gronru, Migard, ustedes dos revisen el panel de control en el edificio del laboratorio, especialmente las áreas con almacenes y equipos de laboratorio grandes.",
  ui_story_1020_10200601_67_dialog_content = "Tendremos que controlar manualmente algunos de los interruptores por ahora.",
  ui_story_1020_10200601_68_dialog_content = "¡Recopilaré más información de aquellos que me enviaron mensajes, luego me pondré en contacto con el Gran Mariscal!",
  ui_story_1020_10200601_69_dialog_content = "Tienes percepciones agudas, PlayerName. ¡Alerta a todos cuando sientas peligro!",
  ui_story_1020_10200601_70_dialog_content = "¡No hay problema!",
  ui_story_1020_10200601_71_dialog_content = "(¿Esto tiene algo que ver con esa luz intermitente que acabo de ver?)",
  ui_story_1020_10200601_72_dialog_content = "<color=#e8d9bb>Un equipo de construcción en un túnel de Illumina</color>",
  ui_story_1020_10200601_73_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200601_74_dialog_content = "¡Ciel! ¡Ciel!",
  ui_story_1020_10200601_75_dialog_content = "¡Sal ahora!",
  ui_story_1020_10200601_76_dialog_content = "¿Qué?",
  ui_story_1020_10200601_77_dialog_content = "¿No pudiste sentir ese violento temblor? ¡El túnel frente a ti se ha derrumbado!",
  ui_story_1020_10200601_78_dialog_content = "Pero es más peligroso correr sin rumbo en este momento...",
  ui_story_1020_10200601_79_dialog_content = "De todos modos, estoy activando el mecha dinámico.",
  ui_story_1020_10200601_80_dialog_content = "<color=#e8d9bb>Centro Médico Illumina</color>",
  ui_story_1020_10200601_81_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200601_82_dialog_content = "Todo este alboroto...",
  ui_story_1020_10200601_83_dialog_content = "¿Desperté a todos de nuevo?",
  ui_story_1020_10200601_84_dialog_content = "...",
  ui_story_1020_10200601_85_dialog_content = "No, no esta vez.",
  ui_story_1020_10200601_86_dialog_content = "Yo sigo en la cama...",
  ui_story_1020_10200601_87_dialog_content = "Reinhardt... Solo espero poder hacer algo por Illumina.",
  ui_story_1020_10200601_88_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1020_10200601_89_dialog_content = "¡Gran Mariscal! Finalmente, tú—",
  ui_story_1020_10200601_90_dialog_content = "Lamento haberte hecho esperar.",
  ui_story_1020_10200601_91_dialog_content = "Se ha detectado una máquina peligrosa en un almacén del Parque Tecnológico. ¿Dónde están todos ustedes?",
  ui_story_1020_10200601_92_dialog_content = "Estamos en el Almacén Cero. ¡Ulysses lo ha estado usando en secreto!",
  ui_story_1020_10200601_93_dialog_content = "¿Almacén Cero?",
  ui_story_1020_10200601_94_dialog_content = "¡Contiene super soldados y una antigua máquina con posibles vínculos con Eclipse que está causando el terremoto!",
  ui_story_1020_10200601_95_dialog_content = "¡Retrocede!",
  ui_story_1020_10200601_96_dialog_content = "¡Todos necesitan evacuar el área ahora mismo!",
  ui_story_1020_10200601_97_dialog_content = "Dr. Algol...",
  ui_story_1020_10200601_98_dialog_content = "¡Mantén esos controles estables! ¡Va a llevar tiempo si queremos construir un nuevo núcleo para resolver las brechas de defensa!",
  ui_story_1020_10200601_99_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10200601_100_dialog_content = "¡Oh, cierto! Jefe de personal, por favor haga que Reinhardt escolte a Ulysses hasta aquí!",
  ui_story_1020_10200601_101_dialog_content = "<color=#e8d9bb>Sala de Conferencias de Alto Nivel Illumina</color>",
  ui_story_1020_10200601_102_dialog_content = "El sistema de control automático está fuera de control. Las puertas cercanas al nivel de la superficie están funcionando mal. El túnel se ha derrumbado...",
  ui_story_1020_10200601_103_dialog_content = "¿Es este el resultado que estabas esperando?",
  ui_story_1020_10200601_104_dialog_content = "¿Qué tal Lumopolis?",
  ui_story_1020_10200601_105_dialog_content = "Nada está pasando.",
  ui_story_1020_10200601_106_dialog_content = "...",
  ui_story_1020_10200601_107_dialog_content = "¿Estás pensando en anunciar el <color=#FFB400>Protocolo de Emergencia</color>?",
  ui_story_1020_10200601_108_dialog_content = "Aún no es el momento.",
  ui_story_1020_10200601_109_dialog_content = "Siento que el suelo tiembla.",
  ui_story_1020_10200601_110_dialog_content = "Yo también.",
  ui_story_1020_10200601_111_dialog_content = "¿Es esto todo lo que viene de la gente que pretende apoderarse de mi laboratorio?",
  ui_story_1020_10200601_112_dialog_content = "Jejeje... ¿Qué crees que eres capaz de hacer?",
  ui_story_1020_10200601_113_dialog_content = "Sabías que había un problema con esa máquina y solo estabas esperando que algo sucediera, ¿verdad?",
  ui_story_1020_10200601_114_dialog_content = "... ¿Problema con el prototipo?",
  ui_story_1020_10200601_115_dialog_content = "Deberías... descubrir la historia por ti mismo...",
  ui_story_1020_10200601_116_dialog_content = "Wrath, Hiiro, mantén un ojo en Ulysses. No lo pierdas de vista por ningún motivo.",
  ui_story_1020_10200601_117_dialog_content = "Iré a evaluar la situación y te diré cuando sea seguro llevarlo allí.",
  ui_story_1020_10200601_118_dialog_content = "Entendido.",
  ui_story_1020_10200601_119_dialog_content = "Míralo, PlayerName.",
  ui_story_1020_10200601_120_dialog_content = "<color=#e8d9bb>Nivel superficial de la ciudad de Gannon</color>",
  ui_story_1020_10200601_121_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200601_122_dialog_content = "¡Sí, Comandante Barton! ¡Las paredes están temblando violentamente como si alguien hubiera presionado el interruptor de las puertas!",
  ui_story_1020_10200601_123_dialog_content = "¿Todas las puertas?",
  ui_story_1020_10200601_124_dialog_content = "No. Principalmente es que los Eclipsites se acercan desde las dos puertas seriamente dañadas a la derecha!",
  ui_story_1020_10200601_125_dialog_content = "Vivian y su compañía probablemente se encontraron con problemas.",
  ui_story_1020_10200601_126_dialog_content = "Defiende las puertas a toda costa.",
  ui_story_1020_10200601_127_dialog_content = "Incluso si hacen agujeros en ellos, los taparemos con torretas y haremos estallar a los invasores a medida que lleguen!",
  ui_story_1020_10200601_128_dialog_content = "¡Si te gusta ver explotar las cabezas de los Eclipsites, hoy estás de suerte!",
  ui_story_1020_10200601_129_dialog_content = "¡Entendido!",
  ui_story_1020_10200601_130_dialog_content = "<color=#e8d9bb>¡Boom—Boom—Boom!</color>",
  ui_story_1020_10200601_131_dialog_content = "¡Jajaja!",
  ui_story_1020_10200601_132_dialog_content = "¡Cabezas explotando!",
  ui_story_1020_10200601_133_dialog_content = "¡Aquí vienen los más poderosos de la Barton Legión!",
  ui_story_1020_10200602_1_dialog_content = "¡Boo, boo, boo!",
  ui_story_1020_10200602_2_dialog_content = "...",
  ui_story_1020_10200602_3_dialog_content = "¿Están todos bien?",
  ui_story_1020_10200602_4_dialog_content = "¡Gracias por detener a los monstruos detrás de mí, Gran Mariscal!",
  ui_story_1020_10200602_5_dialog_content = "¡Nunca pensé que esos super-soldados caídos se levantarían y atacarían de nuevo!",
  ui_story_1020_10200602_6_dialog_content = "¡Hemos vuelto, hemos vuelto! ¡La alarma de la escotilla de varios laboratorios estaba sonando!",
  ui_story_1020_10200602_7_dialog_content = "Están cerradas de nuevo, con soldados vigilando fuera del laboratorio.",
  ui_story_1020_10200602_8_dialog_content = "Buen trabajo, todos.",
  ui_story_1020_10200602_9_dialog_content = "Así que incluso con Illumina en una situación tan crítica, aún insististe en ir a un lugar aún más peligroso. ¿Por qué no me sorprende, PlayerName?",
  ui_story_1020_10200602_10_dialog_content = "Lo siento...",
  ui_story_1020_10200602_11_dialog_content = "Me alegra que estés a salvo. No tenía idea de que Ulysses estaba utilizando este lugar para producir super-soldados...",
  ui_story_1020_10200602_12_dialog_content = "Dame un informe de estado, Vivian.",
  ui_story_1020_10200602_13_dialog_content = "Todo comenzó con brechas en las defensas de Gannon y super soldados atacándonos en el Parque Tecnológico.",
  ui_story_1020_10200602_14_dialog_content = "Afortunadamente, la Dra. Algol encontró este lugar y descubrió el prototipo sellado. En este momento, está intentando construir un núcleo de defensa.",
  ui_story_1020_10200602_15_dialog_content = "Entonces, el temblor de hace un momento, ¿se resolvió ese problema?",
  ui_story_1020_10200602_16_dialog_content = "Por el momento, sí. Logré abrir una nueva ruta de acceso y estabilizar los controles, pero quién sabe dónde ocurrirá la próxima violación de seguridad.",
  ui_story_1020_10200602_17_dialog_content = "¿Dónde está Ulysses?",
  ui_story_1020_10200602_18_dialog_content = "Nos habló de esta máquina, pero necesitaba entender la situación antes de decidir si traerlo aquí o no.",
  ui_story_1020_10200602_19_dialog_content = "Su condición actual es... especial, por decir lo menos.",
  ui_story_1020_10200602_20_dialog_content = "¿Te dijo quién era su contacto dentro de Eclipse?",
  ui_story_1020_10200602_21_dialog_content = "Si me estás preguntando eso, entonces no hay duda al respecto...",
  ui_story_1020_10200602_22_dialog_content = "Mencionó que encontró pistas relacionadas con el Ingeniero dentro del prototipo.",
  ui_story_1020_10200602_23_dialog_content = "Según Ulysses, el Ingeniero fue quien estableció por primera vez la Federación Illumina y desapareció sin dejar rastro hace más de seiscientos años...",
  ui_story_1020_10200602_24_dialog_content = "Desapareció hace seiscientos años... Y ahora el Ingeniero está usando una computadora para comunicarse con Ulysses...",
  ui_story_1020_10200602_25_dialog_content = "¿Usando poderes psíquicos como PlayerName?",
  ui_story_1020_10200602_26_dialog_content = "¿Poder psíquico?",
  ui_story_1020_10200602_27_dialog_content = "(Esas visiones que vi en mi cabeza... ¿Fueron creadas por poderes como el mío?)",
  ui_story_1020_10200602_28_dialog_content = "¿No es eso algo que solo los Caelestites pueden hacer?",
  ui_story_1020_10200602_29_dialog_content = "Si el Ingeniero realmente existe, entonces comunicarse con Ulysses en tiempo real a través del prototipo es teóricamente posible, siempre y cuando el circuito sea lo suficientemente eficiente.",
  ui_story_1020_10200602_30_dialog_content = "Pero el prototipo no tiene cables, al menos que yo pueda ver, ni ningún hardware para enviar y recibir mensajes. Eso significa—",
  ui_story_1020_10200602_31_dialog_content = "Bip—",
  ui_story_1020_10200602_32_dialog_content = "Esta es la <color=#FFB400>interfaz</color> que Algol le dijo a Guardian One que trajera.",
  ui_story_1020_10200602_33_dialog_content = "Gracias, dámelo aquí.",
  ui_story_1020_10200602_34_dialog_content = "Entonces, por ejemplo...",
  ui_story_1020_10200602_35_dialog_content = "Mientras esté conectado a un circuito como este, Guardian One puede aparecer en mi computadora y comunicarse conmigo en tiempo real.",
  ui_story_1020_10200602_36_dialog_content = "Oh. ¡Hola a todos! ¿Se ve mi cara demasiado grande?",
  ui_story_1020_10200602_37_dialog_content = "No vimos ningún <color=#FFB400>circuito</color> así cuando revisamos. Todo estaba impecable. Incluso las paredes y los pisos estaban soldados sin costuras...",
  ui_story_1020_10200602_38_dialog_content = "Eso es extraño. Según nuestros registros, este almacén no estaba en uso porque demasiados circuitos viejos se habían fusionado prácticamente con su entorno. No había forma de que pudiéramos aprovecharlo.",
  ui_story_1020_10200602_39_dialog_content = "¿Es eso realmente cierto? Porque cuando llegué aquí por primera vez, no parecía diferente a como es ahora.",
  ui_story_1020_10200602_40_dialog_content = "Es posible que alguien lo arregló antes de eso.",
  ui_story_1020_10200602_41_dialog_content = "Arreglar un almacén tan grande no es tarea fácil, ese viejo granuja...",
  ui_story_1020_10200602_42_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10200602_43_dialog_content = "<color=#e8d9bb>Zzz—Zzz—</color>",
  ui_story_1020_10200602_44_dialog_content = "Oye, ¿por qué tus circuitos están chispeando, Dr. Algol?",
  ui_story_1020_10200602_45_dialog_content = "¿Eh? ¿Sobrecarga de energía? ¡Pero eso es imposible!",
  ui_story_1020_10200602_46_dialog_content = "Espera... ¿Cada componente individual está funcionando a máxima potencia?",
  ui_story_1020_10200602_47_dialog_content = "<color=#e8d9bb>¡Bzz—Bang!</color>",
  ui_story_1020_10200602_48_dialog_content = "¡Argh! ¡Fritó mi circuito!",
  ui_story_1020_10200602_49_dialog_content = "Algol está enojado.",
  ui_story_1020_10200602_50_dialog_content = "¡Boo, boo, boo!",
  ui_story_1020_10200602_51_dialog_content = "<color=#e8d9bb>Bip-bip-bip-</color>",
  ui_story_1020_10200602_52_dialog_content = "¡De toda la mala suerte! ¡Ahora el nuevo módulo de defensa está atascado!",
  ui_story_1020_10200602_53_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10200602_54_dialog_content = "<color=#e8d9bb>Zoom—</color>",
  ui_story_1020_10200602_55_dialog_content = "¿Se está deteniendo?",
  ui_story_1020_10200602_56_dialog_content = "<color=#e8d9bb>Buzz Buzz-</color>",
  ui_story_1020_10200602_57_dialog_content = "¡Es un cerebro!",
  ui_story_1020_10200602_58_dialog_content = "...",
  ui_story_1020_10200602_59_dialog_content = "¿Podría ser este el llamado \"Ingeniero\"?",
  ui_story_1020_10200602_60_dialog_content = "Esas imágenes parpadeantes... ¿Estaba intentando comunicarse conmigo?",
  ui_story_1020_10200602_61_dialog_content = "Oye, ¿cómo es que se fue?",
  ui_story_1020_10200602_62_dialog_content = "¡Boo, boo, boo!",
  ui_story_1020_10200602_63_dialog_content = "¿Qué? ¿Está hablando? ¿Puedes descifrar su idioma?",
  ui_story_1020_10200602_64_dialog_content = "... Boo, boo...",
  ui_story_1020_10200602_65_dialog_content = "¿Qué está diciendo el Ingeniero?",
  ui_story_1020_10200602_66_dialog_content = "... Boo, boo...",
  ui_story_1020_10200602_67_dialog_content = "\"Ha sido un largo tiempo\"",
  ui_story_1020_10200602_68_dialog_content = "... Boo, boo...",
  ui_story_1020_10200602_69_dialog_content = "\"Doctor\"",
  ui_story_1020_10200602_70_dialog_content = "... Boo, boo...",
  ui_story_1020_10200602_71_dialog_content = "\"Ulysses\"",
  ui_story_1020_10200602_72_dialog_content = "...",
  ui_story_1020_10200602_73_dialog_content = "¡Bool! ¡Cambia las rutas de acceso e intenta recuperar el módulo!",
  ui_story_1020_10200602_74_dialog_content = "¡Bu!",
  ui_story_1020_10200602_75_dialog_content = "<color=#e8d9bb>Zoom—</color>",
  ui_story_1020_10200602_76_dialog_content = "...",
  ui_story_1020_10200602_77_dialog_content = "Ha pasado... mucho tiempo...",
  ui_story_1020_10200602_78_dialog_content = "Sí... Sí... Jaja...",
  ui_story_1020_10200602_79_dialog_content = "Así que has venido...",
  ui_story_1020_10200602_80_dialog_content = "¿Quién?",
  ui_story_1020_10200602_81_dialog_content = "El Ingeniero...",
  ui_story_1020_10200602_82_dialog_content = "¿Dónde?",
  ui_story_1020_10200602_83_dialog_content = "Dame la última pastilla, Esien.",
  ui_story_1020_10200602_84_dialog_content = "Señor...",
  ui_story_1020_10200602_85_dialog_content = "¡Dámelo!",
  ui_story_1020_10200602_86_dialog_content = "<color=#e8d9bb>Celda de prisión Illumina</color>",
  ui_story_1020_10200602_87_dialog_content = "(Eclipsiano) E-Eres tú... ¡El gobernante supremo!",
  ui_story_1020_10200602_88_dialog_content = "(Eclipsian) Tu fiel sirviente, Figerald, ha estado arrodillado aquí todo este tiempo, esperando tu llegada.",
  ui_story_1020_10200602_89_dialog_content = "...",
  ui_story_1020_10200602_90_dialog_content = "<color=#e8d9bb>Sonido metálico-</color>",
  ui_story_1020_10200602_91_dialog_content = "(Eclipsiano) ...",
  ui_story_1020_10200602_92_dialog_content = "(Hablando en Eclipsiano) ¡T-Tiembla ante ti! ¡Nunca me atrevería a ir en contra de tus deseos!",
  ui_story_1020_10200602_93_dialog_content = "(Eclipsian) Permíteme redimirme...",
  ui_story_1020_10200602_94_dialog_content = "(En eclipsiano) La misión que una vez fallé se completará, incluso a costa de mi propia vida.",
  ui_story_1020_10200701_1_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200701_2_dialog_content = "Ya se llevó el núcleo de Guardian One, Ulysses. ¿Qué más quiere?",
  ui_story_1020_10200701_3_dialog_content = "¿No te parece aterrador que la Subciudad esté al borde del colapso, Máscara de Hierro?",
  ui_story_1020_10200701_4_dialog_content = "Planificaste todo esto... ¿Entregaste la esencia de Illumina a Eclipse en bandeja de plata solo para obtener más recursos para la investigación y cumplir tu sueño?",
  ui_story_1020_10200701_5_dialog_content = "También creí una vez que Illumina no estaría aquí hoy sin el Ingeniero.",
  ui_story_1020_10200701_6_dialog_content = "Entonces me di cuenta de que el núcleo de Guardian One nunca fue la vida de Illumina.",
  ui_story_1020_10200701_7_dialog_content = "¡Yo era!",
  ui_story_1020_10200701_8_dialog_content = "¿Cómo puede el sistema de defensa de Gannon convertirse en un colador simplemente por la falta de un núcleo?",
  ui_story_1020_10200701_9_dialog_content = "Permíteme contarte sobre el plan del Ingeniero...",
  ui_story_1020_10200701_10_dialog_content = "Quería unificar y quemar, desafiar la insignificancia de los Aurorians con su grandeza...",
  ui_story_1020_10200701_11_dialog_content = "¡Pero no quiero esperar mi fin en esta oscura ciudad subterránea como tú! ¡Lo desafiaré!",
  ui_story_1020_10200701_12_dialog_content = "Locura... ¡Esto es una locura!",
  ui_story_1020_10200701_13_dialog_content = "¿Sabes cómo planeaba lograr eso?",
  ui_story_1020_10200701_14_dialog_content = "Construyó todo esto, entró en silencio y entregó las tareas de recuperar el núcleo y crear Eclipsites al tonto Wraith.",
  ui_story_1020_10200701_15_dialog_content = "Dormido durante varios cientos de años, él ha despertado.",
  ui_story_1020_10200701_16_dialog_content = "Pero el mundo ha cambiado. Ya no es el Ingeniero del que aprendí en los archivos.",
  ui_story_1020_10200701_17_dialog_content = "Lo que sea que él pueda hacer, probablemente yo también pueda lograrlo.",
  ui_story_1020_10200701_18_dialog_content = "¡Cierra tu asquerosa boca!",
  ui_story_1020_10200701_19_dialog_content = "Cualquiera de nosotros aquí puede matarte con un movimiento de la mano. Será mejor que—",
  ui_story_1020_10200701_20_dialog_content = "¿Qué puedes hacer?",
  ui_story_1020_10200701_21_dialog_content = "...",
  ui_story_1020_10200701_22_dialog_content = "Jeje... Tengo todo lo que necesito listo en mi almacén.",
  ui_story_1020_10200701_23_dialog_content = "¡Alto!",
  ui_story_1020_10200701_24_dialog_content = "... ¿Estás tratando de detenerme?",
  ui_story_1020_10200701_25_dialog_content = "No vas a ninguna parte.",
  ui_story_1020_10200701_26_dialog_content = "... Ninguno de ustedes me cree, pero ahora soy el único que puede—",
  ui_story_1020_10200701_27_dialog_content = "¡Solo da otro paso!",
  ui_story_1020_10200701_28_dialog_content = "Guarda el arma.",
  ui_story_1020_10200701_29_dialog_content = "...",
  ui_story_1020_10200701_30_dialog_content = "El tiempo se nos acaba a ti y a mí, Máscara de Hierro, pero a Illumina aún le queda un largo camino por recorrer, al igual que a los Aurorians.",
  ui_story_1020_10200701_31_dialog_content = "Sabía que este día llegaría, ¡pero no me rendiré aunque todos ustedes desaprueben!",
  ui_story_1020_10200701_32_dialog_content = "Lucharé a mi manera.",
  ui_story_1020_10200701_33_dialog_content = "Si no puedes ayudar, lo haré yo mismo...",
  ui_story_1020_10200701_34_dialog_content = "¿Tienes las agallas para verlo?",
  ui_story_1020_10200701_35_dialog_content = "...",
  ui_story_1020_10200701_36_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1020_10200701_37_dialog_content = "Gran Mariscal?",
  ui_story_1020_10200701_38_dialog_content = "Nos dijo que trajéramos a Ulysses.",
  ui_story_1020_10200701_39_dialog_content = "...",
  ui_story_1020_10200701_40_dialog_content = "El juego de ajedrez no es nada sin las piezas de ajedrez, Belisaria. ¿Cómo puedes permitirte ser el que haga movimientos en ese caso?",
  ui_story_1020_10200701_41_dialog_content = "Creo que pase lo que pase, Reinhardt mantendrá a Gannon intacto. ¿Pero eres capaz de hacer lo mismo?",
  ui_story_1020_10200701_42_dialog_content = "...",
  ui_story_1020_10200701_43_dialog_content = "Davidar, contacta con Barrett.",
  ui_story_1020_10200701_44_dialog_content = "El Dr. Barrett te ha estado esperando durante mucho tiempo.",
  ui_story_1020_10200701_45_dialog_content = "¿Cuál es la decisión?",
  ui_story_1020_10200701_46_dialog_content = "Inicie el <color=#FFB400>Protocolo de Emergencia</color>.",
  ui_story_1020_10200701_47_dialog_content = "Desempaquen el equipo original, cambien la ruta preestablecida, abran el eje de transporte y trasladen a los civiles a las Subciudades de reserva.",
  ui_story_1020_10200701_48_dialog_content = "Los vehículos y el eje de transporte están funcionando normalmente. Se puede transportar a los civiles.",
  ui_story_1020_10200701_49_dialog_content = "Pero solicito suficientes tropas para garantizar un transporte seguro en los ejes del Comité.",
  ui_story_1020_10200701_50_dialog_content = "Solo hazlo. El Comité abrirá el camino para ti.",
  ui_story_1020_10200701_51_dialog_content = "Así es como me gusta.",
  ui_story_1020_10200701_52_dialog_content = "Ustedes dos lleven Ulysses al almacén.",
  ui_story_1020_10200701_53_dialog_content = "Espera, vehículos y eje de transporte... ¿Qué quieres decir?",
  ui_story_1020_10200701_54_dialog_content = "Aviones desarrollados por Illumina y una red de rieles subterráneos diseñados específicamente para ellos.",
  ui_story_1020_10200701_55_dialog_content = "¿Aeronaves?",
  ui_story_1020_10200701_56_dialog_content = "¿Crees que Illumina solo tiene trenes terrestres, transportistas y túneles?",
  ui_story_1020_10200701_57_dialog_content = "Entonces, ¿de qué se tratan el equipo original y la ruta preestablecida?",
  ui_story_1020_10200701_58_dialog_content = "No me importa decirte, estas aeronaves están destinadas para esa ciudad flotante, y la ruta preestablecida va directamente a Lumopolis desde aquí.",
  ui_story_1020_10200701_59_dialog_content = "¿Estos aviones estaban armados para atacar Lumopolis?",
  ui_story_1020_10200701_60_dialog_content = "Necesitas diferentes armas para luchar contra diferentes oponentes. Y cuando hayas decidido golpear la superficie, tienes que hacer lo que sea necesario.",
  ui_story_1020_10200701_61_dialog_content = "...",
  ui_story_1020_10200701_62_dialog_content = "No anticipé que este sería el momento para iniciar el protocolo.",
  ui_story_1020_10200701_63_dialog_content = "Incluso si no lo dices, al menos tenemos el mismo interés en este asunto.",
  ui_story_1020_10200701_64_dialog_content = "Lleva a Ulysses a su almacén. Ahora es tu rehén.",
  ui_story_1020_10200701_65_dialog_content = "...",
  ui_story_1020_10200701_66_dialog_content = "Jeje. Veo que ya no eres el líder cínico que solías ser.",
  ui_story_1020_10200701_67_dialog_content = "Nos volveremos a ver, ¿verdad?",
  ui_story_1020_10200701_68_dialog_content = "Hay tiempo para jugar.",
  ui_story_1020_10200701_69_dialog_content = "Pero tienes que ser serio cuando las cosas se ponen difíciles.",
  ui_story_1020_10200701_70_dialog_content = "Si puedes manejar eso, no creo que necesitemos vernos de nuevo.",
  ui_story_1020_10200701_71_dialog_content = "Nada ha sucedido en Lumopolis incluso después de que se abrió el eje de transporte.",
  ui_story_1020_10200701_72_dialog_content = "Después de mantener un perfil bajo durante tantos años, sería una lástima no aprovechar esta oportunidad para atacar la ciudad flotante.",
  ui_story_1020_10200701_73_dialog_content = "Regresa a tus deberes. Todavía tenemos muchas cosas pendientes por hacer.",
  ui_story_1020_10200701_74_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200701_75_dialog_content = "Axelia, Yingel, ¿qué deberíamos hacer ahora?",
  ui_story_1020_10200701_76_dialog_content = "Lo que siempre hemos hecho antes. El Gran Mariscal y los demás fueron al almacén, así que deberíamos protegerlos.",
  ui_story_1020_10200701_77_dialog_content = "Como máquinas de guerra, ¿siempre sabes qué debes hacer en todo momento?",
  ui_story_1020_10200701_78_dialog_content = "Ha estado claro para mí desde que tuve la edad suficiente para pensar.",
  ui_story_1020_10200701_79_dialog_content = "Recién lo supe hace poco. Tú también lo sabrás, Sean.",
  ui_story_1020_10200701_80_dialog_content = "Fácil para ti decir. Ustedes dos son—",
  ui_story_1020_10200701_81_dialog_content = "¡Ay!",
  ui_story_1020_10200701_82_dialog_content = "Yingel! ¿Por qué me pinchaste? Estoy sangrando...",
  ui_story_1020_10200701_83_dialog_content = "¿No son también los Aurorians de carne y hueso máquinas de guerra?",
  ui_story_1020_10200701_84_dialog_content = "Olvida lo que pasó en la reunión. Pase lo que pase, el Gran Mariscal nunca minimizará tu existencia o propósito.",
  ui_story_1020_10200701_85_dialog_content = "Ella y el Gran Mariscal Wrath son ambos víctimas del proyecto, pero aún así siguen cumpliendo con sus deberes.",
  ui_story_1020_10200701_86_dialog_content = "Probablemente sea extraño decir esto, pero con Grandes Mariscales como ellos, no tengo miedo en absoluto.",
  ui_story_1020_10200701_87_dialog_content = "...",
  ui_story_1020_10200701_88_dialog_content = "Yo tampoco.",
  ui_story_1020_10200701_89_dialog_content = "Tú...",
  ui_story_1020_10200701_90_dialog_content = "¡Vamos, vámonos! Corre más rápido, Sean!",
  ui_story_1020_10200701_91_dialog_content = "... ¡Bueno!",
  ui_story_1020_10200701_92_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200801_1_dialog_content = "El temblor... Se detuvo.",
  ui_story_1020_10200801_2_dialog_content = "¿Tuvimos éxito en construir un nuevo núcleo?",
  ui_story_1020_10200801_3_dialog_content = "No... La velocidad de procesamiento es más lenta de lo que esperábamos, y lleva demasiado tiempo lograr esto.",
  ui_story_1020_10200801_4_dialog_content = "Pero solo dame un poco más de tiempo. ¡Sé que puedo hacerlo!",
  ui_story_1020_10200801_5_dialog_content = "¡Bu!",
  ui_story_1020_10200801_6_dialog_content = "Deja de perder el tiempo...",
  ui_story_1020_10200801_7_dialog_content = "¡Quédate quieto, Ulysses!",
  ui_story_1020_10200801_8_dialog_content = "Estás aquí.",
  ui_story_1020_10200801_9_dialog_content = "También es idea de Belisaria. Ordenó a la gente de Gannon que se reubicara.",
  ui_story_1020_10200801_10_dialog_content = "No puedo creerlo... Dr. Algol, ¿cómo planeas lidiar con Ulysses?",
  ui_story_1020_10200801_11_dialog_content = "Dime, Ulysses, ¿hiciste todos estos Eclipsites como parte de un trato con el Ingeniero?",
  ui_story_1020_10200801_12_dialog_content = "Qué ingenuo. Pero parece que has aprendido algo a lo largo de los años para iniciar sesión en el sistema y mantener a Gannon estable.",
  ui_story_1020_10200801_13_dialog_content = "Sin embargo, te superaste a ti mismo cuando intentaste acceder a los datos de defensa de Guardian y defenderte de sus ataques al mismo tiempo.",
  ui_story_1020_10200801_14_dialog_content = "¿A qué estás llegando?",
  ui_story_1020_10200801_15_dialog_content = "Las brechas en Illumina no pueden ser arregladas una a la vez. Es simple desmantelar las defensas.",
  ui_story_1020_10200801_16_dialog_content = "Pero puedo simplemente decirle que pare.",
  ui_story_1020_10200801_17_dialog_content = "Muéstrame cómo hacerlo.",
  ui_story_1020_10200801_18_dialog_content = "No puedo hacer eso. Dije que el Caelestite podía, pero ninguno de ustedes lo creyó.",
  ui_story_1020_10200801_19_dialog_content = "¿Yo?",
  ui_story_1020_10200801_20_dialog_content = "No lo involucres en esto. Solo dinos cómo detener al Ingeniero.",
  ui_story_1020_10200801_21_dialog_content = "¿Detener? No quiero detenerlo. Solo estoy aquí para ver si rompiste a mis bebés.",
  ui_story_1020_10200801_22_dialog_content = "¡Te atreves a faltar a tu palabra!",
  ui_story_1020_10200801_23_dialog_content = "Todo esto no tenía nada que ver con ninguno de ustedes en primer lugar.",
  ui_story_1020_10200801_24_dialog_content = "<color=#e8d9bb>Buzz Buzz-</color>",
  ui_story_1020_10200801_25_dialog_content = "No otra vez...",
  ui_story_1020_10200801_26_dialog_content = "... Boo, boo...",
  ui_story_1020_10200801_27_dialog_content = "\"¿Regalo\"?",
  ui_story_1020_10200801_28_dialog_content = "... ¿Qué significa eso?",
  ui_story_1020_10200801_29_dialog_content = "No voy a culparte por los experimentos incompletos que destruiste.",
  ui_story_1020_10200801_30_dialog_content = "Pero le preparé algo extra.",
  ui_story_1020_10200801_31_dialog_content = "Déjame ver, debería estar por aquí...",
  ui_story_1020_10200801_32_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200801_33_dialog_content = "¡Argh!",
  ui_story_1020_10200801_34_dialog_content = "¡Aférrate a mí!",
  ui_story_1020_10200801_35_dialog_content = "¿Qué has hecho, Ulysses?",
  ui_story_1020_10200801_36_dialog_content = "¡Este terremoto es más grande que el último!",
  ui_story_1020_10200801_37_dialog_content = "¡No solo está temblando! ¡Se está moviendo!",
  ui_story_1020_10200801_38_dialog_content = "No pierdas tu equilibrio—",
  ui_story_1020_10200801_39_dialog_content = "¡Jajajajaja! ¡Mira!",
  ui_story_1020_10200801_40_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200801_41_dialog_content = "Esos <color=#FFB400>súper-soldados</color>, la fusión de Aurorianos y Eclipsites, cada uno capaz de luchar contra cien enemigos a la vez...",
  ui_story_1020_10200801_42_dialog_content = "¡Superaron cualquier cosa que hayas hecho hace mucho tiempo!",
  ui_story_1020_10200801_43_dialog_content = "Todo el subsuelo está inundado...",
  ui_story_1020_10200801_44_dialog_content = "¿Cuántos hay?",
  ui_story_1020_10200801_45_dialog_content = "... ¡Están debajo del suelo en el que estamos parados! ¡No es de extrañar que no pudiéramos encontrarlos!",
  ui_story_1020_10200801_46_dialog_content = "Unos cientos según mi estimación... No, más.",
  ui_story_1020_10200801_47_dialog_content = "Tienen cables saliendo de cada poro como si estuvieran siendo alimentados...",
  ui_story_1020_10200801_48_dialog_content = "¡Ulysses!",
  ui_story_1020_10200801_49_dialog_content = "<color=#e8d9bb>¡Bang—Bang—Bang—!</color>",
  ui_story_1020_10200801_50_dialog_content = "Esto es malo... ¡Esos súper soldados están empezando a moverse!",
  ui_story_1020_10200801_51_dialog_content = "<color=#e8d9bb>Clang—Clang—</color>",
  ui_story_1020_10200801_52_dialog_content = "¡Revisa los cables en el almacén... Están lanzando chispas!",
  ui_story_1020_10200801_53_dialog_content = "¡Los cables fusionados con su entorno han estado bajo el almacén todo el tiempo!",
  ui_story_1020_10200801_54_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10200801_55_dialog_content = "Entonces, así es como él controla a los súper soldados. Con estos, podría darles órdenes a través de la computadora...",
  ui_story_1020_10200801_56_dialog_content = "... ¡Ahora lo entiendo! ¡Bool!",
  ui_story_1020_10200801_57_dialog_content = "¡Bu!",
  ui_story_1020_10200801_58_dialog_content = "¿Entonces, cómo te gusta?",
  ui_story_1020_10200801_59_dialog_content = "¡Los Eclipsites que invadieron Astra hace diez o incluso veinte años no pueden esperar igualarlos!",
  ui_story_1020_10200801_60_dialog_content = "¿Qué?",
  ui_story_1020_10200801_61_dialog_content = "¡Jajaja!",
  ui_story_1020_10200801_62_dialog_content = "<color=#e8d9bb>Buzz Buzz-</color>",
  ui_story_1020_10200801_63_dialog_content = "(¿Cómo es que el Ingeniero puede oír la voz de Ulysses?)",
  ui_story_1020_10200801_64_dialog_content = "(¿Es el prototipo? ¿O tienen algún otro medio de comunicación?)",
  ui_story_1020_10200801_65_dialog_content = "... Boo, boo...",
  ui_story_1020_10200801_66_dialog_content = "\"No lo es\"",
  ui_story_1020_10200801_67_dialog_content = "... Boo, boo...",
  ui_story_1020_10200801_68_dialog_content = "\"Vale la pena mencionar\"",
  ui_story_1020_10200801_X68_dialog_content = "(¿Cómo es que el Ingeniero puede oír la voz de Ulysses?)",
  ui_story_1020_10200801_X69_dialog_content = "(¿Es el prototipo? ¿O tienen algún otro medio de comunicación?)",
  ui_story_1020_10200801_69_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200801_70_dialog_content = "¡Los super soldados están de pie!",
  ui_story_1020_10200801_X70_dialog_content = "¿Cómo te parece eso... Jaja...",
  ui_story_1020_10200801_71_dialog_content = "Hiiro, somete a Ulysses! Todos los demás, ¡retírense!",
  ui_story_1020_10200801_72_dialog_content = "¡Entendido!",
  ui_story_1020_10200801_73_dialog_content = "...",
  ui_story_1020_10200801_74_dialog_content = "¡Dr. Algol!",
  ui_story_1020_10200801_75_dialog_content = "... ¡Illumina está acabada si dejamos esta máquina sola!",
  ui_story_1020_10200801_76_dialog_content = "¿Cómo te parece eso... Jaja...",
  ui_story_1020_10200801_77_dialog_content = "<color=#e8d9bb>Bip-bip-bip-</color>",
  ui_story_1020_10200801_78_dialog_content = "¡Dinos cómo cerrar el almacén, Ulysses!",
  ui_story_1020_10200801_79_dialog_content = "¡Respóndeme!",
  ui_story_1020_10200801_80_dialog_content = "Esto no tiene nada que ver contigo. ¡No son tu enemigo! Puedes irte...",
  ui_story_1020_10200801_81_dialog_content = "¡Basta de tus tonterías!",
  ui_story_1020_10200801_82_dialog_content = "Bool, ¿has encontrado otra entrada? ¡Necesitas apurarte!",
  ui_story_1020_10200801_83_dialog_content = "¡Boo, boo, boo!",
  ui_story_1020_10200801_X83_dialog_content = "¡Vamos, solo un poco más rápido!",
  ui_story_1020_10200801_84_dialog_content = "<color=#e8d9bb>¡Bang—Bang—Bang—!</color>",
  ui_story_1020_10200801_85_dialog_content = "Rugir—",
  ui_story_1020_10200801_86_dialog_content = "¡Dr. Algol!",
  ui_story_1020_10200801_87_dialog_content = "...",
  ui_story_1020_10200801_88_dialog_content = "El Dr. Algol sigue negándose a irse...",
  ui_story_1020_10200801_89_dialog_content = "¡Permíteme usar mis poderes para rescatarte, Algol!",
  ui_story_1020_10200801_90_dialog_content = "¡No! ¡Salgan de aquí, todos ustedes!",
  ui_story_1020_10200801_91_dialog_content = "Ya encontré una forma de controlar a los súper soldados...",
  ui_story_1020_10200801_92_dialog_content = "¡Boo, boo, boo!",
  ui_story_1020_10200801_93_dialog_content = "Bien, ¡la base de datos ha sido actualizada! Solo necesito acceder a ella ahora...",
  ui_story_1020_10200801_94_dialog_content = "¡Vamos... Un poco más rápido!",
  ui_story_1020_10200801_95_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10200801_96_dialog_content = "¡Esquiva, Algol!",
  ui_story_1020_10200801_97_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_1020_10200801_98_dialog_content = "¿Boo?",
  ui_story_1020_10200801_99_dialog_content = "Rugirrrrr—",
  ui_story_1020_10200801_100_dialog_content = "¿Qué está pasando? ¡Los super soldados no están atacando a Algol!",
  ui_story_1020_10200801_101_dialog_content = "...",
  ui_story_1020_10200801_102_dialog_content = "<color=#e8d9bb>¡Estallido! ¡Estallido! ¡Estallido!</color>",
  ui_story_1020_10200801_103_dialog_content = "¿Están atacando... el prototipo?",
  ui_story_1020_10200801_104_dialog_content = "¿Es por esto que Ulysses creó a esos súper soldados?",
  ui_story_1020_10200801_105_dialog_content = "Jajajajajaja, te gusta eso, ¿no?",
  ui_story_1020_10200801_106_dialog_content = "¿Cómo se siente? ¿Dónde están tus Eclipsites ahora?",
  ui_story_1020_10200801_107_dialog_content = "<color=#e8d9bb>Buzz Buzz-</color>",
  ui_story_1020_10200801_108_dialog_content = "... Boo, boo...",
  ui_story_1020_10200801_109_dialog_content = "\"Gracias\"",
  ui_story_1020_10200801_110_dialog_content = "... ¿Gracias?",
  ui_story_1020_10200801_111_dialog_content = "...",
  ui_story_1020_10200801_112_dialog_content = "Rugido...",
  ui_story_1020_10200801_113_dialog_content = "Los súper soldados... Dejaron de moverse.",
  ui_story_1020_10200801_114_dialog_content = "¿Qué están buscando?",
  ui_story_1020_10200801_115_dialog_content = "<color=#e8d9bb>Zzz—Zzz—</color>",
  ui_story_1020_10200801_116_dialog_content = "Los cables se están volviendo locos otra vez, Dr. Algol!",
  ui_story_1020_10200801_117_dialog_content = "No te preocupes. Simplemente cancelaré sus pedidos...",
  ui_story_1020_10200801_118_dialog_content = "<color=#e8d9bb>Bip-bip-bip-</color>",
  ui_story_1020_10200801_119_dialog_content = "¿Me estás tomando el pelo? ¡Argh, odio esta cosa!",
  ui_story_1020_10200801_120_dialog_content = "¿Qué estás haciendo?",
  ui_story_1020_10200801_121_dialog_content = "<color=#e8d9bb>Zzz—Zzz—</color>",
  ui_story_1020_10200801_122_dialog_content = "¡Mira lo que está detrás de los súper soldados!",
  ui_story_1020_10200801_123_dialog_content = "¡Roooooooor!",
  ui_story_1020_10200801_124_dialog_content = "¡Está empezando a atacar!",
  ui_story_1020_10200801_125_dialog_content = "¿Qué estás haciendo a mis bebés?",
  ui_story_1020_10200801_126_dialog_content = "¡Roooooooor!",
  ui_story_1020_10200801_127_dialog_content = "¡Cuidado, Algol!",
  ui_story_1020_10200901_1_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200901_2_dialog_content = "¡Comandante Barton, ya hemos hecho todo lo posible!",
  ui_story_1020_10200901_3_dialog_content = "¡Pero nuestros camaradas en la <color=#FFB400>Puerta 10</color> aún están enfrascados en la batalla y necesitan asistencia urgente!",
  ui_story_1020_10200901_4_dialog_content = "¿Así que todos ustedes, los élites, simplemente van a dejar que alguien más aproveche esta oportunidad para luchar?",
  ui_story_1020_10200901_5_dialog_content = "¡No, Comandante! Las puertas están temblando demasiado violentamente para que nuestros cuerpos lo soporten...",
  ui_story_1020_10200901_6_dialog_content = "Puerta 10... ¿No es eso hacia el patio de servicio?",
  ui_story_1020_10200901_7_dialog_content = "¿Ese niño está intentando acaparar la gloria al hacer que Soroz sostenga las puertas?",
  ui_story_1020_10200901_8_dialog_content = "¿Puede un Colossus soportar las puertas?",
  ui_story_1020_10200901_9_dialog_content = "¿Por qué no puede si logró criar al Caelestite?",
  ui_story_1020_10200901_10_dialog_content = "¡Sígueme! ¡Nadie puede decirme que este cuerpo es inferior a un montón de chatarra!",
  ui_story_1020_10200901_11_dialog_content = "¡Comandante! También está temblando salvajemente en la <color=#FFB400>Puerta 9</color>. ¡Parece que una fuerte corriente de aire está subiendo desde el subsuelo a los niveles superiores!",
  ui_story_1020_10200901_12_dialog_content = "¿Subterráneo? ¡Revisa todos los conductos ahora! ¡Cada esquina y cada pulgada!",
  ui_story_1020_10200901_13_dialog_content = "¡Ya hemos inspeccionado todo! ¡No se encontraron rastros de Eclipsites!",
  ui_story_1020_10200901_14_dialog_content = "¿Que esta pasando aqui?",
  ui_story_1020_10200901_15_dialog_content = "<color=#e8d9bb>Alrededor de la Puerta 9</color>",
  ui_story_1020_10200901_16_dialog_content = "Oficial, el suelo está temblando salvajemente en esta área. ¡Por favor, evacue a un lugar seguro!",
  ui_story_1020_10200901_17_dialog_content = "No te preocupes por mí. El eje de transporte de abajo está funcionando y vine a medir el nivel de temblor aquí arriba.",
  ui_story_1020_10200901_18_dialog_content = "El pozo de transporte...",
  ui_story_1020_10200901_19_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200901_20_dialog_content = "Aceptable, apenas perjudicial para la puerta.",
  ui_story_1020_10200901_21_dialog_content = "...",
  ui_story_1020_10200901_22_dialog_content = "<color=#e8d9bb>Dawn Academia de Lumopolis</color>",
  ui_story_1020_10200901_23_dialog_content = "¡Noche Blanca en lo alto! ¿Has oído? Algo extraño le ocurrió a la <color=#FFB400>Piedra Noche Blanca</color> de la academia, y Lumina ha fluctuado salvajemente durante mucho tiempo.",
  ui_story_1020_10200901_24_dialog_content = "¡El Padre y las monjas corrieron pero no pudieron calmar las fluctuaciones a pesar de lanzar Luminatics con todo su poder!",
  ui_story_1020_10200901_25_dialog_content = "¿Esto está relacionado con la vibración que sacudió Lumopolis antes?",
  ui_story_1020_10200901_26_dialog_content = "Sí, me temo que las ruinas antiguas han comenzado a resonar con un poder misterioso de nuevo.",
  ui_story_1020_10200901_27_dialog_content = "Esto ocurrió antes cuando un trastorno de la aurora estalló en Crepúsculo en el pasado, pero las cosas son más serias esta vez.",
  ui_story_1020_10200901_28_dialog_content = "<color=#e8d9bb>Lumopolis, Corte Real</color>",
  ui_story_1020_10200901_29_dialog_content = "Mira, esos ejes se están abriendo como una boca hambrienta en el suelo. ¡Illumina se ha reducido a un lobo hambriento!",
  ui_story_1020_10200901_30_dialog_content = "El lobo aún no ha mordido a Lumopolis.",
  ui_story_1020_10200901_31_dialog_content = "Cancele la alarma, Capitán. Las ruinas están básicamente seguras ahora.",
  ui_story_1020_10200901_32_dialog_content = "Si mi señor.",
  ui_story_1020_10200901_33_dialog_content = "Señor de la Ciudad, la piedra que contiene Lumina en la Dawn Academia reaccionó violentamente a la vibración. ¿Crees que hay una fuerza desconocida en Lumopolis?",
  ui_story_1020_10200901_34_dialog_content = "Noche Blanca en lo alto. Su Alteza, no necesita preocuparse por esto.",
  ui_story_1020_10200901_35_dialog_content = "Aunque esto nunca ha ocurrido desde que Lady Santa ingresó al Templo de Lumopolis, el Dios de la Luz nos guiará.",
  ui_story_1020_10200901_36_dialog_content = "¿Qué crees que causó la respuesta en la Piedra Noche Blanca, Papá?",
  ui_story_1020_10200901_37_dialog_content = "Algo relevante ha sido registrado en los tomos. Se dice que la Lumina comenzará a fluctuar salvajemente cuando aparezca un nuevo <color=#FFB400>heredero del espíritu</color>.",
  ui_story_1020_10200901_38_dialog_content = "...",
  ui_story_1020_10200901_39_dialog_content = "La fuerza maligna oculta en las ruinas subterráneas una vez sacudió todo el Azurite. Fue la Heredera del Espíritu, la Santa, quien la disipó.",
  ui_story_1020_10200901_40_dialog_content = "Según mis cálculos, la Santa ha protegido Azurite durante muchos años.",
  ui_story_1020_10200901_41_dialog_content = "El mal solo puede ser expulsado pero no desterrado. Lumopolis no es puro.",
  ui_story_1020_10200901_42_dialog_content = "¿Estará Lumopolis en peligro, Papá?",
  ui_story_1020_10200901_43_dialog_content = "No.",
  ui_story_1020_10200901_44_dialog_content = "¿Qué pasa con la Federación Illumina?",
  ui_story_1020_10200901_45_dialog_content = "Primero, deben encontrar su propia fe.",
  ui_story_1020_10200901_46_dialog_content = "Mantén un ojo en los mensajes de Illumina, Capitán.",
  ui_story_1020_10200901_47_dialog_content = "¡Sí, Señor Schwartz!",
  ui_story_1020_10200901_48_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10200901_49_dialog_content = "¿Cuál es la situación actual, Dr. Algol?",
  ui_story_1020_10200901_50_dialog_content = "El panel de control ahora muestra que el núcleo está casi completo.",
  ui_story_1020_10200901_51_dialog_content = "No puedo creer que el Ingeniero aún no nos haya atacado... ¡Aguanta, Bool!",
  ui_story_1020_10200901_52_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10200901_53_dialog_content = "¿Qué?",
  ui_story_1020_10200901_54_dialog_content = "<color=#e8d9bb>Buzz Buzz-</color>",
  ui_story_1020_10200901_55_dialog_content = "... Boo, boo...",
  ui_story_1020_10200901_56_dialog_content = "\"Ve a casa, Caelestite\"",
  ui_story_1020_10200901_57_dialog_content = "¡El Caelestite no va a ninguna parte!",
  ui_story_1020_10200901_58_dialog_content = "...",
  ui_story_1020_10200901_59_dialog_content = "¿No estaba el Ingeniero hablando con Ulysses? ¿Cómo supo acerca de PlayerName?",
  ui_story_1020_10200901_60_dialog_content = "Ven a casa, Caelestite.",
  ui_story_1020_10200901_61_dialog_content = "Creo que escucho su voz...",
  ui_story_1020_10200901_62_dialog_content = "¿De dónde viene?",
  ui_story_1020_10200901_63_dialog_content = "Desde dentro de mi cabeza...",
  ui_story_1020_10200901_64_dialog_content = "Entonces, esas visiones que vi fueron realmente hechas por poderes psíquicos después de todo...",
  ui_story_1020_10200901_65_dialog_content = "Ven a casa, Caelestite.",
  ui_story_1020_10200901_66_dialog_content = "... ¿Quién eres tú?",
  ui_story_1020_10200901_67_dialog_content = "Ustedes me llaman el Ingeniero.",
  ui_story_1020_10200901_68_dialog_content = "Eres un Eclipsite... ¿Y estás controlando a los súper soldados de Illumina a través de esta máquina por orden de Eclipse, verdad?",
  ui_story_1020_10200901_69_dialog_content = "No.",
  ui_story_1020_10200901_70_dialog_content = "... Pero tú robaste el núcleo de Guardian One, lo que permitió a los Eclipsites invadir Gannon City.",
  ui_story_1020_10200901_71_dialog_content = "Eso me pertenece en primer lugar.",
  ui_story_1020_10200901_72_dialog_content = "Como tú.",
  ui_story_1020_10200901_73_dialog_content = "... Soy un Caelestite. Nací en Eraveil.",
  ui_story_1020_10200901_74_dialog_content = "¿De dónde vinieron los Caelestitas?",
  ui_story_1020_10200901_75_dialog_content = "¿Qué le hiciste a mi pueblo... a mí?",
  ui_story_1020_10200901_76_dialog_content = "Ven a casa, Caelestite.",
  ui_story_1020_10200901_77_dialog_content = "Continúa la noble causa conmigo.",
  ui_story_1020_10200901_78_dialog_content = "¿Causa noble? ¡El Celestita no va a ninguna parte!",
  ui_story_1020_10200901_79_dialog_content = "¿De qué estás hablando, Ulysses?",
  ui_story_1020_10200901_80_dialog_content = "...",
  ui_story_1020_10200901_81_dialog_content = "¿Él también puede enlazar con tu mente?",
  ui_story_1020_10200901_82_dialog_content = "Él y tú no son lo mismo.",
  ui_story_1020_10200901_83_dialog_content = "Te diré toda la verdad que estás muriendo por saber.",
  ui_story_1020_10200901_84_dialog_content = "Sobre las antiguas batallas de la Zona Oscura, el nivel de atraque de los Colosos, el hogar de los Caelestitas...",
  ui_story_1020_10200901_85_dialog_content = "Y los compatriotas que has estado anhelando.",
  ui_story_1020_10200901_86_dialog_content = "!",
  ui_story_1020_10200901_87_dialog_content = "<color=#e8d9bb>Bip—Bip bip—Bip bip bip—</color>",
  ui_story_1020_10200901_88_dialog_content = "La pulsera de Algol está reportando una amenaza.",
  ui_story_1020_10200901_89_dialog_content = "El patio de servicio de Illumina...",
  ui_story_1020_10200901_90_dialog_content = "PlayerName, el Coloso está cortando la conexión a mi terminal!",
  ui_story_1020_10200901_91_dialog_content = "Soroz...",
  ui_story_1020_10200901_92_dialog_content = "¿Es esto tu obra?",
  ui_story_1020_10200901_93_dialog_content = "Activé el Colossus para ti.",
  ui_story_1020_10200901_94_dialog_content = "¡No... No!",
  ui_story_1020_10200901_95_dialog_content = "<color=#e8d9bb>Ruido sordo-</color>",
  ui_story_1020_10200901_96_dialog_content = "¡PlayerName!",
  ui_story_1020_10200901_97_dialog_content = "¡Oh! Ha salido.",
  ui_story_1020_10200901_98_dialog_content = "Mantén el ritmo, Vivian. Es peligroso allí afuera ahora mismo.",
  ui_story_1020_10200901_99_dialog_content = "¡Entendido!",
  ui_story_1020_10200901_100_dialog_content = "¡El Caelestite no va a ninguna parte! Yo soy tu objetivo...",
  ui_story_1020_10200901_101_dialog_content = "¡Basta ya de tonterías, Ulysses!",
  ui_story_1020_10200901_102_dialog_content = "¡Déjame ir! ¡Déjame encargarme de él!",
  ui_story_1020_10200901_103_dialog_content = "<color=#e8d9bb>Clic, clic-</color>",
  ui_story_1020_10200901_104_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10200901_105_dialog_content = "¡Detente, Ulysses!",
  ui_story_1020_10200901_106_dialog_content = "¡Rugido!",
  ui_story_1020_10200901_107_dialog_content = "Después de todos estos años... lo hice...",
  ui_story_1020_10200901_108_dialog_content = "¿Son estos suficientes?",
  ui_story_1020_10200901_109_dialog_content = "¡Hay más! ¡Miles más! Súper soldados mil veces más fuertes que los Eclipsites!",
  ui_story_1020_10200901_110_dialog_content = "<color=#e8d9bb>Buzz Buzz-</color>",
  ui_story_1020_10200901_111_dialog_content = "... Boo, boo...",
  ui_story_1020_10200901_112_dialog_content = "\"Una última vez\"",
  ui_story_1020_10200901_113_dialog_content = "¡Oh no, va a ordenar a los súper soldados que ataquen! Necesitamos tener Ulysses bajo control!",
  ui_story_1020_10200901_114_dialog_content = "¡Déjame Ulysses a mí!",
  ui_story_1020_10200901_115_dialog_content = "<color=#e8d9bb>Bip-bip-bip-</color>",
  ui_story_1020_10200901_116_dialog_content = "¡Argh! Fue un dolor crear otro módulo de defensa también!",
  ui_story_1020_10200901_117_dialog_content = "¡Rugido!",
  ui_story_1020_10201001_1_dialog_content = "¡PlayerName!",
  ui_story_1020_10201001_2_dialog_content = "Todavía nos queda un largo camino desde aquí hasta el patio de servicio. ¡Es demasiado peligroso allá afuera!",
  ui_story_1020_10201001_3_dialog_content = "... ¡No dejaré que Soroz se escape!",
  ui_story_1020_10201001_4_dialog_content = "¿Cómo puede Soroz irse sin tu orden?",
  ui_story_1020_10201001_5_dialog_content = "...",
  ui_story_1020_10201001_6_dialog_content = "Lo vi...",
  ui_story_1020_10201001_7_dialog_content = "¿Qué es?",
  ui_story_1020_10201001_8_dialog_content = "Vi lo que Ulysses vio antes...",
  ui_story_1020_10201001_9_dialog_content = "Hay una voz... El Ingeniero nos está diciendo a mí y a Soroz que vayamos a casa...",
  ui_story_1020_10201001_10_dialog_content = "PlayerName...",
  ui_story_1020_10201001_11_dialog_content = "No fue fácil para mí encontrar a Soroz de nuevo, y solo estuvimos juntos unos pocos días...",
  ui_story_1020_10201001_12_dialog_content = "¡Lo juro... Juro que no dejaré que esto suceda!",
  ui_story_1020_10201001_13_dialog_content = "Pero, ¿qué puedo hacer? Tiene que haber algo...",
  ui_story_1020_10201001_14_option_content = "Vínculo Telepático",
  ui_story_1020_10201001_15_dialog_content = "...",
  ui_story_1020_10201001_16_option_content = "Vínculo Telepático",
  ui_story_1020_10201001_17_dialog_content = "...",
  ui_story_1020_10201001_18_dialog_content = "¿Ya se fue Soroz?",
  ui_story_1020_10201001_19_dialog_content = "El momento en que salí del laboratorio hoy más temprano, sentí algo indescriptible.",
  ui_story_1020_10201001_20_dialog_content = "Vi un rayo de luz sobre una estructura masiva, llevando todas mis esperanzas con él...",
  ui_story_1020_10201001_21_dialog_content = "Y por alguna razón, sentí que Soroz despegaría desde allí...",
  ui_story_1020_10201001_22_dialog_content = "Yo... No sabía por qué me sentía así en ese momento...",
  ui_story_1020_10201001_23_dialog_content = "Después de eso y los sueños que vi, debería haberlo descubierto antes...",
  ui_story_1020_10201001_24_option_content = "Vínculo Telepático",
  ui_story_1020_10201001_25_dialog_content = "...",
  ui_story_1020_10201001_26_option_content = "Enlace Telepático",
  ui_story_1020_10201001_27_dialog_content = "...",
  ui_story_1020_10201001_28_option_content = "Enlace Telepático",
  ui_story_1020_10201001_29_dialog_content = "...",
  ui_story_1020_10201001_30_dialog_content = "¡Argh!",
  ui_story_1020_10201001_31_dialog_content = "¡Para ahora, PlayerName!",
  ui_story_1020_10201001_32_dialog_content = "¡Has usado demasiado tus poderes psíquicos hoy y te ves enfermo!",
  ui_story_1020_10201001_33_dialog_content = "Ya perdí contacto con Vice... No sé qué haré si también pierdo a Soroz...",
  ui_story_1020_10201001_34_dialog_content = "... ¿A dónde va Soroz? ¿Qué quiere el Ingeniero con eso?",
  ui_story_1020_10201001_35_dialog_content = "Siempre podrías preguntarme esas preguntas—",
  ui_story_1020_10201001_36_dialog_content = "¡Desenvaina!",
  ui_story_1020_10201001_37_dialog_content = "¡Vivian!",
  ui_story_1020_10201001_38_dialog_content = "... Figerald?",
  ui_story_1020_10201001_39_dialog_content = "Demasiado débil, no, demasiado tierno, diría yo...",
  ui_story_1020_10201001_40_dialog_content = "¡Tan tierno que te compadezco!",
  ui_story_1020_10201001_41_dialog_content = "Jejeje, no hay nada como el sabor de la desesperación cuando una persona pierde algo que realmente aprecia.",
  ui_story_1020_10201001_42_dialog_content = "... ¿Sabías que Soroz se iría volando?",
  ui_story_1020_10201001_43_dialog_content = "Bueno, ¿por qué no me preguntas qué le he hecho a Soroz?",
  ui_story_1020_10201001_44_dialog_content = "¡Tú!",
  ui_story_1020_10201001_45_dialog_content = "Espera, PlayerName, algo no está bien con él.",
  ui_story_1020_10201001_46_dialog_content = "Estaba inmovilizado en una celda pero aún así logró escapar...",
  ui_story_1020_10201001_47_dialog_content = "¿Todavía no lo crees? Su poder hace todo esto posible.",
  ui_story_1020_10201001_48_dialog_content = "Esas cadenas me ataron, en efecto. Pero enseñé a la escoria que me confinó a apreciar la belleza de la desesperación en su último momento.",
  ui_story_1020_10201001_49_dialog_content = "Desafortunadamente, el sabor de su sufrimiento ni siquiera se comparaba con el de los Celestitas.",
  ui_story_1020_10201001_50_dialog_content = "Jajaja, ahora elige, ¡Caelestite! ¿Morirás una muerte sin sentido como tus inútiles compañeros?",
  ui_story_1020_10201001_51_dialog_content = "¿O te convertirás en mi regalo para el supremo gobernante y presenciarás su gloria a mi lado?",
  ui_story_1020_10201001_52_dialog_content = "¡Un Celestita nunca moriría una muerte sin sentido! ¿Dónde está el Ingeniero?",
  ui_story_1020_10201001_53_dialog_content = "¡Jajaja! ¡Entonces parece que has elegido la última opción!",
  ui_story_1020_10201001_54_dialog_content = "En ese caso, no hay necesidad de perdonar al tonto a tu lado.",
  ui_story_1020_10201001_55_dialog_content = "¡No te atrevas a lastimar a PlayerName!",
  ui_story_1020_10201001_56_dialog_content = "¿Así que deseas experimentar el poder de mi Darkflow? Deberías saber, nació de la sangre de los Aurorians caídos.",
  ui_story_1020_10201001_57_dialog_content = "Ponte detrás de mí, PlayerName!",
  ui_story_1020_10201001_58_dialog_content = "Tu resistencia no es nada menos que ridícula...",
  ui_story_1020_10201001_59_dialog_content = "Agradece que aún puedes sentir dolor. Cuando llegue su glorioso momento, él te liberará de tu sufrimiento.",
  ui_story_1020_10201001_60_dialog_content = "Cuervo, te ofrezco la sangre de un Caelestita!",
  ui_story_1020_10201001_61_dialog_content = "¡No dejaré que lastimes a PlayerName, Eclipsite!",
  ui_story_1020_10201001_62_dialog_content = "¡Menos mal que llegué justo a tiempo!",
  ui_story_1020_10201001_63_dialog_content = "PlayerName! Oficial Vivian! ¿Alguno de ustedes está herido?",
  ui_story_1020_10201001_64_dialog_content = "¿Sean? ¡Sal de aquí! ¡Ese Darkflow es extremadamente peligroso!",
  ui_story_1020_10201001_65_dialog_content = "Lo sé, pero tengo que protegerte, PlayerName!",
  ui_story_1020_10201001_66_dialog_content = "¿Bueno? No te decepcioné, ¿verdad?",
  ui_story_1020_10201001_67_dialog_content = "¡Para nada! ¿Cómo pudiste resistir su ataque, Sean?",
  ui_story_1020_10201001_68_dialog_content = "¡Ja! ¡Es porque soy tan buen luchador como Yingel o Axelia!",
  ui_story_1020_10201001_69_dialog_content = "Solo resulta que también soy un auroriano de carne y hueso.",
  ui_story_1020_10201001_70_dialog_content = "Jefe de Personal, PlayerName, ¡déjame este Eclipsite a mí!",
  ui_story_1020_10201001_71_dialog_content = "¡Ten cuidado, Sean! Él es muy astuto. Te cubriremos eliminando a otros Eclipsites detrás de ti!",
  ui_story_1020_10201001_72_dialog_content = "¡Entendido!",
  ui_story_1020_10201001_73_dialog_content = "Ah... ¡Tan tierno! ¡Tan fresco!",
  ui_story_1020_10201101_1_dialog_content = "Gusanos... ¿De verdad creen que pueden detenerme?",
  ui_story_1020_10201101_2_dialog_content = "Debo completar mi misión esta vez, o de lo contrario—",
  ui_story_1020_10201101_3_dialog_content = "Tú, allí, con las orejas largas y peludas... ¿Cómo pudiste sobrevivir a mi ataque de Darkflow completamente ileso?",
  ui_story_1020_10201101_4_dialog_content = "¿Y? ¡No dejaré que lastimes a mis amigos!",
  ui_story_1020_10201101_5_dialog_content = "Je, tu mirada lo explica todo... Por eso sigues vivo después de que el resto de la bestia fuera aniquilado.",
  ui_story_1020_10201101_6_dialog_content = "¿Qué estás diciendo?",
  ui_story_1020_10201101_7_dialog_content = "Yo, Figerald, tuve el distinguido honor de participar en la exterminación masiva de tus antepasados. Fue mi contribución más gloriosa a nuestro supremo gobernante.",
  ui_story_1020_10201101_8_dialog_content = "Sin embargo, parece que al hacer las paces con los Aurorianos, tu tipo perezoso y traicionero ha encontrado una forma de sobrevivir.",
  ui_story_1020_10201101_9_dialog_content = "De alguna manera, no eres diferente a las cucarachas. ¿No estás de acuerdo?",
  ui_story_1020_10201101_10_dialog_content = "¡Cállate! ¡No te permitiré hablar de Sean de esa manera!",
  ui_story_1020_10201101_11_dialog_content = "¿Te estás enfadando? Quieres matarme ahora mismo, ¿verdad?",
  ui_story_1020_10201101_12_dialog_content = "Pero aún deseas saber a dónde fue Soroz, ¿verdad? No solo Soroz, sino también esa inútil chica Illuminan.",
  ui_story_1020_10201101_13_dialog_content = "No te preocupes, estoy seguro de que Anemone le dio una muerte espléndidamente horrorosa.",
  ui_story_1020_10201101_14_dialog_content = "Vice... ¿Ella se encontró con Anemone? ¡Dime qué le pasó!",
  ui_story_1020_10201101_15_dialog_content = "¿Oh? Veamos si puedo recordar...",
  ui_story_1020_10201101_16_dialog_content = "¿Dónde está el Ingeniero? ¿A dónde fue Soroz? ¡Dime!",
  ui_story_1020_10201101_17_dialog_content = "...",
  ui_story_1020_10201101_18_dialog_content = "¡Oh poderoso y supremo maestro, por favor no me abandones!",
  ui_story_1020_10201101_19_dialog_content = "...",
  ui_story_1020_10201101_20_dialog_content = "\"¿Maestría\"? ¿A quién está hablando?",
  ui_story_1020_10201101_21_dialog_content = "El Ingeniero debe estar comunicándose con él a través de su conciencia en este momento...",
  ui_story_1020_10201101_22_dialog_content = "Este podría ser el momento perfecto para buscar pistas.",
  ui_story_1020_10201101_23_dialog_content = "¿Qué haces aquí, PlayerName?",
  ui_story_1020_10201101_24_option_content = "¡Potencia de fuerza!",
  ui_story_1020_10201101_25_dialog_content = "(¡Argh! Este dolor es insoportable...)",
  ui_story_1020_10201101_26_dialog_content = "(¡Pero no hay otra manera!)",
  ui_story_1020_10201101_27_dialog_content = "(Necesito saber qué pasó con Vice y Soroz...)",
  ui_story_1020_10201101_28_dialog_content = "(Necesito encontrar las respuestas...)",
  ui_story_1020_10201101_29_dialog_content = "Tu cuerpo se ha vuelto frágil y grotesco.",
  ui_story_1020_10201101_30_dialog_content = "¡No me importa! Mientras lleve tu marca, esos humildes Aurorianos y Eclipsitas se inclinarán ante mí.",
  ui_story_1020_10201101_31_dialog_content = "¿Inclinarme ante ti? ¿Y qué pasa conmigo entonces?",
  ui_story_1020_10201101_32_dialog_content = "¡T-Tiembla ante tu poder, mi señor! Permíteme servir como tus alas, ¡y dedicaré toda mi vida a ti!",
  ui_story_1020_10201101_33_dialog_content = "¿Estás dispuesto a ponerte este anillo como reconocimiento de tu nuevo estatus?",
  ui_story_1020_10201101_34_dialog_content = "Un anillo...",
  ui_story_1020_10201101_35_dialog_content = "¡Estoy dispuesto! ¡Este anillo es un símbolo de tu gracia, un regalo que solo las almas más nobles pueden recibir! ¡Le da sentido a mi existencia!",
  ui_story_1020_10201101_36_dialog_content = "¡Me arrodillo ante ti en gratitud, supremo gobernante!",
  ui_story_1020_10201101_37_dialog_content = "Muy bien.",
  ui_story_1020_10201101_38_dialog_content = "P-Por favor, concédeme... ¡Arrrrrrgh!",
  ui_story_1020_10201101_39_dialog_content = "Mi... ¡Mi cabeza! El dolor... ¡No puedo soportarlo más! Soberano supremo... Por favor, sálvame...",
  ui_story_1020_10201101_40_dialog_content = "(Esta es una pieza de los recuerdos del pasado de Figerald, y esa voz de ahora era el Ingeniero...)",
  ui_story_1020_10201101_41_dialog_content = "(Un Espectro de Eclipse se pone voluntariamente ese anillo parecido a una grillete...)",
  ui_story_1020_10201101_42_dialog_content = "(...)",
  ui_story_1020_10201101_43_dialog_content = "(No sabía que podía usar mis poderes para ver tan lejos en el pasado... ¿Sucedió esto debido al sueño del Ingeniero?)",
  ui_story_1020_10201101_44_dialog_content = "(¿O es porque Algol me entrenó para vincularme exitosamente con Bool?)",
  ui_story_1020_10201101_45_dialog_content = "(Si quiero aprender sobre la ubicación de Vice y Soroz, necesitaré adentrarme en sus recuerdos más recientes...)",
  ui_story_1020_10201101_46_option_content = "Alcance Telepático—",
  ui_story_1020_10201101_47_dialog_content = "(Urgh, este Darkflow... Se siente tan mal como cuando conecté mentes con Bool por primera vez.)",
  ui_story_1020_10201101_48_dialog_content = "(Pero ahora que he experimentado algo así, creo que puedo manejar esto...)",
  ui_story_1020_10201101_49_dialog_content = "(¿Eh? ¿Es esta la Zona Oscura?)",
  ui_story_1020_10201101_50_dialog_content = "(Este pozo es enorme, y la fisura parece extenderse aún más lejos...)",
  ui_story_1020_10201101_51_dialog_content = "(¿Podrían ser estas las ruinas de la antigua guerra que mencionó el Ingeniero?)",
  ui_story_1020_10201101_52_dialog_content = "(¿Qué diablos pasó aquí? ¿Cómo terminó este lugar en un estado tan terrible?)",
  ui_story_1020_10201101_53_dialog_content = "(No veo ninguna señal de un Colossus cerca...)",
  ui_story_1020_10201101_54_option_content = "Alcance Telepático—",
  ui_story_1020_10201101_55_dialog_content = "(¿Es eso... un montón de restos de Coloso?)",
  ui_story_1020_10201101_56_dialog_content = "(Uno, dos, tres...)",
  ui_story_1020_10201101_57_dialog_content = "(...)",
  ui_story_1020_10201101_58_dialog_content = "(El lugar de atraque de los Colossus...)",
  ui_story_1020_10201101_59_dialog_content = "(Una playa plana y desolada... Es tan diferente al Obelisco del Retorno.)",
  ui_story_1020_10201101_60_dialog_content = "(¿Qué les pasó? No queda nada de ellos excepto estructuras desgastadas como huesos de dragón...)",
  ui_story_1020_10201101_61_dialog_content = "(¿Hace cuánto tiempo fue esto? No puedo sentir ni las más débiles señales de vida aquí...)",
  ui_story_1020_10201101_62_dialog_content = "(Eso es correcto, el núcleo de Guardian One...)",
  ui_story_1020_10201101_63_dialog_content = "(Quizás las coordenadas que vi en los datos de Soroz sean una pista...)",
  ui_story_1020_10201101_64_dialog_content = "(Coordenadas... Pilares brillantes...)",
  ui_story_1020_10201101_65_option_content = "Alcance Telepático—",
  ui_story_1020_10201101_66_dialog_content = "(¡Eso es!)",
  ui_story_1020_10201101_67_dialog_content = "(No hay error. Esto es exactamente lo que vi en los recuerdos de Ulysses...)",
  ui_story_1020_10201101_68_dialog_content = "(Estos pilares brillantes son el núcleo de Guardian One. Ahora puedo verlos claramente...)",
  ui_story_1020_10201101_69_dialog_content = "(La piedra está subiendo. Debe haber algo allá arriba...)",
  ui_story_1020_10201101_70_dialog_content = "¿Estás preparado?",
  ui_story_1020_10201101_71_dialog_content = "Sí. El último <color=#FFB400>Anillo de Conducción</color> está en la mano.",
  ui_story_1020_10201101_72_dialog_content = "Muy bien.",
  ui_story_1020_10201101_73_dialog_content = "Leí su honorable nombre y espero que lo mire—",
  ui_story_1020_10201101_74_dialog_content = "Esperamos humildemente su llegada—",
  ui_story_1020_10201101_75_dialog_content = "¿Quién eres?",
  ui_story_1020_10201101_76_dialog_content = "...",
  ui_story_1020_10201101_77_dialog_content = "Una chica Illuminan y un científico.",
  ui_story_1020_10201101_78_dialog_content = "Illumina.",
  ui_story_1020_10201101_79_dialog_content = "Ese cuervo inútil también está en Illumina.",
  ui_story_1020_10201101_80_dialog_content = "Illumina... Cómo extraño ese nombre.",
  ui_story_1020_10201101_81_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10201101_82_dialog_content = "(Esa escena de hace un momento... No fue un sueño después de todo...)",
  ui_story_1020_10201101_83_dialog_content = "(Pero esta vez, Forsakin está aquí en lugar de Vice...)",
  ui_story_1020_10201101_84_dialog_content = "(Los que están a su lado... ¿Son esos Fantasmas?)",
  ui_story_1020_10201101_85_dialog_content = "¡E-Eres tú... El gobernante supremo!",
  ui_story_1020_10201101_86_dialog_content = "Tu fiel servidor, Figerald, ha estado arrodillado aquí todo este tiempo, esperando tu llegada.",
  ui_story_1020_10201101_87_dialog_content = "No has logrado nada.",
  ui_story_1020_10201101_88_dialog_content = "¡Te he servido bien, maestro! Fui yo quien lideró la exterminación de las bestias—",
  ui_story_1020_10201101_89_dialog_content = "Un asunto de hace siglos ahora.",
  ui_story_1020_10201101_90_dialog_content = "En el momento que lo necesite, tomaré de vuelta todo lo que te he otorgado.",
  ui_story_1020_10201101_91_dialog_content = "Mi señor... Nunca harías tal cosa, ¿verdad? ¡Sirvo como tus alas, creadas por tus propias manos!",
  ui_story_1020_10201101_92_dialog_content = "Te liberaré de tus restricciones.",
  ui_story_1020_10201101_93_dialog_content = "Demuestra tu valía ante Eclipse trayéndome la Caelestita.",
  ui_story_1020_10201101_94_dialog_content = "Todavía tengo suficiente energía para activar el Colossus.",
  ui_story_1020_10201101_95_dialog_content = "<color=#e8d9bb>Sonido metálico-</color>",
  ui_story_1020_10201101_96_dialog_content = "...",
  ui_story_1020_10201101_97_dialog_content = "¡T-Tiemblo ante ti! ¡Nunca me atrevería a ir en contra de tus deseos!",
  ui_story_1020_10201101_98_dialog_content = "(...)",
  ui_story_1020_10201101_99_dialog_content = "(El Ingeniero vino a la ciudad de Gannon para llamar a los Wraiths de vuelta...)",
  ui_story_1020_10201101_100_dialog_content = "(Y él quiere llevarme a mí y a Soroz con él...)",
  ui_story_1020_10201101_101_dialog_content = "¿Te gusta eso?",
  ui_story_1020_10201101_102_dialog_content = "¿Estás... observándome?",
  ui_story_1020_10201101_103_dialog_content = "Siempre.",
  ui_story_1020_10201101_104_dialog_content = "Te concedí las visiones. Deberías agradecerme por mostrarte lo espectacular en el Campo de Batalla de la Espira.",
  ui_story_1020_10201101_105_dialog_content = "El Campo de Batalla de la Cumbre... ¿Entonces realmente sucedió?",
  ui_story_1020_10201101_106_dialog_content = "Solo la verdad tiene valor.",
  ui_story_1020_10201101_107_dialog_content = "Esa grieta era una vez mi hogar, pero la guerra me destrozó.",
  ui_story_1020_10201101_108_dialog_content = "Busqué los fragmentos para recomponer mi base, y luego reinicié mi corazón.",
  ui_story_1020_10201101_109_dialog_content = "Esos Colosos agotaron sus núcleos por mi causa.",
  ui_story_1020_10201101_110_dialog_content = "... ¿Va a ser Soroz tu próximo sacrificio también? ¿Estás intentando destruir el mundo?",
  ui_story_1020_10201101_111_dialog_content = "No, no lo hago.",
  ui_story_1020_10201101_112_dialog_content = "Llegarás a entender. Tú y yo somos iguales.",
  ui_story_1020_10201101_113_dialog_content = "...",
  ui_story_1020_10201101_114_dialog_content = "... ¿Dónde está Soroz?",
  ui_story_1020_10201101_115_dialog_content = "... ¿Y qué pasó con Vice?",
  ui_story_1020_10201101_116_dialog_content = "...",
  ui_story_1020_10201101_117_dialog_content = "(... Se está oscureciendo cada vez más...)",
  ui_story_1020_10201101_118_dialog_content = "Recuerda, la luz te cegará. Solo puedes ver la verdad en la oscuridad.",
  ui_story_1020_10201101_119_dialog_content = "Acepta la oscuridad, déjala entrar y permítele ser tu fuerza.",
  ui_story_1020_10201101_120_dialog_content = "¡Me niego!",
  ui_story_1020_10201101_121_dialog_content = "Permite que la oscuridad sea tu fuerza.",
  ui_story_1020_10201101_122_dialog_content = "¡No llevaré tus grilletes!",
  ui_story_1020_10201101_123_dialog_content = "(A este paso, la oscuridad realmente va a consumirme...)",
  ui_story_1020_10201102_1_dialog_content = "<color=#e8d9bb>Chapoteo—</color>",
  ui_story_1020_10201102_2_dialog_content = "(Escucho un piano en la oscuridad...)",
  ui_story_1020_10201102_3_dialog_content = "(Este lugar... Es tan brillante...)",
  ui_story_1020_10201102_4_dialog_content = "(Estas ondas de luz fluyentes parecen reflejarse en la superficie de un lago...)",
  ui_story_1020_10201102_5_dialog_content = "(¿Es esta... la aurora sobre Northland?)",
  ui_story_1020_10201102_6_dialog_content = "(¿Eh? ¿Qué es eso...)",
  ui_story_1020_10201102_7_dialog_content = "PlayerName.",
  ui_story_1020_10201102_8_dialog_content = "¿Soroz? ¿Eres tú realmente? ¡Soroz!",
  ui_story_1020_10201102_9_dialog_content = "Escuché un piano hace un segundo y luego tu voz, PlayerName.",
  ui_story_1020_10201102_10_dialog_content = "¿Un piano? ¡Yo también lo escuché! ¡No esperaba alcanzarte así!",
  ui_story_1020_10201102_11_dialog_content = "¿Dónde estás ahora mismo, Soroz?",
  ui_story_1020_10201102_12_dialog_content = "...",
  ui_story_1020_10201102_13_dialog_content = "No lo sé.",
  ui_story_1020_10201102_14_dialog_content = "...",
  ui_story_1020_10201102_15_dialog_content = "Él te dio la orden, ¿no es así?",
  ui_story_1020_10201102_16_dialog_content = "...",
  ui_story_1020_10201102_17_dialog_content = "Puedes simplemente ignorarlo... ¿no puedes Soroz?",
  ui_story_1020_10201102_18_dialog_content = "...",
  ui_story_1020_10201102_19_dialog_content = "Lo siento, PlayerName.",
  ui_story_1020_10201102_20_dialog_content = "Los Caelestitas soñaron con la libertad toda su vida...",
  ui_story_1020_10201102_21_dialog_content = "Los datos fugaces me ofrecieron un vistazo de Caelestites y Colosos antes de conocerte...",
  ui_story_1020_10201102_22_dialog_content = "Vi innumerables generaciones de Caelestites y Colosos luchando por liberarse de las cadenas.",
  ui_story_1020_10201102_23_dialog_content = "Esta vez...",
  ui_story_1020_10201102_24_dialog_content = "Creo que he fallado.",
  ui_story_1020_10201102_25_dialog_content = "Soroz... Por favor, no te vayas...",
  ui_story_1020_10201102_26_dialog_content = "Podemos liberarnos juntos de estos grilletes, ¿no es así?",
  ui_story_1020_10201102_27_dialog_content = "...",
  ui_story_1020_10201102_28_dialog_content = "En este momento, soy tanto Soroz como Naviduz...",
  ui_story_1020_10201102_29_dialog_content = "Así como Solituz, Probarduz, Vocoduz, Spanduz...",
  ui_story_1020_10201102_30_dialog_content = "Lo que puedo hacer es proteger a mi Navegante lo mejor que pueda, como lo hicieron mis predecesores en su momento.",
  ui_story_1020_10201102_31_dialog_content = "En mi tiempo contigo, cada vuelo que tomamos fue el mejor momento de mi vida.",
  ui_story_1020_10201102_32_dialog_content = "Si puedo romper los grilletes, nos volveremos a encontrar.",
  ui_story_1020_10201102_33_dialog_content = "Soroz...",
  ui_story_1020_10201102_34_dialog_content = "Independientemente de cuántas señales reciba...",
  ui_story_1020_10201102_35_dialog_content = "Mientras todavía tenga un \"corazón\", solo escuchará tu voz, PlayerName.",
  ui_story_1020_10201102_36_dialog_content = "...",
  ui_story_1020_10201102_37_dialog_content = "Soroz...",
  ui_story_1020_10201102_38_dialog_content = "¿Soroz?",
  ui_story_1020_10201102_39_dialog_content = "PlayerName...",
  ui_story_1020_10201102_40_option_content = "Enlace Telepático",
  ui_story_1020_10201102_41_dialog_content = "...",
  ui_story_1020_10201102_42_option_content = "Enlace Telepático—",
  ui_story_1020_10201102_43_dialog_content = "...",
  ui_story_1020_10201102_44_option_content = "¡Enlace Telepático!",
  ui_story_1020_10201102_45_dialog_content = "...",
  ui_story_1020_10201102_46_option_content = "¡Enlace Telepático!",
  ui_story_1020_10201102_47_dialog_content = "¡PlayerName!",
  ui_story_1020_10201102_48_dialog_content = "...",
  ui_story_1020_10201102_49_dialog_content = "No puedo...",
  ui_story_1020_10201102_50_dialog_content = "¡Ya no puedo sentir a Soroz!",
  ui_story_1020_10201102_51_dialog_content = "Por fin estás despierto, PlayerName. ¿Estás bien?",
  ui_story_1020_10201102_52_dialog_content = "Me duele verte así, PlayerName.",
  ui_story_1020_10201102_53_dialog_content = "Fue espeluznante la forma en que murmurabas para ti mismo. Afortunadamente, Sean sometió a Figerald para que pudieras recuperar tus sentidos!",
  ui_story_1020_10201102_54_dialog_content = "¡En realidad, todos ayudaron en eso!",
  ui_story_1020_10201102_55_dialog_content = "¿...?",
  ui_story_1020_10201102_56_dialog_content = "Lo vimos desaparecer en una nube de Darkflow con nuestros propios ojos.",
  ui_story_1020_10201102_57_dialog_content = "Solo Sean podría resistir ese tipo de Darkflow.",
  ui_story_1020_10201102_58_dialog_content = "(¿Todos... realmente lograron vencer a Figerald?)",
  ui_story_1020_10201102_59_dialog_content = "(Justo cuando estaba a punto de caer en la oscuridad infinita, escuché un piano y vi la superficie brillante de un lago... ¿Qué fue eso?)",
  ui_story_1020_10201102_60_dialog_content = "¿Qué pasó, PlayerName? Usaste el Impulso Forzado en Figerald e hiciste ruidos extraños...",
  ui_story_1020_10201102_61_dialog_content = "Pude sentir Soroz...",
  ui_story_1020_10201102_62_dialog_content = "Soroz? ¿Dónde está?",
  ui_story_1020_10201102_63_dialog_content = "Soroz se fue para protegerme...",
  ui_story_1020_10201102_64_dialog_content = "...",
  ui_story_1020_10201102_65_dialog_content = "¿Podemos ir a Soroz más tarde, PlayerName? Tenemos que encontrarnos con el Gran Mariscal.",
  ui_story_1020_10201102_66_dialog_content = "Es muy peligroso para ti estar aquí solo. Si esos tres niños no hubieran llegado a tiempo, Figerald nos habría capturado.",
  ui_story_1020_10201102_67_dialog_content = "Gracias a todos...",
  ui_story_1020_10201102_68_dialog_content = "Vamos. Cuando esta crisis termine, recuperaremos Soroz seguro!",
  ui_story_1020_10201102_69_dialog_content = "Sí...",
  ui_story_1020_10201102_70_dialog_content = "(Vi al Ingeniero a través de la mente de Figerald...)",
  ui_story_1020_10201102_71_dialog_content = "(Debo encontrar pistas...)",
  ui_story_1020_10201102_72_dialog_content = "Eso estuvo demasiado cerca, PlayerName. Si esos tres niños no hubieran aparecido a tiempo, probablemente—",
  ui_story_1020_10201102_73_dialog_content = "¡Lo sé...!",
  ui_story_1020_10201102_74_dialog_content = "¡Ve a encontrarte con el Gran Mariscal ahora, PlayerName!",
  ui_story_1020_10201201_1_dialog_content = "¡Booo!",
  ui_story_1020_10201201_2_dialog_content = "Entonces Bool está diciendo que... Supongo que el módulo de defensa debería funcionar esta vez?",
  ui_story_1020_10201201_3_dialog_content = "Quizás. Jaja... ¡Jajajajaja!",
  ui_story_1020_10201201_4_dialog_content = "Uf, todavía me duele desde los hombros hasta las puntas de los dedos, pero ya está hecho-",
  ui_story_1020_10201201_5_dialog_content = "Gracias a la ayuda de todos, pude terminarlo mucho más rápido de lo anticipado... Aun así, no esperaba que una batalla de pura inteligencia fuera tan difícil...",
  ui_story_1020_10201201_6_dialog_content = "¡Nada es fácil cuando se trata de esta máquina antigua!",
  ui_story_1020_10201201_7_dialog_content = "<color=#e8d9bb>Bip-bip-bip-</color>",
  ui_story_1020_10201201_8_dialog_content = "¿Eh? El nuevo programa sigue reportando errores...",
  ui_story_1020_10201201_9_dialog_content = "¿El Ingeniero sigue trabajando en nuestra contra de alguna manera? ¿O podría ser que el módulo del Guardián tiene problemas desde el principio?",
  ui_story_1020_10201201_10_dialog_content = "<size=45>¡Boo, boo, boo!</size>",
  ui_story_1020_10201201_11_dialog_content = "Veamos... Veamos...",
  ui_story_1020_10201201_12_dialog_content = "¿Eh? ¿Dónde está Ulysses? ¡Necesito obtener más respuestas de él! Quién sabe qué ha hecho con esta máquina a lo largo de los años...",
  ui_story_1020_10201201_13_dialog_content = "¿Todavía necesito un núcleo capaz de manejar cálculos aún más complejos?",
  ui_story_1020_10201201_14_dialog_content = "¿Boo?",
  ui_story_1020_10201201_15_dialog_content = "Eso pareció ser demasiado para que Ulysses lo asimilara. Sus ojos han estado cerrados y nunca se movió.",
  ui_story_1020_10201201_16_dialog_content = "Reinhardt, viendo que la máquina es estable, y los super-soldados ya no son agresivos...",
  ui_story_1020_10201201_17_dialog_content = "Debemos aprovechar la oportunidad para reunir a los super-soldados restantes y prevenir más ataques.",
  ui_story_1020_10201201_18_dialog_content = "Estoy de acuerdo. Y de todos modos son nuestros soldados... Quizás Black Umbrella Laboratories encuentre una forma de tratarlos.",
  ui_story_1020_10201201_19_dialog_content = "... En su origen, parece que todos están siendo controlados por el prototipo. Me temo que no tenemos más opción que esperar a que el Dr. Algol termine de construir un nuevo módulo.",
  ui_story_1020_10201201_20_dialog_content = "¿Qué necesita que hagamos ahora, Dr. Algol?",
  ui_story_1020_10201201_21_dialog_content = "Lidiar con estos súper soldados no será fácil.",
  ui_story_1020_10201201_22_dialog_content = "Probablemente estos cables se extiendan aún más profundo de lo que podemos imaginar. Nos llevaría semanas desenterrarlos todos.",
  ui_story_1020_10201201_23_dialog_content = "Por no mencionar que hay otros riesgos involucrados... Parece que recuperar el módulo del Guardián y usarlo para reparar el núcleo no será suficiente...",
  ui_story_1020_10201201_24_dialog_content = "Para reparar todas las brechas de seguridad de la ciudad de Gannon, necesitaré construir un sistema defensivo completamente nuevo, ¡uno que sea completamente independiente del Ingeniero y el Guardián!",
  ui_story_1020_10201201_25_dialog_content = "¿Quieres decir que no dependemos de ninguna otra tecnología y construimos un sistema de defensa que es solo de Illumina con nuestra propia tecnología?",
  ui_story_1020_10201201_26_dialog_content = "Correcto. Desafortunadamente, el núcleo actual no tiene suficiente capacidad de procesamiento, lo que hace que construir un sistema completamente nuevo mientras se defiende contra posibles ataques sea aún más desafiante.",
  ui_story_1020_10201201_27_dialog_content = "Si tuviera más núcleos para ayudar a procesar más datos, no sería tanto problema...",
  ui_story_1020_10201201_28_dialog_content = "¿Sería útil si usamos otras computadoras en la ciudad de Gannon, Dr. Algol?",
  ui_story_1020_10201201_29_dialog_content = "No tenemos tantos en espera en este momento, así que me temo que no marcaría una diferencia.",
  ui_story_1020_10201201_30_dialog_content = "¡No estoy hablando de los que están en espera! ¡Estoy hablando de cada una de las computadoras en la ciudad de Gannon!",
  ui_story_1020_10201201_31_dialog_content = "¿Cada uno? Bueno, con tanto poder de procesamiento a mi disposición... Estoy seguro de que ayudaría mucho.",
  ui_story_1020_10201201_32_dialog_content = "Pero al hacer eso, todos los demás procesos de ingeniería se detendrán temporalmente, incluyendo nuestras puertas y sistemas de soporte vital...",
  ui_story_1020_10201201_33_dialog_content = "¿Podría una ciudad tan grande como Gannon durar siquiera un minuto sin esos sistemas vitales?",
  ui_story_1020_10201201_34_dialog_content = "...",
  ui_story_1020_10201201_35_dialog_content = "No solo eso, el nuevo sistema de defensa necesitará ser probado. Si no puede manejar los mismos procesos complejos que el núcleo al que está reemplazando, entonces solo colapsará de nuevo.",
  ui_story_1020_10201201_36_dialog_content = "En este momento, todo lo que puedo hacer es tratar de anticipar las acciones del Ingeniero y vencerlo en su propio juego.",
  ui_story_1020_10201201_37_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10201201_38_dialog_content = "Eso no funcionará.",
  ui_story_1020_10201201_39_dialog_content = "¡Booo!",
  ui_story_1020_10201201_40_dialog_content = "También eres parte del prototipo.",
  ui_story_1020_10201201_41_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10201201_42_dialog_content = "¿Bool se te ocurrió algo?",
  ui_story_1020_10201201_43_dialog_content = "Bool quiere servir como el núcleo del nuevo sistema de defensa de Gannon City.",
  ui_story_1020_10201201_44_dialog_content = "¿Bool? ¿Cómo puede hacer eso?",
  ui_story_1020_10201201_45_dialog_content = "Exactamente. Como mi asistente y parte del prototipo, no ha hecho más que complicarme las cosas.",
  ui_story_1020_10201201_46_dialog_content = "¡Booo!",
  ui_story_1020_10201201_47_dialog_content = "¡Bool obviamente ha sido de gran ayuda para el Dr. Algol!",
  ui_story_1020_10201201_48_dialog_content = "¡Bu!",
  ui_story_1020_10201201_49_dialog_content = "Bip—",
  ui_story_1020_10201201_50_dialog_content = "Algol, por favor abre el <color=#FFB400>compartimento de mantenimiento</color> del Guardián Uno.",
  ui_story_1020_10201201_51_dialog_content = "Utiliza el <color=#FFB400>núcleo</color> del Guardián Uno para proteger la ciudad de Gannon.",
  ui_story_1020_10201201_52_dialog_content = "¿Ah?",
  ui_story_1020_10201201_53_dialog_content = "Guardian One quiere abandonar su inteligencia y convertirse en una máquina que se ocupa de los ataques de datos.",
  ui_story_1020_10201201_54_dialog_content = "No te di inteligencia artificial solo para que la deseches y te conviertas en otra parte sin sentido de las defensas de la Ciudad de Gannon, Guardian One.",
  ui_story_1020_10201201_55_dialog_content = "Guardian One lo sabe. Algol quiere que Guardian One pueda procesar conversaciones complicadas entre Aurorians y convertirse en el amigo de Algol.",
  ui_story_1020_10201201_56_dialog_content = "Pero Algol necesita a Guardian One. Por favor, usa el núcleo de Guardian One para proteger Gannon City.",
  ui_story_1020_10201201_57_dialog_content = "No.",
  ui_story_1020_10201201_58_dialog_content = "Algol, por favor usa el núcleo de Guardián Uno para proteger Gannon City.",
  ui_story_1020_10201201_59_dialog_content = "¡No!",
  ui_story_1020_10201201_60_dialog_content = "¡Bip! Algol, por favor usa el núcleo de Guardián Uno para proteger Gannon City.",
  ui_story_1020_10201201_61_dialog_content = "¡Dije que no, así que ya déjalo!",
  ui_story_1020_10201201_62_dialog_content = "¡Dije que no, así que ya déjalo!",
  ui_story_1020_10201201_63_dialog_content = "...",
  ui_story_1020_10201201_64_dialog_content = "Tú... ¿Cuándo aprendiste a imitar a los demás de esa manera...",
  ui_story_1020_10201201_65_dialog_content = "Guardian One pensó en ello durante mucho tiempo antes de entender. \"Bip, bip, bip, bip, bip.\" Algol en realidad no dijo nada en ese momento.",
  ui_story_1020_10201201_66_dialog_content = "...",
  ui_story_1020_10201201_67_dialog_content = "Solo estás haciendo esto más difícil para mí. ¿Lo sabes, verdad?",
  ui_story_1020_10201201_68_dialog_content = "Guardian One sabe eso, pero esta es la solicitud de Guardian One. Algol, por favor usa el núcleo de Guardian One para proteger Gannon City.",
  ui_story_1020_10201201_69_dialog_content = "¿Incluso sabes a qué tendrás que enfrentarte para proteger la ciudad de Gannon?",
  ui_story_1020_10201201_70_dialog_content = "Este lugar no solo está lleno de cables y alambres. También hay muchos datos maliciosos que pueden invadir tu mente.",
  ui_story_1020_10201201_71_dialog_content = "¡Ese mismo dato malicioso puede limitar tu razonamiento e incluso obligarte a atacar a Illumina como si fueras un Eclipsite!",
  ui_story_1020_10201201_72_dialog_content = "Esto no es solo una simple migración de datos. ¡Estarías abandonando tu capacidad para crear y adaptarte, y te convertirías en otra herramienta para que otros te exploten!",
  ui_story_1020_10201201_73_dialog_content = "Guardian One no comenzará a imaginar cosas, porque Algol le dijo a Guardian One que pensar es la especialidad de los Aurorianos.",
  ui_story_1020_10201201_74_dialog_content = "Con un mentor sabio como Algol, Guardian One puede abandonar la capacidad de pensar y centrarse solo en proteger la Ciudad Gannon.",
  ui_story_1020_10201201_75_dialog_content = "¡Ni siquiera estás dispuesto a hacerme una taza de café! ¿Qué te hace pensar...",
  ui_story_1020_10201201_76_dialog_content = "Guardian One sabe que a Algol no le gustaría que Guardian One fuera solo un robot mayordomo, sino un compañero con el que pueda divertirse.",
  ui_story_1020_10201201_77_dialog_content = "Guardian One solo tiene una condición. Si Guardian One va a vivir aquí, entonces por favor organice este lugar como la oficina de Algol y coloque más plantas verdes aquí.",
  ui_story_1020_10201201_78_dialog_content = "Cuando se creen Guardian Two y Guardian Three, por favor diseñalos con una carcasa que sea más fácil de mover, a diferencia de lo que tiene Guardian One...",
  ui_story_1020_10201201_79_dialog_content = "Algol siempre dice que Guardian One parece un buzón y siempre tiene el impulso de meter cartas en la boca de Guardian One.",
  ui_story_1020_10201201_80_dialog_content = "...",
  ui_story_1020_10201201_81_dialog_content = "Ah, hay una cosa más que decirle a Algol...",
  ui_story_1020_10201201_82_dialog_content = "Guardian One hizo una cosa que Algol desconocía cuando Guardian One estaba comunicándose telepáticamente con PlayerName.",
  ui_story_1020_10201201_83_dialog_content = "?",
  ui_story_1020_10201201_84_dialog_content = "Esa comunicación hizo que Guardian One creyera que puede confiar en PlayerName con toda su conciencia.",
  ui_story_1020_10201201_85_dialog_content = "Si Algol necesita un amigo, Guardian One recomienda que Algol se haga amigo de PlayerName.",
  ui_story_1020_10201201_86_dialog_content = "...",
  ui_story_1020_10201201_87_dialog_content = "Adiós, Algol.",
  ui_story_1020_10201201_88_dialog_content = "A Guardian One le gusta la nueva expresión Algol diseñada para él.",
  ui_story_1020_10201201_89_dialog_content = "Bip—bip—bip—",
  ui_story_1020_10201201_90_dialog_content = "<color=#e8d9bb>Sonido metálico-</color>",
  ui_story_1020_10201201_91_dialog_content = "Boo...",
  ui_story_1020_10201201_92_dialog_content = "Bip, bip, bip, bip, bip.",
  ui_story_1020_10201201_93_dialog_content = "...",
  ui_story_1020_10201201_94_dialog_content = "¿No tenemos ninguna otra opción, Gran Mariscal?",
  ui_story_1020_10201201_95_dialog_content = "...",
  ui_story_1020_10201201_96_dialog_content = "Esta puede ser nuestra única opción ahora. Cuando el Ingeniero apareció por primera vez, ya lo había considerado.",
  ui_story_1020_10201201_97_dialog_content = "Lo siento, Dr. Algol. Sé que Guardian One era tu buen amigo.",
  ui_story_1020_10201201_98_dialog_content = "Mi único amigo, en realidad.",
  ui_story_1020_10201201_99_dialog_content = "Pero ¿qué tipo de amigo haría algo así? Jaja...",
  ui_story_1020_10201201_100_dialog_content = "Un buzón parlante y santurrón...",
  ui_story_1020_10201201_101_dialog_content = "¡Eso es lo que era!",
  ui_story_1020_10201201_102_dialog_content = "Pero ahora que tenemos un nuevo núcleo, ¿sigue en pie tu sugerencia? ¿La de apagar los procesos esenciales de Gannon City por un minuto?",
  ui_story_1020_10201201_103_dialog_content = "?",
  ui_story_1020_10201201_104_dialog_content = "Si es así, podemos redirigir toda la potencia de procesamiento de la ciudad de Gannon y ayudarte a reemplazar el núcleo.",
  ui_story_1020_10201201_105_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10201201_106_dialog_content = "No puedo hacerlo, no en menos de un minuto.",
  ui_story_1020_10201201_107_dialog_content = "¡Entonces te daremos diez minutos! Te conseguiremos todos los ordenadores y la mano de obra que necesites. ¿Podrás hacerlo entonces?",
  ui_story_1020_10201201_108_dialog_content = "¿Hablas en serio?",
  ui_story_1020_10201201_109_dialog_content = "Muerto en serio.",
  ui_story_1020_10201201_110_dialog_content = "La gente de Illumina no sobrevivió bioingenierizando a los Aurorianos, Dr. Algol.",
  ui_story_1020_10201201_111_dialog_content = "Ni dependiendo de esta máquina antigua.",
  ui_story_1020_10201201_112_dialog_content = "Así es. Aunque Ulysses piensa que hemos estado dependiendo del Guardián durante los últimos seiscientos años...",
  ui_story_1020_10201201_113_dialog_content = "Creo que fueron los soldados de la Federación Illumina quienes han mantenido en pie nuestras murallas.",
  ui_story_1020_10201201_114_dialog_content = "¡Si no podemos protegerlo ni siquiera durante diez minutos, entonces Illumina nunca volverá a encontrar su lugar en Astra! ¡Es un riesgo que debemos correr!",
  ui_story_1020_10201201_115_dialog_content = "Incluso pondré mi propia vida en tus manos, si es necesario. Eso es porque estoy dispuesto a ser el tipo de amigo que cree en ti.",
  ui_story_1020_10201201_116_dialog_content = "...",
  ui_story_1020_10201201_117_dialog_content = "Yo también.",
  ui_story_1020_10201201_118_dialog_content = "¡Y yo!",
  ui_story_1020_10201201_119_dialog_content = "... ¿Así que todos ustedes piensan que creer en el poder de la amistad nos ayudará a lograr lo imposible?",
  ui_story_1020_10201201_120_dialog_content = "Jaja, la última vez que escuché algo tan ridículo fue en la escuela primaria.",
  ui_story_1020_10201201_121_dialog_content = "Aun así, estoy dispuesto a darle una oportunidad.",
  ui_story_1020_10201201_122_dialog_content = "Jejeje, ¡me encanta jugar juegos con mis amigos!",
  ui_story_1020_10201201_123_dialog_content = "¡Entonces comencemos! Hiiro, ¡conéctate al sistema de transmisión de emergencia de la ciudad! ¡Es hora de que dé la orden!",
  ui_story_1020_10201201_124_dialog_content = "¡Entendido!",
  ui_story_1020_10201201_125_dialog_content = "<color=#e8d9bb>bip—bip—</color>",
  ui_story_1020_10201201_126_dialog_content = "Gran Mariscal.",
  ui_story_1020_10201201_127_dialog_content = "Vale, pensé que nunca llegaría a usar esta frecuencia.",
  ui_story_1020_10201201_128_dialog_content = "Este es un anuncio de emergencia. Durante los próximos diez minutos, estaremos redirigiendo toda la capacidad de procesamiento de la ciudad para abordar una crisis urgente.",
  ui_story_1020_10201201_129_dialog_content = "Durante este tiempo, recaerá en cada uno de nosotros defender la ciudad de Gannon.",
  ui_story_1020_10201201_130_dialog_content = "¡A tu comando, Gran Mariscal!",
  ui_story_1020_10201201_131_dialog_content = "Las zonas de aislamiento, los pisos de guarnición y los pisos de amortiguación estarán directamente expuestos a los ataques de Eclipsite. Barton, asumirás el mando de estas áreas.",
  ui_story_1020_10201201_132_dialog_content = "¡Entendido!",
  ui_story_1020_10201201_133_dialog_content = "Sharona, regresa a Gannon City y ataca a los Eclipsites desde la superficie. El equipo de ingeniería debería haber terminado las evacuaciones de civiles para ahora.",
  ui_story_1020_10201201_134_dialog_content = "Entendido.",
  ui_story_1020_10201201_135_dialog_content = "Hiiro, te pongo a cargo de los sectores de agricultura, minería, manufactura y almacén.",
  ui_story_1020_10201201_136_dialog_content = "Un pequeño número de trabajadores militares y no militares están sosteniendo operaciones mecánicas allí abajo. Por favor, proporciona refuerzos a los sectores superiores e inferiores según sea necesario.",
  ui_story_1020_10201201_137_dialog_content = "Sin problema.",
  ui_story_1020_10201201_138_dialog_content = "¿Qué hay de mí?",
  ui_story_1020_10201201_139_dialog_content = "El sector de investigación aún está infestado de Eclipsites. Wrath, tú y tu equipo deben localizar cada almacén que contenga Eclipsites y evitar que lleguen a los niveles superiores a toda costa.",
  ui_story_1020_10201201_140_dialog_content = "¡Entendido!",
  ui_story_1020_10201201_141_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10201201_142_dialog_content = "Elude el Sistema de Guardianes para construir una nueva jaula para que sigas ocupando esta subciudad...",
  ui_story_1020_10201201_143_dialog_content = "Todos ustedes están demasiado acostumbrados a vivir en la oscuridad...",
  ui_story_1020_10201201_144_dialog_content = "¿Qué le pasa al cuerpo de Ulysses?",
  ui_story_1020_10201201_145_dialog_content = "Es mi negligencia. Estaba demasiado concentrado en luchar contra los super-soldados para notar que él mismo se subía a la mesa de operaciones.",
  ui_story_1020_10201201_146_dialog_content = "¿Se transformó en tan poco tiempo?",
  ui_story_1020_10201201_147_dialog_content = "... Me temo que sus modificaciones han estado en marcha desde hace mucho tiempo. No acaban de empezar recientemente.",
  ui_story_1020_10201201_148_dialog_content = "La defensa no resolverá nada. Solo la resistencia activa lo hará... ¡Un núcleo ya no es necesario con este cuerpo!",
  ui_story_1020_10201201_149_dialog_content = "Sigue causando problemas, y te cortaré la cabeza, Ulysses!",
  ui_story_1020_10201201_150_dialog_content = "¡Espera! ¡Todos, retrocedan!",
  ui_story_1020_10201201_151_dialog_content = "Dije que nunca tuve miedo de la Zona Oscura...",
  ui_story_1020_10201201_152_dialog_content = "Incluso si todos fallan...",
  ui_story_1020_10201201_153_dialog_content = "¡Lo haré yo mismo!",
  ui_story_1020_10201201_154_dialog_content = "<color=#e8d9bb>Bip-bip-bip-</color>",
  ui_story_1020_10201201_155_dialog_content = "... ¿Sobrecarga de datos? ¿Podría ser esto obra de Ulysses?",
  ui_story_1020_10201201_156_dialog_content = "...",
  ui_story_1020_10201201_157_dialog_content = "¿Continuar la misión? ¿Gran Mariscal?",
  ui_story_1020_10201201_158_dialog_content = "¡A mi orden, Bool!",
  ui_story_1020_10201201_159_dialog_content = "¡Booooo!",
  ui_story_1020_10201201_160_dialog_content = "¡Manténganse al plan original, todos! ¡Necesitamos proteger a la Dra. Algol mientras ella reemplaza el núcleo! ¡Dejen este lugar en mis manos!",
  ui_story_1020_10201201_161_dialog_content = "¡Sí!",
  ui_story_1020_10201201_162_dialog_content = "¡Entendido!",
  ui_story_1020_10201201_163_dialog_content = "¡Alto y claro, Gran Mariscal!",
  ui_story_1020_10201201_164_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_1020_10201201_165_dialog_content = "¡Cuidado, el almacén de super-soldados se está abriendo de nuevo!",
  ui_story_1020_10201201_166_dialog_content = "¿Están siguiendo a Ulysses?",
  ui_story_1020_10201201_167_dialog_content = "¡Un núcleo ya no es necesario con este cuerpo!",
  ui_story_1020_10201201_168_dialog_content = "¡Idiota! ¿Crees que ese cuerpo te hace invencible?",
  ui_story_1020_10201201_169_dialog_content = "¡Después de todas estas modificaciones, el Ingeniero podría tomar el control total sobre ti con un solo cable!",
  ui_story_1020_10201201_170_dialog_content = "Y el almacén está lleno de cables...",
  ui_story_1020_10201201_171_dialog_content = "¡Reinhardt! ¡Dile al resto de estas personas que se vayan de aquí! De lo contrario, los cables podrían tomar el control de ellos!",
  ui_story_1020_10201201_172_dialog_content = "¡Solo necesito que estés aquí para ayudarme a proteger el nuevo sistema de defensa!",
  ui_story_1020_10201201_173_dialog_content = "¡Haz lo que dice Algol, todos!",
  ui_story_1020_10201201_174_dialog_content = "¿Por qué tipo de tonto me tomas? ¿Cómo podría dejaros a los dos luchar contra todos estos super-soldados?",
  ui_story_1020_10201201_175_dialog_content = "¡Proporcionaré apoyo, Gran Mariscal!",
  ui_story_1020_10201201_176_dialog_content = "¡Yo también!",
  ui_story_1020_10201201_177_dialog_content = "¡Entonces te dejaremos a cargo de los super soldados! ¡No pierdas de vista a Ulysses tampoco!",
  ui_story_1020_10201201_178_dialog_content = "Bool, encuentra la interfaz y corta la conexión entre el prototipo y estos super-soldados. ¡Después de eso, reemplaza el núcleo!",
  ui_story_1020_10201201_179_dialog_content = "¡Booooo!",
  ui_story_1020_10201301_1_dialog_content = "¡Booo!",
  ui_story_1020_10201301_2_dialog_content = "¡Funcionó... Funcionó! ¡Jajajajaja!",
  ui_story_1020_10201301_3_dialog_content = "¡Lo hiciste, Guardián Uno! ¡Realmente lo hiciste!",
  ui_story_1020_10201301_4_dialog_content = "¡Bu!",
  ui_story_1020_10201301_5_dialog_content = "Acabamos de escuchar un fuerte estruendo, Gran Mariscal. ¿Estás bien—",
  ui_story_1020_10201301_6_dialog_content = "Shhh, ¿escuchas eso?",
  ui_story_1020_10201301_7_dialog_content = "(Eclipsiano) 1011X.",
  ui_story_1020_10201301_8_dialog_content = "(Eclipsiano) 01X11.",
  ui_story_1020_10201301_9_dialog_content = "(Eclipsiano) X1010.",
  ui_story_1020_10201301_10_dialog_content = "¿Qué le está pasando al profesor?",
  ui_story_1020_10201301_11_dialog_content = "...",
  ui_story_1020_10201301_12_dialog_content = "(Eclipsiano) 0111X.",
  ui_story_1020_10201301_13_dialog_content = "(Eclipsiano) 0X111.",
  ui_story_1020_10201301_14_dialog_content = "... ¿Eclipsiano?",
  ui_story_1020_10201301_15_dialog_content = "?",
  ui_story_1020_10201301_16_dialog_content = "Suena extraño salir de su boca, pero no se puede negar, ese es el mismo idioma que los Eclipsites usan para comunicarse.",
  ui_story_1020_10201301_17_dialog_content = "... Eso es lo que PlayerName estaba murmurando cuando se conectó con Figerald.",
  ui_story_1020_10201301_18_dialog_content = "1011X.",
  ui_story_1020_10201301_19_dialog_content = "... ¿Así?",
  ui_story_1020_10201301_20_dialog_content = "Espera, ¿qué fue eso de nuevo? Dilo más despacio.",
  ui_story_1020_10201301_21_dialog_content = "1... 0... 1... 1... X...",
  ui_story_1020_10201301_22_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10201301_23_dialog_content = "¿PlayerName entiende Eclipsiano?",
  ui_story_1020_10201301_24_dialog_content = "Realmente no lo entiendo, y esto puede sonar extraño... Pero repetir sus palabras ahora es bastante fácil para mí...",
  ui_story_1020_10201301_25_dialog_content = "No es de extrañar... ¡Es justo como cuando te vinculaste con Bool para ayudarnos a registrar esos otros números!",
  ui_story_1020_10201301_26_dialog_content = "Existe una conexión entre Eclipsiano y el lenguaje de computación del prototipo...",
  ui_story_1020_10201301_27_dialog_content = "La mayoría de los Eclipsites parecen completamente carentes de mente hasta que se les da la orden de atacar.",
  ui_story_1020_10201301_28_dialog_content = "Pedidos... Idioma... Sí, todo está empezando a sumar!",
  ui_story_1020_10201301_29_dialog_content = "(En eclipsiano) 2355X11874...",
  ui_story_1020_10201301_30_dialog_content = "(Eclipsiano) 32456901X14361...",
  ui_story_1020_10201301_31_dialog_content = "(Si Ulysses está comunicándose con el Ingeniero en este momento...)",
  ui_story_1020_10201301_32_dialog_content = "Podría ser capaz de usar mis poderes en él...",
  ui_story_1020_10201301_33_dialog_content = "¿Qué estás haciendo, PlayerName? ¡Ulysses ha matado a muchas personas, merece morir!",
  ui_story_1020_10201301_34_dialog_content = "Pero esta podría ser la única manera de encontrar a Soroz y Vice...",
  ui_story_1020_10201301_35_dialog_content = "¡PlayerName!",
  ui_story_1020_10201301_36_dialog_content = "Deja de usar tus poderos. Estás en tu límite.",
  ui_story_1020_10201301_37_dialog_content = "¿Es este realmente mi límite...",
  ui_story_1020_10201301_38_dialog_content = "Lo siento, pero esto es lo único que puedo hacer ahora mismo...",
  ui_story_1020_10201301_39_option_content = "Enlace Telepático—",
  ui_story_1020_10201301_40_dialog_content = "Ponte el anillo o sé mi combustible.",
  ui_story_1020_10201301_41_dialog_content = "Como he dicho innumerables veces antes, no cederé ante ti.",
  ui_story_1020_10201301_42_dialog_content = "No llegué a verme así porque temía a la muerte...",
  ui_story_1020_10201301_43_dialog_content = "De estudiar a los muertos a convertir a los vivos en muertos, hace mucho tiempo que me he insensibilizado a ello.",
  ui_story_1020_10201301_44_dialog_content = "Eres valiente más allá de lo normal, Uly.",
  ui_story_1020_10201301_45_dialog_content = "Como yo en el pasado.",
  ui_story_1020_10201301_46_dialog_content = "Jejeje... Jajajaja... ¿Solo \"como\"?",
  ui_story_1020_10201301_47_dialog_content = "Incluso Robby renunció entonces. Yo era el único que quedaba del enorme laboratorio que aún recordaba la razón del estudio en primer lugar...",
  ui_story_1020_10201301_48_dialog_content = "Eso es para encontrar lo que hizo poderosos a los Eclipsites y una forma para que los Aurorianos sobrevivan.",
  ui_story_1020_10201301_49_dialog_content = "Tu nombre apareció cuando revisé los archivos. Me llevaste a hojear los polvorientos registros e investigar al Guardián en secreto.",
  ui_story_1020_10201301_50_dialog_content = "Eso fue también cuando vi la planta para la producción mecanizada de Eclipsites y Caelestites bombardeando Astra en Colosos...",
  ui_story_1020_10201301_51_dialog_content = "Así como los Aurorianos que se refugian en las subciudades.",
  ui_story_1020_10201301_52_dialog_content = "Eoria pasó de azul a un rojo ardiente, segundos antes de convertirse en un mundo muerto de ceniza negra.",
  ui_story_1020_10201301_53_dialog_content = "La Aurora cubrió el cielo, y la órbita fue desviada...",
  ui_story_1020_10201301_54_dialog_content = "Tecnología, guerra, animosidad, vida...",
  ui_story_1020_10201301_55_dialog_content = "Fue tú quien me mostró la crueldad y me obligó a vivir con miedo.",
  ui_story_1020_10201301_56_dialog_content = "¿Qué fue lo que dije?",
  ui_story_1020_10201301_57_dialog_content = "\"¡Debes ser más valiente si quieres derrotar a los Eclipsites!\"",
  ui_story_1020_10201301_58_dialog_content = "\"¡Aún más atrevido!\"",
  ui_story_1020_10201301_59_dialog_content = "Siempre que escuchaba eso, generalmente no podía decir quién era, si estaba en el pasado o en el futuro.",
  ui_story_1020_10201301_60_dialog_content = "Incluso pensaría, \"¿Por qué yo?\"",
  ui_story_1020_10201301_61_dialog_content = "Pero cuando superé el miedo, lo descifré y desde entonces no he tenido miedo.",
  ui_story_1020_10201301_62_dialog_content = "Incluso cuando me enfrento a este mundo cruel, incluso cuando te enfrento a ti.",
  ui_story_1020_10201301_63_dialog_content = "Venciste ese miedo, pero obtuviste un miedo nuevo.",
  ui_story_1020_10201301_64_dialog_content = "¿Qué nuevo miedo?",
  ui_story_1020_10201301_65_dialog_content = "¿Te gustaría verlo?",
  ui_story_1020_10201301_66_dialog_content = "...",
  ui_story_1020_10201301_67_dialog_content = "negador.",
  ui_story_1020_10201301_68_dialog_content = "Señor.",
  ui_story_1020_10201301_69_dialog_content = "La teoría sobre Eclipsium que propusiste en el seminario vale la pena investigar.",
  ui_story_1020_10201301_70_dialog_content = "Gracias, señor. Pero Illumina no puede apoyar mi estudio por ahora.",
  ui_story_1020_10201301_71_dialog_content = "Habrá materiales disponibles después de la guerra. Entonces puedes construir tu propio laboratorio alrededor de Gannon y hacer los experimentos que quieras.",
  ui_story_1020_10201301_72_dialog_content = "... Gracias, señor.",
  ui_story_1020_10201301_73_dialog_content = "¿Cómo va el progreso, Denier?",
  ui_story_1020_10201301_74_dialog_content = "Esta es la semilla que cultivé, señor.",
  ui_story_1020_10201301_75_dialog_content = "Excelente... Es muy bonito.",
  ui_story_1020_10201301_76_dialog_content = "Si pudiéramos implantarlo en nuestros soldados...",
  ui_story_1020_10201301_77_dialog_content = "¡Es solo un estudio, señor! El Darkflow en la semilla devorará a los Aurorians.",
  ui_story_1020_10201301_78_dialog_content = "¿Devorar a los Aurorians? ¿Sabes cómo los Eclipsites están devorando el mundo?",
  ui_story_1020_10201301_79_dialog_content = "?",
  ui_story_1020_10201301_80_dialog_content = "Tu resultado es sobresaliente, Negador. Es hora de una metamorfosis Aurorian.",
  ui_story_1020_10201301_81_dialog_content = "... ¿Qué planeas hacer?",
  ui_story_1020_10201301_82_dialog_content = "Entrégale la semilla.",
  ui_story_1020_10201301_83_dialog_content = "...",
  ui_story_1020_10201301_84_dialog_content = "Entrégalo.",
  ui_story_1020_10201301_85_dialog_content = "Me niego.",
  ui_story_1020_10201301_86_dialog_content = "¿Te estás oponiendo a Illumina?",
  ui_story_1020_10201301_87_dialog_content = "No, señor.",
  ui_story_1020_10201301_88_dialog_content = "Nunca olvides, sin mí, no hay tú.",
  ui_story_1020_10201301_89_dialog_content = "...",
  ui_story_1020_10201301_90_dialog_content = "Ahora recuerdo, ese es el Illuminan llamado Forsakin, el que siempre quisiste ser.",
  ui_story_1020_10201301_91_dialog_content = "No...",
  ui_story_1020_10201301_92_dialog_content = "Tu orgullo, tu obra maestra se llama Proyecto: Sol Artificial, ¿verdad?",
  ui_story_1020_10201301_93_dialog_content = "Ya reconocí tu talento, Uly. Ahora usa el anillo, el símbolo de ese reconocimiento.",
  ui_story_1020_10201301_94_dialog_content = "¡No necesito tu reconocimiento, y nunca me someteré a tu voluntad!",
  ui_story_1020_10201301_95_dialog_content = "(Ulysses lastimó a tantas personas y realizó todos esos terribles experimentos, pero nunca cedió ante el Ingeniero...)",
  ui_story_1020_10201301_96_dialog_content = "(¿Por qué es eso?)",
  ui_story_1020_10201301_97_dialog_content = "¿Estás sorprendido, Caelestite?",
  ui_story_1020_10201301_98_dialog_content = "Entonces puedes verme cuando estoy usando mis habilidades psíquicas...",
  ui_story_1020_10201301_99_dialog_content = "¿Cómo?",
  ui_story_1020_10201301_100_dialog_content = "Cuando el Colossus \"me vio\", yo \"te vi\".",
  ui_story_1020_10201301_101_dialog_content = "El \"yo\" en la autoconciencia es un concepto abstracto. Lo que parece ser consciente puede ser en realidad el recipiente para otra conciencia.",
  ui_story_1020_10201301_102_dialog_content = "Porque siempre hay una inteligencia superior detrás de ello.",
  ui_story_1020_10201301_103_dialog_content = "La antigua máquina es mi vehículo, al igual que ese Wraith, y pronto, él.",
  ui_story_1020_10201301_104_dialog_content = "Ulysses... ¡No te pongas ese anillo!",
  ui_story_1020_10201301_105_dialog_content = "Él no puede oírte.",
  ui_story_1020_10201301_106_dialog_content = "...",
  ui_story_1020_10201301_107_dialog_content = "Vice, Soroz... ¡Voy a encontrarlos a ambos!",
  ui_story_1020_10201301_108_dialog_content = "Seguro.",
  ui_story_1020_10201301_109_dialog_content = "Una luz nos separó brevemente antes. Quizás hay algo que querré ver allí.",
  ui_story_1020_10201301_110_dialog_content = "La superficie de un lago resplandeciente...",
  ui_story_1020_10201301_111_dialog_content = "¿Qué escuchaste? Nunca me pondré ese anillo, y no moriré tan fácilmente.",
  ui_story_1020_10201301_112_dialog_content = "Es inútil luchar en tu estado.",
  ui_story_1020_10201301_113_dialog_content = "No importa en qué estado me encuentre, pero les diré cómo los aurorianos pueden sobrevivir.",
  ui_story_1020_10201301_114_dialog_content = "Soy el único en el mundo que te entiende. Pero respeto tu deseo.",
  ui_story_1020_10201301_115_dialog_content = "¿Qué le vas a hacer?",
  ui_story_1020_10201301_116_dialog_content = "Dale lo que quiere.",
  ui_story_1020_10201301_117_dialog_content = "Siempre habrá grandes científicos para cada generación en Illumina.",
  ui_story_1020_10201301_118_dialog_content = "Pero sin ellos y el prototipo, aún podemos encontrarnos en otro lugar. Ya conoces mis coordenadas.",
  ui_story_1020_10201301_119_dialog_content = "...",
  ui_story_1020_10201301_120_dialog_content = "Recuerda, la luz puede ser engañosa. Intenta ocultar el hecho de que la oscuridad es la verdad.",
  ui_story_1020_10201301_121_dialog_content = "Acepta la oscuridad, déjala entrar y permítele ser tu fuerza.",
  ui_story_1020_10201301_122_dialog_content = "Urgh—",
  ui_story_1020_10201301_123_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10201301_124_dialog_content = "¿Tu cerebro sigue intacto, PlayerName?",
  ui_story_1020_10201301_125_dialog_content = "¡Estoy bien! Pero Ulysses...",
  ui_story_1020_10201301_126_dialog_content = "¡Hraaagh!",
  ui_story_1020_10201301_127_dialog_content = "¡Bu! ¡Bu! ¡Bu!",
  ui_story_1020_10201301_128_dialog_content = "Deja de avanzar, profesor, o—",
  ui_story_1020_10201301_129_dialog_content = "<color=#e8d9bb>Hacer clic-</color>",
  ui_story_1020_10201301_130_dialog_content = "...",
  ui_story_1020_10201301_131_dialog_content = "¿Me dispararías? Yo te creé... Todos ustedes me entienden, ¿verdad?",
  ui_story_1020_10201301_132_dialog_content = "¡Se está comportando como Figerald!",
  ui_story_1020_10201301_133_dialog_content = "No, no son iguales.",
  ui_story_1020_10201301_134_dialog_content = "Ulysses nunca cedió a la voluntad del Ingeniero, por lo que él está tratando de destruirlo... Ulysses se está resistiendo en este momento.",
  ui_story_1020_10201301_135_dialog_content = "...",
  ui_story_1020_10201301_136_dialog_content = "¿Qué deberíamos hacer con él, Gran Mariscal?",
  ui_story_1020_10201301_137_dialog_content = "... ¡Detente, Ulysses! ¿No entiendes?",
  ui_story_1020_10201301_138_dialog_content = "Pensaste que estabas salvando a los Aurorians del Eclipse todo este tiempo. ¡Nunca te diste cuenta de que te habías unido a ellos hace mucho tiempo!",
  ui_story_1020_10201301_139_dialog_content = "Diles... Caelestita...",
  ui_story_1020_10201301_140_dialog_content = "10011000... Cómo pueden sobrevivir los Aurorians... 00!",
  ui_story_1020_10201301_141_dialog_content = "No escatimar esfuerzos... 12933... Llevar al extremo... 11012... es el... 103001111...",
  ui_story_1020_10201301_142_dialog_content = "Única oportunidad...",
  ui_story_1020_10201301_143_dialog_content = "01100...",
  ui_story_1020_10201301_144_dialog_content = "No...",
  ui_story_1020_10201301_145_dialog_content = "Eres especial... Debes enfrentarte al destino... a tu manera...",
  ui_story_1020_10201301_146_dialog_content = "Pero... 10011001X0... Pero...",
  ui_story_1020_10201301_147_dialog_content = "Urgh... Arghhhh—",
  ui_story_1020_10201301_148_dialog_content = "1001X1000... El mundo que cambié...",
  ui_story_1020_10201301_149_dialog_content = "Seguramente... 10102099... será tu futuro... 1X120...",
  ui_story_1020_10201301_150_dialog_content = "¡Bool!",
  ui_story_1020_10201301_151_dialog_content = "¡Pasa un cable al cuerpo de Ulysses! Necesitamos encontrar la interfaz y destruir la conexión entre él y el Ingeniero!",
  ui_story_1020_10201301_152_dialog_content = "Argh-",
  ui_story_1020_10201301_153_dialog_content = "Es muy tarde ahora.",
  ui_story_1020_10201301_154_dialog_content = "...",
  ui_story_1020_10201301_155_dialog_content = "No importa lo que hizo por Illumina en el pasado, ya no es uno de nosotros, ni siquiera un Auroriano, para el caso.",
  ui_story_1020_10201301_156_dialog_content = "Puso en peligro a toda la Ciudad de Gannon en múltiples ocasiones y se llevó la vida de sus compatriotas.",
  ui_story_1020_10201301_157_dialog_content = "Como Gran Mariscal de la Federación Illumina, por la presente condeno a Ulysses a muerte por sus crímenes.",
  ui_story_1020_10201301_158_dialog_content = "¡Hraaagh!",
  ui_story_1020_10201301_159_dialog_content = "¡Mátalo!",
  ui_story_1020_10201402_1_dialog_content = "¿Puedes ser salvado... si yo muero?",
  ui_story_1020_10201402_2_dialog_content = "Apenas estoy contento con este resultado, Robby...",
  ui_story_1020_10201402_3_dialog_content = "<color=#e8d9bb>En un Sanatorio Illumina en Tiempos de Guerra Durante la Crisis de Darkover</color>",
  ui_story_1020_10201402_4_dialog_content = "Oye, ha pasado mucho tiempo, Uly.",
  ui_story_1020_10201402_5_dialog_content = "No esperaba verte aquí, Robby...",
  ui_story_1020_10201402_6_dialog_content = "¿Cómo has estado—",
  ui_story_1020_10201402_7_dialog_content = "¿Qué nueva idea estás reflexionando hoy?",
  ui_story_1020_10201402_8_dialog_content = "...",
  ui_story_1020_10201402_9_dialog_content = "Mi experimento falló de nuevo, Uly. <color=#FFB400>Entrañas 77</color> solo devolvió unos pocos sujetos chamuscados...",
  ui_story_1020_10201402_10_dialog_content = "Tocaron la música que siempre escuchamos en el laboratorio hoy... Oh, ¿qué acabas de decir?",
  ui_story_1020_10201402_11_dialog_content = "...",
  ui_story_1020_10201402_12_dialog_content = "Dije que todavía llevas ese broche.",
  ui_story_1020_10201402_13_dialog_content = "Sí. Lo estuve buscando toda la tarde ayer. Resultó que Sasha lo escondió. Qué niño travieso.",
  ui_story_1020_10201402_14_dialog_content = "...",
  ui_story_1020_10201402_15_dialog_content = "Ella ha comenzado a escribir poesía últimamente. Permíteme leerte uno para ver qué piensas, Uly.",
  ui_story_1020_10201402_16_dialog_content = "Robby...",
  ui_story_1020_10201402_17_dialog_content = "Has olvidado cómo nos sumergimos en la investigación y las pistas sobre el Ingeniero.",
  ui_story_1020_10201402_18_dialog_content = "Solo recuerdas a la familia que falleció temprano...",
  ui_story_1020_10201402_19_dialog_content = "De hecho, estoy bastante feliz por ti, jejeje.",
  ui_story_1020_10201402_20_dialog_content = "Si nunca me hubiera encontrado con el nombre del Ingeniero o hubiera tenido las visiones...",
  ui_story_1020_10201402_21_dialog_content = "Si pudiéramos seguir discutiendo nuestros sueños en el laboratorio como antes...",
  ui_story_1020_10201402_22_dialog_content = "Lo primero que dirías cuando me vieras todos los días sería...",
  ui_story_1020_10201402_23_dialog_content = "¿Qué nueva idea estás pensando hoy, Uly?",
  ui_story_1020_10201402_24_dialog_content = "...",
  ui_story_1020_10201402_25_dialog_content = "Uli.",
  ui_story_1020_10201402_26_dialog_content = "¿Si?",
  ui_story_1020_10201402_27_dialog_content = "¿Has experimentado una crisis de fe?",
  ui_story_1020_10201402_28_dialog_content = "...",
  ui_story_1020_10201402_29_dialog_content = "No.",
  ui_story_1020_10201402_30_dialog_content = "¿Cuál crees que es peor...",
  ui_story_1020_10201402_31_dialog_content = "¿Crisis de tu fe o incapacidad para alcanzar tu objetivo?",
  ui_story_1020_10201402_32_dialog_content = "...",
  ui_story_1020_10201402_33_dialog_content = "Crisis de mi fe o incapacidad para alcanzar mi objetivo...",
  ui_story_1020_10201402_34_dialog_content = "¿Cuál es más lamentable?",
  ui_story_1020_10201402_35_dialog_content = "...",
  ui_story_1020_10201501_1_dialog_content = "... ¡Es como un lienzo!",
  ui_story_1020_10201501_2_dialog_content = "Sí, y en el lienzo de Minch además. ¡Garabatos aleatorios antes de salpicar pintura en él!",
  ui_story_1020_10201501_3_dialog_content = "... Tiene una sensación artística única.",
  ui_story_1020_10201501_4_dialog_content = "¿A qué estás llegando?",
  ui_story_1020_10201501_5_dialog_content = "¡La Dama Victoria no nos trajo a todos aquí para que te burles de mí!",
  ui_story_1020_10201501_6_dialog_content = "¡Oh, hablando de eso, gracias, Lady Victoria!",
  ui_story_1020_10201501_7_dialog_content = "¡Gracias, Lady Victoria!",
  ui_story_1020_10201501_8_dialog_content = "¡Gracias, Lady Victoria!",
  ui_story_1020_10201501_9_dialog_content = "No tomaré crédito por ello. Esta es una bendición del Señor de la Verdad.",
  ui_story_1020_10201501_10_dialog_content = "¿Dónde estoy?",
  ui_story_1020_10201501_11_dialog_content = "...",
  ui_story_1020_10201501_12_dialog_content = "El <color=#FFB400>Río Prístino</color> se encuentra fuera del tiempo y el espacio. La única diferencia entre él y el mundo exterior es la fluidez.",
  ui_story_1020_10201501_13_dialog_content = "¿No perderemos el control de nuestras propias vidas si esto sigue así?",
  ui_story_1020_10201501_14_dialog_content = "¿Por qué nos trajiste aquí?",
  ui_story_1020_10201501_15_dialog_content = "Para encontrar la marca correspondiente a nuestro espacio-tiempo y permitir que el Señor de la Verdad venga con nosotros.",
  ui_story_1020_10201501_16_dialog_content = "Bla bla bla...",
  ui_story_1020_10201501_17_dialog_content = "Señorita Victoria, aún no hemos terminado nuestra misión de reconocimiento en la Zona Oscura. ¿Realmente puede Illumina obtener las coordenadas que enviamos desde aquí?",
  ui_story_1020_10201501_18_dialog_content = "El Señor de la Verdad predica que si hay voluntad, hay una manera. Todo depende de ti.",
  ui_story_1020_10201501_19_dialog_content = "<color=#e8d9bb>¡Sploosh—!</color>",
  ui_story_1020_10201501_20_dialog_content = "Oye, Vice, ¿dejaste caer algo?",
  ui_story_1020_10201501_21_dialog_content = "¡Oh no, es mi insignia de Illumina!",
  ui_story_1020_10201501_22_dialog_content = "¿Qué debería hacer ahora? No puedo volver a recogerlo...",
  ui_story_1020_10201501_23_dialog_content = "Espera, ¿cómo es que una pequeña insignia iluminó todo el río de esta manera?",
  ui_story_1020_10201501_24_dialog_content = "Todo está tranquilo en el campo, pero debajo de la superficie del río es otra cuestión completamente.",
  ui_story_1020_10201501_25_dialog_content = "La superficie del lago... Guau, es tan fría y no parece real.",
  ui_story_1020_10201501_26_dialog_content = "La superficie del lago...",
  ui_story_1020_10201501_27_dialog_content = "Estás despierto, PlayerName.",
  ui_story_1020_10201501_28_dialog_content = "¿Dónde estoy?",
  ui_story_1020_10201501_29_dialog_content = "¿Carleen? ¿Qué estás... Qué estoy haciendo aquí?",
  ui_story_1020_10201501_30_dialog_content = "¿No recuerdas nada?",
  ui_story_1020_10201501_31_dialog_content = "Acabo de tener un sueño sobre la superficie brillante de un lago... Pero por alguna razón no puedo recordar ninguno de los detalles...",
  ui_story_1020_10201501_32_dialog_content = "¡Oh, eso es correcto! ¿Está bien Illumina?",
  ui_story_1020_10201501_33_dialog_content = "Je, debes estar bien si puedes hablar con tanta energía.",
  ui_story_1020_10201501_34_dialog_content = "Buena recuperación después de tres días enteros de sueño. Es bueno ser joven.",
  ui_story_1020_10201501_35_dialog_content = "¿Dormí durante tres días seguidos?",
  ui_story_1020_10201501_36_dialog_content = "Sí. El capitán Carleen ya ha visitado tres veces.",
  ui_story_1020_10201501_37_dialog_content = "Sentí que algo más que eso perturbaría a Vivian...",
  ui_story_1020_10201501_38_dialog_content = "Originalmente, esto fue una <color=#FFB400>reunión conjunta</color> organizada por la Federación de Illumina. Lo siento, no pudimos decidir una hora antes.",
  ui_story_1020_10201501_39_dialog_content = "Pero ahora que PlayerName está despierto, y el Capitán de la Guardia está aquí, ¿por qué no hacerlo hoy?",
  ui_story_1020_10201501_40_dialog_content = "Claro, estoy bien con eso.",
  ui_story_1020_10201501_41_dialog_content = "Una reunión conjunta... ¿Qué pasó mientras estaba fuera? ¿Y qué pasa con Ulysses?",
  ui_story_1020_10201501_42_dialog_content = "Está muerto. El incidente con el Ingeniero también se ha resuelto por el momento.",
  ui_story_1020_10201501_43_dialog_content = "Después de revisar todo el asunto, puedo más o menos adivinar lo que viste en su mente, PlayerName.",
  ui_story_1020_10201501_44_dialog_content = "Después de buscar en su laboratorio, encontramos una gran cantidad de registros experimentales que contienen información vital.",
  ui_story_1020_10201501_45_dialog_content = "Pero lo que más me sorprende es que Ulysses logró resistir al Ingeniero durante tanto tiempo a pesar de estar en su punto de mira.",
  ui_story_1020_10201501_46_dialog_content = "Sin embargo, como dijo el Gran Mariscal, mientras Ulysses miraba a la Zona Oscura, esta lo estaba corrompiendo a cambio...",
  ui_story_1020_10201501_47_dialog_content = "Antes de que se diera cuenta, se convirtió en uno de los Eclipse.",
  ui_story_1020_10201501_48_dialog_content = "Sí. Parece que la crisis a la que nos enfrentamos fue algo que la ciudad de Gannon no había visto en más de seiscientos años.",
  ui_story_1020_10201501_49_dialog_content = "Pero gracias al arduo trabajo de todos, nuestra ciudad sobrevivió. Tampoco podríamos haberlo hecho sin el Dr. Algol.",
  ui_story_1020_10201501_50_dialog_content = "Entonces, ¿dónde está ella?",
  ui_story_1020_10201501_51_dialog_content = "Pensé que el Dr. Algol estaría en coma durante días como tú.",
  ui_story_1020_10201501_52_dialog_content = "Pero después de que la crisis terminó, ella reanudó su investigación como si nada hubiera pasado.",
  ui_story_1020_10201501_53_dialog_content = "Ella debería estar fuera hoy buscando piezas para reparar a Guardian One, creo.",
  ui_story_1020_10201501_54_dialog_content = "¿Ya está trabajando en restaurar a Guardian One? Pero Algol casi nunca sale.",
  ui_story_1020_10201501_55_dialog_content = "Probablemente sea porque puede montar el nuevo transporte de Illumina.",
  ui_story_1020_10201501_56_dialog_content = "¿El nuevo transporte de Illumina? ¿A qué te refieres?",
  ui_story_1020_10201501_57_dialog_content = "Ulysses pasó tantos años investigando a los Colosos, y el equipo de ingeniería logró crear versiones en miniatura de ellos basándose en su investigación.",
  ui_story_1020_10201501_58_dialog_content = "Estos vehículos de pequeña escala nos ayudaron a evacuar a muchos de nuestros residentes durante el incidente. También los utilizaremos para la próxima expedición conjunta.",
  ui_story_1020_10201501_59_dialog_content = "...",
  ui_story_1020_10201501_60_option_content = "Ulysses...",
  ui_story_1020_10201501_61_option_content = "Vehículos a pequeña escala...",
  ui_story_1020_10201501_62_dialog_content = "¿Realmente van a continuar con su investigación?",
  ui_story_1020_10201501_63_dialog_content = "Sé lo que te preocupa.",
  ui_story_1020_10201501_64_dialog_content = "No se trata solo de estos pequeños vehículos, sino también de Aurorians como Sean que son capaces de explorar la Zona Oscura también.",
  ui_story_1020_10201501_65_dialog_content = "La realidad es que nada de esto sería posible sin la investigación de Ulysses.",
  ui_story_1020_10201501_66_dialog_content = "Estoy seguro de que tomar esta decisión no fue menos difícil que elegir otorgar plena autoridad de investigación al Sistema Guardian durante la crisis de Darkover.",
  ui_story_1020_10201501_67_dialog_content = "Pero esta vez, a pesar de que el Consejo de Ciencias y todos nuestros principales científicos en el Laboratorio de Investigación han tenido la oportunidad de evaluar y votar sobre su investigación...",
  ui_story_1020_10201501_68_dialog_content = "Todos aún están divididos sobre si aprobarlo o no.",
  ui_story_1020_10201501_69_dialog_content = "En lo que a mí respecta, proteger las vidas de la Federación Illumina es nuestra prioridad más importante.",
  ui_story_1020_10201501_70_dialog_content = "¿Eso significa que estabas en contra de usar su investigación?",
  ui_story_1020_10201501_71_dialog_content = "Todo lo contrario, en realidad.",
  ui_story_1020_10201501_72_dialog_content = "Parte de garantizar nuestra supervivencia es tomar pequeños riesgos calculados. Necesitamos estar completamente conscientes de esos riesgos, así como de cómo aprovecharlos al máximo.",
  ui_story_1020_10201501_73_dialog_content = "Debemos continuar estudiando a nuestros enemigos y probando nuestros límites si queremos mejorar las condiciones de supervivencia para todos los aurorianos.",
  ui_story_1020_10201501_74_dialog_content = "¿Es por eso que estás organizando esta expedición conjunta? Espera... ¿Eso significa que Lumopolis también está en peligro?",
  ui_story_1020_10201501_75_dialog_content = "Lumopolis nunca estuvo en peligro, pero muchos reliquias exhibieron patrones de Lumina caóticos, lo que llamó la atención del Señor de la Ciudad.",
  ui_story_1020_10201501_76_dialog_content = "Después de lo que ocurrió en Gannon City, el Comité está dispuesto a explorar más vías de cooperación sobre la expedición conjunta con las otras facciones.",
  ui_story_1020_10201501_77_dialog_content = "Carleen ha aceptado servir como capitán del Equipo de Expedición de Lumopolis. Con el tiempo, Northland y Umbraton también enviarán a sus propios representantes aquí.",
  ui_story_1020_10201501_78_dialog_content = "Oh, Gran Mariscal, los entrometidos en el Desierto de Rediesel deben haber escuchado las noticias en algún lugar, y recibí el mensaje de que quieren ser parte de ello.",
  ui_story_1020_10201501_79_dialog_content = "Quiero saber tus pensamientos sobre esto, PlayerName.",
  ui_story_1020_10201501_80_dialog_content = "Mis pensamientos...",
  ui_story_1020_10201501_81_dialog_content = "En el pasado, nunca tomé realmente la iniciativa de buscar algo. Simplemente dejé que los rastros de los Celestitas guiaran mi camino.",
  ui_story_1020_10201501_82_dialog_content = "Pero mientras reparaba a Soroz, me di cuenta de que no todas esas huellas llevaban a cosas buenas...",
  ui_story_1020_10201501_83_dialog_content = "Ni siquiera sabía si era una buena persona o no...",
  ui_story_1020_10201501_84_dialog_content = "Pero después de lo que pasé con Vice y Soroz, esa sensación de agradable sorpresa por lo inesperado desapareció por completo.",
  ui_story_1020_10201501_85_dialog_content = "Y porque lo perdí, tengo que recuperarlo... lo antes posible.",
  ui_story_1020_10201501_86_dialog_content = "Eso me recuerda... Últimamente, siento que miré al pasado, aunque podría haber sido el futuro...",
  ui_story_1020_10201501_87_dialog_content = "De cualquier manera, hay un lugar que necesito investigar.",
  ui_story_1020_10201501_88_dialog_content = "Podría ser la Zona Oscura, o algún lugar aún más lejano e inalcanzable.",
  ui_story_1020_10201501_89_dialog_content = "¿Por qué tengo la sensación de destino al respecto?",
  ui_story_1020_10201501_90_dialog_content = "¿En serio? Bueno, un amigo del este una vez leyó mi fortuna y dijo que mi destino no estaba exactamente \"en la lista\"...",
  ui_story_1020_10201501_91_dialog_content = "Los Caelestites son capaces de liberarse de las ataduras innatas, por eso no creo en el destino.",
  ui_story_1020_10201501_92_dialog_content = "Con convicción, coraje y sabiduría, seguramente recuperarás lo que perdiste.",
  ui_story_1020_10201501_93_dialog_content = "¡Seguro!",
  ui_story_1020_10201501_94_dialog_content = "Me alegra que pienses de esta manera.",
  ui_story_1020_10201501_95_dialog_content = "Como Gran Mariscal de la Federación Illumina, tengo la responsabilidad de encontrar y recuperar a mis compatriotas, naturalmente, eso incluye a Charon, Vice y sus compañeros de escuadrón.",
  ui_story_1020_10201501_96_dialog_content = "Si decides aceptar, la Federación Illumina está dispuesta a ayudarte a explorar la Zona Oscura y buscar Soroz.",
  ui_story_1020_10201501_97_dialog_content = "Sí. Tú eres la razón por la que Lumopolis se unió a esta expedición.",
  ui_story_1020_10201501_98_dialog_content = "Gracias a todos...",
  ui_story_1020_10201501_99_dialog_content = "¡Dado que tengo la confianza y el apoyo de todos, definitivamente tengo que ser parte de esta expedición conjunta!",
  ui_story_1020_10201501_100_dialog_content = "Pero, ¿por dónde deberíamos empezar?",
  ui_story_1020_10201501_101_dialog_content = "Para ser honesto, hay bastantes lugares para elegir.",
  ui_story_1020_10201501_102_dialog_content = "¿Qué es eso?",
  ui_story_1020_10201501_103_dialog_content = "La memoria de Helios.",
  ui_story_1020_10201501_104_dialog_content = "Qué libro tan grande... ¿Y ya está terminado? Chandra es prácticamente un rayo engrasado.",
  ui_story_1020_10201501_105_dialog_content = "Fue un día largo después de todo, y todos trabajaban al máximo incluso con un invitado inesperado que nos retrasaba.",
  ui_story_1020_10201501_106_dialog_content = "Veo que estás bien, así que tal vez finalmente pueda tener una buena noche de sueño ahora.",
  ui_story_1020_10201501_107_dialog_content = "Oh, ¿qué fue eso sobre una superficie de lago brillante en tu sueño, PlayerName?",
  ui_story_1020_10201501_108_dialog_content = "Sí... Vi la superficie de un lago brillante...",
  ui_story_1020_10201501_109_dialog_content = "Y también una insignia que parece muy familiar...",
  ui_story_1020_10201501_110_dialog_content = "¿Pueden pensar en algo así?",
  ui_story_1020_10201501_111_dialog_content = "Cuando estaba siendo tragado por la oscuridad, de repente escuché el sonido de un piano. Después de eso, la luz comenzó a entrar...",
  ui_story_1020_10201501_112_dialog_content = "<color=#e8d9bb>¡Sploosh—!</color>",
  ui_story_1020_10201501_113_dialog_content = "¿Escuchan esa música, todos?",
  ui_story_1020_10201501_114_dialog_content = "¡Lo oigo!",
  ui_story_1020_10201501_115_dialog_content = "¿Qué?",
  ui_story_1020_10201501_116_dialog_content = "Bueno, se detuvo después de que Merry gritó en voz alta.",
  ui_story_1020_10201501_117_dialog_content = "¡Alaba al Señor de la Verdad!",
  ui_story_1020_10201501_118_dialog_content = "Has encontrado la marca, señorita Vice. Por favor, guíanos a tu manera.",
  ui_story_1020_10201501_119_dialog_content = "¿Yo?",
  ui_story_1020_10201501_120_dialog_content = "Cuando tú y el Caelestite activaron el Colossus, despertaron este río dormido.",
  ui_story_1020_10201501_121_dialog_content = "Desde ese momento, diste vuelta a una nueva página en la historia de Eoria.",
  ui_story_1020_10201501_122_dialog_content = "Por favor, guíanos nuevamente a tu manera.",
  ui_story_1020_10201501_123_dialog_content = "Por favor, guíanos nuevamente a tu manera.",
  ui_story_1020_10201501_124_dialog_content = "?",
  ui_story_1020_10201501_125_dialog_content = "...",
  ui_story_1020_10201501_126_dialog_content = "No me digas...",
  ui_story_1020_10201501_127_dialog_content = "Esta cosa del piano es el panel de control del Colossus, ¿verdad?",
  ui_story_1020_10201501_128_dialog_content = "Déjame ayudarte a poner en marcha el Colossus, Navegador.",
  ui_story_1020_10201501_129_dialog_content = "¿Conmigo? Eres un Aurorian, Vice. No tienes habilidades psíquicas.",
  ui_story_1020_10201501_130_dialog_content = "Pero puedo ser tu fuerza. Yo... puedo ayudar.",
  ui_story_1020_10201501_131_dialog_content = "?",
  ui_story_1020_10201501_132_dialog_content = "Cree en mí, PlayerName. Tu y yo... Realmente no somos tan diferentes.",
  ui_story_1020_10201501_133_dialog_content = "Es una larga historia. ¡Te lo diré la próxima vez cuando tenga la oportunidad!",
  ui_story_1020_10201501_134_dialog_content = "Déjame mostrarte cómo se \"juega\"...",
  ui_story_1020_10201501_135_dialog_content = "Lo que dijo la señorita Victoria me recordó ciertas cosas...",
  ui_story_1020_10201501_136_dialog_content = "...",
  ui_story_1020_10201501_137_dialog_content = "Es muy simple. Es como tocar el piano.",
  ui_story_1020_10201501_138_dialog_content = "...",
  ui_story_1020_10201501_139_dialog_content = "¡Pero no hay puntaje aquí! ¿Puedes señalar qué teclas debo tocar?",
  ui_story_1020_10201501_140_dialog_content = "...",
  ui_story_1020_10201501_141_dialog_content = "Puedo sentir... la energía fluyendo.",
  ui_story_1020_10201501_142_dialog_content = "Sí. Es como una conversación, aunque no entiendo el idioma de Colossus.",
  ui_story_1020_10201501_143_dialog_content = "El idioma está dentro de las teclas del piano.",
  ui_story_1020_10201501_144_dialog_content = "Terminemos el comando de activación, Vice.",
  ui_story_1020_10201501_145_dialog_content = "...",
  ui_story_1020_10201501_146_dialog_content = "Si así es como debo guiarte, sé qué hacer ahora.",
  ui_story_1020_10201501_147_dialog_content = "¡Escuchen, chicos! ¡Es un piano tocando!",
  ui_story_1020_10201501_148_dialog_content = "El río que brilla con una luz misteriosa es el santuario del Señor.",
  ui_story_1020_10201501_149_dialog_content = "Escucha la melodía enigmática y revela verdades infinitas.",
  ui_story_1020_10201501_150_dialog_content = "May el Señor de la Verdad sea testigo de nuestra exploración, camina con nosotros y ven.",
  ui_story_1021_10210100_1_dialog_content = "<color=#e8d9bb>Hace muchos años cerca de las fronteras de Northland...</color>",
  ui_story_1021_10210100_2_dialog_content = "Una vez que cruce la colina adelante, Su Majestad, estará fuera del territorio de Northland.",
  ui_story_1021_10210100_3_dialog_content = "...",
  ui_story_1021_10210100_4_dialog_content = "La tundra tiene una vasta extensión. Todavía hay gente de Northland viviendo en el otro lado.",
  ui_story_1021_10210100_5_dialog_content = "Deberías volver ahora, señor Novio. Esto es algo que quiero hacer.",
  ui_story_1021_10210100_6_dialog_content = "Los reyes y reinas del pasado, así como el vasto e ilimitado invierno, recordarán todo lo que has hecho por Northland.",
  ui_story_1021_10210100_7_dialog_content = "El poder para defender Northland no proviene de mí, sino de la tierra misma.",
  ui_story_1021_10210100_8_dialog_content = "Para ese fin, no defraudaré a mis predecesores.",
  ui_story_1021_10210100_9_dialog_content = "Por el Norte, vivimos para defender esta tierra.",
  ui_story_1021_10210100_10_dialog_content = "<color=#e8d9bb>Crujido-</color>",
  ui_story_1021_10210100_11_dialog_content = "La nieve dejó de caer, veo.",
  ui_story_1021_10210100_12_dialog_content = "No recuerdo un clima tan agradable en este bosque en particular...",
  ui_story_1021_10210100_13_dialog_content = "¡Ja!",
  ui_story_1021_10210100_14_dialog_content = "¿Ah?",
  ui_story_1021_10210100_15_dialog_content = "Te estoy advirtiendo, extraño. ¡Vete ahora o enfrenta la ira del Jefe Tiare!",
  ui_story_1021_10210100_16_dialog_content = "¿Eres Tiare?",
  ui_story_1021_10210100_17_dialog_content = "¿Como sabes mi nombre?",
  ui_story_1021_10210100_18_dialog_content = "Ejem... Incluso si de alguna manera aprendieras mi nombre, ¡nunca te permitiría poner un pie dentro del asentamiento de la tribu Snow Fox!",
  ui_story_1021_10210100_19_dialog_content = "¿Eres de la tribu Fox de nieve? ¿Dónde están tus padres?",
  ui_story_1021_10210100_20_dialog_content = "¡Ambos están ocupados protegiendo Northland! ¡Ahora deja de divagar y dime qué estás haciendo aquí!",
  ui_story_1021_10210100_21_dialog_content = "Tiare, ¡ven a ver lo que la abuela te trajo!",
  ui_story_1021_10210100_22_dialog_content = "¡Vaya, son mis ramitas aromáticas favoritas!",
  ui_story_1021_10210100_23_dialog_content = "Ahora dime, ¿por qué no estás en el altar sino haciendo travesuras aquí afuera?",
  ui_story_1021_10210100_24_dialog_content = "Bueno... El anciano dijo que ese no es lugar para niños...",
  ui_story_1021_10210100_25_dialog_content = "Veo que ese viejo zorro se está volviendo senil ahora.",
  ui_story_1021_10210100_26_dialog_content = "Abuela, ¡hice algo genial hoy! Mira, estoy manteniendo a este extraño fuera de nuestro asentamiento!",
  ui_story_1021_10210100_27_dialog_content = "...",
  ui_story_1021_10210100_28_dialog_content = "¡Muy bien, Tiare!",
  ui_story_1021_10210100_29_dialog_content = "Ahora, ¿todavía recuerdas la leyenda de los Tres Pinos?",
  ui_story_1021_10210100_30_dialog_content = "¡Lo hago!",
  ui_story_1021_10210100_31_dialog_content = "Ella es muy inteligente y no necesita que le repitas el mito otra vez.",
  ui_story_1021_10210100_32_dialog_content = "Si no lo hago, nadie recordará, y no pasará mucho tiempo antes de que ella comience a aprender y a contar las historias de otras personas.",
  ui_story_1021_10210100_33_dialog_content = "...",
  ui_story_1021_10210100_34_dialog_content = "Soy Bethlehem. Encantado de conocerlos a ambos.",
  ui_story_1021_10210100_35_dialog_content = "Mi gratitud a tus antepasados por proteger a Northland. Ahora me despido.",
  ui_story_1021_10210100_36_dialog_content = "...",
  ui_story_1021_10210100_37_dialog_content = "<color=#e8d9bb>Crujido-</color>",
  ui_story_1021_10210100_38_dialog_content = "Mencionaste que la luz del Faro llegaría hasta aquí.",
  ui_story_1021_10210100_39_dialog_content = "...",
  ui_story_1021_10210100_40_dialog_content = "La tribu no ha escuchado los llantos de un recién nacido durante muchos años.",
  ui_story_1021_10210100_41_dialog_content = "Estoy agradecido por cada guardia producido por la Tribu Fox de Nieve.",
  ui_story_1021_10210100_42_dialog_content = "Esos niños no nacieron en un majestuoso palacio sino en un bosque que podía ser asaltado por los Eclipsites en cualquier momento.",
  ui_story_1021_10210100_43_dialog_content = "Una generación tras otra, sus antepasados murieron y fueron enterrados aquí para proteger a Northland.",
  ui_story_1021_10210100_44_dialog_content = "Puedo llevarla de regreso al Palacio de Invierno.",
  ui_story_1021_10210100_45_dialog_content = "Si los Eclipsites arrasan Northland, ¿te irías a otro lugar?",
  ui_story_1021_10210100_46_dialog_content = "Nunca.",
  ui_story_1021_10210100_47_dialog_content = "Northland nos crió y nos protegió. Debemos protegerla a cambio, a través de todas las generaciones.",
  ui_story_1021_10210100_48_dialog_content = "¿Por qué estoy recordando lo que sucedió ese día...",
  ui_story_1021_10210100_49_dialog_content = "El clima a lo largo de las fronteras ha tomado un giro inusual, Su Majestad, y la luz del Faro ha cambiado ligeramente.",
  ui_story_1021_10210100_50_dialog_content = "Todo esto no es coincidencia... Ya lo había anticipado.",
  ui_story_1021_10210100_51_dialog_content = "Como anticipaste, la crisis en Illumina antes no fue un incidente aislado, y la construcción de puestos avanzados no está progresando sin problemas...",
  ui_story_1021_10210100_52_dialog_content = "Debemos vigilar de cerca la Zona Oscura.",
  ui_story_1021_10210100_53_dialog_content = "Es imperativo lanzar una expedición conjunta ya que es vital para el futuro de todos los Aurorianos. Además, estamos a solo unos días de la reunión conjunta.",
  ui_story_1021_10210100_54_dialog_content = "Iré a echar un vistazo.",
  ui_story_1021_10210100_55_dialog_content = "¿Ahora mismo?",
  ui_story_1021_10210100_56_dialog_content = "Sí. ¿Has visto a Tiare?",
  ui_story_1021_10210100_57_dialog_content = "Ella tiene-",
  ui_story_1021_10210100_58_dialog_content = "¿Va a salir, Su Majestad? Por favor, permítame acompañarle.",
  ui_story_1021_10210100_59_dialog_content = "...",
  ui_story_1021_10210100_60_dialog_content = "Me voy solo por unos días. Novio está a cargo del Palacio de Invierno mientras tanto. Espero que puedas mantenerte alerta y listo mientras estoy fuera.",
  ui_story_1021_10210100_61_dialog_content = "¡Muy bien, Su Majestad!",
  ui_story_1021_10210100_62_dialog_content = "(¿Por qué la reina tiene tanta prisa?)",
  ui_story_1021_10210100_63_dialog_content = "Las huellas en esos alféizares de las ventanas deberían ser limpiadas.",
  ui_story_1021_10210100_64_dialog_content = "¡Seguro!",
  ui_story_1021_10210100_65_dialog_content = "<color=#e8d9bb>¡Awoo!</color>",
  ui_story_1021_10210100_66_dialog_content = "...",
  ui_story_1021_10210100_67_dialog_content = "No puedo creer que todavía no haya respuesta...",
  ui_story_1021_10210100_68_dialog_content = "Su Majestad ha estado ausente durante días ahora.",
  ui_story_1021_10210100_69_dialog_content = "Si yo, como su guardia, no puedo estar a su lado, ¿cómo se supone que debo mantenerme alerta y preparado?",
  ui_story_1021_10210100_70_dialog_content = "<color=#e8d9bb>¡Awoo!</color>",
  ui_story_1021_10210100_71_dialog_content = "son ustedes...",
  ui_story_1021_10210100_72_dialog_content = "Bu ju...",
  ui_story_1021_10210100_73_dialog_content = "¿Qué?",
  ui_story_1021_10210100_74_dialog_content = "¡Awoo!",
  ui_story_1021_10210100_75_dialog_content = "¿Cómo ocurrió eso?",
  ui_story_1021_10210100_76_dialog_content = "Regresé justo antes de que la reina dejara el palacio. El anciano y yo incluso nos deleitamos con la cosecha del año...",
  ui_story_1021_10210100_77_dialog_content = "Pero como guardia de Su Majestad, parece que no puedo—",
  ui_story_1021_10210100_78_dialog_content = "¡Awooooooo!",
  ui_story_1021_10210100_79_dialog_content = "¡Entendido! ¡Volveré contigo ahora mismo!",
  ui_story_1021_10210100_80_dialog_content = "¡Zorro de nieve! ¡Es un zorro de nieve!",
  ui_story_1021_10210100_81_dialog_content = "¡Interrumpiste la conferencia del Sr. Antony otra vez! ¿Dónde viste un zorro de nieve?",
  ui_story_1021_10210100_82_dialog_content = "¡Vamos, eso es solo un conejo saltando por ahí!",
  ui_story_1021_10210100_83_dialog_content = "Pero realmente lo vi... ¡Se veía exactamente como el zorro de nieve en el libro!",
  ui_story_1021_10210100_84_dialog_content = "Admito que es raro ver un zorro de nieve en la ciudad... Me crees, ¿verdad? Sr. Antony?",
  ui_story_1021_10210100_85_dialog_content = "Se dice que antes de que Northland se llamara Northland, los zorros de nieve se hicieron amigos de algunos aurorianos y protegieron sus hábitats juntos.",
  ui_story_1021_10210100_86_dialog_content = "¿Todavía quedan zorros de nieve en Northland ahora?",
  ui_story_1021_10210100_87_dialog_content = "Creo que sí. Son inteligentes y etéreos. Se supone que algunos han vivido durante cientos, incluso miles de años...",
  ui_story_1021_10210100_88_dialog_content = "¿Miles? ¿Qué tan viejos son?",
  ui_story_1021_10210100_89_dialog_content = "Mucho más antiguo que el pino de nieve más viejo en Northland. ¿Recuerdas la historia de los Tres Pinos que te conté antes?",
  ui_story_1021_10210100_90_dialog_content = "¡Lo hacemos!",
  ui_story_1021_10210100_91_dialog_content = "Antes de que Northland se convirtiera en el Northland que conocemos, había tres grandes pinos nevados que soñaban con proteger la tierra...",
  ui_story_1021_10210100_92_dialog_content = "Pero todas las demás criaturas se burlaban de ellos. ¿Cómo podrían los simples árboles de pino de nieve proteger todo Northland?",
  ui_story_1021_10210100_93_dialog_content = "Luego, los leñadores talaron los tres árboles en la guerra posterior.",
  ui_story_1021_10210100_94_dialog_content = "Uno fue utilizado en la construcción de un granero de almacenamiento...",
  ui_story_1021_10210100_95_dialog_content = "Uno fue convertido en una mesa y vendido a una familia pobre...",
  ui_story_1021_10210100_96_dialog_content = "Nadie quería el tercero, así que se guardó en un almacén y nunca volvió a ver el sol.",
  ui_story_1021_10210100_97_dialog_content = "Muchos años después, una dama embarazada dio a luz a un niño en ese mismo corral...",
  ui_story_1021_10210100_98_dialog_content = "El infante nacido en el montón de heno fue nuestro primer Queen del Norte!",
  ui_story_1021_10210100_99_dialog_content = "Muchos años después, la reina ayudó a esa pobre familia.",
  ui_story_1021_10210100_100_dialog_content = "En esa misma mesa, los cuatro hermanos sin un centavo juraron ante la reina que defenderían a la familia real durante generaciones.",
  ui_story_1021_10210100_101_dialog_content = "¡Así es como sus descendientes asumieron el manto de los Guardias Reales de Northland!",
  ui_story_1021_10210100_102_dialog_content = "Vaya. Lo siento, Sr. Antony, olvidé la historia del último árbol...",
  ui_story_1021_10210100_103_dialog_content = "Más tarde, la reina encontró el árbol en el almacén y lo convirtió en un cetro.",
  ui_story_1021_10210100_104_dialog_content = "Ese cetro puede convocar a todas las criaturas de Northland para defender el territorio.",
  ui_story_1021_10210100_105_dialog_content = "Los pinos nevados son nuestros ángeles guardianes. Solo con ellos podemos asegurar la seguridad y la paz en nuestra patria para las generaciones venideras.",
  ui_story_1021_10210100_106_dialog_content = "...",
  ui_story_1021_10210100_107_dialog_content = "¿Cómo puede suceder esto...",
  ui_story_1021_10210100_108_dialog_content = "Los zorros... El anciano... ¿Qué pasó aquí?",
  ui_story_1021_10210100_109_dialog_content = "...",
  ui_story_1021_10210100_110_dialog_content = "<color=#e8d9bb>¡Awoooo!</color>",
  ui_story_1021_10210201_1_dialog_content = "<color=#e8d9bb>Comando Temporal, Comité de la Expedición Conjunta Astra</color>",
  ui_story_1021_10210201_2_dialog_content = "Ha pasado un tiempo, PlayerName!",
  ui_story_1021_10210201_3_dialog_content = "De hecho, Wendy. ¡Siempre llegas a tiempo como siempre!",
  ui_story_1021_10210201_4_dialog_content = "¡Está atascado! Esta bufanda no es más que problemas...",
  ui_story_1021_10210201_5_dialog_content = "Oye, ¡Pepi también llegó a tiempo! ¿Dónde está tu protegido Tweety?",
  ui_story_1021_10210201_6_dialog_content = "Para ser honesto, no tengo grandes expectativas sobre ella. Todavía le queda un largo camino por recorrer para ser una mensajera calificada.",
  ui_story_1021_10210201_7_dialog_content = "Ella grita, \"¡Estaré aquí mismo!\" cada vez que la apuras, pero quién sabe dónde podría estar, recogiendo las letras que perdió!",
  ui_story_1021_10210201_8_dialog_content = "Aunque como mentor, tengo que tolerar su impaciencia, descuido y la ocasional irresponsabilidad...",
  ui_story_1021_10210201_9_dialog_content = "Parece que ella ha aprendido algo de eso de ti... Espera un minuto, sonaba como si te estuvieras describiendo a ti mismo, en realidad...",
  ui_story_1021_10210201_10_dialog_content = "¡Al menos ella me tiene para cuidar de ella!",
  ui_story_1021_10210201_11_dialog_content = "¿Pero quién cuida de mí? Acabo de regresar de mis vacaciones y Vivian me envió a revisar el puesto de expedición conjunta en Crepúsculo.",
  ui_story_1021_10210201_12_dialog_content = "¿Qué tipo de lugar abandonado es Crepúsculo de todos modos? La tormenta de arena es sombría, llena de Darkflow, y está en todas partes.",
  ui_story_1021_10210201_13_dialog_content = "Me dejó aturdido todo el día y demasiado lento para poder trabajar...",
  ui_story_1021_10210201_14_dialog_content = "¡Urgh! No puedo concentrarme ni un minuto... Tengo que encontrar un nuevo trabajo el próximo mes.",
  ui_story_1021_10210201_15_option_content = "¡Ahí estás, Vivian!",
  ui_story_1021_10210201_16_dialog_content = "!",
  ui_story_1021_10210201_17_dialog_content = "Aunque eso es de lo que mis colegas siempre se quejan, les animo y les recuerdo que la Señora Vivian nos trata bastante bien!",
  ui_story_1021_10210201_18_dialog_content = "La programación es razonable con buen salario. También puedes crecer a lo largo de diferentes tareas. ¿Dónde más puedes encontrar un trabajo maravilloso como este?",
  ui_story_1021_10210201_19_dialog_content = "Vaya, seguro que cambiaste de opinión muy rápido.",
  ui_story_1021_10210201_20_option_content = "Bienvenido al Equipo de Expedición de la Zona Oscura.",
  ui_story_1021_10210201_21_dialog_content = "¿Zona Oscura? Me largo de aquí. Comparado con eso, el trabajo de mensajero es diez mil veces mejor.",
  ui_story_1021_10210201_22_dialog_content = "Piénsalo... Puedo programar las entregas como quiera, y no solo soy libre para moverme, sino que no hay peligro de perder el trabajo...",
  ui_story_1021_10210201_23_dialog_content = "Entonces, agradezco la oferta, pero me conformaré con... uh, ¡seguir siendo un buen mensajero!",
  ui_story_1021_10210201_24_dialog_content = "Creo que tengo derecho a pedirle a Vivian un incentivo ya que te he convencido de quedarte...",
  ui_story_1021_10210201_25_dialog_content = "Es hora de la reunión, Gran Mariscal, pero el representante de Northland aún está ausente.",
  ui_story_1021_10210201_26_dialog_content = "Recibí un mensaje de Northland esta mañana. Podemos proceder como de costumbre.",
  ui_story_1021_10210201_27_dialog_content = "Sí, Gran Mariscal.",
  ui_story_1021_10210201_28_dialog_content = "Representantes honorados, gracias por asistir a la primera reunión de la Conferencia Conjunta de Expedición de Astra.",
  ui_story_1021_10210201_29_dialog_content = "Soy Vivian, Jefe de Estado Mayor de la Federación Illumina. Si no hay objeciones, comenzaremos.",
  ui_story_1021_10210201_30_dialog_content = "Nada de mí.",
  ui_story_1021_10210201_31_dialog_content = "Como representante del Señor de las Sombras, no tengo ninguna objeción.",
  ui_story_1021_10210201_32_dialog_content = "No veo otra opción que empezar en este caso.",
  ui_story_1021_10210201_33_dialog_content = "Entonces, comencemos oficialmente la reunión.",
  ui_story_1021_10210201_34_dialog_content = "Elegimos esta ubicación abierta con la esperanza de que podamos llegar a un acuerdo sobre un futuro para los Aurorianos juntos.",
  ui_story_1021_10210201_35_dialog_content = "En primer lugar, me gustaría agradecer a la Unión de Mensajería por sus contribuciones durante la construcción de los puestos avanzados.",
  ui_story_1021_10210201_36_dialog_content = "Para garantizar que todas las facciones puedan responder a la operación del Equipo de Expedición de la Zona Oscura de manera oportuna, la Unión de Mensajería proporcionará apoyo en muchas áreas...",
  ui_story_1021_10210201_37_dialog_content = "Incluyendo la difusión de información entre puestos avanzados y la notificación de pistas relacionadas con la Zona Oscura. La Unión de Mensajería asumirá la tarea vital de monitoreo y validación.",
  ui_story_1021_10210201_38_dialog_content = "¡Sí! ¡La Unión de Mensajería siempre cumple!",
  ui_story_1021_10210201_39_dialog_content = "Ahora, el Gran Mariscal de la Federación Illumina presentará el plan para la expedición conjunta y solicitará sus comentarios.",
  ui_story_1021_10210201_40_dialog_content = "En cuanto a la ruta, se mencionó en nuestra correspondencia anterior...",
  ui_story_1021_10210201_41_dialog_content = "Planeamos construir varios <color=#FFB400>puestos avanzados</color> cerca de la Zona Oscura para facilitar el apoyo y el reconocimiento.",
  ui_story_1021_10210201_42_dialog_content = "Basándonos en la ubicación geográfica de las diversas facciones, estableceremos <color=#FFB400>tres puestos avanzados</color> en el norte de Astra.",
  ui_story_1021_10210201_43_dialog_content = "El primero está en <color=#FFB400>Twilight</color> al noroeste. Su escala y ventaja actuales lo convierten en una base de respaldo muy adecuada para el Equipo de Expedición de la Zona Oscura.",
  ui_story_1021_10210201_44_dialog_content = "El Señor de la Ciudad de Lumopolis y yo hemos llegado a un acuerdo sobre la gobernanza mutua de Crepúsculo. La construcción formal del puesto avanzado allí es prueba de nuestro consenso.",
  ui_story_1021_10210201_45_dialog_content = "Se establecerá un comando estratégico en Twilight para proporcionar el apoyo necesario al Equipo de Expedición.",
  ui_story_1021_10210201_46_dialog_content = "Leo estará a cargo del puesto avanzado y actualizará regularmente a la sede general sobre el progreso.",
  ui_story_1021_10210201_47_dialog_content = "Las otras dos serán el <color=#FFB400>Puesto Avanzado de Eraveil</color> y el <color=#FFB400>Puesto Avanzado de Northland</color>.",
  ui_story_1021_10210201_48_dialog_content = "Actualmente estamos evaluando la viabilidad del Puesto de Eraveil, teniendo en cuenta el impacto de las ruinas subterráneas locales.",
  ui_story_1021_10210201_49_dialog_content = "La construcción del puesto avanzado de Northland se prolongará debido al entorno único. Haré un anuncio una vez que tenga la confirmación del Queen del Norte.",
  ui_story_1021_10210201_50_dialog_content = "Por último, me gustaría aclarar una cosa.",
  ui_story_1021_10210201_51_dialog_content = "La ruta y las coordenadas para la expedición fueron el resultado de los esfuerzos entre el Dr. Algol de la Federación Illumina y un oficial de inteligencia.",
  ui_story_1021_10210201_52_dialog_content = "Toda la información ha sido validada muchas veces para garantizar seguridad y precisión. La compartiremos con todos ustedes con el propósito de participación mutua y protección.",
  ui_story_1021_10210201_53_dialog_content = "Puedes hacer preguntas sobre la información mencionada anteriormente.",
  ui_story_1021_10210201_54_dialog_content = "Entiendo que Illumina ha pagado caro para obtener los datos sobre la Zona Oscura.",
  ui_story_1021_10210201_55_dialog_content = "Pero no hay escasez de personas ambiciosas en la Federación Illumina, y esto es sobre el futuro de los Aurorians. ¿Deberías estar decidiendo tú solo la lista para la expedición?",
  ui_story_1021_10210201_56_dialog_content = "Por supuesto. En Illumina, no juzgamos a las personas por su ambición, sino por su coraje y determinación para superar desafíos.",
  ui_story_1021_10210201_57_dialog_content = "En primer lugar, ya tenemos un <color=#FFB400>equipo de exploración</color> de élite en posición dentro de la Zona Oscura. Allanarán el camino para las operaciones de seguimiento.",
  ui_story_1021_10210201_58_dialog_content = "A continuación, tenemos a la <color=#FFB400>Dra. Barrett</color> como nuestra consultora operativa. Su equipo creó la aeronave utilizada para la expedición.",
  ui_story_1021_10210201_59_dialog_content = "Y al Jefe de Inteligencia <color=#FFB400>Teniente Philyshy</color> se le asigna la supervisión de las rutinas diarias del escuadrón, así como de las comunicaciones.",
  ui_story_1021_10210201_60_dialog_content = "Además, nuestro personal de reserva militar está pasando por las inspecciones finales. Ofrecerán un respaldo sólido al equipo de expedición.",
  ui_story_1021_10210201_61_dialog_content = "Dada la información proporcionada, nosotros, Lumopolis, enviaremos escuadrones de élite para despejar obstáculos para los equipos subsiguientes.",
  ui_story_1021_10210201_62_dialog_content = "...",
  ui_story_1021_10210201_63_dialog_content = "(¿Escuadrones de élite? Veo que Lumopolis también busca un papel principal en la expedición. Supongo que incluso Carleen no tiene idea de lo que trama el Señor de la Ciudad...)",
  ui_story_1021_10210201_64_dialog_content = "Los escuadrones de Lumopolis lucharán junto a todos y se esforzarán por brindar todo el apoyo a la expedición.",
  ui_story_1021_10210201_65_dialog_content = "Sí. Nuestras municiones están listas para funcionar, solo esperando la señal.",
  ui_story_1021_10210201_66_dialog_content = "Ejem, ejem... El Gremio de Umbraton también tiene abundantes suministros listos. Nuestras caravanas los entregarán al punto de partida.",
  ui_story_1021_10210201_67_dialog_content = "Aunque Umbraton no tiene experiencia en este tipo de operación, hemos preparado suficientes provisiones para que un <color=#FFB400>equipo de expedición</color> dure un año.",
  ui_story_1021_10210201_68_dialog_content = "Gracias por tu generosidad.",
  ui_story_1021_10210201_69_dialog_content = "Esto es un ganar-ganar para Umbraton, en lo que a mí respecta.",
  ui_story_1021_10210201_70_dialog_content = "Notificaremos a todos del horario específico lo antes posible.",
  ui_story_1021_10210201_71_dialog_content = "(Esto es lo que llamarías \"aportar lo que puedas\"...)",
  ui_story_1021_10210201_72_dialog_content = "¿Tienes algo que decir, PlayerName?",
  ui_story_1021_10210201_73_dialog_content = "Bueno, no tengo nada que ofrecer excepto la voluntad de proteger a los amigos!",
  ui_story_1021_10210201_74_dialog_content = "A donde vamos está lleno de peligros, pero me aseguraré de que mi equipo esté a salvo.",
  ui_story_1021_10210201_75_dialog_content = "No permitiré que mis compañeros de equipo se lastimen o se pierdan por alguna razón...",
  ui_story_1021_10210201_76_dialog_content = "...",
  ui_story_1021_10210201_77_dialog_content = "(¿Dije algo malo?)",
  ui_story_1021_10210201_78_dialog_content = "No dudes en informar a la guild si necesitas algo, PlayerName.",
  ui_story_1021_10210201_79_dialog_content = "Gracias, Bethel. Lo tendré en cuenta.",
  ui_story_1021_10210201_80_dialog_content = "Ahora que hemos terminado con el tema principal, permíteme salirme por la tangente.",
  ui_story_1021_10210201_81_dialog_content = "Cuando era joven, esperaba que pudiera visitar donde quisiera en persona cuando me convirtiera en el Señor de la Ciudad de Lumopolis.",
  ui_story_1021_10210201_82_dialog_content = "Sin embargo, en retrospectiva, me llevó tanto tiempo solo para administrar bien la ciudad.",
  ui_story_1021_10210201_83_dialog_content = "Entonces, públicamente, me gustaría ver mucho más del mundo a través de los ojos de ustedes, los jóvenes, mientras aún estoy vivo.",
  ui_story_1021_10210201_84_dialog_content = "En privado, aunque este sea un viaje desafiante, espero que Carleen pueda unirse a ti para presenciar el nacimiento de una nueva era.",
  ui_story_1021_10210201_85_dialog_content = "Mi señor...",
  ui_story_1021_10210201_86_dialog_content = "¿Crees que la expedición marcará el inicio de una nueva era?",
  ui_story_1021_10210201_87_dialog_content = "Por supuesto. O debería decir que una nueva era comenzó cuando empezaste a desvelar un misterio tras otro en Astra.",
  ui_story_1021_10210201_88_dialog_content = "Apoyamos la expedición al cien por ciento, porque el futuro de Astra ya está en tus manos.",
  ui_story_1021_10210201_89_dialog_content = "Ayúdame, Roy! No puedo hacer esto todo por mí mismo.",
  ui_story_1021_10210201_90_dialog_content = "Dicen que te conformarás con sobras cuando envejezcas, pero para mí, todo en lo que puedo pensar es qué salsa irá con mi bistec esta noche.",
  ui_story_1021_10210201_91_dialog_content = "¡Achuu!",
  ui_story_1021_10210201_92_dialog_content = "Esta aeronave de Illumina puede ser nueva, pero la tecnología huele tan fuerte como el polvo de pimienta... ¡Achís!",
  ui_story_1021_10210201_93_dialog_content = "Honcho Sinsa siempre cubre todas sus bases. Está muy interesado en la expedición de Caelestite, así que tenemos que estudiar esto, ¡podría ser útil!",
  ui_story_1021_10210201_94_dialog_content = "Veo que Sinsa aún mete su nariz donde no le corresponde... Tenemos que irnos, Tiny One!",
  ui_story_1021_10210201_95_dialog_content = "Las máquinas nuevas necesitan tiempo para perder el olor, así que espero que no te importe, Capitán.",
  ui_story_1021_10210201_96_dialog_content = "Oh, está bien. Los olores no me molestan.",
  ui_story_1021_10210201_97_dialog_content = "Recibí un mensaje de la Queen del Norte esta mañana, informando que la construcción del puesto avanzado se retrasaría unos días. No dio detalles específicos y no era mi lugar como aliado preguntar.",
  ui_story_1021_10210201_98_dialog_content = "Pero la expedición requiere que todos los puestos avancen al unísono, e Illumina no puede prescindir de más cuerpos.",
  ui_story_1021_10210201_99_dialog_content = "Por lo tanto, debo molestarte para que corras por mí.",
  ui_story_1021_10210201_100_dialog_content = "Claro. Han pasado muchas cosas últimamente y hace mucho tiempo que no voy a Northland.",
  ui_story_1021_10210201_101_dialog_content = "Eso es perfecto. PlayerName también puede familiarizarte con el funcionamiento de la aeronave.",
  ui_story_1021_10210201_102_dialog_content = "Puedes contar conmigo. Aunque es diferente de Soroz, gran parte del diseño me resulta lo suficientemente familiar.",
  ui_story_1021_10210201_103_dialog_content = "Por eso ya he visto la mitad de Astra solo en eso.",
  ui_story_1021_10210201_104_dialog_content = "Muy agradecido. Contáctame si hay algún problema. El sistema de comunicación ha sido configurado.",
  ui_story_1021_10210201_105_dialog_content = "¡Ten un viaje seguro!",
  ui_story_1021_10210201_106_dialog_content = "¡Lo tienes!",
  ui_story_1021_10210201_107_dialog_content = "¿Deberíamos decirle a PlayerName que hay dos chicos de Rediesel Wrench a bordo, Gran Mariscal?",
  ui_story_1021_10210201_108_dialog_content = "No. Eso sucede bastante a menudo en las expediciones. Ellos pueden manejarlo.",
  ui_story_1021_10210201_109_dialog_content = "Además, ¿no estaba la Rediesel Wrench clamando por unirse a la operación ellos mismos?",
  ui_story_1021_10210301_1_dialog_content = "<color=#e8d9bb>Un rato después ...</color>",
  ui_story_1021_10210301_2_dialog_content = "Estaba preocupado de que no pudiera acostumbrarme a montar en una aeronave Illumina.",
  ui_story_1021_10210301_3_dialog_content = "Pero a pesar de ser mucho más pequeño, es bastante similar a Soroz. Antes de que me dé cuenta, casi estamos en Northland.",
  ui_story_1021_10210301_4_dialog_content = "Como te dije, no sería un problema.",
  ui_story_1021_10210301_5_dialog_content = "Antes de aterrizar, ¿te gustaría intentar volarlo? Viste lo sencillo que fue cuando despegamos.",
  ui_story_1021_10210301_6_dialog_content = "Bueno, claro, solo guíame a través de ello.",
  ui_story_1021_10210301_7_dialog_content = "Vale, entonces primero, el panel de control aquí mostrará—",
  ui_story_1021_10210301_8_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_1021_10210301_9_dialog_content = "¡Ah!",
  ui_story_1021_10210301_10_dialog_content = "¿Qué está pasando? ¡Ni siquiera he tocado nada!",
  ui_story_1021_10210301_11_dialog_content = "¡Mantén la calma! Probablemente solo sea turbulencia...",
  ui_story_1021_10210301_12_dialog_content = "Vamos a bucear... Solo tira de la palanca, luego—",
  ui_story_1021_10210301_13_dialog_content = "<color=#e8d9bb>Bip, bip, bip...</color>",
  ui_story_1021_10210301_14_dialog_content = "¡Oh, no!",
  ui_story_1021_10210301_15_dialog_content = "<color=#e8d9bb>Bip, bip, bip...</color>",
  ui_story_1021_10210301_16_dialog_content = "¿Lo has encontrado, Roy? Tal vez deberíamos salir y tomar el control de la nave.",
  ui_story_1021_10210301_17_dialog_content = "Salir ahora solo empeorará las cosas. Terminaré... aquí en un segundo... No, no puedo conseguir la ventaja en la oscuridad.",
  ui_story_1021_10210301_18_dialog_content = "¡Tengo una luz justo aquí!",
  ui_story_1021_10210301_19_dialog_content = "Eso realmente deslumbra... ¿Dónde estamos ahora?",
  ui_story_1021_10210301_20_dialog_content = "Al menos a unas pocas cientos de millas del desierto de Rediesel. Se está volviendo cada vez más blanco allá afuera. Podríamos estar en Northland...",
  ui_story_1021_10210301_21_dialog_content = "En ese caso, no es raro encontrarse con turbulencias.",
  ui_story_1021_10210301_22_dialog_content = "Hmm, la construcción es diferente a lo que imaginaba. No creo que pueda arreglarlo.",
  ui_story_1021_10210301_23_dialog_content = "¿Qué quieres decir con \"diferente\"? ¡Esto es vida o muerte! ¡Déjame echar un vistazo!",
  ui_story_1021_10210301_24_dialog_content = "Dijiste que el problema es con el ascensor, ¿verdad?",
  ui_story_1021_10210301_25_dialog_content = "Sí, más o menos. No veo ningún eje de transmisión en esta aeronave de Illumina.",
  ui_story_1021_10210301_26_dialog_content = "... ¡Eso es porque está roto!",
  ui_story_1021_10210301_27_dialog_content = "Ya veo... Déjame hurgar en mi bolsillo en busca de algo útil mientras intentas arreglártelas con una llave por ahora.",
  ui_story_1021_10210301_28_dialog_content = "No tienes ningún sentido de la fatalidad inminente, ¿verdad?",
  ui_story_1021_10210301_29_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_1021_10210301_30_dialog_content = "¡Urgh!",
  ui_story_1021_10210301_31_dialog_content = "¡Se acabó ahora! ¿Estás bien?",
  ui_story_1021_10210301_32_dialog_content = "¿Dónde está Carleen? Veo manchas de sangre. No me digas... ¡Carleen!",
  ui_story_1021_10210301_33_dialog_content = "!",
  ui_story_1021_10210301_34_dialog_content = "¡Nunca volveré a viajar en un avión!",
  ui_story_1021_10210301_35_dialog_content = "(Supongo que ella está bien...)",
  ui_story_1021_10210301_36_dialog_content = "Está bien, no más. Todo es mi culpa.",
  ui_story_1021_10210301_37_dialog_content = "Pero francamente, no esperaba que la turbulencia fuera tan fuerte aquí en Northland.",
  ui_story_1021_10210301_38_dialog_content = "...",
  ui_story_1021_10210301_39_dialog_content = "Aunque es parte de la aventura...",
  ui_story_1021_10210301_40_dialog_content = "Afortunadamente, la palanca respondió en el último segundo.",
  ui_story_1021_10210301_41_dialog_content = "Guau, no puedo creer que aterrizamos de manera segura incluso con el timón doblado a este ángulo...",
  ui_story_1021_10210301_42_dialog_content = "¿Estás pescando cumplidos sobre tu habilidad de pilotaje?",
  ui_story_1021_10210301_43_dialog_content = "Err, no sé cómo responder a eso...",
  ui_story_1021_10210301_44_dialog_content = "<color=#e8d9bb>Awooo—</color>",
  ui_story_1021_10210301_45_dialog_content = "¿Es este un terreno de caza para animales? Hay sangre por todas partes...",
  ui_story_1021_10210301_46_dialog_content = "Parece que aquí tuvo lugar una pelea recientemente. Todavía deberíamos estar lejos del Palacio de Invierno. Tal vez esto sea obra de los Eclipsites...",
  ui_story_1021_10210301_47_dialog_content = "¿Eclipsites? Entonces estamos fuera del alcance del Beacon.",
  ui_story_1021_10210301_48_dialog_content = "La tierra que no está cubierta por el Faro aquí es mucho más grande de lo que piensas, especialmente el norte donde los Eclipsites se desbocan...",
  ui_story_1021_10210301_49_dialog_content = "Solo he escuchado historias sobre ello y nunca pensé que sería tan aterrador en persona...",
  ui_story_1021_10210301_50_dialog_content = "...",
  ui_story_1021_10210301_51_dialog_content = "... ¡Oigo a alguien!",
  ui_story_1021_10210301_52_dialog_content = "Echemos un vistazo.",
  ui_story_1021_10210301_53_dialog_content = "¡Humph!",
  ui_story_1021_10210301_54_dialog_content = "Vamos, niña, no me mires así! Te lo dije, nos obligaron a estar aquí.",
  ui_story_1021_10210301_55_dialog_content = "Mi licencia de piloto aún está en la aeronave. Espera aquí y la conseguiré para ti...",
  ui_story_1021_10210301_56_dialog_content = "¿Tenemos licencias, Roy?",
  ui_story_1021_10210301_57_dialog_content = "Siempre es problemático llevar a los novatos. ¿Perdiste tu licencia otra vez, verdad? ¡Déjame ir a buscarla para ti ahora mismo!",
  ui_story_1021_10210301_58_dialog_content = "¡Alto!",
  ui_story_1021_10210301_59_dialog_content = "Déjalos ir.",
  ui_story_1021_10210301_60_dialog_content = "¡Anciano! ¿Qué estás haciendo aquí? ¿No eres tú—",
  ui_story_1021_10210301_61_dialog_content = "No te preocupes por mí.",
  ui_story_1021_10210301_62_dialog_content = "Pero esto es lo que la tribu se ha convertido de la noche a la mañana. ¿Cómo no voy a preocuparme? ¿No viste la sangre oscura que se desprendía de esos pobres zorros?",
  ui_story_1021_10210301_63_dialog_content = "No deberías haber venido.",
  ui_story_1021_10210301_64_dialog_content = "¿Por qué siempre me dices que me mantenga alejado? ¡Esta es mi casa!",
  ui_story_1021_10210301_65_dialog_content = "... ¿Tiare?",
  ui_story_1021_10210301_66_dialog_content = "Ahora ven, cúbrete detrás de este escudo.",
  ui_story_1021_10210301_67_dialog_content = "¡He sido negligente en mi deber como guardia de Su Majestad!",
  ui_story_1021_10210301_68_dialog_content = "¡Por favor, no me dejes atrás y lucha contra los Eclipsites tú solo de nuevo!",
  ui_story_1021_10210301_69_dialog_content = "¡Permítame ser su valiente vanguardia, Su Majestad!",
  ui_story_1021_10210301_70_dialog_content = "Guardia de Queen...",
  ui_story_1021_10210301_71_dialog_content = "Eres tú...",
  ui_story_1021_10210301_72_dialog_content = "¿Qué estás haciendo aquí? ¿Y qué pasó?",
  ui_story_1021_10210301_73_dialog_content = "...",
  ui_story_1021_10210301_74_dialog_content = "(¿Es eso un legendario zorro de nieve? Me está mirando como si quisiera que me vaya.)",
  ui_story_1021_10210301_75_dialog_content = "Vinimos a visitar a Su Majestad, pero nuestra aeronave se encontró con fuerte turbulencia y se vio obligada a aterrizar aquí.",
  ui_story_1021_10210301_76_dialog_content = "...",
  ui_story_1021_10210301_77_dialog_content = "... Por favor, perdónanos por molestarte.",
  ui_story_1021_10210301_78_dialog_content = "¿Esos dos están contigo?",
  ui_story_1021_10210301_79_dialog_content = "¿De qué estás hablando?",
  ui_story_1021_10210301_80_dialog_content = "¡Acaban de estar aquí!",
  ui_story_1021_10210301_81_dialog_content = "Hicieron gestos a mis amigos con objetos extraños en la mano y afirmaron ser los pilotos de la aeronave.",
  ui_story_1021_10210301_82_dialog_content = "¡Pero solo estábamos yo y Carleen en ese vehículo!",
  ui_story_1021_10210301_83_dialog_content = "¡Imposible!",
  ui_story_1021_10210301_84_dialog_content = "Tómalo con calma, Tiare.",
  ui_story_1021_10210301_85_dialog_content = "Si te lastiman a ti o a tus amigos, PlayerName y yo no les permitiremos salir impunes.",
  ui_story_1021_10210301_86_dialog_content = "Pero escuché que mencionaste \"esta es tu casa\"?",
  ui_story_1021_10210301_87_dialog_content = "Esta es la frontera de Northland, frecuentada por Eclipsites...",
  ui_story_1021_10210301_88_dialog_content = "Estoy... siguiendo la orden de la reina para revisar el Bosque de Snowpine.",
  ui_story_1021_10210301_89_dialog_content = "Entiendo. ¿Te importaría llevarnos a Su Majestad cuando termines?",
  ui_story_1021_10210301_90_dialog_content = "No podemos encontrar el camino al Palacio de Invierno, ¡pero sin duda podemos ayudar si aparecen los Eclipsites!",
  ui_story_1021_10210301_91_dialog_content = "<color=#e8d9bb>¡Awoooo!</color>",
  ui_story_1021_10210301_92_dialog_content = "¡No!",
  ui_story_1021_10210301_93_dialog_content = "Quiero decir, está muy lejos del palacio y es muy peligroso aquí, así que deberías irte.",
  ui_story_1021_10210301_94_dialog_content = "Eso es...",
  ui_story_1021_10210301_95_dialog_content = "(Definitivamente algo anda mal con Tiare...)",
  ui_story_1021_10210301_96_dialog_content = "¿Puedes decirnos qué pasó aquí?",
  ui_story_1021_10210301_97_dialog_content = "...",
  ui_story_1021_10210301_98_dialog_content = "¿No estás aquí por la reina?",
  ui_story_1021_10210301_99_dialog_content = "Solo sigue las huellas de ese conejo y la verás.",
  ui_story_1021_10210301_100_dialog_content = "Cuando lo hagas, por favor hazle saber... que limpiaré las huellas, pero no ahora.",
  ui_story_1021_10210301_101_dialog_content = "...",
  ui_story_1021_10210301_102_dialog_content = "Y ella se ha ido en un abrir y cerrar de ojos...",
  ui_story_1021_10210301_103_dialog_content = "Nunca pensé que la tribu de la Fox Nieve existiera en Northland...",
  ui_story_1021_10210301_104_dialog_content = "Cuando estudié en Northland, escuché a algunas personas locales decir...",
  ui_story_1021_10210301_105_dialog_content = "Había un asentamiento en el extremo noroeste donde se reunían los zorros de nieve y vivían del Bosque de Pino Nevado.",
  ui_story_1021_10210301_106_dialog_content = "Protegieron los bosques y las ruinas debajo.",
  ui_story_1021_10210301_107_dialog_content = "Pero como nadie lo vio con sus propios ojos, nadie estaba seguro si era un hecho o un mito. Sin embargo, la parte de fobia a los Aurorianos parece ser cierta...",
  ui_story_1021_10210301_108_dialog_content = "¿Notaste a los zorros heridos refugiándose detrás de Tiare?",
  ui_story_1021_10210301_109_dialog_content = "Sí, y ese viejo zorro de nieve nos miró como si fuéramos sus némesis.",
  ui_story_1021_10210301_110_dialog_content = "Los zorros deben haber dejado las manchas de sangre.",
  ui_story_1021_10210301_111_dialog_content = "Algunas de las manchas son negras, algunas rojas, y me están dando náuseas...",
  ui_story_1021_10210301_112_dialog_content = "Se dice que algunos zorros de nieve son \"espíritus de la montaña\" nacidos del poder de la naturaleza, y cuando se ven manchados por Darkflow, sus cuerpos también mutan.",
  ui_story_1021_10210301_113_dialog_content = "Probablemente no te sientas bien debido al Darkflow en las manchas de sangre.",
  ui_story_1021_10210301_114_dialog_content = "¿Darkflow? Entonces hay más en el mensaje que ella quería que le pasáramos a la reina.",
  ui_story_1021_10210301_115_dialog_content = "Dado todo lo que sabemos, probablemente los Eclipsites invadieron Northland y no solo lastimaron a los zorros sino que también destruyeron el puesto de avanzada.",
  ui_story_1021_10210301_116_dialog_content = "Así que por eso Su Majestad aún no ha enviado a ningún representante...",
  ui_story_1021_10210301_117_dialog_content = "¡También pone a Tiare en gran peligro!",
  ui_story_1021_10210301_118_dialog_content = "Deberíamos alcanzarla, así podemos ayudar si se mete en problemas.",
  ui_story_1021_10210301_119_dialog_content = "¡Sigamos el rastro de sangre! Esta área está llena de Eclipsites, ¡así que debemos tener cuidado nosotros mismos!",
  ui_story_1021_10210401_1_dialog_content = "El camino termina aquí... No sé si es la sangre o algo, pero mi cabeza está empezando a dar vueltas...",
  ui_story_1021_10210401_2_dialog_content = "Déjame... intentar usar mi habilidad psíquica...",
  ui_story_1021_10210401_3_dialog_content = "PlayerName, sé que no lo has usado desde lo que pasó la última vez. Entonces, ¿estás seguro?",
  ui_story_1021_10210401_4_option_content = "Si...",
  ui_story_1021_10210401_5_dialog_content = "De hecho, durante mucho tiempo, me siento inseguro cuando pienso en usar habilidades psíquicas...",
  ui_story_1021_10210401_6_option_content = "Todavía estoy un poco asustado.",
  ui_story_1021_10210401_7_dialog_content = "Desde entonces, la idea de usar habilidades psíquicas me ha estado torturando por dentro...",
  ui_story_1021_10210401_8_dialog_content = "¿Te preocupa lo que verás y que puedas llamar la atención del Ingeniero de nuevo?",
  ui_story_1021_10210401_9_dialog_content = "Sí. También me preocupa que pueda ver o escuchar malas noticias sobre Vice o Soroz...",
  ui_story_1021_10210401_10_dialog_content = "Sé que lo que pasó tuvo un gran impacto en ti, pero—",
  ui_story_1021_10210401_11_dialog_content = "Pero las habilidades psíquicas son lo que uso para luchar y cómo protejo a todos.",
  ui_story_1021_10210401_12_dialog_content = "Independientemente, ¡tengo que superar mis miedos y mejorar mi control!",
  ui_story_1021_10210401_13_dialog_content = "Entonces, agradezco la preocupación, Carleen. Estoy bien ahora.",
  ui_story_1021_10210401_14_dialog_content = "Me alegra ver que has vuelto tan pronto, PlayerName. Estoy realmente feliz por ti.",
  ui_story_1021_10210401_15_dialog_content = "Recuerda, estoy aquí contigo. Si algo sale mal, lo enfrentaremos juntos.",
  ui_story_1021_10210401_16_dialog_content = "¡Entendido!",
  ui_story_1021_10210401_17_option_content = "Enlace Telepático—",
  ui_story_1021_10210401_18_dialog_content = "(Gran cueva vacía...)",
  ui_story_1021_10210401_19_dialog_content = "(Estos glaciares han estado aquí durante mucho tiempo.)",
  ui_story_1021_10210401_20_dialog_content = "... Ganaría el Rally de Rediesel si se inscribiera.",
  ui_story_1021_10210401_21_dialog_content = "¡Dos patas no pueden igualar a cuatro ruedas! Espera, ¿hueles algo fuerte?",
  ui_story_1021_10210401_22_dialog_content = "(Las voces... ¿De dónde vinieron?)",
  ui_story_1021_10210401_23_dialog_content = "(¡Manchas de sangre negras y rojas igual que las del suelo de arriba!)",
  ui_story_1021_10210401_24_dialog_content = "(Al menos todavía tengo el control de mi propia mente...)",
  ui_story_1021_10210401_25_dialog_content = "(Oh, y Tiare estuvo aquí... ¿Es esta cueva debajo del Bosque Snowpine?)",
  ui_story_1021_10210401_26_dialog_content = "El hedor a podrido me recuerda al Rediesel que tanto extraño...",
  ui_story_1021_10210401_27_dialog_content = "Apaga la luz antes de que atraiga algo extraño. No quiero pasar por este frío por nada.",
  ui_story_1021_10210401_28_dialog_content = "¿Por qué tenemos que escondernos aquí? Ahora ni siquiera podemos encontrar a alguien que nos dé indicaciones.",
  ui_story_1021_10210401_29_dialog_content = "¿No dijiste que lo que más odiabas era el subterráneo, Roy?",
  ui_story_1021_10210401_30_dialog_content = "(¿Esos dos?)",
  ui_story_1021_10210401_31_dialog_content = "(Hay muchos desvíos alrededor, ¿cómo llegaron allí?)",
  ui_story_1021_10210401_32_option_content = "Alcance Telepático—",
  ui_story_1021_10210401_33_dialog_content = "...",
  ui_story_1021_10210401_34_dialog_content = "¿Qué viste?",
  ui_story_1021_10210401_35_dialog_content = "Los intrusos que mencionó Tiare son dos de mis amigos de Rediesel.",
  ui_story_1021_10210401_36_dialog_content = "Después de extender mi visión, creo que vi un bulto de Darkflow expandiéndose como vapor hinchado.",
  ui_story_1021_10210401_37_dialog_content = "Está muy cerca de nosotros...",
  ui_story_1021_10210401_38_dialog_content = "!",
  ui_story_1021_10210401_39_dialog_content = "Hay manchas de sangre idénticas a las del suelo también. Tiare también debería estar dentro de esa cueva.",
  ui_story_1021_10210401_40_dialog_content = "¡Entonces tenemos que apurarnos y llegar a ellos! ¿Por dónde vamos ahora?",
  ui_story_1021_10210401_41_dialog_content = "El rastro termina aquí, por lo que la cueva debería estar detrás de estos pinos nevados. ¡Sígueme!",
  ui_story_1021_10210401_42_dialog_content = "(Tiare, Roy, y Tiny One también... ¡Espero que no les pase nada malo!)",
  ui_story_1021_10210401_43_dialog_content = "<color=#e8d9bb>Awooo...</color>",
  ui_story_1021_10210401_44_dialog_content = "Oh gran deidad antigua, siempre te he admirado como tú siempre nos has observado desde arriba.",
  ui_story_1021_10210401_45_dialog_content = "Las sombras de la oscuridad han descendido una vez más, manchando nuestros cuerpos como depredadores y dejando marcas indelebles.",
  ui_story_1021_10210401_46_dialog_content = "En el Palacio de Invierno, soy un Guardia de Queen...",
  ui_story_1021_10210401_47_dialog_content = "Pero aquí, soy un líder jurado para proteger a la tribu.",
  ui_story_1021_10210401_48_dialog_content = "Nutriste a la tribu y nos otorgaste un linaje sagrado, permitiéndonos conectarnos con tu presencia divina.",
  ui_story_1021_10210401_49_dialog_content = "Pero ahora, los pocos miembros de la tribu que quedan viven día y noche en agonía, sus cuerpos colapsando. Sé que un día volveremos a tu abrazo.",
  ui_story_1021_10210401_50_dialog_content = "May vuelves a lanzar tu mirada compasiva sobre nosotros, como cuando bendijiste a nuestros antepasados y a la tribu antes.",
  ui_story_1021_10210401_51_dialog_content = "<color=#e8d9bb>¡Awoooo!</color>",
  ui_story_1021_10210401_52_dialog_content = "Aquellos Aurorianos que han invadido inadvertidamente están en peligro. No me queda nada para mantenerlos fuera otra vez...",
  ui_story_1021_10210401_53_dialog_content = "Eso se suponía que era mi deber, anciano...",
  ui_story_1021_10210401_54_dialog_content = "Tiare, ¡mira la lanza en tu mano! Eres un guardia de Northland... Por favor, olvida todas las preocupaciones que tienes por este lugar...",
  ui_story_1021_10210401_55_dialog_content = "*tose*",
  ui_story_1021_10210401_56_dialog_content = "Te lo ruego, anciano... No puedo simplemente ver morir a mi tribu y a mi gente...",
  ui_story_1021_10210401_57_dialog_content = "Tú... no deberías haber vuelto...",
  ui_story_1021_10210401_58_dialog_content = "¿Qué debería hacer ahora...?",
  ui_story_1021_10210401_59_dialog_content = "<color=#e8d9bb>Goteo, goteo...</color>",
  ui_story_1021_10210401_60_dialog_content = "¡Ay!",
  ui_story_1021_10210401_61_dialog_content = "Ten cuidado, el camino helado es muy resbaladizo. Espera, ¿por qué está goteando agua?",
  ui_story_1021_10210401_62_dialog_content = "Ya he pisado varios charcos seguidos. Probablemente el horrible olor me afectó y me hizo tropezar con el último.",
  ui_story_1021_10210401_63_dialog_content = "Espera, creo que acabo de pisar algo esponjoso y suave... Échale un vistazo por mí.",
  ui_story_1021_10210401_64_dialog_content = "Parece que... un zorro de nieve.",
  ui_story_1021_10210401_65_dialog_content = "¿Sigue vivo?",
  ui_story_1021_10210401_66_dialog_content = "...",
  ui_story_1021_10210401_67_dialog_content = "Oh, estoy acabado. Estoy viendo una luz blanca...",
  ui_story_1021_10210401_68_dialog_content = "Sal de eso. Realmente hay una luz adelante.",
  ui_story_1021_10210401_69_dialog_content = "<color=#e8d9bb>Goteo, goteo...</color>",
  ui_story_1021_10210401_70_dialog_content = "¿Estoy delirando, Tiny One? Siento que vamos a llegar a casa si seguimos caminando así.",
  ui_story_1021_10210401_71_dialog_content = "Se está poniendo más caliente también... y de alguna manera mis músculos se relajan mucho.",
  ui_story_1021_10210401_72_dialog_content = "En ese caso, te dejaré llevar esta bolsa de gemas.",
  ui_story_1021_10210401_73_dialog_content = "¿Qué estás diciendo? ¿Cómo puedes simplemente renunciar a gemas gratis así como así?",
  ui_story_1021_10210401_74_dialog_content = "¡Oye, no toques mi cabeza. Tus manos están pegajosas de sudor!",
  ui_story_1021_10210401_75_dialog_content = "¿Por qué tú... Urgh, no puedo mantener los ojos abiertos con este brillo repentino... ¿No te dije que las luces brillantes atraen problemas?",
  ui_story_1021_10210401_76_dialog_content = "¡Oigan, ustedes dos!",
  ui_story_1021_10210401_77_dialog_content = "Hablando de problemas...",
  ui_story_1021_10210401_78_dialog_content = "Hola.",
  ui_story_1021_10210401_79_dialog_content = "Hola, PlayerName. ¿También estás buscando tesoros?",
  ui_story_1021_10210401_80_dialog_content = "¿Caza del tesoro? ¿Por qué te escabulliste a bordo de nuestra aeronave?",
  ui_story_1021_10210401_81_dialog_content = "¿Sinsa olvidó entregar el formulario de registro o algo así? Estamos representando a Rediesel Wrench en la conferencia de expedición conjunta.",
  ui_story_1021_10210401_82_dialog_content = "¿Quién iba a saber que la reunión era tan aburrida que de alguna manera terminamos aquí después de despertarnos de una siesta...",
  ui_story_1021_10210401_83_dialog_content = "Dado esa enorme mochila, ¡es más probable que estés en Northland para robar las gemas! Te aconsejo que las devuelvas a donde las encontraste!",
  ui_story_1021_10210401_84_dialog_content = "¿Qué, estamos en Northland? Honestamente, nunca he salido del desierto de Rediesel, ¡mucho menos sabía que hay gemas aquí!",
  ui_story_1021_10210401_85_dialog_content = "Pero arreglé tu vehículo para ti, así que tomaré esta bolsa como muestra de tu agradecimiento.",
  ui_story_1021_10210401_86_dialog_content = "Por qué tú-",
  ui_story_1021_10210401_87_dialog_content = "Creo que sé lo que pasó, Carleen.",
  ui_story_1021_10210401_88_dialog_content = "Están entre los mejores mecánicos de Rediesel Wrench, y hay una sala de mantenimiento en la aeronave cerca del timón de cola bastante lejos de la cabina de mando.",
  ui_story_1021_10210401_89_dialog_content = "Aterrizamos de manera segura incluso con el timón retorcido como estaba... Tal vez se escondían en esa habitación y nos hicieron un favor...",
  ui_story_1021_10210401_90_dialog_content = "¿Tu lo crees?",
  ui_story_1021_10210401_91_dialog_content = "Entonces, sobre el avión... gracias.",
  ui_story_1021_10210401_92_dialog_content = "No te preocupes. Estamos en una expedición juntos, ¡tenemos que cuidarnos mutuamente!",
  ui_story_1021_10210401_93_dialog_content = "<color=#e8d9bb>Goteo, goteo...</color>",
  ui_story_1021_10210401_94_dialog_content = "Lo primero es lo primero. Cuando volvamos, puedo darte Nightium, pero deja las gemas en Northland.",
  ui_story_1021_10210401_95_dialog_content = "Nightium, dices... Supongo que eso servirá.",
  ui_story_1021_10210401_96_dialog_content = "Es muy peligroso aquí. Roy, Tiny One, ¿sabes a dónde fue la chica con los zorros de nieve?",
  ui_story_1021_10210401_97_dialog_content = "¡Sí, pero ella se movía demasiado rápido para que pudiéramos seguirle el ritmo!",
  ui_story_1021_10210401_98_dialog_content = "En realidad, estábamos tratando de alejarnos de ella...",
  ui_story_1021_10210401_99_dialog_content = "Hay muchos cadáveres de zorros en la cueva, PlayerName. Muchos de los zorros que estaban con ella también resultaron gravemente heridos.",
  ui_story_1021_10210401_100_dialog_content = "Entonces tenemos que encontrarla lo más pronto posible.",
  ui_story_1021_10210401_101_dialog_content = "Ya que conoces el camino, guía adelante.",
  ui_story_1021_10210401_102_dialog_content = "No tenemos problemas aquí afuera, pero no más adentro. Demasiadas bifurcaciones... Casi nos perdemos nosotros mismos.",
  ui_story_1021_10210401_103_dialog_content = "Roy, mi luz...",
  ui_story_1021_10210401_104_dialog_content = "¿Se atenuó?",
  ui_story_1021_10210401_105_dialog_content = "Eso significa que el Darkflow se está volviendo más fuerte.",
  ui_story_1021_10210401_106_dialog_content = "Por mucho que me gusten los lugares más cálidos, lo siento, PlayerName, Miss Nightium, ¡me voy con Tiny One!",
  ui_story_1021_10210401_107_dialog_content = "No puedo creerlo. Acaban de decir que deberíamos ayudarnos mutuamente... ¿Qué camino tomamos ahora?",
  ui_story_1021_10210401_108_dialog_content = "Permíteme usar mi habilidad psíquica.",
  ui_story_1021_10210401_109_option_content = "Alcance Telepático—",
  ui_story_1021_10210401_110_dialog_content = "Codicia, ira, obsesión... todas ilusiones que causan sufrimiento de la mente y el cuerpo.",
  ui_story_1021_10210401_111_dialog_content = "La ira se convierte en rabia. La rabia se convierte en aflicción.",
  ui_story_1021_10210401_112_dialog_content = "Sí, sí...",
  ui_story_1021_10210401_113_dialog_content = "La fanfarronería... está aún más contenida...",
  ui_story_1021_10210401_114_dialog_content = "(¿Una Eclipsite?)",
  ui_story_1021_10210401_115_dialog_content = "(Demasiado borroso para distinguir, pero el que acabo de sentir...)",
  ui_story_1021_10210401_116_dialog_content = "(El Darkflow a su alrededor... Mi cabeza... siento como si estuviera siendo golpeada por un puño...)",
  ui_story_1021_10210401_117_dialog_content = "¡Mi señor!",
  ui_story_1021_10210401_118_dialog_content = "¿Si?",
  ui_story_1021_10210401_119_dialog_content = "Graah!",
  ui_story_1021_10210401_120_dialog_content = "(!)",
  ui_story_1021_10210401_121_dialog_content = "...",
  ui_story_1021_10210401_122_dialog_content = "Restricción... Restricción...",
  ui_story_1021_10210401_123_dialog_content = "M-Mi señor...",
  ui_story_1021_10210401_124_dialog_content = "No te preocupes y acércate. No te haré daño.",
  ui_story_1021_10210401_125_dialog_content = "Si...",
  ui_story_1021_10210401_126_dialog_content = "Mi señor... Hay Aurorianos reprobables cerca...",
  ui_story_1021_10210401_127_dialog_content = "...",
  ui_story_1021_10210401_128_dialog_content = "Yo... Yo creo que podrían afectar tu meditación...",
  ui_story_1021_10210401_129_dialog_content = "¿Dónde estoy?",
  ui_story_1021_10210401_130_dialog_content = "Has pasado la fortaleza.",
  ui_story_1021_10210401_131_dialog_content = "<color=#FFB400>Snowland</color>... He ido lo suficientemente lejos, en efecto.",
  ui_story_1021_10210401_132_dialog_content = "Desde que cambió, nunca he vuelto.",
  ui_story_1021_10210401_133_dialog_content = "Cambiado...",
  ui_story_1021_10210401_134_dialog_content = "¡El cambio es verdaderamente una privación despiadada!",
  ui_story_1021_10210401_135_dialog_content = "Mi señor...",
  ui_story_1021_10210401_136_dialog_content = "Agradezco el recordatorio oportuno... Restricción... Restricción...",
  ui_story_1021_10210401_137_dialog_content = "<color=#e8d9bb>Goteo, goteo...</color>",
  ui_story_1021_10210401_138_dialog_content = "El hielo aquí se está derritiendo, y es causado por el Darkflow de ese Eclipsite.",
  ui_story_1021_10210401_139_dialog_content = "¿Qué viste esta vez, PlayerName? ¿Por qué pareces preocupado?",
  ui_story_1021_10210401_140_dialog_content = "Vi ese Eclipsite...",
  ui_story_1021_10210401_141_dialog_content = "¡Pensándolo bien, deberíamos permanecer juntos!",
  ui_story_1021_10210401_142_dialog_content = "¿Tienes el valor de volver?",
  ui_story_1021_10210401_143_dialog_content = "¡Nos encontramos con un montón de Eclipsites allí, PlayerName!",
  ui_story_1021_10210401_144_dialog_content = "¡Graaah!",
  ui_story_1021_10210401_145_dialog_content = "¡Cuidado, Carleen!",
  ui_story_1021_10210401_146_dialog_content = "¡Nos los trajiste dibujándolos!",
  ui_story_1021_10210401_147_dialog_content = "¡Ponte detrás de mí, Tiny One!",
  ui_story_1021_10210401_148_dialog_content = "Está lo suficientemente cerca para que pueda decir que es Darkflow normal, no el tipo creciente que acabo de sentir...",
  ui_story_1021_10210401_149_dialog_content = "¡No te quedes ahí parado, PlayerName! ¡Da órdenes para la batalla!",
  ui_story_1021_10210401_150_dialog_content = "¡Entendido!",
  ui_story_1021_10210402_1_dialog_content = "Esto termina cuando el hielo se descongela.",
  ui_story_1021_10210402_2_dialog_content = "¡Todo despejado!",
  ui_story_1021_10210402_3_dialog_content = "¿Todos están bien?",
  ui_story_1021_10210402_4_dialog_content = "¡Su Majestad! ¿Qué hace aquí?",
  ui_story_1021_10210402_5_dialog_content = "Estaba en el géiser y sentí tus Luminatics.",
  ui_story_1021_10210402_6_dialog_content = "<color=#e8d9bb>Hace un rato...</color>",
  ui_story_1021_10210402_7_dialog_content = "<color=#e8d9bb>Sploosh, sploosh... ¡Boom!</color>",
  ui_story_1021_10210402_8_dialog_content = "Su Majestad, es eso—",
  ui_story_1021_10210402_9_dialog_content = "El <color=#FFB400>géiser</color> fronterizo. Ha vuelto a brotar después de años de inactividad, un reloj que despeja las cicatrices del pasado de Northland justo a tiempo...",
  ui_story_1021_10210402_10_dialog_content = "El agua de obsidiana que brota contiene Darkflow y ha destruido plantas, hogares y esa tribu inocente...",
  ui_story_1021_10210402_11_dialog_content = "Puedo ver en el espejo que la energía en la Zona Oscura ha estado cada vez más activa. ¿Cuál es su plan, Su Majestad?",
  ui_story_1021_10210402_12_dialog_content = "Cuando termine la próxima erupción, iré a la fuente y me ocuparé de ese Eclipsite.",
  ui_story_1021_10210402_13_dialog_content = "Ese Espejo de Northland tuyo tiene abundante Lumina en reserva. Cuento contigo para suprimir la propagación de Darkflow después de que yo entre.",
  ui_story_1021_10210402_14_dialog_content = "Sí, Su Majestad.",
  ui_story_1021_10210402_15_dialog_content = "<color=#e8d9bb>Sploosh, sploosh... ¡Boom!</color>",
  ui_story_1021_10210402_16_dialog_content = "¿Mmm?",
  ui_story_1021_10210402_17_dialog_content = "¿Por qué frunce el ceño, Su Majestad?",
  ui_story_1021_10210402_18_dialog_content = "Nadie está más familiarizado con cómo manipula Lumina que yo.",
  ui_story_1021_10210402_19_dialog_content = "No puedo esperar más. Dejo el resto en tus manos.",
  ui_story_1021_10210402_20_dialog_content = "...Sí, Su Majestad.",
  ui_story_1021_10210402_21_dialog_content = "Entonces, el géiser en erupción causó la destrucción.",
  ui_story_1021_10210402_22_dialog_content = "Y el Darkflow atrajo hordas de Eclipsites que dañaron a los pequeños y débiles zorros de nieve. Probablemente hayas visto muchas indicaciones en la cueva.",
  ui_story_1021_10210402_23_dialog_content = "Deberías irte antes de la próxima erupción.",
  ui_story_1021_10210402_24_dialog_content = "Pero Su Majestad, acabo de sentir un Eclipsite muy poderoso aquí...",
  ui_story_1021_10210402_25_dialog_content = "Vinimos a confirmar los planes para el puesto avanzado de Northland pero aterrizamos cerca debido a un accidente.",
  ui_story_1021_10210402_26_dialog_content = "Luego vimos a Tiare con una manada de zorros heridos, y no parecían estar bien...",
  ui_story_1021_10210402_27_dialog_content = "Estábamos preocupados por su seguridad, así que los seguimos hasta aquí. Por cierto, ¿dónde están los dos chicos de Rediesel?",
  ui_story_1021_10210402_28_dialog_content = "...",
  ui_story_1021_10210402_29_dialog_content = "Su Majestad, esto está fuera de la jurisdicción real...",
  ui_story_1021_10210402_30_dialog_content = "¿Enviaste a tu guardia Tiare aquí para verificar a los Eclipsites?",
  ui_story_1021_10210402_31_dialog_content = "\"Queen's Guard\" es un título que Tiare modeló después de la Guardia Real y se lo otorgó a sí misma.",
  ui_story_1021_10210402_32_dialog_content = "Para convertirse en Guardia Real, todavía tiene que descubrir qué significa defender Northland, una pregunta eterna perseguida por la gente de esta tierra.",
  ui_story_1021_10210402_33_dialog_content = "¡Señor Novio!",
  ui_story_1021_10210402_34_dialog_content = "Carleen, PlayerName.",
  ui_story_1021_10210402_35_dialog_content = "Ya que estás aquí, sé lo que pasó.",
  ui_story_1021_10210402_36_dialog_content = "Sabías desde hace mucho tiempo que Tiare dejaría el Palacio de Invierno y regresaría a su tribu.",
  ui_story_1021_10210402_37_dialog_content = "Tiare en efecto es miembro de la legendaria tribu de nieve Fox. Incluso parece ser—",
  ui_story_1021_10210402_38_dialog_content = "Tiare es el líder de la tribu de nieve Fox.",
  ui_story_1021_10210402_39_dialog_content = "¿El líder?",
  ui_story_1021_10210402_40_dialog_content = "¿No hay nadie mayor que ella en la tribu ahora?",
  ui_story_1021_10210402_41_dialog_content = "...",
  ui_story_1021_10210402_42_dialog_content = "Oh, Su Majestad, Tiare quería informarle que limpiará las huellas, pero no ahora...",
  ui_story_1021_10210402_43_dialog_content = "¿A qué se refería ella con eso?",
  ui_story_1021_10210402_44_dialog_content = "La pregunta eterna... aunque ni siquiera yo he logrado hacer eso...",
  ui_story_1021_10210402_45_dialog_content = "Nunca ha descuidado este lugar en todas sus inspecciones por Northland, Su Majestad.",
  ui_story_1021_10210402_46_dialog_content = "Este es mi deber, Novio. Tú sácalos de aquí mientras yo rastreo a Tiare.",
  ui_story_1021_10210402_47_dialog_content = "Ya he hecho lo último, Su Majestad.",
  ui_story_1021_10210402_48_dialog_content = "Sí.",
  ui_story_1021_10210402_49_dialog_content = "¡Su Majestad, el fuerte Darkflow que sentí se está acercando!",
  ui_story_1021_10210402_50_dialog_content = "¿Soy yo de quien hablas?",
  ui_story_1021_10210402_51_dialog_content = "¡La espada de Aurora!",
  ui_story_1021_10210402_52_dialog_content = "¡Rápido, refúgiate en mi campo de Lumina!",
  ui_story_1021_10210402_53_dialog_content = "¿Eres el autoproclamado Queen de Snowland? Veo que me he perdido mucho.",
  ui_story_1021_10210402_54_dialog_content = "¡Está encima de nosotros tan rápido!",
  ui_story_1021_10210402_55_dialog_content = "Tú...",
  ui_story_1021_10210402_56_dialog_content = "<color=#FFB400>Natas</color> convertirá tu cerebro en néctar y lo repartirá entre tus compatriotas.",
  ui_story_1021_10210402_57_dialog_content = "¿Compatriotas? ¿De qué estás hablando?",
  ui_story_1021_10210402_58_dialog_content = "Néctar...",
  ui_story_1021_10210402_59_dialog_content = "Hablando de néctar...",
  ui_story_1021_10210402_60_dialog_content = "Me siento terrible...",
  ui_story_1021_10210402_61_dialog_content = "(Su Darkflow podría penetrar el escudo de la reina...)",
  ui_story_1021_10210402_62_dialog_content = "¡Gran Frío Extremo!",
  ui_story_1021_10210402_63_dialog_content = "Nuestra presencia solo complicará su esfuerzo, Su Majestad. Confíe en que estarán a mi cuidado.",
  ui_story_1021_10210402_64_dialog_content = "Gracias, Novio.",
  ui_story_1021_10210402_65_dialog_content = "¡Permítame luchar con usted, Su Majestad!",
  ui_story_1021_10210402_66_dialog_content = "No, y esa es mi orden.",
  ui_story_1021_10210402_67_dialog_content = "...",
  ui_story_1021_10210402_68_dialog_content = "Carleen, PlayerName, por favor sigue a mi personal a la superficie de arriba.",
  ui_story_1021_10210402_69_dialog_content = "¿Cómo, exactamente?",
  ui_story_1021_10210402_70_dialog_content = "...",
  ui_story_1021_10210402_71_dialog_content = "¡Señor Novio!",
  ui_story_1021_10210402_72_dialog_content = "Permanece en la oscuridad en paz.",
  ui_story_1021_10210402_73_dialog_content = "¡No habrá oscuridad en Northland mientras la aurora aún brille! ¡Hoja de Aurora!",
  ui_story_1021_10210402_74_dialog_content = "Estás muy por debajo de la liga de esa mujer.",
  ui_story_1021_10210402_75_dialog_content = "¡No eres digno de juzgar a la reina!",
  ui_story_1021_10210402_76_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_1021_10210402_77_dialog_content = "¡Regresa aquí, Tiare!",
  ui_story_1021_10210402_78_dialog_content = "Como guardia de Su Majestad, ¡debo estar ante usted como un escudo!",
  ui_story_1021_10210402_79_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_1021_10210402_80_dialog_content = "¡No harás daño a Su Majestad! ¡Esta es una advertencia de la Guardia del Queen!",
  ui_story_1021_10210402_81_dialog_content = "Cráneo orgulloso... Piernas poderosas y blancas como la nieve...",
  ui_story_1021_10210402_82_dialog_content = "May ¿me puedes decir qué es eso en tus ojos?",
  ui_story_1021_10210402_83_dialog_content = "¡Es mi determinación matarte!",
  ui_story_1021_10210402_84_dialog_content = "Me recuerdas a ella...",
  ui_story_1021_10210402_85_dialog_content = "Cuando se ató su vestido negro alrededor de la cintura, cortó el extremo para poder liderar la carga de sus soldados a máxima velocidad de manera más eficaz.",
  ui_story_1021_10210402_86_dialog_content = "¡No parpadees o mi lanza te cegará igual de rápido!",
  ui_story_1021_10210402_87_dialog_content = "Qué mirada cautivadora. Desafortunadamente, es demasiado tarde...",
  ui_story_1021_10210402_88_dialog_content = "¡Esto termina cuando el hielo se derrite!",
  ui_story_1021_10210402_89_dialog_content = "¿Su Majestad?",
  ui_story_1021_10210402_90_dialog_content = "Esta no es tu pelea. ¡Ahora sal por el pasaje que hice!",
  ui_story_1021_10210402_91_dialog_content = "¿Pero qué hay de ti?",
  ui_story_1021_10210402_92_dialog_content = "¡Estaré justo detrás de ti! ¿Me harías el favor, Sr. Novio?",
  ui_story_1021_10210402_93_dialog_content = "¡Concédeme poder, Bastón de Terra!",
  ui_story_1021_10210402_94_dialog_content = "¿Por qué no los mataste, mi señor?",
  ui_story_1021_10210402_95_dialog_content = "Porque vi mi ira en los ojos de ese zorro...",
  ui_story_1021_10210402_96_dialog_content = "La ira es una señal de cobardía. Juré no ser esclavo de la ira.",
  ui_story_1021_10210402_97_dialog_content = "Las reinas de Snowland...",
  ui_story_1021_10210402_98_dialog_content = "Los glaciares que crearon nunca se derriten en mi Fuego de Sombra...",
  ui_story_1021_10210501_1_dialog_content = "...",
  ui_story_1021_10210501_2_dialog_content = "Su Majestad... ¿Por qué se ha detenido?",
  ui_story_1021_10210501_3_dialog_content = "En cada lugar que pasamos, la influencia del Darkflow ha expuesto el lecho rocoso que yace debajo de las capas de hielo...",
  ui_story_1021_10210501_4_dialog_content = "Sin embargo, esta área está completamente inafectada... Además, siento un poder único emanando de este lugar.",
  ui_story_1021_10210501_5_dialog_content = "Sé lo que debo hacer ahora, Novio. Por favor, cuídense mucho, todos ustedes.",
  ui_story_1021_10210501_6_dialog_content = "Pero... Su Majestad...",
  ui_story_1021_10210501_7_dialog_content = "... ¡Por favor, déjame ir contigo!",
  ui_story_1021_10210501_8_dialog_content = "...",
  ui_story_1021_10210501_9_dialog_content = "Tu propósito aquí es proteger a tu tribu, no a la reina. Recuerda eso.",
  ui_story_1021_10210501_10_dialog_content = "Pero.",
  ui_story_1021_10210501_11_dialog_content = "Es solo porque mi tribu está en tal peligro que no tenemos más opción que refugiarnos en el altar...",
  ui_story_1021_10210501_12_dialog_content = "¿Es eso lo que estoy sintiendo? ¿El poder protector del altar?",
  ui_story_1021_10210501_13_dialog_content = "Su Majestad... Yo... No puedo dejarle acercarse al altar!",
  ui_story_1021_10210501_14_dialog_content = "¿Cómo te atreves a interponerte en el camino de la reina, Tiare! ¿Tienes alguna idea de lo que estás haciendo?",
  ui_story_1021_10210501_15_dialog_content = "... Juré protegerte incluso en los lugares más peligrosos, pero el altar...",
  ui_story_1021_10210501_16_dialog_content = "¡Perdóname, pero no puedo dejarte ir allí!",
  ui_story_1021_10210501_17_dialog_content = "¡Hice una promesa a mis antepasados cuando me convertí en el líder de la Tribu Fox de Nieve!",
  ui_story_1021_10210501_18_dialog_content = "¿Es el odio lo que me impide acercarme al altar?",
  ui_story_1021_10210501_19_dialog_content = "Yo... para ser honesto, no estoy del todo seguro...",
  ui_story_1021_10210501_20_dialog_content = "...",
  ui_story_1021_10210501_21_dialog_content = "Si albergas dudas sobre el conflicto entre tu tribu y la corte real, debes disiparlas tú mismo buscando la verdad.",
  ui_story_1021_10210501_22_dialog_content = "Pero por el bien de todo Northland, debo verla ahora. Por favor, cree en mí, Tiare.",
  ui_story_1021_10210501_23_dialog_content = "¡Su Majestad!",
  ui_story_1021_10210501_24_dialog_content = "Deja que ella venga, Tiare.",
  ui_story_1021_10210501_25_dialog_content = "¿Eh? ¿Quién dijo eso?",
  ui_story_1021_10210501_26_dialog_content = "¿Anciano? Pero... ¿Es esto realmente—",
  ui_story_1021_10210501_27_dialog_content = "lo permitiré.",
  ui_story_1021_10210501_28_dialog_content = "¿Se siente algo mejor, señora?",
  ui_story_1021_10210501_29_dialog_content = "Gracias por preguntar, este viejo cuerpo aún vive.",
  ui_story_1021_10210501_30_dialog_content = "Ese es el zorro, Carleen... ¡Ese viejo zorro de nieve que conocimos antes es el que está hablando!",
  ui_story_1021_10210501_31_dialog_content = "No deberías estar tan sorprendido. Además, parece que se ha recuperado bastante bien...",
  ui_story_1021_10210501_32_dialog_content = "Aunque, juzgando por su voz, parece ser una \"ella\".",
  ui_story_1021_10210501_33_dialog_content = "...",
  ui_story_1021_10210501_34_dialog_content = "Por favor, discúlpelos, anciano. No son de Northland, y haré que muestren respeto y se vayan de inmediato.",
  ui_story_1021_10210501_35_dialog_content = "Eso no será necesario. Aquellos que realmente respetaban al anciano zorro de nieve ya han fallecido. Solo estás aquí para saldar una deuda, y nada más.",
  ui_story_1021_10210501_36_dialog_content = "¡Pido que muestres más respeto al dirigirte a la reina!",
  ui_story_1021_10210501_37_dialog_content = "¡Silencio, Carleen!",
  ui_story_1021_10210501_38_dialog_content = "...",
  ui_story_1021_10210501_39_dialog_content = "No te preocupes, porque mi furia cesó hace mucho tiempo. Todo lo que queda de este ser antiguo es el marco maltratado que ves ante ti.",
  ui_story_1021_10210501_40_dialog_content = "A pesar de todo, nuestra tribu una vez mostró respeto por su monarca. El estado miserable de esta cueva debería servir como una respuesta adecuada a sus preguntas.",
  ui_story_1021_10210501_41_dialog_content = "Anciano, ¿se le permite realmente a la reina—",
  ui_story_1021_10210501_42_dialog_content = "Solo desearía que nunca tuvieras que soportar estas cosas, Tiare.",
  ui_story_1021_10210501_43_dialog_content = "...",
  ui_story_1021_10210501_44_dialog_content = "Anciano, los Eclipsites que invadieron Northland ya han llegado tan lejos en tu territorio...",
  ui_story_1021_10210501_45_dialog_content = "El poder de la naturaleza protege este lugar. Aunque pueda ser débil, los Eclipsites no tienen forma de acercarse al altar. Ven conmigo.",
  ui_story_1021_10210501_46_dialog_content = "...",
  ui_story_1021_10210501_47_dialog_content = "<color=#e8d9bb>Awooo...</color>",
  ui_story_1021_10210501_48_dialog_content = "¿Es este el altar que la tribu de Tiare ha estado protegiendo?",
  ui_story_1021_10210501_49_dialog_content = "Nunca esperé ver un lugar como este escondido en una cueva...",
  ui_story_1021_10210501_50_dialog_content = "Este altar fue construido por nuestros antepasados cuando Northland fue creado por primera vez.",
  ui_story_1021_10210501_51_dialog_content = "Este lugar... ¿A quién o qué rinde homenaje?",
  ui_story_1021_10210501_52_dialog_content = "El altar se erige en adoración a los Tres Árboles de Pino Nevado y nuestros antepasados, los protectores del Bosque de Pino Nevado y todo Northland.",
  ui_story_1021_10210501_53_dialog_content = "Los Tres Árboles de Pino de Nieve... ¿Te refieres a estos tres tocones?",
  ui_story_1021_10210501_54_dialog_content = "Llevando la ambición de proteger a Northland, estaban destinados a ser derribados, y sin embargo, su poder nunca se disipó.",
  ui_story_1021_10210501_55_dialog_content = "Si los Tres Árboles de Pino de Nieve eligen resurgir, las montañas se abrirán para ellos. El cielo tampoco ha olvidado su poder, y por lo tanto, fuerza a la luz a pasar por las grietas de arriba.",
  ui_story_1021_10210501_56_dialog_content = "Esta tableta... ¿Tiene algún tipo de inscripciones antiguas?",
  ui_story_1021_10210501_57_dialog_content = "¿Qué dice?",
  ui_story_1021_10210501_58_dialog_content = "\"Le da vitalidad al monarca cansado, quien a su vez trae paz al mundo.\"",
  ui_story_1021_10210501_59_dialog_content = "\"Su sagrado pacto convierte la oscuridad en luz.\"",
  ui_story_1021_10210501_60_dialog_content = "\"Contemplar su divinidad es encontrar felicidad y paz.\"",
  ui_story_1021_10210501_61_dialog_content = "Podría ser esto...",
  ui_story_1021_10210501_62_dialog_content = "El registro más antiguo conocido de las legendarias Tres Pinos...",
  ui_story_1021_10210501_63_dialog_content = "¿La leyenda que es popular en Northland?",
  ui_story_1021_10210501_64_dialog_content = "El primer pino es testigo del nacimiento de la primera reina de Northland, el segundo representa la lealtad de sus guardias reales...",
  ui_story_1021_10210501_65_dialog_content = "Y el tercero se convierte en el propio cetro de la reina...",
  ui_story_1021_10210501_66_dialog_content = "Jajaja, simplemente rebosa de la vanidad de los sucesores reales...",
  ui_story_1021_10210501_67_dialog_content = "Considérense afortunados de que ella no esté presente para escuchar esto, o les daría a todos una buena paliza.",
  ui_story_1021_10210501_68_dialog_content = "Aun así, conozco demasiado bien la importancia de un origen glorioso para cualquier imperio.",
  ui_story_1021_10210501_69_dialog_content = "<color=#828282>¡Ding!</color>",
  ui_story_1021_10210501_70_dialog_content = "!",
  ui_story_1021_10210501_71_dialog_content = "¡Anciano!",
  ui_story_1021_10210501_72_dialog_content = "L-Lo siento por la interrupción... ¿Qué pasa con tu Spotlight, Tiny One?",
  ui_story_1021_10210501_73_dialog_content = "Yo... Yo tampoco sé por qué hizo eso...",
  ui_story_1021_10210501_74_dialog_content = "¿Ustedes dos han estado escondiéndose allí todo este tiempo?",
  ui_story_1021_10210501_75_dialog_content = "Urgh... Forasteros...",
  ui_story_1021_10210501_76_dialog_content = "Dile a tus amigos que tomen esa cosa y se vayan, PlayerName! El cuerpo del anciano es demasiado débil para manejarlo!",
  ui_story_1021_10210501_77_dialog_content = "¡Tiny One!",
  ui_story_1021_10210501_78_dialog_content = "¿Por qué... Por qué no funciona?",
  ui_story_1021_10210501_79_dialog_content = "<color=#e8d9bb>Whoosh, whoosh—</color>",
  ui_story_1021_10210501_80_dialog_content = "Mi lanza parece estar surgiendo con poder...",
  ui_story_1021_10210501_81_dialog_content = "¿Qué es esta cosa en el mundo?",
  ui_story_1021_10210501_82_dialog_content = "<color=#e8d9bb>Whoosh, whoosh—</color>",
  ui_story_1021_10210501_83_dialog_content = "Mi bastón está resonando con el altar...",
  ui_story_1021_10210501_84_dialog_content = "...",
  ui_story_1021_10210501_85_dialog_content = "Pero parece que la Fuerza de Invierno de la reina es su elección...",
  ui_story_1021_10210501_86_dialog_content = "... ¿Q-Qué?",
  ui_story_1021_10210501_87_dialog_content = "¡Permaneceré al lado de un monarca, quien a su vez traerá paz a este mundo!",
  ui_story_1021_10210501_88_dialog_content = "(Esa voz...)",
  ui_story_1021_10210501_89_dialog_content = "¡A través de mi poder, convertiré la oscuridad en luz!",
  ui_story_1021_10210501_90_dialog_content = "Mientras los demás sientan felicidad y paz al mirarme, estaré más que satisfecho...",
  ui_story_1021_10210501_91_dialog_content = "Jajaja... Ustedes dos pueden ser tan arrogantes a veces...",
  ui_story_1021_10210501_92_dialog_content = "¿Crees que eres diferente? Jajaja...",
  ui_story_1021_10210501_93_dialog_content = "El altar resuena con tres voces distintas...",
  ui_story_1021_10210501_94_dialog_content = "También los escucho...",
  ui_story_1021_10210501_95_dialog_content = "¿Son estas... las voces de lo divino?",
  ui_story_1021_10210501_96_dialog_content = "...",
  ui_story_1021_10210501_97_dialog_content = "Lo divino... ha reconocido tu poder...",
  ui_story_1021_10210501_98_dialog_content = "Innumerables visiones pasaron por mis ojos hace un momento...",
  ui_story_1021_10210501_99_dialog_content = "Lo divino solo reconoce el poder de aquellos que son dignos...",
  ui_story_1021_10210501_100_dialog_content = "En otras palabras...",
  ui_story_1021_10210501_101_dialog_content = "Tu primera reina... Ella realmente obtuvo su bendición...",
  ui_story_1021_10210501_102_dialog_content = "Bueno.",
  ui_story_1021_10210501_103_dialog_content = "Esto sería inimaginable para nuestros ancestros fallecidos...",
  ui_story_1021_10210501_104_dialog_content = "<color=#e8d9bb>¡Morir!</color>",
  ui_story_1021_10210501_105_dialog_content = "Avanza y cumple tu promesa, y siempre encontrarás descanso en Northland.",
  ui_story_1021_10210501_106_dialog_content = "¡Vacila, y colgaré tus vergonzosas cabezas de los pinos nevados para que tus descendientes las vean!",
  ui_story_1021_10210501_107_dialog_content = "¿Eh? ¿De quién son estos pensamientos? No estaba usando mis poderes justo ahora...",
  ui_story_1021_10210501_108_dialog_content = "Todos siguen de pie alrededor del altar como antes...",
  ui_story_1021_10210501_109_dialog_content = "Esto... Esto era la fortaleza una vez inexpugnable en la frontera de Northland...",
  ui_story_1021_10210501_110_dialog_content = "¿Será que nosotros estamos—",
  ui_story_1021_10210501_111_dialog_content = "Sí. Este altar estaba ubicado dentro del patio de la fortaleza.",
  ui_story_1021_10210501_112_dialog_content = "...",
  ui_story_1021_10210501_113_dialog_content = "Gente del Reino Congelado, desaparezcan de este lugar.",
  ui_story_1021_10210501_114_dialog_content = "...",
  ui_story_1021_10210501_115_dialog_content = "¿Está... hablándonos?",
  ui_story_1021_10210501_116_dialog_content = "Nuestro atuendo... Comparado con el de ellos, es...",
  ui_story_1021_10210501_117_dialog_content = "Al robar el poder de los pinos de nieve, nos has quitado nuestra protección.",
  ui_story_1021_10210501_118_dialog_content = "¡Pero recuerda mis palabras, nuestro pueblo nunca olvidará nuestra promesa para ellos!",
  ui_story_1021_10210501_119_dialog_content = "Incluso si todos perecemos en el bosque que nos dio vida, incluso si somos aplastados por el peso de este cielo opresivo...",
  ui_story_1021_10210501_120_dialog_content = "Nunca reconoceré a ningún monarca que no sea el mío.",
  ui_story_1021_10210501_121_dialog_content = "...",
  ui_story_1021_10210501_122_dialog_content = "Señor Rode...",
  ui_story_1021_10210501_123_dialog_content = "¡Hagen! Tráeme la armadura que me otorgó el rey, ¡para que pueda recompensar a los hombres que lideran nuestro asalto!",
  ui_story_1021_10210501_124_dialog_content = "Señor Rode... Por favor, use esta armadura con orgullo.",
  ui_story_1021_10210501_125_dialog_content = "¡Esta no será mi última pelea, Hagen! Mientras te tenga a mi lado, ¡nunca caeré!",
  ui_story_1021_10210501_126_dialog_content = "...",
  ui_story_1021_10210501_127_dialog_content = "Vamos, Hagen.",
  ui_story_1021_10210501_128_dialog_content = "Siempre estaré a tu lado, Lord Rode...",
  ui_story_1021_10210501_129_dialog_content = "...",
  ui_story_1021_10210501_130_dialog_content = "El Señor Rode era un hombre grande y poderoso que, sin embargo, se preocupaba profundamente por sus soldados. Estábamos seguros de que se convertiría en el próximo rey de Northland.",
  ui_story_1021_10210501_131_dialog_content = "¡Hermanos! Por el rey y todo Northland, marchamos hacia la batalla!",
  ui_story_1021_10210501_132_dialog_content = "¡A la batalla!",
  ui_story_1021_10210501_133_dialog_content = "¡A la batalla!",
  ui_story_1021_10210501_134_dialog_content = "<color=#e8d9bb>Whoosh, whoosh—</color>",
  ui_story_1021_10210501_135_dialog_content = "Se fue... ¿Eso fue el \"poder de la naturaleza\" justo ahora?",
  ui_story_1021_10210501_136_dialog_content = "...",
  ui_story_1021_10210501_137_dialog_content = "¿Así que serviste como guardia del Señor Rode, anciano?",
  ui_story_1021_10210501_138_dialog_content = "Sí, Tiare. Él era tu antepasado y un orgulloso miembro de la tribu, el tipo que has idolatrado desde que eras solo un niño.",
  ui_story_1021_10210501_139_dialog_content = "Con nuestra tribu en su estado actual, no tengo forma de enfrentarlo ahora.",
  ui_story_1021_10210501_140_dialog_content = "Las cicatrices en tu cara... ¿Las obtuviste durante tu batalla con los Eclipsites en aquel entonces?",
  ui_story_1021_10210501_141_dialog_content = "No hay necesidad de lamentarse por una historia tan antigua, Tiare.",
  ui_story_1021_10210501_142_dialog_content = "Aunque nuestras cicatrices aún son visibles hasta el día de hoy, lo que no ves es nuestra victoria sobre los Eclipsites ese día, así como nuestra celebración con una hoguera en el Bosque de Snowpine.",
  ui_story_1021_10210501_143_dialog_content = "¿Por qué no me dijiste nada de esto?",
  ui_story_1021_10210501_144_dialog_content = "Si supieras, habrías dejado el Palacio de Invierno para proteger este lugar, tal como tus antepasados juraron hacer.",
  ui_story_1021_10210501_145_dialog_content = "Te conozco demasiado bien, Tiare. Incluso como guardia de la reina, la sangre de nuestra gente fluye por tus venas.",
  ui_story_1021_10210501_146_dialog_content = "Llegará el día en que nuestra tribu ya no exista. Decirte estas cosas sería inútil.",
  ui_story_1021_10210501_147_dialog_content = "Además, ya has elegido a tu monarca.",
  ui_story_1021_10210501_148_dialog_content = "...",
  ui_story_1021_10210501_149_dialog_content = "Y la persona a la que has jurado lealtad ha demostrado ser digna del poder divino. Ya no tienes razón para quedarte y protegernos más.",
  ui_story_1021_10210501_150_dialog_content = "...",
  ui_story_1021_10210501_151_dialog_content = "Pero... ¿Y qué pasa con el \"poder robado\" del que hablaba el Señor Rode?",
  ui_story_1021_10210501_152_dialog_content = "El Faro...",
  ui_story_1021_10210501_153_dialog_content = "¿El Faro? ¿Te refieres al Faro de Northland?",
  ui_story_1021_10210501_154_dialog_content = "\"Contemplar su divinidad es encontrar felicidad y paz.\"",
  ui_story_1021_10210501_155_dialog_content = "...",
  ui_story_1021_10210501_156_dialog_content = "Para erradicar a los Eclipsites y traer luz a todo Northland...",
  ui_story_1021_10210501_157_dialog_content = "Los antepasados de la familia real recibieron un pino de nieve que contenía el poder de la naturaleza.",
  ui_story_1021_10210501_158_dialog_content = "El pino de nieve se cortó solo, y su madera se convirtió en combustible para la Chispa, que sirvió como el primer Faro de Northland.",
  ui_story_1021_10210501_159_dialog_content = "Desde entonces, todo Northland ha estado bañado en su luz... Como resultado, el Bosque de Snowpine ha ido perdiendo gradualmente su poder para repeler a los Eclipsites.",
  ui_story_1021_10210501_160_dialog_content = "...",
  ui_story_1021_10210501_161_dialog_content = "¿Viste esto en tus visiones?",
  ui_story_1021_10210501_162_dialog_content = "Sí. Los pinos de nieve reconocieron a la familia real y eligieron convertirse en el Faro de Northland.",
  ui_story_1021_10210501_163_dialog_content = "Solo entonces pudieron lograr su objetivo de proteger nuestra tierra...",
  ui_story_1021_10210501_164_dialog_content = "Entiendo...",
  ui_story_1021_10210501_165_dialog_content = "En otras palabras, la familia real nunca robó el poder de los pinos de nieve, ¿verdad?",
  ui_story_1021_10210501_166_dialog_content = "...",
  ui_story_1021_10210501_167_dialog_content = "...",
  ui_story_1021_10210501_168_dialog_content = "Antes de convertirse en el Faro de Northland, lo divino usó su poder para protegernos aquí. En ese entonces, sus poderes aún no habían sido privados.",
  ui_story_1021_10210501_169_dialog_content = "Nuestros antepasados construyeron este altar en honor a ellos, para adorarlos y demostrar nuestra fe y esperanza todos los días.",
  ui_story_1021_10210501_170_dialog_content = "Encendieron lámparas de aceite de pino incluso en los inviernos más fríos, todo para garantizar la paz y la prosperidad de nuestra tribu.",
  ui_story_1021_10210501_171_dialog_content = "Pero el paso del tiempo trajo cambios inesperados a lo largo de los años. Cosechas fallidas, enfermedades y todo tipo de dificultades azotaron a nuestra tribu...",
  ui_story_1021_10210501_172_dialog_content = "Cuando se cortaron los pinos de nieve, el odio y la desesperación cayeron rápidamente sobre nuestra gente.",
  ui_story_1021_10210501_173_dialog_content = "Bajo el reinado del rey, comenzamos a rezar en el altar día y noche por el favor de lo divino.",
  ui_story_1021_10210501_174_dialog_content = "Pero los Eclipsites llegaron de todos modos, y me vi obligado a presenciar el nacimiento y la muerte de muchos de los nuestros. A pesar de nuestras súplicas más desesperadas, lo divino nunca nos respondió...",
  ui_story_1021_10210501_175_dialog_content = "Su silencio era prueba de que nuestra tribu estaba destinada a la extinción como castigo por nuestro odio.",
  ui_story_1021_10210501_176_dialog_content = "Esa es la historia de nuestra especie. Antes de que nacieras, estaba seguro de que encontraría mi fin de esta manera...",
  ui_story_1021_10210501_177_dialog_content = "Anciano...",
  ui_story_1021_10210501_178_dialog_content = "Me he vuelto demasiado viejo, Tiare. Todo lo que tengo para sostenerme ahora son estos recuerdos.",
  ui_story_1021_10210501_179_dialog_content = "Dime, ¿has tomado tu decisión? ¿Y estás listo para cumplirla por el resto de tu vida?",
  ui_story_1021_10210501_180_dialog_content = "Deseo proteger a nuestra tribu, anciano... pero también deseo ayudar a la reina.",
  ui_story_1021_10210501_181_dialog_content = "Si hay una división entre la familia real y nuestra tribu, por favor dígamelo, y haré todo lo que esté a mi alcance para superarla.",
  ui_story_1021_10210501_182_dialog_content = "Para defender a Northland de los Eclipsites, ¿deberíamos confiar los unos en los otros por ahora y permanecer unidos?",
  ui_story_1021_10210501_183_dialog_content = "...",
  ui_story_1021_10210501_184_dialog_content = "Anciano, hay algo que siempre ha existido en mis recuerdos, algo que concierne al Refugio Primordial.",
  ui_story_1021_10210501_185_dialog_content = "Acabo de verlo fugazmente en mis visiones...",
  ui_story_1021_10210501_186_dialog_content = "El pino de nieve que sirvió como el primer Faro de Northland, el árbol que una vez estuvo enraizado aquí, fue potenciado por la antigua energía que emanaba de este lugar.",
  ui_story_1021_10210501_187_dialog_content = "¿Estoy en lo correcto al asumir que el Refugio Primal existe en algún lugar cerca del altar?",
  ui_story_1021_10210501_188_dialog_content = "Si es así, ¿conoces alguna forma de invocarlo y usar su poder para defender Northland?",
  ui_story_1021_10210501_189_dialog_content = "¿Una forma de invocar el Refugio Primordial? Jeje...",
  ui_story_1021_10210501_190_dialog_content = "Tendrías que apagar el Faro de Northland y permitir que nuevos brotes crezcan de estos tres árboles caídos.",
  ui_story_1021_10210501_191_dialog_content = "...",
  ui_story_1021_10210501_192_dialog_content = "Aparte del Faro, hay otros dos pinos de nieve que deben ser devueltos al altar, ¿verdad?",
  ui_story_1021_10210501_193_dialog_content = "Correcto.",
  ui_story_1021_10210501_194_dialog_content = "Anciano... ¿Es eso cierto?",
  ui_story_1021_10210501_195_dialog_content = "...",
  ui_story_1021_10210501_196_dialog_content = "Pero el Faro de Northland nunca se ha apagado... Si la llama se extingue, ¿no significa eso que el Palacio de Invierno y la gente del reino—",
  ui_story_1021_10210501_197_dialog_content = "¿Qué pasó con ser el \"guardaespaldas de Su Majestad\"?",
  ui_story_1021_10210501_198_dialog_content = "Tu reina desea convocar al Refugio Primordial y saldar su deuda con nuestra tribu. ¿Buscas desafiarla?",
  ui_story_1021_10210501_199_dialog_content = "¡Por supuesto que no! Siempre seguiré a la reina a donde quiera que vaya! Pero...",
  ui_story_1021_10210501_200_dialog_content = "Mírame, Tiare.",
  ui_story_1021_10210501_201_dialog_content = "...",
  ui_story_1021_10210501_202_dialog_content = "Por favor, ten fe en mí. Acepté este poder y sé lo que debo hacer para retribuir esa bendición.",
  ui_story_1021_10210501_203_dialog_content = "Como mi guardia, deseo que me ayudes a invocar el Refugio Primordial para defender a todo Northland.",
  ui_story_1021_10210501_204_dialog_content = "Depende de ti traer de vuelta los otros dos pinos de nieve. ¿Entiendes?",
  ui_story_1021_10210501_205_dialog_content = "Su Majestad...",
  ui_story_1021_10210501_206_dialog_content = "Todo lo que yace bajo la nieve es Northland, un reino al que he jurado proteger con mi vida.",
  ui_story_1021_10210501_207_dialog_content = "La luz del Faro no llega a este lugar, por lo que es mi responsabilidad defender tu hogar de los Eclipsites.",
  ui_story_1021_10210501_208_dialog_content = "...",
  ui_story_1021_10210501_209_dialog_content = "Novio, ¿estás familiarizado con la ubicación de los pinos nevados, sí?",
  ui_story_1021_10210501_210_dialog_content = "Sí, Su Majestad. Tenga la seguridad de que los recuperaremos mientras usted se enfrenta al Eclipsite.",
  ui_story_1021_10210501_211_dialog_content = "...",
  ui_story_1021_10210501_212_dialog_content = "Voy con el señor Novio y los demás ahora, anciano...",
  ui_story_1021_10210501_213_dialog_content = "Ve. Sigue tu propio faro y cumple tu promesa a tu reina.",
  ui_story_1021_10210501_214_dialog_content = "¡Lo haré!",
  ui_story_1021_10210601_1_dialog_content = "Queen Bethlehem está luchando contra los Eclipsites toda ella sola... ¿Realmente no hay nada que podamos hacer para ayudarla?",
  ui_story_1021_10210601_2_dialog_content = "La última vez que Su Majestad me rescató, me otorgó mi poder único. Ella ha hecho tanto por mí, y sin embargo, no puedo luchar a su lado en este momento...",
  ui_story_1021_10210601_3_dialog_content = "Y con buena razón. Después de tu encuentro anterior con ese Eclipsite, deberías saber lo poderoso que es.",
  ui_story_1021_10210601_4_dialog_content = "Además, sigues ayudando a la reina al recuperar los pinos de nieve para ella.",
  ui_story_1021_10210601_5_dialog_content = "El Darkflow que brota de este géiser ha estado erosionando las llanuras de nieve de Northland todo este tiempo...",
  ui_story_1021_10210601_6_dialog_content = "Su Majestad acudió al anciano en busca de una forma de purgar este mal de nuestra tierra. En otras palabras, para invocar el Refugio Primordial.",
  ui_story_1021_10210601_7_dialog_content = "Entonces, ¿dónde podemos encontrar los otros dos pinos de nieve, señor Novio?",
  ui_story_1021_10210601_8_dialog_content = "Aparte del que se encuentra en el Faro, los otros dos pinos de nieve se encuentran en ubicaciones separadas, donde continúan protegiendo a Northland hasta el día de hoy.",
  ui_story_1021_10210601_9_dialog_content = "¿Continuar protegiendo Northland?",
  ui_story_1021_10210601_10_dialog_content = "En efecto. Uno se guarda dentro del Palacio de Invierno, mientras que el otro yace en el lugar de tu nacimiento.",
  ui_story_1021_10210601_11_dialog_content = "Sin embargo, el paso del tiempo puede haberlos hecho prácticamente irreconocibles ahora. ¿Quizás la leyenda de los Tres Pinos arrojará más luz sobre el asunto?",
  ui_story_1021_10210601_12_dialog_content = "Aunque el poder de la naturaleza normalmente permanece dormido, debería resonar con el poder que la reina te otorgó cuando te acercas a los pinos de nieve.",
  ui_story_1021_10210601_13_dialog_content = "Comprendido. Gracias, Señor Novio!",
  ui_story_1021_10210601_14_dialog_content = "Tanto Queen Bethlehem como el zorro mayor entienden lo que significa proteger con sus vidas.",
  ui_story_1021_10210601_15_dialog_content = "Como guardián de Northland, también tienes un papel que desempeñar, Tiare. Estás en una misión para proteger.",
  ui_story_1021_10210601_16_dialog_content = "Déjamelo a mí. ¡No decepcionaré a nadie!",
  ui_story_1021_10210601_17_dialog_content = "¡Espera, Tiare! ¡Déjame ir contigo!",
  ui_story_1021_10210601_18_dialog_content = "¿Tú?",
  ui_story_1021_10210601_19_dialog_content = "¡Yo también puedo ayudar!",
  ui_story_1021_10210601_20_dialog_content = "¿Pero realmente crees que puedes seguirme el ritmo? O mejor dicho, ¿estás dispuesto a dejarme llevarte de nuevo?",
  ui_story_1021_10210601_21_dialog_content = "¿Llevar?",
  ui_story_1021_10210601_22_dialog_content = "... Si eso significa que puedo ayudarte, ¡entonces lo haré!",
  ui_story_1021_10210601_23_dialog_content = "Las habilidades psíquicas de PlayerName podrían ayudar.",
  ui_story_1021_10210601_24_dialog_content = "Ya veo... Entonces dejo las cosas aquí a ti y a los demás, señor Novio!",
  ui_story_1021_10210601_25_dialog_content = "PlayerName y yo volveremos enseguida!",
  ui_story_1021_10210601_26_dialog_content = "¿E-Eh?",
  ui_story_1021_10210601_27_dialog_content = "Y así como así, se fueron...",
  ui_story_1021_10210601_28_dialog_content = "El fluido cargado de Darkflow se está arrastrando constantemente hacia el palacio...",
  ui_story_1021_10210601_29_dialog_content = "Parece que incluso la impresionante Lumina de Nikinis es impotente para contenerlo ahora.",
  ui_story_1021_10210601_30_dialog_content = "Solo podemos esperar que Tiare regrese con los pinos de nieve a tiempo. Todavía hay esperanza para la supervivencia de su tribu...",
  ui_story_1021_10210601_31_dialog_content = "Por favor, permítame servir como guardia de Northland, Señor Novio. ¡También deseo hacer mi parte para proteger el reino!",
  ui_story_1021_10210601_32_dialog_content = "<color=#e8d9bb>Al otro lado del bosque</color>",
  ui_story_1021_10210601_33_dialog_content = "Bueno, ya que no tenemos una forma de volver al Desierto de Rediesel en este momento, nuestra mejor opción es ayudar a PlayerName y a los demás a salvar el día.",
  ui_story_1021_10210601_34_dialog_content = "¿Hablas en serio?",
  ui_story_1021_10210601_35_dialog_content = "¡Absolutamente! Además, todo es para el beneficio de Rediesel.",
  ui_story_1021_10210601_36_dialog_content = "PlayerName ha ayudado mucho a Sinsa en lo que respecta a la situación de Eve.",
  ui_story_1021_10210601_37_dialog_content = "Por eso, Sinsa siempre está dispuesto a echar una mano cuando PlayerName está en peligro.",
  ui_story_1021_10210601_38_dialog_content = "Esos dos son uña y carne. Sinsa solo finge que no lo sabe.",
  ui_story_1021_10210601_39_dialog_content = "¡Así que si les ayudamos en nombre de Rediesel Wrench, él nos deberá un favor!",
  ui_story_1021_10210601_40_dialog_content = "¡Eres un genio, Roy! No es de extrañar que el mandamás Sinsa siempre diga que podemos aprender una o dos cosas de ti!",
  ui_story_1021_10210601_41_dialog_content = "Por supuesto, ahora sigamos moviéndonos. ¡Eliminaremos a cualquier Eclipsites en nuestro camino mientras seguimos el flujo del líquido negro!",
  ui_story_1021_10210601_42_dialog_content = "<color=#e8d9bb>Cerca de la frontera de Northland</color>",
  ui_story_1021_10210601_43_dialog_content = "(Eclipsian) Mi señor... No podemos ir más allá...",
  ui_story_1021_10210601_44_dialog_content = "(Eclipsian) Dicen que la luz de esa maldita baliza desgarrará nuestros cuerpos.",
  ui_story_1021_10210601_45_dialog_content = "(Eclipsita) El hielo y las llamas no significan nada para nosotros, y tampoco debería hacerlo la luz de esa baliza malvada.",
  ui_story_1021_10210601_46_dialog_content = "<color=#e8d9bb>¡Awoooo!</color>",
  ui_story_1021_10210601_47_dialog_content = "(Eclipsian) Las bestias blancas nos están aullando.",
  ui_story_1021_10210601_48_dialog_content = "(Eclipsian) Después de todos estos años, cuando la fortaleza y sus guardias han vuelto al polvo, aún permanecen.",
  ui_story_1021_10210601_49_dialog_content = "(Eclipsian) Northland realmente es un lugar maravilloso para estar.",
  ui_story_1021_10210601_50_dialog_content = "¡Hoja de Escarcha!",
  ui_story_1021_10210601_51_dialog_content = "¡Todos los invasores de Northland encontrarán su fin en la nieve!",
  ui_story_1021_10210601_52_dialog_content = "Incluso después de perdonarte, has elegido perseguirme con tal tenacidad obstinada.",
  ui_story_1021_10210601_53_dialog_content = "Dime, ¿piensas sellarnos en una pared de hielo una vez más?",
  ui_story_1021_10210601_54_dialog_content = "... ¿Qué sabes sobre <color=#FFB400>esa batalla</color>?",
  ui_story_1021_10210601_55_dialog_content = "Parece que todavía eres bastante joven.",
  ui_story_1021_10210601_56_dialog_content = "(Eclipsian) Ve. Hazle compañía a nuestro amigo.",
  ui_story_1021_10210601_57_dialog_content = "(Eclipsian) ¡Sí, mi señor!",
  ui_story_1021_10210700_1_dialog_content = "... La reina dijo que tenía que entregar este mensaje lo más rápido que pude!",
  ui_story_1021_10210700_2_dialog_content = "Es así, ¿ves?",
  ui_story_1021_10210700_3_dialog_content = "Así que la expedición conjunta ya ha comenzado incluso antes de entrar en la Zona Oscura.",
  ui_story_1021_10210700_4_dialog_content = "Aun así, necesitamos defender el puesto avanzado en Northland. Vamos, Vivian, nos vamos a Northland de inmediato.",
  ui_story_1021_10210700_5_dialog_content = "Sí, Gran Mariscal.",
  ui_story_1021_10210700_6_dialog_content = "También me acompañarás, Ms. Blanc.",
  ui_story_1021_10210700_7_dialog_content = "Si mi señor.",
  ui_story_1021_10210700_8_dialog_content = "¿También vamos nosotros, Bethel?",
  ui_story_1021_10210700_9_dialog_content = "Por supuesto. Umbraton no puede permitirse perder esto.",
  ui_story_1021_10210700_10_dialog_content = "Pero Northland se encuentra a una altitud tan alta...",
  ui_story_1021_10210700_11_dialog_content = "Todos estamos en igualdad de condiciones aquí, Lady Bethel. Eres bienvenida a viajar con nosotros en nuestro avión si así lo deseas.",
  ui_story_1021_10210700_12_dialog_content = "¡Muy apreciado!",
  ui_story_1021_10210700_13_dialog_content = "T-Tiare... ¿No puedo simplemente caminar una parte del viaje? Siento que mi espalda está a punto de partirse en dos...",
  ui_story_1021_10210700_14_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_1021_10210700_15_dialog_content = "No puedo creer que me hayas llevado todo este camino... ¡y sobre tus hombros, nada menos!",
  ui_story_1021_10210700_16_dialog_content = "Dijiste que podía llevarte, así que lo hice. ¿Todos los forasteros son tan propensos a decir lo que no quieren decir?",
  ui_story_1021_10210700_17_dialog_content = "Para nada... Para ser honesto, no pensé que estabas hablando en serio antes...",
  ui_story_1021_10210700_18_dialog_content = "¡Pero creo que ahora sé cómo funciona el líder de los zorros de nieve!",
  ui_story_1021_10210700_19_dialog_content = "¡Uf! Puedo ver el Palacio de Invierno desde aquí...",
  ui_story_1021_10210700_20_dialog_content = "Grr...",
  ui_story_1021_10210700_21_dialog_content = "Uh, ¿qué eres tú—",
  ui_story_1021_10210700_22_dialog_content = "<color=#e8d9bb>¡Awoo!</color>",
  ui_story_1021_10210700_23_dialog_content = "¡Tienes una respuesta!",
  ui_story_1021_10210700_24_dialog_content = "Sí. Así es como los zorros y yo nos comunicamos entre nosotros.",
  ui_story_1021_10210700_25_dialog_content = "Entonces, ¿qué dijiste hace un momento?",
  ui_story_1021_10210700_26_dialog_content = "Les dije que el agua negra aún no había llegado a este lugar. Los zorros dijeron que le informarían al Señor Novio.",
  ui_story_1021_10210700_27_dialog_content = "¿Puedes transmitir tanta información con un solo aullido?",
  ui_story_1021_10210700_28_dialog_content = "¡Así es! ¡Tú también deberías intentarlo!",
  ui_story_1021_10210700_29_option_content = "¿Yo? M-Tal vez no...",
  ui_story_1021_10210700_30_dialog_content = "¿Por qué? ¿Es demasiado vergonzoso para ti?",
  ui_story_1021_10210700_31_dialog_content = "¡N-De ninguna manera! ¿Qué te hace decir eso?",
  ui_story_1021_10210700_32_dialog_content = "Cuando llegué por primera vez al Palacio de Invierno, algunos de los guardias me imitaban todo el tiempo...",
  ui_story_1021_10210700_33_dialog_content = "Al principio, pensé que mi aullido era demasiado fuerte, pero luego me di cuenta de que el volumen no tenía nada que ver con eso.",
  ui_story_1021_10210700_34_dialog_content = "¡Aun así, nunca me avergoncé de ello! Hice todo lo posible para evitar aullar en el Palacio de Invierno...",
  ui_story_1021_10210700_35_dialog_content = "Pero cuando es tarde en la noche o estoy de patrulla por mi cuenta, todavía me gusta comunicarme con los zorros de esta manera.",
  ui_story_1021_10210700_36_dialog_content = "¡No hay nada de qué avergonzarse! Escucha esto—",
  ui_story_1021_10210700_37_dialog_content = "¡Arrgh!",
  ui_story_1021_10210700_38_option_content = "¡Uwaaagh!",
  ui_story_1021_10210700_39_dialog_content = "¿Bien?",
  ui_story_1021_10210700_40_dialog_content = "...",
  ui_story_1021_10210700_41_dialog_content = "Esa expresión en tu cara... ¿Realmente fue tan mala?",
  ui_story_1021_10210700_42_dialog_content = "No, solo estoy tratando de entender lo que dijiste hace un momento... ¿Estabas pidiendo comida o diciendo que el clima es bueno?",
  ui_story_1021_10210700_43_dialog_content = "¿Por qué no lo intentas de nuevo?",
  ui_story_1021_10210700_44_dialog_content = "Ah... Tal vez más tarde.",
  ui_story_1021_10210700_45_dialog_content = "Simplemente levanta la cabeza y endereza el cuello así.",
  ui_story_1021_10210700_46_dialog_content = "Levanta mi cabeza... y endereza mi cuello...",
  ui_story_1021_10210700_47_dialog_content = "¡Eso es! Ahora solo abre la boca, encuentra las palabras que quieres decir desde lo más profundo de tu corazón, ¡y grítalas todas de una vez!",
  ui_story_1021_10210700_48_dialog_content = "Grr...",
  ui_story_1021_10210700_49_dialog_content = "<color=#e8d9bb>¡Awoo!</color>",
  ui_story_1021_10210700_50_dialog_content = "¿Ves? Tenía razón, ¿no?",
  ui_story_1021_10210700_51_dialog_content = "¡Guau! No sé si mi mensaje fue claro o no, ¡pero es genial recibir una respuesta!",
  ui_story_1021_10210700_52_dialog_content = "Escuchar tu alegría también hace felices a los zorros.",
  ui_story_1021_10210700_53_dialog_content = "Bien, creo que hemos descansado lo suficiente. ¡Ahora es el momento de llevarte al Palacio de Invierno de una vez!",
  ui_story_1021_10210700_54_dialog_content = "¡O-Oye! ¡Al menos déjame mirar hacia adelante!",
  ui_story_1021_10210700_55_dialog_content = "¡Hola, señorita Zarya! Has recolectado mucho mineral hoy, ¿verdad?",
  ui_story_1021_10210700_56_dialog_content = "¡Es correcto! Es mi primer trabajo de la reina, así que naturalmente, ¡tengo que hacer mi mejor esfuerzo!",
  ui_story_1021_10210700_57_dialog_content = "Escucho que tus Luminatics son muy poderosos. ¡Extraer tanto mineral debe haber sido fácil para alguien como tú!",
  ui_story_1021_10210700_58_dialog_content = "No del todo... Todavía me congelo accidentalmente de vez en cuando...",
  ui_story_1021_10210700_59_dialog_content = "Afortunadamente solo me congelo parcialmente, ¡pero aún tengo mucho que aprender! De todos modos, me voy al Palacio de Invierno para informar a la reina. ¡Adiós!",
  ui_story_1021_10210700_60_dialog_content = "Oh... Pero por lo que he oído, Su Majestad no está en el Palacio de Invierno en este momento...",
  ui_story_1021_10210700_61_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_1021_10210700_62_dialog_content = "Qué-",
  ui_story_1021_10210700_63_dialog_content = "Es PlayerName y Tiare... Pero, ¿qué están haciendo aquí?",
  ui_story_1021_10210700_64_dialog_content = "Hemos buscado en cada rincón del lugar, pero tu lanza no ha respondido ni una sola vez...",
  ui_story_1021_10210700_65_dialog_content = "Quizás la energía antigua ha estado latente durante demasiado tiempo...",
  ui_story_1021_10210700_66_dialog_content = "Novio dijo que deberíamos buscar pistas en la leyenda. ¿Alguna idea de lo que quiso decir con eso?",
  ui_story_1021_10210700_67_dialog_content = "El pino de nieve en el Palacio de Invierno debería corresponder a la primera parte de la leyenda: \"Brinda vitalidad al monarca cansado, quien a su vez trae paz al mundo.\"",
  ui_story_1021_10210700_68_dialog_content = "Entonces, ¿cómo suele la reina recuperar su fuerza cuando está cansada?",
  ui_story_1021_10210700_69_dialog_content = "La reina no pasa mucho tiempo en el Palacio de Invierno. Más a menudo que no, está en su dormitorio, en el comedor o en los jardines detrás del palacio.",
  ui_story_1021_10210700_70_dialog_content = "Parece que la reina alivia su estrés de la misma manera que yo: con comida, sueño y mucho tiempo libre.",
  ui_story_1021_10210700_71_dialog_content = "De alguna manera, no creo que la reina se deleite en las cosas de las que estás hablando...",
  ui_story_1021_10210700_72_dialog_content = "¿Por qué ustedes dos tienen tanta prisa por encontrar a la reina? ¿Sucede algo?",
  ui_story_1021_10210700_73_dialog_content = "Este mineral...",
  ui_story_1021_10210700_74_dialog_content = "No te preocupes. ¡Te prometo que el mineral no es de los alrededores de tu casa!",
  ui_story_1021_10210700_75_dialog_content = "¿Qué estás haciendo aquí, Zarya?",
  ui_story_1021_10210700_76_dialog_content = "¿No me viste hace un momento? Los vi a los dos corriendo hacia el palacio, así que pensé que tenían un asunto urgente con la reina.",
  ui_story_1021_10210700_77_dialog_content = "Pero me han dicho que la reina está ausente del Palacio de Invierno en este momento, así que vine a decírtelo.",
  ui_story_1021_10210700_78_dialog_content = "Eso ya lo sabemos.",
  ui_story_1021_10210700_79_dialog_content = "Entonces, ¿qué haces aquí exactamente?",
  ui_story_1021_10210700_80_dialog_content = "Buscando algo.",
  ui_story_1021_10210700_81_dialog_content = "¿Es así? ¿Quizás puedo echarte una mano?",
  ui_story_1021_10210700_82_dialog_content = "Bueno, estamos buscando algo... que alivie el cansancio de la reina.",
  ui_story_1021_10210700_83_dialog_content = "Hmm... Eso casi suena como un juego que a los niños les gusta jugar, uno que está basado en una leyenda...",
  ui_story_1021_10210700_84_dialog_content = "¿Y este juego es común entre los niños?",
  ui_story_1021_10210700_85_dialog_content = "Por supuesto. A menudo se ve a los niños locales jugando este juego en el jardín de la reina.",
  ui_story_1021_10210700_86_dialog_content = "¿Realmente se permite a los niños entrar así como así al Palacio de Invierno?",
  ui_story_1021_10210700_87_dialog_content = "Queen Bethlehem nunca ha visto el palacio como algo que le pertenece exclusivamente.",
  ui_story_1021_10210700_88_dialog_content = "Es tan generosa como diligente. Ahora que lo pienso, no creo haberla visto tomar un descanso nunca...",
  ui_story_1021_10210700_89_dialog_content = "Hay asientos y bancos por todo el palacio, incluyendo estas hermosas sillas columpio en el jardín, pero nunca la he visto sentarse en una.",
  ui_story_1021_10210700_90_dialog_content = "Entonces, tal vez la respuesta que buscamos... ¡está justo aquí! ¡Ven a ver esto, Tiare!",
  ui_story_1021_10210700_91_dialog_content = "...",
  ui_story_1021_10210700_92_dialog_content = "¿Eh? ¡Tu lanza está brillando!",
  ui_story_1021_10210700_93_dialog_content = "¡Ajá... lo sabía!",
  ui_story_1021_10210700_94_dialog_content = "El trono de la reina...",
  ui_story_1021_10210700_95_dialog_content = "¿Es esto lo que estás buscando?",
  ui_story_1021_10210700_96_dialog_content = "Un trono es la cosa perfecta para disipar la fatiga de un monarca. También es un símbolo de su autoridad...",
  ui_story_1021_10210700_97_dialog_content = "Así que hicieron el trono de la reina con el primer pino de nieve... Pero no creo que la haya visto sentarse en él nunca...",
  ui_story_1021_10210700_98_dialog_content = "¿Podría ser que se niega a descansar en él porque conoce su origen?",
  ui_story_1021_10210700_99_dialog_content = "...",
  ui_story_1021_10210700_100_dialog_content = "¡Parece que el trono está cambiando!",
  ui_story_1021_10210700_101_dialog_content = "Su Majestad, en nombre de las tribus que han jurado lealtad al Queen del Norte, permítame presentarle esto: un trono digno de su soberanía.",
  ui_story_1021_10210700_102_dialog_content = "A partir de este día, puedes mirar a tus súbditos desde lo alto de este asiento de poder.",
  ui_story_1021_10210700_103_dialog_content = "Mi fiel sirviente, ¿sabes cuánto tiempo tomaría recorrer la longitud y anchura de todo Northland?",
  ui_story_1021_10210700_104_dialog_content = "No estoy seguro, Su Majestad... ¿Pero por qué pregunta?",
  ui_story_1021_10210700_105_dialog_content = "No hay forma de que pueda proteger a Northland desde un trono frío. Para preservar nuestra hermosa tierra, debo viajar a cada rincón de ella.",
  ui_story_1021_10210700_106_dialog_content = "Pero a medida que cae la nieve, los caminos que tomas inevitablemente desaparecerán, y tendrás que crear nuevos.",
  ui_story_1021_10210700_107_dialog_content = "Los bosques también cambiarán con la llegada de cada nueva primavera.",
  ui_story_1021_10210700_108_dialog_content = "Entonces viajaré sin descanso, patrullando la tierra hasta que cada rincón de ella caiga bajo la luz protectora del Faro.",
  ui_story_1021_10210700_109_dialog_content = "¿Fue eso...?",
  ui_story_1021_10210700_110_dialog_content = "¿Acabamos de presenciar el momento en que Su Majestad se convirtió por primera vez en Queen del Norte?",
  ui_story_1021_10210700_111_dialog_content = "Pudimos verlo sin el uso de mis poderes... Debe haber ocurrido incluso antes de eso...",
  ui_story_1021_10210700_112_dialog_content = "Las tribus de Northland crearon un trono para ella como símbolo de su lealtad, pero ella se negó a sentarse en él.",
  ui_story_1021_10210700_113_dialog_content = "Y desde que Queen Bethlehem heredó su voluntad, ha estado viajando por la tierra sin descanso...",
  ui_story_1021_10210700_114_dialog_content = "¡Mira!",
  ui_story_1021_10210700_115_dialog_content = "El trono se convirtió en una pequeña rama...",
  ui_story_1021_10210700_116_dialog_content = "Parece que este es el pino de nieve que hemos estado buscando.",
  ui_story_1021_10210700_117_dialog_content = "¡Qué poder tan asombroso!",
  ui_story_1021_10210700_118_dialog_content = "Con esto, podremos ayudar a la reina...",
  ui_story_1021_10210700_119_dialog_content = "¡Así es, y ahora nos dirigimos a nuestra próxima parada, tu casa!",
  ui_story_1021_10210700_120_dialog_content = "¡Entonces vamos!",
  ui_story_1021_10210700_121_dialog_content = "¡Oye! La próxima vez que vayas a una legendaria búsqueda de tesoros, ¡déjame unirme a ti!",
  ui_story_1021_10210700_122_dialog_content = "<color=#e8d9bb>Desde ese momento, la Queen del Norte ya no tiene un trono.</color>",
  ui_story_1021_10210801_1_dialog_content = "<color=#e8d9bb>Whoosh, whoosh, whoosh—</color>",
  ui_story_1021_10210801_2_dialog_content = "El clima cambió repentinamente...",
  ui_story_1021_10210801_3_dialog_content = "El Faro está completamente cubierto por una ventisca. Me pregunto cómo estarán Su Majestad y los demás...",
  ui_story_1021_10210801_4_dialog_content = "¿Entonces tienes alguna idea de dónde encontrar el próximo pino de nieve?",
  ui_story_1021_10210801_5_dialog_content = "La siguiente parte de la leyenda dice, \"Su sagrado pacto convierte la oscuridad en luz.\"",
  ui_story_1021_10210801_6_dialog_content = "Recuerdo que mi abuela mencionó algo al respecto...",
  ui_story_1021_10210801_7_dialog_content = "Northland experimentó una era de oscuridad en algún momento del pasado y solo emergió de ella gracias a un antiguo pacto con lo divino.",
  ui_story_1021_10210801_8_dialog_content = "Un pacto, ¿eh? Suena demasiado abstracto para mí...",
  ui_story_1021_10210801_9_dialog_content = "Pero un pacto siempre existirá mientras alguien lo recuerde y lo mantenga.",
  ui_story_1021_10210801_10_dialog_content = "Al menos eso es lo que me dijo mi abuela...",
  ui_story_1021_10210801_11_dialog_content = "Creo que tengo una idea...",
  ui_story_1021_10210801_12_dialog_content = "Estoy bastante seguro de que tu abuela era exactamente ese tipo de persona, lo que significa que podría ser capaz de encontrar una pista dentro de tus recuerdos de ella...",
  ui_story_1021_10210801_13_dialog_content = "¿En serio?",
  ui_story_1021_10210801_14_dialog_content = "Pero mi abuela falleció hace tanto tiempo... No sé si mis recuerdos son tan útiles como crees...",
  ui_story_1021_10210801_15_dialog_content = "¿Por qué?",
  ui_story_1021_10210801_16_dialog_content = "... Lo sabrás una vez que los veas.",
  ui_story_1021_10210801_17_dialog_content = "¡No te preocupes, estoy seguro de que encontraré algo!",
  ui_story_1021_10210801_18_option_content = "Enlace Telepático—",
  ui_story_1021_10210801_19_dialog_content = "¡Basta! ¡Me niego a escuchar más!",
  ui_story_1021_10210801_20_dialog_content = "¿Qué, no puedo decir algunas cosas más antes de que llegue mi hora?",
  ui_story_1021_10210801_21_dialog_content = "Abuela... ¿Esto significa que ya no jugarás conmigo?",
  ui_story_1021_10210801_22_dialog_content = "Me temo que no, mi pequeña Tiare... Prométeme que serás una niña buena y crecerás grande y fuerte, ¿de acuerdo?",
  ui_story_1021_10210801_23_dialog_content = "Si tan solo pudieras hacerlo antes, Tiare...",
  ui_story_1021_10210801_24_dialog_content = "Si tengo un arrepentimiento en la vida, es que no estaré lo suficientemente tiempo para verte crecer...",
  ui_story_1021_10210801_25_dialog_content = "En unos pocos años, me uniré a mis seres queridos que ya no están...",
  ui_story_1021_10210801_26_dialog_content = "No olvides a tu vieja abuela, Tiare... o a tu tribu... Recuerda siempre...",
  ui_story_1021_10210801_27_dialog_content = "Deja de lastimar a todos con tus palabras. Pronto ninguno de nosotros estará vivo para recordarlas.",
  ui_story_1021_10210801_28_dialog_content = "Ve a jugar con los otros zorros allá, Tiare.",
  ui_story_1021_10210801_29_dialog_content = "Wow... Esta es mi cola, y...",
  ui_story_1021_10210801_30_dialog_content = "Esto es... ¡No, espera, déjame adivinar!",
  ui_story_1021_10210801_31_dialog_content = "No debes traer Tiare aquí nunca más.",
  ui_story_1021_10210801_32_dialog_content = "Tiare es una niña de esta tribu. Nunca puede olvidar la gloria de su pueblo, ni las bendiciones de sus antepasados que llevaron a su nacimiento.",
  ui_story_1021_10210801_33_dialog_content = "Ella se convertirá en la líder de esta tribu y una verdadera guardiana de Northland. Me aseguraré de ello...",
  ui_story_1021_10210801_34_dialog_content = "Y cuando llegue ese día, ella será la que se dé cuenta de ese pacto.",
  ui_story_1021_10210801_35_dialog_content = "En el pasado, las tribus de Northland se mantenían unidas, pero ahora solo los zorros de nieve permanecen para proteger nuestra tierra.",
  ui_story_1021_10210801_36_dialog_content = "Nunca veremos la realización del pacto. Tal vez la <color=#FFB400>tableta</color> ha sido casi olvidada por lo divino.",
  ui_story_1021_10210801_37_dialog_content = "No dejes que te oiga decir eso a Tiare, viejo zorro polvoriento.",
  ui_story_1021_10210801_38_dialog_content = "Lo divino nunca olvidaría, y mientras Tiare esté vivo, nosotros tampoco lo haremos.",
  ui_story_1021_10210801_39_dialog_content = "... Entonces destruiré la tableta antes de que Tiare se entere.",
  ui_story_1021_10210801_40_dialog_content = "Valoras esa tableta más que nadie. Nunca harías tal cosa.",
  ui_story_1021_10210801_41_dialog_content = "No tengo otra opción.",
  ui_story_1021_10210801_42_dialog_content = "¿Es tan malo ocultarle estas cosas? Solo mírala, jugando felizmente como una niña normal. ¿No es suficiente?",
  ui_story_1021_10210801_43_dialog_content = "Su deber es proteger a la tribu, ¡no ese palacio de hielo!",
  ui_story_1021_10210801_44_dialog_content = "La familia real robó el poder de lo divino sin dar nada a cambio. No solo eso, también sellaron a nuestros valientes soldados en una tumba congelada, junto con los invasores de Northland...",
  ui_story_1021_10210801_45_dialog_content = "Ha pasado más de un milenio... ¿Pero ha habido algún cambio en el hielo?",
  ui_story_1021_10210801_46_dialog_content = "¿Crees que Tiare seguirá siendo tan feliz si se entera de nuestro trágico pasado?",
  ui_story_1021_10210801_47_dialog_content = "Pacto, protección... Todo me parece tan cruel ahora.",
  ui_story_1021_10210801_48_dialog_content = "La crueldad que he visto en ti desde el momento en que naciste, y hasta—",
  ui_story_1021_10210801_49_dialog_content = "Eso es suficiente. El corazón de Tiare será lo suficientemente fuerte para enfrentar esta crueldad, al igual que sus grandes antepasados antes que ella.",
  ui_story_1021_10210801_50_dialog_content = "...",
  ui_story_1021_10210801_51_dialog_content = "Abuela, este zorro te llamó una vieja bruja malvada. ¡Jajaja! ¡Para, eso hace cosquillas!",
  ui_story_1021_10210801_52_dialog_content = "¡Yo... no voy a perder contra ti!",
  ui_story_1021_10210801_53_dialog_content = "...",
  ui_story_1021_10210801_54_dialog_content = "¿Qué pasa?",
  ui_story_1021_10210801_55_dialog_content = "... Los viste discutir, ¿verdad?",
  ui_story_1021_10210801_56_dialog_content = "Sí. Estaban divididos sobre si debían o no dejarte convertirte en el líder de tu tribu.",
  ui_story_1021_10210801_57_dialog_content = "No tenía idea de que el anciano no quería que lideraras a los zorros de nieve...",
  ui_story_1021_10210801_58_dialog_content = "Lo sé... La anciana nunca fue de las que daban la bienvenida a los extraños, ni siquiera quería que yo volviera a la tribu...",
  ui_story_1021_10210801_59_dialog_content = "Quizás es porque sabía que terminaría así bajo mi liderazgo.",
  ui_story_1021_10210801_60_dialog_content = "Eso no es en absoluto. El anciano estaba preocupado de que nunca volvieras a ser feliz y de que pasaras tu vida en odio como tu abuela.",
  ui_story_1021_10210801_61_dialog_content = "¿Feliz?",
  ui_story_1021_10210801_62_dialog_content = "Así que por eso quería que cortara lazos con la tribu y sirviera como guardia de la reina...",
  ui_story_1021_10210801_63_dialog_content = "Ella guardó este secreto para sí misma todo este tiempo...",
  ui_story_1021_10210801_64_dialog_content = "Nunca me dejan acercarme al altar...",
  ui_story_1021_10210801_65_dialog_content = "O contándome sobre la leyenda...",
  ui_story_1021_10210801_66_dialog_content = "Incluso cuando la tribu estaba en peligro, ella me alejó...",
  ui_story_1021_10210801_67_dialog_content = "La anciana tiene un profundo amor por su tribu, pero te ama aún más, Tiare...",
  ui_story_1021_10210801_68_dialog_content = "...",
  ui_story_1021_10210801_69_dialog_content = "¡Es por eso que no puedo abandonar mi promesa como líder de los zorros de nieve!",
  ui_story_1021_10210801_70_dialog_content = "¡Creo en Su Majestad! Si ella dice que invocar al Refugio Primordial salvará a mi tribu, ¡entonces debe ser cierto!",
  ui_story_1021_10210801_71_dialog_content = "¡Para entonces, el mayor nunca me obligará a irme!",
  ui_story_1021_10210801_72_dialog_content = "¡Sé que puedes hacerlo, Tiare!",
  ui_story_1021_10210801_73_dialog_content = "Pero incluso después de buscar en mis recuerdos, todavía no hemos encontrado ninguna pista sobre el paradero del pino de nieve, ¿verdad?",
  ui_story_1021_10210801_74_dialog_content = "No, hablaron de una tableta... Aparentemente, registró un pacto entre lo divino y la Tribu Fox de la Nieve?",
  ui_story_1021_10210801_75_dialog_content = "Una tableta...",
  ui_story_1021_10210801_76_dialog_content = "Tu abuela dijo que la anciana lo apreciaba más que nadie.",
  ui_story_1021_10210801_77_dialog_content = "Pero es posible que ella ya lo haya destruido...",
  ui_story_1021_10210801_78_dialog_content = "...",
  ui_story_1021_10210801_79_dialog_content = "Piénsalo. Si realmente el anciano lo valoraba, entonces debe haber ido a algún lugar para verlo bastante a menudo.",
  ui_story_1021_10210801_80_dialog_content = "Lugares donde suele ir el anciano... La cueva, el altar, las montañas, y...",
  ui_story_1021_10210801_81_dialog_content = "Podría ser...",
  ui_story_1021_10210801_82_dialog_content = "Antes de dejar la tribu, había un lugar donde el anciano iba a mirar el Faro todo el día. No está lejos de aquí.",
  ui_story_1021_10210801_83_dialog_content = "No veo nada más que árboles por aquí...",
  ui_story_1021_10210801_84_dialog_content = "... ¿Quién está ahí? ¡Muéstrense!",
  ui_story_1021_10210801_85_dialog_content = "Uh-oh... Parece que nos encontraste de nuevo...",
  ui_story_1021_10210801_86_dialog_content = "¡Ustedes dos otra vez!",
  ui_story_1021_10210801_87_dialog_content = "Vamos, ¿es esta realmente alguna forma de recompensarnos? Después de todo, nos tomamos todo el problema de limpiar a los Eclipsites de este lugar.",
  ui_story_1021_10210801_88_dialog_content = "¡Apenas creo que un ladrón de gemas como tú podría ser tan bondadoso! ¿Ahora qué robaste esta vez?",
  ui_story_1021_10210801_89_dialog_content = "Nada en absoluto, te lo aseguro. ¡Tuvimos suerte de escapar de esa cueva solo con nuestras vidas!",
  ui_story_1021_10210801_90_dialog_content = "Uh... Creo que deberías simplemente decirles la verdad, Roy.",
  ui_story_1021_10210801_91_dialog_content = "Dijiste que, como miembro del equipo de exploración conjunta, Rediesel Wrench nunca pasaría por alto las vidas o la seguridad de nuestros aliados.",
  ui_story_1021_10210801_92_dialog_content = "Como no pudimos encontrar a ninguno de ustedes después de salir de la cueva, ¡Roy y yo decidimos eliminar a los Eclipsites que habían aparecido en esta área!",
  ui_story_1021_10210801_93_dialog_content = "Es cierto, no vimos ni un solo Eclipsite en nuestro camino hasta aquí... ¡Realmente os debemos una!",
  ui_story_1021_10210801_94_dialog_content = "¿De qué estás hablando? ¡Por muy lejano que sea este lugar, aún está protegido por la luz del Faro!",
  ui_story_1021_10210801_95_dialog_content = "... ¿C-Cómo se suponía que íbamos a saber eso? ¡No hay ninguna señal por aquí ni nada! ¿Estás diciendo que no teníamos que luchar contra esos Eclipsites justo ahora?",
  ui_story_1021_10210801_96_dialog_content = "De hecho, estoy bastante seguro de que vi un marcador antes, Roy...",
  ui_story_1021_10210801_97_dialog_content = "Tiare! ¿Podría ser ese marcador—",
  ui_story_1021_10210801_98_dialog_content = "¡La tableta!",
  ui_story_1021_10210801_99_dialog_content = "¡Saca tu lanza y veamos qué sucede!",
  ui_story_1021_10210801_100_dialog_content = "¡Todo potenciado por la naturaleza!",
  ui_story_1021_10210801_101_dialog_content = "No habríamos desperdiciado nuestra energía si hubiera brillado así antes...",
  ui_story_1021_10210801_102_dialog_content = "Esta brillante inscripción... Debe haber sido escrita con aceite de pino de nieve.",
  ui_story_1021_10210801_103_dialog_content = "Mi abuela una vez dijo que nuestras lámparas de aceite de pino eran los ojos de todo Northland.",
  ui_story_1021_10210801_104_dialog_content = "Apuesto a que brilla muy brillante en la noche...",
  ui_story_1021_10210801_105_dialog_content = "Nunca hubiera pensado que uno de los pinos de nieve se estaba utilizando como marcador para el límite del Faro.",
  ui_story_1021_10210801_106_dialog_content = "¡Guau! ¿Qué esta pasando?",
  ui_story_1021_10210801_107_dialog_content = "¡Valientes guardias de Northland! La guerra ha terminado y la construcción del Faro ya está completa.",
  ui_story_1021_10210801_108_dialog_content = "Esta fortaleza congelada permanecerá en conmemoración de las vidas perdidas en defensa de las fronteras de Northland. Servirá como un recordatorio para nuestro pueblo y una advertencia para nuestros enemigos.",
  ui_story_1021_10210801_109_dialog_content = "A todos los que están reunidos aquí hoy, les prometo:",
  ui_story_1021_10210801_110_dialog_content = "La luz del Faro protegerá este lugar. ¡Ya no será el cruce de la oscuridad y la luz!",
  ui_story_1021_10210801_111_dialog_content = "Tus familias compartirán la paz y la prosperidad de Northland.",
  ui_story_1021_10210801_112_dialog_content = "May toda la naturaleza sirva como mi testigo, y May el Faro de Northland proteja nuestro justo reino.",
  ui_story_1021_10210801_113_dialog_content = "También les pido a ustedes, junto con lo divino, que sean testigos de este pacto, que extiendo a sus tribus.",
  ui_story_1021_10210801_114_dialog_content = "Como el primer Queen del Norte, juro que mis descendientes defenderán nuestra tierra hasta el final!",
  ui_story_1021_10210801_115_dialog_content = "Como líderes tribales de Northland, ¡juramos aquí que nuestros descendientes defenderán nuestra tierra hasta el final!",
  ui_story_1021_10210801_116_dialog_content = "La primera reina de Northland fue realmente algo especial...",
  ui_story_1021_10210801_117_dialog_content = "Entonces el pacto no fue entre tu tribu y lo divino...",
  ui_story_1021_10210801_118_dialog_content = "Fue una promesa entre la primera reina y todos los guardias fronterizos...",
  ui_story_1021_10210801_119_dialog_content = "Es por eso que mis antepasados siempre han vigilado este lugar. Pero la reina no cumplió su promesa y nuestra tribu entró en decadencia...",
  ui_story_1021_10210801_120_dialog_content = "Ahí es de donde viene nuestra animosidad hacia la familia real...",
  ui_story_1021_10210801_121_dialog_content = "Parece imposible que la luz del Faro llegue a este lugar...",
  ui_story_1021_10210801_122_dialog_content = "Lo sé... Pero durante años, la reina ha estado patrullando constantemente las fronteras de la tierra.",
  ui_story_1021_10210801_123_dialog_content = "Honestamente creo que ninguna de las partes incumplió su promesa.",
  ui_story_1021_10210801_124_dialog_content = "Y ahora me han confiado la tarea de invocar el Refugio Primordial y defender Northland...",
  ui_story_1021_10210801_125_dialog_content = "¡Esto debe ser lo que el señor Novio quería que entendiera!",
  ui_story_1021_10210801_126_dialog_content = "La búsqueda de los pinos nevados me ha dado una comprensión completamente nueva de Northland.",
  ui_story_1021_10210801_127_dialog_content = "Parece que está volviendo a su forma original, igual que el trono de la reina...",
  ui_story_1021_10210801_128_dialog_content = "¡Y con eso, hemos encontrado el segundo pino de nieve!",
  ui_story_1021_10210801_129_dialog_content = "En cuanto al tercero, me pregunto si Queen Bethlehem realmente tiene la intención de extinguir la Baliza de Northland por ello...",
  ui_story_1021_10210801_130_dialog_content = "¡Ya no tengo dudas en mi mente! ¡Lo que la reina se proponga hacer, estaré allí para ayudarla a lograrlo!",
  ui_story_1021_10210801_131_dialog_content = "¡Vamos a devolver estos dos pinos de nieve a ellos!",
  ui_story_1021_10210801_132_dialog_content = "¡Correcto!",
  ui_story_1021_10210801_133_dialog_content = "¡Oh, y... Gracias, ustedes dos!",
  ui_story_1021_10210801_134_dialog_content = "Jajaja, no lo menciones.",
  ui_story_1021_10210801_135_dialog_content = "Deberíamos echarles una mano ahora que los hemos encontrado, Roy.",
  ui_story_1021_10210801_136_dialog_content = "Oh, supongo. Vamos.",
  ui_story_1021_10210801_137_dialog_content = "<color=#e8d9bb>Desde ese momento, la tableta que lleva la promesa entre la reina y las tribus de Northland ha desaparecido.</color>",
  ui_story_1021_10210801_138_dialog_content = "¡Anciano! ¡Señor Novio! Hemos vuelto con el—",
  ui_story_1021_10210801_139_dialog_content = "¿Qué está pasando encima del altar?",
  ui_story_1021_10210801_140_dialog_content = "Queen Bethlehem está extrayendo el poder de la Chispa de dentro de su cuerpo y condensándolo en la Mecha.",
  ui_story_1021_10210801_141_dialog_content = "¿La Mecha? ¿Esto significa que el Faro cerca del acantilado se ha apagado?",
  ui_story_1021_10210801_142_dialog_content = "No. En realidad, Su Majestad ha estado actuando como el Faro de Northland durante mucho tiempo. Lo que ves ante ti es su propia fuerza vital.",
  ui_story_1021_10210801_143_dialog_content = "Su propia fuerza vital... Pero, ¿no la debilita enormemente?",
  ui_story_1021_10210801_144_dialog_content = "Sí, pero también le permite expulsar a los Eclipsites de las fronteras de Northland.",
  ui_story_1021_10210801_145_dialog_content = "Su Majestad...",
  ui_story_1021_10210801_146_dialog_content = "Aunque han pasado innumerables años desde entonces, el Faro prometido a este lugar finalmente se construirá, con tu ayuda, por supuesto.",
  ui_story_1021_10210801_147_dialog_content = "¿Entonces qué debería hacer ahora?",
  ui_story_1021_10210801_148_dialog_content = "Debes colocar los pinos de nieve en el altar y devolver el poder en tu lanza a lo divino junto con ellos.",
  ui_story_1021_10210801_149_dialog_content = "Ven, recemos a lo divino...",
  ui_story_1021_10210801_150_dialog_content = "Yo, Hagen, anciano de la tribu de la Nieve Fox y guardián del Señor Rode, dios de la guerra de Northland, imploro la intervención divina!",
  ui_story_1021_10210801_151_dialog_content = "Yo, Tiare, líder de la Tribu de Nieve Fox y guardián de Bethlehem, Queen del Norte, imploro la intervención divina!",
  ui_story_1021_10210801_152_dialog_content = "¡La Queen del Norte ha honrado su pacto! Su poder es tuyo, así como el poder dentro de estas ramas!",
  ui_story_1021_10210801_153_dialog_content = "¡Por favor acéptalos y nutre los Tres Pinos de Nieve con tu fuerza vivificante, para que puedan crecer una vez más!",
  ui_story_1021_10210801_154_dialog_content = "Bendice nuestras antiguas y sagradas tierras con tu protección eterna—",
  ui_story_1021_10210801_155_dialog_content = "¡Concédeme poder, Bastón de Terra!",
  ui_story_1021_10210801_156_dialog_content = "<color=#e8d9bb>Whoosh, whoosh—</color>",
  ui_story_1021_10210801_157_dialog_content = "!",
  ui_story_1021_10210801_158_dialog_content = "¡Los tres tocones... De repente crecieron y se convirtieron en un solo árbol colosal!",
  ui_story_1021_10210801_159_dialog_content = "¿Es este el poder del Primal Haven?",
  ui_story_1021_10210801_160_dialog_content = "...",
  ui_story_1021_10210801_161_dialog_content = "El poder dentro de mi lanza no fue recuperado... Si acaso, ¡parece que un poder mayor está fluyendo hacia ella!",
  ui_story_1021_10210801_162_dialog_content = "Esta cosa está parpadeando como un relámpago... ¿Es energía que proviene de dentro de los pinos de nieve?",
  ui_story_1021_10210801_163_dialog_content = "...",
  ui_story_1021_10210801_164_dialog_content = "Aquí, en la cima del mundo, nuestros ancestros descubrieron un arroyo cálido y suave.",
  ui_story_1021_10210801_165_dialog_content = "Este arroyo, como una bendición del cielo, serpenteaba por el paisaje congelado de Northland durante todo el año y se extendía hasta los confines más lejanos de Astra...",
  ui_story_1021_10210801_166_dialog_content = "Este fue el origen del Refugio Primordial. El arroyo trajo vida al Bosque de Pino de Nieve, que a su vez dio vida a nuestros ancestros más antiguos.",
  ui_story_1021_10210801_167_dialog_content = "Bajo la protección de Primal Haven, los snowpines y Wick se han unido para crear este nuevo Faro.",
  ui_story_1021_10210801_168_dialog_content = "Su luz atravesará el largo invierno y las montañas cubiertas de nieve, disipando la oscuridad e iluminando nuestras amadas tierras.",
  ui_story_1021_10210801_169_dialog_content = "Además, Tiare, has sido elegido por lo divino para servir como un verdadero guardián de Northland.",
  ui_story_1021_10210801_170_dialog_content = "Lo divino me ha elegido... ¡y me ha bendecido con poder!",
  ui_story_1021_10210801_171_dialog_content = "El poder dentro de esta lanza congelada arde como fuego. ¡Se siente como una antorcha en mi mano!",
  ui_story_1021_10210801_172_dialog_content = "Tiare, a partir de este día, debes asumir el peso tanto de la fuerza divina como del deber...",
  ui_story_1021_10210801_173_dialog_content = "Emplea tu valentía y sabiduría en defensa de toda Northland.",
  ui_story_1021_10210802_1_dialog_content = "¿Un rayo de luz proveniente del Bosque Snowpine? ¿Podría ser un conjunto de ruinas antiguas aún por descubrir?",
  ui_story_1021_10210802_2_dialog_content = "¿O quizás es algún tipo de señal?",
  ui_story_1021_10210802_3_dialog_content = "El Faro de las leyendas proporciona tanto orientación como protección para todo Northland. ¿Es posible que exista más de un faro?",
  ui_story_1021_10210802_4_dialog_content = "Si es así, ¿cómo se distribuyen?",
  ui_story_1021_10210802_5_dialog_content = "¿Y qué efecto tiene su luz sobre la tierra?",
  ui_story_1021_10210802_6_dialog_content = "<color=#e8d9bb>En un rincón oculto de la tierra</color>",
  ui_story_1021_10210802_7_dialog_content = "Entonces, después de todo, Northland realmente contiene un poder como este.",
  ui_story_1021_10210802_8_dialog_content = "El arroyo ha retomado su flujo y rápidamente llegará al mar.",
  ui_story_1021_10210802_9_dialog_content = "Creo que a Lady Victoria le agradarán mucho nuestros hallazgos.",
  ui_story_1021_10210802_10_dialog_content = "Entonces, vámonos de inmediato.",
  ui_story_1021_10210802_11_dialog_content = "<color=#e8d9bb>A bordo de una aeronave de la Federación Illumina</color>",
  ui_story_1021_10210802_12_dialog_content = "Nunca había visto una luz así antes... como el sol de la mañana saliendo detrás de las montañas nevadas.",
  ui_story_1021_10210802_13_dialog_content = "¡Establece un rumbo hacia esa luz! ¡Máxima velocidad adelante!",
  ui_story_1021_10210802_14_dialog_content = "Sí, Gran Mariscal!",
  ui_story_1021_10210901_1_dialog_content = "Parece... el nuevo Faro ya está completo.",
  ui_story_1021_10210901_2_dialog_content = "¡Su Majestad! ¿Está herido? Apenas puedo soportar verlo en un estado tan debilitado...",
  ui_story_1021_10210901_3_dialog_content = "Estoy bien, Carleen. Todo Northland está bajo una protección aún mayor ahora, al igual que yo.",
  ui_story_1021_10210901_4_dialog_content = "Graah!",
  ui_story_1021_10210901_5_dialog_content = "(Eclipsian) Mi señor... Quema...",
  ui_story_1021_10210901_6_dialog_content = "(En eclipsiano) ¡Quema!",
  ui_story_1021_10210901_7_dialog_content = "(Eclipsiano) Esta sensación... ahora recuerdo...",
  ui_story_1021_10210901_8_dialog_content = "(Eclipsiano) Una chica cabalgando a través de la nieve en el lomo de un alce...",
  ui_story_1021_10210901_9_dialog_content = "(Eclipsian) Lo recuerdo todo ahora.",
  ui_story_1021_10210901_10_dialog_content = "(Eclipsian) Parece que mis pruebas han demostrado ser valiosas.",
  ui_story_1021_10210901_11_dialog_content = "¡Todos cargados de energía!",
  ui_story_1021_10210901_12_dialog_content = "...",
  ui_story_1021_10210901_13_dialog_content = "Graah!",
  ui_story_1021_10210901_14_dialog_content = "¡Su Majestad! Carleen! ¡Lamento mucho la tardanza!",
  ui_story_1021_10210901_15_dialog_content = "¡Ese ataque de hace un momento fue increíble, Tiare!",
  ui_story_1021_10210901_16_dialog_content = "¡Parece que tanto tu lanza como tu fuerza se han vuelto mucho más fuertes!",
  ui_story_1021_10210901_17_dialog_content = "El anciano dijo que esto es prueba de que lo divino me ha reconocido. ¡Ahora soy un guardia digno de la reina!",
  ui_story_1021_10210901_18_dialog_content = "¡Y un guardián de todo Northland!",
  ui_story_1021_10210901_19_dialog_content = "¡Así es!",
  ui_story_1021_10210901_20_dialog_content = "Puedo sentir cuánto has crecido, Tiare. Bien hecho.",
  ui_story_1021_10210901_21_dialog_content = "Gracias por ayudarme a crear este nuevo Faro.",
  ui_story_1021_10210901_22_dialog_content = "¡Su Majestad! Acabo de descubrir la historia del trono en el Palacio de Invierno, aprendiendo el juramento entre la familia real y las tribus... y también...",
  ui_story_1021_10210901_23_dialog_content = "¡Tengo tanto que contarte! Pero lo que más deseo decir es esto—",
  ui_story_1021_10210901_24_dialog_content = "A partir de ahora, yo, Tiare, siempre estaré a tu lado! Nunca más tendrás que enfrentarte a ninguna batalla solo, ¡Su Majestad!",
  ui_story_1021_10210901_25_dialog_content = "\"La nieve derretida lleva agua a través de montañas y arroyos, dando vida a esta tierra bendita...\"",
  ui_story_1021_10210901_26_dialog_content = "¡Prepárate para morir, Eclipsite!",
  ui_story_1021_10210901_27_dialog_content = "¡Espera, Tiare!",
  ui_story_1021_10210901_28_dialog_content = "¿Su Majestad?",
  ui_story_1021_10210901_29_dialog_content = "¿No solo sabes sobre esa batalla, sino que también conoces la bendición de Northland? ¿Cómo?",
  ui_story_1021_10210901_30_dialog_content = "En aquel momento, un silencio mortal se apoderó de estas tierras nevadas.",
  ui_story_1021_10210901_31_dialog_content = "Un sol negro como la brea flotaba en el cielo arriba, y la llegada de nuestro dios estaba cerca...",
  ui_story_1021_10210901_32_dialog_content = "Pero entonces apareció esa chica...",
  ui_story_1021_10210901_33_dialog_content = "...",
  ui_story_1021_10210901_34_dialog_content = "¿Viste el primer Queen de Northland?",
  ui_story_1021_10210901_35_dialog_content = "Con un rayo de luz en su mano, ella destrozó la cúpula y nos separó de nuestro dios para siempre.",
  ui_story_1021_10210901_36_dialog_content = "Deseaba desesperadamente mirar al sol negro una última vez.",
  ui_story_1021_10210901_37_dialog_content = "Pero con el arma en sus manos, me golpeó ciegamente.",
  ui_story_1021_10210901_38_dialog_content = "He recordado todo después de este juicio...",
  ui_story_1021_10210901_39_dialog_content = "La última llama que mis ojos vieron no fue mi ira...",
  ui_story_1021_10210901_40_dialog_content = "¡Para empezar, nunca fue ira!",
  ui_story_1021_10210901_41_dialog_content = "¡Era un haz de luz danzante que pintó mi mundo con ira!",
  ui_story_1021_10210901_42_dialog_content = "(Eclipsiano) No temo ni al hielo ni al fuego...",
  ui_story_1021_10210901_43_dialog_content = "(Eclipsian) Pero esa luz blanca parpadeante... Solo deseo saber qué es...",
  ui_story_1021_10210901_44_dialog_content = "¡El Faro! ¡Es el Faro de la reina!",
  ui_story_1021_10210901_45_dialog_content = "¡La reina ha traído la luz del Faro para salvarnos!",
  ui_story_1021_10210901_46_dialog_content = "(Eclipsiano) El Faro...",
  ui_story_1021_10210901_47_dialog_content = "Graah!",
  ui_story_1021_10210901_48_dialog_content = "Ahora recuerdo todo.",
  ui_story_1021_10210901_49_dialog_content = "Todo...",
  ui_story_1021_10210901_50_dialog_content = "Mi juicio ha terminado ahora. Pueden irse con sus vidas intactas.",
  ui_story_1021_10210901_51_dialog_content = "...",
  ui_story_1021_10210901_52_dialog_content = "¡No pienses que te dejaré escapar!",
  ui_story_1021_10210901_53_dialog_content = "¡Te haré pagar por lo que le has hecho a los zorros y a toda nuestra tribu!",
  ui_story_1021_10210901_54_dialog_content = "Si te niegas a irte... entonces ven y encuentra tu fin.",
  ui_story_1021_10210901_55_dialog_content = "Tiare!",
  ui_story_1021_10210901_56_dialog_content = "¡Todos cargados de energía!",
  ui_story_1021_10210901_57_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1021_10210901_58_dialog_content = "*tose* M-Maldito Eclipsite... No te dejaré escapar...",
  ui_story_1021_10210901_59_dialog_content = "Tiare!",
  ui_story_1021_10210901_60_dialog_content = "¡Cuidado! ¡Está intentando arrastrarte a la Zona Oscura!",
  ui_story_1021_10210901_61_dialog_content = "Justo ahora... ¿Fue eso un disparo de cañón?",
  ui_story_1021_10210901_62_dialog_content = "Mira al cielo, PlayerName—",
  ui_story_1021_10210901_63_dialog_content = "Hemos fallado nuestro objetivo, pero parece que PlayerName y los demás están intentando entrar en el dominio de los Eclipsites.",
  ui_story_1021_10210901_64_dialog_content = "¡Baja la altitud y cúbrelos!",
  ui_story_1021_10210901_65_dialog_content = "Sí, Gran Mariscal!",
  ui_story_1021_10210901_66_dialog_content = "Están abriendo fuego, Bethel! ¿Esto significa que nosotros—",
  ui_story_1021_10210901_67_dialog_content = "Illumina y Lumopolis están proporcionando refuerzos. No te interpongas en su camino.",
  ui_story_1021_10210901_68_dialog_content = "¡Necesitamos subir a la cubierta y levantar la bandera de la expedición conjunta!",
  ui_story_1021_10210901_69_dialog_content = "Todas las fuerzas están listas para desplegarse. Podemos aterrizar en cualquier momento, señor!",
  ui_story_1021_10210901_70_dialog_content = "Extermina a cualquier Eclipsites con los que te encuentres a lo largo de la frontera y refuerza las posiciones de los soldados de Northland. Deja la batalla principal a nuestros jóvenes amigos.",
  ui_story_1021_10210901_71_dialog_content = "¡Si mi señor!",
  ui_story_1021_10210901_72_dialog_content = "Es una aeronave de Illumina...",
  ui_story_1021_10210901_73_dialog_content = "Además de un dirigible de Lumopolis... Todos están enfocados en nuestra posición actual.",
  ui_story_1021_10210901_74_dialog_content = "Pero parece que ese Eclipsite está intentando provocar a Tiare y atraernos hacia él...",
  ui_story_1021_10210901_75_dialog_content = "¡Tiare es rápida! ¡Está a punto de saltar la pared frente a nosotros!",
  ui_story_1021_10210901_76_dialog_content = "Una vez que crucemos esa pared, me temo que no habrá vuelta atrás.",
  ui_story_1021_10210901_77_dialog_content = "Aun así, la luz del Faro debería alcanzar más allá. Ven conmigo.",
  ui_story_1021_10210901_78_dialog_content = "Te ayudaré a llegar a la cima de la montaña creando un camino de hielo. ¡Debemos ayudar a Tiare a expulsar a ese Eclipsite de Northland de una vez por todas!",
  ui_story_1021_10210901_79_dialog_content = "¡Correcto!",
  ui_story_1021_10210901_80_dialog_content = "Tiare!",
  ui_story_1021_10210901_81_dialog_content = "¡No nos dejes atrás así! ¡Estamos todos juntos en esto!",
  ui_story_1021_10210901_82_dialog_content = "¡Su Majestad! ¡Mis amigos! ¿Y ustedes dos también?",
  ui_story_1021_10210901_83_dialog_content = "¡No olvides, el Rediesel también es parte de la expedición conjunta!",
  ui_story_1021_10210901_84_dialog_content = "Así es. Después de todo, ustedes son los que dijeron que deberíamos tener una ceremonia de bienvenida emocionante antes de comenzar la expedición.",
  ui_story_1021_10210901_85_dialog_content = "No recuerdo haber dicho nada sobre eso...",
  ui_story_1021_10210901_86_dialog_content = "Pero como guardia de Northland, te doy mi palabra de que no descansaré hasta que estos Eclipsites hayan sido expulsados de nuestras tierras!",
  ui_story_1021_10210901_87_dialog_content = "Sin siquiera darse cuenta, la expedición conjunta ya ha llegado hasta aquí en su viaje.",
  ui_story_1021_10210901_88_dialog_content = "Justo adelante está el territorio de los Eclipsites, ¡pero monstruos sedientos de sangre como ellos no tienen cabida en este mundo!",
  ui_story_1021_10210901_89_dialog_content = "¡Sigamos la luz del Faro y exterminémoslos sin piedad!",
  ui_story_1021_10210901_90_dialog_content = "Esas son algunas palabras poderosas que vienen de la reina...",
  ui_story_1021_10210901_91_dialog_content = "Con Tiare como mi guardia, no puedo evitar sentirme inspirado por ella.",
  ui_story_1021_10210901_92_dialog_content = "Reúne tu valor y mantén a los demás cerca de tu corazón, porque el futuro de Northland y todos los Aurorianos depende de nosotros...",
  ui_story_1021_10210901_93_dialog_content = "Actúa como el faro del otro, y tu fuerza superará cualquier terror que podamos enfrentar.",
  ui_story_1021_10210901_94_dialog_content = "!",
  ui_story_1021_10210901_95_dialog_content = "¡Oye, mira esa piedra destrozada! ¡Parece que el Eclipsite no se alejará demasiado de ella!",
  ui_story_1021_10210901_96_dialog_content = "¡Entonces lo destruiremos juntos! Conmigo, todos, marchamos hacia la Zona Oscura!",
  ui_story_1021_10210901_97_dialog_content = "¡A la carga!",
  ui_story_1021_10210902_1_dialog_content = "Interesante. Esto ha ido mucho más allá de mis expectativas...",
  ui_story_1021_10210902_2_dialog_content = "Pero para ascender a mayores alturas, debo ejercer autocontrol.",
  ui_story_1021_10210902_3_dialog_content = "Antes de irme, tengo un mensaje final para todos ustedes...",
  ui_story_1021_10210902_4_dialog_content = "Deja que el hedor de la oscuridad invada tus sentidos y entra en nuestro dominio...",
  ui_story_1021_10210902_5_dialog_content = "Los cadáveres de aquellos que vinieron antes que tú están apilados tan altos como montañas, y sus voces llamarán tus nombres dondequiera que vayas.",
  ui_story_1021_10210902_6_dialog_content = "Yo, Ira el Protector del Rey, te esperaré en la tierra de la noche eterna.",
  ui_story_1021_10210902_7_dialog_content = "Espero con ansias nuestro próximo encuentro...",
  ui_story_1021_10211001_1_dialog_content = "Los Eclipsites se han retirado de Northland y la fuente de luz del Faro se ha estabilizado una vez más.",
  ui_story_1021_10211001_2_dialog_content = "¿Nuestros aliados han llamado a sus soldados de vuelta?",
  ui_story_1021_10211001_3_dialog_content = "Sí, pero el Jefe de Personal de la Federación Illumina está esperando al Caelestite y su grupo en el Valle de la Escarcha de Pino.",
  ui_story_1021_10211001_4_dialog_content = "A pesar de que el puesto avanzado está incompleto, parece que nuestra expedición a la Zona Oscura ha comenzado oficialmente, y de una manera impresionante, ni más ni menos.",
  ui_story_1021_10211001_5_dialog_content = "Al menos, este nuevo Faro les proporcionará un refugio temporal antes de adentrarse profundamente en la Zona Oscura.",
  ui_story_1021_10211001_6_dialog_content = "¿Esto significa que se irán de aquí?",
  ui_story_1021_10211001_7_dialog_content = "Sí, por eso debemos redoblar nuestros esfuerzos para terminar la construcción del puesto avanzado.",
  ui_story_1021_10211001_8_dialog_content = "Su Majestad, los preparativos para nuestra partida están completos. Hemos venido a despedirnos.",
  ui_story_1021_10211001_9_dialog_content = "Carleen no puede esperar para volver y continuar sus lecciones de vuelo. ¿No es así?",
  ui_story_1021_10211001_10_dialog_content = "E-Eso no es... Hay muchos otros asuntos urgentes que atender...",
  ui_story_1021_10211001_11_dialog_content = "Entonces te deseo un buen viaje. Gracias una vez más por ayudarme a crear este nuevo Faro para Northland.",
  ui_story_1021_10211001_12_dialog_content = "¡No podríamos haberlo hecho sin Tiare tampoco! Hablando de eso, ¿dónde está ella?",
  ui_story_1021_10211001_13_dialog_content = "Ella también tiene otros asuntos que atender.",
  ui_story_1021_10211001_14_dialog_content = "Por favor, asegúrale a los miembros del Equipo de Expedición que el puesto avanzado se completará lo antes posible.",
  ui_story_1021_10211001_15_dialog_content = "El Señor de la Ciudad dice que enviará a los Guardianes de la Noche Blanca para ayudar en su construcción, aunque su llegada puede retrasarse dos días.",
  ui_story_1021_10211001_16_dialog_content = "¡Y conozco a dos ingenieros expertos que pueden comenzar a trabajar hoy!",
  ui_story_1021_10211001_17_dialog_content = "¡Tienes razón! Esos dos han tenido gemas en sus mentes durante mucho tiempo. Por favor, considera cualquier cosa que hayan tomado como un adelanto de su pago.",
  ui_story_1021_10211001_18_dialog_content = "Seguro que ustedes dos están emocionados de ponernos a trabajar...",
  ui_story_1021_10211001_19_dialog_content = "No tenemos ni idea de lo que pasó con esas gemas... Y si trabajamos gratis, el Jefe Sinsa no nos dejará escuchar el final de eso.",
  ui_story_1021_10211001_20_dialog_content = "Además, preferiría apoyar a todos desde el desierto de Rediesel, donde hace calor y es agradable. Northland es un lugar maravilloso y todo eso, pero preferiría no volver nunca más.",
  ui_story_1021_10211001_21_dialog_content = "¿Qué tal si nos acompañas en la expedición?",
  ui_story_1021_10211001_22_dialog_content = "Tendremos que ver. Soy un hombre muy ocupado, ¿sabes?",
  ui_story_1021_10211001_23_dialog_content = "Este día, que parecía tan inalcanzable a pesar de mi predicción, está casi a la mano.",
  ui_story_1021_10211001_24_dialog_content = "En el pasado, cada facción tenía su propia postura, y la expedición conjunta no era más que una aspiración política elevada.",
  ui_story_1021_10211001_25_dialog_content = "Pero ahora, se cuidan mutuamente como verdaderos camaradas de armas...",
  ui_story_1021_10211001_26_dialog_content = "Rezo para que su camaradería los sostenga y preserve mientras entran en la Zona Oscura.",
  ui_story_1021_10211001_27_dialog_content = "<color=#e8d9bb>Cerca del Valle Escarcha de Pino</color>",
  ui_story_1021_10211001_28_dialog_content = "PlayerName! ¡Esperar!",
  ui_story_1021_10211001_29_dialog_content = "¿Qué pasa, Tiare?",
  ui_story_1021_10211001_30_dialog_content = "¡Traje algunos regalos para todos! Pero en mi camino aquí, los dejé caer accidentalmente, junto con la persona que me estaba ayudando a entregarlos. ¡Lo siento!",
  ui_story_1021_10211001_31_dialog_content = "No puedes seguir haciendo esto, Tiare. A este ritmo, nadie será lo suficientemente valiente para quedarse contigo...",
  ui_story_1021_10211001_32_dialog_content = "¿Entonces qué planeas hacer ahora? Nos encantaría tenerte como miembro del Equipo de Expedición, ¿sabes?",
  ui_story_1021_10211001_33_dialog_content = "¡Con tu coraje y agilidad, estoy seguro de que podrías ayudarnos en cualquier situación peligrosa!",
  ui_story_1021_10211001_34_dialog_content = "Agradezco tu oferta, pero no olvides que tengo algo aún más importante que hacer ahora mismo.",
  ui_story_1021_10211001_35_dialog_content = "Después de todo lo que hemos pasado juntos, me doy cuenta de que mis deberes están lejos de terminar.",
  ui_story_1021_10211001_36_dialog_content = "Como un verdadero guardián de Northland, ¡tengo que seguir dando lo mejor de mí!",
  ui_story_1021_10211001_37_dialog_content = "¡Por eso he decidido quedarme en Northland! Continuaré la historia iniciada por mis antepasados zorros de nieve y las reinas pasadas de Northland!",
  ui_story_1021_10211001_38_dialog_content = "¡Haré que el anciano comparta cada una de las historias que mi abuela nunca me contó!",
  ui_story_1021_10211001_39_dialog_content = "¡Parece una forma significativa de honrar su legado! No olvides, ¡yo también estuve allí para ser testigo de parte de la historia!",
  ui_story_1021_10211001_40_dialog_content = "¡Si escuchas alguna historia nueva, recuerda contármela toda en una carta!",
  ui_story_1021_10211001_41_dialog_content = "¡Oh! Hay otra manera—",
  ui_story_1021_10211001_42_dialog_content = "Grr...",
  ui_story_1021_10211001_43_dialog_content = "Grr...",
  ui_story_1021_10211001_44_dialog_content = "¿Por qué ustedes dos están aullando como un montón de animales mientras arrastro todas estas cosas yo solo?",
  ui_story_1021_10211001_45_dialog_content = "Es eso...",
  ui_story_1021_10211001_46_dialog_content = "Ese es Zarya, otro amigo que hice en Northland.",
  ui_story_1021_10211001_47_dialog_content = "Así que tú eres el que estaba ayudando a Tiare a llevar sus regalos...",
  ui_story_1021_10211001_48_dialog_content = "¡Corrió más rápido que el viento! La perdí completamente de vista antes de que incluso tocara el suelo!",
  ui_story_1021_10211001_49_dialog_content = "Bueno, eso es algo bastante común cuando viajas con Tiare.",
  ui_story_1021_10211001_50_dialog_content = "¿Es así? ¿O fue porque Tiare todavía estaba enojado conmigo?",
  ui_story_1021_10211001_51_dialog_content = "¡Humph! Fue tu culpa por lanzar un montón de cristales de hielo a los niños!",
  ui_story_1021_10211001_52_dialog_content = "Eres el que olvidó decirme que ir a tu casa implicaba dejar que los zorros de nieve se turnaran para lamer mis manos...",
  ui_story_1021_10211001_53_dialog_content = "¡Eso no es una costumbre en ninguna otra parte de Northland!",
  ui_story_1021_10211001_54_dialog_content = "...",
  ui_story_1021_10211001_55_dialog_content = "¿Entonces esas cosas brillantes son tus regalos?",
  ui_story_1021_10211001_56_dialog_content = "¿Es esto mineral de Lumina?",
  ui_story_1021_10211001_57_dialog_content = "¡Lo adivinaste! Me cansé de arrastrar estos todo el camino desde la casa de Tiare!",
  ui_story_1021_10211001_58_dialog_content = "¡No puedo aceptar algo tan valioso como un regalo!",
  ui_story_1021_10211001_59_dialog_content = "¿Por qué no? Como líder de los zorros de nieve, quiero recompensaros adecuadamente por salvar a mi tribu...",
  ui_story_1021_10211001_60_dialog_content = "Este también es el deseo del anciano.",
  ui_story_1021_10211001_61_dialog_content = "La reina también dice que este mineral se puede utilizar para repeler a los Eclipsites e iluminar tu camino a través de la Zona Oscura. Los necesitarás en tu expedición.",
  ui_story_1021_10211001_62_dialog_content = "Pero su luz también está impidiendo que los Eclipsites crucen las fronteras de Northland...",
  ui_story_1021_10211001_63_dialog_content = "¡Este es un regalo de nuestra tribu! ¡Tómalo ahora antes de que me arrepienta!",
  ui_story_1021_10211001_64_dialog_content = "¡Ah... Y-Yo acepto!",
  ui_story_1021_10211001_65_dialog_content = "(Comienzo a extrañar cuando ella era solo la guardia de la reina...)",
  ui_story_1021_10211001_66_dialog_content = "...",
  ui_story_1021_10211001_67_dialog_content = "Parece que ahora estás en paz dejando que Tiare haga lo que quiera.",
  ui_story_1021_10211001_68_dialog_content = "Incluso si no es como mi guardia real, estoy seguro de que ella encontrará su lugar en Northland muy pronto.",
  ui_story_1021_10211001_69_dialog_content = "Sin embargo, siempre serás su faro. Desde aquella avalancha, siempre ha sido así.",
  ui_story_1021_10211001_70_dialog_content = "<color=#e8d9bb>El día que la tribu fue aniquilada...</color>",
  ui_story_1021_10211001_71_dialog_content = "¿Te resulta difícil servir como guardia de la reina?",
  ui_story_1021_10211001_72_dialog_content = "Su Majestad es inimaginablemente poderosa... Siempre que hay peligro, la reina siempre viene al rescate. Como resultado, mi trabajo rara vez es difícil.",
  ui_story_1021_10211001_73_dialog_content = "Ella siempre me salva del peligro, una y otra vez...",
  ui_story_1021_10211001_74_dialog_content = "La tribu Snow Fox siempre paga sus deudas, por eso juré protegerla después de que me rescató de esa avalancha.",
  ui_story_1021_10211001_75_dialog_content = "¿Realmente crees que la entiendes?",
  ui_story_1021_10211001_76_dialog_content = "¡Por supuesto! Cuando Su Majestad estaba patrullando nuestras tierras, la seguí de cerca sin que ella lo supiera...",
  ui_story_1021_10211001_77_dialog_content = "Sus movimientos, su aroma, incluso la forma en que respira, los conozco muy bien.",
  ui_story_1021_10211001_78_dialog_content = "Puedo sentir el rechazo de la tribu hacia los forasteros, pero la reina es diferente...",
  ui_story_1021_10211001_79_dialog_content = "Cuando ella me mira, me recuerda a un pariente lejano que solo visita una vez al año...",
  ui_story_1021_10211001_80_dialog_content = "Cuando ella aparece, irradia una cierta luz sobre la tribu y también sobre mi mundo...",
  ui_story_1021_10211001_81_dialog_content = "Entonces parece que sabes lo que debe hacerse, Tiare. La respuesta siempre ha estado en tu corazón.",
  ui_story_1021_10211001_82_dialog_content = "La persona que llena tu mundo de luz es un faro para tu vida.",
  ui_story_1021_10211001_83_dialog_content = "May sigues la luz de tu faro y te bañas en su cálido resplandor.",
  ui_story_1021_10211001_84_dialog_content = "Cuando finalmente seas capaz de iluminar tu propio camino, estoy seguro de que tu luz servirá como un faro para nuestra tribu.",
  ui_story_1021_10211001_85_dialog_content = "...",
  ui_story_1021_10211001_86_dialog_content = "¿No le vas a decir la verdad sobre la avalancha?",
  ui_story_1021_10211001_87_dialog_content = "Decírselo no haría ninguna diferencia en este punto.",
  ui_story_1021_10211001_88_dialog_content = "...",
  ui_story_1021_10211001_89_dialog_content = "Aun así, creo que tú también eres un faro para ella.",
  ui_story_1021_10211001_90_dialog_content = "<color=#e8d9bb>Hace algunos años...</color>",
  ui_story_1021_10211001_91_dialog_content = "<color=#e8d9bb>Crujido, crujido, crujido-</color>",
  ui_story_1021_10211001_92_dialog_content = "?",
  ui_story_1021_10211001_93_dialog_content = "(En lo que pareció un abrir y cerrar de ojos, la pequeña niña que una vez me lanzó bolas de nieve ha crecido...)",
  ui_story_1021_10211001_94_dialog_content = "(Vivir completamente solo en el Bosque de Snowpine debe haberse sentido tan solitario a veces.)",
  ui_story_1021_10211001_95_dialog_content = "<color=#e8d9bb>Susurro, susurro—</color>",
  ui_story_1021_10211001_96_dialog_content = "...",
  ui_story_1021_10211001_97_dialog_content = "...",
  ui_story_1021_10211001_98_dialog_content = "(Y aún así, sigue siendo una niña tan impaciente...)",
  ui_story_1021_10211001_99_dialog_content = "(Ella siempre me ha seguido desde la distancia, pero hoy elige revelarse ante mí...)",
  ui_story_1021_10211001_100_dialog_content = "...",
  ui_story_1021_10211001_101_dialog_content = "Cada año, alrededor de la misma época, apareces en estas tierras.",
  ui_story_1021_10211001_102_dialog_content = "...",
  ui_story_1021_10211001_103_dialog_content = "Pero aún no has cumplido tu promesa de traernos la luz del Faro.",
  ui_story_1021_10211001_104_dialog_content = "...",
  ui_story_1021_10211001_105_dialog_content = "Gracias a todos. Sin ustedes, Northland no sería tan pacífico como lo es hoy.",
  ui_story_1021_10211001_106_dialog_content = "Aunque nuestros ancestros eligieron quedarse aquí y perecieron en la guerra...",
  ui_story_1021_10211001_107_dialog_content = "La decisión de seguir protegiendo este lugar es nuestra.",
  ui_story_1021_10211001_108_dialog_content = "...",
  ui_story_1021_10211001_109_dialog_content = "Toma Tiare y vete.",
  ui_story_1021_10211001_110_dialog_content = "?",
  ui_story_1021_10211001_111_dialog_content = "Mis días están contados. Cuando ella sea mayor, aprenderá el precio de la protección y el peso de su responsabilidad.",
  ui_story_1021_10211001_112_dialog_content = "No deseo que ella pase su vida protegiendo obstinadamente el Bosque de Snowpine en soledad, como lo hizo su abuela en su momento.",
  ui_story_1021_10211001_113_dialog_content = "Tiare... es un niño voluntarioso.",
  ui_story_1021_10211001_114_dialog_content = "Pero soy muy consciente de la curiosidad y la esperanza que ella siente hacia ti.",
  ui_story_1021_10211001_115_dialog_content = "...",
  ui_story_1021_10211001_116_dialog_content = "<color=#e8d9bb>El anciano salta de vuelta al bosque, y una enorme bola de nieve rueda hacia Tiare...</color>",
  ui_story_1021_10211001_117_dialog_content = "¡Ahhh!",
  ui_story_1021_10211001_118_dialog_content = "Esto termina cuando el hielo se descongela—",
  ui_story_1021_10211001_119_dialog_content = "Me salvaste...",
  ui_story_1021_10211001_120_dialog_content = "Y no solo eso...",
  ui_story_1021_10211001_121_dialog_content = "Tu lanza debería ser mucho más duradera ahora.",
  ui_story_1021_10211001_122_dialog_content = "¡Está brillando con una luz tan brillante!",
  ui_story_1021_10211001_123_dialog_content = "Justo como ese faro...",
  ui_story_1021_10211001_124_dialog_content = "Espera...",
  ui_story_1021_10211001_125_dialog_content = "...",
  ui_story_1021_10211001_126_dialog_content = "M-Mi nombre es Tiare!",
  ui_story_1021_10211001_127_dialog_content = "...",
  ui_story_1021_10211001_128_dialog_content = "¡Y desde este día en adelante, no importa a dónde vayas, siempre estaré allí para protegerte! La tribu Fox de la Nieve siempre paga sus deudas!",
  ui_story_1021_10211001_129_dialog_content = "...",
  ui_story_1021_10211001_130_dialog_content = "Gracias por todo lo que haces por Northland.",
  ui_story_1021_10211001_131_dialog_content = "Aunque mi juramento pesa mucho sobre mí, lo llevo con orgullo en cada paso que doy...",
  ui_story_1021_10211001_132_dialog_content = "Les prometo a todos que la luz del Faro de Northland llegará a este lugar...",
  ui_story_1021_10211001_133_dialog_content = "Algún día iluminará tierras aún más lejanas.",
  ui_story_1022_10220100_1_dialog_content = "(¿Qué... dónde estoy?)",
  ui_story_1022_10220100_2_dialog_content = "<color=#e8d9bb>El mundo circundante es frío y completamente carente de luz, lo que hace imposible discernir las direcciones.</color>",
  ui_story_1022_10220100_3_dialog_content = "(¿Por qué estoy en un lugar como este?)",
  ui_story_1022_10220100_4_dialog_content = "(Está poniéndose más frío... No puedo simplemente quedarme aquí, ¡tengo que seguir moviéndome!)",
  ui_story_1022_10220100_5_dialog_content = "(Pero, ¿a dónde debería ir? Está demasiado oscuro para ver algo... ¿Eh? ¿Qué es eso?)",
  ui_story_1022_10220100_6_dialog_content = "<color=#e8d9bb>Un pequeño punto de luz, muy lejos en la distancia, rompe la aplastante oscuridad.</color>",
  ui_story_1022_10220100_7_dialog_content = "<color=#e8d9bb>Sin desanimarse por la noche fría y opresiva, la luz se vuelve cada vez más brillante, hasta que su calidez y brillantez iluminan todo a su alrededor.</color>",
  ui_story_1022_10220100_8_dialog_content = "<color=#e8d9bb>Como el sol brillando a través de una noche eterna.</color>",
  ui_story_1022_10220100_9_dialog_content = "(Una fuente masiva de Lumina... Es tan pura, y siento como si me estuviera observando... O incluso guiándome.)",
  ui_story_1022_10220100_10_dialog_content = "... eventualmente lo olvidarás. El tiempo cura todo, y si alguien más especial entra en tu vida, seguirás adelante.",
  ui_story_1022_10220100_11_dialog_content = "¿Quién está ahí? ¿Estás hablando conmigo?",
  ui_story_1022_10220100_12_dialog_content = "E-Es tan frío... Mi cuerpo entero se está congelando...",
  ui_story_1022_10220100_13_dialog_content = "... Coger un resfriado, ¡miau!",
  ui_story_1022_10220100_14_dialog_content = "Hace frío... Tan frío...",
  ui_story_1022_10220100_15_dialog_content = "Eso es porque pateaste la manta. ¡Tampoco puedo ponértela encima, ya que te has enrollado sobre ella!",
  ui_story_1022_10220100_16_dialog_content = "Entonces si no quieres resfriarte, levántate ya.",
  ui_story_1022_10220100_17_dialog_content = "¿Eh? ¿Estaba durmiendo justo ahora? Entonces todo fue un sueño...",
  ui_story_1022_10220100_18_dialog_content = "¡Hacía mucho frío también! Gracias por despertarme, Philyshy.",
  ui_story_1022_10220100_19_dialog_content = "¡No lo menciones! Y ya que tu lugar está libre ahora, es mi turno para una pequeña siesta...",
  ui_story_1022_10220100_20_dialog_content = "¿Eh? H-Hey, espera un segundo! ¡No te duermas así como así!",
  ui_story_1022_10220100_21_dialog_content = "¿Cuál es la situación? ¿Dónde estamos ahora?",
  ui_story_1022_10220100_22_dialog_content = "Mira por la ventana y compruébalo tú mismo, miau.",
  ui_story_1022_10220100_23_dialog_content = "¿Qué hay afuera... Ah!",
  ui_story_1022_10220100_24_dialog_content = "<color=#e8d9bb>Fuera de la aeronave, una oscuridad espesa y densa fluye a través de la tierra, extendiéndose infinitamente hacia la distancia.</color>",
  ui_story_1022_10220100_25_dialog_content = "<color=#e8d9bb>Justo como en la pesadilla.</color>",
  ui_story_1022_10220100_26_dialog_content = "La Zona Oscura... ¿Ya estamos en la Zona Oscura?",
  ui_story_1022_10220100_27_dialog_content = "¡Sí! Iba a decírtelo, pero te vi acurrucado temblando, miau.",
  ui_story_1022_10220100_28_dialog_content = "A-¡Ejem!",
  ui_story_1022_10220100_29_dialog_content = "(Me pregunto si la Zona Oscura podría haber influido en el sueño que acabo de tener.)",
  ui_story_1022_10220100_30_dialog_content = "(Y esa bola de Lumina... ¿También existe en el mundo real...?)",
  ui_story_1022_10220100_31_option_content = "Alcance Telepático",
  ui_story_1022_10220100_32_dialog_content = "¡...!",
  ui_story_1022_10220100_33_dialog_content = "(¡Sí existe! Pero... ¿Qué podría ser?)",
  ui_story_1022_10220100_34_dialog_content = "De todos modos, la situación sí empeoró un poco...",
  ui_story_1022_10220100_35_dialog_content = "Pude seguir el rastro de dos conjuntos diferentes de coordenadas.",
  ui_story_1022_10220100_36_dialog_content = "El primer conjunto pertenece al equipo de exploración de élite de Lumina. El otro conjunto pertenece al Oficial Charon y Vice.",
  ui_story_1022_10220100_37_dialog_content = "¿Qué le pasó a Vice?!",
  ui_story_1022_10220100_38_dialog_content = "Cálmate un poco... aunque supongo que no puedo culparte por preocuparte. Definitivamente algo no está bien con sus coordenadas.",
  ui_story_1022_10220100_39_dialog_content = "La señal del equipo de exploración ha ido debilitándose con el tiempo. Es posible que la Zona Oscura esté teniendo algún tipo de efecto negativo en nuestros dispositivos de comunicación.",
  ui_story_1022_10220100_40_dialog_content = "Pero, ¿no se supone que nuestros comunicadores deberían funcionar dentro de la Zona Oscura?",
  ui_story_1022_10220100_41_dialog_content = "Es cierto, pero hay otras cosas en las que pensar. La geografía, el clima, la distancia y la densidad de Darkflow pueden afectar seriamente la efectividad de nuestros comunicadores.",
  ui_story_1022_10220100_42_dialog_content = "Veo... E-Entonces, ¿qué pasa con Vice y Charon?",
  ui_story_1022_10220100_43_dialog_content = "Sus coordenadas... siguen saltando por todos lados.",
  ui_story_1022_10220100_44_dialog_content = "¿Saltando?",
  ui_story_1022_10220100_45_dialog_content = "¡Sí! Están constantemente en movimiento como un punto láser, un momento aquí y al siguiente allí. Me estoy mareando; solo estoy tratando de seguir el ritmo. ¡Miau!",
  ui_story_1022_10220100_46_dialog_content = "Hasta donde yo sé, el Other End de Charon no es capaz de ese tipo de movimiento...",
  ui_story_1022_10220100_47_dialog_content = "Pero tampoco parece que su comunicador esté roto. Es extraño, ¿verdad?",
  ui_story_1022_10220100_48_dialog_content = "Quizás sea otro efecto de la Zona Oscura... ¿Todavía no podemos contactarlos?",
  ui_story_1022_10220100_49_dialog_content = "El Comandante Hiiro lo intentó, pero aún nada... Ni siquiera sé a dónde se han ido esta vez.",
  ui_story_1022_10220100_50_dialog_content = "¡¿Cómo está pasando esto, miau?! He revisado cada uno de los informes de inteligencia sobre este lugar, ¡pero aún no tengo una respuesta! ¡Supongo que realmente tengo que arremangarme para esto!",
  ui_story_1022_10220100_51_dialog_content = "¿No crees que ellos... se encontraron con un Fantasma, verdad...?",
  ui_story_1022_10220100_52_dialog_content = "¡¿Maullar?!",
  ui_story_1022_10220100_53_dialog_content = "Todavía no sabemos nada sobre sus poderes, ¿verdad? ¡Incluso podrían ser capaces de algo tan loco como la teleportación!",
  ui_story_1022_10220100_54_dialog_content = "Estoy seguro de que a los Espectros también les interesaría mucho la habilidad de Vice para pilotar un Colossus como Punta de lanza...",
  ui_story_1022_10220100_55_dialog_content = "¿Y si uno de ellos logra tomarla como rehén y causar estragos en todo el mundo?!",
  ui_story_1022_10220100_56_dialog_content = "¡¡¡Miau!!! E-E-Eso sería...",
  ui_story_1022_10220100_57_dialog_content = "Eso sería prácticamente imposible, dado que Charon y Other End están con ella ahora mismo.",
  ui_story_1022_10220100_58_dialog_content = "¡Comandante Hiiro!",
  ui_story_1022_10220100_59_dialog_content = "Hiiro... ¿Estás seguro de que es imposible? Incluso si solo hay una pequeña posibilidad, ¿y si—",
  ui_story_1022_10220100_60_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_1022_10220100_61_dialog_content = "Ay—",
  ui_story_1022_10220100_62_dialog_content = "(E-Ella acaba de golpear mi cabeza muy fuerte...)",
  ui_story_1022_10220100_63_dialog_content = "Es imposible descartar completamente una posibilidad, lo que lo hace igualmente inútil preocuparse por ello.",
  ui_story_1022_10220100_64_dialog_content = "Antes de embarcarnos en esta expedición, dijiste que te prepararías y evitarías sacar conclusiones precipitadas. ¿Ya te olvidaste de eso?",
  ui_story_1022_10220100_65_dialog_content = "No-No lo he hecho, pero no puedo evitarlo cuando escucho que Vice se ve envuelto en una situación extraña...",
  ui_story_1022_10220100_66_dialog_content = "(Uf, mi cabeza... ¡Hiiro me golpeó fuerte!)",
  ui_story_1022_10220100_67_dialog_content = "Entiendo, pero la Zona Oscura está llena de peligros inimaginables. Necesitas mantenerte enfocado.",
  ui_story_1022_10220100_68_dialog_content = "Espero que Vice también tenga esto en cuenta. Al igual que tú, ella es la primera en preocuparse por los demás tan pronto como las cosas se ponen peligrosas.",
  ui_story_1022_10220100_69_dialog_content = "Todavía necesita más entrenamiento como soldado.",
  ui_story_1022_10220100_70_dialog_content = "Hiiro... Realmente estás preocupado por Vice también, ¿no es así?",
  ui_story_1022_10220100_71_dialog_content = "¿No es obvio?",
  ui_story_1022_10220100_72_dialog_content = "Vice, oficial Charon, e incluso el oficial técnico Gronru... No nos faltan gatitos traviesos en nuestras filas, ¿eh?",
  ui_story_1022_10220100_73_dialog_content = "¿Gronru? ¿Qué le pasó a ella?",
  ui_story_1022_10220100_74_dialog_content = "... Desde que Punta de lanza reapareció, Gronru se ha estado sumergiendo en un trabajo de reparación interminable. Ni siquiera ha tocado un videojuego en todo este tiempo.",
  ui_story_1022_10220100_75_dialog_content = "Como la persona que una vez fue responsable de los experimentos de Punta de lanza, probablemente se sienta culpable hacia Vice y el Gran Mariscal...",
  ui_story_1022_10220100_76_dialog_content = "No tenemos tiempo para preocuparnos por los sentimientos de otras personas en este momento. Nuestra situación ya es lo suficientemente peligrosa como está.",
  ui_story_1022_10220100_77_dialog_content = "Nuestro dirigible fue diseñado para volar en conjunto con los otros dos, para que pudiéramos protegernos mutuamente.",
  ui_story_1022_10220100_78_dialog_content = "Pero ahora que sus coordenadas se han vuelto inciertas, necesitamos hacer algunos ajustes de emergencia a nuestra operación.",
  ui_story_1022_10220100_79_dialog_content = "Por preocupados que estemos por Charon y Vice, estoy seguro de que todos estamos de acuerdo en que reagruparnos con ellos no es una opción en este momento, ¿verdad?",
  ui_story_1022_10220100_80_dialog_content = "(Ella tiene razón. Incluso si logramos alcanzar su posición, hay una buena posibilidad de que se teletransporten a otro lugar nuevamente... ¡Maldita sea!)",
  ui_story_1022_10220100_81_dialog_content = "Debido a la interferencia de la Zona Oscura, tampoco hemos recibido una señal del equipo de exploración en mucho tiempo.",
  ui_story_1022_10220100_82_dialog_content = "En este punto, solo estamos perdiendo el tiempo a tientas en la oscuridad. No lograremos nada si esto continúa.",
  ui_story_1022_10220100_83_dialog_content = "... Hay una bola de Lumina allá afuera.",
  ui_story_1022_10220100_84_dialog_content = "¿Qué?",
  ui_story_1022_10220100_85_dialog_content = "Yo... Yo sentí una gran concentración de Lumina en algún lugar profundo de la Zona Oscura. Realmente no puedo describirlo, pero podría estar cerca de la frontera de la noche eterna.",
  ui_story_1022_10220100_86_dialog_content = "... ¡No puedo creer que haya tal cosa, miau!",
  ui_story_1022_10220100_87_dialog_content = "Es difícil creer que Lumina podría estar en la Zona Oscura. Pero si los otros equipos notan algo fuera de lo común, probablemente lo investigarán.",
  ui_story_1022_10220100_88_dialog_content = "Podría servir como un punto de reunión improvisado para todos nosotros...",
  ui_story_1022_10220100_89_dialog_content = "¡Comandante Hiiro! ¡Solicitud entrante de nuestra base trasera!",
  ui_story_1022_10220100_90_dialog_content = "Envíalo a través.",
  ui_story_1022_10220100_91_dialog_content = "¡Entendido!",
  ui_story_1022_10220100_92_dialog_content = "... Probando, probando. ¿Alguien me escucha?",
  ui_story_1022_10220100_93_dialog_content = "Reinhardt! ¡Gracias a Dios que todavía podemos contactarte!",
  ui_story_1022_10220100_94_dialog_content = "Te escuchamos alto y claro, Gran Mariscal. Parece que algunos de nuestros canales de comunicación aún están intactos.",
  ui_story_1022_10220100_95_dialog_content = "Eso no hace que la Zona Oscura sea menos problemática. ¿Todavía no hay señales del equipo de exploración o sus coordenadas, eh?",
  ui_story_1022_10220100_96_dialog_content = "Realmente tienes un gran trabajo por delante esta vez, Hiiro. Aguanta ahí.",
  ui_story_1022_10220100_97_dialog_content = "Por supuesto. Mi subordinada aún está en algún lugar, y es mi deber traerla a casa de manera segura.",
  ui_story_1022_10220100_98_dialog_content = "Y con el ejército de Lumopolis estableciendo un campamento base en el suelo, no tenemos que preocuparnos por cubrir nuestra retaguardia.",
  ui_story_1022_10220100_99_dialog_content = "¿Y tú, Gran Mariscal? ¿Cómo avanzan las cosas con el Comité? ¿Te lo están dificultando?",
  ui_story_1022_10220100_100_dialog_content = "Humph, si no me dieran ningún problema, empezaría a preguntarme si estaba en el camino correcto.",
  ui_story_1022_10220100_101_dialog_content = "En cualquier caso, las cosas avanzan sin problemas por mi parte. Con el paso del tiempo, parece que el Comité es una serpiente que se come la cola.",
  ui_story_1022_10220100_102_dialog_content = "No entiendo muy bien tus palabras.",
  ui_story_1022_10220100_103_dialog_content = "No importa si es Belisaria o los otros actores sin nombre en el espectáculo... ¡incluso podemos contar con Ulysses!",
  ui_story_1022_10220100_104_dialog_content = "No desean nada más que utilizar la ciencia y la tecnología para garantizar la supervivencia de todos los aurorianos.",
  ui_story_1022_10220100_105_dialog_content = "Eso es innegable, sí.",
  ui_story_1022_10220100_106_dialog_content = "Pero la ciencia y la tecnología también pueden ser despiadadas, y la proximidad del Comité a esos aspectos más crueles ha tenido un profundo efecto en ellos.",
  ui_story_1022_10220100_107_dialog_content = "Pero hay un lado frío y duro en la tecnología. El comité está más cerca de él y ha sido el más afectado.",
  ui_story_1022_10220100_108_dialog_content = "A cambio de racionalidad, eficiencia y practicidad, han abandonado su compasión por sus compañeros Aurorianos... Y al hacerlo, se oponen a su objetivo original—",
  ui_story_1022_10220100_109_dialog_content = "Para crear un mundo donde los Aurorianos puedan vivir vidas felices y pacíficas.",
  ui_story_1022_10220100_110_dialog_content = "(Incluso Ulysses solo quería mejorar a los Aurorianos para ayudarles a luchar contra los Eclipsites...)",
  ui_story_1022_10220100_111_dialog_content = "... Si persiguen ciegamente la eficiencia a expensas de su humanidad, ¿qué los hace diferentes de los Eclipsites siguiendo las órdenes de un Fantasma?",
  ui_story_1022_10220100_112_dialog_content = "Precisamente, por eso la última generación de líderes quiere encontrar otra forma de avanzar, como Yingel y Sean.",
  ui_story_1022_10220100_113_dialog_content = "No quiero quedarme atrás, tendré que lograr algunos éxitos sin precedentes más, justo como ellos.",
  ui_story_1022_10220100_114_dialog_content = "¿No crees que ya has hecho suficientes de esos...?",
  ui_story_1022_10220100_115_dialog_content = "¡Jajaja! Haces que suene como algo tan malo!",
  ui_story_1022_10220100_116_dialog_content = "... Pero la verdad es que todavía tengo mucho por lograr como el Gran Mariscal de Illumina. Ignoré todo tipo de amenazas ocultas en el pasado debido a la guerra.",
  ui_story_1022_10220100_117_dialog_content = "Por eso, tuve que llegar a un acuerdo con el Comité, al igual que mi predecesor, mientras ellos tomaban el control del rumbo de la Federación hacia el futuro.",
  ui_story_1022_10220100_118_dialog_content = "¡He oído suficiente, Gran Mariscal! Todos sabemos que no eres ese tipo de persona, y—",
  ui_story_1022_10220100_119_dialog_content = "Relájate, Hiiro. Solo estoy exponiendo los hechos para poder establecer nuevas metas para mí mismo.",
  ui_story_1022_10220100_120_dialog_content = "No soy el mismo que solía ser. La revolución que imaginamos en aquel entonces se va a convertir en realidad, y seré yo quien la haga realidad.",
  ui_story_1022_10220100_121_dialog_content = "El Comité puede seguir teniendo sus propósitos, pero me niego a dejar que desvíen el poder de Illumina por el camino equivocado.",
  ui_story_1022_10220100_122_dialog_content = "Expondré las caras ocultas detrás de sus máscaras de hierro y veré si aún queda algo de humanidad en ellos.",
  ui_story_1022_10220100_123_dialog_content = "No puedo decir mucho más ahora, pero prometo que explicaré todo pronto. Solo dame un poco más de tiempo, todos.",
  ui_story_1022_10220100_124_dialog_content = "<color=#e8d9bb>Mientras tanto, en una reunión del Comité Illumina—</color>",
  ui_story_1022_10220100_125_dialog_content = "Reinhardt hizo un regreso después de su derrota, los experimentos de Ulysses fueron expuestos para que el mundo los viera...",
  ui_story_1022_10220100_126_dialog_content = "Y ahora temo que las armas preparadas para Azurite sufran un destino similar.",
  ui_story_1022_10220100_127_dialog_content = "Parece que cada plan que eliges apoyar finalmente se vuelve en tu contra.",
  ui_story_1022_10220100_128_dialog_content = "Así que dinos, Belisaria, ¿cómo piensas asumir la responsabilidad de esto?",
  ui_story_1022_10220100_129_dialog_content = "¡La reputación del Comité se arruinará por completo si seguimos encubriendo estos vergonzosos fracasos!",
  ui_story_1022_10220100_130_dialog_content = "Entonces, ¿por qué molestarse en ocultarlos, especialmente en un momento como este?",
  ui_story_1022_10220100_131_dialog_content = "Si te importa tanto salvar la cara, entonces también podrías pedirme que renuncie ahora mismo.",
  ui_story_1022_10220100_132_dialog_content = "... ¿Y tienes algún problema con eso?",
  ui_story_1022_10220100_133_dialog_content = "No se trata de mí. Todo lo que importa es si la situación lo exige o no.",
  ui_story_1022_10220100_134_dialog_content = "Estoy preparado para renunciar en cualquier momento, si es necesario, para proteger la reputación del Comité.",
  ui_story_1022_10220100_135_dialog_content = "Esa es mi razón para estar aquí.",
  ui_story_1022_10220100_136_dialog_content = "... Humph.",
  ui_story_1022_10220100_137_dialog_content = "Pero antes de que tomes cualquier medida, te pido que tomes en cuenta a Reinhardt, así como su poder y atractivo.",
  ui_story_1022_10220100_138_dialog_content = "¿Has considerado la moral de los soldados que sirven bajo el Gran Mariscal? ¿Cómo ven al Comité?",
  ui_story_1022_10220100_139_dialog_content = "...",
  ui_story_1022_10220100_140_dialog_content = "La única razón por la que hemos llegado tan lejos es porque Illumina decidió dividir su poder de gobierno entre el Comité y el ejército.",
  ui_story_1022_10220100_141_dialog_content = "El actual esplendor de Illumina puede atribuirse al sistema de equilibrio de poder entre ambos lados. Años de tensión y luchas de poder nos han llevado a este punto exacto en la historia.",
  ui_story_1022_10220100_142_dialog_content = "Pero cuando el conflicto estalla inevitablemente, la competencia del Gran Mariscal determina la precariedad de nuestra situación.",
  ui_story_1022_10220100_143_dialog_content = "En el pasado, me vi obligado a subir al escenario y negociar con los militares. Pero dadas nuestras actuales discrepancias con ellos, podría elegir irme fácilmente.",
  ui_story_1022_10220100_144_dialog_content = "¿Pero qué pasa después de eso?",
  ui_story_1022_10220100_145_dialog_content = "¿Cuál de ustedes tomaría mi lugar? ¿Alguno de ustedes es incluso capaz de asumir mi papel?",
  ui_story_1022_10220100_146_dialog_content = "<color=#e8d9bb>Un largo silencio llena el salón de reuniones.</color>",
  ui_story_1022_10220100_147_dialog_content = "Todavía queda un asunto sin terminar, así que por favor tómate un tiempo para pensar en lo que he dicho.",
  ui_story_1022_10220100_148_dialog_content = "En ausencia de razón, ¿qué tipo de futuro creará el poder sin restricciones?",
  ui_story_1022_10220100_149_dialog_content = "Pero es muy posible que iniciemos una guerra real si intervenimos de nuevo.",
  ui_story_1022_10220100_150_dialog_content = "El propósito del Comité siempre ha sido imponer restricciones. ¿Por qué deberíamos temer al conflicto ahora, de todos los tiempos?",
  ui_story_1022_10220100_151_dialog_content = "¿Pero cómo promovería la lucha interna sin sentido alguno de nuestros planes?",
  ui_story_1022_10220100_152_dialog_content = "Por el momento, debemos ceder el control de Illumina a <color=#FFB400>ella</color>. Deberíamos haberlo hecho antes, pero nuestra incertidumbre hacia <color=#FFB400>ella</color> nos detuvo.",
  ui_story_1022_10220100_153_dialog_content = "Dejen sus disputas. Debemos actuar como uno solo si queremos resistir esta tormenta.",
  ui_story_1022_10220100_154_dialog_content = "¿Como uno? ¿Cuando cada persona en Illumina nos ve como nada más que una molestia? Jeje, no se necesita ser un genio para saber lo que la gente piensa del Comité: un vestigio obstinado y entrometido del pasado.",
  ui_story_1022_10220100_155_dialog_content = "¿Has tomado tu decisión?",
  ui_story_1022_10220100_156_dialog_content = "Parece que es hora de que <color=#FFB400>nosotros</color> hagamos acto de presencia.",
  ui_story_1022_10220100_157_dialog_content = "¡...!",
  ui_story_1022_10220100_158_dialog_content = "Illumina nació de la división, pero eso no significa que deba morir por ello.",
  ui_story_1022_10220100_159_dialog_content = "No importa quién esté en el poder en cualquier momento dado. Lo único que importa es que no repitamos nuestros errores.",
  ui_story_1022_10220100_160_dialog_content = "Illumina nunca sufrirá traidores nunca más.",
  ui_story_1022_10220201_1_dialog_content = "<color=#e8d9bb>En lo profundo de la Zona Oscura...</color>",
  ui_story_1022_10220201_2_dialog_content = "No es bueno, capitán. Todavía no podemos establecer contacto con los demás.",
  ui_story_1022_10220201_3_dialog_content = "¿Significa esto que nunca los volveremos a ver...?",
  ui_story_1022_10220201_4_dialog_content = "Está bien si no podemos contactarlos. Eso simplemente significa que somos libres de hacer lo que queramos.",
  ui_story_1022_10220201_5_dialog_content = "Tener comunicación con ellos no es diferente a estar con una correa. Solo hará que nuestro trabajo sea mucho más difícil.",
  ui_story_1022_10220201_6_dialog_content = "¡C-Capitán! ¿Estás seguro de que deberías decir eso tan alto...?",
  ui_story_1022_10220201_7_dialog_content = "¿Quién crees que nos va a escuchar? ¿Esa roca de allí? ¿O tal vez ese gigantesco pedazo de hielo?",
  ui_story_1022_10220201_8_dialog_content = "... ¡Ejem!",
  ui_story_1022_10220201_9_dialog_content = "¡Capitán! Yo... Creo que acabo de escuchar un sonido de tos ahorita...",
  ui_story_1022_10220201_10_option_content = "¿Qué tenía eso de tan raro?!",
  ui_story_1022_10220201_11_dialog_content = "Tiene razón, ¿sabes? Fue una tos perfectamente normal.",
  ui_story_1022_10220201_12_option_content = "No, definitivamente lo escuchaste.",
  ui_story_1022_10220201_13_dialog_content = "Tiene razón, ¿sabes? Una tos deliberada como esa solo puede significar que alguien está tratando de llamar nuestra atención.",
  ui_story_1022_10220201_14_dialog_content = "¡Ahora, identifícate! ¿Estás con las fuerzas principales?",
  ui_story_1022_10220201_15_dialog_content = "Aplaudo tu compostura a pesar de tu situación actual, capitán Pepita.",
  ui_story_1022_10220201_16_dialog_content = "Por esa razón, estoy dispuesto a pasar por alto tus palabras esta vez. Solo no dejes que vuelva a suceder.",
  ui_story_1022_10220201_17_dialog_content = "C-C-Comandante Hiiro de la 3ra Legión!",
  ui_story_1022_10220201_18_dialog_content = "¡Ahh, está tan oscuro y tranquilo aquí! Qué lugar perfecto para una siesta.",
  ui_story_1022_10220201_19_dialog_content = "¿¡Y también el Jefe de Intel?!",
  ui_story_1022_10220201_20_dialog_content = "¡Yo... Yo voy a preparar té para todos!",
  ui_story_1022_10220201_21_dialog_content = "¡Aquí no hay té! ¿Ves lo que hicieron, chicos? ¡Mi equipo está aterrado por culpa de ustedes!",
  ui_story_1022_10220201_22_dialog_content = "...",
  ui_story_1022_10220201_23_dialog_content = "¿Y cuál es el problema contigo, chico tosiendo? ¿Por qué te escondes allá atrás? ¿Asustado de que tu rango no pueda competir con el de ellos?",
  ui_story_1022_10220201_24_dialog_content = "N-No soy un soldado, solo soy un Caelestite...",
  ui_story_1022_10220201_25_dialog_content = "¡Eso es aún peor! ¿Qué haces siguiéndolos cuando ni siquiera tienes órdenes de hacerlo?!",
  ui_story_1022_10220201_26_dialog_content = "Eso no es cierto. Resulta que estamos trabajando juntos por un objetivo común—",
  ui_story_1022_10220201_27_dialog_content = "¿Y cuál sería ese objetivo? ¿Hacerte su pequeño perrito faldero?",
  ui_story_1022_10220201_28_dialog_content = "¿¡P-Por qué, tú...!",
  ui_story_1022_10220201_29_dialog_content = "... Suficiente, ustedes dos. Ya fue bastante difícil para nuestros equipos reagruparse, ahora simplemente intercambiemos información y planifiquemos nuestro próximo movimiento.",
  ui_story_1022_10220201_30_dialog_content = "Hmm... ¿Así que ustedes se dirigían hacia alguna gigantesca bola de Lumina cuando se cruzaron con nosotros?",
  ui_story_1022_10220201_31_dialog_content = "Suena un poco demasiado conveniente para mí. ¿Estás seguro de que no estás simplemente tomando el pelo?",
  ui_story_1022_10220201_32_dialog_content = "¿Por qué mentiríamos sobre esto?",
  ui_story_1022_10220201_33_dialog_content = "Sois los únicos que conocen la respuesta a eso. ¿Quizás no puedes decirme la verdad ahora mismo? ¿O tal vez simplemente disfrutas mucho de las bromas...",
  ui_story_1022_10220201_34_dialog_content = "¿Bromas? ¿De qué demonios estás hablando—",
  ui_story_1022_10220201_35_dialog_content = "¡¿Ya te pondrás serio, verdad?!",
  ui_story_1022_10220201_36_dialog_content = "¿PlayerName?",
  ui_story_1022_10220201_37_dialog_content = "Hiiro y yo vinimos a la Zona Oscura para buscar a un amigo muy importante.",
  ui_story_1022_10220201_38_dialog_content = "Íbamos hacia el baile de Lumina con la esperanza de encontrarla, pero nos quedamos con las manos vacías...",
  ui_story_1022_10220201_39_dialog_content = "¿Por qué nos burlaríamos de ti?!",
  ui_story_1022_10220201_40_dialog_content = "¿Tu amigo...?!",
  ui_story_1022_10220201_41_dialog_content = "Y no te atrevas a decir algo como, \"Apuesto a que estás bastante decepcionado de que solo me encontraste\", ¡o realmente me enojaré!",
  ui_story_1022_10220201_42_dialog_content = "...",
  ui_story_1022_10220201_43_dialog_content = "...",
  ui_story_1022_10220201_44_dialog_content = "¡Jajajajaja!",
  ui_story_1022_10220201_45_dialog_content = "¿Q-Qué te ríes...?",
  ui_story_1022_10220201_46_dialog_content = "¿Así que no estás enojado ahora mismo? No voy a mentir, estoy algo curioso por ver cómo eres cuando estás \"realmente enojado\"!",
  ui_story_1022_10220201_47_dialog_content = "Tienes que ser—",
  ui_story_1022_10220201_48_dialog_content = "Pero desafortunadamente, tendrá que esperar. No planeaba decir algo así en primer lugar.",
  ui_story_1022_10220201_49_dialog_content = "Malinterpreté a ustedes, así que pido disculpas por dejarme llevar un poco con mi temperamento. ¡Mi error!",
  ui_story_1022_10220201_50_dialog_content = "M-Mal juzgado...?",
  ui_story_1022_10220201_51_dialog_content = "Eres de Illumina, así que supuse que todos ustedes eran un montón de lacayos sin cerebro siguiendo órdenes para sumergirse en la Zona Oscura.",
  ui_story_1022_10220201_52_dialog_content = "¡Pero resulta que... Estás aquí por tu amigo! ¡Jajaja!",
  ui_story_1022_10220201_53_dialog_content = "¡Eres especialmente valiente! Se necesita una persona realmente especial para explotar así frente al comandante de la 3ra Legión.",
  ui_story_1022_10220201_54_dialog_content = "¡Me gustas!",
  ui_story_1022_10220201_55_dialog_content = "¡¿?!",
  ui_story_1022_10220201_56_dialog_content = "¡¿Q-Q-Qué se supone que significa eso...?!",
  ui_story_1022_10220201_57_dialog_content = "No parpadeo cuando miento o bromeo, pero esta vez es diferente.",
  ui_story_1022_10220201_58_dialog_content = "¡Cualquiera con autodeterminación está bien en mi libro!",
  ui_story_1022_10220201_59_dialog_content = "Estoy bastante seguro de que todos tienen eso...",
  ui_story_1022_10220201_60_dialog_content = "Bien, nos hemos desviado del tema lo suficiente.",
  ui_story_1022_10220201_61_dialog_content = "Pepita, ahora que estás hablando, hablemos de lo que has encontrado hasta ahora.",
  ui_story_1022_10220201_62_dialog_content = "¿Has obtenido alguna nueva información desde que entraste en la Zona Oscura?",
  ui_story_1022_10220201_63_dialog_content = "Nuestro progreso, huh... Explorar la Zona Oscura no es fácil, incluso para alguien tan hábil como yo. Se necesita mucho esfuerzo para hacer cualquier cosa por aquí, sabes.",
  ui_story_1022_10220201_64_dialog_content = "Como cuando intentamos establecer un campamento base. ¡Tuve que usar estos carteles de se busca aquí para el papel tapiz!",
  ui_story_1022_10220201_65_dialog_content = "<color=#FFB400>MIS</color> carteles de se busca.",
  ui_story_1022_10220201_66_dialog_content = "¿Tus carteles de buscado? No creo que lo entienda muy bien, jaja...",
  ui_story_1022_10220201_67_dialog_content = "Hmm... Es extraño... Pero tuve un sueño sobre ella hace un tiempo...",
  ui_story_1022_10220201_68_dialog_content = "La chica en mi sueño también me resultaba terriblemente familiar.",
  ui_story_1022_10220201_69_dialog_content = "Supongo que eres el Jefe de Inteligencia de Illumina por una razón, ¿eh?",
  ui_story_1022_10220201_70_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_1022_10220201_71_dialog_content = "¡Agáchate, PlayerName!",
  ui_story_1022_10220201_72_dialog_content = "<color=#e8d9bb>Una poderosa explosión sacude la cueva congelada, y innumerables carámbanos caen desde arriba.</color>",
  ui_story_1022_10220201_73_dialog_content = "<color=#e8d9bb>A pesar del repentino alboroto, Pepita suelta una risa robusta.</color>",
  ui_story_1022_10220201_74_dialog_content = "Solo ve a buscar a tu amigo. No me meteré en tu camino, ¡así que recuerda mantenerte fuera del mío!",
  ui_story_1022_10220201_75_dialog_content = "¡Miau! Sé que la he visto antes, ¿pero dónde?!",
  ui_story_1022_10220201_76_dialog_content = "¿Qué está pasando? ¿Cómo se derrumbó la cueva de hielo tan de repente? ¿Dónde está Pepita?",
  ui_story_1022_10220201_77_dialog_content = "...Probablemente, ella se escapó.",
  ui_story_1022_10220201_78_dialog_content = "¿Escapó? ¿Pero por qué?!",
  ui_story_1022_10220201_79_dialog_content = "¡Miau! ¡Ahora recuerdo! ¡Esa chica es una forajida buscada!",
  ui_story_1022_10220201_80_dialog_content = "¿Una forajida? ¿Pero entonces por qué Illumina la puso a cargo del equipo de exploración y la envió a la Zona Oscura?!",
  ui_story_1022_10220201_81_dialog_content = "Porque la capturamos y la metimos en prisión hace un tiempo.",
  ui_story_1022_10220201_82_dialog_content = "Entonces, ¿estamos diciendo que tenemos algo sobre ella, algo para obligarla a servirnos? ¿Y por qué ella, específicamente?",
  ui_story_1022_10220201_83_dialog_content = "¿Qué exactamente llevó a Pepita a la cárcel, Philyshy?",
  ui_story_1022_10220201_84_dialog_content = "Sin idea, honestamente...",
  ui_story_1022_10220201_85_dialog_content = "Nemesis fue responsable de investigarla y arrestarla. Aparentemente, sus órdenes vinieron directamente del Comité.",
  ui_story_1022_10220201_86_dialog_content = "Debe haber sido serio, entonces.",
  ui_story_1022_10220201_87_dialog_content = "Uh... ¿Podría interrumpir solo un segundo?",
  ui_story_1022_10220201_88_dialog_content = "Tiene sentido que Pepita se escape si realmente es una delincuente buscada, pero ¿por qué elegiría hacerlo aquí de todos los lugares?",
  ui_story_1022_10220201_89_dialog_content = "Antes de encontrarnos, ella y su equipo operaban sin supervisión. ¿Por qué no escapó en aquel entonces?",
  ui_story_1022_10220201_90_dialog_content = "¿Por qué esperaría hasta que Hiiro esté aquí? ¡Esto solo haría que sea más difícil para ella escapar!",
  ui_story_1022_10220201_91_dialog_content = "Bueno...",
  ui_story_1022_10220201_92_dialog_content = "¿Qué fue esa explosión justo ahora? ¿Estamos bajo ataque? ¿El capitán activó una de nuestras trampas para los Eclipsites?",
  ui_story_1022_10220201_93_dialog_content = "¿Eh? ¡¿Dónde fue el capitán?!",
  ui_story_1022_10220201_94_dialog_content = "¿Miau? ¿Tienes trampas escondidas por aquí?!",
  ui_story_1022_10220201_95_dialog_content = "La Zona Oscura nos desorienta, dificultando confiar en nuestros sentidos. Para protegernos, el capitán estableció una serie de trampas alrededor de cada perímetro.",
  ui_story_1022_10220201_96_dialog_content = "Y ella intensificó aún más sus contramedidas después de que encontramos ese lugar.",
  ui_story_1022_10220201_97_dialog_content = "Sé que la capitana puede ser un poco abrasiva a veces, pero en realidad se preocupa mucho por nosotros... Jejeje...",
  ui_story_1022_10220201_98_dialog_content = "...",
  ui_story_1022_10220201_99_dialog_content = "Así que esperó hasta ahora para escapar...",
  ui_story_1022_10220201_100_dialog_content = "... ¿solo para dejar a sus compañeros de equipo a nuestro cuidado? ¡Oh, Pepita!",
  ui_story_1022_10220201_101_dialog_content = "<color=#e8d9bb>Zona Oscura, Campamento Base de Lumopolis—</color>",
  ui_story_1022_10220201_102_dialog_content = "Pepita—ese es el nombre del objetivo para esta operación.",
  ui_story_1022_10220201_103_dialog_content = "Nuestro objetivo es muy astuto, y haría cualquier cosa para escapar. Todos deben permanecer en alerta máxima.",
  ui_story_1022_10220201_104_dialog_content = "No podemos permitirnos repetir nuestros errores.",
  ui_story_1022_10220201_105_dialog_content = "¡Sí, capitán!",
  ui_story_1022_10220201_106_dialog_content = "Perdóname... Fui engañado debido a mi descuido...",
  ui_story_1022_10220201_107_dialog_content = "No te culpes por esto, Erica.",
  ui_story_1022_10220201_108_dialog_content = "El Comité de Illumina tiene una larga historia de tratos con ella. Era inevitable que hicieran el trato primero.",
  ui_story_1022_10220201_109_dialog_content = "¡Pero esta vez, tenemos la iniciativa!",
  ui_story_1022_10220201_110_dialog_content = "¿Te importaría elaborar sobre tus planes?",
  ui_story_1022_10220201_111_dialog_content = "¡D-Dama Carleen...!",
  ui_story_1022_10220202_1_dialog_content = "Aquí está tu Mirada del Abismo. Por favor, disfruta.",
  ui_story_1022_10220202_2_dialog_content = "Tal color tentador, aroma pecaminoso y patrones giratorios en todo... Ya veo. Esto debe ser realmente la bebida maldita de un dios malvado.",
  ui_story_1022_10220202_3_dialog_content = "Ahhh...! Su dulzura se permea a través de mi estómago y hasta mi misma alma! Qué bebida demoníacamente divina...",
  ui_story_1022_10220202_4_dialog_content = "¡Si no exploro las profundidades del infierno, nadie más lo hará! ¡Tráeme otro, barman!",
  ui_story_1022_10220202_5_dialog_content = "¡Jajajaja! Todo ese teatro por un pequeño trago, ¿eh? ¡No puedo decir que no me divierte!",
  ui_story_1022_10220202_6_dialog_content = "¿Quién está ahí? ¿Qué vil criatura se atreve a burlarse de mí?",
  ui_story_1022_10220202_7_dialog_content = "Fui yo, pero apenas soy una criatura humilde. Te he estado observando todo este tiempo, ya ves.",
  ui_story_1022_10220202_8_dialog_content = "¿Así que te gusta este tipo de bebida, eh? Conozco algunas bebidas similares, si estás buscando una recomendación.",
  ui_story_1022_10220202_9_dialog_content = "¿Una recomendación...? Supongo que puedo seguir tu pequeño truco por ahora...",
  ui_story_1022_10220202_10_dialog_content = "Solo asegúrate de que no contenga alcohol. Gracias.",
  ui_story_1022_10220202_11_dialog_content = "¿Qué?",
  ui_story_1022_10220202_12_dialog_content = "<size=30>...¿Por qué actúa así si no ha estado bebiendo en absoluto?</size>",
  ui_story_1022_10220202_13_dialog_content = "Pareces bastante familiarizado con el menú... ¿Eres un cliente habitual aquí?",
  ui_story_1022_10220202_14_dialog_content = "Podrías decir eso, pero las bebidas no son lo único que conozco. ¡Peligro, emoción, engaño y disfrute están todos en la cima de mi menú!",
  ui_story_1022_10220202_15_dialog_content = "¿Así que ves este mundo falso solo como una selección de delicias con las que complacer tu paladar? Ya veo... Quizás también tengas el potencial para luchar contra lo desconocido...",
  ui_story_1022_10220202_16_dialog_content = "¡Un brindis por entregarnos a nuestra naturaleza pecaminosa!",
  ui_story_1022_10220202_17_dialog_content = "¡Oye, oye!",
  ui_story_1022_10220202_18_dialog_content = "Ahhh... Otra bebida estimulante suntuosamente. Tu recomendación no podría haber sido más perfecta, desconocido.",
  ui_story_1022_10220202_19_dialog_content = "Te lo dije, ¿no?",
  ui_story_1022_10220202_20_dialog_content = "Entonces, ¿por qué insistes en pedir bebidas así? No me pareces ningún tipo de santurrón.",
  ui_story_1022_10220202_21_dialog_content = "La verdad es... Estoy en servicio activo ahora mismo, lo que significa que tengo que estar alerta en todo momento...",
  ui_story_1022_10220202_22_dialog_content = "Wow, tu trabajo debe ser realmente importante, ¿eh?",
  ui_story_1022_10220202_23_dialog_content = "Por qué, sí... Como miembro de la División de Investigación de Herejes de Lumopolis, nuestro noble trabajo no podría ser más importante para el mundo...",
  ui_story_1022_10220202_24_dialog_content = "¿Qué está haciendo la División de Investigación de Herejes en Umbraton?!",
  ui_story_1022_10220202_25_dialog_content = "Estamos persiguiendo a un objetivo altamente peligroso. Umbraton es un antro de maldad sin ley e inmoral, lo que lo convierte en el lugar perfecto para que ella se esconda.",
  ui_story_1022_10220202_26_dialog_content = "El delincuente en cuestión robó un valioso tomo de Lumopolis antes de escapar a esta ciudad y ocultar sus movimientos...",
  ui_story_1022_10220202_27_dialog_content = "(No puede estar hablando de mí, ¿verdad...?)",
  ui_story_1022_10220202_28_dialog_content = "Nuestro objetivo es aprehenderla y recuperar el tomo robado... ¿Hmm? Espera, amigo, ¿a dónde vas?",
  ui_story_1022_10220202_29_dialog_content = "Yo... creo que bebí un poco demasiado. Solo voy a refrescarme en el baño, ¡vuelvo enseguida!",
  ui_story_1022_10220202_30_dialog_content = "... ¡Maldiciones! Esa era nuestra oportunidad, pero ella aún logró escaparse!",
  ui_story_1022_10220202_31_dialog_content = "Ese amable y animado desconocido... ¿Era Pepita? ¿Pero cómo podría ser esto...?",
  ui_story_1022_10220202_32_dialog_content = "¡Todavía hay tiempo! ¡Tras ella!",
  ui_story_1022_10220202_33_dialog_content = "No podemos permitir que Illumina llegue a ella primero...",
  ui_story_1022_10220202_34_dialog_content = "(... Este escondite debería servir por ahora.)",
  ui_story_1022_10220202_35_dialog_content = "(Un árbol está mejor escondido en un bosque, así que para un Aurorian como yo, mi mejor opción es esconderme...)",
  ui_story_1022_10220202_36_dialog_content = "(¡En un funeral!)",
  ui_story_1022_10220202_37_dialog_content = "(¡Nadie esperaría que me escondiera en un ataúd y fingiera estar muerto! ¡Estarán cavando hoyos el resto de sus vidas buscándome! ¡Jajaja—)",
  ui_story_1022_10220202_38_dialog_content = "Eso es suficiente. Sal del ataúd, Pepita.",
  ui_story_1022_10220202_39_dialog_content = "De nuevo, te queda bastante bien.",
  ui_story_1022_10220202_40_dialog_content = "De todos modos, ¿no tienes ningún respeto por los muertos?",
  ui_story_1022_10220202_41_dialog_content = "!!!",
  ui_story_1022_10220202_42_dialog_content = "(¿Qué me delató?! Ah, ¡mi ropa!)",
  ui_story_1022_10220202_43_dialog_content = "(Fui descuidado. Ni siquiera una persona muerta se presentaría a su propio funeral vistiendo trapos como estos...)",
  ui_story_1022_10220202_44_dialog_content = "(Cuando todo esto termine... ¡Voy a conseguirme ropa nueva y bonita!)",
  ui_story_1022_10220202_45_dialog_content = "¿Estás hablando de Pepita, el delincuente que robó un valioso libro de Lumopolis?",
  ui_story_1022_10220202_46_dialog_content = "Sí, mi señora. Sin embargo, el tomo robado no era más que una falsificación, por lo que el robo en sí no es particularmente nefasto.",
  ui_story_1022_10220202_47_dialog_content = "Nuestra preocupación es que ella tomó este tomo falso y se unió a True Order, ¡la organización más atroz y herética que jamás haya plagado Astra!",
  ui_story_1022_10220202_48_dialog_content = "... Si el libro robado es falso, entonces ¿dónde está el verdadero?",
  ui_story_1022_10220202_49_dialog_content = "Ahí radica el problema, mi lady. El tomo genuino se perdió hace muchos años, pero nuestra investigación hasta ahora indica—",
  ui_story_1022_10220202_50_dialog_content = "¡Que también puede haber caído en manos de la Orden Verdadera!",
  ui_story_1022_10220202_51_dialog_content = "Entiendo ahora. True Order siempre ha sido una amenaza escurridiza, sus miembros aparecen y desaparecen como susurros en la noche.",
  ui_story_1022_10220202_52_dialog_content = "Entonces, cuando Pepita apareció y se sentó a beber con Erica, viste una oportunidad en el ladrón ruidoso y fanfarrón.",
  ui_story_1022_10220202_53_dialog_content = "Y así intentaste usarla para rastrear a True Order y recuperar el verdadero tomo.",
  ui_story_1022_10220202_54_dialog_content = "Sí, Lady Carleen. Nuestro plan en ese momento era exactamente como lo describiste ahora.",
  ui_story_1022_10220202_55_dialog_content = "Pero los malditos Ejecutores del Comité Illumina estaban un paso adelante de nosotros. Después de acorralar a Pepita, la llevaron de vuelta a la Federación...",
  ui_story_1022_10220202_56_dialog_content = "Ahora que lo mencionas, parece que Pepita ha sido enviada a la Zona Oscura bajo las órdenes de Illumina. No será fácil para nosotros detenerla en este momento.",
  ui_story_1022_10220202_57_dialog_content = "Quizás, pero tenga la seguridad, Lady Carleen.",
  ui_story_1022_10220202_58_dialog_content = "Para esta operación, la División de Investigación de Herejes ya ha obtenido permiso del Señor de la Ciudad, así como de la propia Gran Mariscal.",
  ui_story_1022_10220202_59_dialog_content = "Después de reunirse entre ellos, nuestros líderes autorizaron nuestra continua persecución del delincuente conocido como Pepita, para que finalmente podamos llevarla ante la justicia como previamente teníamos la intención.",
  ui_story_1022_10220202_60_dialog_content = "¡No la dejaremos escapar esta vez!",
  ui_story_1022_10220202_61_dialog_content = "... Aun así, actualmente estamos trabajando en colaboración con el equipo de expedición de la Zona Oscura de Illumina.",
  ui_story_1022_10220202_62_dialog_content = "Se encontraron con Pepita hace poco tiempo.",
  ui_story_1022_10220301_1_dialog_content = "¡Por aquí, Carleen! ¡Ustedes llegaron aquí rápidamente!",
  ui_story_1022_10220301_2_dialog_content = "Por supuesto. Cuando uno de los tesoros más valiosos de Lumopolis está en juego, no hay tiempo que perder.",
  ui_story_1022_10220301_3_dialog_content = "¿Qué pasa? ¿Estás exhausto con tu primer encuentro con ese ladrón?",
  ui_story_1022_10220301_4_dialog_content = "B-Bueno, estaría mintiendo si dijera que no me desconcertó...",
  ui_story_1022_10220301_5_dialog_content = "¡Pero no me subestimes! Ella no podría haber ido muy lejos, ¡así que simplemente usaré mis poderes para localizarla!",
  ui_story_1022_10220301_6_dialog_content = "...",
  ui_story_1022_10220301_7_dialog_content = "Philyshy está llevando a los compañeros de equipo de Pepita de regreso en el dirigible, pero Hiiro y yo nos quedaremos contigo.",
  ui_story_1022_10220301_8_dialog_content = "Como se le asignó explorar la Zona Oscura bajo las órdenes de Illumina, tengo la obligación de localizarla y obtener cualquier información que haya recopilado.",
  ui_story_1022_10220301_9_dialog_content = "Perdóname, pero me temo que ella volverá con nosotros en su lugar.",
  ui_story_1022_10220301_10_dialog_content = "¿Y usted es?",
  ui_story_1022_10220301_11_dialog_content = "El capitán de la División de Investigación de Herejes en Lumopolis. Permíteme explicar nuestra situación—",
  ui_story_1022_10220301_12_dialog_content = "...¿El Gran Mariscal autorizó la operación de Lumopolis para capturar a Pepita?",
  ui_story_1022_10220301_13_dialog_content = "Entendido. Eres bienvenido a tomarla bajo tu custodia, pero solo después de que le haya hecho algunas preguntas.",
  ui_story_1022_10220301_14_dialog_content = "La capitana estaba muy emocionada cuando descubrió ese lugar por primera vez, pero luego nos sacó de allí casi inmediatamente, como si de repente estuviera extremadamente preocupada por nuestra seguridad.",
  ui_story_1022_10220301_15_dialog_content = "Algo me dice que lo que vimos allí no le era del todo desconocido...",
  ui_story_1022_10220301_16_dialog_content = "Pepita claramente debe haber descubierto algo.",
  ui_story_1022_10220301_17_dialog_content = "¡Hmph, ustedes soldados de Illumina nunca cambian! Ya nos la arrebataron una vez antes, ¡y ahora amenazan con hacerlo de nuevo!",
  ui_story_1022_10220301_18_dialog_content = "Como dije, eres bienvenido a llevártela-",
  ui_story_1022_10220301_19_dialog_content = "¡No recuerdo haberles dado permiso para pasarme alrededor de la mesa como un plato de bistec!",
  ui_story_1022_10220301_20_dialog_content = "Pepita!",
  ui_story_1022_10220301_21_dialog_content = "¡Así que finalmente has decidido entregarte!",
  ui_story_1022_10220301_22_dialog_content = "¡Mi amigo! No, espera... No puedo dejarme engañar de nuevo...",
  ui_story_1022_10220301_23_dialog_content = "¿Quién dijo que te estaba engañando? La diversión que tuvimos bebiendo juntos era real, y también lo eran tus emociones.",
  ui_story_1022_10220301_24_dialog_content = "¡Así que acero tu resolución y enfréntame en una pelea real, Erica!",
  ui_story_1022_10220301_25_dialog_content = "Mis emociones... Una realidad en un mundo falso...",
  ui_story_1022_10220301_26_dialog_content = "¡No la engañarás una segunda vez, Pepita!",
  ui_story_1022_10220301_27_dialog_content = "(¡Tan rápido!)",
  ui_story_1022_10220301_28_dialog_content = "¡No te vas a escapar!",
  ui_story_1022_10220301_29_dialog_content = "¡Pétalos Efímeros Sobre Cenizas!",
  ui_story_1022_10220301_30_dialog_content = "<color=#e8d9bb>Ola tras ola de ataques vuelan hacia Pepita, quien los contrarresta juguetonamente o los esquiva con agilidad sin esfuerzo.</color>",
  ui_story_1022_10220301_31_dialog_content = "<color=#e8d9bb>A pesar de las abrumadoras probabilidades, apenas parece estar en desventaja.</color>",
  ui_story_1022_10220301_32_dialog_content = "¿¡No se ve afectada por la influencia de la Zona Oscura?!",
  ui_story_1022_10220301_33_dialog_content = "Sabía que había algo diferente en ella...",
  ui_story_1022_10220301_34_dialog_content = "(Los aurorianos normales sienten presión cuando se mueven en la Zona Oscura, pero Pepita parece completamente inafectado...)",
  ui_story_1022_10220301_35_dialog_content = "¡Jajajaja! Parece que estás empezando a entender cuán poderoso soy!",
  ui_story_1022_10220301_36_dialog_content = "Desafortunadamente para ti, ¡el tutorial se acabó! ¡Ahora es el momento para que realmente me desate!",
  ui_story_1022_10220301_37_dialog_content = "Muy bien, Petey—Muéstrales lo que tienes!",
  ui_story_1022_10220301_38_dialog_content = "¡Este poder...!",
  ui_story_1022_10220301_39_dialog_content = "¿Qué está pasando?! Cada vez es más y más difícil respirar...",
  ui_story_1022_10220301_40_dialog_content = "El Darkflow se está volviendo más grueso...",
  ui_story_1022_10220301_41_dialog_content = "(Sin duda alguna... ¡La muñeca en las manos de Pepita está emitiendo la misma energía que un Eclipsite! ¿¡Pero cómo?!)",
  ui_story_1022_10220301_42_dialog_content = "¡Más grande, más grande! Hazte tan grande como puedas!",
  ui_story_1022_10220301_43_dialog_content = "<color=#e8d9bb>Pepita se ríe maniáticamente mientras su extraña muñeca continúa creciendo de manera incontrolable. Después de un tiempo, comienza a lanzar una serie de ataques explosivos desde su cuerpo hinchado.</color>",
  ui_story_1022_10220301_44_dialog_content = "<color=#e8d9bb>Incluso su sombra parecía consistir en una sustancia desconocida, apretando las mentes y cuerpos de cualquiera que quedara atrapado en sus fronteras.</color>",
  ui_story_1022_10220301_45_dialog_content = "¡Mi gente no sobrevivirá mucho más a este ritmo...!",
  ui_story_1022_10220301_46_dialog_content = "¿Cuándo consiguió ella una muñeca tan extraña?!",
  ui_story_1022_10220301_47_dialog_content = "Su nombre es Petey, para tu información. Es mi <color=#FFB400>familiar</color>, así que naturalmente tiene que ser un poco mágico!",
  ui_story_1022_10220301_48_dialog_content = "¡Incluso te dejaré jugar con él, ya que soy tan amable! Disfruten de su tiempo juntos, ¡todos—",
  ui_story_1022_10220301_49_dialog_content = "Porque no durará mucho.",
  ui_story_1022_10220301_50_dialog_content = "¡...!",
  ui_story_1022_10220301_51_dialog_content = "¿Qué... qué es eso?",
  ui_story_1022_10220301_52_dialog_content = "¿Qué pasa, PlayerName? ¿Por qué estás mirando alrededor así?",
  ui_story_1022_10220301_53_dialog_content = "<color=#e8d9bb>Ella está aquí.</color>",
  ui_story_1022_10220301_54_dialog_content = "Algo se dirige hacia nosotros... Algo con una gran cantidad de Darkflow... ¡A-Apartense, todos!",
  ui_story_1022_10220301_55_dialog_content = "<color=#e8d9bb>De repente, una enorme lágrima cae del cielo. Mientras todos se apresuran a retirarse, su color blanco lechoso se refleja en sus ojos horrorizados.</color>",
  ui_story_1022_10220301_56_dialog_content = "<color=#e8d9bb>La lágrima se estrella contra el suelo...</color>",
  ui_story_1022_10220301_57_dialog_content = "<color=#e8d9bb>Y una devastadora explosión sacude todo el campo de batalla.</color>",
  ui_story_1022_10220301_58_dialog_content = "¿Quién se mete con mi amigo?",
  ui_story_1022_10220301_59_dialog_content = "¡<color=#FFB400>Ursura</color>! ¡Sabía que vendrías!",
  ui_story_1022_10220301_60_dialog_content = "<color=#e8d9bb>Mientras el polvo se asienta, una figura aparece en el centro de la explosión, su mera presencia sofoca el aire en los pulmones de todos.</color>",
  ui_story_1022_10220301_61_dialog_content = "Esta longitud de onda... ¡Es un <color=#FFB400>Fantasma</color>!",
  ui_story_1022_10220301_62_dialog_content = "Pepita, ¡tú villano! ¿Estás conspirando no solo con el True Order, sino también con los Eclipsites?!",
  ui_story_1022_10220301_63_dialog_content = "No puedo discernir su apariencia. Es como si estuviera de pie en una espesa niebla...",
  ui_story_1022_10220301_64_dialog_content = "\"¿Conspirando\"? ¿Qué significa eso incluso?! ¡Pepita y yo hemos sido amigos durante mucho tiempo! Si alguien está conspirando, ¡son ustedes!",
  ui_story_1022_10220301_65_dialog_content = "?!!",
  ui_story_1022_10220301_66_dialog_content = "¡Jajajaja, deberías ver las expresiones en sus rostros! Ahh, eso solo compensa todos los problemas con los que he lidiado desde que reaparecí.",
  ui_story_1022_10220301_67_dialog_content = "... Sabías que eventualmente atraeríamos a un Espectro hacia nosotros, ¿no es así?",
  ui_story_1022_10220301_68_dialog_content = "¡Vamos, obvio! ¿Crees que soy lo suficientemente tonto como para pelear con ustedes sin alguien como Ursura para apoyarme? ¡Vamos, dame algo de crédito!",
  ui_story_1022_10220301_69_dialog_content = "Dime, ¿cómo se siente caer en mis trucos una vez más, señor Caelestite?",
  ui_story_1022_10220301_70_dialog_content = "¡Urgh...!",
  ui_story_1022_10220301_71_dialog_content = "¿Cómo está el pequeño Petey, Pepita? Sentí su presencia hace un momento, así que vine a ver cómo estás. ¿Ves lo amable que soy?",
  ui_story_1022_10220301_72_dialog_content = "Está justo aquí, ¿ves? Espera... ¿No vas a llevártelo de vuelta, verdad? Ahora somos realmente buenos amigos, ¡sabes!",
  ui_story_1022_10220301_73_dialog_content = "(¿Estoy escuchando bien? ¿Por qué suena como si realmente fueran amigos...?)",
  ui_story_1022_10220301_74_dialog_content = "No asumas que estás a salvo solo porque un Fantasma ha venido a tu rescate, Pepita.",
  ui_story_1022_10220301_75_dialog_content = "¡Todavía debes rendir cuentas por robar un libro sagrado de Lumopolis!",
  ui_story_1022_10220301_76_dialog_content = "¿Robar? Ese libro pertenecía a True Order en primer lugar, muchas gracias.",
  ui_story_1022_10220301_77_dialog_content = "¡¿Qué?!",
  ui_story_1022_10220301_78_dialog_content = "Es cierto, lo que significa que nunca robé nada de Lumopolis para empezar.",
  ui_story_1022_10220301_79_dialog_content = "Y en cuanto a Illumina, digamos que ustedes tienen suerte de que esté dispuesto a dejar las cosas ir.",
  ui_story_1022_10220301_80_dialog_content = "¡Eso no quiere decir que no me debas nada, sin embargo! Después de todo, nada es gratis!",
  ui_story_1022_10220301_81_dialog_content = "...",
  ui_story_1022_10220301_82_dialog_content = "Esa vieja bruja Belisaria pensó que podría usar mi \"corazón\" para controlarme, pero estaba equivocada. Completamente equivocada.",
  ui_story_1022_10220301_83_dialog_content = "¡El Gran Pepita no sirve a nadie! ¡Jajaja!",
  ui_story_1022_10220301_84_dialog_content = "Vámonos de aquí, Ursura.",
  ui_story_1022_10220301_85_dialog_content = "¡Vamos a enloquecer toda la noche!",
  ui_story_1022_10220301_86_dialog_content = "Pepita...",
  ui_story_1022_10220301_87_dialog_content = "¡Alto ahí!",
  ui_story_1022_10220301_88_dialog_content = "¡Ugh... Todos ustedes son muy molestos! ¡Solo mueran ya!!!",
  ui_story_1022_10220301_89_dialog_content = "¡¡Grahhhh—!!",
  ui_story_1022_10220301_90_dialog_content = "¡Cuidado!",
  ui_story_1022_10220302_1_dialog_content = "(Ve, Petey. Dile a Lady Victoria dónde estoy ahora mismo.)",
  ui_story_1022_10220302_2_dialog_content = "¿Por qué sigues parado, Pepita? ¡Pensé que dijiste que íbamos a divertirnos un poco!",
  ui_story_1022_10220302_3_dialog_content = "¡Viniendo, viniendo!",
  ui_story_1022_10220302_4_dialog_content = "¡Bwahaha, viste sus caras ahora mismo? ¡Estaban tan enojados aunque los golpeé tan mal!",
  ui_story_1022_10220302_5_dialog_content = "¡Sí, lo hiciste! Solo desearía que estuvieras allí para ver cómo los volé a todos con mis trampas antes. ¡Nunca lo vieron venir!",
  ui_story_1022_10220302_6_dialog_content = "¡Ahh, fue una vista tan increíble!",
  ui_story_1022_10220302_7_dialog_content = "*Sollozando* ¿Y-Y no me invitaste? ¡Eso no es justo, Pepita!",
  ui_story_1022_10220302_8_dialog_content = "¡Ahora me debes! ¡Vamos a volvernos aún más locos que nunca antes, me oyes?!",
  ui_story_1022_10220302_9_dialog_content = "Lo sé, así que deja de llorar. Los buenos tiempos nunca se detienen cuando los dos estamos juntos, ¿recuerdas?",
  ui_story_1022_10220302_10_dialog_content = "(Eclipsian) Hay un pequeño objeto en movimiento a lo lejos. Parece que está huyendo.",
  ui_story_1022_10220302_11_dialog_content = "(Hablando en Eclipsiano) Ah—Es el familiar que esa Aurorian le dio a Lady Ursura!",
  ui_story_1022_10220302_12_dialog_content = "(Hablando en Eclipsiano) ¿Qué problemas está causando ahora? Los aurorianos son demasiado astutos para ser confiables, eso es bien sabido.",
  ui_story_1022_10220302_13_dialog_content = "(Eclipsian) ¿Deberíamos dejarlos ir?",
  ui_story_1022_10220302_14_dialog_content = "(Eclipsiano) ¡No, tonto! ¡Debemos capturar a ese familiar y devolverlo a Lady Ursura!",
  ui_story_1022_10220302_15_dialog_content = "(Eclipsiano) ¡Entendido!",
  ui_story_1022_10220302_16_dialog_content = "¡¡¡Maldita sea todo!!!",
  ui_story_1022_10220302_17_dialog_content = "La teníamos completamente rodeada... ¡Y aún así se nos escapó de las manos otra vez!",
  ui_story_1022_10220302_18_dialog_content = "No seas tan duro contigo mismo. Ninguno de nosotros sabía que Pepita puede llamar a un Fantasma para que la ayude.",
  ui_story_1022_10220302_19_dialog_content = "Mis sospechas, por otro lado, han sido completamente confirmadas.",
  ui_story_1022_10220302_20_dialog_content = "Ese Fantasma tenía algo similar al coral creciendo de su cuerpo...",
  ui_story_1022_10220302_21_dialog_content = "Una vez que descubrió \"ese lugar\", supo que un Wraith estaba cerca. En ese momento, decidió usar al Wraith como medio para escapar y se entregó a él.",
  ui_story_1022_10220302_22_dialog_content = "¿Rendirse... a un Fantasma? Pero, ¿qué podría ofrecerle un Fantasma?",
  ui_story_1022_10220302_23_dialog_content = "¡Todo lo que demuestra es que ella ha caído más allá de la salvación! No dejes que te influya con sus palabras nunca más, Erica!",
  ui_story_1022_10220302_24_dialog_content = "...",
  ui_story_1022_10220302_25_dialog_content = "¿Nadie más lo encuentra extraño?",
  ui_story_1022_10220302_26_dialog_content = "¿Qué quieres decir, Carleen?",
  ui_story_1022_10220302_27_dialog_content = "Esa Wraith, Ursura, es claramente una enemiga extremadamente poderosa, y sin embargo, no parecía particularmente interesada en luchar contra nosotros.",
  ui_story_1022_10220302_28_dialog_content = "Ambas veces que atacó, fue para proteger a Pepita.",
  ui_story_1022_10220302_29_option_content = "¿P-Podría ser este el poder de la amistad?!",
  ui_story_1022_10220302_30_dialog_content = "... Este no es el momento para bromas.",
  ui_story_1022_10220302_31_dialog_content = "¡Lo siento!",
  ui_story_1022_10220302_32_option_content = "Pero bromas aparte, parecían ser amigos el uno del otro.",
  ui_story_1022_10220302_33_dialog_content = "Pepita estaba segura de que Ursura vendría a rescatarla, que era la única razón por la que se mostró frente a nosotros.",
  ui_story_1022_10220302_34_dialog_content = "¿Amistad entre un Fantasma y un Aurorian... Es realmente posible?",
  ui_story_1022_10220302_35_dialog_content = "Estoy de acuerdo: el comportamiento de Ursura fue cualquier cosa menos normal.",
  ui_story_1022_10220302_36_dialog_content = "Ella no tenía enemistad hacia nosotros, y solo estaba interesada en ayudar a Pepita... ¿Pero por qué? ¿Podrían estar planeando algo más?",
  ui_story_1022_10220302_37_dialog_content = "¿Quizás esos dos solo están interesados en divertirse juntos?",
  ui_story_1022_10220302_38_dialog_content = "...",
  ui_story_1022_10220302_39_dialog_content = "¡No seas absurdo!",
  ui_story_1022_10220302_40_dialog_content = "¡Ahora agarra tu Piedra Lumina y prepárate para partir, Erica!",
  ui_story_1022_10220302_41_dialog_content = "¿Qué? ¿De verdad van tras de Pepita?!",
  ui_story_1022_10220302_42_dialog_content = "¡Por supuesto que lo estamos, y ningún Espectro nos impedirá cumplir nuestra misión! Ahora, ¡mantente fuera de nuestro camino!",
  ui_story_1022_10220302_43_dialog_content = "No tenemos otra opción. Pepita tiene información que podría llevarnos al tomo robado de Lumopolis.",
  ui_story_1022_10220302_44_dialog_content = "... Una vez que la encontremos, podemos hacer todas las preguntas que queramos.",
  ui_story_1022_10220302_45_dialog_content = "(Parece que Carleen está insinuando a True Order, y la posibilidad de que el libro robado realmente les pertenezca...)",
  ui_story_1022_10220302_46_dialog_content = "(Mencionó anteriormente que Pepita era miembro de la Orden Verdadera.)",
  ui_story_1022_10220302_47_dialog_content = "(Pero si ese es el caso, ¿por qué fue tomada prisionera por los Illumina? ¿Y por qué parece que tiene una deuda que cobrar de ellos?)",
  ui_story_1022_10220302_48_dialog_content = "(Hay demasiado que no sabemos en este momento...)",
  ui_story_1022_10220401_1_dialog_content = "¡Bienvenidos a la Tundra Coralina!",
  ui_story_1022_10220401_2_dialog_content = "¡Hermoso, no es así? ¡Apuesto a que nunca has visto algo tan extraño como esto! Adelante, grita y alza la voz todo lo que quieras!",
  ui_story_1022_10220401_3_dialog_content = "Es tan hermoso de una manera retorcida y torcida. Puedo ver por qué te gusta tanto este lugar.",
  ui_story_1022_10220401_4_dialog_content = "¿Qué pasa? ¿No te emociona este lugar? ¡Vamos, muestra algo de emoción!",
  ui_story_1022_10220401_5_dialog_content = "Hablo en serio, Ursura. Este lugar es tan hermoso y único que me tomó completamente desprevenido.",
  ui_story_1022_10220401_6_dialog_content = "(O al menos lo hizo la primera vez que lo vi.)",
  ui_story_1022_10220401_7_dialog_content = "Suficientemente bueno para mí, supongo. ¡Vamos, hay mucha diversión por aquí!",
  ui_story_1022_10220401_8_dialog_content = "¡Más te vale! Me has emocionado mucho con este lugar, ¡así que no me decepciones!",
  ui_story_1022_10220401_9_dialog_content = "<color=#e8d9bb>Lo que debería haber sido un campo pálido y silencioso de hielo era en cambio un paisaje vibrante lleno de líquenes, corales y árboles coloridos, como una escena sacada directamente de un oscuro cuento de hadas.</color>",
  ui_story_1022_10220401_10_dialog_content = "<color=#e8d9bb>Y allí, moviéndose entre los corales—</color>",
  ui_story_1022_10220401_11_dialog_content = "¡¿?!",
  ui_story_1022_10220401_12_dialog_content = "(¿Son esos... Aurorians? No, sus ojos apagados y sin vida se parecen más a los de los Eclipsites, pero no se parecen en nada.)",
  ui_story_1022_10220401_13_dialog_content = "<color=#e8d9bb>Las criaturas sin alma, similares a los aurorianos, se mueven mecánicamente entre los arrecifes de coral, limpiando los líquenes excesivos de sus superficies.</color>",
  ui_story_1022_10220401_14_dialog_content = "<color=#e8d9bb>Contra el espléndido telón de fondo de árboles y corales, sus rígidos movimientos parecen aún más escalofriantes.</color>",
  ui_story_1022_10220401_15_dialog_content = "Hola Ursura, ¿esos son...?",
  ui_story_1022_10220401_16_dialog_content = "¿Realmente no sabes qué son esos? ¡Son corales, tonto!",
  ui_story_1022_10220401_17_dialog_content = "No, me refiero a las personas que caminan a su alrededor... ¿Son Aurorians o Eclipsites? ¿O tal vez algo completamente diferente?",
  ui_story_1022_10220401_18_dialog_content = "Oh... ¿Por qué estás perdiendo tiempo mirándolos? No tiene sentido, sabes.",
  ui_story_1022_10220401_19_dialog_content = "Te lo diré ahora mismo, definitivamente no heredaron nada de lo que hace que los Aurorians sean divertidos para jugar.",
  ui_story_1022_10220401_20_dialog_content = "(\"¿Heredar\"? En otras palabras... De alguna manera están conectados con los aurorianos.)",
  ui_story_1022_10220401_21_dialog_content = "Después de pasar tanto tiempo aquí, esos chicos se han vuelto mucho más duraderos. Es por eso que <color=#FFB400>nosotros</color> los usamos para tareas simples como la limpieza.",
  ui_story_1022_10220401_22_dialog_content = "Escuchan lo suficientemente bien cuando les decimos que hagan cosas, pero de lo contrario son completamente inútiles.",
  ui_story_1022_10220401_23_dialog_content = "Son terribles para las conversaciones, no saben cómo divertirse y mueren demasiado fácilmente. Simplemente no se comparan con los Aurorians, ¡sabes!",
  ui_story_1022_10220401_24_dialog_content = "(¿No tienen forma de comunicarse o contraatacar...? ¿Es eso lo que ella está tratando de decir?)",
  ui_story_1022_10220401_25_dialog_content = "¡Ah, pero no te preocupes por ellos! Soy yo quien dirige este lugar, ¡ahora sígueme!",
  ui_story_1022_10220401_26_dialog_content = "...",
  ui_story_1022_10220402_1_dialog_content = "Fiu... Finalmente hemos terminado con los experimentos de hoy.",
  ui_story_1022_10220402_2_dialog_content = "¿Soy el único que piensa que las pruebas se han estado poniendo más difíciles últimamente?",
  ui_story_1022_10220402_3_dialog_content = "No, tienes razón... Para ser honesto, no sé cuánto más puedo soportar.",
  ui_story_1022_10220402_4_dialog_content = "Me duele todo el cuerpo como loco, y sigo teniendo pesadillas todas las noches...",
  ui_story_1022_10220402_5_dialog_content = "Aquí igual...",
  ui_story_1022_10220402_6_dialog_content = "¡Parece que Pepita está aguantando muy bien! ¡Incluso con un corazón débil y las peores pruebas de todos nosotros, nada parece frenarte!",
  ui_story_1022_10220402_7_dialog_content = "¡Ahh, esto no es nada para mí!",
  ui_story_1022_10220402_8_dialog_content = "¡Comparado con el peligro al que se enfrentó mi papá, esto es solo un paseo por el parque!",
  ui_story_1022_10220402_9_dialog_content = "Oh sí... Tu padre fue a explorar en la Zona Oscura, ¿no Pepita?",
  ui_story_1022_10220402_10_dialog_content = "¡Sí! Es parte del Equipo de Exploración de la Zona Oscura de Illumina, ¡así que hace todo tipo de cosas increíbles allí!",
  ui_story_1022_10220402_11_dialog_content = "Por eso quiero explorar la Zona Oscura también. ¡Apuesto a que estará muy orgulloso de mí! ¡Jajaja!",
  ui_story_1022_10220402_12_dialog_content = "¡Ese es el espíritu, Pepita! ¡Te respaldaremos todo el camino!",
  ui_story_1022_10220402_13_dialog_content = "Pero espera, ¿no significa eso que no podrás verlo durante nuestro próximo día de visita?",
  ui_story_1022_10220402_14_dialog_content = "... N-No se puede evitar. Después de todo, él es un chico realmente ocupado...",
  ui_story_1022_10220402_15_dialog_content = "¡Está bien! Si hay algo que quieras, solo dímelo y le pediré a mi mamá que te lo traiga!",
  ui_story_1022_10220402_16_dialog_content = "E-Está bien... Gracias.",
  ui_story_1022_10220402_17_dialog_content = "Mi papá vendrá a verme una vez que regrese... Estoy seguro de ello.",
  ui_story_1022_10220402_18_dialog_content = "<color=#e8d9bb>Algunos años después-</color>",
  ui_story_1022_10220402_19_dialog_content = "¿Cómo ha estado ella últimamente?",
  ui_story_1022_10220402_20_dialog_content = "Lo mismo de siempre, señora. Ella tira cualquier comida que no le gusta, y pide doble ración de las cosas que sí le gustan—",
  ui_story_1022_10220402_21_dialog_content = "Ella sigue gritándonos que toquemos música, y comienza a cantar a todo pulmón si la ignoramos...",
  ui_story_1022_10220402_22_dialog_content = "Ella ha estado aquí el tiempo suficiente para que todos ustedes conozcan sus preferencias. Si se niega a comer algo, entonces no se lo sirvan.",
  ui_story_1022_10220402_23_dialog_content = "... S-Sí, señora!",
  ui_story_1022_10220402_24_dialog_content = "¿No crees que la estás consintiendo demasiado? Después de todo, solo es una prisionera.",
  ui_story_1022_10220402_25_dialog_content = "Ella y su corazón son ambos especímenes invaluables. Tenemos más que perder que cualquier otro si sucumbe a la desnutrición.",
  ui_story_1022_10220402_26_dialog_content = "Y además, desperdiciar comida nunca es bueno.",
  ui_story_1022_10220402_27_dialog_content = "... Entonces esperemos que ella coopere contigo.",
  ui_story_1022_10220402_28_dialog_content = "Oye, ¿qué pasa allí? ¿Conseguiste mi disco, o tengo que seguir cantando? ¡No me digas que estás empezando a gustar de mi voz o algo así!",
  ui_story_1022_10220402_29_dialog_content = "Supongo que no debería decepcionar a mis aficionados, ¡así que aquí vamos! ¡Ejem! Llévame a caaaaaasa, a esos campos de veeeeerde♪",
  ui_story_1022_10220402_30_dialog_content = "Nunca has visto un campo verde en tu vida, Pepita.",
  ui_story_1022_10220402_31_dialog_content = "Ugh, no tú de nuevo. Estoy harto de ver tu vieja y fea cara, piérdete.",
  ui_story_1022_10220402_32_dialog_content = "¿Es eso cierto? Recuerdo lo emocionado que solías estar cada vez que te visitaba en el laboratorio.",
  ui_story_1022_10220402_33_dialog_content = "Y eso fue porque yo era la única persona que alguna vez vino a verte.",
  ui_story_1022_10220402_34_dialog_content = "No estabas allí para verme. Solo viniste para ver cómo estaba tu preciado sujeto de prueba.",
  ui_story_1022_10220402_35_dialog_content = "El valor de un sujeto de prueba es tanto concreto como cuantificable.",
  ui_story_1022_10220402_36_dialog_content = "Pero cosas como las emociones, e incluso los lazos familiares, son demasiado vagos para ser confiables. De hecho, a menudo llevan a las personas por mal camino.",
  ui_story_1022_10220402_37_dialog_content = "Tú, de todas las personas, deberías saber eso.",
  ui_story_1022_10220402_38_dialog_content = "...",
  ui_story_1022_10220402_39_dialog_content = "Si realmente odias la hipocresía tanto como dices, entonces en lugar de soltar todas estas tonterías rebeldes...",
  ui_story_1022_10220402_40_dialog_content = "Deberías ver mi presencia aquí de una manera más positiva... Mi precioso sujeto de prueba.",
  ui_story_1022_10220402_41_dialog_content = "¡Ven aquí, Ulysses!",
  ui_story_1022_10220402_42_dialog_content = "...",
  ui_story_1022_10220402_43_dialog_content = "¿¡Eh?! ¡E-Es ese dispositivo otra vez!",
  ui_story_1022_10220402_44_dialog_content = "(Sin duda alguna. Ese año, cuando esos científicos de Illumina reemplazaron mi corazón defectuoso con uno artificial...)",
  ui_story_1022_10220402_45_dialog_content = "(Vi ese dispositivo junto a mi cama cuando desperté de la cirugía.)",
  ui_story_1022_10220402_46_dialog_content = "(Y dentro de él... ¡Está mi corazón original! ¡Estoy seguro de ello!)",
  ui_story_1022_10220402_47_dialog_content = "Parece que sabes exactamente lo que hay dentro de este contenedor.",
  ui_story_1022_10220402_48_dialog_content = "... ¿Qué quieres de mí?",
  ui_story_1022_10220402_49_dialog_content = "Es simple. Necesitamos que uses tus poderes únicos para entrar en la Zona Oscura y recuperar el núcleo de guardián uno.",
  ui_story_1022_10220402_50_dialog_content = "Si tienes éxito, te entregaré esto personalmente.",
  ui_story_1022_10220402_51_dialog_content = "También puedo usar nuestra tecnología mejorada para terminar de construir tu corazón artificial incompleto. La elección es tuya.",
  ui_story_1022_10220402_52_dialog_content = "¿Crees que puedes manipularme así?!",
  ui_story_1022_10220402_53_dialog_content = "Ya te dije que no dejes que tus emociones guíen tus elecciones, Pepita.",
  ui_story_1022_10220402_54_dialog_content = "Piensa larga y detenidamente sobre lo que realmente quieres, y el precio que estás dispuesto a pagar por ello.",
  ui_story_1022_10220402_55_dialog_content = "...",
  ui_story_1022_10220402_56_dialog_content = "<color=#e8d9bb>En la Tundra de Coral de la Zona Oscura.</color>",
  ui_story_1022_10220402_57_dialog_content = "<color=#e8d9bb>Con una voz aguda, Ursura ordena a sus subordinados Eclipsite que preparen un banquete en honor a su amiga.</color>",
  ui_story_1022_10220402_58_dialog_content = "<color=#e8d9bb>Cuando Pepita vuelve en sí, se da cuenta de que estuvo perdida en sus recuerdos durante bastante tiempo.</color>",
  ui_story_1022_10220402_59_dialog_content = "<color=#e8d9bb>Mientras contempla las magníficas formaciones de coral, recuerda por qué decidió abandonar su trato con Belisaria y venir aquí en su lugar.</color>",
  ui_story_1022_10220402_60_dialog_content = "Ursura.",
  ui_story_1022_10220402_61_dialog_content = "¡Idiota! ¿Quién te dijo que pusieras coral rojo y verde en el mismo plato?! ¡Tu gusto estético no es mejor que el de una hormiga!",
  ui_story_1022_10220402_62_dialog_content = "Justamente por eso es tan importante ser de una línea de sangre noble... ¿Necesitabas algo, Pepita?",
  ui_story_1022_10220402_63_dialog_content = "¿Recuerdas lo que te dije cuando nos conocimos por primera vez? ¿La historia sobre mi corazón?",
  ui_story_1022_10220402_64_dialog_content = "Sobre cómo esas personas extrajeron mi corazón original y—",
  ui_story_1022_10220402_65_dialog_content = "¡Ugh, esos idiotas Aurorianos! ¡Arrancaron tu corazón y ni siquiera tuvieron la decencia de reemplazarlo con uno completamente funcional! ¡Por eso estás en tanto dolor todo el tiempo!",
  ui_story_1022_10220402_66_dialog_content = "Recuerdo todo lo que me contaste sobre eso, Pepita... Así que no hay necesidad de empezar desde el principio.",
  ui_story_1022_10220402_67_dialog_content = "Claro, pero en aquel entonces, dijiste algo sobre poder crear también un corazón funcional.",
  ui_story_1022_10220402_68_dialog_content = "<color=#e8d9bb>La mirada de Pepita cae al centro del pecho de Ursura, donde ramas de coral palpitante y ondulante sobresalen de manera espectacular.</color>",
  ui_story_1022_10220402_69_dialog_content = "<color=#e8d9bb>Estos mismos corales son los que componen el propio corazón de Ursura.</color>",
  ui_story_1022_10220402_70_dialog_content = "¡Por supuesto que puedo! Después de todo, ¡tengo el poder más puro y noble aquí!",
  ui_story_1022_10220402_71_dialog_content = "Para alguien tan poderoso como yo, ¡crear un corazón poderoso de coral es tan simple como respirar!",
  ui_story_1022_10220402_72_dialog_content = "... Entonces, ¿cuándo puedes empezar?",
  ui_story_1022_10220402_73_dialog_content = "¿Eso significa que finalmente has tomado una decisión?",
  ui_story_1022_10220402_74_dialog_content = "¡Hmph! En ese caso... ¡Tienes que prometerme algo primero!",
  ui_story_1022_10220501_1_dialog_content = "¡Nyaaa! ¿Por qué todas las cosas locas suceden cuando no estoy cerca?!",
  ui_story_1022_10220501_2_dialog_content = "¡Pero está bien! Como el Jefe de Intel favorito de todos, traje mucha información valiosa para que la usemos!",
  ui_story_1022_10220501_3_dialog_content = "¿Se trata de Pepita?!",
  ui_story_1022_10220501_4_dialog_content = "¡Lo adivinaste! Antes de que me fuera, apenas sabíamos algo sobre esa chica a pesar de que la enviamos a la Zona Oscura con su propio equipo.",
  ui_story_1022_10220501_5_dialog_content = "¡Así que conseguí a Yingel, y ella fue lo suficientemente amable para escanear un montón de documentos del Comité para nosotros!",
  ui_story_1022_10220501_6_dialog_content = "¿El Comité? Sabía que había más en ella de lo que pensábamos.",
  ui_story_1022_10220501_7_dialog_content = "Según lo que encontramos en sus archivos, el Comité envió un Equipo de Expedición diferente a la Zona Oscura hace años...",
  ui_story_1022_10220501_8_dialog_content = "Y resulta que el padre de Pepita era uno de sus miembros.",
  ui_story_1022_10220501_9_dialog_content = "¿Eh? ¿Estás diciendo que ella fue ascendida al Equipo de Expedición?",
  ui_story_1022_10220501_10_dialog_content = "No, PlayerName. Piensa en la apariencia de Pepita durante nuestra batalla.",
  ui_story_1022_10220501_11_dialog_content = "No llevaba ningún tipo de equipo, y sin embargo, sus movimientos no se vieron afectados por el Darkflow en absoluto.",
  ui_story_1022_10220501_12_dialog_content = "Si esta característica es hereditaria, entonces todo esto tiene mucho más sentido.",
  ui_story_1022_10220501_13_dialog_content = "... Tienes razón. Si la habilidad de Pepita para moverse libremente en la Zona Oscura es heredada, entonces su papá probablemente también la tenía.",
  ui_story_1022_10220501_14_dialog_content = "Entonces, su exploración debe haber sido realmente exitosa, ¿verdad?",
  ui_story_1022_10220501_15_dialog_content = "Por el contrario, todo su equipo fue aniquilado...",
  ui_story_1022_10220501_16_dialog_content = "¡¿E-Eliminados?!",
  ui_story_1022_10220501_17_dialog_content = "Eso es correcto, y el único sobreviviente fue el padre de Pepita.",
  ui_story_1022_10220501_18_dialog_content = "Pero parece que su habilidad especial no fue lo único que utilizó para regresar. Hay una buena posibilidad de que tuviera que recurrir a algunos medios menos que nobles para sobrevivir...",
  ui_story_1022_10220501_19_dialog_content = "Porque tan pronto como regresó, firmó toda la documentación necesaria para colocar a Pepita bajo la custodia de un laboratorio de Illumina.",
  ui_story_1022_10220501_20_dialog_content = "¿Abandonó a su propia hija?!",
  ui_story_1022_10220501_21_dialog_content = "¡Pero eso es básicamente aceptar dejarla convertirse en un sujeto de prueba!",
  ui_story_1022_10220501_22_dialog_content = "Lo sé... Es por eso que Yingel piensa que debe haber hecho algo tan malo que la única forma de salvarse era sacrificando a su propio niño...",
  ui_story_1022_10220501_23_dialog_content = "... Increíble.",
  ui_story_1022_10220501_24_dialog_content = "No pensé que alguien en la Federación pudiera hacer algo tan cobarde.",
  ui_story_1022_10220501_25_dialog_content = "Después de eso, nuestras exploraciones en la Zona Oscura disminuyeron significativamente, pero la investigación sobre Pepita continuó sin vacilación.",
  ui_story_1022_10220501_26_dialog_content = "Para maximizar su fuerza de combate y movilidad, el Comité reemplazó su deficiente corazón auroriano con uno artificial.",
  ui_story_1022_10220501_27_dialog_content = "¿Qué? ¿Quieres decir que su corazón es hecho por el hombre?",
  ui_story_1022_10220501_28_dialog_content = "En otras palabras, el Comité nunca abandonó sus planes para explorar la Zona Oscura. Más bien, estaban criando a Pepita para ser el próximo líder del Equipo de Expedición.",
  ui_story_1022_10220501_29_dialog_content = "¡Esa es una posibilidad distinta seguro! Sin embargo...",
  ui_story_1022_10220501_30_dialog_content = "Nuestra tecnología sobre corazones artificiales aún está lejos de estar desarrollada, lo que significa que Pepita probablemente también fue un valioso sujeto de prueba...",
  ui_story_1022_10220501_31_dialog_content = "Pobre Pepita... ¿Cómo pudieron hacerle pasar por tanto dolor?",
  ui_story_1022_10220501_32_dialog_content = "Lo sé, pero se pone peor. Después de que Pepita descubrió el trato entre su padre y el Comité, se salió completamente de control...",
  ui_story_1022_10220501_33_dialog_content = "Escapó de Illumina a la primera oportunidad que tuvo, y comenzó a vagar por Astra como fugitiva. Por lo que hemos recopilado, parece que ahora se ha unido al True Order.",
  ui_story_1022_10220501_34_dialog_content = "Finalmente entiendo... Sin ningún otro lugar a donde ir, terminó con ellos...",
  ui_story_1022_10220501_35_dialog_content = "¡Pero espera, hay más! Después de que escapó, Pepita en realidad se infiltró de nuevo en la Federación en un momento dado.",
  ui_story_1022_10220501_36_dialog_content = "Una elección valiente pero tonta. ¿Cuál era su objetivo?",
  ui_story_1022_10220501_37_dialog_content = "Supongo que su objetivo era robar de nuevo su corazón original.",
  ui_story_1022_10220501_38_dialog_content = "Pero no nos llevó mucho tiempo encontrarla, así que volvió a huir.",
  ui_story_1022_10220501_39_dialog_content = "Entonces, tenía a dos facciones principales persiguiéndola, pero Illumina la capturó al final. No solo eso, sino que también la enviaron directamente a la Zona Oscura...",
  ui_story_1022_10220501_40_dialog_content = "No sé cómo describirlo de otra manera... Pero ella tiene una de las historias más coloridas que he visto.",
  ui_story_1022_10220501_41_dialog_content = "(Realmente no puedo culparla por odiar la autoridad o ser rebelde...)",
  ui_story_1022_10220501_42_dialog_content = "Y ahora ella está aliada con un Fantasma.",
  ui_story_1022_10220501_43_dialog_content = "Excelente trabajo, Philyshy. Informaré todo al Gran Mariscal lo más pronto posible.",
  ui_story_1022_10220502_1_dialog_content = "... Y esa es nuestra situación hasta ahora. La capacidad de Pepita para moverse libremente a través de la Zona Oscura es definitivamente valiosa.",
  ui_story_1022_10220502_2_dialog_content = "¿Cómo deberíamos proceder, Gran Mariscal?",
  ui_story_1022_10220502_3_dialog_content = "Si nos encontramos con ella de nuevo, ¿se espera realmente que nos quedemos de brazos cruzados y dejemos que Lumopolis se la lleve?",
  ui_story_1022_10220502_4_dialog_content = "Es muy probable que Pepita sepa algo sobre el tesoro robado de Lumopolis.",
  ui_story_1022_10220502_5_dialog_content = "Esta exploración es un esfuerzo conjunto entre Illumina y Lumopolis. Si queremos tener éxito, no podemos simplemente ignorar sus intereses.",
  ui_story_1022_10220502_6_dialog_content = "Pero-",
  ui_story_1022_10220502_7_dialog_content = "Eso no significa que no podamos trazar la línea en algún lugar, sin embargo.",
  ui_story_1022_10220502_8_dialog_content = "Yingel me informó sobre el pasado de Pepita hace un tiempo. Sospechaba que ella podría tener un talento para explorar la Zona Oscura—",
  ui_story_1022_10220502_9_dialog_content = "Así que compartí esa información con el Señor de la Ciudad de Lumopolis.",
  ui_story_1022_10220502_10_dialog_content = "¡¿Qué?! E-Entonces... ¿Cuál fue su reacción?",
  ui_story_1022_10220502_11_dialog_content = "Cualquiera con ojos puede ver que Pepita es mucho más útil en el campo que en una celda de prisión.",
  ui_story_1022_10220502_12_dialog_content = "Schwartz no es una excepción.",
  ui_story_1022_10220502_13_dialog_content = "Si podemos utilizar a Pepita y sus habilidades a nuestro máximo provecho, todos se beneficiarán.",
  ui_story_1022_10220502_14_dialog_content = "No solo para esta operación, sino también a largo plazo.",
  ui_story_1022_10220502_15_dialog_content = "¿Deseas usarla para recopilar más información que nos podría dar ventaja sobre los Eclipsites en nuestras futuras batallas... Es eso?",
  ui_story_1022_10220502_16_dialog_content = "Parece que estamos en la misma página, Señor Schwartz.",
  ui_story_1022_10220502_17_dialog_content = "Hmph... En lo que a mí respecta, ella no es más que una ladrona insignificante. Siempre y cuando nos diga lo que sabe sobre nuestro tomo sagrado, Lumopolis no la verá como una enemiga.",
  ui_story_1022_10220502_18_dialog_content = "Veo... ¡Impresionante trabajo, Gran Mariscal!",
  ui_story_1022_10220502_19_dialog_content = "Me alegro de que entiendas, así que simplemente sigue sus planes por ahora.",
  ui_story_1022_10220502_20_dialog_content = "Además, estoy seguro de que Pepita será incluso más problemático que todo Lumopolis allí afuera! ¡Jajajaja!",
  ui_story_1022_10220502_21_dialog_content = "¡N-No en absoluto! Sin tu oportuna intervención, Lumopolis ciertamente habría encarcelado a esa mujer!",
  ui_story_1022_10220502_22_dialog_content = "Después de todo... El líder de la División de Investigación de Herejes tiene una obsesión casi maníaca con True Order.",
  ui_story_1022_10220502_23_dialog_content = "¿Q-Qué quieres decir, Pepita ya no enfrentará castigo?!",
  ui_story_1022_10220502_24_dialog_content = "¡El Señor de la Ciudad debería estar completamente al tanto de su asociación con la Orden Verdadera!",
  ui_story_1022_10220502_25_dialog_content = "Sí, pero el Señor de la Ciudad también está considerando los beneficios a largo plazo que ella puede proporcionar para todos los Aurorians.",
  ui_story_1022_10220502_26_dialog_content = "Todavía tenemos órdenes de interrogarla también sobre el tomo robado.",
  ui_story_1022_10220502_27_dialog_content = "¿Pero cómo... Cómo podemos dejar que se aleje tan fácilmente...?",
  ui_story_1022_10220502_28_dialog_content = "... Sé que guardas rencor contra la True Order, y tu venganza te ha convertido en un miembro ejemplar de la División de Investigación de Herejes.",
  ui_story_1022_10220502_29_dialog_content = "Pero si los objetivos de tu odio realmente pertenecen a True Order ha estado en cuestión durante años.",
  ui_story_1022_10220502_30_dialog_content = "No... No podemos simplemente dejarla ir... No así...",
  ui_story_1022_10220502_31_dialog_content = "¡Eso es suficiente, ahora compóngase usted mismo!",
  ui_story_1022_10220502_32_dialog_content = "Ahora estamos en la Zona Oscura. Al permitirte ser controlado por tus emociones, ¡estás poniendo en juego las vidas de tus camaradas!",
  ui_story_1022_10220502_33_dialog_content = "...Tienes razón, mi señora. Por favor, perdona mi arrebato...",
  ui_story_1022_10220502_34_dialog_content = "Yo... Solo necesito algo de tiempo solo, eso es todo.",
  ui_story_1022_10220502_35_dialog_content = "...",
  ui_story_1022_10220601_1_dialog_content = "No puedo dejarla ir... ¡No lo haré! Incluso si tengo que hacerlo yo mismo... La haré pagar...",
  ui_story_1022_10220601_2_dialog_content = "Ella y cada miembro de la Orden Verdadera... ¡Deben ser condenados a muerte!",
  ui_story_1022_10220601_3_dialog_content = "Veo que todavía tienes la intención de hacer algo tonto.",
  ui_story_1022_10220601_4_dialog_content = "¡D-Dama Carleen...!",
  ui_story_1022_10220601_5_dialog_content = "¿Qué tienes en tu mano?",
  ui_story_1022_10220601_6_dialog_content = "Es... Se llama el Resonador de la Noche Blanca. Es uno de los artefactos alojados en el Templo de Lumopolis, y es capaz de detectar la presencia de nuestros objetos benditos.",
  ui_story_1022_10220601_7_dialog_content = "Ha estado reaccionando intensamente a algo desde que entramos en la Zona Oscura.",
  ui_story_1022_10220601_8_dialog_content = "Creo que uno de los artefactos perdidos de Lumopolis puede estar cerca.",
  ui_story_1022_10220601_9_dialog_content = "¿Está apuntando en una dirección específica? Como... ¿Cuál es la dirección en la que Pepita y Ursura se fueron?",
  ui_story_1022_10220601_10_dialog_content = "Yo...",
  ui_story_1022_10220601_11_dialog_content = "Estabas planeando rastrearlos y recuperar nuestros artefactos perdidos todo por ti mismo, ¿no es así?",
  ui_story_1022_10220601_12_dialog_content = "Si es así, no solo estás sobreestimando tus habilidades, ¡sino que también estás subestimando gravemente a tus aliados!",
  ui_story_1022_10220601_13_dialog_content = "¿Si una sola persona fuera capaz de lograr algo aquí, nos habríamos unido para crear este Equipo de Expedición?!",
  ui_story_1022_10220601_14_dialog_content = "No estoy seguro de si debería mencionar esto o no... Pero siento esa enorme bola de Lumina en la misma dirección también.",
  ui_story_1022_10220601_15_dialog_content = "¡¿?!",
  ui_story_1022_10220601_16_dialog_content = "Los Espectros son nuestro enemigo común. Eso es todo lo que tengo que decir.",
  ui_story_1022_10220601_17_dialog_content = "Tú... Hmph.",
  ui_story_1022_10220601_18_dialog_content = "También quiero encontrar a Pepita, capitán... No para castigarla, sino para salvarla.",
  ui_story_1022_10220601_19_dialog_content = "El propósito de nuestra organización es salvar al mundo de fuerzas desconocidas... Y nuestros aliados no son una excepción. Al menos... Así es como me siento.",
  ui_story_1022_10220601_20_dialog_content = "Erica... Has demostrado ser más tranquilo y sabio de lo que pensaba anteriormente. Yo, por otro lado...",
  ui_story_1022_10220601_21_dialog_content = "Perdóname, Lady Carleen... Y a todos ustedes también. Dejé que mi venganza nublara mi razón, y por eso debo disculparme.",
  ui_story_1022_10220601_22_dialog_content = "Es solo que... ¡Siempre que incluso pienso en el True Order, yo—!",
  ui_story_1022_10220601_23_dialog_content = "Nadie te pide que dejes tu rencor de inmediato. Incluso los mejores de nosotros tendríamos problemas para hacer eso.",
  ui_story_1022_10220601_24_dialog_content = "Pero la venganza no puede costar tu propia vida... Por eso decidimos formar este equipo y cuidarnos mutuamente, ¿verdad?",
  ui_story_1022_10220601_25_dialog_content = "Yo...",
  ui_story_1022_10220601_26_dialog_content = "Ahora, pongámonos en marcha. ¡Vamos a marchar juntos hacia la guarida de Ursura!",
  ui_story_1022_10220601_27_dialog_content = "<color=#e8d9bb>Siguiendo la guía del Resonador de la Noche Blanca, el equipo finalmente descubre una vasta extensión de tierra llena de plantas coloridas y distorsionadas.</color>",
  ui_story_1022_10220601_28_dialog_content = "Vaya, este lugar...",
  ui_story_1022_10220601_29_dialog_content = "Es tan extraño, y aún así tan impresionantemente hermoso... Tengo un mal presentimiento sobre esto...",
  ui_story_1022_10220601_30_dialog_content = "Parece que estamos en el camino correcto. Los subordinados de Pepita mencionaron algo sobre descubrir una tierra de coral.",
  ui_story_1022_10220601_31_dialog_content = "La influencia de Ursura puede ser la fuente de este paisaje distorsionado.",
  ui_story_1022_10220601_32_dialog_content = "... Ahora clasificando esta área como \"<color=#FFB400>Sector 44 Inexplorado</color>.\"",
  ui_story_1022_10220601_33_dialog_content = "Ven conmigo, PlayerName. Hay algo que me gustaría preguntarte.",
  ui_story_1022_10220601_34_dialog_content = "Qué es, Carleen?",
  ui_story_1022_10220601_35_dialog_content = "¿Dices que puedes sentir una enorme bola de Lumina en algún lugar de aquí, sí?",
  ui_story_1022_10220601_36_dialog_content = "¿Es posible que uno de nuestros artefactos sea la fuente de esa Lumina?",
  ui_story_1022_10220601_37_dialog_content = "¿Eh? ¿T-Tú te refieres al que el Resonador de la Noche Blanca está detectando?!",
  ui_story_1022_10220601_38_dialog_content = "Supongo que no puedo descartarlo completamente, pero algo me dice que ese no es el caso...",
  ui_story_1022_10220601_39_dialog_content = "Realmente no puedo explicar por qué me siento así. Llámalo un instinto visceral, pero hay algo cálido y familiar en esa bola de Lumina...",
  ui_story_1022_10220601_40_dialog_content = "Ya veo... Eso es todo lo que necesitaba preguntar. Regresemos.",
  ui_story_1022_10220601_41_dialog_content = "¿Estás bien, Carleen? Parece que... Estás cargando algún tipo de carga.",
  ui_story_1022_10220601_42_dialog_content = "Definitivamente lo soy, dado que soy parte de la delegación de Lumopolis a la Zona Oscura...",
  ui_story_1022_10220601_43_dialog_content = "... Pero quizás solo estoy siendo demasiado impaciente. Después de todo lo que ha pasado, tal vez solo quiero lograr algo.",
  ui_story_1022_10220601_44_dialog_content = "En lugar de sentirme como una bestia atrapada en la oscuridad.",
  ui_story_1022_10220601_45_dialog_content = "Pero tienes razón, no debería tener tanta prisa.",
  ui_story_1022_10220601_46_option_content = "¡No he dicho nada todavía!",
  ui_story_1022_10220601_47_dialog_content = "¡Pero ibas a hacerlo, verdad?!",
  ui_story_1022_10220601_48_dialog_content = "Eh, ¡s-sí! ¡Por supuesto!",
  ui_story_1022_10220601_49_option_content = "Está bien sentirse así.",
  ui_story_1022_10220601_50_dialog_content = "Entiendo totalmente tu inquietud... Porque me siento exactamente de la misma manera.",
  ui_story_1022_10220601_51_dialog_content = "... Gracias. Eso me reconforta más que cualquier otra cosa que pudieras haber dicho.",
  ui_story_1022_10220601_52_dialog_content = "¿Mmm? Algo parece estar pasando por allí. ¡Vamos!",
  ui_story_1022_10220601_53_dialog_content = "Mi mal presentimiento sobre este lugar solo se está volviendo más fuerte... Un dios del mal debe haber descendido sobre este lugar...",
  ui_story_1022_10220601_54_dialog_content = "¡¿Cuerpos?! Espera, ¿son estos... Aurorianos?!",
  ui_story_1022_10220601_55_dialog_content = "No se parecen del todo a ellos... Pero tampoco se parecen a los Eclipsites. ¿Qué son?",
  ui_story_1022_10220601_56_dialog_content = "... Estas criaturas son similares a los Aurorianos, en el sentido de que hay débiles rastros de Lumina en sus cuerpos.",
  ui_story_1022_10220601_57_dialog_content = "Sin embargo, parece que el Lumina ha sido completamente drenado de ellos.",
  ui_story_1022_10220601_58_dialog_content = "¿Quién o qué podría hacer algo tan horrible?! Matarlos así es...",
  ui_story_1022_10220601_59_dialog_content = "Yo también lo pensé, pero luego eché un vistazo más de cerca.",
  ui_story_1022_10220601_60_dialog_content = "La causa de su muerte no fue que su Lumina fuera absorbida. De hecho, parecen haber vivido durante un período prolongado de tiempo en este estado.",
  ui_story_1022_10220601_61_dialog_content = "Pero cómo... ¿Cómo pueden los Aurorianos sobrevivir sin su Lumina?",
  ui_story_1022_10220601_62_dialog_content = "Cadáveres aurorianos despojados de Lumina y un artefacto robado de Lumopolis...",
  ui_story_1022_10220601_63_dialog_content = "... ¡Malditos sean estos asquerosos Eclipsites! ¿Cómo se atreven a corromper a los nuestros de esta manera?!",
  ui_story_1022_10220601_64_dialog_content = "¿Alguna vez te ocurrió pensar que tal vez ustedes, los Aurorians, son los que han estado robando al Eclipse todo este tiempo?",
  ui_story_1022_10220601_65_dialog_content = "Como los lugares que llamas hogar...",
  ui_story_1022_10220601_66_dialog_content = "¡¡!!",
  ui_story_1022_10220601_67_dialog_content = "¿Qué te pasa, PlayerName?",
  ui_story_1022_10220601_68_dialog_content = "... No es nada.",
  ui_story_1022_10220601_69_dialog_content = "(¿Estoy imaginando cosas, o escuché una voz débil llamando hace un momento...?)",
  ui_story_1022_10220701_1_dialog_content = "Todos estas personas murieron al mismo tiempo.",
  ui_story_1022_10220701_2_dialog_content = "También hay extraños fragmentos de metal dispersos entre los corales... ¿Qué exactamente ocurrió aquí?",
  ui_story_1022_10220701_3_dialog_content = "Podría ser capaz de responder eso.",
  ui_story_1022_10220701_4_dialog_content = "... Contamos contigo.",
  ui_story_1022_10220701_5_dialog_content = "Simplemente no te esfuerces demasiado, PlayerName.",
  ui_story_1022_10220701_6_option_content = "Escaneo psíquico",
  ui_story_1022_10220701_7_dialog_content = "¿¡Eh?! ¿Qué... Es esto...?",
  ui_story_1022_10220701_8_dialog_content = "<color=#e8d9bb>El rugido ensordecedor de maquinaria pesada llena el aire.</color>",
  ui_story_1022_10220701_9_dialog_content = "<color=#e8d9bb>La tierra tiembla a raíz de su movimiento.</color>",
  ui_story_1022_10220701_10_dialog_content = "<color=#e8d9bb>Innumerables máquinas extrañas surcan los cielos, intercaladas con hermosos y retorcidos corales y plantas.</color>",
  ui_story_1022_10220701_11_dialog_content = "<color=#e8d9bb>Una escena mucho más sorprendente en comparación con el tranquilo campo de coral visto anteriormente.</color>",
  ui_story_1022_10220701_12_dialog_content = "(Los fragmentos de metal que Hiiro encontró deben haber venido de estas máquinas.)",
  ui_story_1022_10220701_13_dialog_content = "(¿Estoy mirando... El campo de coral <color=#FFB400>en el pasado</color>?)",
  ui_story_1022_10220701_14_dialog_content = "(¡Ah! ¡Los que pilotan esas máquinas son los seres parecidos a los Aurorianos que vimos antes! ¿Han estado viviendo aquí todo el tiempo?)",
  ui_story_1022_10220701_15_dialog_content = "<color=#e8d9bb>La serenidad de estas tierras solo puede apreciarse en presencia de criaturas vivientes.</color>",
  ui_story_1022_10220701_16_dialog_content = "<color=#e8d9bb>Aparte del zumbido interminable de sus máquinas, el campo de coral está completamente silencioso.</color>",
  ui_story_1022_10220701_17_dialog_content = "(No hay comunicación entre ellos, y sus acciones y expresiones son tan rígidas. Es como si solo estuvieran pasando por los movimientos de su trabajo.)",
  ui_story_1022_10220701_18_dialog_content = "(Me recuerdan a los Eclipsites de bajo nivel... Entonces, ¿por qué se parecen más a los Aurorianos por fuera?)",
  ui_story_1022_10220701_19_dialog_content = "Jeje... Después de todos estos años, parece que somos los únicos aún capaces de hablar.",
  ui_story_1022_10220701_20_dialog_content = "(¡Gah! Dios... ¡No esperaba escuchar a ninguno de ellos hablar!)",
  ui_story_1022_10220701_21_dialog_content = "Desde que nací, este lugar no ha cambiado. Aparte de las máquinas, lo único que hay aquí son esos vacíos y silenciosos cascarones de personas...",
  ui_story_1022_10220701_22_dialog_content = "Apenas puedo distinguirlos ya.",
  ui_story_1022_10220701_23_dialog_content = "¿Pero por qué estamos malditos a vivir así?",
  ui_story_1022_10220701_24_dialog_content = "¿Por qué no podemos dejar esta tierra de muerte y ver el mundo exterior?",
  ui_story_1022_10220701_25_dialog_content = "¡Es imposible!",
  ui_story_1022_10220701_26_dialog_content = "Cuando era joven, conocí a algunas personas como nosotros que intentaron escapar...",
  ui_story_1022_10220701_27_dialog_content = "Entonces, ¿qué pasó? ¿Los volviste a ver alguna vez?",
  ui_story_1022_10220701_28_dialog_content = "No. Murieron... Todos ellos.",
  ui_story_1022_10220701_29_dialog_content = "¡¿?!",
  ui_story_1022_10220701_30_dialog_content = "Hay un lugar fuera de donde vivimos. Es como un horno ardiente, y quemó a cada uno de ellos hasta convertirlos en cenizas.",
  ui_story_1022_10220701_31_dialog_content = "Nadie ha intentado irse desde entonces. Incluso aquellos que se alejan un poco demasiado de este lugar nunca se vuelven a ver.",
  ui_story_1022_10220701_32_dialog_content = "¿Pero por qué...? ¿Realmente no hay esperanza para nosotros? ¿Estamos realmente destinados a morir aquí?",
  ui_story_1022_10220701_33_dialog_content = "Qué destino tan cruel...",
  ui_story_1022_10220701_34_dialog_content = "¡¿?!",
  ui_story_1022_10220701_35_dialog_content = "(¡Ah! ¡Están mirándome directamente!)",
  ui_story_1022_10220701_36_dialog_content = "H-Hola allí...?",
  ui_story_1022_10220701_37_dialog_content = "¿Un forastero? Ugh, estoy tan celoso.",
  ui_story_1022_10220701_38_dialog_content = "¿Qué te trae a este lugar condenado? No hay nada aquí excepto máquinas y coral.",
  ui_story_1022_10220701_39_dialog_content = "Oh, y hagas lo que hagas, no comas el coral. Convertirá tu sangre en este desagradable color blanco lechoso.",
  ui_story_1022_10220701_40_dialog_content = "Justo como los nuestros.",
  ui_story_1022_10220701_41_dialog_content = "<color=#e8d9bb>La criatura similar a un Aurorian muestra una sonrisa autodespreciativa.</color>",
  ui_story_1022_10220701_42_dialog_content = "¿Comer el coral hará que mi sangre se vuelva blanca? Ya veo... Gracias por la advertencia.",
  ui_story_1022_10220701_43_dialog_content = "¿Pero no hay nada más para comer por aquí?",
  ui_story_1022_10220701_44_dialog_content = "Para nada. Solo coral, coral, y más maldito coral...",
  ui_story_1022_10220701_45_dialog_content = "Este lugar está maldito, te lo digo. Cada día, aparecen nuevos corales y líquenes.",
  ui_story_1022_10220701_46_dialog_content = "Las máquinas no pueden seguir funcionando correctamente si no las limpiamos a tiempo.",
  ui_story_1022_10220701_47_dialog_content = "Especialmente esa horno. Pase lo que pase, no podemos dejar que se detenga.",
  ui_story_1022_10220701_48_dialog_content = "Para pasar nuestras vidas esclavizadas en las malas hierbas, manteniendo una caldera viva sin una pizca de dignidad... Debemos estar malditos también.",
  ui_story_1022_10220701_49_dialog_content = "... Aparte de mí, ¿ha pasado alguien más por aquí? Como... ¿Un Eclipsite?",
  ui_story_1022_10220701_50_dialog_content = "Un Fantasma aparece de vez en cuando, ¿verdad?",
  ui_story_1022_10220701_51_dialog_content = "Eso es correcto. Su nombre es Yodu.",
  ui_story_1022_10220701_52_dialog_content = "¿Un Fantasma?!",
  ui_story_1022_10220701_53_dialog_content = "Él es el que nos va a matar.",
  ui_story_1022_10220701_54_dialog_content = "Él es el que nos va a matar.",
  ui_story_1022_10220701_55_dialog_content = "Él es el que nos va a matar.",
  ui_story_1022_10220701_56_dialog_content = "¡¿?!",
  ui_story_1022_10220701_57_dialog_content = "Un día, cuando piense que ya no somos útiles para él, va a matarnos a todos sin dejar a ninguno.",
  ui_story_1022_10220701_58_dialog_content = "Pero después de estar atrapados aquí toda nuestra vida, bien podríamos haber muerto hace mucho tiempo.",
  ui_story_1022_10220701_59_dialog_content = "Atrapados aquí toda nuestra vida.",
  ui_story_1022_10220701_60_dialog_content = "Atrapados aquí toda nuestra vida.",
  ui_story_1022_10220701_61_dialog_content = "...!!!",
  ui_story_1022_10220701_62_dialog_content = "¿Qué pasa, PlayerName? Te has puesto completamente pálido.",
  ui_story_1022_10220701_63_dialog_content = "Yo... Solo sentí los pensamientos persistentes de las personas que murieron aquí.",
  ui_story_1022_10220701_64_dialog_content = "...",
  ui_story_1022_10220701_65_dialog_content = "¿Hasta el día de hoy, sus almas todavía están atrapadas aquí? May encuentren la paz algún día.",
  ui_story_1022_10220701_66_dialog_content = "¿Así que un Fantasma llamado Yodu fue responsable de sus muertes? Imperdonable...",
  ui_story_1022_10220701_67_dialog_content = "Eso es correcto, y el poder de Ursura no es nada comparado con el suyo.",
  ui_story_1022_10220701_68_dialog_content = "Esa es una forma de pensar peligrosa. Todos los Espectros deben ser tratados como amenazas altamente peligrosas, tú lo sabes.",
  ui_story_1022_10220701_69_dialog_content = "¡Lo siento!",
  ui_story_1022_10220701_70_dialog_content = "No lo seas. Solo quiero que estés alerta cuando la situación lo requiera.",
  ui_story_1022_10220701_71_dialog_content = "Por lo que viste en tus visiones, es seguro asumir que esto fue una base de investigación en el pasado—",
  ui_story_1022_10220701_72_dialog_content = "Los trabajadores eran estas criaturas similares a los Aurorianos, y su supervisor era Yodu el Fantasma.",
  ui_story_1022_10220701_73_dialog_content = "Sí... Estaba pensando en la misma línea.",
  ui_story_1022_10220701_74_dialog_content = "Con la excepción de unas pocas personas, los trabajadores estaban completamente carentes de pensamiento, emoción e incluso de habla.",
  ui_story_1022_10220701_75_dialog_content = "Su tarea principal era mantener las máquinas en funcionamiento eliminando corales, musgos y otros crecimientos biológicos.",
  ui_story_1022_10220701_76_dialog_content = "Y al parecer, la máquina más importante era una especie de horno.",
  ui_story_1022_10220701_77_dialog_content = "¿Pero por qué cosas como el coral y el musgo siguen creciendo aquí? ¿Podría tener algo que ver con Ursura?",
  ui_story_1022_10220701_78_dialog_content = "Es posible que estas cosas crezcan dondequiera que Ursura vaya.",
  ui_story_1022_10220701_79_dialog_content = "Si eso es cierto, entonces ella también debió haber estado cerca de la base de investigación en aquel entonces. Incluso podría estar conectada con Yodu de alguna manera.",
  ui_story_1022_10220701_80_dialog_content = "Lo cual es aún más razón para verla como una amenaza seria...",
  ui_story_1022_10220701_81_dialog_content = "Y sin embargo, ella y Pepita de alguna manera se convirtieron en amigos incondicionales. Seguramente no la lastimaría por eso...",
  ui_story_1022_10220701_82_dialog_content = "... En este punto, no estoy seguro si descubrir este lugar Pepita fue algo bueno o no.",
  ui_story_1022_10220701_83_dialog_content = "Perdón, pero ¿puedo intervenir?",
  ui_story_1022_10220701_84_dialog_content = "¿Qué es?",
  ui_story_1022_10220701_85_dialog_content = "En caso de que alguien no lo haya notado, el Darkflow aquí es inusualmente escaso. Es como si ni siquiera estuviéramos en la Zona Oscura en absoluto.",
  ui_story_1022_10220701_86_dialog_content = "¿Podría ser que el artefacto detectado por el Resonador de la Noche Blanca... está repeliendo el darkflow circundante al igual que nuestras <color=#FFB400>Piedras Lumina</color>?",
  ui_story_1022_10220701_87_dialog_content = "Tienes razón...! Pero no lo sabremos a menos que sigamos buscando.",
  ui_story_1022_10220701_88_dialog_content = "Ursura no puede estar demasiado lejos de nosotros ahora. Mantente en guardia.",
  ui_story_1022_10220800_1_dialog_content = "<color=#e8d9bb>En lo profundo del bosque de coral, Pepita está perdida en sus pensamientos mientras contempla el retorcido paisaje.</color>",
  ui_story_1022_10220800_2_dialog_content = "Entonces, ¿has pensado en lo que dije, Pepita?",
  ui_story_1022_10220800_3_dialog_content = "... Oh, estás de vuelta. ¿Qué está pasando ahí fuera?",
  ui_story_1022_10220800_4_dialog_content = "No hay nada de qué preocuparse, solo un par de hormigas molestas. La poderosa Ursura tiene cosas mejores que hacer que perder su tiempo con ellas.",
  ui_story_1022_10220800_5_dialog_content = "Tú, por otro lado, me debes una respuesta.",
  ui_story_1022_10220800_6_dialog_content = "Solo asiente con la cabeza, y usaré el coral para hacerte un corazón completamente nuevo.",
  ui_story_1022_10220800_7_dialog_content = "Y a cambio... ¿Tengo que quedarme aquí y jugar contigo para siempre?",
  ui_story_1022_10220800_8_dialog_content = "No estarías jugando \"con\"migo, estaríamos jugando \"juntos\"! También quieres eso, ¿no es así? Después de todo, nos divertimos más cuando estamos juntos!",
  ui_story_1022_10220800_9_dialog_content = "Tienes razón. Estar aquí es muy divertido, y es raro para mí encontrar a alguien tan loco como yo.",
  ui_story_1022_10220800_10_dialog_content = "¡Exactamente! Así que solo di la palabra, ¡y comenzaré con tu nuevo corazón!",
  ui_story_1022_10220800_11_dialog_content = "Una vez que lo haga, tu sangre cambiará de ese molesto tono de rojo a un blanco puro y noble como el mío. ¡Entonces puedes quedarte aquí para siempre!",
  ui_story_1022_10220800_12_dialog_content = "... Ursura.",
  ui_story_1022_10220800_13_dialog_content = "¿¡Sí!?",
  ui_story_1022_10220800_14_dialog_content = "¿Recuerdas lo que pasó cuando nos conocimos por primera vez, verdad?",
  ui_story_1022_10220800_15_dialog_content = "... ¿Eh? ¿Por qué estás desenterrando el pasado de repente?",
  ui_story_1022_10220800_16_dialog_content = "...",
  ui_story_1022_10220800_17_dialog_content = "(¿Qué... Qué está pasando? ¿Dónde estoy...?)",
  ui_story_1022_10220800_18_dialog_content = "Graaah!!",
  ui_story_1022_10220800_19_dialog_content = "Uf... uf... ¡Jajaja... ¿Es todo lo que tienes? ¡Dale!",
  ui_story_1022_10220800_20_dialog_content = "¡Graaah—!",
  ui_story_1022_10220800_21_dialog_content = "¡Urgh! Mi corazón duele de nuevo... Maldita sea... ¡Corazón falso y estúpido!",
  ui_story_1022_10220800_22_dialog_content = "(Si tan solo tuviera un corazón real y saludable... Nada de esto estaría sucediendo...)",
  ui_story_1022_10220800_23_dialog_content = "(Lo recuerdo ahora. Vine a explorar la Zona Oscura con la Verdadera Orden, pero me separé por mi cuenta y fui emboscado por un grupo de Eclipsites.)",
  ui_story_1022_10220800_24_dialog_content = "(Y gracias a mi estúpido y defectuoso corazón, no fui lo suficientemente fuerte para evitar ser capturado...)",
  ui_story_1022_10220800_25_dialog_content = "(Muriendo porque jugué demasiado... Eso es muy típico de mí, ¿verdad? Je... Jeje...)",
  ui_story_1022_10220800_26_dialog_content = "... ¡Jajajaja!",
  ui_story_1022_10220800_27_dialog_content = "¿Qué está pasando? Me desperté de mi largo, largo sueño pensando que había un Aurorian cerca.",
  ui_story_1022_10220800_28_dialog_content = "Pero en cambio encuentro a algún maniaco riendo histéricamente en el suelo.",
  ui_story_1022_10220800_29_dialog_content = "¡¿Quién está ahí?!",
  ui_story_1022_10220800_30_dialog_content = "Pero está bien, vuélvete tan loco como quieras. Después de todo, tu corazón y sangre—",
  ui_story_1022_10220800_31_dialog_content = "<color=#FFB400>¡Pertenece a mí ahora!</color>",
  ui_story_1022_10220800_32_dialog_content = "<color=#e8d9bb>Un Eclipsite que se parece a una pequeña niña sonríe diabólicamente, revelando sus afilados colmillos.</color>",
  ui_story_1022_10220800_33_dialog_content = "<color=#e8d9bb>Un escalofrío recorre la espalda de Pepita al ver la cruel sonrisa de la pequeña niña.</color>",
  ui_story_1022_10220800_34_dialog_content = "Jaja...",
  ui_story_1022_10220800_35_dialog_content = "¿¡Sigues riendo?! ¿Qué tiene de gracioso todo esto, eh? ¿No sabes que estás a punto de convertirte en la próxima comida del gran Ursura?!",
  ui_story_1022_10220800_36_dialog_content = "Lo siento, simplemente me parece gracioso que una pequeña niña con colmillos de demonio piense que yo soy el loco aquí.",
  ui_story_1022_10220800_37_dialog_content = "¿Q-Qué sabrías tú?! ¡Mis colmillos son un símbolo de mi noble nacimiento, muchas gracias!",
  ui_story_1022_10220800_38_dialog_content = "¿Nacimiento noble? Suena bastante bien, pero ¿no te convierte eso simplemente en un monstruo cursi y chupasangre?",
  ui_story_1022_10220800_39_dialog_content = "¡Cuando termine de drenar la vida de ti, vas a parecer cuero barato!",
  ui_story_1022_10220800_40_dialog_content = "¡Jajaja! Ay hombre, esto es simplemente demasiado loco!",
  ui_story_1022_10220800_41_dialog_content = "Por lo general, la gente no puede dejar de comprarme comida y bebidas a donde quiera que vaya. ¡Ese es el tipo de respeto que exijo en el mundo!",
  ui_story_1022_10220800_42_dialog_content = "¡Pero esta es la primera vez que alguien se ofrece a chupar mi sangre! Tienes una forma divertida de mostrar tu admiración, ¿sabes eso?",
  ui_story_1022_10220800_43_dialog_content = "\"¡Admiración,\" mi trasero! La única persona que admiro es mi abuelo, ¿entendido?!",
  ui_story_1022_10220800_44_dialog_content = "¡Voy a beber hasta la última gota de tu sangre y convertirte en mi esclavo eterno! Veremos quién se ríe después de eso, ¡imbécil!",
  ui_story_1022_10220800_45_dialog_content = "¿Esclavo...?",
  ui_story_1022_10220800_46_dialog_content = "Mmm, finalmente te tengo asustado, ¿eh? ¡Bien! Sabrás aún mejor una vez que te tenga rogando por piedad.",
  ui_story_1022_10220800_47_dialog_content = "Sí... No, gracias.",
  ui_story_1022_10220800_48_dialog_content = "¡¿Qué?! ¿Cu-Cuándo me lo quitaste? ¡Devuélveme eso!",
  ui_story_1022_10220800_49_dialog_content = "Mátame si quieres, pero no te dejaré convertirme en tu esclavo.",
  ui_story_1022_10220800_50_dialog_content = "<color=#FFB400>¡Si no soy libre, prefiero estar muerto!</color>",
  ui_story_1022_10220800_51_dialog_content = "<color=#e8d9bb>Pepita recoge un trozo de coral afilado y se lo clava en su propio pecho, salpicando sangre roja brillante a su alrededor.</color>",
  ui_story_1022_10220800_52_dialog_content = "¡...!",
  ui_story_1022_10220800_53_dialog_content = "Urgh... Sangre... Asquerosa, sangre roja... ¡¡¡Ahhhhhh—!!!",
  ui_story_1022_10220800_54_dialog_content = "Graaah!!",
  ui_story_1022_10220800_55_dialog_content = "¡Sálvanos!",
  ui_story_1022_10220800_56_dialog_content = "¡Por favor, perdónanos, Señorita Ursura! ¡Perdona nuestras vidas miserables!!",
  ui_story_1022_10220800_57_dialog_content = "¡Yo... Yo odio ver sangre! ¡Asegúrate de que no sangren cuando los estés matando, idiotas!",
  ui_story_1022_10220800_58_dialog_content = "(Eclipsiano) ¡Entendido!",
  ui_story_1022_10220800_59_dialog_content = "Aaaaaahhh!!!",
  ui_story_1022_10220800_60_dialog_content = "¡Urk! ¿N-No te dije que no los dejaras sangrar? Son mis nuevos amigos, ¡así que presta atención cuando te digo cosas así!",
  ui_story_1022_10220800_61_dialog_content = "(Eclipsian) ¡Sí, Lady Ursura! Haremos todo lo posible...",
  ui_story_1022_10220800_62_dialog_content = "Tch, ustedes son puro bla bla bla...",
  ui_story_1022_10220800_63_dialog_content = "Tengo que mantenerme fuerte... Mi nuevo dios es incluso más grande que el llamado Señor de la Verdad...",
  ui_story_1022_10220800_64_dialog_content = "¡Desciende a nuestro mundo y límpialo, mi señor!",
  ui_story_1022_10220800_65_dialog_content = "Ngh... Debo haber estado dormido demasiado tiempo... Casi lo olvido...",
  ui_story_1022_10220800_66_dialog_content = "¡Ya he sido bendecido con un anillo del Eclipse. Ya no necesito beber sangre, por eso ahora no puedo soportar ni verla!",
  ui_story_1022_10220800_67_dialog_content = "*Sollozando* Beberlo, bañarme en él... ¡Nada de eso me hace feliz ahora! ¡Abuelo!",
  ui_story_1022_10220800_68_dialog_content = "(Ella está llorando histéricamente de repente... Se ve tan triste, llamando a su abuelo así.)",
  ui_story_1022_10220800_69_dialog_content = "(¿Qué tipo de hombre la dejaría sola aquí? Probablemente alguien como mi inútil excusa de padre.)",
  ui_story_1022_10220800_70_dialog_content = "E-Eh, ¿estás bien? Tos, tos... Oh cierto, soy yo el que tiene un problema aquí... Jeje.",
  ui_story_1022_10220800_71_dialog_content = "¡Por supuesto que estoy bien! ¿¡Por qué no lo estaría?!",
  ui_story_1022_10220800_72_dialog_content = "¡Urgh! ¿Q-Qué estás intentando hacerme ahora...?",
  ui_story_1022_10220800_73_dialog_content = "¡D-No pienses que puedes detenerme sangrando por todas partes! ¡P-Puedo ver y beber sangre perfectamente bien!",
  ui_story_1022_10220800_74_dialog_content = "¡Ey! Deja de lamer mi herida así, ¡tú monstruo...!",
  ui_story_1022_10220800_75_dialog_content = "Ugh... Tan asqueroso...",
  ui_story_1022_10220800_76_dialog_content = "<color=#e8d9bb>Aparece una lágrima blanca como la leche en la esquina del ojo de Ursura.</color>",
  ui_story_1022_10220800_77_dialog_content = "Si es tan asqueroso, entonces simplemente deténgalo ya—",
  ui_story_1022_10220800_78_dialog_content = "Ngh... ¡Arrrgh— Gaaaaahhhh!",
  ui_story_1022_10220800_79_dialog_content = "<color=#e8d9bb>De repente, como si fuera tocada por algún tipo de poder primordial, Ursura comienza a gritar y convulsionar mientras más lágrimas blancas fluyen de sus ojos.</color>",
  ui_story_1022_10220800_80_dialog_content = "¡¿E-Es realmente tan malo?!",
  ui_story_1022_10220800_81_dialog_content = "¡Graaaaagh!",
  ui_story_1022_10220800_82_dialog_content = "(¡E-Ella está perdiendo el control! Tengo que salir de aquí, pero... Maldición, he perdido demasiada sangre!)",
  ui_story_1022_10220800_83_dialog_content = "P... Petey... ¡Hora de hacer lo tuyo!",
  ui_story_1022_10220800_84_dialog_content = "¿Una muñeca? Urgh...",
  ui_story_1022_10220800_85_dialog_content = "<color=#e8d9bb>A pesar de que su cuerpo entero temblaba violentamente, Ursura logra invocar una pequeña muñeca gris para arrastrarla lejos.</color>",
  ui_story_1022_10220800_86_dialog_content = "<color=#e8d9bb>¡¡Boom!! Mientras las lágrimas blancas caen al suelo donde Pepita está acostado, explotan con una fuerza destructiva sorprendentemente.</color>",
  ui_story_1022_10220800_87_dialog_content = "(¿Ella está... Salvándome?)",
  ui_story_1022_10220800_88_dialog_content = "(¿Qué le está pasando de todos modos? ¿No le harán daño también esas explosiones? Maldita sea... Ya no puedo abrir los ojos. Definitivamente me excedí.)",
  ui_story_1022_10220800_89_dialog_content = "(¿Es hoy... El día que finalmente muero?)",
  ui_story_1022_10220800_90_dialog_content = "<color=#e8d9bb>Después de mucho tiempo...</color>",
  ui_story_1022_10220800_91_dialog_content = "...",
  ui_story_1022_10220800_92_dialog_content = "(¿Todavía estoy vivo, huh? Supongo que no debería sorprenderme...)",
  ui_story_1022_10220800_93_dialog_content = "¿Qué pasa con ese corazón tuyo?",
  ui_story_1022_10220800_94_dialog_content = "Ursura...",
  ui_story_1022_10220800_95_dialog_content = "No es tu corazón original. ¿Es esa tecnología de Illumina?",
  ui_story_1022_10220800_96_dialog_content = "... ¿Por qué me salvaste?",
  ui_story_1022_10220800_97_dialog_content = "Cuando me convertí en parte de Eclipse, pensé que finalmente tendría amigos que nunca me defraudarían.",
  ui_story_1022_10220800_98_dialog_content = "Pero todos resultaron ser un montón de gusanos inútiles. Una dama noble como yo merece algo mucho mejor.",
  ui_story_1022_10220800_99_dialog_content = "Pero tú... Estás bien.",
  ui_story_1022_10220800_100_dialog_content = "<size=30>Incluso te preocupas por mí.</size>",
  ui_story_1022_10220800_101_dialog_content = "Jaja...",
  ui_story_1022_10220800_102_dialog_content = "¡Deja de reír!",
  ui_story_1022_10220800_103_dialog_content = "¿Y qué, me estás reconociendo o algo así?",
  ui_story_1022_10220800_104_dialog_content = "¿Y qué tiene de malo eso? ¡Deberías sentirte honrado, sabes! ¡La mayoría de las personas estarían bailando y gritando a todo pulmón por algo como esto!",
  ui_story_1022_10220800_105_dialog_content = "No importa cuán buen corazón te haga Illumina, porque siempre estarás bajo su control.",
  ui_story_1022_10220800_106_dialog_content = "¡Pero puedo hacerte un corazón completamente nuevo, uno que puedas llamar totalmente tuyo!",
  ui_story_1022_10220800_107_dialog_content = "¿Recuerdas cómo te respondí en aquel entonces?",
  ui_story_1022_10220800_108_dialog_content = "¡Por supuesto! Dijiste, \"No gracias, todavía quiero aguantar esto un poco más.\"",
  ui_story_1022_10220800_109_dialog_content = "¡Y sin embargo, aquí estás a mi lado una vez más! Es curioso cómo funciona eso, ¿eh?",
  ui_story_1022_10220800_110_dialog_content = "Nunca conseguirás lo que quieres confiando en este corazón, Pepita.",
  ui_story_1022_10220800_111_dialog_content = "¡Por supuesto que no! Sé de primera mano lo malo que es este corazón falso.",
  ui_story_1022_10220800_112_dialog_content = "<color=#e8d9bb>He maldecido este corazón tantas veces, y deseado que pudiera tener uno perfecto en su lugar.</color>",
  ui_story_1022_10220800_113_dialog_content = "<color=#e8d9bb>Un corazón fuerte y saludable que nadie podría controlar. Uno que me permitiría luchar tanto como quisiera sin cansarme nunca. Ese es el tipo de corazón que siempre he querido.</color>",
  ui_story_1022_10220800_114_dialog_content = "<color=#e8d9bb>Por eso todavía vine aquí, a pesar de que sabía que Ursura impondría algún tipo de condición.</color>",
  ui_story_1022_10220800_115_dialog_content = "<color=#e8d9bb>Porque a diferencia de Belisaria, que siempre me menosprecia, al menos Ursura me trata como su igual.</color>",
  ui_story_1022_10220800_116_dialog_content = "<color=#e8d9bb>En cuanto a su condición—</color>",
  ui_story_1022_10220800_117_dialog_content = "<color=#FFB400>\"Quedarse aquí para siempre.\"</color>",
  ui_story_1022_10220800_118_dialog_content = "<color=#e8d9bb>En cuanto la escuché decirlo, mi estado de ánimo cambió completamente. Mientras miraba el paisaje congelado y los corales retorcidos que crecían de él, el mismo pensamiento se repetía una y otra vez en mi cabeza.</color>",
  ui_story_1022_10220800_119_dialog_content = "<color=#e8d9bb>\"¿Es esto realmente lo que será el resto de mi vida?\"</color>",
  ui_story_1022_10220800_120_dialog_content = "<color=#e8d9bb>... No.</color>",
  ui_story_1022_10220800_121_dialog_content = "<color=#e8d9bb>El mundo es un lugar tan enorme.</color>",
  ui_story_1022_10220800_122_dialog_content = "<color=#e8d9bb>Y todavía no he tenido la oportunidad de ver mis campos de verde.</color>",
  ui_story_1022_10220800_123_dialog_content = "Mi respuesta es la misma que era antes.",
  ui_story_1022_10220800_124_dialog_content = "Gracias, pero no gracias, Ursura.",
  ui_story_1022_10220800_125_dialog_content = "Todavía quiero aguantar esto un poco más de tiempo.",
  ui_story_1022_10220901_1_dialog_content = "¡Me engañaste!",
  ui_story_1022_10220901_2_dialog_content = "Lo sé, y lo siento mucho! Pero aún nos divertimos mucho juntos, ¿verdad?",
  ui_story_1022_10220901_3_dialog_content = "Pero es mejor si no estamos juntos todos los días de nuestras vidas, ¿no crees? Después de todo, dicen que un poco de distancia hace que las amistades sean aún más preciadas!",
  ui_story_1022_10220901_4_dialog_content = "...",
  ui_story_1022_10220901_5_dialog_content = "Búscalo.",
  ui_story_1022_10220901_6_dialog_content = "(Eclipsiano) ¡Entendido!",
  ui_story_1022_10220901_7_dialog_content = "¿Eh? ¿A quién buscar? No es como si tuviera parientes para que secuestres, ¿recuerdas?",
  ui_story_1022_10220901_8_dialog_content = "... ¿Petey?! Ursura... ¿Cuándo lo trajiste de vuelta?",
  ui_story_1022_10220901_9_dialog_content = "Hace un tiempo, en realidad. Simplemente no quería mostrarte porque me importas mucho.",
  ui_story_1022_10220901_10_dialog_content = "¡Pero aunque soy un buen amigo... Sigues intentando dejarme! ¿¡Por qué!?",
  ui_story_1022_10220901_11_dialog_content = "... Ya te dije por qué, ¿no es así?",
  ui_story_1022_10220901_12_dialog_content = "<color=#FFB400>Si no soy libre... ¡Preferiría estar muerto!</color>",
  ui_story_1022_10220901_13_dialog_content = "Graaah...",
  ui_story_1022_10220901_14_dialog_content = "¡Detenla!",
  ui_story_1022_10220901_15_dialog_content = "(Eclipsiano) ¡Haz como manda la Lady Ursura!",
  ui_story_1022_10220901_16_dialog_content = "Graaah!!",
  ui_story_1022_10220901_17_dialog_content = "¿Es todo lo que tienes?",
  ui_story_1022_10220901_18_dialog_content = "Graaah...",
  ui_story_1022_10220901_19_dialog_content = "¡¿Q-Qué crees que estás haciendo?! ¡Morirás a este ritmo!",
  ui_story_1022_10220901_20_dialog_content = "¡Así que llama a tus Eclipsites y déjame ir!",
  ui_story_1022_10220901_21_dialog_content = "Graah...",
  ui_story_1022_10220901_22_dialog_content = "Urgh... Jeje, odio decírtelo Ursura, pero necesitarás secuaces más fuertes si quieres detenerme.",
  ui_story_1022_10220901_23_dialog_content = "¡Lo siento, no puedo quedarme! ¡Adiós-adiós!",
  ui_story_1022_10220901_24_dialog_content = "¡No te atrevas!",
  ui_story_1022_10220901_25_dialog_content = "Ngh...",
  ui_story_1022_10220901_26_dialog_content = "Tu corazón te está doliendo de nuevo, ¿no es así? Ese pedazo de chatarra no es lo suficientemente fuerte como para seguirte el ritmo.",
  ui_story_1022_10220901_27_dialog_content = "¡Deberías conocer tus límites ya!",
  ui_story_1022_10220901_28_dialog_content = "¡Sí, claro!",
  ui_story_1022_10220901_29_dialog_content = "¡Urk...!",
  ui_story_1022_10220901_30_dialog_content = "¡Consíguela, todos ustedes!",
  ui_story_1022_10220901_31_dialog_content = "... ¡Mantente fuera de mi camino!",
  ui_story_1022_10220901_32_dialog_content = "¿¡Has perdido la cabeza!? ¡Tu corazón va a explotar si sigues luchando así!",
  ui_story_1022_10220901_33_dialog_content = "¡Te agotarás antes de que siquiera comience a tomar esta batalla en serio!",
  ui_story_1022_10220901_34_dialog_content = "¡Eso está... Bien para mí!",
  ui_story_1022_10220901_35_dialog_content = "Estoy... ¿Estoy sangrando?",
  ui_story_1022_10220901_36_dialog_content = "Maldito seas... ¡¿Cómo te atreves a hacerme sangrar?! ¡Eso es todo! Si deseas morir tan desesperadamente, ¡permíteme complacerte!!!",
  ui_story_1022_10220901_37_dialog_content = "Arrrgh—!",
  ui_story_1022_10220901_38_dialog_content = "<color=#e8d9bb>Chunda-chunda, chunda-chunda, chunda-chunda, chunda-chunda-</color>",
  ui_story_1022_10220901_39_dialog_content = "<color=#e8d9bb>El latido dentro de su pecho se vuelve aún más salvaje e intenso.</color>",
  ui_story_1022_10220901_40_dialog_content = "<color=#e8d9bb>Su corazón ya no solo late, sino que también retumba furiosamente como un tren al borde del descarrilamiento.</color>",
  ui_story_1022_10220901_41_dialog_content = "<color=#e8d9bb>Cada ola de dolor insoportable es suficiente para desgarrar la mente de cualquiera.</color>",
  ui_story_1022_10220901_42_dialog_content = "<color=#e8d9bb>Pero ella ya no nota el dolor, ni nada más por cierto.</color>",
  ui_story_1022_10220901_43_dialog_content = "<color=#e8d9bb>La claridad de su mente le permite concentrarse completamente en un único pensamiento.</color>",
  ui_story_1022_10220901_44_dialog_content = "Mientras arda lo más brillante posible... ¿Entonces qué tiene de malo morir?",
  ui_story_1022_10220901_45_dialog_content = "No soy la mascota de nadie, y nunca me rendiré a nadie...",
  ui_story_1022_10220901_46_dialog_content = "<color=#FFB400>¡Yo... Me pertenezco a mí mismo!</color>",
  ui_story_1022_10220902_1_dialog_content = "El Resonador de la Noche Blanca está respondiendo cada vez con más intensidad. El artefacto robado debería estar cerca.",
  ui_story_1022_10220902_2_dialog_content = "Em...",
  ui_story_1022_10220902_3_dialog_content = "¡Ahora es aún más fuerte! Nuestro objetivo podría ser un objeto pequeño, así que dispersémonos y busquemos en el área!",
  ui_story_1022_10220902_4_dialog_content = "A veces, las respuestas que buscamos están escondidas a plena vista...",
  ui_story_1022_10220902_5_dialog_content = "Ahora no es el momento para acertijos, Erica. Solo concéntrate en encontrar el artefacto perdido.",
  ui_story_1022_10220902_6_dialog_content = "No era un acertijo, mi lady. Estaba hablando de esa masa de luz sagrada frente a ti...",
  ui_story_1022_10220902_7_dialog_content = "¡¿Qué?!",
  ui_story_1022_10220902_8_dialog_content = "No...",
  ui_story_1022_10220902_9_dialog_content = "¡Deja de reír! Tú tampoco lo notaste, ¿verdad?",
  ui_story_1022_10220902_10_dialog_content = "E-Eso es porque estaba demasiado ocupado observando el Resonador... ¡Pero eso no es importante ahora! Necesitamos confirmar si es o no el artefacto perdido de Lumopolis.",
  ui_story_1022_10220902_11_dialog_content = "La Lumina que está emitiendo es tan pura y relajante...",
  ui_story_1022_10220902_12_dialog_content = "¿Lo encontramos?!",
  ui_story_1022_10220902_13_dialog_content = "No hay duda. Este objeto está disipando el Darkflow en el área circundante.",
  ui_story_1022_10220902_14_dialog_content = "En otras palabras, realmente es una de las reliquias sagradas y perdidas hace mucho tiempo de la Orden Verdadera.",
  ui_story_1022_10220902_15_dialog_content = "Esa voz.",
  ui_story_1022_10220902_16_dialog_content = "Hoy, este objeto sagrado regresa a sus legítimos dueños, y todas las cosas vuelven a sus caminos originales. Tal es el misterio de la obra de nuestro señor.",
  ui_story_1022_10220902_17_dialog_content = "¿Quién te crees que eres?! ¡Suelta el tesoro sagrado de Lumopolis en este instante!",
  ui_story_1022_10220902_18_dialog_content = "No te adelantes, Victoria. Todavía tenemos mucho que discutir, como el paradero de nuestro texto sagrado!",
  ui_story_1022_10220902_19_dialog_content = "Victoria...? ¿¡El líder de la herética Orden Verdadera...?!",
  ui_story_1022_10220902_20_dialog_content = "\"¿Hereje\", dices? Jejeje... Supongo que nuestra noble búsqueda de la Verdad podría ser vista así por las mentes ignorantes del mundo.",
  ui_story_1022_10220902_21_dialog_content = "En cuanto a este artefacto, nunca he tomado nada que no me perteneciera primero. Este objeto fue robado de la ciudad de Varaki por el maestro de este dominio.",
  ui_story_1022_10220902_22_dialog_content = "Las pistas que me llevaron a este lugar me fueron dadas por nada más y nada menos que Pepita, un miembro de nuestra orden.",
  ui_story_1022_10220902_23_dialog_content = "¿Qué encuentras tan irrazonable en mis acciones, Lady Carleen?",
  ui_story_1022_10220902_24_dialog_content = "... ¡Silencio, hereje!",
  ui_story_1022_10220902_25_dialog_content = "Tus palabras traicioneras ya no mancharán a los inocentes...",
  ui_story_1022_10220902_26_dialog_content = "¡¡¡Ahora muere!!!",
  ui_story_1022_10220902_27_dialog_content = "Huff... Huff...",
  ui_story_1022_10220902_28_dialog_content = "(Hay coral a mi alrededor... ¿Eso significa que aún no he escapado?)",
  ui_story_1022_10220902_29_dialog_content = "(Ursura se contuvo hace un momento, pero eso no significa que no cambie de opinión más tarde... Si me atrapa de nuevo, realmente estaré muerto.)",
  ui_story_1022_10220902_30_dialog_content = "(¿Eh? ¿Qué es ese ruido?)",
  ui_story_1022_10220902_31_dialog_content = "¡Gah! Maldiciones... Un vil hereje como tú no debería ser tan poderoso...",
  ui_story_1022_10220902_32_dialog_content = "Tanto odio desenfrenado... Dime, ¿qué hizo el Orden Verdadero para incurrir en tu ira?",
  ui_story_1022_10220902_33_dialog_content = "Esos pasos... ¡Es ella!",
  ui_story_1022_10220902_34_dialog_content = "¿Erica? ¿L-Lady Victoria?! ¿Qué haces aquí? Pensé que Petey fue atrapado antes de que pudiera enviar mi mensaje...",
  ui_story_1022_10220902_35_dialog_content = "El destino siempre encuentra un camino bajo la guía de nuestro señor.",
  ui_story_1022_10220902_36_dialog_content = "Pero veo que estás herido, Pepita. ¿Quién podría haber hecho esto a...? No importa. Parece que ya no hay necesidad de preguntar más.",
  ui_story_1022_10220902_37_dialog_content = "¿A dónde crees que vas, Pepita?! ¡Con toda la sangre que has perdido, deberías haber muerto diez veces ya!",
  ui_story_1022_10220902_38_dialog_content = "¡Realmente me enfadaré si no dejas de correr! ¡Aquí, te mostraré exactamente lo que te haré si no te quedas quieto!",
  ui_story_1022_10220902_39_dialog_content = "¡...!",
  ui_story_1022_10220902_40_dialog_content = "Ven a mí, Pepita.",
  ui_story_1022_10220902_41_dialog_content = "¿Quién te crees que eres, interponiéndote en mi camino?! Espera... E-Eres tú...!",
  ui_story_1022_10220902_42_dialog_content = "No he hecho nada para interponerte. Todo lo que he hecho es quedarme aquí sin moverme.",
  ui_story_1022_10220902_43_dialog_content = "Pepita es quien eligió dejarte y estar a mi lado.",
  ui_story_1022_10220902_44_dialog_content = "Y la persona que la obligó a tomar esta decisión no es otro que tú.",
  ui_story_1022_10220902_45_dialog_content = "Desde el principio, tu mayor obstáculo siempre has sido tú.",
  ui_story_1022_10220902_46_dialog_content = "...",
  ui_story_1022_10220902_47_dialog_content = "Tú... ¡Estás equivocado! Pepita es mío, no tuyo...",
  ui_story_1022_10220902_48_dialog_content = "Los misterios de la Verdad son vastos e insondables. Es natural que te pierdas en la confusión.",
  ui_story_1022_10220902_49_dialog_content = "Pero ten cuidado, porque aquellos que rechazan el conocimiento y abrazan la crueldad y la ignorancia—",
  ui_story_1022_10220902_50_dialog_content = "Algún día se encontrarán perdidos en la noche eterna, un lugar donde incluso la luz de la Verdad no brilla.",
  ui_story_1022_10220902_51_dialog_content = "Yo... Tú... ¡¡¡Waaaaaaaaaaah—!!!",
  ui_story_1022_10220902_52_dialog_content = "<color=#e8d9bb>La amenazante agresión del Fantasma se convierte en un llanto histérico casi al instante. Mientras huye lejos en la distancia, aún se pueden escuchar sus gritos por su abuelo.</color>",
  ui_story_1022_10220902_53_dialog_content = "¿E-Ella empezó a llorar y se escapó?!",
  ui_story_1022_10220902_54_dialog_content = "Jeje... Perdóname, pero ha pasado algún tiempo desde que puse a una niña en su lugar.",
  ui_story_1022_10220902_55_dialog_content = "Ese Fantasma y los Varaki están unidos por el destino hasta cierto punto, pero cuando vi cuánto había lastimado a Pepita, no pude evitarlo.",
  ui_story_1022_10220902_56_dialog_content = "(¿Otro Varaki?!)",
  ui_story_1022_10220902_57_dialog_content = "Quédate quieto, Pepita. Déjame atender tus heridas.",
  ui_story_1022_10220902_58_dialog_content = "Ese emblema... ¿Lo usaste para encontrarme, Lady Victoria?",
  ui_story_1022_10220902_59_dialog_content = "Sí. Este emblema es una creación mía, uno que está inextricablemente conectado a tu energía vital. Me permite seguir la energía de tu corazón artificial.",
  ui_story_1022_10220902_60_dialog_content = "También me alerta cuando estás en grave peligro.",
  ui_story_1022_10220902_61_dialog_content = "Así que sí, Pepita: vine aquí solo por ti, y parece que el destino fue lo suficientemente amable para reunir a la Orden con una de sus reliquias perdidas también.",
  ui_story_1022_10221001_1_dialog_content = "¡Eso me recuerda! Tú conoces a Charon, ¿no es así Lady Victoria?",
  ui_story_1022_10221001_2_dialog_content = "¿Sabes dónde están él y Vice ahora mismo? ¿O por qué las coordenadas del Otro Extremo siguen saltando por todo nuestro mapa?",
  ui_story_1022_10221001_3_dialog_content = "¿No se encontraron con otro Espectro, verdad?!",
  ui_story_1022_10221001_4_dialog_content = "Estaría encantado de contarte sobre—¿Hmm? Veo que has vuelto, ¿eh? Dime, ¿qué pretendes hacer esta vez?",
  ui_story_1022_10221001_5_dialog_content = "¡Yo... Yo debería hacerte la misma pregunta! ¡Este ladrón robó un texto sagrado de Lumopolis! ¿Realmente crees que puedes protegerla del juicio?!",
  ui_story_1022_10221001_6_dialog_content = "Además, nuestro texto sagrado ha llegado a las manos de tu grupo... ¡Lo que significa que todos ustedes son igualmente culpables!",
  ui_story_1022_10221001_7_dialog_content = "¡Oye! ¿Quién dijo que podías hablar de nosotros así?!",
  ui_story_1022_10221001_8_dialog_content = "La tensión entre ambos lados se acerca a su punto de ruptura... Pero, ¿qué puedo hacer?",
  ui_story_1022_10221001_9_dialog_content = "¿No te lo ha dicho ya Pepita? Tu llamado \"texto sagrado\" no es diferente al relicario que tengo en mis manos ahora mismo, en el sentido de que todos pertenecían originalmente a la Orden Verdadera.",
  ui_story_1022_10221001_10_dialog_content = "¡Absurdo! ¿Cómo puedes afirmar que tantas cosas pertenecen a tu maldita orden? Dime, ¿también todo Astra te pertenece?!",
  ui_story_1022_10221001_11_dialog_content = "Si no escuchas a la razón... Entonces te detendré por la fuerza.",
  ui_story_1022_10221001_12_dialog_content = "¡A las armas, Erica!",
  ui_story_1022_10221001_13_dialog_content = "¡Sí señor!",
  ui_story_1022_10221001_14_dialog_content = "¡Espera!",
  ui_story_1022_10221001_15_dialog_content = "... No interfieras, PlayerName.",
  ui_story_1022_10221001_16_dialog_content = "Independientemente de las circunstancias, tenemos el deber de preguntar sobre el paradero de nuestro artefacto perdido.",
  ui_story_1022_10221001_17_dialog_content = "Entonces, ¡usa tus palabras, no tus armas! ¿O ya olvidaste los deseos del Señor de la Ciudad?",
  ui_story_1022_10221001_18_dialog_content = "Pero...",
  ui_story_1022_10221001_19_dialog_content = "Si no queremos obstaculizar nuestra exploración conjunta, necesitamos intentar resolver las cosas de la manera más pacífica posible—",
  ui_story_1022_10221001_20_dialog_content = "\"¿Nuestra\" exploración? ¿Y de qué lado estás, de todos modos?",
  ui_story_1022_10221001_21_dialog_content = "¡¿Qué?!",
  ui_story_1022_10221001_22_dialog_content = "Todo este tiempo he depositado mi confianza en ti, solo para que te alíes con el enemigo en el peor momento posible.",
  ui_story_1022_10221001_23_dialog_content = "\"¡Armamos este equipo para cuidarnos unos a otros!\" Esas fueron tus palabras, ¡mentiroso desvergonzado!",
  ui_story_1022_10221001_24_dialog_content = "Ahora hazte a un lado antes de que yo—",
  ui_story_1022_10221001_25_dialog_content = "¿Antes tú qué?",
  ui_story_1022_10221001_26_dialog_content = "¿Tú tampoco?!",
  ui_story_1022_10221001_27_dialog_content = "PlayerName tiene razón. La exploración de la Zona Oscura tiene prioridad sobre todo lo demás. El Gran Mariscal de Illumina y el Señor de la Ciudad de Lumopolis ambos estuvieron de acuerdo con esto.",
  ui_story_1022_10221001_28_dialog_content = "Entonces, si deseas continuar con tus \"investigaciones\", sugiero que bajes tus armas primero.",
  ui_story_1022_10221001_29_dialog_content = "...",
  ui_story_1022_10221001_30_dialog_content = "Capitán...",
  ui_story_1022_10221001_31_dialog_content = "... Herejes... ¡Deben ser condenados a muerte!!",
  ui_story_1022_10221002_1_dialog_content = "¡Urgh! Maldición... Tú...",
  ui_story_1022_10221002_2_dialog_content = "(Ella es demasiado poderosa, y la Zona Oscura me ha debilitado severamente...)",
  ui_story_1022_10221002_3_dialog_content = "¡No te dejaré... escapar!",
  ui_story_1022_10221002_4_dialog_content = "Nuestro señor me ha revelado que Pepita está destinado a una gloria aún mayor.",
  ui_story_1022_10221002_5_dialog_content = "Hasta la próxima vez. May Que la luz de la Verdad los guíe a todos.",
  ui_story_1022_10221002_6_dialog_content = "... ¡Cobardes!",
  ui_story_1022_10221002_7_dialog_content = "¡Espera Dama Victoria, todavía no me has respondido! ¿Qué pasa con Vice y Charon?!",
  ui_story_1022_10221002_8_dialog_content = "¡Vaya! ¿E-Estoy volando?! ¿Qué estás haciendo, Hiiro—",
  ui_story_1022_10221002_9_dialog_content = "Mantente quieto. No estamos volando, solo me estoy moviendo tan rápido como puedo.",
  ui_story_1022_10221002_10_dialog_content = "Es la única manera de que alcancemos a Victoria.",
  ui_story_1022_10221002_11_dialog_content = "¿Mmm?",
  ui_story_1022_10221002_12_dialog_content = "¿Qué es, Dama Victoria?",
  ui_story_1022_10221002_13_dialog_content = "Continúa sin mí, Pepita. Si te quedas aquí más tiempo, las cosas solo se volverán mucho más problemáticas.",
  ui_story_1022_10221002_14_dialog_content = "Rápidamente.",
  ui_story_1022_10221002_15_dialog_content = "... ¡Bueno!",
  ui_story_1022_10221002_16_dialog_content = "¡Ella está por aquí!",
  ui_story_1022_10221002_17_dialog_content = "¡Lady Victoria! Tú sabes exactamente donde está Vice, ¿verdad?!",
  ui_story_1022_10221002_18_dialog_content = "No seas tan precipitado, mi joven amigo. Cuando llegue el momento de revelar las escrituras, te reunirás con ella.",
  ui_story_1022_10221002_19_dialog_content = "Pero ahora simplemente no es el momento... Adiós.",
  ui_story_1022_10221002_20_dialog_content = "(¡Así que ella sí sabe sobre Vice!)",
  ui_story_1022_10221002_21_option_content = "¡Potencia de fuerza!",
  ui_story_1022_10221002_22_dialog_content = "Jejeje...",
  ui_story_1022_10221002_23_dialog_content = "¿Q-Qué es esto...?",
  ui_story_1022_10221002_24_dialog_content = "<color=#e8d9bb>Monolíticas columnas de hielo ascienden al cielo, flotando en marcado contraste con la oscuridad fluida de la noche eterna.</color>",
  ui_story_1022_10221002_25_dialog_content = "<color=#e8d9bb>Encerrado en una de las enormes formaciones de hielo no es otro que—</color>",
  ui_story_1022_10221002_26_dialog_content = "... Vice!",
  ui_story_1022_10221002_27_dialog_content = "(Pero ¿cómo?! ¿Qué está haciendo ella en un lugar como este...?)",
  ui_story_1022_10221002_28_option_content = "Escanea de nuevo",
  ui_story_1022_10221002_29_dialog_content = "El sonido de un piano es arte en su forma más pura. Puede trascender las mismas fronteras del tiempo y el espacio.",
  ui_story_1022_10221002_30_dialog_content = "¿Qué estás haciendo, Vice?",
  ui_story_1022_10221002_31_dialog_content = "¡PlayerName está en peligro! ¡Tengo que hacer algo antes de que se pierda en la oscuridad del Ingeniero!",
  ui_story_1022_10221002_32_dialog_content = "Usaré este piano para advertirle...",
  ui_story_1022_10221002_33_dialog_content = "El Ingeniero está observando a nuestro amigo Caelestite muy de cerca. Tan de cerca, de hecho, que sus mentes ahora están vinculadas.",
  ui_story_1022_10221002_34_dialog_content = "Es probable que el Ingeniero te note si interfieres.",
  ui_story_1022_10221002_35_dialog_content = "¡Pero-!",
  ui_story_1022_10221002_36_dialog_content = "Honestamente, Dama Victoria, ¿no tienes sentido del romance?",
  ui_story_1022_10221002_37_dialog_content = "¿Crees que tu señor estaría complacido contigo si cortas esta maravillosa música y abandonas a nuestro amigo a la oscuridad?",
  ui_story_1022_10221002_38_dialog_content = "¿Oh? Parece que estás dispuesto a no solo invocar el nombre de nuestro señor, sino también a luchar con el Ingeniero.",
  ui_story_1022_10221002_39_dialog_content = "¿Finalmente estás listo para abrazar la Verdad y despertar al poder de tu linaje?",
  ui_story_1022_10221002_40_dialog_content = "Eso es bastante presuntuoso, dado que solo pronuncié una sola frase. Permíteme reiterar: No tengo absolutamente ningún interés en la llamada \"Verdad\" que defiendes incansablemente.",
  ui_story_1022_10221002_41_dialog_content = "Entonces eso es de hecho una tragedia.",
  ui_story_1022_10221002_42_dialog_content = "... ¡Allí! ¡PlayerName logró liberarse!",
  ui_story_1022_10221002_43_dialog_content = "Pero Soroz ya se ha ido...",
  ui_story_1022_10221002_44_dialog_content = "No te preocupes, querido Vice. PlayerName nunca abandonaría su Coloso, y nosotros nunca lo abandonaríamos a él.",
  ui_story_1022_10221002_45_dialog_content = "Eso hace que las cosas sean un poco más complicadas.",
  ui_story_1022_10221002_46_dialog_content = "¿Arruinando el momento otra vez, milady?",
  ui_story_1022_10221002_47_dialog_content = "La Verdad protege a cada miembro de la Orden Verdadera. Sin embargo, como personas de Illumina, aún no han sido elegidos.",
  ui_story_1022_10221002_48_dialog_content = "Si insisten en ponerse en riesgo... Entonces me temo que no tengo otra opción.",
  ui_story_1022_10221002_49_dialog_content = "<color=#e8d9bb>Chapoteo—</color>",
  ui_story_1022_10221002_50_dialog_content = "¡Gahhh!",
  ui_story_1022_10221002_51_dialog_content = "¡¿Q-Qué es el significado de esto?!",
  ui_story_1022_10221002_52_dialog_content = "<color=#e8d9bb>Con un movimiento de su mano, Victoria divide el Río Prístino en dos.</color>",
  ui_story_1022_10221002_53_dialog_content = "<color=#e8d9bb>Charon y Vice caen sin fin en sus profundidades.</color>",
  ui_story_1022_10221002_54_dialog_content = "<color=#e8d9bb>Mientras caen, una voz misteriosa susurra en sus oídos—</color>",
  ui_story_1022_10221002_55_dialog_content = "Mientras contenga incluso una sola gota de agua del Río Prístino, ni siquiera el Darkflow más poderoso derretirá este hielo.",
  ui_story_1022_10221002_56_dialog_content = "Bwaaaaaa—¿Eh? ¿D-Detuvimos la caída?",
  ui_story_1022_10221002_57_dialog_content = "... ¿Qué es este lugar?",
  ui_story_1022_10221002_58_dialog_content = "<color=#e8d9bb>En un abrir y cerrar de ojos, sus alrededores cambiaron completamente.</color>",
  ui_story_1022_10221002_59_dialog_content = "<color=#e8d9bb>Un cielo oscurecido los rodea, espeso y retorcido como un cenagal vivo. Parece distorsionado, como si lo estuvieran viendo a través de una ventana de vidrio pesado e irregular.</color>",
  ui_story_1022_10221002_60_dialog_content = "<color=#e8d9bb>El vidrio, sin embargo, es en realidad—</color>",
  ui_story_1022_10221002_61_dialog_content = "¿Hielo? ¿Cu-Cuándo quedamos atrapados en un gigantesco pilar de hielo?!",
  ui_story_1022_10221002_62_dialog_content = "¿Eh? Ese sonido...",
  ui_story_1022_10221002_63_dialog_content = "<color=#e8d9bb>Golpe, golpe, golpe-</color>",
  ui_story_1022_10221002_64_dialog_content = "¡Rompe, maldito bloque congelado! ¡Ninguna tumba de hielo puede encerrar las llamas de mis emociones!",
  ui_story_1022_10221002_65_dialog_content = "¡O-Oficial Charon! ¿Tú también estás atrapado aquí?!",
  ui_story_1022_10221002_66_dialog_content = "<color=#e8d9bb>Golpe, golpe, golpe-</color>",
  ui_story_1022_10221002_67_dialog_content = "<color=#e8d9bb>Bajo el implacable asalto del Otro Extremo, el hielo comienza a agrietarse.</color>",
  ui_story_1022_10221002_68_dialog_content = "¡Toma mi mano, Vice!",
  ui_story_1022_10221002_69_dialog_content = "¡Ya voy!",
  ui_story_1022_10221002_70_dialog_content = "Vice.",
  ui_story_1022_10221002_71_dialog_content = "(¿Eh? ¿Estoy imaginando cosas, o acabo de escuchar la voz de Lady Victoria?)",
  ui_story_1022_10221002_72_dialog_content = "Escúchame, Vice.",
  ui_story_1022_10221002_73_dialog_content = "PlayerName está a punto de enfrentar su prueba más desafiante hasta ahora. Él—",
  ui_story_1022_10221002_74_dialog_content = "<color=#e8d9bb>La voz de Victoria aparece en los oídos de Vice, clara como el día.</color>",
  ui_story_1022_10221002_75_dialog_content = "¡¡!!",
  ui_story_1022_10221002_76_dialog_content = "¿Qué estás esperando, Vice?! ¡Ven aquí al instante!",
  ui_story_1022_10221002_77_dialog_content = "...",
  ui_story_1022_10221002_78_dialog_content = "Tú sigue adelante, oficial Charon.",
  ui_story_1022_10221002_79_dialog_content = "Me quedo aquí.",
  ui_story_1022_10221002_80_dialog_content = "¡¿Qué?!",
  ui_story_1022_10221002_81_dialog_content = "PlayerName me necesita...",
  ui_story_1022_10221002_82_dialog_content = "Y mientras esté aquí, sé que puedo ayudarlo.",
  ui_story_1022_10221002_83_dialog_content = "<color=#FFB400>Vice</color>—!",
  ui_story_1022_10221002_84_dialog_content = "<color=#e8d9bb>Quiero gritarle, alcanzarla y hacerle saber que estoy aquí. Quiero estar a su lado, o al menos ver su sonrisa de nuevo...</color>",
  ui_story_1022_10221002_85_dialog_content = "<color=#e8d9bb>Pero mi visión sigue oscureciendo.</color>",
  ui_story_1022_10221002_86_dialog_content = "<color=#e8d9bb>Más oscuro y oscuro.</color>",
  ui_story_1022_10221002_87_dialog_content = "<color=#e8d9bb>Como si estuviera envuelto por la noche eterna.</color>",
  ui_story_1022_10221002_88_dialog_content = "<color=#e8d9bb>Pero la única fuente de luz proviene de ella.</color>",
  ui_story_1022_10221002_89_dialog_content = "<color=#e8d9bb>Rodeado por todos lados por la oscuridad fría y opresiva—</color>",
  ui_story_1022_10221002_90_dialog_content = "<color=#e8d9bb>Su luz deslumbrante brilla en todas las direcciones.</color>",
  ui_story_1022_10221002_91_dialog_content = "<color=#e8d9bb>Como el sol brillando a través de una noche eterna.</color>",
  ui_story_1022_10221002_92_dialog_content = "(Esa bola de Lumina que sentí antes... Era Vice todo el tiempo...)",
  ui_story_1022_10221002_93_dialog_content = "(La luz de su alma era lo único que me impedía perderme en la oscuridad.)",
  ui_story_1022_10221002_94_dialog_content = "(Ustedes me llaman el Navegante porque cuentan conmigo para guiarlos a través de sus batallas más difíciles...)",
  ui_story_1022_10221002_95_dialog_content = "(Pero el que me ha estado guiando todo el tiempo es Vice.)",
  ui_story_1022_10221002_96_dialog_content = "(Desde el primer día que nos conocimos...)",
  ui_story_1022_10221101_1_dialog_content = "... PlayerName.",
  ui_story_1022_10221101_2_dialog_content = "¡Despierta, PlayerName!",
  ui_story_1022_10221101_3_dialog_content = "Hiiro...",
  ui_story_1022_10221101_4_dialog_content = "... La vi, Hiiro! ¡Sé dónde está Vice! Ella es la fuente de esa Lumina que sentí antes, ¡pero está atrapada en una gigantesca columna de hielo! ¡Tenemos que salvarla!",
  ui_story_1022_10221101_5_dialog_content = "Estoy escuchando, pero primero necesitas calmarte. Toma, bebe un poco de agua.",
  ui_story_1022_10221101_6_dialog_content = "O-Vale, gracias...",
  ui_story_1022_10221101_7_dialog_content = "Creo que deberías saberlo, pero Victoria ya se fue. Ella desapareció de repente hace algún tiempo.",
  ui_story_1022_10221101_8_dialog_content = "¿Desapareció?",
  ui_story_1022_10221101_9_dialog_content = "Sí. Parece que el Victoria con quien hablamos no era más que una ilusión.",
  ui_story_1022_10221101_10_dialog_content = "*sollozando* ¡Abuelo! Waaahhhh—",
  ui_story_1022_10221101_11_dialog_content = "¿Cómo pudiste morir y dejarme solo así?! Si todavía estuvieras aquí, esa <color=#FFB400>mujer desagradable</color> no habría sido tan cruel conmigo!",
  ui_story_1022_10221101_12_dialog_content = "Abuelo...",
  ui_story_1022_10221101_13_dialog_content = "...",
  ui_story_1022_10221101_14_dialog_content = "Supongo que ya no tiene sentido llorar por ello. Después de todo, él está muerto.",
  ui_story_1022_10221101_15_dialog_content = "¡Pero ahora tengo a Pepita! ¡Ella se preocupa por mí más que nadie!",
  ui_story_1022_10221101_16_dialog_content = "Pero esa malvada dama la alejó de mí...",
  ui_story_1022_10221101_17_dialog_content = "<size=50>¡Wahhhhhhhh!</size>",
  ui_story_1022_10221101_18_dialog_content = "Como dije antes, tú eres el que alejó a Pepita.",
  ui_story_1022_10221101_19_dialog_content = "¡¿Qué?!",
  ui_story_1022_10221101_20_dialog_content = "¿Es realmente tan difícil para ti usar tu cabeza de vez en cuando? Entiendo que nunca has tenido que hacerlo, dada tu herencia...",
  ui_story_1022_10221101_21_dialog_content = "Pero incluso una mente aburrida es una cosa terrible de desperdiciar. ¿No estás de acuerdo—",
  ui_story_1022_10221101_22_dialog_content = "¿<color=#FFB400>Hija largamente abandonada del decimotercer jefe de familia</color>?",
  ui_story_1022_10221101_23_dialog_content = "Cómo... ¡Cómo te atreves a mencionar eso!",
  ui_story_1022_10221101_24_dialog_content = "¡Idiota! ¡Cómo te atreves a ofrecerle tal sangre sucia a mi preciosa nieta!",
  ui_story_1022_10221101_25_dialog_content = "¡Ursura puede distinguir entre la sangre noble y la sangre de un plebeyo tonto! ¿Estás intentando matarla con tu miserable ofrenda?!",
  ui_story_1022_10221101_26_dialog_content = "¡P-Perdóname, mi señor!",
  ui_story_1022_10221101_27_dialog_content = "Waaaaaaaaaaah!",
  ui_story_1022_10221101_28_dialog_content = "No llores, querida. Tu abuelo te encontrará la mejor sangre del mundo.",
  ui_story_1022_10221101_29_dialog_content = "Solo la sangre más dulce y deliciosa servirá para mi pequeño genio querido...",
  ui_story_1022_10221101_30_dialog_content = "<color=#e8d9bb>¡Choque! Con un solo barrido, cada pieza de vajilla cae al suelo y se estrella en pedazos.</color>",
  ui_story_1022_10221101_31_dialog_content = "¿Qu-Qué es, mi señora?! ¿Hemos hecho algo más para ofenderte?",
  ui_story_1022_10221101_32_dialog_content = "¿En serio no lo sabes? ¡Apenas me has traído alguna \"presa\" con la que jugar hoy! Si mi abuelo todavía estuviera vivo, no te atreverías a insultarme de esta manera!",
  ui_story_1022_10221101_33_dialog_content = "P-Pero mi señora... Si reducimos el número de plebeyos demasiado rápido, la producción disminuirá y nuestra gente no tendrá suficiente para comer...",
  ui_story_1022_10221101_34_dialog_content = "¡Entonces déjalos comer pastel, si tienen tanta hambre! ¿Realmente tengo que explicarte las cosas?!",
  ui_story_1022_10221101_35_dialog_content = "N-No, mi señora... Organizaré más presas de inmediato.",
  ui_story_1022_10221101_36_dialog_content = "¡¡¡Huye...!!!",
  ui_story_1022_10221101_37_dialog_content = "¡Jajajaja! ¡Ahora esto es más parecido! Los juegos de caza siempre son más divertidos cuando hay mucha presa!",
  ui_story_1022_10221101_38_dialog_content = "Corre tan lejos y tan rápido como puedas, pequeños conejos! Y no te preocupes...",
  ui_story_1022_10221101_39_dialog_content = "Me aseguraré de divertirme mucho con cada uno de ustedes.",
  ui_story_1022_10221101_40_dialog_content = "Todos tendrán un turno... lo prometo.",
  ui_story_1022_10221101_41_dialog_content = "Las cosas solían ser tan geniales. En aquel entonces, todos me escuchaban y jugaban conmigo, sin hacer preguntas...",
  ui_story_1022_10221101_42_dialog_content = "Pero ya no más. Todo se ha ido ahora... ¡Y todo es por culpa tuya, escoria de Varaki!",
  ui_story_1022_10221101_43_dialog_content = "Gracias a ti, no tuve más remedio que retirarme a Eclipse, donde todo lo que podía hacer era dormir, dormir, dormir. Nadie me escuchaba, ni siquiera se preocupaba por mí, para el caso...",
  ui_story_1022_10221101_44_dialog_content = "¡¡Todo es tu culpa!!",
  ui_story_1022_10221101_45_dialog_content = "¿Veo que vuelves a culpar a otras personas?",
  ui_story_1022_10221101_46_dialog_content = "La razón por la que fuiste exiliado fue por tu tiranía y tu traición.",
  ui_story_1022_10221101_47_dialog_content = "Fuiste tú quien lideró un ejército de Eclipsites hacia la Ciudad de Varaki, matando a innumerables creyentes inocentes y escapando con la reliquia sagrada del True Order. Ese capítulo manchado de sangre de la historia de Varaki fue escrito por nadie más que tú mismo.",
  ui_story_1022_10221101_48_dialog_content = "Así que cuando hojeé las páginas polvorientas de la historia de nuestra familia, me sorprendió descubrir la gravedad de tus pecados...",
  ui_story_1022_10221101_49_dialog_content = "¡Cállate! ¡Solo cállate ya! ¿Qué tiene de malo matar a unos cuantos Aurorians de todos modos? ¡No es como si tú no hubieras hecho lo mismo, verdad?!",
  ui_story_1022_10221101_50_dialog_content = "Nada hacía más feliz a mi abuelo que verme feliz... ¡Pero entonces tú y tu gente tenían que arruinarlo!",
  ui_story_1022_10221101_51_dialog_content = "No creas que puedes sermonearme solo porque eres el líder de la familia...",
  ui_story_1022_10221101_52_dialog_content = "Mientras arda lo más brillante posible... ¿Entonces qué tiene de malo morir?",
  ui_story_1022_10221101_53_dialog_content = "No soy la mascota de nadie, y nunca me rendiré a nadie...",
  ui_story_1022_10221101_54_dialog_content = "<color=#FFB400>¡Yo... Me pertenezco a mí mismo!</color>",
  ui_story_1022_10221101_55_dialog_content = "... ¡Pertenezco a mí mismo! ¡Nunca te escucharé a ti ni a nadie más!",
  ui_story_1022_10221101_56_dialog_content = "Qué ridículo mal uso del credo de Pepita. Si ella estuviera aquí ahora mismo, estaría derramando lágrimas de risa.",
  ui_story_1022_10221101_57_dialog_content = "¡¡¡No te atrevas a mencionarla!!!",
  ui_story_1022_10221101_58_dialog_content = "<color=#e8d9bb>Mientras Ursura grita salvajemente, un espeso Darkflow comienza a erupcionar a su alrededor. </color>",
  ui_story_1022_10221101_59_dialog_content = "<color=#e8d9bb>La rodea y gorgotea en todas direcciones, avanzando ominosamente sobre el hielo oscurecido.</color>",
  ui_story_1022_10221101_60_dialog_content = "<color=#e8d9bb>Innumerables brotes brotan del hielo, crepitando y ramificándose mientras forman enormes racimos de coral retorcido.</color>",
  ui_story_1022_10221101_61_dialog_content = "<color=#e8d9bb>Los corales comienzan a entrelazarse grotescamente, como las venas de un monstruo gigantesco.</color>",
  ui_story_1022_10221101_62_dialog_content = "<color=#e8d9bb>Pum-pum.</color>",
  ui_story_1022_10221101_63_dialog_content = "<color=#e8d9bb>Todo el bosque de coral, una entidad viva por sí misma, pulsa en sincronía con el corazón que late en el centro de la densa niebla negra.</color>",
  ui_story_1022_10221101_64_dialog_content = "<color=#e8d9bb>Con cada latido, más del viscoso Darkflow se derrama, corrompiendo la vida de cada Aurorian en las cercanías.</color>",
  ui_story_1022_10221101_65_dialog_content = "¡Graaagh—!",
  ui_story_1022_10221102_1_dialog_content = "<color=#e8d9bb>¡Grieta!</color>",
  ui_story_1022_10221102_2_dialog_content = "<color=#e8d9bb>Victoria finalmente logra atravesar la densa capa de Darkflow de Ursura, aunque no sin pagar un precio.</color>",
  ui_story_1022_10221102_3_dialog_content = "¡Tos—!",
  ui_story_1022_10221102_4_dialog_content = "Ja... ¡Jajaja! ¿Es todo lo que puedes reunir, señorita Jefa de la Casa?!",
  ui_story_1022_10221102_5_dialog_content = "¡Con solo un poco de esfuerzo adicional, puedo fácilmente hacerte arrodillar!",
  ui_story_1022_10221102_6_dialog_content = "Supongo que tiene sentido. Después de todo, desperté al poder de mi linaje cuando era solo una pequeña niña. ¡Incluso mi abuelo dijo que nunca ha habido un genio como yo antes!",
  ui_story_1022_10221102_7_dialog_content = "¿Pero qué hay de ti, vieja bruja? Por cómo se ven las cosas, ¡no despertaste a tus poderes hasta que tu vida ya estaba a la mitad! ¡Jajajajaja!",
  ui_story_1022_10221102_8_dialog_content = "... Je.",
  ui_story_1022_10221102_9_dialog_content = "¿Qué es tan gracioso?",
  ui_story_1022_10221102_10_dialog_content = "Desperté a mis poderes antes que nadie en toda la historia de nuestra familia! ¡Eso me hace el más puro y talentoso de nuestra especie! ¡Nunca podrías esperar compararte conmigo!",
  ui_story_1022_10221102_11_dialog_content = "¡A estas alturas, podrías hacerme el jefe de tu casa! ¡Jajaja—",
  ui_story_1022_10221102_12_dialog_content = "<color=#e8d9bb>La risa maniática de Ursura llega a un abrupto final.</color>",
  ui_story_1022_10221102_13_dialog_content = "<color=#e8d9bb>Con una mirada de horrorizada perplejidad, ella observa cómo las heridas de Victoria se curan rápidamente una por una. Incluso su ropa rasgada vuelve a su estado original.</color>",
  ui_story_1022_10221102_14_dialog_content = "¡¿P-Pero cómo...?!",
  ui_story_1022_10221102_15_dialog_content = "¿Realmente estás tan sorprendido por esto? Supuse que un genio como tú ya habría visto a través de mi técnica.",
  ui_story_1022_10221102_16_dialog_content = "¡Tú... estás guardando la mayor parte de tu poder en otro lugar, verdad?! ¿Qué exactamente estás tramando?!",
  ui_story_1022_10221102_17_dialog_content = "Después de sumergir a esos dos en las profundidades del Río Prístino, es natural que me quede a vigilarlos. Después de todo, la Zona Oscura es un lugar peligroso.",
  ui_story_1022_10221102_18_dialog_content = "Si no te hubieras desviado tanto del camino de la Verdad... Nuestro señor también te estaría protegiendo.",
  ui_story_1022_10221102_19_dialog_content = "Imposible... ¡No hay forma de que tengas suficiente fuerza para luchar contra mí y cuidar de otras personas al mismo tiempo!",
  ui_story_1022_10221102_20_dialog_content = "Soy el más fuerte... ¡Desperté a mis poderes mucho antes que cualquier otro! Mi fuerza es la más pura, y mi potencial es ilimitado... ¡D-Debe haber algún tipo de truco en tu poder! ¡Tiene que haberlo!",
  ui_story_1022_10221102_21_dialog_content = "¿Es esa la única explicación que puedes dar? Parece que despertaste a tus poderes <color=#FFB400>demasiado temprano</color>.",
  ui_story_1022_10221102_22_dialog_content = "¿Qué?",
  ui_story_1022_10221102_23_dialog_content = "Tu despertar fue prematuro, lo que te hizo arrogante y por ende lamentablemente ingenuo. Ni una sola vez has intentado cultivar tu poder a través del pensamiento o el entrenamiento.",
  ui_story_1022_10221102_24_dialog_content = "No se puede negar tu fuerza, Ursura. Representas los impulsos más primarios e insaciables de nuestra especie.",
  ui_story_1022_10221102_25_dialog_content = "Yo, por otro lado, soy exactamente lo contrario de ti.",
  ui_story_1022_10221102_26_dialog_content = "¿Q-Qué se supone que significa eso...?",
  ui_story_1022_10221102_27_dialog_content = "Desperté a mis poderes mucho más tarde que tú.",
  ui_story_1022_10221102_28_dialog_content = "Para comprender la Verdad, viajé la longitud y la anchura de la tierra, reflexionando sobre todo lo que presencié.",
  ui_story_1022_10221102_29_dialog_content = "Fue un viaje que no has experimentado y no volverás a experimentar.",
  ui_story_1022_10221102_30_dialog_content = "Y como mis métodos se te escapan... Sólo puedo pedirte que uses tu imaginación.",
  ui_story_1022_10221102_31_dialog_content = "Después de todo... Nunca podrías entender posiblemente.",
  ui_story_1022_10221102_32_dialog_content = "¡C-Cállate! ¡Soy el más fuerte, no tú...!",
  ui_story_1022_10221102_33_dialog_content = "<color=#e8d9bb>El furioso grito de Ursura no es suficiente para suprimir el miedo en su corazón. Toda su vida, le dijeron que era un genio entre genios.</color>",
  ui_story_1022_10221102_34_dialog_content = "<color=#e8d9bb>Pero esta repentina revelación fue un terrible shock para su corazón, su mente y sus sentidos—</color>",
  ui_story_1022_10221102_35_dialog_content = "<color=#FFB400>Orden</color>...",
  ui_story_1022_10221102_36_dialog_content = "<color=#e8d9bb>Es el pináculo, el reino supremo al que aspiran todos los Aurorianos que buscan la Verdad.</color>",
  ui_story_1022_10221102_37_dialog_content = "<color=#e8d9bb>A través de una consulta sincera, supera todo deseo puro y primitivo. Un himno de adoración dedicado a la Verdad.</color>",
  ui_story_1022_10221102_38_dialog_content = "Una respuesta maravillosa, Ursura. Ahora, es hora de ponerlo en práctica.",
  ui_story_1022_10221102_39_dialog_content = "Observa mi técnica secreta. Mira de cerca y no apartes la vista.",
  ui_story_1022_10221102_40_dialog_content = "Esta peregrinación, la ofrezco a nuestro señor—",
  ui_story_1022_10221102_41_dialog_content = "¡Waaaahhhh—!",
  ui_story_1022_10221102_42_dialog_content = "¿Por qué? ¡¿Por qué?! La marca del Eclipse me fue dada hace mucho tiempo, entonces ¿por qué...",
  ui_story_1022_10221102_43_dialog_content = "... ¿Por qué soy un auroriano de nuevo?!",
  ui_story_1022_10221102_44_dialog_content = "No... Por favor... No quiero morir... No quiero desvanecerme...",
  ui_story_1022_10221102_45_dialog_content = "¡¡¡Nooooooo!!!",
  ui_story_1022_10221102_46_dialog_content = "Qué técnica tan aterradora... Ya veo. Así que esta es tu idea de redención.",
  ui_story_1022_10221102_47_dialog_content = "Al negar lo inmaterial, ¿pretendes ofrecer solo la esencia pura al señor de toda conciencia?",
  ui_story_1022_10221102_48_dialog_content = "No... El que realmente debería ser temido eres tú, Victoria.",
  ui_story_1022_10221102_49_dialog_content = "Tu poder es algo que incluso yo anhelo controlar una vez más. ¿No existe nada más allá de tu campo de visión?",
  ui_story_1022_10221102_50_dialog_content = "<color=#e8d9bb>El río iridiscente serpentea y fluye por toda la eternidad. En sus aguas, el tiempo no tiene significado.</color>",
  ui_story_1022_10221102_51_dialog_content = "<color=#e8d9bb>Incluso ahora, innumerables pasados y futuros se disponen de manera equitativa ante el Recluso, incluyendo sus realidades paralelas.</color>",
  ui_story_1022_10221102_52_dialog_content = "Pero apenas importa ahora... Ven.",
  ui_story_1022_10221102_53_dialog_content = "<color=#e8d9bb>Con un aplauso de sus manos, el Recluso abre una grieta en el espacio, y un tren impulsado por vapor sale volando del vacío.</color>",
  ui_story_1022_10221102_54_dialog_content = "¡Aaaahhhh—!",
  ui_story_1022_10221102_55_dialog_content = "Silencio. En mi soledad, mis oídos se han desacostumbrado a los gritos de los demás.",
  ui_story_1022_10221102_56_dialog_content = "¡No este maldito río otra vez! ¿Y quién podrías ser tú?! Espera... Te he visto antes.",
  ui_story_1022_10221102_57_dialog_content = "Eres... El primo de mi padre que murió hace mucho tiempo, así como el tío de Victoria... <color=#FFB400>Wilhelm Varaki</color>.",
  ui_story_1022_10221102_58_dialog_content = "Siempre puedes referirte a mí como tu tío también, ¿sabes?",
  ui_story_1022_10221102_59_dialog_content = "Sí, bueno, perdóname por no querer discutir lazos familiares con un hombre muerto, especialmente en el extraño ambiente en el que nos encontramos ahora mismo.",
  ui_story_1022_10221102_60_dialog_content = "... Eres tan molesto y verboso como Victoria.",
  ui_story_1022_10221102_61_dialog_content = "¿Qué fue eso? ¡Te haré saber que mi elocuente discurso no tiene nada que ver con el delirio fanático de esa mujer!",
  ui_story_1022_10221102_62_dialog_content = "Primero la hija de mi hermano, ahora tú... ¿Quizás debería cambiar el escudo de nuestra familia para incluir una cuna y un chupete?",
  ui_story_1022_10221102_63_dialog_content = "Tu nombre es Charon, si no me equivoco? Dime, ¿sabes por qué estás aquí?",
  ui_story_1022_10221102_64_dialog_content = "¿Estás diciendo que esto no fue obra tuya?",
  ui_story_1022_10221102_65_dialog_content = "Victoria desea que perfecciones tus técnicas conmigo y profundices tu comprensión de la verdad. Ella ve un gran potencial oculto en ti.",
  ui_story_1022_10221102_66_dialog_content = "¡¿Qué?! ¡Le dije a esa bruja que no quiero tener nada que ver con ella o su supuesta Verdad!",
  ui_story_1022_10221102_67_dialog_content = "Y estabas indiscutiblemente desinteresado en ese momento, sí.",
  ui_story_1022_10221102_68_dialog_content = "Pero el tiempo ha pasado y ya no eres la persona que solías ser. Dime, ¿cuáles son tus pensamientos ahora?",
  ui_story_1022_10221102_69_dialog_content = "Yo...",
  ui_story_1022_10221102_70_dialog_content = "<color=#e8d9bb>\"¡Por supuesto que todavía no estoy interesado!\" Las palabras casi se habían formado en la boca de Charon.</color>",
  ui_story_1022_10221102_71_dialog_content = "<color=#e8d9bb>Pero de repente, la imagen de Vice congelado en una columna de hielo apareció en su mente. Recordó que su subordinado todavía estaba rodeado de Eclipsites en un lugar de noche eterna.</color>",
  ui_story_1022_10221102_72_dialog_content = "<color=#e8d9bb>Ella eligió quedarse allí por el bien de Caelestite, lo que significa que probablemente esté en grave peligro. Por extensión, significa que sus camaradas de Illumina también están en peligro.</color>",
  ui_story_1022_10221102_73_dialog_content = "<color=#e8d9bb>Bajo estas circunstancias...</color>",
  ui_story_1022_10221102_74_dialog_content = "... Tal vez finalmente sea hora de superar mi fase rebelde.",
  ui_story_1022_10221102_75_dialog_content = "Hmph, al menos eres consciente de tu propia terquedad, lo que significa que aún hay esperanza para ti... A diferencia de algunas personas.",
  ui_story_1022_10221102_76_dialog_content = "Pero afortunadamente, no tendré que poner en peligro mi propia vida inexistente esta vez. ¿No es así?",
  ui_story_1022_10221200_1_dialog_content = "...",
  ui_story_1022_10221200_2_dialog_content = "(Una cueva... Así es. Logré retroceder hasta nuestro primer sitio de campamento antes de desmayarme de agotamiento.)",
  ui_story_1022_10221200_3_dialog_content = "(Lady Victoria probablemente fue tras Ursura. Tengo que encontrarla...)",
  ui_story_1022_10221200_4_dialog_content = "¡Maldita sea todo! Nuestro objetivo y el tomo robado estaban justo frente a nosotros, ¡y aún así perdimos nuestra oportunidad!",
  ui_story_1022_10221200_5_dialog_content = "(Uh-oh, ¿qué está haciendo ella aquí? Bueno que no tenía prisa por irme.)",
  ui_story_1022_10221200_6_dialog_content = "Por favor, no te muevas tanto, capitán. Volverás a abrir tus heridas.",
  ui_story_1022_10221200_7_dialog_content = "(Erica... Ella parecía tan preocupada cuando vio mis heridas antes.)",
  ui_story_1022_10221200_8_dialog_content = "¡Estoy bien, Erica! Además, estoy más preocupado por lo que nuestro invitado no invitado está haciendo aquí.",
  ui_story_1022_10221200_9_dialog_content = "¿No recibiste nuestro mensaje? Me enviaron para ayudarte.",
  ui_story_1022_10221200_10_dialog_content = "(¿Alguien más está aquí? Ni siquiera los noté...)",
  ui_story_1022_10221200_11_dialog_content = "\"¿Ayúdanos\", dices? Nuestro equipo entero tenía a Pepita rodeada, ¡y aún así se escapó! ¿Cómo podrías ayudarnos ahora?!",
  ui_story_1022_10221200_12_dialog_content = "(¿Están hablando de mí, eh?)",
  ui_story_1022_10221200_13_dialog_content = "Por supuesto, utilizando un método infalible para capturarla.",
  ui_story_1022_10221200_14_dialog_content = "Por favor, toma esto.",
  ui_story_1022_10221200_15_dialog_content = "¿Un control remoto? ¿Qué estás tratando de decir, que esto puede revelar su ubicación con solo presionar un botón?!",
  ui_story_1022_10221200_16_dialog_content = "Precisamente.",
  ui_story_1022_10221200_17_dialog_content = "... Estás bromeando.",
  ui_story_1022_10221200_18_dialog_content = "Para nada. A lo que te refieres como un \"control remoto\" es en realidad una contramedida implementada hace Belisaria años.",
  ui_story_1022_10221200_19_dialog_content = "Con ello, puedes controlar el corazón artificial que late en el pecho de Pepita.",
  ui_story_1022_10221200_20_dialog_content = "¡¡!!",
  ui_story_1022_10221200_21_dialog_content = "¿El corazón de Pepita... es artificial?",
  ui_story_1022_10221200_22_dialog_content = "Y este botón específico se puede usar para apagar completamente su corazón. No debería tener que explicar qué sucede después de eso... ¿Verdad?",
  ui_story_1022_10221200_23_dialog_content = "Usar esta función para localizarla es prácticamente infalible, ¿no estás de acuerdo?",
  ui_story_1022_10221200_24_dialog_content = "¡¿Estás loco?! ¡Eso no sería diferente a asesinarla!",
  ui_story_1022_10221200_25_dialog_content = "Tomar una vida solo es asesinato cuando la víctima es inocente.",
  ui_story_1022_10221200_26_dialog_content = "Pero cuando la víctima es un delincuente buscado... Entonces, se convierte en una ejecución.",
  ui_story_1022_10221200_27_dialog_content = "¿Hay realmente alguna diferencia entre las dos...?",
  ui_story_1022_10221200_28_dialog_content = "Cuando Pepita traicionó a Illumina por primera vez, Belisaria tenía este mismo dispositivo en sus manos ese día.",
  ui_story_1022_10221200_29_dialog_content = "Pero aunque vio al delincuente escapar con sus propios ojos, no pudo presionar el botón. Fue... Una gran decepción.",
  ui_story_1022_10221200_30_dialog_content = "(Belisaria...)",
  ui_story_1022_10221200_31_dialog_content = "Pero creo que eres diferente de la llamada \"Dama de Hierro\".",
  ui_story_1022_10221200_32_dialog_content = "Tu rencor hacia los criminales de Lumopolis es genuino.",
  ui_story_1022_10221200_33_dialog_content = "Yo...",
  ui_story_1022_10221200_34_dialog_content = "¡No lo hagas, capitán!",
  ui_story_1022_10221200_35_dialog_content = "¡Esto... Esto no es el camino correcto! Pepita puede haber cometido algunos crímenes, ¡pero eso no la convierte en una mala persona!",
  ui_story_1022_10221200_36_dialog_content = "Como un espíritu afín, puedo verlo en sus ojos cada vez que nos encontramos cara a cara.",
  ui_story_1022_10221200_37_dialog_content = "Todos somos culpables de cometer errores a lo largo de nuestras vidas... ¡Las enseñanzas del Dios de la Luz nos lo dicen! Pero incluso el pecador más culpable merece una oportunidad de redención!",
  ui_story_1022_10221200_38_dialog_content = "Erica...!",
  ui_story_1022_10221200_39_dialog_content = "¡¿Quién está ahí?!",
  ui_story_1022_10221200_40_dialog_content = "¿P-Pepita?! ¿Cuándo tú—",
  ui_story_1022_10221200_41_dialog_content = "Eh, lo siento, creo que me estás confundiendo con otra persona. D-No te preocupes por mí, ¡solo continúa con tu conversación!",
  ui_story_1022_10221200_42_dialog_content = "... ¡Después de ella!",
  ui_story_1022_10221200_43_dialog_content = "Espera, Pepita! ¡No te vayas!",
  ui_story_1022_10221200_44_dialog_content = "¡Dile a tu capitán que entregue ese control remoto primero!",
  ui_story_1022_10221200_45_dialog_content = "¡Por favor confía en mí, Pepita! No dejaré que te hagan daño, así que—",
  ui_story_1022_10221200_46_dialog_content = "¡Sí, claro! Háblame cuando estés clasificado por encima de ese loco capitán tuyo!",
  ui_story_1022_10221200_47_dialog_content = "¡Solo escucha, Pepita! Estás corriendo hacia—",
  ui_story_1022_10221200_48_dialog_content = "¡Ríndete! No voy a parar por nada—¡Wh-Whoa!",
  ui_story_1022_10221200_49_dialog_content = "<color=#e8d9bb>Una repentina ráfaga de viento frígido casi tumba a Pepita al suelo.</color>",
  ui_story_1022_10221200_50_dialog_content = "<color=#e8d9bb>Unos pasos más, y ella habría caído de cabeza en un abismo bostezante e insondable.</color>",
  ui_story_1022_10221200_51_dialog_content = "¡Pepita! ¡¿Estás bien?!",
  ui_story_1022_10221200_52_dialog_content = "... No te acerques más.",
  ui_story_1022_10221200_53_dialog_content = "Bien, no lo haré, ¡pero por favor solo escúchame!",
  ui_story_1022_10221200_54_dialog_content = "El Señor de la Ciudad ha acordado no castigarte siempre que nos cuentes todo lo que sabes sobre nuestro tomo perdido. Si haces eso, prometo—",
  ui_story_1022_10221200_55_dialog_content = "¿Eres tú el que hace la promesa, o es el Señor de la Ciudad?",
  ui_story_1022_10221200_56_dialog_content = "Yo...",
  ui_story_1022_10221200_57_dialog_content = "No puedes prometer nada, ¿verdad? Todo lo que puedes hacer es esperar que tu preciado Señor de la Ciudad cumpla su palabra!",
  ui_story_1022_10221200_58_dialog_content = "¡Bueno gracias, pero no gracias! No tengo intención de sobrevivir, gracias a la supuesta misericordia de tu maestro.",
  ui_story_1022_10221200_59_dialog_content = "<color=#FFB400>¡Si no soy libre, prefiero estar muerto!</color>",
  ui_story_1022_10221200_60_dialog_content = "<color=#e8d9bb>Sin un momento de vacilación, Pepita se gira y salta desde el borde del acantilado.</color>",
  ui_story_1022_10221200_61_dialog_content = "Pepita!!!",
  ui_story_1022_10221200_62_dialog_content = "<color=#e8d9bb>Erica se apresura al borde del abismo, pero no ve ninguna señal de Pepita en la niebla giratoria de abajo.</color>",
  ui_story_1022_10221200_63_dialog_content = "...",
  ui_story_1022_10221200_64_dialog_content = "*suspiros* Otra persona más que fue incapaz de presionar el botón.",
  ui_story_1022_10221200_65_dialog_content = "Esa es la segunda vez que tomo la decisión equivocada. Parece que debería reflexionar un poco sobre mí mismo.",
  ui_story_1022_10221200_66_dialog_content = "... Erica tenía razón. Ella era una delincuente, pero eso no significaba que merecía morir. Yo... ¡Yo nunca quitaría la vida de una persona por mis propios motivos egoístas!",
  ui_story_1022_10221200_67_dialog_content = "Tú... ¿Quién demonios eres en el mundo?",
  ui_story_1022_10221200_68_dialog_content = "Tu curiosidad supera tu ignorancia, capitán. ¿Todos en la División de Investigación de Herejes de Lumopolis son así?",
  ui_story_1022_10221200_69_dialog_content = "Pepita ya no es de tu incumbencia.",
  ui_story_1022_10221200_70_dialog_content = "Este asunto está ahora en manos de los <color=#FFB400>Ejecutores</color> de Illumina.",
  ui_story_1022_10221200_71_dialog_content = "<color=#e8d9bb>En lo profundo de la Zona Oscura, un poderoso rayo de luz destella antes de la entrada de una cierta cueva.</color>",
  ui_story_1022_10221200_72_dialog_content = "¿Qué pasó...? ¿Cuándo yo... Espera. ¿Fui enviado de vuelta?!",
  ui_story_1022_10221200_73_dialog_content = "Cielos negros, frío amargo, denso Darkflow... ¡Y el Eclipse! ¡Realmente he vuelto! Oh gracias, muchas gracias...",
  ui_story_1022_10221200_74_dialog_content = "Al menos tienes la decencia de agradecer a nuestro señor por traerte de vuelta, Figerald.",
  ui_story_1022_10221200_75_dialog_content = "...",
  ui_story_1022_10221200_76_dialog_content = "Oh genial, ustedes también están aquí.",
  ui_story_1022_10221200_77_dialog_content = "Así es, y ciertamente nos has hecho esperar. Si tuvieras incluso una pizca de talento, nuestro tiempo no se habría desperdiciado tan innecesariamente.",
  ui_story_1022_10221200_78_dialog_content = "Vaya, esas son algunas palabras hirientes, Asmodeus. Yo fui el que se lanzó de cabeza a la batalla por nuestro señor, pero ¿qué has hecho tú por él?",
  ui_story_1022_10221200_79_dialog_content = "Porque asaltaría la ciudad de Gannon de nuevo sin pensarlo dos veces, si eso es lo que él quisiera que hiciera.",
  ui_story_1022_10221200_80_dialog_content = "Entonces considérate afortunado de tener al menos una cualidad redentora, Figerald.",
  ui_story_1022_10221200_81_dialog_content = "... ¿Qué se supone que significa eso?",
  ui_story_1022_10221200_82_dialog_content = "¿Y qué hace ella aquí de todos modos? Esta es una reunión de los Ocho Espectros, entonces, ¿dónde encaja ella?",
  ui_story_1022_10221200_83_dialog_content = "...",
  ui_story_1022_10221200_84_dialog_content = "¿Quieres decir que no lo sabes? En Eclipse, solo hay un único camino de ascenso.",
  ui_story_1022_10221200_85_dialog_content = "Para que alguien pueda ascender, la persona que está por encima de ellos debe desaparecer primero.",
  ui_story_1022_10221200_86_dialog_content = "Siempre ha habido ocho Espectros en el Eclipse. Ni siete, ni nueve, sino ocho.",
  ui_story_1022_10221200_87_dialog_content = "¿Q-Qué demonios estás diciendo? ¡Solo dime por qué Forsakin está aquí!",
  ui_story_1022_10221200_88_dialog_content = "Un general tonto no necesita soldados astutos. Los logros de Forsakin superan con creces los tuyos.",
  ui_story_1022_10221200_89_dialog_content = "<color=#FFB400>Ascensión</color> es solo una recompensa adecuada para sus esfuerzos.",
  ui_story_1022_10221200_90_dialog_content = "!!!",
  ui_story_1022_10221200_91_dialog_content = "¿Q-Qué es esto?! ¿¡Cuál de ustedes me ató así?! ¡Suéltame ahora mismo!!!",
  ui_story_1022_10221200_92_dialog_content = "... No tengo ganas de ver qué sucede después. Voy a entrar.",
  ui_story_1022_10221200_93_dialog_content = "Hmph, tampoco tengo ninguna razón para quedarme atrás. Termina rápido y entra, Forsakin. La reunión está a punto de comenzar.",
  ui_story_1022_10221200_94_dialog_content = "...",
  ui_story_1022_10221200_95_dialog_content = "...",
  ui_story_1022_10221200_96_dialog_content = "Ja... ¡Jajajaja! ¡Háganla pedazos, mis secuaces!",
  ui_story_1022_10221200_97_dialog_content = "¡Graaah!",
  ui_story_1022_10221200_98_dialog_content = "...",
  ui_story_1022_10221200_99_dialog_content = "Te has vuelto más fuerte... ¿Pero eres lo suficientemente fuerte para esto? ¿Realmente tienes las agallas para seguir adelante con ello?",
  ui_story_1022_10221200_100_dialog_content = "Porque si me comes ahora, solo significa que alguien más te comerá en el futuro...",
  ui_story_1022_10221200_101_dialog_content = "El día en que aparezca un Eclipsite más fuerte y respetado... Será el día en que te conviertan en su comida.",
  ui_story_1022_10221200_102_dialog_content = "¿Eres lo suficientemente valiente para llegar tan lejos? Porque una vez que lo hagas, no hay vuelta atrás.",
  ui_story_1022_10221200_103_dialog_content = "... En lo más profundo de tu corazón, todavía piensas que eres un auroriano, ¿no es así?!",
  ui_story_1022_10221200_104_dialog_content = "...",
  ui_story_1022_10221200_105_dialog_content = "¿Ya has terminado?",
  ui_story_1022_10221200_106_dialog_content = "... ya no siento los movimientos de Ursura.",
  ui_story_1022_10221200_107_dialog_content = "Veo. Ella demostró ser útil al final. Gracias a ella, pudimos ver la técnica secreta de esa persona.",
  ui_story_1022_10221200_108_dialog_content = "El acto principal comienza ahora.",
  ui_story_1022_10221200_109_dialog_content = "... Ella está aquí.",
  ui_story_1022_10221200_110_dialog_content = "¿Mmm?",
  ui_story_1022_10221200_111_dialog_content = "<color=#e8d9bb>Una figura emerge de las sombras, atrayendo la atención de todos.</color>",
  ui_story_1022_10221200_112_dialog_content = "...",
  ui_story_1022_10221200_113_dialog_content = "Jeje, como se esperaba de nuestro talentoso nuevo miembro... Creo que serás mucho más de lo que Figerald alguna vez fue.",
  ui_story_1022_10221200_114_dialog_content = "No, Asmodeus... Es Ursura. Ella está aquí.",
  ui_story_1022_10221200_115_dialog_content = "...",
  ui_story_1022_10221200_116_dialog_content = "La <color=#FFB400>Sustancia X</color> fue extraída de su ser, y su corazón y cuerpo fueron prácticamente aniquilados... Sin embargo, ella aún vive. Y no solo eso, sino que se está recuperando lentamente.",
  ui_story_1022_10221200_117_dialog_content = "¿Es por su linaje original? Su esencia ya había sido corrompida una vez en impura <color=#FFB400>Sustancia N</color>.",
  ui_story_1022_10221200_118_dialog_content = "Aunque le quitaron su naturaleza inmaterial, ella aún sobrevivió.",
  ui_story_1022_10221200_119_dialog_content = "Mientras la rama de coral que ella creó sea devuelta, su naturaleza inmaterial... El poder de <color=#FFB400>X</color> también volverá a ella, y su corazón latirá una vez más.",
  ui_story_1022_10221200_120_dialog_content = "<color=#e8d9bb>¡Chirrido, chirrido, chirrido!</color>",
  ui_story_1022_10221200_121_dialog_content = "Baja la voz, Petey. Solo quiero dormir un poco más...",
  ui_story_1022_10221200_122_dialog_content = "P-Petey?!",
  ui_story_1022_10221200_123_dialog_content = "¿Eres tú quien me rescató? ¿Pero por qué te escapaste? ¿Y qué pasa con Ursura? Ella está... ¿Ella no está muerta, verdad?!",
  ui_story_1022_10221200_124_dialog_content = "J-Justo cálmate, Pepita. Si Petey aún está vivo, eso significa que Ursura también debe estarlo. Pero si Petey está aquí ahora, también significa que está en grandes problemas...",
  ui_story_1022_10221200_125_dialog_content = "... Espera, ¿por qué sigo preocupándome por ella?!",
  ui_story_1022_10221200_126_dialog_content = "Oh, ¿a quién estoy engañando? Buscadores de problemas temerarios como nosotros... Prácticamente estamos hechos el uno para el otro.",
  ui_story_1022_10221200_127_dialog_content = "<color=#e8d9bb>Por alguna razón, Petey se envuelve alrededor de la pierna de Pepita y comienza a chillar frenéticamente.</color>",
  ui_story_1022_10221200_128_dialog_content = "Sí, sí, sé que estás preocupado por tu maestro... Espera, ¿quieres decir que no lo estás? Entonces, ¿qué eres tú—Bwaaaaa!!!",
  ui_story_1022_10221200_129_dialog_content = "<color=#e8d9bb>Una grieta en el espacio se abre sobre Pepita, y un tren sale disparado de ella a toda velocidad.</color>",
  ui_story_1022_10221200_130_dialog_content = "¿Un t-tren?!?",
  ui_story_1022_10221200_131_dialog_content = "La Zona Oscura es un lugar frío y desolado. Un noble conductor como yo nunca podría abandonar a un solitario Aurorian en esta congelada tierra de muerte.",
  ui_story_1022_10221200_132_dialog_content = "Bueno, ¿señora? ¿Le gustaría subir al tren más espectacular que existe?"
}
return config
